DROP TRIGGER SITI_H501.ANAG_SOGGETTI_PATRI_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.ANAG_SOGGETTI_PATRI_TIB
  before insert ON SITI_H501.ANAG_SOGGETTI  
  for each row
declare
  num number;
begin
  select count(*) into num
    from anag_soggetti_ext
   where cod_soggetto = :new.cod_soggetto;
  
  if num = 0 then
    insert into anag_soggetti_ext (cod_soggetto) values (:new.cod_soggetto);
  end if;
   
end anag_soggetti_patri_TIB;
/


DROP TRIGGER SITI_H501.ANAG_SOGGETTI_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.ANAG_SOGGETTI_TIB
  before insert or update ON SITI_H501.ANAG_SOGGETTI  
  for each row
declare
  dataFine date := to_date('31129999', 'ddmmyyyy');
  vcuaa varchar2(16) := null;
  deno varchar2(300) := null;
begin
  if :new.PKID is null then
    select anag_soggetto_seq.nextval into :new.pkid from dual;
  end if;

  if :new.denominazione is null then 
   :new.denominazione := trim(:new.cognome || ' ' || :new.nome);
  end if;
  
  if :new.INDIRIZZO_EST is null then
    if :new.FKCIVICO_RESI is not null then
      begin
        select trim(t.PREFISSO || ' ' || t.NOME || ' ' || l.nome)
          into :new.INDIRIZZO_EST  
          from aggr_localizza l, AGGR_TOPO t 
         where l.PKID_LOC = :new.FKCIVICO_RESI 
           and l.fkid_type = -1
           and t.AGGR_CODE = 1
           and t.PKID_TOPO = l.PKID_TOPO
           and sysdate between t.DATA_INIZIO_VAL and t.DATA_FINE_VAL;
      exception when no_data_found then
        null;
      end; 
    end if;
  end if;
  
end anag_soggetti_TIB;
/


DROP TRIGGER SITI_H501.ANAINQUI_IOFU;

CREATE OR REPLACE TRIGGER SITI_H501.ANAINQUI_IOFU
instead of update ON SITI_H501.ANAINQUI
declare
  cnt pls_integer;
begin
  if (:new.cod_inq is not null) then

    select count(*) into cnt
      from anag_soggetti_ext
     where cod_soggetto = :new.cod_inq;

    if (cnt = 0) then
      insert into anag_soggetti_ext (cod_soggetto) values (:new.cod_inq);
    end if;

    update anag_soggetti_ext
       set banca = :new.banca, cab = :new.cab, abi = :new.abi, c_c = :new.c_c,
           cin = :new.cin, note = :new.note, titolo = :new.titolo,
           STATO_INQ = :new.STATO_INQ,
           TIPO_DOC = :new.TIPO_DOC, NUM_DOC = :new.NUM_DOC, RIL_IL_DOC = :new.RIL_IL_DOC,
           AUTORITA_DOC = :new.AUTORITA_DOC, DIP_SN = :new.DIP_SN, COD_SPORT = :new.COD_SPORT,
           CHIAVEINQ = :new.CHIAVEINQ, COD_UTE = :new.COD_UTE, CITTADINANZA = :new.CITTADINANZA,
           COD_AFFI = :new.COD_AFFI, USO_STRUM = :new.USO_STRUM,
           TIPOINTEFAT = :new.TIPOINTEFAT,
           IBAN_PAESE = :new.IBAN_PAESE, IBAN_CIN_EUR = :new.IBAN_CIN_EUR,
         ft_denom = :new.ft_denom
     where cod_soggetto = :new.cod_inq;
  end if;
end;
/


