DROP TRIGGER SITI_H501.CENTRIRESP_CHECK_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.CENTRIRESP_CHECK_TIB
BEFORE INSERT
ON SITI_H501.CENTRIRESP
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
DECLARE
  existing_tipo                 VARCHAR (1) := NULL;
  check_enabled                 VARCHAR (2) := 'SI';
BEGIN
  -- verifico se esiste un oggetto padre o figlio all'interno dei centri di responsabilitï¿½
  BEGIN
    SELECT NVL (valore, 'SI')
      INTO check_enabled
      FROM gisparams
     WHERE variabile = 'PATRI_SETTORI_CHECK';
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      check_enabled := 'SI';
  END;

  IF check_enabled = 'SI' THEN
    BEGIN
      SELECT DISTINCT obj.tipo
                 INTO existing_tipo
                 FROM
                      /* AGGREGATI */
                      (SELECT   a.id_cata_topo AS id_object,
                                'A' AS tipo,
                                b.cod_nazionale,
                                b.foglio,
                                b.particella,
                                b.sub,
                                -1 AS unimm,
                                -1 AS vano,
                                MIN (b.data_inizio_val) AS data_inizio_val,
                                MAX (b.data_fine_val) AS data_fine_val
                           FROM aggr_topo a, aggr_part b
                          WHERE a.aggr_code = b.aggr_code AND a.pkid_topo = b.pkid_topo
                       GROUP BY a.id_cata_topo, b.cod_nazionale, b.foglio, b.particella, b.sub
                       /* PARTICELLE */
                       UNION
                       SELECT   id_particella AS id_object,
                                'P' AS tipo,
                                cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                -1 AS unimm,
                                -1 AS vano,
                                MIN (data_aggi) AS data_inizio_val,
                                MAX (data_fine) AS data_fine_val
                           FROM sititrkc
                       GROUP BY id_particella, cod_nazionale, foglio, particella, sub
                       /* UIU */
                       UNION
                       SELECT   id_cata_uiu AS id_object,
                                'U' AS tipo,
                                cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm,
                                -1 AS vano,
                                MIN (data_inizio_val) AS data_inizio_val,
                                MAX (data_fine_val) AS data_fine_val
                           FROM sitiuiu
                       GROUP BY id_cata_uiu, cod_nazionale, foglio, particella, sub, unimm
                       /* VANI*/
                       UNION
                       SELECT   id_cata_vano AS id_object,
                                'V' AS tipo,
                                cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm,
                                -1 AS vano,
                                MIN (data_inizio_val) AS data_inizio_val,
                                MAX (data_fine_val) AS data_fine_val
                           FROM sitiedi_vani
                       GROUP BY id_cata_vano, cod_nazionale, foglio, particella, sub, unimm, vano) obj,
                      --centriresp cr,
							 (SELECT * FROM centriresp WHERE FK_OBJECT <> :NEW.fk_object AND TIPO <> :NEW.tipo AND DATA_INIZIO_VAL <> :NEW.data_inizio_val AND DATA_FINE_VAL <> :NEW.data_fine_val) cr,
                      -- ricerco i dati catastali in base al tipo e all'id dell'oggetto
                      (SELECT DISTINCT cod_nazionale,
                                       foglio,
                                       particella,
                                       sub,
                                       unimm,
                                       vano
                                  FROM (
                                        /* AGGREGATI */
                                        SELECT DISTINCT b.cod_nazionale,
                                                        b.foglio,
                                                        b.particella,
                                                        b.sub,
                                                        -1 AS unimm,
                                                        -1 AS vano
                                                   FROM aggr_topo a, aggr_part b
                                                  WHERE a.aggr_code = b.aggr_code AND a.pkid_topo = b.pkid_topo
                                                        AND a.id_cata_topo = :NEW.fk_object AND 'A' = :NEW.tipo
                                        UNION
                                        /* PARTICELLE */
                                        SELECT DISTINCT cod_nazionale,
                                                        foglio,
                                                        particella,
                                                        sub,
                                                        -1 AS unimm,
                                                        -1 AS vano
                                                   FROM sititrkc
                                                  WHERE id_particella = :NEW.fk_object AND 'P' = :NEW.tipo
                                        UNION
                                        /* UIU */
                                        SELECT DISTINCT cod_nazionale,
                                                        foglio,
                                                        particella,
                                                        sub,
                                                        unimm,
                                                        -1 AS vano
                                                   FROM sitiuiu
                                                  WHERE id_cata_uiu = :NEW.fk_object AND 'U' = :NEW.tipo
                                        UNION
                                        /* VANI*/
                                        SELECT DISTINCT cod_nazionale,
                                                        foglio,
                                                        particella,
                                                        sub,
                                                        unimm,
                                                        vano
                                                   FROM sitiedi_vani
                                                  WHERE id_cata_vano = :NEW.fk_object AND 'V' = :NEW.tipo)) o
                WHERE obj.cod_nazionale = o.cod_nazionale
        AND obj.foglio = o.foglio
      AND obj.particella = o.particella
                  AND obj.sub = o.sub
                  AND obj.unimm =
                       CASE
                         WHEN (obj.tipo = 'U' OR obj.tipo = 'V') AND (:NEW.tipo = 'U' OR :NEW.tipo = 'V') THEN o.unimm
         ELSE obj.unimm
                       END
      AND obj.vano =
        CASE
                         WHEN obj.tipo = 'V' AND :NEW.tipo = 'V' THEN o.vano
                         ELSE obj.vano
                       END
                  AND cr.data_inizio_val <= :NEW.data_fine_val
                  AND cr.data_fine_val >= :NEW.data_inizio_val
       AND obj.id_object = cr.fk_object
                  AND obj.tipo = cr.tipo
      AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        existing_tipo := NULL;
    END;

    IF existing_tipo = 'A' THEN
      raise_application_error (-20001, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati all'' aggregato ');
    ELSIF existing_tipo = 'P' THEN
      raise_application_error (-20002, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati alla particella ');
    ELSIF existing_tipo = 'U' THEN
      raise_application_error (-20003, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati all'' unitï¿½ immobiliare ');
    ELSIF existing_tipo = 'V' THEN
      raise_application_error (-20004, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati ad uno o piï¿½ vani ');
    ELSIF existing_tipo IS NOT NULL THEN
      raise_application_error (-20005, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati ad altri oggetti ');
    END IF;
  END IF;
END;
/


DROP TRIGGER SITI_H501.COINTESTATARI_IOFU;

CREATE OR REPLACE TRIGGER SITI_H501.COINTESTATARI_IOFU
  INSTEAD OF UPDATE
  ON SITI_H501.COINTESTATARI
  FOR EACH ROW
BEGIN
  UPDATE patri_loc_cointesta
     SET perc_spese = :NEW.perc_spese_inq,
         fattura = 'N',
         tipo_uscita = :NEW.tipo_uscita,
         id_impreg = :NEW.id_impreg
   WHERE fk_atto = :OLD.codice AND pk_cuaa = :OLD.cod_inq AND id_co = :OLD.id_co;
END;
/


DROP TRIGGER SITI_H501.COMUNI_IOFU;

CREATE OR REPLACE TRIGGER SITI_H501.COMUNI_IOFU
instead of update ON SITI_H501.COMUNI
for each row
begin
  update patri_siticomu_ext 
     set num_abitanti = :new.NABIT, 
         ANNO = :new.anno,
         ISTAT_AGR = :new.istat_agr,
         UFF_COMP = :new.UFF_COMP, 
         CONCESSIONE_DI = :new.CONCESSIONE_DI, 
         CONCESSIONE_CC = :new.CONCESSIONE_CC, 
         NOTE_COM = :new.NOTE_COM
   where cod_nazionale = :new.codice;
   
  if nvl(:new.UB_GEO, 'X') != nvl(:old.UB_GEO, 'X') then
    update siticomu set ubicazione_geografica = :new.UB_GEO
     where cod_nazionale = :new.codice;
  end if;
   
end;
/


DROP TRIGGER SITI_H501.CONS_CONS_TIB;

