DROP TRIGGER SITI_H501.CREA_LOCK_CUAA_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.CREA_LOCK_CUAA_TIB
BEFORE
INSERT
ON SITI_H501.CREA_LOCK_CUAA
FOR EACH ROW
DECLARE
  CURSOR C1 IS SELECT CUAA,UTENTE,"TIMESTAMP",TIPO_LOCK FROM CONS_LKCU_TAB WHERE CUAA=:NEW.CUAA;

  CU VARCHAR2(20);
  UT VARCHAR2(20);
  TI DATE;
  TL NUMBER(1);
BEGIN
  OPEN C1;
  FETCH C1 INTO CU,UT,TI,TL;
  IF C1%NOTFOUND THEN CU:=NULL; END IF;
  CLOSE C1;

  DELETE FROM CONS_LKCU_TAB WHERE ((SYSDATE - TIMESTAMP) * 24 * 60) > 30 AND TIPO_LOCK=0;

  IF CU IS NOT NULL THEN
    IF UPPER(UT) = :NEW.UTENTE AND TL=0 THEN
        UPDATE CONS_LKCU_TAB SET UTENTE=:NEW.UTENTE,TIMESTAMP=SYSDATE,TIPO_LOCK=:NEW.TIPO_LOCK WHERE CUAA=:NEW.CUAA;
    ELSE
      IF TL = 0 THEN
        RAISE_APPLICATION_ERROR(-20001,'CONSISTENZA ' || :NEW.CUAA || ' BLOCCATA TEMPORANEAMENTE DA UTENTE ' || UT);
      ELSE
        IF UPPER(UT) = :NEW.UTENTE THEN
          RAISE_APPLICATION_ERROR(-20002,'CONSISTENZA ' || :NEW.CUAA || ' BLOCCATA DA UTENTE ' || UT);
        ELSE
          RAISE_APPLICATION_ERROR(-20003,'CONSISTENZA ' || :NEW.CUAA || ' BLOCCATA DA UTENTE ' || UT);
        END IF;
      END IF;
    END IF;
  ELSE
    INSERT INTO CONS_LKCU_TAB(CUAA,UTENTE,TIMESTAMP,TIPO_LOCK)
    VALUES(:NEW.CUAA,:NEW.UTENTE,SYSDATE,:NEW.TIPO_LOCK);
  END IF;
END;
/


