   END IF;

   :NEW.DATA_FINE_VAL:=CXF_UTILS.SCADI_CALIB(:NEW.ID_CXF,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE);
