DROP TRIGGER SITI_H501.CXF_EDIFICIO_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.CXF_EDIFICIO_TIB
BEFORE INSERT
ON SITI_H501.CXF_EDIFICIO
FOR EACH ROW
DECLARE
CURSOR C1 IS SELECT Nvl(Max(PROG_EDI),0) FROM cxf_edificio WHERE id_cxf=:NEW.id_cxf AND particella=:NEW.PARTICELLA;
NEWPROG NUMBER(4);
BEGIN
  SELECT CXF_EDIFICIO_SEQ.NEXTVAL INTO :NEW.ID_EDIFICIO FROM DUAL;
  IF :NEW.PROG_EDI IS NULL THEN
    OPEN C1;
    FETCH C1 INTO NEWPROG;
    CLOSE C1;
    :NEW.PROG_EDI := NEWPROG+1;
  END IF;
END;
/


