CREATE OR REPLACE TRIGGER SITI_H501.FIRECATALOG_TUB
BEFORE
UPDATE
ON SITI_H501.FIRECATALOG
FOR EACH ROW
BEGIN
   IF :NEW.COD_NAZIONALE IS NULL THEN
	CATALOG_DATA.ASSEGNACODICI_ACTIVE(:NEW.IDCAT,:NEW.DATA_INIZIO_VAL,:NEW.SE_ROW_ID);
   ELSE
	IF :NEW.SE_ROW_ID = 0 THEN
		CATALOG_DATA.ASSEGNACODICI_PART(:NEW.IDCAT,:NEW.DATA_INIZIO_VAL,:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB);
	ELSE
		CATALOG_DATA.CATALOGA_PART(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DATA_INIZIO_VAL,:NEW.IDCAT);
	END IF;
   END IF;
END;
/


DROP TRIGGER SITI_H501.FORNITORI_IOFI;

CREATE OR REPLACE TRIGGER SITI_H501.FORNITORI_IOFI
INSTEAD OF INSERT
ON SITI_H501.FORNITORI FOR EACH ROW
DECLARE
   num number;
   new_id number;
   new_pk_cuaa number;
   new_id_tag number;
BEGIN
    select count(*) into num
      from an_tags
     where DESCR = 'MANU_FORN';

    if num = 0 then
      INSERT INTO AN_TAGS ( ID_TAG, DESCR, SYSTEM, INIZIO, FINE ) VALUES (
      -11, 'MANU_FORN', 'Y',  TO_Date( '01/01/1980 12:00:00 AM', 'MM/DD/YYYY HH:MI:SS AM'),  TO_Date( '12/31/9999 12:00:00 AM', 'MM/DD/YYYY HH:MI:SS AM'));
    end if;


        select anag_soggetto_seq.nextval into new_id from dual;
        select cons_azie_seq.nextval into new_pk_cuaa from dual;
        insert into anag_soggetti (
            pkid,
            COD_SOGGETTO,
            DENOMINAZIONE,
            indirizzo_est,
            CAP,
            TELEFONO,
            FAX,
            MAIL,
            COD_FISCALE,
            PART_IVA,
            cell,
            per_rif,
            localita,

            data_fine_val,
            data_inizio_val,
            data_lav,
            utente_inizio
        )
        values(
            new_id,
            new_pk_cuaa,--rForn.id_frn,
            :new.descrizione,
            :new.indirizzo,
            :new.cap,
            :new.TEL,
            :new.FAX,
            :new.EMAIL,
            :new.COD_FISC,
            :new.P_IVA,
            :new.cell,
            :new.per_rif,
            :new.COMUNE,

            to_date('31129999', 'ddmmyyyy'),--data_fine_val,
            to_date('01011980', 'ddmmyyyy'),--data_inizio_val,
            sysdate,--data_lav,
            'FORNI_VIW'--utente_inizio,

        );
        insert into cons_azie_tab(
            pk_cuaa,
            cuaa,
            data_inizio,
            data_fine,
            data_registrazione,
            utente,
            timestamp,
            cod_stato,
            data_inizio_stato,
            cod_ente
            )values(
            new_pk_cuaa,
            'FORNI_'||new_pk_cuaa,
            to_date('01011980', 'ddmmyyyy'), to_date('99991231', 'yyyymmdd'), sysdate,'FORNI_VIW', sysdate, 0, to_date('01011980', 'ddmmyyyy'), null
        )
        ;

        update anag_soggetti_ext set
        cod_ute=:new.cod_ute,
        note=:new.note,
        cab=:new.cab,
        abi=:new.abi,
        banca=:new.banca,
        c_c=:new.c_c,
        cod_sport=:new.cod_sport,
        cin=:new.cin,
        iban_paese=:new.iban_paese,
        iban_cin_eur=:new.iban_cin_eur
        where cod_soggetto=new_pk_cuaa;--rForn.id_frn;


        select an_tags_seq.nextval into new_id_tag from dual;
        insert into AN_SOGGETTI_TAGS
            (ID,ID_SOGGETTO, ID_TAG, UT_INIZIO,INIZIO,UT_FINE,FINE,LAST_MODIFIED)
            values
            (new_id_tag,new_pk_cuaa,(select ID_TAG from an_tags where DESCR = 'MANU_FORN'),
            'FORNI_VIW',to_date('01011980', 'ddmmyyyy'),NULL,to_date('99991231', 'yyyymmdd'),SYSDATE
            );


END FORNITORI_iofi;
/


DROP TRIGGER SITI_H501.FORNITORI_IOFU;

CREATE OR REPLACE TRIGGER SITI_H501.FORNITORI_IOFU
instead of update ON SITI_H501.FORNITORI
declare
  cnt pls_integer;
begin
  if (:new.CODICE is not null) then

    select count(*) into cnt
      from anag_soggetti_ext
     where cod_soggetto = :new.CODICE;

    if (cnt = 0) then
      insert into anag_soggetti_ext (cod_soggetto) values (:new.CODICE);
    end if;

    update anag_soggetti_ext
       set
           cod_ute = :new.COD_UTE,
           note = :new.note,
           banca = :new.banca,
           cab = :new.cab,
           abi = :new.abi,
           c_c = :new.c_c,
           COD_SPORT = :new.COD_SPORT,
           cin = :new.cin,
           IBAN_PAESE = :new.IBAN_PAESE,
           IBAN_CIN_EUR = :new.IBAN_CIN_EUR
           --,
           --cell = :new.CELL,
           --per_rif = :new.per_rif
     where cod_soggetto = :new.CODICE;
  end if;
end;
/


DROP TRIGGER SITI_H501.GISPARAMS_VIEW_TRG;

CREATE OR REPLACE TRIGGER SITI_H501.GISPARAMS_VIEW_TRG
instead of insert or update or delete ON SITI_H501.GISPARAMS for each row
declare
    counter number;
begin
  if inserting then
    update gisparams_all set valore=:new.valore, label=:new.label, tipo=:new.tipo, hidden='N'
        where variabile=:new.variabile;
    IF SQL%ROWCOUNT < 1
    THEN
        insert into gisparams_all (variabile,valore,label,tipo,hidden) values (:new.variabile,:new.valore,:new.label,:new.tipo,'N');
    END IF;
  elsif updating then
    update gisparams_all set variabile=:new.variabile, valore=:new.valore, label=:new.label, tipo=:new.tipo, hidden='N'
        where variabile=:old.variabile;
  else
    update gisparams_all set hidden='Y'
        where variabile=:old.variabile;
  end if;
end;
/


DROP TRIGGER SITI_H501.IMPO_CESPITI_TR1;

CREATE OR REPLACE TRIGGER SITI_H501.IMPO_CESPITI_TR1
-- a.caleffi 2010-04-26 rimossa funzione to_date in campi che sono gia' data
-- a.caleffi 2008-12-24 cambiata ricerca in getcodnaz
before insert on SITI_H501.IMPO_CESPITI
for each row
declare
  cursor c_tit_uiu(p_cn varchar2, p_pkc number) is
    select * from siticonduz_imm_all2
      where cod_nazionale = p_cn and foglio = :new.foglio and particella = :new.particella and sub = :new.sub
        and unimm = :new.unimm and (sysdate between data_inizio and data_fine)
        and pk_cuaa = p_pkc
    order by tipo_titolo;

  cursor c_tit_part(p_cn varchar2, p_pkc number) is
    select * from siticond_all2
      where cod_nazionale = p_cn and foglio = :new.foglio and particella = :new.particella and sub = :new.sub
        and (sysdate between data_inizio and data_fine) and pk_cuaa = p_pkc
    order by tipo_titolo;

  CURSOR c_docs IS SELECT * FROM sitifile_tipi_atto_doc WHERE FKID_TIPO_ATTO=-21;

  cn            varchar2(4);
  pkc           number(9);
  n_tmp         pls_integer;
  m_id_cespite  number(9);
  m_id_tit      number(9);
  m_tp_tit      varchar2(5);
  m_id_atto     number(9);
begin

  -- a.caleffi 2008-10-28 se UNIMM ha valore -1 allora lo setto a NULL
  -- dato che in SITIDATA un campo numerico non puo' essere passato a null
  IF (-1 = :NEW.unimm)THEN
    :NEW.unimm := NULL;
  END IF;

  if (:new.particella is not null and length(:new.particella) != 5) then
    :new.particella := lpad(trim(:new.particella), 5, '0');
  end if;

  -- a.caleffi 2008-12-24 se la sezione e' uno spazio, la considero null
  --   aggiunto in quanto anche se in access c'e' null con SITIData puo' arrivare uno spazio.
  IF (' ' = :new.id_sezc) THEN
    cn := getcodnaz(:new.istatp, :new.istatc, null);
  else
    cn := getcodnaz(:new.istatp, :new.istatc, :new.id_sezc);
  END IF;

  if cn is null then
    raise no_data_found;
  end if;

  select pk_cuaa into pkc from cons_azie_tab where cuaa = :new.codi_sogg;

  -- Verifico se esiste giï¿½ un cespite con quel codice
  begin
    select pk_cuaa, pk_cespite into n_tmp, m_id_cespite from patri_cespiti where cod_cespite = :new.cod_cespite;
    if n_tmp != pkc then
      raise_application_error(-20001, 'Esiste un cespite di un soggetto differente con lo stesso codice!');
    end if;
  exception when no_data_found then
    -- Non esiste
    null;
  end;


  -- Verifico se esiste un titolo per il soggetto
  if :new.unimm is not null THEN
    for r in c_tit_uiu(cn, pkc) loop
      m_id_tit := r.pkid_tit;
      m_tp_tit := r.tipo_titolo;
      exit;
    end loop;
  ELSE
    for r in c_tit_part(cn, pkc) loop
      m_id_tit := r.pkid_tit;
      m_tp_tit := r.tipo_titolo;
      exit;
    end loop;
  end if;

  if m_id_tit is null THEN
    -- Non ci sono titoli, non posso creare il cespite
    raise_application_error(-20002, 'Il un soggetto non ha titoli sulla particella/UIU!');
  end if;

  if m_id_cespite is null THEN
    m_id_atto := sitifile.inserisci_atto(-21, 'LOADER');
    FOR rdocs IN c_docs LOOP
      SELECT SITIFILE_DOCUMENTI_SEQ.NEXTVAL INTO n_tmp FROM dual;
      INSERT INTO sitifile_documenti (pkid_doc, fkid_tipo_doc, descrizione_breve, data_lav, data_scadenza,
                                      cod_archiviazione, utente_ins, data_aggiornamento, descrizione_estesa,
                                      valido, chain_id, data_inizio_val, data_fine_val, utente_fin, locked_by,
                                      lock_date, ovl_id)
        VALUES(n_tmp, rdocs.fkid_tipo_doc, NULL, sysdate, NULL, NULL, 'LOADER', SYSDATE, NULL,
               'Y', n_tmp, :new.data_inizio, To_Date('99991231','YYYYMMDD'), NULL, NULL, NULL, 1);

      INSERT INTO sitifile_documenti_campi_ext (FKID_DOC) VALUES (n_tmp);

      sitifile.inserisci_doc_in_atto(m_id_atto, n_tmp, 'LOADER');
    END LOOP;

    -- a.caleffi fix 2008-11-04 aggiunto campo PROVENIENZA
    -- a.caleffi fix 2008-11-12 aggiunto campo PK_CUAA per avere il soggetto nei cespiti
    -- a.caleffi add 2008-11-17 aggiunti campi vari per importare piu' informazioni
		-- a.caleffi 2010-04-26 rimossa funzione to_date in campi che sono gia' data
    insert into patri_cespiti (COD_NAZIONALE,DESCRIZIONE,COD_CESPITE, COD_IMM,COD_CAT_INV,COD_CAT_CES,COD_CAT_CES_ALT,
                               FL_SOGGETTO_ICI,COD_METODO_STIMA, FL_TP_LOCAZIONE,CAT_AMMINIS,COD_AMMINIS,
                               NUM_INVENTARIO, DATA_INIZIO_VAL,UTENTE_INI,PK_ATTO,
                               PROVENIENZA, PK_CUAA,
                               /* a.caleffi add 2008-11-17 righe aggiunte */
                               VAL_ORIGINALE, VAL_A_NUOVO, RIVALUTAZIONI,
                               VAL_ATTUALE, VAL_RESIDUO, DT_ULT_AMM_DAL,
                               DT_ULT_AMM_AL, ULT_AMM_IMPO, DATA_AMM_INI,
                               VAL_BENE, TP_VAL_ICI, COD_ALIQ_ICI,
                               NOTE, DT_ULT_RIVAL, VAL_TERRE,
                               VAL_ATTUALE_F, VAL_RESIDUO_F, DT_ULT_AMM_DAL_F,
                               DT_ULT_AMM_AL_F, ULT_AMM_IMPO_F, ULT_FV_CONS,
                               DT_ULT_FV_CONS, VAL_TOT_F, VAL_TERRE_F,
                               COD_ALIQ_AMM)
      values (cn, :new.descr, :new.cod_cespite, :new.cod_imm, :new.cat_inv, :new.cat_ces, :new.cat_ces_alt,
              flag(:new.soggetto_ici, 'Y'), :new.metodo_stima, case when :new.locabile != 'N' then 'L' when :new.locabile = 'N' then 'A' end,
              :new.cat_amminis, :new.cod_amminis, :new.num_inv, :new.data_inizio, 'LOADER', m_id_atto,
              :NEW.provenienza, pkc,
               /* a.caleffi add 2008-11-17 righe aggiunte */
              :NEW.VAL_ORIGINALE, :NEW.VAL_A_NUOVO, :NEW.RIVALUTAZIONI,
              :NEW.VAL_ATTUALE, :NEW.VAL_RESIDUO, :NEW.DT_ULT_AMM_DAL,
              :NEW.DT_ULT_AMM_AL, :NEW.ULT_AMM_IMPO, :NEW.DATA_AMM_INI,
              :NEW.VAL_BENE, :NEW.TP_VAL_ICI, :NEW.COD_ALIQ_ICI,
              :NEW.NOTE, :NEW.DT_ULT_RIVAL, :NEW.VAL_TERRE,
              :NEW.VAL_ATTUALE_F, :NEW.VAL_RESIDUO_F, :NEW.DT_ULT_AMM_DAL_F,
              :NEW.DT_ULT_AMM_AL_F, :NEW.ULT_AMM_IMPO_F, :NEW.ULT_FV_CONS,
              :NEW.DT_ULT_FV_CONS, :NEW.VAL_TOT_F, :NEW.VAL_TERRE_F,
              :NEW.COD_ALIQ_AMM)

      returning pk_cespite into m_id_cespite;

  end if;

  if :new.unimm is not null then
    insert into patri_cespiti_uiu (fk_cespite, pk_tit, tipo_titolo, pkid)
      values (m_id_cespite, m_id_tit, m_tp_tit, PATRI_CESPITI_PART_UIU_SEQ.nextval);
  ELSE
	  insert into patri_cespiti_part (fk_cespite, pk_tit, tipo_titolo, pkid)
      values (m_id_cespite, m_id_tit, m_tp_tit, PATRI_CESPITI_PART_UIU_SEQ.nextval);
  end if;

  patri_pck.allinea_cespite(m_id_cespite);
end;
/


DROP TRIGGER SITI_H501.IMPO_CONS_TERRENI_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.IMPO_CONS_TERRENI_TIB
BEFORE
 INSERT
ON SITI_H501.IMPO_CONS_TERRENI
REFERENCING OLD AS OLD NEW AS NEW
 FOR EACH ROW
/* Formatted on 2004/02/26 12:23 (Formatter Plus v4.8.0) */
DECLARE
   cod_naz   VARCHAR2 (4);
   errore    NUMBER       := 0;
BEGIN
   :NEW.cod_soggetto := TRIM (:NEW.cod_soggetto);

   IF :NEW.cod_nazionale IS NULL
   THEN
      cod_naz := NULL;
      cod_naz :=
         import_gis_data.getcodnaz (:NEW.istatp,
                                    :NEW.istatc,
                                    TRIM (:NEW.sezione)
                                   );

      IF cod_naz IS NOT NULL
      THEN
         :NEW.cod_nazionale := cod_naz;
      ELSE
         :NEW.cod_nazionale := '0000';
         errore := errore + 1;                         -- manca cod_nazionale
      END IF;
   END IF;

   IF :NEW.sub IS NULL OR TRIM (:NEW.sub) IS NULL
   THEN
      :NEW.sub := ' ';
   ELSE
      :NEW.sub := TRIM (:NEW.sub);
   END IF;

   :NEW.particella := LPAD (:NEW.particella, 5, '0');

   /*IF import_cons_data.esistesoggetto (:NEW.cod_soggetto) <= 0
   THEN
      errore := errore + 2;
   END IF;*/
   IF :NEW.foglio <= 0
   THEN
      errore := errore + 2;
   END IF;

   IF :NEW.QUOTA <= 0
   THEN
      errore := errore + 4;
   END IF;

   IF :NEW.particella = '00000'
   THEN
      errore := errore + 8;
   END IF;

   IF LENGTH (:NEW.cod_soggetto) <> 16 AND LENGTH (:NEW.cod_soggetto) <> 11
   THEN
      errore := errore + 16;
   END IF;

   :NEW.errore_pre_caricamento := errore;
EXCEPTION
   WHEN OTHERS
   THEN
      -- Consider logging the error and then re-raise
      RAISE;
END;
/


