DROP TRIGGER SITI_H501.IMPO_SITIEDI_PIANI;

CREATE OR REPLACE TRIGGER SITI_H501.IMPO_SITIEDI_PIANI BEFORE INSERT ON SITI_H501.IMPO_SITIEDI_PIANI
FOR EACH row
/*
a.caleffi 2009-12-17

processa l'inserimento del record nella tabella impo_sitiedi_piani inserendo il record nella tabella
sitiedi_piani previa convalida dei dati di input
*/
DECLARE
  strFldCod_nazionale VARCHAR2(4);
  iFldEdificio NUMBER(5);

BEGIN

  :NEW.piano := Upper(:NEW.piano);

  ----------
  -- cerco il codice nazionale del comune
  ----------
  SELECT getcodnaz(:NEW.istatp, :NEW.istatc, :NEW.id_sezc)
  INTO strFldCod_nazionale
  FROM dual;

  IF (strFldCod_nazionale IS NULL) THEN
    RAISE_APPLICATION_ERROR(-20001, '(1) Errore. Codice nazionale comune non trovato istatp=[' || :NEW.istatp || '] istatc=[' || :NEW.istatc || '] id_sezc=[' || :NEW.id_sezc || ']');
  END IF;

  ----------
  -- cerco il valore del campo edificio
  ----------
  SELECT impo_sitiedi_findEdificio(:NEW.codice_edificio, :NEW.data_inizio_val)
  INTO iFldEdificio
  FROM dual;

  IF (0 = iFldEdificio) THEN
    RAISE_APPLICATION_ERROR(-20001, '(2) Errore. Codice edificio [' || :NEW.codice_edificio || '] non trovato.');
  END IF;

  ----------
  -- controllo il valore del campo sub
  ----------
  IF ((:NEW.sub IS NULL) or (:NEW.sub = '')) THEN
    :NEW.sub := ' ';
  END IF;


  ----------
  -- inserisco il record
  ----------
  INSERT INTO sitiedi_piani(cod_nazionale, foglio, particella
    , sub, edificio, piano
    , quotamin, quotamax
    , data_inizio_val, data_fine_val, data_lav
    , utente, nome_piano)

  VALUES(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, iFldEdificio, :NEW.piano
    , :NEW.quotamin, :NEW.quotamax
    , :NEW.data_inizio_val, :NEW.data_fine_val, :NEW.data_inizio_val
    , :NEW.utente, :NEW.piano);

END;
/


DROP TRIGGER SITI_H501.IMPO_SITIEDI_TBI;

CREATE OR REPLACE TRIGGER SITI_H501.IMPO_SITIEDI_TBI BEFORE INSERT ON SITI_H501.IMPO_SITIEDI
FOR EACH row
/*
a.caleffi 2009-12-17

processa l'inserimento del record nella tabella impo_sitiedi inserendo il record nella tabella
sitiedi previa convalida dei dati di input
*/
DECLARE
  strFldCod_nazionale VARCHAR2(4);
  iFldEdificio NUMBER(5);
  iTempValue NUMBER(5);

BEGIN

  :NEW.descr := Upper(:NEW.descr);

  ----------
  -- cerco il codice nazionale del comune
  ----------
  SELECT getcodnaz(:NEW.istatp, :NEW.istatc, :NEW.id_sezc)
  INTO strFldCod_nazionale
  FROM dual;

  IF (strFldCod_nazionale IS NULL) THEN
    RAISE_APPLICATION_ERROR(-20001, '(1) Errore. Codice nazionale comune non trovato istatp=[' || :NEW.istatp || '] istatc=[' || :NEW.istatc || '] id_sezc=[' || :NEW.id_sezc || ']');
  END IF;


  ----------
  -- cerco il prossimo valore per il campo edificio
  ----------
  SELECT Nvl(Max(edificio), 1) +1
  INTO iFldEdificio
  FROM sitiedi;

  ----------
  -- controllo se l'edificio e' gia' presente nella tabella in base alla data fine validita'
  ----------
  SELECT Count(*)
  INTO iTempValue
  FROM sitiedi
  WHERE codice_edificio = :NEW.codice_edificio
  AND data_fine_val = :NEW.data_fine_val;

  IF (iTempValue > 0)THEN
    RAISE_APPLICATION_ERROR(-20001, '(2) Errore. Codice edificio [' || :NEW.codice_edificio || ']'
      || ' gia'' presente data_fine_val=[' || :NEW.data_fine_val || '] in tabella SITIEDI');
  END IF;


  ----------
  -- controllo che il terreno su cui vuole inserire l'edificio esista
  ----------
  SELECT Count(*)
  INTO iTempValue
  FROM sititrkc
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND :NEW.data_inizio_val BETWEEN data_aggi AND data_fine;


  IF (0 = iTempValue)THEN
    RAISE_APPLICATION_ERROR(-20001, '(3) Errore. Terreno non trovato in corso di validita');
  END IF;

  ----------
  -- controllo il valore del campo sub
  ----------
  IF ((:NEW.sub IS NULL) or (:NEW.sub = '')) THEN
    :NEW.sub := ' ';
  END IF;

  ----------
  -- inserisco il record
  ----------
  INSERT INTO sitiedi(cod_nazionale, foglio, particella
    , sub, edificio, descr
    , data_inizio_val, data_fine_val, data_lav
    , utente, codice_edificio)

  VALUES(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, iFldEdificio, :NEW.descr
    , :NEW.data_inizio_val, :NEW.data_fine_val, :NEW.data_inizio_val
    , :NEW.utente, :NEW.codice_edificio);

END;
/


DROP TRIGGER SITI_H501.IMPO_SITIEDI_UIU;

CREATE OR REPLACE TRIGGER SITI_H501.IMPO_SITIEDI_UIU BEFORE INSERT ON SITI_H501.IMPO_SITIEDI_UIU
FOR EACH row
/*
a.caleffi 2009-12-17

processa l'inserimento del record nella tabella impo_sitiedi_uiu inserendo il record nella tabella
sitiedi_uiu e sitiedi_uiu_ext previa convalida dei dati di input
*/
DECLARE
  strFldCod_nazionale VARCHAR2(4);
  iFldEdificio NUMBER(5);
  iTempValue NUMBER(5);

  CURSOR curFindUiuExt(pi_strCodNazionale VARCHAR2, pi_iFoglio NUMBER, pi_strParticella VARCHAR2
    , pi_strSub VARCHAR2, pi_iUnimm NUMBER, pi_dtDataInizioVal DATE) is
  SELECT data_inizio_val, data_fine_val, fk_tipologia
  FROM sitiedi_uiu_ext
  WHERE cod_nazionale = pi_strCodNazionale
  AND foglio = pi_iFoglio
  AND particella = pi_strParticella
  AND sub = pi_strSub
  AND unimm = pi_iUnimm
  AND pi_dtDataInizioVal BETWEEN data_inizio_val AND data_fine_val;

  dtFld_data_inizio_val DATE;
  dtFld_data_fine_val DATE;
  iFld_fk_tipologia NUMBER(9);
BEGIN

  :NEW.piano := Upper(:NEW.piano);

  ---------------------------------------
  -- cerco il codice nazionale del comune
  ---------------------------------------
  SELECT getcodnaz(:NEW.istatp, :NEW.istatc, :NEW.id_sezc)
  INTO strFldCod_nazionale
  FROM dual;

  IF (strFldCod_nazionale IS NULL) THEN
    RAISE_APPLICATION_ERROR(-20001, '(1) Errore. Codice nazionale comune non trovato istatp=[' || :NEW.istatp || '] istatc=[' || :NEW.istatc || '] id_sezc=[' || :NEW.id_sezc || ']');
  END IF;

  -------------------------------------
  -- cerco il valore del campo edificio
  -------------------------------------
  SELECT impo_sitiedi_findEdificio(:NEW.codice_edificio, :NEW.data_inizio_val)
  INTO iFldEdificio
  FROM dual;

  IF (0 = iFldEdificio) THEN
    RAISE_APPLICATION_ERROR(-20001, '(2) Errore. Codice edificio [' || :NEW.codice_edificio || '] non trovato.');
  END IF;

  -- controllo il valore del campo sub
  IF ((:NEW.sub IS NULL) or (:NEW.sub = '')) THEN
    :NEW.sub := ' ';
  END IF;

  --------------------------
  -- controllo esistenza UIU
  --------------------------
  SELECT Count(*)
  INTO iTempValue
  FROM sitiuiu
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND unimm = :NEW.unimm
  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;

  IF (0 = iTempValue) THEN
    RAISE_APPLICATION_ERROR(-20001, '(3) Errore. UIU non trovata, istatp=[' || :NEW.istatp || ']'
      || ' istatc=[' || :NEW.istatc || ']'
      || ' id_sezc=[' || :NEW.id_sezc || ']'
      || ' foglio=[' || :NEW.foglio || ']'
      || ' particella=[' || :NEW.particella || ']'
      || ' sub=[' || :NEW.sub || ']'
      || ' unimm=[' || :NEW.unimm || ']'
      || ' data_inizio_val=[' || :NEW.data_inizio_val || ']');
  END if;


  ----------------------------
  -- controllo campo tipologia
  ----------------------------
  SELECT Count(*)
  INTO iTempValue
  FROM sitiedi_tp_imm
  WHERE pk_tipologia = :NEW.fk_tipologia;

  IF (0 = iTempValue) THEN
    RAISE_APPLICATION_ERROR(-20001, '(4) Errore. Tipologia [' || :NEW.fk_tipologia || '] non trovata in tabella SITIEDI_TP_IMM.');
  END IF;

  --------------------------
  -- controllo esistenza Piano
  --------------------------

  SELECT Count(*)
  INTO iTempValue
  FROM sitiedi_piani
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND piano = :NEW.piano
  AND edificio = iFldEdificio
  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;

  IF (0 = iTempValue) THEN
    RAISE_APPLICATION_ERROR(-20001, '(5) Errore. Piano [' || :NEW.piano ||'] non trovato');
  END IF;

  -----------------------------------------------------
  -- controllo esistenza UIU in tabella SITIEDI_UIU_EXT
  -----------------------------------------------------

  OPEN curFindUiuExt(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, :NEW.unimm, :NEW.data_inizio_val);

  FETCH curFindUiuExt INTO dtFld_data_inizio_val, dtFld_data_fine_val, iFld_fk_tipologia;

  IF (curFindUiuExt%FOUND) THEN
    -- se il periodo della UIU trovata e' diverso dal periodo cercato allora segnalo errore
    IF (dtFld_data_inizio_val <> :NEW.data_inizio_val OR
      dtFld_data_fine_val <> :NEW.data_fine_val) THEN

      RAISE_APPLICATION_ERROR(-20001, '(5) Errore. UIU trovata in periodo data_inizio_val=[' || dtFld_data_inizio_val || ']'
        || ' data_fine_val=[' || dtFld_data_fine_val || ']'
        || ' non coincidente con data_inizio_val=[' || :NEW.data_inizio_val || ']'
        || ' data_fine_val=[' || :NEW.data_fine_val || ']');

    ELSE

      -- se la tipologia non e' la stessa segnalo errore
      IF (iFld_fk_tipologia <> :NEW.fk_tipologia) THEN
        RAISE_APPLICATION_ERROR(-20001, '(6) Errore. Tipologia errata.'
        || ' trovato=[' || iFld_fk_tipologia || ']'
        || ' atteso=[' || :NEW.fk_tipologia || ']');

      END IF;  -- iFld_fk_tipologia

    END IF;

  ELSE  -- curFindUiuExt%FOUND

    -- inserisco la riga nella tabella dato che non esiste
    INSERT INTO sitiedi_uiu_ext(cod_nazionale, foglio, particella
      , sub, unimm
      , data_inizio_val, data_fine_val, data_lav
      , utente, fk_tipologia)
    VALUES(strFldCod_nazionale, :NEW.foglio, :NEW.particella
      , :NEW.sub, :NEW.unimm
      , :NEW.data_inizio_val, :NEW.data_fine_val, :NEW.data_inizio_val
      , :NEW.utente, :NEW.fk_tipologia);

  END IF;  -- curFindUiuExt%FOUND


  CLOSE curFindUiuExt;


  ----------
  -- inserisco il record
  ----------
  INSERT INTO sitiedi_uiu(cod_nazionale, foglio, particella
    , sub, unimm
    , edificio, piano
    , data_inizio_val, data_fine_val, data_lav
    , utente)

  VALUES(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, :NEW.unimm
    , iFldEdificio, :NEW.piano
    , :NEW.data_inizio_val, :NEW.data_fine_val, :NEW.data_inizio_val
    , :NEW.utente);

END;
/


DROP TRIGGER SITI_H501.IMPO_SITIEDI_VANI;

CREATE OR REPLACE TRIGGER SITI_H501.IMPO_SITIEDI_VANI BEFORE INSERT ON SITI_H501.IMPO_SITIEDI_VANI
FOR EACH row
/*
a.caleffi 2009-12-17

processa l'inserimento del record nella tabella impo_sitiedi_vani inserendo il record nella tabella
sitiedi_vani previa convalida dei dati di input
*/
DECLARE
  strFldCod_nazionale VARCHAR2(4);
  iFldEdificio NUMBER(5);
  iTempValue NUMBER(5);
  iFldVano NUMBER(5);

  CURSOR curFindUiuExt(pi_strCodNazionale VARCHAR2, pi_iFoglio NUMBER, pi_strParticella VARCHAR2
    , pi_strSub VARCHAR2, pi_iUnimm NUMBER, pi_dtDataInizioVal DATE) is
  SELECT fk_tipologia
  FROM sitiedi_uiu_ext
  WHERE cod_nazionale = pi_strCodNazionale
  AND foglio = pi_iFoglio
  AND particella = pi_strParticella
  AND sub = pi_strSub
  AND unimm = pi_iUnimm
  AND pi_dtDataInizioVal BETWEEN data_inizio_val AND data_fine_val;

  iFld_fk_tipologia NUMBER(9);

BEGIN

  :NEW.piano := Upper(:NEW.piano);
  :NEW.nome_vano := upper(:NEW.nome_vano);

  ---------------------------------------
  -- cerco il codice nazionale del comune
  ---------------------------------------
  SELECT getcodnaz(:NEW.istatp, :NEW.istatc, :NEW.id_sezc)
  INTO strFldCod_nazionale
  FROM dual;

  IF (strFldCod_nazionale IS NULL) THEN
    RAISE_APPLICATION_ERROR(-20001, '(1) Errore. Codice nazionale comune non trovato istatp=[' || :NEW.istatp || '] istatc=[' || :NEW.istatc || '] id_sezc=[' || :NEW.id_sezc || ']');
  END IF;


  -------------------------------------
  -- cerco il valore del campo edificio
  -------------------------------------
  SELECT impo_sitiedi_findEdificio(:NEW.codice_edificio, :NEW.data_inizio_val)
  INTO iFldEdificio
  FROM dual;

  IF (0 = iFldEdificio) THEN
    RAISE_APPLICATION_ERROR(-20001, '(2) Errore. Codice edificio [' || :NEW.codice_edificio || '] non trovato.');
  END IF;

  -- controllo il valore del campo sub
  IF ((:NEW.sub IS NULL) or (:NEW.sub = '')) THEN
    :NEW.sub := ' ';
  END IF;

  --------------------------
  -- controllo esistenza UIU
  --------------------------
  SELECT Count(*)
  INTO iTempValue
  FROM sitiuiu
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND unimm = :NEW.unimm
  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;

  IF (0 = iTempValue) THEN
    RAISE_APPLICATION_ERROR(-20001, '(3) Errore. UIU non trovata, istatp=[' || :NEW.istatp || ']'
      || ' istatc=[' || :NEW.istatc || ']'
      || ' id_sezc=[' || :NEW.id_sezc || ']'
      || ' foglio=[' || :NEW.foglio || ']'
      || ' particella=[' || :NEW.particella || ']'
      || ' sub=[' || :NEW.sub || ']'
      || ' unimm=[' || :NEW.unimm || ']'
      || ' data_inizio_val=[' || :NEW.data_inizio_val || ']');
  END if;

  ---------------------
  -- controllo AMBIENTE
  ---------------------

  -- cerco la tipologia in base al record della tabella SITIEDI_UIU_EXT
  OPEN curFindUiuExt(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, :NEW.unimm, :NEW.data_inizio_val);

  FETCH curFindUiuExt INTO iFld_fk_tipologia;

  IF (curFindUiuExt%NOTFOUND) THEN
    RAISE_APPLICATION_ERROR(-20001, '(4) Errore. UIU non trovata in tabella SITIEDI_UIU_EXT.istatp=[' || :NEW.istatp || ']'
        || ' istatc=[' || :NEW.istatc || ']'
        || ' id_sezc=[' || :NEW.id_sezc || ']'
        || ' foglio=[' || :NEW.foglio || ']'
        || ' particella=[' || :NEW.particella || ']'
        || ' sub=[' || :NEW.sub || ']'
        || ' unimm=[' || :NEW.unimm || ']'
        || ' data_inizio_val=[' || :NEW.data_inizio_val || ']');
  END IF;


  SELECT Count(*)
  INTO iTempValue
  FROM sitiedi_supe_codes
  WHERE fk_tipologia = iFld_fk_tipologia
  AND internal_code = :NEW.ambiente;

  IF (0 = iTempValue)THEN
    RAISE_APPLICATION_ERROR(-20001, '(5) Errore. Valore Ambiente=[' || :NEW.ambiente || '] non trovato in tabella SITIEDI_SUPE_CODES con'
      || ' fk_tipologia=[' || iFld_fk_tipologia || ']');
  END IF;

  --------------------------
  -- controllo esistenza Piano
  --------------------------

  SELECT Count(*)
  INTO iTempValue
  FROM sitiedi_piani
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND piano = :NEW.piano
  AND edificio = iFldEdificio
  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;

  IF (0 = iTempValue) THEN
    RAISE_APPLICATION_ERROR(-20001, '(6) Errore. Piano [' || :NEW.piano ||'] non trovato');
  END IF;


  --------------------------------------
  -- calcolo il numero del prossimo vano
  --------------------------------------
  SELECT Count(*) +1
  INTO iFldVano
  FROM sitiedi_vani
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND unimm = :NEW.unimm;
--  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;


  -------------------
  -- inserisco record
  -------------------

  INSERT INTO sitiedi_vani(cod_nazionale, foglio, particella
    , sub, unimm
    , edificio, piano, vano
    , data_inizio_val, data_fine_val, data_lav
    , utente, nome_vano
    , ambiente, supe_ambiente
    , altezzamin, altezzamax
    , volume, perimetro)

  VALUES(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, :NEW.unimm
    , iFldEdificio, :NEW.piano, iFldVano
    , :NEW.data_inizio_val, :NEW.data_fine_val, :NEW.data_inizio_val
    , :NEW.utente, :NEW.nome_vano
    , :NEW.ambiente, :NEW.supe_ambiente
    , :NEW.altezzamin, :NEW.altezzamax
    , :NEW.volume, :NEW.perimetro);

END;
/


