DROP TRIGGER SITI_H501.INVENTA_IOFU;

CREATE OR REPLACE TRIGGER SITI_H501.INVENTA_IOFU
instead of update ON SITI_H501.INVENTA
for each row
begin

  if :old.fk_cespite is null then
    raise_application_error(-20001, '[fk_cespite is null] Impossibile modificare questo tipo di record!');
  end if;

  if :old.estrom = 'S' THEN
  	  update patri_cespiti
	     set COD_ALIQ_AMM = :new.cod_ali, DATA_AMM_INI = :new.data_amm, cod_invevend = :new.cod_invevend,
	         COD_ALIQ_AMM_FISC = :new.cod_ali_fisc, data_amm_fisc_ini = :new.data_amm_fisc,
				BUONOTA = :new.buonota, IMP_VEN = :new.imp_ven, VARIAZ = :new.variaz
	   where PK_CESPITE = :old.fk_cespite;
	ELSE
	  update patri_cespiti
	     set COD_ALIQ_AMM = :new.cod_ali, DATA_AMM_INI = :new.data_amm, cod_invevend = :new.cod_invevend,
	         COD_ALIQ_AMM_FISC = :new.cod_ali_fisc, data_amm_fisc_ini = :new.data_amm_fisc
	   where PK_CESPITE = :old.fk_cespite;
	END IF;
end;
/


DROP TRIGGER SITI_H501.IOFT_INSERT_CATA_PART;

CREATE OR REPLACE TRIGGER SITI_H501.IOFT_INSERT_CATA_PART
INSTEAD OF INSERT
ON SITI_H501.CATA_PART
FOR EACH ROW
DECLARE
  IDF NUMBER(9) := :new.id_foglio;
BEGIN

  if (IDF is null) then
    IDF:=migrazione.crea_id_foglio(:new.cod_nazionale,:new.foglio);
  end if;

  INSERT INTO cata_estremi
  (id_particella, id_foglio, particella, sub)
  VALUES
  (:NEW.id_cata_part, IDF, :new.particella, :new.sub);

END ioft_insert_cata_part;
/


