CREATE OR REPLACE TRIGGER SITI_H501.IOFT_SITIDFIU
INSTEAD OF INSERT OR UPDATE OR DELETE
ON SITI_H501.SITIDFIU
FOR EACH ROW
DECLARE
DI DATE;
DF DATE;
BEGIN

  if inserting then
    DI:=:NEW.DATA_INIZIO_VAL;
    DF:=:NEW.DATA_FINE_VAL;
    IF DI IS NULL THEN DI := SYSDATE;  END IF;
    IF DF IS NULL THEN DF := To_Date('99991231','YYYYMMDD');  END IF;

    INSERT INTO AGGR_TOPO
    (AGGR_CODE,PKID_TOPO, PREFISSO, NOME, COD_NAZIONALE, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, TIPO, NUMERO, PREFISSO_ALT, NOME_ALT, NOTE)
    VALUES
    (2,:NEW.PKID_fium, :NEW.PREFISSO, :NEW.NOME, :NEW.COD_NAZIONALE, DI, DF, :NEW.UTENTE, :NEW.TIPO, :NEW.NUMERO, :NEW.PREFISSO_ALT, :NEW.NOME_ALT, :NEW.NOTE);
  elsif updating then
    update aggr_topo
       set PREFISSO = :new.prefisso,
           NOME = :new.nome,
           COD_NAZIONALE = :new.cod_nazionale,
           DATA_INIZIO_VAL = :new.data_inizio_val,
           DATA_FINE_VAL = :new.data_fine_val,
           UTENTE = :new.utente,
           TIPO = :new.tipo,
           NUMERO = :new.numero,
           PREFISSO_ALT = :new.prefisso_alt,
           NOME_ALT = :new.nome_alt,
           NOTE = :new.note
     where AGGR_CODE = 2
       and PKID_TOPO = :old.pkid_fium
       and DATA_FINE_VAL = :old.DATA_FINE_VAL;
  elsif deleting then
    delete from aggr_topo
     where AGGR_CODE = 2
       and PKID_TOPO = :old.pkid_fium
       and DATA_FINE_VAL = :old.DATA_FINE_VAL;
  end if;
END IOFT_SITIDfiu;
/


