DROP TRIGGER SITI_H501.LOAD_CAT_UIU_IND_TR1;

CREATE OR REPLACE TRIGGER SITI_H501.LOAD_CAT_UIU_IND_TR1
before insert ON SITI_H501.LOAD_CAT_UIU_IND
for each row
declare
  flag  number;
begin
  :new.civ1 := remove_lead_zero(:new.civ1);
  :new.civ2 := remove_lead_zero(:new.civ2);
  :new.civ3 := remove_lead_zero(:new.civ3);

  select nvl(max(toDelete) + 1, 0)
    into :new.toDelete
    from load_cat_uiu_ind
   where codi_fisc_luna = :new.codi_fisc_luna
     and sezione = :new.sezione
     and id_imm = :new.id_imm
     and progressivo = :new.progressivo
     and toponimo = :new.toponimo
     and ind = :new.ind
     and ((civ1 = :new.civ1 OR civ1 IS NULL AND :NEW.civ1 IS NULL))
     and ((civ2 = :new.civ2 OR civ2 IS NULL AND :NEW.civ2 IS NULL))
     and ((civ3 = :new.civ3 OR civ3 IS NULL AND :NEW.civ3 IS NULL));

  if :new.seq is null or :new.toDelete = 0 then
    select nvl(max(seq) + 1, 0)
      into :new.seq
      from load_cat_uiu_ind
     where codi_fisc_luna = :new.codi_fisc_luna
       and sezione = :new.sezione
       and id_imm = :new.id_imm
       and progressivo = :new.progressivo;
  end if;
end;
/


