DROP TRIGGER SITI_H501.LOADICI_FAB_IDENT_DEF_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.LOADICI_FAB_IDENT_DEF_TIB
   BEFORE INSERT
   ON SITI_H501.LOADICI_FAB_IDENT_DEF
   FOR EACH ROW
DECLARE
BEGIN
