CREATE OR REPLACE TRIGGER SITI_H501.LOAD_PATRI_LOC_SPESE_TR1
  BEFORE INSERT
  ON SITI_H501.LOAD_PATRI_LOC_SPESE
  FOR EACH ROW
DECLARE
  id_atto   NUMBER;
  id_doc    NUMBER;
BEGIN
  SELECT pkid_atto
    INTO id_atto
    FROM sitidata_atti_titoli
   WHERE pkid_atto_utente = :NEW.fk_atto AND fkid_tipo_atto = -22;

  INSERT INTO patri_loc_spese
              (fk_atto, cod_fat, importo, dataini, datafin, imprate, numtrate,
               numprate, note, cod_mil, cod_bil, conguaglio, datafinprec, gruppo,
               codrisc, id_contr, compe_dal, compe_al, periodo, tipo_comp,
               ID, soc_assoc, sogg_iva, fattura, sing_cod_inq,
               id_stornato, il_id
              )
       VALUES (id_atto, :NEW.cod_fat, :NEW.importo, :NEW.dataini, :NEW.datafin, :NEW.imprate, :NEW.numtrate,
               :NEW.numprate, :NEW.note, :NEW.cod_mil, :NEW.cod_bil, :NEW.conguaglio, :NEW.datafinprec, :NEW.gruppo,
               :NEW.codrisc, :NEW.id_contr, :NEW.compe_dal, :NEW.compe_al, :NEW.periodo, :NEW.tipo_comp,
               (SELECT NVL (MAX (ID), 0) + 1 FROM patri_loc_spese), :NEW.soc_assoc, :NEW.sogg_iva, :NEW.fattura, :NEW.sing_cod_inq,
               :NEW.id_stornato, (SELECT NVL (MAX (ID), 0) + 1 FROM patri_loc_spese)
              );
EXCEPTION
  WHEN OTHERS THEN
    :NEW.ERROR_CODE := SQLCODE;
END;
/


DROP TRIGGER SITI_H501.LOAD_PATRI_LOC_TIPO_CONTR_TR1;

CREATE OR REPLACE TRIGGER SITI_H501.LOAD_PATRI_LOC_TIPO_CONTR_TR1 before insert ON SITI_H501.LOAD_PATRI_LOC_TIPO_CONTR for each row
declare
  id_atto number;
  id_doc number;
begin

  SELECT pkid_atto
    INTO id_atto
    FROM sitidata_atti_titoli
   WHERE pkid_atto_utente = :new.pkid_atto AND fkid_tipo_atto = -22;

  select ad.fkid_doc into id_doc
    from sitifile_atti_doc ad, sitifile_documenti d
   where ad.fkid_atto = id_atto
     and d.FKID_TIPO_DOC = -27
     and d.pkid_doc = ad.FKID_DOC
     and rownum = 1;

  insert into patri_loc_tipo_contr
    (FKID_DOC, COD_TIPO_CONTR, COD_CALCOLO_CANONE, FL_SOGGETTO_IVA, FL_FATT_EMISSIONE, FL_FATT_POSTICIPATA,
     FL_INTERESSI_MORA, FL_COMUNICA_AGG_CANONE, FL_RESCISSIONE, FL_ATTO_AL_LEGALE, FL_ESCLUDI_RICAL_AUT, FL_ESCLUDI_AGG_CANONE,
     FL_ESCLUDI_FATTURAZIONE, ISTAT_IPB, ISTAT_AR, ISTAT_PCT_INCREM, ISTAT_NR_ANNI_AGG, ISTAT_BASE_MESE, ISTAT_BASE_ANNO,
     OGGETTO_LOCAZIONE, N_MESI_DISDETTA, N_MESI_RESCISSIONE, N_MESI_RESCISSIONE_DAL, DATA_RESCISSIONE_DAL, DT_ULT_AGG_ISTAT, COEF_BASE,
     COSTO_BASE, COSTO_UP, SUP_CONV, ANNO_VETUS, CAN_NOISTA, AGG_ISTAT, IMP_REG, ANNI_DER, COEF_VETUS)
   values (id_doc, :new.COD_TIPO_CONTR, :new.COD_CALCOLO_CANONE, flag(:new.FL_SOGGETTO_IVA), flag(:new.FL_FATT_EMISSIONE), flag(:new.FL_FATT_POSTICIPATA),
     flag(:new.FL_INTERESSI_MORA, 'Y'), flag(:new.FL_COMUNICA_AGG_CANONE, 'Y'), flag(:new.FL_RESCISSIONE, 'Y'), flag(:new.FL_ATTO_AL_LEGALE, 'Y'), flag(:new.FL_ESCLUDI_RICAL_AUT, 'Y'), flag(:new.FL_ESCLUDI_AGG_CANONE, 'Y'),
     flag(:new.FL_ESCLUDI_FATTURAZIONE, 'Y'), :new.ISTAT_IPB, :new.ISTAT_AR, :new.ISTAT_PCT_INCREM, :new.ISTAT_NR_ANNI_AGG, :new.ISTAT_BASE_MESE, :new.ISTAT_BASE_ANNO,
     :new.OGGETTO_LOCAZIONE, :new.N_MESI_DISDETTA, :new.N_MESI_RESCISSIONE, :new.N_MESI_RESCISSIONE_DAL, :new.DATA_RESCISSIONE_DAL, :new.DT_ULT_AGG_ISTAT, :new.COEF_BASE,
     :new.COSTO_BASE, :new.COSTO_UP, :new.SUP_CONV, :new.ANNO_VETUS, :new.CAN_NOISTA, :new.AGG_ISTAT, :new.IMP_REG, :new.ANNI_DER, :new.COEF_VETUS);

exception when others then
  :new.error_code := sqlcode;
end;
/


DROP TRIGGER SITI_H501.LOADP_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.LOADP_TIB
BEFORE
INSERT
ON SITI_H501.LOADP
FOR EACH ROW
DECLARE
  TOL NUMBER(5,4) := 0.0001;
  -- HO USATO PK DI SITIPART PER CONTROLLARE SE ESISTE LA PARTICELLA, DA CARICARE, IN SITICATA
  -- (IN SITICATA ESISTE DATA_FINE E NON DATA_FINE_VAL)
  CURSOR CCENS IS SELECT 1 FROM SITICATA WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE=:NEW.DATA_FINE_VAL;
  CURSOR CCENT IS SELECT 1 FROM SITICENT WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE_VAL=:NEW.DATA_FINE_VAL;
  --CURSOR CINT IS SELECT 0 FROM SITIPART WHERE SDO_RELATE(SHAPE,:NEW.SHAPE, 'MASK=CONTAINS+INSIDE+COVERS+COVEREDBY+OVERLAPBDYINTERSECT+EQUAL') = 'TRUE';
  --CURSOR CPART IS SELECT SDO_GEOM.SDO_INTERSECTION(SHAPE,:NEW.SHAPE,TOL) AS SHAPE FROM SITIPART WHERE SDO_RELATE(SHAPE,:NEW.SHAPE, 'MASK=CONTAINS+INSIDE+COVERS+COVEREDBY+OVERLAPBDYINTERSECT+EQUAL') = 'TRUE';
  CURSOR CPART IS SELECT 1 FROM SITIPART
  WHERE SDO_RELATE(SHAPE,:NEW.SHAPE, 'MASK=CONTAINS+INSIDE+COVERS+COVEREDBY+OVERLAPBDYINTERSECT+EQUAL') = 'FALSE'
        OR (SDO_RELATE(SHAPE,:NEW.SHAPE, 'MASK=CONTAINS+INSIDE+COVERS+COVEREDBY+OVERLAPBDYINTERSECT+EQUAL') = 'TRUE'
            AND
            SDO_GEOM.SDO_AREA(SDO_GEOM.SDO_INTERSECTION(SHAPE,:NEW.SHAPE,TOL),TOL) < (SDO_GEOM.SDO_AREA(:NEW.SHAPE,TOL) / 10));
  CURSOR CPAR2 IS SELECT 1 FROM SITIPART WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB;
  CURSOR CCOMU IS SELECT 1 FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FLAG_CATA=2;
  ESISTE NUMBER(1);
BEGIN
  :NEW.COD_ERRORE := 0;

  IF BITAND(:NEW.CONTROLLI,1)=1 AND :NEW.DATA_FINE_VAL > SYSDATE THEN
    ESISTE:=0;
    OPEN CCENS;
    FETCH CCENS INTO ESISTE;
    CLOSE CCENS;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20010; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,4)=4 THEN
    ESISTE:=0;
    OPEN CCENT;
    FETCH CCENT INTO ESISTE;
    CLOSE CCENT;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20012; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,8)=8 THEN
    ESISTE:=0;
    OPEN CPART;
    FETCH CPART INTO ESISTE;
    CLOSE CPART;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20013; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,64)=64 THEN
    ESISTE:=0;
    OPEN CPAR2;
    FETCH CPAR2 INTO ESISTE;
    CLOSE CPAR2;
    IF ESISTE != 0 THEN    :NEW.COD_ERRORE:=-20016; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,128)=128 THEN
    ESISTE:=0;
    OPEN CCOMU;
    FETCH CCOMU INTO ESISTE;
    CLOSE CCOMU;
    IF ESISTE != 0 THEN :NEW.FOGLIO:=9999; END IF;
  END IF;
  /*
  IF BITAND(:NEW.CONTROLLI,4)=4 THEN
    ESISTE:=1;
    OPEN CINT;
    FETCH CINT INTO ESISTE;
    CLOSE CINT;
    IF ESISTE=0 THEN
      ESISTE:=1;
      FOR REC IN CPART
      LOOP
        IF SDO_GEOM.SDO_AREA(REC.SHAPE,TOL) >= (SDO_GEOM.SDO_AREA(:NEW.SHAPE,TOL) / 10) THEN
          ESISTE:=O;
        END IF;
      END LOOP;
    END IF;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20011; END IF;
  END IF;
  */
  IF :NEW.COD_ERRORE = 0 THEN
    IF :NEW.DATA_LAV IS NULL THEN
      :NEW.DATA_LAV:=SYSDATE;
    END IF;
    IF :NEW.DATA_INIZIO_VAL IS NULL THEN
      :NEW.DATA_INIZIO_VAL:=SYSDATE;
    END IF;

    INSERT INTO SITIPART(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,DATA_LAV,ALLEGATO,SVILUPPO,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,SHAPE,AREA_PART,DELTA_X_FOTO,DELTA_Y_FOTO,CONTRASTO,LUMINOSITA,COD_DIGI,COD_EDIF,FLAG1,FLAG2,FLAG3,SE_ROW_ID,NOTE,ISTATP,SORGENTE,TAVOLA,FLAGCARICO,STATO_PROP)
    VALUES(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DATA_LAV,:NEW.ALLEGATO,:NEW.SVILUPPO,:NEW.UTENTE,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.SHAPE,:NEW.AREA_PART,:NEW.DELTA_X_FOTO,:NEW.DELTA_Y_FOTO,:NEW.CONTRASTO,:NEW.LUMINOSITA,:NEW.COD_DIGI,:NEW.COD_EDIF,:NEW.FLAG1,:NEW.FLAG2,:NEW.FLAG3,:NEW.SE_ROW_ID,:NEW.NOTE,:NEW.ISTATP,:NEW.SORGENTE,:NEW.TAVOLA,:NEW.FLAGCARICO,:NEW.STATO_PROP);
  END IF;
EXCEPTION
   WHEN OTHERS
   THEN
      :NEW.COD_ERRORE := SQLCODE;
      IF SQLCODE = -20005 THEN
        UPDATE SITIPART SET DATA_FINE_VAL = :NEW.DATA_FINE_VAL,UTENTE_FINE = :NEW.UTENTE WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_INIZIO_VAL=:NEW.DATA_INIZIO_VAL;
        :NEW.COD_ERRORE := 0;
      ELSIF SQLCODE = -20001 THEN
        :NEW.COD_ERRORE := 0;
      END IF;
END;
/


DROP TRIGGER SITI_H501.LOADSOGG_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.LOADSOGG_TIB
  BEFORE INSERT
  ON SITI_H501.LOADSOGG
  FOR EACH ROW
DECLARE
  
  scartato			NUMBER (1);
  pkCuaa				cons_azie_tab.pk_cuaa%type;
  comuNascita		siticomu_istat.codi_fisc_luna%type;
  comuResi			siticomu_istat.codi_fisc_luna%type;
  idRappLegale	anag_soggetti.cod_soggetto%type;
  
  dtIni					date;
  dtFin					date;
  
BEGIN
  :NEW.cod_errore := 0;
  scartato := 0;
  pkCuaa := 0;
  
  if :new.COMU_NASC is null then
  	begin
    	select codi_fisc_luna into comuNascita
        from siticomu_istat
       where ISTATP = :new.COMU_NASC_ISTATP
         and ISTATC = :new.COMU_NASC_ISTATC;
    exception when no_data_found then
    	comuNascita := null;
    end;
  else
  	comuNascita := :new.COMU_NASC; 
  end if;
  
  comuResi := :new.RESI_COMU;
  
  begin
  	select pk_cuaa into idRappLegale
      from cons_azie_tab
     where cuaa = :new.cuaa
       and rownum = 1;
  exception when no_data_found then
  	idRappLegale := null;
  end;
  
  begin
  	select pk_cuaa into pkCuaa from cons_azie_tab where cuaa = :new.cuaa;
    
    update ANAG_SOGGETTI 
       set data_fine_val = :new.DATA_INIZIO - (1 / 24 / 60 / 60)
     where cod_soggetto = pkCuaa
       and DATA_FINE_VAL = to_date('99991231', 'yyyymmdd');
    
  exception when no_data_found then
  	select cons_azie_seq.nextval into pkCuaa from dual;
    
    INSERT INTO CONS_AZIE_TAB(PK_CUAA,CUAA,DATA_INIZIO,DATA_FINE,DATA_REGISTRAZIONE,UTENTE)
      VALUES(pkCuaa, :NEW.CUAA, :new.data_inizio, :new.data_fine, SYSDATE, :NEW.UTENTE);

  end;
  
  dtFin := to_date('99991231', 'yyyymmdd');
  
	INSERT INTO ANAG_SOGGETTI (PKID, COD_SOGGETTO, DENOMINAZIONE,
                              NOME, SESSO, D_NASCITA, 
                              D_MORTE, FKCOD_COMU_NASC, FKCIVICO_RESI, 
                              FLAG_PERS_FISICA, COD_FISCALE, PART_IVA, 
                              DATA_INIZIO_VAL, DATA_FINE_VAL, DATA_LAV, 
                              UTENTE_INIZIO, UTENTE_FINE, FKRAPP_LEGALE, 
                              VALIDO_INIZIO, NATURA_GIURIDICA, VALIDO_FINE, 
                              ATTO_INIZIO, ATTO_FINE, FONTE_INIZIO, 
                              FONTE_FINE, FKCOD_COMU_RESI, LOCALITA, 
                              CAP) 
	  VALUES (anag_soggetto_seq.nextval, pkCuaa, :new.RAGI_SOCI,
             :new.NOME, :new.SESSO, :new.DATA_NASC,
             :new.DATA_MORTE, comuNascita, null,
             :new.FLAG_PERS_FISICA, :new.CODI_FISC, :new.CODI_PIVA,
             :new.DATA_INIZIO, dtFin, sysdate,
             :new.UTENTE, null, idRappLegale, 'Y', :new.NATURA_GIURIDICA, 'N',
             null, null, null, 
             null, comuResi, null, null);

	  
  
END;
/


DROP TRIGGER SITI_H501.LOADS_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.LOADS_TIB
BEFORE INSERT
ON SITI_H501.LOADS
FOR EACH ROW
DECLARE
  TOL NUMBER(5,4) := 0.0001;
  -- HO USATO LA PK DI SITIPART PER CONTROLLARE SE ESISTE LA PARTICELLA, CONTENENTE IL SUOLO DA CARICARE, IN SITIPART
  CURSOR CPARTA IS SELECT 1 FROM SITIPART WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE_VAL=:NEW.DATA_FINE_VAL;
  CURSOR CPARTS IS SELECT 1 FROM SITIPART WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE_VAL=:NEW.DATA_FINE_VAL AND SDO_GEOM.SDO_AREA(SDO_GEOM.SDO_DIFFERENCE(:NEW.SHAPE,SHAPE,TOL),TOL) < (SDO_GEOM.SDO_AREA(SHAPE,TOL) / 10);
  CURSOR CSUOL IS SELECT 1 FROM SITISUOLO WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND PROG_POLIGONO=:NEW.PROG_POLIGONO;
  CURSOR CCOMU IS SELECT 1 FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FLAG_CATA=2;
  ESISTE NUMBER(1);
BEGIN
  :NEW.COD_ERRORE := 0;

  IF BITAND(:NEW.CONTROLLI,16)=16 THEN
    ESISTE:=0;
    OPEN CPARTA;
    FETCH CPARTA INTO ESISTE;
    CLOSE CPARTA;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20014; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,32)=32 THEN
    ESISTE:=0;
    OPEN CPARTS;
    FETCH CPARTS INTO ESISTE;
    CLOSE CPARTS;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20015; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,64)=64 THEN
    ESISTE:=0;
    OPEN CSUOL;
    FETCH CSUOL INTO ESISTE;
    CLOSE CSUOL;
    IF ESISTE != 0 THEN    :NEW.COD_ERRORE:=-20016; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,128)=128 THEN
    ESISTE:=0;
    OPEN CCOMU;
    FETCH CCOMU INTO ESISTE;
    CLOSE CCOMU;
    IF ESISTE != 0 THEN :NEW.FOGLIO:=9999; END IF;
  END IF;

  IF :NEW.COD_ERRORE = 0 THEN

    IF :NEW.DATA_LAV IS NULL THEN
      :NEW.DATA_LAV:=SYSDATE;
    END IF;
    IF :NEW.DATA_INIZIO_VAL IS NULL THEN
      :NEW.DATA_INIZIO_VAL:=SYSDATE;
    END IF;

    INSERT INTO SITISUOLO(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,PROG_POLIGONO,DATA_FINE_VAL,ALLEGATO,SVILUPPO,
    CAMPAGNA,UTENTE,DATA_INIZIO_VAL,DATA_LAV,AREA_COLT,COD_COLTURA,SHAPE,ANNO_FOTO,MESE_FOTO,
    COD_VARIETA,TARA,COD_UTIL,STATO_COLT,
    SORGENTE,ISTATP,TAVOLA,FLAGCARICO,STATO_PROP,GRUPPO)
    VALUES(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.PROG_POLIGONO,:NEW.DATA_FINE_VAL,:NEW.ALLEGATO,:NEW.SVILUPPO,
    :NEW.CAMPAGNA,:NEW.UTENTE,:NEW.DATA_INIZIO_VAL,:NEW.DATA_LAV,:NEW.AREA_COLT,:NEW.COD_COLTURA,:NEW.SHAPE,:NEW.ANNO_FOTO,:NEW.MESE_FOTO,
    :NEW.COD_VARIETA,:NEW.TARA,:NEW.COD_UTIL,:NEW.STATO_COLT,:NEW.SORGENTE,:NEW.ISTATP,:NEW.TAVOLA,:NEW.FLAGCARICO,:NEW.STATO_PROP,:NEW.GRUPPO);
  END IF;
EXCEPTION
   WHEN OTHERS
   THEN
      :NEW.COD_ERRORE := SQLCODE;
      IF SQLCODE = -20005 THEN
        UPDATE SITISUOLO SET DATA_FINE_VAL = :NEW.DATA_FINE_VAL,UTENTE_FINE = :NEW.UTENTE WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_INIZIO_VAL=:NEW.DATA_INIZIO_VAL;
        :NEW.COD_ERRORE := 0;
      ELSIF SQLCODE = -20001 THEN
        :NEW.COD_ERRORE := 0;
      END IF;
END ;
/


DROP TRIGGER SITI_H501.LOADT_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.LOADT_TIB
BEFORE
INSERT
ON SITI_H501.LOADT
FOR EACH ROW
DECLARE
  -- HO USATO PK DI SITITRKC PER CONTROLLARE SE ESISTE, IN SITICATA, IL CATASTO CENSUARIO DA CARICARE
  CURSOR CCENS IS SELECT 1 FROM SITICATA WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE=:NEW.DATA_FINE;
  CURSOR CTRKC IS SELECT 1 FROM SITITRKC WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB;
  CURSOR CCOMU IS SELECT 1 FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FLAG_CATA=2;
  ESISTE NUMBER(1);
BEGIN
  :NEW.COD_ERRORE := 0;

  IF BITAND(:NEW.CONTROLLI,1)=1 THEN
    ESISTE:=0;
    OPEN CCENS;
    FETCH CCENS INTO ESISTE;
    CLOSE CCENS;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20010; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,64)=64 THEN
    ESISTE:=0;
    OPEN CTRKC;
    FETCH CTRKC INTO ESISTE;
    CLOSE CTRKC;
    IF ESISTE != 0 THEN    :NEW.COD_ERRORE:=-20016; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,128)=128 THEN
    ESISTE:=0;
    OPEN CCOMU;
    FETCH CCOMU INTO ESISTE;
    CLOSE CCOMU;
    IF ESISTE != 0 THEN :NEW.FOGLIO:=9999; END IF;
  END IF;

  IF :NEW.COD_ERRORE = 0 THEN
    IF :NEW.ISTATP IS NULL THEN SELECT ISTATP INTO :NEW.ISTATP FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE; END IF;

    INSERT INTO SITITRKC(ISTATP,SIGLA_PROV,COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,DENOMINATORE,QUAL_CAT,DATA_AGGI,DATA_FINE,AREA_PART,PARTITA,UTENTE,CLASSE_TERRENO,SORGENTE,SUB_UC)
    VALUES(:NEW.ISTATP,:NEW.SIGLA_PROV,:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DENOMINATORE,:NEW.QUAL_CAT,:NEW.DATA_AGGI,:NEW.DATA_FINE,:NEW.AREA_PART,:NEW.PARTITA,:NEW.UTENTE,:NEW.CLASSE_TERRENO,:NEW.SORGENTE,:NEW.SUB_UC);
  END IF;
EXCEPTION
  WHEN OTHERS
  THEN
    :NEW.COD_ERRORE := SQLCODE;
    IF SQLCODE = -20005 THEN
      UPDATE SITITRKC SET DATA_FINE = :NEW.DATA_FINE,UTENTE_FINE = :NEW.UTENTE WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_AGGI=:NEW.DATA_AGGI;
      :NEW.COD_ERRORE := 0;
    ELSIF SQLCODE = -20001 THEN
      :NEW.COD_ERRORE := 0;
    END IF;
END;
/


DROP TRIGGER SITI_H501.LOADU_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.LOADU_TIB
BEFORE
INSERT
ON SITI_H501.LOADU
FOR EACH ROW
DECLARE
  -- HO USATO PK DI SITITRKC PER CONTROLLARE SE ESISTE, IN SITICATA, L'UNITA' ARBOREA DA CARICARE
  -- (IN SITICATA ESISTE DATA_FINE E NON DATA_FINE_VAL COME IN SITIUNAR)
  CURSOR CCENS IS SELECT 1 FROM SITICATA WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE=:NEW.DATA_FINE_VAL;
  CURSOR CUNAR IS SELECT 1 FROM SITIUNAR WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND UNAR=:NEW.UNAR;
  CURSOR CCOMU IS SELECT 1 FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FLAG_CATA=2;
  ESISTE NUMBER(1);
BEGIN
  :NEW.COD_ERRORE := 0;

  IF BITAND(:NEW.CONTROLLI,1)=1 THEN
    ESISTE:=0;
    OPEN CCENS;
    FETCH CCENS INTO ESISTE;
    CLOSE CCENS;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20010; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,64)=64 THEN
    ESISTE:=0;
    OPEN CUNAR;
    FETCH CUNAR INTO ESISTE;
    CLOSE CUNAR;
    IF ESISTE != 0 THEN    :NEW.COD_ERRORE:=-20016; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,128)=128 THEN
    ESISTE:=0;
    OPEN CCOMU;
    FETCH CCOMU INTO ESISTE;
    CLOSE CCOMU;
    IF ESISTE != 0 THEN :NEW.FOGLIO:=9999; END IF;
  END IF;

  IF :NEW.COD_ERRORE = 0 THEN
    INSERT INTO SITIUNAR(pkid_unar,cod_nazionale,foglio,particella,sub,unar,data_inizio_val,data_fine_val,data_lav,tipo_unar,area,sesto_su_fila,sesto_tra_file,num_ceppi,anno_impi,forma_all,flag_irri,cod_dest_prod,cod_tipo_colt,cod_varieta,cod_tipo_vari,utente,utente_fine,id_trasf,id_trasf_fine,num_pian_prod,num_altre,campagna,cod_tipo_vign,tipo_impi,num_cast,iden_regi,gruppo,giacitura,roccia,scheletro,stato_vegetativo,potatura,giudizio,supplementari,meccanizzabile,sorgente,dim_chioma_cm,eta_impi)
    VALUES(:NEW.pkid_unar,:NEW.cod_nazionale,:NEW.foglio,:NEW.particella,:NEW.sub,:NEW.unar,:NEW.data_inizio_val,:NEW.data_fine_val,:NEW.data_lav,:NEW.tipo_unar,:NEW.area,:NEW.sesto_su_fila,:NEW.sesto_tra_file,:NEW.num_ceppi,:NEW.anno_impi,:NEW.forma_all,:NEW.flag_irri,:NEW.cod_dest_prod,:NEW.cod_tipo_colt,:NEW.cod_varieta,:NEW.cod_tipo_vari,:NEW.utente,:NEW.utente_fine,:NEW.id_trasf,:NEW.id_trasf_fine,:NEW.num_pian_prod,:NEW.num_altre,:NEW.campagna,:NEW.cod_tipo_vign,:NEW.tipo_impi,:NEW.num_cast,:NEW.iden_regi,:NEW.gruppo,:NEW.giacitura,:NEW.roccia,:NEW.scheletro,:NEW.stato_vegetativo,:NEW.potatura,:NEW.giudizio,:NEW.supplementari,:NEW.meccanizzabile,:NEW.sorgente,:NEW.dim_chioma_cm,:NEW.eta_impi);
  END IF;
EXCEPTION
   WHEN OTHERS
   THEN
      :NEW.COD_ERRORE := SQLCODE;
      IF SQLCODE = -20005 THEN
        UPDATE SITIUNAR SET DATA_FINE_VAL = :NEW.data_fine_val,UTENTE_FINE = :NEW.utente WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND data_inizio_val=:NEW.data_inizio_val;
        :NEW.COD_ERRORE := 0;
      ELSIF SQLCODE = -20001 THEN
        :NEW.COD_ERRORE := 0;
      END IF;
END;
/


DROP TRIGGER SITI_H501.LP_CONTRATT_IOFU;

CREATE OR REPLACE TRIGGER SITI_H501.LP_CONTRATT_IOFU
  INSTEAD OF UPDATE
  ON SITI_H501.LP_CONTRATT
  REFERENCING NEW AS NEW OLD AS OLD
  FOR EACH ROW
DECLARE
  sdummy1                       VARCHAR2 (100);
  sdummy2                       VARCHAR2 (100);
  sdummy3                       VARCHAR2 (100);
  cnt                           PLS_INTEGER;
  dt_att                        DATE := TO_DATE ('99991231', 'yyyymmdd');
  max_dt                        DATE;
  m_multiple_rent               VARCHAR2 (2) := 'NO';
  exist_subloc                  PLS_INTEGER := 0;
BEGIN
  IF :OLD.codice != :NEW.codice THEN
    raise_application_error (-20001, 'Impossibile modificare il codice del contratto!');
  END IF;

  IF NOT au.equals (:OLD.data_cont, :NEW.data_cont) THEN
    raise_application_error (-20003, 'Impossibile modificare la data di decorrenza!');
  END IF;

  BEGIN
    SELECT cod_tipo_contr
      INTO sdummy3
      FROM patri_loc_tipo_contr
     WHERE fkid_doc = :OLD.pkid_doc;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      INSERT INTO patri_loc_tipo_contr
                  (fkid_doc, cod_tipo_contr
                  )
           VALUES (:OLD.pkid_doc, :NEW.cod_tcont
                  );
  END;

  -- ID_CONTR, SUP_LOCA, P_SUP_LOCA,
  IF NOT au.equals (:OLD.cod_tcont, :NEW.cod_tcont) THEN
    UPDATE patri_loc_tipo_contr
       SET cod_tipo_contr = :NEW.cod_tcont
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.canone_ini, :NEW.canone_ini) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_canone_iniziale = :NEW.canone_ini
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.canone_fin, :NEW.canone_fin) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_canone_finale = :NEW.canone_fin
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.periodo, :NEW.periodo) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_cod_periodo = :NEW.periodo
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.codrisc, :NEW.codrisc) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_cod_riscos = :NEW.codrisc
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.codcalc, :NEW.codcalc) THEN
    UPDATE patri_loc_tipo_contr
       SET cod_calcolo_canone = :NEW.codcalc
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.can_applic, :NEW.can_applic) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_cod_calcolo = :NEW.can_applic
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.can_pre_pa, :NEW.can_pre_pa) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_canone_pre_pa = :NEW.can_pre_pa
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.data_p_ini, :NEW.data_p_ini) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_dt_pagam_ini = :NEW.data_p_ini
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.cauzione, :NEW.cauzione) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_cauzione = :NEW.cauzione
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.data_d_cau, :NEW.data_d_cau) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_dt_in_cauzione = :NEW.data_d_cau
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.perc_incr, :NEW.perc_incr) THEN
    UPDATE patri_loc_tipo_contr
       SET istat_pct_increm = :NEW.perc_incr
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.istat_ipb, :NEW.istat_ipb) THEN
    UPDATE patri_loc_tipo_contr
       SET istat_ipb = :NEW.istat_ipb
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.istat_ar, :NEW.istat_ar) THEN
    UPDATE patri_loc_tipo_contr
       SET istat_ar = :NEW.istat_ar
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.annoreg, :NEW.annoreg) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_imp_reg_anno_pr = :NEW.annoreg
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.mesereg, :NEW.mesereg) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_imp_reg_mese_pr = :NEW.mesereg
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.num_reg, :NEW.num_reg) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_imp_reg_num_reg = :NEW.num_reg
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.serie_reg, :NEW.serie_reg) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_imp_reg_serie_reg = :NEW.serie_reg
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.tipo_reg, :NEW.tipo_reg) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_imposta_reg = :NEW.tipo_reg
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.freq_reg, :NEW.freq_reg) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_imposta_reg_freq = :NEW.freq_reg
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.uffi_reg, :NEW.uffi_reg) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_imp_reg_cod_uff = :NEW.uffi_reg
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.data_istat, :NEW.data_istat) THEN
    UPDATE patri_loc_tipo_contr
       SET dt_ult_agg_istat = :NEW.data_istat
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.am_istatb, :NEW.am_istatb) THEN
    UPDATE patri_loc_tipo_contr
       SET istat_base_anno = SUBSTR (:NEW.am_istatb, 1, 4),
           istat_base_mese = SUBSTR (:NEW.am_istatb, -2)
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.add_mora, :NEW.add_mora) THEN
    UPDATE patri_loc_tipo_contr
       SET fl_interessi_mora = :NEW.add_mora
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.sogg_iva, :NEW.sogg_iva) THEN
    UPDATE patri_loc_tipo_contr
       SET fl_soggetto_iva = :NEW.sogg_iva
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.fattura, :NEW.fattura) THEN
    IF :NEW.fattura = 'N' THEN
      sdummy1 := 'N';
      sdummy2 := 'N';
    ELSIF :NEW.fattura = '1' THEN
      sdummy1 := 'S';
      sdummy2 := 'N';
    ELSE
      sdummy1 := 'S';
      sdummy2 := 'S';
    END IF;

    UPDATE patri_loc_tipo_contr
       SET fl_fatt_emissione = sdummy1,
           fl_fatt_posticipata = sdummy2
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.n_anni_istat, :NEW.n_anni_istat) THEN
    UPDATE patri_loc_tipo_contr
       SET istat_nr_anni_agg = :NEW.n_anni_istat
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.posticipato, :NEW.posticipato) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_fl_rata_post = :NEW.posticipato
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.escludi_ric, :NEW.escludi_ric) THEN
    IF :NEW.escludi_ric = 'S' THEN
      sdummy1 := 'S';
      sdummy2 := 'S';
    ELSIF :NEW.escludi_ric = 'C' THEN
      sdummy1 := 'N';
      sdummy2 := 'S';
    ELSE
      sdummy1 := 'N';
      sdummy2 := 'N';
    END IF;

    UPDATE patri_loc_tipo_contr
       SET fl_escludi_rical_aut = sdummy1,
           fl_escludi_agg_canone = sdummy2
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.escludi_bol, :NEW.escludi_bol) THEN
    UPDATE patri_loc_tipo_contr
       SET fl_escludi_fatturazione = :NEW.escludi_bol
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.note_con, :NEW.note_con) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_note_contratto = :NEW.note_con
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.com_inqui, :NEW.com_inqui) THEN
    UPDATE patri_loc_tipo_contr
       SET fl_comunica_agg_canone = :NEW.com_inqui
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  -- verifico se i multicontratti sono attivi
  BEGIN
    SELECT UPPER (valore)
      INTO m_multiple_rent
      FROM gisparams
     WHERE variabile = 'MULTIPLE_RENT';
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      m_multiple_rent := 'NO';
  END;

  IF NOT au.equals (:OLD.cessazione, :NEW.cessazione) THEN
    IF (:NEW.cessazione IS NULL AND m_multiple_rent = 'NO') THEN
      -- Riapro il contratto...
      -- Controllo che non ne esista uno successivo
      SELECT COUNT (*)
        INTO cnt
        FROM cons_ufre_tab t, cons_ufre_tab t2
       WHERE t.atto_ini = :OLD.codice AND t2.cod_nazionale = t.cod_nazionale AND t2.foglio = t.foglio
             AND t2.particella = t.particella AND t2.sub = t.sub AND t2.atto_ini != :OLD.codice
             AND t2.data_inizio > t.data_inizio;

      IF cnt > 0 THEN
        raise_application_error (-20005, 'Impossibile togliere la cessazione, esiste un contratto successivo!');
      END IF;

      SELECT COUNT (*)
        INTO cnt
        FROM cons_urui_tab t, cons_urui_tab t2
       WHERE t.atto_ini = :OLD.codice AND t.fl_totale = 'Y' AND t2.cod_nazionale = t.cod_nazionale
             AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub AND t2.unimm = t.unimm
             AND t2.fl_totale = 'Y' AND t2.atto_ini != :OLD.codice AND t2.data_inizio > t.data_inizio;

      IF cnt > 0 THEN
        raise_application_error (-20005, 'Impossibile togliere la cessazione, esiste un contratto successivo!');
      END IF;
    ELSIF (:NEW.cessazione IS NOT NULL) THEN
      -- verifico se il contratto  associato ad una sublocazione in essere
      SELECT COUNT (*)
        INTO exist_subloc
        FROM cons_subloc_tab
       WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND data_inizio < :NEW.cessazione AND data_fine > :NEW.cessazione;

      IF (exist_subloc > 0) THEN
        raise_application_error
                         (-20011,
                          'Non  possibile cessare il contratto di locazione:  in corso di validit una sublocazione.');
      END IF;

      -- Controllo che non cessi prima dell'inizio...
      SELECT MAX (data_inizio)
        INTO max_dt
        FROM (SELECT data_inizio
                FROM cons_urui_tab
               WHERE atto_ini = :OLD.codice
              UNION
              SELECT data_inizio
                FROM cons_ufre_tab
               WHERE atto_ini = :OLD.codice);

      IF (max_dt > :NEW.cessazione) THEN
        raise_application_error (-20004, 'Data cessazione minore di data contratto!');
      END IF;

      IF :OLD.cessazione >= dt_att THEN
        -- se era attuale controllo che non esista un altro contratto...
        IF (m_multiple_rent = 'NO') THEN
          SELECT COUNT (*)
            INTO cnt
            FROM cons_ufre_tab t, cons_ufre_tab t2
           WHERE t.atto_ini = :OLD.codice AND t2.cod_nazionale = t.cod_nazionale AND t2.foglio = t.foglio
                 AND t2.particella = t.particella AND t2.sub = t.sub AND t2.atto_ini != :OLD.codice
                 AND t2.data_inizio < :NEW.cessazione AND t2.data_fine > :NEW.cessazione;

          IF cnt = 0 THEN
            -- per le UIU controllo solo i contratti "totali"
            SELECT COUNT (*)
              INTO cnt
              FROM cons_urui_tab t, cons_urui_tab t2
             WHERE t.atto_ini = :OLD.codice AND t.fl_totale = 'Y' AND t2.cod_nazionale = t.cod_nazionale
                   AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub AND t2.unimm = t.unimm
                   AND t2.fl_totale = 'Y' AND t2.atto_ini ! = :OLD.codice AND t2.data_inizio < :NEW.cessazione
                   AND t2.data_fine > :NEW.cessazione;
          END IF;

          IF cnt > 0 THEN
            -- esiste gi un contratto successivo....
            raise_application_error (-20004, 'Esiste un contratto in vigore alla data specificata!');
          END IF;
        END IF;
      END IF;
    END IF;

    -- Modifico i dati
    max_dt := NULL;

    IF (:NEW.cessazione IS NULL) THEN
      -- Tolgo cessazione, riapro solo quelli che hanno max(data_fine)
      -- perch sono quelli che sono stati precedentemente cessati
      SELECT MAX (data_fine)
        INTO max_dt
        FROM (SELECT data_fine
                FROM cons_urui_tab
               WHERE atto_ini = :OLD.codice
              UNION
              SELECT data_fine
                FROM cons_ufre_tab
               WHERE atto_ini = :OLD.codice);
    ELSE
      -- Imposto cessazione...
      IF (:OLD.cessazione IS NULL) THEN
        -- Era un contratto attivo...
        max_dt := dt_att;
      ELSE
        -- Era gi cessato, sto spostando la data per correzione...
        max_dt := :OLD.cessazione;
      END IF;
    END IF;

    UPDATE cons_ufre_tab
       SET data_fine = NVL (:NEW.cessazione, dt_att)
     WHERE atto_ini = :OLD.codice AND data_fine = max_dt;

    UPDATE cons_urui_tab
       SET data_fine = NVL (:NEW.cessazione, dt_att)
     WHERE atto_ini = :OLD.codice AND data_fine = max_dt;

    UPDATE cons_urui_vani
       SET data_fine_val = NVL (:NEW.cessazione, dt_att)
     WHERE id_atto = :OLD.codice AND data_fine_val = max_dt;

    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_dt_fine = NVL (:NEW.cessazione, dt_att)
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.accr_int_dp, :NEW.accr_int_dp) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_fl_int_cauzione = :NEW.accr_int_dp
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.natura_dp, :NEW.natura_dp) THEN
    UPDATE sitifile_documenti_campi_ext
