     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.scadenza_dp, :NEW.scadenza_dp) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_dt_scad_cauzione = :NEW.scadenza_dp
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.data_rest_dp, :NEW.data_rest_dp) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_dt_out_cauzione = :NEW.data_rest_dp
