  END IF;

  IF NOT au.equals (:OLD.rescissione_inq, :NEW.rescissione_inq) THEN
    UPDATE patri_loc_tipo_contr
       SET fl_rescissione = :NEW.rescissione_inq
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.n_mesi_rescis, :NEW.n_mesi_rescis) THEN
