     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.imposta_dep, :NEW.imposta_dep) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_fl_imp_reg_cauz = :NEW.imposta_dep
