  END IF;

  IF NOT au.equals (:OLD.spese_dep2, :NEW.spese_dep2) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_spese_dep2 = :NEW.spese_dep2
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.cod_trib_dep2, :NEW.cod_trib_dep2) THEN
    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_cod_trib_dep2 = :NEW.spese_dep2
