DROP TRIGGER SITI_H501.PATRI_CESPITI_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.PATRI_CESPITI_TIB
before insert or update ON SITI_H501.PATRI_CESPITI
for each row
begin
  if inserting then
    if :new.pk_cespite is null then
      select patri_cespiti_seq.nextval into :new.pk_cespite from dual;
    end if;
    if :new.num_inventario is null then
      select nvl(max(num_inventario) + 1, 1)
        into :new.num_inventario
        from patri_cespiti;
    end if;
  end if;
  if :new.data_lav is null then
    :new.data_lav := sysdate;
  end if;

  if updating then
    if :new.data_lav=:old.data_lav then
        :new.data_lav := sysdate;
    end if;
    if  not(
        au.equals(:new.COD_CESPITE,:old.COD_CESPITE)        and
        au.equals(:new.cod_cat_inv,:old.cod_cat_inv)        and
        au.equals(:new.cod_cat_ces,:old.cod_cat_ces)        and
        au.equals(:new.val_terre,:old.val_terre)            and au.equals(:new.val_terre_f,:old.val_terre_f) and
        au.equals(:new.VAL_BENE,:old.VAL_BENE)              and au.equals(:new.val_tot_f,:old.val_tot_f) and
        au.equals(:new.RIVALUTAZIONI,:old.RIVALUTAZIONI)    and
        au.equals(:new.VAL_ATTUALE,:old.VAL_ATTUALE)        and au.equals(:new.VAL_ATTUALE_F,:old.VAL_ATTUALE_F) and
        au.equals(:new.VAL_RESIDUO,:old.VAL_RESIDUO)        and au.equals(:new.VAL_RESIDUO_F,:old.VAL_RESIDUO_F) and
        au.equals(:new.ULT_AMM_IMPO,:old.ULT_AMM_IMPO)      and au.equals(:new.ULT_AMM_IMPO_F,:old.ULT_AMM_IMPO_F) --and
        --au.equals(:new.utente_ini,:old.utente_ini)
        ) then



        insert into patri_cespiti_stor
        (
              PK_CESPITE         ,--
              COD_CESPITE        ,--
              COD_CAT_INV        ,--
              COD_CAT_CES        ,--
              VAL_BENE           ,--
              VAL_ATTUALE        ,--
              VAL_RESIDUO        ,--
              RIVALUTAZIONI      ,--
              ULT_AMM_IMPO       ,--
              VAL_ATTUALE_F      ,--
              VAL_RESIDUO_F      ,--
              ULT_AMM_IMPO_F     ,--
              VAL_TOT_F          ,--
              VAL_TERRE_F        ,--
              VAL_TERRE          ,--
              utente_ini         ,
              DATA_STOR
        )
        values
        (
              :old.PK_CESPITE         ,--
              :old.COD_CESPITE        ,--
              :old.COD_CAT_INV        ,--
              :old.COD_CAT_CES        ,--
              :old.VAL_BENE           ,--
              :old.VAL_ATTUALE        ,--
              :old.VAL_RESIDUO        ,--
              :old.RIVALUTAZIONI      ,--
              :old.ULT_AMM_IMPO       ,--
              :old.VAL_ATTUALE_F      ,--
              :old.VAL_RESIDUO_F      ,--
              :old.ULT_AMM_IMPO_F     ,--
              :old.VAL_TOT_F          ,--
              :old.VAL_TERRE_F        ,--
              :old.VAL_TERRE          ,--
              :old.utente_ini         ,
              :new.data_lav

        );
    end if;
  end if;

end;
/


DROP TRIGGER SITI_H501.PATRI_PART_EXT_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.PATRI_PART_EXT_TIB
