DROP TRIGGER SITI_H501.SITICIVI_TR1;

CREATE OR REPLACE TRIGGER SITI_H501.SITICIVI_TR1
instead of insert or update or delete
ON SITI_H501.SITICIVI
for each row
begin
  if inserting then
  	 insert into AGGR_LOCALIZZA (PKID_LOC, fkid_type, PKID_TOPO, COD_NAZIONALE, NOME, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, SHAPE, NOTE, UTENTE_FINE, ID_TRASF, ID_TRASF_FINE)
	   values (:new.pkid_civi, -1, :new.pkid_stra, :new.COD_NAZIONALE, :new.civico, :new.DATA_INIZIO_VAL, :new.DATA_FINE_VAL, :new.UTENTE, :new.SHAPE, :new.NOTE, :new.UTENTE_FINE, :new.ID_TRASF, :new.ID_TRASF_FINE);
  elsif updating then
    UPDATE AGGR_LOCALIZZA SET
	   PKID_LOC        = :new.PKID_civi,
       PKID_TOPO       = :new.PKID_stra,
       COD_NAZIONALE   = :new.COD_NAZIONALE,
       NOME            = :new.civico,
       DATA_INIZIO_VAL = :new.DATA_INIZIO_VAL,
       DATA_FINE_VAL   = :new.DATA_FINE_VAL,
       UTENTE          = :new.UTENTE,
       SHAPE           = :new.SHAPE,
       NOTE            = :new.NOTE,
       UTENTE_FINE     = :new.UTENTE_FINE,
       ID_TRASF        = :new.ID_TRASF,
       ID_TRASF_FINE   = :new.ID_TRASF_FINE
     WHERE PKID_LOC = :old.PKID_civi;
  else
    delete from AGGR_LOCALIZZA where pkid_loc = :old.pkid_civi;
  end if;
end;
/


