DROP TRIGGER SITI_H501.SITICIVI_UIU_TR1;

CREATE OR REPLACE TRIGGER SITI_H501.SITICIVI_UIU_TR1 
instead of insert or update or delete 
ON SITI_H501.SITICIVI_UIU 
for each row
begin 
  if inserting then 
  	 insert into sitiloc_uiu (fkid_type, PKID_LOC, PKID_UIU, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, SCALA, PIANO, INTERNO, UTENTE_FINE, PRINCIPALE) 
	   values (-1, :new.pkid_civi, :new.PKID_UIU, :new.DATA_INIZIO_VAL, :new.DATA_FINE_VAL, :new.UTENTE, :new.SCALA, :new.PIANO, :new.INTERNO, :new.UTENTE_FINE, :new.PRINCIPALE); 
  elsif updating then 
    UPDATE SITILOC_UIU 
	   SET PKID_LOC        = :new.PKID_CIVI, 
           PKID_UIU        = :new.PKID_UIU, 
           DATA_INIZIO_VAL = :new.DATA_INIZIO_VAL, 
           DATA_FINE_VAL   = :new.DATA_FINE_VAL, 
       	   UTENTE          = :new.UTENTE, 
	       SCALA           = :new.SCALA, 
		   PIANO           = :new.PIANO, 
		   INTERNO         = :new.INTERNO, 
		   UTENTE_FINE     = :new.UTENTE_FINE, 
       	   PRINCIPALE      = :new.PRINCIPALE 
		where PKID_LOC     = :old.PKID_CIVI 
		  and PKID_UIU     = :old.PKID_UIU; 
    null; 
  else 
    delete from SITILOC_UIU where pkid_loc = :old.pkid_civi; 
  end if; 
end;
/


