  END IF;

  IF :NEW.se_row_id IS NULL or :NEW.se_row_id = 0 THEN
    SELECT SITIEDI_PIANI_SEQ.NEXTVAL INTO :NEW.SE_ROW_ID FROM DUAL;
  END IF;
  :NEW.DATA_FINE_VAL := UPDATE_PATRI_DATA.SCADI_LIVELLI(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.PIANO,:NEW.EDIFICIO,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE);

