	UPDATE SITISUOLO SET SHAPE=SDO_TOOLS.OFFSET(SHAPE,:NEW.DELTAX,:NEW.DELTAY) WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
	UPDATE SITIPIANTE SET SHAPE=SDO_TOOLS.OFFSET(SHAPE,:NEW.DELTAX,:NEW.DELTAY) WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
	UPDATE SITIFOTC SET SHAPE=SDO_TOOLS.OFFSET(SHAPE,:NEW.DELTAX,:NEW.DELTAY) WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
