DROP TRIGGER SITI_H501.SITIPIANTE_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.SITIPIANTE_TIB
BEFORE INSERT
ON SITI_H501.SITIPIANTE
FOR EACH ROW
DECLARE
	IDF NUMBER(9);
BEGIN
	IF :NEW.SE_ROW_ID IS NULL THEN
    SELECT SITIPIANTE_SEQ.NEXTVAL INTO :NEW.SE_ROW_ID FROM DUAL;
  END IF;

  IF :NEW.COD_NAZIONALE IS NULL AND :NEW.ID_PARTICELLA IS NOT NULL THEN
    SELECT
    COD_NAZIONALE,FOGLIO,PARTICELLA,SUB
    INTO
    :NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB
    FROM CATA_PART WHERE ID_CATA_PART = :NEW.ID_PARTICELLA;
  END IF;

  IF :NEW.ID_PARTICELLA IS NULL AND :NEW.COD_NAZIONALE IS NOT NULL THEN
    IDF:=MIGRAZIONE.CREA_ID_FOGLIO(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
    :NEW.ID_PARTICELLA:=MIGRAZIONE.CREA_ID_PARTICELLA(IDF,:NEW.PARTICELLA, :NEW.SUB);
  END IF;

  IF :NEW.SORGENTE > 0 THEN
      :NEW.DATA_FINE_VAL := UPDATE_GIS_DATA.SCADI_PIANTE(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE,:NEW.PROG_POLIGONO,:NEW.STATO_PROP,:NEW.ID_TRASF);
      IF :NEW.SORGENTE = 3 THEN
        IF :NEW.STATO_PROP=0 THEN
          UPDATE SITIPIANTE SET STATO_PROP=0,VALI_PROD=2 WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND STATO_PROP > 0 AND DATA_INIZIO_VAL < :NEW.DATA_INIZIO_VAL;
        END IF;
        SITIUTILS.AGG_ANOM_REFR(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
      END IF;
   END IF;
END;
/


