DROP TRIGGER SITI_H501.SITIPLAV_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.SITIPLAV_TIB
BEFORE INSERT
ON SITI_H501.SITIPLAV
FOR EACH ROW
DECLARE
	STMT  VARCHAR2(2048);
	VCOUNT INTEGER;
BEGIN
	IF :NEW.ISTATP IS NULL THEN
		SELECT SITICOMU.ISTATP INTO :NEW.ISTATP FROM SITICOMU WHERE SITICOMU.COD_NAZIONALE=:NEW.COD_NAZIONALE;
	END IF;
	IF :NEW.prog_lav IS NULL THEN
		STMT := 'SELECT MAX(prog_lav) FROM SITIPLAV WHERE COD_NAZIONALE=''' || :NEW.COD_NAZIONALE || ''' AND FOGLIO=' || :NEW.FOGLIO || ' AND PARTICELLA=''' || :NEW.PARTICELLA ||''' AND SUB=''' || :NEW.SUB ||''' AND ID_LAV=' || :NEW.ID_LAV;
		EXECUTE IMMEDIATE STMT INTO VCOUNT;
		IF VCOUNT IS NULL THEN
			:NEW.prog_lav:=1;
		ELSE
			:NEW.prog_lav:=VCOUNT+1;
		END IF;
	END IF;

  IF :NEW.PROG_LAV > 1 then
			UPDATE SITIPLAV SET LAST=0 WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND ID_LAV=:NEW.ID_LAV AND LAST=1;
  END IF;
END;
/


