  IF (INSERTING AND :NEW.ID_PARTICELLA IS NULL) OR (UPDATING AND (:OLD.ID_PARTICELLA IS NULL OR :NEW.ID_PARTICELLA IS NULL)) THEN
    :NEW.ID_PARTICELLA := MIGRAZIONE.CREA_ID_PARTICELLA_ESTREMI(:NEW.COD_NAZIONALE, :NEW.FOGLIO, :NEW.PARTICELLA, :NEW.SUB);
  END IF;
