DROP TRIGGER SITI_H501.SITITRKC_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.SITITRKC_TIB
BEFORE
INSERT
ON SITI_H501.SITITRKC
FOR EACH ROW
BEGIN
  SELECT SITITRKC_SEQ.NEXTVAL INTO :NEW.TRKC_ID FROM DUAL;
  IF :NEW.SUB='0' OR :NEW.SUB='00' OR :NEW.SUB='000' THEN :NEW.SUB:=' '; END IF;

  IF :NEW.DATA_FINE IS NULL THEN :NEW.DATA_FINE:=TO_DATE('99991231000000','YYYYMMDDHH24MISS'); END IF;

  if :new.flag_provenienza != 'F' then
    -- Se import da catasto ignoro... --
    :NEW.DATA_FINE := UPDATE_GIS_DATA.SCADI_TRKC(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DATA_AGGI,:NEW.DATA_FINE,:NEW.UTENTE,0,:NEW.ID_TRASF);
  end if;

  IF :NEW.VALIDA IS NULL THEN
    IF :NEW.DATA_FINE = TO_DATE('99991231000000','YYYYMMDDHH24MISS') THEN
      :NEW.VALIDA:=1;
    ELSE
      :NEW.VALIDA:=0;
    END IF;
  END IF;
  SITIUTILS.AGG_ANOM_REFR (:NEW.COD_NAZIONALE, :NEW.FOGLIO);
END;
/


