BEGIN
    if :new.ID_PARTICELLA is null then
      begin
        SELECT  ID_CATA_PART
          INTO :NEW.ID_PARTICELLA
          FROM CATA_PART
          WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE
            AND FOGLIO       =:NEW.FOGLIO
            and PARTICELLA   =:new.PARTICELLA
            AND SUB          =:NEW.SUB;
      EXCEPTION
      when no_data_found  then
        :NEW.ID_PARTICELLA:=null;
      END;
    END IF;
  END;
/


