  IF :NEW.PKID_UIU IS NULL THEN
    SELECT SITIUIU_SEQ.NEXTVAL INTO :NEW.PKID_UIU FROM DUAL;
  END IF;
  IF :NEW.FLAG_PROVENIENZA != 'F' THEN
    :NEW.DATA_FINE_VAL := UPDATE_PATRI_DATA.SCADI_UIU(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.UNIMM,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE);
  END IF;
  IF :NEW.COD_NAZIONALE_URBA IS NULL THEN
    :NEW.COD_NAZIONALE_URBA := :NEW.COD_NAZIONALE;
  END IF;
  IF :NEW.FOGLIO_URBA IS NULL OR :NEW.FOGLIO_URBA = 0 THEN
    :NEW.FOGLIO_URBA := :NEW.FOGLIO;
  END IF;
  IF :NEW.PARTICELLA_URBA IS NULL THEN
    :NEW.PARTICELLA_URBA := :NEW.PARTICELLA;
  END IF;
  IF :NEW.SUB_URBA IS NULL THEN
    :NEW.SUB_URBA := :NEW.SUB;
