DROP TRIGGER SITI_H501.SOCIETA_IOFU;

CREATE OR REPLACE TRIGGER SITI_H501.SOCIETA_IOFU
instead of update ON SITI_H501.SOCIETA
declare
  cnt pls_integer;
begin
  if (:new.cod_soc is not null) then

    select count(*) into cnt
      from anag_soggetti_ext
     where cod_soggetto = :new.cod_soc;

    if (cnt = 0) then
      insert into anag_soggetti_ext (cod_soggetto) values (:new.cod_soc);
    end if;

    update anag_soggetti_ext
       set banca = :new.banca, cab = :new.cab, abi = :new.abi, c_c = :new.c_c,
           cin = :new.cin, soc_dip_num = :new.soc_dip_num, prog_bol = :new.prog_bol,
           prog_fat = :new.prog_fat, nfile_fat = :new.nfile_fat, nfile_bol = :new.nfile_bol,
           mod_cont = :new.mod_cont, nfile_cont = :new.nfile_cont, nfile_contpag = :new.nfile_contpag,
           nfile_ritcont = :new.nfile_ritcont, codsocute = :new.codsocute, fattura = :new.fattura,
           add_mora = :new.add_mora, accr_int_dp = :new.accr_int_dp, mod_rendi = :new.mod_rendi,
           tribunale = :new.tribunale, cciaa = :new.cciia, fisso_nloc = :new.fisso_nloc,
           fisso_uiu = :new.fisso_uiu, note = :new.note, perc_ricavi = :new.perc_ricavi,
           data_bol = :new.data_bol, scadenza = :new.scadenza, data_fat = :new.data_fat,
           nfile_continc = :new.nfile_continc, titolo = :new.titolo, mod_contpas = :new.mod_contpas,
           nfile_contpas = :new.nfile_contpas, prog_bol_pas = :new.prog_bol_pas, data_bol_pas = :new.data_bol_pas,
           nfile_bolpas = :new.nfile_bolpas, mod_continve = :new.mod_continve, nfile_continve = :new.nfile_continve,
           soc_assoc = :new.soc_assoc, COD_PERSO_COSTI = :new.COD_PERSO_COSTI, nfile_costi_imp = :new.nfile_costi_imp,
           nfile_costi_exp = :new.nfile_costi_exp, cod_perso_vend = :new.cod_perso_vend,
           IBAN_PAESE = :new.IBAN_PAESE, IBAN_CIN_EUR = :new.IBAN_CIN_EUR
     where cod_soggetto = :new.cod_soc;
  end if;
end;
/


DROP TRIGGER SITI_H501.SPESE_IOFIU;

CREATE OR REPLACE TRIGGER SITI_H501.SPESE_IOFIU
instead of insert or update ON SITI_H501.SPESE
for each row
begin
  if inserting then
    insert into patri_loc_spese (FK_ATTO, COD_FAT, IMPORTO, DATAINI, DATAFIN, IMPRATE, NUMTRATE, NUMPRATE, NOTE, COD_MIL, COD_BIL, CONGUAGLIO, DATAFINPREC, GRUPPO, CODRISC, ID_CONTR, COMPE_DAL, COMPE_AL, PERIODO, TIPO_COMP, ID, SOC_ASSOC, SOGG_IVA, FATTURA, SING_COD_INQ, ID_STORNATO)
      values (:new.codice, :new.COD_FAT, :new.IMPORTO, to_date(:new.DATAINI, 'dd/mm/yyyy'),
              to_date(:new.DATAFIN, 'dd/mm/yyyy'), :new.IMPRATE, :new.NUMTRATE, :new.NUMPRATE, :new.NOTE, :new.COD_MIL,
              :new.COD_BIL, :new.CONGUAGLIO, to_date(:new.DATAFINPREC, 'dd/mm/yyyy'), :new.GRUPPO, :new.CODRISC,
              :new.ID_CONTR, :new.COMPE_DAL, :new.COMPE_AL, :new.PERIODO, :new.TIPO_COMP, :new.ID,
              :new.SOC_ASSOC,
              :new.SOGG_IVA, :new.FATTURA, :new.SING_COD_INQ, :new.ID_STORNATO);
  else
    update patri_loc_spese
       set cod_fat = :new.COD_FAT, importo = :new.IMPORTO, dataini = to_date(:new.DATAINI, 'dd/mm/yyyy'),
           datafin = to_date(:new.DATAFIN, 'dd/mm/yyyy'), imprate = :new.IMPRATE, numtrate = :new.NUMTRATE,
           numprate = :new.NUMPRATE, note = :new.NOTE, cod_mil = :new.COD_MIL, cod_bil = :new.COD_BIL,
           conguaglio = :new.CONGUAGLIO, datafinprec = to_date(:new.DATAFINPREC, 'dd/mm/yyyy'), gruppo = :new.GRUPPO,
           codrisc = :new.CODRISC, id_contr = :new.ID_CONTR, compe_dal = :new.COMPE_DAL, compe_al = :new.COMPE_AL,
           periodo = :new.PERIODO, tipo_comp = :new.TIPO_COMP, soc_assoc = :new.SOC_ASSOC,
           sogg_iva = :new.SOGG_IVA, fattura = :new.FATTURA, sing_cod_inq = :new.SING_COD_INQ, id_stornato = :new.ID_STORNATO
     where fk_atto = :old.codice and id = :old.id;
  end if;
end;
/


DROP TRIGGER SITI_H501.SSO_USERS_TR1;

CREATE OR REPLACE TRIGGER SITI_H501.SSO_USERS_TR1
before update or delete ON SITI_H501.SSO_USERS
for each row
begin

  if deleting or (updating and :old.password != :new.password) then
    delete from sso_pwd_warnings where userid=:old.userid;
  end if;

end;
/


DROP TRIGGER SITI_H501.SUBENTRO_TR1;

CREATE OR REPLACE TRIGGER SITI_H501.SUBENTRO_TR1
  BEFORE INSERT
  ON SITI_H501.SUBENTRO
  REFERENCING NEW AS NEW OLD AS OLD
  FOR EACH ROW
DECLARE
  dt_start                      DATE := :NEW.data_uscita_out;
  dt_end                        DATE := dt_start - (1 / 60 / 60 / 24);
  dt_check                      DATE := NULL;
  tmp_data_fine                 DATE := NULL;
  tmp_data_inizio               DATE := NULL;
  dt_fine_cntr                  DATE := NULL;
  dt_last_out                   DATE := NULL;
  pk_cuaa_out                   cons_ufre_tab.pk_cuaa%TYPE;
  new_id_co                     PLS_INTEGER;
  is_subloc                     PLS_INTEGER := 0;
  cnt                           NUMBER := 0;
  isdeletable                   NUMBER := 0;
  err_code                      NUMBER := NULL;
  err_msg                       VARCHAR2 (4000) := '';
BEGIN
  -- selezione dei dati del vecchio inquilino
  IF :NEW.id_co_out IS NOT NULL THEN
    SELECT cod_inq
      INTO pk_cuaa_out
      FROM cointestatari
     WHERE codice = :NEW.codice AND id_co = :NEW.id_co_out;
  ELSE
    pk_cuaa_out := NULL;
  END IF;

  -- verifico che il codice dell'inquilino che subentra non sia lo stesso di quello che esce
  IF :NEW.cod_inq_in IS NOT NULL AND CAST (:NEW.cod_inq_in AS NUMBER) = pk_cuaa_out THEN
    err_code := -20002;
    err_msg := 'Il soggetto che subentra coincide con il soggetto che cessa';
    patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                            :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out, err_code,
                            err_msg);
    raise_application_error (err_code, err_msg);
  END IF;

  -- verifico se il soggetto uscente ï¿½ da cancellare fisicamente dal db (correzione di errore)
  IF :NEW.data_uscita_out IS NULL THEN
    IF pk_cuaa_out IS NULL THEN
      err_code := -20005;
      err_msg := 'La correzione non ï¿½ possibile: non ï¿½ stato specificato l''inquilino ';
      patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                              :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out, err_code,
                              err_msg);
      raise_application_error (err_code, err_msg);
    END IF;

    -- flag di correzione attivato
    isdeletable := 1;

    -- verifico se l'inquilino era giï¿½ uscito altre volte
    SELECT MAX (data_uscita)
      INTO dt_last_out
      FROM patri_loc_cointesta
     WHERE fk_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND id_co >= 50000;

    -- poichï¿½ la data di uscita ï¿½ nulla devo ricercare fin da quando il soggetto era inquilino
    IF dt_last_out IS NULL THEN
      -- l'inquilino NON era giï¿½ uscito altre volte
      SELECT MIN (data_inizio)
        INTO dt_start
        FROM (SELECT data_inizio
                FROM cons_ufre_tab
               WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out
              UNION
              SELECT data_inizio
                FROM cons_urui_tab
               WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out
              UNION
              SELECT data_inizio
                FROM cons_subloc_tab
               WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out);
    ELSE
      -- l'inquilino era giï¿½ uscito altre volte, quindi la data di inizio della correzione deve essere maggiore dell'ultima data
      -- di cessazione
      SELECT MIN (data_inizio)
        INTO dt_start
        FROM (SELECT data_inizio
                FROM cons_ufre_tab
               WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > dt_last_out
              UNION
              SELECT data_inizio
                FROM cons_urui_tab
               WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > dt_last_out
              UNION
              SELECT data_inizio
                FROM cons_subloc_tab
               WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > dt_last_out);
    END IF;

    IF dt_start IS NULL THEN
      err_code := -20006;
      err_msg := 'Non ï¿½ stata trovata la data iniziale della correzione';
      patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                              :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out, err_code,
                              err_msg);
      raise_application_error (err_code, err_msg);
    END IF;

    dt_end := dt_start - (1 / 60 / 60 / 24);
  ELSE
    -- flag di correzione disattivato
    isdeletable := 0;
  END IF;

  -- verifico che l'inquilino che esce fosse nel contratto alla data di cessazione
  IF :NEW.id_co_out IS NOT NULL AND pk_cuaa_out IS NOT NULL AND :NEW.data_uscita_out IS NOT NULL THEN
    SELECT COUNT (*)
      INTO cnt
      FROM (SELECT DISTINCT pk_cuaa
                       FROM cons_ufre_tab
                      WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio < :NEW.data_uscita_out
                            AND data_fine > :NEW.data_uscita_out AND pk_cuaa = pk_cuaa_out
            UNION
            SELECT DISTINCT pk_cuaa
                       FROM cons_urui_tab
                      WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio < :NEW.data_uscita_out
                            AND data_fine > :NEW.data_uscita_out AND pk_cuaa = pk_cuaa_out
            UNION
            SELECT DISTINCT pk_cuaa
                       FROM cons_subloc_tab
                      WHERE atto_inizio = CAST (:NEW.codice AS NUMBER) AND data_inizio < :NEW.data_uscita_out
                            AND data_fine > :NEW.data_uscita_out AND pk_cuaa = pk_cuaa_out);

    IF cnt = 0 THEN
      err_code := -20009;
      err_msg := 'Il soggetto che cessa non era inquilino del contratto alla data selezionata';
      patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                              :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out, err_code,
                              err_msg);
      raise_application_error (err_code, err_msg);
    END IF;
  END IF;

  -- verifico se il contratto ï¿½ di sublocazione
  SELECT DECODE (parent_contratt_id, NULL, 0, 1)
    INTO is_subloc
    FROM contratt
   WHERE codice = :NEW.codice;

  IF is_subloc = 0 THEN                                                            -- il contratto NON ï¿½ di sublocazione
    -- verifico se vi ï¿½ cessazione senza subentro (il contratto non puï¿½ essere chiuso facendo cessare l'unico inquilino)
    IF pk_cuaa_out IS NOT NULL AND :NEW.cod_inq_in IS NULL THEN
      -- verifico il numero di inquilini , se = 1 lancio un'eccezione
      SELECT COUNT (*)
        INTO cnt
        FROM (SELECT DISTINCT pk_cuaa
                         FROM cons_ufre_tab
                        WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio <= dt_start
                              AND data_fine >= dt_start
              UNION
              SELECT DISTINCT pk_cuaa
                         FROM cons_urui_tab
                        WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio <= dt_start
                              AND data_fine >= dt_start);

      IF cnt = 1 THEN
        err_code := -20003;
        err_msg := 'Non ï¿½ possibile far cessare l''unico soggetto intestatario del contratto di locazione';
        patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                                :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out,
                                err_code, err_msg);
        raise_application_error (err_code, err_msg);
      END IF;
    END IF;

    -- creo i nuovi titoli
    IF :NEW.cod_inq_in IS NOT NULL AND isdeletable = 0 THEN        -- isDeleteble = 1 sarï¿½ risolta dal codice piï¿½ in giï¿½
      -- se non c'ï¿½ cessazione ma solo nuovi inquilini
      IF :NEW.id_co_out IS NULL THEN
        -- prendo la data di fine massima del contratto
        SELECT MAX (data_fine)
          INTO dt_fine_cntr
          FROM (SELECT data_fine
                  FROM cons_ufre_tab
                 WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_fine > dt_start
                UNION
                SELECT data_fine
                  FROM cons_urui_tab
                 WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_fine > dt_start);

        IF dt_fine_cntr IS NULL THEN
          err_code := -20010;
          err_msg := 'La data di inserimento del contratto ï¿½ posteriore alla sua data di scadenza';
          patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                                  :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out,
                                  err_code, err_msg);
          raise_application_error (err_code, err_msg);
        END IF;

        -- non avendo l'inquilino che esce come riferimento ne prendo uno a caso tra quelli esistenti alla data di inserimento del nuovo inquilino
        -- e che risultano attiva
        BEGIN
          SELECT pk_cuaa,
                 data_fine
            INTO pk_cuaa_out,
                 tmp_data_fine
            FROM (SELECT   pk_cuaa,
                           data_fine
                      FROM (SELECT DISTINCT pk_cuaa,
                                            MAX (data_fine) AS data_fine
                                       FROM cons_ufre_tab
                                      WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio <= dt_start
                                            AND data_fine >= dt_start
                                   GROUP BY pk_cuaa
                            UNION
                            SELECT DISTINCT pk_cuaa,
                                            MAX (data_fine) AS data_fine
                                       FROM cons_urui_tab
                                      WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio <= dt_start
                                            AND data_fine >= dt_start
                                   GROUP BY pk_cuaa)
                  ORDER BY data_fine DESC)
           WHERE ROWNUM = 1;

          tmp_data_inizio := dt_start;

          LOOP
            IF pk_cuaa_out IS NULL THEN
              err_code := -20007;
              err_msg := 'Non ï¿½ stata trovata nessuna titolaritï¿½ alla data specificata';
              patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in,
                                      :NEW.fattura_in, :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out,
                                      :NEW.id_co_out, err_code, err_msg);
              raise_application_error (err_code, err_msg);
            END IF;

            -- creo nuovi titoli part.
            INSERT INTO cons_ufre_tab cut
                        (pkid_uffr,
                         cod_nazionale,
                         foglio,
                         allegato,
                         sviluppo,
                         particella,
                         unimm,
                         perc_poss,
                         tipo_titolo,
                         data_registrazione,
                         utente,
                         TIMESTAMP,
                         pk_cuaa,
                         sub,
                         data_inizio,
                         data_fine,
                         atto_ini,
                         sorgente,
                         atto_fin,
                         tipo_documento,
                         tit_no_cod,
                         valido_ini,
                         valido_fin,
                         cod_sogg_cat,
                         fl_totale
                        )
              (SELECT cons_tit_seq.NEXTVAL,
                      cod_nazionale,
                      foglio,
                      allegato,
                      sviluppo,
                      particella,
                      unimm,
                      perc_poss,
                      tipo_titolo,
                      data_registrazione,
                      'CLIENT',
                      SYSDATE,
                      :NEW.cod_inq_in,
                      sub,
                      tmp_data_inizio,
                      data_fine,
                      atto_ini,
                      NULL,
                      NULL,
                      tipo_documento,
                      tit_no_cod,
                      valido_ini,
                      valido_fin,
                      cod_sogg_cat,
                      fl_totale
                 FROM cons_ufre_tab
                WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= tmp_data_inizio
                      AND data_fine > tmp_data_inizio);

            -- inserisco eventuali titoli part che iniziano successivamente alla data di inizio
            INSERT INTO cons_ufre_tab cut
                        (pkid_uffr,
                         cod_nazionale,
                         foglio,
                         allegato,
                         sviluppo,
                         particella,
                         unimm,
                         perc_poss,
                         tipo_titolo,
                         data_registrazione,
                         utente,
                         TIMESTAMP,
                         pk_cuaa,
                         sub,
                         data_inizio,
                         data_fine,
                         atto_ini,
                         sorgente,
                         atto_fin,
                         tipo_documento,
                         tit_no_cod,
                         valido_ini,
                         valido_fin,
                         cod_sogg_cat,
                         fl_totale
                        )
              (SELECT cons_tit_seq.NEXTVAL,
                      cod_nazionale,
                      foglio,
                      allegato,
                      sviluppo,
                      particella,
                      unimm,
                      perc_poss,
                      tipo_titolo,
                      data_registrazione,
                      'CLIENT',
                      SYSDATE,
                      :NEW.cod_inq_in,
                      sub,
                      data_inizio,
                      data_fine,
                      atto_ini,
                      NULL,
                      NULL,
                      tipo_documento,
                      tit_no_cod,
                      valido_ini,
                      valido_fin,
                      cod_sogg_cat,
                      fl_totale
                 FROM cons_ufre_tab
                WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > tmp_data_inizio
                      AND data_fine <= tmp_data_fine);

            -- creo nuovi titoli uiu
            INSERT INTO cons_urui_tab
                        (pkid_urui,
                         cod_nazionale,
                         foglio,
                         allegato,
                         sviluppo,
                         particella,
                         unimm,
                         perc_poss,
                         tipo_titolo,
                         data_registrazione,
                         utente,
                         TIMESTAMP,
                         pk_cuaa,
                         sub,
                         data_inizio,
                         data_fine,
                         atto_ini,
                         sorgente,
                         atto_fin,
                         tipo_documento,
                         tit_no_cod,
                         valido_ini,
                         valido_fin,
                         cod_sogg_cat,
                         fl_totale
                        )
              (SELECT cons_tit_seq.NEXTVAL,
                      cod_nazionale,
                      foglio,
                      allegato,
                      sviluppo,
                      particella,
                      unimm,
                      perc_poss,
                      tipo_titolo,
                      data_registrazione,
                      'CLIENT',
                      SYSDATE,
                      :NEW.cod_inq_in,
                      sub,
                      tmp_data_inizio,
                      data_fine,
                      atto_ini,
                      NULL,
                      NULL,
                      tipo_documento,
                      tit_no_cod,
                      valido_ini,
                      valido_fin,
                      cod_sogg_cat,
                      fl_totale
                 FROM cons_urui_tab
                WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= tmp_data_inizio
                      AND data_fine > tmp_data_inizio);

            -- inserisco eventuali titoli uiu che iniziano successivamente alla data di inizio
            INSERT INTO cons_urui_tab
                        (pkid_urui,
                         cod_nazionale,
                         foglio,
                         allegato,
                         sviluppo,
                         particella,
                         unimm,
                         perc_poss,
                         tipo_titolo,
                         data_registrazione,
                         utente,
                         TIMESTAMP,
                         pk_cuaa,
                         sub,
                         data_inizio,
                         data_fine,
                         atto_ini,
                         sorgente,
                         atto_fin,
                         tipo_documento,
                         tit_no_cod,
                         valido_ini,
                         valido_fin,
                         cod_sogg_cat,
                         fl_totale
                        )
              (SELECT cons_tit_seq.NEXTVAL,
                      cod_nazionale,
                      foglio,
                      allegato,
                      sviluppo,
                      particella,
                      unimm,
                      perc_poss,
                      tipo_titolo,
                      data_registrazione,
                      'CLIENT',
                      SYSDATE,
                      :NEW.cod_inq_in,
                      sub,
                      data_inizio,
                      data_fine,
                      atto_ini,
                      NULL,
                      NULL,
                      tipo_documento,
                      tit_no_cod,
                      valido_ini,
                      valido_fin,
                      cod_sogg_cat,
                      fl_totale
                 FROM cons_urui_tab
                WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > tmp_data_inizio
                      AND data_fine <= tmp_data_fine);

            EXIT WHEN tmp_data_fine = dt_fine_cntr;


            -- reiposto la data di inizio a un secondo dopo la data di fine dell'intervallo corrente
            tmp_data_inizio := tmp_data_fine + (1 / (24 * 60 * 60));

				-- se le titolaritï¿½ appena inserite non arrivano fino alla fine del contratto
				-- allora cerco un altro inquilino che inizia nell'intervallo successivo
            BEGIN

				  SELECT pk_cuaa,
                     data_fine
                INTO pk_cuaa_out,
                     tmp_data_fine
                FROM (SELECT   pk_cuaa,
                               data_fine
                          FROM (SELECT DISTINCT pk_cuaa,
                                                MAX (data_fine) AS data_fine
                                           FROM cons_ufre_tab
                                          WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio = tmp_data_inizio
                                                AND data_fine <= dt_fine_cntr
                                       GROUP BY pk_cuaa
                                UNION
                                SELECT DISTINCT pk_cuaa,
                                                MAX (data_fine) AS data_fine
                                           FROM cons_urui_tab
                                          WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND data_inizio = tmp_data_inizio
                                                AND data_fine <= dt_fine_cntr
                                       GROUP BY pk_cuaa)
                      ORDER BY data_fine DESC)
               WHERE ROWNUM = 1;

				EXCEPTION
              WHEN NO_DATA_FOUND THEN
                err_code := -20007;
                err_msg := 'Non ï¿½ stata trovata nessuna titolaritï¿½ alla data specificata';
                patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in,
                                        :NEW.fattura_in, :NEW.data_uscita_out, :NEW.tipo_uscita_out,
                                        :NEW.id_impreg_out, :NEW.id_co_out, err_code, err_msg);
                raise_application_error (err_code, err_msg);
            END;

          END LOOP;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            err_code := -20007;
            err_msg := 'Non ï¿½ stata trovata nessuna titolaritï¿½ alla data specificata';
            patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in,
                                    :NEW.fattura_in, :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out,
                                    :NEW.id_co_out, err_code, err_msg);
            raise_application_error (err_code, err_msg);
        END;
      ELSE
-- fine nuovo inquilino senza subentro -- inizio subentro                                                                                            -- c'ï¿½ subentro
        -- creo nuovi titoli part.
        INSERT INTO cons_ufre_tab cut
                    (pkid_uffr,
                     cod_nazionale,
                     foglio,
                     allegato,
                     sviluppo,
                     particella,
                     unimm,
                     perc_poss,
                     tipo_titolo,
                     data_registrazione,
                     utente,
                     TIMESTAMP,
                     pk_cuaa,
                     sub,
                     data_inizio,
                     data_fine,
                     atto_ini,
                     sorgente,
                     atto_fin,
                     tipo_documento,
                     tit_no_cod,
                     valido_ini,
                     valido_fin,
                     cod_sogg_cat,
                     fl_totale
                    )
          (SELECT cons_tit_seq.NEXTVAL,
                  cod_nazionale,
                  foglio,
                  allegato,
                  sviluppo,
                  particella,
                  unimm,
                  perc_poss,
                  tipo_titolo,
                  data_registrazione,
                  'CLIENT',
                  SYSDATE,
                  :NEW.cod_inq_in,
                  sub,
                  dt_start,
                  data_fine,
                  atto_ini,
                  NULL,
                  NULL,
                  tipo_documento,
                  tit_no_cod,
                  valido_ini,
                  valido_fin,
                  cod_sogg_cat,
                  fl_totale
             FROM cons_ufre_tab
            WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start
                  AND data_fine > dt_start);

        -- aggiorno eventuali titoli part che iniziano successivamente alla data di subentro
        UPDATE cons_ufre_tab
           SET pk_cuaa = :NEW.cod_inq_in
         WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > dt_start
               AND data_fine > dt_start;

        -- creo nuovi titoli uiu
        INSERT INTO cons_urui_tab
                    (pkid_urui,
                     cod_nazionale,
                     foglio,
                     allegato,
                     sviluppo,
                     particella,
                     unimm,
                     perc_poss,
                     tipo_titolo,
                     data_registrazione,
                     utente,
                     TIMESTAMP,
                     pk_cuaa,
                     sub,
                     data_inizio,
                     data_fine,
                     atto_ini,
                     sorgente,
                     atto_fin,
                     tipo_documento,
                     tit_no_cod,
                     valido_ini,
                     valido_fin,
                     cod_sogg_cat,
                     fl_totale
                    )
          (SELECT cons_tit_seq.NEXTVAL,
                  cod_nazionale,
                  foglio,
                  allegato,
                  sviluppo,
                  particella,
                  unimm,
                  perc_poss,
                  tipo_titolo,
                  data_registrazione,
                  'CLIENT',
                  SYSDATE,
                  :NEW.cod_inq_in,
                  sub,
                  dt_start,
                  data_fine,
                  atto_ini,
                  NULL,
                  NULL,
                  tipo_documento,
                  tit_no_cod,
                  valido_ini,
                  valido_fin,
                  cod_sogg_cat,
                  fl_totale
             FROM cons_urui_tab
            WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start
                  AND data_fine > dt_start);

        -- aggiorno eventuali titoli uiu che iniziano successivamente alla data di subentro
        UPDATE cons_urui_tab
           SET pk_cuaa = :NEW.cod_inq_in
         WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > dt_start
               AND data_fine > dt_start;
      END IF;

      -- inserisco il nuovo inquilino
      new_id_co := :NEW.id_co_out;

      -- se non c'ï¿½ cessazione ma solo nuovi inquilini
      IF :NEW.id_co_out IS NULL THEN
        -- calcolo l'id_co del nuovo inquilino
        SELECT NVL (MAX (id_co), -1) + 1
          INTO new_id_co
          FROM cointestatari
         WHERE codice = :NEW.codice AND id_co < 50000;
      END IF;

      INSERT INTO patri_loc_cointesta
                  (fk_atto, pk_cuaa, id_co, perc_spese, fattura, tipo_uscita, data_uscita, id_impreg)
        (SELECT CAST (:NEW.codice AS NUMBER),
                CAST (:NEW.cod_inq_in AS NUMBER),
                new_id_co,
                :NEW.perc_spese_inq_in,
                :NEW.fattura_in,
                NULL,
                NULL,
                NULL
           FROM (SELECT DISTINCT pk_cuaa
                            FROM (SELECT pk_cuaa
                                    FROM cons_ufre_tab
                                   WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = :NEW.cod_inq_in
                                         AND data_inizio <= dt_start AND data_fine > dt_start
                                  UNION
                                  SELECT pk_cuaa
                                    FROM cons_ufre_tab
                                   WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = :NEW.cod_inq_in
                                         AND data_inizio > dt_start AND data_fine > dt_start
                                  UNION
                                  SELECT pk_cuaa
                                    FROM cons_urui_tab
                                   WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = :NEW.cod_inq_in
                                         AND data_inizio <= dt_start AND data_fine > dt_start
                                  UNION
                                  SELECT pk_cuaa
                                    FROM cons_urui_tab
                                   WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = :NEW.cod_inq_in
                                         AND data_inizio > dt_start AND data_fine > dt_start)));
    END IF;
-- fine subentro                                                                                       -- fine nuovi titoli

    -- se c'ï¿½ cessazione o correzione di errore
    IF :NEW.id_co_out IS NOT NULL THEN
      -- verifico se ï¿½ una correzione ad un errore
      IF isdeletable = 1 THEN                                                                      -- correzione errore
        IF :NEW.cod_inq_in IS NOT NULL THEN                                 -- correzione di errore con nuovo inquilino
          -- associo tutti i titoli particelle del vecchio soggetto al nuovo soggetto a partire dalla data di inizio
          UPDATE cons_ufre_tab
             SET pk_cuaa = :NEW.cod_inq_in
           WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio >= dt_start;

          -- associo tutti i titoli uiu del vecchio soggetto al nuovo soggetto a partire dalla data di inizio
          UPDATE cons_urui_tab
             SET pk_cuaa = :NEW.cod_inq_in
           WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio >= dt_start;

          -- sostituisco il vecchio inquilino con quello nuovo
          UPDATE patri_loc_cointesta plc
             SET pk_cuaa = :NEW.cod_inq_in,
                 fattura = :NEW.fattura_in,
                 perc_spese = :NEW.perc_spese_inq_in,
                 tipo_uscita = NULL,
                 data_uscita = NULL,
                 id_impreg = NULL
           WHERE fk_atto = CAST (:NEW.codice AS NUMBER) AND id_co = :NEW.id_co_out AND pk_cuaa = pk_cuaa_out
                 AND EXISTS (
                      SELECT DISTINCT pk_cuaa
                                 FROM (SELECT pk_cuaa
                                         FROM cons_ufre_tab
                                        WHERE atto_ini = CAST (:NEW.codice AS NUMBER)
                                              AND pk_cuaa = CAST (:NEW.cod_inq_in AS NUMBER) AND data_inizio >= dt_start
                                       UNION
                                       SELECT pk_cuaa
                                         FROM cons_urui_tab
                                        WHERE atto_ini = CAST (:NEW.codice AS NUMBER)
                                              AND pk_cuaa = CAST (:NEW.cod_inq_in AS NUMBER) AND data_inizio >= dt_start));
        ELSE                                                               -- correzione di errore senza nuovo inquilino
          /*
          * ATTENZIONE: NON VIENE VOLUTAMENTE (CONTROLLO DEMANDATO AL CLIENT) FATTO IL CONTROLLO CHE L'INQUILINO DA CANCELLARE
          *       NON SIA QUELLO PRINCIPALE (ID_CO = 0)
          *
          */

          -- elimino i vecchi titoli part.
          DELETE FROM cons_ufre_tab
                WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio >= dt_start;

          -- elimino vecchi titoli uiu
          DELETE FROM cons_urui_tab
                WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio >= dt_start;

          -- elimino il vecchio inquilino
          DELETE FROM patri_loc_cointesta
                WHERE fk_atto = CAST (:NEW.codice AS NUMBER) AND id_co < 50000 AND pk_cuaa = pk_cuaa_out;
        END IF;
      ELSE                                                                               -- non c'ï¿½ correzione di errore
--      -- Verifico la data di cessazione (data_fine) se anteriore alla data di inizio
--         select max(data_inizio) into dt_check
--           from (SELECT data_inizio
--                   FROM cons_ufre_tab
--                  WHERE atto_ini = :NEW.codice AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start AND data_fine >= dt_start
--                  UNION
--                 SELECT data_inizio
--                   FROM cons_urui_tab
--                  WHERE atto_ini = :NEW.codice AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start AND data_fine >= dt_start);
--
--         if dt_check > dt_end then
--            Raise_application_error (-20004, 'La data di cessazione ï¿½ uguale o precedente alla data di inizio locazione per questo inquilino');
--         end if;

        -- cesso vecchi titoli part.
        UPDATE cons_ufre_tab
           SET data_fine = dt_end
         WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start
               AND data_fine >= dt_start;

        -- cesso vecchi titoli uiu
        UPDATE cons_urui_tab
           SET data_fine = dt_end
         WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start
               AND data_fine >= dt_start;

        -- aggiorno vecchio inquilino
        SELECT NVL (MAX (id_co), 50000) + 1
          INTO new_id_co
          FROM cointestatari
         WHERE codice = :NEW.codice AND id_co > 50000;

        UPDATE patri_loc_cointesta plc
           SET id_co = new_id_co,
               tipo_uscita = :NEW.tipo_uscita_out,
               data_uscita = :NEW.data_uscita_out,
               id_impreg = :NEW.id_impreg_out,
               perc_spese = 0
         WHERE fk_atto = CAST (:NEW.codice AS NUMBER) AND id_co = :NEW.id_co_out AND pk_cuaa = pk_cuaa_out
               AND EXISTS (
                    SELECT DISTINCT pk_cuaa
                               FROM (SELECT pk_cuaa
                                       FROM cons_ufre_tab
                                      WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out
                                            AND data_fine = dt_end
                                     UNION
                                     SELECT pk_cuaa
                                       FROM cons_urui_tab
                                      WHERE atto_ini = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out
                                            AND data_fine = dt_end));
      END IF;                                                                       -- FINE non c'ï¿½ correzione di errore
    END IF;                                                                                 -- fine cessazione inquilino
  ELSE                                                                           -- FINE LOCAZIONE - INIZIO SUBLOCAZIONI
    -- verifico se vi ï¿½ cessazione senza subentro (il contratto non puï¿½ essere chiuso facendo cessare l'unico inquilino)
    IF pk_cuaa_out IS NOT NULL AND :NEW.cod_inq_in IS NULL THEN
      -- verifico il numero di inquilini , se = 1 lancio un'eccezione
      SELECT COUNT (*)
        INTO cnt
        FROM (SELECT DISTINCT pk_cuaa
                         FROM cons_subloc_tab
                        WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND data_inizio <= dt_start
                              AND data_fine >= dt_start);

      IF cnt = 1 THEN
        err_code := -20003;
        err_msg := 'Non ï¿½ possibile far cessare l''unico soggetto intestatario del contratto di sublocazione';
        patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                                :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out,
                                err_code, err_msg);
        raise_application_error (err_code, err_msg);
      END IF;
    END IF;

    -- creo i nuovi titoli
    IF :NEW.cod_inq_in IS NOT NULL AND isdeletable = 0 THEN        -- isDeleteble = 1 sarï¿½ risolta piï¿½ in giï¿½ nel codice
      -- se non c'ï¿½ cessazione ma solo nuovi inquilini
      IF :NEW.id_co_out IS NULL THEN
        /*
        *   TODO: Inserire lo stesso codice delle locazioni nel caso di inserimento di nuovo inquilino
        *     senza subentro. Per ora questo caso ï¿½ risolto lanciando un'eccezzione
        *
        */

        -- non avendo l'inquilino che esce come riferimento ne prendo uno a caso tra quelli esistenti alla data di inserimento del nuovo inquilino
        SELECT pk_cuaa
          INTO pk_cuaa_out
          FROM (SELECT DISTINCT pk_cuaa
                           FROM cons_subloc_tab
                          WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND data_inizio <= dt_start
                                AND data_fine >= dt_start)
         WHERE ROWNUM = 1;

        IF pk_cuaa_out IS NULL THEN
          err_code := -20007;
          err_msg := 'Non ï¿½ stata trovata nessuna titolaritï¿½ alla data specificata';
          patri_pck.subentro_log (:NEW.codice, :NEW.cod_ces, :NEW.cod_inq_in, :NEW.perc_spese_inq_in, :NEW.fattura_in,
                                  :NEW.data_uscita_out, :NEW.tipo_uscita_out, :NEW.id_impreg_out, :NEW.id_co_out,
                                  err_code, err_msg);
          raise_application_error (err_code, err_msg);
        END IF;
      END IF;

      -- creo nuovi titoli
      INSERT INTO cons_subloc_tab cst
                  (pkid_subloc,
                   tipo_titolo,
                   fkid_atto,
                   pk_cuaa,
                   perc_poss,
                   fkid_obj,
                   obj_type,
                   atto_inizio,
                   atto_fine,
                   data_inizio,
                   data_fine,
                   utente,
                   data_var
                  )
        (SELECT cons_tit_seq.NEXTVAL,
                tipo_titolo,
                fkid_atto,
                :NEW.cod_inq_in,
                perc_poss,
                fkid_obj,
                obj_type,
                atto_inizio,
                atto_fine,
                dt_start,
                data_fine,
                'CLIENT',
                SYSDATE
           FROM cons_subloc_tab
          WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start
                AND data_fine > dt_start);

      -- aggiorno eventuali titoli che iniziano successivamente alla data di inizio
      UPDATE cons_subloc_tab
         SET pk_cuaa = :NEW.cod_inq_in
       WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio > dt_start
             AND data_fine > dt_start;

      -- inserisco il nuovo inquilino
      new_id_co := :NEW.id_co_out;

      -- se non c'ï¿½ cessazione ma solo nuovi inquilini
      IF :NEW.id_co_out IS NULL THEN
        -- calcolo l'id_co del nuovo inquilino
        SELECT NVL (MAX (id_co), -1) + 1
          INTO new_id_co
          FROM cointestatari
         WHERE codice = :NEW.codice AND id_co < 50000;
      END IF;

      INSERT INTO patri_loc_cointesta
                  (fk_atto, pk_cuaa, id_co, perc_spese, fattura, tipo_uscita, data_uscita, id_impreg)
        (SELECT CAST (:NEW.codice AS NUMBER),
                CAST (:NEW.cod_inq_in AS NUMBER),
                new_id_co,
                :NEW.perc_spese_inq_in,
                :NEW.fattura_in,
                NULL,
                NULL,
                NULL
           FROM (SELECT DISTINCT pk_cuaa
                            FROM (SELECT pk_cuaa
                                    FROM cons_subloc_tab
                                   WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = :NEW.cod_inq_in
                                         AND data_inizio <= dt_start AND data_fine > dt_start
                                  UNION
                                  SELECT pk_cuaa
                                    FROM cons_subloc_tab
                                   WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = :NEW.cod_inq_in
                                         AND data_inizio > dt_start AND data_fine > dt_start)));
    END IF;                                                                                         -- fine nuovi titoli

    -- se c'ï¿½ cessazione o correzione di errore
    IF pk_cuaa_out IS NOT NULL THEN
      -- verifico se ï¿½ una correzione ad un errore
      IF isdeletable = 1 THEN                                                                      -- correzione errore
        IF :NEW.cod_inq_in IS NOT NULL THEN                                 -- correzione di errore con nuovo inquilino
          -- associo tutti i titoli del vecchio soggetto al nuovo soggetto a partire dalla data di inizio
          UPDATE cons_subloc_tab
             SET pk_cuaa = :NEW.cod_inq_in
           WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio >= dt_start;

          -- sostituisco il vecchio inquilino con quello nuovo
          UPDATE patri_loc_cointesta plc
             SET pk_cuaa = :NEW.cod_inq_in,
                 fattura = :NEW.fattura_in,
                 perc_spese = :NEW.perc_spese_inq_in,
                 tipo_uscita = NULL,
                 data_uscita = NULL,
                 id_impreg = NULL
           WHERE fk_atto = CAST (:NEW.codice AS NUMBER) AND id_co = :NEW.id_co_out AND pk_cuaa = pk_cuaa_out
                 AND EXISTS (
                      SELECT DISTINCT pk_cuaa
                                 FROM (SELECT pk_cuaa
                                         FROM cons_subloc_tab
                                        WHERE fkid_atto = CAST (:NEW.codice AS NUMBER)
                                              AND pk_cuaa = CAST (:NEW.cod_inq_in AS NUMBER) AND data_inizio >= dt_start));
        ELSE                                                               -- correzione di errore senza nuovo inquilino
          /*
          * ATTENZIONE: NON VIENE VOLUTAMENTE (CONTROLLO DEMANDATO AL CLIENT) FATTO IL CONTROLLO CHE L'INQUILINO DA CANCELLARE
          *       NON SIA QUELLO PRINCIPALE (ID_CO = 1)
          *
          */

          -- elimino i vecchi titoli part.
          DELETE FROM cons_subloc_tab
                WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio >= dt_start;

          -- elimino il vecchio inquilino
          DELETE FROM patri_loc_cointesta
                WHERE fk_atto = CAST (:NEW.codice AS NUMBER) AND id_co < 50000 AND pk_cuaa = pk_cuaa_out;
        END IF;
      ELSE                                                                               -- non c'ï¿½ correzione di errore
        -- cesso vecchi titoli
        UPDATE cons_subloc_tab
           SET data_fine = dt_end
         WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out AND data_inizio <= dt_start
               AND data_fine >= dt_start;

        -- aggiorno vecchio inquilino
        SELECT NVL (MAX (id_co), 50000) + 1
          INTO new_id_co
          FROM cointestatari
         WHERE codice = :NEW.codice AND id_co > 50000;

        UPDATE patri_loc_cointesta plc
           SET id_co = new_id_co,
               tipo_uscita = :NEW.tipo_uscita_out,
               data_uscita = :NEW.data_uscita_out,
               id_impreg = :NEW.id_impreg_out,
               perc_spese = 0
         WHERE fk_atto = CAST (:NEW.codice AS NUMBER) AND id_co = :NEW.id_co_out AND pk_cuaa = pk_cuaa_out
               AND EXISTS (
                    SELECT DISTINCT pk_cuaa
                               FROM (SELECT pk_cuaa
                                       FROM cons_subloc_tab
                                      WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND pk_cuaa = pk_cuaa_out
                                            AND data_fine = dt_end));
      END IF;                                                                       -- FINE non c'ï¿½ correzione di errore
    END IF;                                                                                 -- fine cessazione inquilino
  END IF;                                                                                               -- fine di tutto
END;
/


DROP TRIGGER SITI_H501.TABCATCE_TBI;

CREATE OR REPLACE TRIGGER SITI_H501.TABCATCE_TBI
before insert ON SITI_H501.TABCATCE for each row
DISABLE
begin
  begin
     insert into sitifile_tipi_atto_cat (PKCATEGORIA, DESCRIZIONE) values ('AS_B_DWG_' || :new.CAT_CES, 'Disegni cat. cespite: ' || :new.ces_des);
  exception when dup_val_on_index then
       null;
  end;
  begin
     insert into sitifile_tipi_atto_cat (PKCATEGORIA, DESCRIZIONE) values ('AS_B_DOC_' || :new.CAT_CES, 'Documenti cat. cespite: ' || :new.ces_des);
  exception when dup_val_on_index then
       null;
  end;
  begin
     insert into sitifile_tipi_atto_cat (PKCATEGORIA, DESCRIZIONE) values ('AS_B_RDOC_' || :new.CAT_CES, 'Doc. obbligatori cat. cespite: ' || :new.ces_des);
  exception when dup_val_on_index then
       null;
  end;
end;
/


