DROP TRIGGER SITI_H501.TIB_SITIFGAN;

CREATE OR REPLACE TRIGGER SITI_H501.TIB_SITIFGAN 
BEFORE
INSERT
ON SITI_H501.SITIFGAN
FOR EACH ROW
DECLARE
 CURSOR C1 IS SELECT COD_NAZIONALE FROM SITICOMU WHERE ISTATP=TRIM(TO_CHAR(:NEW.ISTAT_PROV,'000')) AND ISTATC=TRIM(TO_CHAR(:NEW.ISTAT_COM,'000')) AND NVL(ID_SEZC,' ')=UPPER(:NEW.SEZIONE);
 CURSOR C2 IS SELECT TO_NUMBER(ISTATP),TO_NUMBER(ISTATC),Decode(ID_SEZC,NULL,' ',ID_SEZC) FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE;
 CODICE_LETTO CHAR(4);
BEGIN
  IF :NEW.COD_NAZIONALE IS NULL THEN
 OPEN C1;
 FETCH C1 INTO CODICE_LETTO;
 IF C1%NOTFOUND THEN CODICE_LETTO:='0000'; END IF;
 CLOSE C1;
    IF CODICE_LETTO IS NOT NULL THEN
      :NEW.COD_NAZIONALE := CODICE_LETTO;
    END IF;
  ELSE
    IF :NEW.ISTAT_PROV IS NULL THEN
  OPEN C2;
  FETCH C2 INTO :NEW.ISTAT_PROV,:NEW.ISTAT_COM,:NEW.SEZIONE;
  IF C2%NOTFOUND THEN :NEW.ISTAT_PROV:=0;:NEW.ISTAT_COM:=0;:NEW.SEZIONE:=' '; END IF;
  CLOSE C2;
    END IF;
  END IF;
END;
/


