DROP TRIGGER SITI_H501.TMPLOADFOG_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.TMPLOADFOG_TIB
BEFORE
INSERT
ON SITI_H501.TMPLOADFOG
FOR EACH ROW
DECLARE
  PRESENTE NUMBER(4);
BEGIN
  IF :NEW.FOGLIO = 9999 THEN
	SELECT COUNT(*) INTO PRESENTE FROM SITILOAD_AGGIORNAMENTI WHERE ID_INDIRIZZO=:NEW.ID_INDIRIZZO AND COD_NAZIONALE=:NEW.COD_NAZIONALE;
  ELSE
	SELECT COUNT(*) INTO PRESENTE FROM SITILOAD_AGGIORNAMENTI WHERE ID_INDIRIZZO=:NEW.ID_INDIRIZZO AND COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO;
  END IF;

  IF PRESENTE=0 THEN
  	IF :NEW.FOGLIO != 9999 THEN
    	INSERT INTO SITILOAD_AGGIORNAMENTI(COD_NAZIONALE,FOGLIO,ID_INDIRIZZO,DATA_TRKC,DATA_CENT,DATA_PART,DATA_SUOLO,DATA_OLIO,DATA_VINO,DATA_CONS)
    	VALUES(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.ID_INDIRIZZO,:NEW.DATA_TRKC,:NEW.DATA_CENT,:NEW.DATA_PART,:NEW.DATA_SUOLO,:NEW.DATA_OLIO,:NEW.DATA_VINO,:NEW.DATA_CONS);
	END IF;
  ELSE
  	IF :NEW.FOGLIO = 9999 THEN
    	UPDATE SITILOAD_AGGIORNAMENTI SET
    	DATA_TRKC =Nvl(:NEW.DATA_TRKC,DATA_TRKC),
    	DATA_CENT =Nvl(:NEW.DATA_CENT,DATA_CENT),
    	DATA_PART =Nvl(:NEW.DATA_PART,DATA_PART),
    	DATA_SUOLO=Nvl(:NEW.DATA_SUOLO,DATA_SUOLO),
    	DATA_OLIO =Nvl(:NEW.DATA_OLIO,DATA_OLIO),
    	DATA_VINO =Nvl(:NEW.DATA_VINO,DATA_VINO),
    	DATA_CONS =Nvl(:NEW.DATA_CONS,DATA_CONS)
    	WHERE ID_INDIRIZZO=:NEW.ID_INDIRIZZO AND COD_NAZIONALE=:NEW.COD_NAZIONALE;
	ELSE
    	UPDATE SITILOAD_AGGIORNAMENTI SET
    	DATA_TRKC =Nvl(:NEW.DATA_TRKC,DATA_TRKC),
    	DATA_CENT =Nvl(:NEW.DATA_CENT,DATA_CENT),
    	DATA_PART =Nvl(:NEW.DATA_PART,DATA_PART),
    	DATA_SUOLO=Nvl(:NEW.DATA_SUOLO,DATA_SUOLO),
    	DATA_OLIO =Nvl(:NEW.DATA_OLIO,DATA_OLIO),
    	DATA_VINO =Nvl(:NEW.DATA_VINO,DATA_VINO),
    	DATA_CONS =Nvl(:NEW.DATA_CONS,DATA_CONS)
    	WHERE ID_INDIRIZZO=:NEW.ID_INDIRIZZO AND COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO;
	END IF;
  END IF;
END;
/


DROP TRIGGER SITI_H501.VEST_FIDUCIALE_TIB;

CREATE OR REPLACE TRIGGER SITI_H501.VEST_FIDUCIALE_TIB
BEFORE INSERT OR UPDATE
ON SITI_H501.VEST_FIDUCIALE
FOR EACH ROW
DECLARE
BEGIN
  IF :NEW.ID_FIDUCIALE IS NULL THEN
    SELECT VEST_FIDUCIALE_SEQ.NEXTVAL INTO :NEW.ID_FIDUCIALE FROM DUAL;
  END IF;

  IF :NEW.ID_CXF IS NOT NULL THEN

    SELECT COD_NAZIONALE,FOGLIO
    INTO :NEW.COD_NAZIONALE,:NEW.TAVOLA
    FROM CXF_HEADER WHERE ID_CXF = :NEW.ID_CXF;

  END IF;

END;
