DROP VIEW DIOGENE_H501.CAT_PARTICELLE_GAUSS;

/* Formatted on 18/07/2022 12:22:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.CAT_PARTICELLE_GAUSS
(
    GEOMETRY,
    AREA,
    COMUNE,
    LAYER,
    PARTICELLA,
    PERIMETER,
    FK_COMUNE,
    FK_PAR_CATASTALI,
    PK_PARTICELLE,
    LABEL_POSIZIONE,
    LABEL_ALTEZZA,
    LABEL_ROTAZIONE,
    CENTROIDE,
    MAPSHEET,
    LABEL_X,
    LABEL_Y,
    FOGLIO,
    SUB,
    ALLEGATO
)
BEQUEATH DEFINER
AS
    SELECT shape                                         AS geometry,
           area_part                                     AS area,
           UPPER (cod_nazionale)                         AS comune,
           DECODE (particella,
                   'STRAD', 'STRADA',
                   'ACQUA', 'ACQUA',
                   'PARTICELLE')                         AS layer,
           particella,
           0                                             AS perimeter,
           UPPER (cod_nazionale)                         AS fk_comune,
              cod_nazionale
           || LPAD (foglio, 5, '0')
           || particella
           || LPAD (NVL (TRIM (sub), '0000'), 4, '0')    AS fk_par_catastali,
           se_row_id                                     AS pk_particelle,
           NULL                                          AS label_posizione,
           NULL                                          AS label_altezza,
           NULL                                          AS label_rotazione,
           NULL                                          AS centroide,
           NULL                                          AS mapsheet,
           NULL                                          AS label_x,
           NULL                                          AS label_y,
           foglio,
           sub,
           ALLEGATO
      FROM sitipart
     WHERE data_fine_val = TO_DATE ('99991231', 'YYYYMMDD')
    UNION ALL
    SELECT shape                                         AS geometry,
           area_colt                                     AS area,
           cod_nazionale                                 AS comune,
           'FABBRICATI'                                  AS layer,
           particella,
           0                                             AS perimeter,
           cod_nazionale                                 AS fk_comune,
              cod_nazionale
           || LPAD (foglio, 5, '0')
           || particella
           || LPAD (NVL (TRIM (sub), '0000'), 4, '0')    AS fk_par_catastali,
           se_row_id                                     AS pk_particelle,
           NULL                                          AS label_posizione,
           NULL                                          AS label_altezza,
           NULL                                          AS label_rotazione,
           NULL                                          AS centroide,
           NULL                                          AS mapsheet,
           NULL                                          AS label_x,
           NULL                                          AS label_y,
           foglio,
           sub,
           ALLEGATO
      FROM sitisuolo
     WHERE     data_fine_val = TO_DATE ('99991231', 'YYYYMMDD')
           AND (cod_util = 100 OR (cod_util = 5 AND cod_coltura = 660));


