    TIPO_LOC,
    SEZ2011,
    TIPO_LOC_N,
    LOC2011,
    COD_TIPO_S,
    COD_ASC,
    SHAPE_AREA,
    SHAPE_LEN,
    SHAPE
)
BEQUEATH DEFINER
AS
