    COD_STAGNO,
    COD_FIUME,
    COD_LAGO,
    COD_LAGUNA,
    COD_VAL_P,
    COD_ZONA_C,
    COD_IS_AMM,
    COD_IS_LAC,
    COD_IS_MAR,
    COD_AREA_S,
    COD_MONT_D,
    LOC,
    LOC2001,
    TIPO_LOC,
    SEZ2011,
    TIPO_LOC_N,
    LOC2011,
    COD_TIPO_S,
    COD_ASC,
    SHAPE_AREA,
    SHAPE_LEN,
    SHAPE
)
BEQUEATH DEFINER
AS
    SELECT r.id                  AS COD_RISCHIO,
           R.PROFILI_RISCHIO     desc_RISCHIO,
           c.Risk_Score,
           s."SE_ROW_ID",
           s."OBJECTID",
           s."GISTAT_SEZ",
           s."PERIMETER",
           s."COD_ISTAT",
           s."PRO_COM",
           s."SEZ2001",
           s."SEZ",
           s."COD_TIPO",
           s."COD_STAGNO",
           s."COD_FIUME",
           s."COD_LAGO",
           s."COD_LAGUNA",
           s."COD_VAL_P",
           s."COD_ZONA_C",
           s."COD_IS_AMM",
           s."COD_IS_LAC",
           s."COD_IS_MAR",
           s."COD_AREA_S",
           s."COD_MONT_D",
           s."LOC",
           s."LOC2001",
           s."TIPO_LOC",
           s."SEZ2011",
           s."TIPO_LOC_N",
           s."LOC2011",
           s."COD_TIPO_S",
           s."COD_ASC",
           s."SHAPE_AREA",
           s."SHAPE_LEN",
           s."SHAPE"
      FROM sezioni_istat  s
           LEFT JOIN CRIF_INDICATORI c
               ON c.codice_sezione = LPAD (S.SEZ2011, 13, '0')
           LEFT JOIN CRIF_PROFILI_RISCHIO r
               ON (   (    c.risk_score > R.SCORE_MIN
                       AND c.risk_score <= r.score_max)
                   OR (r.score_min IS NULL AND c.risk_score IS NULL));


