    CAP,
    ID_EXT_D_SEZIONE_ELETTORALE,
    ID_EXT_D_VIA,
    ID_EXT_D_FRAZIONE,
    DT_INIZIO_VAL,
    DT_FINE_VAL,
    DT_EXP_DATO,
    DT_INS,
