    CIV_LIV1,
    CIV_LIV2,
    CIV_LIV3,
    CIVICO_COMPOSTO
)
BEQUEATH DEFINER
AS
    SELECT sit_d_civico.ID,
           sit_d_civico.id_ext,
           sit_d_civico.id_orig,
           sit_d_civico.fk_ente_sorgente,
           sit_d_civico.cap,
           sit_d_civico.id_ext_d_sezione_elettorale,
           sit_d_civico.id_ext_d_via,
           sit_d_civico.id_ext_d_frazione,
           sit_d_civico.dt_inizio_val,
