           sit_d_civico.flag_dt_val_dato,
           LPAD (
               SYS.XMLTYPE.getstringval (
                   SYS.XMLTYPE.EXTRACT (
                       sit_d_civico.civico_composto,
                       '/civicocomposto/att[@tipo="numero"]/@valore')),
