/* Formatted on 18/07/2022 12:22:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.SIT_D_PERS_FAM_DATE
(
    ID,
    ID_EXT,
    ID_ORIG,
    FK_ENTE_SORGENTE,
    RELAZ_PAR,
    ID_EXT_D_FAMIGLIA,
    ID_EXT_D_PERSONA,
    DT_INIZIO_VAL,
    DT_FINE_VAL,
    DT_INS,
    DT_MOD,
    DT_EXP_DATO,
    CTR_HASH,
    NEW_DT_INIZIO_DATO,
    NEW_DT_FINE_DATO,
    FLAG_DT_VAL_DATO,
    PROCESSID
)
BEQUEATH DEFINER
AS
    SELECT t.ID,
           t.ID_EXT,
           t.ID_ORIG,
           t.FK_ENTE_SORGENTE,
           t.RELAZ_PAR,
           t.ID_EXT_D_FAMIGLIA,
           t.ID_EXT_D_PERSONA,
           t.DT_INIZIO_VAL,
           t.DT_FINE_VAL,
           t.DT_INS,
           t.DT_MOD,
           t.DT_EXP_DATO,
           t.CTR_HASH,
           NVL (dt_inizio_dato, dt_inizio_val)    AS new_dt_inizio_dato,
           NVL (
               NVL (
                   dt_fine_dato,
                   (SELECT MIN (dt_inizio_dato) - 1
                      FROM sit_d_pers_fam t1
                     WHERE     T1.ID_EXT_D_PERSONA = t.id_ext_d_persona
                           AND t1.dt_inizio_dato > t.dt_inizio_dato)),
               dt_fine_val)                       AS new_dt_fine_dato,
           t.FLAG_DT_VAL_DATO,
           t.PROCESSID
      FROM sit_d_pers_fam t;


