DROP VIEW DIOGENE_H501.SIT_ENTE_SORGENTE;

/* Formatted on 18/07/2022 12:22:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.SIT_ENTE_SORGENTE
(
    ID,
    COD_SORGENTE,
    DESCRIZIONE,
    FK_ENTE,
    DISABILITA_STORICO,
    OGGETTI_RIFERIMENTO,
    CIVICI_RIFERIMENTO,
    SOGGETTI_RIFERIMENTO,
    TIPO_FONTE,
    VIE_RIFERIMENTO,
    FABBRICATI_RIFERIMENTO,
    FORNITURA_IN_REPLACE
)
BEQUEATH DEFINER
AS
    SELECT F.ID,
           F.CODICE                              COD_SORGENTE,
           F.DESCRIZIONE,
           SIT_ENTE.ID                           FK_ENTE,
           TO_NUMBER_ALL (K1.VALUE_CONF)         DISABILITA_STORICO,
           (SELECT PROG_OLD
              FROM AM_FONTE_TIPOINFO TI
             WHERE     F.CODICE || '|' || TI.INFORMAZIONE = K2.VALUE_CONF
                   AND TI.FK_AM_FONTE = F.ID)    OGGETTI_RIFERIMENTO,
           (SELECT PROG_OLD
              FROM AM_FONTE_TIPOINFO TI
             WHERE     F.CODICE || '|' || TI.INFORMAZIONE = K3.VALUE_CONF
                   AND TI.FK_AM_FONTE = F.ID)    CIVICI_RIFERIMENTO,
           (SELECT PROG_OLD
              FROM AM_FONTE_TIPOINFO TI
             WHERE     F.CODICE || '|' || TI.INFORMAZIONE = K4.VALUE_CONF
                   AND TI.FK_AM_FONTE = F.ID)    SOGGETTI_RIFERIMENTO,
           TIPO_FONTE,
           (SELECT PROG_OLD
              FROM AM_FONTE_TIPOINFO TI
             WHERE     F.CODICE || '|' || TI.INFORMAZIONE = K5.VALUE_CONF
                   AND TI.FK_AM_FONTE = F.ID)    VIE_RIFERIMENTO,
           (SELECT PROG_OLD
              FROM AM_FONTE_TIPOINFO TI
             WHERE     F.CODICE || '|' || TI.INFORMAZIONE = K7.VALUE_CONF
                   AND TI.FK_AM_FONTE = F.ID)    FABBRICATI_RIFERIMENTO,
           TO_NUMBER_ALL (K6.VALUE_CONF)         FORNITURA_IN_REPLACE
      FROM AM_FONTE          F,
           AM_FONTE_COMUNE   FC,
           SIT_ENTE,
           AM_KEY_VALUE_EXT  K1,
           AM_KEY_VALUE_EXT  K2,
           AM_KEY_VALUE_EXT  K3,
           AM_KEY_VALUE_EXT  K4,
           AM_KEY_VALUE_EXT  K5,
           AM_KEY_VALUE_EXT  K6,
           AM_KEY_VALUE_EXT  K7
     WHERE     FC.FK_AM_FONTE = F.ID
           AND FC.FK_AM_COMUNE = SIT_ENTE.CODENT
           AND fc.fk_am_comune = K1.FK_AM_COMUNE(+)
           AND FC.FK_AM_FONTE = K1.FK_AM_FONTE(+)
           AND 'disabilita.storico' = K1.KEY_CONF(+)
           AND fc.fk_am_comune = K2.FK_AM_COMUNE(+)
           AND 'oggetti.di.riferimento' = K2.KEY_CONF(+)
           AND fc.fk_am_comune = K3.FK_AM_COMUNE(+)
           AND 'civici.di.riferimento' = K3.KEY_CONF(+)
           AND fc.fk_am_comune = K4.FK_AM_COMUNE(+)
           AND 'soggetti.di.riferimento' = K4.KEY_CONF(+)
           AND fc.fk_am_comune = K5.FK_AM_COMUNE(+)
           AND 'vie.di.riferimento' = K5.KEY_CONF(+)
           AND fc.fk_am_comune = K5.FK_AM_COMUNE(+)
           AND 'fabbricati.di.riferimento' = K7.KEY_CONF(+)
           AND fc.fk_am_comune = K7.FK_AM_COMUNE(+)
           AND FC.FK_AM_FONTE = K6.FK_AM_FONTE(+)
           AND FC.FK_AM_COMUNE = K6.FK_AM_COMUNE(+)
           AND 'fornitura.in.replace' = K6.KEY_CONF(+);


DROP VIEW DIOGENE_H501.SITICOMU_VIEW;

/* Formatted on 18/07/2022 12:22:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.SITICOMU_VIEW
(
    COD_NAZIONALE,
    ISTATP,
    ISTATC,
    ID_SEZC,
    NOME,
    DENO_PROV,
    SIGLA_PROV,
    ISTATR,
    CODI_FISC_LUNA,
    FLAG_CATA,
    CO_FOGLIO1,
    CO_FOGLIO2,
    COD_PROVINCIA,
    COD_COMUNE,
    SEZIONE_CENSUARIA,
    SEZIONE2,
    ID_COMUNE,
    ISOPR,
    UBICAZIONE_GEOGRAFICA,
    DATA_AGGIORNAMENTO
)
BEQUEATH DEFINER
AS
    SELECT d.cod_sezione             COD_NAZIONALE,
           b.istatp                  ISTATP,
           c.istatc                  ISTATC,
           TRIM (d.sezione)          ID_SEZC,
           c.nome                    NOME,
           b.deno_prov               DENO_PROV,
           b.sigla_prov              SIGLA_PROV,
           a.istatr                  ISTATR,
           c.cod_comune              CODI_FISC_LUNA,
           d.flag_cata               FLAG_CATA,
           1                         CO_FOGLIO1,
           0                         CO_FOGLIO2,
           TO_NUMBER (b.istatp)      COD_PROVINCIA,
           TO_NUMBER (c.istatc)      COD_COMUNE,
           d.sezione                 SEZIONE_CENSUARIA,
           d.sezione2                SEZIONE2,
           c.id_comune               ID_COMUNE,
           0                         ISOPR,
           ubicazione_geografica     UBICAZIONE_GEOGRAFICA,
           SYSDATE                   DATA_AGGIORNAMENTO
      FROM cata_regi     a,
           cata_prov     b,
           cata_comu     c,
           cata_sezioni  d
     WHERE     b.id_regi = a.id_regi
           AND c.id_prov = b.id_prov
           AND d.id_comune = c.id_comune;


