DROP VIEW DIOGENE_H501.V_CF_FAMIGLIA_ATTUALE;

/* Formatted on 18/07/2022 12:22:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.V_CF_FAMIGLIA_ATTUALE
(
    CF,
    ID_ORIG,
    CODENT
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT UPPER (p.codfisc) cf, f.id_orig, ente.codent
      FROM SIT_ENTE              ente,
           sit_d_persona         p,
           SIT_D_PERS_FAM_DDATE  pf,
           SIT_D_FAMIGLIA        f
     WHERE     P.ID_EXT = PF.ID_EXT_D_PERSONA(+)
           AND PF.ID_EXT_D_FAMIGLIA = F.ID_EXT(+)
           AND SYSDATE BETWEEN NVL (PF.DT_INIZIO_DATO,
                                    TO_DATE ('01/01/0001', 'dd/MM/yyyy'))
                           AND NVL (PF.DT_FINE_DATO,
                                    TO_DATE ('31/12/9999', 'dd/MM/yyyy'))
           AND SYSDATE BETWEEN NVL (PF.DT_INIZIO_VAL,
                                    TO_DATE ('01/01/0001', 'dd/MM/yyyy'))
                           AND NVL (PF.DT_FINE_VAL,
                                    TO_DATE ('31/12/9999', 'dd/MM/yyyy'))
           AND SYSDATE BETWEEN NVL (F.DT_INIZIO_DATO,
                                    TO_DATE ('01/01/0001', 'dd/MM/yyyy'))
                           AND NVL (F.DT_FINE_DATO,
                                    TO_DATE ('31/12/9999', 'dd/MM/yyyy'));


DROP VIEW DIOGENE_H501.V_IND_CAT_UIU;

/* Formatted on 18/07/2022 12:22:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.V_IND_CAT_UIU
(
    COD_NAZIONALE,
    CODI_FISC_LUNA,
    FOGLIO,
    MAPPALE,
    SUB,
    GRAFFATO,
    PREFISSO,
    INDIRIZZO,
    CIVICO,
    ID_IMM,
    PROGRESSIVO,
    SEQ,
    SEZIONE
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT C.COD_NAZIONALE,
                    C.CODI_FISC_LUNA,
                    ID.FOGLIO,
                    ID.MAPPALE,
                    ID.SUB,
                    id.graffato,
                    t.descr                         PREFISSO,
                    ind.ind                         indirizzo,
                    remove_lead_zero (ind.civ1)     AS civico,
                    +ind.id_imm,
                    ind.progressivo,
                    ind.seq,
                    ind.sezione
      FROM load_cat_uiu_id   ID,
           siticomu          c,
           load_cat_uiu_ind  ind,
           cat_d_toponimi    t,
           SIT_ENTE
     WHERE     c.codi_fisc_luna = SIT_ENTE.CODENT
           AND ID.codi_fisc_luna = c.codi_fisc_luna
           AND ID.sez = c.sezione_censuaria
           AND ind.codi_fisc_luna = c.codi_fisc_luna
           AND ind.sezione = ID.sezione
           AND ind.id_imm = ID.id_imm
           AND ind.progressivo = ID.progressivo
           AND t.pk_id = ind.toponimo
           AND IND.SEQ =
               (SELECT MAX (SEQ)
                  FROM load_cat_uiu_ind IND2
                 WHERE     IND2.ID_IMM = IND.ID_IMM
                       AND IND2.CODI_FISC_LUNA = IND.CODI_FISC_LUNA
                       AND IND2.PROGRESSIVO = IND.PROGRESSIVO)
           AND ID.SEQ =
               (SELECT MAX (SEQ)
                  FROM load_cat_uiu_id LID2
                 WHERE     LID2.ID_IMM = ID.ID_IMM
                       AND LID2.CODI_FISC_LUNA = ID.CODI_FISC_LUNA
                       AND LID2.PROGRESSIVO = ID.PROGRESSIVO)
           AND IND.PROGRESSIVO =
               (SELECT MAX (PROGRESSIVO)
                  FROM load_cat_uiu_ind IND2
                 WHERE     IND2.ID_IMM = IND.ID_IMM
                       AND IND2.CODI_FISC_LUNA = IND.CODI_FISC_LUNA);


DROP VIEW DIOGENE_H501.V_IND_SIT_UIU;

/* Formatted on 18/07/2022 12:22:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.V_IND_SIT_UIU
(
    PKID_UIU,
    FOGLIO,
    PARTICELLA,
    SUB,
    UNIMM,
    DATA_FINE_VAL,
    CIVICO,
    PREFISSO,
    INDIRIZZO,
    PK_CIVICO,
    PK_INDIRIZZO
)
BEQUEATH DEFINER
AS
    SELECT sitiuiu.PKID_UIU,
           SITIUIU.FOGLIO,
           SITIUIU.PARTICELLA,
           SITIUIU.SUB,
           SITIUIU.UNIMM,
           sitiuiu.DATA_FINE_VAL,
           siticivi.CIVICO,
           sitidstr.PREFISSO,
           sitidstr.NOME          AS INDIRIZZO,
           siticivi.PKID_CIVI     AS PK_CIVICO,
           sitidstr.PKID_STRA     AS PK_INDIRIZZO
      FROM sitiuiu,
           siticivi_uiu,
           siticivi,
           sitidstr,
           siticomu,
           SIT_ENTE
     WHERE     SITICOMU.CODI_FISC_LUNA = SIT_ENTE.CODENT
           AND siticivi_uiu.PKID_UIU(+) = sitiuiu.PKID_UIU
           AND siticivi_uiu.PKID_CIVI = siticivi.PKID_CIVI(+)
           AND sitidstr.PKID_STRA(+) = siticivi.PKID_STRA
           AND siticivi_uiu.DATA_FINE_VAL(+) =
               TO_DATE ('99991231', 'yyyymmdd')
           AND siticivi.DATA_FINE_VAL(+) = TO_DATE ('99991231', 'yyyymmdd')
           AND sitidstr.DATA_FINE_VAL(+) = TO_DATE ('99991231', 'yyyymmdd')
           AND SITIUIU.COD_NAZIONALE = SITICOMU.COD_NAZIONALE;


