DROP VIEW DIOGENE_H501.PERSONA_CIVICI_V;

/* Formatted on 18/07/2022 12:22:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.PERSONA_CIVICI_V
(
    PK_ANAGRAFE,
    PK_D_CIVICO,
    ID_ORIG_PERSONA,
    CODFISC,
    COGNOME,
    NOME,
    SESSO,
    DATA_NASCITA,
    ID_EXT_COMUNE_NASCITA,
    POSIZ_ANA,
    DT_INIZIO_VAL_PERSONA,
    DT_FINE_VAL_PERSONA,
    DT_INIZIO_INDIRIZZO,
    DT_FINE_INDIRIZZO,
    VIASEDIME,
    DESCRIZIONE_VIA,
    ID_ORIG_VIA,
    ID_ORIG_CIVICO,
    CIV_LIV1,
    CIV_LIV2,
    CIV_LIV3,
    CIV_COMPOSTO,
    CODENT,
    ID_EXT_PERSONA,
    DATA_IMM_PERSONA,
    DATA_EMI_PERSONA,
    DATA_MOR_PERSONA,
    ID_EXT_D_CIVICO,
    DT_FINE_VAL,
    FK_ENTE_SORGENTE,
    ID_EXT
)
BEQUEATH DEFINER
AS
    SELECT p.ID               pk_anagrafe,
           CV.ID              pk_d_civico,
           p.id_orig          id_orig_persona,
           p.codfisc,
           p.cognome,
           p.nome,
           p.sesso,
           p.data_nascita,
           p.id_ext_comune_nascita,
           p.posiz_ana,
           p.dt_inizio_val    dt_inizio_val_persona,
           p.dt_fine_val      dt_fine_val_persona,
           PC.DT_INIZIO_DATO,
           PC.DT_FINE_DATO,
           CV.viasedime,
           CV.descrizione     descrizione_via,
           CV.id_orig_via     id_orig_via,
           CV.id_orig         id_orig_civico,
           CV.civ_liv1,
           CV.civ_liv2,
           CV.civ_liv3,
           --modificata da qui
           CASE
               WHEN     TRIM (LEADING 0 FROM CV.civ_liv1) IS NOT NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv2) IS NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv3) IS NULL
               THEN
                   TRIM (LEADING 0 FROM CV.civ_liv1)
               WHEN     TRIM (LEADING 0 FROM CV.civ_liv1) IS NOT NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv2) IS NOT NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv3) IS NULL
               THEN
                      TRIM (LEADING 0 FROM CV.civ_liv1)
                   || '/'
                   || TRIM (LEADING 0 FROM CV.civ_liv2)
               WHEN     TRIM (LEADING 0 FROM CV.civ_liv1) IS NOT NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv2) IS NOT NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv3) IS NOT NULL
               THEN
                      TRIM (LEADING 0 FROM CV.civ_liv1)
                   || '/'
                   || TRIM (LEADING 0 FROM CV.civ_liv2)
                   || '/'
                   || TRIM (LEADING 0 FROM CV.civ_liv3)
               WHEN     TRIM (LEADING 0 FROM CV.civ_liv1) IS NOT NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv2) IS NULL
                    AND TRIM (LEADING 0 FROM CV.civ_liv3) IS NOT NULL
               THEN
                      TRIM (LEADING 0 FROM CV.civ_liv1)
                   || '/'
                   || TRIM (LEADING 0 FROM CV.civ_liv3)
           END                civ_composto,
           --a qui
           ente_s_v.codent,
           p.id_ext           id_ext_persona,
           p.data_imm         data_imm_persona,
           p.data_emi         data_emi_persona,
           p.data_mor         data_mor_persona,
           CV.id_ext          id_ext_d_civico,
           p.dt_fine_val,
           p.fk_ente_sorgente,
           p.id_ext
      FROM sit_d_persona         p,
           sit_d_persona_civico  pc,
           sit_d_civico_via_v    CV,
           ente_s_v
     WHERE     p.id_ext = pc.id_ext_d_persona
           AND pc.id_ext_d_civico = CV.id_ext
           AND pc.dt_fine_val IS NULL
           AND CV.dt_fine_val IS NULL
           AND ente_s_v.id_sorgente = p.fk_ente_sorgente;


DROP VIEW DIOGENE_H501.V_STORICO_ANA_COORD_CAT;

/* Formatted on 18/07/2022 12:22:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.V_STORICO_ANA_COORD_CAT
(
    ID,
    ID_EXT,
    ID_ORIG,
    COGNOME,
    NOME,
    SESSO,
    DATA_NASCITA,
    COMUNE_NASCITA,
    PROV_NASCITA,
    FOGLIO,
    MAPPALE,
    SUBALTERNO,
    TIPO_INDIRIZZO_PERS,
    INDIRIZZO_PERS,
    CIVICO_PERS,
    INDIRIZZO_CAT,
    CIVICO_CAT,
    BARRATO_CAT,
    DT_INIZIO_VAL_PERS,
    DT_FINE_VAL_PERS,
    DT_INIZIO_DATO_PERS,
    DT_FINE_DATO_PERS,
    DT_INIZIO_DATO_CAT,
    DT_FINE_DATO_CAT,
    DT_INIZIO_FILE_CAT,
    DT_FINE_FILE_CAT
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT
           P.ID,
           P.ID_EXT,
           P.ID_ORIG,
           P.COGNOME,
           P.NOME,
           P.SESSO,
           P.DATA_NASCITA,
           C.DESCRIZIONE                         AS COMUNE_NASCITA,
           PR.SIGLA                              AS PROV_NASCITA,
           CC.FOGLIO,
           CC.MAPPALE,
           CC.SUBALTERNO,
           V.VIASEDIME                           AS TIPO_INDIRIZZO_PERS,
           V.DESCRIZIONE_VIA                     AS INDIRIZZO_PERS,
           V.CIV_COMPOSTO                        AS CIVICO_PERS,
           CC.DESCRIZIONE_VIA                    AS INDIRIZZO_CAT,
           CC.NUMERO_CIVICO                      AS CIVICO_CAT,
           CC.BARRATO                            AS BARRATO_CAT,
           P.DT_INIZIO_VAL                       AS DT_INIZIO_VAL_PERS,
           P.DT_FINE_VAL                         AS DT_FINE_VAL_PERS,
           P.DT_INIZIO_DATO                      AS DT_INIZIO_DATO_PERS,
           P.DT_FINE_DATO                        AS DT_FINE_DATO_PERS,
           CC.DT_INIZIO_DATO                     AS DT_INIZIO_DATO_CAT,
           CC.DT_FINE_DATO                       AS DT_FINE_DATO_CAT,
           TO_DATE (CC.NOME_FILE, 'YYYYMMDD')    AS DT_INIZIO_FILE_CAT,
           TO_DATE (
               (SELECT MIN (CC1.NOME_FILE)
                  FROM SIT_D_PERSONA_COORD_CAT CC1
                 WHERE     CC1.ID_EXT = CC.ID_EXT
                       AND TO_DATE (CC1.NOME_FILE, 'YYYYMMDD') >
                           TO_DATE (CC.NOME_FILE, 'YYYYMMDD')),
               'YYYYMMDD')                       AS DT_FINE_FILE_CAT
      FROM SIT_D_PERSONA_COORD_CAT  CC
           INNER JOIN SIT_D_PERSONA P ON CC.ID_EXT = P.ID_EXT
           LEFT OUTER JOIN PERSONA_CIVICI_V V ON V.ID_EXT = P.ID_EXT
           LEFT OUTER JOIN SIT_COMUNE C
               ON     C.ID_EXT = P.ID_EXT_COMUNE_NASCITA
                  AND NVL (C.DT_FINE_VAL,
                           TO_DATE ('31/12/9999', 'DD/MM/YYYY')) =
                      TO_DATE ('31/12/9999', 'DD/MM/YYYY')
           LEFT OUTER JOIN SIT_PROVINCIA PR
               ON     PR.ID_EXT = C.ID_EXT_D_PROVINCIA
                  AND NVL (PR.DT_FINE_VAL,
                           TO_DATE ('31/12/9999', 'DD/MM/YYYY')) =
                      TO_DATE ('31/12/9999', 'DD/MM/YYYY');


