/* Formatted on 18/07/2022 12:22:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DIOGENE_H501.PERSONA_CIVICI_SHAPE_V
(
    CIVICO,
    PK_ANAGRAFE,
    PK_SITICIVI,
    CODFISC,
    COGNOME,
    NOME,
    SESSO,
    DATA_NASCITA,
    ID_EXT_COMUNE_NASCITA,
    POSIZ_ANA,
    DT_INIZIO_VAL_PERSONA,
    DT_FINE_VAL_PERSONA,
    VIASEDIME,
    DESCRIZIONE_VIA,
    PREFISSO_VIA,
    NOME_VIA,
    ID_ORIG_VIA,
    CIV_LIV1,
    CIV_LIV2,
    CIV_LIV3,
    SHAPE,
    CODENT
)
BEQUEATH DEFINER
AS
    SELECT civ.civico,
           pc.pk_anagrafe,
           civ.pkid_civi         pk_siticivi,
           pc.codfisc,
           pc.cognome,
           pc.nome,
           pc.sesso,
           pc.data_nascita,
           pc.id_ext_comune_nascita,
           pc.posiz_ana,
           pc.dt_inizio_val_persona,
           pc.dt_fine_val_persona,
           pc.viasedime,
           pc.descrizione_via,
           str.prefisso          prefisso_via,
           str.nome              nome_via,
           pc.id_orig_via        id_orig_via,
           pc.civ_liv1,
           pc.civ_liv2,
           pc.civ_liv3,
           civ.shape             AS shape,
           str.cod_nazionale     codent
      FROM persona_civici_v pc, siticivi civ, sitidstr str
     WHERE     pc.id_orig_via = str.numero
           AND pc.civ_composto = civ.civico                       --modificata
           -- NON POSSO SCENDARE + DEL NUMERO VISTO CHE IN SITI IL CAMPO E' UNICO     AND civ.pkid_stra = str.pkid_stra
           AND civ.pkid_stra = str.pkid_stra
           AND str.data_fine_val =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
           AND civ.data_fine_val =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
           AND str.cod_nazionale = pc.codent;


