    BENE_ID,
    CHIAVE,
    COD_INVENTARIO,
    COD_NAZIONALE,
    COD_VIA,
    DESCR_VIA,
    CIVICO,
    SHAPE
)
BEQUEATH DEFINER
AS
    (SELECT i.id,
            i.dm_b_bene_id     ID_BENE,
