                                     );


DROP VIEW VIRGILIO_H501.DM_B_MAPPALE_PART;

/* Formatted on 18/07/2022 12:22:22 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW VIRGILIO_H501.DM_B_MAPPALE_PART
(
    ID,
    TIPO,
    BENE_ID,
    CHIAVE,
    COD_INVENTARIO,
    COD_NAZIONALE,
    FOGLIO,
    PARTICELLA,
    SHAPE
)
BEQUEATH DEFINER
AS
    (SELECT m.id,
            'F'               AS tipo,
            B.ID,
            b.chiave,
            b.cod_chiave1     cod_inventario,
            p.cod_nazionale,
            p.foglio,
            p.particella,
            shape
       FROM sitipart p, dm_b_mappale m, dm_b_bene b
