            AND p.cod_nazionale = m.cod_comune
            AND p.particella = LPAD (mappale, 5, '0')
            AND b.id = m.dm_b_bene_id)
    UNION ALL
    (SELECT m.id,
            'T'               AS tipo,
            B.ID,
            b.chiave,
            b.cod_chiave1     cod_inventario,
            p.cod_nazionale,
            p.foglio,
            p.particella,
            shape
       FROM sitipart p, dm_b_terreno m, dm_b_bene b
      WHERE     p.foglio = m.foglio
            AND p.cod_nazionale = m.cod_comune
            AND p.particella = LPAD (mappale, 5, '0')
            AND b.id = m.dm_b_bene_id);


DROP VIEW VIRGILIO_H501.IS_PAG_SOGGETTI;

/* Formatted on 18/07/2022 12:22:22 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW VIRGILIO_H501.IS_PAG_SOGGETTI
(
    ORIGINE,
    CF,
    DESCRIZIONE,
    DATA_CONTABILE
)
BEQUEATH DEFINER
AS
      SELECT DISTINCT "ORIGINE",
                      "CF",
                      "DESCRIZIONE",
                      "DATA_CONTABILE"
        FROM (SELECT DISTINCT
                     'MAV'             origine,
                     codice_fiscale    cf,
                        TRIM (
                               s.segmento1
                            || ' - '
                            || s.segmento2
                            || ' '
                            || s.segmento3
                            || ' '
                            || s.segmento4)
                     || indirizzo      descrizione,
                     D.DATA_CONTABILE
                FROM Is_Pag_Mav_Soggetto s, Is_Pag_Mav_Disposizione d
               WHERE     s.codice_Fiscale = d.codice_Debitore
                     AND D.DATA_CONTABILE BETWEEN TO_DATE (
                                                      NVL (NULL, '01/01/0001'),
                                                      'dd/MM/yyyy')
                                              AND TO_DATE (
                                                      NVL (NULL, '31/12/9999'),
                                                      'dd/MM/yyyy')
              UNION ALL
              SELECT DISTINCT 'BONIFICO'                    origine,
                              d.codifica_fisc_ordinante     cf,
                              d.descr_ordinante             descrizione,
                              M.DATA_REGIS_CONTAB           data_contabile
                FROM IS_PAG_RND_MOVIMENTO_INFO d, IS_PAG_RND_MOVIMENTO m
               WHERE     D.ID_FLUSSO = M.ID_FLUSSO
                     AND D.PROGRESSIVO = m.progressivo
                     AND D.PROGRESSIVO_MOV = M.PROGRESSIVO_mov
                     AND NVL (D.PROGRESSIVO_PRATICA, 00) =
                         NVL (M.PROGRESSIVO_PRATICA, 00))
    ORDER BY cf, data_contabile;


