           ID_TITOLO,
           TIPO_ACQUISIZIONE,
           TIPO_DIRITTO_REALE,
           OGGETTO,
           STRUMENTO_COSTRUTTIVO,
           ANNO_ACQUISIZIONE,
           NORMATIVA_UTILIZZATA,
           DOCPROP_ORIGINE,
           DOCPROP_NUMERO,
           DOCPROP_CONTRAENTI,
           DOCPROP_PAGAMENTO,
           DOCPROP_PATTICOND,
           DOCPROP_SERVATT,
           DOCPROP_SERVPASS,
           TO_DATE (TIT_DATA, 'YYYYMMdd')         TIT_DATA,
           TIT_REG_ATTI,
           TIT_REG_UFFICIO,
           TIT_REG_NUMERO,
           TIT_REG_VOLUME,
           TIT_REG_SERIE,
           TO_DATE (TIT_REG_DATA, 'YYYYMMdd')     TIT_REG_DATA,
           TO_DATE (TRASCR_DATA, 'YYYYMMdd')      TRASCR_DATA,
           TRASCR_NUM,
           TRASCR_NUMORDINE,
           TRASCR_LOCALITA,
           ANNOTAZIONI,
           NULL                                   AS DT_INIZIO_DATO,
           NULL                                   AS DT_FINE_DATO,
           v.PROVENIENZA,
           v.tipo,
           SYSDATE                                AS DT_INIZIO_VAL,
           NULL                                   AS DT_FINE_VAL,
           NULL                                   AS DT_MOD,
           NULL                                   AS ctr_hash,
           SYSDATE
      FROM VIRGILIO_GIT.V_F205_BENE_TITOLI  V
           LEFT JOIN VIRGILIO_GIT.DM_B_BENE b ON b.chiave = v.chiave_bene;


DROP VIEW VIRGILIO_H501.V_F205_BENE_INDIRIZZI;

/* Formatted on 18/07/2022 12:22:22 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW VIRGILIO_H501.V_F205_BENE_INDIRIZZI
(
    PK_ORIG_BENE,
    CHIAVE_BENE,
    FL_PRINCIPALE,
    COD_VIA,
    TIPOVIA,
    DESCR_VIA,
    CIVICO,
    COD_COM,
    COMUNE,
    PROV,
    TIPO,
    PROVENIENZA,
    ID
)
BEQUEATH DEFINER
AS
    (SELECT c."PK_ORIG",
            c."CHIAVE_BENE",
            c."FL_PRINCIPALE",
            c."COD_VIA",
            c."TIPOVIA",
            c."DESCR_VIA",
            c."CIVICO",
            c."COD_COM",
            c."COMUNE",
            c.prov,
            c."TIPO",
            'INVENTAMI'    provenienza,
               chiave_bene
            || '|'
            || NVL (fl_principale, 0)
            || '|'
            || cod_com
            || '|'
            || cod_via
            || '|'
            || civico      AS id
       FROM (SELECT -- i.rowid  rigaid--i.id_fabbricato, i.id_immobile, i.cod_via, i.civico, i.cod_comune, i.fl_principale, i.cap,
                    Im.ID                        PK_ORIG,
                    TO_CHAR (cod_inventario)     chiave_bene,
                    i.fl_principale,
                    i.cod_via,
                    vie.tipovia,
                    vie.descr_via,
                    i.civico,
                    com.cod_com,
                    com.comune,
                    com.prov,
                    'I'                          tipo
               FROM indirizzi  i
                    LEFT JOIN tab_vie vie ON vie.cod_via = i.cod_via
                    LEFT JOIN tab_comuni com ON i.cod_comune = com.cod_com,
                    immobili   im
              WHERE     im.id = i.id_immobile
                    AND id_fabbricato IS NULL
                    AND tipo = '01'
             UNION
             SELECT --i.rowid, --i.id_fabbricato, i.id_immobile, i.cod_via, i.civico, i.cod_comune, i.fl_principale, i.cap,
                    F.ID                   PK_ORIG,
                    DECODE (
                        COD_FABBRICATO,
                        NULL,    cod_inventario
                              || '@'
                              || F.COD_FABBRICATO
                              || '@F'
                              || F.ID
                              || '@FIS',
                        DECODE (
                            (SELECT COUNT (*)
                               FROM fabbricatI FF
                              WHERE     ID_IMMOBILE = F.ID_IMMOBILE
                                    AND COD_FABBRICATO = F.COD_FABBRICATO),
                            1, cod_inventario || '@' || F.COD_FABBRICATO,
                               cod_inventario
                            || '@'
                            || F.COD_FABBRICATO
                            || '@F'
                            || F.ID
                            || '@FIS'))    chiave_bene,
                    i.fl_principale,
                    i.cod_via,
                    vie.tipovia,
                    vie.descr_via,
                    i.civico,
                    com.cod_com,
                    com.comune,
                    com.prov,
                    'F'                    tipo
               FROM fabbricati  f,
                    indirizzi   i
                    LEFT JOIN tab_vie vie ON vie.cod_via = i.cod_via
                    LEFT JOIN tab_comuni com ON i.cod_comune = com.cod_com,
                    immobili    im
              WHERE     f.id = i.id_fabbricato
                    AND i.id_immobile = im.id
                    AND im.tipo = '01'
                    AND (COD_FABBRICATO IS NULL OR COLLEGA IS NOT NULL)) c);


DROP VIEW VIRGILIO_H501.V_F205_BENE_MAPPALI;

/* Formatted on 18/07/2022 12:22:22 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW VIRGILIO_H501.V_F205_BENE_MAPPALI
(
    CHIAVE_BENE,
    CHIAVE1,
    CHIAVE2,
    CHIAVE3,
    CHIAVE4,
    CHIAVE5,
    TIPO_MAPPALE,
    COD_COM,
    SEZIONE,
    FOGLIO,
    MAPPALE,
    DATA_INIZIO,
    DATA_FINE,
    TIPO,
    PROVENIENZA,
    ID
)
BEQUEATH DEFINER
AS
    SELECT c."CHIAVE_BENE",
           c."CHIAVE1",
           c."CHIAVE2",
           c."CHIAVE3",
           c."CHIAVE4",
           c."CHIAVE5",
           c."TIPO_MAPPALE",
           c."COD_COMUNE",
           c."SEZIONE",
           c."FOGLIO",
           c."MAPPALE",
           c."DATA_INIZIO",
           c."DATA_FINE",
           c."TIPO",
           c."PROVENIENZA",
              chiave_bene
           || '|'
           || cod_comune
           || '|'
           || foglio
           || '|'
           || mappale
      FROM (SELECT DECODE (
                       COD_FABBRICATO,
                       NULL,    cod_inventario
                             || '@'
                             || F.COD_FABBRICATO
                             || '@F'
                             || F.ID
                             || '@FIS',
                       DECODE (
                           (SELECT COUNT (*)
                              FROM fabbricatI FF
                             WHERE     ID_IMMOBILE = F.ID_IMMOBILE
                                   AND COD_FABBRICATO = F.COD_FABBRICATO),
                           1, cod_inventario || '@' || F.COD_FABBRICATO,
                              cod_inventario
                           || '@'
                           || F.COD_FABBRICATO
                           || '@F'
                           || F.ID
                           || '@FIS'))
                       chiave_bene,
                   COD_INVENTARIO
                       CHIAVE1,
                   F.COD_FABBRICATO
                       CHIAVE2,
                   DECODE (COD_FABBRICATO, NULL, 'F' || F.ID, NULL)
                       CHIAVE3,
                   NULL
                       CHIAVE4,
                   NULL
                       CHIAVE5,
                   NULL
                       TIPO_MAPPALE,
                   F.COD_COMUNE,
                   NULL
                       AS sezione,
                   FC.FOGLIO,
                   FC.MAPPALE,
                   NULL
                       DATA_INIZIO,
                   NULL
                       DATA_FINe,
                   'F'
                       tipo,
                   'INVENTAMI'
                       PROVENIENZA
              FROM IMMOBILI  I
                   JOIN FABBRICATI F
                       ON     F.ID_IMMOBILE = I.ID
                          AND i.tipo = '01'
                          AND (COD_FABBRICATO IS NULL OR COLLEGA IS NOT NULL)
                   JOIN R_FABBRICATI_CATASTO FC ON FC.ID_FABBRICATO = F.ID) c;


