)
BEQUEATH DEFINER
AS
    SELECT TO_CHAR (COD_INVENTARIO)
               CHIAVE_BENE,
           COD_INVENTARIO
               CHIAVE1,
           NULL
               CHIAVE2,
           NULL
               CHIAVE3,
           NULL
               CHIAVE4,
           NULL
               CHIAVE5,
           f.cod_comune,
           NULL
               AS sezione,
           foglio,
           mappale,
           sub,
           superfice
               superficie,
           classe,
           qualita,
           tt.descrizione
               tipologia,
           ft.descrizione
               finalita,
           fonte,
           uso_attuale,
           cod_utiliz
               cod_utilizzo,
           partita,
           unita,
           annotazione,
           redd_domin,
           redd_agrar,
           valut_inv
               valore_inventario,
           val_catastale,
           val_acquisto,
           val_mercato
               rendita_presunta,
           quot_poss,
           f.note,
           f.fl_vendita
               dismesso,
           TO_DATE (f.data_vendita, 'yyyy/MM/dd')
               dt_vendita,
           (SELECT    '{"contratti":['
                   || (  SELECT wm_concat (json)     AS employees
                           FROM (SELECT DISTINCT
                                        id_terreno,
                                           '{"Intestatario":"'
                                        || intestatario
                                        || '", "Tipologia":"'
                                        || DECODE (tipologia,
                                                   1, 'USI DIVERSI',
                                                   2, 'AGRICOLO')
                                        || '", "Parte":"'
                                        || parte
                                        || '"}'    json
                                   FROM contratti)
                          WHERE id_terreno = f.id
                       GROUP BY id_terreno)
                   || ']}'
              FROM DUAL)
               contratti,
           NULL
               DATA_INIZIO,
           NULL
               DATA_FINe,
           'I'
               tipo,
           'INVENTAMI'
               PROVENIENZA,
              cod_inventario
           || '@T'
           || F.ID
           || '@FIS'
           || '|'
           || f.cod_comune
           || '|'
           || foglio
           || '|'
           || mappale
      FROM DEMANIO.IMMOBILI  I
           JOIN DEMANIO.TERRENI F ON F.ID_IMMOBILE = I.ID AND i.tipo = '01'
           LEFT JOIN DEMANIO.tab_finalita_terreno ft
               ON f.id_finalita_terreno = ft.id
           LEFT JOIN DEMANIO.tab_tipologia_terreno tt
               ON f.id_tipologia_terreno = tt.id;


