/* Formatted on 18/07/2022 12:22:22 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW VIRGILIO_H501.V_F205_BENE_TITOLI
(
    CHIAVE_BENE,
    CHIAVE1,
    CHIAVE2,
    CHIAVE3,
    CHIAVE4,
    CHIAVE5,
    ID_TITOLO,
    TIPO_ACQUISIZIONE,
    TIPO_DIRITTO_REALE,
    OGGETTO,
    STRUMENTO_COSTRUTTIVO,
    ANNO_ACQUISIZIONE,
    NORMATIVA_UTILIZZATA,
    DOCPROP_ORIGINE,
    DOCPROP_NUMERO,
    DOCPROP_CONTRAENTI,
    DOCPROP_PAGAMENTO,
    DOCPROP_PATTICOND,
    DOCPROP_SERVATT,
    DOCPROP_SERVPASS,
    TIT_DATA,
    TIT_REG_ATTI,
    TIT_REG_UFFICIO,
    TIT_REG_NUMERO,
    TIT_REG_VOLUME,
    TIT_REG_SERIE,
    TIT_REG_DATA,
    TRASCR_DATA,
    TRASCR_NUM,
    TRASCR_NUMORDINE,
    TRASCR_LOCALITA,
    ANNOTAZIONI,
    PROVENIENZA,
    TIPO,
    ID
)
BEQUEATH DEFINER
AS
    SELECT -- i.rowid  rigaid--i.id_fabbricato, i.id_immobile, i.cod_via, i.civico, i.cod_comune, i.fl_principale, i.cap,
           TO_CHAR (cod_inventario)    chiave_bene,
           COD_INVENTARIO              CHIAVE1,
           NULL                        CHIAVE2,
           NULL                        CHIAVE3,
           NULL                        CHIAVE4,
           NULL                        CHIAVE5,
           TO_CHAR (t.id)              id_titolo,
           TA.DESCRIZIONE              tipo_acquisizione,
           dr.descrizione              tipo_DIRITTO_REALE,
           oggetto,
           CASE t.tipo_strumento
               WHEN 1 THEN 'ROGITO (Atto Notarile)'
               WHEN 2 THEN 'DECRETO DI ESPROPRIO'
               WHEN 3 THEN 'DELIBERA'
               WHEN 4 THEN 'ALTRO'
               ELSE 'NON CODIFICATO'
           END                         STRUMENTO_COSTRUTTIVO,
           anno_acquisizione,
           normativa_acquisizione      normativa_utilizzata,
           CASE ORIGINE_TITOLO
               WHEN 'GM' THEN 'Giunta Municipale'
               WHEN 'P' THEN 'Prefetto'
               WHEN 'CC' THEN 'Consiglio Comunale'
               ELSE ORIGINE_TITOLO
           END                         DOCPROP_ORIGINE,
           NUM_TITOLO                  DOCPROP_NUMERO,
           CONTRAENTI                  DOCPROP_CONTRAENTI,
           PAGAMENTO                   DOCPROP_PAGAMENTO,
           PATTI_COND                  DOCPROP_PATTICOND,
           SERV_ATT                    DOCPROP_SERVATT,
           SERV_PASS                   DOCPROP_SERVPASS,
           DATA_TITOLO                 TIT_DATA,
           t.ATTO_REGISTRAZIONE        TIT_REGATTI,
           UFFICIO_REGISTRO            TIT_UFFICIO_REGISTRO,
           NUM_REGISTRO                TIT_NUMERO_REGISTRO,
           VOLUME_REGISTRO             TIT_VOLUME_REGISTRO,
           SERIE_REGISTRO              TIT_SERIE_REGISTRO,
           DATA_REGISTRO               TIT_DATA_REGISTRO,
           DATA_TRASCRIZIONE           TRASCR_DATA,
           NUM_TRASCRIZIONE            TRASCR_NUM,
           NUM_ORDINE                  TRASCR_NUMORDINE,
           LOCALITA_REGISTRO           TRASCR_LOCALITA,
           T.ANNOTAZIONI,
           'INVENTAMI'                 PROVENIENZA,
           'I'                         TIPO,
           NULL                        ID
      FROM DEMANIO.titoli  t
           LEFT JOIN DEMANIO.TAB_ACQUISIZIONE ta
               ON t.id_tipo_acquisizione = ta.id
           LEFT JOIN DEMANIO.tab_diritto_reale dr
               ON t.id_tipo_diritto_reale = dr.id
           LEFT JOIN DEMANIO.titoli_proprieta tp ON tp.id_titolo = t.id
           LEFT JOIN DEMANIO.immobili i ON tp.id_immobile = i.id
     WHERE I.TIPO = '01' AND i.cod_inventario IS NOT NULL;


