    TOT_ABITATIVA,
    TOT_USI_DIVERSI,
    TOT_UNITA,
    TOT_UNITA_COMUNALI,
    NUM_BOX,
    DATA_CENSIMENTO,
    STATO_CENSIMENTO,
    DATA_RIL,
    DATA_INS,
    DATA_AGG,
    MEF_TIPOLOGIA,
    MEF_UTILIZZO,
    MEF_FINALITA,
    MEF_NATURA_GIURIDICA,
    NUM_PARTI,
    VOLUME_TOT,
    SUP_COP,
    SUP_TOT,
    SUP_TOT_SLP,
    SUP_LOC,
    SUP_OPER,
    SUP_CO_SE,
    NUM_PIANI_F,
    NUM_PIANI_I,
    REND_CATAS,
    VOLUME_F,
    VOLUME_I,
    SUP_COMMERCIALE,
    VAL_ACQUISTO,
    VAL_CATASTALE,
    NUM_VANI,
    METRI_Q,
    PROVENIENZA
)
BEQUEATH DEFINER
AS
    SELECT I.ID
               PK_ORIG,
           TO_CHAR (cod_inventario)
               chiave,
           NULL
               chiave_padre,
           COD_INVENTARIO
               CHIAVE1,
           NULL
               CHIAVE2,
           NULL
               CHIAVE3,
           NULL
               CHIAVE4,
           NULL
               CHIAVE5,
           NULL
               cod_ecografico,
           COD_INVENTARIO
               cod_inventario,
           TIPO
               COD_TIPO,
           DECODE (tipo,  '01', 'Proprietà',  '02', 'Fitti Passivi',  NULL)
               des_tipo,
           NUM_CARTELLA
               COD_cartella,
           NULL
               des_cartella,
           TIPO_BENE
               COD_tipo_bene,
           CASE
               WHEN TIPO_BENE = 3 AND NUM_PARTI > 1
               THEN
                   'Gruppo di Unità'
               ELSE
                   DECODE (tipo_bene,
                           '1', 'Edificio',
                           '2', 'Complesso',
                           '3', 'Unità',
                           '4', 'Area',
                           'Area')
           END
               des_tipo_bene,
           TIPO_PROPRIETA
               COD_tipo_proprieta,
           NULL
               des_tipo_proprieta,
           TIPO_USO
               COD_tipo_uso,
           u.descrizione
               des_tipo_uso,
           i.descrizione,
           note,
           ID_CAT_INVENTARIALE
               COD_cat_inventariale,
           c.descrizione
               des_cat_inventariale,
           i.categoria
               COD_CATEGORIA,
           NULL
               des_categoria,
           NULL
               COD_SOTTO_CATEGORIA,
           NULL
               DES_SOTTO_CATEGORIA,
           NULL
               QUALITA,
           QUOTA_PRO
               QUOTA_PROPRIETA,
           FL_VENDITA,
           FL_CONGELATO,
           FL_ANTICO_POSSESSO,
           TO_DATE (DATA_VENDITA, 'yyyyMMdd')
               DATA_VENDITA,
           ANNO_ACQ,
           ANNO_COSTR,
           ANNO_RISTR,
           VAL_INVENTARIALE,
           TOT_ABITATIVA,
           TOT_USI_DIVERSI,
           NULL
               TOT_UNITA,
           TOT_UNITA_COMUNALI,
           NUM_BOX,
           TO_DATE (DATA_CENSIMENTO, 'yyyyMMdd')
               DATA_CENSIMENTO,
           STATO_CENSIMENTO,
           TO_DATE (NULL, 'yyyyMMdd')
               data_ril,
           TO_DATE (NULL, 'yyyyMMdd')
               DATA_INS,
           TO_DATE (NULL, 'yyyyMMdd')
               data_agg,
           NULL
               MEF_TIPOLOGIA,
           NULL
               MEF_UTILIZZO,
           NULL
               MEF_FINALITA,
           NULL
               MEF_NATURA_GIURIDICA,
           NUM_PARTI,
           VOLUME
               VOLUME_TOT,
           SUP_COP,
           SUP_TOT,
           SUP_TOT_SLP,
           SUP_LOC,
           SUP_OPER,
           SUP_CO_SE,
           NUM_PIANI_F,
           NUM_PIANI_I
               NUM_PIANI_I,
           TO_NUMBER (NULL)
               REND_CATAS,
           TO_NUMBER (NULL)
               VOLUME_F,
           TO_NUMBER (NULL)
               VOLUME_I,
           TO_NUMBER (NULL)
               SUP_COMMERCIALE,
           TO_NUMBER (NULL)
               VAL_ACQUISTO,
           TO_NUMBER (NULL)
               VAL_CATASTALE,
           TO_NUMBER (NULL)
               NUM_VANI,
           TO_NUMBER (NULL)
               METRI_Q,
           'INVENTAMI'
               PROVENIENZA
      FROM immobili  i
           LEFT JOIN tab_cat_inventariale c ON i.id_cat_inventariale = c.id
           LEFT JOIN tab_tipo_uso u ON i.tipo_uso = u.id
     WHERE I.TIPO = '01';


