/* Formatted on 18/07/2022 12:22:23 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW VIRGILIO_H501.V_INSDEM_B_BENE_FABB
(
    CHIAVE,
    COD_CHIAVE1,
    COD_CHIAVE2,
    COD_CHIAVE3,
    COD_CHIAVE4,
    COD_CHIAVE5,
    COD_ECOGRAFICO,
    COD_TIPO_BENE,
    DES_TIPO_BENE,
    NUM_PARTI,
    DESCRIZIONE,
    NOTE,
    CHIAVE_PADRE,
    DM_B_BENE_PADRE_ID,
    PROVENIENZA,
    TIPO,
    DT_INIZIO_VAL,
    DT_FINE_VAL,
    DT_MOD,
    CTR_HASH,
    DT_ELAB
)
BEQUEATH DEFINER
AS
      SELECT ID_ORIG,
             CHIAVE1,
             CHIAVE2,
             CHIAVE3,
             CHIAVE4,
             CHIAVE5,
             COD_ECOGRAFICO,
             COD_TIPO_BENE,
             DES_TIPO_BENE,
             num_parti,
             DESCRIZIONE,
             NOTE,
             CHIAVE_PADRE,
             (SELECT id
                FROM DM_B_BENE
               WHERE CHIAVE = V.CHIAVE_PADRE)    DM_B_BENE_PADRE_FK,
             V.PROVENIENZA                       PROVENIENZA,
             V.TIPO,
             DT_INIZIO_VAL,
             DT_FINE_VAL,
             DT_MOD,
             CTR_HASH,
             SYSDATE
        FROM R_DEMANIO_BENE V
       WHERE v.tipo = 'F'
    ORDER BY TO_NUMBER (chiave1), TO_NUMBER (chiave2);


