    DT_INIZIO_VAL,
    DT_FINE_VAL,
    DT_MOD,
    CTR_HASH,
    DT_ELAB
)
BEQUEATH DEFINER
AS
    SELECT B.ID                                   DM_B_BENE_FK,
           NULL                                   COD_EVENTO,
           'VENDITA'                              DESCRIZIONE_EVENTO,
           TO_CHAR (DATA_VENDITA, 'yyyymmdd')     DATA_EVENTO,
           V.PROVENIENZA                          PROVENIENZA,
           v.TIPO,
           v.DT_INIZIO_VAL                        DATA_VAL_DA,
           v.DT_FINE_VAL                          DATA_VAL_A,
           v.DT_MOD,
           v.ctr_hash,
           SYSDATE                                DATA_INS
      FROM R_DEMANIO_BENE_EVENTI V JOIN DM_B_BENE b ON b.chiave = v.id_orig
     WHERE FL_VENDITA = 1
    UNION
    SELECT B.ID                DM_B_BENE_FK,
           NULL                COD_EVENTO,
           'ACQUISTO',
           ANNO_ACQ,
           V.PROVENIENZA       PROVENIENZA,
           v.TIPO,
           v.DT_INIZIO_VAL     DATA_VAL_DA,
           v.DT_FINE_VAL       DATA_VAL_A,
           v.DT_MOD,
           v.ctr_hash,
           SYSDATE             DATA_INS
      FROM R_DEMANIO_BENE_EVENTI V JOIN DM_B_BENE b ON b.chiave = v.id_orig
     WHERE ANNO_ACQ IS NOT NULL
    UNION
    SELECT B.ID                DM_B_BENE_FK,
           NULL                COD_EVENTO,
           'COSTRUZIONE',
           ANNO_COSTR,
           V.PROVENIENZA       PROVENIENZA,
           v.TIPO,
           v.DT_INIZIO_VAL     DATA_VAL_DA,
           v.DT_FINE_VAL       DATA_VAL_A,
           v.DT_MOD,
           v.ctr_hash,
           SYSDATE             DATA_INS
      FROM R_DEMANIO_BENE_EVENTI V JOIN DM_B_BENE b ON b.chiave = v.id_orig
     WHERE ANNO_COSTR IS NOT NULL
    UNION
    SELECT B.ID                DM_B_BENE_FK,
           NULL                COD_EVENTO,
           'RISTRUTTURAZIONE',
           ANNO_RISTR,
           V.PROVENIENZA       PROVENIENZA,
           v.TIPO,
           v.DT_INIZIO_VAL     DATA_VAL_DA,
           v.DT_FINE_VAL       DATA_VAL_A,
           v.DT_MOD,
           v.ctr_hash,
           SYSDATE             DATA_INS
      FROM R_DEMANIO_BENE_EVENTI V JOIN DM_B_BENE b ON b.chiave = v.id_orig
     WHERE ANNO_RISTR IS NOT NULL;


DROP VIEW VIRGILIO_H501.VW_ANAGRAFE;

/* Formatted on 18/07/2022 12:22:23 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW VIRGILIO_H501.VW_ANAGRAFE
(
    TIPO_SOGGETTO,
    CODICE_FISCALE,
    COGNOME,
    NOME,
    SESSO,
    DATA_NASCITA,
    DESCR_COMUNE_NASCITA,
    DESCR_INDIRIZZO
)
BEQUEATH DEFINER
AS
    (SELECT ana.posiz_ana           tipo_soggetto,
            ana.codfisc             codice_fiscale,
            ana.cognome,
            ana.nome,
            ana.sesso,
            ana.data_nascita,
            c.descrizione           descr_comune_nascita,
            LTRIM (
                   ana.viasedime
                || ' '
                || ana.descrizione_via
                || ' '
                || LTRIM (ana.civ_liv1, '0')
                || '/'
                || ana.civ_liv2)    AS descr_indirizzo
       FROM sit_comune c, persona_civici_v ana
      WHERE     ana.id_ext_comune_nascita = c.id_ext
            AND c.dt_fine_val IS NULL
            AND ana.dt_fine_val_persona IS NULL);


