CREATE OR REPLACE FORCE VIEW SITI_H501.AG_TOPO
(
    ID_TYPE,
    ID_TOPO,
    COD_UTENTE,
    ID_COMUNE,
    INIZIO,
    FINE,
    UT_INIZIO,
    UT_FINE,
    ATTO_INI
)
BEQUEATH DEFINER
AS
    SELECT aggr_code                                      AS id_type,
           pkid_topo                                      AS id_topo,
