DROP VIEW SITI_H501.ASSIOMA_ALLEGATI;

/* Formatted on 18/07/2022 12:22:58 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.ASSIOMA_ALLEGATI
(
    ID_BUILDING,
    INVENTARY,
    FLAG_DELETE,
    DOC_CAT_DESCRIPTION,
    FKID_CATEGORIA,
    PKID_ATTO,
    PKID_TIPO,
    DESCRIZIONE_ATTO,
    PKID_DOC,
    FKID_TIPO_DOC,
    DESCRIZIONE_DOC,
    ID_FILE,
    ID_FORMATO,
    NOMEFILE,
    NOMEFILEC,
    NOTE
)
BEQUEATH DEFINER
AS
      SELECT assioma_building_doc.id_building,
             assioma_building_doc.inventary,
             assioma_building_doc.flag_delete,
             assioma_doc_cat.doc_cat_description,
             sitifile_tipi_atto_cat_mm.fkid_categoria,
             sitifile_atti.pkid_atto,
             sitifile_tipi_atto.pkid_tipo,
             sitifile_tipi_atto.descrizione     AS descrizione_atto,
             sitifile_documenti.pkid_doc,
             sitifile_documenti.fkid_tipo_doc,
             sitifile_tipidoc.descrizione       AS descrizione_doc,
             sitifile_caricati.id_file,
             sitifile_caricati.id_formato,
             sitifile_caricati.nomefile,
             sitifile_caricati.nomefilec,
             sitifile_caricati.note
        FROM ((((((((assioma_building_doc
                     LEFT JOIN
                     sitifile_atti
                     ON assioma_building_doc.pkid_atto =
                        sitifile_atti.pkid_atto)
                    LEFT JOIN
                    sitifile_atti_doc
                    ON sitifile_atti_doc.fkid_atto = sitifile_atti.pkid_atto)
                   LEFT JOIN
                   sitifile_tipi_atto
                   ON sitifile_atti.fkid_tipo_atto =
                      sitifile_tipi_atto.pkid_tipo)
                  LEFT JOIN
                  sitifile_tipi_atto_cat_mm
                  ON sitifile_tipi_atto_cat_mm.fkid_tipo_atto =
                     sitifile_tipi_atto.pkid_tipo)
                 LEFT JOIN
                 assioma_doc_cat
                 ON sitifile_tipi_atto_cat_mm.fkid_categoria LIKE
                        assioma_doc_cat.doc_cat_prefix)
                LEFT JOIN
                sitifile_documenti
                ON sitifile_atti_doc.fkid_doc = sitifile_documenti.pkid_doc)
               LEFT JOIN
               sitifile_tipidoc
               ON sitifile_documenti.fkid_tipo_doc =
                  sitifile_tipidoc.pkid_tipo_doc)
              LEFT JOIN
              sitifile_documenti_file
              ON sitifile_documenti.pkid_doc = sitifile_documenti_file.fkid_doc)
             LEFT JOIN sitifile_caricati
                 ON sitifile_documenti_file.fkid_file =
                    sitifile_caricati.id_file
    ORDER BY assioma_building_doc.inventary,
             assioma_building_doc.id_building,
             assioma_doc_cat.doc_cat_prefix,
             sitifile_atti.pkid_atto,
             sitifile_documenti.pkid_doc,
             sitifile_caricati.note,
             sitifile_caricati.nomefile;


DROP VIEW SITI_H501.ASSIOMA_ATTI_LIST;

/* Formatted on 18/07/2022 12:22:58 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.ASSIOMA_ATTI_LIST
(
    PKID_ATTO,
    FKID_TIPO_ATTO,
    DATA_AGGIORNAMENTO,
    UTENTE_INS,
    DATA_INS,
    VALIDO,
    DESCRIZIONE,
    NOTE,
    PKCATEGORIA,
    DESCRIZIONE_CAT
)
BEQUEATH DEFINER
AS
    SELECT SITIFILE_ATTI."PKID_ATTO",
           SITIFILE_ATTI."FKID_TIPO_ATTO",
           SITIFILE_ATTI."DATA_AGGIORNAMENTO",
           SITIFILE_ATTI."UTENTE_INS",
           SITIFILE_ATTI."DATA_INS",
           SITIFILE_ATTI."VALIDO",
           SITIFILE_TIPI_ATTO.DESCRIZIONE,
           SITIFILE_TIPI_ATTO.NOTE,
           SITIFILE_TIPI_ATTO_CAT.PKCATEGORIA,
           SITIFILE_TIPI_ATTO_CAT.DESCRIZIONE     AS DESCRIZIONE_CAT
      FROM SITIFILE_ATTI,
           SITIFILE_TIPI_ATTO,
           SITIFILE_TIPI_ATTO_CAT,
           SITIFILE_TIPI_ATTO_CAT_MM
     WHERE     SITIFILE_ATTI.FKID_TIPO_ATTO = SITIFILE_TIPI_ATTO.PKID_TIPO
           AND SITIFILE_TIPI_ATTO.PKID_TIPO =
               SITIFILE_TIPI_ATTO_CAT_MM.FKID_TIPO_ATTO
           AND SITIFILE_TIPI_ATTO_CAT_MM.FKID_CATEGORIA =
               SITIFILE_TIPI_ATTO_CAT.PKCATEGORIA;


