DROP VIEW SITI_H501.ASSIOMA_DOC_FIELD_LIST;

/* Formatted on 18/07/2022 12:22:58 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.ASSIOMA_DOC_FIELD_LIST
(
    PKID_TIPO_DOC,
    DESCRIZIONE_DOC,
    FKID_CAMPO,
    POSITION,
    DESCRIZIONE_CAMPO,
    TIPO_VALORE,
    TIPO_CAMPO,
    LUNGHEZZA_CAMPO,
    FORMATTER
)
BEQUEATH DEFINER
AS
    SELECT sitifile_tipidoc.pkid_tipo_doc,
           sitifile_tipidoc.descrizione        AS descrizione_doc,
           sitifile_tipi_doc_campi_ext.fkid_campo,
           sitifile_tipi_doc_campi_ext.position,
           siti_tipi_campi_ext.descrizione     AS descrizione_campo,
           siti_tipi_campi_ext.tipo_valore,
           siti_tipi_campi_ext.tipo_campo,
           siti_tipi_campi_ext.lunghezza_campo,
           siti_tipi_campi_ext.formatter
      FROM sitifile_tipidoc, sitifile_tipi_doc_campi_ext, siti_tipi_campi_ext
     WHERE     sitifile_tipidoc.pkid_tipo_doc =
               sitifile_tipi_doc_campi_ext.fkid_tipo_doc
           AND sitifile_tipi_doc_campi_ext.fkid_campo =
               siti_tipi_campi_ext.pkid;


DROP VIEW SITI_H501.ASSIOMA_FIELDS_USED;

/* Formatted on 18/07/2022 12:22:58 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.ASSIOMA_FIELDS_USED
(
    INVENTARY,
    ID_CESPITE,
    FLAG_DELETE,
    PKCATEGORIA,
    LONG_DESCRIPTION_CAT,
    SHORT_DESCRIPTION_CAT,
    DOC_CAT_PREFIX,
    PKID_ATTO,
    FKID_TIPO_ATTO,
    ATTO_VALIDO,
    DESCRIPTION_ATTO,
    PKID_DOC,
    FKID_TIPO_DOC,
    DESCRIZIONE_BREVE,
    DESCRIZIONE_ESTESA,
    DOC_VALIDO,
    DESCRIPTION_TYPEDOC,
    FKID_CAMPO,
    DESCRIPTION_FIELD,
    TIPO_VALORE,
    LUNGHEZZA_CAMPO
)
BEQUEATH DEFINER
AS
    SELECT assioma_building_doc.inventary,
           assioma_building_doc.id_building,
           assioma_building_doc.flag_delete,
           sitifile_tipi_atto_cat.pkcategoria,
           sitifile_tipi_atto_cat.descrizione      AS long_description_cat,
           assioma_doc_cat.doc_cat_description     AS short_description_cat,
           assioma_doc_cat.doc_cat_prefix,
           assioma_building_doc.pkid_atto,
           sitifile_atti.fkid_tipo_atto,
           sitifile_atti.valido                    AS atto_valido,
           sitifile_tipi_atto.descrizione          AS description_atto,
           sitifile_documenti.pkid_doc,
           sitifile_documenti.fkid_tipo_doc,
           sitifile_documenti.descrizione_breve,
           sitifile_documenti.descrizione_estesa,
           sitifile_documenti.valido               AS doc_valido,
           sitifile_tipidoc.descrizione            AS description_typedoc,
           sitifile_tipi_doc_campi_ext.fkid_campo,
           siti_tipi_campi_ext.descrizione         AS description_field,
           siti_tipi_campi_ext.tipo_valore,
           siti_tipi_campi_ext.lunghezza_campo
      FROM assioma_building_doc,
           assioma_doc_cat,
           sitifile_tipi_atto_cat,
           sitifile_tipi_atto_cat_mm,
           sitifile_atti,
           sitifile_tipi_atto,
           sitifile_atti_doc,
           sitifile_documenti,
           sitifile_tipidoc,
           sitifile_tipi_doc_campi_ext,
           siti_tipi_campi_ext
     WHERE     assioma_building_doc.pkid_atto = sitifile_atti.pkid_atto
           AND sitifile_tipi_atto_cat.pkcategoria LIKE
                   assioma_doc_cat.doc_cat_prefix
           AND sitifile_tipi_atto_cat.pkcategoria =
               sitifile_tipi_atto_cat_mm.fkid_categoria
           AND sitifile_tipi_atto_cat_mm.fkid_tipo_atto =
               sitifile_tipi_atto.pkid_tipo
           AND sitifile_tipi_atto.pkid_tipo = sitifile_atti.fkid_tipo_atto
           AND sitifile_atti.pkid_atto = sitifile_atti_doc.fkid_atto
           AND sitifile_atti_doc.fkid_doc = sitifile_documenti.pkid_doc
           AND sitifile_documenti.fkid_tipo_doc =
               sitifile_tipidoc.pkid_tipo_doc
           AND sitifile_documenti.fkid_tipo_doc =
               sitifile_tipi_doc_campi_ext.fkid_tipo_doc
           AND sitifile_tipi_doc_campi_ext.fkid_campo =
               siti_tipi_campi_ext.pkid;


