DROP VIEW SITI_H501.CHK_LOAD_TITOLI_PART;

/* Formatted on 18/07/2022 12:22:58 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CHK_LOAD_TITOLI_PART
(
    PKTIT,
    TIPO,
    FOGLIO,
    PARTICELLA,
    SUB,
    DATA_INIZIO,
    DENOMINAZIONE,
    FOGLIO1,
    PARTICELLA1,
    SUB1,
    DATA_INIZIO1,
    DENOMINAZIONE1,
    COD_FISC,
    TP_SOG
)
BEQUEATH DEFINER
AS
    SELECT "PKTIT",
           "TIPO",
           "FOGLIO",
           "PARTICELLA",
           "SUB",
           "DATA_INIZIO",
           "DENOMINAZIONE",
           "FOGLIO1",
           "PARTICELLA1",
           "SUB1",
           "DATA_INIZIO1",
           "DENOMINAZIONE1",
           "COD_FISC",
           "TP_SOG"
      FROM (WITH
                COMEDOVREBBERO
                AS
                    (--
                     SELECT TRIM (a.cod_diritto)
                                AS cod_diritto,
                            TRIM (TO_CHAR (B.FOGLIO, '0000'))
                                AS FOGLIO1,
                            LPAD (B.MAPPALE, 5, '0')
                                AS PARTICELLA1,
                            (CASE WHEN B.SUB IS NULL THEN ' ' ELSE B.SUB END)
                                AS SUB1,
                            TO_DATE (a.DATA_EFFIC_INI, 'YYYYMMDD')
                                AS DATA_INIZIO1,
                            TRIM (TRIM (COGNOME) || ' ' || TRIM (NOME))
                                AS DENOMINAZIONE1,
                            C.COD_FISC,
                            C.TP_SOG
                       FROM LOAD_CAT_TIT  a,
                            (  SELECT foglio,
                                      mappale,
                                      sub,
                                      id_imm
                                 FROM load_cat_par
                             GROUP BY foglio,
                                      mappale,
                                      sub,
                                      id_imm) b,
                            load_cat_sog  c
                      WHERE     a.id_imm = b.id_imm
                            AND a.tp_imm = 'T'
                            AND a.ID_SOG = C.ID_SOG
                            AND a.stato_siti IS NULL--
                                                    ),
                --come sono
                COMESONO
                AS
                    (--
                     SELECT PKTIT,
                            tipo,
                            cod_diritto,
                            TRIM (TO_CHAR (FOGLIO, '0000'))     AS FOGLIO,
                            PARTICELLA,
                            SUB,
                            DATA_INIZIO,
                            DENOMINAZIONE
                       FROM (SELECT a.PKID_CONS     AS PKTIT,
                                    'CONS'          AS tipo,
                                    '10'            AS cod_diritto,
                                    a.FOGLIO,
                                    a.PARTICELLA,
                                    a.SUB,
                                    a.DATA_FINE,
                                    a.DATA_INIZIO,
                                    B.DENOMINAZIONE
                               FROM cons_cons_tab a, anag_soggetti b
                              WHERE a.PK_CUAA = B.COD_SOGGETTO
                             UNION
                             SELECT a.PKID_UFFR               AS PKTIT,
                                    'UFRE'                    AS tipo,
                                    TRIM (tipo_documento)     AS cod_diritto,
                                    a.FOGLIO,
                                    a.PARTICELLA,
                                    a.SUB,
                                    a.DATA_FINE,
                                    a.DATA_INIZIO,
                                    B.DENOMINAZIONE
                               FROM CONS_UFRE_TAB a, ANAG_SOGGETTI B
                              WHERE a.PK_CUAA = B.COD_SOGGETTO)--
                                                               )
            SELECT "PKTIT",
                   "TIPO",
                   "FOGLIO",
                   "PARTICELLA",
                   "SUB",
                   "DATA_INIZIO",
                   "DENOMINAZIONE",
                   "FOGLIO1",
                   "PARTICELLA1",
                   "SUB1",
                   "DATA_INIZIO1",
                   "DENOMINAZIONE1",
                   "COD_FISC",
                   "TP_SOG"
              FROM (SELECT cs.*, cd.*
                      FROM COMESONO CS, COMEDOVREBBERO CD
                     WHERE     CS.COD_DIRITTO = CD.COD_DIRITTO(+)
                           AND CS.FOGLIO = CD.FOGLIO1(+)
                           AND CS.PARTICELLA = CD.PARTICELLA1(+)
                           AND CS.SUB = CD.SUB1(+)
                           AND CS.DATA_INIZIO = CD.DATA_INIZIO1(+)
                           AND CS.DENOMINAZIONE = CD.DENOMINAZIONE1(+)
                    UNION
                    SELECT cs.*, cd.*
                      FROM COMESONO CS, COMEDOVREBBERO CD
                     WHERE     CS.COD_DIRITTO(+) = CD.COD_DIRITTO
                           AND CS.FOGLIO(+) = CD.FOGLIO1
                           AND CS.PARTICELLA(+) = CD.PARTICELLA1
                           AND CS.SUB(+) = CD.SUB1
                           AND CS.DATA_INIZIO(+) = CD.DATA_INIZIO1
                           AND CS.DENOMINAZIONE(+) = CD.DENOMINAZIONE1)
             WHERE (FOGLIO IS NULL OR FOGLIO1 IS NULL));


