/* Formatted on 18/07/2022 12:22:58 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CHK_LOAD_TITOLI_UIU
(
    PKTIT,
    TIPO,
    FOGLIO,
    PARTICELLA,
    SUB,
    DATA_INIZIO,
    DENOMINAZIONE,
    FOGLIO1,
    PARTICELLA1,
    SUB1,
    DATA_INIZIO1,
    DENOMINAZIONE1,
    COD_FISC,
