           "TIPO",
           "FOGLIO",
           "PARTICELLA",
           "SUB",
           "DATA_INIZIO",
           "DENOMINAZIONE",
           "FOGLIO1",
           "PARTICELLA1",
           "SUB1",
           "DATA_INIZIO1",
           "DENOMINAZIONE1",
           "COD_FISC",
           "TP_SOG"
      FROM (WITH
                COMEDOVREBBERO
                AS
                    (--
                     SELECT TRIM (a.cod_diritto)
                                AS cod_diritto,
                            B.FOGLIO
                                AS FOGLIO1,
                            B.MAPPALE
                                AS PARTICELLA1,
                            (CASE WHEN B.SUB = ' ' THEN '0000' ELSE B.SUB END)
                                AS SUB1,
                            TO_DATE (a.DATA_EFFIC_INI, 'YYYYMMDD')
                                AS DATA_INIZIO1,
                            TRIM (TRIM (COGNOME) || ' ' || TRIM (NOME))
                                AS DENOMINAZIONE1,
                            C.COD_FISC,
                            C.TP_SOG
                       FROM LOAD_CAT_TIT  a,
                            (  SELECT foglio,
                                      mappale,
                                      sub,
                                      id_imm
                                 FROM load_cat_uiu_id
                                WHERE graffato = 'N'
                             GROUP BY foglio,
                                      mappale,
                                      sub,
                                      id_imm) b,
                            load_cat_sog  c
                      WHERE     a.id_imm = b.id_imm
                            AND a.tp_imm = 'F'
                            AND a.ID_SOG = C.ID_SOG
                            AND a.stato_siti IS NULL--
                                                    ),
                --come sono
                COMESONO
                AS
                    (--
                     SELECT PKTIT,
                            tipo,
                            cod_diritto,
                            TRIM (TO_CHAR (FOGLIO, '0000'))     AS FOGLIO,
                            PARTICELLA,
                            TRIM (TO_CHAR (UNIMM, '0000'))      AS SUB,
                            DATA_INIZIO,
                            DENOMINAZIONE
                       FROM (SELECT a.PKID_CSUI     AS PKTIT,
                                    'CSUI'          AS tipo,
                                    '10'            AS cod_diritto,
                                    a.FOGLIO,
                                    a.PARTICELLA,
                                    a.SUB,
                                    a.UNIMM,
                                    a.DATA_FINE,
                                    a.DATA_INIZIO,
                                    B.DENOMINAZIONE
                               FROM cons_csui_tab a, anag_soggetti b
                              WHERE a.PK_CUAA = B.COD_SOGGETTO
                             UNION
                             SELECT a.PKID_URUI               AS PKTIT,
                                    'URUI'                    AS tipo,
                                    TRIM (tipo_documento)     AS cod_diritto,
                                    a.FOGLIO,
                                    a.PARTICELLA,
                                    a.SUB,
                                    a.UNIMM,
                                    a.DATA_FINE,
                                    a.DATA_INIZIO,
                                    B.DENOMINAZIONE
                               FROM CONS_URUI_TAB a, ANAG_SOGGETTI B
                              WHERE a.PK_CUAA = B.COD_SOGGETTO)--
                                                               )
            SELECT "PKTIT",
                   "TIPO",
                   "FOGLIO",
                   "PARTICELLA",
                   "SUB",
                   "DATA_INIZIO",
                   "DENOMINAZIONE",
                   "FOGLIO1",
                   "PARTICELLA1",
                   "SUB1",
                   "DATA_INIZIO1",
                   "DENOMINAZIONE1",
                   "COD_FISC",
                   "TP_SOG"
              FROM (SELECT cs.*, cd.*
                      FROM COMESONO CS, COMEDOVREBBERO CD
                     WHERE     CS.COD_DIRITTO = CD.COD_DIRITTO(+)
                           AND CS.FOGLIO = CD.FOGLIO1(+)
                           AND CS.PARTICELLA = CD.PARTICELLA1(+)
                           AND CS.SUB = CD.SUB1(+)
                           AND CS.DATA_INIZIO = CD.DATA_INIZIO1(+)
                           AND CS.DENOMINAZIONE = CD.DENOMINAZIONE1(+)
                    UNION
                    SELECT cs.*, cd.*
                      FROM COMESONO CS, COMEDOVREBBERO CD
                     WHERE     CS.COD_DIRITTO(+) = CD.COD_DIRITTO
                           AND CS.FOGLIO(+) = CD.FOGLIO1
                           AND CS.PARTICELLA(+) = CD.PARTICELLA1
                           AND CS.SUB(+) = CD.SUB1
                           AND CS.DATA_INIZIO(+) = CD.DATA_INIZIO1
                           AND CS.DENOMINAZIONE(+) = CD.DENOMINAZIONE1)
             WHERE (FOGLIO IS NULL OR FOGLIO1 IS NULL));


DROP VIEW SITI_H501.CONSISTENZA_VIW;

/* Formatted on 18/07/2022 12:22:58 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONSISTENZA_VIW
(
    DRIF,
    COD_NAZIONALE,
    FOGLIO,
    PARTICELLA,
    SUB,
    DATA_INIZIO,
    DATA_FINE,
    CUAA,
    TIPO_TITOLO,
    QUOTA_CONDUZIONE,
    QUOTA_LIMITE,
    UTENTE
)
BEQUEATH DEFINER
AS
    SELECT b.data_inizio     AS drif,
           a.cod_nazionale,
           a.foglio,
           a.particella,
           a.sub,
           a.data_inizio,
           a.data_fine,
           c.cuaa,
           a.TIPO_TITOLO,
           PERC_POSS         AS QUOTA_CONDUZIONE,
           100               AS QUOTA_LIMITE,
           a.utente
      FROM cons_cons_tab  A,
           (  SELECT cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio
                FROM cons_cons_tab
               WHERE PK_CUAA < 999999999
            GROUP BY cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio
            UNION
              SELECT cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio
                FROM cons_ufre_tab
               WHERE PK_CUAA < 999999999
            GROUP BY cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio) B,
           cons_azie_tab  C
     WHERE     a.cod_nazionale = b.cod_nazionale
           AND a.foglio = b.foglio
           AND a.particella = b.particella
           AND a.sub = b.sub
           AND a.data_inizio <= b.data_inizio
           AND a.data_fine >= b.data_inizio
           AND a.PK_CUAA < 999999999
           AND a.pk_cuaa = c.PK_CUAA
           AND c.data_inizio <= b.data_inizio
           AND c.data_fine >= b.data_inizio
    UNION
    SELECT b.data_inizio     AS data_rife,
           a.cod_nazionale,
           a.foglio,
           a.particella,
           a.sub,
           a.data_inizio,
           a.data_fine,
           c.cuaa,
           a.TIPO_TITOLO,
           PERC_POSS         AS QUOTA_CONDUZIONE,
           100               AS QUOTA_LIMITE,
           a.utente
      FROM cons_ufre_tab  A,
           (  SELECT cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio
                FROM cons_cons_tab
               WHERE PK_CUAA < 999999999
            GROUP BY cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio
            UNION
              SELECT cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio
                FROM cons_ufre_tab
               WHERE PK_CUAA < 999999999
            GROUP BY cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     data_inizio) B,
           cons_azie_tab  C
     WHERE     a.cod_nazionale = b.cod_nazionale
           AND a.foglio = b.foglio
           AND a.particella = b.particella
           AND a.sub = b.sub
           AND a.data_inizio <= b.data_inizio
           AND a.data_fine >= b.data_inizio
           AND a.PK_CUAA < 999999999
           AND a.pk_cuaa = c.PK_CUAA
           AND c.data_inizio <= b.data_inizio
           AND c.data_fine >= b.data_inizio;


