                    "AM_ISTATB",
                    "IMP_REG",
                    "TIPO_UT",
                    "CANONE_INI",
                    "CANONE_FIN",
                    "ANNI_DER",
                    "ADD_MORA",
                    "DATA_DISD",
                    "SOGG_IVA",
                    "FATTURA",
                    "N_ANNI_ISTAT",
                    "POSTICIPATO",
                    "ESCLUDI_RIC",
                    "ESCLUDI_BOL",
                    "NOTE_CON",
                    "COM_INQUI",
                    "CESSAZIONE",
                    "RLOCK",
                    "ACCR_INT_DP",
                    "COD_TRIBUTO",
                    "NATURA_DP",
                    "SCADENZA_DP",
                    "DATA_REST_DP",
                    "RESCISSIONE_INQ",
                    "N_MESI_RESCIS",
                    "MESE_ISTAT_RIC",
                    "LEGALE",
                    "IMPOSTA_DEP",
                    "SPESE_DEP1",
                    "COD_TRIB_DEP1",
                    "SPESE_DEP2",
                    "COD_TRIB_DEP2",
                    "TIPO_DEP",
                    "DATA_STIP",
                    "ESCLUDI_CONG",
                    "CODICE_GEMELLO",
                    "VERSANTE_IMPOSTA",
                    "COD_UTE",
                    "FR_DENUNCIA",
                    "TIPO_INT_DP",
                    "OGG_LOCAZIONE",
                    "RESCISSIONE_DAL",
                    "PARENT_CONTRATT_ID"
      FROM (SELECT CAST (a.pkid_atto AS VARCHAR2 (10))
                       AS codice,
                   d.pkid_doc,
                   ltc.COD_TIPO_CONTR
                       AS cod_tcont,
                   de.sys_loc_dt_decorrenza
                       AS data_cont,
                   de.SYS_LOC_COD_PERIODO
                       AS periodo,
                   de.SYS_LOC_COD_RISCOS
                       AS codrisc,
                   ltc.cod_calcolo_canone
                       AS codcalc,
                   ltc.costo_base,
                   ltc.costo_up,
                   ltc.sup_conv,
                   CAST (ltc.anno_vetus AS VARCHAR2 (4))
                       AS anno_vetus,
                   ltc.coef_vetus,
                   ltc.CAN_NOISTA,
                   de.sys_loc_cod_calcolo
                       AS CAN_APPLIC,
                   de.sys_loc_canone_pre_pa
                       AS CAN_PRE_PA,
                   de.sys_loc_dt_pagam_ini
                       AS DATA_P_INI,
                   de.sys_loc_cauzione
                       AS CAUZIONE,
                   de.sys_loc_dt_in_cauzione
                       AS DATA_D_CAU,
                   ltc.istat_pct_increm
                       AS PERC_INCR,
                   ltc.AGG_ISTAT,
                   ltc.istat_ipb
                       AS ISTAT_IPB,
                   ltc.istat_ar
                       AS ISTAT_AR,
                   de.sys_loc_imp_reg_anno_pr
                       AS ANNOREG,
                   SUBSTR ('00' || de.sys_loc_imp_reg_mese_pr, -2)
                       AS MESEREG,
                   de.sys_loc_imp_reg_num_reg
                       AS NUM_REG,
                   de.sys_loc_imp_reg_serie_reg
                       AS SERIE_REG,
                   de.sys_loc_imposta_reg
                       AS TIPO_REG,
                   de.sys_loc_imposta_reg_freq
                       AS FREQ_REG,
                   NULL
                       AS DATA_US_REG,
                   de.sys_loc_imp_reg_cod_uff
                       AS UFFI_REG,
                   ltc.dt_ult_agg_istat
                       AS DATA_ISTAT,
                      SUBSTR ('0000' || ltc.istat_base_anno, -4)
                   || SUBSTR ('00' || ltc.istat_base_mese, -2)
                       AS AM_ISTATB,
                   ltc.IMP_REG,
                   ltc.TIPO_UT
                       AS TIPO_UT,
                   de.sys_loc_canone_iniziale
                       AS CANONE_INI,
                   de.sys_loc_canone_finale
                       AS CANONE_FIN,
                   ltc.ANNI_DER,
                   ltc.fl_interessi_mora
                       AS ADD_MORA,
                   NULL
                       AS DATA_DISD,
                   ltc.fl_soggetto_iva
                       AS SOGG_IVA,
                   CASE
                       WHEN ltc.fl_fatt_emissione = 'N' THEN 'N'
                       WHEN ltc.FL_FATT_POSTICIPATA = 'N' THEN '1'
                       ELSE '2'
                   END
                       AS FATTURA,
                   ltc.istat_nr_anni_agg
                       AS N_ANNI_ISTAT,
                   de.sys_loc_fl_rata_post
                       AS POSTICIPATO,
                   CASE
                       WHEN ltc.fl_escludi_rical_aut = 'S' THEN 'S'
                       WHEN ltc.fl_escludi_agg_canone = 'S' THEN 'C'
                       ELSE 'N'
                   END
                       AS ESCLUDI_RIC,
                   ltc.fl_escludi_fatturazione
                       AS ESCLUDI_BOL,
                   de.sys_loc_note_contratto
                       AS NOTE_CON,
                   ltc.fl_comunica_agg_canone
                       AS COM_INQUI,
                   DECODE (de.sys_loc_dt_fine,
                           TO_DATE ('99991231', 'yyyymmdd'), TO_DATE (NULL),
                           de.sys_loc_dt_fine)
                       AS CESSAZIONE,
                   NULL
                       AS RLOCK,
                   de.sys_loc_fl_int_cauzione
                       AS ACCR_INT_DP,
                   NULL
                       AS COD_TRIBUTO,
                   de.sys_loc_cauzione_natura
                       AS NATURA_DP,
                   de.sys_loc_dt_scad_cauzione
                       AS SCADENZA_DP,
                   de.sys_loc_dt_out_cauzione
                       AS DATA_REST_DP,
                   ltc.fl_rescissione
                       AS RESCISSIONE_INQ,
                   ltc.N_MESI_RESCISSIONE
                       AS N_MESI_RESCIS,
                   de.sys_loc_scad_rin_istat
                       AS MESE_ISTAT_RIC,
                   ltc.fl_atto_al_legale
                       AS LEGALE,
                   de.sys_loc_fl_imp_reg_cauz
                       AS IMPOSTA_DEP,
                   de.sys_loc_spese_dep1
                       AS SPESE_DEP1,
                   de.sys_loc_cod_trib_dep1
                       AS COD_TRIB_DEP1,
                   de.sys_loc_spese_dep2
                       AS SPESE_DEP2,
                   de.sys_loc_cod_trib_dep2
                       AS COD_TRIB_DEP2,
                   de.sys_loc_cauzione_tipo
                       AS TIPO_DEP,
                   de.sys_loc_dt_stipula
                       AS DATA_STIP,
                   de.sys_loc_escludi_cong
                       AS ESCLUDI_CONG,
                   de.sys_loc_codice_gemello
                       AS CODICE_GEMELLO,
                   de.sys_loc_versante_imposta
                       AS VERSANTE_IMPOSTA,
                   de.sys_loc_cod_ute
                       AS COD_UTE,
                   de.sys_loc_fr_denuncia
                       AS FR_DENUNCIA,
                   DECODE (de.sys_loc_tp_int_cauzione,
                           NULL, '0',
                           de.sys_loc_tp_int_cauzione)
                       AS TIPO_INT_DP,
                   ltc.oggetto_locazione
                       AS OGG_LOCAZIONE,
                   ltc.data_rescissione_dal
                       AS RESCISSIONE_DAL,
                   NULL
                       AS PARENT_CONTRATT_ID --, de.SYS_LOC_DT_SCAD_CONT as SCAD_CONT
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   cons_ufre_tab                 t,
                   patri_loc_tipo_contr          ltc,
                   cons_cons_tab                 t2,
                   patri_cespiti_part            ce,
                   patri_cespiti                 c
             WHERE     a.FKID_TIPO_ATTO = -22
                   AND ad.FKID_ATTO = a.pkid_atto
                   AND d.PKID_DOC = ad.FKID_DOC
                   AND d.FKID_TIPO_DOC = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND t.ATTO_INI = a.PKID_ATTO
                   AND t2.cod_nazionale = t.cod_nazionale
                   AND t2.foglio = t.foglio
                   AND t2.particella = t.particella
                   AND t2.sub = t.sub
                   AND t2.data_inizio <=
                       NVL (de.sys_loc_dt_fine,
                            TO_DATE ('31129999', 'ddmmyyyy'))
                   AND t2.data_fine >= de.sys_loc_dt_decorrenza
                   AND ce.pk_tit = t2.pkid_cons
                   AND ce.tipo_titolo = t2.tipo_titolo
                   AND c.pk_cespite = ce.fk_cespite
                   AND ltc.FKID_DOC(+) = d.PKID_DOC
            UNION
            SELECT CAST (a.pkid_atto AS VARCHAR2 (10))
                       AS codice,
                   d.pkid_doc,
                   ltc.COD_TIPO_CONTR
                       AS cod_tcont,
                   de.sys_loc_dt_decorrenza
                       AS data_cont,
                   de.SYS_LOC_COD_PERIODO
                       AS periodo,
                   de.SYS_LOC_COD_RISCOS
                       AS codrisc,
                   ltc.cod_calcolo_canone
                       AS codcalc,
                   ltc.costo_base,
                   ltc.costo_up,
                   ltc.sup_conv,
                   CAST (ltc.anno_vetus AS VARCHAR2 (4))
                       AS anno_vetus,
                   ltc.coef_vetus,
                   ltc.CAN_NOISTA,
                   de.sys_loc_cod_calcolo
                       AS CAN_APPLIC,
                   de.sys_loc_canone_pre_pa
                       AS CAN_PRE_PA,
                   de.sys_loc_dt_pagam_ini
                       AS DATA_P_INI,
                   de.sys_loc_cauzione
                       AS CAUZIONE,
                   de.sys_loc_dt_in_cauzione
                       AS DATA_D_CAU,
                   ltc.istat_pct_increm
                       AS PERC_INCR,
                   ltc.AGG_ISTAT,
                   ltc.istat_ipb
                       AS ISTAT_IPB,
                   ltc.istat_ar
                       AS ISTAT_AR,
                   de.sys_loc_imp_reg_anno_pr
                       AS ANNOREG,
                   SUBSTR ('00' || de.sys_loc_imp_reg_mese_pr, -2)
                       AS MESEREG,
                   de.sys_loc_imp_reg_num_reg
                       AS NUM_REG,
                   de.sys_loc_imp_reg_serie_reg
                       AS SERIE_REG,
                   de.sys_loc_imposta_reg
                       AS TIPO_REG,
                   de.sys_loc_imposta_reg_freq
                       AS FREQ_REG,
                   NULL
                       AS DATA_US_REG,
                   de.sys_loc_imp_reg_cod_uff
                       AS UFFI_REG,
                   ltc.dt_ult_agg_istat
                       AS DATA_ISTAT,
                      SUBSTR ('0000' || ltc.istat_base_anno, -4)
                   || SUBSTR ('00' || ltc.istat_base_mese, -2)
                       AS AM_ISTATB,
                   ltc.IMP_REG,
                   ltc.TIPO_UT
                       AS TIPO_UT,
                   de.sys_loc_canone_iniziale
                       AS CANONE_INI,
                   de.sys_loc_canone_finale
                       AS CANONE_FIN,
                   ltc.ANNI_DER,
                   ltc.fl_interessi_mora
                       AS ADD_MORA,
                   NULL
                       AS DATA_DISD,
                   ltc.fl_soggetto_iva
                       AS SOGG_IVA,
                   CASE
                       WHEN ltc.fl_fatt_emissione = 'N' THEN 'N'
                       WHEN ltc.FL_FATT_POSTICIPATA = 'N' THEN '1'
                       ELSE '2'
                   END
                       AS FATTURA,
                   ltc.istat_nr_anni_agg
                       AS N_ANNI_ISTAT,
                   de.sys_loc_fl_rata_post
                       AS POSTICIPATO,
                   CASE
                       WHEN ltc.fl_escludi_rical_aut = 'S' THEN 'S'
                       WHEN ltc.fl_escludi_agg_canone = 'S' THEN 'C'
                       ELSE 'N'
                   END
                       AS ESCLUDI_RIC,
                   ltc.fl_escludi_fatturazione
                       AS ESCLUDI_BOL,
                   de.sys_loc_note_contratto
                       AS NOTE_CON,
                   ltc.fl_comunica_agg_canone
                       AS COM_INQUI,
                   DECODE (de.sys_loc_dt_fine,
                           TO_DATE ('99991231', 'yyyymmdd'), TO_DATE (NULL),
                           de.sys_loc_dt_fine)
                       AS CESSAZIONE,
                   NULL
                       AS RLOCK,
                   de.sys_loc_fl_int_cauzione
                       AS ACCR_INT_DP,
                   NULL
                       AS COD_TRIBUTO,
                   de.sys_loc_cauzione_natura
                       AS NATURA_DP,
                   de.sys_loc_dt_scad_cauzione
                       AS SCADENZA_DP,
                   de.sys_loc_dt_out_cauzione
                       AS DATA_REST_DP,
                   ltc.fl_rescissione
                       AS RESCISSIONE_INQ,
                   ltc.N_MESI_RESCISSIONE
                       AS N_MESI_RESCIS,
                   de.sys_loc_scad_rin_istat
                       AS MESE_ISTAT_RIC,
                   ltc.fl_atto_al_legale
                       AS LEGALE,
                   de.sys_loc_fl_imp_reg_cauz
                       AS IMPOSTA_DEP,
                   de.sys_loc_spese_dep1
                       AS SPESE_DEP1,
                   de.sys_loc_cod_trib_dep1
                       AS COD_TRIB_DEP1,
                   de.sys_loc_spese_dep2
                       AS SPESE_DEP2,
                   de.sys_loc_cod_trib_dep2
                       AS COD_TRIB_DEP2,
                   de.sys_loc_cauzione_tipo
                       AS TIPO_DEP,
                   de.sys_loc_dt_stipula
                       AS DATA_STIP,
                   de.sys_loc_escludi_cong
                       AS ESCLUDI_CONG,
                   de.sys_loc_codice_gemello
                       AS CODICE_GEMELLO,
                   de.sys_loc_versante_imposta
                       AS VERSANTE_IMPOSTA,
                   de.sys_loc_cod_ute
                       AS COD_UTE,
                   de.sys_loc_fr_denuncia
                       AS FR_DENUNCIA,
                   DECODE (de.sys_loc_tp_int_cauzione,
                           NULL, '0',
                           de.sys_loc_tp_int_cauzione)
                       AS TIPO_INT_DP,
                   ltc.oggetto_locazione
                       AS OGG_LOCAZIONE,
                   ltc.data_rescissione_dal
                       AS RESCISSIONE_DAL,
                   NULL
                       AS PARENT_CONTRATT_ID --, de.SYS_LOC_DT_SCAD_CONT as SCAD_CONT
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   cons_urui_tab                 t,
                   patri_loc_tipo_contr          ltc,
                   cons_csui_tab                 t2,
                   patri_cespiti_uiu             ce,
                   patri_cespiti                 c
             WHERE     a.FKID_TIPO_ATTO = -22
                   AND ad.FKID_ATTO = a.pkid_atto
                   AND d.PKID_DOC = ad.FKID_DOC
                   AND d.FKID_TIPO_DOC = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND t.ATTO_INI = a.PKID_ATTO
                   AND t2.cod_nazionale = t.cod_nazionale
                   AND t2.foglio = t.foglio
                   AND t2.particella = t.particella
                   AND t2.sub = t.sub
                   AND t2.unimm = t.unimm
                   AND t2.data_inizio <=
                       NVL (de.sys_loc_dt_fine,
                            TO_DATE ('31129999', 'ddmmyyyy'))
                   AND t2.data_fine >= de.sys_loc_dt_decorrenza
                   AND ce.pk_tit = t2.pkid_csui
                   AND ce.tipo_titolo = t2.tipo_titolo
                   AND c.pk_cespite = ce.fk_cespite
                   AND ltc.FKID_DOC(+) = d.PKID_DOC
            UNION
            -- SUBLOCAZIONI
            SELECT CAST (a.pkid_atto AS VARCHAR2 (10))
                       AS codice,
                   d.pkid_doc,
                   ltc.cod_tipo_contr
                       AS cod_tcont,
                   de.sys_loc_dt_decorrenza
                       AS data_cont,
                   de.sys_loc_cod_periodo
                       AS periodo,
                   de.sys_loc_cod_riscos
                       AS codrisc,
                   ltc.cod_calcolo_canone
                       AS codcalc,
                   ltc.costo_base,
                   ltc.costo_up,
                   ltc.sup_conv,
                   CAST (ltc.anno_vetus AS VARCHAR2 (4))
                       AS anno_vetus,
                   ltc.coef_vetus,
                   ltc.can_noista,
                   de.sys_loc_cod_calcolo
                       AS can_applic,
                   de.sys_loc_canone_pre_pa
                       AS can_pre_pa,
                   de.sys_loc_dt_pagam_ini
                       AS data_p_ini,
                   de.sys_loc_cauzione
                       AS cauzione,
                   de.sys_loc_dt_in_cauzione
                       AS data_d_cau,
                   ltc.istat_pct_increm
                       AS perc_incr,
                   ltc.agg_istat,
                   ltc.istat_ipb
                       AS istat_ipb,
                   ltc.istat_ar
                       AS istat_ar,
                   de.sys_loc_imp_reg_anno_pr
                       AS annoreg,
                   SUBSTR ('00' || de.sys_loc_imp_reg_mese_pr, -2)
                       AS mesereg,
                   de.sys_loc_imp_reg_num_reg
                       AS num_reg,
                   de.sys_loc_imp_reg_serie_reg
                       AS serie_reg,
                   de.sys_loc_imposta_reg
                       AS tipo_reg,
                   de.sys_loc_imposta_reg_freq
                       AS freq_reg,
                   NULL
                       AS data_us_reg,
                   de.sys_loc_imp_reg_cod_uff
                       AS uffi_reg,
                   ltc.dt_ult_agg_istat
                       AS data_istat,
                      SUBSTR ('0000' || ltc.istat_base_anno, -4)
                   || SUBSTR ('00' || ltc.istat_base_mese, -2)
                       AS am_istatb,
                   ltc.imp_reg,
                   ltc.tipo_ut
                       AS tipo_ut,
                   de.sys_loc_canone_iniziale
                       AS canone_ini,
                   de.sys_loc_canone_finale
                       AS canone_fin,
                   ltc.anni_der,
                   ltc.fl_interessi_mora
                       AS add_mora,
                   NULL
                       AS data_disd,
                   ltc.fl_soggetto_iva
                       AS sogg_iva,
                   CASE
                       WHEN ltc.fl_fatt_emissione = 'N' THEN 'N'
                       WHEN ltc.fl_fatt_posticipata = 'N' THEN '1'
                       ELSE '2'
                   END
                       AS fattura,
                   ltc.istat_nr_anni_agg
                       AS n_anni_istat,
                   de.sys_loc_fl_rata_post
                       AS posticipato,
                   CASE
                       WHEN ltc.fl_escludi_rical_aut = 'S' THEN 'S'
                       WHEN ltc.fl_escludi_agg_canone = 'S' THEN 'C'
                       ELSE 'N'
                   END
                       AS escludi_ric,
                   ltc.fl_escludi_fatturazione
                       AS escludi_bol,
                   de.sys_loc_note_contratto
                       AS note_con,
                   ltc.fl_comunica_agg_canone
                       AS com_inqui,
                   DECODE (de.sys_loc_dt_fine,
                           TO_DATE ('99991231', 'yyyymmdd'), TO_DATE (NULL),
                           de.sys_loc_dt_fine)
                       AS CESSAZIONE,
                   NULL
                       AS rlock,
                   de.sys_loc_fl_int_cauzione
                       AS accr_int_dp,
                   NULL
                       AS cod_tributo,
                   de.sys_loc_cauzione_natura
                       AS natura_dp,
                   de.sys_loc_dt_scad_cauzione
                       AS scadenza_dp,
                   de.sys_loc_dt_out_cauzione
                       AS data_rest_dp,
                   ltc.fl_rescissione
                       AS rescissione_inq,
                   ltc.n_mesi_rescissione
                       AS n_mesi_rescis,
                   de.sys_loc_scad_rin_istat
                       AS mese_istat_ric,
                   ltc.fl_atto_al_legale
                       AS legale,
                   de.sys_loc_fl_imp_reg_cauz
                       AS imposta_dep,
                   de.sys_loc_spese_dep1
                       AS spese_dep1,
                   de.sys_loc_cod_trib_dep1
                       AS cod_trib_dep1,
                   de.sys_loc_spese_dep2
                       AS spese_dep2,
                   de.sys_loc_cod_trib_dep2
                       AS cod_trib_dep2,
                   de.sys_loc_cauzione_tipo
                       AS tipo_dep,
                   de.sys_loc_dt_stipula
                       AS data_stip,
                   de.sys_loc_escludi_cong
                       AS escludi_cong,
                   de.sys_loc_codice_gemello
                       AS codice_gemello,
                   de.sys_loc_versante_imposta
                       AS versante_imposta,
                   de.sys_loc_cod_ute
                       AS cod_ute,
                   de.sys_loc_fr_denuncia
                       AS fr_denuncia,
                   DECODE (de.sys_loc_tp_int_cauzione,
                           NULL, '0',
                           de.sys_loc_tp_int_cauzione)
                       AS tipo_int_dp,
                   ltc.oggetto_locazione
                       AS ogg_locazione,
                   ltc.data_rescissione_dal
                       AS rescissione_dal,
                   cst.fkid_atto
                       AS parent_contratt_id --, de.SYS_LOC_DT_SCAD_CONT as SCAD_CONT
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   cons_subloc_tab               cst,
                   patri_cespiti_part            ce,
                   patri_cespiti                 c,
                   patri_loc_tipo_contr          ltc,
                   (SELECT DISTINCT id_particella,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub
                      FROM sititrkc) st,
                   (SELECT DISTINCT pkid_uffr     AS pkid_tit,
                                    tipo_titolo,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    NULL          AS unimm,
                                    atto_ini,
                                    data_inizio,
                                    data_fine
                      FROM cons_ufre_tab) cond
             WHERE     a.fkid_tipo_atto = -22
                   AND ad.fkid_atto = a.pkid_atto
                   AND d.pkid_doc = ad.fkid_doc
                   AND d.fkid_tipo_doc = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND cst.atto_inizio = a.pkid_atto
                   AND cst.obj_type = 'P'
                   AND cst.fkid_obj = st.id_particella
                   AND st.cod_nazionale = cond.cod_nazionale
                   AND st.foglio = cond.foglio
                   AND st.particella = cond.particella
                   AND st.sub = cond.sub
                   AND cst.fkid_atto = cond.atto_ini
                   AND cst.data_fine <= cond.data_fine
                   AND cond.pkid_tit = ce.pk_tit
                   AND cond.tipo_titolo = ce.tipo_titolo
                   AND ce.fk_cespite = c.pk_cespite
                   AND ltc.fkid_doc(+) = d.pkid_doc
            UNION
            SELECT CAST (a.pkid_atto AS VARCHAR2 (10))
                       AS codice,
                   d.pkid_doc,
                   ltc.cod_tipo_contr
                       AS cod_tcont,
                   de.sys_loc_dt_decorrenza
                       AS data_cont,
                   de.sys_loc_cod_periodo
                       AS periodo,
                   de.sys_loc_cod_riscos
                       AS codrisc,
                   ltc.cod_calcolo_canone
                       AS codcalc,
                   ltc.costo_base,
                   ltc.costo_up,
                   ltc.sup_conv,
                   CAST (ltc.anno_vetus AS VARCHAR2 (4))
                       AS anno_vetus,
                   ltc.coef_vetus,
                   ltc.can_noista,
                   de.sys_loc_cod_calcolo
                       AS can_applic,
                   de.sys_loc_canone_pre_pa
                       AS can_pre_pa,
                   de.sys_loc_dt_pagam_ini
                       AS data_p_ini,
                   de.sys_loc_cauzione
                       AS cauzione,
                   de.sys_loc_dt_in_cauzione
                       AS data_d_cau,
                   ltc.istat_pct_increm
                       AS perc_incr,
                   ltc.agg_istat,
                   ltc.istat_ipb
                       AS istat_ipb,
                   ltc.istat_ar
                       AS istat_ar,
                   de.sys_loc_imp_reg_anno_pr
                       AS annoreg,
                   SUBSTR ('00' || de.sys_loc_imp_reg_mese_pr, -2)
                       AS mesereg,
                   de.sys_loc_imp_reg_num_reg
                       AS num_reg,
                   de.sys_loc_imp_reg_serie_reg
                       AS serie_reg,
                   de.sys_loc_imposta_reg
                       AS tipo_reg,
                   de.sys_loc_imposta_reg_freq
                       AS freq_reg,
                   NULL
                       AS data_us_reg,
                   de.sys_loc_imp_reg_cod_uff
                       AS uffi_reg,
                   ltc.dt_ult_agg_istat
                       AS data_istat,
                      SUBSTR ('0000' || ltc.istat_base_anno, -4)
                   || SUBSTR ('00' || ltc.istat_base_mese, -2)
                       AS am_istatb,
                   ltc.imp_reg,
                   ltc.tipo_ut
                       AS tipo_ut,
                   de.sys_loc_canone_iniziale
                       AS canone_ini,
                   de.sys_loc_canone_finale
                       AS canone_fin,
                   ltc.anni_der,
                   ltc.fl_interessi_mora
                       AS add_mora,
                   NULL
                       AS data_disd,
                   ltc.fl_soggetto_iva
                       AS sogg_iva,
                   CASE
                       WHEN ltc.fl_fatt_emissione = 'N' THEN 'N'
                       WHEN ltc.fl_fatt_posticipata = 'N' THEN '1'
                       ELSE '2'
                   END
                       AS fattura,
                   ltc.istat_nr_anni_agg
                       AS n_anni_istat,
                   de.sys_loc_fl_rata_post
                       AS posticipato,
                   CASE
                       WHEN ltc.fl_escludi_rical_aut = 'S' THEN 'S'
                       WHEN ltc.fl_escludi_agg_canone = 'S' THEN 'C'
                       ELSE 'N'
                   END
                       AS escludi_ric,
                   ltc.fl_escludi_fatturazione
                       AS escludi_bol,
                   de.sys_loc_note_contratto
                       AS note_con,
                   ltc.fl_comunica_agg_canone
                       AS com_inqui,
                   DECODE (de.sys_loc_dt_fine,
                           TO_DATE ('99991231', 'yyyymmdd'), TO_DATE (NULL),
                           de.sys_loc_dt_fine)
                       AS CESSAZIONE,
                   NULL
                       AS rlock,
                   de.sys_loc_fl_int_cauzione
                       AS accr_int_dp,
                   NULL
                       AS cod_tributo,
                   de.sys_loc_cauzione_natura
                       AS natura_dp,
                   de.sys_loc_dt_scad_cauzione
                       AS scadenza_dp,
                   de.sys_loc_dt_out_cauzione
                       AS data_rest_dp,
                   ltc.fl_rescissione
                       AS rescissione_inq,
                   ltc.n_mesi_rescissione
                       AS n_mesi_rescis,
                   de.sys_loc_scad_rin_istat
                       AS mese_istat_ric,
                   ltc.fl_atto_al_legale
                       AS legale,
                   de.sys_loc_fl_imp_reg_cauz
                       AS imposta_dep,
                   de.sys_loc_spese_dep1
                       AS spese_dep1,
                   de.sys_loc_cod_trib_dep1
                       AS cod_trib_dep1,
                   de.sys_loc_spese_dep2
                       AS spese_dep2,
                   de.sys_loc_cod_trib_dep2
                       AS cod_trib_dep2,
                   de.sys_loc_cauzione_tipo
                       AS tipo_dep,
                   de.sys_loc_dt_stipula
                       AS data_stip,
                   de.sys_loc_escludi_cong
                       AS escludi_cong,
                   de.sys_loc_codice_gemello
                       AS codice_gemello,
                   de.sys_loc_versante_imposta
                       AS versante_imposta,
                   de.sys_loc_cod_ute
                       AS cod_ute,
                   de.sys_loc_fr_denuncia
                       AS fr_denuncia,
                   DECODE (de.sys_loc_tp_int_cauzione,
                           NULL, '0',
                           de.sys_loc_tp_int_cauzione)
                       AS tipo_int_dp,
                   ltc.oggetto_locazione
                       AS ogg_locazione,
                   ltc.data_rescissione_dal
                       AS rescissione_dal,
                   st.fkid_atto
                       AS parent_contratt_id --, de.SYS_LOC_DT_SCAD_CONT as SCAD_CONT
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   patri_cespiti_uiu             ce,
                   patri_cespiti                 c,
                   patri_loc_tipo_contr          ltc,
                   (SELECT DISTINCT st.cod_nazionale,
                                    st.foglio,
                                    st.particella,
                                    st.sub,
                                    st.unimm,
                                    cst.tipo_titolo,
                                    cst.fkid_atto,
                                    cst.atto_inizio,
                                    cst.atto_fine,
                                    cst.data_inizio,
                                    cst.data_fine
                      FROM cons_subloc_tab  cst,
                           (SELECT DISTINCT id_cata_uiu,
                                            cod_nazionale,
                                            foglio,
                                            particella,
                                            sub,
                                            unimm
                              FROM sitiuiu) st
                     WHERE     cst.obj_type = 'U'
                           AND cst.fkid_obj = st.id_cata_uiu
                    UNION
                    SELECT DISTINCT st.cod_nazionale,
                                    st.foglio,
                                    st.particella,
                                    st.sub,
                                    st.unimm,
                                    cst.tipo_titolo,
                                    cst.fkid_atto,
                                    cst.atto_inizio,
                                    cst.atto_fine,
                                    cst.data_inizio,
                                    cst.data_fine
                      FROM cons_subloc_tab  cst,
                           (SELECT DISTINCT id_cata_vano,
                                            cod_nazionale,
                                            foglio,
                                            particella,
                                            sub,
                                            unimm
                              FROM sitiedi_vani) st
                     WHERE     cst.obj_type = 'V'
                           AND cst.fkid_obj = st.id_cata_vano) st,
                   (SELECT DISTINCT pkid_urui     AS pkid_tit,
                                    tipo_titolo,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    unimm,
                                    atto_ini,
                                    data_inizio,
                                    data_fine
                      FROM cons_urui_tab) cond
             WHERE     a.fkid_tipo_atto = -22
                   AND ad.fkid_atto = a.pkid_atto
                   AND d.pkid_doc = ad.fkid_doc
                   AND d.fkid_tipo_doc = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND st.atto_inizio = a.pkid_atto
                   AND st.cod_nazionale = cond.cod_nazionale
                   AND st.foglio = cond.foglio
                   AND st.particella = cond.particella
                   AND st.sub = cond.sub
                   AND st.unimm = cond.unimm
                   AND st.fkid_atto = cond.atto_ini
                   AND st.data_fine <= cond.data_fine
                   AND cond.pkid_tit = ce.pk_tit
                   AND cond.tipo_titolo = ce.tipo_titolo
                   AND ce.fk_cespite = c.pk_cespite
                   AND ltc.fkid_doc(+) = d.pkid_doc);


DROP VIEW SITI_H501.CONTRATT_CESPITI;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONTRATT_CESPITI
(
    CODICE,
    ID_CONTR,
    PKID_DOC,
    COD_CES
)
BEQUEATH DEFINER
AS
    SELECT CAST (fkid_atto AS VARCHAR2 (10))
               AS codice,
           ROW_NUMBER ()
               OVER (PARTITION BY fkid_atto
                     ORDER BY data_fine_val DESC, cod_ces ASC)
               AS id_contr,
           pkid_doc,
           cod_ces
      FROM (  SELECT ad.fkid_atto,
                     d.pkid_doc,
                     c.cod_cespite         AS cod_ces,
                     MAX (t.data_fine)     AS data_fine_val
                FROM sitifile_atti               a,
                     sitifile_atti_doc           ad,
                     sitifile_documenti          d,
                     sitifile_documenti_campi_ext de,
                     cons_ufre_tab               t,
                     cons_cons_tab               t2,
                     patri_cespiti_part          ce,
                     patri_cespiti               c
               WHERE     a.fkid_tipo_atto = -22
                     AND ad.fkid_atto = a.pkid_atto
                     AND d.pkid_doc = ad.fkid_doc
                     AND d.fkid_tipo_doc = -27
                     AND de.fkid_doc = d.pkid_doc
                     AND t.atto_ini = a.pkid_atto
                     AND t2.cod_nazionale = t.cod_nazionale
                     AND t2.foglio = t.foglio
                     AND t2.particella = t.particella
                     AND t2.sub = t.sub
                     AND t2.data_inizio <= de.sys_loc_dt_fine
                     AND t2.data_fine >= de.sys_loc_dt_decorrenza
                     AND ce.pk_tit = t2.pkid_cons
                     AND ce.tipo_titolo = t2.tipo_titolo
                     AND c.pk_cespite = ce.fk_cespite
                     AND TRUNC (t.data_inizio, 'DDD') <
                         TRUNC (t.data_fine, 'DDD')
            GROUP BY ad.fkid_atto, d.pkid_doc, c.cod_cespite
            UNION
              SELECT ad.fkid_atto,
                     d.pkid_doc,
                     c.cod_cespite         AS cod_ces,
                     MAX (t.data_fine)     AS data_fine_val
                FROM sitifile_atti               a,
                     sitifile_atti_doc           ad,
                     sitifile_documenti          d,
                     sitifile_documenti_campi_ext de,
                     cons_urui_tab               t,
                     cons_csui_tab               t2,
                     patri_cespiti_uiu           ce,
                     patri_cespiti               c
               WHERE     a.fkid_tipo_atto = -22
                     AND ad.fkid_atto = a.pkid_atto
                     AND d.pkid_doc = ad.fkid_doc
                     AND d.fkid_tipo_doc = -27
                     AND de.fkid_doc = d.pkid_doc
                     AND t.atto_ini = a.pkid_atto
                     AND t2.cod_nazionale = t.cod_nazionale
                     AND t2.foglio = t.foglio
                     AND t2.particella = t.particella
                     AND t2.sub = t.sub
                     AND t2.unimm = t.unimm
                     AND t2.data_inizio <= de.sys_loc_dt_fine
                     AND t2.data_fine >= de.sys_loc_dt_decorrenza
                     AND ce.pk_tit = t2.pkid_csui
                     AND ce.tipo_titolo = t2.tipo_titolo
                     AND c.pk_cespite = ce.fk_cespite
                     AND TRUNC (t.data_inizio, 'DDD') <
                         TRUNC (t.data_fine, 'DDD')
            GROUP BY ad.fkid_atto, d.pkid_doc, c.cod_cespite
            UNION
              SELECT ad.fkid_atto,
                     d.pkid_doc,
                     c.cod_cespite           AS cod_ces,
                     MAX (cst.data_fine)     AS data_fine_val
                FROM sitifile_atti               a,
                     sitifile_atti_doc           ad,
                     sitifile_documenti          d,
                     sitifile_documenti_campi_ext de,
                     cons_subloc_tab             cst,
                     patri_cespiti_part          ce,
                     patri_cespiti               c,
                     patri_loc_tipo_contr        ltc,
                     (SELECT DISTINCT id_particella,
                                      cod_nazionale,
                                      foglio,
                                      particella,
                                      sub
                        FROM sititrkc) st,
                     (SELECT DISTINCT pkid_uffr     AS pkid_tit,
                                      tipo_titolo,
                                      cod_nazionale,
                                      foglio,
                                      particella,
                                      sub,
                                      NULL          AS unimm,
                                      atto_ini,
                                      data_inizio
                        FROM cons_ufre_tab) cond
               WHERE     a.fkid_tipo_atto = -22
                     AND ad.fkid_atto = a.pkid_atto
                     AND d.pkid_doc = ad.fkid_doc
                     AND d.fkid_tipo_doc = -27
                     AND de.fkid_doc = d.pkid_doc
                     AND cst.atto_inizio = a.pkid_atto
                     AND cst.obj_type = 'P'
                     AND cst.fkid_obj = st.id_particella
                     AND st.cod_nazionale = cond.cod_nazionale
                     AND st.foglio = cond.foglio
                     AND st.particella = cond.particella
                     AND st.sub = cond.sub
                     AND cst.fkid_atto = cond.atto_ini
                     AND cond.pkid_tit = ce.pk_tit
                     AND cond.tipo_titolo = ce.tipo_titolo
                     AND ce.fk_cespite = c.pk_cespite
                     AND TRUNC (cst.data_inizio, 'DDD') <
                         TRUNC (cst.data_fine, 'DDD')
            GROUP BY ad.fkid_atto, d.pkid_doc, c.cod_cespite
            UNION
              SELECT ad.fkid_atto,
                     d.pkid_doc,
                     c.cod_cespite          AS cod_ces,
                     MAX (st.data_fine)     AS data_fine_val
                FROM sitifile_atti               a,
                     sitifile_atti_doc           ad,
                     sitifile_documenti          d,
                     sitifile_documenti_campi_ext de,
                     patri_cespiti_uiu           ce,
                     patri_cespiti               c,
                     patri_loc_tipo_contr        ltc,
                     (SELECT DISTINCT st.cod_nazionale,
                                      st.foglio,
                                      st.particella,
                                      st.sub,
                                      st.unimm,
                                      cst.tipo_titolo,
                                      cst.fkid_atto,
                                      cst.atto_inizio,
                                      cst.atto_fine,
                                      cst.data_inizio,
                                      cst.data_fine
                        FROM cons_subloc_tab cst,
                             (SELECT DISTINCT id_cata_uiu,
                                              cod_nazionale,
                                              foglio,
                                              particella,
                                              sub,
                                              unimm
                                FROM sitiuiu) st
                       WHERE     cst.obj_type = 'U'
                             AND cst.fkid_obj = st.id_cata_uiu
                      UNION
                      SELECT DISTINCT st.cod_nazionale,
                                      st.foglio,
                                      st.particella,
                                      st.sub,
                                      st.unimm,
                                      cst.tipo_titolo,
                                      cst.fkid_atto,
                                      cst.atto_inizio,
                                      cst.atto_fine,
                                      cst.data_inizio,
                                      cst.data_fine
                        FROM cons_subloc_tab cst,
                             (SELECT DISTINCT id_cata_vano,
                                              cod_nazionale,
                                              foglio,
                                              particella,
                                              sub,
                                              unimm
                                FROM sitiedi_vani) st
                       WHERE     cst.obj_type = 'V'
                             AND cst.fkid_obj = st.id_cata_vano) st,
                     (SELECT DISTINCT pkid_urui     AS pkid_tit,
                                      tipo_titolo,
                                      cod_nazionale,
                                      foglio,
                                      particella,
                                      sub,
                                      unimm,
                                      atto_ini,
                                      data_inizio
                        FROM cons_urui_tab) cond
               WHERE     a.fkid_tipo_atto = -22
                     AND ad.fkid_atto = a.pkid_atto
                     AND d.pkid_doc = ad.fkid_doc
                     AND d.fkid_tipo_doc = -27
                     AND de.fkid_doc = d.pkid_doc
                     AND st.atto_inizio = a.pkid_atto
                     AND st.cod_nazionale = cond.cod_nazionale
                     AND st.foglio = cond.foglio
                     AND st.particella = cond.particella
                     AND st.sub = cond.sub
                     AND st.unimm = cond.unimm
                     AND st.fkid_atto = cond.atto_ini
                     AND cond.pkid_tit = ce.pk_tit
                     AND cond.tipo_titolo = ce.tipo_titolo
                     AND ce.fk_cespite = c.pk_cespite
                     AND TRUNC (st.data_inizio, 'DDD') <
                         TRUNC (st.data_fine, 'DDD')
            GROUP BY ad.fkid_atto, d.pkid_doc, c.cod_cespite);


DROP VIEW SITI_H501.CONTRATT_LIST;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONTRATT_LIST
(
    CODICE,
    ID_CONTR,
    COD_CES,
    COD_INQ,
    COD_TCONT,
    DATA_CONT,
    ESCLUDI_RIC,
    ESCLUDI_BOL,
    CESSAZIONE,
    COD_UTE
)
BEQUEATH DEFINER
AS
    SELECT CAST (pkid_atto AS VARCHAR2 (10))     AS codice,
           1                                     AS id_contr,
           (SELECT cod_cespite
              FROM patri_cespiti
             WHERE pk_cespite = a.fk_cespite)    AS cod_ces,
           CAST (
               (SELECT MIN (pk_cuaa)
                  FROM (SELECT pk_cuaa, atto_ini, data_fine
                          FROM cons_ufre_tab
                        UNION ALL
                        SELECT pk_cuaa, atto_ini, data_fine
                          FROM cons_urui_tab)
                 WHERE     atto_ini = a.pkid_atto
                       AND data_fine = de.sys_loc_dt_fine)
                   AS VARCHAR2 (10))             AS cod_inq,
           ltc.COD_TIPO_CONTR                    AS cod_tcont,
           de.sys_loc_dt_decorrenza              AS data_cont,
           CASE
               WHEN ltc.fl_escludi_rical_aut = 'S' THEN 'S'
               WHEN ltc.fl_escludi_agg_canone = 'S' THEN 'C'
               ELSE 'N'
           END                                   AS ESCLUDI_RIC,
           ltc.fl_escludi_fatturazione           AS ESCLUDI_BOL,
           CAST (
               DECODE (de.sys_loc_dt_fine,
                       TO_DATE ('99991231', 'yyyymmdd'), NULL,
                       de.sys_loc_dt_fine)
                   AS DATE)                      AS CESSAZIONE,
           de.sys_loc_cod_ute                    AS cod_ute
      -- NEW_FIELDS
      /*
      ,de.SYS_LOC_COD_PERIODO as periodo,
      de.SYS_LOC_COD_RISCOS as codrisc, ltc.cod_calcolo_canone as codcalc,
      ltc.costo_base, ltc.costo_up, ltc.sup_conv, cast(ltc.anno_vetus as varchar2(4)) as anno_vetus,
      ltc.coef_vetus, ltc.CAN_NOISTA, de.sys_loc_cod_calcolo as CAN_APPLIC,
      de.sys_loc_canone_pre_pa as CAN_PRE_PA, de.sys_loc_dt_pagam_ini as DATA_P_INI,
      de.sys_loc_cauzione as CAUZIONE,
      de.sys_loc_dt_in_cauzione as DATA_D_CAU,
      ltc.istat_pct_increm as PERC_INCR,
      ltc.AGG_ISTAT,
      ltc.istat_ipb as ISTAT_IPB, ltc.istat_ar as ISTAT_AR, de.sys_loc_imp_reg_anno_pr as ANNOREG,
      substr('00' || de.sys_loc_imp_reg_mese_pr, -2) as MESEREG, de.sys_loc_imp_reg_num_reg as NUM_REG,
      de.sys_loc_imp_reg_serie_reg as SERIE_REG, de.sys_loc_imposta_reg as TIPO_REG,
      de.sys_loc_imposta_reg_freq as FREQ_REG, null as DATA_US_REG,
      de.sys_loc_imp_reg_cod_uff as UFFI_REG,
      ltc.dt_ult_agg_istat as DATA_ISTAT, substr('0000' || ltc.istat_base_anno, -4) || substr('00' || ltc.istat_base_mese, -2) as AM_ISTATB,
      ltc.IMP_REG, null as TIPO_UT, de.sys_loc_canone_iniziale as CANONE_INI, de.sys_loc_canone_finale as CANONE_FIN, ltc.ANNI_DER,
      ltc.fl_interessi_mora as ADD_MORA, null as DATA_DISD,
      ltc.fl_soggetto_iva as SOGG_IVA,
      case when ltc.fl_fatt_emissione = 'N' then 'N' when ltc.FL_FATT_POSTICIPATA = 'N' then '1' else '2' end as FATTURA,
      ltc.istat_nr_anni_agg as N_ANNI_ISTAT, de.sys_loc_fl_rata_post as POSTICIPATO,
      de.sys_loc_note_contratto as NOTE_CON,
      ltc.fl_comunica_agg_canone as COM_INQUI,
      null as RLOCK,
      de.sys_loc_fl_int_cauzione as ACCR_INT_DP, null as COD_TRIBUTO,
      de.sys_loc_cauzione_natura as NATURA_DP, de.sys_loc_dt_scad_cauzione as SCADENZA_DP,
      de.sys_loc_dt_out_cauzione as DATA_REST_DP, ltc.fl_rescissione as RESCISSIONE_INQ,
      ltc.N_MESI_RESCISSIONE as N_MESI_RESCIS,
      nvl(de.sys_loc_perc_spese_inq, 100) as PERC_SPESE_INQ,
      de.sys_loc_scad_rin_istat as MESE_ISTAT_RIC, ltc.fl_atto_al_legale as LEGALE,
      de.sys_loc_fl_imp_reg_cauz as IMPOSTA_DEP, de.sys_loc_spese_dep1 as SPESE_DEP1,
      de.sys_loc_cod_trib_dep1 as COD_TRIB_DEP1, de.sys_loc_spese_dep2 as SPESE_DEP2,
      de.sys_loc_cod_trib_dep2 as COD_TRIB_DEP2,
      de.sys_loc_cauzione_tipo as TIPO_DEP, de.sys_loc_dt_stipula as DATA_STIP,
      de.sys_loc_escludi_cong as ESCLUDI_CONG, de.sys_loc_codice_gemello as CODICE_GEMELLO,
      de.sys_loc_versante_imposta as VERSANTE_IMPOSTA,
      de.sys_loc_fr_denuncia as FR_DENUNCIA,
      de.sys_loc_tp_int_cauzione as TIPO_INT_DP, ltc.oggetto_locazione as OGG_LOCAZIONE,
      ltc.data_rescissione_dal as RESCISSIONE_DAL
      */
      -- /NEW_FIELDS
      FROM sitifile_atti_doc             ad,
           sitifile_documenti            d,
           sitifile_documenti_campi_ext  de,
           patri_loc_tipo_contr          ltc,
           (SELECT DISTINCT pkid_atto, pk_cespite AS fk_cespite
              FROM (SELECT a.pkid_atto, pc.pk_cespite
                      FROM sitifile_atti       a,
                           cons_ufre_tab       t,
                           cons_cons_tab       t2,
                           patri_cespiti_part  c,
                           patri_cespiti       pc
                     WHERE     a.fkid_tipo_atto = -22
                           AND t.atto_ini = a.pkid_atto
                           AND t2.cod_nazionale = t.cod_nazionale
                           AND t2.foglio = t.foglio
                           AND t2.particella = t.particella
                           AND t2.sub = t.sub
                           AND t2.data_inizio <= t.data_fine
                           AND t2.data_fine >= t.data_inizio
                           AND c.pk_tit = t2.pkid_cons
                           AND c.tipo_titolo = t2.tipo_titolo
                           AND c.fk_cespite = pc.pk_cespite
                    UNION ALL
                    SELECT a.pkid_atto, pc.pk_cespite
                      FROM sitifile_atti      a,
                           cons_urui_tab      t,
                           cons_csui_tab      t2,
                           patri_cespiti_uiu  c,
                           patri_cespiti      pc
                     WHERE     a.fkid_tipo_atto = -22
                           AND t.atto_ini = a.pkid_atto
                           AND t2.cod_nazionale = t.cod_nazionale
                           AND t2.foglio = t.foglio
                           AND t2.particella = t.particella
                           AND t2.sub = t.sub
                           AND t2.unimm = t.unimm
                           AND t2.data_inizio <= t.data_fine
                           AND t2.data_fine >= t.data_inizio
                           AND c.pk_tit = t2.pkid_csui
                           AND c.tipo_titolo = t2.tipo_titolo
                           AND c.fk_cespite = pc.pk_cespite)
             WHERE patri_pck.getid_contr (pk_cespite, pkid_atto, 'A') = 1) a
     WHERE     ad.FKID_ATTO = a.pkid_atto
           AND d.PKID_DOC = ad.FKID_DOC
           AND d.FKID_TIPO_DOC = -27
           AND de.fkid_doc = d.pkid_doc
           AND ltc.FKID_DOC = d.PKID_DOC;


DROP VIEW SITI_H501.CONTRATT_VAR;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONTRATT_VAR
(
    ETYPE,
    COD_NAZIONALE,
    FOGLIO,
    PARTICELLA,
    SUB,
    UNIMM,
    ATTO_INI,
    DATA_VAR
)
BEQUEATH DEFINER
AS
    WITH
        urui_tab_processed
        AS
            (  SELECT a.atto_ini,
                      a.cod_nazionale,
                      a.foglio,
                      a.particella,
                      a.sub,
                      a.unimm,
                      a.fl_totale,
                      MIN (a.data_inizio)     AS data_inizio,
                      MAX (b.data_fine)       AS data_fine
                 FROM cons_urui_tab a, cons_urui_tab b
                WHERE     a.cod_nazionale = b.cod_nazionale
                      AND a.foglio = b.foglio
                      AND a.particella = b.particella
                      AND a.sub = b.sub
                      AND a.unimm = b.unimm
                      AND a.atto_ini = b.atto_ini
                      AND a.data_fine + (1 / 24 / 60 / 60) = b.data_inizio
             GROUP BY a.atto_ini,
                      a.cod_nazionale,
                      a.foglio,
                      a.particella,
                      a.sub,
                      a.unimm,
                      a.fl_totale),
        urui_tab
        AS
            (SELECT * FROM urui_tab_processed
             UNION
             SELECT a.atto_ini,
                    a.cod_nazionale,
                    a.foglio,
                    a.particella,
                    a.sub,
                    a.unimm,
                    a.fl_totale,
                    a.data_inizio,
                    a.data_fine
               FROM cons_urui_tab a
              WHERE (cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     unimm,
                     atto_ini) NOT IN
                        (SELECT cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm,
                                atto_ini
                           FROM urui_tab_processed b
                          WHERE     a.data_inizio < b.data_fine
                                AND a.data_fine > b.data_inizio)),
        ufre_tab_processed
        AS
            (  SELECT a.atto_ini,
                      a.cod_nazionale,
                      a.foglio,
                      a.particella,
                      a.sub,
                      NULL                    AS unimm,
                      a.fl_totale,
                      MIN (a.data_inizio)     AS data_inizio,
                      MAX (b.data_fine)       AS data_fine
                 FROM cons_ufre_tab a, cons_ufre_tab b
                WHERE     a.cod_nazionale = b.cod_nazionale
                      AND a.foglio = b.foglio
                      AND a.particella = b.particella
                      AND a.sub = b.sub
                      AND a.atto_ini = b.atto_ini
                      AND a.data_fine + (1 / 24 / 60 / 60) = b.data_inizio
             GROUP BY a.atto_ini,
                      a.cod_nazionale,
                      a.foglio,
                      a.particella,
                      a.sub,
                      a.fl_totale),
        ufre_tab
        AS
            (SELECT * FROM ufre_tab_processed
             UNION
             SELECT a.atto_ini,
                    a.cod_nazionale,
                    a.foglio,
                    a.particella,
                    a.sub,
                    NULL     AS unimm,
                    a.fl_totale,
                    a.data_inizio,
                    a.data_fine
               FROM cons_ufre_tab a
              WHERE (cod_nazionale,
                     foglio,
                     particella,
                     sub,
                     unimm,
                     atto_ini) NOT IN
                        (SELECT cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm,
                                atto_ini
                           FROM ufre_tab_processed b
                          WHERE     a.data_inizio < b.data_fine
                                AND a.data_fine > b.data_inizio))
    SELECT DISTINCT
           variaz.etype,
           variaz.cod_nazionale,
           variaz.foglio,
           variaz.particella,
           variaz.sub,
           variaz.unimm,
           variaz.atto_ini,
           CASE
               WHEN variaz.data_var < contratt_dates.data_inizio
               THEN
                   contratt_dates.data_inizio
               ELSE
                   CASE
                       WHEN variaz.data_var > contratt_dates.data_fine
                       THEN
                           contratt_dates.data_fine
                       ELSE
                           variaz.data_var
                   END
           END    AS date_var
      FROM (SELECT DISTINCT 'P'                 AS etype,
                            cod_nazionale,
                            foglio,
                            particella,
                            sub,
                            NULL                AS unimm,
                            cut.atto_ini,
                            cut.data_inizio     AS data_var
              FROM ufre_tab cut
            UNION
            SELECT DISTINCT 'P'               AS etype,
                            cod_nazionale,
                            foglio,
                            particella,
                            sub,
                            NULL              AS unimm,
                            cut.atto_ini,
                            cut.data_fine     AS data_var
              FROM ufre_tab cut
            UNION
            SELECT DISTINCT 'U'                 AS etype,
                            cod_nazionale,
                            foglio,
                            particella,
                            sub,
                            unimm,
                            cut.atto_ini,
                            cut.data_inizio     AS data_var
              FROM urui_tab cut
             WHERE cut.fl_totale = 'Y'
            UNION
            SELECT DISTINCT 'U'               AS etype,
                            cod_nazionale,
                            foglio,
                            particella,
                            sub,
                            unimm,
                            cut.atto_ini,
                            cut.data_fine     AS data_var
              FROM urui_tab cut
             WHERE cut.fl_totale = 'Y'
            UNION
            SELECT DISTINCT 'U'                     AS etype,
                            cut.cod_nazionale,
                            cut.foglio,
                            cut.particella,
                            cut.sub,
                            cut.unimm,
                            cut.atto_ini,
                            cuv.data_inizio_val     AS data_var
              FROM urui_tab cut, cons_urui_vani cuv
             WHERE     cut.cod_nazionale = cuv.cod_nazionale
                   AND cut.foglio = cuv.foglio
                   AND cut.particella = cuv.particella
                   AND cut.sub = cuv.sub
                   AND cut.unimm = cuv.unimm
                   AND cut.atto_ini = cuv.id_atto
                   AND cut.fl_totale = 'N'
            UNION
            SELECT DISTINCT 'U'                   AS etype,
                            cut.cod_nazionale,
                            cut.foglio,
                            cut.particella,
                            cut.sub,
                            cut.unimm,
                            cut.atto_ini,
                            cuv.data_fine_val     AS data_var
              FROM urui_tab cut, cons_urui_vani cuv
             WHERE     cut.cod_nazionale = cuv.cod_nazionale
                   AND cut.foglio = cuv.foglio
                   AND cut.particella = cuv.particella
                   AND cut.sub = cuv.sub
                   AND cut.unimm = cuv.unimm
                   AND cut.atto_ini = cuv.id_atto
                   AND cut.fl_totale = 'N'
            UNION
            SELECT DISTINCT cst.obj_type        AS etype,
                            st.cod_nazionale,
                            st.foglio,
                            st.particella,
                            st.sub,
                            st.unimm,
                            cst.atto_inizio     AS atto_ini,
                            cst.data_inizio     AS data_var
              FROM cons_subloc_tab  cst,
                   (SELECT DISTINCT id_particella,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    NULL     AS unimm
                      FROM sititrkc) st
             WHERE cst.obj_type = 'P' AND cst.fkid_obj = st.id_particella
            UNION
            SELECT DISTINCT cst.obj_type        AS etype,
                            st.cod_nazionale,
                            st.foglio,
                            st.particella,
                            st.sub,
                            st.unimm,
                            cst.atto_inizio     AS atto_ini,
                            cst.data_fine       AS data_var
              FROM cons_subloc_tab  cst,
                   (SELECT DISTINCT id_particella,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    NULL     AS unimm
                      FROM sititrkc) st
             WHERE cst.obj_type = 'P' AND cst.fkid_obj = st.id_particella
            UNION
            SELECT DISTINCT cst.obj_type        AS etype,
                            st.cod_nazionale,
                            st.foglio,
                            st.particella,
                            st.sub,
                            st.unimm,
                            cst.atto_inizio     AS atto_ini,
                            cst.data_inizio     AS data_var
              FROM cons_subloc_tab  cst,
                   (SELECT DISTINCT id_cata_uiu,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    unimm
                      FROM sitiuiu) st
             WHERE cst.obj_type = 'U' AND cst.fkid_obj = st.id_cata_uiu
            UNION
            SELECT DISTINCT 'U'                 AS etype,
                            st.cod_nazionale,
                            st.foglio,
                            st.particella,
                            st.sub,
                            st.unimm,
                            cst.atto_inizio     AS atto_ini,
                            cst.data_inizio     AS data_var
              FROM cons_subloc_tab  cst,
                   (SELECT DISTINCT id_cata_vano,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    unimm
                      FROM sitiedi_vani) st
             WHERE cst.obj_type = 'V' AND cst.fkid_obj = st.id_cata_vano
            UNION
            SELECT DISTINCT cst.obj_type        AS etype,
                            st.cod_nazionale,
                            st.foglio,
                            st.particella,
                            st.sub,
                            st.unimm,
                            cst.atto_inizio     AS atto_ini,
                            cst.data_fine       AS data_var
              FROM cons_subloc_tab  cst,
                   (SELECT DISTINCT id_cata_uiu,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    unimm
                      FROM sitiuiu) st
             WHERE cst.obj_type = 'U' AND cst.fkid_obj = st.id_cata_uiu
            UNION
            SELECT DISTINCT 'U'                 AS etype,
                            st.cod_nazionale,
                            st.foglio,
                            st.particella,
                            st.sub,
                            st.unimm,
                            cst.atto_inizio     AS atto_ini,
                            cst.data_fine       AS data_var
              FROM cons_subloc_tab  cst,
                   (SELECT DISTINCT id_cata_vano,
                                    cod_nazionale,
                                    foglio,
                                    particella,
                                    sub,
                                    unimm
                      FROM sitiedi_vani) st
             WHERE cst.obj_type = 'V' AND cst.fkid_obj = st.id_cata_vano)
           variaz,
           (SELECT DISTINCT
                   sa.pkid_atto                  AS atto_ini,
                   sce.sys_loc_dt_decorrenza     AS data_inizio,
                   sce.sys_loc_dt_fine           AS data_fine
              FROM sitifile_atti                 sa,
                   sitifile_documenti            sd,
                   sitifile_atti_doc             sac,
                   sitifile_documenti_campi_ext  sce
             WHERE     sa.pkid_atto = sac.fkid_atto
                   AND sa.fkid_tipo_atto = -22
                   AND sd.pkid_doc = sac.fkid_doc
                   AND sd.fkid_tipo_doc = -27
                   AND sce.fkid_doc = sd.pkid_doc) contratt_dates
     WHERE variaz.atto_ini = contratt_dates.atto_ini;


DROP VIEW SITI_H501.GISPARAMS;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.GISPARAMS
(
    VARIABILE,
    VALORE,
    LABEL,
    TIPO
)
BEQUEATH DEFINER
AS
    SELECT variabile,
           valore,
           label,
           tipo
      FROM gisparams_all
     WHERE hidden = 'N';


DROP VIEW SITI_H501.LOAD_CAT_PRM_INCR;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.LOAD_CAT_PRM_INCR
(
    DT_CARICO,
    COD_NAZ,
    DT_RIF,
    TIPOLOGIA
)
BEQUEATH DEFINER
AS
    (SELECT DT_CARICO,
            SUBSTR (ROW1, 30, 5)    AS COD_NAZ,
            CASE
                WHEN LENGTH (ROW5) <= 40 THEN SUBSTR (ROW5, 30, 10)
                ELSE SUBSTR (ROW5, 41, 10)
            END                     AS DT_RIF,
            ROW4                    AS TIPOLOGIA
       FROM SITI_H501.LOAD_CAT_PRM
      WHERE ROW1 <> 'INCREMENTALE'
     UNION
     SELECT (SELECT DT_CARICO
               FROM SITI_H501.LOAD_CAT_PRM
              WHERE LOAD_ID = A.LOAD_ID)                  DT_CARICO,
            (SELECT ROW2
               FROM SITI_H501.LOAD_CAT_PRM
              WHERE LOAD_ID = A.LOAD_ID)                  AS COD_NAZ,
            TO_CHAR (DATA_INIZIALE + 30, 'DD/MM/YYYY')    AS DT_RIF,
            TIPO_FILE
       FROM SITI_H501.LOAD_CAT_INCREMENTALI A);


DROP VIEW SITI_H501.LP_CONTRATT;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.LP_CONTRATT
(
    CODICE,
    PKID_DOC,
    COD_TCONT,
    DATA_CONT,
    PERIODO,
    CODRISC,
    CODCALC,
    COSTO_BASE,
    COSTO_UP,
    SUP_CONV,
    ANNO_VETUS,
    COEF_VETUS,
    CAN_NOISTA,
    CAN_APPLIC,
    CAN_PRE_PA,
    DATA_P_INI,
    CAUZIONE,
    DATA_D_CAU,
    PERC_INCR,
    AGG_ISTAT,
    ISTAT_IPB,
    ISTAT_AR,
    ANNOREG,
    MESEREG,
    NUM_REG,
    SERIE_REG,
    TIPO_REG,
    FREQ_REG,
    DATA_US_REG,
    UFFI_REG,
    DATA_ISTAT,
    AM_ISTATB,
    IMP_REG,
    TIPO_UT,
    CANONE_INI,
    CANONE_FIN,
    ANNI_DER,
    ADD_MORA,
    DATA_DISD,
    SOGG_IVA,
    FATTURA,
    N_ANNI_ISTAT,
    POSTICIPATO,
    ESCLUDI_RIC,
    ESCLUDI_BOL,
    NOTE_CON,
    COM_INQUI,
    CESSAZIONE,
    RLOCK,
    ACCR_INT_DP,
    COD_TRIBUTO,
    NATURA_DP,
    SCADENZA_DP,
    DATA_REST_DP,
    RESCISSIONE_INQ,
    N_MESI_RESCIS,
    MESE_ISTAT_RIC,
    LEGALE,
    IMPOSTA_DEP,
    SPESE_DEP1,
    COD_TRIB_DEP1,
    SPESE_DEP2,
    COD_TRIB_DEP2,
    TIPO_DEP,
    DATA_STIP,
    ESCLUDI_CONG,
    CODICE_GEMELLO,
    VERSANTE_IMPOSTA,
    COD_UTE,
    FR_DENUNCIA,
    TIPO_INT_DP,
    OGG_LOCAZIONE,
    RESCISSIONE_DAL,
    DURATA
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT "CODICE",
                    "PKID_DOC",
                    "COD_TCONT",
                    "DATA_CONT",
                    "PERIODO",
                    "CODRISC",
                    "CODCALC",
                    "COSTO_BASE",
                    "COSTO_UP",
                    "SUP_CONV",
                    "ANNO_VETUS",
                    "COEF_VETUS",
                    "CAN_NOISTA",
                    "CAN_APPLIC",
                    "CAN_PRE_PA",
                    "DATA_P_INI",
                    "CAUZIONE",
                    "DATA_D_CAU",
                    "PERC_INCR",
                    "AGG_ISTAT",
                    "ISTAT_IPB",
                    "ISTAT_AR",
                    "ANNOREG",
                    "MESEREG",
                    "NUM_REG",
                    "SERIE_REG",
                    "TIPO_REG",
                    "FREQ_REG",
                    "DATA_US_REG",
                    "UFFI_REG",
                    "DATA_ISTAT",
                    "AM_ISTATB",
                    "IMP_REG",
                    "TIPO_UT",
                    "CANONE_INI",
                    "CANONE_FIN",
                    "ANNI_DER",
                    "ADD_MORA",
                    "DATA_DISD",
                    "SOGG_IVA",
                    "FATTURA",
                    "N_ANNI_ISTAT",
                    "POSTICIPATO",
                    "ESCLUDI_RIC",
                    "ESCLUDI_BOL",
                    "NOTE_CON",
                    "COM_INQUI",
                    "CESSAZIONE",
                    "RLOCK",
                    "ACCR_INT_DP",
                    "COD_TRIBUTO",
                    "NATURA_DP",
                    "SCADENZA_DP",
                    "DATA_REST_DP",
                    "RESCISSIONE_INQ",
                    "N_MESI_RESCIS",
                    "MESE_ISTAT_RIC",
                    "LEGALE",
                    "IMPOSTA_DEP",
                    "SPESE_DEP1",
                    "COD_TRIB_DEP1",
                    "SPESE_DEP2",
                    "COD_TRIB_DEP2",
                    "TIPO_DEP",
                    "DATA_STIP",
                    "ESCLUDI_CONG",
                    "CODICE_GEMELLO",
                    "VERSANTE_IMPOSTA",
                    "COD_UTE",
                    "FR_DENUNCIA",
                    "TIPO_INT_DP",
                    "OGG_LOCAZIONE",
                    "RESCISSIONE_DAL",
                    "DURATA"
      FROM (SELECT CAST (a.pkid_atto AS VARCHAR2 (10))
                       AS codice,
                   d.pkid_doc,
                   ltc.COD_TIPO_CONTR
                       AS cod_tcont,
                   de.sys_loc_dt_decorrenza
                       AS data_cont,
                   de.SYS_LOC_COD_PERIODO
                       AS periodo,
                   de.SYS_LOC_COD_RISCOS
                       AS codrisc,
                   ltc.cod_calcolo_canone
                       AS codcalc,
                   ltc.costo_base,
                   ltc.costo_up,
                   ltc.sup_conv,
                   CAST (ltc.anno_vetus AS VARCHAR2 (4))
                       AS anno_vetus,
                   ltc.coef_vetus,
                   ltc.CAN_NOISTA,
                   de.sys_loc_cod_calcolo
                       AS CAN_APPLIC,
                   de.sys_loc_canone_pre_pa
                       AS CAN_PRE_PA,
                   de.sys_loc_dt_pagam_ini
                       AS DATA_P_INI,
                   de.sys_loc_cauzione
                       AS CAUZIONE,
                   de.sys_loc_dt_in_cauzione
                       AS DATA_D_CAU,
                   ltc.istat_pct_increm
                       AS PERC_INCR,
                   ltc.AGG_ISTAT,
                   ltc.istat_ipb
                       AS ISTAT_IPB,
                   ltc.istat_ar
                       AS ISTAT_AR,
                   de.sys_loc_imp_reg_anno_pr
                       AS ANNOREG,
                   SUBSTR ('00' || de.sys_loc_imp_reg_mese_pr, -2)
                       AS MESEREG,
                   de.sys_loc_imp_reg_num_reg
                       AS NUM_REG,
                   de.sys_loc_imp_reg_serie_reg
                       AS SERIE_REG,
                   de.sys_loc_imposta_reg
                       AS TIPO_REG,
                   de.sys_loc_imposta_reg_freq
                       AS FREQ_REG,
                   NULL
                       AS DATA_US_REG,
                   de.sys_loc_imp_reg_cod_uff
                       AS UFFI_REG,
                   ltc.dt_ult_agg_istat
                       AS DATA_ISTAT,
                      SUBSTR ('0000' || ltc.istat_base_anno, -4)
                   || SUBSTR ('00' || ltc.istat_base_mese, -2)
                       AS AM_ISTATB,
                   ltc.IMP_REG,
                   NULL
                       AS TIPO_UT,
                   de.sys_loc_canone_iniziale
                       AS CANONE_INI,
                   de.sys_loc_canone_finale
                       AS CANONE_FIN,
                   ltc.ANNI_DER,
                   ltc.fl_interessi_mora
                       AS ADD_MORA,
                   NULL
                       AS DATA_DISD,
                   ltc.fl_soggetto_iva
                       AS SOGG_IVA,
                   CASE
                       WHEN ltc.fl_fatt_emissione = 'N' THEN 'N'
                       WHEN ltc.FL_FATT_POSTICIPATA = 'N' THEN '1'
                       ELSE '2'
                   END
                       AS FATTURA,
                   ltc.istat_nr_anni_agg
                       AS N_ANNI_ISTAT,
                   de.sys_loc_fl_rata_post
                       AS POSTICIPATO,
                   CASE
                       WHEN ltc.fl_escludi_rical_aut = 'S' THEN 'S'
                       WHEN ltc.fl_escludi_agg_canone = 'S' THEN 'C'
                       ELSE 'N'
                   END
                       AS ESCLUDI_RIC,
                   ltc.fl_escludi_fatturazione
                       AS ESCLUDI_BOL,
                   de.sys_loc_note_contratto
                       AS NOTE_CON,
                   ltc.fl_comunica_agg_canone
                       AS COM_INQUI,
                   CAST (
                       DECODE (de.sys_loc_dt_fine,
                               TO_DATE ('99991231', 'yyyymmdd'), NULL,
                               de.sys_loc_dt_fine)
                           AS DATE)
                       AS CESSAZIONE,
                   NULL
                       AS RLOCK,
                   de.sys_loc_fl_int_cauzione
                       AS ACCR_INT_DP,
                   NULL
                       AS COD_TRIBUTO,
                   de.sys_loc_cauzione_natura
                       AS NATURA_DP,
                   de.sys_loc_dt_scad_cauzione
                       AS SCADENZA_DP,
                   de.sys_loc_dt_out_cauzione
                       AS DATA_REST_DP,
                   ltc.fl_rescissione
                       AS RESCISSIONE_INQ,
                   ltc.N_MESI_RESCISSIONE
                       AS N_MESI_RESCIS,
                   de.sys_loc_scad_rin_istat
                       AS MESE_ISTAT_RIC,
                   ltc.fl_atto_al_legale
                       AS LEGALE,
                   de.sys_loc_fl_imp_reg_cauz
                       AS IMPOSTA_DEP,
                   de.sys_loc_spese_dep1
                       AS SPESE_DEP1,
                   de.sys_loc_cod_trib_dep1
                       AS COD_TRIB_DEP1,
                   de.sys_loc_spese_dep2
                       AS SPESE_DEP2,
                   de.sys_loc_cod_trib_dep2
                       AS COD_TRIB_DEP2,
                   de.sys_loc_cauzione_tipo
                       AS TIPO_DEP,
                   de.sys_loc_dt_stipula
                       AS DATA_STIP,
                   de.sys_loc_escludi_cong
                       AS ESCLUDI_CONG,
                   de.sys_loc_codice_gemello
                       AS CODICE_GEMELLO,
                   de.sys_loc_versante_imposta
                       AS VERSANTE_IMPOSTA,
                   de.sys_loc_cod_ute
                       AS COD_UTE,
                   de.sys_loc_fr_denuncia
                       AS FR_DENUNCIA,
                   DECODE (de.sys_loc_tp_int_cauzione,
                           NULL, '0',
                           de.sys_loc_tp_int_cauzione)
                       AS TIPO_INT_DP,
                   ltc.oggetto_locazione
                       AS OGG_LOCAZIONE,
                   ltc.data_rescissione_dal
                       AS RESCISSIONE_DAL,
                   CAST (NULL AS NUMBER)
                       AS durata
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   cons_ufre_tab                 t,
                   patri_loc_tipo_contr          ltc,
                   patri_cespiti_part            ce,
                   patri_cespiti                 c
             WHERE     a.FKID_TIPO_ATTO = -22
                   AND ad.FKID_ATTO = a.pkid_atto
                   AND d.PKID_DOC = ad.FKID_DOC
                   AND d.FKID_TIPO_DOC = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND t.ATTO_INI = a.PKID_ATTO
                   AND ce.pk_tit = t.pkid_uffr
                   AND ce.tipo_titolo = t.tipo_titolo
                   AND c.pk_cespite = ce.fk_cespite
                   AND ltc.FKID_DOC(+) = d.PKID_DOC
            UNION ALL
            SELECT CAST (a.pkid_atto AS VARCHAR2 (10))
                       AS codice,
                   d.pkid_doc,
                   ltc.COD_TIPO_CONTR
                       AS cod_tcont,
                   de.sys_loc_dt_decorrenza
                       AS data_cont,
                   de.SYS_LOC_COD_PERIODO
                       AS periodo,
                   de.SYS_LOC_COD_RISCOS
                       AS codrisc,
                   ltc.cod_calcolo_canone
                       AS codcalc,
                   ltc.costo_base,
                   ltc.costo_up,
                   ltc.sup_conv,
                   CAST (ltc.anno_vetus AS VARCHAR2 (4))
                       AS anno_vetus,
                   ltc.coef_vetus,
                   ltc.CAN_NOISTA,
                   de.sys_loc_cod_calcolo
                       AS CAN_APPLIC,
                   de.sys_loc_canone_pre_pa
                       AS CAN_PRE_PA,
                   de.sys_loc_dt_pagam_ini
                       AS DATA_P_INI,
                   de.sys_loc_cauzione
                       AS CAUZIONE,
                   de.sys_loc_dt_in_cauzione
                       AS DATA_D_CAU,
                   ltc.istat_pct_increm
                       AS PERC_INCR,
                   ltc.AGG_ISTAT,
                   ltc.istat_ipb
                       AS ISTAT_IPB,
                   ltc.istat_ar
                       AS ISTAT_AR,
                   de.sys_loc_imp_reg_anno_pr
                       AS ANNOREG,
                   SUBSTR ('00' || de.sys_loc_imp_reg_mese_pr, -2)
                       AS MESEREG,
                   de.sys_loc_imp_reg_num_reg
                       AS NUM_REG,
                   de.sys_loc_imp_reg_serie_reg
                       AS SERIE_REG,
                   de.sys_loc_imposta_reg
                       AS TIPO_REG,
                   de.sys_loc_imposta_reg_freq
                       AS FREQ_REG,
                   NULL
                       AS DATA_US_REG,
                   de.sys_loc_imp_reg_cod_uff
                       AS UFFI_REG,
                   ltc.dt_ult_agg_istat
                       AS DATA_ISTAT,
                      SUBSTR ('0000' || ltc.istat_base_anno, -4)
                   || SUBSTR ('00' || ltc.istat_base_mese, -2)
                       AS AM_ISTATB,
                   ltc.IMP_REG,
                   NULL
                       AS TIPO_UT,
                   de.sys_loc_canone_iniziale
                       AS CANONE_INI,
                   de.sys_loc_canone_finale
                       AS CANONE_FIN,
                   ltc.ANNI_DER,
                   ltc.fl_interessi_mora
                       AS ADD_MORA,
                   NULL
                       AS DATA_DISD,
                   ltc.fl_soggetto_iva
                       AS SOGG_IVA,
                   CASE
                       WHEN ltc.fl_fatt_emissione = 'N' THEN 'N'
                       WHEN ltc.FL_FATT_POSTICIPATA = 'N' THEN '1'
                       ELSE '2'
                   END
                       AS FATTURA,
                   ltc.istat_nr_anni_agg
                       AS N_ANNI_ISTAT,
                   de.sys_loc_fl_rata_post
                       AS POSTICIPATO,
                   CASE
                       WHEN ltc.fl_escludi_rical_aut = 'S' THEN 'S'
                       WHEN ltc.fl_escludi_agg_canone = 'S' THEN 'C'
                       ELSE 'N'
                   END
                       AS ESCLUDI_RIC,
                   ltc.fl_escludi_fatturazione
                       AS ESCLUDI_BOL,
                   de.sys_loc_note_contratto
                       AS NOTE_CON,
                   ltc.fl_comunica_agg_canone
                       AS COM_INQUI,
                   CAST (
                       DECODE (de.sys_loc_dt_fine,
                               TO_DATE ('99991231', 'yyyymmdd'), NULL,
                               de.sys_loc_dt_fine)
                           AS DATE)
                       AS CESSAZIONE,
                   NULL
                       AS RLOCK,
                   de.sys_loc_fl_int_cauzione
                       AS ACCR_INT_DP,
                   NULL
                       AS COD_TRIBUTO,
                   de.sys_loc_cauzione_natura
                       AS NATURA_DP,
                   de.sys_loc_dt_scad_cauzione
                       AS SCADENZA_DP,
                   de.sys_loc_dt_out_cauzione
                       AS DATA_REST_DP,
                   ltc.fl_rescissione
                       AS RESCISSIONE_INQ,
                   ltc.N_MESI_RESCISSIONE
                       AS N_MESI_RESCIS,
                   de.sys_loc_scad_rin_istat
                       AS MESE_ISTAT_RIC,
                   ltc.fl_atto_al_legale
                       AS LEGALE,
                   de.sys_loc_fl_imp_reg_cauz
                       AS IMPOSTA_DEP,
                   de.sys_loc_spese_dep1
                       AS SPESE_DEP1,
                   de.sys_loc_cod_trib_dep1
                       AS COD_TRIB_DEP1,
                   de.sys_loc_spese_dep2
                       AS SPESE_DEP2,
                   de.sys_loc_cod_trib_dep2
                       AS COD_TRIB_DEP2,
                   de.sys_loc_cauzione_tipo
                       AS TIPO_DEP,
                   de.sys_loc_dt_stipula
                       AS DATA_STIP,
                   de.sys_loc_escludi_cong
                       AS ESCLUDI_CONG,
                   de.sys_loc_codice_gemello
                       AS CODICE_GEMELLO,
                   de.sys_loc_versante_imposta
                       AS VERSANTE_IMPOSTA,
                   de.sys_loc_cod_ute
                       AS COD_UTE,
                   de.sys_loc_fr_denuncia
                       AS FR_DENUNCIA,
                   DECODE (de.sys_loc_tp_int_cauzione,
                           NULL, '0',
                           de.sys_loc_tp_int_cauzione)
                       AS TIPO_INT_DP,
                   ltc.oggetto_locazione
                       AS OGG_LOCAZIONE,
                   ltc.data_rescissione_dal
                       AS RESCISSIONE_DAL,
                   CAST (NULL AS NUMBER)
                       AS durata
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   cons_urui_tab                 t,
                   patri_loc_tipo_contr          ltc,
                   patri_cespiti_uiu             ce,
                   patri_cespiti                 c
             WHERE     a.FKID_TIPO_ATTO = -22
                   AND ad.FKID_ATTO = a.pkid_atto
                   AND d.PKID_DOC = ad.FKID_DOC
                   AND d.FKID_TIPO_DOC = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND t.ATTO_INI = a.PKID_ATTO
                   AND ce.pk_tit = t.pkid_urui
                   AND ce.tipo_titolo = t.tipo_titolo
                   AND c.pk_cespite = ce.fk_cespite
                   AND ltc.FKID_DOC(+) = d.PKID_DOC);


DROP VIEW SITI_H501.LP_CONTRATT_CESPITI;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.LP_CONTRATT_CESPITI
(
    CODICE,
    ID_CONTR,
    PKID_DOC,
    COD_CES,
    PK_CESPITE
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT
           codice,
           ROW_NUMBER ()
               OVER (PARTITION BY codice
                     ORDER BY data_fine_val DESC, pk_cespite ASC)
               AS id_contr,
           pkid_doc,
           cod_ces,
           pk_cespite
      FROM (SELECT DISTINCT
                   CAST (a.pkid_atto AS VARCHAR2 (10))     AS codice,
                   d.pkid_doc,
                   c.cod_cespite                           AS cod_ces,
                   c.pk_cespite,
                   t.data_fine                             AS data_fine_val
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   cons_ufre_tab                 t,
                   patri_cespiti_part            ce,
                   patri_cespiti                 c
             WHERE     a.fkid_tipo_atto = -22
                   AND ad.fkid_atto = a.pkid_atto
                   AND d.pkid_doc = ad.fkid_doc
                   AND d.fkid_tipo_doc = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND t.atto_ini = a.pkid_atto
                   AND t.data_inizio <= de.sys_loc_dt_fine
                   AND t.data_fine >= de.sys_loc_dt_decorrenza
                   AND ce.pk_tit = t.pkid_uffr
                   AND ce.tipo_titolo = t.tipo_titolo
                   AND c.pk_cespite = ce.fk_cespite
                   AND TRUNC (t.data_inizio, 'DDD') <
                       TRUNC (t.data_fine, 'DDD')
            UNION ALL
            SELECT DISTINCT
                   CAST (a.pkid_atto AS VARCHAR2 (10))     AS codice,
                   d.pkid_doc,
                   c.cod_cespite                           AS cod_ces,
                   c.pk_cespite,
                   t.data_fine                             AS data_fine_val
              FROM sitifile_atti                 a,
                   sitifile_atti_doc             ad,
                   sitifile_documenti            d,
                   sitifile_documenti_campi_ext  de,
                   cons_urui_tab                 t,
                   patri_cespiti_uiu             ce,
                   patri_cespiti                 c
             WHERE     a.fkid_tipo_atto = -22
                   AND ad.fkid_atto = a.pkid_atto
                   AND d.pkid_doc = ad.fkid_doc
                   AND d.fkid_tipo_doc = -27
                   AND de.fkid_doc = d.pkid_doc
                   AND t.atto_ini = a.pkid_atto
                   AND t.data_inizio <= de.sys_loc_dt_fine
                   AND t.data_fine >= de.sys_loc_dt_decorrenza
                   AND ce.pk_tit = t.pkid_urui
                   AND ce.tipo_titolo = t.tipo_titolo
                   AND c.pk_cespite = ce.fk_cespite
                   AND TRUNC (t.data_inizio, 'DDD') <
                       TRUNC (t.data_fine, 'DDD'));


