DROP VIEW SITI_H501.SC_TEDI;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.SC_TEDI
(
    DUMMY,
    COD_CES,
    CODIMM,
    PK_CESPITE,
    CODSTUN,
    GRDESTUS,
    CODDESTUS,
    MESE_UL,
    ANNO_UL,
    MESE_RIS,
    ULTIMA_RIS,
    DATA_AB,
    CODTRISC,
    CODTSI,
    CODTASC,
    TIPOL_CAT,
    CLASSE_DEM,
    UBICAZIO,
    LIV_PIANO,
    STATO_CM,
    VERDE_COM,
    VANI_UTILI,
    SUP_TERRE,
    SUP_UI,
    SUP_GARAGE,
    SUP_PAC,
    SUP_PAS,
    SUP_BALC,
    SUP_TER,
    SUP_CAN,
    SUP_SOF,
    SUP_ALTRI,
    SUP_GODI,
    AMMOB,
    ALL_PORT,
    PIANO,
    SCALA
)
BEQUEATH DEFINER
AS
    SELECT Patri_Pck.init_sc_tedi_from_cespite (c.pk_cespite)
               AS dummy,
           c.cod_cespite
               AS cod_ces,
           c.cod_imm
               AS codimm,
           ec.pk_cespite,
           ec.cod_st_un
               AS codstun,
           ec.cod_gr_dest_uso
               AS grdestus,
           ec.cod_dest_uso
               AS coddestus,
           DECODE (Patri_Pck.get_mese_costr,
                   0, NULL,
                   LPAD ('' || Patri_Pck.get_mese_costr, 2, '0'))
               AS mese_ul,
           DECODE (Patri_Pck.get_anno_costr,
                   0, NULL,
                   Patri_Pck.get_anno_costr)
               AS anno_ul,
           DECODE (Patri_Pck.get_mese_ul_ris,
                   0, NULL,
                   LPAD ('' || Patri_Pck.get_mese_ul_ris, 2, '0'))
               AS mese_ris,
           DECODE (Patri_Pck.get_anno_ul_ris,
                   0, NULL,
                   Patri_Pck.get_anno_ul_ris)
               AS ultima_ris,
           ec.dt_abitabilita
               AS data_ab,
           ec.cod_t_risc
               AS CODTRISC,
           ec.cod_t_si
               AS CODTSI,
           ec.cod_t_asc
               AS CODTASC,
           Patri_Pck.get_coef_tipol_cat
               AS TIPOL_CAT,
           Patri_Pck.get_coef_cl_dem
               AS CLASSE_DEM,
           Patri_Pck.get_coef_ubicaz
               AS UBICAZIO,
           Patri_Pck.get_coef_liv_piano
               AS LIV_PIANO,
           Patri_Pck.get_coef_stato_cons
               AS STATO_CM,
           Patri_Pck.get_coef_verde_com
               AS VERDE_COM,
           Patri_Pck.get_vani_utili
               AS VANI_UTILI,
           Patri_Pck.get_sup_part
               AS sup_terre,
           Patri_Pck.get_sup_ui
               AS sup_ui,
           Patri_Pck.get_sup_garage
               AS sup_garage,
           Patri_Pck.get_sup_pac
               AS sup_pac,
           Patri_Pck.get_sup_pas
               AS sup_pas,
           Patri_Pck.get_sup_balc (c.pk_cespite)
               AS sup_balc,
           0
               AS sup_ter,
           0
               AS sup_can,
           0
               AS sup_sof,
           Patri_Pck.get_sup_verde_com
               AS sup_altri,
           Patri_Pck.get_sup_godi
               AS sup_godi,
           ec.fl_ammob
               AS AMMOB,
           ec.fl_all_port
               AS ALL_PORT,
           c.piano,
           c.scala
      FROM PATRI_CESPITI c, PATRI_CESPITI_EC ec
     WHERE     ec.pk_cespite = c.pk_cespite
           AND (   (    c.tipo_estrom IS NULL
                    AND c.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy'))
                OR c.tipo_estrom IS NOT NULL);


