DROP VIEW SITI_H501.SETTORI_CR_AGGREGATI;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.SETTORI_CR_AGGREGATI
(
    FK_SETTORE,
    TIPO,
    ETYPE,
    COD_NAZIONALE,
    FOGLIO,
    PARTICELLA,
    SUB,
    UNIMM,
    VANO
)
BEQUEATH DEFINER
AS
    WITH
        cra
        AS
            (SELECT fk_settore, tipo, fk_object
               FROM centriresp
              WHERE     data_inizio_val <= SYSDATE
                    AND data_fine_val >= SYSDATE
                    AND fk_settore IS NOT NULL),
        agg_t
        AS
            (SELECT cra.fk_settore,
                    cra.tipo,
                    at1.aggr_code,
                    at1.pkid_topo,
                    at1.data_inizio_val,
                    at1.data_fine_val
               FROM cra, aggr_topo at1
              WHERE     at1.data_inizio_val <= SYSDATE
                    AND at1.data_fine_val >= SYSDATE
                    AND cra.tipo = 'A'
                    AND cra.fk_object = at1.id_cata_topo),
        agg_p
        AS
            (SELECT agg_t.fk_settore,
                    agg_t.tipo,
                    'P'      AS etype,
                    ap1.cod_nazionale,
                    ap1.foglio,
                    ap1.particella,
                    ap1.sub,
                    NULL     AS unimm,
                    NULL     AS vano
               FROM aggr_part ap1, agg_t
              WHERE     ap1.aggr_code = agg_t.aggr_code
                    AND ap1.pkid_topo = agg_t.pkid_topo
                    AND ap1.data_inizio_val <= SYSDATE
                    AND ap1.data_fine_val >= SYSDATE)
    SELECT "FK_SETTORE",
           "TIPO",
           "ETYPE",
           "COD_NAZIONALE",
           "FOGLIO",
           "PARTICELLA",
           "SUB",
           "UNIMM",
           "VANO"
      FROM agg_p
    UNION ALL
    SELECT agg_p.fk_settore,
           agg_p.tipo,
           'U'      AS etype,
           su.cod_nazionale,
           su.foglio,
           su.particella,
           su.sub,
           su.unimm,
           NULL     AS vano
      FROM cata_uiu su, agg_p
     WHERE     su.cod_nazionale = agg_p.cod_nazionale
           AND su.foglio = agg_p.foglio
           AND su.particella = agg_p.particella
           AND su.sub = agg_p.sub
    UNION ALL
