           su.cod_nazionale,
           su.foglio,
           su.particella,
           su.sub,
           su.unimm,
           NULL     AS vano
      FROM cata_uiu su, part p
     WHERE     su.cod_nazionale = p.cod_nazionale
           AND su.foglio = p.foglio
           AND su.particella = p.particella
           AND su.sub = p.sub
    UNION ALL
    SELECT p.fk_settore,
           p.tipo,
           'V'     AS etype,
           sv.cod_nazionale,
           sv.foglio,
           sv.particella,
