/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.SITICOMU
(
    COD_NAZIONALE,
    ISTATP,
    ISTATC,
    ID_SEZC,
    NOME_COMUNE,
    NOME,
    DENO_PROV,
    SIGLA_PROV,
    ISTATR,
    CODI_FISC_LUNA,
    FLAG_CATA,
    CO_FOGLIO1,
    CO_FOGLIO2,
    COD_PROVINCIA,
    COD_COMUNE,
    SEZIONE_CENSUARIA,
    COD_TIPO_ZONA,
    DATA_AGGIORNAMENTO,
    CODICE_TNBZ,
    ISOPR,
    ID_COMUNE,
    ID_SEZIONE,
    ID_PROV,
    UBICAZIONE_GEOGRAFICA
)
BEQUEATH DEFINER
AS
    (SELECT d.cod_sezione,
            b.istatp,
            c.istatc,
            TRIM (d.sezione),
            d.nome,
            c.nome,
            b.deno_prov,
            b.sigla_prov,
            a.istatr,
            c.cod_comune,
            d.flag_cata,
            1,
            0,
            TO_NUMBER (b.istatp),
            TO_NUMBER (c.istatc),
            d.sezione,
            NULL         AS cod_tipo_zona,
            d.inizio     AS data_aggiornamento,
            NULL         AS codice_tnbz,
            NULL         AS isopr,
            c.id_comune,
            d.id_sezione,
            b.id_prov,
            ubicazione_geografica
       FROM CATA_REGI     a,
            CATA_PROV     b,
            CATA_COMU     c,
            CATA_SEZIONI  d
      WHERE     b.id_regi = a.id_regi
            AND c.id_prov = b.id_prov
            AND d.id_comune = c.id_comune);


