           a.sub,
           b.pk_cuaa,
           b.cuaa              AS cuaa,
           a.tipo_titolo,
           a.perc_poss,
           a.tipo_documento,
           a.tit_no_cod,
           a.valido_ini        AS valido_inizio,
           a.valido_fin        AS valido_fine,
           a.atto_ini          AS atto_inizio,
