           a.data_inizio,
           a.data_fine,
           pkid_cons * 100     id_conduzione,
           pkid_cons           AS pkid_tit,
           fl_totale
      FROM cons_cons_tab a, cons_azie_tab b
     WHERE b.pk_cuaa = a.pk_cuaa
