DROP VIEW SITI_H501.SITIFGLC;

/* Formatted on 18/07/2022 12:22:59 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.SITIFGLC
(
    COD_NAZIONALE,
    FOGLIO,
    ALLEGATO,
    SVILUPPO,
    DATA_CAT,
    TIPO,
    FILENAME,
    FILETYPE,
    SHAPE,
    SHAPEMAPPA,
    SE_ROW_ID,
    SCALA_ORIG,
    FLAG_STATO,
    TAVOLA,
    ID_FOGLIO,
    ID_TAVO,
    ISTATP
)
BEQUEATH DEFINER
AS
    SELECT A.COD_SEZIONE,
           B.FOGLIO,
           D.ALLEGATO,
           D.SVILUPPO,
           TO_CHAR (C.INIZIO, 'YYYYMM'),
           'T',
           D.NOME_MAPPA,
           DECODE (D.MAP_TYPE,  1, 'TIF',  2, 'DWG'),
           C.SHAPE,
           D.SHAPE     AS shapemappa,
           NVL (d.id_mappa, C.ID_TAVO),
           D.SCALA,
           NVL (b.flag_stato, 0),
           C.TAVOLA,
           B.ID_FOGLIO,
           C.ID_TAVO,
           F.ISTATP
      FROM CATA_SEZIONI  A,
           CATA_FOGL     B,
           GIS_TAVO      C,
           GIS_MAPPE     D,
           CATA_COMU     E,
           CATA_PROV     F
     WHERE     F.ID_PROV = E.ID_PROV
           AND E.ID_COMUNE = A.ID_COMUNE
           AND B.ID_SEZIONE = A.ID_SEZIONE
           AND C.ID_FOGLIO = B.ID_FOGLIO
           AND C.INIZIO <= SYSDATE
           AND C.FINE >= SYSDATE
           AND D.ID_TAVO(+) = C.ID_TAVO
           AND (D.MAP_TYPE IN (1, 2) OR D.MAP_TYPE IS NULL);


