    REDDITO_DOMINICALE,
    SUB_UC,
    QUAL_CAT,
    CLASSE_TERRENO,
    PARTITA,
    ATTO_INI,
    ATTO_FIN
)
BEQUEATH DEFINER
AS
    SELECT c.id_cat,
           CATALOG_DATA.GETCODEPRGC (c.CODICE)     AS codice,
           c.SUPE_INTE,
