DROP VIEW SITI_H501.STATOFAM;

/* Formatted on 18/07/2022 12:23:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.STATOFAM
(
    COD_INQ,
    COGN_NOME,
    PROFES,
    REDDITO_DI,
    REDDITO_AU,
    PENSIONE,
    DETRAZIO,
    COD_FISC,
    NATO_A,
    PROV_NATO_A,
    NATO_IL,
    ID,
    NOTE_COMP,
    ESCLUDI_COMP,
    TIPO_COMP,
    OSP_DATA_ENT,
    OSP_SCAD,
    OSP_USCITA
)
BEQUEATH DEFINER
AS
    WITH
        redditi_sogg
        AS
            (  SELECT cod_soggetto,
                      SUM (reddito_lav_dip)     AS reddito_lav_dip,
                      SUM (reddito_lav_aut)     AS reddito_lav_aut,
                      SUM (reddito_pens)        AS reddito_pens
                 FROM patri_anag_redditi a
                WHERE data_fine_val >= SYSDATE
             GROUP BY cod_soggetto)
    SELECT DISTINCT
           CAST (s2.cod_soggetto AS VARCHAR2 (10))    AS cod_inq,
           s.denominazione                            AS cogn_nome,
           CAST (NULL AS VARCHAR2 (30))               AS profes,
           NVL (redditi_sogg.reddito_lav_dip, 0)      AS reddito_di,
           NVL (redditi_sogg.reddito_lav_aut, 0)      AS reddito_au,
           NVL (redditi_sogg.reddito_pens, 0)         AS pensione,
           CASE
               WHEN r.fkcod_ruolo <= -101 AND r.fkcod_ruolo >= -199 THEN 'C'
               ELSE NULL
           END                                        AS detrazio,
           s.cod_fiscale                              AS cod_fisc,
           c.nome                                     AS nato_a,
           c.sigla_prov                               AS prov_nato_a,
           s.d_nascita                                AS nato_il,
           CAST (0 AS NUMBER)                         AS ID,
           CAST (NULL AS VARCHAR2 (255))              AS note_comp,
           'N'                                        AS escludi_comp,
           CASE
               WHEN r.fkcod_ruolo <= -301 AND r.fkcod_ruolo >= -399 THEN '1'
               ELSE '0'
           END                                        AS tipo_comp,
           CAST (NULL AS DATE)                        AS osp_data_ent,
           CAST (NULL AS DATE)                        AS osp_scad,
           CAST (NULL AS DATE)                        AS osp_uscita
      FROM anag_relazioni  r,
           anag_soggetti   s,
           anag_relazioni  r2,
           anag_soggetti   s2,
           redditi_sogg,
           siticomu_istat  c
     WHERE     r.pktipo_rel = -100
           AND s.cod_soggetto = r.pkcod_sogg
           AND s.data_inizio_val <= SYSDATE
           AND s.data_fine_val >= SYSDATE
           AND r.data_inizio_val <= SYSDATE
           AND r.data_fine_val = TO_DATE ('31129999', 'ddmmyyyy')
           AND r2.pkid_relazione = r.pkid_relazione
           AND s2.cod_soggetto = r2.pkcod_sogg
           AND s2.data_inizio_val <= SYSDATE
           AND r2.data_inizio_val <= SYSDATE
           AND s2.data_fine_val >= SYSDATE
           AND r2.data_fine_val = TO_DATE ('31129999', 'ddmmyyyy')
           AND redditi_sogg.cod_soggetto(+) = s.cod_soggetto
           AND c.codi_fisc_luna(+) = s.fkcod_comu_nasc
    UNION
    SELECT DISTINCT
           CAST (asogg.cod_soggetto AS VARCHAR2 (10))     AS cod_inq,
           asogg.denominazione                            AS cogn_nome,
           CAST (NULL AS VARCHAR2 (30))                   AS profes,
           NVL (redditi_sogg.reddito_lav_dip, 0)          AS reddito_di,
           NVL (redditi_sogg.reddito_lav_aut, 0)          AS reddito_au,
           NVL (redditi_sogg.reddito_pens, 0)             AS pensione,
           'C'                                            AS detrazio,
           asogg.cod_fiscale                              AS cod_fisc,
           c.nome                                         AS nato_a,
           c.sigla_prov                                   AS prov_nato_a,
           asogg.d_nascita                                AS nato_il,
           CAST (0 AS NUMBER)                             AS ID,
           CAST (NULL AS VARCHAR2 (255))                  AS note_comp,
           'N'                                            AS escludi_comp,
           '0'                                            AS tipo_comp,
           CAST (NULL AS DATE)                            AS osp_data_ent,
           CAST (NULL AS DATE)                            AS osp_scad,
           CAST (NULL AS DATE)                            AS osp_uscita
      FROM anag_soggetti asogg, siticomu_istat c, redditi_sogg
     WHERE     asogg.cod_soggetto NOT IN (SELECT pkcod_sogg
                                            FROM anag_relazioni
                                           WHERE PKTIPO_REL = -100)
           AND ASOGG.DATA_INIZIO_VAL <= TO_DATE ('31129999', 'ddmmyyyy')
           AND ASOGG.DATA_FINE_VAL >= TO_DATE ('31129999', 'ddmmyyyy')
           AND c.codi_fisc_luna(+) = ASOGG.fkcod_comu_nasc
           AND redditi_sogg.cod_soggetto(+) = asogg.cod_soggetto;


DROP VIEW SITI_H501.TERRE05;

/* Formatted on 18/07/2022 12:23:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.TERRE05
(
    COD_CES,
    COMUNE,
    PARTITA,
    PROGR,
    FOGLIO,
    NUMERO,
    SUBALTERNO,
    SUP_ETTARI,
    SUP_ARE,
    SUP_CENTIA,
    QUALITA,
    REDDITO,
    RED_DOMIN,
    RED_AGRAR,
    SERV_ATT,
    SERV_PAS,
    DQUALITA,
    TIPO_PARTI,
    CONSISTENZA,
    RAP_CONS,
    ID,
    COD_NAZIONALE,
    NOTE,
    CLASSE,
    PROTOC,
    ANNO_PROT,
    RED_DOMIN_CATASTO,
    RED_AGRAR_CATASTO,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    DAVARIAZIONE,
    FLAG_CATA,
    PARTITA_TAVOLARE,
    CORPO_TAVOLARE,
    PORZIONE_MATERIALE
)
BEQUEATH DEFINER
AS
    SELECT part.cod_ces,
           part.comune,
           part.partita,
           part.progr,
           part.foglio,
           part.numero,
           part.subalterno,
           part.sup_ettari,
           part.sup_are,
           part.sup_centia,
           part.qualita,
           part.reddito,
           part.red_domin,
           part.red_agrar,
           part.serv_att,
           part.serv_pas,
           part.dqualita,
           part.tipo_parti,
           part.consistenza,
           part.rap_cons,
           part.ID,
           part.cod_nazionale,
           part.note,
           part.classe,
           part.protoc,
           part.anno_prot,
           part.red_domin_catasto,
           part.red_agrar_catasto,
           part.data_inizio_val,
           part.data_fine_val,
           part.davariazione,
           part.flag_cata,
           CASE WHEN part.flag_cata = 1 THEN part.foglio ELSE NULL END
               AS partita_tavolare,
           CASE WHEN part.flag_cata > 0 THEN sp.tavola ELSE NULL END
               AS corpo_tavolare,
           NULL
               AS porzione_materiale
      FROM (SELECT c.cod_cespite
                       AS cod_ces,
                   sc.nome
                       AS comune,
                   p.partita,
                   NULL
                       AS progr,
                   p.foglio,
                   p.particella
                       AS numero,
                   p.sub
                       AS subalterno,
                   conversion_utils_pck.metri2ettari_round (p.area_part)
                       AS sup_ettari,
                   conversion_utils_pck.metri2are_round (p.area_part)
                       AS sup_are,
                   conversion_utils_pck.metri2centiare_round (p.area_part)
                       AS sup_centia,
                   p.qual_cat
                       AS qualita,
                   CAST (p.rendita AS NUMBER)
                       AS reddito,
                   p.reddito_dominicale / (t.perc_poss / 100)
                       AS red_domin,
                   p.reddito_agrario / (t.perc_poss / 100)
                       AS red_agrar,
                   NULL
                       AS serv_att,
                   NULL
                       AS serv_pas,
                   NULL
                       AS dqualita,
                   NULL
                       AS tipo_parti,
                   CAST (t.perc_poss AS NUMBER)
                       AS consistenza,
                   100
                       AS rap_cons,
                   t.pkid_cons
                       AS ID,
                   p.cod_nazionale,
                   p.annotazioni
                       AS note,
                   p.classe_terreno
                       AS classe,
                   NULL
                       AS protoc,
                   NULL
                       AS anno_prot,
                   CAST (p.reddito_dominicale AS NUMBER)
                       AS red_domin_catasto,
                   CAST (p.reddito_agrario AS NUMBER)
                       AS red_agrar_catasto,
                   TRUNC (GREATEST (p.data_aggi, c.data_inizio_val), 'DDD')
                       AS data_inizio_val,
                   CASE
                       WHEN TRUNC (LEAST (p.data_fine, c.data_fine_val),
                                   'DDD') =
                            TO_DATE ('99991231', 'yyyymmdd')
                       THEN
                           TO_DATE (NULL)
                       ELSE
                           TRUNC (
                               LEAST ((p.data_fine + (1 / 24 / 60 / 60)) - 1,
                                      c.data_fine_val),
                               'DDD')
                   END
                       AS data_fine_val,
                   '1'
                       AS davariazione,
                   sc.flag_cata,
                   p.data_fine
                       AS data_fine_part
              FROM patri_cespiti       c,
                   patri_cespiti_part  cp,
                   sititrkc            p,
                   cons_cons_tab       t,
                   siticomu            sc
             WHERE     cp.fk_cespite = c.pk_cespite
                   AND t.pkid_cons = cp.pk_tit
                   AND t.tipo_titolo = cp.tipo_titolo
                   AND p.cod_nazionale = t.cod_nazionale
                   AND p.foglio = t.foglio
                   AND p.particella = t.particella
                   AND p.sub = t.sub
                   AND p.data_aggi < t.data_fine
                   AND p.data_fine > t.data_inizio
                   AND t.data_inizio < c.data_fine_val
                   AND t.data_fine > c.data_inizio_val
                   AND sc.cod_nazionale = t.cod_nazionale
                   AND TRUNC (GREATEST (p.data_aggi, c.data_inizio_val),
                              'DDD') !=
                       TRUNC (
                             LEAST (p.data_fine, c.data_fine_val)
                           + (1 / 24 / 60 / 60),
                           'DDD')
            UNION
            SELECT c.cod_cespite
                       AS cod_ces,
                   sc.nome
                       AS comune,
                   p.partita,
                   NULL
                       AS progr,
                   p.foglio,
                   p.particella
                       AS numero,
                   p.sub
                       AS subalterno,
                   conversion_utils_pck.metri2ettari_round (p.area_part)
                       AS sup_ettari,
                   conversion_utils_pck.metri2are_round (p.area_part)
                       AS sup_are,
                   conversion_utils_pck.metri2centiare_round (p.area_part)
                       AS sup_centia,
                   p.qual_cat
                       AS qualita,
                   CAST (p.rendita AS NUMBER)
                       AS reddito,
                   p.reddito_dominicale / (t.perc_poss / 100)
                       AS red_domin,
                   p.reddito_agrario
                       AS red_agrar,
                   NULL
                       AS serv_att,
                   NULL
                       AS serv_pas,
                   NULL
                       AS dqualita,
                   NULL
                       AS tipo_parti,
                   CAST (t.perc_poss AS NUMBER)
                       AS consistenza,
                   100
                       AS rap_cons,
                   t.pkid_uffr
                       AS ID,
                   p.cod_nazionale,
                   p.annotazioni
                       AS note,
                   p.classe_terreno
                       AS classe,
                   NULL
                       AS protoc,
                   NULL
                       AS anno_prot,
                   CAST (p.reddito_dominicale AS NUMBER)
                       AS red_domin_catasto,
                   CAST (p.reddito_agrario AS NUMBER)
                       AS red_agrar_catasto,
                   TRUNC (GREATEST (p.data_aggi, c.data_inizio_val), 'DDD')
                       AS data_inizio_val,
                   CASE
                       WHEN TRUNC (LEAST (p.data_fine, c.data_fine_val),
                                   'DDD') =
                            TO_DATE ('99991231', 'yyyymmdd')
                       THEN
                           TO_DATE (NULL)
                       ELSE
                           TRUNC (
                               LEAST ((p.data_fine + (1 / 24 / 60 / 60)) - 1,
                                      c.data_fine_val),
                               'DDD')
                   END
                       AS data_fine_val,
                   '1'
                       AS davariazione,
                   sc.flag_cata,
                   p.data_fine
                       AS data_fine_part
              FROM patri_cespiti       c,
                   patri_cespiti_part  cp,
                   sititrkc            p,
                   cons_ufre_tab       t,
                   siticomu            sc
             WHERE     cp.fk_cespite = c.pk_cespite
                   AND t.pkid_uffr = cp.pk_tit
                   AND t.tipo_titolo = cp.tipo_titolo
                   AND p.cod_nazionale = t.cod_nazionale
                   AND p.foglio = t.foglio
                   AND p.particella = t.particella
                   AND p.sub = t.sub
                   AND p.data_aggi < t.data_fine
                   AND p.data_fine > t.data_inizio
                   AND t.data_inizio < c.data_fine_val
                   AND t.data_fine > c.data_inizio_val
                   AND sc.cod_nazionale = t.cod_nazionale
                   AND TRUNC (GREATEST (p.data_aggi, c.data_inizio_val),
                              'DDD') !=
                       TRUNC (
                           LEAST ((p.data_fine + (1 / 24 / 60 / 60)) - 1,
                                  c.data_fine_val),
                           'DDD')) part,
           sitipart  sp
     WHERE     part.cod_nazionale = sp.cod_nazionale(+)
           AND part.foglio = sp.foglio(+)
           AND part.numero = sp.particella(+)
           AND part.subalterno = sp.sub(+)
           AND part.data_fine_part >= sp.data_inizio_val(+)
           AND part.data_fine_part <= sp.data_fine_val(+);


DROP VIEW SITI_H501.UISITIRPAN_CUAA;

/* Formatted on 18/07/2022 12:23:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.UISITIRPAN_CUAA
(
    CUAA,
    ISTAT_PROV,
    COD_NAZIONALE,
    FOGLIO,
    ANOM21,
    ANOM22,
    ANOM23,
    ANOM24,
    ANOM25,
    ANOM26,
    ANOM27,
    ANOM28,
    ANOM29,
    ANOM30
)
BEQUEATH DEFINER
AS
      SELECT CUAA,
             ISTAT_PROV,
             COD_NAZIONALE,
             FOGLIO,
             SUM (DECODE (BITAND (FLAG_ANOM, 1), 1, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 2), 2, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 4), 4, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 8), 8, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 16), 16, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 32), 32, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 64), 64, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 128), 128, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 256), 256, 1, 0)),
             SUM (DECODE (BITAND (FLAG_ANOM, 512), 512, 1, 0))
        FROM UISITIRPAN_CUAA_TAB
    GROUP BY ISTAT_PROV,
             COD_NAZIONALE,
             FOGLIO,
             CUAA;


DROP VIEW SITI_H501.URBA04;

/* Formatted on 18/07/2022 12:23:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.URBA04
(
    COD_CES,
    COMUNE,
    PARTITA,
    SEZIONE,
    FOGLIO,
    NUMERO,
    DENOMINATORE,
    SUBALTERNO,
    STADIO,
    ZONA,
    CATEGORIA1,
    CATEGORIA2,
    CLASSE,
    RENDITA_CATASTO,
    RENDITA,
    VANI,
    CONSISTENZ,
    RAP_CONS,
    DATA_MODI,
    PROTOC,
    ANNO_PROT,
    SERV_ATT,
    SERV_PAS,
    TIPO_PARTI,
    ID,
    COD_NAZIONALE,
    NOTE,
    MICROZONA,
    SUP_CAT,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    DAVARIAZIONE,
    FLAG_CATA,
    PARTITA_TAVOLARE,
    CORPO_TAVOLARE,
    PORZIONE_MATERIALE
)
BEQUEATH DEFINER
AS
    SELECT uiu.cod_ces,
           uiu.comune,
           uiu.partita,
           uiu.sezione,
           uiu.foglio,
           uiu.numero,
           uiu.denominatore,
           uiu.subalterno,
           uiu.stadio,
           uiu.zona,
           uiu.categoria1,
           uiu.categoria2,
           uiu.classe,
           uiu.rendita_catasto,
           uiu.rendita,
           uiu.vani,
           uiu.consistenz,
           uiu.rap_cons,
           uiu.data_modi,
           uiu.protoc,
           uiu.anno_prot,
           uiu.serv_att,
           uiu.serv_pas,
           uiu.tipo_parti,
           uiu.ID,
           uiu.cod_nazionale,
           uiu.note,
           uiu.microzona,
           uiu.sup_cat,
           uiu.data_inizio_val,
           uiu.data_fine_val,
           uiu.davariazione,
           uiu.flag_cata,
           CASE WHEN uiu.flag_cata = 1 THEN uiu.foglio ELSE NULL END
               AS partita_tavolare,
           CASE WHEN uiu.flag_cata > 0 THEN sp.tavola ELSE NULL END
               AS corpo_tavolare,
           NULL
               AS porzione_materiale
      FROM (SELECT c.cod_cespite                          AS cod_ces,
                   sc.nome                                AS comune,
                   u.partita,
                   sc.sezione_censuaria                   AS sezione,
                   u.foglio,
                   u.particella                           AS numero,
                   u.sub                                  AS denominatore,
                   CASE
                       WHEN u.unimm >= 90000
                       THEN
                           '(' || (u.unimm - 90000) || ')'
                       ELSE
                           TO_CHAR (u.unimm)
                   END                                    AS subalterno,
                   NULL                                   AS stadio,
                   u.zona,
                   SUBSTR (u.categoria, 1, 1)             AS categoria1,
                   TO_NUMBER (SUBSTR (u.categoria, 2))    AS categoria2,
                   u.classe,
                   CAST (u.rendita AS NUMBER)             AS rendita_catasto,
                   (u.rendita / (t.perc_poss / 100))      AS rendita,
                   CAST (u.consistenza AS NUMBER)         AS vani,
                   CAST (t.perc_poss AS NUMBER)           AS consistenz,
                   100                                    AS rap_cons,
                   u.data_lav                             AS data_modi,
                   NULL                                   AS protoc,
                   NULL                                   AS anno_prot,
                   NULL                                   AS serv_att,
                   NULL                                   AS serv_pas,
                   NULL                                   AS tipo_parti,
                   t.pkid_csui                            AS ID,
                   u.cod_nazionale,
                   u.note,
                   u.microzona,
                   CAST (u.sup_cat AS NUMBER)             AS sup_cat,
                   TRUNC (u.data_inizio_val, 'DDD')       AS data_inizio_val,
                   CASE
                       WHEN TRUNC (LEAST (u.data_fine_val, t.data_fine),
                                   'DDD') =
                            TO_DATE ('99991231', 'yyyymmdd')
                       THEN
                           TO_DATE (NULL)
                       WHEN   TRUNC (
                                    LEAST (u.data_fine_val, t.data_fine)
                                  + (1 / 24 / 60 / 60),
                                  'DDD')
                            - 1 <
                            TRUNC (u.data_inizio_val + (1 / 24 / 60 / 60),
                                   'DDD')
                       THEN
                           TRUNC (u.data_inizio_val, 'DDD')
                       ELSE
                             TRUNC (
                                   LEAST (u.data_fine_val, t.data_fine)
                                 + (1 / 24 / 60 / 60),
                                 'DDD')
                           - 1
                   END                                    AS data_fine_val,
                   '1'                                    AS davariazione,
                   sc.flag_cata,
                   u.data_fine_val                        AS data_fine_uiu
              FROM patri_cespiti      c,
                   patri_cespiti_uiu  cu,
                   sitiuiu            u,
                   cons_csui_tab      t,
                   siticomu           sc
             WHERE     cu.fk_cespite = c.pk_cespite
                   AND t.pkid_csui = cu.pk_tit
                   AND t.tipo_titolo = cu.tipo_titolo
                   AND u.cod_nazionale = t.cod_nazionale
                   AND u.foglio = t.foglio
                   AND u.particella = t.particella
                   AND u.sub = t.sub
                   AND u.unimm = t.unimm
                   AND u.data_fine_val =
                       (SELECT MAX (data_fine_val)
                          FROM sitiuiu
                         WHERE     cod_nazionale = t.cod_nazionale
                               AND foglio = t.foglio
                               AND particella = t.particella
                               AND sub = t.sub
                               AND unimm = t.unimm
                               AND data_inizio_val <= t.data_fine)
                   AND sc.cod_nazionale = t.cod_nazionale
                   AND TRUNC (c.data_fine_val, 'ddd') >=
                       TRUNC (t.data_INIZIO, 'ddd')
                   AND TRUNC (c.data_INIZIO_val, 'ddd') <=
                       TRUNC (t.data_FINE, 'ddd')
            UNION ALL
            SELECT c.cod_cespite                        AS cod_ces,
                   sc.nome                              AS comune,
                   u.partita,
                   sc.sezione_censuaria                 AS sezione,
                   u.foglio,
                   u.particella                         AS numero,
                   u.sub                                AS denominatore,
                   CASE
                       WHEN u.unimm >= 90000
                       THEN
                           '(' || (u.unimm - 90000) || ')'
                       ELSE
                           TO_CHAR (u.unimm)
                   END                                  AS subalterno,
                   NULL                                 AS stadio,
                   u.zona,
                   SUBSTR (u.categoria, 1, 1)           AS categoria1,
                   TO_NUMBER (SUBSTR (u.categoria, 2)),
                   u.classe,
                   CAST (u.rendita AS NUMBER)           AS rendita_catasto,
                   (u.rendita / (t.perc_poss / 100))    AS rendita,
                   CAST (u.consistenza AS NUMBER)       AS vani,
                   CAST (t.perc_poss AS NUMBER)         AS consistenz,
                   100                                  AS rap_cons,
                   u.data_lav                           AS data_modi,
                   NULL                                 AS protoc,
                   NULL                                 AS anno_prot,
                   NULL                                 AS serv_att,
                   NULL                                 AS serv_pas,
                   NULL                                 AS tipo_parti,
                   t.pkid_urui                          AS ID,
                   u.cod_nazionale,
                   u.note,
                   u.microzona,
                   CAST (u.sup_cat AS NUMBER)           AS sup_cat,
                   TRUNC (u.data_inizio_val, 'DDD')     AS data_inizio_val,
                   CASE
                       WHEN TRUNC (LEAST (u.data_fine_val, t.data_fine),
                                   'DDD') =
                            TO_DATE ('99991231', 'yyyymmdd')
                       THEN
                           TO_DATE (NULL)
                       WHEN   TRUNC (
                                    LEAST (u.data_fine_val, t.data_fine)
                                  + (1 / 24 / 60 / 60),
                                  'DDD')
                            - 1 <
                            TRUNC (u.data_inizio_val + (1 / 24 / 60 / 60),
                                   'DDD')
                       THEN
                           TRUNC (u.data_inizio_val, 'DDD')
                       ELSE
                             TRUNC (
                                   LEAST (u.data_fine_val, t.data_fine)
                                 + (1 / 24 / 60 / 60),
                                 'DDD')
                           - 1
                   END                                  AS data_fine_val,
                   '1'                                  AS davariazione,
                   sc.flag_cata,
                   u.data_fine_val                      AS data_fine_uiu
              FROM patri_cespiti      c,
                   patri_cespiti_uiu  cu,
                   sitiuiu            u,
                   cons_urui_tab      t,
                   siticomu           sc
             WHERE     cu.fk_cespite = c.pk_cespite
                   AND t.pkid_urui = cu.pk_tit
                   AND t.tipo_titolo = cu.tipo_titolo
                   AND u.cod_nazionale = t.cod_nazionale
                   AND u.foglio = t.foglio
                   AND u.particella = t.particella
                   AND u.sub = t.sub
                   AND u.unimm = t.unimm
                   AND u.data_fine_val =
                       (SELECT MAX (data_fine_val)
                          FROM sitiuiu
                         WHERE     cod_nazionale = t.cod_nazionale
                               AND foglio = t.foglio
                               AND particella = t.particella
                               AND sub = t.sub
                               AND unimm = t.unimm
                               AND data_inizio_val <= t.data_fine)
                   AND sc.cod_nazionale = t.cod_nazionale
                   AND TRUNC (c.data_fine_val, 'ddd') >=
                       TRUNC (t.data_INIZIO, 'ddd')
                   AND TRUNC (c.data_INIZIO_val, 'ddd') <=
                       TRUNC (t.data_FINE, 'ddd')) uiu,
           sitipart  sp
     WHERE     uiu.cod_nazionale = sp.cod_nazionale(+)
           AND uiu.foglio = sp.foglio(+)
           AND uiu.numero = sp.particella(+)
           AND uiu.denominatore = sp.sub(+)
           AND uiu.data_fine_uiu >= sp.data_inizio_val(+)
           AND uiu.data_fine_uiu <= sp.data_fine_val(+);


DROP VIEW SITI_H501.VANAGRAFICA;

/* Formatted on 18/07/2022 12:23:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.VANAGRAFICA
(
    CODICE_SOGGETTO,
    CUAA,
    COD_FISCALE,
    PART_IVA,
    DENOMINAZIONE,
    NOME,
    SESSO,
    D_NASCITA,
    D_MORTE,
    FKCOD_COMU_NASC,
    FLAG_PERS_FISICA,
    FKRAPP_LEGALE,
    PK_CIVI,
    INDIRIZZO,
    NOME_COMUNE,
    SIGLA_PROVINCIA,
    FKCOD_COMU_RESI,
    DATA_FINE_VAL,
    DATA_INIZIO_VAL,
    DATA_LAV,
    UTENTE_INIZIO,
    UTENTE_FINE,
    VALIDO_INIZIO,
    VALIDO_FINE,
    ATTO_INIZIO,
    ATTO_FINE,
    NATURA_GIURIDICA,
    RAPP_LEGALE,
    COD_FISC_RAPP_LEGALE,
    COGNOME_RAPP_LEGALE,
    NOME_RAPP_LEGALE
)
BEQUEATH DEFINER
AS
    SELECT s.cod_soggetto
               AS codice_soggetto,
           a.cuaa,
           s.cod_fiscale,
           s.part_iva,
           s.denominazione,
           s.nome,
           s.sesso,
           s.d_nascita,
           s.d_morte,
           s.fkcod_comu_nasc,
           s.flag_pers_fisica,
           s.fkrapp_legale,
           civi.pk_civi,
           DECODE (
               civi.pk_civi,
               NULL, s.indirizzo_est,
               TRIM (
                      civi.pre_strada
                   || ' '
                   || civi.nome_strada
                   || ' '
                   || civi.civico))
               AS indirizzo,
           c.nome
               AS nome_comune,
           c.sigla_prov
               AS sigla_provincia,
           s.fkcod_comu_resi,
           s.data_fine_val,
           s.data_inizio_val,
           s.data_lav,
           s.utente_inizio,
           s.utente_fine,
           s.valido_inizio,
           s.valido_fine,
           s.atto_inizio,
           s.atto_fine,
           n.descrizione
               AS natura_giuridica,
           TRIM (l.denominazione || ' ' || l.nome)
               AS rapp_legale,
           l.cod_fiscale
               AS cod_fisc_rapp_legale,
           l.denominazione
               AS cognome_rapp_legale,
           l.nome
               AS nome_rapp_legale
      FROM cons_azie_tab     a,
           natura_giuridica  n,
           anag_soggetti     s,
           siticomu_v        c,
           (SELECT civ.pkid_civi           pk_civi,
                   civ.civico              civico,
                   str.nome                nome_strada,
                   str.prefisso            pre_strada,
                   civ.data_inizio_val     civico_data_inizio,
                   civ.data_fine_val       civico_data_fine,
                   str.data_inizio_val     str_data_inizio,
                   str.data_fine_val       str_data_fine
              FROM siticivi civ, sitidstr str
             WHERE civ.pkid_stra = str.pkid_stra) civi,
           anag_soggetti     l
     WHERE     s.fkcivico_resi = civi.pk_civi(+)
           AND a.pk_cuaa = s.cod_soggetto
           AND n.codice(+) = s.natura_giuridica
           AND s.data_fine_val > civi.civico_data_inizio(+)
           AND s.data_fine_val <= civi.civico_data_fine(+)
           AND s.data_fine_val > civi.str_data_inizio(+)
           AND s.data_fine_val <= civi.str_data_fine(+)
           AND s.fkrapp_legale = l.cod_soggetto(+)
           AND s.data_fine_val > l.data_inizio_val(+)
           AND s.data_fine_val <= l.data_fine_val(+)
           AND s.fkcod_comu_resi = c.codi_fisc_luna(+)
WITH READ ONLY;


