DROP VIEW SITI_H501.VATTI_REPORT;

/* Formatted on 18/07/2022 12:23:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.VATTI_REPORT
(
    ID_ATTO,
    DESCRIZIONE_ATTO,
    DESCRIZIONE_DOCUMENTO,
    DESCRIZIONE_BREVE,
    COD_ARCHIVIAZIONE,
    OBBLIGATORIO,
    DATA_AGGIORNAMENTO,
    PRESENTE
)
BEQUEATH DEFINER
AS
    SELECT atti.pkid_atto        id_atto,
           tatto.descrizione     descrizione_atto,
           tdoc.descrizione      descrizione_documento,
           doc.descrizione_breve,
           doc.cod_archiviazione,
           tatto_doc.obbligatorio,
           att_doc.data_aggiornamento,
           'PRESENTE'            AS presente
      FROM SITIFILE_ATTI           atti,
           SITIFILE_TIPI_ATTO      tatto,
           SITIFILE_TIPI_ATTO_DOC  tatto_doc,
           SITIFILE_TIPIDOC        tdoc,
           SITIFILE_DOCUMENTI      doc,
           SITIFILE_ATTI_DOC       att_doc
     WHERE     atti.fkid_tipo_atto = tatto.pkid_tipo
           AND atti.pkid_atto = att_doc.fkid_atto
           AND att_doc.fkid_doc = doc.pkid_doc
           AND doc.fkid_tipo_doc = tdoc.pkid_tipo_doc
           AND tatto_doc.fkid_tipo_atto = tatto.pkid_tipo
           AND tatto_doc.fkid_tipo_doc = tdoc.pkid_tipo_doc
           AND SYSDATE BETWEEN tatto_doc.data_inizio_val
                           AND tatto_doc.data_fine_val
    UNION ALL
    SELECT atti.pkid_atto        id_atto,
           tatto.descrizione     descrizione_atto,
           tdoc.descrizione      descrizione_documento,
           ''                    descrizione_breve,
           ''                    cod_archiviazione,
           tatto_doc.obbligatorio,
           NULL                  data_aggiornamento,
           'NON PRESENTE'        AS presente
      FROM SITIFILE_ATTI           atti,
           SITIFILE_TIPI_ATTO      tatto,
           SITIFILE_TIPI_ATTO_DOC  tatto_doc,
           SITIFILE_TIPIDOC        tdoc
     WHERE     atti.fkid_tipo_atto = tatto.pkid_tipo
           AND tatto.pkid_tipo = tatto_doc.fkid_tipo_atto
           AND tatto_doc.fkid_tipo_doc = tdoc.pkid_tipo_doc
           AND SYSDATE BETWEEN tatto_doc.data_inizio_val
                           AND tatto_doc.data_fine_val
           AND NOT EXISTS
                   (SELECT 1
                      FROM sitifile_documenti d, sitifile_atti_doc adoc
                     WHERE     d.fkid_tipo_doc = tdoc.pkid_tipo_doc
                           AND d.pkid_doc = adoc.fkid_doc
                           AND adoc.fkid_atto = atti.pkid_atto);


