/* Formatted on 18/07/2022 12:23:00 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.VIE
(
    CODCOMUN,
    CODVIA,
    DENOM,
    COMUNE,
    TIPO_V,
    CAP,
    CIRCOSCRIZIONE,
    QUARTIERE,
    ZONA_URBANA,
    SEZIONE_CENS,
    ISOLATO
)
BEQUEATH DEFINER
AS
    SELECT v.COD_NAZIONALE                        AS CODCOMUN,
           v.NUMERO                               AS CODVIA,
           TRIM (v.prefisso || ' ' || v.NOME)     AS DENOM,
           ci.nome                                AS COMUNE,
           NULL                                   AS TIPO_V,
           V.CAP,
           NULL                                   AS CIRCOSCRIZIONE,
           NULL                                   AS QUARTIERE,
           NULL                                   AS ZONA_URBANA,
           NULL                                   AS SEZIONE_CENS,
           NULL                                   AS ISOLATO
      FROM aggr_topo v, siticomu c, siticomu_istat ci
     WHERE     v.aggr_code = 1
           AND c.cod_nazionale = v.cod_nazionale
           AND ci.CODI_FISC_LUNA = c.CODI_FISC_LUNA
