  IF NOT au.equals (:OLD.com_inqui, :NEW.com_inqui) THEN
    UPDATE patri_loc_tipo_contr
       SET fl_comunica_agg_canone = :NEW.com_inqui
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  -- verifico se i multicontratti sono attivi
  BEGIN
    SELECT UPPER (valore)
      INTO m_multiple_rent
      FROM gisparams
     WHERE variabile = 'MULTIPLE_RENT';
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      m_multiple_rent := 'NO';
  END;

  IF NOT au.equals (:OLD.cessazione, :NEW.cessazione) THEN
    IF (:NEW.cessazione IS NULL AND m_multiple_rent = 'NO') THEN
      -- Riapro il contratto...
      -- Controllo che non ne esista uno successivo
      SELECT COUNT (*)
        INTO cnt
        FROM cons_ufre_tab t, cons_ufre_tab t2
       WHERE t.atto_ini = :OLD.codice AND t2.cod_nazionale = t.cod_nazionale AND t2.foglio = t.foglio
             AND t2.particella = t.particella AND t2.sub = t.sub AND t2.atto_ini != :OLD.codice
             AND t2.data_inizio > t.data_inizio;

      IF cnt > 0 THEN
        raise_application_error (-20005, 'Impossibile togliere la cessazione, esiste un contratto successivo!');
      END IF;

      SELECT COUNT (*)
        INTO cnt
        FROM cons_urui_tab t, cons_urui_tab t2
       WHERE t.atto_ini = :OLD.codice AND t.fl_totale = 'Y' AND t2.cod_nazionale = t.cod_nazionale
             AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub AND t2.unimm = t.unimm
             AND t2.fl_totale = 'Y' AND t2.atto_ini != :OLD.codice AND t2.data_inizio > t.data_inizio;

      IF cnt > 0 THEN
        raise_application_error (-20005, 'Impossibile togliere la cessazione, esiste un contratto successivo!');
      END IF;
    ELSIF (:NEW.cessazione IS NOT NULL) THEN
      -- verifico se il contratto  associato ad una sublocazione in essere
      SELECT COUNT (*)
        INTO exist_subloc
        FROM cons_subloc_tab
       WHERE fkid_atto = CAST (:NEW.codice AS NUMBER) AND data_inizio < :NEW.cessazione AND data_fine > :NEW.cessazione;

      IF (exist_subloc > 0) THEN
        raise_application_error
                         (-20011,
                          'Non  possibile cessare il contratto di locazione:  in corso di validit una sublocazione.');
      END IF;

      -- Controllo che non cessi prima dell'inizio...
      SELECT MAX (data_inizio)
        INTO max_dt
        FROM (SELECT data_inizio
                FROM cons_urui_tab
               WHERE atto_ini = :OLD.codice
              UNION
              SELECT data_inizio
                FROM cons_ufre_tab
               WHERE atto_ini = :OLD.codice);

      IF (max_dt > :NEW.cessazione) THEN
        raise_application_error (-20004, 'Data cessazione minore di data contratto!');
      END IF;

      IF :OLD.cessazione >= dt_att THEN
        -- se era attuale controllo che non esista un altro contratto...
        IF (m_multiple_rent = 'NO') THEN
          SELECT COUNT (*)
            INTO cnt
            FROM cons_ufre_tab t, cons_ufre_tab t2
           WHERE t.atto_ini = :OLD.codice AND t2.cod_nazionale = t.cod_nazionale AND t2.foglio = t.foglio
                 AND t2.particella = t.particella AND t2.sub = t.sub AND t2.atto_ini != :OLD.codice
                 AND t2.data_inizio < :NEW.cessazione AND t2.data_fine > :NEW.cessazione;

          IF cnt = 0 THEN
            -- per le UIU controllo solo i contratti "totali"
            SELECT COUNT (*)
              INTO cnt
              FROM cons_urui_tab t, cons_urui_tab t2
             WHERE t.atto_ini = :OLD.codice AND t.fl_totale = 'Y' AND t2.cod_nazionale = t.cod_nazionale
                   AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub AND t2.unimm = t.unimm
                   AND t2.fl_totale = 'Y' AND t2.atto_ini ! = :OLD.codice AND t2.data_inizio < :NEW.cessazione
                   AND t2.data_fine > :NEW.cessazione;
          END IF;

          IF cnt > 0 THEN
            -- esiste gi un contratto successivo....
            raise_application_error (-20004, 'Esiste un contratto in vigore alla data specificata!');
          END IF;
        END IF;
      END IF;
    END IF;

    -- Modifico i dati
    max_dt := NULL;

    IF (:NEW.cessazione IS NULL) THEN
      -- Tolgo cessazione, riapro solo quelli che hanno max(data_fine)
      -- perch sono quelli che sono stati precedentemente cessati
      SELECT MAX (data_fine)
        INTO max_dt
        FROM (SELECT data_fine
                FROM cons_urui_tab
               WHERE atto_ini = :OLD.codice
              UNION
              SELECT data_fine
                FROM cons_ufre_tab
               WHERE atto_ini = :OLD.codice);
    ELSE
      -- Imposto cessazione...
      IF (:OLD.cessazione IS NULL) THEN
        -- Era un contratto attivo...
        max_dt := dt_att;
      ELSE
        -- Era gi cessato, sto spostando la data per correzione...
        max_dt := :OLD.cessazione;
      END IF;
    END IF;

    UPDATE cons_ufre_tab
       SET data_fine = NVL (:NEW.cessazione, dt_att)
     WHERE atto_ini = :OLD.codice AND data_fine = max_dt;

    UPDATE cons_urui_tab
       SET data_fine = NVL (:NEW.cessazione, dt_att)
     WHERE atto_ini = :OLD.codice AND data_fine = max_dt;

    UPDATE cons_urui_vani
       SET data_fine_val = NVL (:NEW.cessazione, dt_att)
     WHERE id_atto = :OLD.codice AND data_fine_val = max_dt;

    UPDATE sitifile_documenti_campi_ext
       SET sys_loc_dt_fine = NVL (:NEW.cessazione, dt_att)
     WHERE fkid_doc = :OLD.pkid_doc;
  END IF;

  IF NOT au.equals (:OLD.accr_int_dp, :NEW.accr_int_dp) THEN
