CREATE OR REPLACE TRIGGER SITI_H501.LP_COPROPRIE_IOFU
instead of update ON SITI_H501.LP_COPROPRIE
for each row
begin
  update patri_loc_coproprie
     set perc_spese = :new.perc_proprie,
         tipo_uscita = :new.tipo_uscita, id_impreg = :new.id_impreg
   where fk_atto = :old.codice
     and pk_cuaa = :old.cod_proprie
	  and id_co = :old.id_co;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.LP_SCADENZE_IOFIU
instead of insert or update or delete ON SITI_H501.LP_SCADENZE
for each row
declare
  id_doc    pls_integer;
  code_ok   varchar2(10);
begin
  if updating then
    update patri_loc_scadenze_contr
       set pkid_scad=:new.id_scadenze, data_inizio=:new.data_dec, data_disdetta=:new.data_disdetta,
           data_fine=:new.scadenza, DATA_RIC_COM=:new.DATA_RIC_COM, DATA_SPEDIZIONE=:new.DATA_SPEDIZIONE,
           COMUNICAZIONE=:new.COMUNICAZIONE, TIPO=:new.TIPO, DATA_RILASCIO=:new.DATA_RILASCIO
     where fkid_doc=:old.fkid_doc and pkid_scad=:old.id_scadenze;
  else
    if inserting then
      code_ok := :new.codice;
    else
      code_ok := :old.codice;
    end if;

    select d.pkid_doc into id_doc
      from sitifile_atti_doc ad, sitifile_documenti d
     where ad.fkid_atto = code_ok
       and d.pkid_doc = ad.fkid_doc
       and d.FKID_TIPO_DOC = -27
       and rownum = 1;

    if inserting then
      insert into patri_loc_scadenze_contr (PKID_SCAD, FKID_DOC, DATA_INIZIO, DATA_FINE, DATA_DISDETTA, DATA_RIC_COM, DATA_SPEDIZIONE, COMUNICAZIONE,
                                            TIPO, DATA_RILASCIO)
        values (:new.id_scadenze, id_doc, :new.data_dec, :new.scadenza, :new.data_disdetta, :new.data_ric_com, :new.data_spedizione,
                :new.comunicazione, :new.tipo, :new.data_rilascio);
    else
      delete from patri_loc_scadenze_contr where pkid_scad = :old.id_scadenze and fkid_doc = id_doc;
    end if;

  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.LP_SPESE_IOFIU
instead of insert or update ON SITI_H501.LP_SPESE
for each row
begin
  if inserting then
    insert into patri_loc_spese (FK_ATTO, COD_FAT, IMPORTO, DATAINI, DATAFIN, IMPRATE, NUMTRATE, NUMPRATE, NOTE, COD_MIL, COD_BIL, CONGUAGLIO, DATAFINPREC, GRUPPO, CODRISC, ID_CONTR, COMPE_DAL, COMPE_AL, PERIODO, TIPO_COMP, ID, SOC_ASSOC, SOGG_IVA, FATTURA, SING_COD_INQ, ID_STORNATO)
      values (:new.codice, :new.COD_FAT, :new.IMPORTO, to_date(:new.DATAINI, 'dd/mm/yyyy'),
              to_date(:new.DATAFIN, 'dd/mm/yyyy'), :new.IMPRATE, :new.NUMTRATE, :new.NUMPRATE, :new.NOTE, :new.COD_MIL,
              :new.COD_BIL, :new.CONGUAGLIO, to_date(:new.DATAFINPREC, 'dd/mm/yyyy'), :new.GRUPPO, :new.CODRISC,
              :new.ID_CONTR, :new.COMPE_DAL, :new.COMPE_AL, :new.PERIODO, :new.TIPO_COMP, :new.ID,
              :new.SOC_ASSOC,
              :new.SOGG_IVA, :new.FATTURA, :new.SING_COD_INQ, :new.ID_STORNATO);
  else
    update patri_loc_spese
       set cod_fat = :new.COD_FAT, importo = :new.IMPORTO, dataini = to_date(:new.DATAINI, 'dd/mm/yyyy'),
           datafin = to_date(:new.DATAFIN, 'dd/mm/yyyy'), imprate = :new.IMPRATE, numtrate = :new.NUMTRATE,
           numprate = :new.NUMPRATE, note = :new.NOTE, cod_mil = :new.COD_MIL, cod_bil = :new.COD_BIL,
           conguaglio = :new.CONGUAGLIO, datafinprec = to_date(:new.DATAFINPREC, 'dd/mm/yyyy'), gruppo = :new.GRUPPO,
           codrisc = :new.CODRISC, id_contr = :new.ID_CONTR, compe_dal = :new.COMPE_DAL, compe_al = :new.COMPE_AL,
           periodo = :new.PERIODO, tipo_comp = :new.TIPO_COMP, soc_assoc = :new.SOC_ASSOC,
           sogg_iva = :new.SOGG_IVA, fattura = :new.FATTURA, sing_cod_inq = :new.SING_COD_INQ, id_stornato = :new.ID_STORNATO
           where fk_atto = :old.codice and id = :old.id;
  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.SCADENZE_IOFIU
instead of insert or update or delete ON SITI_H501.SCADENZE
for each row
declare
  id_doc    pls_integer;
  code_ok   varchar2(10);
begin
  if updating then
    update patri_loc_scadenze_contr
       set pkid_scad=:new.id_scadenze, data_inizio=:new.data_dec, data_disdetta=:new.data_disdetta,
           data_fine=:new.scadenza, DATA_RIC_COM=:new.DATA_RIC_COM, DATA_SPEDIZIONE=:new.DATA_SPEDIZIONE,
           COMUNICAZIONE=:new.COMUNICAZIONE, TIPO=:new.TIPO, DATA_RILASCIO=:new.DATA_RILASCIO
     where fkid_doc=:old.fkid_doc and pkid_scad=:old.id_scadenze;
  else
    if inserting then
      code_ok := :new.codice;
    else
      code_ok := :old.codice;
    end if;

    select d.pkid_doc into id_doc
      from sitifile_atti_doc ad, sitifile_documenti d
     where ad.fkid_atto = code_ok
       and d.pkid_doc = ad.fkid_doc
       and d.FKID_TIPO_DOC = -27
       and rownum = 1;

    if inserting then
      insert into patri_loc_scadenze_contr (PKID_SCAD, FKID_DOC, DATA_INIZIO, DATA_FINE, DATA_DISDETTA, DATA_RIC_COM, DATA_SPEDIZIONE, COMUNICAZIONE,
                                            TIPO, DATA_RILASCIO)
        values (:new.id_scadenze, id_doc, :new.data_dec, :new.scadenza, :new.data_disdetta, :new.data_ric_com, :new.data_spedizione,
                :new.comunicazione, :new.tipo, :new.data_rilascio);
    else
      delete from patri_loc_scadenze_contr where pkid_scad = :old.id_scadenze and fkid_doc = id_doc;
    end if;

  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.SITICIVI_TR1
instead of insert or update or delete
ON SITI_H501.SITICIVI
for each row
begin
  if inserting then
  	 insert into AGGR_LOCALIZZA (PKID_LOC, fkid_type, PKID_TOPO, COD_NAZIONALE, NOME, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, SHAPE, NOTE, UTENTE_FINE, ID_TRASF, ID_TRASF_FINE)
	   values (:new.pkid_civi, -1, :new.pkid_stra, :new.COD_NAZIONALE, :new.civico, :new.DATA_INIZIO_VAL, :new.DATA_FINE_VAL, :new.UTENTE, :new.SHAPE, :new.NOTE, :new.UTENTE_FINE, :new.ID_TRASF, :new.ID_TRASF_FINE);
  elsif updating then
    UPDATE AGGR_LOCALIZZA SET
	   PKID_LOC        = :new.PKID_civi,
       PKID_TOPO       = :new.PKID_stra,
       COD_NAZIONALE   = :new.COD_NAZIONALE,
       NOME            = :new.civico,
       DATA_INIZIO_VAL = :new.DATA_INIZIO_VAL,
       DATA_FINE_VAL   = :new.DATA_FINE_VAL,
       UTENTE          = :new.UTENTE,
       SHAPE           = :new.SHAPE,
       NOTE            = :new.NOTE,
       UTENTE_FINE     = :new.UTENTE_FINE,
       ID_TRASF        = :new.ID_TRASF,
       ID_TRASF_FINE   = :new.ID_TRASF_FINE
     WHERE PKID_LOC = :old.PKID_civi;
  else
    delete from AGGR_LOCALIZZA where pkid_loc = :old.pkid_civi;
  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.SITICIVI_UIU_TR1 
instead of insert or update or delete 
ON SITI_H501.SITICIVI_UIU 
for each row
begin 
  if inserting then 
  	 insert into sitiloc_uiu (fkid_type, PKID_LOC, PKID_UIU, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, SCALA, PIANO, INTERNO, UTENTE_FINE, PRINCIPALE) 
	   values (-1, :new.pkid_civi, :new.PKID_UIU, :new.DATA_INIZIO_VAL, :new.DATA_FINE_VAL, :new.UTENTE, :new.SCALA, :new.PIANO, :new.INTERNO, :new.UTENTE_FINE, :new.PRINCIPALE); 
  elsif updating then 
    UPDATE SITILOC_UIU 
	   SET PKID_LOC        = :new.PKID_CIVI, 
           PKID_UIU        = :new.PKID_UIU, 
           DATA_INIZIO_VAL = :new.DATA_INIZIO_VAL, 
           DATA_FINE_VAL   = :new.DATA_FINE_VAL, 
       	   UTENTE          = :new.UTENTE, 
	       SCALA           = :new.SCALA, 
		   PIANO           = :new.PIANO, 
		   INTERNO         = :new.INTERNO, 
		   UTENTE_FINE     = :new.UTENTE_FINE, 
       	   PRINCIPALE      = :new.PRINCIPALE 
		where PKID_LOC     = :old.PKID_CIVI 
		  and PKID_UIU     = :old.PKID_UIU; 
    null; 
  else 
    delete from SITILOC_UIU where pkid_loc = :old.pkid_civi; 
  end if; 
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.SOCIETA_IOFU
instead of update ON SITI_H501.SOCIETA
declare
  cnt pls_integer;
begin
  if (:new.cod_soc is not null) then

    select count(*) into cnt
      from anag_soggetti_ext
     where cod_soggetto = :new.cod_soc;

    if (cnt = 0) then
      insert into anag_soggetti_ext (cod_soggetto) values (:new.cod_soc);
    end if;

    update anag_soggetti_ext
       set banca = :new.banca, cab = :new.cab, abi = :new.abi, c_c = :new.c_c,
           cin = :new.cin, soc_dip_num = :new.soc_dip_num, prog_bol = :new.prog_bol,
           prog_fat = :new.prog_fat, nfile_fat = :new.nfile_fat, nfile_bol = :new.nfile_bol,
           mod_cont = :new.mod_cont, nfile_cont = :new.nfile_cont, nfile_contpag = :new.nfile_contpag,
           nfile_ritcont = :new.nfile_ritcont, codsocute = :new.codsocute, fattura = :new.fattura,
           add_mora = :new.add_mora, accr_int_dp = :new.accr_int_dp, mod_rendi = :new.mod_rendi,
           tribunale = :new.tribunale, cciaa = :new.cciia, fisso_nloc = :new.fisso_nloc,
           fisso_uiu = :new.fisso_uiu, note = :new.note, perc_ricavi = :new.perc_ricavi,
           data_bol = :new.data_bol, scadenza = :new.scadenza, data_fat = :new.data_fat,
           nfile_continc = :new.nfile_continc, titolo = :new.titolo, mod_contpas = :new.mod_contpas,
           nfile_contpas = :new.nfile_contpas, prog_bol_pas = :new.prog_bol_pas, data_bol_pas = :new.data_bol_pas,
           nfile_bolpas = :new.nfile_bolpas, mod_continve = :new.mod_continve, nfile_continve = :new.nfile_continve,
           soc_assoc = :new.soc_assoc, COD_PERSO_COSTI = :new.COD_PERSO_COSTI, nfile_costi_imp = :new.nfile_costi_imp,
           nfile_costi_exp = :new.nfile_costi_exp, cod_perso_vend = :new.cod_perso_vend,
           IBAN_PAESE = :new.IBAN_PAESE, IBAN_CIN_EUR = :new.IBAN_CIN_EUR
     where cod_soggetto = :new.cod_soc;
  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.SPESE_IOFIU
instead of insert or update ON SITI_H501.SPESE
for each row
begin
  if inserting then
    insert into patri_loc_spese (FK_ATTO, COD_FAT, IMPORTO, DATAINI, DATAFIN, IMPRATE, NUMTRATE, NUMPRATE, NOTE, COD_MIL, COD_BIL, CONGUAGLIO, DATAFINPREC, GRUPPO, CODRISC, ID_CONTR, COMPE_DAL, COMPE_AL, PERIODO, TIPO_COMP, ID, SOC_ASSOC, SOGG_IVA, FATTURA, SING_COD_INQ, ID_STORNATO)
      values (:new.codice, :new.COD_FAT, :new.IMPORTO, to_date(:new.DATAINI, 'dd/mm/yyyy'),
              to_date(:new.DATAFIN, 'dd/mm/yyyy'), :new.IMPRATE, :new.NUMTRATE, :new.NUMPRATE, :new.NOTE, :new.COD_MIL,
              :new.COD_BIL, :new.CONGUAGLIO, to_date(:new.DATAFINPREC, 'dd/mm/yyyy'), :new.GRUPPO, :new.CODRISC,
              :new.ID_CONTR, :new.COMPE_DAL, :new.COMPE_AL, :new.PERIODO, :new.TIPO_COMP, :new.ID,
              :new.SOC_ASSOC,
              :new.SOGG_IVA, :new.FATTURA, :new.SING_COD_INQ, :new.ID_STORNATO);
  else
    update patri_loc_spese
       set cod_fat = :new.COD_FAT, importo = :new.IMPORTO, dataini = to_date(:new.DATAINI, 'dd/mm/yyyy'),
           datafin = to_date(:new.DATAFIN, 'dd/mm/yyyy'), imprate = :new.IMPRATE, numtrate = :new.NUMTRATE,
           numprate = :new.NUMPRATE, note = :new.NOTE, cod_mil = :new.COD_MIL, cod_bil = :new.COD_BIL,
           conguaglio = :new.CONGUAGLIO, datafinprec = to_date(:new.DATAFINPREC, 'dd/mm/yyyy'), gruppo = :new.GRUPPO,
           codrisc = :new.CODRISC, id_contr = :new.ID_CONTR, compe_dal = :new.COMPE_DAL, compe_al = :new.COMPE_AL,
           periodo = :new.PERIODO, tipo_comp = :new.TIPO_COMP, soc_assoc = :new.SOC_ASSOC,
           sogg_iva = :new.SOGG_IVA, fattura = :new.FATTURA, sing_cod_inq = :new.SING_COD_INQ, id_stornato = :new.ID_STORNATO
     where fk_atto = :old.codice and id = :old.id;
  end if;
end;
/


