DROP VIEW SITI_H501.ANAINQUI;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.ANAINQUI
(
    COD_INQ,
    COD_FISC,
    SESSO,
    COGN_NOME,
    LUOGO_NS,
    DATA_NS,
    RES_VIA,
    RES_CAP,
    RES_CITTA,
    RES_TEL,
    FT_DENOM,
    FT_VIA,
    FT_CAP,
    FT_CITTA,
    P_IVA,
    ANNO_RED,
    REDDITO_NE,
    REDDITO_DI,
    REDDITO_AU,
    REDDITO,
    COMP_NUCL,
    COMP_CAR,
    STATO_INQ,
    REDDITO_PE,
    NOTE,
    TIPO_DOC,
    NUM_DOC,
    RIL_IL_DOC,
    AUTORITA_DOC,
    CAB,
    ABI,
    BANCA,
    C_C,
    DIP_SN,
    COD_SPORT,
    CHIAVEINQ,
    COD_UTE,
    COD_RAP,
    CITTADINANZA,
    COD_AFFI,
    TITOLO,
    PROV_NS,
    RES_PR,
    FT_PR,
    USO_STRUM,
    TIPOINTEFAT,
    CIN,
    ISE,
    ISEE,
    IBAN_PAESE,
    IBAN_CIN_EUR,
    FAX,
    E_MAIL,
    REFERENTE,
    CELLULARE,
    LOCALITA
)
BEQUEATH DEFINER
AS
    SELECT CAST (s.COD_SOGGETTO AS VARCHAR2 (10))        AS cod_inq,
           s.COD_FISCALE                                 AS cod_fisc,
           s.SESSO                                       AS sesso,
           s.DENOMINAZIONE                               AS cogn_nome,
           cn.nome                                       AS luogo_ns,
           s.D_NASCITA                                   AS data_ns,
           indirizzo_est                                 AS res_via,
           s.CAP                                         AS res_cap,
           c.nome                                        AS res_citta,
           s.TELEFONO                                    AS res_tel,
           se.ft_denom,
           indirizzo_est_recap                           AS ft_via,
           s.CAP_RECAP                                   AS ft_cap,
           cr.nome                                       AS ft_citta,
           s.PART_IVA                                    AS p_iva,
           EXTRACT (YEAR FROM SYSDATE)                   AS anno_red,
           patri_pck.init_ana_inqui (s.cod_soggetto)     AS reddito_ne,
           patri_pck.get_reddito_ld                      AS reddito_di,
           patri_pck.get_reddito_au                      AS reddito_au,
           patri_pck.get_reddito_tot                     AS reddito,
           patri_pck.get_comp_nucl                       AS comp_nucl,
           patri_pck.get_comp_car                        AS comp_car,
           se.stato_inq,
           patri_pck.get_reddito_pe                      AS reddito_pe,
           se.note,
           se.tipo_doc,
           se.num_doc,
           se.ril_il_doc,
           se.autorita_doc,
           se.cab,
           se.abi,
           se.banca,
           se.c_c,
           se.dip_sn,
           se.cod_sport,
           se.chiaveinq,
           se.cod_ute,
           s.FKRAPP_LEGALE                               AS cod_rap,
           se.cittadinanza,
           se.cod_affi,
           se.titolo,
           cn.SIGLA_PROV                                 AS prov_ns,
           c.SIGLA_PROV                                  AS res_pr,
           cr.SIGLA_PROV                                 AS ft_pr,
           se.uso_strum,
           se.tipointefat,
           se.cin,
           patri_pck.get_ise                             AS ise,
           patri_pck.get_isee                            AS isee,
           se.IBAN_PAESE,
           se.IBAN_CIN_EUR,
           s.fax                                         AS fax,
           s.mail                                        AS e_mail,
           s.per_rif                                     AS referente,
           s.cell                                        AS cellulare,
           s.localita
      FROM anag_soggetti      s,
           anag_soggetti_ext  se,
           siticomu_istat     c,
           siticomu_istat     cn,
           siticomu_istat     cr
     WHERE     se.cod_soggetto = s.cod_soggetto
           AND c.CODI_FISC_LUNA(+) = s.FKCOD_COMU_RESI
           AND cn.CODI_FISC_LUNA(+) = s.FKCOD_COMU_NASC
           AND cr.CODI_FISC_LUNA(+) = s.FKCOD_COMU_RECAPITO
           AND SYSDATE BETWEEN s.DATA_INIZIO_VAL AND s.DATA_FINE_VAL;


DROP VIEW SITI_H501.CENTRIRESP_CES_UP;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CENTRIRESP_CES_UP
(
    PKID,
    FK_OBJECT,
    TIPO,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    FK_SETTORE,
    FK_SERVIZIO,
    FK_CONSEGN,
    COD_CESPITE
)
BEQUEATH DEFINER
AS
    SELECT cr."PKID",
           cr."FK_OBJECT",
           cr."TIPO",
           cr."DATA_INIZIO_VAL",
           cr."DATA_FINE_VAL",
           cr."FK_SETTORE",
           cr."FK_SERVIZIO",
           cr."FK_CONSEGN",
           cr."PERC",
           pc.cod_cespite
      FROM cata_part           cp,
           siticond_all2       sc,
           patri_cespiti_part  pcp,
           patri_cespiti       pc,
           centriresp          cr
     WHERE     cp.cod_nazionale = sc.cod_nazionale
           AND cp.foglio = sc.foglio
           AND cp.particella = sc.particella
           AND cp.sub = sc.sub
           AND sc.pkid_tit = pcp.pk_tit
           AND sc.tipo_titolo = pcp.tipo_titolo
           AND pcp.fk_cespite = pc.pk_cespite
           AND cr.tipo = 'P'
           AND cr.fk_object = cp.id_cata_part
           AND sc.data_inizio <= cr.data_inizio_val
           AND sc.data_fine >= cr.data_fine_val
           AND (   (    pc.tipo_estrom IS NULL
                    AND pc.data_fine_val = TO_DATE ('31129999', 'DDMMYYYY'))
                OR pc.tipo_estrom IS NOT NULL)
    UNION ALL
    SELECT cr."PKID",
           cr."FK_OBJECT",
           cr."TIPO",
           cr."DATA_INIZIO_VAL",
           cr."DATA_FINE_VAL",
           cr."FK_SETTORE",
           cr."FK_SERVIZIO",
           cr."FK_CONSEGN",
           cr."PERC",
           pc.cod_cespite
      FROM CATA_UIU             cu,
           siticonduz_imm_all2  sc,
           patri_cespiti_uiu    pcp,
           patri_cespiti        pc,
           centriresp           cr
     WHERE     cu.cod_nazionale = sc.cod_nazionale
           AND cu.foglio = sc.foglio
           AND cu.particella = sc.particella
           AND cu.sub = sc.sub
           AND cu.unimm = sc.unimm
           AND sc.pkid_tit = pcp.pk_tit
           AND sc.tipo_titolo = pcp.tipo_titolo
           AND pcp.fk_cespite = pc.pk_cespite
           AND cr.tipo = 'U'
           AND cr.fk_object = cu.id_cata_uiu
           AND sc.data_inizio <= cr.data_inizio_val
           AND sc.data_fine >= cr.data_fine_val
           AND (   (    pc.tipo_estrom IS NULL
                    AND pc.data_fine_val = TO_DATE ('31129999', 'DDMMYYYY'))
                OR pc.tipo_estrom IS NOT NULL);


DROP VIEW SITI_H501.CES_OBJECT;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CES_OBJECT
(
    TIPO,
    FK_OBJECT,
    COD_CESPITE,
    DATA_INIZIO,
    DATA_FINE,
    TIPO_ESTROM,
    ITEM_TYPE,
    COD_NAZIONALE,
    FOGLIO,
    PARTICELLA,
    SUB,
    UNIMM,
    VANO
)
BEQUEATH DEFINER
AS
    SELECT 'P'                 AS tipo,
           cp.id_cata_part     AS fk_object,
           pc.cod_cespite,
           sc.data_inizio,
           sc.data_fine,
           pc.tipo_estrom,
           'PART',
           cp.cod_nazionale,
           cp.foglio,
           cp.particella,
           cp.sub,
           NULL,
           NULL                AS item_type
      FROM cata_part           cp,
           siticond_all2       sc,
           patri_cespiti_part  pcp,
           patri_cespiti       pc
     WHERE     cp.cod_nazionale = sc.cod_nazionale
           AND cp.foglio = sc.foglio
           AND cp.particella = sc.particella
           AND cp.sub = sc.sub
           AND sc.pkid_tit = pcp.pk_tit
           AND sc.tipo_titolo = pcp.tipo_titolo
           AND pcp.fk_cespite = pc.pk_cespite
           AND (   (    pc.tipo_estrom IS NULL
                    AND pc.data_fine_val = TO_DATE ('31129999', 'DDMMYYYY'))
                OR pc.tipo_estrom IS NOT NULL)
    UNION ALL
    SELECT 'U'                AS tipo,
           cu.id_cata_uiu     AS fk_object,
           pc.cod_cespite,
           sc.data_inizio,
           sc.data_fine,
           pc.tipo_estrom,
           'UIU'              AS item_type,
           cu.cod_nazionale,
           cu.foglio,
           cu.particella,
           cu.sub,
           cu.unimm,
           NULL
      FROM CATA_UIU             cu,
           siticonduz_imm_all2  sc,
           patri_cespiti_uiu    pcp,
           patri_cespiti        pc
     WHERE     cu.cod_nazionale = sc.cod_nazionale
           AND cu.foglio = sc.foglio
           AND cu.particella = sc.particella
           AND cu.sub = sc.sub
           AND cu.unimm = sc.unimm
           AND sc.pkid_tit = pcp.pk_tit
           AND sc.tipo_titolo = pcp.tipo_titolo
           AND pcp.fk_cespite = pc.pk_cespite
           AND (   (    pc.tipo_estrom IS NULL
                    AND pc.data_fine_val = TO_DATE ('31129999', 'DDMMYYYY'))
                OR pc.tipo_estrom IS NOT NULL)
    UNION ALL
      SELECT 'A'                                 AS tipo,
             atopo.id_cata_topo                  AS fk_object,
             'C' || MIN (atopo.pkid_topo)        AS cod_ces,
             TO_DATE ('1700101', 'yyyymmdd')     AS data_inizio,
             NULL                                AS data_fine,
             NULL                                AS tipo_estrom,
             'AGGR'                              AS item_type,
             ap.cod_nazionale,
             ap.foglio,
             ap.particella,
             ap.sub,
             NULL,
             NULL
        FROM (SELECT t.cod_nazionale,
                     t.foglio,
                     t.particella,
                     t.sub,
                     t.pkid_tit
                FROM patri_cespiti_uiu  p,
                     siticonduz_imm_all2 t,
                     patri_cespiti      pc
               WHERE     t.tipo_titolo = p.tipo_titolo
                     AND t.pkid_tit = p.pk_tit
                     AND p.fk_cespite = pc.pk_cespite
                     AND (   (    pc.tipo_estrom IS NULL
                              AND pc.data_fine_val >=
                                  TO_DATE ('31129999', 'ddmmyyyy'))
                          OR pc.tipo_estrom IS NOT NULL)) ces,
             aggr_part ap,
             aggr_topo atopo
       WHERE     ap.cod_nazionale(+) = ces.cod_nazionale
             AND ap.foglio(+) = ces.foglio
             AND ap.particella(+) = ces.particella
             AND ap.sub(+) = ces.sub
             AND ap.aggr_code(+) NOT IN (1, 2)
             AND atopo.pkid_topo(+) = ap.pkid_topo
             AND atopo.numero IS NOT NULL
             AND ap.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy')
    GROUP BY atopo.id_cata_topo,
             atopo.cod_nazionale,
             atopo.numero,
             atopo.nome,
             ap.cod_nazionale,
             ap.foglio,
             ap.particella,
             ap.sub
    UNION ALL
    SELECT DISTINCT 'V'                   AS tipo,
                    ID_CATA_VANO          AS fk_object,
                    c.COD_CESPITE         AS uni_imm,
                    v.data_inizio_val     AS data_inizio,
                    v.data_fine_val       AS data_fine,
                    NULL                  AS tipo_estrom,
                    'VANO'                AS item_type,
                    v.cod_nazionale,
                    v.foglio,
                    v.particella,
                    v.sub,
                    v.unimm,
                    v.vano
      FROM patri_cespiti        c,
           patri_cespiti_uiu    cu,
           siticonduz_imm_all2  t,
           sitiedi_vani         v
     WHERE     t.cod_nazionale = v.cod_nazionale
           AND t.foglio = v.foglio
           AND t.particella = v.particella
           AND t.sub = v.sub
           AND t.unimm = v.unimm
           AND cu.pk_tit = t.PKID_TIT
           AND c.PK_CESPITE = cu.FK_CESPITE
           AND v.data_fine_val = TO_DATE ('31129999', 'ddmmyyyy');


DROP VIEW SITI_H501.CES_UP;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CES_UP
(
    TIPO,
    FK_OBJECT,
    COD_CESPITE,
    DATA_INIZIO,
    DATA_FINE,
    TIPO_ESTROM
)
BEQUEATH DEFINER
AS
    SELECT 'P'                 AS tipo,
           cp.id_cata_part     AS fk_object,
           pc.cod_cespite,
           sc.data_inizio,
           sc.data_fine,
           pc.tipo_estrom
      FROM cata_part           cp,
           siticond_all2       sc,
           patri_cespiti_part  pcp,
           patri_cespiti       pc
     WHERE     cp.cod_nazionale = sc.cod_nazionale
           AND cp.foglio = sc.foglio
           AND cp.particella = sc.particella
           AND cp.sub = sc.sub
           AND sc.pkid_tit = pcp.pk_tit
           AND sc.tipo_titolo = pcp.tipo_titolo
           AND pcp.fk_cespite = pc.pk_cespite
           AND (   (    pc.tipo_estrom IS NULL
                    AND pc.data_fine_val = TO_DATE ('31129999', 'DDMMYYYY'))
                OR pc.tipo_estrom IS NOT NULL)
    UNION ALL
    SELECT 'U'                AS tipo,
           cu.id_cata_uiu     AS fk_object,
           pc.cod_cespite,
           sc.data_inizio,
           sc.data_fine,
           pc.tipo_estrom
      FROM CATA_UIU             cu,
           siticonduz_imm_all2  sc,
           patri_cespiti_uiu    pcp,
           patri_cespiti        pc
     WHERE     cu.cod_nazionale = sc.cod_nazionale
           AND cu.foglio = sc.foglio
           AND cu.particella = sc.particella
           AND cu.sub = sc.sub
           AND cu.unimm = sc.unimm
           AND sc.pkid_tit = pcp.pk_tit
           AND sc.tipo_titolo = pcp.tipo_titolo
           AND pcp.fk_cespite = pc.pk_cespite
           AND (   (    pc.tipo_estrom IS NULL
                    AND pc.data_fine_val = TO_DATE ('31129999', 'DDMMYYYY'))
                OR pc.tipo_estrom IS NOT NULL);


DROP VIEW SITI_H501.COINTESTATARI;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.COINTESTATARI
(
    CODICE,
    COD_INQ,
    PERC_SPESE_INQ,
    ID_CO,
    DATA_USCITA,
    TIPO_USCITA,
    ID_IMPREG,
    DATA_INIZIO
)
BEQUEATH DEFINER
AS
    SELECT CAST (c.fk_atto AS VARCHAR2 (10))    AS codice,
           CAST (c.pk_cuaa AS VARCHAR2 (10))    AS cod_inq,
           c.perc_spese                         AS perc_spese_inq,
           c.id_co,
           TRUNC (c.data_uscita, 'DD')          AS data_uscita,
           c.tipo_uscita,
           c.id_impreg,
           CASE
               WHEN c.id_co < 50000 THEN TRUNC (d.data_inizio + 1, 'DD')
               ELSE NULL
           END                                  AS data_inizio
      FROM patri_loc_cointesta  c,
           contratt             ctrl,
           (  SELECT MIN (data_inizio) AS data_inizio, atto_ini, pk_cuaa
                FROM (SELECT a.data_inizio,
                             b.data_uscita,
                             a.atto_ini,
                             a.pk_cuaa
                        FROM (SELECT data_inizio, atto_ini, pk_cuaa
                                FROM cons_ufre_tab
                               WHERE tipo_titolo <> 9
                              UNION
                              SELECT data_inizio, atto_ini, pk_cuaa
                                FROM cons_urui_tab
                               WHERE tipo_titolo <> 9
                              UNION
                              SELECT data_inizio,
                                     fkid_atto     AS atto_ini,
                                     pk_cuaa
                                FROM cons_subloc_tab
                               WHERE tipo_titolo <> 9) a,
                             (  SELECT pk_cuaa,
                                       fk_atto,
                                       MAX (data_uscita)     AS data_uscita
                                  FROM patri_loc_cointesta
                                 WHERE id_co >= 50000
                              GROUP BY pk_cuaa, fk_atto) b
                       WHERE     a.atto_ini = b.fk_atto(+)
                             AND a.pk_cuaa = b.pk_cuaa(+))
               WHERE (   data_uscita IS NULL
                      OR (data_uscita IS NOT NULL AND data_inizio > data_uscita))
            GROUP BY atto_ini, pk_cuaa) d
     WHERE     c.pk_cuaa = d.pk_cuaa(+)
           AND c.fk_atto = d.atto_ini(+)
           AND c.fk_atto = CAST (ctrl.codice AS NUMBER);


