CREATE OR REPLACE FORCE VIEW SITI_H501.CONS_SOGG_VIW
(
    PKID,
    PK_CUAA,
    CUAA,
    COD_FISCALE,
    CODI_FISC,
    PART_IVA,
    CODI_PIVA,
    RAGI_SOCI,
    COGNOME,
    NOME,
    SESSO,
    D_NASCITA,
    D_COSTITUZIONE,
    DATA_NASC,
    D_MORTE,
    FKCOD_COMU_RESI,
    FKCOD_COMU_NASC,
    COMU_NASC,
    FKCIVICO_RESI,
    FKCOD_COMU_RECAPITO,
    FKCIVICO_RECAPITO,
    FLAG_PERS_FISICA,
    FKRAPP_LEGALE,
    DATA_FINE_VAL,
    DATA_INIZIO_VAL,
    DATA_LAV,
    UTENTE_INIZIO,
    UTENTE_FINE,
    VALIDO_INIZIO,
    VALIDO_FINE,
    ATTO_INIZIO,
    ATTO_FINE,
    NATURA_GIURIDICA,
    RESI_COMU,
    CAP,
    CAP_RECAP,
    TELEFONO,
    FAX,
    MAIL,
    INDIRIZZO_EST,
    INDIRIZZO_EST_RECAP,
    FL_PART_IVA,
    LOCALITA,
    CELL,
    PER_RIF
)
BEQUEATH DEFINER
AS
    SELECT s.pkid,
           s.cod_soggetto         AS pk_cuaa,
           a.cuaa,
           s.cod_fiscale,
           s.cod_fiscale          AS codi_fisc,
           s.part_iva,
           s.part_iva             AS codi_piva,
           s.denominazione        AS ragi_soci,
           s.cognome,
           s.nome,
           s.sesso,
           s.d_nascita,
           s.d_costituzione,
           s.d_nascita            AS DATA_NASC,
           s.d_morte,
           s.fkcod_comu_resi,
           s.fkcod_comu_nasc,
           s.fkcod_comu_nasc      AS COMU_NASC,
           s.fkcivico_resi,
           s.fkcod_comu_recapito,
           s.fkcivico_recapito,
           s.flag_pers_fisica,
           s.fkrapp_legale,
           s.data_fine_val,
           s.data_inizio_val,
           s.data_lav,
           s.utente_inizio,
           s.utente_fine,
           s.valido_inizio,
           s.valido_fine,
           s.atto_inizio,
           s.atto_fine,
           s.natura_giuridica,
           civi.cod_nazionale     AS RESI_COMU,
           s.cap,
           s.cap_recap,
           s.telefono,
           s.fax,
           s.mail,
           s.indirizzo_est,
           s.indirizzo_est_recap,
           s.FL_PART_IVA,
           s.localita,
           s.cell,
           s.per_rif
      FROM CONS_AZIE_TAB  A,
           ANAG_SOGGETTI  S
           LEFT OUTER JOIN (SITICIVI civi)
               ON s.fkcivico_resi = civi.pkid_civi
