DROP VIEW SITI_H501.FORNITORI;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.FORNITORI
(
    CODICE,
    DESCRIZIONE,
    INDIRIZZO,
    COMUNE,
    CAP,
    PROVINCIA,
    COD_UTE,
    ID_FRN,
    TEL,
    CELL,
    PER_RIF,
    NOTE,
    FAX,
    EMAIL,
    CAB,
    ABI,
    BANCA,
    C_C,
    COD_SPORT,
    COD_FISC,
    P_IVA,
    CIN,
    IBAN_PAESE,
    IBAN_CIN_EUR,
    LOCALITA
)
BEQUEATH DEFINER
AS
    SELECT CAST (s.COD_SOGGETTO AS VARCHAR2 (10))     AS CODICE,
           s.DENOMINAZIONE                            AS DESCRIZIONE,
           s.indirizzo_est                            AS INDIRIZZO,
           c.nome                                     AS COMUNE,
           s.CAP                                      AS CAP,
           cr.SIGLA_PROV                              AS PROVINCIA,
           se.cod_ute                                 AS COD_UTE,
           s.COD_SOGGETTO                             AS ID_FRN,
           s.TELEFONO                                 AS TEL,
           s.cell                                     AS CELL,
           s.per_rif                                  AS PER_RIF,
           se.note                                    AS NOTE,
           s.FAX                                      AS FAX,
           s.MAIL                                     AS EMAIL,
           se.cab                                     AS CAB,
           se.abi                                     AS ABI,
           se.banca                                   AS BANCA,
           se.c_c                                     AS C_C,
           se.cod_sport                               AS COD_SPORT,
           s.COD_FISCALE                              AS COD_FISC,
           s.PART_IVA                                 AS p_iva,
           se.cin                                     AS CIN,
           se.IBAN_PAESE                              AS IBAN_PAESE,
           se.IBAN_CIN_EUR                            AS IBAN_CIN_EUR,
           S.LOCALITA
      FROM anag_soggetti      s,
           anag_soggetti_ext  se,
           siticomu_istat     c,
           siticomu_istat     cr,
           AN_SOGGETTI_TAGS,
           AN_TAGS
     WHERE     se.cod_soggetto = s.cod_soggetto
           AND c.CODI_FISC_LUNA(+) = s.FKCOD_COMU_RESI
           AND cr.CODI_FISC_LUNA(+) = s.FKCOD_COMU_RECAPITO
           AND s.COD_SOGGETTO = AN_SOGGETTI_TAGS.ID_SOGGETTO
           AND AN_SOGGETTI_TAGS.ID_TAG = AN_TAGS.ID_TAG
           AND AN_TAGS.DESCR = 'MANU_FORN'
           AND SYSDATE BETWEEN AN_SOGGETTI_TAGS.inizio
                           AND AN_SOGGETTI_TAGS.fine
           AND SYSDATE BETWEEN AN_TAGS.INIZIO AND AN_TAGS.fine
           AND SYSDATE BETWEEN s.DATA_INIZIO_VAL AND s.DATA_FINE_VAL;


DROP VIEW SITI_H501.INVENTA;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.INVENTA
(
    FK_CESPITE,
    DATINSE,
    COD_SOC,
    CAT_INV,
    NUM_ORD,
    CAT_CES,
    CAT_ALT,
    COD_CES,
    DESCRIZIONE,
    CAT_AMM,
    COD_AMM,
    ARC_TIT,
    VARIAZ,
    DATA_VAR,
    BUONOTA,
    ESTROM,
    OSSERVAZ,
    GRUPPO,
    COD_ALI,
    DATA_AMM,
    IMP_VEN,
    COD_CALC,
    COD_INVEVEND,
    ZONA_SISMICA,
    TIPO_ESTROM,
    COD_ALI_FISC,
    DATA_AMM_FISC,
    FL_TP_LOCAZIONE,
    COD_VIA,
    CIVICO,
    INTERNO,
    FL_SOGGETTO_ICI,
    COD_NAZIONALE
)
BEQUEATH DEFINER
AS
    SELECT CAST (pk_cespite AS NUMBER (9))           AS fk_cespite,
           (SELECT MIN (DATA_INIZIO_VAL)
              FROM patri_cespiti
             WHERE cod_cespite = ces.cod_cespite)    AS datinse,
           TO_CHAR (ces.PK_CUAA)                     AS cod_soc,
           COD_CAT_INV                               AS cat_inv,
           NUM_INVENTARIO                            AS num_ord,
           COD_CAT_CES                               AS cat_ces,
           COD_CAT_CES_ALT                           AS cat_alt,
           COD_CESPITE                               AS cod_ces,
           descrizione,
           CAT_AMMINIS                               AS cat_amm,
           COD_AMMINIS                               AS cod_amm,
           ci.modello                                AS arc_tit,
           variaz,
           DECODE (data_fine_val,
                   TO_DATE ('99991231', 'yyyymmdd'), CAST (NULL AS DATE),
                   data_fine_val)                    AS data_var,
           buonota,
           --decode(data_fine_val, to_date('99991231','yyyymmdd'), 'N', 'S') as estrom,
           DECODE (tipo_estrom, NULL, 'N', 'S')      AS ESTROM,
           NULL                                      AS osservaz,
           cod_gruppo                                AS gruppo,
           COD_ALIQ_AMM                              AS cod_ali,
           DATA_AMM_INI                              AS data_amm,
           imp_ven,
           NULL                                      AS cod_calc,
           COD_INVEVEND                              AS cod_invevend,
           NULL                                      AS zona_sismica,
           tipo_estrom,
           COD_ALIQ_AMM_FISC                         AS cod_ali_fisc,
           DATA_AMM_FISC_INI                         AS data_amm_fisc,
           FL_TP_LOCAZIONE,
           cod_via,
           civico,
           interno,
           FL_SOGGETTO_ICI,
           cod_nazionale
      FROM patri_cespiti ces, tabcatin ci
     WHERE     ci.cat_inv(+) = ces.COD_CAT_INV
           AND FL_TP_LOCAZIONE IN ('A', 'L')
           AND (   (    ces.tipo_estrom IS NULL
                    AND ces.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy'))
                OR ces.tipo_estrom IS NOT NULL)
           AND (   patri_pck.getinventario () = 999999999
                OR EXISTS
                       (SELECT 1
                          FROM cons_cuaa_ente
                         WHERE     pk_cuaa = ces.pk_cuaa
                               AND cod_ente = patri_pck.getinventario ()
                               AND data_fine =
                                   TO_DATE ('99991231', 'yyyymmdd')))
    UNION ALL
    SELECT CAST (pk_cespite AS NUMBER (9))           AS fk_cespite,
           (SELECT MIN (DATA_INIZIO_VAL)
              FROM patri_cespiti
             WHERE cod_cespite = ces.cod_cespite)    AS datinse,
           TO_CHAR (ces.PK_CUAA)                     AS cod_soc,
           COD_CAT_INV                               AS cat_inv,
           NUM_INVENTARIO                            AS num_ord,
           COD_CAT_CES                               AS cat_ces,
           COD_CAT_CES_ALT                           AS cat_alt,
           COD_CESPITE                               AS cod_ces,
           descrizione,
           CAT_AMMINIS                               AS cat_amm,
           COD_AMMINIS                               AS cod_amm,
           ci.modello                                AS arc_tit,
           variaz,
           DECODE (data_fine_val,
                   TO_DATE ('99991231', 'yyyymmdd'), CAST (NULL AS DATE),
                   data_fine_val)                    AS data_var,
           buonota,
           --decode(data_fine_val, to_date('99991231','yyyymmdd'), 'N', 'S') as estrom,
           DECODE (tipo_estrom, NULL, 'N', 'S')      AS ESTROM,
           NULL                                      AS osservaz,
           cod_gruppo                                AS gruppo,
           COD_ALIQ_AMM                              AS cod_ali,
           DATA_AMM_INI                              AS data_amm,
           imp_ven,
           NULL                                      AS cod_calc,
           COD_INVEVEND                              AS cod_invevend,
           NULL                                      AS zona_sismica,
           tipo_estrom                               AS ESTROM,
           COD_ALIQ_AMM_FISC                         AS cod_ali_fisc,
           DATA_AMM_FISC_INI                         AS data_amm_fisc,
           FL_TP_LOCAZIONE,
           cod_via,
           civico,
           interno,
           FL_SOGGETTO_ICI,
           cod_nazionale
      FROM patri_cespiti  ces,
           tabcatin       ci,
           (SELECT DISTINCT fk_cespite
              FROM patri_cespiti_uiu) p
     WHERE     ci.cat_inv(+) = ces.COD_CAT_INV
           AND FL_TP_LOCAZIONE = 'R'
           AND (   (    ces.tipo_estrom IS NULL
                    AND ces.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy'))
                OR ces.tipo_estrom IS NOT NULL)
           AND ces.pk_cespite = p.fk_cespite
           AND (   patri_pck.getinventario () = 999999999
                OR EXISTS
                       (SELECT 1
                          FROM cons_cuaa_ente
                         WHERE     pk_cuaa = ces.pk_cuaa
                               AND cod_ente = patri_pck.getinventario ()
                               AND data_fine =
                                   TO_DATE ('99991231', 'yyyymmdd')))
    UNION ALL
    SELECT CAST (pk_cespite AS NUMBER (9))           AS fk_cespite,
           (SELECT MIN (DATA_INIZIO_VAL)
              FROM patri_cespiti
             WHERE cod_cespite = ces.cod_cespite)    AS datinse,
           TO_CHAR (ces.PK_CUAA)                     AS cod_soc,
           COD_CAT_INV                               AS cat_inv,
           NUM_INVENTARIO                            AS num_ord,
           COD_CAT_CES                               AS cat_ces,
           COD_CAT_CES_ALT                           AS cat_alt,
           COD_CESPITE                               AS cod_ces,
           descrizione,
           CAT_AMMINIS                               AS cat_amm,
           COD_AMMINIS                               AS cod_amm,
           ci.modello                                AS arc_tit,
           variaz,
           DECODE (data_fine_val,
                   TO_DATE ('99991231', 'yyyymmdd'), CAST (NULL AS DATE),
                   data_fine_val)                    AS data_var,
           buonota,
           --decode(data_fine_val, to_date('99991231','yyyymmdd'), 'N', 'S') as estrom,
           DECODE (tipo_estrom, NULL, 'N', 'S')      AS ESTROM,
           NULL                                      AS osservaz,
           aggr.cod_aggr                             AS gruppo,
           COD_ALIQ_AMM                              AS cod_ali,
           DATA_AMM_INI                              AS data_amm,
           imp_ven,
           NULL                                      AS cod_calc,
           COD_INVEVEND                              AS cod_invevend,
           NULL                                      AS zona_sismica,
           tipo_estrom                               AS ESTROM,
           COD_ALIQ_AMM_FISC                         AS cod_ali_fisc,
           DATA_AMM_FISC_INI                         AS data_amm_fisc,
           FL_TP_LOCAZIONE,
           cod_via,
           civico,
           interno,
           FL_SOGGETTO_ICI,
           cod_nazionale
      FROM patri_cespiti  ces,
           tabcatin       ci,
           (SELECT DISTINCT fk_cespite
              FROM patri_cespiti_part
             WHERE fk_cespite NOT IN
                       (SELECT fk_cespite FROM patri_cespiti_uiu)) p,
           (  SELECT ces.fk_cespite,
                     DECODE (MIN (t.pkid_topo),
                             NULL, NULL,
                             'C' || MIN (t.pkid_topo))    AS cod_aggr
                FROM (SELECT pcp.fk_cespite,
                             sca.cod_nazionale,
                             sca.foglio,
                             sca.particella,
                             sca.sub
                        FROM patri_cespiti_part pcp, siticond_all2 sca
                       WHERE     sca.tipo_titolo = pcp.tipo_titolo
                             AND sca.pkid_tit = pcp.pk_tit) ces,
                     aggr_part ap,
                     aggr_topo t
               WHERE     ap.cod_nazionale(+) = ces.cod_nazionale
                     AND ap.foglio(+) = ces.foglio
                     AND ap.particella(+) = ces.particella
                     AND ap.sub(+) = ces.sub
                     AND ap.aggr_code(+) NOT IN (1, 2)
                     AND t.pkid_topo(+) = ap.pkid_topo
            GROUP BY ces.fk_cespite) aggr
     WHERE     ci.cat_inv(+) = ces.COD_CAT_INV
           AND FL_TP_LOCAZIONE = 'R'
           AND aggr.fk_cespite(+) = ces.pk_cespite
           AND ces.pk_cespite = p.fk_cespite
           AND (   (    ces.tipo_estrom IS NULL
                    AND ces.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy'))
                OR ces.tipo_estrom IS NOT NULL)
           AND (   patri_pck.getinventario () = 999999999
                OR EXISTS
                       (SELECT 1
                          FROM cons_cuaa_ente
                         WHERE     pk_cuaa = ces.pk_cuaa
                               AND cod_ente = patri_pck.getinventario ()
                               AND data_fine =
                                   TO_DATE ('99991231', 'yyyymmdd')))
    UNION ALL
      SELECT CAST (NULL AS NUMBER (9))            AS fk_cespite,
             TO_DATE ('1700101', 'yyyymmdd')      AS datinse,
             NULL                                 AS cod_soc,
             NULL                                 AS cat_inv,
             100000000 + MIN (t.pkid_topo)        AS num_ord,
             NULL                                 AS cat_ces,
             NULL                                 AS cat_alt,
             'C' || MIN (t.pkid_topo)             AS cod_ces,
             t.nome,
             NULL                                 AS cat_amm,
             NULL                                 AS cod_amm,
             NULL                                 AS arc_tit,
             NULL                                 AS variaz,
             TO_DATE ('17000101', 'yyyymmdd')     AS data_var,
             NULL                                 AS buonota,
             'N'                                  AS estrom,
             NULL                                 AS osservaz,
             NULL                                 AS gruppo,
             NULL                                 AS cod_ali,
             NULL                                 AS data_amm,
             NULL                                 AS imp_ven,
             NULL                                 AS cod_calc,
             NULL                                 AS cod_invevend,
             NULL                                 AS zona_sismica,
             NULL                                 AS tipo_estrom,
             NULL                                 AS cod_ali_fisc,
             NULL                                 AS data_amm_fisc,
             'R'                                  AS FL_TP_LOCAZIONE,
             NULL                                 AS cod_via,
             NULL                                 AS civico,
             NULL                                 AS interno,
             'N'                                  AS FL_SOGGETTO_ICI,
             t.cod_nazionale
        FROM (SELECT t.cod_nazionale,
                     t.foglio,
                     t.particella,
                     t.sub,
                     t.pkid_tit
                FROM patri_cespiti_uiu  p,
                     siticonduz_imm_all2 t,
                     patri_cespiti      pc
               WHERE     t.tipo_titolo = p.tipo_titolo
                     AND t.pkid_tit = p.pk_tit
                     AND p.fk_cespite = pc.pk_cespite
                     AND (   (    pc.tipo_estrom IS NULL
                              AND pc.data_fine_val >=
                                  TO_DATE ('31129999', 'ddmmyyyy'))
                          OR pc.tipo_estrom IS NOT NULL)) ces,
             aggr_part ap,
             aggr_topo t
       WHERE     ap.cod_nazionale(+) = ces.cod_nazionale
             AND ap.foglio(+) = ces.foglio
             AND ap.particella(+) = ces.particella
             AND ap.sub(+) = ces.sub
             AND ap.aggr_code(+) NOT IN (1, 2)
             AND t.pkid_topo(+) = ap.pkid_topo
             AND t.numero IS NOT NULL
             AND ap.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy')
    GROUP BY t.cod_nazionale, t.numero, t.nome;


DROP VIEW SITI_H501.LOCALI;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.LOCALI
(
    ID_LOCALE,
    UNI_IMM,
    DESCRUNI,
    SOT_IMM,
    DESCRSOT,
    LOCALE,
    DESCRLOC,
    AREA_MQ,
    PERIM_MT,
    H_MEDIA,
    TIPOLOGIA,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    VOLUME_MC
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT ID_CATA_VANO      AS id_locale,
                    c.COD_CESPITE     AS uni_imm,
                    c.DESCRIZIONE     AS descruni,
                    v.piano           AS sot_imm,
                    v.piano           AS descrsot,
                    v.vano            AS locale,
                    v.nome_vano       AS descrloc,
                    supe_ambiente     AS area_mq,
                    v.perimetro       AS perim_mt,
                    v.altezzamin      AS h_media,
                    ambiente          AS tipologia,
                    v.data_inizio_val,
                    v.data_fine_val,
                    v.volume          AS volume_mc
      FROM patri_cespiti        c,
           patri_cespiti_uiu    cu,
           siticonduz_imm_all2  t,
           sitiedi_vani         v
     WHERE     t.cod_nazionale = v.cod_nazionale
           AND t.foglio = v.foglio
           AND t.particella = v.particella
           AND t.sub = v.sub
           AND t.unimm = v.unimm
           AND cu.pk_tit = t.PKID_TIT
           AND c.PK_CESPITE = cu.FK_CESPITE
           AND v.data_fine_val = TO_DATE ('31129999', 'ddmmyyyy');


DROP VIEW SITI_H501.LP_CONTRATT_CESPITI_VALID;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.LP_CONTRATT_CESPITI_VALID
(
    CODICE,
    ID_CONTR,
    COD_CES,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    SUP_LOCA,
    P_SUP_LOCA,
    PK_CESPITE
)
BEQUEATH DEFINER
AS
    SELECT a.codice,
           cc.id_contr,
           a.cod_ces,
           a.data_inizio_val,
           a.data_fine_val,
           a.sup_loca,
           a.p_sup_loca,
           a.pk_cespite
      FROM (SELECT DISTINCT
                   loc.atto_inizio                    AS codice,
                   loc.cod_cespite                    AS cod_ces,
                   TRUNC (dt_var.data_inizio_val)     AS data_inizio_val,
                   CASE
                       WHEN dt_var.data_fine_val =
                            TO_DATE ('31129999', 'DDMMYYYY')
                       THEN
                           NULL
                       ELSE
                           TRUNC (dt_var.data_fine_val, 'DDD')
                   END                                AS data_fine_val,
                   patri_pck.get_superficie_cespite_locata (
                       loc.pk_cespite,
                       loc.atto_inizio,
                         TRUNC (dt_var.data_inizio_val, 'DDD')
                       + (1 - (1 / 24 / 60 / 60)))    AS sup_loca,
                   patri_pck.get_pct_sup_cespite_locata (
                       loc.pk_cespite,
                       loc.atto_inizio,
                         TRUNC (dt_var.data_inizio_val, 'DDD')
                       + (1 - (1 / 24 / 60 / 60)))    AS p_sup_loca,
                   loc.pk_cespite
              FROM sitifile_atti_doc             sfad,
                   sitifile_atti                 sfa,
                   sitifile_documenti            sfd,
                   sitifile_documenti_campi_ext  sfdce,
                   (SELECT DISTINCT 'U'     AS etype,
                                    scia2.cod_nazionale,
                                    scia2.foglio,
                                    scia2.particella,
                                    scia2.sub,
                                    scia2.unimm,
                                    pc.pk_cespite,
                                    pc.cod_cespite,
                                    scia2.atto_inizio
                      FROM siticonduz_imm_all2  scia2,
                           patri_cespiti_uiu    pcu,
                           patri_cespiti        pc
                     WHERE     scia2.tipo_titolo NOT IN (1, 3)
                           AND scia2.pkid_tit = pcu.pk_tit
                           AND scia2.tipo_titolo = pcu.tipo_titolo
                           AND pcu.fk_cespite = pc.pk_cespite
                    UNION
                    SELECT DISTINCT 'P'      AS etype,
                                    scia2.cod_nazionale,
                                    scia2.foglio,
                                    scia2.particella,
                                    scia2.sub,
                                    NULL     AS unimm,
                                    pc.pk_cespite,
                                    pc.cod_cespite,
                                    scia2.atto_inizio
                      FROM siticond_all2       scia2,
                           patri_cespiti_part  pcp,
                           patri_cespiti       pc
                     WHERE     scia2.tipo_titolo NOT IN (1, 3)
                           AND scia2.pkid_tit = pcp.pk_tit
                           AND scia2.tipo_titolo = pcp.tipo_titolo
                           AND pcp.fk_cespite = pc.pk_cespite) loc,
                   (  SELECT etype,
                             cod_nazionale,
                             foglio,
                             particella,
                             sub,
                             unimm,
                             atto_ini,
                             MAX (data_inizio)     AS data_inizio_val,
                             data_fine             AS data_fine_val
                        FROM (SELECT a.etype,
                                     a.cod_nazionale,
                                     a.foglio,
                                     a.particella,
                                     a.sub,
                                     a.unimm,
                                     a.atto_ini,
                                     a.data_var     AS data_inizio,
                                     b.data_var     AS data_fine
                                FROM (SELECT DISTINCT etype,
                                                      cod_nazionale,
                                                      foglio,
                                                      particella,
                                                      sub,
                                                      unimm,
                                                      atto_ini,
                                                      data_var
                                        FROM contratt_var) a,
                                     (SELECT DISTINCT etype,
                                                      cod_nazionale,
                                                      foglio,
                                                      particella,
                                                      sub,
                                                      unimm,
                                                      atto_ini,
                                                      data_var
                                        FROM contratt_var) b
                               WHERE     a.cod_nazionale = b.cod_nazionale
                                     AND a.foglio = b.foglio
                                     AND a.particella = b.particella
                                     AND a.sub = b.sub
                                     AND NVL (a.unimm, -1) = NVL (b.unimm, -1)
                                     AND a.etype = b.etype
                                     AND a.atto_ini = b.atto_ini
                                     AND a.data_var < b.data_var)
                    GROUP BY etype,
                             cod_nazionale,
                             foglio,
                             particella,
                             sub,
                             unimm,
                             atto_ini,
                             data_fine) dt_var
             WHERE     sfa.pkid_atto = loc.atto_inizio
                   AND sfa.fkid_tipo_atto = -22
                   AND sfad.fkid_atto = sfa.pkid_atto
                   AND sfd.pkid_doc = sfad.fkid_doc
                   AND sfd.fkid_tipo_doc = -27
                   AND sfdce.fkid_doc = sfd.pkid_doc
                   AND dt_var.atto_ini = loc.atto_inizio
                   AND dt_var.atto_ini = loc.atto_inizio
                   AND dt_var.etype = loc.etype
                   AND dt_var.cod_nazionale = loc.cod_nazionale
                   AND dt_var.foglio = loc.foglio
                   AND dt_var.particella = loc.particella
                   AND dt_var.sub = loc.sub
                   AND NVL (dt_var.unimm, -1) = NVL (loc.unimm, -1)) a,
           lp_contratt_cespiti  cc
     WHERE     sup_loca <> -1
           AND a.codice = cc.codice
           AND a.cod_ces = cc.cod_ces
           AND (   a.data_fine_val IS NULL
                OR (    a.data_fine_val IS NOT NULL
                    AND a.data_fine_val <> a.data_inizio_val));


DROP VIEW SITI_H501.PATRI_CESPITI_CAT_VIW;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.PATRI_CESPITI_CAT_VIW
(
    ETYPE,
    PK_CESPITE,
    DESCRIZIONE,
    COD_NAZIONALE,
    FOGLIO,
    PARTICELLA,
    SUB,
    UNIMM,
    PK_TIT,
    TIPO_TITOLO,
