    COD_AMMINIS,
    COD_IMM,
    FL_SOGGETTO_ICI,
    DATA_LAV,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    COD_GRUPPO
)
BEQUEATH DEFINER
AS
    SELECT 'P'      AS etype,
           c.pk_cespite,
           c.descrizione,
           t.cod_nazionale,
           t.foglio,
           t.particella,
           t.sub,
           NULL     AS unimm,
           cp.pk_tit,
           cp.tipo_titolo,
           t.pk_cuaa,
           t.cuaa,
           t.data_inizio,
           t.data_fine,
           c.cod_cespite,
           c.num_inventario,
           c.cod_cat_inv,
           c.cod_cat_ces,
           c.cod_cat_ces_alt,
           c.cod_aliq_amm,
           c.cod_aliq_amm_fisc,
           c.data_amm_ini,
           c.data_amm_fisc_ini,
           c.cod_invevend,
           c.cat_amminis,
           c.cod_amminis,
           c.cod_imm,
           c.fl_soggetto_ici,
           c.data_lav,
           c.data_inizio_val,
           c.data_fine_val,
           c.cod_gruppo
      FROM patri_cespiti c, patri_cespiti_part cp, siticond_all t
     WHERE     cp.FK_CESPITE = c.PK_CESPITE
           AND t.PKID_TIT = cp.pk_tit
           AND t.TIPO_TITOLO = cp.tipo_titolo
    UNION ALL
    SELECT 'U'     AS etype,
           c.pk_cespite,
           c.descrizione,
           t.cod_nazionale,
           t.foglio,
           t.particella,
           t.sub,
           t.unimm,
           cp.pk_tit,
           cp.tipo_titolo,
           t.pk_cuaa,
           t.cuaa,
           t.data_inizio,
           t.data_fine,
           c.cod_cespite,
           c.num_inventario,
           c.cod_cat_inv,
           c.cod_cat_ces,
           c.cod_cat_ces_alt,
           c.cod_aliq_amm,
           c.cod_aliq_amm_fisc,
           c.data_amm_ini,
           c.data_amm_fisc_ini,
           c.cod_invevend,
           c.cat_amminis,
           c.cod_amminis,
           c.cod_imm,
           c.fl_soggetto_ici,
           c.data_lav,
           c.data_inizio_val,
           c.data_fine_val,
           c.cod_gruppo
      FROM patri_cespiti c, patri_cespiti_uiu cp, siticonduz_imm_all t
     WHERE     cp.FK_CESPITE = c.PK_CESPITE
           AND t.PKID_TIT = cp.pk_tit
           AND t.TIPO_TITOLO = cp.tipo_titolo;


DROP VIEW SITI_H501.PROPRIETARI;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.PROPRIETARI
(
    COD_PROPRIE,
    COD_FISC,
    SESSO,
    COGN_NOME,
    LUOGO_NS,
    DATA_NS,
    RES_VIA,
    RES_CAP,
    RES_CITTA,
    RES_TEL,
    FT_DENOM,
    FT_VIA,
    FT_CAP,
    FT_CITTA,
    P_IVA,
    ANNO_RED,
    STATO_INQ,
    NOTE,
    TIPO_DOC,
    NUM_DOC,
    RIL_IL_DOC,
    AUTORITA_DOC,
    CAB,
    ABI,
    BANCA,
    C_C,
    CIN,
    COD_SPORT,
    CHIAVEINQ,
    COD_UTE,
    COD_RAP,
    CITTADINANZA,
    COD_AFFI,
    TITOLO,
    PROV_NS,
    RES_PR,
    FT_PR,
    E_MAIL,
    FAX,
    IBAN_PAESE,
    IBAN_CIN_EUR,
    REFERENTE,
    CELLULARE,
    LOCALITA
)
BEQUEATH DEFINER
AS
    SELECT CAST (s.COD_SOGGETTO AS VARCHAR2 (10))     AS COD_PROPRIE,
           s.COD_FISCALE                              AS cod_fisc,
           s.SESSO                                    AS sesso,
           s.DENOMINAZIONE                            AS cogn_nome,
           cn.nome                                    AS luogo_ns,
           s.D_NASCITA                                AS data_ns,
           indirizzo_est                              AS res_via,
           s.CAP                                      AS res_cap,
           c.nome                                     AS res_citta,
           s.TELEFONO                                 AS res_tel,
           s.DENOMINAZIONE                            AS ft_denom,
           indirizzo_est_recap                        AS ft_via,
           s.CAP_recap                                AS ft_cap,
           cr.nome                                    AS ft_citta,
           s.PART_IVA                                 AS p_iva,
           se.anno_red,
           CAST (NULL AS VARCHAR2 (2))                AS stato_inq,
           se.note,
           se.tipo_doc,
           se.num_doc,
           se.ril_il_doc,
           se.autorita_doc,
           se.cab,
           se.abi,
           se.banca,
           se.c_c,
           se.cin,
           se.cod_sport,
           se.chiaveinq,
           se.cod_ute,
           s.FKRAPP_LEGALE                            AS cod_rap,
           se.cittadinanza,
           se.cod_affi,
           se.titolo,
           cn.SIGLA_PROV                              AS prov_ns,
           c.SIGLA_PROV                               AS res_pr,
           cr.SIGLA_PROV                              AS ft_pr,
           s.mail                                     AS e_mail,
           s.fax,
           se.IBAN_PAESE,
           se.IBAN_CIN_EUR,
           s.per_rif                                  AS referente,
           s.cell                                     AS cellulare,
           s.localita
      FROM anag_soggetti      s,
           anag_soggetti_ext  se,
           siticomu_istat     c,
           siticomu_istat     cn,
           siticomu_istat     cr
     WHERE     se.cod_soggetto = s.cod_soggetto
           AND c.CODI_FISC_LUNA(+) = s.FKCOD_COMU_RESI
           AND cn.CODI_FISC_LUNA(+) = s.FKCOD_COMU_NASC
           AND cr.CODI_FISC_LUNA(+) = s.FKCOD_COMU_RECAPITO
           AND SYSDATE BETWEEN s.DATA_INIZIO_VAL AND s.DATA_FINE_VAL;


DROP VIEW SITI_H501.RAPPRESENTANTI;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.RAPPRESENTANTI
(
    COD_RAP,
    NOME,
    QUALIFICA,
    NATO_A,
    NATO_IL,
    CITTA,
    INDIRIZZO,
    CAP,
    P_IVA,
    COD_FISC,
    TELEFONO,
    CITTADINANZA,
    SESSO,
    PROV,
    PROV_NS
)
BEQUEATH DEFINER
AS
    SELECT CAST (cod_soggetto AS VARCHAR2 (10))     AS cod_rap,
           denominazione                            AS nome,
           CAST (NULL AS VARCHAR2 (40))             AS qualifica,
           c.nome                                   AS nato_a,
           d_nascita                                AS nato_il,
           cr.nome                                  AS citta,
           s.INDIRIZZO_EST                          AS indirizzo,
           s.cap,
           s.part_iva                               AS p_iva,
           s.cod_fiscale                            AS cod_fisc,
           s.telefono,
           NULL                                     AS cittadinanza,
           sesso,
           c.SIGLA_PROV                             AS prov,
           cr.sigla_prov                            AS prov_ns
      FROM anag_soggetti s, siticomu_istat c, siticomu_istat cr
     WHERE     s.cod_soggetto IN
                   (SELECT FKRAPP_LEGALE
                      FROM anag_soggetti
                     WHERE FKRAPP_LEGALE IS NOT NULL AND FKRAPP_LEGALE != 0)
           AND s.data_fine_val > SYSDATE
           AND c.codi_fisc_luna(+) = s.FKCOD_COMU_NASC
           AND cr.codi_fisc_luna(+) = s.FKCOD_COMU_RESI;


DROP VIEW SITI_H501.RPT_ALL_TIT_VIW;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.RPT_ALL_TIT_VIW
(
    PKID,
    COD_NAZIONALE,
    FOGLIO,
    ALLEGATO,
    SVILUPPO,
    PARTICELLA,
    SUB,
    UNIMM,
    PERC_POSS,
    TIPO_TITOLO,
    PK_CUAA,
    DATA_INIZIO,
    DATA_FINE,
    TIPO_DOCUMENTO,
    TIT_NO_COD,
    RAGI_SOCI,
    NOME,
    CODI_FISC,
    CODI_PIVA
)
BEQUEATH DEFINER
AS
    SELECT t.PKID_CSUI       AS PKID,
           t.COD_NAZIONALE,
           t.FOGLIO,
           t.ALLEGATO,
           t.SVILUPPO,
           t.PARTICELLA,
           t.SUB,
           t.UNIMM,
           t.PERC_POSS,
           t.TIPO_TITOLO,
           t.PK_CUAA,
           t.DATA_INIZIO,
           t.DATA_FINE,
           t.TIPO_DOCUMENTO,
           t.TIT_NO_COD,
           s.ragi_soci,
           s.nome,
           s.cod_fiscale     AS codi_fisc,
           s.part_iva        AS codi_piva
      FROM cons_csui_tab t, cons_sogg_viw s
     WHERE s.pk_cuaa = t.pk_cuaa
    UNION ALL
    SELECT t.PKID_URUI     AS PKID,
           t.COD_NAZIONALE,
           t.FOGLIO,
           t.ALLEGATO,
           t.SVILUPPO,
           t.PARTICELLA,
           t.SUB,
           t.UNIMM,
           t.PERC_POSS,
           t.TIPO_TITOLO,
           t.PK_CUAA,
           t.DATA_INIZIO,
           t.DATA_FINE,
           t.TIPO_DOCUMENTO,
           t.TIT_NO_COD,
           s.ragi_soci,
           s.nome,
           s.cod_fiscale,
           s.part_iva
      FROM cons_urui_tab t, cons_sogg_viw s
     WHERE s.pk_cuaa = t.pk_cuaa
    UNION ALL
    SELECT t.PKID_CONS     AS PKID,
           t.COD_NAZIONALE,
           t.FOGLIO,
           t.ALLEGATO,
           t.SVILUPPO,
           t.PARTICELLA,
           t.SUB,
           t.UNIMM,
           t.PERC_POSS,
           t.TIPO_TITOLO,
           t.PK_CUAA,
           t.DATA_INIZIO,
           t.DATA_FINE,
           t.TIPO_DOCUMENTO,
           t.TIT_NO_COD,
           s.ragi_soci,
           s.nome,
           s.codi_fisc,
           s.codi_piva
      FROM cons_cons_tab t, cons_sogg_viw s
     WHERE s.pk_cuaa = t.pk_cuaa
    UNION ALL
    SELECT t.PKID_UFFR     AS PKID,
           t.COD_NAZIONALE,
           t.FOGLIO,
           t.ALLEGATO,
           t.SVILUPPO,
           t.PARTICELLA,
           t.SUB,
           t.UNIMM,
           t.PERC_POSS,
           t.TIPO_TITOLO,
           t.PK_CUAA,
           t.DATA_INIZIO,
           t.DATA_FINE,
           t.TIPO_DOCUMENTO,
           t.TIT_NO_COD,
           s.ragi_soci,
           s.nome,
           s.codi_fisc,
           s.codi_piva
      FROM cons_ufre_tab t, cons_sogg_viw s
     WHERE s.pk_cuaa = t.pk_cuaa;


DROP VIEW SITI_H501.SC_EDI;

/* Formatted on 18/07/2022 12:23:01 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.SC_EDI
(
    PK_CESPITE,
    COD_CES,
    CODCOM,
    CODVIA,
    NUMERO,
    INTERNO,
    ORIG_ICI,
    COD_AUTOR,
    MET_STIM,
    PROVEN,
    ZONA_PRG,
    ZONA_COM,
    SOGG_ICI,
    TIPO_ICI,
    CODALIICI,
    GESTIONE,
    BENE_RLA,
    DESAGG,
    VAL_TOT,
    VAL_ORIG,
    VAL_ATTU,
    VAL_RESI,
    ONER_AN,
    VAL_NUOVO,
    RIVALUTA,
    DATARIVA,
    TOT_CES,
    ULT_AMM_DAL,
    ULT_AMM_AL,
    ACC_ESE,
    VAL_TERRE,
    VAL_ATTU_F,
    VAL_RESI_F,
    ULT_AMM_DAL_F,
    ULT_AMM_AL_F,
    ACC_ESE_F,
    FV_CONS,
    FV_CONS_DATA,
    VAL_TOT_F,
    VAL_TERRE_F
)
BEQUEATH DEFINER
AS
    SELECT pk_cespite,
           c.COD_CESPITE
               AS cod_ces,
           c.cod_nazionale
               AS codcom,
           c.cod_via
               AS codvia,
           c.civico
               AS numero,
           c.interno,
           patri_pck.get_tipo_acquisizione (c.pk_cespite)
               AS orig_ici,
           NULL
               AS cod_autor,
           c.cod_metodo_stima
               AS met_stim,
           c.provenienza
               AS proven,
           NULL
               AS zona_prg,
           NULL
               AS zona_com,
           c.FL_SOGGETTO_ICI
               AS sogg_ici,
           c.TP_VAL_ICI
               AS tipo_ici,
           c.COD_ALIQ_ICI
               AS codaliici,
           NULL
               AS gestione,
           c.FL_TP_LOCAZIONE
               AS bene_rla,
           c.note
               AS desagg,
           c.VAL_BENE
               AS val_tot,
           c.VAL_ORIGINALE
               AS val_orig,
           c.VAL_ATTUALE
               AS val_attu,
           c.VAL_RESIDUO
               AS val_resi,
           NULL
               AS oner_an,
           c.VAL_A_NUOVO
               AS val_nuovo,
           c.RIVALUTAZIONI
               AS rivaluta,
           c.DT_ULT_RIVAL
               AS DATARIVA,
           NULL
               AS tot_ces,
           c.DT_ULT_AMM_DAL
               AS ULT_AMM_DAL,
           c.DT_ULT_AMM_AL
               AS ULT_AMM_AL,
           c.ULT_AMM_IMPO
               AS ACC_ESE,
           c.val_terre,
           c.VAL_ATTUALE_F
               AS VAL_ATTU_F,
           c.VAL_RESIDUO_F
               AS VAL_RESI_F,
           c.DT_ULT_AMM_DAL_F
               AS ULT_AMM_DAL_F,
           c.DT_ULT_AMM_AL_F
               AS ULT_AMM_AL_F,
           c.ULT_AMM_IMPO_F
               AS ACC_ESE_F,
           c.ULT_FV_CONS
               AS FV_CONS,
           c.DT_ULT_FV_CONS
               AS FV_CONS_DATA,
           c.val_tot_f,
           c.val_terre_f
      FROM patri_cespiti c
     WHERE    (    c.tipo_estrom IS NULL
               AND c.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy'))
           OR c.tipo_estrom IS NOT NULL
    UNION ALL
      SELECT CAST (NULL AS NUMBER (9))     AS fk_cespite,
             'C' || MIN (t.pkid_topo)      AS cod_ces,
             t.cod_nazionale,
             NULL                          AS codvia,
             NULL                          AS numero,
             NULL                          AS interno,
             0                             AS orig_ici,
             NULL                          AS cod_autor,
             NULL                          AS met_stim,
             NULL                          AS proven,
             NULL                          AS zona_prg,
             NULL                          AS zona_com,
             'N'                           AS sogg_ici,
             NULL                          AS tipo_ici,
             NULL                          AS codaliici,
             NULL                          AS gestione,
             'R'                           AS bene_rla,
             NULL                          AS desagg,
             NULL                          AS val_tot,
             NULL                          AS val_orig,
             NULL                          AS val_attu,
             NULL                          AS val_resi,
             NULL                          AS oner_an,
             NULL                          AS val_nuovo,
             NULL                          AS rivaluta,
             NULL                          AS DATARIVA,
             NULL                          AS tot_ces,
             NULL                          AS ULT_AMM_DAL,
             NULL                          AS ULT_AMM_AL,
             NULL                          AS ACC_ESE,
             NULL                          AS val_terre,
             NULL                          AS VAL_ATTU_F,
             NULL                          AS VAL_RESI_F,
             NULL                          AS ULT_AMM_DAL_F,
             NULL                          AS ULT_AMM_AL_F,
             NULL                          AS ACC_ESE_F,
             NULL                          AS FV_CONS,
             NULL                          AS FV_CONS_DATA,
             NULL                          AS val_tot_f,
             NULL                          AS val_terre_f
        FROM (SELECT t.cod_nazionale,
                     t.foglio,
                     t.particella,
                     t.sub,
                     t.pkid_tit
                FROM patri_cespiti_uiu  p,
                     siticonduz_imm_all2 t,
                     patri_cespiti      pc
               WHERE     t.tipo_titolo = p.tipo_titolo
                     AND t.pkid_tit = p.pk_tit
                     AND p.fk_cespite = pc.pk_cespite
                     AND (   (    pc.tipo_estrom IS NULL
                              AND pc.data_fine_val >=
                                  TO_DATE ('31129999', 'ddmmyyyy'))
                          OR pc.tipo_estrom IS NOT NULL)) ces,
             aggr_part ap,
             aggr_topo t
       WHERE     ap.cod_nazionale(+) = ces.cod_nazionale
             AND ap.foglio(+) = ces.foglio
             AND ap.particella(+) = ces.particella
             AND ap.sub(+) = ces.sub
             AND ap.aggr_code(+) NOT IN (1, 2)
             AND t.pkid_topo(+) = ap.pkid_topo
             AND t.numero IS NOT NULL
    GROUP BY t.cod_nazionale, t.numero, t.nome;


