DROP VIEW SITI_H501.SETTORI_CR_LOC;

/* Formatted on 18/07/2022 12:23:02 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.SETTORI_CR_LOC
(
    FK_ATTO,
    FK_SETTORE,
    SUBLOC
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT sa.atto_inizio, cr.fk_settore, 0 AS SUBLOC
      FROM siticond_all2 sa, cata_part cp, centriresp cr
     WHERE     cp.cod_nazionale = sa.cod_nazionale
           AND cp.foglio = sa.foglio
           AND cp.particella = sa.particella
           AND cp.sub = sa.sub
           AND sa.data_inizio <= SYSDATE
           AND sa.data_fine >= SYSDATE
           AND sa.tipo_titolo NOT IN ('1', '3')
           AND cr.fk_object = cp.id_cata_part
           AND cr.data_inizio_val <= SYSDATE
           AND cr.data_fine_val >= SYSDATE
           AND cr.fk_settore IS NOT NULL
           AND cr.tipo = 'P'
    UNION
    SELECT DISTINCT sia.atto_inizio, cr.fk_settore, 0 AS SUBLOC
      FROM siticonduz_imm_all2 sia, cata_uiu cu, centriresp cr
     WHERE     cu.cod_nazionale = sia.cod_nazionale
           AND cu.foglio = sia.foglio
           AND cu.particella = sia.particella
           AND cu.sub = sia.sub
           AND cu.unimm = sia.unimm
           AND sia.data_inizio <= SYSDATE
           AND sia.data_fine >= SYSDATE
           AND sia.tipo_titolo NOT IN ('1', '3')
           AND sia.fl_totale = 'Y'
           AND cr.fk_object = cu.id_cata_uiu
           AND cr.data_inizio_val <= SYSDATE
           AND cr.data_fine_val >= SYSDATE
           AND cr.fk_settore IS NOT NULL
           AND cr.tipo = 'U'
    UNION
    SELECT DISTINCT cuv.id_atto, cr.fk_settore, 0 AS SUBLOC
      FROM siticonduz_imm_all2  sia,
           cons_urui_vani       cuv,
           sitiedi_vani         sv,
           centriresp           cr
     WHERE     cuv.cod_nazionale = sia.cod_nazionale
           AND cuv.foglio = sia.foglio
           AND cuv.particella = sia.particella
           AND cuv.sub = sia.sub
           AND cuv.unimm = sia.unimm
           AND sia.data_inizio <= SYSDATE
           AND sia.data_fine >= SYSDATE
           AND sia.tipo_titolo NOT IN ('1', '3')
           --AND fl_totale = 'N'
           AND cuv.cod_nazionale = sv.cod_nazionale
           AND cuv.foglio = sv.foglio
           AND cuv.particella = sv.particella
           AND cuv.sub = sv.sub
           AND cuv.unimm = sv.unimm
           AND cuv.vano = sv.vano
           AND cuv.data_inizio_val <= SYSDATE
           AND cuv.data_fine_val >= SYSDATE
           AND cr.tipo = 'V'
           AND cr.fk_object = sv.id_cata_vano
           AND cr.data_inizio_val <= SYSDATE
           AND cr.data_fine_val >= SYSDATE
           AND cr.fk_settore IS NOT NULL
    UNION
    SELECT DISTINCT cst.atto_inizio, cr.fk_settore, 1 AS SUBLOC
      FROM CONS_SUBLOC_TAB cst, centriresp cr
     WHERE     CST.data_inizio <= SYSDATE
           AND CST.data_fine >= SYSDATE
           AND CST.FKID_OBJ = FK_OBJECT
           AND cst.obj_type = cr.tipo
           AND cr.data_inizio_val <= SYSDATE
           AND cr.data_fine_val >= SYSDATE
           AND cr.fk_settore IS NOT NULL;


