CREATE OR REPLACE FORCE VIEW SITI_H501.SITIDSTR_DATA
(
    PKID_STRA,
    PREFISSO,
    NOME,
    COD_NAZIONALE,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    UTENTE,
    TIPO,
    NUMERO,
    PREFISSO_ALT,
    NOME_ALT,
    NOTE,
    STR_LEN
)
