           (SELECT ROUND (SUM (SDO_GEOM.sdo_length (shape, 0.005)), 2)
              FROM sitidstr_graf
             WHERE cod_nazionale = s.cod_nazionale AND numero = s.numero)    AS str_len
      FROM sitidstr s
     WHERE s.data_fine_val >= SYSDATE;


