CREATE OR REPLACE TRIGGER SITI_H501.ANAINQUI_IOFU
instead of update ON SITI_H501.ANAINQUI
declare
  cnt pls_integer;
begin
  if (:new.cod_inq is not null) then

    select count(*) into cnt
      from anag_soggetti_ext
     where cod_soggetto = :new.cod_inq;

    if (cnt = 0) then
      insert into anag_soggetti_ext (cod_soggetto) values (:new.cod_inq);
    end if;

    update anag_soggetti_ext
       set banca = :new.banca, cab = :new.cab, abi = :new.abi, c_c = :new.c_c,
           cin = :new.cin, note = :new.note, titolo = :new.titolo,
           STATO_INQ = :new.STATO_INQ,
           TIPO_DOC = :new.TIPO_DOC, NUM_DOC = :new.NUM_DOC, RIL_IL_DOC = :new.RIL_IL_DOC,
           AUTORITA_DOC = :new.AUTORITA_DOC, DIP_SN = :new.DIP_SN, COD_SPORT = :new.COD_SPORT,
           CHIAVEINQ = :new.CHIAVEINQ, COD_UTE = :new.COD_UTE, CITTADINANZA = :new.CITTADINANZA,
           COD_AFFI = :new.COD_AFFI, USO_STRUM = :new.USO_STRUM,
           TIPOINTEFAT = :new.TIPOINTEFAT,
           IBAN_PAESE = :new.IBAN_PAESE, IBAN_CIN_EUR = :new.IBAN_CIN_EUR,
         ft_denom = :new.ft_denom
     where cod_soggetto = :new.cod_inq;
  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.COINTESTATARI_IOFU
  INSTEAD OF UPDATE
  ON SITI_H501.COINTESTATARI
  FOR EACH ROW
BEGIN
  UPDATE patri_loc_cointesta
     SET perc_spese = :NEW.perc_spese_inq,
         fattura = 'N',
         tipo_uscita = :NEW.tipo_uscita,
         id_impreg = :NEW.id_impreg
   WHERE fk_atto = :OLD.codice AND pk_cuaa = :OLD.cod_inq AND id_co = :OLD.id_co;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.COMUNI_IOFU
instead of update ON SITI_H501.COMUNI
for each row
begin
  update patri_siticomu_ext 
     set num_abitanti = :new.NABIT, 
         ANNO = :new.anno,
         ISTAT_AGR = :new.istat_agr,
         UFF_COMP = :new.UFF_COMP, 
         CONCESSIONE_DI = :new.CONCESSIONE_DI, 
         CONCESSIONE_CC = :new.CONCESSIONE_CC, 
         NOTE_COM = :new.NOTE_COM
   where cod_nazionale = :new.codice;
   
  if nvl(:new.UB_GEO, 'X') != nvl(:old.UB_GEO, 'X') then
    update siticomu set ubicazione_geografica = :new.UB_GEO
     where cod_nazionale = :new.codice;
  end if;
   
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.FORNITORI_IOFI
INSTEAD OF INSERT
ON SITI_H501.FORNITORI FOR EACH ROW
DECLARE
   num number;
   new_id number;
   new_pk_cuaa number;
   new_id_tag number;
BEGIN
    select count(*) into num
      from an_tags
     where DESCR = 'MANU_FORN';

    if num = 0 then
      INSERT INTO AN_TAGS ( ID_TAG, DESCR, SYSTEM, INIZIO, FINE ) VALUES (
      -11, 'MANU_FORN', 'Y',  TO_Date( '01/01/1980 12:00:00 AM', 'MM/DD/YYYY HH:MI:SS AM'),  TO_Date( '12/31/9999 12:00:00 AM', 'MM/DD/YYYY HH:MI:SS AM'));
    end if;


        select anag_soggetto_seq.nextval into new_id from dual;
        select cons_azie_seq.nextval into new_pk_cuaa from dual;
        insert into anag_soggetti (
            pkid,
            COD_SOGGETTO,
            DENOMINAZIONE,
            indirizzo_est,
            CAP,
            TELEFONO,
            FAX,
            MAIL,
            COD_FISCALE,
            PART_IVA,
            cell,
            per_rif,
            localita,

            data_fine_val,
            data_inizio_val,
            data_lav,
            utente_inizio
        )
        values(
            new_id,
            new_pk_cuaa,--rForn.id_frn,
            :new.descrizione,
            :new.indirizzo,
            :new.cap,
            :new.TEL,
            :new.FAX,
            :new.EMAIL,
            :new.COD_FISC,
            :new.P_IVA,
            :new.cell,
            :new.per_rif,
            :new.COMUNE,

            to_date('31129999', 'ddmmyyyy'),--data_fine_val,
            to_date('01011980', 'ddmmyyyy'),--data_inizio_val,
            sysdate,--data_lav,
            'FORNI_VIW'--utente_inizio,

        );
        insert into cons_azie_tab(
            pk_cuaa,
            cuaa,
            data_inizio,
            data_fine,
            data_registrazione,
            utente,
            timestamp,
            cod_stato,
            data_inizio_stato,
            cod_ente
            )values(
            new_pk_cuaa,
            'FORNI_'||new_pk_cuaa,
            to_date('01011980', 'ddmmyyyy'), to_date('99991231', 'yyyymmdd'), sysdate,'FORNI_VIW', sysdate, 0, to_date('01011980', 'ddmmyyyy'), null
        )
        ;

        update anag_soggetti_ext set
        cod_ute=:new.cod_ute,
        note=:new.note,
        cab=:new.cab,
        abi=:new.abi,
        banca=:new.banca,
        c_c=:new.c_c,
        cod_sport=:new.cod_sport,
        cin=:new.cin,
        iban_paese=:new.iban_paese,
        iban_cin_eur=:new.iban_cin_eur
        where cod_soggetto=new_pk_cuaa;--rForn.id_frn;


        select an_tags_seq.nextval into new_id_tag from dual;
        insert into AN_SOGGETTI_TAGS
            (ID,ID_SOGGETTO, ID_TAG, UT_INIZIO,INIZIO,UT_FINE,FINE,LAST_MODIFIED)
            values
            (new_id_tag,new_pk_cuaa,(select ID_TAG from an_tags where DESCR = 'MANU_FORN'),
            'FORNI_VIW',to_date('01011980', 'ddmmyyyy'),NULL,to_date('99991231', 'yyyymmdd'),SYSDATE
            );


END FORNITORI_iofi;
/


CREATE OR REPLACE TRIGGER SITI_H501.FORNITORI_IOFU
instead of update ON SITI_H501.FORNITORI
declare
  cnt pls_integer;
begin
  if (:new.CODICE is not null) then

    select count(*) into cnt
      from anag_soggetti_ext
     where cod_soggetto = :new.CODICE;

    if (cnt = 0) then
      insert into anag_soggetti_ext (cod_soggetto) values (:new.CODICE);
    end if;

    update anag_soggetti_ext
       set
           cod_ute = :new.COD_UTE,
           note = :new.note,
           banca = :new.banca,
           cab = :new.cab,
           abi = :new.abi,
           c_c = :new.c_c,
           COD_SPORT = :new.COD_SPORT,
           cin = :new.cin,
           IBAN_PAESE = :new.IBAN_PAESE,
           IBAN_CIN_EUR = :new.IBAN_CIN_EUR
           --,
           --cell = :new.CELL,
           --per_rif = :new.per_rif
     where cod_soggetto = :new.CODICE;
  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.INVENTA_IOFU
instead of update ON SITI_H501.INVENTA
for each row
begin

  if :old.fk_cespite is null then
    raise_application_error(-20001, '[fk_cespite is null] Impossibile modificare questo tipo di record!');
  end if;

  if :old.estrom = 'S' THEN
  	  update patri_cespiti
	     set COD_ALIQ_AMM = :new.cod_ali, DATA_AMM_INI = :new.data_amm, cod_invevend = :new.cod_invevend,
	         COD_ALIQ_AMM_FISC = :new.cod_ali_fisc, data_amm_fisc_ini = :new.data_amm_fisc,
				BUONOTA = :new.buonota, IMP_VEN = :new.imp_ven, VARIAZ = :new.variaz
	   where PK_CESPITE = :old.fk_cespite;
	ELSE
	  update patri_cespiti
	     set COD_ALIQ_AMM = :new.cod_ali, DATA_AMM_INI = :new.data_amm, cod_invevend = :new.cod_invevend,
	         COD_ALIQ_AMM_FISC = :new.cod_ali_fisc, data_amm_fisc_ini = :new.data_amm_fisc
	   where PK_CESPITE = :old.fk_cespite;
	END IF;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.PROPRIETARI_IOFU
instead of update ON SITI_H501.PROPRIETARI
declare
  cnt pls_integer;
begin
  if (:new.COD_PROPRIE is not null) then

    select count(*) into cnt
      from anag_soggetti_ext
     where cod_soggetto = :new.COD_PROPRIE;

    if (cnt = 0) then
      insert into anag_soggetti_ext (cod_soggetto) values (:new.COD_PROPRIE);
    end if;

    update anag_soggetti_ext
       set anno_red = :new.anno_red, note = :new.note,
           TIPO_DOC = :new.TIPO_DOC, NUM_DOC = :new.NUM_DOC, RIL_IL_DOC = :new.RIL_IL_DOC,
           AUTORITA_DOC = :new.AUTORITA_DOC,
           banca = :new.banca, cab = :new.cab, abi = :new.abi, c_c = :new.c_c, cin = :new.cin,
           COD_SPORT = :new.COD_SPORT, CHIAVEINQ = :new.CHIAVEINQ, COD_UTE = :new.COD_UTE, CITTADINANZA = :new.CITTADINANZA,
           COD_AFFI = :new.COD_AFFI, titolo = :new.titolo, FT_PR = :new.FT_PR,
           IBAN_PAESE = :new.IBAN_PAESE, IBAN_CIN_EUR = :new.IBAN_CIN_EUR
     where cod_soggetto = :new.COD_PROPRIE;
  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.SC_EDI_IOFU
instead of update ON SITI_H501.SC_EDI
for each row
begin

  update patri_cespiti
     set FL_SOGGETTO_ICI = :new.sogg_ici, TP_VAL_ICI = :new.tipo_ici,
         cod_metodo_stima = :new.met_stim,
         provenienza = :new.proven, COD_ALIQ_ICI = :new.codaliici,
         FL_TP_LOCAZIONE = :new.bene_rla, VAL_BENE = :new.val_tot,
         VAL_ORIGINALE = :new.val_orig, VAL_ATTUALE = :new.val_attu,
         VAL_RESIDUO = :new.val_resi, VAL_A_NUOVO = :new.val_nuovo,
         RIVALUTAZIONI = :new.rivaluta, DT_ULT_RIVAL = :new.DATARIVA,
         DT_ULT_AMM_DAL = :new.ULT_AMM_DAL, DT_ULT_AMM_AL = :new.ULT_AMM_AL,
         ULT_AMM_IMPO = :new.ACC_ESE, VAL_ATTUALE_F = :new.VAL_ATTU_F,
         VAL_RESIDUO_F = :new.VAL_RESI_F, DT_ULT_AMM_DAL_F = :new.ULT_AMM_DAL_F,
         DT_ULT_AMM_AL_F = :new.ULT_AMM_AL_F, ULT_AMM_IMPO_F = :new.ACC_ESE_F,
         ULT_FV_CONS = :new.FV_CONS, DT_ULT_FV_CONS = :new.FV_CONS_DATA,
         val_tot_f = :new.val_tot_f, val_terre_f = :new.val_terre_f,
         note=:new.desagg, val_terre = :new.val_terre
   where pk_cespite = :old.pk_cespite;

end;
/


