DROP VIEW SITI_H501.ASSIOMA_BUILDING_LIST;

/* Formatted on 18/07/2022 12:23:02 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.ASSIOMA_BUILDING_LIST
(
    NUM_ORD,
    DATINSE,
    COD_CES,
    DESCRIZIONE,
    ESTROM,
    CAT_AMM,
    COD_AMM,
    GRUPPO,
    RAG_SOC,
    BENE_RLA,
    NUMERO,
    INTERNO,
    SOGG_ICI,
    CITY,
    PROV,
    STREET,
    CAT_CES,
    CAT_ALT,
    CAT_INV
)
BEQUEATH DEFINER
AS
    SELECT pc.num_ord,
           pc.datinse,
           pc.cod_ces,
           pc.descrizione,
           pc.estrom,
           pc.cat_amm,
           pc.cod_amm,
           pc.gruppo,
           s.denominazione        AS rag_soc,
           pc.FL_TP_LOCAZIONE     AS bene_rla,
           pc.cod_via             AS numero,
           pc.interno,
           pc.FL_SOGGETTO_ICI     AS sogg_ici,
           comuni.descr           AS city,
           comuni.prov,
           vie.denom              AS street,
           tabcatce.ces_des       AS cat_ces,
           a.ces_des              AS cat_alt,
           tabcatin.des_sin       AS cat_inv
      FROM inventa        pc,
           anag_soggetti  s,
           tabcatce,
           tabcatin,
           tabcatce       a,
           comuni,
           vie
     WHERE     s.cod_soggetto = pc.cod_soc
           AND s.DATA_FINE_VAL >= TO_DATE ('99991231', 'yyyymmdd')
           AND comuni.codice = pc.cod_nazionale
           AND vie.codvia(+) = pc.cod_via
           AND vie.codcomun(+) = pc.cod_nazionale
           AND tabcatce.cat_ces = pc.cat_ces
           AND tabcatin.cat_inv = pc.cat_inv
           AND a.cat_ces(+) = pc.cat_alt;


