    N_CELOSS,
    D_CELOSS,
    N_CELCIN,
    D_CELCIN,
    CITY,
    PROV,
    STREET
)
BEQUEATH DEFINER
AS
    SELECT INVENTA.NUM_ORD,
           INVENTA.DATINSE,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.CAT_INV,
           INVENTA.CAT_CES,
           INVENTA.CAT_ALT,
           INVENTA.DESCRIZIONE,
           INVENTA.ESTROM,
           INVENTA.CAT_AMM,
           INVENTA.COD_AMM,
           INVENTA.GRUPPO,
           SC_CIM.NUMERO,
           SC_CIM.ANNOCOST,
           SC_CIM.N_FOSCOM,
           SC_CIM.N_POSCOM,
           SC_CIM.D_FOSCOM,
           SC_CIM.N_TOMFAM,
           SC_CIM.N_POSFAM,
           SC_CIM.D_TOMFAM,
           SC_CIM.N_LOCPUN,
           SC_CIM.D_LOCPUN,
           SC_CIM.N_LOCLUN,
           SC_CIM.D_LOCLUN,
           SC_CIM.N_TOMMON,
           SC_CIM.N_POSMON,
           SC_CIM.D_TOMMON,
           SC_CIM.N_CELOSS,
           SC_CIM.D_CELOSS,
           SC_CIM.N_CELCIN,
           SC_CIM.D_CELCIN,
           COMUNI.DESCR     AS CITY,
           COMUNI.PROV,
           VIE.DENOM        AS STREET
      FROM (
          (((INVENTA LEFT JOIN SC_CIM ON INVENTA.COD_CES = SC_CIM.COD_CES)
            LEFT JOIN
            COMUNI
            ON SC_CIM.CODCOM = COMUNI.CODICE)
           LEFT JOIN
           VIE
           ON SC_CIM.CODVIA = VIE.CODVIA AND SC_CIM.CODCOM = VIE.CODCOMUN)
          LEFT JOIN
          TABCATCE
          ON INVENTA.CAT_CES = TABCATCE.CAT_CES)
     WHERE TABCATCE.PATH_SC = 'SC_CIM';


