CREATE OR REPLACE FORCE VIEW SITI_H501.CENTRIRESP_CESPITI
(
    COD_CESPITE,
    FK_SETTORE,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL
)
BEQUEATH DEFINER
AS
      SELECT DISTINCT ces_object.cod_cespite,
                      centriresp.FK_SETTORE,
                      centriresp.DATA_INIZIO_VAL,
                      centriresp.DATA_FINE_VAL
        FROM centriresp, ces_object
       WHERE     centriresp.fk_object = ces_object.fk_object
             AND centriresp.tipo = ces_object.tipo
             AND data_fine_val = TO_DATE ('31129999', 'ddmmyyyy')
    GROUP BY ces_object.cod_cespite,
             centriresp.FK_SETTORE,
             centriresp.DATA_INIZIO_VAL,
             centriresp.DATA_FINE_VAL;


