    COMUNE,
    NUMERO,
    ESTROM
)
BEQUEATH DEFINER
AS
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           SC_EDI_VIE.DENOM,
           SC_EDI_VIE.COMUNE,
           SC_EDI_VIE.NUMERO,
           INVENTA.ESTROM
      FROM INVENTA, SC_EDI_VIE
     WHERE (INVENTA.COD_CES(+) = SC_EDI_VIE.COD_CES)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           A.DENOM,
           A.COMUNE,
           A.NUMERO,
           INVENTA.ESTROM
      FROM INVENTA,
           (SELECT SC_CIM.COD_CES,
                   VIE.DENOM,
                   VIE.COMUNE,
                   SC_CIM.NUMERO
              FROM SC_CIM, VIE
             WHERE (    SC_CIM.CODCOM = VIE.CODCOMUN
                    AND SC_CIM.CODVIA = VIE.CODVIA)) A
     WHERE A.COD_CES = INVENTA.COD_CES(+)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           B.DENOM,
           B.COMUNE,
           B.NUMERO,
           INVENTA.ESTROM
      FROM INVENTA,
           (SELECT VIE.DENOM,
                   VIE.COMUNE,
                   SC_GIA.NUMERO,
                   SC_GIA.COD_CES
              FROM VIE, SC_GIA
             WHERE     SC_GIA.CODCOM = VIE.CODCOMUN
                   AND SC_GIA.CODVIA = VIE.CODVIA) B
     WHERE B.COD_CES = INVENTA.COD_CES(+)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           C.DENOM,
           C.COMUNE,
           C.NUMERO,
           INVENTA.ESTROM
      FROM INVENTA,
           (SELECT VIE.DENOM,
                   VIE.COMUNE,
                   SC_MON.NUMERO,
                   SC_MON.COD_CES
              FROM VIE, SC_MON
             WHERE     SC_MON.CODCOM = VIE.CODCOMUN
                   AND SC_MON.CODVIA = VIE.CODVIA) C
     WHERE C.COD_CES = INVENTA.COD_CES(+)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           D.DENOM,
           D.COMUNE,
           D.NUMERO,
           INVENTA.ESTROM
      FROM INVENTA,
           (SELECT VIE.DENOM,
                   VIE.COMUNE,
                   SC_RET.NUMERO,
                   SC_RET.COD_CES
              FROM VIE, SC_RET
             WHERE     SC_RET.CODCOM = VIE.CODCOMUN
                   AND SC_RET.CODVIA = VIE.CODVIA) D
     WHERE D.COD_CES = INVENTA.COD_CES(+)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           E.DENOM,
           E.COMUNE,
           ''     AS NUMERO,
           INVENTA.ESTROM
      FROM INVENTA,
           (SELECT VIE.DENOM, VIE.COMUNE, SC_STR.COD_CES
              FROM VIE, SC_STR
             WHERE     SC_STR.CODCOM = VIE.CODCOMUN
                   AND SC_STR.CODVIA = VIE.CODVIA) E
     WHERE E.COD_CES = INVENTA.COD_CES(+)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           ''     AS DENOM,
           ''     AS COMUNE,
           ''     AS NUMERO,
           INVENTA.ESTROM
      FROM INVENTA, SC_MOB
     WHERE (INVENTA.COD_CES = SC_MOB.COD_CES)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           ''     AS DENOM,
           ''     AS COMUNE,
           ''     AS NUMERO,
           INVENTA.ESTROM
      FROM INVENTA, SC_MOP
     WHERE (INVENTA.COD_CES = SC_MOP.COD_CES)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           ''     AS DENOM,
           ''     AS COMUNE,
           ''     AS NUMERO,
           INVENTA.ESTROM
      FROM INVENTA, SC_TEL
     WHERE (INVENTA.COD_CES = SC_TEL.COD_CES)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           ''     AS DENOM,
           ''     AS COMUNE,
           ''     AS NUMERO,
           INVENTA.ESTROM
      FROM INVENTA, SC_PRO
     WHERE (INVENTA.COD_CES = SC_PRO.COD_CES)
    UNION
    SELECT INVENTA.NUM_ORD,
           INVENTA.CAT_CES,
           INVENTA.CAT_AMM,
           INVENTA.COD_SOC,
           INVENTA.COD_CES,
           INVENTA.DESCRIZIONE,
           INVENTA.CAT_INV,
           INVENTA.COD_AMM,
           ''     AS DENOM,
           ''     AS COMUNE,
           ''     AS NUMERO,
           INVENTA.ESTROM
      FROM INVENTA, SC_COMP
     WHERE (INVENTA.COD_CES = SC_COMP.COD_CES);


