/* Formatted on 18/07/2022 12:23:02 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONS_COMP
(
    COD_SOC,
    CAT_CES,
    CAT_INV,
    COD_CES,
    ID_CES,
    DENOM,
    UNITA,
    DIMENSIONE,
    USO,
    ISDIS,
    DESCRIZIONE,
    UNI_IMM,
    SOT_IMM,
    LOC_IMM,
