           INVENTA.CAT_CES,
           INVENTA.CAT_INV,
           INVENTA.COD_CES,
           A.ID_CES,
           A.DENOM,
           A.UNITA,
           A.DIMENSIONE,
           A.USO,
           A.ISDIS,
           A.DESCRIZIONE,
           A.UNI_IMM,
           A.SOT_IMM,
           A.LOC_IMM,
           A.DESCRUNI,
           A.DESCRSOT,
           A.DESCRLOC
      FROM INVENTA,
           (SELECT IM_CMP.COD_CES,
                   IM_CMP.ID_CES,
                   IM_CMP.DENOM,
                   IM_CMP.UNITA,
