              FROM IM_CMP, IM_TPO_CMP, EDIFICI
             WHERE     IM_CMP.TIPO_CMP = IM_TPO_CMP.TPO_CMP(+)
                   AND (IM_CMP.LOC_IMM = EDIFICI.LOCALE(+))
                   AND (IM_CMP.SOT_IMM = EDIFICI.SOT_IMM(+))
                   AND (IM_CMP.UNI_IMM = EDIFICI.UNI_IMM(+))) A
