/* Formatted on 18/07/2022 12:23:02 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONS_INT
(
    N_INT,
    NINTCLI,
    DESCR,
    DESC_EST,
    TPO_ESE,
    STATO,
    PRE_CONTAB,
    CONTAB,
    IDCSL,
    NOTE,
    COL,
    DATA_SCA_COL,
    DESC_COL,
    DATA_ESE_COL,
    RICHIEDENTE,
    RIF_FAT,
    IDTEC,
    COD_CES,
    ID_INT,
    ID_CES,
    NUM_ORD,
    COD_SOC,
    CAT_INV,
    CAT_CES,
    URG
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT A.N_INT,
                    A.NINTCLI,
                    A.DESCR,
                    A.DESC_EST,
                    A.TPO_ESE,
                    A.STATO,
                    A.PRE_CONTAB,
                    A.CONTAB,
                    A.IDCSL,
                    A.NOTE,
                    A.COL,
                    A.DATA_SCA_COL,
                    A.DESC_COL,
                    A.DATA_ESE_COL,
                    A.RICHIEDENTE,
                    A.RIF_FAT,
                    A.IDTEC,
                    A.COD_CES,
                    A.ID_INT,
                    A.ID_CES,
                    A.NUM_ORD,
                    A.COD_SOC,
                    A.CAT_INV,
                    A.CAT_CES,
                    IM_CAT_LAV.DESCRIZIONE     AS URG
      FROM IM_CAT_LAV,
           IM_INTDATE,
           (SELECT IM_INTERVENTI.N_INT,
                   IM_INTERVENTI.NINTCLI,
                   IM_INTERVENTI.DESCR,
                   IM_INTERVENTI.DESC_EST,
                   IM_INTERVENTI.TPO_ESE,
                   IM_INTERVENTI.PRE_CONTAB,
                   IM_INTERVENTI.CONTAB,
                   IM_INTERVENTI.IDCSL,
                   IM_INTERVENTI.NOTE,
                   IM_INTERVENTI.COL,
                   IM_INTERVENTI.DATA_SCA_COL,
                   IM_INTERVENTI.DESC_COL,
                   IM_INTERVENTI.DATA_ESE_COL,
                   IM_INTERVENTI.RICHIEDENTE,
                   IM_INTERVENTI.RIF_FAT,
                   IM_INTERVENTI.IDTEC,
                   IM_INTERVENTI.ID_INT,
                   IM_INTERVENTI.IDCATLAV,
                   IM_CMP.COD_CES,
                   IM_CMP.ID_CES,
                   INVENTA.NUM_ORD,
                   INVENTA.COD_SOC,
                   INVENTA.CAT_INV,
                   INVENTA.CAT_CES,
                   IM_STATOINTERVENTO.DESCRIZIONE     AS STATO
              FROM IM_INTERVENTI,
                   IM_INTREL,
                   IM_CMP,
                   IM_STATOINTERVENTO,
                   INVENTA
             WHERE     IM_INTERVENTI.ID_INT = IM_INTREL.ID_INT(+)
                   AND IM_INTREL.ID_CES = IM_CMP.ID_CES(+)
                   AND IM_CMP.COD_CES = INVENTA.COD_CES(+)
                   AND IM_INTERVENTI.IDSTATOINT =
                       IM_STATOINTERVENTO.IDSTATOINT(+)
                   AND IM_INTERVENTI.GRP = 0
                   AND IM_INTERVENTI.CAPEGRP = 0) A
     WHERE     A.IDCATLAV = IM_CAT_LAV.CODICE(+)
           AND A.ID_INT = IM_INTDATE.ID_INT(+);


DROP VIEW SITI_H501.CONS_LOC;

/* Formatted on 18/07/2022 12:23:02 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONS_LOC
(
    CAT_CES,
    COD_CES,
    CAT_INV,
    COD_SOC,
    CODICE,
    COD_TCONT,
    DATA_CONT,
    CESSAZIONE,
    P_SUP_LOCA,
    SUP_LOCA,
    CAN_APPLIC,
    COGN_NOME,
    CODIMM
)
BEQUEATH DEFINER
AS
    SELECT INVENTA.CAT_CES,
           INVENTA.COD_CES,
           INVENTA.CAT_INV,
           INVENTA.COD_SOC,
           CONTRATT.CODICE,
           CONTRATT.COD_TCONT,
           CONTRATT.DATA_CONT,
           CONTRATT.CESSAZIONE,
           CONTRATT.P_SUP_LOCA,
           CONTRATT.SUP_LOCA,
           CONTRATT.CAN_APPLIC,
           ANAINQUI.COGN_NOME,
           SC_TEDI.CODIMM
      FROM CONTRATT,
           ANAINQUI,
