     WHERE     ANAINQUI.COD_INQ(+) = CONTRATT.COD_INQ
           AND CONTRATT.COD_CES = INVENTA.COD_CES(+)
           AND INVENTA.COD_CES = SC_TEDI.COD_CES(+)
           AND (   CONTRATT.ID_CONTR = 1
                OR CONTRATT.ID_CONTR = 0
                OR CONTRATT.ID_CONTR IS NULL);


