DROP VIEW SITI_H501.CONTRATT_CESPITI_VALID;

/* Formatted on 18/07/2022 12:23:02 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONTRATT_CESPITI_VALID
(
    CODICE,
    ID_CONTR,
    COD_CES,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    SUP_LOCA,
    P_SUP_LOCA
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT z.codice,
                    cc.id_contr,
                    z.cod_ces,
                    z.data_inizio_val,
                    z.data_fine_val,
                    ROUND (z.sup_loca, 2),
                    z.p_sup_loca
      FROM (SELECT atto_inizio               AS codice,
                   cod_cespite               AS cod_ces,
                   data_inizio_val,
                   data_fine_val,
                   sup_loca,
                   DECODE (subloca,
                           0, Patri_Pck.get_pct_sup_cespite_locata1 (
                                  pk_cespite,
                                  sup_loca,
                                  atto_inizio,
                                  data_sup),
                           Patri_Pck.get_pct_sup_cespite_sublocata1 (
                               pk_cespite,
                               sup_loca,
                               atto_inizio,
                               data_sup))    AS p_sup_loca
              FROM (SELECT ff.atto_inizio,
                           ff.cod_cespite,
                           ff.data_inizio_val,
                           ff.data_fine_val,
                           ff.data_sup,
                           ff.pk_cespite,
                           ff.subloca,
                           DECODE (
                               ff.subloca,
                               0, Patri_Pck.get_superficie_cespite_locata (
                                      ff.pk_cespite,
                                      ff.atto_inizio,
                                      data_sup),
                               Patri_Pck.get_sup_cespite_sublocata (
                                   ff.pk_cespite,
                                   ff.atto_inizio,
                                   data_sup))    AS sup_loca
                      FROM (SELECT DISTINCT
                                   subloca,
                                   loc.atto_inizio,
                                   loc.cod_cespite,
                                   TRUNC (dt_var.data_inizio_val)
                                       AS data_inizio_val,
                                   CASE
                                       WHEN dt_var.data_fine_val =
                                            TO_DATE ('31129999', 'DDMMYYYY')
                                       THEN
                                           NULL
                                       ELSE
                                           TRUNC (dt_var.data_fine_val,
                                                  'DDD')
                                   END
                                       AS data_fine_val,
                                   GREATEST (
                                         TRUNC (dt_var.data_inizio_val,
                                                'DDD')
                                       + (1 - (1 / 24 / 60 / 60)),
                                       (SELECT MIN (pccv.data_inizio)
                                          FROM patri_cespiti_cat_viw pccv
                                         WHERE pccv.pk_cespite =
                                               loc.pk_cespite))
                                       AS data_sup,
                                   loc.pk_cespite
                              FROM SITIFILE_ATTI_DOC             sfad,
                                   SITIFILE_ATTI                 sfa,
                                   SITIFILE_DOCUMENTI            sfd,
                                   SITIFILE_DOCUMENTI_CAMPI_EXT  sfdce,
                                   (SELECT DISTINCT
                                           0                  AS subloca,
                                           'U'                AS etype,
                                           scia1.cod_nazionale,
                                           scia1.foglio,
                                           scia1.Particella,
                                           scia1.sub,
                                           scia1.unimm,
                                           pc.pk_cespite,
                                           pc.cod_cespite,
                                           scia2.atto_ini     AS atto_inizio
                                      FROM CONS_CSUI_TAB      scia1,
                                           CONS_URUI_TAB      scia2,
                                           PATRI_CESPITI_UIU  pcu,
                                           PATRI_CESPITI      pc
                                     WHERE     scia1.cod_nazionale =
                                               scia2.cod_nazionale
                                           AND scia1.foglio = scia2.foglio
                                           AND scia1.Particella =
                                               scia2.Particella
                                           AND scia1.sub = scia2.sub
                                           AND scia1.unimm = scia2.unimm
                                           AND scia1.data_inizio <=
                                               scia2.data_fine
                                           AND scia1.data_fine >=
                                               scia2.data_inizio
                                           AND scia1.tipo_titolo IN (1, 3)
                                           AND scia1.pkid_csui = pcu.pk_tit
                                           AND scia1.tipo_titolo =
                                               pcu.tipo_titolo
                                           AND pcu.fk_cespite = pc.pk_cespite
                                    UNION
                                    SELECT DISTINCT
                                           0                  AS subloca,
                                           'P'                AS etype,
                                           scia1.cod_nazionale,
                                           scia1.foglio,
                                           scia1.Particella,
                                           scia1.sub,
                                           NULL               AS unimm,
                                           pc.pk_cespite,
                                           pc.cod_cespite,
                                           scia2.atto_ini     AS atto_inizio
                                      FROM CONS_CONS_TAB       scia1,
                                           CONS_UFRE_TAB       scia2,
                                           PATRI_CESPITI_PART  pcp,
                                           PATRI_CESPITI       pc
                                     WHERE     scia1.cod_nazionale =
                                               scia2.cod_nazionale
                                           AND scia1.foglio = scia2.foglio
                                           AND scia1.Particella =
                                               scia2.Particella
                                           AND scia1.sub = scia2.sub
                                           AND scia1.data_inizio <=
                                               scia2.data_fine
                                           AND scia1.data_fine >=
                                               scia2.data_inizio
                                           AND scia1.tipo_titolo IN (1, 3)
                                           AND scia1.pkid_cons = pcp.pk_tit
                                           AND scia1.tipo_titolo =
                                               pcp.tipo_titolo
                                           AND pcp.fk_cespite = pc.pk_cespite
                                    UNION
                                    SELECT DISTINCT 1       AS subloca,
                                                    'U'     AS etype,
                                                    scia2.cod_nazionale,
                                                    scia2.foglio,
                                                    scia2.Particella,
                                                    scia2.sub,
                                                    scia2.unimm,
                                                    pc.pk_cespite,
                                                    pc.cod_cespite,
                                                    cst.atto_inizio
                                      FROM CONS_URUI_TAB      scia2,
                                           CONS_SUBLOC_TAB    cst,
                                           PATRI_CESPITI_UIU  pcu,
                                           PATRI_CESPITI      pc
                                     WHERE     cst.fkid_atto = scia2.atto_ini
                                           AND (   cst.obj_type = 'U'
                                                OR cst.obj_type = 'V')
                                           AND scia2.pkid_urui = pcu.pk_tit
                                           AND scia2.tipo_titolo =
                                               pcu.tipo_titolo
                                           AND pcu.fk_cespite = pc.pk_cespite
                                    UNION
                                    SELECT DISTINCT 1        AS subloca,
                                                    'P'      AS etype,
                                                    scia2.cod_nazionale,
                                                    scia2.foglio,
                                                    scia2.Particella,
                                                    scia2.sub,
                                                    NULL     AS unimm,
                                                    pc.pk_cespite,
                                                    pc.cod_cespite,
                                                    cst.atto_inizio
                                      FROM CONS_UFRE_TAB       scia2,
                                           CONS_SUBLOC_TAB     cst,
                                           PATRI_CESPITI_PART  pcp,
                                           PATRI_CESPITI       pc
                                     WHERE     cst.fkid_atto = scia2.atto_ini
                                           AND cst.obj_type = 'P'
                                           AND scia2.pkid_uffr = pcp.pk_tit
                                           AND scia2.tipo_titolo =
                                               pcp.tipo_titolo
                                           AND pcp.fk_cespite = pc.pk_cespite)
                                   loc,
                                   (SELECT *
                                      FROM (  SELECT etype,
                                                     cod_nazionale,
                                                     foglio,
                                                     Particella,
                                                     sub,
                                                     unimm,
                                                     atto_ini,
                                                     MAX (data_inizio)
                                                         AS data_inizio_val,
                                                     data_fine
                                                         AS data_fine_val
                                                FROM (SELECT A.etype,
                                                             A.cod_nazionale,
                                                             A.foglio,
                                                             A.Particella,
                                                             A.sub,
                                                             A.unimm,
                                                             A.atto_ini,
                                                             A.data_var
                                                                 AS data_inizio,
                                                             B.data_var
                                                                 AS data_fine
                                                        FROM (SELECT DISTINCT
                                                                     etype,
                                                                     cod_nazionale,
                                                                     foglio,
                                                                     Particella,
                                                                     sub,
                                                                     unimm,
                                                                     atto_ini,
                                                                     data_var
                                                                FROM contratt_var)
                                                             A,
                                                             (SELECT DISTINCT
                                                                     etype,
                                                                     cod_nazionale,
                                                                     foglio,
                                                                     Particella,
                                                                     sub,
                                                                     unimm,
                                                                     atto_ini,
                                                                     data_var
                                                                FROM contratt_var)
                                                             B
                                                       WHERE     A.cod_nazionale =
                                                                 B.cod_nazionale
                                                             AND A.foglio =
                                                                 B.foglio
                                                             AND A.Particella =
                                                                 B.Particella
                                                             AND A.sub = B.sub
                                                             AND NVL (A.unimm,
                                                                      -1) =
                                                                 NVL (B.unimm,
                                                                      -1)
                                                             AND A.etype =
                                                                 B.etype
                                                             AND A.atto_ini =
                                                                 B.atto_ini
                                                             AND A.data_var <
                                                                 B.data_var)
                                            GROUP BY etype,
                                                     cod_nazionale,
                                                     foglio,
                                                     Particella,
                                                     sub,
                                                     unimm,
                                                     atto_ini,
                                                     data_fine)
                                     WHERE    data_fine_val =
                                              TO_DATE ('31129999',
                                                       'ddmmyyyy')
                                           OR (    data_fine_val <
                                                   TO_DATE ('31129999',
                                                            'ddmmyyyy')
                                               AND TRUNC (data_fine_val,
                                                          'DDD') <>
                                                   TRUNC (data_inizio_val,
                                                          'DDD'))) dt_var
                             WHERE     sfa.pkid_atto = loc.atto_inizio
                                   AND sfa.fkid_tipo_atto = -22
                                   AND sfad.fkid_atto = sfa.pkid_atto
                                   AND sfd.pkid_doc = sfad.fkid_doc
                                   AND sfd.fkid_tipo_doc = -27
                                   AND sfdce.fkid_doc = sfd.pkid_doc
                                   AND dt_var.atto_ini = loc.atto_inizio
                                   AND dt_var.atto_ini = loc.atto_inizio
                                   AND dt_var.etype = loc.etype
                                   AND dt_var.cod_nazionale =
                                       loc.cod_nazionale
                                   AND dt_var.foglio = loc.foglio
                                   AND dt_var.Particella = loc.Particella
                                   AND dt_var.sub = loc.sub
                                   AND NVL (dt_var.unimm, -1) =
                                       NVL (loc.unimm, -1)) ff)
             WHERE sup_loca <> -1) z,
           contratt_cespiti  cc
     WHERE z.codice = cc.codice AND z.cod_ces = cc.cod_ces
-- query completamente ristrutturata
;


DROP VIEW SITI_H501.CONTRATT_CESPITI_VALID_PK;

/* Formatted on 18/07/2022 12:23:03 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.CONTRATT_CESPITI_VALID_PK
(
    CODICE,
    ID_CONTR,
    COD_CES,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    SUP_LOCA,
    P_SUP_LOCA,
    PK_CESPITE
)
BEQUEATH DEFINER
AS
    SELECT a.codice,
           cc.id_contr,
           a.cod_ces,
           a.data_inizio_val,
           a.data_fine_val,
           a.sup_loca,
           a.p_sup_loca,
           a.pk_cespite
      FROM (SELECT DISTINCT
                   loc.atto_inizio
                       AS codice,
                   loc.cod_cespite
                       AS cod_ces,
                   TRUNC (dt_var.data_inizio_val)
                       AS data_inizio_val,
                   CASE
                       WHEN dt_var.data_fine_val =
                            TO_DATE ('31129999', 'DDMMYYYY')
                       THEN
                           NULL
                       ELSE
                           TRUNC (dt_var.data_fine_val, 'DDD')
                   END
                       AS data_fine_val,
                   ROUND (patri_pck.get_superficie_cespite_locata (
                              loc.pk_cespite,
                              loc.atto_inizio,
                              GREATEST (
                                  dt_var.data_inizio_val + (1 / 24 / 60 / 60),
                                  (SELECT MIN (data_inizio)
                                     FROM patri_cespiti_cat_viw
                                    WHERE pk_cespite = loc.pk_cespite))),
                          1)
                       AS sup_loca,
                   patri_pck.get_pct_sup_cespite_locata (
                       loc.pk_cespite,
                       loc.atto_inizio,
                       GREATEST (dt_var.data_inizio_val + (1 / 24 / 60 / 60),
                                 (SELECT MIN (data_inizio)
                                    FROM patri_cespiti_cat_viw
                                   WHERE pk_cespite = loc.pk_cespite)))
                       AS p_sup_loca,
                   loc.pk_cespite
              FROM sitifile_atti_doc             sfad,
                   sitifile_atti                 sfa,
                   sitifile_documenti            sfd,
                   sitifile_documenti_campi_ext  sfdce,
                   (SELECT DISTINCT 'U'     AS etype,
                                    scia1.cod_nazionale,
                                    scia1.foglio,
                                    scia1.particella,
                                    scia1.sub,
                                    scia1.unimm,
                                    pc.pk_cespite,
                                    pc.cod_cespite,
                                    scia2.atto_inizio
                      FROM siticonduz_imm_all2  scia1,
                           siticonduz_imm_all2  scia2,
                           patri_cespiti_uiu    pcu,
                           patri_cespiti        pc
                     WHERE     scia1.cod_nazionale = scia2.cod_nazionale
                           AND scia1.foglio = scia2.foglio
                           AND scia1.particella = scia2.particella
                           AND scia1.sub = scia2.sub
                           AND scia1.unimm = scia2.unimm
                           AND scia1.data_inizio <= scia2.data_fine
                           AND scia1.data_fine >= scia2.data_inizio
                           AND scia1.tipo_titolo IN (1, 3)
                           AND scia2.tipo_titolo NOT IN (1, 3)
                           AND scia1.pkid_tit = pcu.pk_tit
                           AND scia1.tipo_titolo = pcu.tipo_titolo
                           AND pcu.fk_cespite = pc.pk_cespite
                    UNION
                    SELECT DISTINCT 'P'      AS etype,
                                    scia1.cod_nazionale,
                                    scia1.foglio,
                                    scia1.particella,
                                    scia1.sub,
                                    NULL     AS unimm,
                                    pc.pk_cespite,
                                    pc.cod_cespite,
                                    scia2.atto_inizio
                      FROM siticond_all2       scia1,
                           siticond_all2       scia2,
                           patri_cespiti_part  pcp,
                           patri_cespiti       pc
                     WHERE     scia1.cod_nazionale = scia2.cod_nazionale
                           AND scia1.foglio = scia2.foglio
                           AND scia1.particella = scia2.particella
                           AND scia1.sub = scia2.sub
                           AND scia1.data_inizio <= scia2.data_fine
                           AND scia1.data_fine >= scia2.data_inizio
                           AND scia1.tipo_titolo IN (1, 3)
                           AND scia2.tipo_titolo NOT IN (1, 3)
                           AND scia1.pkid_tit = pcp.pk_tit
                           AND scia1.tipo_titolo = pcp.tipo_titolo
                           AND pcp.fk_cespite = pc.pk_cespite) loc,
                   (  SELECT etype,
                             cod_nazionale,
                             foglio,
                             particella,
                             sub,
                             unimm,
                             atto_ini,
                             MAX (data_inizio)     AS data_inizio_val,
                             data_fine             AS data_fine_val
                        FROM (SELECT a.etype,
                                     a.cod_nazionale,
                                     a.foglio,
                                     a.particella,
                                     a.sub,
                                     a.unimm,
                                     a.atto_ini,
                                     a.data_var     AS data_inizio,
                                     b.data_var     AS data_fine
                                FROM (SELECT DISTINCT etype,
                                                      cod_nazionale,
                                                      foglio,
                                                      particella,
                                                      sub,
                                                      unimm,
                                                      atto_ini,
                                                      data_var
                                        FROM contratt_var) a,
                                     (SELECT DISTINCT etype,
                                                      cod_nazionale,
                                                      foglio,
                                                      particella,
                                                      sub,
                                                      unimm,
                                                      atto_ini,
                                                      data_var
                                        FROM contratt_var) b
                               WHERE     a.cod_nazionale = b.cod_nazionale
                                     AND a.foglio = b.foglio
                                     AND a.particella = b.particella
                                     AND a.sub = b.sub
                                     AND NVL (a.unimm, -1) = NVL (b.unimm, -1)
                                     AND a.etype = b.etype
                                     AND a.atto_ini = b.atto_ini
                                     AND a.data_var < b.data_var)
                    GROUP BY etype,
                             cod_nazionale,
                             foglio,
                             particella,
                             sub,
                             unimm,
                             atto_ini,
                             data_fine) dt_var
             WHERE     sfa.pkid_atto = loc.atto_inizio
                   AND sfa.fkid_tipo_atto = -22
                   AND sfad.fkid_atto = sfa.pkid_atto
                   AND sfd.pkid_doc = sfad.fkid_doc
                   AND sfd.fkid_tipo_doc = -27
                   AND sfdce.fkid_doc = sfd.pkid_doc
                   AND dt_var.atto_ini = loc.atto_inizio
                   AND dt_var.etype = loc.etype
                   AND dt_var.cod_nazionale = loc.cod_nazionale
                   AND dt_var.foglio = loc.foglio
                   AND dt_var.particella = loc.particella
                   AND dt_var.sub = loc.sub
                   AND NVL (dt_var.unimm, -1) = NVL (loc.unimm, -1)) a,
           contratt_cespiti  cc
     WHERE     sup_loca <> -1
           AND a.codice = cc.codice
           AND a.cod_ces = cc.cod_ces
           AND (   a.data_fine_val IS NULL
                OR (    a.data_fine_val IS NOT NULL
                    AND a.data_fine_val <> a.data_inizio_val))
    UNION                                                       --SUBLOCAZIONI
    SELECT a.codice,
           cc.id_contr,
           a.cod_ces,
           a.data_inizio_val,
           a.data_fine_val,
           a.sup_loca,
           a.p_sup_loca,
           a.pk_cespite
      FROM (SELECT DISTINCT
                   loc.atto_inizio
                       AS codice,
                   loc.cod_cespite
                       AS cod_ces,
                   TRUNC (dt_var.data_inizio_val)
                       AS data_inizio_val,
                   CASE
                       WHEN dt_var.data_fine_val =
                            TO_DATE ('31129999', 'DDMMYYYY')
                       THEN
                           NULL
                       ELSE
                           TRUNC (dt_var.data_fine_val, 'DDD')
                   END
                       AS data_fine_val,
                   ROUND (
                       patri_pck.get_sup_cespite_sublocata (
                           loc.pk_cespite,
                           loc.atto_inizio,
                           dt_var.data_inizio_val + (1 / 24 / 60 / 60)),
                       1)
                       AS sup_loca,
                   patri_pck.get_pct_sup_cespite_sublocata (
                       loc.pk_cespite,
                       loc.atto_inizio,
                       dt_var.data_inizio_val + (1 / 24 / 60 / 60))
                       AS p_sup_loca,
                   loc.pk_cespite
              FROM sitifile_atti_doc             sfad,
                   sitifile_atti                 sfa,
                   sitifile_documenti            sfd,
                   sitifile_documenti_campi_ext  sfdce,
                   (SELECT DISTINCT 'U'     AS etype,
                                    scia2.cod_nazionale,
                                    scia2.foglio,
                                    scia2.particella,
                                    scia2.sub,
                                    scia2.unimm,
                                    pc.pk_cespite,
                                    pc.cod_cespite,
                                    cst.atto_inizio
                      FROM siticonduz_imm_all2  scia2,
                           cons_subloc_tab      cst,
                           patri_cespiti_uiu    pcu,
                           patri_cespiti        pc
                     WHERE     scia2.tipo_titolo NOT IN (1, 3)
                           AND cst.fkid_atto = scia2.atto_inizio
                           AND (cst.obj_type = 'U' OR cst.obj_type = 'V')
                           AND scia2.pkid_tit = pcu.pk_tit
                           AND scia2.tipo_titolo = pcu.tipo_titolo
                           AND pcu.fk_cespite = pc.pk_cespite
                    UNION
                    SELECT DISTINCT 'P'      AS etype,
                                    scia2.cod_nazionale,
                                    scia2.foglio,
                                    scia2.particella,
                                    scia2.sub,
                                    NULL     AS unimm,
                                    pc.pk_cespite,
                                    pc.cod_cespite,
                                    cst.atto_inizio
                      FROM siticond_all2       scia2,
                           cons_subloc_tab     cst,
                           patri_cespiti_part  pcp,
                           patri_cespiti       pc
                     WHERE     scia2.tipo_titolo NOT IN (1, 3)
                           AND cst.fkid_atto = scia2.atto_inizio
                           AND cst.obj_type = 'P'
                           AND scia2.pkid_tit = pcp.pk_tit
                           AND scia2.tipo_titolo = pcp.tipo_titolo
                           AND pcp.fk_cespite = pc.pk_cespite) loc,
                   (  SELECT etype,
                             cod_nazionale,
                             foglio,
                             particella,
                             sub,
                             unimm,
                             atto_ini,
                             MAX (data_inizio)     AS data_inizio_val,
                             data_fine             AS data_fine_val
                        FROM (SELECT a.etype,
                                     a.cod_nazionale,
                                     a.foglio,
                                     a.particella,
                                     a.sub,
                                     a.unimm,
                                     a.atto_ini,
                                     a.data_var     AS data_inizio,
                                     b.data_var     AS data_fine
                                FROM (SELECT DISTINCT etype,
                                                      cod_nazionale,
                                                      foglio,
                                                      particella,
                                                      sub,
                                                      unimm,
                                                      atto_ini,
                                                      data_var
                                        FROM contratt_var) a,
                                     (SELECT DISTINCT etype,
                                                      cod_nazionale,
                                                      foglio,
                                                      particella,
                                                      sub,
                                                      unimm,
                                                      atto_ini,
                                                      data_var
                                        FROM contratt_var) b
                               WHERE     a.cod_nazionale = b.cod_nazionale
                                     AND a.foglio = b.foglio
                                     AND a.particella = b.particella
                                     AND a.sub = b.sub
                                     AND NVL (a.unimm, -1) = NVL (b.unimm, -1)
                                     AND a.etype = b.etype
                                     AND a.atto_ini = b.atto_ini
                                     AND a.data_var < b.data_var)
                    GROUP BY etype,
                             cod_nazionale,
                             foglio,
                             particella,
                             sub,
                             unimm,
                             atto_ini,
                             data_fine) dt_var
             WHERE     sfa.pkid_atto = loc.atto_inizio
                   AND sfa.fkid_tipo_atto = -22
                   AND sfad.fkid_atto = sfa.pkid_atto
                   AND sfd.pkid_doc = sfad.fkid_doc
                   AND sfd.fkid_tipo_doc = -27
                   AND sfdce.fkid_doc = sfd.pkid_doc
                   AND dt_var.atto_ini = loc.atto_inizio
                   AND dt_var.atto_ini = loc.atto_inizio
