                   AND NVL (dt_var.unimm, -1) = NVL (loc.unimm, -1)) a,
           contratt_cespiti  cc
     WHERE     sup_loca <> -1
           AND a.codice = cc.codice
           AND a.cod_ces = cc.cod_ces
           AND (   a.data_fine_val IS NULL
                OR (    a.data_fine_val IS NOT NULL
                    AND a.data_fine_val <> a.data_inizio_val));


DROP VIEW SITI_H501.SETTORI_CES_OBJECT;

/* Formatted on 18/07/2022 12:23:03 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW SITI_H501.SETTORI_CES_OBJECT
(
    COD_CESPITE,
    FK_SETTORE
)
BEQUEATH DEFINER
AS
    SELECT ces_object.cod_cespite, settori_cr_all.fk_settore
      FROM ces_object, settori_cr_all
     WHERE     settori_cr_all.cod_nazionale = ces_object.COD_NAZIONALE
           AND settori_cr_all.foglio = ces_object.FOGLIO
           AND settori_cr_all.particella = ces_object.PARTICELLA
           AND settori_cr_all.sub = ces_object.SUB
           AND ces_object.TIPO = 'P'
    UNION ALL
    SELECT DISTINCT ces_object.cod_cespite, settori_cr_all.fk_settore
      FROM ces_object, settori_cr_all
     WHERE     settori_cr_all.cod_nazionale = ces_object.COD_NAZIONALE
           AND settori_cr_all.foglio = ces_object.FOGLIO
           AND settori_cr_all.particella = ces_object.PARTICELLA
           AND settori_cr_all.sub = ces_object.SUB
           AND settori_cr_all.unimm = ces_object.unimm
           AND ces_object.TIPO = 'U'
    UNION ALL
    SELECT DISTINCT ces_object.cod_cespite, settori_cr_all.fk_settore
      FROM ces_object, settori_cr_all
     WHERE     settori_cr_all.cod_nazionale = ces_object.COD_NAZIONALE
           AND settori_cr_all.foglio = ces_object.FOGLIO
           AND settori_cr_all.particella = ces_object.PARTICELLA
           AND settori_cr_all.sub = ces_object.SUB
           AND settori_cr_all.unimm = ces_object.unimm
           AND settori_cr_all.vano = ces_object.vano
           AND ces_object.TIPO = 'V'
    UNION ALL
    SELECT DISTINCT ces_object.cod_cespite, settori_cr_all.fk_settore
      FROM ces_object, settori_cr_all
     WHERE     settori_cr_all.cod_nazionale = ces_object.COD_NAZIONALE
           AND settori_cr_all.foglio = ces_object.FOGLIO
           AND settori_cr_all.particella = ces_object.PARTICELLA
           AND settori_cr_all.sub = ces_object.SUB
           AND ces_object.TIPO = 'A';

DROP VIEW CS_ROMA.CS_O_OPERATORE_ANAGRAFICA;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_O_OPERATORE_ANAGRAFICA
(
    ID,
    USERNAME,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    TOOLTIP,
    ABILITATO,
    COGNOME,
    NOME,
    CODICE_FISCALE,
    DATA_NASCITA,
    COMUNE_NASCITA,
    EMAIL
)
BEQUEATH DEFINER
AS
    (SELECT op."ID",
            op."USERNAME",
            op."DATA_INIZIO_VAL",
            op."DATA_FINE_VAL",
            op."TOOLTIP",
            op."ABILITATO",
            anag.cognome,
            anag.nome,
            anag.codice_fiscale,
            anag.data_nascita,
            anag.comune_nascita,
            u.email
       FROM cs_o_operatore  op
            LEFT JOIN am_anagrafica anag ON fk_am_user = op.username
            LEFT JOIN am_user u ON u.name = op.username);


DROP VIEW CS_ROMA.CS_RDC_ANAGRAFICA_GEPI;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_RDC_ANAGRAFICA_GEPI
(
    ID_DOMANDA,
    COGNOME,
    NOME,
    CF,
    SESSO,
    DATA_NASCITA,
    NAS_COMUNE_COD,
    NAZIONALITA,
    RES_COMUNE_COD,
    RES_INDIRIZZO,
    TELEFONO,
    CELLULARE,
    EMAIL,
    AMBITO_APPARTENENZA,
    DATA_PRESENTAZIONE_DOMANDA,
    RICHIEDENTE,
    SOGGETTO_ID
)
BEQUEATH DEFINER
AS
    (SELECT GEPI.ID_DOMANDA,
            GEPI.NOME_COMPLETO     AS COGNOME,
            NULL                   AS NOME,
            UPPER (GEPI.CF)        CF,
            GEPI.SESSO,
            GEPI.DATA_NASCITA,
            GEPI.NAS_COMUNE_COD,
            GEPI.NAZIONALITA,
            GEPI.RES_COMUNE_COD,
            GEPI.RES_INDIRIZZO,
            GEPI.TELEFONO,
            GEPI.CELLULARE,
            GEPI.EMAIL,
            GEPI.AMBITO_APPARTENENZA,
            GEPI.DATA_PRESENTAZIONE_DOMANDA,
            GEPI.RICHIEDENTE,
            casi.anagrafica_id     soggetto_id
       FROM RDC_ANAGRAFICA_GEPI  gepi
            LEFT JOIN (SELECT s.anagrafica_Id, a.*
                         FROM CS_A_ANAGRAFICA A, CS_A_SOGGETTO S
                        WHERE s.anagrafica_Id = a.id) casi
                ON (casi.cf = gepi.cf)
      WHERE GEPI.RES_COMUNE_COD IN
                (SELECT COD_CATASTALE FROM CS_O_ORGANIZZAZIONE));


DROP VIEW CS_ROMA.CS_SS_PRIVACY;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_SS_PRIVACY
(
    CF,
    DT_INS,
    USER_INS,
    SCHEDA_ID,
    ORGANIZZAZIONE_ID,
    DT_SOTTOSCRIZIONE,
    FLAG_CENTRI_IMPIEGO
)
BEQUEATH DEFINER
AS
    (SELECT ssp.CF,
            ssp.DT_INS,
            ssp.USER_INS,
            ssp.SCHEDA_ID,
            ssp.ORGANIZZAZIONE_ID,
            ssp.DT_SOTTOSCRIZIONE,
            SOCLAV.FLAG_CONSENSO     AS FLAG_CENTRI_IMPIEGO
       FROM SS_SCHEDA_PRIVACY  SSP
            LEFT JOIN CS_O_ORGANIZZAZIONE o ON (ORGANIZZAZIONE_ID = o.ID)
            LEFT JOIN RDC_CONSENSI_SOC_TO_LAV SOCLAV
                ON     SOCLAV.CF = SSP.CF
                   AND (SOCLAV.COD_ENTE_FROM = O.COD_CATASTALE));


DROP VIEW CS_ROMA.CS_TB_MAP_STACIV_GIT2CS;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_TB_MAP_STACIV_GIT2CS
(
    ENTE,
    COD_ORIG,
