)
BEQUEATH DEFINER
AS
    SELECT DISTINCT map.ente, map.cod_orig, map.cod_dest
      FROM IDS_MAPPING_GIT2CS map, cs_o_organizzazione o
     WHERE     UPPER (o.COD_CATASTALE) = UPPER (map.ente)
           AND CAMPO_ORIG = 'SIT_D_PERS_FAM.STATO_CIVILE'
           AND CAMPO_DEST = 'CS_TB_STATO_CIVILE.ID';


