DROP VIEW CS_ROMA.CS_VISTA_CASI_SS;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_VISTA_CASI_SS
(
    ID_SCHEDA,
    PROVENIENZA,
    ACCESSO_DATA,
    ACCESSO_OPER_CF,
    ACCESSO_OPER_COGNOME,
    ACCESSO_OPER_NOME,
    ACCESSO_UFFICIO,
    SEGNALATO_COGNOME,
    SEGNALATO_NOME,
    SEGNALATO_CF,
    TIPO_INTERVENTO,
    CATEGORIA_SOCIALE_ID
)
BEQUEATH DEFINER
AS
    SELECT ss.id             id_scheda,
           cs.provenienza,
           SSA.DATA          accesso_data,
           ssa.operatore     accesso_oper_cf,
           anag.cognome      accesso_oper_cognome,
           anag.nome         accesso_oper_nome,
           uff.nome          accesso_ufficio,
           sa.cognome        segnalato_cognome,
           sa.nome           segnalato_nome,
           SA.CF             segnalato_cf,
           TIPO.TIPO,
           REL.CATEGORIA_SOCIALE_ID
      FROM cs_ss_scheda_segr  cs,
           ss_scheda          ss
           LEFT JOIN SS_REL_SCHEDA_CAT_SOC rel ON rel.scheda_id = ss.id
           LEFT JOIN ss_scheda_segnalato se ON se.id = ss.segnalato
           LEFT JOIN ss_anagrafica sa ON se.anagrafica = sa.id
           LEFT JOIN ss_scheda_accesso ssa ON ssa.id = ss.accesso
           LEFT JOIN SS_UFFICIO uff ON (uff.ID = SSA.REL_UPO_UFFICIO_ID)
           LEFT JOIN am_anagrafica anag ON ANAG.FK_AM_USER = SSA.OPERATORE
           LEFT JOIN SS_TIPO_SCHEDA tipo ON tipo.id = ss.tipo
     WHERE     cs.scheda_id = ss.id
           AND cs.provenienza = 'SS'
           AND ss.completa = 1
           AND ss.eliminata = 0
    -- la prima query prende i dati di Segretariato Sociale da CS_SS_SCHEDA_SEGR (TIPO_SCHEDA = SS)
    UNION
    -- la seconda query prende i dati degli altri sistemi (di fatto, l'intera tabella CS_SCHEDE_ALTRA_PROVENIENZA)
    SELECT cs_altri.id_scheda_segr,
           cs_altri.provenienza,
           cs_altri.accesso_data,
           cs_altri.accesso_oper_cf,
           cs_altri.accesso_oper_cognome,
           cs_altri.accesso_oper_nome,
           cs_altri.accesso_ufficio,
           cs_altri.segnalato_cognome,
           cs_altri.segnalato_nome,
           cs_altri.segnalato_cf,
           cs_altri.tipo_intervento,
           cs_altri.categoria_sociale_id
      FROM CS_SCHEDE_ALTRA_PROVENIENZA cs_altri;


DROP VIEW CS_ROMA.CS_VISTA_INTERVENTI_CASO;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_VISTA_INTERVENTI_CASO
(
    ID,
    TIPOINTERVENTO,
    TIPOINTERVENTOCUSTOM,
    INIZIO_DAL,
    INIZIO_AL,
    FINE_DAL,
    FINE_AL,
    STATO,
    CASO_ID
)
BEQUEATH DEFINER
AS
      SELECT DISTINCT i.id,
                      TIPOINT.DESCRIZIONE      tipoIntervento,
                      tipoCust.descrizione     tipoInterventoCustom,
                      i.inizio_dal,
                      i.inizio_al,
                      i.fine_dal,
                      i.fine_al,
                      s.tipo                   stato,
                      caso_id
        FROM cs_d_diario      d,
             cs_flg_intervento fgl,
             cs_i_intervento  i
             LEFT JOIN cs_i_intervento_eseg_mast m ON i.id = m.intervento_id
             LEFT JOIN cs_i_intervento_eseg e
                 ON e.intervento_eseg_mast_id = m.id
             LEFT JOIN CS_CFG_INT_ESEG_STATO s
                 ON (s.id = e.stato_id AND s.tipo = 'E')
             LEFT JOIN CS_C_TIPO_INTERVENTO tipoInt
                 ON (tipoInt.id = I.SCTI_TIPO_INTERVENTO_ID)
             LEFT JOIN CS_C_TIPO_INTERVENTO_CUSTOM tipoCust
                 ON (tipoCust.id = I.TIPO_INTERVENTO_CUSTOM_ID)
       WHERE d.id = fgl.diario_id AND fgl.intervento_id = i.id
    ORDER BY d.caso_id, i.id;


DROP VIEW CS_ROMA.CS_VISTA_PAI;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_VISTA_PAI
(
    DIARIO_ID,
    SETTORE_ID,
    VIS_SECONDO_LIVELLO,
    DATA_ULTIMA_MODIFICA,
    OP_ULTIMA_MODIFICA,
    TIPO_BENEFICIARIO,
    CASO_ID,
    TIPO_PAI_ID,
    TIPO_PAI_DESC,
    DT_ATTIVAZIONE_DA,
    DT_CHIUSURA_DA,
    DATA_CHIUSURA_PREVISTA,
    CHIUSO,
    DA_CHIUDERE,
    DATA_MONITORAGGIO,
    VERIFICA_UNITA_MISURA,
    VERIFICA_OGNI,
    DA_CONTROLLARE,
    OBIETTIVI_BREVE,
    RAGGIUNTI_BREVE,
    OBIETTIVI_MEDIO,
    RAGGIUNTI_MEDIO,
    OBIETTIVI_LUNGO,
    RAGGIUNTI_LUNGO
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT
           p.diario_id,
           OS.SETTORE_ID,
           D.VIS_SECONDO_LIVELLO,
           NVL (D.DT_MOD, D.DT_INS)
               DATA_ULTIMA_MODIFICA,
           NVL (ANAO.COGNOME || ' ' || ANAO.NOME, ANAO.CODICE_FISCALE)
               OP_ULTIMA_MODIFICA,
           P.TIPO_BENEFICIARIO,
           D.CASO_ID,
           P.TIPO_PAI_ID,
           TIPOPAI.DESCRIZIONE
               TIPO_PAI_DESC,
           D.DT_ATTIVAZIONE_DA,
           D.DT_CHIUSURA_DA,
           P.DATA_CHIUSURA_PREVISTA,
           CASE WHEN d.DT_CHIUSURA_DA < SYSDATE THEN 1 ELSE 0 END
               chiuso,
           CASE
               WHEN     NVL (D.DT_CHIUSURA_DA,
                             TO_DATE ('31/12/9999', 'DD/MM/YYYY')) >=
                        SYSDATE
                    AND P.DATA_CHIUSURA_PREVISTA < SYSDATE
               THEN
                   1
               ELSE
                   0
           END
               da_Chiudere,
           P.DATA_MONITORAGGIO,
           P.VERIFICA_UNITA_MISURA,
           P.VERIFICA_OGNI,
           CASE
               WHEN     P.VERIFICA_UNITA_MISURA IS NOT NULL
                    AND P.VERIFICA_OGNI IS NOT NULL
                    AND P.VERIFICA_OGNI > 0
                    AND NVL (D.DT_CHIUSURA_DA,
                             TO_DATE ('31/12/9999', 'DD/MM/YYYY')) >=
                        SYSDATE
               THEN
                   CASE
                       WHEN     P.VERIFICA_UNITA_MISURA = 'Giorni'
                            AND SYSDATE >
                                  NVL (P.DATA_MONITORAGGIO,
                                       D.DT_ATTIVAZIONE_DA)
                                + VERIFICA_OGNI
                       THEN
                           1
                       WHEN     P.VERIFICA_UNITA_MISURA = 'Settimane'
                            AND SYSDATE >
                                (  NVL (P.DATA_MONITORAGGIO,
                                        D.DT_ATTIVAZIONE_DA)
                                 + (7 * VERIFICA_OGNI))
                       THEN
                           1
                       WHEN     P.VERIFICA_UNITA_MISURA = 'Mesi'
                            AND SYSDATE >
                                ADD_MONTHS (
                                    NVL (P.DATA_MONITORAGGIO,
                                         D.DT_ATTIVAZIONE_DA),
                                    VERIFICA_OGNI)
                       THEN
                           1
                       WHEN     P.VERIFICA_UNITA_MISURA = 'Anni'
                            AND SYSDATE >
                                ADD_MONTHS (
                                    NVL (P.DATA_MONITORAGGIO,
                                         D.DT_ATTIVAZIONE_DA),
                                    12 * VERIFICA_OGNI)
                       THEN
                           1
                       ELSE
                           0
                   END
               ELSE
                   0
           END
               da_Controllare,
           P.OBIETTIVI_BREVE,
           P.RAGGIUNTI_BREVE,
           P.OBIETTIVI_MEDIO,
           P.RAGGIUNTI_MEDIO,
           P.OBIETTIVI_LUNGO,
           P.RAGGIUNTI_LUNGO
      FROM CS_D_PAI  P
           LEFT JOIN CS_D_DIARIO D ON (p.diario_id = d.id)
           LEFT JOIN CS_PAI_MAST_SOGG s ON (d.id = s.diario_id)
           LEFT JOIN CS_O_OPERATORE_SETTORE os
               ON (d.operatore_settore_id = os.id)
           LEFT JOIN CS_A_SOGGETTO sc ON (sc.caso_id = d.caso_id)
           LEFT JOIN CS_O_OPERATORE_ANAGRAFICA ANAO
               ON (NVL (D.USR_MOD, D.USER_INS) = ANAO.USERNAME)
           LEFT JOIN CS_TB_TIPO_PAI tipoPai ON TIPOPAI.ID = P.TIPO_PAI_ID
     WHERE D.TIPO_DIARIO_ID = 8;


DROP VIEW CS_ROMA.CS_VISTA_SCHEDE;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_VISTA_SCHEDE
(
    ID_SCHEDA,
    PROVENIENZA,
    ACCESSO_DATA,
    ACCESSO_OPER_CF,
    ACCESSO_OPER_COGNOME,
    ACCESSO_OPER_NOME,
    ACCESSO_UFFICIO,
    ACCESSO_COD_ENTE,
    SEGNALATO_COGNOME,
    SEGNALATO_NOME,
    SEGNALATO_CF,
    TIPO_INTERVENTO,
    CATEGORIA_SOCIALE_ID
)
BEQUEATH DEFINER
AS
    SELECT ss.id                          id_scheda,
           NVL (cs.provenienza, 'SS')     provenienza,
           SSA.DATA                       accesso_data,
           ssa.operatore                  accesso_oper_cf,
           anag.cognome                   accesso_oper_cognome,
           anag.nome                      accesso_oper_nome,
           uff.nome                       accesso_ufficio,
           O.COD_ROUTING,
           sa.cognome                     segnalato_cognome,
           sa.nome                        segnalato_nome,
           SA.CF                          segnalato_cf,
           TIPO.TIPO,
           REL.CATEGORIA_SOCIALE_ID
      FROM ss_scheda  ss
           LEFT JOIN cs_ss_scheda_segr cs
               ON (cs.scheda_id = ss.id AND cs.provenienza = 'SS')
           LEFT JOIN SS_REL_SCHEDA_CAT_SOC rel ON rel.scheda_id = ss.id
           LEFT JOIN ss_scheda_segnalato se ON se.id = ss.segnalato
           LEFT JOIN ss_anagrafica sa ON se.anagrafica = sa.id
           LEFT JOIN ss_scheda_accesso ssa ON ssa.id = ss.accesso
           LEFT JOIN SS_UFFICIO uff ON (uff.ID = SSA.REL_UPO_UFFICIO_ID)
           LEFT JOIN am_anagrafica anag ON ANAG.FK_AM_USER = SSA.OPERATORE
           LEFT JOIN SS_TIPO_SCHEDA tipo ON tipo.id = ss.tipo
           LEFT JOIN CS_O_ORGANIZZAZIONE o
               ON (o.id = SSA.REL_UPO_ORGANIZZAZIONE_ID)
     WHERE ss.completa = 1 AND ss.eliminata = 0
    -- la prima query prende i dati di Segretariato Sociale da CS_SS_SCHEDA_SEGR (TIPO_SCHEDA = SS)
    UNION
    -- la seconda query prende i dati degli altri sistemi (di fatto, l'intera tabella CS_SCHEDE_ALTRA_PROVENIENZA)
    SELECT cs_altri.id_scheda_segr,
           cs_altri.provenienza,
           cs_altri.accesso_data,
           cs_altri.accesso_oper_cf,
           cs_altri.accesso_oper_cognome,
           cs_altri.accesso_oper_nome,
           cs_altri.accesso_ufficio,
           NULL     accesso_cod_ente,
           cs_altri.segnalato_cognome,
           cs_altri.segnalato_nome,
           cs_altri.segnalato_cf,
           cs_altri.tipo_intervento,
           cs_altri.categoria_sociale_id
      FROM CS_SCHEDE_ALTRA_PROVENIENZA cs_altri;


