DROP VIEW CS_ROMA.V_AR_C_TARIFFA;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_AR_C_TARIFFA
(
    ID,
    COD_TARIFFA,
    DESC_TARIFFA,
    ORGANIZZAZIONE_ID,
    COD_ROUTING,
    UNITA_MISURA_ID,
    UNITA_MISURA_DESC,
    TIPO_INTERVENTO_CUSTOM_ID,
    TARIFFA,
    DATA_DA,
    DATA_A,
    ABILITATO,
    USER_INS,
    DT_INS,
    USR_MOD,
    DT_MOD
)
BEQUEATH DEFINER
AS
    SELECT argo_tariffa.ID,
           argo_tariffa.COD_TARIFFA,
           argo_tariffa.DESC_TARIFFA,
           cs_organizzazione.ID              AS ORGANIZZAZIONE_ID,
           cs_organizzazione.cod_routing     AS COD_ROUTING,
           argo_tariffa.UNITA_MISURA_ID,
           unitaMisura.VALORE                AS UNITA_MISURA_DESC,
           argo_tariffa.TIPO_INTERVENTO_CUSTOM_ID,
           argo_tariffa.TARIFFA,
           argo_tariffa.DATA_DA,
           argo_tariffa.DATA_A,
           argo_tariffa.ABILITATO,
           argo_tariffa.USER_INS,
           argo_tariffa.DT_INS,
           argo_tariffa.USR_MOD,
           argo_tariffa.DT_MOD
      FROM AR_C_TARIFFA  argo_tariffa
           INNER JOIN AR_TB_UNITA_MISURA unitaMisura
               ON unitaMisura.ID = argo_tariffa.UNITA_MISURA_ID
           INNER JOIN AR_O_ORGANIZZAZIONE argo_organizzazione
               ON argo_tariffa.ORGANIZZAZIONE_ID = argo_organizzazione.ID
           INNER JOIN CS_O_ORGANIZZAZIONE cs_organizzazione
               ON argo_organizzazione.BELFIORE =
                  cs_organizzazione.COD_ROUTING;


