/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_AR_V_INDIRIZZI_ZONE
(
    ZONA_SOC,
    CODICE_VIA,
    INDIRIZZO,
    CIVICO_NUMERO,
    COMUNE_DES,
    COMUNE_COD,
    STATO_COD,
    PROV_SIGLA,
    STATO_DES,
    INDIRIZZO_HASH,
    INDIRIZZO_ESTESO
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT "ZONA_SOC",
                    "CODICE_VIA",
                    "INDIRIZZO",
                    "CIVICO_NUMERO",
                    "COMUNE_DES",
                    "COMUNE_COD",
                    "STATO_COD",
                    "PROV_SIGLA",
                    "STATO_DES",
                    "INDIRIZZO_HASH",
                    "INDIRIZZO_ESTESO"
      FROM (SELECT (SELECT nome
                      FROM cs_o_zona_soc
                     WHERE abilitato = '1')                zona_soc,
                   codice_via,
                   indirizzo,
                   civico_numero,
                   COM_DES                                 COMUNE_DES,
                   COM_COD                                 COMUNE_COD,
                   STATO_COD,
                   prov                                    prov_sigla,
                   stato_des,
                   INDIRIZZI_UTIL.gethash (INDIRIZZO,
                                           civico_numero,
                                           COM_DES,
                                           PROV,
                                           STATO_DES).a    INDIRIZZO_HASH,
                   INDIRIZZI_UTIL.gethash (INDIRIZZO,
                                           civico_numero,
                                           COM_DES,
                                           PROV,
                                           STATO_DES).b    INDIRIZZO_ESTESO
              FROM cs_a_ana_indirizzo
             WHERE INDIRIZZO <> 'Senza fissa dimora'
            UNION
            SELECT (SELECT nome
                      FROM cs_o_zona_soc
                     WHERE abilitato = '1')
                       zona_soc,
                   NULL
                       CODICE_VIA,
                   indirizzo_RES,
                   NUM_CIV_RES,
                   COM_RES_DES,
                   COM_RES_COD,
                   COM_ALTRO_COD,
                   prov_RES_COD,
                   DECODE (COM_ALTRO_DES, NULL, 'ITALIA', COM_ALTRO_DES)
                       stato_des,
                   INDIRIZZI_UTIL.gethash (indirizzo_RES,
                                           NUM_CIV_RES,
                                           COM_RES_DES,
                                           prov_RES_COD,
                                           COM_ALTRO_DES).a
                       INDIRIZZO_HASH,
                   INDIRIZZI_UTIL.gethash (indirizzo_RES,
                                           NUM_CIV_RES,
                                           COM_RES_DES,
                                           prov_RES_COD,
                                           COM_ALTRO_DES).b
                       INDIRIZZO_ESTESO
              FROM CS_A_COMPONENTE);


DROP VIEW CS_ROMA.V_ATT_PROF_PROBL;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_ATT_PROF_PROBL
(
    CHIAVE,
    ID_CASO,
    DATA,
    ANNO,
    MESE,
    ANNO_MESE,
    SOGGETTO,
    ID_ATTIVITA_PROF,
    ID_MACRO_ATT,
    MACRO_ATTIVITA,
    ID_MICRO_ATT,
    MICRO_ATTIVITA,
    CON_CHI,
    RIUNIONE_CON,
    ANALISI_PROBL,
    TIPO_INETR_PROP,
    N_OPERATORI,
    ORE_IMPIEGATE,
    OPERATORE_ATTPROF,
    ID_PROBLEMATICHE,
    PROBLEMATICHE,
    PROB_RISOLTO,
    TIPO_PROBL,
    TIPO_PROBL_DETT,
    ID_INTERVENTO_PROPOSTO,
    TIPO_INTERVENTO_PROPOSTO,
    ZONA_SOCIALE,
    BELFIORE,
    COMUNE,
    UFFICIO,
    UFFICIO_2_LIV,
    COD_OPE_RESP,
    OPERATORE_RESP,
    ID_ASSOCIATOPAI
)
BEQUEATH DEFINER
AS
    (SELECT cas.ID || '-' || (SELECT NOME FROM CS_O_ZONA_SOC)
                CHIAVE,
            CAS.ID
                ID_CASO,
            D.DT_AMMINISTRATIVA
                DATA,
            EXTRACT (YEAR FROM D.DT_AMMINISTRATIVA)
                ANNO,
            EXTRACT (MONTH FROM D.DT_AMMINISTRATIVA)
                MESE,
               EXTRACT (YEAR FROM D.DT_AMMINISTRATIVA)
            || '/'
            || EXTRACT (MONTH FROM D.DT_AMMINISTRATIVA)
                ANNO_MESE,
            ANA.COGNOME || ' ' || ANA.NOME
                SOGGETTO,
            D.ID
                ID_ATTIVITA_PROF,
            MAA.ID
                ID_MACRO_ATT,
            MAA.DESCRIZIONE
                MACRO_ATTIVITA,
            MIA.ID
                ID_MICRO_ATT,
            MIA.DESCRIZIONE
                MICRO_ATTIVITA,
            SETT.NOME
                CON_CHI,
            DIAC.DESCRIZIONE
                RIUNIONE_CON,
            CASE
                WHEN REL.FLAG_RILEVAZ_PROBLEMATICHE = 1 THEN 'SI'
                ELSE 'NO'
            END
                ANALISI_PROBL,
            CASE WHEN TIPOINT.ID IS NULL THEN 'NO' ELSE 'SI' END
                TIPO_INETR_PROP,
            REL.NUM_OPERATORI
                N_OPERATORI,
            TO_CHAR (REL.ORE_IMPIEGATE, 'HH24:MI')
                ORE_IMPIEGATE,
            vopeana1.COGNOME || ' ' || vopeana1.NOME
                OPERATORE_ATTPROF,
            P.ID
                ID_PROBLEMATICHE,
            P.DESCRIZIONE
                PROBLEMATICHE,
            CASE
                WHEN RRP.FLAG_RISOLTA = 1 THEN 'SI'
                WHEN RRP.FLAG_RISOLTA = 0 THEN 'NO'
                ELSE NULL
            END
                PROB_RISOLTO,
            CASE
                WHEN P.FLAG_MAT_IMM = 'I' THEN 'IMMATERIALI'
                WHEN P.FLAG_MAT_IMM = 'M' THEN 'MATERIALI'
                ELSE NULL
            END
                TIPO_PROBL,
            P.TIPO
                TIPO_PROBL_DETT,
            TIPOINT.ID
                ID_INTERVENTO_PROPOSTO,
            tipoint.descrizione
                TIPO_INTERVENTO_PROPOSTO,
            (SELECT NOME FROM CS_O_ZONA_SOC)
                ZONA_SOCIALE,
            ORG.COD_ROUTING
                BELFIORE,
            ORG.NOME
                COMUNE,
            SETTOR.NOME
                UFFICIO,
            OPE.TOOLTIP
                UFFICIO_2_LIV,
            OPE.USERNAME
                COD_OPE_RESP,
            vopeana.cognome || ' ' || vopeana.nome
                OPERATORE_RESP,
            CASE
                WHEN rdd.diario_id IS NULL THEN NULL
                ELSE rdd.diario_id || '-' || (SELECT NOME FROM CS_O_ZONA_SOC)
            END
                ID_ASSOCIATOPAI
       FROM cs_d_diario                    d,
            cs_tb_tipo_diario              td,
            cs_d_relazione                 rel,
            cs_tb_macro_attivita           maa,
            cs_tb_micro_attivita           mia,
            cs_a_soggetto                  sog,
            cs_a_anagrafica                ana,
            cs_a_caso                      cas,
            cs_o_settore                   sett,
            cs_c_diario_conchi             diac,
            CS_D_RELAZIONE_CON_CHI         conchi,
            cs_rel_relazione_prob          rrp,
            cs_tb_prob                     p,
            cs_a_caso_ope_tipo_ope         coto,
            cs_o_operatore_tipo_operatore  oto,
            cs_o_operatore_settore         os,
            cs_o_settore                   settor,
            cs_o_organizzazione            org,
            cs_o_operatore                 ope,
            cs_rel_relazione_tipoint       reltint,
            cs_c_tipo_intervento           tipoint,
            cs_rel_diario_diariorif        rdd,
            cs_o_operatore_anagrafica      vopeana,
            cs_o_operatore_anagrafica      vopeana1
      WHERE     D.TIPO_DIARIO_ID = td.id
            AND D.CASO_ID = cas.id
            AND rel.diario_id = d.id
            AND REL.MACRO_ATT_ID = maa.id
            AND REL.MICRO_ATT_ID = mia.id
            AND D.CASO_ID = sog.caso_ID
            AND SOG.ANAGRAFICA_ID = ANA.ID
            AND SETT.ID(+) = REL.RIUNIONE_CON_ID
            AND CONCHI.RELAZIONE_ID(+) = REL.DIARIO_ID
            AND diac.id(+) = CONCHI.DIARIO_CON_CHI_ID
            AND D.ID = RRP.RELAZIONE_DIARIO_ID(+)
            AND RRP.PROB_ID = p.id(+)
            AND CAS.ID = coto.caso_id
            AND coto.operatore_tipo_operatore_id = oto.id
            AND oto.operatore_settore_id = OS.ID
            AND OS.SETTORE_ID = settor.id
            AND settor.organizzazione_id = org.id
            AND os.operatore_id = ope.id
            AND rel.diario_id = reltint.relazione_diario_id(+)
            AND reltint.tipo_intervento_id = tipoint.id(+)
            AND rdd.diario_id_rif(+) = D.ID
            AND OPE.USERNAME = vopeana.username
            AND D.USER_INS = vopeana1.username
            AND D.TIPO_DIARIO_ID = 6
            AND coto.flag_responsabile = 1);


