DROP VIEW CS_ROMA.V_BI_INVIANTE;

/* Formatted on 18/07/2022 12:23:32 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_INVIANTE
(
    ID_ORGANIZZAZIONE,
    ORGANIZZAZIONE_NOME,
    COD_ROUTING,
    ID_INVIANTE,
    CF,
    NOME_INVIANTE,
    TIPO_INVIANTE,
    ZONA_NOME,
    INV_ABILITATO,
    ORA_SCHEMA_NAME,
    CRITERI_ACCETTAZIONE
)
BEQUEATH DEFINER
AS
    (SELECT o.id              ID_ORGANIZZAZIONE,
            o.NOME            ORGANIZZAZIONE_NOME,
            o.cod_routing,
            id_inviante,
            o.cf,
            INV.NOME_INVIANTE,
            tipo_INVIANTE,
            zona_nome,
            INV.abilitato     INV_ABILITATO,
            INV.ORA_SCHEMA_NAME,
            INV.CRITERI_ACCETTAZIONE
       FROM AR_BI_INVIANTE INV, CS_O_ORGANIZZAZIONE O
      WHERE     INV.tipo_inviante = 'SISO'
            AND ORA_SCHEMA_NAME = SYS_CONTEXT ('USERENV', 'CURRENT_SCHEMA')
            AND INV.ZONA_NOME = (SELECT NOME FROM CS_O_ZONA_SOC)
            AND O.COD_ROUTING = INV.COD_ROUTING);


DROP VIEW CS_ROMA.V_BI_TR_CN_OR;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CN_OR
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    O_TIPO_CODICE_ORG,
    O_CODICE_ORG,
    NOME,
    EMAIL,
    FLAG_CAPOFILA,
    COD_CATASTALE
)
BEQUEATH DEFINER
AS
    SELECT 'CN_OR'
               TIPO_RECORD,
           (SELECT nome FROM cs_o_zona_soc)
               Z_ZONA_SOCIALE,
           inv.ID_INVIANTE
               codice_inviante,
           O_TIPO_CODICE_ORG,
           DECODE (sel.O_TIPO_CODICE_ORG, 'CF', sel.CF, sel.COD_ROUTING)
               O_CODICE_ORG,
           NOME,
           EMAIL,
           sel.FLAG_CAPOFILA,
           sel.COD_CATASTALE
      FROM (SELECT CASE
                       WHEN O.CF IS NULL
                       THEN
                           'CR'
                       WHEN (SELECT COUNT (*)     conta
                               FROM cs_o_organizzazione oo
                              WHERE oo.cf = o.cf) > 1
                       THEN
                           'CR'
                       ELSE
                           'CF'
                   END    O_TIPO_CODICE_ORG,
                   O.CF,
                   O.COD_ROUTING,
                   O.ID,
                   O.NOME,
                   O.EMAIL,
                   O.FLAG_CAPOFILA,
                   O.COD_CATASTALE
              FROM CS_o_organizzazione O) SEL,
           V_BI_INVIANTE  INV
     WHERE     DECODE (sel.O_TIPO_CODICE_ORG, 'CF', sel.CF, sel.COD_ROUTING)
                   IS NOT NULL
           AND INV.TIPO_INVIANTE = 'SISO'
           AND INV.ZONA_NOME = (SELECT NOME FROM CS_O_ZONA_SOC)
           AND INV.ID_ORGANIZZAZIONE = SEL.ID;


DROP VIEW CS_ROMA.V_BI_TR_SA_PR;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_SA_PR
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    PK_SCHEDA_ID,
    S_PRESTAZIONE,
    DATA_RICHIESTA
)
BEQUEATH DEFINER
AS
    (SELECT 'SA_PR'                             TIPO_RECORD,
            (SELECT NOME FROM CS_O_ZONA_SOC)    Z_ZONA_SOCIALE,
            ID_INVIANTE                         CODICE_INVIANTE,
            PK_SCHEDA_ID,
            IC.ID                               S_PRESTAZIONE,
            CAST (
                (  TIMESTAMP '1970-01-01 00:00:00 GMT'
                 + NUMTODSINTERVAL (
                         REPLACE (
                             SUBSTR (REPLACE (DATA_RICHIESTA, '"', ''),
                                     1,
                                     13),
                             ',',
                             '')
                       / 1000,
                       'SECOND'))
                    AT TIME ZONE 'Europe/Rome'
                    AS DATE)                    DATA_RICHIESTA
       FROM (SELECT SUBSTR (STR, INSTR (STR, '"dataRichiesta"') + 16)
                        DATA_RICHIESTA,
                    SUBSTR (STR, 1, INSTR (STR, '","') - 1)
                        PRESTAZIONE,
                    str,
                    PK_SCHEDA_ID,
                    ID_INVIANTE,
                    TIPO_INVIANTE
               FROM (SELECT DBMS_LOB.SUBSTR (C.DATI_CLOB, 4000, 26)    STR,
                            S.ID                                       PK_SCHEDA_ID
                       FROM CS_D_DIARIO D, SS_SCHEDA S, CS_D_CLOB C
                      WHERE     D.TIPO_DIARIO_ID = '22'
                            AND S.ID = D.SCHEDA_ID
                            AND C.ID = D.CLOB_ID)
                    INNER JOIN Ss_scheda s ON PK_SCHEDA_ID = S.ID
                    LEFT JOIN ss_scheda_accesso sa ON S.ACCESSO = sa.id
                    LEFT JOIN cs_o_organizzazione org
                        ON org.ID = SA.REL_UPO_ORGANIZZAZIONE_ID
                    LEFT JOIN V_BI_INVIANTE INV
                        ON ORG.ID = INV.ID_ORGANIZZAZIONE
              WHERE INV.TIPO_INVIANTE = 'SISO')
            INNER JOIN CS_C_TIPO_INTERVENTO_CUSTOM IC
                ON PRESTAZIONE = IC.DESCRIZIONE);


DROP VIEW CS_ROMA.V_BI_TR_SA_SR;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_SA_SR
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    PK_SCHEDA_ID,
    S_SERVIZIO
)
BEQUEATH DEFINER
AS
    (SELECT 'SA_SR'                              TIPO_RECORD,
            (SELECT NOME FROM CS_O_ZONA_SOC)     Z_ZONA_SOCIALE,
            ID_INVIANTE                          CODICE_INVIANTE,
            S.ID                                 PK_SCHEDA_ID,
            INTD.INTERVENTO                      S_SERVIZIO
       FROM SS_SCHEDA  S
            LEFT JOIN ss_scheda_accesso sa ON S.ACCESSO = sa.id
            LEFT JOIN cs_o_organizzazione org
                ON org.ID = SA.REL_UPO_ORGANIZZAZIONE_ID
            LEFT JOIN V_BI_INVIANTE INV ON ORG.ID = INV.ID_ORGANIZZAZIONE
            LEFT JOIN SS_SCHEDA_INTERVENTI SCINT ON S.INTERVENTI = scint.id
            LEFT JOIN ss_interventi_schede ints ON scint.id = ints.scheda
            INNER JOIN ss_intervento intd ON ints.intervento = intd.id);


