DROP VIEW CS_ROMA.V_CASI_OPERATORI_ATTUALI;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_CASI_OPERATORI_ATTUALI
(
    CASO_ID,
    SOGG_CF,
    SOGG_COGNOME,
    SOGG_NOME,
    SOGG_TEL,
    SOGG_CELL,
    SOGG_EMAIL,
    SOGG_SESSO,
    SOGG_CITTADINANZA,
    FLAG_RESPONSABILE,
    OPERATORE_ID,
    SETTORE_ID,
    SETTORE_NOME,
    ORG_NOME,
    ORG_BELFIORE,
    USERNAME,
    OPE_COGNOME,
    OPE_NOME
)
BEQUEATH DEFINER
AS
    SELECT ope.caso_id,
           A.CF               SOGG_CF,
           A.COGNOME          SOGG_COGNOME,
           A.NOME             SOGG_NOME,
           A.TEL              SOGG_TEL,
           A.CELL             SOGG_CELL,
           A.EMAIL            SOGG_EMAIL,
           A.SESSO            SOGG_SESSO,
           A.CITTADINANZA     SOGG_CITTADINANZA,
           ope.flag_responsabile,
           os.operatore_id,
           os.settore_id,
           S.NOME             settore_nome,
           o.nome             org_nome,
           O.COD_ROUTING      org_belfiore,
           oana.username,
           oana.cognome       ope_cognome,
           oana.nome          ope_nome
      FROM CS_A_CASO  C
           LEFT JOIN cs_a_caso_ope_tipo_ope ope ON C.ID = OPE.CASO_ID
           LEFT JOIN cs_o_operatore_tipo_operatore oti
               ON ope.operatore_tipo_operatore_id = oti.id
           LEFT JOIN cs_o_operatore_settore os
               ON oti.operatore_settore_id = os.id
           LEFT JOIN CS_O_OPERATORE_ANAGRAFICA oana
               ON os.operatore_id = oana.id
           LEFT JOIN cs_o_settore s ON os.settore_id = s.id
           LEFT JOIN cs_o_organizzazione o ON s.organizzazione_id = o.id
           INNER JOIN CS_A_SOGGETTO S ON S.CASO_ID = C.ID
           INNER JOIN CS_A_ANAGRAFICA A ON S.ANAGRAFICA_ID = A.ID
     WHERE     SYSDATE BETWEEN oti.data_inizio_app AND oti.data_fine_app
           AND SYSDATE BETWEEN os.data_inizio_app AND os.data_fine_app
           AND SYSDATE BETWEEN OANA.DATA_INIZIO_VAL
                           AND NVL (OANA.DATA_FINE_VAL, SYSDATE + 1);


