DROP VIEW CS_ROMA.V_CS_SS_INFO_SOGGETTI;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_CS_SS_INFO_SOGGETTI
(
    DATA,
    CF,
    TEL,
    CELL,
    EMAIL,
    INDIRIZZO,
    CIVICO,
    PROV,
    COM_COD,
    COM_DES,
    STATO_COD,
    STATO_DES
)
BEQUEATH DEFINER
AS
    SELECT "DATA",
           "CF",
           "TEL",
           "CELL",
           "EMAIL",
           "INDIRIZZO",
           "CIVICO",
           "PROV",
           "COM_COD",
           "COM_DES",
           "STATO_COD",
           "STATO_DES"
      FROM (--recupero anagrafiche da altre risorse inserite
            SELECT NVL (dt_mod, dt_ins)        data,
                   UPPER (cf)                  CF,
                   tel,
                   cell,
                   email,
                   C.INDIRIZZO_RES             indirizzo,
                   TO_CHAR (C.NUM_CIV_RES)     civico,
                   C.PROV_RES_COD              prov,
                   C.COM_RES_COD               com_cod,
                   C.COM_RES_DES               com_des,
                   c.com_altro_cod             stato_cod,
                   C.COM_ALTRO_DES             stato_des
              FROM cs_a_componente c, cs_a_anagrafica ana
             WHERE C.ANAGRAFICA_ID = ana.id
            UNION ALL
            --recupero anagrafiche da UDC segnalante
            SELECT NVL (dt_mod, dt_ins)     data,
                   UPPER (cf)               CF,
                   telefono,
                   S.CEL,
                   email,
                   S.VIA,
                   NULL,
                   COM.DENO_PROV,
                   S.COMUNE,
                   COM.DENOMINAZIONE,
                   NULL,
                   NULL
              FROM ss_scheda_segnalante  s
                   LEFT JOIN am_tab_comuni com
                       ON COM.COD_ISTAT_COMUNE = s.comune,
                   ss_Scheda             ss
             WHERE ss.segnalante = s.id
            UNION ALL
            --recupero anagrafiche da UDC segnalato
            SELECT NVL (dt_mod, dt_ins)     data,
                   UPPER (ana.cf),
                   SE.TELEFONO,
                   SE.CEL,
                   SE.EMAIL,
                   ind.via,
                   TO_CHAR (ind.numero),
                   ind.prov_cod,
                   ind.comune_cod,
                   ind.comune_des,
                   ind.stato_cod,
                   ind.stato_des
              FROM ss_anagrafica        ana,
                   ss_scheda            s,
                   ss_scheda_Segnalato  se
                   LEFT JOIN ss_indirizzo ind ON se.residenza = ind.id
             WHERE ana.id = SE.ANAGRAFICA AND S.SEGNALATO = se.id)
     WHERE     cf IS NOT NULL
           AND (   tel IS NOT NULL
                OR cell IS NOT NULL
                OR email IS NOT NULL
                OR indirizzo IS NOT NULL
                OR civico IS NOT NULL
                OR prov IS NOT NULL
                OR com_cod IS NOT NULL
                OR com_des IS NOT NULL
                OR stato_cod IS NOT NULL
                OR stato_des IS NOT NULL);


DROP VIEW CS_ROMA.V_EROG_EXPORT_FLUSSO;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_EROG_EXPORT_FLUSSO
(
    INTERVENTO_ESEG_ID,
    IDENTIFICAZIONE_FLUSSO,
    DATA_ESPORTAZIONE,
    REVOCABILE
)
BEQUEATH DEFINER
AS
    SELECT e.INTERVENTO_ESEG_ID,
           em.IDENTIFICAZIONE_FLUSSO,
           CASE WHEN DT_EXPORT IS NOT NULL THEN DT_EXPORT ELSE e.DT_INS END
               AS DATA_ESPORTAZIONE,
           CASE WHEN DT_EXPORT IS NOT NULL THEN 1 ELSE 0 END
               AS revocabile
      FROM CS_I_PS_EXPORT  e
           JOIN CS_I_PS_EXPORT_MAST em ON (e.EXPORT_MASTER_ID = em.id)
     WHERE e.FLAG_ESPORTATO = 1;

COMMENT ON TABLE CS_ROMA.V_EROG_EXPORT_FLUSSO IS 'Utilizzata in fase di Esportazione Casellario da Cartella Sociale. Indica, per gli INTERVENTO_ESEG_ID, quali siano i dati relativi al flusso esportato (e non revocato). DATA_ESPORTAZIONE è DT_EXPORT oppure DT_INS per i flussi esportati prima della modifica SISO-719. REVOCABILE indica se la riga è revocabile da applicativo web (le esportazioni compiute prima della modifica SISO-719 non sono revocabili senza intervento manuale, poiché sul DB mancano dei dati di riferimento).';


DROP VIEW CS_ROMA.V_EROG_EXPORT_STATUS;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_EROG_EXPORT_STATUS
(
    INTERVENTO_ESEG_ID,
    STATUS_ESPORTATO
)
BEQUEATH DEFINER
AS
      SELECT INTERVENTO_ESEG_ID, MAX (FLAG_ESPORTATO) AS STATUS_ESPORTATO
        FROM CS_I_PS_EXPORT
    GROUP BY INTERVENTO_ESEG_ID;

COMMENT ON TABLE CS_ROMA.V_EROG_EXPORT_STATUS IS 'Utilizzata in fase di Esportazione Casellario da Cartella Sociale. Indica quali INTERVENTI_ESEG_ID sono stati oggetto di esportazione e quale sia il loro status attuale: 0 = [tutte le] esportazioni revocate, si può esportare; 1 = esportazione avvenuta, necessaria revoca prima di poter esportare nuovamente';


DROP VIEW CS_ROMA.V_EROG_LST_DETT;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_EROG_LST_DETT
(
    ER_DETT_ID,
    ER_DATA_ESECUZIONE,
    ER_NOTE,
    ER_QUOTA_VALORE,
    VALORE,
    ER_QUOTA_NOTE,
    ER_NOTE_ALTRE_COMPART,
    ER_PERC_GESTITA_ENTE_DETT,
    ER_SPESA_DETT,
    ER_VALORE_GESTITA_ENTE_DETT,
    ER_OPERATORE_DENOM,
    ER_SETTORE_ID,
    ER_SETTORE,
    ER_ORG_ID,
    ER_ORG_NOME,
    ER_ORG_BELFIORE,
    ER_STATO_ID,
    ER_STATO_NOME,
    ER_STATO_TIPO,
    ER_STATO_EROGAZIONE_POSSIBILE,
    ER_FLAG_CHIUDI,
    ER_MAST_ID,
    PS_EXPORT
)
BEQUEATH DEFINER
AS
    SELECT IE.ID
               ER_DETT_ID,
           IE.DATA_ESECUZIONE
               ER_DATA_ESECUZIONE,
           IE.NOTE
               ER_NOTE,
           VQ.VAL_QUOTA
               ER_QUOTA_VALORE,
           UM.VALORE,
           VQ.NOTE
               ER_QUOTA_NOTE,
           IE.NOTE_ALTRE_COMPART
               ER_NOTE_ALTRE_COMPART,
           IE.PERC_GESTITA_ENTE
               ER_PERC_GESTITA_ENTE_DETT,
           IE.SPESA
               ER_SPESA_DETT,
           NVL (IE.VALORE_GESTITA_ENTE,
                IE.SPESA * IE.PERC_GESTITA_ENTE / 100)
               ER_VALORE_GESTITA_ENTE_DETT,
           DECODE (NOME_OPERATORE_EROG,
                   NULL, OSETTANA.COGNOME || ' ' || OSETTANA.NOME,
                   NOME_OPERATORE_EROG)
               ER_OPERATORE_DENOM,
           SETT.ID
               ER_SETTORE_ID,
           SETT.NOME
               ER_SETTORE,
           ORG.ID
               ER_ORG_ID,
           ORG.NOME
               ER_ORG_NOME,
           ORG.COD_ROUTING
               ER_ORG_BELFIORE,
           ST.ID
               ER_STATO_ID,
           ST.NOME
               ER_STATO_NOME,
           ST.TIPO
               ER_STATO_TIPO,
           ST.EROGAZIONE_POSSIBILE
               ER_STATO_EROGAZIONE_POSSIBILE,
           ST.flag_chiudi
               ER_FLAG_CHIUDI,
           IE.INTERVENTO_ESEG_MAST_ID
               ER_MAST_ID,
           'NO'
               PS_EXPORT
      FROM CS_I_INTERVENTO_ESEG  IE
           INNER JOIN CS_CFG_INT_ESEG_STATO ST ON IE.STATO_ID = ST.ID
           LEFT JOIN CS_I_VAL_QUOTA VQ ON IE.VAL_QUOTA_ID = VQ.ID
           LEFT JOIN cs_o_operatore_settore osett
               ON IE.OPERATORE_SETTORE_ID = osett.id
           LEFT JOIN cs_o_operatore_anagrafica osettana
               ON osett.operatore_id = OSETTANA.ID
           LEFT JOIN CS_O_SETTORE SETT ON osett.SETTORE_ID = SETT.ID
           LEFT JOIN CS_O_ORGANIZZAZIONE ORG
               ON SETT.ORGANIZZAZIONE_ID = ORG.ID
           INNER JOIN CS_I_INTERVENTO_ESEG_MAST M
               ON IE.INTERVENTO_ESEG_MAST_ID = M.ID
           LEFT JOIN CS_I_QUOTA IQ ON M.QUOTA_ID = IQ.ID
           LEFT JOIN CS_TB_UNITA_MISURA UM ON IQ.UNITA_MISURA_ID = UM.ID;


