           pr.settore_gestore_id,
           lav.descrizione     cond_lavoro,
           tit.id              titolo_studio_cod,
           tit.descrizione     titolo_studio,
           ing.id              ing_mercato_cod,
           ing.descrizione     ing_mercato,
           pr.id               PR_ID,
           M.SETT_SECONDO_LIVELLO,
           ps.COD_PRESTAZIONE,
           ps.DENOM_PRESTAZIONE,
           PR.FLAG_SERVIZIO_AMBITO
      FROM cs_i_intervento_eseg_mast  m
           LEFT JOIN cs_i_intervento_pr pr ON m.int_progetto_id = pr.id
           LEFT JOIN ar_ff_progetto arp ON arp.id = pr.progetto_id
           LEFT JOIN ar_ff_progetto_attivita arpa
               ON arpa.id = pr.progetto_attivita_id
           LEFT JOIN cs_o_settore stit ON PR.SETTORE_TITOLARE_ID = stit.id
           LEFT JOIN cs_o_organizzazione otit
               ON stit.organizzazione_id = otit.id
           LEFT JOIN CS_TB_COND_LAVORO lav ON PR.COND_LAVORO_ID = lav.id
           LEFT JOIN CS_TB_TITOLO_STUDIO tit ON PR.TITOLO_STUDIO_ID = tit.id
           LEFT JOIN CS_TB_ING_MERCATO ing ON PR.ING_MERCATO_FK = ing.id
           LEFT JOIN CS_I_PS ps ON m.id = ps.INT_ESEG_MAST_ID;


