DROP VIEW CS_ROMA.V_INDIRIZZI_CASO;

/* Formatted on 18/07/2022 12:23:33 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_INDIRIZZI_CASO
(
    ZONA_SOCIALE,
    ID_ANAGRAFICA,
    ID_CASO,
    CODICE_FISCALE,
    TIPO_INDIRIZZO_ID,
    TIPO_IND_DESC,
    DATA_INIZIO_APP,
    DATA_FINE_APP,
    INDIRIZZO_HASH,
    INDIRIZZO_ESTESO
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT a.zona_sociale,
                    a.id_anagrafica,
                    a.id_caso,
                    a.codice_fiscale,
                    a.TIPO_INDIRIZZO_ID,
                    b.descrizione     tipo_ind_desc,
                    a.DATA_INIZIO_APP,
                    a.DATA_FINE_APP,
                    a.INDIRIZZO_HASH,
                    a.INDIRIZZO_ESTESO
      FROM (SELECT DISTINCT
                   (SELECT nome FROM cs_o_zona_soc)        zona_sociale,
                   ana.id                                  id_anagrafica,
                   SOG.CASO_ID                             id_caso,
                   ANA.CF                                  codice_fiscale,
                   IND.TIPO_INDIRIZZO_ID,
                   IND.DATA_INIZIO_APP,
                   IND.DATA_FINE_APP,
                   INDIRIZZI_UTIL.gethash (INDIRIZZO,
                                           civico_numero,
                                           COM_DES,
                                           PROV,
                                           STATO_DES).a    INDIRIZZO_HASH,
                   INDIRIZZI_UTIL.gethash (INDIRIZZO,
                                           civico_numero,
                                           COM_DES,
                                           PROV,
                                           STATO_DES).b    INDIRIZZO_ESTESO
              FROM cs_a_anagrafica  ana
                   INNER JOIN cs_a_soggetto sog ON ANA.ID = SOG.ANAGRAFICA_ID
                   INNER JOIN cs_a_indirizzo ind
                       ON ANA.ID = IND.SOGGETTO_ANAGRAFICA_ID
                   INNER JOIN cs_a_ana_indirizzo aind
                       ON IND.ANA_INDIRIZZO_ID = AIND.ID
            UNION
            SELECT DISTINCT
                   (SELECT nome FROM cs_o_zona_soc)
                       zona_sociale,
                   ana.id
                       id_anagrafica,
                   NULL
                       id_caso,
                   ANA.CF
                       codice_fiscale,
                   1,
                   NULL,
                   NULL,                                              --com.*,
                   INDIRIZZI_UTIL.gethash (INDIRIZZO_RES,
                                           NUM_CIV_RES,
                                           COM_RES_DES,
                                           PROV_RES_COD,
                                           COM_ALTRO_DES).a
                       INDIRIZZO_HASH,
                   INDIRIZZI_UTIL.gethash (INDIRIZZO_RES,
                                           NUM_CIV_RES,
                                           COM_RES_DES,
                                           PROV_RES_COD,
                                           COM_ALTRO_DES).b
                       INDIRIZZO_ESTESO
              FROM cs_a_anagrafica  ana
                   INNER JOIN cs_a_componente com
                       ON ana.id = COM.ANAGRAFICA_ID) a
           LEFT JOIN CS_TB_TIPO_INDIRIZZO b ON a.tipo_indirizzo_id = B.ID;


