DROP VIEW CS_ROMA.V_MONITORAGGIO;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_MONITORAGGIO
("ZONA SOCIALE", COMUNE, BELFIORE, DATA_, ANNO, 
 MESE, "NUMERO SCHEDE INSERITE", "NUMERO SCHEDE MODIFICATE", "NUMERO CARTELLE INSERITE", "NUMERO CARTELLE MODIFICATE", 
 "NUMERO TIPO FASC INSERITI", "NUMERO TIPO FASC MODIFICATI", "NUMERO EROGAZIONI INSERITE", "NUMERO EROGAZIONI MODIFICATE")
BEQUEATH DEFINER
AS 
SELECT TO_CHAR (NVL (aaAA."ZONA SOCIALE", bbbB."ZONA SOCIALE"))"ZONA SOCIALE",
       TO_CHAR (NVL (aaaa.comune, bbbb.comune)) "COMUNE",
       TO_CHAR (NVL (aaaa.belfiore, bbbb.belfiore)) belfiore,
       TO_CHAR (NVL(aaaa.DATA_,bbbb.DATA_))DATA_,
       TO_CHAR (NVL(aaaa.ANNO,bbbb.ANNO))ANNO,
       TO_CHAR (NVL(aaaa.MESE,bbbb.MESE))MESE,
       NVL (aaaA."NUMERO SCHEDE INSERITE", 0) "NUMERO SCHEDE INSERITE",
       NVL (aaaA."NUMERO SCHEDE MODIFICATE", 0) "NUMERO SCHEDE MODIFICATE",
       NVL (aaaA."NUMERO CARTELLE INSERITE", 0) "NUMERO CARTELLE INSERITE",
       NVL (aaaA."NUMERO CARTELLE MODIFICATE", 0)"NUMERO CARTELLE MODIFICATE",
       NVL (AAAA."NUMERO TIPO FASC INSERITI", 0)"NUMERO TIPO FASC INSERITI",
       NVL (AAAA."NUMERO TIPO FASC MODIFICATI", 0)"NUMERO TIPO FASC MODIFICATI",
       NVL (bbbb."NUMERO EROGAZIONI INSERITE", 0)"NUMERO EROGAZIONI INSERITE",
       NVL (bbbb."NUMERO EROGAZIONI MODIFICATE", 0)"NUMERO EROGAZIONI MODIFICATE"
  FROM (
SELECT TO_CHAR (NVL (aaA."ZONA SOCIALE", bbb."ZONA SOCIALE")) "ZONA SOCIALE",
               TO_CHAR (NVL (aaa.comune, bbb.comune)) "COMUNE",
               TO_CHAR (NVL (aaa.belfiore, bbb.belfiore)) belfiore,
               TO_CHAR (NVL(aaa.DATA_,bbb.DATA_))DATA_,
               TO_CHAR (NVL(aaa.ANNO,bbb.ANNO))ANNO,
               TO_CHAR (NVL(aaa.MESE,bbb.MESE))MESE,
               NVL (aaa."NUMERO SCHEDE INSERITE", 0) "NUMERO SCHEDE INSERITE",
               NVL (aaa."NUMERO SCHEDE MODIFICATE", 0) "NUMERO SCHEDE MODIFICATE",
               NVL (aaa."NUMERO CARTELLE INSERITE", 0) "NUMERO CARTELLE INSERITE",
               NVL (aaa."NUMERO CARTELLE MODIFICATE", 0)"NUMERO CARTELLE MODIFICATE",
               NVL (bbb."NUMERO TIPO FASC INSERITI", 0) "NUMERO TIPO FASC INSERITI",
               NVL (bbb."NUMERO TIPO FASC MODIFICATI", 0) "NUMERO TIPO FASC MODIFICATI"
          FROM (
SELECT TO_CHAR (NVL (aa."ZONA SOCIALE", bb."ZONA SOCIALE"))"ZONA SOCIALE",
                       TO_CHAR (NVL (aa.comune, bb.comune)) "COMUNE",
                       TO_CHAR (NVL (aa.belfiore, bb.belfiore)) belfiore,
                       TO_CHAR (NVL(aa.DATA_,bb.DATA_))DATA_,
                       TO_CHAR (NVL(aa.ANNO,bb.ANNO))ANNO,
                       TO_CHAR (NVL(aa.MESE,bb.MESE))MESE,
                       NVL (aa."NUMERO SCHEDE INSERITE", 0)"NUMERO SCHEDE INSERITE",
                       NVL (aa."NUMERO SCHEDE MODIFICATE", 0)"NUMERO SCHEDE MODIFICATE",
                       NVL (bb."NUMERO CARTELLE INSERITE", 0)"NUMERO CARTELLE INSERITE",
                       NVL (bb."NUMERO CARTELLE MODIFICATE", 0)"NUMERO CARTELLE MODIFICATE"
                        FROM (
                         SELECT
                               TO_CHAR (NVL (a.zona_sociale, b.zona_sociale))"ZONA SOCIALE",                  
                               TO_CHAR (NVL (a.comune, b.comune)) "COMUNE",
                               TO_CHAR (NVL (a.BELFIORE, b.BELFIORE)) BELFIORE,
                               TO_CHAR (NVL(a.data1,b.data1))DATA_,
                               TO_CHAR (NVL(a.data2,b.data2))ANNO,
                               TO_CHAR (NVL(a.data3,b.data3))MESE,                           
                               NVL (a."NUMERO SCHEDE INSERITE", 0)"NUMERO SCHEDE INSERITE",
                               NVL (b."NUMERO SCHEDE MODIFICATE", 0)"NUMERO SCHEDE MODIFICATE"
                               FROM
                             --SCHEDE INSERITE
                             ( SELECT ZONA_SOCIALE,
                                 COMUNE,
                                 BELFIORE,
                                 COUNT (DISTINCT ID_SCHEDA)"NUMERO SCHEDE INSERITE",
                                       TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                                       EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                                       EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) data3
                                         FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)zona_sociale,
                                                 O.NOME COMUNE,
                                                 O.COD_ROUTING belfiore,
                                                 S.ID ID_SCHEDA,
                                                 s.*,
                                                 A.REL_UPO_ORGANIZZAZIONE_ID
                                                 FROM SS_SCHEDA S,
                                                 SS_SCHEDA_ACCESSO A,
                                                 CS_O_ORGANIZZAZIONE O
                                                 WHERE S.ACCESSO = A.ID
                                                        AND A.REL_UPO_ORGANIZZAZIONE_ID =O.ID
                                                 AND S.COMPLETA = 1
                                                 AND S.ELIMINATA = 0)SCHEDE_INS
                                                 GROUP BY ZONA_SOCIALE, COMUNE,BELFIORE,TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy'))a
                               FULL OUTER JOIN
                         -- SCHEDE MODIFICATE
                          (SELECT ZONA_SOCIALE,
                                         COMUNE,
                                         BELFIORE,
                                         COUNT (DISTINCT ID_SCHEDA)"NUMERO SCHEDE MODIFICATE",
                                         TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                                         EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                                         EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data3
                                    FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)zona_sociale,
                                                 O.NOME COMUNE,
                                                 O.COD_ROUTING belfiore,
                                                 S.ID ID_SCHEDA,
                                                 s.*,
                                                 A.REL_UPO_ORGANIZZAZIONE_ID
                                            FROM SS_SCHEDA S,
                                                 SS_SCHEDA_ACCESSO A,
                                                 CS_O_ORGANIZZAZIONE O
                                           WHERE S.ACCESSO = A.ID
                                             AND A.REL_UPO_ORGANIZZAZIONE_ID =O.ID
                                                 AND S.COMPLETA = 1
                                                 AND S.ELIMINATA = 0
                                                 AND TO_DATE (TO_CHAR ( S.DT_MOD,'dd/mm/yyyy'),'dd/mm/yyyy') <>TO_DATE (TO_CHAR (S.DT_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) SCHEDE_MOD
                                            GROUP BY ZONA_SOCIALE, COMUNE,BELFIORE, TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) b
                           ON     
                           a.ZONA_SOCIALE = b.zona_sociale
                           AND a.comune = b.comune
                           AND A.BELFIORE=B.BELFIORE
                           and a.data1=b.data1
                           and a.data2=b.data2
                           and a.data3=b.data3)aa
                       FULL OUTER JOIN
                        (SELECT 
                               TO_CHAR (NVL (c.zona_sociale, d.zona_sociale))"ZONA SOCIALE",
                               TO_CHAR (NVL (c.comune, d.comune)) "COMUNE",
                               TO_CHAR (NVL (c.belfiore, d.belfiore)) belfiore,
                               TO_CHAR (NVL(c.data1,d.data1))DATA_,
                               TO_CHAR (NVL(c.data2,d.data2))ANNO,
                               TO_CHAR (NVL(c.data3,d.data3))MESE,   
                             NVL (c."NUMERO CARTELLE INSERITE", 0)"NUMERO CARTELLE INSERITE", 
                             NVL (d."NUMERO CARTELLE MODIFICATE", 0) "NUMERO CARTELLE MODIFICATE"
                            FROM (  SELECT 
                                    ZONA_SOCIALE, 
                                    COMUNE,
                                    belfiore,
                                    COUNT (DISTINCT ID)"NUMERO CARTELLE INSERITE",
                                    TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                                    EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                                    EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy'))data3
                                    FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)
                                                 ZONA_SOCIALE,
                                                 ORG.NOME COMUNE,
                                                 ORG.COD_ROUTING belfiore,
                                                 C.*
                                            FROM CS_A_CASO C,
                                                 CS_D_DIARIO D,
                                                 CS_IT_STEP STEP,
                                                 CS_O_ORGANIZZAZIONE ORG
                                           WHERE C.ID = D.CASO_ID
                                                 AND D.ID = STEP.DIARIO_ID
                                                 AND STEP.ORGANIZZAZIONE_ID = ORG.ID
                                                 AND STEP.CFG_IT_STATO_ID = 1) CASO_INS
                                    GROUP BY ZONA_SOCIALE, COMUNE,belfiore,TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) c
                               FULL OUTER JOIN
                               (  SELECT ZONA_SOCIALE,
                                         COMUNE,
                                         belfiore,
                                         COUNT (DISTINCT ID)"NUMERO CARTELLE MODIFICATE",
                                         TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                                         EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                                         EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data3
                                    FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC) ZONA_SOCIALE,
                                                 ORG.NOME COMUNE,
                                                 ORG.COD_ROUTING belfiore,
                                                 C.*
                                            FROM CS_A_CASO C,
                                                 CS_D_DIARIO D,
                                                 CS_IT_STEP STEP,
                                                 CS_O_ORGANIZZAZIONE ORG
                                           WHERE C.ID = D.CASO_ID
                                                 AND D.ID = STEP.DIARIO_ID
                                                 AND STEP.ORGANIZZAZIONE_ID =ORG.ID
                                                 AND STEP.DIARIO_ID =(SELECT MAX (ID)
                                                                        FROM CS_D_DIARIO A
                                                                         WHERE     A.CASO_ID = C.ID
                                                                                    AND A.TIPO_DIARIO_ID =1)
                                                 AND TO_DATE (TO_CHAR (C.DT_MOD,'dd/mm/yyyy'),'dd/mm/yyyy') <> TO_DATE (TO_CHAR (C.DT_INS,'dd/mm/yyyy'),'dd/mm/yyyy'))CASO_mod
                                GROUP BY ZONA_SOCIALE, COMUNE,belfiore,TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy'))  d
                                  ON     c.ZONA_SOCIALE = d.zona_sociale
                                     AND c.comune = d.comune
                                     and c.belfiore =d.belfiore
                                      and c.data1=d.data1
                                      and c.data2=d.data2
                                      and c.data3=d.data3) bb
                          ON     aa."ZONA SOCIALE" = bb."ZONA SOCIALE"
                             AND aa.COMUNE = bb.COMUNE
                             and aa.belfiore=bb.belfiore
                             and aa.data_=bb.data_
                             and aa.ANNO=bb.ANNO
                             and aa.MESE=bb.MESE) aaa
               FULL OUTER JOIN
               --fascicolo--
               (SELECT  TO_CHAR (NVL (zz."ZONA SOCIALE", yy."ZONA SOCIALE"))"ZONA SOCIALE",
                               TO_CHAR (NVL (zz.comune, yy.comune)) "COMUNE",
                               TO_CHAR (NVL (zz.belfiore, yy.belfiore)) belfiore,
                               TO_CHAR (NVL(zz.data1,yy.data1))DATA_,
                               TO_CHAR (NVL(zz.data2,yy.data2))ANNO,
                               TO_CHAR (NVL(zz.data3,yy.data3))MESE,   
                               NVL (zz."NUMERO FASCICOLI INSERITI", 0)"NUMERO TIPO FASC INSERITI",
                               NVL (YY."NUMERO FASCICOLI MODIFICATI", 0)"NUMERO TIPO FASC MODIFICATI"
                               from (
 (  SELECT ZONA_SOCIALE "ZONA SOCIALE",
                         COMUNE,
                         belfiore,
                         COUNT (DISTINCT CASO_ID) "NUMERO FASCICOLI INSERITI",
                         TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                         EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                         EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) data3
                    FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC) ZONA_SOCIALE,
                                 ORG.NOME COMUNE,
                                 ORG.COD_ROUTING belfiore,
                                 D.*
                            FROM CS_D_DIARIO D,
                                 CS_O_OPERATORE_SETTORE OS,
                                 CS_O_SETTORE SETT,
                                 CS_O_ORGANIZZAZIONE ORG
                           WHERE     D.TIPO_DIARIO_ID NOT IN (1,
                                                              13,
                                                              14,
                                                              15)
                                 AND D.CASO_ID IS NOT NULL
                                 AND D.OPERATORE_SETTORE_ID = OS.ID
                                 AND OS.SETTORE_ID = SETT.ID
                                 AND ORG.ID = SETT.ORGANIZZAZIONE_ID) FASCICOLO_INS
                GROUP BY ZONA_SOCIALE, COMUNE,belfiore,TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy'))zz
                FULL OUTER JOIN
                (  SELECT ZONA_SOCIALE "ZONA SOCIALE",
                         COMUNE,
                         belfiore,
                         COUNT (DISTINCT CASO_ID) "NUMERO FASCICOLI MODIFICATI",
                         TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                         EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                         EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data3
                    FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC) ZONA_SOCIALE,
                                 ORG.NOME COMUNE,
                                 ORG.COD_ROUTING belfiore,
                                 D.*
                            FROM CS_D_DIARIO D,
                                 CS_O_OPERATORE_SETTORE OS,
                                 CS_O_SETTORE SETT,
                                 CS_O_ORGANIZZAZIONE ORG
                           WHERE     D.TIPO_DIARIO_ID NOT IN (1,
                                                              13,
                                                              14,
                                                              15)
                                 AND D.CASO_ID IS NOT NULL
                                 AND D.OPERATORE_SETTORE_ID = OS.ID
                                 AND OS.SETTORE_ID = SETT.ID
                                 AND D.DT_mod is not null
                                 AND TO_DATE (TO_CHAR ( D.DT_MOD,'dd/mm/yyyy'),'dd/mm/yyyy') <>TO_DATE (TO_CHAR (D.DT_ins,'dd/mm/yyyy'),'dd/mm/yyyy')
                                 AND ORG.ID = SETT.ORGANIZZAZIONE_ID) FASCICOLO_mod
                GROUP BY ZONA_SOCIALE, COMUNE,belfiore,TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy'))yy                
                            ON     zz."ZONA SOCIALE" = yy."ZONA SOCIALE"
                                     AND zz.comune = yy.comune
                                     and zz.belfiore =yy.belfiore
                                      and zz.data1=yy.data1
                                      and zz.data2=yy.data2
                                      and zz.data3=yy.data3))bbb
                  ON     aaa."ZONA SOCIALE" = bbb."ZONA SOCIALE"
                     AND aaa.COMUNE = bbb.COMUNE
                      AND aaa.COMUNE = bbb.COMUNE
                      and aaa.belfiore=bbb.belfiore
                      and aaa.data_=bbb.data_
                      and aaa.ANNO=bbb.ANNO
                      and aaa.MESE=bbb.MESE
                ) AAAA
       FULL OUTER JOIN
        (SELECT TO_CHAR (NVL (e.ZONA_SOCIALE, F.ZONA_SOCIALE)) "ZONA SOCIALE",
               TO_CHAR (NVL (e.COMUNE, F.COMUNE)) "COMUNE",
               TO_CHAR (NVL (e.belfiore, F.belfiore)) belfiore,
               TO_CHAR (NVL(e.data1,f.data1))DATA_,
               TO_CHAR (NVL(e.data2,f.data2))ANNO,
               TO_CHAR (NVL(e.data3,f.data3))MESE,       
               NVL (e."NUMERO EROGAZIONI INSERITE", 0)"NUMERO EROGAZIONI INSERITE",
               NVL (F."NUMERO EROGAZIONI MODIFICATE", 0)"NUMERO EROGAZIONI MODIFICATE"
          FROM (  SELECT ZONA_SOCIALE,
                         COMUNE,
                         belfiore,
                         COUNT (DISTINCT ID) "NUMERO EROGAZIONI INSERITE",
                         TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                         EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                         EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) data3
                    FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC) ZONA_SOCIALE,
                                 org.NOME COMUNE,
                                 ORG.COD_ROUTING belfiore,
                                 MAST.*
                            FROM cs_i_intervento_eseg_mast mast,
                                 cs_i_intervento_pr prog,
                                 cs_o_settore sett,
                                 cs_o_organizzazione org
                           WHERE     MAST.INT_PROGETTO_ID = PROG.ID
                                 AND PROG.SETTORE_TITOLARE_ID = sett.id
                                 AND sett.organizzazione_id = org.id
                                ) erog_INS
                GROUP BY ZONA_SOCIALE, COMUNE, belfiore,TO_DATE (TO_CHAR (dt_ins,'dd/mm/yyyy'),'dd/mm/yyyy')) e
               FULL OUTER JOIN
               (  SELECT ZONA_SOCIALE,
                         COMUNE,
                         belfiore,
                         COUNT (DISTINCT ID) "NUMERO EROGAZIONI MODIFICATE",
                         TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy') data1,
                         EXTRACT (YEAR FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data2,
                         EXTRACT (MONTH FROM TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) data3
                    FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC) ZONA_SOCIALE,
                                 org.NOME COMUNE,
                                 ORG.COD_ROUTING belfiore,
                                 MAST.*
                            FROM cs_i_intervento_eseg_mast mast,
                                 cs_i_intervento_pr prog,
                                 cs_o_settore sett,
                                 cs_o_organizzazione org
                           WHERE     MAST.INT_PROGETTO_ID = PROG.ID
                                 AND PROG.SETTORE_TITOLARE_ID = sett.id
                                 AND sett.organizzazione_id = org.id
                                 AND TO_DATE (TO_CHAR (MAST.DT_MOD, 'dd/mm/yyyy'),'dd/mm/yyyy') <>TO_DATE (TO_CHAR (MAST.DT_INS, 'dd/mm/yyyy'),'dd/mm/yyyy')) erog_MOD
                GROUP BY ZONA_SOCIALE, COMUNE, belfiore,TO_DATE (TO_CHAR (dt_mod,'dd/mm/yyyy'),'dd/mm/yyyy')) F
                  ON e.ZONA_SOCIALE = F.ZONA_SOCIALE
                   AND e.COMUNE = F.COMUNE
                   AND e.BELFIORE=f.BELFIORE
                   and e.data1=f.data1
                   and e.data2=f.data2
                   and e.data3=f.data3)
                   BBBB
          ON      AAAA."ZONA SOCIALE" = BBBB."ZONA SOCIALE"
              AND AAAA.COMUNE = BBBB.COMUNE
              AND aaaa.BELFIORE=BBBB.BELFIORE
              and aaaa.DATA_=bbbb.DATA_
              and aaaa.ANNO=bbbb.ANNO
              AND aaaa.MESE=bbbb.MESE;


DROP VIEW CS_ROMA.V_NUM_INT_CS;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_NUM_INT_CS
(
    ZONA_SOCIALE,
    ORGANIZZAZIONE_ID,
    ORGANIZZAZIONE,
    SETTORE_ID,
    SETTORE,
    CATEGORIA_SOCIALE_ID,
    CATEGORIA_SOCIALE,
    DATAINS,
    DATA_INSERIMENTO,
    N_SCHEDE_CARTELLA_SOCIALE
)
BEQUEATH DEFINER
AS
      SELECT 7                                   AS "ZONA_SOCIALE",
             IT.organizzazione_id,
             O.NOME                              ORGANIZZAZIONE,
             settore_id,
             SE.NOME                             AS SETTORE,
             SC.CATEGORIA_SOCIALE_ID,
             CAT.DESCRIZIONE                     AS "CATEGORIA_SOCIALE",
             C.DT_INS                            DATAINS,
             TO_CHAR (C.DT_INS, 'DD/MM/YYYY')    AS "DATA_INSERIMENTO",
             --C.ID,
             COUNT (DISTINCT S.ANAGRAFICA_ID)    AS "N_SCHEDE_CARTELLA_SOCIALE"
        FROM CS_A_SOGGETTO              S,
             CS_A_ANAGRAFICA            a,
             CS_A_CASO                  c,
             CS_A_SOGGETTO_CATEGORIA_SOC sc,
             CS_IT_STEP                 it,
             CS_D_DIARIO                ITD,
             CS_A_CASO_OPE_TIPO_OPE     coto,
             CS_O_ORGANIZZAZIONE        O,
             cs_O_SETTORE               SE,
             CS_C_CATEGORIA_SOCIALE     CAT
       WHERE     S.CASO_ID = C.ID
             AND S.ANAGRAFICA_ID = A.ID
             AND SC.SOGGETTO_ANAGRAFICA_ID = S.ANAGRAFICA_ID
             AND SC.DATA_FINE_APP >= SYSDATE
             AND SC.PREVALENTE = 1
             AND COTO.CASO_ID(+) = C.ID
             AND IT.ID = (SELECT MAX (it2.id)
                            FROM CS_IT_STEP it2
                           WHERE IT2.CASO_ID = S.CASO_ID)
             AND ITD.ID = IT.DIARIO_ID
             AND IT.ORGANIZZAZIONE_ID = O.ID
             AND IT.SETTORE_ID = SE.ID
             AND SC.CATEGORIA_SOCIALE_ID = CAT.ID
    --  AND SC.CATEGORIA_SOCIALE_ID = 1
    GROUP BY IT.organizzazione_id,
             settore_id,
             SE.NOME,
             SC.CATEGORIA_SOCIALE_ID,
             -- C.ID,
             O.NOME,
             CAT.DESCRIZIONE,
             C.DT_INS;


DROP VIEW CS_ROMA.V_NUM_INT_UDC;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_NUM_INT_UDC
(
    ZONA_SOCIALE,
    ORGANIZZAZIONE_ID,
    ORGANIZZAZIONE,
    UFFICIO_ID,
    UFFICIO,
    PUNTO_DI_CONTATTO_ID,
    PUNTO_DI_CONTATTO,
    TIPO_INTEVENTO_ID,
    TIPO_INTERVENTO,
    COMPLETA,
    ELIMINATA,
    DATA,
    N_SCHEDE_UDC
)
BEQUEATH DEFINER
AS
      SELECT (SELECT nome FROM cs_o_zona_soc)     "ZONA_SOCIALE",
             ORG.ID                               ORGANIZZAZIONE_ID,
             ORG.NOME                             ORGANIZZAZIONE,
             U.ID                                 UFFICIO_ID,
             U.NOME                               UFFICIO,
             PC.ID                                PUNTO_DI_CONTATTO_ID,
             PC.NOME                              PUNTO_DI_CONTATTO,
             S.TIPO                               TIPO_INTEVENTO_ID,
             TS.TIPO                              TIPO_INTERVENTO,
             S.COMPLETA,
             S.ELIMINATA,
             TO_CHAR (SA.DATA, 'DD/MM/YYYY')      DATA,
             COUNT (S.ID)                         N_SCHEDE_UDC
        FROM ss_scheda          s,
             ss_scheda_accesso  sa,
             cs_o_organizzazione org,
             ss_ufficio         u,
             ss_punto_contatto  pc,
             ss_tipo_scheda     ts
       WHERE     S.ACCESSO = sa.id(+)
             AND ORg.ID = SA.REL_UPO_ORGANIZZAZIONE_ID
             AND U.ID = SA.REL_UPO_UFFICIO_ID
             AND PC.ID = SA.REL_UPO_PUNTO_CONTATTO_ID
             AND S.TIPO = TS.ID(+)
    GROUP BY ORG.ID,
             ORG.NOME,
             U.ID,
             U.NOME,
             PC.ID,
             PC.NOME,
             S.TIPO,
             TS.TIPO,
             S.COMPLETA,
             S.ELIMINATA,
             SA.DATA;


DROP VIEW CS_ROMA.V_NUM_INT_UDC_DETT;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_NUM_INT_UDC_DETT
(
    ZONA_SOCIALE,
    ID_SCHEDA,
    ORGANIZZAZIONE_ID,
    ORGANIZZAZIONE,
    UFFICIO_ID,
    UFFICIO,
    PUNTO_DI_CONTATTO_ID,
    PUNTO_DI_CONTATTO,
    COGNOME,
    NOME,
    CITTADINANZA,
    COMUNE,
    VIA,
    TIPO_INTEVENTO_ID,
    TIPO_INTERVENTO,
    INTERLOCUTORE,
    COMPLETA,
    ELIMINATA,
    DATA_INSERIMENTO,
    DATA_ACCESSO,
    SESSO,
    DATA_NASCITA,
    ETA,
    ID,
    BISOGNI_ESPRESSI,
    INTER_RICH,
    SERVIZI_RICHIESTI
)
BEQUEATH DEFINER
AS
    SELECT (SELECT nome FROM cs_o_zona_soc)
               "ZONA_SOCIALE",
           S.ID
               id_scheda,
           ORG.ID
               ORGANIZZAZIONE_ID,
           ORG.NOME
               ORGANIZZAZIONE,
           U.ID
               UFFICIO_ID,
           U.NOME
               UFFICIO,
           PC.ID
               PUNTO_DI_CONTATTO_ID,
           PC.NOME
               PUNTO_DI_CONTATTO,
           a.cognome,
           a.nome,
           a.cittadinanza,
           I.COMUNE_COD,
           -- com.denominazione,
           I.VIA,
           S.TIPO
               TIPO_INTEVENTO_ID,
           CASE
               WHEN TS.TIPO IS NULL AND s.COMPLETA = 0 AND S.ELIMINATA = 0
               THEN
                   'da completare'
               WHEN     TS.TIPO IS NOT NULL
                    AND s.COMPLETA = 1
                    AND S.ELIMINATA = 1
               THEN
                   'eliminata'
               WHEN TS.TIPO IS NULL AND s.COMPLETA = 0 AND S.ELIMINATA = 1
               THEN
                   'eliminata'
               ELSE
                   TS.TIPO
           END
               "TIPO_INTERVENTO",
           SA.INTERLOCUTORE,
           --TS.TIPO TIPO_INTERVENTO,
           S.COMPLETA,
           S.ELIMINATA,
           S.DT_INS
               DATA_INSERIMENTO,
           TO_CHAR (SA.DATA, 'DD/MM/YYYY')
               DATA_ACCESSO,
           A.SESSO,
           A.DATA_NASCITA,
             --extract ( year from (sysdate))-1,
             -- --case when  extract ( month from (data_nascita)) >  extract ( month from (sysdate))
             --                              or extract ( month from (data_nascita))= extract ( month from (sysdate)) and extract ( day from (data_nascita))>extract ( day from (sysdate))
             --                           then 1 else 0 end tt,
             EXTRACT (YEAR FROM (SYSDATE))
           - CASE
                 WHEN EXTRACT (MONTH FROM (data_nascita)) > EXTRACT (MONTH FROM (SYSDATE)) OR EXTRACT (MONTH FROM (data_nascita)) = EXTRACT (MONTH FROM (SYSDATE)) AND EXTRACT (DAY FROM (data_nascita)) > EXTRACT (DAY FROM (SYSDATE))
                 THEN
                     1
                 ELSE
                     0
             END
           - EXTRACT (YEAR FROM (data_nascita))
               eta,
           ms.ID,
           CASE WHEN M.MOTIVO IS NULL THEN 'Non Inserito' ELSE M.MOTIVO END
               bisogni_espressi,
           ints.id
               inter_rich,
           CASE
               WHEN intd.intervento IS NULL THEN 'Non Inserito'
               ELSE intd.intervento
           END
               servizi_richiesti
      --COUNT (S.ID) N_SCHEDE_UDC
      FROM ss_scheda              s,
           ss_scheda_accesso      sa,
           cs_o_organizzazione    org,
           ss_ufficio             u,
           ss_punto_contatto      pc,
           ss_tipo_scheda         ts,
           ss_scheda_segnalato    se,
           ss_anagrafica          a,
           ss_motivazioni_schede  ms,
           ss_motivazione         m,
           ss_scheda_motivazione  sm,
           ss_indirizzo           i,
           ss_interventi_schede   ints,
           ss_scheda_interventi   scint,
           ss_intervento          intd
     -- TAB_ISTAT_COMUNI_ITA com
     WHERE     S.ACCESSO = sa.id(+)
           AND ORg.ID = SA.REL_UPO_ORGANIZZAZIONE_ID
           AND U.ID = SA.REL_UPO_UFFICIO_ID
           AND PC.ID = SA.REL_UPO_PUNTO_CONTATTO_ID
           AND S.TIPO = TS.ID(+)
           AND S.SEGNALATO = SE.ID(+)
           AND SE.ANAGRAFICA = A.ID(+)
           AND S.MOTIVAZIONE = SM.ID(+)
           AND SM.ID = ms.scheda_motivazione_id(+)
           AND ms.motivazione = m.id(+)
           AND se.RESIDENZA = I.ID(+)
           -- and I.COMUNE=com.codice_istat_com
           AND (S.COMPLETA <> 0 OR S.ELIMINATA <> 1)
           AND S.INTERVENTI = scint.id(+)
           AND scint.id = ints.scheda(+)
           AND ints.intervento = intd.id(+);


DROP VIEW CS_ROMA.V_O_OPERATORI_SETTORI;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_O_OPERATORI_SETTORI
(
    OPERATORE_SETTORE_ID,
    OPERATORE_ID,
    USERNAME,
    COGNOME,
    NOME,
    ORGANIZZAZIONE_ID,
    ORGANIZZAZIONE_NOME,
    COD_CATASTALE,
    COD_ROUTING,
    ORGANIZZAZIONE_CF,
    FLAG_CAPOFILA,
    SETTORE_ID,
    SETTORE_NOME,
    SETTORE_EMAIL,
    SECONDO_LIVELLO
)
BEQUEATH DEFINER
AS
    SELECT osins.ID           OPERATORE_SETTORE_ID,
           OPERATORE_ID,
           OP.USERNAME,
           A.COGNOME,
           A.NOME,
           oins.id            organizzazione_id,
           oins.nome          ORGANIZZAZIONE_NOME,
           oins.cod_catastale,
           oins.cod_routing,
           oins.cf            ORGANIZZAZIONE_CF,
           oins.flag_capofila,
           sins.id            settore_id,
           sins.nome          settore_nome,
           SINS.EMAIL         SETTORE_EMAIL,
           SL.DESCRIZIONE     SECONDO_LIVELLO
      FROM cs_o_operatore_settore  osins
           LEFT JOIN cs_o_settore sins ON (OSINS.SETTORE_ID = SINS.ID)
           LEFT JOIN CS_TB_SECONDO_LIVELLO SL ON (ID_SECONDO_LIVELLO = SL.ID)
           LEFT JOIN CS_O_ORGANIZZAZIONE OINS
               ON (SINS.ORGANIZZAZIONE_ID = OINS.ID)
           LEFT JOIN cs_o_operatore op ON (OP.ID = OSINS.OPERATORE_ID)
           LEFT JOIN AM_ANAGRAFICA A ON A.FK_AM_USER = OP.USERNAME;


DROP VIEW CS_ROMA.V_PROB_APERTE;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_PROB_APERTE
(
    ID,
    DESCRIZIONE,
    FLAG_MAT_IMM,
    TIPO,
    TOOLTIP,
    ABILITATO,
    CASO_ID,
    RESPONSABILE_ID,
    TEMPO_TRASCORSO,
    Z_ZONA_SOCIALE
)
BEQUEATH DEFINER
AS
    SELECT p."ID",
           p."DESCRIZIONE",
           p."FLAG_MAT_IMM",
           p."TIPO",
           p."TOOLTIP",
           p."ABILITATO",
           d.caso_id,
           d.responsabile_id,
           CASE
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 1
               THEN
                   '0 - 1 Mese'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 2
               THEN
                   '1 - 2 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 3
               THEN
                   '2 - 3 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 4
               THEN
                   '3 - 4 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 5
               THEN
                   '4 - 5 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 6
               THEN
                   '5 - 6 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 7
               THEN
                   '6 - 7 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 8
               THEN
                   '7 - 8 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 9
               THEN
                   '8 - 9 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 10
               THEN
                   '9 - 10 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 11
               THEN
                   '10 - 11 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) < 12
               THEN
                   '11 -12 Mesi'
               WHEN (MONTHS_BETWEEN (SYSDATE, d.dt_amministrativa)) > 12
               THEN
                   'Oltre 1 Anno'
           END                                 tempo_trascorso,
           (SELECT nome FROM cs_o_zona_soc)    Z_ZONA_SOCIALE
      FROM cs_rel_relazione_prob rrp, cs_d_diario d, cs_tb_prob p
     WHERE     rrp.relazione_diario_id = d.id
           AND rrp.flag_risolta = '0'
           AND p.id = prob_id
           AND NOT EXISTS
                   (SELECT 1
                      FROM cs_rel_relazione_prob  rrpa
                           INNER JOIN cs_d_diario da
                               ON rrpa.relazione_diario_id = da.id
                     WHERE     d.caso_id = da.caso_id
                           AND rrp.prob_id = rrpa.prob_id
                           AND d.dt_amministrativa <= da.dt_amministrativa
                           AND rrpa.flag_risolta = '1');


DROP VIEW CS_ROMA.V_SETT_CATSOC_TIPOINT;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_SETT_CATSOC_TIPOINT
(
    SETTORE_ID,
    NOME,
    INTERVENTO_ID,
    ORIGINE_DATO,
    DESCRIZIONE_INTERVENTO,
    CATEGORIA_SOCIALE_ID,
    CATEGORIA_SOCIALE_DESCR
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT A.SETTORE_ID,
                    S.NOME,
                    b.t_classe_id     INTERVENTO_ID,
                    'ARGO'            ORIGINE_DATO,
                    b.descrizione     DESCRIZIONE_INTERVENTO,
                    c.id              categoria_sociale_id,
                    C.DESCRIZIONE     categoria_sociale_descr
      FROM CS_rel_settore_catsoc   a,
           v_gerarchia_servizi     b,
           cs_c_categoria_sociale  c,
           cs_o_settore            s
     WHERE     A.CATEGORIA_SOCIALE_ID = c.id
           AND C.DESCRIZIONE = b.root_descrizione
           AND flag_intervento = '1'
           AND A.SETTORE_ID = s.id
    UNION
    SELECT DISTINCT A.SETTORE_ID,
                    S.NOME,
                    b.ID              INTERVENTO_ID,
                    'CUSTOM'          ORIGINE_DATO,
                    b.descrizione     DESCRIZIONE_INTERVENTO,
                    c.id              categoria_sociale_id,
                    C.DESCRIZIONE     categoria_sociale_descr
      FROM cs_rel_settore_catsoc        a,
           CS_C_TIPO_INTERVENTO_CUSTOM  b,
           CS_REL_CATSOC_TIPO_INTER     CTI,
           cs_c_categoria_sociale       c,
           cs_o_settore                 s
     WHERE     A.CATEGORIA_SOCIALE_ID = CTI.CATEGORIA_SOCIALE_ID
           AND C.ID = CTI.CATEGORIA_SOCIALE_ID
           AND B.ID = CTI.TIPO_INTERVENTO_ID
           AND A.SETTORE_ID = s.id;


DROP VIEW CS_ROMA.V_SS_SCHEDE;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_SS_SCHEDE
(
    PK_SCHEDA_ID,
    O_ZONA_SOCIALE,
    O_BELFIORE,
    O_NOME_ORG,
    O_NOME_UFFICIO,
    O_PUNTO_DI_CONTATTO,
    S_COMPLETA,
    S_ELIMINATA,
    S_DATA,
    S_TIPO_INTERVENTO,
    S_MODALITA,
    S_MOTIVO,
    S_INTERLOCUTORE,
    U_STRANIERO_N_ACC,
    U_TELEFONO,
    U_CELLULARE,
    U_EMAIL,
    U_TESSERA_SANITARIA,
    U_MEDICO,
    U_STP,
    U_COND_LAVORO,
    U_TITOLO_STUDIO,
    U_CITTADINANZA,
    U_CITTADINANZA_2,
    U_COGNOME,
    CF,
    U_NOME,
    U_SESSO,
    U_ETA,
    U_COMUNE_NASCITA_COD,
    U_COMUNE_NASCITA_DES,
    U_DATA_NASCITA,
    U_PROV_NASCITA_COD,
    U_STATO_NASCITA_COD,
    U_STATO_NASCITA_DES,
    U_COMUNE_RES,
    U_VIA_RES,
    UPC,
    COGNOME_SEGN,
    NOME_SEGN,
    CF_SEGN
)
BEQUEATH DEFINER
AS
    SELECT S.ID
               PK_SCHEDA_ID,
           (SELECT nome FROM cs_o_zona_soc)
               O_ZONA_SOCIALE,
           ORG.COD_ROUTING
               O_BELFIORE,
           ORG.NOME
               O_NOME_ORG,
           U.NOME
               O_NOME_UFFICIO,
           PC.NOME
               O_PUNTO_DI_CONTATTO,
           S.COMPLETA
               S_COMPLETA,
           S.ELIMINATA
               S_ELIMINATA,
           SA.DATA
               S_DATA,
           TS.TIPO
               S_TIPO_INTERVENTO,
           SA.MODALITA
               S_MODALITA,
           SA.MOTIVO
               S_MOTIVO,
           SA.INTERLOCUTORE
               S_INTERLOCUTORE,
           SE.STRANIERO_N_ACC
               U_STRANIERO_N_ACC,
           SE.TELEFONO
               U_TELEFONO,
           SE.CEL
               U_CELLULARE,
           SE.EMAIL
               U_EMAIL,
           SE.TESSERA_SANITARIA
               U_TESSERA_SANITARIA,
           SE.MEDICO
               U_MEDICO,
           STP
               U_STP,
           TBCL.DESCRIZIONE
               U_COND_LAVORO,
           TBTS.DESCRIZIONE
               U_TITOLO_STUDIO,
           --    NULL U_STATUS_GIURIDICO,
           A.CITTADINANZA
               U_CITTADINANZA,
           A.CITTADINANZA_2
               U_CITTADINANZA_2,
           A.COGNOME
               U_COGNOME,
           A.CF,
           A.NOME
               U_NOME,
           A.SESSO
               U_SESSO,
           TRUNC (MONTHS_BETWEEN (SYSDATE, A.data_nascita) / 12)
               U_ETA,
           A.COMUNE_NASCITA_COD
               U_COMUNE_NASCITA_COD,
           A.COMUNE_NASCITA_DES
               U_COMUNE_NASCITA_DES,
           A.DATA_NASCITA
               U_DATA_NASCITA,
           A.PROV_NASCITA_COD
               U_PROV_NASCITA_COD,
           A.STATO_NASCITA_COD
               U_STATO_NASCITA_COD,
           A.STATO_NASCITA_DES
               U_STATO_NASCITA_DES,
           I.COMUNE_COD
               U_COMUNE_RES,
           I.VIA
               U_VIA_RES,
           ORG.ID || U.ID || PC.ID
               upc,
           SS.COGNOME
               COGNOME_SEGN,
           SS.NOME
               NOME_SEGN,
           SS.CF
               CF_SEGN
      FROM ss_scheda  s
           LEFT JOIN ss_scheda_accesso sa ON S.ACCESSO = sa.id
           LEFT JOIN ss_tipo_scheda ts ON S.TIPO = TS.ID
           LEFT JOIN cs_o_organizzazione org
               ON org.ID = SA.REL_UPO_ORGANIZZAZIONE_ID
           LEFT JOIN ss_ufficio u ON U.ID = SA.REL_UPO_UFFICIO_ID
           LEFT JOIN ss_punto_contatto pc
               ON PC.ID = SA.REL_UPO_PUNTO_CONTATTO_ID
           LEFT JOIN SS_SCHEDA_SEGNALATO SE ON S.SEGNALATO = SE.ID
           LEFT JOIN SS_ANAGRAFICA A ON SE.ANAGRAFICA = A.ID
           LEFT JOIN ss_indirizzo i ON se.RESIDENZA = I.ID
           LEFT JOIN CS_TB_COND_LAVORO TBCL ON SE.LAVORO = TBCL.ID
           LEFT JOIN CS_TB_TITOLO_STUDIO TBTS
               ON SE.TITOLO_STUDIO_ID = TBTS.ID
           LEFT JOIN SS_SCHEDA_SEGNALANTE SS ON S.SEGNALANTE = SS.ID;


DROP VIEW CS_ROMA.V_SS_SCHEDE_UDC_DIFF;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_SS_SCHEDE_UDC_DIFF
(
    ID_SCHEDA,
    CF,
    NOME,
    COGNOME,
    DT
)
BEQUEATH DEFINER
AS
      SELECT MAX (s2.ID)         AS ID_SCHEDA,
             a.CF,
             a.NOME,
             a.COGNOME,
             MAX (s3."DATA")     AS DT
        FROM CS_A_ANAGRAFICA    a,
             SS_ANAGRAFICA      sa,
             SS_SCHEDA_SEGNALATO s,
             SS_SCHEDA          s2,
             SS_SCHEDA_ACCESSO  s3,
             CS_A_SOGGETTO      sog
       WHERE     sog.ANAGRAFICA_ID = a.id
             AND s.ANAGRAFICA = sa.id
             AND s2.SEGNALATO = s.ID
             AND s2.completa = 1
             AND s2.eliminata = 0
             AND s3.ID = s2.ACCESSO
             AND UPPER (a.CF) = UPPER (sa.CF)
             AND s3."DATA" > (SELECT MAX (a1.DATA_INIZIO_APP)
                                FROM CS_A_DATI_SOCIALI a1
                               WHERE a1.SOGGETTO_ANAGRAFICA_ID = a.ID)
    GROUP BY a.CF, a.NOME, a.COGNOME
    ORDER BY a.CF, dt;


