    U_STP,
    U_COND_LAVORO,
    U_TITOLO_STUDIO,
    U_CITTADINANZA,
    U_CITTADINANZA_2,
    U_COGNOME,
    CF,
    U_NOME,
    U_SESSO,
    U_COMUNE_NASCITA_COD,
