    I_AFFIDATARIO,
    I_RUOLO,
    SENZA_FISSA_DIMORA,
    ALIAS
)
BEQUEATH DEFINER
AS
    (SELECT SA.PK_SCHEDA_ID,
            Z_ZONA_SOCIALE
                ZONA_SOCIALE,
            O_NOME_ORG
                ORGANIZZAZIONE,
            O_BELFIORE
                BELFIORE,
            O_NOME_UFFICIO
                UFFICIO,
            O_PUNTO_DI_CONTATTO
                PUNTO_DI_CONTATTI,
            SA.S_COMPLETA,
            SA.S_ELIMINATA,
            SA.S_DATA,
            SA.S_TIPO_INTERVENTO,
            SA.S_MODALITA,
            SA.S_MOTIVO,
            SA.S_INTERLOCUTORE,
            SA.U_STRANIERO_N_ACC,
            SA.U_TELEFONO,
            SA.U_CELLULARE,
            SA.U_EMAIL,
            SA.U_TESSERA_SANITARIA,
            SA.U_MEDICO,
            SA.U_STP,
            SA.U_COND_LAVORO,
            SA.U_TITOLO_STUDIO,
            SA.U_CITTADINANZA,
            SA.U_CITTADINANZA_2,
            SA.U_COGNOME,
            SA.CF,
            SA.U_NOME,
            SA.U_SESSO,
            SA.U_COMUNE_NASCITA_COD,
            SA.U_COMUNE_NASCITA_DES,
            SA.U_DATA_NASCITA,
            SA.U_PROV_NASCITA_COD,
            SA.U_STATO_NASCITA_COD,
            SA.U_STATO_NASCITA_DES,
            SA.U_COMUNE_RES,
            SA.U_VIA_RES,
            TRUNC (MONTHS_BETWEEN (SYSDATE, SA.U_DATA_NASCITA) / 12)
                U_ETA,
            OPERATORE,
            UTENTE_ACCOMPAGNATO,
            UTENTE_PRESENTE_INFORMATO,
            I_COGNOME,
            i_NOME,
            I_AFFIDATARIO,
            I_RUOLO,
            SENZA_FISSA_DIMORA,
            ALIAS
       FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)    Z_ZONA_SOCIALE,
                    S.ID                                PK_SCHEDA_ID,
                    ORG.cod_routing                     O_BELFIORE,
                    ORG.NOME                            O_NOME_ORG,
                    U.NOME                              O_NOME_UFFICIO,
                    PC.NOME                             O_PUNTO_DI_CONTATTO,
                    S.COMPLETA                          S_COMPLETA,
                    S.ELIMINATA                         S_ELIMINATA,
                    SA.DATA                             S_DATA,
                    TS.TIPO                             S_TIPO_INTERVENTO,
                    SA.MODALITA                         S_MODALITA,
                    SA.MOTIVO                           S_MOTIVO,
                    SA.INTERLOCUTORE                    S_INTERLOCUTORE,
                    SE.STRANIERO_N_ACC                  U_STRANIERO_N_ACC,
                    SE.TELEFONO                         U_TELEFONO,
                    SE.CEL                              U_CELLULARE,
                    SE.EMAIL                            U_EMAIL,
                    SE.TESSERA_SANITARIA                U_TESSERA_SANITARIA,
                    SE.MEDICO                           U_MEDICO,
                    STP                                 U_STP,
                    TBCL.DESCRIZIONE                    U_COND_LAVORO,
                    TBTS.DESCRIZIONE                    U_TITOLO_STUDIO,
                    --    NULL U_STATUS_GIURIDICO,
                    A.CITTADINANZA                      U_CITTADINANZA,
                    A.CITTADINANZA_2                    U_CITTADINANZA_2,
                    A.COGNOME                           U_COGNOME,
                    TRIM (UPPER (A.CF))                 CF,
                    A.NOME                              U_NOME,
                    A.SESSO                             U_SESSO,
                    -- TRUNC (MONTHS_BETWEEN (SYSDATE, A.data_nascita) / 12) U_ETA,
                    A.COMUNE_NASCITA_COD                U_COMUNE_NASCITA_COD,
                    A.COMUNE_NASCITA_DES                U_COMUNE_NASCITA_DES,
                    A.DATA_NASCITA                      U_DATA_NASCITA,
                    A.PROV_NASCITA_COD                  U_PROV_NASCITA_COD,
                    A.STATO_NASCITA_COD                 U_STATO_NASCITA_COD,
                    A.STATO_NASCITA_DES                 U_STATO_NASCITA_DES,
                    I.COMUNE_COD                        U_COMUNE_RES,
                    I.VIA                               U_VIA_RES,
                    SA.OPERATORE,
                    SA.UTENTE_ACCOMPAGNATO,
                    SA.UTENTE_PRESENTE_INFORMATO,
                    SS.COGNOME                          I_COGNOME,
                    SS.NOME                             I_NOME,
                    SS.AFFIDATARIO                      I_AFFIDATARIO,
                    SS.RUOLO                            I_RUOLO,
                    SE.SENZA_FISSA_DIMORA,
                    A.ALIAS
               FROM ss_scheda  s
                    INNER JOIN ss_scheda_accesso sa ON S.ACCESSO = sa.id
                    LEFT JOIN SS_SCHEDA_SEGNALANTE SS ON s.segnalante = ss.id
                    LEFT JOIN ss_tipo_scheda ts ON S.TIPO = TS.ID
                    LEFT JOIN cs_o_organizzazione org
                        ON org.ID = SA.REL_UPO_ORGANIZZAZIONE_ID
                    LEFT JOIN ss_ufficio u ON U.ID = SA.REL_UPO_UFFICIO_ID
                    LEFT JOIN ss_punto_contatto pc
                        ON PC.ID = SA.REL_UPO_PUNTO_CONTATTO_ID
                    LEFT JOIN SS_SCHEDA_SEGNALATO SE ON S.SEGNALATO = SE.ID
                    LEFT JOIN SS_ANAGRAFICA A ON SE.ANAGRAFICA = A.ID
                    LEFT JOIN ss_indirizzo i ON se.RESIDENZA = I.ID
                    LEFT JOIN CS_TB_COND_LAVORO TBCL ON SE.LAVORO = TBCL.ID
                    LEFT JOIN CS_TB_TITOLO_STUDIO TBTS
                        ON SE.TITOLO_STUDIO_ID = TBTS.ID) SA);


DROP VIEW CS_ROMA.V_S2_BISOGNI;

/* Formatted on 18/07/2022 12:23:34 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_S2_BISOGNI
(
    ZONA_SOCIALE,
    PK_SCHEDA_ID_FK,
    S_BISOGNO
)
BEQUEATH DEFINER
AS
    (SELECT (SELECT nome FROM cs_o_zona_soc)     ZONA_SOCIALE,
            S.ID                                 pk_SCHEDA_ID_FK,
            mot.motivo                           S_bisogno
       FROM SS_SCHEDA  S
            LEFT JOIN SS_SCHEDA_MOTIVAZIONE SCMOT ON S.MOTIVAZIONE = SCMOT.id
            LEFT JOIN ss_motivazioni_schede mots
                ON scmot.id = mots.scheda_motivazione_id
            LEFT JOIN ss_motivazione mot ON mots.motivazione = mot.id);


