                                PUNTO_CONTATO,
                            AC.DATA
                                "DATA ACCESSO",
                            EXTRACT (YEAR FROM AC.DATA)
                                ANNO_INSERIMENTO,
                            EXTRACT (MONTH FROM AC.DATA)
                                MESE_INSERIMENTO,
                            ANAG.COGNOME || ' ' || ANAG.NOME
                                OPERATORE,
                            AC.INTERLOCUTORE,
                            SEGNAL.COGNOME || ' ' || SEGNAL.NOME
                                "COGNOME/NOME INTELOCUTORE",
                            AC.MOTIVO
                                "MOTIVO DI ACCESSO",
                            AC.MOTIVO_DESC
                                "DESCR MOTIVO DI ACCESSO",
                            AC.MODALITA
                                "MODALITA DI ACCESSO",
                            ANA.COGNOME || +' ' || +ANA.NOME
                                "COGNOME/NOME UTENTE",
                            ANA.CF
                                CODICE_FISCALE,
                            ANA.DATA_NASCITA,
                            TRUNC (
                                  MONTHS_BETWEEN (SYSDATE, ANA.data_nascita)
                                / 12)
                                ANNI,
                            CASE
                                WHEN TRUNC (
                                           MONTHS_BETWEEN (SYSDATE,
                                                           ANA.data_nascita)
                                         / 12) <
                                     18
                                THEN
                                    'Minore'
                            END
                                minore,
                            CASE
                                WHEN     TRUNC (
                                               MONTHS_BETWEEN (
                                                   SYSDATE,
                                                   ANA.data_nascita)
                                             / 12) >=
                                         18
                                     AND (  MONTHS_BETWEEN (SYSDATE,
                                                            ANA.data_nascita)
                                          / 12) <
                                         31
                                THEN
                                    '18 - 30'
                            END
                                DICTRE,
                            CASE
                                WHEN     TRUNC (
                                               MONTHS_BETWEEN (
                                                   SYSDATE,
                                                   ANA.data_nascita)
                                             / 12) >=
                                         31
                                     AND (  MONTHS_BETWEEN (SYSDATE,
                                                            ANA.data_nascita)
                                          / 12) <
                                         46
                                THEN
                                    '31 - 45'
                            END
                                TREQUA,
                            CASE
                                WHEN     TRUNC (
                                               MONTHS_BETWEEN (
                                                   SYSDATE,
                                                   ANA.data_nascita)
                                             / 12) >=
                                         46
                                     AND (  MONTHS_BETWEEN (SYSDATE,
                                                            ANA.data_nascita)
                                          / 12) <
                                         66
                                THEN
                                    '46 - 65'
                            END
                                QUARSESS,
                            CASE
                                WHEN TRUNC (
                                           MONTHS_BETWEEN (SYSDATE,
                                                           ANA.data_nascita)
                                         / 12) >
                                     65
                                THEN
                                    ' > 65'
                            END
                                MAG65,
                            CASE
                                WHEN TRUNC (
                                           MONTHS_BETWEEN (SYSDATE,
                                                           ANA.data_nascita)
                                         / 12) <
                                     18
                                THEN
                                    'Minore'
                                WHEN     TRUNC (
                                               MONTHS_BETWEEN (
                                                   SYSDATE,
                                                   ANA.data_nascita)
                                             / 12) >=
                                         18
                                     AND (  MONTHS_BETWEEN (SYSDATE,
                                                            ANA.data_nascita)
                                          / 12) <
                                         31
                                THEN
                                    '18 - 30'
                                WHEN     TRUNC (
                                               MONTHS_BETWEEN (
                                                   SYSDATE,
                                                   ANA.data_nascita)
                                             / 12) >=
                                         31
                                     AND (  MONTHS_BETWEEN (SYSDATE,
                                                            ANA.data_nascita)
                                          / 12) <
                                         46
                                THEN
                                    '31 - 45'
                                WHEN     TRUNC (
                                               MONTHS_BETWEEN (
                                                   SYSDATE,
                                                   ANA.data_nascita)
                                             / 12) >=
                                         46
                                     AND (  MONTHS_BETWEEN (SYSDATE,
                                                            ANA.data_nascita)
                                          / 12) <
                                         66
                                THEN
                                    '46 - 65'
                                WHEN TRUNC (
                                           MONTHS_BETWEEN (SYSDATE,
                                                           ANA.data_nascita)
                                         / 12) >
                                     65
                                THEN
                                    ' > 65'
                            END
                                fascia_eta,
                            ANA.SESSO,
                            ANA.STATO_CIVILE,
                            ANA.CITTADINANZA,
                            IND.VIA
                                "VIA DI RESIDENZA",
                            IND.COMUNE_DES
                                "COMUNE DI RESIDENZA",
                            TIT.DESCRIZIONE
                                "TITOLO DI STUDIO",
                            CLAV.DESCRIZIONE
                                "CONDIZIONE LAVORATIVA",
                            --  TIPF.DESCRIZIONE "TIPOLOGIA FAMILIARE",
                            MOT.MOTIVO
                                BISOGNI,
                            SER.INTERVENTO
                                SERVIZIO_RICHIESTO,
                            TIP.TIPO
                                TIPO_INTERVENTO,
                            CAT.DESCRIZIONE
                                "CATEGORIA SOCIALE"
                       FROM ss_scheda                  s,
                            ss_scheda_segnalato        seg,
                            ss_anagrafica              ana,
                            SS_SCHEDA_INTERVENTI       S_INT,
                            SS_INTERVENTI_SCHEDE       INT_S,
                            SS_INTERVENTO              SER,
                            SS_TIPO_SCHEDA             TIP,
                            CS_O_ORGANIZZAZIONE        ORG,
                            SS_UFFICIO                 UFF,
                            SS_PUNTO_CONTATTO          PC,
                            SS_SCHEDA_ACCESSO          AC,
                            SS_SCHEDA_SEGNALANTE       SEGNAL,
                            SS_INDIRIZZO               IND,
                            CS_TB_TITOLO_STUDIO        TIT,
                            CS_TB_COND_LAVORO          CLAV,
                            CS_TB_TIPOLOGIA_FAMILIARE  TIP_FAM,
                            SS_SCHEDA_MOTIVAZIONE      SMOT,
                            SS_MOTIVAZIONI_SCHEDE      MOTS,
                            SS_MOTIVAZIONE             MOT,
                            CS_SS_SCHEDA_SEGR          SEGR,
                            CS_C_CATEGORIA_SOCIALE     CAT,
                            CS_D_DIARIO                DIA,
                            CS_D_CLOB                  CLO,
                            -- CS_TB_TIPOLOGIA_FAMILIARE TIPF,
                            SS_OPERATORE_ANAGRAFICA    ANAG,
                            SS_REL_SCHEDA_CAT_SOC      rel_cat
                      WHERE     S.SEGNALATO = SEG.ID
                            AND SEG.ANAGRAFICA = ANA.ID
                            AND S.INTERVENTI = S_INT.ID(+)
                            AND S_INT.ID = INT_S.SCHEDA(+)
                            AND INT_S.INTERVENTO = SER.ID(+)
                            AND S.TIPO = TIP.ID
                            AND S.ACCESSO = AC.ID
                            AND AC.REL_UPO_ORGANIZZAZIONE_ID = ORG.ID
                            AND AC.REL_UPO_PUNTO_CONTATTO_ID = PC.ID
                            AND AC.REL_UPO_UFFICIO_ID = UFF.ID
                            AND S.SEGNALANTE = SEGNAL.ID(+)
                            AND SEG.RESIDENZA = IND.ID(+)
                            AND SEG.TITOLO_STUDIO_ID = TIT.ID(+)
                            AND SEG.LAVORO = CLAV.ID(+)
                            AND SEG.TIPOLOGIA_FAMILIARE = TIP_FAM.ID(+)
                            AND S.MOTIVAZIONE = SMOT.ID(+)
                            AND SMOT.ID = MOTS.SCHEDA_MOTIVAZIONE_ID(+)
                            AND MOTS.MOTIVAZIONE = MOT.ID(+)
                            AND S.ID = SEGR.ID(+)
                            AND S.ID = DIA.SCHEDA_ID
                            AND DIA.CLOB_ID = CLO.ID
                            --            AND TO_CHAR (CLO.DATI_CLOB) LIKE '%tipologiaFamiliare":%'
                            --            AND REPLACE (
                            --                   REPLACE (
                            --                      SUBSTR (
                            --                         TO_CHAR (CLO.DATI_CLOB),
                            --                           INSTR (TO_CHAR (CLO.DATI_CLOB),
                            --                                  'tipologiaFamiliare":')
                            --                         + 20,
                            --                         2),
                            --                      ',',
                            --                      ''),
                            --                   '}',
                            --                   '') = TIPF.ID
                            AND s.completa = 1
                            AND s.eliminata = 0
                            AND ANAG.OPERATORE(+) = AC.OPERATORE
                            AND S.ID = rel_cat.scheda_id(+)
                            AND rel_cat.categoria_sociale_id = cat.id(+)) aaa,
                    (SELECT DISTINCT
                            S.IDENTIFICATIVO,
                            perm.descrizione    permesso,
                            REPLACE (
                                REPLACE (
                                    REPLACE (
                                        REPLACE (
                                            REPLACE (
                                                SUBSTR (
                                                    TO_CHAR (CLO.DATI_CLOB),
                                                      INSTR (
                                                          TO_CHAR (
                                                              CLO.DATI_CLOB),
                                                          '"idPraticaPermesso":"')
                                                    + 20,
                                                    10),
                                                ',',
                                                ''),
                                            '}',
                                            ''),
                                        '"',
                                        ''),
                                    'null',
                                    ''),
                                'codice:',
                                '')             n_permesso
                       FROM ss_scheda                  s,
                            ss_scheda_segnalato        seg,
                            ss_anagrafica              ana,
                            SS_SCHEDA_INTERVENTI       S_INT,
                            SS_INTERVENTI_SCHEDE       INT_S,
                            SS_INTERVENTO              SER,
                            SS_TIPO_SCHEDA             TIP,
                            CS_O_ORGANIZZAZIONE        ORG,
                            SS_UFFICIO                 UFF,
                            SS_PUNTO_CONTATTO          PC,
                            SS_SCHEDA_ACCESSO          AC,
                            SS_SCHEDA_SEGNALANTE       SEGNAL,
                            SS_INDIRIZZO               IND,
                            CS_TB_TITOLO_STUDIO        TIT,
                            CS_TB_COND_LAVORO          CLAV,
                            CS_TB_TIPOLOGIA_FAMILIARE  TIP_FAM,
                            SS_SCHEDA_MOTIVAZIONE      SMOT,
                            SS_MOTIVAZIONI_SCHEDE      MOTS,
                            SS_MOTIVAZIONE             MOT,
                            CS_SS_SCHEDA_SEGR          SEGR,
                            CS_C_CATEGORIA_SOCIALE     CAT,
                            CS_D_DIARIO                DIA,
                            CS_D_CLOB                  CLO,
                            -- CS_TB_TIPOLOGIA_FAMILIARE TIPF,
                            SS_OPERATORE_ANAGRAFICA    ANAG,
                            cs_tb_permesso             perm,
                            SS_REL_SCHEDA_CAT_SOC      rel_cat
                      WHERE     S.SEGNALATO = SEG.ID
                            AND SEG.ANAGRAFICA = ANA.ID
                            AND S.INTERVENTI = S_INT.ID(+)
                            AND S_INT.ID = INT_S.SCHEDA(+)
                            AND INT_S.INTERVENTO = SER.ID(+)
                            AND S.TIPO = TIP.ID
                            AND S.ACCESSO = AC.ID
                            AND AC.REL_UPO_ORGANIZZAZIONE_ID = ORG.ID
                            AND AC.REL_UPO_PUNTO_CONTATTO_ID = PC.ID
                            AND AC.REL_UPO_UFFICIO_ID = UFF.ID
                            AND S.SEGNALANTE = SEGNAL.ID(+)
                            AND SEG.RESIDENZA = IND.ID(+)
                            AND SEG.TITOLO_STUDIO_ID = TIT.ID(+)
                            AND SEG.LAVORO = CLAV.ID(+)
                            AND SEG.TIPOLOGIA_FAMILIARE = TIP_FAM.ID(+)
                            AND S.MOTIVAZIONE = SMOT.ID(+)
                            AND SMOT.ID = MOTS.SCHEDA_MOTIVAZIONE_ID(+)
                            AND MOTS.MOTIVAZIONE = MOT.ID(+)
                            AND S.ID = SEGR.ID(+)
                            AND S.ID = DIA.SCHEDA_ID
                            AND DIA.CLOB_ID = CLO.ID
                            AND TO_CHAR (CLO.DATI_CLOB) LIKE
                                    '%"permesso":{"codice":%'
                            AND REPLACE (
                                    REPLACE (
                                        REPLACE (
                                            REPLACE (
                                                SUBSTR (
                                                    TO_CHAR (CLO.DATI_CLOB),
                                                      INSTR (
                                                          TO_CHAR (
                                                              CLO.DATI_CLOB),
                                                          '"permesso":{"codice":')
                                                    + 22,
                                                    2),
                                                ',',
                                                ''),
                                            '}',
                                            ''),
                                        '"',
                                        ''),
                                    'ul',
                                    '') =
                                perm.ID(+)
                            AND s.completa = 1
                            AND s.eliminata = 0
                            AND ANAG.OPERATORE(+) = AC.OPERATORE
                            AND S.ID = rel_cat.scheda_id(+)
                            AND rel_cat.categoria_sociale_id = cat.id(+)) bbb
              WHERE aaa.IDENTIFICATIVO = bbb.IDENTIFICATIVO(+)) dett,
            (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)    ZONA_SOC,
                    S.ID                                PK_SCHEDA_ID,
                    CAST (
                        (  TIMESTAMP '1970-01-01 00:00:00 GMT'
                         + NUMTODSINTERVAL (
                                 REPLACE (
                                     REPLACE (
                                         REPLACE (
                                             SUBSTR (
                                                 SUBSTR (
                                                     DBMS_LOB.SUBSTR (
                                                         C.DATI_CLOB,
                                                         4000,
                                                         26),
                                                       INSTR (
                                                           DBMS_LOB.SUBSTR (
                                                               C.DATI_CLOB,
                                                               4000,
                                                               26),
                                                           '"dataRichiesta"')
                                                     + 16),
                                                 1,
                                                 14),
                                             '"',
                                             ''),
                                         '}',
                                         ''),
                                     ',',
                                     '')
                               / 1000,
                               'SECOND'))
                            AT TIME ZONE 'Europe/Rome'
                            AS DATE)                    DATA_RICHIESTA,
                    c.id                                id_clob,
                    d.id                                diario_id,
                    SUBSTR (
                        DBMS_LOB.SUBSTR (C.DATI_CLOB, 4000, 26),
                        1,
                          INSTR (DBMS_LOB.SUBSTR (C.DATI_CLOB, 4000, 26),
                                 '","')
                        - 1)                            PRESTAZIONE,
                    Z.PDSMACRO,
                    T.PDSMICRO
               FROM CS_D_DIARIO             D,
                    SS_SCHEDA               S,
                    CS_D_CLOB               C,
                    CS_TB_MICRO_INTERVENTO  t,
                    CS_TB_MACRO_INTERVENTO  Z    --SS_SCHEDA_INTERVENTI S_INT,
              WHERE     D.TIPO_DIARIO_ID = '22'
                    AND S.ID = D.SCHEDA_ID
                    AND C.ID = D.CLOB_ID
                    AND TO_CHAR (c.DATI_CLOB) LIKE '%selezionePDS":%'
                    AND REPLACE (
                            REPLACE (
                                REPLACE (
                                    REPLACE (
                                        REPLACE (
                                            SUBSTR (
                                                TO_CHAR (C.DATI_CLOB),
                                                  INSTR (
                                                      TO_CHAR (c.DATI_CLOB),
                                                      'selezionePDS":')
                                                + 15,
                                                3),
                                            'ul',
                                            ''),
                                        '"',
                                        ''),
                                    '}',
                                    ''),
                                'l',
                                ''),
                            ',',
                            '') =
                        t.id(+)
                    AND T.ID_PDSMACRO = Z.ID(+)) dett1
      WHERE     dett.id_scheda = dett1.PK_SCHEDA_ID(+)
            AND dett.zona_sociale = dett1.ZONA_SOC(+));


DROP VIEW CS_ROMA.V_TABULATO_ACCESSI;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_TABULATO_ACCESSI
(
    IDENTIFICATIVO,
    ZONA_SOCIALE,
    BELFIORE,
    COMUNE,
    UFFICIO,
    PUNTO_CONTATO,
    "DATA ACCESSO",
    ANNO_INSERIMENTO,
    MESE_INSERIMENTO,
    OPERATORE,
    INTERLOCUTORE,
    "COGNOME/NOME INTELOCUTORE",
    "MOTIVO DI ACCESSO",
    "DESCR MOTIVO DI ACCESSO",
    "MODALITA DI ACCESSO",
    "COGNOME/NOME UTENTE",
    CODICE_FISCALE,
    DATA_NASCITA,
    SESSO,
    STATO_CIVILE,
    CITTADINANZA,
    "VIA DI RESIDENZA",
    "COMUNE DI RESIDENZA",
    "TITOLO DI STUDIO",
    "CONDIZIONE LAVORATIVA",
    "TIPOLOGIA FAMILIARE",
    TIPO_INTERVENTO,
    ID_SCHEDA,
    ID_ORG,
    CODICE_ORG,
    CAT_SOCIALE_CODISTAT
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            S.IDENTIFICATIVO,
            (SELECT NOME FROM CS_O_ZONA_SOC)
                ZONA_SOCIALE,
            ORG.COD_ROUTING
                BELFIORE,
            ORG.NOME
                COMUNE,
            UFF.NOME
                UFFICIO,
            PC.NOME
                PUNTO_CONTATO,
            AC.DATA
                "DATA ACCESSO",
            EXTRACT (YEAR FROM AC.DATA)
                ANNO_INSERIMENTO,
            EXTRACT (MONTH FROM AC.DATA)
                MESE_INSERIMENTO,
            ANAG.COGNOME || ' ' || ANAG.NOME
                OPERATORE,
            AC.INTERLOCUTORE,
            SEGNAL.COGNOME || ' ' || SEGNAL.NOME
                "COGNME/NOME INTELOCUTORE",
            AC.MOTIVO
                "MOTIVO DI ACCESSO",
            AC.MOTIVO_DESC
                "DESCR MOTIVO DI ACCESSO",
            AC.MODALITA
                "MODALITA DI ACCESSO",
            ANA.COGNOME || +' ' || +ANA.NOME
                "COGNOME/NOME UTENTE",
            ANA.CF
                CODICE_FISCALE,
            ANA.DATA_NASCITA,
            ANA.SESSO,
            ANA.STATO_CIVILE,
            ANA.CITTADINANZA,
            IND.VIA
                "VIA DI RESIDENZA",
            IND.COMUNE_DES
                "COMUNE DI RESIDENZA",
            TIT.DESCRIZIONE
                "TITOLO DI STUDIO",
            CLAV.DESCRIZIONE
                "CONDIZIONE LAVORATIVA",
            TIPF.DESCRIZIONE
                "TIPOLOGIA FAMILIARE",
            TIP.TIPO
                TIPO_INTERVENTO,
            S.ID
                ID_SCHEDA,
            ORG.ID
                ID_ORG,
            ORG.CF
                CODICE_ORG,
            CSOC.CATEGORIA_SOCIALE_ID
                CAT_SOCIALE_CODISTAT
       FROM ss_scheda                  s,
            ss_scheda_segnalato        seg,
            ss_anagrafica              ana,
            SS_SCHEDA_INTERVENTI       S_INT,
            SS_INTERVENTI_SCHEDE       INT_S,
            SS_INTERVENTO              SER,
            SS_TIPO_SCHEDA             TIP,
            CS_O_ORGANIZZAZIONE        ORG,
            SS_UFFICIO                 UFF,
            SS_PUNTO_CONTATTO          PC,
            SS_SCHEDA_ACCESSO          AC,
            SS_SCHEDA_SEGNALANTE       SEGNAL,
            SS_INDIRIZZO               IND,
            CS_TB_TITOLO_STUDIO        TIT,
            CS_TB_COND_LAVORO          CLAV,
            CS_TB_TIPOLOGIA_FAMILIARE  TIP_FAM,
            CS_SS_SCHEDA_SEGR          SEGR,
            CS_D_DIARIO                DIA,
            CS_D_CLOB                  CLO,
            CS_TB_TIPOLOGIA_FAMILIARE  TIPF,
            SS_OPERATORE_ANAGRAFICA    ANAG,
            SS_REL_SCHEDA_CAT_SOC      CSOC
      WHERE     S.SEGNALATO = SEG.ID
            AND SEG.ANAGRAFICA = ANA.ID
            AND S.ID = CSOC.SCHEDA_ID(+)
            AND S.INTERVENTI = S_INT.ID(+)
            AND S_INT.ID = INT_S.SCHEDA(+)
            AND INT_S.INTERVENTO = SER.ID(+)
            AND S.TIPO = TIP.ID
            AND S.ACCESSO = AC.ID
            AND AC.REL_UPO_ORGANIZZAZIONE_ID = ORG.ID
            AND AC.REL_UPO_PUNTO_CONTATTO_ID = PC.ID
            AND AC.REL_UPO_UFFICIO_ID = UFF.ID
            AND S.SEGNALANTE = SEGNAL.ID(+)
            AND SEG.RESIDENZA = IND.ID(+)
            AND SEG.TITOLO_STUDIO_ID = TIT.ID(+)
            AND SEG.LAVORO = CLAV.ID(+)
            AND SEG.TIPOLOGIA_FAMILIARE = TIP_FAM.ID(+)
            AND S.ID = SEGR.ID(+)
            AND S.ID = DIA.SCHEDA_ID
            AND DIA.CLOB_ID = CLO.ID(+)
            AND TO_CHAR (CLO.DATI_CLOB) LIKE '%tipologiaFamiliare":%'
            AND REPLACE (
                    REPLACE (
                        SUBSTR (
                            TO_CHAR (CLO.DATI_CLOB),
                              INSTR (TO_CHAR (CLO.DATI_CLOB),
                                     'tipologiaFamiliare":')
                            + 20,
                            2),
                        ',',
                        ''),
                    '}',
                    '') =
                TIPF.ID(+)
            AND s.completa = 1
            AND s.eliminata = 0
            AND ANAG.OPERATORE(+) = AC.OPERATORE);


DROP VIEW CS_ROMA.V_TIPI_INTERVENTO_USATI;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_TIPI_INTERVENTO_USATI
(
    ID,
    SCTI_TIPO_INTERVENTO_ID,
    CODICE_MEMO,
    DESCRIZIONE,
    TIPO_INTERVENTO_CUSTOM_ID,
    DESCRIZIONE_CUSTOM,
    CATEGORIA_SOCIALE_ID,
    CATEGORIA_SOCIALE_DESCRIZIONE,
    N_OCCORRENZE
)
BEQUEATH DEFINER
AS
    SELECT ROWNUM,
           lst."SCTI_TIPO_INTERVENTO_ID",
           lst."CODICE_MEMO",
           lst."DESCRIZIONE",
           lst."TIPO_INTERVENTO_CUSTOM_ID",
           lst."DESCRIZIONE_CUSTOM",
           lst."CATEGORIA_SOCIALE_ID",
           lst."CATEGORIA_SOCIALE_DESCRIZIONE",
           lst."N_OCCORRENZE"
      FROM (  SELECT SCTI_TIPO_INTERVENTO_ID,
                     CODICE_MEMO,
                     DESCRIZIONE,
                     TIPO_INTERVENTO_CUSTOM_ID,
                     DESCRIZIONE_CUSTOM,
                     categoria_sociale_id,
                     categoria_sociale_descrizione,
                     SUM (CONTA)     N_OCCORRENZE
                FROM (  SELECT SCTI_TIPO_INTERVENTO_ID,
                               TI.CODICE_MEMO,
                               TI.DESCRIZIONE,
                               TIPO_INTERVENTO_CUSTOM_ID,
                               C.DESCRIZIONE      DESCRIZIONE_CUSTOM,
                               COUNT (*)          CONTA,
                               cs.id              categoria_sociale_id,
                               cs.descrizione     categoria_sociale_descrizione
                          FROM CS_I_INTERVENTO I
                               LEFT JOIN CS_C_TIPO_INTERVENTO TI
                                   ON I.SCTI_TIPO_INTERVENTO_ID = TI.ID
                               LEFT JOIN CS_C_TIPO_INTERVENTO_CUSTOM C
                                   ON I.TIPO_INTERVENTO_CUSTOM_ID = C.ID
                               LEFT JOIN cs_c_categoria_sociale cs
                                   ON i.scti_categoria_sociale_id = CS.ID
                      GROUP BY 'I',
                               SCTI_TIPO_INTERVENTO_ID,
                               ti.CODICE_MEMO,
                               TI.DESCRIZIONE,
                               TIPO_INTERVENTO_CUSTOM_ID,
                               C.DESCRIZIONE,
                               cs.id,
                               cs.descrizione
                      UNION ALL
                      SELECT E.*,
                             V.CATEGORIA_SOCIALE_ID    categoria_sociale_id,
                             V.CAT_SOC                 categoria_sociale_descrizione
                        FROM (  SELECT I.TIPO_INTERVENTO_ID,
                                       TI.CODICE_MEMO,
                                       TI.DESCRIZIONE,
                                       TIPO_INTERVENTO_CUSTOM_ID,
                                       C.DESCRIZIONE     DESCRIZIONE_CUSTOM,
                                       COUNT (*)         CONTA
                                  FROM CS_I_INTERVENTO_ESEG_MAST I
                                       LEFT JOIN CS_C_TIPO_INTERVENTO TI
                                           ON I.TIPO_INTERVENTO_ID = TI.ID
                                       LEFT JOIN CS_C_TIPO_INTERVENTO_CUSTOM C
                                           ON I.TIPO_INTERVENTO_CUSTOM_ID = C.ID
                                 WHERE TIPO_INTERVENTO_CUSTOM_ID IS NOT NULL
                              GROUP BY 'E',
                                       I.TIPO_INTERVENTO_ID,
                                       TI.CODICE_MEMO,
                                       TI.DESCRIZIONE,
                                       TIPO_INTERVENTO_CUSTOM_ID,
                                       C.DESCRIZIONE) E
                             LEFT JOIN V_CATSOC_TIPOINTER V
                                 ON E.TIPO_INTERVENTO_ID = V.TIPO_INTERVENTO_ID
                      UNION ALL
                      SELECT E.*,
                             V.CATEGORIA_SOCIALE_ID    categoria_sociale_id,
                             V.CAT_SOC                 categoria_sociale_descrizione
                        FROM (  SELECT I.TIPO_INTERVENTO_ID,
                                       TI.CODICE_MEMO,
                                       TI.DESCRIZIONE,
                                       TIPO_INTERVENTO_CUSTOM_ID,
                                       C.DESCRIZIONE     DESCRIZIONE_CUSTOM,
                                       COUNT (*)         CONTA
                                  FROM CS_I_INTERVENTO_ESEG_MAST I
                                       LEFT JOIN CS_C_TIPO_INTERVENTO TI
                                           ON I.TIPO_INTERVENTO_ID = TI.ID
                                       LEFT JOIN CS_C_TIPO_INTERVENTO_CUSTOM C
                                           ON I.TIPO_INTERVENTO_CUSTOM_ID = C.ID
                                       LEFT JOIN V_CATSOC_TIPOINTER V
                                           ON I.TIPO_INTERVENTO_ID =
                                              V.TIPO_INTERVENTO_ID
                                 WHERE TIPO_INTERVENTO_CUSTOM_ID IS NULL
                              GROUP BY 'E',
                                       I.TIPO_INTERVENTO_ID,
                                       TI.CODICE_MEMO,
                                       TI.DESCRIZIONE,
                                       TIPO_INTERVENTO_CUSTOM_ID,
                                       C.DESCRIZIONE) E
                             LEFT JOIN V_CATSOC_TIPOINTER V
                                 ON E.TIPO_INTERVENTO_ID = V.TIPO_INTERVENTO_ID)
                     S
            GROUP BY SCTI_TIPO_INTERVENTO_ID,
                     CODICE_MEMO,
                     DESCRIZIONE,
                     TIPO_INTERVENTO_CUSTOM_ID,
                     DESCRIZIONE_CUSTOM,
                     categoria_sociale_id,
                     categoria_sociale_descrizione) lst;


