           (SELECT nome FROM cs_o_zona_soc)
               Z_ZONA_SOCIALE,
           O.COD_ROUTING
               O_ORG_BELFIORE,
           O.NOME
               O_ORG_NOME,
           SE.NOME
               O_SETTORE_NOME,
           C.DT_INS
               C_DATAINS_CASO,
           a.cognome
               C_COGNOME,
           a.nome
               C_NOME,
           a.data_nascita
               C_DATA_NASCITA,
           --          TRUNC (
           --               MONTHS_BETWEEN (SYSDATE, TO_DATE (a.data_nascita, 'DD-MM-YYYY'))
           --             / 12)
           --             C_ETA,
           TRUNC (MONTHS_BETWEEN (SYSDATE, a.data_nascita) / 12)
               C_ETA,
           a.cf
               C_CF,
           a.data_decesso
               C_DATA_DECESSO,
           a.sesso
               C_SESSO,
           a.cittadinanza
               C_CITTADINANZA,
           A.CITTADINANZA_2
               c_cittadinanza_2,
           ind.DATA_INIZIO_APP
               C_IND_RES_DT_INIZIO,
           ANAIND.CODICE_VIA
               C_IND_RES_CODICE_VIA,
           ANAIND.COM_COD
               C_IND_COM_RES_COD_ISTAT,
           ANAIND.COM_DES
               C_IND_RES_COM_DES,
           ANAIND.INDIRIZZO
               C_IND_RES_INDIRIZZO,
           ANAIND.CIVICO_NUMERO
               C_IND_RES_CIVICO_NUMERO,
           ANAIND.PROV
               C_IND_RES_PROV,
           ANAIND.STATO_COD
               C_IND_RES_STATO_COD,
           ANAIND.STATO_DES
               C_IND_RES_STATO_DES,
           DIAFAM.DESCRIZIONE
               CDS_TIPOLOGIA_FAMILIARE,
           PNUCLEO.DESCRIZIONE
               CDS_PROBLEMATICA_NUCLEO,
           DS.DATA_INIZIO_APP
               CDS_DATA_AGG_DATI_SOCIALI,
           TBPS.DESCRIZIONE
               CDS_PROBLEMATICA_SOGGETTO,
           TBTS.DESCRIZIONE
               CDS_TITOLO_STUDIO,
           TBCL.DESCRIZIONE
               CDS_CONDIZIONE_LAVORATIVA,
           DS.STRANIERO_N_ACC
               CDS_MINORE_STRAN_NON_ACC,
           DS.N_MINORI
               CDS_NUMERO_MINORI_NEL_NUCLEO,
           NULL
               CDS_STATUS_GIURIDICO,
           NULL
               CDS_TIPOLOGIA_ABITAZIONE,
           NULL
               CDS_TITOLO_GODIMENTO,
           NULL
               CR_DATA_AGG_RISORSE,
           NULL
               CR_PARENTI_DISPONIBILI,
           DI.DATA_INIZIO_APP
               CDI_DATA_AGG_INVALIDITA,
           DI.INVALIDITA_CIVILE
               CDI_INVALIDITA_CIVILE,
           DI.PERC_INVALIDITA
               CDI_PERC_INVALIDITA,
           DI.ACCOMPAGNAMENTO
               CDI_ACCOMPAGNAMENTO,
           DI.LEGGE104
               CDI_LEGGE104,
           DI.DATA_INVALIDITA
               CDI_DATA_INVALIDITA,
           DI.DATA_SCADENZA_INVALIDITA
               CDI_DATA_SCADENZA_INVALIDITA,
           DI.CERTIFICAZIONE_H
               CDI_CERTIFICAZIONE_H,
           DI.DATA_CERTIFICAZIONE
               CDI_DATA_CERTIFICAZIONE_H,
           DI.DATA_SCADENZA_CERTIFICAZIONE
               CDI_DATA_SCAD_CERTIFICAZIONE,
           DIS.DATA_INIZIO_APP
               CDIS_DATA_AGG_DISABILITA,
           TBDIS.DESCRIZIONE
               CDIS_GRAVITA_DISABILITA,
           TBDISTIPO.DESCRIZIONE
               CDIS_TIPOLOGIA_DISABILITA,
           IT_STATO.NOME
               IT_ULTIMO_STATO_CASO,
           ITD.DT_AMMINISTRATIVA
               IT_ULTIMO_STATO_ITER_DATA,
           O.ID
               ID_ORG,
           O.CF
               CODICE_ORG
      FROM CS_A_SOGGETTO        S
           LEFT JOIN cs_a_dati_sociali ds
               ON (    S.ANAGRAFICA_ID = DS.SOGGETTO_ANAGRAFICA_ID
                   AND DS.DATA_FINE_APP =
                       TO_DATE ('31-12-9999', 'dd-mm-yyyy'))
           LEFT JOIN
           (SELECT diafam.ID, TO_CHAR (clobfam.dati_clob), tbtf.descrizione
              FROM cs_d_diario                diafam,
                   cs_d_clob                  clobfam,
                   cs_tb_TIPOLOGIA_FAMILIARE  tbtf
             WHERE     DIAfam.CLOB_ID = clobfam.ID
                   AND diafam.tipo_diario_id = 14
                   AND TO_CHAR (clobfam.DATI_CLOB) LIKE
                           '%tipologiaFamiliare":%'
                   AND REPLACE (
                           REPLACE (
                               SUBSTR (
                                   TO_CHAR (clobfam.DATI_CLOB),
                                     INSTR (TO_CHAR (clobfam.DATI_CLOB),
                                            'tipologiaFamiliare":')
                                   + 20,
                                   2),
                               ',',
                               ''),
                           '}',
                           '') =
                       tbtf.ID(+)) diafam
               ON DS.DIARIO_FAM_CONV_ID = diafam.ID
           LEFT JOIN CS_TB_MOTIVO_SEGNAL PNUCLEO
               ON DS.PROBLEMA_NUCLEO_ID = PNUCLEO.ID
           LEFT JOIN CS_TB_PROBLEMATICA TBPS ON DS.PROBLEMATICA_ID = TBPS.ID
           LEFT JOIN CS_TB_TITOLO_STUDIO TBTS
               ON DS.TITOLO_STUDIO_ID = TBTS.ID
           LEFT JOIN CS_TB_COND_LAVORO TBCL
               ON DS.COND_LAVORATIVA_ID = TBCL.ID
           LEFT JOIN cs_a_dati_INVALIDITA DI
               ON (    S.ANAGRAFICA_ID = DI.SOGGETTO_ANAGRAFICA_ID
                   AND DI.DATA_FINE_APP =
                       TO_DATE ('31-12-9999', 'dd-mm-yyyy'))
           LEFT JOIN CS_A_DISABILITA DIS
               ON (    S.ANAGRAFICA_ID = DIS.SOGGETTO_ANAGRAFICA_ID
                   AND DIS.DATA_FINE_APP =
                       TO_DATE ('31-12-9999', 'dd-mm-yyyy'))
           LEFT JOIN CS_TB_DISAB_GRAVITA TBDIS ON DIS.GRAVITA_ID = TBDIS.ID
           LEFT JOIN CS_TB_DISAB_TIPOLOGIA TBDISTIPO
               ON DIS.TIPOLOGIA_ID = TBDISTIPO.ID
           LEFT JOIN CS_A_INDIRIZZO IND
               ON (    S.ANAGRAFICA_ID = IND.SOGGETTO_ANAGRAFICA_ID
                   AND IND.TIPO_INDIRIZZO_ID = '1'
                   AND ind.data_fine_app IS NULL)
           LEFT JOIN CS_A_ANA_INDIRIZZO ANAIND
               ON IND.ANA_INDIRIZZO_ID = ANAIND.ID,
           CS_A_ANAGRAFICA      a,
           CS_A_CASO            c,
           CS_IT_STEP           it
           LEFT JOIN CS_CFG_IT_STATO IT_STATO
               ON IT.CFG_IT_STATO_ID = IT_STATO.ID,
           CS_D_DIARIO          ITD,
           CS_O_ORGANIZZAZIONE  O,
           cs_O_SETTORE         SE
     WHERE     S.CASO_ID = C.ID
           AND S.ANAGRAFICA_ID = A.ID
           AND IT.ID = (SELECT MAX (it2.id)
                          FROM CS_IT_STEP it2
                         WHERE IT2.CASO_ID = S.CASO_ID)
           AND ITD.ID = IT.DIARIO_ID
           AND IT.ORGANIZZAZIONE_ID = O.ID
           AND IT.SETTORE_ID = SE.ID;


DROP VIEW CS_ROMA.V_T1_CASO_OPE_TIPO_OPE;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_T1_CASO_OPE_TIPO_OPE
(
    PK_T1_CASO_ID_FK,
    PK_T1_CF_OPERATORE,
    PK_T1_TIPO_OPERATORE,
    Z_ZONA_SOCIALE,
    O_FLAG_RESPONSABILE,
    O_DATA_INI_PIC,
    O_DATA_FINE_PIC,
    O_TIPO_OPE_DT_INIZIO,
    O_TIPO_OPE_DT_FINE,
    O_OPE_SETT_DT_INIZIO,
    O_OPE_SETT_DT_FINE,
    O_COGNOME_OPERATORE,
    O_NOME_OPERATORE,
    O_NOME_SETTORE,
    O_NOME_ORG,
    O_BELFIORE_ORG
)
BEQUEATH DEFINER
AS
    SELECT c.id                                 pk_T1_caso_id_FK,
           oana.codice_fiscale                  PK_T1_CF_OPERATORE,
           TIO.DESCRIZIONE                      PK_T1_TIPO_OPERATORE,
           (SELECT nome FROM cs_o_zona_soc)     Z_ZONA_SOCIALE,
           flag_responsabile                    O_FLAG_RESPONSABILE,
           OPE.data_inizio_app                  O_DATA_INI_PIC,
           OPE.data_fine_app                    O_DATA_FINE_PIC,
           OTI.DATA_INIZIO_APP                  O_TIPO_OPE_DT_INIZIO,
           OTI.DATA_FINE_APP                    O_TIPO_OPE_DT_FINE,
           OS.DATA_INIZIO_APP                   O_OPE_SETT_DT_INIZIO,
           OS.DATA_FINE_APP                     O_OPE_SETT_DT_FINE,
           oana.cognome                         O_COGNOME_OPERATORE,
           oana.nome                            O_NOME_OPERATORE,
           s.nome                               o_nome_settore,
           o.nome                               o_nome_org,
           o.cod_routing                        o_belfiore_org
      FROM CS_A_CASO  C
           LEFT JOIN cs_a_caso_ope_tipo_ope ope ON C.ID = OPE.CASO_ID
           LEFT JOIN cs_o_operatore_tipo_operatore oti
               ON ope.operatore_tipo_operatore_id = oti.id
           LEFT JOIN cs_o_operatore_settore os
               ON oti.operatore_settore_id = os.id
           LEFT JOIN CS_O_OPERATORE_ANAGRAFICA oana
               ON os.operatore_id = oana.id
           LEFT JOIN cs_o_settore s ON os.settore_id = s.id
           LEFT JOIN cs_o_organizzazione o ON s.organizzazione_id = o.id
           LEFT JOIN CS_TB_TIPO_OPERATORE TIO
               ON OTI.TIPO_OPERATORE_ID = TIO.ID;


DROP VIEW CS_ROMA.V_T2_CASI_CATEGORIE_SOC;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_T2_CASI_CATEGORIE_SOC
(
    PK_T2_CAT_SOCIALE_CODISTAT,
    PK_T2_CASO_ID_FK,
    Z_ZONA_SOCIALE,
    CS_PREVALENTE,
    CS_CATSOC_DESCRIZIONE,
    CS_DATA_INIZIO_CATEGORIA,
    CS_DATA_FINE_CATEGORIA
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT
           CS.CODICE_MEMO                       PK_T2_CAT_SOCIALE_CODISTAT,
           c.id                                 PK_T2_CASO_ID_FK,
           (SELECT nome FROM cs_o_zona_soc)     Z_ZONA_SOCIALE,
           prevalente                           CS_PREVALENTE,
           cs.DESCRIZIONE                       CS_CATSOC_DESCRIZIONE,
           SC.DATA_INIZIO_APP                   CS_DATA_INIZIO_CATEGORIA,
           SC.DATA_FINE_APP                     CS_DATA_FINE_CATEGORIA
      FROM CS_A_CASO  c
           LEFT JOIN CS_A_SOGGETTO S ON S.CASO_ID = C.ID
           LEFT JOIN CS_A_SOGGETTO_CATEGORIA_SOC sc
               ON     SC.SOGGETTO_ANAGRAFICA_ID = S.ANAGRAFICA_ID
                  AND SC.DATA_FINE_APP >= SYSDATE
           LEFT JOIN CS_C_CATEGORIA_SOCIALE CS
               ON SC.CATEGORIA_SOCIALE_ID = CS.ID;


