/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_T3_FLG_INTERVENTI_CASI
(
    PK_T3_I_ID,
    Z_ZONA_SOCIALE,
    C_CASO_ID_FK,
    FLG_FLAG_ATT_SOSP_C,
    FLG_RESPINTO,
    FLG_DT_AMMINISTRATIVA,
    FLG_DT_ATTIVAZIONE_DA,
    FLG_DT_ATTIVAZIONE_A,
    FLG_DT_SOSPENSIONE_DA,
    FLG_DT_SOSPENSIONE_A,
    FLG_DT_CHIUSURA_DA,
    FLG_DT_CHIUSURA_A,
    FLG_DT_INS,
    FLG_DT_MOD,
    I_FLAG_PRIMAER_RINNOVO,
    I_FLAG_UNATANTUM,
    I_FINE_DAL,
    I_FINE_AL,
    I_SETTORE2,
    I_BELFIORE_ORG,
    I_NOME_ORG,
    I_CS_CODICE_MEMO,
    I_CS_DESCRIZIONE,
    I_TI_COD_ISTAT,
    I_TI_DESC_ISTAT,
    I_TI_SUB_COD_ISTAT,
    I_TIC_CODICE_MEMO,
    I_TIC_DESCRIZIONE
)
BEQUEATH DEFINER
AS
    SELECT SEL.I_ID                             PK_T3_I_ID,
           (SELECT nome FROM cs_o_zona_soc)     Z_ZONA_SOCIALE,
           D.CASO_ID                            C_CASO_ID_FK,
           FLG.FLAG_ATT_SOSP_C                  FLG_FLAG_ATT_SOSP_C,
           FLG.FLAG_RESPINTO                    FLG_RESPINTO,
           D.DT_AMMINISTRATIVA                  FLG_DT_AMMINISTRATIVA,
           DT_ATTIVAZIONE_DA                    FLG_DT_ATTIVAZIONE_DA,
           DT_ATTIVAZIONE_A                     FLG_DT_ATTIVAZIONE_A,
           DT_SOSPENSIONE_DA                    FLG_DT_SOSPENSIONE_DA,
           DT_SOSPENSIONE_A                     FLG_DT_SOSPENSIONE_A,
           DT_CHIUSURA_DA                       FLG_DT_CHIUSURA_DA,
           DT_CHIUSURA_A                        FLG_DT_CHIUSURA_A,
           D.DT_INS                             FLG_DT_INS,
           D.DT_MOD                             FLG_DT_MOD,
           SEL.I_FLAG_PRIMAER_RINNOVO,
           SEL.I_FLAG_UNATANTUM,
           SEL.I_FINE_DAL,
           SEL.I_FINE_AL,
           SEL.I_SETTORE2,
           SEL.I_belfiore_org,
           sel.i_nome_org,
           CS_CODICE_MEMO                       I_CS_CODICE_MEMO,
           CS_DESCRIZIONE                       I_CS_DESCRIZIONE,
           SEL.TI_cod_istat                     I_TI_cod_istat,
           SEL.TI_DESC_istat                    I_TI_DESC_istat,
           SEL.TI_SUB_cod_istat                 I_TI_SUB_cod_istat,
           SEL.TIC_CODICE_MEMO                  I_TIC_CODICE_MEMO,
           sel.TIC_DESCRIZIONE                  I_TIC_DESCRIZIONE
      FROM cs_flg_intervento  FLG
           INNER JOIN CS_D_DIARIO D ON FLG.DIARIO_ID = D.ID
           INNER JOIN cs_a_caso c ON D.CASO_ID = C.ID
           LEFT JOIN
           (SELECT I.ID                       I_ID,
                   I.flag_primaer_rinnovo     I_flag_primaer_rinnovo,
                   I.FLAG_UNATANTUM           I_FLAG_UNATANTUM,
                   I.FINE_DAL                 I_FINE_DAL,
                   I.FINE_AL                  I_FINE_AL,
                   s.nome                     I_settore2,
                   o.COD_ROUTING              i_belfiore_org,
                   o.nome                     i_nome_org,
                   ti.id                      ti_id,
                   TI.CODICE_MEMO             TI_cod_istat,
                   TI.SUB_CODICE_MEMO         TI_SUB_cod_istat,
                   ti.descrizione             TI_DESC_istat,
                   tic.id                     TIC_id,
                   tic.descrizione            TIC_DESCRIZIONE,
                   TIC.CODICE_MEMO            TIC_CODICE_MEMO,
                   CS.ID                      CS_ID,
                   CS.CODICE_MEMO             CS_CODICE_MEMO,
                   CS.DESCRIZIONE             CS_DESCRIZIONE
              FROM cs_i_intervento              i,
                   cs_c_categoria_sociale       cs,
                   cs_o_settore                 s,
                   CS_O_ORGANIZZAZIONE          O,
                   cs_c_tipo_intervento         ti,
                   cs_c_tipo_intervento_custom  tic
             WHERE     i.scti_settore_id = s.id
                   AND scti_tipo_intervento_id = ti.id
                   AND tipo_intervento_custom_id = tic.id(+)
                   AND S.ORGANIZZAZIONE_ID = O.ID
                   AND I.SCTI_CATEGORIA_SOCIALE_ID = CS.ID(+)) SEL
               ON FLG.INTERVENTO_ID = SEL.I_ID
     WHERE flg.DIARIO_ID = (SELECT MAX (DIARIO_ID)
                              FROM CS_FLG_INTERVENTO II
                             WHERE II.INTERVENTO_ID = FLG.INTERVENTO_ID);


