                INDIRIZZO_DOMICILIO,
            C.COMUNE_DOMICILIO,
            SIR.COMUNE_DOM_ID,
            C.TELEFONO,
            C.CELLULARE,
            C.EMAIL,
            SIR.COND_MERCATO_INGRESSO,
            C.FLAG_ALTRO_CORSO
                FLAG_FREQUENZA_ALTRO_CORSO,
            SIR.DURATA_RICERCA
                DURATA_RICERCA_LAVORO_COD,
            RICLAV.DESCRIZIONE
                DURATA_RICERCA_LAVORO,
            SIR.TIPOLOGIA_LAVORO_ID
                TIPOLOGIA_LAVORO_ID,
            C.DESC_TIPO_LAVORO
                TIPOLOGIA_LAVORO_DESC,
            SIR.TIPO_ORARIO_LAVORO_ID
                TIPO_ORARIO_LAVORO_ID,
            C.DESC_ORARIO_LAVORO
                TIPO_ORARIO_LAVORO_DESC,
            C.AZ_RAGIONE_SOCIALE
                RAGIONE_SOCIALE_AZIENDA,
            C.AZ_PI
                PARTITA_IVA_AZIENDA,
            C.AZ_CF
                CODICE_FISCALE_AZIENDA,
            C.AZ_VIA
                INDIRIZZO_AZIENDA,
            C.AZ_COMUNE_COD
                COMUNE_AZIENDA_ID,
            C.AZ_COMUNE_DES
                COMUNE_AZIENDA_DESC,
            C.AZ_PROV,
            C.AZ_COD_ATECO,
            SIR.COD_ATECO_ANNO
                ATECO_AZIENDA_COD_ATECO_ANNO,
            C.AZ_FORMA_GIURIDICA
                AZ_FORMA_GIURIDICA_COD,
            SIR.FRM_GIURIDICA_COD
                AZ_FORMA_GIURIDICA_RNA_COD,
            az_fg.descrizione
                AZ_FORMA_GIURIDICA,
            SIR.DIMENSIONE_AZIENDA_ID
                DIMENSIONE_AZIENDA_ID,
            C.DESC_DIM_AZIENDA
                AZ_DIMENSIONE_DESC,
            SIR.TITOLO_STUDIO
                TITOLO_STUDIO_COD,
            DECODE (C.ANNO_CONSEGUIMENTO_TITOLO_STU,
                    '0', NULL,
                    C.ANNO_CONSEGUIMENTO_TITOLO_STU)
                ANNO_CONSEGUIMENTO_TITOLO_STU,
            SIR.COD_VULNERABILE_PA,
            gr.descrizione
                GRUPPO_VULNERABILE_DESC,
            C.IBAN,
            C.FLAG_RES_DOM,
            SIR.FLAG_RESIDENZA
                FLAG_COMUNICAZIONE_RESIDENZA,
            AZ_COMUNE.CAP
                CAP_AZIENDA
       FROM CS_I_INTERVENTO_PR_FSE  c
            LEFT JOIN CS_I_INTERVENTO_ESEG_MAST m
                ON (m.INT_PROGETTO_ID = c.INTERVENTO_PR_ID)
            LEFT JOIN CS_I_INTERVENTO_ESEG_MAST_SOGG s
                ON (m.ID = s.INT_ESEG_MAST_ID AND FLAG_RIFERIMENTO = 1)
            LEFT JOIN CS_TB_G_VULNERABILE gr ON (C.GR_VULNERABILE_ID = gr.id)
            LEFT JOIN CS_TB_FORMA_GIURIDICA az_fg
                ON (C.AZ_FORMA_GIURIDICA = az_fg.id)
            LEFT JOIN CS_TB_DURATA_RIC_LAVORO ricLav
                ON (ricLav.id = c.durata_ric_lavoro_id)
            LEFT JOIN CS_I_INTERVENTO_PR_FSE_SIRU sir
                ON (C.INTERVENTO_PR_ID = SIR.INTERVENTO_PR_ID)
            LEFT JOIN FSE_CHK_IT_COMUNE az_comune
                ON (C.AZ_COMUNE_COD = AZ_COMUNE.id));


DROP VIEW CS_ROMA.V_T5_ITER;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_T5_ITER
(
    PK_T5_ITER_ID,
    Z_ZONA_SOCIALE,
    STATO,
    DATA_ITER,
    DATA_INS_ITER,
    OPERATORE_RESPONSABILE,
    CASO_ID,
    SETTORE,
    ORGANIZZAZIONE_BELFIORE,
    ORGANIZZAZIONE_NOME,
    SETTORE_NOME,
    OPERATORE,
    ORGANIZZAZIONE_TO_BELFIORE,
    ORGANIZZAZIONE_TO_NOME,
    SETTORE_TO,
    OPERATORE_TO
)
BEQUEATH DEFINER
AS
    SELECT it.id                                pk_t5_iter_id,
           (SELECT nome FROM cs_o_zona_soc)     Z_ZONA_SOCIALE,
           IT_STATO.NOME                        STATO,
           ITD.DT_AMMINISTRATIVA                DATA_ITER,
           ITD.DT_INS                           DATA_INS_ITER,
           OPERESP.USERNAME                     OPERATORE_RESPONSABILE,
           it.caso_id,
           SE.NOME                              SETTORE,
           O.COD_ROUTING                        organizzazione_BELFIORE,
           o.nome                               ORGANIZZAZIONE_NOME,
           SETT.NOME                            SETTORE_NOME,
           OPE.USERNAME                         operatore,
           ORG2.COD_ROUTING                     ORGANIZZAZIONE_TO_BELFIORE,
           ORG2.NOME                            ORGANIZZAZIONE_TO_NOME,
           SETT2.NOME                           SETTORE_TO,
           OPE2.USERNAME                        operatore_to
      FROM CS_A_CASO  C
           LEFT JOIN CS_D_DIARIO ITD ON ITD.CASO_ID = C.ID
           INNER JOIN CS_IT_STEP it ON ITD.ID = IT.DIARIO_ID
           LEFT JOIN CS_CFG_IT_STATO IT_STATO
               ON IT.CFG_IT_STATO_ID = IT_STATO.ID
           LEFT JOIN CS_O_ORGANIZZAZIONE O ON IT.ORGANIZZAZIONE_ID = O.ID
           LEFT JOIN cs_O_SETTORE SE ON IT.SETTORE_ID = SE.ID
           LEFT JOIN cs_o_operatore ope ON IT.OPERATORE_ID = ope.id
           LEFT JOIN cs_o_operatore ope2 ON IT.OPERATORE_to = ope2.id
           LEFT JOIN cs_o_settore sett ON IT.settore_id = sett.id
           LEFT JOIN cs_o_settore sett2 ON IT.settore_ID_TO = sett2.id
           LEFT JOIN cs_o_ORGANIZZAZIONE ORG2
               ON IT.ORGANIZZAZIONE_ID_TO = ORG2.id
           LEFT JOIN cs_o_operatore operesp
               ON ITd.responsabile_id = operesp.id;


DROP VIEW CS_ROMA.V_T6_PAI;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_T6_PAI
(
    Z_ZONA_SOCIALE,
    PAI_ID,
    PAI_CASO_ID,
    TIPO_PAI_ID,
    FF_PROGETTO_DESCRIZIONE,
    FF_PROGETTO_CODICE,
    DATA_ATTIVAZIONE_PAI,
    DATA_CHIUSURA_PREVISTA,
    DATA_CHIUSURA,
    MOTIVO_CHIUSURA,
    OBIETTIVI_RAGGIUNTI_BREVE,
    OBIETTIVI_RAGGIUNTI_MEDIO,
    OBIETTIVI_RAGGIUNTI_LUNGO,
    PAI_SETTORE_NOME,
    PAI_ORGANIZZAZIONE_NOME,
    PAI_OPERATORE,
    PAI_DATA_AGG,
    C_COGNOME,
    C_NOME,
    C_CF,
    C_DATA_NASCITA,
    C_SESSO,
    C_DATA_DECESSO,
    IT_ULTIMO_STATO_CASO,
    IT_ULTIMO_STATO_ITER_DATA,
    ATTUALE_ORG_CARICO_BELFIORE,
    ATTUALE_ORG_CARICO_NOME,
    ATTUALE_SETTORE_CARICO_NOME,
    TIPO_PAI_DESCRIZIONE,
    CITTADINANZA
)
BEQUEATH DEFINER
AS
    SELECT PAI."Z_ZONA_SOCIALE",
           PAI."PAI_ID",
           PAI."PAI_CASO_ID",
           PAI."TIPO_PAI_ID",
           PAI."FF_PROGETTO_DESCRIZIONE",
           PAI."FF_PROGETTO_CODICE",
           PAI."DATA_ATTIVAZIONE_PAI",
           PAI."DATA_CHIUSURA_PREVISTA",
           PAI."DATA_CHIUSURA",
           PAI."MOTIVO_CHIUSURA",
           PAI."OBIETTIVI_RAGGIUNTI_BREVE",
           PAI."OBIETTIVI_RAGGIUNTI_MEDIO",
           PAI."OBIETTIVI_RAGGIUNTI_LUNGO",
           PAI."PAI_SETTORE_NOME",
           PAI."PAI_ORGANIZZAZIONE_NOME",
           PAI."PAI_OPERATORE",
           PAI."PAI_DATA_AGG",
           CASI.C_COGNOME,
           CASI.C_NOME,
           CASI.C_CF,
           CASI.C_DATA_NASCITA,
           CASI.C_SESSO,
           CASI.C_DATA_DECESSO,
           CASI.IT_ULTIMO_STATO_CASO,
           CASI.IT_ULTIMO_STATO_ITER_DATA,
           CASI.O_ORG_BELFIORE     ATTUALE_ORG_CARICO_BELFIORE,
           CASI.O_ORG_NOME         ATTUALE_ORG_CARICO_NOME,
           CASI.O_SETTORE_NOME     ATTUALE_SETTORE_CARICO_NOME,
           TPAI.DESCRIZIONE        TIPO_PAI_DESCRIZIONE,
           PAI.CITTADINANZA        CITTADINANZA
      FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)
                       Z_ZONA_SOCIALE,
                   D.ID
                       PAI_ID,
                   D.CASO_ID
                       PAI_CASO_ID,
                   PAI.TIPO_PAI_ID
                       TIPO_PAI_ID,
                   pr.descrizione
                       FF_PROGETTO_DESCRIZIONE,
                   PR.CODICE_MEMO
                       FF_PROGETTO_CODICE,
                   D.DT_ATTIVAZIONE_DA
                       DATA_ATTIVAZIONE_PAI,
                   PAI.DATA_CHIUSURA_PREVISTA,
                   D.DT_CHIUSURA_DA
                       DATA_CHIUSURA,
                   PAI.MOTIVO_CHIUSURA,
                   SOGG.CITTADINANZA,
                   CASE
                       WHEN PAI.RAGGIUNTI_BREVE = 3 THEN 'SI'
                       WHEN PAI.RAGGIUNTI_BREVE = 2 THEN 'PARZIALMENTE'
                       WHEN PAI.RAGGIUNTI_BREVE = 1 THEN 'NO'
                   END
                       OBIETTIVI_RAGGIUNTI_BREVE,
                   CASE
                       WHEN PAI.RAGGIUNTI_MEDIO = 3 THEN 'SI'
                       WHEN PAI.RAGGIUNTI_MEDIO = 2 THEN 'PARZIALMENTE'
                       WHEN PAI.RAGGIUNTI_MEDIO = 1 THEN 'NO'
                   END
                       OBIETTIVI_RAGGIUNTI_MEDIO,
                   CASE
                       WHEN PAI.RAGGIUNTI_LUNGO = 3 THEN 'SI'
                       WHEN PAI.RAGGIUNTI_LUNGO = 2 THEN 'PARZIALMENTE'
                       WHEN PAI.RAGGIUNTI_LUNGO = 1 THEN 'NO'
                   END
                       OBIETTIVI_RAGGIUNTI_LUNGO,
                   SINS.NOME
                       PAI_SETTORE_NOME,
                   OINS.NOME
                       PAI_ORGANIZZAZIONE_NOME,
                   vopeana1.COGNOME || ' ' || vopeana1.NOME
                       PAI_OPERATORE,
                   NVL (D.DT_mod, d.dt_ins)
                       PAI_DATA_AGG
              FROM cs_d_diario                d,
                   AR_FF_PROGETTO             PR,
                   cs_o_operatore_settore     osins,
                   cs_o_settore               sins,
                   CS_O_ORGANIZZAZIONE        OINS,
                   cs_d_pai                   pai,
                   CS_PAI_MAST_SOGG           sogg,
                   cs_o_operatore_anagrafica  vopeana1
             WHERE     PAI.TIPO_PROGETTO_ID = pr.ID(+)
                   AND D.OPERATORE_SETTORE_ID = OSINS.ID(+)
                   AND OSINS.SETTORE_ID = SINS.ID(+)
                   AND SINS.ORGANIZZAZIONE_ID = OINS.ID(+)
                   AND OSINS.OPERATORE_ID = VOPEANA1.ID(+)
                   AND pai.diario_id = d.id
                   AND pai.DIARIO_ID = SOGG.DIARIO_ID(+)
                   AND NVL (SOGG.FLAG_INTESTATARIO, 0) = 1
                   AND D.TIPO_DIARIO_ID = 8) PAI
           LEFT JOIN V_T0_CASI CASI ON PK_T0_CASO_ID = PAI.PAI_CASO_ID
           LEFT JOIN cs_tb_tipo_pai tpai ON PAI.TIPO_PAI_ID = TPAI.ID;


