CREATE OR REPLACE FORCE VIEW CS_ROMA.V_T7_PAI_AFFIDO
(
    Z_ZONA_SOCIALE,
    PAI_ID,
    DATA_INIZIO_AFFIDO,
    DATA_TERMINE_AFFIDO,
    DATA_ANNULLAMENTO_AFFIDO,
    TIPOLOGIA_AFFIDO,
    AFFIDO_PROFESSIONALE,
    ADOTTABILE,
    NATURA_AFFIDO,
    ENTITA,
    FORME_AFFIDAMENTO,
    COLLOCAMENTO,
    PRESENZA_RETI_FAMIGLIE,
    IS_MINORE_ALLONTANATO,
    GENITORI_SCONOSCIUTI,
    FUORI_REGIONE,
    CONTATTI_CON_FO,
    AFFIDATARI,
    FA_CONOSCIUTA_DAL_MINORE,
    FA_FUORI_REGIONE,
    FA_BDF,
    AFFIDO_PROFESSIONALE_DESC,
    ADOTTABILE_DESC,
    PRESENZA_RETI_FAMIGLIE_DESC,
    IS_MINORE_ALLONTANATO_DESC,
    GENITORI_SCONOSCIUTI_DESC,
    FUORI_REGIONE_DESC,
    FA_CONOSCIUTA_DAL_MINORE_DESC,
    FA_FUORI_REGIONE_DESC,
    FA_BDN_DESC
)
BEQUEATH DEFINER
AS
    SELECT PAI."Z_ZONA_SOCIALE",
           PAI."PAI_ID",
           PAI."DATA_INIZIO_AFFIDO",
           PAI."DATA_TERMINE_AFFIDO",
           PAI."DATA_ANNULLAMENTO_AFFIDO",
           PAI."TIPOLOGIA_AFFIDO",
           PAI."AFFIDO_PROFESSIONALE",
           PAI."ADOTTABILE",
           PAI."NATURA_AFFIDO",
           PAI."ENTITA",
           -- PAI."SITUAZIONI_PARTICOLARI",
           PAI."FORME_AFFIDAMENTO",
           PAI."COLLOCAMENTO",
           PAI."PRESENZA_RETI_FAMIGLIE",
           -- PAI."DISABILITA_DURANTE_AFFIDO",
           -- PAI."STRANIERO_NON_ACCOMPAGNATO",
           -- PAI."STRANIERO_AFF_CULTURA",
           PAI."IS_MINORE_ALLONTANATO",
           PAI."GENITORI_SCONOSCIUTI",
           PAI."FUORI_REGIONE",
           PAI."CONTATTI_CON_FO",
           PAI."AFFIDATARI",
           PAI."FA_CONOSCIUTA_DAL_MINORE",
           PAI."FA_FUORI_REGIONE",
           PAI."FA_BDF",
           DECODE (AFFIDO_PROFESSIONALE,
                   0, 'Non professonale',
                   1, 'Affido professionale')
               AFFIDO_PROFESSIONALE_DESC,
           DECODE (ADOTTABILE,
                   0, 'Non adottabile',
                   1, 'Adottabile',
                   2, 'In attesa di decisione del tribunale')
               ADOTTABILE_DESC,
           DECODE (PRESENZA_RETI_FAMIGLIE,
                   1, 'Presenza di reti di famiglie',
                   0, 'Non presenti reti di famiglie')
               PRESENZA_RETI_FAMIGLIE_desc,
           --          DECODE (disabilita_durante_affido,
           --                  1, 'Disabile durante affido',
           --                  0, 'Non disabile durante affido')
           --             disabilita_durante_affido_desc,
           --          DECODE (STRANIERO_NON_ACCOMPAGNATO,
           --                  1, 'Minore straniero non accompagnato',
           --                  0, 'NO Minore Straniero non accompagnato')
           --            STRAN_NON_ACCOMPAGNATO_DESC,
           --          DECODE (
           ----             STRANIERO_AFF_CULTURA,
           ----             1, 'Minore straniero e affidatari appartenenti a stessa cultura/origine',
           ----             0, 'Minore e affidatari non appartenenti alla stessa cultura')
           --             STRANIERO_AFF_CULTURA_desc,
           DECODE (
               IS_MINORE_ALLONTANATO,
               1, 'Il minore ha è stato allontanamento dalla famiglia di origine da provvedimento giudice',
               0, 'Minore non allontanato da provvedimento giudice')
               IS_MINORE_ALLONTANATO_desc,
           DECODE (GENITORI_SCONOSCIUTI,
                   1, 'Famiglia di origine sconosciuta',
                   0, 'Famiglia di origine conosciuta')
               GENITORI_SCONOSCIUTI_desc,
           DECODE (FUORI_REGIONE,
                   1, 'Famiglia di origine residente fuori regione',
                   0, 'Famiglia di origine in regione')
               FUORI_REGIONE_desc,
           DECODE (
               FA_CONOSCIUTA_DAL_MINORE,
               1, 'Famiglia affidataria in precedenza conosciuta dal minore',
               0, 'Famiglia affidataria non conosciuta dal minore')
               FA_CONOSCIUTA_DAL_MINORE_DESC,
           DECODE (FA_fuori_regione,
                   1, 'Famiglia affidataria residente fuori regione',
                   0, 'Famiglia affidataria residente in regione')
               FA_fuori_regione_desc,
           DECODE (fa_bdf,
                   1, 'Famiglia già presente in banca dati famiglie',
                   2, 'Famiglia inserita in BDF nell''ambito del progetto',
                   0, 'Famiglia affidataria non inserita in BDF')
               fa_bdn_desc
      FROM (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)
                       Z_ZONA_SOCIALE,
                   DIARIO_PAI_ID
                       PAI_ID,
                   STATOINI.DATA_STATO_AFFIDO
                       DATA_INIZIO_AFFIDO,
                   statotermine.DATA_STATO_AFFIDO
                       DATA_termine_AFFIDO,
                   statoannull.DATA_STATO_AFFIDO
                       DATA_ANNULLAMENTO_AFFIDO,
                   DECODE (CODICE_TIPO_AFFIDO,
                           'TIPO_AFFIDO_ACCOGLIENZA', 'Accoglienza',
                           'TIPO_AFFIDO_FAMILIARE', 'Familiare')
                       TIPOLOGIA_AFFIDO,
                   AFFIDAMENTO_PROFESSIONALE
                       AFFIDO_PROFESSIONALE,
                   DECODE (CODICE_ADOTTABILE,
                           'ADOTTABILE_ATTESA_TRIBUNALE', '2',
                           'ADOTTABILE_SI', '1',
                           'ADOTTABILE_NO', '0')
                       ADOTTABILE,
                   DECODE (CODICE_NATURA_ACCOGLIENZA,
                           'NATURA_ACCOGLIENZA_GIUDIZIALE', 'Giudiziale',
                           'NATURA_ACCOGLIENZA_CONSENSUALE', 'Consensuale',
                           NULL)
                       NATURA_AFFIDO,
                   DECODE (
                       CODICE_ENTITA_AFFIDO,
                       'ENTITA_AFFIDO_DIURNO', 'Diurno',
                       'ENTITA_AFFIDO_DIURNO_PARZIALE', 'Diurno Parziale',
                       'ENTITA_AFFIDO_RESIDENZIALE', 'Residenziale (full time)',
                       'ENTITA_AFFIDO_RESIDENZIALE_PARZIALE', 'Residenziale Parziale')
                       ENTITA,
                   -- DECODE (
                   --    CODICE_SITUAZIONI_PARTICOLARI,
                   --   'SITUAZIONI_PARTICOLARI_AUTONOMIA_GIOVANI', 'Affidamento in emergenza',
                   --     'SITUAZIONI_PARTICOLARI_EMERGENZA', 'Affidamento per l''autonomia dei giovani',
                   --   NULL)
                   --     situazioni_particolari,
                   DECODE (
                       CODICE_FORME_AFFIDAMENTO,
                       'FORME_AFFIDAMENTO_COSOLIDATE_FAM_DISABILI', 'Affidamento familiare di disabili',
                       'FORME_AFFIDAMENTO_COSOLIDATE_FAM_NEONATI', 'Affidamento familiare di neonati e bambini in tenera età (0-24 mesi)',
                       'FORME_AFFIDAMENTO_COSOLIDATE_EMERGENZA', 'Affidamento in emergenza per bambini zero ? dodici anni',
                       'FORME_AFFIDAMENTO_COSOLIDATE_ADOLESCENTI', 'Affidamento di adolescenti',
                       'ALTRE_FORME_ACCOGLIENZA_GB', 'Accoglienza genitore ? bambino',
                       'FORME_AFFIDAMENTO_COSOLIDATE_FAM_STRANIERI_NON_ACC', 'Affidamento familiare di minori stranieri non accompagnati',
                       'FORME_AFFIDAMENTO_COSOLIDATE_FAM_STRANIERI_STESSAC', 'Affidamento di minori stranieri a famiglie della stessa cultura',
                       'ALTRE_FORME_VICINATO_SOLIDALE', 'Vicinato solidale',
                       'FORME_AFFIDAMENTO_COSOLIDATE_AUTONOMIA_GIOVANI', 'Affidamento per l?autonomia dei giovani',
                       NULL)
                       forme_affidamento,
                   DECODE (
                       CODICE_COLLOCAMENTO,
                       'COLLOCAMENTO_ETERO_FAMILAIRE', 'Collocamento Etero-familiare ',
                       'COLLOCAMENTO_INTRA_FAMILIARE_MATERNO', 'Collocamento Intra-familiare materno',
                       'COLLOCAMENTO_INTRA_FAMILIARE_PATERNO', 'Collocamento Intra-familiare paterno')
                       collocamento,
                   presenza_reti_famiglie,
                   --  DISABILITA_DURANTE_AFFIDO,
                   --   STRANIERO_NON_ACCOMPAGNATO,
                   --  STRANIERO_AFF_CULTURA,
                   ORIG.IS_MINORE_ALLONTANATO,
                   orig.GENITORI_SCONOSCIUTI,
                   ORIG.FUORI_REGIONE,
                   DECODE (
                       codice_frequenza_contatti,
                       'FREQUENZA_CONTATTI_SALTUARI', 'Saltuari',
                       'FREQUENZA_CONTATTI_FREQUENTI', 'Frequenti (almeno mensili)',
                       'FREQUENZA_CONTATTI_NESSUN_CONTATTO', 'Nessun Contatto',
                       'FREQUENZA_CONTATTI_MOLTO_FREQUENTI', 'Molto frequenti (più volte a settimana)',
                       NULL)
                       CONTATTI_CON_FO,
                   DECODE (CODICE_TIPO_FAMIGLIA,
                           'AFFIDATARI_SINGOLO_DONNA', 'Singolo donna',
                           'AFFIDATARI_SINGOLO_UOMO', 'Singolo uomo',
                           'AFFIDATARI_COPPIA', 'Coppia')
                       AFFIDATARI,
                   FAMAFF.CONOSCIUTA_DAL_MINORE
                       FA_CONOSCIUTA_DAL_MINORE,
                   FAMAFF.FUORI_REGIONE
                       FA_FUORI_REGIONE,
                   DECODE (FAMAFF.CODICE_BANCA_DATI_FAM,
                           'BANCA_DATI_FAMIGLIE_NON_INSERITA', 3,
                           'BANCA_DATI_FAMIGLIE_PRESENTE', 1,
                           'BANCA_DATI_FAMIGLIE_INSERITA', 2)
                       FA_BDF
              FROM CS_PAI_AFFIDO  AFF
                   LEFT JOIN (SELECT *
                                FROM cs_pai_affido_stato
                               WHERE CODICE = '50') statoINI
                       ON AFF.ID = STATOINI.PAI_AFFIDO_ID
                   LEFT JOIN (SELECT *
                                FROM cs_pai_affido_stato
                               WHERE CODICE = '60') statotermine
                       ON AFF.ID = statotermine.PAI_AFFIDO_ID
                   LEFT JOIN (SELECT *
                                FROM cs_pai_affido_stato
                               WHERE CODICE = '70') statoannull
                       ON AFF.ID = statoannull.PAI_AFFIDO_ID
                   LEFT JOIN CS_PAI_AFFIDO_FAMIGLIA_ORIG ORIG
                       ON ORIG.ID = AFF.FAM_ORIG_ID
                   LEFT JOIN CS_PAI_AFFIDO_FAMIGLIA_AFF FAMAFF
                       ON FAMAFF.ID = AFF.FAM_AFF_ID) PAI;


DROP VIEW CS_ROMA.V_UDC_PC_CONF;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_UDC_PC_CONF
(
    ZONA_SOCIALE,
    ORGANIZZAZIONE,
    UFFICIO,
    PUNTO_DI_CONTATTI
)
BEQUEATH DEFINER
AS
    SELECT (SELECT nome FROM cs_o_zona_soc)     "ZONA_SOCIALE",
           --ORG.ID ORGANIZZAZIONE_ID,
           ORG.NOME                             ORGANIZZAZIONE,
           --U.ID UFFICIO_ID,
           U.NOME                               UFFICIO,
           --PC.ID PUNTO_DI_CONTATTO_ID ,
           PC.NOME                              PUNTO_DI_CONTATTI
      --ORG.ID||U.ID||PC.ID upc
      FROM cs_o_organizzazione   org,
           ss_ufficio            u,
           ss_punto_contatto     pc,
           ss_rel_uff_pcont_org  rel
     WHERE     REL.ORGANIZZAZIONE_ID = ORG.ID
           AND REL.UFFICIO_ID = U.ID
           AND REL.PUNTO_CONTATTO_ID = PC.ID
           AND U.NOME LIKE 'UDC%'
--order by ZONA_SOCIALE,U.NOME;
;


DROP VIEW CS_ROMA.V_UTENTI_CARTELLA;

/* Formatted on 18/07/2022 12:23:35 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_UTENTI_CARTELLA
(
    USERNAME,
    COGNOME,
    NOME,
    CODICE_FISCALE,
    DATA_NASCITA,
    COMUNE_NASCITA,
    EMAIL,
    ENTI
)
BEQUEATH DEFINER
AS
    (SELECT u.name     username,
            a.cognome,
            a.nome,
            a.codice_fiscale,
            data_nascita,
            comune_nascita,
            u.email,
            enti
       FROM (  SELECT fk_am_user,
                      LISTAGG (fk_am_comune, '|')
                          WITHIN GROUP (ORDER BY fk_am_comune)    enti
                 FROM (SELECT DISTINCT fk_am_user, fk_am_comune
                         FROM V_UTENTI_INSTANCE_GRUPPI, cs_o_organizzazione o
                        WHERE     FK_AM_APPLICATION = 'CarSociale'
                              AND O.COD_ROUTING = fk_am_comune)
             GROUP BY fk_am_user) g,
            AM_ANAGRAFICA  a,
            am_user        u
      WHERE a.fk_am_user = g.fk_am_user AND u.name = a.fk_am_user);


DROP VIEW CS_ROMA.V_UTENTI_UFFICI_SETTORI;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_UTENTI_UFFICI_SETTORI
(
    APP,
    USERNAME,
    COGNOME,
    NOME,
    EMAIL,
    SETTORE_UFFICIO_ID,
    SETTORE_UFFICIO,
    RUOLO,
    TIPO_OPERATORE,
    ORGANIZZAZIONE_ID,
    ORGANIZZAZIONE,
    BELFIORE,
    ZONA_SOCIALE
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT 'udc'             App,
                     ua.fk_am_user     username,
                     a.cognome,
                     a.nome,
                     u.email,
                     ssu.id            settore_ufficio_id,
                     SSU.NOME          settore_ufficio,
                     d.fk_am_group     RUOLO,
                     NULL              TIPO_OPERATORE,
                     rel.organizzazione_id,
                     o.nome            organizzazione,
                     o.COD_ROUTING,
                     ZS.NOME           ZONA_SOCIALE
       FROM V_COMUNI_UTENTI_INSTANCE  Ua,
            V_UTENTI_INSTANCE_GRUPPI  UIG,
            CS_O_ORGANIZZAZIONE       O,
            SS_REL_UFF_PCONT_ORG      rel,
            ss_ufficio                ssu,
            am_user_group             d,
            am_group                  g,
            cs_o_zona_soc             zs,
            am_user                   u,
            am_anagrafica             a
      WHERE     O.COD_ROUTING = ua.fk_am_comune
            AND rel.organizzazione_id = o.id
            AND SSU.ID = REL.UFFICIO_ID
            AND d.fk_am_user = ua.fk_am_user
            AND d.fk_am_group = g.name
            AND g.fk_am_comune = o.COD_ROUTING
            AND ua.fk_am_application = 'SegretariatoSoc'
            AND u.name = d.fk_am_user
            AND u.name = a.fk_am_user
            AND UIG.INSTANCE = UA.FK_AM_INSTANCE
            AND UIG.FK_AM_USER = d.fk_am_user
            AND UIG.GRUPPO = D.fk_am_group
            AND d.fk_am_group NOT LIKE 'ADMINGIT%'
            AND NOT EXISTS
                    (SELECT 1
                       FROM AM_USER_GROUP AMUG
                      WHERE     FK_AM_USER = ua.fk_am_user
                            AND (    INSTR (ssu.escludi_am_group,
                                            AMUG.fk_am_group) >
                                     0
                                 AND INSTR (ssu.escludi_am_group,
                                            AMUG.fk_am_group)
                                         IS NOT NULL))
            AND O.ABILITATO = '1'
            AND ZS.ABILITATO = '1'
            AND NOT EXISTS
                    (SELECT 1
                       FROM am_user u
                      WHERE     name = ua.fk_am_user
                            AND u.DISABLE_CAUSE IS NOT NULL)
     UNION
     SELECT DISTINCT 'cartella'           App,
                     ua.fk_am_user        username,
                     a.cognome,
                     a.nome,
                     u.email,
                     OS.SETTORE_ID,
                     S.NOME               SETTORE,
                     OS.AM_GROUP          RUOLO,
                     TBTO.DESCRIZIONE     TIPO_OPERATORE,
                     O.ID                 ORGANIZZAZIONE_ID,
                     O.NOME               ORGANIZZAZIONE,
                     o.COD_ROUTING,
                     ZS.NOME              ZONA_SOCIALE
       FROM CS_O_ZONA_SOC                 ZS,
            V_COMUNI_UTENTI_APPLICAZIONI  ua
            INNER JOIN cs_o_operatore op ON OP.USERNAME = uA.fk_am_user
            INNER JOIN AM_USER U ON UA.FK_AM_USER = U.NAME
            INNER JOIN AM_ANAGRAFICA A ON A.FK_AM_USER = U.NAME
            INNER JOIN CS_O_OPERATORE_SETTORE OS ON OP.ID = OS.OPERATORE_ID
            INNER JOIN CS_O_SETTORE S ON S.ID = OS.SETTORE_ID
            INNER JOIN CS_O_ORGANIZZAZIONE O ON S.ORGANIZZAZIONE_ID = O.ID
            LEFT JOIN CS_O_OPERATORE_TIPO_OPERATORE OTO
                ON OTO.OPERATORE_SETTORE_ID = OS.ID
            INNER JOIN CS_TB_TIPO_OPERATORE TBTO
                ON OTO.TIPO_OPERATORE_ID = TBTO.ID
      WHERE     ua.fk_am_application = 'CarSociale'
            AND ua.fk_am_comune = o.COD_ROUTING
            AND OP.ABILITATO = '1'
            AND S.ABILITATO = '1'
            AND O.ABILITATO = '1'
            AND OS.DATA_FINE_APP = TO_DATE ('31-12-9999', 'DD-MM-YYYY')
            AND OTO.DATA_FINE_APP = TO_DATE ('31-12-9999', 'DD-MM-YYYY')
            AND NOT EXISTS
                    (SELECT 1
                       FROM am_user u
                      WHERE     name = ua.fk_am_user
                            AND u.DISABLE_CAUSE IS NOT NULL));


