DROP VIEW CS_ROMA.CS_VISTA_FSE;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.CS_VISTA_FSE
(
    ID,
    TIPO,
    PROGETTO_ATTIVITA_ID,
    PROGETTO,
    DATA_SOTTOSCRIZIONE,
    SOGGETTO_ATTUATORE,
    ORG_TITOLARE_ID,
    ORG_TITOLARE_DESC,
    COGNOME,
    NOME,
    CF,
    DATA_NASCITA,
    NASCITA_COMUNE_ID,
    NASCITA_NAZIONE_ID,
    CITTADINANZA,
    RES_NAZIONE_ID,
    RES_COMUNE_ID,
    RES_INDIRIZZO,
    DOM_COMUNE_ID,
    DOM_INDIRIZZO,
    TELEFONO,
    CELLULARE,
    EMAIL,
    TITOLO_STUDIO,
    COND_MERCATO_INGRESSO,
    DURATA_RICERCA,
    COD_VULNERABILE_PA,
    NASCITA_COMUNE_DESC,
    CITTADINANZA_COD,
    RES_COMUNE_DESC,
    RES_CAP,
    DOM_COMUNE_DESC,
    DOM_CAP
)
BEQUEATH DEFINER
AS
    (SELECT fse.TIPO || '@' || fse.id     AS ID,
            fse."TIPO",
            fse."PROGETTO_ATTIVITA_ID",
            fse."PROGETTO",
            fse."DATA_SOTTOSCRIZIONE",
            fse."SOGGETTO_ATTUATORE",
            fse.orgTitolare,
            titolare.nome                 orgTitolareDesc,
            fse."COGNOME",
            fse."NOME",
            fse."CF",
            fse."DATA_NASCITA",
            fse."COMUNE_NASCITA_ID",
            fse."NAZIONE_NASCITA_ID",
            fse."CITTADINANZA",
            fse.NAZIONE_RES_ID,
            fse."COMUNE_RES_ID",
            fse."INDIRIZZO_RESIDENZA",
            fse."COMUNE_DOM_ID",
            fse."INDIRIZZO_DOMICILIO",
            fse."TELEFONO",
            fse."CELLULARE",
            fse."EMAIL",
            fse."TITOLO_STUDIO",
            fse."COND_MERCATO_INGRESSO",
            fse."DURATA_RICERCA",
            fse."COD_VULNERABILE_PA",
            nascita.denominazione         COMUNE_NASCITA_DES,
            citt.sigla                    AS cittadinanza_cod,
            com_res.denominazione         res_comune_desc,
            com_res.cap                   res_cap,
            com_dom.denominazione         dom_comune_des,
            com_dom.cap                   dom_cap
       FROM (SELECT DISTINCT
                    TIPO.ID
                        AS TIPO,
                    m.caso_id
                        AS ID,
                    attivita.codice
                        PROGETTO_ATTIVITA_ID,
                    progetto.descrizione
                        PROGETTO,
                    c.dt_sottoscrizione
                        DATA_SOTTOSCRIZIONE,
                    c.soggetto_attuatore
                        soggetto_Attuatore,
                    M.ORGANIZZAZIONE_ID
                        orgTitolare,
                    a.cognome,
                    TO_CHAR (a.nome)
                        nome,
                    UPPER (A.CF)
                        CF,
                    SIR.DATA_NASCITA,
                    SIR.COMUNE_NASCITA_ID,
                    SIR.NAZIONE_NASCITA_ID,
                    SIR.cittadinanza,
                    DECODE (RESIDENZA.STATO_COD,
                            1, NULL,
                            RESIDENZA.STATO_COD)
                        NAZIONE_RES_ID,
                    SIR.COMUNE_RES_ID,
                       RESIDENZA.INDIRIZZO
                    || DECODE (RESIDENZA.CIVICO_NUMERO,
                               NULL, '',
                               ', ' || RESIDENZA.CIVICO_NUMERO)
                        INDIRIZZO_RESIDENZA,
                    DECODE (DOMIND.ANA_INDIRIZZO_ID,
                            NULL, SIR.COMUNE_RES_ID,
                            SIR.COMUNE_DOM_ID)
                        COMUNE_DOM_ID,
                    DECODE (
                        DOMIND.ANA_INDIRIZZO_ID,
                        NULL,    RESIDENZA.INDIRIZZO
                              || DECODE (RESIDENZA.CIVICO_NUMERO,
                                         NULL, '',
                                         ', ' || RESIDENZA.CIVICO_NUMERO),
                           DOMICILIO.INDIRIZZO
                        || DECODE (DOMICILIO.CIVICO_NUMERO,
                                   NULL, '',
                                   ', ' || DOMICILIO.CIVICO_NUMERO))
                        INDIRIZZO_DOMICILIO,
                    A.TEL
                        AS TELEFONO,
                    A.CELL
                        AS cellulare,
                    A.EMAIL,
                    SIR.TITOLO_STUDIO,
                    SIR.COND_MERCATO_INGRESSO,
                    SIR.DURATA_RICERCA,
                    SIR.COD_VULNERABILE_PA
               FROM CS_EXTRA_FSE_DATI_LAVORO  c
                    LEFT JOIN CS_EXTRA_FSE_MAST m
                        ON (C.EXTRA_FSE_MAST_ID = M.ID)
                    LEFT JOIN CS_TB_TIPO_EXTRA_FSE TIPO
                        ON (M.TIPO_EXTRA_FSE_ID = tipo.id)
                    LEFT JOIN CS_A_SOGGETTO s ON (M.CASO_ID = S.CASO_ID)
                    LEFT JOIN CS_A_ANAGRAFICA a ON (S.ANAGRAFICA_ID = a.id)
                    LEFT JOIN CS_A_INDIRIZZO resInd
                        ON (    S.ANAGRAFICA_ID =
                                resInd.SOGGETTO_ANAGRAFICA_ID
                            AND resInd.TIPO_INDIRIZZO_ID = 1
                            AND resInd.data_fine_app IS NULL)
                    LEFT JOIN CS_A_ANA_INDIRIZZO residenza
                        ON (RESIND.ANA_INDIRIZZO_ID = residenza.id)
                    LEFT JOIN CS_A_INDIRIZZO domInd
                        ON (    S.ANAGRAFICA_ID =
                                domInd.SOGGETTO_ANAGRAFICA_ID
                            AND domInd.TIPO_INDIRIZZO_ID = 3
                            AND domInd.data_fine_app IS NULL)
                    LEFT JOIN CS_A_ANA_INDIRIZZO domicilio
                        ON (domInd.ANA_INDIRIZZO_ID = domicilio.id)
                    LEFT JOIN CS_EXTRA_FSE_SIRU sir
                        ON (M.ID = SIR.EXTRA_FSE_MAST_ID)
                    LEFT JOIN AR_FF_PROGETTO progetto
                        ON (progetto.id = C.PROGETTO_ID)
                    LEFT JOIN AR_FF_PROGETTO_ATTIVITA attivita
                        ON (attivita.id = C.PROGETTO_ATTIVITA_ID)
              WHERE     M.TIPO_EXTRA_FSE_ID = 1
                    AND progetto.codice_memo IS NOT NULL
             UNION ALL
             SELECT DISTINCT
                    TIPO.ID
                        AS TIPO,
                    M.SCHEDA_ID
                        AS ID,
                    attivita.codice
                        PROGETTO_ATTIVITA_ID,
                    progetto.descrizione
                        PROGETTO_ID,
                    c.dt_sottoscrizione
                        DATA_SOTTOSCRIZIONE,
                    c.soggetto_attuatore
                        soggetto_Attuatore,
                    m.ORGANIZZAZIONE_ID
                        orgTitolare,
                    a.cognome,
                    a.nome,
                    UPPER (A.CF)
                        CF,
                    SIR.DATA_NASCITA,
                    SIR.COMUNE_NASCITA_ID,
                    SIR.NAZIONE_NASCITA_ID,
                    SIR.cittadinanza,
                    DECODE (RESIDENZA.STATO_COD,
                            1, NULL,
                            RESIDENZA.STATO_COD)
                        NAZIONE_RES_ID,
                    SIR.COMUNE_RES_ID,
                       RESIDENZA.VIA
                    || DECODE (RESIDENZA.NUMERO,
                               NULL, '',
                               ', ' || RESIDENZA.NUMERO)
                        INDIRIZZO_RESIDENZA,
                    DECODE (SS.domicilio,
                            NULL, SIR.COMUNE_RES_ID,
                            SIR.COMUNE_DOM_ID)
                        COMUNE_DOM_ID,
                    DECODE (
                        SS.domicilio,
                        NULL,    RESIDENZA.VIA
                              || DECODE (RESIDENZA.NUMERO,
                                         NULL, '',
                                         ', ' || RESIDENZA.NUMERO),
                           DOMICILIO.VIA
                        || DECODE (DOMICILIO.NUMERO,
                                   NULL, '',
                                   ', ' || DOMICILIO.NUMERO))
                        INDIRIZZO_DOMICILIO,
                    SS.TELEFONO
                        AS TELEFONO,
                    SS.CEL
                        AS CELLULARE,
                    SS.EMAIL
                        AS EMAIL,
                    SIR.TITOLO_STUDIO,
                    SIR.COND_MERCATO_INGRESSO,
                    SIR.DURATA_RICERCA,
                    SIR.COD_VULNERABILE_PA
               FROM CS_EXTRA_FSE_DATI_LAVORO  c
                    LEFT JOIN CS_EXTRA_FSE_MAST m
                        ON (C.EXTRA_FSE_MAST_ID = M.ID)
                    LEFT JOIN CS_TB_TIPO_EXTRA_FSE TIPO
                        ON (M.TIPO_EXTRA_FSE_ID = tipo.id)
                    LEFT JOIN SS_SCHEDA s ON (M.SCHEDA_ID = S.ID)
                    LEFT JOIN SS_SCHEDA_SEGNALATO ss ON (s.segnalato = ss.id)
                    LEFT JOIN SS_ANAGRAFICA a ON (SS.ANAGRAFICA = a.id)
                    LEFT JOIN SS_INDIRIZZO residenza
                        ON (SS.RESIDENZA = residenza.id)
                    LEFT JOIN SS_INDIRIZZO domicilio
                        ON (ss.domicilio = domicilio.id)
                    LEFT JOIN CS_EXTRA_FSE_SIRU sir
                        ON (M.ID = SIR.EXTRA_FSE_MAST_ID)
                    LEFT JOIN AR_FF_PROGETTO progetto
                        ON (progetto.id = C.PROGETTO_ID)
                    LEFT JOIN AR_FF_PROGETTO_ATTIVITA attivita
                        ON (attivita.id = C.PROGETTO_ATTIVITA_ID)
              WHERE     M.TIPO_EXTRA_FSE_ID = 2
                    AND progetto.codice_memo IS NOT NULL
             UNION ALL
             SELECT DISTINCT
                    TIPO.ID                       AS TIPO,
                    M.ID,
                    arpa.codice                   PROGETTO_ATTIVITA_ID,
                    arp.descrizione               PROGETTO_ID,
                    c.dt_sottoscrizione           DATA_SOTTOSCRIZIONE,
                    c.soggetto_attuatore          soggetto_Attuatore,
                    arp.organizzazione_id         orgTitolare,
                    S.COGNOME,
                    S.NOME,
                    UPPER (S.CF)                  CF,
                    SIR.DATA_NASCITA,
                    SIR.COMUNE_NASCITA_ID,
                    SIR.NAZIONE_NASCITA_ID,
                    SIR.cittadinanza,
                    S.NAZIONE_RESIDENZA           NAZIONE_RESIDENZA_ID,
                    SIR.COMUNE_RES_ID,
                    S.VIA_RESIDENZA               INDIRIZZO_RESIDENZA,
                    DECODE (c.comune_domicilio,
                            NULL, SIR.COMUNE_RES_ID,
                            SIR.COMUNE_DOM_ID)    COMUNE_DOM_ID,
                    DECODE (c.comune_domicilio,
                            NULL, S.VIA_RESIDENZA,
                            C.VIA_DOMICILIO)      INDIRIZZO_DOMICILIO,
                    C.TELEFONO,
                    C.CELLULARE,
                    C.EMAIL,
                    SIR.TITOLO_STUDIO,
                    SIR.COND_MERCATO_INGRESSO,
                    SIR.DURATA_RICERCA,
                    SIR.COD_VULNERABILE_PA
               FROM CS_TB_TIPO_EXTRA_FSE          TIPO,
                    V_INTERVENTO_PR_FSE_JSON_EXT  c
                    LEFT JOIN CS_I_INTERVENTO_ESEG_MAST m
                        ON (m.INT_PROGETTO_ID = c.INTERVENTO_PR_ID)
                    LEFT JOIN CS_I_INTERVENTO_PR pr
                        ON (PR.ID = C.INTERVENTO_PR_ID)
                    LEFT JOIN V_AR_SETTORE_PROGETTO arp
                        ON (    arp.settore_id = pr.settore_titolare_id
                            AND PR.progetto_id = arp.id)
                    LEFT JOIN AR_FF_PROGETTO_ATTIVITA arpa
                        ON (arpa.id = pr.progetto_attivita_id)
                    LEFT JOIN V_EROG_MAST_SOGG_JSON_EXT s
                        ON (    m.ID = s.INT_ESEG_MAST_ID
                            AND FLAG_RIFERIMENTO = 1)
                    LEFT JOIN CS_I_INTERVENTO_PR_FSE_SIRU sir
                        ON (C.INTERVENTO_PR_ID = SIR.INTERVENTO_PR_ID)
              WHERE TIPO.ID = 3 AND M.ID IS NOT NULL AND S.CF IS NOT NULL)
            fse
            LEFT JOIN FSE_CHK_IT_COMUNE nascita
                ON nascita.id = FSE.COMUNE_NASCITA_ID
            LEFT JOIN AM_TAB_NAZIONI citt
                ON (citt.cod_istat_nazione =
                    DECODE (FSE.cittadinanza, '000', '1', fse.cittadinanza))
            LEFT JOIN FSE_CHK_IT_COMUNE com_res
                ON com_res.id = FSE.COMUNE_RES_ID
            LEFT JOIN FSE_CHK_IT_COMUNE com_dom
                ON com_dom.id = FSE.COMUNE_DOM_ID
            LEFT JOIN CS_O_ORGANIZZAZIONE titolare
                ON titolare.id = orgTitolare);


DROP VIEW CS_ROMA.V_BI_TR_CS_AN;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_AN
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    CASO_ID,
    IDENTIFICATIVO,
    O_CODICE_ORG,
    O_SETTORE_NOME,
    C_DATAINS_CASO,
    C_COGNOME,
    C_NOME,
    C_DATA_NASCITA,
    C_CF,
    C_DATA_DECESSO,
    C_SESSO,
    C_CITTADINANZA,
    C_CITTADINANZA2,
    C_IND_RES_DT_INIZIO,
    C_IND_RES_CODICE_VIA,
    C_IND_COM_RES_COD_ISTAT,
    C_IND_RES_INDIRIZZO,
    C_IND_RES_CIVICO_NUMERO,
    C_IND_RES_PROV,
    C_IND_RES_STATO_COD,
    C_IND_DOM_DT_INIZIO,
    C_IND_DOM_CODICE_VIA,
    C_IND_COM_DOM_COD_ISTAT,
    C_IND_DOM_INDIRIZZO,
    C_IND_DOM_CIVICO_NUMERO,
    C_IND_DOM_PROV,
    C_IND_DOM_STATO_COD,
    CDS_DATA_AGG_DATI_SOCIALI,
    CDS_TIPOLOGIA_FAMILIARE,
    CDS_CONDIZIONE_LAVORATIVA,
    CDS_TITOLO_STUDIO,
    CDS_MINORE_STRAN_NON_ACC,
    CDS_GRUPPO_VULNERABILE,
    CDI_DATA_AGG_INVALIDITA,
    CDI_INVALIDITA_CIVILE,
    CDI_PERC_INVALIDITA,
    CDI_ACCOMPAGNAMENTO,
    CDI_LEGGE104,
    CDI_DATA_INVALIDITA,
    CDI_DATA_SCADENZA_INVALIDITA,
    CDI_CERTIFICAZIONE_H,
    CDI_DATA_CERTIFICAZIONE_H,
    CDI_DATA_SCAD_CERTIFICAZIONE,
    CDIS_DATA_AGG_DISABILITA,
    CDIS_GRAVITA_DISABILITA,
    CDIS_TIPOLOGIA_DISABILITA,
    IT_ULTIMO_STATO_CASO,
    IT_ULTIMO_STATO_ITER_DATA,
    STATO_CIVILE_COD
)
BEQUEATH DEFINER
AS
    (SELECT 'CS_AN'
                TIPO_RECORD,
            (SELECT NOME FROM CS_O_ZONA_SOC)
                Z_ZONA_SOCIALE,
            INV.ID_INVIANTE
                CODICE_INVIANTE,
            caso_id,
            identificativo,
            UTIL_ORG.O_CODICE_ORG,
            O_SETTORE_NOME,
            C_DATAINS_CASO,
            C_COGNOME,
            C_NOME,
            C_DATA_NASCITA,
            C_CF,
            C_DATA_DECESSO,
            C_SESSO,
            C_CITTADINANZA,
            C_CITTADINANZA2,
            C_IND_RES_DT_INIZIO,
            C_IND_RES_CODICE_VIA,
            C_IND_COM_RES_COD_ISTAT,
            C_IND_RES_INDIRIZZO,
            C_IND_RES_CIVICO_NUMERO,
            DECODE (C_IND_RES_STATO_COD, 100, C_IND_RES_PROV, NULL)
                C_IND_RES_PROV,
            C_IND_RES_STATO_COD,
            C_IND_DOM_DT_INIZIO,
            C_IND_DOM_CODICE_VIA,
            C_IND_COM_DOM_COD_ISTAT,
            C_IND_DOM_INDIRIZZO,
            C_IND_DOM_CIVICO_NUMERO,
            DECODE (C_IND_DOM_STATO_COD, 100, C_IND_DOM_PROV, NULL)
                C_IND_DOM_PROV,
            C_IND_DOM_STATO_COD,
            CDS_DATA_AGG_DATI_SOCIALI,
            CDS_TIPOLOGIA_FAMILIARE,
            CDS_CONDIZIONE_LAVORATIVA,
            CDS_TITOLO_STUDIO,
            CDS_MINORE_STRAN_NON_ACC,
            CDS_GRUPPO_VULNERABILE,
            CDI_DATA_AGG_INVALIDITA,
            CDI_INVALIDITA_CIVILE,
            CDI_PERC_INVALIDITA,
            CDI_ACCOMPAGNAMENTO,
            CDI_LEGGE104,
            CDI_DATA_INVALIDITA,
            CDI_DATA_SCADENZA_INVALIDITA,
            CDI_CERTIFICAZIONE_H,
            CDI_DATA_CERTIFICAZIONE_H,
            CDI_DATA_SCAD_CERTIFICAZIONE,
            CDIS_DATA_AGG_DISABILITA,
            CDIS_GRAVITA_DISABILITA,
            CDIS_TIPOLOGIA_DISABILITA,
            IT_ULTIMO_STATO_CASO,
            IT_ULTIMO_STATO_ITER_DATA,
            STATO_CIVILE_COD
       FROM V_BI_INVIANTE       INV,
            V_BI_UTIL_TIPO_ORG  UTIL_ORG,
            (SELECT DISTINCT
                    c.id
                        PK_T0_CASO_ID,
                    o.id
                        id_organizzazione,
                    c.id
                        caso_id,
                    c.IDENTIFICATIVO,
                    O.NOME
                        O_ORG_NOME,
                    SE.NOME
                        O_SETTORE_NOME,
                    C.DT_INS
                        C_DATAINS_CASO,
                    a.cognome
                        C_COGNOME,
                    a.nome
                        C_NOME,
                    a.data_nascita
                        C_DATA_NASCITA,
                    a.cf
                        C_CF,
                    a.data_decesso
                        C_DATA_DECESSO,
                    a.sesso
                        C_SESSO,
                    DECODE (n.cod_istat_nazione, 1, 100, n.cod_istat_nazione)
                        C_CITTADINANZA,
                    DECODE (n2.cod_istat_nazione,
                            1, 100,
                            n2.cod_istat_nazione)
                        C_CITTADINANZA2,
                    indr.DATA_INIZIO_APP
                        C_IND_RES_DT_INIZIO,
                    res.CODICE_VIA
                        C_IND_RES_CODICE_VIA,
                    res.COM_COD
                        C_IND_COM_RES_COD_ISTAT,
                    res.INDIRIZZO
                        C_IND_RES_INDIRIZZO,
                    res.CIVICO_NUMERO
                        C_IND_RES_CIVICO_NUMERO,
                    res.PROV
                        C_IND_RES_PROV,
                    DECODE (res.STATO_COD, 1, 100, NVL (res.STATO_COD, 100))
                        C_IND_RES_STATO_COD,
                    DECODE (indd.ana_indirizzo_id,
                            NULL, indr.DATA_INIZIO_APP,
                            indd.DATA_INIZIO_APP)
                        C_IND_DOM_DT_INIZIO,
                    DECODE (indd.ana_indirizzo_id,
                            NULL, RES.CODICE_VIA,
                            DOM.CODICE_VIA)
                        C_IND_DOM_CODICE_VIA,
                    DECODE (indd.ana_indirizzo_id,
                            NULL, RES.COM_COD,
                            DOM.COM_COD)
                        C_IND_COM_DOM_COD_ISTAT,
                    DECODE (indd.ana_indirizzo_id,
                            NULL, RES.INDIRIZZO,
                            DOM.indirizzo)
                        C_IND_DOM_INDIRIZZO,
                    DECODE (indd.ana_indirizzo_id,
                            NULL, RES.CIVICO_NUMERO,
                            DOM.CIVICO_NUMERO)
                        C_IND_DOM_CIVICO_NUMERO,
                    DECODE (indd.ana_indirizzo_id, NULL, RES.PROV, DOM.PROV)
                        C_IND_DOM_PROV,
                    DECODE (
                        indd.ana_indirizzo_id,
                        NULL, DECODE (res.STATO_COD,
                                      1, 100,
                                      NVL (res.STATO_COD, 100)),
                        DECODE (dom.STATO_COD,
                                1, 100,
                                NVL (dom.STATO_COD, 100)))
                        C_IND_DOM_STATO_COD,
                    DS.DATA_INIZIO_APP
                        CDS_DATA_AGG_DATI_SOCIALI,
                    tipfam.descrizione
                        CDS_TIPOLOGIA_FAMILIARE,
                    TBCL.DESCRIZIONE
                        CDS_CONDIZIONE_LAVORATIVA,
                    TBTS.DESCRIZIONE
                        CDS_TITOLO_STUDIO,
                    NVL (DS.STRANIERO_N_ACC, 0)
                        CDS_MINORE_STRAN_NON_ACC,
                    gvul.descrizione
                        CDS_GRUPPO_VULNERABILE,
                    DI.DATA_INIZIO_APP
                        CDI_DATA_AGG_INVALIDITA,
                    DI.INVALIDITA_CIVILE
                        CDI_INVALIDITA_CIVILE,
                    DI.PERC_INVALIDITA
                        CDI_PERC_INVALIDITA,
                    DI.ACCOMPAGNAMENTO
                        CDI_ACCOMPAGNAMENTO,
                    DI.LEGGE104
                        CDI_LEGGE104,
                    DI.DATA_INVALIDITA
                        CDI_DATA_INVALIDITA,
                    DI.DATA_SCADENZA_INVALIDITA
                        CDI_DATA_SCADENZA_INVALIDITA,
                    DI.CERTIFICAZIONE_H
                        CDI_CERTIFICAZIONE_H,
                    DI.DATA_CERTIFICAZIONE
                        CDI_DATA_CERTIFICAZIONE_H,
                    DI.DATA_SCADENZA_CERTIFICAZIONE
                        CDI_DATA_SCAD_CERTIFICAZIONE,
                    DIS.DATA_INIZIO_APP
                        CDIS_DATA_AGG_DISABILITA,
                    TBDIS.DESCRIZIONE
                        CDIS_GRAVITA_DISABILITA,
                    TBDISTIPO.DESCRIZIONE
                        CDIS_TIPOLOGIA_DISABILITA,
                    IT_STATO.NOME
                        IT_ULTIMO_STATO_CASO,
                    ITD.DT_AMMINISTRATIVA
                        IT_ULTIMO_STATO_ITER_DATA,
                    SSC.STATO_CIVILE_COD
               FROM CS_A_SOGGETTO        S
                    LEFT JOIN CS_A_SOGGETTO_STATO_CIVILE SSC
                        ON S.ANAGRAFICA_ID = SSC.SOGGETTO_ANAGRAFICA_ID
                    LEFT JOIN cs_a_dati_sociali ds
                        ON (    S.ANAGRAFICA_ID = DS.SOGGETTO_ANAGRAFICA_ID
                            AND DS.DATA_FINE_APP =
                                TO_DATE ('31-12-9999', 'dd-mm-yyyy'))
                    LEFT JOIN
                    (SELECT diafam.id
                                diafam_id,
                            SUBSTR (a, 1, INSTR (a, '",') - 1)
                                gruppoVulnerabile,
                            SUBSTR (b, 1, INSTR (b, ',') - 1)
                                tipologiaFamiliare
                       FROM (SELECT diafam.id,
                                    TO_CHAR (DATI_CLOB),
                                    SUBSTR (
                                        SUBSTR (
                                            TO_CHAR (DATI_CLOB),
                                            INSTR (TO_CHAR (DATI_CLOB),
                                                   'gruppoVulnerabile')),
                                        21)    a,
                                    SUBSTR (
                                        SUBSTR (
                                            TO_CHAR (DATI_CLOB),
                                            INSTR (TO_CHAR (DATI_CLOB),
                                                   'tipologiaFamiliare')),
                                        21)    b
                               FROM cs_d_clob clobfam, cs_d_diario diafam
                              WHERE     DIAfam.CLOB_ID = clobfam.ID
                                    AND diafam.tipo_diario_id = 14) diafam)
                    seldiafam
                        ON DS.DIARIO_FAM_CONV_ID = seldiafam.diafam_id
                    LEFT JOIN CS_TB_G_VULNERABILE gvul
                        ON gvul.id = seldiafam.gruppoVulnerabile
                    LEFT JOIN CS_TB_TIPOLOGIA_FAMILIARE tipfam
                        ON tipfam.id = seldiafam.tipologiaFamiliare
                    LEFT JOIN CS_TB_MOTIVO_SEGNAL PNUCLEO
                        ON DS.PROBLEMA_NUCLEO_ID = PNUCLEO.ID
                    LEFT JOIN CS_TB_PROBLEMATICA TBPS
                        ON DS.PROBLEMATICA_ID = TBPS.ID
                    LEFT JOIN CS_TB_TITOLO_STUDIO TBTS
                        ON DS.TITOLO_STUDIO_ID = TBTS.ID
                    LEFT JOIN CS_TB_COND_LAVORO TBCL
                        ON DS.COND_LAVORATIVA_ID = TBCL.ID
                    LEFT JOIN cs_a_dati_INVALIDITA DI
                        ON (    S.ANAGRAFICA_ID = DI.SOGGETTO_ANAGRAFICA_ID
                            AND DI.DATA_FINE_APP =
                                TO_DATE ('31-12-9999', 'dd-mm-yyyy'))
                    LEFT JOIN CS_A_DISABILITA DIS
                        ON (    S.ANAGRAFICA_ID = DIS.SOGGETTO_ANAGRAFICA_ID
                            AND DIS.DATA_FINE_APP =
                                TO_DATE ('31-12-9999', 'dd-mm-yyyy'))
                    LEFT JOIN CS_TB_DISAB_GRAVITA TBDIS
                        ON DIS.GRAVITA_ID = TBDIS.ID
                    LEFT JOIN CS_TB_DISAB_TIPOLOGIA TBDISTIPO
                        ON DIS.TIPOLOGIA_ID = TBDISTIPO.ID
                    LEFT JOIN CS_A_INDIRIZZO INDR
                        ON (    S.ANAGRAFICA_ID = INDR.SOGGETTO_ANAGRAFICA_ID
                            AND INDR.TIPO_INDIRIZZO_ID = '1'
                            AND indR.data_fine_app IS NULL)
                    LEFT JOIN CS_A_ANA_INDIRIZZO RES
                        ON INDR.ANA_INDIRIZZO_ID = RES.ID
                    LEFT JOIN CS_A_INDIRIZZO INDD
                        ON (    S.ANAGRAFICA_ID = INDD.SOGGETTO_ANAGRAFICA_ID
                            AND INDD.TIPO_INDIRIZZO_ID = '3'
                            AND indD.data_fine_app IS NULL)
                    LEFT JOIN CS_A_ANA_INDIRIZZO DOM
                        ON INDD.ANA_INDIRIZZO_ID = DOM.ID,
                    CS_A_ANAGRAFICA      a
                    LEFT JOIN am_tab_nazioni n
                        ON (    a.cittadinanza = n.nazionalita
                            AND n.attivo = 1
                            AND n.nazionalita_principale = 1)
                    LEFT JOIN am_tab_nazioni n2
                        ON (    a.cittadinanza_2 = n2.nazionalita
                            AND n2.attivo = 1
                            AND n2.nazionalita_principale = 1),
                    CS_A_CASO            c,
                    CS_IT_STEP           it
                    LEFT JOIN CS_CFG_IT_STATO IT_STATO
                        ON IT.CFG_IT_STATO_ID = IT_STATO.ID,
                    CS_D_DIARIO          ITD,
                    CS_O_ORGANIZZAZIONE  O,
                    cs_O_SETTORE         SE
              WHERE     S.CASO_ID = C.ID
                    AND S.ANAGRAFICA_ID = A.ID
                    AND IT.ID = (SELECT MAX (it2.id)
                                   FROM CS_IT_STEP it2
                                  WHERE IT2.CASO_ID = S.CASO_ID)
                    AND ITD.ID = IT.DIARIO_ID
                    AND IT.ORGANIZZAZIONE_ID = O.ID
                    AND IT.SETTORE_ID = SE.ID) a
      WHERE     INV.TIPO_INVIANTE = 'SISO'
            AND A.ID_ORGANIZZAZIONE = INV.ID_ORGANIZZAZIONE
            AND INV.ID_ORGANIZZAZIONE = UTIL_ORG.ID_ORGANIZZAZIONE);


DROP VIEW CS_ROMA.V_BI_TR_CS_AT;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_AT
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    CAT_SOCIALE_CODISTAT,
    CASO_ID_FK,
    CS_PREVALENTE,
    CS_CATSOC_DESCRIZIONE,
    CS_DATA_INIZIO_CATEGORIA,
    CS_DATA_FINE_CATEGORIA
)
BEQUEATH DEFINER
AS
    SELECT 'CS_AT'
               AS TIPO_RECORD,
           oc.Z_ZONA_SOCIALE
               AS Z_ZONA_SOCIALE,
           an.CODICE_INVIANTE
               AS CODICE_INVIANTE,
           oc.PK_T2_CAT_SOCIALE_CODISTAT
               AS CAT_SOCIALE_CODISTAT,
           TO_CHAR (oc.PK_T2_CASO_ID_FK)
               AS CASO_ID_FK,
           TO_CHAR (oc.CS_PREVALENTE)
               AS CS_PREVALENTE,
           oc.CS_CATSOC_DESCRIZIONE
               AS CS_CATSOC_DESCRIZIONE,
           TO_CHAR (oc.CS_DATA_INIZIO_CATEGORIA, 'dd/MM/yyyy')
               AS CS_DATA_INIZIO_CATEGORIA,
           TO_CHAR (oc.CS_DATA_FINE_CATEGORIA, 'dd/MM/yyyy')
               AS CS_DATA_FINE_CATEGORIA
      FROM V_T2_CASI_CATEGORIE_SOC  oc
           LEFT JOIN V_BI_TR_CS_AN an
               ON     oc.Z_ZONA_SOCIALE = an.Z_ZONA_SOCIALE
                  AND oc.PK_T2_CASO_ID_FK = an.CASO_ID
     WHERE an.CODICE_INVIANTE IS NOT NULL;


DROP VIEW CS_ROMA.V_BI_TR_CS_IT;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_IT
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    CASO_ID,
    STATO,
    DATA_ITER,
    DATA_INS_ITER,
    OPERATORE_RESPONSABILE,
    SETTORE,
    O_CODICE_ORG,
    OPERATORE,
    O_CODICE_ORG_TO,
    SETTORE_TO,
    OPERATORE_TO,
    N_ORD_ITER
)
BEQUEATH DEFINER
AS
    (SELECT 'CS_IT'                              TIPO_RECORD,
            (SELECT nome FROM cs_o_zona_soc)     Z_ZONA_SOCIALE,
            an.CODICE_INVIANTE,
            it.caso_id,
            IT_STATO.NOME                        STATO,
            ITD.DT_AMMINISTRATIVA                DATA_ITER,
            ITD.DT_INS                           DATA_INS_ITER,
            OPERESP.USERNAME                     OPERATORE_RESPONSABILE,
            SETT.NOME                            SETTORE,
            UTIL_ORG1.O_CODICE_ORG               O_CODICE_ORG,
            OPE.USERNAME                         operatore,
            UTIL_ORG1.O_CODICE_ORG               O_CODICE_ORG_TO,
            SETT2.NOME                           SETTORE_TO,
            OPE2.USERNAME                        operatore_to,
            IT.N_ORD
       FROM CS_A_CASO  C
            LEFT JOIN CS_D_DIARIO ITD ON ITD.CASO_ID = C.ID
            INNER JOIN
            (SELECT it.*,
                    D.DT_AMMINISTRATIVA,
                    D.DT_INS,
                    ROW_NUMBER () OVER (PARTITION BY d.caso_id ORDER BY d.id)    N_ORD
               FROM CS_IT_STEP it, CS_D_DIARIO d
              WHERE d.id = it.diario_id) IT
                ON ITD.ID = IT.DIARIO_ID
            LEFT JOIN CS_CFG_IT_STATO IT_STATO
                ON IT.CFG_IT_STATO_ID = IT_STATO.ID
            LEFT JOIN CS_O_ORGANIZZAZIONE O ON IT.ORGANIZZAZIONE_ID = O.ID
            LEFT JOIN cs_o_operatore ope ON IT.OPERATORE_ID = ope.id
            LEFT JOIN cs_o_operatore ope2 ON IT.OPERATORE_to = ope2.id
            LEFT JOIN cs_o_settore sett ON IT.settore_id = sett.id
            LEFT JOIN cs_o_settore sett2 ON IT.settore_ID_TO = sett2.id
            LEFT JOIN cs_o_ORGANIZZAZIONE ORG2
                ON IT.ORGANIZZAZIONE_ID_TO = ORG2.id
            LEFT JOIN cs_o_operatore operesp
                ON ITd.responsabile_id = operesp.id
            LEFT JOIN v_bi_tr_cs_an an ON it.caso_id = an.caso_id
            LEFT JOIN V_BI_UTIL_TIPO_ORG UTIL_ORG1
                ON o.ID = UTIL_ORG1.ID_ORGANIZZAZIONE
            LEFT JOIN V_BI_UTIL_TIPO_ORG UTIL_ORG2
                ON org2.ID = UTIL_ORG2.ID_ORGANIZZAZIONE);


DROP VIEW CS_ROMA.V_BI_TR_CS_OP;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_OP
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    CASO_ID,
    IDENTIFICATIVO_OPERATORE,
    DESCRIZIONE,
    O_FLAG_RESPONSABILE,
    O_DATA_INI_PIC,
    O_DATA_FINE_PIC,
    COGNOME_OPERATORE,
    NOME_OPERATORE,
    O_NOME_SETTORE,
    O_CODICE_ORG
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            'CS_OP'                             AS TIPO_RECORD,
            (SELECT nome FROM cs_o_zona_soc)    Z_ZONA_SOCIALE,
            an.CODICE_INVIANTE,
            S.CASO_ID,
            O.USERNAME                          IDENTIFICATIVO_OPERATORE,
            TIPO.DESCRIZIONE,
            COPE.FLAG_RESPONSABILE              O_FLAG_RESPONSABILE,
            TO_DATE (TO_CHAR (COPE.DATA_INIZIO_APP, 'dd/MM/yyyy'),
                     'dd/MM/yyyy')              O_DATA_INI_PIC,
            TO_DATE (TO_CHAR (COPE.DATA_FINE_APP, 'dd/MM/yyyy'),
                     'dd/MM/yyyy')              O_DATA_FINE_PIC,
            O.COGNOME                           COGNOME_OPERATORE,
            O.NOME                              NOME_OPERATORE,
            SETT.NOME                           O_NOME_SETTORE,
            ORG.O_CODICE_ORG
       FROM CS_A_SOGGETTO                  S,
            CS_A_CASO_OPE_TIPO_OPE         COPE,
            CS_O_OPERATORE_TIPO_OPERATORE  OT,
            CS_TB_TIPO_OPERATORE           TIPO,
            CS_O_OPERATORE_SETTORE         OS,
            CS_O_OPERATORE_ANAGRAFICA      O,
            CS_O_SETTORE                   SETT,
            v_bi_tr_cs_an                  an,
            V_BI_UTIL_TIPO_ORG             ORG
      WHERE     S.CASO_ID = COPE.CASO_ID
            AND COPE.OPERATORE_TIPO_OPERATORE_ID = OT.ID
            AND OT.TIPO_OPERATORE_ID = TIPO.ID
            AND OT.OPERATORE_SETTORE_ID = OS.ID
            AND OS.OPERATORE_ID = O.ID
            AND OS.SETTORE_ID = SETT.ID
            AND SETT.ORGANIZZAZIONE_ID = ORG.ID_ORGANIZZAZIONE
            AND S.CASO_ID = an.caso_id);


DROP VIEW CS_ROMA.V_BI_TR_CS_OR;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_OR
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    CASO_ID,
    O_NOME_SETTORE,
    O_TIPOLOGIA_SETTORE,
    O_CODICE_ORG,
    DATA_INIZIO,
    DATA_FINE
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            'CS_OR'                             AS TIPO_RECORD,
            (SELECT nome FROM cs_o_zona_soc)    Z_ZONA_SOCIALE,
            AN.CODICE_INVIANTE,
            S.CASO_ID,
            SETT.NOME                           O_NOME_SETTORE,
            DECODE (SETT.ID_SECONDO_LIVELLO,
                    NULL, 'SETTORE',
                    'SECONDOLIVELLO')           O_TIPOLOGIA_SETTORE,
            ORGLIV.O_CODICE_ORG,
            S.DATA_INIZIO_APP                   DATA_INIZIO,
            S.DATA_FINE_APP                     DATA_FINE
       FROM CS_A_CASO_ACCESSO_FASCICOLO  S
            LEFT JOIN CS_O_SETTORE SETT ON SETT.ID = S.ID_SETTORE
            LEFT JOIN V_BI_UTIL_TIPO_ORG ORGLIV
                ON S.ID_ORGANIZZAZIONE = ORGLIV.ID_ORGANIZZAZIONE
            LEFT JOIN v_bi_tr_cs_an an ON S.CASO_ID = AN.CASO_ID);


DROP VIEW CS_ROMA.V_BI_TR_CS_PAI;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_PAI
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    PAI_ID,
    PAI_CASO_ID,
    TIPO_PAI_ID,
    FF_PROGETTO_DESCRIZIONE,
    DATA_ATTIVAZIONE_PAI,
    DATA_CHIUSURA_PREVISTA,
    DATA_CHIUSURA,
    MOTIVO_CHIUSURA,
    FLAG_PROGETTO_PRESTAZIONALE,
    OBIETTIVI_RAGGIUNTI_BREVE,
    OBIETTIVI_RAGGIUNTI_MEDIO,
    OBIETTIVI_RAGGIUNTI_LUNGO,
    PAI_SETTORE_NOME,
    PAI_CODICE_ORG,
    PAI_OPERATORE,
    PAI_DATA_AGG,
    CITTADINANZA
)
BEQUEATH DEFINER
AS
    SELECT 'CS_PAI'
               AS TIPO_RECORD,
           (SELECT NOME FROM CS_O_ZONA_SOC)
               Z_ZONA_SOCIALE,
           AN.CODICE_INVIANTE,
           D.ID
               PAI_ID,
           D.CASO_ID
               PAI_CASO_ID,
           PAI.TIPO_PAI_ID
               TIPO_PAI_ID,
           NVL (pr.descrizione, 'Non specificato')
               FF_PROGETTO_DESCRIZIONE,
           D.DT_ATTIVAZIONE_DA
               DATA_ATTIVAZIONE_PAI,
           PAI.DATA_CHIUSURA_PREVISTA,
           D.DT_CHIUSURA_DA
               DATA_CHIUSURA,
           PAI.MOTIVO_CHIUSURA,
           DECODE (PAI.MONITORAGGIO_OBIETTIVI, 1, 'No', 'Si')
               FLAG_PROGETTO_PRESTAZIONALE,
           CASE
               WHEN PAI.MONITORAGGIO_OBIETTIVI = 1
               THEN
                   CASE
                       WHEN PAI.RAGGIUNTI_BREVE = 3 THEN 'SI'
                       WHEN PAI.RAGGIUNTI_BREVE = 2 THEN 'PARZIALMENTE'
                       WHEN PAI.RAGGIUNTI_BREVE = 1 THEN 'NO'
                   END
           END
               OBIETTIVI_RAGGIUNTI_BREVE,
           CASE
               WHEN PAI.MONITORAGGIO_OBIETTIVI = 1
               THEN
                   CASE
                       WHEN PAI.RAGGIUNTI_MEDIO = 3 THEN 'SI'
                       WHEN PAI.RAGGIUNTI_MEDIO = 2 THEN 'PARZIALMENTE'
                       WHEN PAI.RAGGIUNTI_MEDIO = 1 THEN 'NO'
                   END
           END
               OBIETTIVI_RAGGIUNTI_MEDIO,
           CASE
               WHEN PAI.MONITORAGGIO_OBIETTIVI = 1
               THEN
                   CASE
                       WHEN PAI.RAGGIUNTI_LUNGO = 3 THEN 'SI'
                       WHEN PAI.RAGGIUNTI_LUNGO = 2 THEN 'PARZIALMENTE'
                       WHEN PAI.RAGGIUNTI_LUNGO = 1 THEN 'NO'
                   END
           END
               OBIETTIVI_RAGGIUNTI_LUNGO,
           OS.SETTORE_NOME
               PAI_SETTORE_NOME,
           ORGLIV.O_CODICE_ORG
               PAI_CODICE_ORG,
           vopeana1.COGNOME || ' ' || vopeana1.NOME
               PAI_OPERATORE,
           NVL (D.DT_mod, d.dt_ins)
               PAI_DATA_AGG,
           DECODE (SOGG.cittadinanza,
                   'ITALIANA', '000',
                   NAZ.COD_ISTAT_NAZIONE)
               CITTADINANZA
      FROM cs_d_diario                d,
           cs_d_pai                   pai,
           CS_PAI_MAST_SOGG           sogg,
           AR_FF_PROGETTO             PR,
           cs_o_operatore_anagrafica  vopeana1,
           V_O_OPERATORI_SETTORI      OS,
           AM_TAB_NAZIONI             NAZ,
           V_BI_UTIL_TIPO_ORG         ORGLIV,
           v_bi_tr_cs_an              an
     WHERE     PAI.TIPO_PROGETTO_ID = pr.ID(+)
           AND D.CASO_ID = AN.CASO_ID(+)
           AND D.OPERATORE_SETTORE_ID = OS.OPERATORE_SETTORE_ID(+)
           AND OS.OPERATORE_ID = VOPEANA1.ID(+)
           AND SOGG.cittadinanza = naz.nazionalita(+)
           AND OS.ORGANIZZAZIONE_ID = ORGLIV.ID_ORGANIZZAZIONE(+)
           AND pai.diario_id = d.id
           AND D.TIPO_DIARIO_ID = 8
           AND pai.DIARIO_ID = SOGG.DIARIO_ID(+)
           AND NVL (SOGG.FLAG_INTESTATARIO, 0) = 1;


DROP VIEW CS_ROMA.V_BI_TR_PAI;

/* Formatted on 18/07/2022 12:23:36 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_PAI
(
    Z_ZONA_SOCIALE,
    ID_INVIANTE,
    PAI_ID,
    PAI_CASO_ID,
    TIPO_PAI_ID,
    FF_PROGETTO_DESCRIZIONE,
    FF_PROGETTO_CODICE,
    DATA_ATTIVAZIONE_PAI,
    DATA_CHIUSURA_PREVISTA,
    DATA_CHIUSURA,
    MOTIVO_CHIUSURA,
    CITTADINANZA,
    OBIETTIVI_RAGGIUNTI_BREVE,
    OBIETTIVI_RAGGIUNTI_MEDIO,
    OBIETTIVI_RAGGIUNTI_LUNGO,
    PAI_SETTORE_NOME,
    PAI_ORGANIZZAZIONE_NOME,
    PAI_OPERATORE,
    PAI_DATA_AGG
)
BEQUEATH DEFINER
AS
    SELECT (SELECT NOME FROM CS_O_ZONA_SOC)            Z_ZONA_SOCIALE,
           INV.ID_INVIANTE,
           D.ID                                        PAI_ID,
           D.CASO_ID                                   PAI_CASO_ID,
           PAI.TIPO_PAI_ID                             TIPO_PAI_ID,
           pr.descrizione                              FF_PROGETTO_DESCRIZIONE,
           PR.CODICE_MEMO                              FF_PROGETTO_CODICE,
           D.DT_ATTIVAZIONE_DA                         DATA_ATTIVAZIONE_PAI,
           PAI.DATA_CHIUSURA_PREVISTA,
           D.DT_CHIUSURA_DA                            DATA_CHIUSURA,
           PAI.MOTIVO_CHIUSURA,
           SOGG.CITTADINANZA,
           CASE
               WHEN PAI.RAGGIUNTI_BREVE = 3 THEN 'SI'
               WHEN PAI.RAGGIUNTI_BREVE = 2 THEN 'PARZIALMENTE'
               WHEN PAI.RAGGIUNTI_BREVE = 1 THEN 'NO'
           END                                         OBIETTIVI_RAGGIUNTI_BREVE,
           CASE
               WHEN PAI.RAGGIUNTI_MEDIO = 3 THEN 'SI'
               WHEN PAI.RAGGIUNTI_MEDIO = 2 THEN 'PARZIALMENTE'
               WHEN PAI.RAGGIUNTI_MEDIO = 1 THEN 'NO'
           END                                         OBIETTIVI_RAGGIUNTI_MEDIO,
           CASE
               WHEN PAI.RAGGIUNTI_LUNGO = 3 THEN 'SI'
               WHEN PAI.RAGGIUNTI_LUNGO = 2 THEN 'PARZIALMENTE'
               WHEN PAI.RAGGIUNTI_LUNGO = 1 THEN 'NO'
           END                                         OBIETTIVI_RAGGIUNTI_LUNGO,
           OS.SETTORE_NOME                             PAI_SETTORE_NOME,
           OS.ORGANIZZAZIONE_NOME                      PAI_ORGANIZZAZIONE_NOME,
           vopeana1.COGNOME || ' ' || vopeana1.NOME    PAI_OPERATORE,
           NVL (D.DT_mod, d.dt_ins)                    PAI_DATA_AGG
      FROM cs_d_diario                d,
           AR_FF_PROGETTO             PR,
           cs_d_pai                   pai,
           CS_PAI_MAST_SOGG           sogg,
           cs_o_operatore_anagrafica  vopeana1,
           V_BI_INVIANTE              INV,
           V_O_OPERATORI_SETTORI      OS
     WHERE     PAI.TIPO_PROGETTO_ID = pr.ID(+)
           AND INV.TIPO_INVIANTE = 'SISO'
           AND OS.ORGANIZZAZIONE_ID = INV.ID_ORGANIZZAZIONE
           AND D.OPERATORE_SETTORE_ID = OS.OPERATORE_SETTORE_ID(+)
           AND OS.OPERATORE_ID = VOPEANA1.ID(+)
           AND pai.diario_id = d.id
           AND D.TIPO_DIARIO_ID = 8
           AND pai.DIARIO_ID = SOGG.DIARIO_ID(+)
           AND NVL (SOGG.FLAG_INTESTATARIO, 0) = 1;


DROP VIEW CS_ROMA.V_BI_TR_PAIAFFIDO;

/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_PAIAFFIDO
(
    Z_ZONA_SOCIALE,
    ID_INVIANTE,
    PAI_ID,
    DATA_INIZIO_AFFIDO,
    DATA_TERMINE_AFFIDO,
    DATA_ANNULLAMENTO_AFFIDO,
    TIPOLOGIA_AFFIDO,
    AFFIDO_PROFESSIONALE,
    ADOTTABILE,
    NATURA_AFFIDO,
    ENTITA,
    FORME_AFFIDAMENTO,
    COLLOCAMENTO,
    PRESENZA_RETI_FAMIGLIE,
    IS_MINORE_ALLONTANATO,
    GENITORI_SCONOSCIUTI,
    FUORI_REGIONE,
    CONTATTI_CON_FO,
    AFFIDATARI,
    FA_CONOSCIUTA_DAL_MINORE,
    FA_FUORI_REGIONE,
    FA_BDF,
    OPERATORE_SETTORE_ID
)
BEQUEATH DEFINER
AS
    SELECT (SELECT NOME FROM CS_O_ZONA_SOC)
               Z_ZONA_SOCIALE,
           INV.ID_INVIANTE,
           DIARIO_PAI_ID
               PAI_ID,
           STATOINI.DATA_STATO_AFFIDO
               DATA_INIZIO_AFFIDO,
           statotermine.DATA_STATO_AFFIDO
               DATA_termine_AFFIDO,
           statoannull.DATA_STATO_AFFIDO
               DATA_ANNULLAMENTO_AFFIDO,
           DECODE (CODICE_TIPO_AFFIDO,
                   'TIPO_AFFIDO_ACCOGLIENZA', 'Accoglienza',
                   'TIPO_AFFIDO_FAMILIARE', 'Familiare')
               TIPOLOGIA_AFFIDO,
           AFFIDAMENTO_PROFESSIONALE
               AFFIDO_PROFESSIONALE,
           DECODE (CODICE_ADOTTABILE,
                   'ADOTTABILE_ATTESA_TRIBUNALE', '2',
                   'ADOTTABILE_SI', '1',
                   'ADOTTABILE_NO', '0')
               ADOTTABILE,
           DECODE (CODICE_NATURA_ACCOGLIENZA,
                   'NATURA_ACCOGLIENZA_GIUDIZIALE', 'Giudiziale',
                   'NATURA_ACCOGLIENZA_CONSENSUALE', 'Consensuale',
                   NULL)
               NATURA_AFFIDO,
           DECODE (
               CODICE_ENTITA_AFFIDO,
               'ENTITA_AFFIDO_DIURNO', 'Diurno',
               'ENTITA_AFFIDO_DIURNO_PARZIALE', 'Diurno Parziale',
               'ENTITA_AFFIDO_RESIDENZIALE', 'Residenziale (full time)',
               'ENTITA_AFFIDO_RESIDENZIALE_PARZIALE', 'Residenziale Parziale')
               ENTITA,
           --          DECODE (
           ----             CODICE_SITUAZIONI_PARTICOLARI,
           ----             'SITUAZIONI_PARTICOLARI_AUTONOMIA_GIOVANI', 'Affidamento in emergenza',
           ----             'SITUAZIONI_PARTICOLARI_EMERGENZA', 'Affidamento per l''autonomia dei giovani',
           ----             NULL)
           ----             situazioni_particolari,
           DECODE (
               CODICE_FORME_AFFIDAMENTO,
               'FORME_AFFIDAMENTO_COSOLIDATE_FAM_DISABILI', 'Affidamento familiare di disabili',
               'FORME_AFFIDAMENTO_COSOLIDATE_FAM_NEONATI', 'Affidamento familiare di neonati e bambini in tenera età (0-24 mesi)',
               'FORME_AFFIDAMENTO_COSOLIDATE_EMERGENZA', 'Affidamento in emergenza per bambini zero ? dodici anni',
               'FORME_AFFIDAMENTO_COSOLIDATE_ADOLESCENTI', 'Affidamento di adolescenti',
               'ALTRE_FORME_ACCOGLIENZA_GB', 'Accoglienza genitore ? bambino',
               'FORME_AFFIDAMENTO_COSOLIDATE_FAM_STRANIERI_NON_ACC', 'Affidamento familiare di minori stranieri non accompagnati',
               'FORME_AFFIDAMENTO_COSOLIDATE_FAM_STRANIERI_STESSAC', 'Affidamento di minori stranieri a famiglie della stessa cultura',
               'ALTRE_FORME_VICINATO_SOLIDALE', 'Vicinato solidale',
               'FORME_AFFIDAMENTO_COSOLIDATE_AUTONOMIA_GIOVANI', 'Affidamento per l?autonomia dei giovani',
               NULL)
               forme_affidamento,
           DECODE (
               CODICE_COLLOCAMENTO,
               'COLLOCAMENTO_ETERO_FAMILAIRE', 'Collocamento Etero-familiare ',
               'COLLOCAMENTO_INTRA_FAMILIARE_MATERNO', 'Collocamento Intra-familiare materno',
               'COLLOCAMENTO_INTRA_FAMILIARE_PATERNO', 'Collocamento Intra-familiare paterno')
               collocamento,
           presenza_reti_famiglie,
           --  DISABILITA_DURANTE_AFFIDO,
           --  STRANIERO_NON_ACCOMPAGNATO,
           --  STRANIERO_AFF_CULTURA,
           ORIG.IS_MINORE_ALLONTANATO,
           orig.GENITORI_SCONOSCIUTI,
           ORIG.FUORI_REGIONE,
           DECODE (
               codice_frequenza_contatti,
               'FREQUENZA_CONTATTI_SALTUARI', 'Saltuari',
               'FREQUENZA_CONTATTI_FREQUENTI', 'Frequenti (almeno mensili)',
               'FREQUENZA_CONTATTI_NESSUN_CONTATTO', 'Nessun Contatto',
               'FREQUENZA_CONTATTI_MOLTO_FREQUENTI', 'Molto frequenti (più volte a settimana)',
               NULL)
               CONTATTI_CON_FO,
           DECODE (CODICE_TIPO_FAMIGLIA,
                   'AFFIDATARI_SINGOLO_DONNA', 'Singolo donna',
                   'AFFIDATARI_SINGOLO_UOMO', 'Singolo uomo',
                   'AFFIDATARI_COPPIA', 'Coppia')
               AFFIDATARI,
           FAMAFF.CONOSCIUTA_DAL_MINORE
               FA_CONOSCIUTA_DAL_MINORE,
           FAMAFF.FUORI_REGIONE
               FA_FUORI_REGIONE,
           DECODE (FAMAFF.CODICE_BANCA_DATI_FAM,
                   'BANCA_DATI_FAMIGLIE_NON_INSERITA', 3,
                   'BANCA_DATI_FAMIGLIE_PRESENTE', 1,
                   'BANCA_DATI_FAMIGLIE_INSERITA', 2)
               FA_BDF,
           D.OPERATORE_SETTORE_ID
      FROM V_BI_INVIANTE  INV,
           CS_PAI_AFFIDO  AFF
           LEFT JOIN CS_D_DIARIO D ON (AFF.DIARIO_PAI_ID = D.ID)
           LEFT JOIN (SELECT *
                        FROM cs_pai_affido_stato
                       WHERE CODICE = '50') statoINI
               ON AFF.ID = STATOINI.PAI_AFFIDO_ID
           LEFT JOIN (SELECT *
                        FROM cs_pai_affido_stato
                       WHERE CODICE = '60') statotermine
               ON AFF.ID = statotermine.PAI_AFFIDO_ID
           LEFT JOIN (SELECT *
                        FROM cs_pai_affido_stato
                       WHERE CODICE = '70') statoannull
               ON AFF.ID = statoannull.PAI_AFFIDO_ID
           LEFT JOIN CS_PAI_AFFIDO_FAMIGLIA_ORIG ORIG
               ON ORIG.ID = AFF.FAM_ORIG_ID
           LEFT JOIN CS_PAI_AFFIDO_FAMIGLIA_AFF FAMAFF
               ON FAMAFF.ID = AFF.FAM_AFF_ID
           LEFT JOIN V_O_OPERATORI_SETTORI OS
               ON (D.OPERATORE_SETTORE_ID = OS.OPERATORE_SETTORE_ID)
     WHERE     INV.TIPO_INVIANTE = 'SISO'
           AND OS.ORGANIZZAZIONE_ID = INV.ID_ORGANIZZAZIONE;


DROP VIEW CS_ROMA.V_BI_TR_SA;

/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_SA
(
    Z_ZONA_SOCIALE,
    ID_INVIANTE,
    PK_SCHEDA_ID,
    O_CODICE_ORG,
    O_NOME_UFFICIO,
    O_PUNTO_DI_CONTATTO,
    S_COMPLETA,
    S_ELIMINATA,
    S_DATA,
    S_TIPO_INTERVENTO,
    S_MODALITA,
    S_MOTIVO,
    S_INTERLOCUTORE,
    U_STRANIERO_N_ACC,
    U_TELEFONO,
    U_CELLULARE,
    U_EMAIL,
    U_TESSERA_SANITARIA,
    U_MEDICO,
    U_STP,
    U_COND_LAVORO,
    U_TITOLO_STUDIO,
    U_CITTADINANZA,
    U_CITTADINANZA_2,
    U_COGNOME,
    CF,
    U_NOME,
    U_SESSO,
    U_COMUNE_NASCITA_COD,
    U_COMUNE_NASCITA_DES,
    U_DATA_NASCITA,
    U_PROV_NASCITA_COD,
    U_STATO_NASCITA_COD,
    U_STATO_NASCITA_DES,
    U_COMUNE_RES,
    U_VIA_RES,
    U_COMUNE_DOM,
    U_VIA_DOM,
    OPERATORE,
    UTENTE_ACCOMPAGNATO,
    UTENTE_PRESENTE_INFORMATO,
    I_COGNOME,
    I_NOME,
    I_AFFIDATARIO,
    I_RUOLO,
    SENZA_FISSA_DIMORA,
    ALIAS,
    CAT_SOCIALE_CODISTAT
)
BEQUEATH DEFINER
AS
    (SELECT (SELECT NOME FROM CS_O_ZONA_SOC)     Z_ZONA_SOCIALE,
            INV.ID_INVIANTE,
            A."PK_SCHEDA_ID",
            UTIL_ORG.O_CODICE_ORG,
            A."O_NOME_UFFICIO",
            A."O_PUNTO_DI_CONTATTO",
            A."S_COMPLETA",
            A."S_ELIMINATA",
            A."S_DATA",
            A."S_TIPO_INTERVENTO",
            A."S_MODALITA",
            A."S_MOTIVO",
            A."S_INTERLOCUTORE",
            A."U_STRANIERO_N_ACC",
            A."U_TELEFONO",
            A."U_CELLULARE",
            A."U_EMAIL",
            A."U_TESSERA_SANITARIA",
            A."U_MEDICO",
            A."U_STP",
            A."U_COND_LAVORO",
            A."U_TITOLO_STUDIO",
            A."U_CITTADINANZA",
            A."U_CITTADINANZA_2",
            A."U_COGNOME",
            A."CF",
            A."U_NOME",
            A."U_SESSO",
            A."U_COMUNE_NASCITA_COD",
            A."U_COMUNE_NASCITA_DES",
            A."U_DATA_NASCITA",
            A."U_PROV_NASCITA_COD",
            A."U_STATO_NASCITA_COD",
            A."U_STATO_NASCITA_DES",
            A."U_COMUNE_RES",
            A."U_VIA_RES",
            A."U_COMUNE_DOM",
            A."U_VIA_DOM",
            A."OPERATORE",
            A."UTENTE_ACCOMPAGNATO",
            A."UTENTE_PRESENTE_INFORMATO",
            A."I_COGNOME",
            A."I_NOME",
            A."I_AFFIDATARIO",
            A."I_RUOLO",
            A."SENZA_FISSA_DIMORA",
            A."ALIAS",
            A.CAT_SOCIALE_CODISTAT
       FROM V_BI_INVIANTE       INV,
            (SELECT S.ID
                        PK_SCHEDA_ID,
                    ORG.cod_routing
                        O_BELFIORE,
                    ORG.NOME
                        O_NOME_ORG,
                    U.NOME
                        O_NOME_UFFICIO,
                    PC.NOME
                        O_PUNTO_DI_CONTATTO,
                    S.COMPLETA
                        S_COMPLETA,
                    S.ELIMINATA
                        S_ELIMINATA,
                    SA.DATA
                        S_DATA,
                    TS.TIPO
                        S_TIPO_INTERVENTO,
                    SA.MODALITA
                        S_MODALITA,
                    SA.MOTIVO
                        S_MOTIVO,
                    SA.INTERLOCUTORE
                        S_INTERLOCUTORE,
                    SE.STRANIERO_N_ACC
                        U_STRANIERO_N_ACC,
                    TRIM (REPLACE (SE.TELEFONO, ';', ' '))
                        U_TELEFONO,
                    TRIM (REPLACE (SE.CEL, ';', ' '))
                        U_CELLULARE,
                    TRIM (REPLACE (SE.EMAIL, ';', ' '))
                        U_EMAIL,
                    SE.TESSERA_SANITARIA
                        U_TESSERA_SANITARIA,
                    SE.MEDICO
                        U_MEDICO,
                    STP
                        U_STP,
                    TBCL.DESCRIZIONE
                        U_COND_LAVORO,
                    TBTS.DESCRIZIONE
                        U_TITOLO_STUDIO,
                    --    NULL U_STATUS_GIURIDICO,
                    DECODE (N1.COD_ISTAT_NAZIONE,
                            '1', '100',
                            N1.COD_ISTAT_NAZIONE)
                        U_CITTADINANZA,
                    DECODE (N2.COD_ISTAT_NAZIONE,
                            '1', '100',
                            N2.COD_ISTAT_NAZIONE)
                        U_CITTADINANZA_2,
                    A.COGNOME
                        U_COGNOME,
                    TRIM (UPPER (A.CF))
                        CF,
                    A.NOME
                        U_NOME,
                    A.SESSO
                        U_SESSO,
                    -- TRUNC (MONTHS_BETWEEN (SYSDATE, A.data_nascita) / 12) U_ETA,
                    A.COMUNE_NASCITA_COD
                        U_COMUNE_NASCITA_COD,
                    A.COMUNE_NASCITA_DES
                        U_COMUNE_NASCITA_DES,
                    A.DATA_NASCITA
                        U_DATA_NASCITA,
                    A.PROV_NASCITA_COD
                        U_PROV_NASCITA_COD,
                    A.STATO_NASCITA_COD
                        U_STATO_NASCITA_COD,
                    A.STATO_NASCITA_DES
                        U_STATO_NASCITA_DES,
                    I.COMUNE_COD
                        U_COMUNE_RES,
                    I.VIA
                        U_VIA_RES,
                    D.COMUNE_COD
                        U_COMUNE_DOM,
                    D.VIA
                        U_VIA_DOM,
                    SA.OPERATORE,
                    SA.UTENTE_ACCOMPAGNATO,
                    SA.UTENTE_PRESENTE_INFORMATO,
                    SS.COGNOME
                        I_COGNOME,
                    SS.NOME
                        I_NOME,
                    SS.AFFIDATARIO
                        I_AFFIDATARIO,
                    SS.RUOLO
                        I_RUOLO,
                    SE.SENZA_FISSA_DIMORA,
                    A.ALIAS,
                    ORG.ID
                        ID_ORGANIZZAZIONE,
                    CSOC.CATEGORIA_SOCIALE_ID
                        CAT_SOCIALE_CODISTAT
               FROM ss_scheda  s
                    INNER JOIN ss_scheda_accesso sa ON S.ACCESSO = sa.id
                    LEFT JOIN SS_REL_SCHEDA_CAT_SOC csoc
                        ON CSOC.SCHEDA_ID = S.ID
                    LEFT JOIN SS_SCHEDA_SEGNALANTE SS ON s.segnalante = ss.id
                    LEFT JOIN ss_tipo_scheda ts ON S.TIPO = TS.ID
                    LEFT JOIN cs_o_organizzazione org
                        ON org.ID = SA.REL_UPO_ORGANIZZAZIONE_ID
                    LEFT JOIN ss_ufficio u ON U.ID = SA.REL_UPO_UFFICIO_ID
                    LEFT JOIN ss_punto_contatto pc
                        ON PC.ID = SA.REL_UPO_PUNTO_CONTATTO_ID
                    LEFT JOIN SS_SCHEDA_SEGNALATO SE ON S.SEGNALATO = SE.ID
                    LEFT JOIN SS_ANAGRAFICA A ON SE.ANAGRAFICA = A.ID
                    LEFT JOIN am_tab_nazioni n1
                        ON (    a.CITTADINANZA = n1.nazionalita
                            AND n1.attivo = 1
                            AND n1.nazionalita_principale = 1)
                    LEFT JOIN am_tab_nazioni n2
                        ON (    a.CITTADINANZA_2 = n2.nazionalita
                            AND n2.attivo = 1
                            AND n2.nazionalita_principale = 1)
                    LEFT JOIN ss_indirizzo i ON se.RESIDENZA = I.ID
                    LEFT JOIN ss_indirizzo d ON se.domicilio = d.id
                    LEFT JOIN CS_TB_COND_LAVORO TBCL ON SE.LAVORO = TBCL.ID
                    LEFT JOIN CS_TB_TITOLO_STUDIO TBTS
                        ON SE.TITOLO_STUDIO_ID = TBTS.ID) a,
            V_BI_UTIL_TIPO_ORG  UTIL_ORG
      WHERE     INV.TIPO_INVIANTE = 'SISO'
            AND A.ID_ORGANIZZAZIONE = INV.ID_ORGANIZZAZIONE
            AND A.ID_ORGANIZZAZIONE = UTIL_ORG.ID_ORGANIZZAZIONE);


DROP VIEW CS_ROMA.V_CARTSOC_DETT_TRIB;

/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_CARTSOC_DETT_TRIB
(
    CHIAVE,
    ZONA_SOCIALE,
    BELFIORE,
    IDENTIFICATIVO,
    ID,
    "DATA APERTURA",
    "ANNO APERTURA",
    "MESE APERTURA",
    "DATA ITER",
    "ANNO ITER",
    "MESE ITER",
    "Cognome - Nome",
    CF,
    COMUNE,
    "CATEGORIA SOCIALE",
    SETTORE,
    "STATO CARTELLA",
    OPERATORE,
    RESPONSABILE,
    "cf operatore",
    "tipo operatore",
    DATA_INIZIO_APP,
    DATA_FINE_APP,
    TRIBUNALE,
    UFFICIO,
    ZONA_SOCIALE_DESC,
    TRIB_TM_CIVILE,
    TRIB_TM_AMMINISTRATIVO,
    TRIB_PENALE_MINORILE,
    TRIB_T_O,
    TRIB_PROCURA_MINORILE,
    SOMMA_TRIB,
    ULTIMO_ANNO_PIC,
    PRIMO_ANNO_PIC,
    ID_ORG,
    CODICE_ORG
)
BEQUEATH DEFINER
AS
    (SELECT A."CHIAVE",
            A."ZONA_SOCIALE",
            A."BELFIORE",
            A."IDENTIFICATIVO",
            A."ID",
            A."DATA APERTURA",
            A."ANNO APERTURA",
            A."MESE APERTURA",
            A."DATA ITER",
            A."ANNO ITER",
            A."MESE ITER",
            A."Cognome - Nome",
            A."CF",
            A."COMUNE",
            A."CATEGORIA SOCIALE",
            A."SETTORE",
            A."STATO CARTELLA",
            A."OPERATORE",
            A."RESPONSABILE",
            A."cf operatore",
            A."tipo operatore",
            A."DATA_INIZIO_APP",
            A."DATA_FINE_APP",
            A."TRIBUNALE",
            A."UFFICIO",
            A."ZONA_SOCIALE_DESC",
            A."TRIB_TM_CIVILE",
            A."TRIB_TM_AMMINISTRATIVO",
            A."TRIB_PENALE_MINORILE",
            A."TRIB_T_O",
            A."TRIB_PROCURA_MINORILE",
            a.somma_trib,
            TO_CHAR (b.data_iter, 'YYYY')     ULTIMO_ANNO_pic,
            TO_CHAR (c.data_iter, 'YYYY')     PRIMO_ANNO_pic,
            A.ID_ORG,
            A.CODICE_ORG
       FROM (SELECT DISTINCT
                    c.ID || '-' || (SELECT NOME FROM CS_O_ZONA_SOC)
                        CHIAVE,
                    (SELECT B.ID
                       FROM CS_O_ZONA_SOC A, ARBI_D_ZONA_SOC B
                      WHERE A.NOME = B.NOME)
                        ZONA_SOCIALE,
                    CASI.O_ORG_BELFIORE
                        BELFIORE,
                    C.IDENTIFICATIVO,
                    C.ID,
                    C.DT_INS
                        "DATA APERTURA",
                    EXTRACT (YEAR FROM C.DT_INS)
                        "ANNO APERTURA",
                    EXTRACT (MONTH FROM C.DT_INS)
                        "MESE APERTURA",
                    CASI.IT_ULTIMO_STATO_ITER_DATA
                        "DATA ITER",
                    EXTRACT (YEAR FROM CASI.IT_ULTIMO_STATO_ITER_DATA)
                        "ANNO ITER",
                    EXTRACT (MONTH FROM CASI.IT_ULTIMO_STATO_ITER_DATA)
                        "MESE ITER",
                    A.COGNOME || ' ' || A.NOME
                        "Cognome - Nome",
                    A.CF,
                    CASI.O_ORG_NOME
                        COMUNE,
                    CAT.DESCRIZIONE
                        "CATEGORIA SOCIALE",
                    CASI.O_SETTORE_NOME
                        "SETTORE",
                    casi.IT_ULTIMO_STATO_CASO
                        "STATO CARTELLA",
                    AMA.COGNOME || ' ' || AMA.NOME
                        "OPERATORE",
                    COPE.FLAG_RESPONSABILE
                        "RESPONSABILE",
                    OPER.USERNAME
                        "cf operatore",
                    TIPOP.DESCRIZIONE
                        "tipo operatore",
                    NVL (COPE.DATA_INIZIO_APP,
                         TO_DATE ('01/01/1000', 'dd/MM/yyyy'))
                        DATA_INIZIO_APP,
                    NVL (COPE.DATA_FINE_APP,
                         TO_DATE ('01/01/1000', 'dd/MM/yyyy'))
                        DATA_FINE_APP,
                    tri.id
                        tribunale,
                    OPER.TOOLTIP
                        UFFICIO,
                    (SELECT a.NOME
                       FROM CS_O_ZONA_SOC A)
                        ZONA_SOCIALE_DESC,
                    CASE WHEN TRI.TM_CIVILE = 1 THEN 1 ELSE 0 END
                        TRIB_TM_CIVILE,
                    CASE WHEN TRI.TM_AMM = 1 THEN 1 ELSE 0 END
                        TRIB_TM_AMMINISTRATIVO,
                    CASE WHEN TRI.PENALE_MIN = 1 THEN 1 ELSE 0 END
                        TRIB_PENALE_MINORILE,
                    CASE WHEN TRI.TO_FLG = 1 THEN 1 ELSE 0 END
                        TRIB_T_O,
                    CASE WHEN TRI.PROCURA_MIN = 1 THEN 1 ELSE 0 END
                        TRIB_PROCURA_MINORILE,
                    (  CASE WHEN TRI.TM_CIVILE = 1 THEN 1 ELSE 0 END
                     + CASE WHEN TRI.TM_AMM = 1 THEN 1 ELSE 0 END
                     + CASE WHEN TRI.PENALE_MIN = 1 THEN 1 ELSE 0 END
                     + CASE WHEN TRI.TO_FLG = 1 THEN 1 ELSE 0 END
                     + CASE WHEN TRI.PROCURA_MIN = 1 THEN 1 ELSE 0 END)
                        somma_trib,
                    CASI.ID_ORG,
                    CASI.CODICE_ORG
               FROM cs_a_soggetto                  s,
                    cs_a_anagrafica                a,
                    cs_a_caso                      c,
                    cs_a_soggetto_categoria_soc    sc,
                    cs_c_categoria_sociale         cat,
                    CS_A_CASO_OPE_TIPO_OPE         COPE,
                    CS_A_CASO_OPE_TIPO_OPE2        COPE2,
                    CS_O_OPERATORE_tipo_operatore  opetope,
                    cs_o_operatore_settore         os,
                    cs_o_operatore                 oper,
                    cs_tb_tipo_operatore           tipop,
                    V_AM_ANAGRAFICA                AMA,
                    v_t0_casi                      casi,
                    CS_A_TRIBUNALE                 tri
              WHERE     S.ANAGRAFICA_ID = A.ID
                    AND S.CASO_ID = C.ID
                    AND A.ID = SC.SOGGETTO_ANAGRAFICA_ID
                    AND SC.CATEGORIA_SOCIALE_ID = CAT.ID
                    AND C.ID = COPE.CASO_ID(+)
                    AND C.ID = COPE2.CASO_ID(+)
                    AND COPE.OPERATORE_TIPO_OPERATORE_ID = OPETOPE.ID(+)
                    AND OPETOPE.OPERATORE_SETTORE_ID = OS.ID(+)
                    AND OS.OPERATORE_ID = OPER.ID(+)
                    AND OPETOPE.TIPO_OPERATORE_ID = tipop.id(+)
                    AND OPER.USERNAME = AMA.FK_AM_USER(+)
                    AND S.CASO_ID = casi.pk_t0_caso_id
                    AND SC.SOGGETTO_ANAGRAFICA_ID =
                        tri.soggetto_anagrafica_id(+)
                    AND SC.PREVALENTE = 1
                    AND (   tri.id IS NULL
                         OR tri.id =
                            (SELECT MAX (tt.id)
                               FROM CS_A_TRIBUNALE tt
                              WHERE tt.soggetto_anagrafica_id =
                                    tri.soggetto_anagraficA_id))) a
            LEFT JOIN ((  SELECT MAX (DATA_ITER) data_iter, CASO_Id, it2.STATO
                            FROM V_T5_ITER it2
                           WHERE IT2.STATO = 'Presa In Carico'
                        GROUP BY caso_id, STATO)) b
                ON a.id = b.caso_id
            LEFT JOIN ((  SELECT MIN (DATA_ITER) data_iter, CASO_Id, it3.STATO
                            FROM V_T5_ITER it3
                           WHERE IT3.STATO = 'Presa In Carico'
                        GROUP BY caso_id, STATO)) c
                ON a.id = c.caso_id);


DROP VIEW CS_ROMA.V_CS_UNITA_CRISI;

/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_CS_UNITA_CRISI
(
    "Cognome e Nome",
    CF,
    INDIRIZZO,
    "Telefono - Cellulare",
    COMUNE,
    UFFICIO,
    "Assistente Sociale",
    "Stato Cartella",
    "Data Stato cartella",
    ZONA_SOCIALE,
    BELFIORE,
    MOTIVO_CHIUSURA
)
BEQUEATH DEFINER
AS
    SELECT UNO."Cognome e Nome",
           UNO."CF",
           UNO."INDIRIZZO",
           UNO."Telefono - Cellulare",
           UNO."COMUNE",
           UNO."UFFICIO",
           UNO."Assistente Sociale",
           UNO."Stato Cartella",
           UNO."Data Stato cartella",
           UNO."ZONA_SOCIALE",
           UNO."BELFIORE",
           DECODE (UNO."Stato Cartella", 'CHIUSO', DUE.VALORE, NULL)    MOTIVO_CHIUSURA
      FROM (SELECT DISTINCT
                   UPPER (aaa."Cognome - Nome")
                       "Cognome e Nome",
                   aaa.CF,
                   UPPER (aaa.INDIRIZZO) || ' ,' || aaa.civico_numero
                       Indirizzo,
                   TRIM (
                          UPPER (aaa.tel)
                       || ' '
                       || aaa.TIT_TELEFONO
                       || '    '
                       || aaa.CELL
                       || ' '
                       || aaa.TIT_CELLULARE)
                       "Telefono - Cellulare",
                   UPPER (aaa.comune)
                       Comune,
                   UPPER (aaa.SETTORE)
                       Ufficio,
                   UPPER (aaa.operatore)
                       "Assistente Sociale",
                   UPPER (aaa."STATO CARTELLA")
                       "Stato Cartella",
                   UPPER (aaa."DATA ITER")
                       "Data Stato cartella",
                   aaa.ZONA_SOCIALE,
                   aaa.BELFIORE
              FROM (SELECT DISTINCT A."CHIAVE",
                                    A."ZONA_SOCIALE",
                                    A."BELFIORE",
                                    A."IDENTIFICATIVO",
                                    A."ID",
                                    A."DATA APERTURA",
                                    A."ANNO APERTURA",
                                    A."MESE APERTURA",
                                    A."DATA ITER",
                                    A."ANNO ITER",
                                    A."MESE ITER",
                                    A."Cognome - Nome",
                                    A.INDIRIZZO,
                                    A.civico_numero,
                                    A."CF",
                                    A."DATA_NASCITA",
                                    A."C_ETA",
                                    A."ETA",
                                    A.TEL,
                                    A.TIT_TELEFONO,
                                    A.CELL,
                                    A.TIT_CELLULARE,
                                    A."CITTADINANZA",
                                    A."COMUNE",
                                    A."CATEGORIA SOCIALE",
                                    A."SETTORE",
                                    A."STATO CARTELLA",
                                    A."OPERATORE",
                                    A."RESPONSABILE",
                                    A."cf operatore",
                                    A."tipo operatore",
                                    A."DATA_INIZIO_APP",
                                    A."DATA_FINE_APP",
                                    A."UFFICIO",
                                    A."ZONA_SOCIALE_DESC"
                      FROM (SELECT DISTINCT
                                      c.ID
                                   || '-'
                                   || (SELECT NOME FROM CS_O_ZONA_SOC)
                                       CHIAVE,
                                   (SELECT NOME FROM CS_O_ZONA_SOC)
                                       ZONA_SOCIALE,
                                   CASI.O_ORG_BELFIORE
                                       BELFIORE,
                                   C.IDENTIFICATIVO,
                                   C.ID,
                                   C.DT_INS
                                       "DATA APERTURA",
                                   EXTRACT (YEAR FROM C.DT_INS)
                                       "ANNO APERTURA",
                                   EXTRACT (MONTH FROM C.DT_INS)
                                       "MESE APERTURA",
                                   CASI.IT_ULTIMO_STATO_ITER_DATA
                                       "DATA ITER",
                                   EXTRACT (
                                       YEAR FROM CASI.IT_ULTIMO_STATO_ITER_DATA)
                                       "ANNO ITER",
                                   EXTRACT (
                                       MONTH FROM CASI.IT_ULTIMO_STATO_ITER_DATA)
                                       "MESE ITER",
                                   A.COGNOME || ' ' || A.NOME
                                       "Cognome - Nome",
                                   AIND.INDIRIZZO,
                                   AIND.CIVICO_NUMERO,
                                   A.CF,
                                   A.DATA_NASCITA,
                                   A.TEL,
                                   A.TIT_TELEFONO,
                                   A.TIT_CELLULARE,
                                   A.CELL,
                                   TRUNC (
                                         MONTHS_BETWEEN (SYSDATE,
                                                         a.data_nascita)
                                       / 12)
                                       C_ETA,
                                   CASE
                                       WHEN TRUNC (
                                                  MONTHS_BETWEEN (
                                                      SYSDATE,
                                                      a.data_nascita)
                                                / 12) <
                                            18
                                       THEN
                                           'MINORENNE'
                                       ELSE
                                           'MAGGIORENNE'
                                   END
                                       ETA,
                                   CASE
                                       WHEN A.CITTADINANZA = 'ITALIANA'
                                       THEN
                                           'ITALIANA'
                                       ELSE
                                           'STRANIERA'
                                   END
                                       CITTADINANZA,
                                   CASI.O_ORG_NOME
                                       COMUNE,
                                   CAT.DESCRIZIONE
                                       "CATEGORIA SOCIALE",
                                   CASI.O_SETTORE_NOME
                                       "SETTORE",
                                   casi.IT_ULTIMO_STATO_CASO
                                       "STATO CARTELLA",
                                   AMA.COGNOME || ' ' || AMA.NOME
                                       "OPERATORE",
                                   COPE.FLAG_RESPONSABILE
                                       "RESPONSABILE",
                                   OPER.USERNAME
                                       "cf operatore",
                                   TIPOP.DESCRIZIONE
                                       "tipo operatore",
                                   NVL (COPE.DATA_INIZIO_APP,
                                        TO_DATE ('01/01/1000', 'dd/MM/yyyy'))
                                       DATA_INIZIO_APP,
                                   NVL (COPE.DATA_FINE_APP,
                                        TO_DATE ('01/01/1000', 'dd/MM/yyyy'))
                                       DATA_FINE_APP,
                                   OPER.TOOLTIP
                                       UFFICIO,
                                   (SELECT a.NOME
                                      FROM CS_O_ZONA_SOC A)
                                       ZONA_SOCIALE_DESC
                              FROM cs_a_soggetto                  s,
                                   cs_a_anagrafica                a,
                                   CS_A_INDIRIZZO                 IND,
                                   CS_A_ANA_INDIRIZZO             AIND,
                                   cs_a_caso                      c,
                                   cs_a_soggetto_categoria_soc    sc,
                                   cs_c_categoria_sociale         cat,
                                   CS_A_CASO_OPE_TIPO_OPE         COPE,
                                   --  CS_A_CASO_OPE_TIPO_OPE2 COPE2,
                                   CS_O_OPERATORE_tipo_operatore  opetope,
                                   cs_o_operatore_settore         os,
                                   cs_o_operatore                 oper,
                                   cs_tb_tipo_operatore           tipop,
                                   V_AM_ANAGRAFICA                AMA,
                                   v_t0_casi                      casi
                             WHERE     S.ANAGRAFICA_ID = A.ID
                                   AND S.CASO_ID = C.ID
                                   AND A.ID(+) = ind.SOGGETTO_ANAGRAFICA_ID
                                   AND IND.ANA_INDIRIZZO_ID(+) = AIND.ID
                                   AND A.ID = SC.SOGGETTO_ANAGRAFICA_ID
                                   AND SC.CATEGORIA_SOCIALE_ID = CAT.ID
                                   AND C.ID = COPE.CASO_ID(+)
                                   --    AND C.ID = COPE2.CASO_ID(+)
                                   AND COPE.OPERATORE_TIPO_OPERATORE_ID =
                                       OPETOPE.ID(+)
                                   AND OPETOPE.OPERATORE_SETTORE_ID =
                                       OS.ID(+)
                                   AND OS.OPERATORE_ID = OPER.ID(+)
                                   AND OPETOPE.TIPO_OPERATORE_ID =
                                       tipop.id(+)
                                   AND OPER.USERNAME = AMA.FK_AM_USER(+)
                                   AND S.CASO_ID = casi.pk_t0_caso_id
                                   AND SC.PREVALENTE = 1) A) aaa
             WHERE aaa.responsabile = 1) UNO,
           (SELECT A.CF, D.VALORE
              FROM CS_A_ANAGRAFICA        A,
                   cs_A_SOGGETTO          B,
                   CS_IT_STEP             C,
                   CS_IT_STEP_ATTR_VALUE  D
             WHERE     A.ID = B.ANAGRAFICA_ID
                   AND B.CASO_ID = C.CASO_ID
                   AND C.CFG_IT_STATO_ID = 2
                   AND C.ID = D.IT_STEP_ID
                   AND D.CFG_ATTR_ID = 1) DUE
     WHERE UNO.CF = DUE.CF(+);


DROP VIEW CS_ROMA.V_EROG_CARATTERE;

/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_EROG_CARATTERE
(
    FLAG_CARATTERE_PRESTAZIONE,
    FLAG_EROGAZIONE_CHIUSA,
    SPESA_DETTAGLIO,
    COMPART_UTENTI_DETTAGLIO,
    COMPART_SSN_DETTAGLIO,
    N_RIGHE_EROGATE_TIPOE,
    ID,
    USER_INS,
    DT_INS,
    USR_MOD,
    DT_MOD,
    TIPO_INTERVENTO_ID,
    INTERVENTO_ID,
    TIPO_INTERVENTO_CUSTOM_ID,
    DESC_INTERVENTO_ESEG,
    SPESA,
    PERC_GESTITA_ENTE,
    VALORE_GESTITA_ENTE,
    COMPART_UTENTI,
    COMPART_SSN,
    COMPART_ALTRE,
    NOTE_ALTRE_COMPART,
    FF_ORIGINE_ID,
    CODICE_FIN1,
    CATEGORIA_SOCIALE_ID,
    FLAG_SPESA_CALC,
    OPERATORE_SETTORE_ID,
    TIPO_BENEFICIARIO,
    QUOTA_ID,
    PROT_DOM_PREST,
    SETTORE_EROGANTE_ID,
    SETTORE_TITOLARE_ID,
    FF_PROGETTO_DESCRIZIONE,
    COD_PRESTAZIONE
)
BEQUEATH DEFINER
AS
    SELECT CASE
               WHEN     N_RIGHE_EROGATE_TIPOE = 1
                    AND FLAG_EROGAZIONE_CHIUSA = '1'
                    AND FLAG_REGOLARE <> 1
               THEN
                   'OCCASIONALE'
               WHEN N_RIGHE_EROGATE_TIPOE >= 1
               THEN
                   'PERIODICA'
               ELSE
                   NULL
           END    FLAG_CARATTERE_PRESTAZIONE,
           SEL2."FLAG_EROGAZIONE_CHIUSA",
           SEL2."SPESA_DETTAGLIO",
           SEL2."COMPART_UTENTI_DETTAGLIO",
           SEL2."COMPART_SSN_DETTAGLIO",
           SEL2."N_RIGHE_EROGATE_TIPOE",
           SEL2."ID",
           SEL2."USER_INS",
           SEL2."DT_INS",
           SEL2."USR_MOD",
           SEL2."DT_MOD",
           SEL2."TIPO_INTERVENTO_ID",
           SEL2."INTERVENTO_ID",
           SEL2."TIPO_INTERVENTO_CUSTOM_ID",
           SEL2."DESC_INTERVENTO_ESEG",
           SEL2."SPESA",
           SEL2."PERC_GESTITA_ENTE",
           SEL2."VALORE_GESTITA_ENTE",
           SEL2."COMPART_UTENTI",
           SEL2."COMPART_SSN",
           SEL2."COMPART_ALTRE",
           SEL2."NOTE_ALTRE_COMPART",
           SEL2."FF_ORIGINE_ID",
           SEL2."CODICE_FIN1",
           SEL2."CATEGORIA_SOCIALE_ID",
           SEL2."FLAG_SPESA_CALC",
           SEL2."OPERATORE_SETTORE_ID",
           SEL2."TIPO_BENEFICIARIO",
           SEL2."QUOTA_ID",
           SEL2."PROT_DOM_PREST",
           SEL2."SETTORE_EROGANTE_ID",
           SEL2."SETTORE_TITOLARE_ID",
           SEL2."FF_PROGETTO_DESCRIZIONE",
           SEL2."COD_PRESTAZIONE"
      FROM (SELECT DECODE (
                       (SELECT COUNT (*)
                          FROM cs_i_intervento_eseg  eseg
                               INNER JOIN cs_cfg_int_eseg_stato stato
                                   ON stato.id = eseg.stato_id
                         WHERE     eseg.INTERVENTO_eSEG_mast_ID = SEL.id
                               AND stato.FLAG_CHIUDI = '1'),
                       0, '0',
                       '1')
                       FLAG_EROGAZIONE_CHIUSA,
                   (SELECT SUM (spesa)
                      FROM cs_i_intervento_eseg eseg
                     WHERE eseg.INTERVENTO_eSEG_mast_ID = SEL.id)
                       SPESA_DETTAGLIO,
                   (SELECT SUM (COMPART_UTENTI)
                      FROM cs_i_intervento_eseg eseg
                     WHERE eseg.INTERVENTO_eSEG_mast_ID = SEL.id)
                       COMPART_UTENTI_DETTAGLIO,
                   (SELECT SUM (COMPART_SSN)
                      FROM cs_i_intervento_eseg eseg
                     WHERE eseg.INTERVENTO_eSEG_mast_ID = SEL.id)
                       COMPART_SSN_DETTAGLIO,
                   SEL.*
              FROM (SELECT (SELECT COUNT (*)
                              FROM cs_i_intervento_eseg  eseg
                                   INNER JOIN cs_cfg_int_eseg_stato stato
                                       ON stato.id = eseg.stato_id
                             WHERE     eseg.INTERVENTO_eSEG_mast_ID = mast.id
                                   AND stato.tipo = 'E')
                               N_RIGHE_EROGATE_TIPOE,
                           QR.FLAG_REGOLARE,
                           MAST.*
                      FROM V_EROG_MAST_PR  mast
                           LEFT JOIN cs_i_quota_ripartiz qr
                               ON QR.QUOTA_ID = MAST.QUOTA_ID) SEL) SEL2;


DROP VIEW CS_ROMA.V_EROG_EXPORT_HELP;

/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_EROG_EXPORT_HELP
(
    TIPO_EXPORT,
    MIN_DATA_EROGAZIONE,
    MAX_DATA_EROGAZIONE,
    MIN_DATA_EROGAZIONE_A,
    MAX_DATA_EROGAZIONE_A,
    VALORE_GESTITA_ENTE_CALC,
    FLAG_CARATTERE_PRESTAZIONE,
    FLAG_EROGAZIONE_CHIUSA,
    SPESA_DETTAGLIO,
    COMPART_UTENTI_DETTAGLIO,
    COMPART_SSN_DETTAGLIO,
    N_RIGHE_EROGATE_TIPOE,
    ID,
    USER_INS,
    DT_INS,
    USR_MOD,
    DT_MOD,
    TIPO_INTERVENTO_ID,
    INTERVENTO_ID,
    TIPO_INTERVENTO_CUSTOM_ID,
    DESC_INTERVENTO_ESEG,
    SPESA,
    PERC_GESTITA_ENTE,
    VALORE_GESTITA_ENTE,
    COMPART_UTENTI,
    COMPART_SSN,
    COMPART_ALTRE,
    NOTE_ALTRE_COMPART,
    FF_ORIGINE_ID,
    CODICE_FIN1,
    CATEGORIA_SOCIALE_ID,
    FLAG_SPESA_CALC,
    OPERATORE_SETTORE_ID,
    TIPO_BENEFICIARIO,
    QUOTA_ID,
    PROT_DOM_PREST,
    SETTORE_EROGANTE_ID,
    SETTORE_TITOLARE_ID,
    FF_PROGETTO_DESCRIZIONE,
    COD_PRESTAZIONE
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT
           CASE
               WHEN     FLAG_CARATTERE_PRESTAZIONE = 'PERIODICA'
                    AND FLAG_EROGAZIONE_CHIUSA = '1'
               THEN
                   CASE
                       WHEN SPESA_DETTAGLIO IS NULL
                       THEN
                           'EXPORT_MASTER'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NULL
                            AND COMPART_UTENTI IS NULL
                       THEN
                           'EXPORT_RIGHE'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NULL
                            AND COMPART_UTENTI IS NOT NULL
                       THEN
                           'EXPORT_MASTER'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NULL
                       THEN
                           'EXPORT_RIGHE'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NOT NULL
                       THEN
                           'EXPORT_RIGHE'
                       ELSE
                           'ANOMALIA1'
                   END
               WHEN     FLAG_CARATTERE_PRESTAZIONE = 'PERIODICA'
                    AND FLAG_EROGAZIONE_CHIUSA = '0'
               THEN
                   CASE
                       WHEN SPESA_DETTAGLIO IS NULL
                       THEN
                           'TO_CLOSE'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NULL
                            AND COMPART_UTENTI IS NULL
                       THEN
                           'EXPORT_RIGHE'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NULL
                            AND COMPART_UTENTI IS NOT NULL
                       THEN
                           'TO_CLOSE'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NULL
                       THEN
                           'EXPORT_RIGHE'
                       WHEN     SPESA_DETTAGLIO IS NOT NULL
                            AND COMPART_UTENTI_DETTAGLIO IS NOT NULL
                       THEN
                           'EXPORT_RIGHE'
                       ELSE
                           'ANOMALIA2'
                   END
               WHEN FLAG_CARATTERE_PRESTAZIONE = 'OCCASIONALE'
               THEN
                   'EXPORT_MASTER'
           END
               TIPO_EXPORT,
           (SELECT MIN (DATA_ESECUZIONE)
              FROM CS_I_INTERVENTO_ESEG  ES
                   INNER JOIN cs_cfg_int_eseg_stato stato
                       ON stato.id = es.stato_id
             WHERE     ES.INTERVENTO_ESEG_MAST_ID = VC.ID
                   AND STATO.tipo = 'E')
               MIN_DATA_EROGAZIONE,
           (SELECT MAX (DATA_ESECUZIONE)
              FROM CS_I_INTERVENTO_ESEG  ES
                   INNER JOIN cs_cfg_int_eseg_stato stato
                       ON stato.id = es.stato_id
             WHERE     ES.INTERVENTO_ESEG_MAST_ID = VC.ID
                   AND STATO.TIPO = 'E')
               MAX_DATA_EROGAZIONE,
           (SELECT MIN (DATA_ESECUZIONE_a)
              FROM CS_I_INTERVENTO_ESEG  ES
                   INNER JOIN cs_cfg_int_eseg_stato stato
                       ON stato.id = es.stato_id
             WHERE     ES.INTERVENTO_ESEG_MAST_ID = VC.ID
                   AND STATO.tipo = 'E')
               MIN_DATA_EROGAZIONE_A,
           (SELECT MAX (DATA_ESECUZIONE_a)
              FROM CS_I_INTERVENTO_ESEG  ES
                   INNER JOIN cs_cfg_int_eseg_stato stato
                       ON stato.id = es.stato_id
             WHERE     ES.INTERVENTO_ESEG_MAST_ID = VC.ID
                   AND STATO.tipo = 'E')
               MAX_DATA_EROGAZIONE_A,
           NVL (VALORE_GESTITA_ENTE,
                VC.SPESA * PERC_GESTITA_ENTE / 100)
               VALORE_GESTITA_ENTE_CALC,
           VC."FLAG_CARATTERE_PRESTAZIONE",
           VC."FLAG_EROGAZIONE_CHIUSA",
           VC."SPESA_DETTAGLIO",
           VC."COMPART_UTENTI_DETTAGLIO",
           VC."COMPART_SSN_DETTAGLIO",
           VC."N_RIGHE_EROGATE_TIPOE",
           VC."ID",
           VC."USER_INS",
           VC."DT_INS",
           VC."USR_MOD",
           VC."DT_MOD",
           VC."TIPO_INTERVENTO_ID",
           VC."INTERVENTO_ID",
           VC."TIPO_INTERVENTO_CUSTOM_ID",
           VC."DESC_INTERVENTO_ESEG",
           VC."SPESA",
           VC."PERC_GESTITA_ENTE",
           VC."VALORE_GESTITA_ENTE",
           VC."COMPART_UTENTI",
           VC."COMPART_SSN",
           VC."COMPART_ALTRE",
           VC."NOTE_ALTRE_COMPART",
           VC."FF_ORIGINE_ID",
           VC."CODICE_FIN1",
           VC."CATEGORIA_SOCIALE_ID",
           VC."FLAG_SPESA_CALC",
           VC."OPERATORE_SETTORE_ID",
