DROP VIEW CS_ROMA.V_EROG_FIRST_LAST;

/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_EROG_FIRST_LAST
(
    ER_MAST_ID,
    ER_PRIMO_STATO,
    ER_PRIMO_STATO_TIPO,
    ER_PRIMO_STATO_ER_POSSIBILE,
    ER_PRIMO_STATO_DT,
    ER_PRIMO_STATO_FLAG_CHIUDI,
    ER_ULTIMO_STATO,
    ER_ULTIMO_STATO_TIPO,
    ER_ULTIMO_STATO_ER_POSSIBILE,
    ER_ULTIMO_STATO_DT,
    ER_ULTIMO_STATO_FLAG_CHIUDI
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT
           ER_MAST_ID,
           FIRST_VALUE (ER_STATO_NOME) OVER (PARTITION BY er_mast_id)
               er_primo_stato,
           FIRST_VALUE (er_stato_tipo) OVER (PARTITION BY er_mast_id)
               er_PRIMO_stato_tipo,
           FIRST_VALUE (er_stato_erogazione_possibile)
               OVER (PARTITION BY er_mast_id)
               er_PRIMO_stato_er_possibile,
           FIRST_VALUE (er_data_esecuzione) OVER (PARTITION BY er_mast_id)
               er_primo_stato_DT,
           FIRST_VALUE (er_flag_chiudi) OVER (PARTITION BY er_mast_id)
               er_primo_stato_flag_chiudi,
           LAST_VALUE (ER_STATO_NOME) OVER (PARTITION BY er_mast_id)
               er_ultimo_stato,
           LAST_VALUE (er_stato_tipo) OVER (PARTITION BY er_mast_id)
               er_ULTIMO_stato_tipo,
           LAST_VALUE (er_stato_erogazione_possibile)
               OVER (PARTITION BY er_mast_id)
               er_ULTIMO_stato_er_possibile,
           LAST_VALUE (er_data_esecuzione) OVER (PARTITION BY er_mast_id)
               er_ultimo_stato_DT,
           LAST_VALUE (er_flag_chiudi) OVER (PARTITION BY er_mast_id)
               er_ultimo_stato_flag_chiudi
      FROM (  SELECT *
                FROM V_EROG_LST_DETT
            ORDER BY er_mast_id, er_data_esecuzione, er_DETT_id);


