                   ANA.TEL
                       A_TEL,
                   ANA.CELL
                       A_CELL,
                   I.COMP_DENOMINAZIONE,
                   I.COMP_TEL,
                   EM.ID
                       ER_ID,
                   (SELECT COUNT (STATOESEG.ID)
                      FROM CS_I_INTERVENTO_ESEG   DETTESEG,
                           CS_CFG_INT_ESEG_STATO  STATOESEG
                     WHERE     EM.ID = DETTESEG.INTERVENTO_ESEG_MAST_ID
                           AND DETTESEG.STATO_ID = STATOESEG.ID
                           AND STATOESEG.TIPO = 'E')
                       N_EROGAZIONI_E,
                   (SELECT CASE
                               WHEN MAX (data_esecuzione) IS NOT NULL THEN 1
                               ELSE 0
                           END
                      FROM CS_I_INTERVENTO_ESEG   DETTESEG,
                           CS_CFG_INT_ESEG_STATO  STATO
                     WHERE     STATO.ID = DETTESEG.STATO_ID
                           AND STATO.EROGAZIONE_POSSIBILE = '1'
                           AND EM.ID = DETTESEG.INTERVENTO_ESEG_MAST_ID
                           AND DETTESEG.DATA_ESECUZIONE =
                               (SELECT MAX (DATA_ESECUZIONE)
                                  FROM CS_I_INTERVENTO_ESEG ESEGDT
                                 WHERE ESEGDT.INTERVENTO_ESEG_MAST_ID = EM.ID))
                       ER_POSSIBILE_EROGAZ,
                   EMSOGG.CASO_ID
                       ER_SOGG_CASO_ID,
                   IT_STATO.NOME
                       ER_SOGG_STATO_ITER,
                   EMSOGG.FLAG_RIFERIMENTO
                       ER_SOGG_FLAG_RIFERIMENTO,
                   EMSOGG.COGNOME
                       ER_SOGG_COGNOME,
                   EMSOGG.NOME
                       ER_SOGG_NOME,
