                       ER_ORGANIZZAZIONE_ER_BELFIORE,
                   EM.SETTORE_EROGANTE_ID
                       ER_SETTORE_EROG_ID,
                   SEROG.NOME
                       ER_SETTORE_EROG,
                   SGEST.NOME
                       ER_SETTORE_GEST,
                   EM.SETTORE_GESTORE_ID
                       ER_SETTORE_GEST_ID,
                   EM.SETTORE_TITOLARE_ID
                       ER_SETTORE_TIT_ID,
                   EM.TIPO_BENEFICIARIO
                       ER_TIPO_BENEFICIARIO,
                   STIT.NOME
                       ER_SETTORE_TIT,
                   ORGTIT.ID
                       ER_ORGANIZZAZIONE_TIT_ID,
                   ORGTIT.NOME
                       ER_ORGANIZZAZIONE_TIT_NOME,
                   ORGTIT.cod_routing
                       ER_ORGANIZZAZIONE_TIT_BELFIORE,
                   osettana.cognome
                       ER_OPE_COG_INS,
                   osettana.nome
                       ER_OPE_NOME_INS,
                   LF.DESCRIZIONE
                       LF_DESCRIZIONE,
                   EM.FF_PROGETTO_DESCRIZIONE,
                   EM.FF_PROGETTO_CODICE,
                   EM.N_SOTTOCORSO_ATTIVITA,
                   EM.PR_ID,
                   EM.COND_LAVORO,
                   EM.ING_MERCATO_COD,
                   EM.ING_MERCATO,
                   EM.TITOLO_STUDIO_COD,
                   EM.TITOLO_STUDIO,
                   EM.DESC_INTERVENTO_ESEG,
                   EM.TIPO_BENEFICIARIO,
                   EM.SPESA,
                   EM.PERC_GESTITA_ENTE,
                   NVL (EM.VALORE_GESTITA_ENTE,
                        EM.SPESA * EM.PERC_GESTITA_ENTE / 100)
                       VALORE_GESTITA_ENTE,
                   EM.COMPART_SSN,
                   EM.COMPART_UTENTI,
                   EM.COMPART_ALTRE,
                   VFL.ER_PRIMO_STATO,
                   VFL.ER_PRIMO_STATO_DT,
                   VFL.ER_PRIMO_STATO_FLAG_CHIUDI,
                   VFL.ER_ULTIMO_STATO,
                   VFL.ER_ULTIMO_STATO_DT,
                   VFL.ER_ULTIMO_STATO_FLAG_CHIUDI,
                   CASE
                       WHEN QR.FLAG_UNATANTUM = 1 THEN 'Unatantum'
                       WHEN QR.FLAG_REGOLARE = '1' THEN 'Regolare'
                       WHEN QR.FLAG_IRREGOLARE = '1' THEN 'Irregolare'
                       ELSE NULL
                   END
                       qr_frequenza_servizio,
                   DECODE (QR.FLAG_RENDICONTO,
                           'E', 'Ad Evento',
                           'P', 'Periodico',
                           NULL)
                       QR_FREQUENZA_RENDICONTO,
                   DECODE (QR.FLAG_PERIODO_RIPARTIZ,
                           'M', 'Mensile',
                           'G', 'Giornaliero',
                           'A', 'Annuale',
                           'S', 'Settimanale',
                           NULL)
                       QR_FLAG_PERIODO_RIPARTIZ,
                   QR.N_GG_SETTIMANALI
                       QR_N_GG_SETTIMANALI,
                   QR.VAL_QUOTA_PERIODO
                       QR_VAL_QUOTA_PERIODO,
                   UM.VALORE
                       ER_UNITA_MISURA,
                   QR.N_TOT_ACCESSI_SERVIZIO
                       QR_N_TOT_ACCESSI_SERVIZIO,
                   EM.DIARIO_PAI_ID
                       PAI_ID,
                   ORGMAST.CF
                       ORGMAST_CF,
                   ORGEROG.CF
                       ER_ORGANIZZAZIONE_ER_CF,
                   ORGGEST.CF
                       ER_ORGANIZZAZIONE_GS_CF,
                   ORGTIT.CF
                       ER_ORGANIZZAZIONE_TIT_CF
              FROM cs_i_intervento              i,
                   CS_I_QUOTA                   Q,
                   CS_TB_UNITA_MISURA           UM,
                   CS_I_QUOTA_RIPARTIZ          QR,
                   V_EROG_MAST_PR               em,
                   V_EROG_MAST_SOGG_JSON_EXT    EMSOGG,
                   cs_o_operatore_settore       osett,
                   cs_o_settore                 settMAST,
                   CS_O_ORGANIZZAZIONE          ORGMAST,
                   cs_o_operatore_anagrafica    osettana,
                   cs_c_categoria_sociale       cs,
                   cs_o_settore                 s,
                   CS_O_SETTORE                 SGEST,
                   CS_O_SETTORE                 SEROG,
                   CS_O_ORGANIZZAZIONE          ORGEROG,
                   CS_O_ORGANIZZAZIONE          ORGGEST,
                   CS_O_SETTORE                 STIT,
                   CS_O_ORGANIZZAZIONE          ORGTIT,
                   CS_O_ORGANIZZAZIONE          O,
                   cs_c_tipo_intervento         ti,
                   cs_c_tipo_intervento_custom  tic,
                   CS_A_COMPONENTE              COMP,
                   CS_A_ANAGRAFICA              ANA,
                   CS_TB_DISPONIBILITA          DISP,
                   V_LINEAFIN                   LF,
                   V_EROG_FIRST_LAST            VFL,
                   CS_IT_STEP                   it,
                   CS_CFG_IT_STATO              IT_STATO
             WHERE     EMSOGG.CASO_ID = IT.CASO_ID(+)
                   AND IT.CFG_IT_STATO_ID = IT_STATO.ID(+)
                   AND (   IT.ID IS NULL
                        OR IT.ID = (SELECT MAX (it2.id)
                                      FROM CS_IT_STEP it2
                                     WHERE IT2.CASO_ID = EMSOGG.CASO_ID))
                   AND i.scti_settore_id = s.id(+)
                   AND EM.QUOTA_ID = Q.ID(+)
                   AND Q.UNITA_MISURA_ID = UM.ID(+)
                   AND Q.ID = QR.QUOTA_ID(+)
                   AND EM.ID = VFL.ER_MAST_ID(+)
                   AND EM.TIPO_INTERVENTO_ID = ti.id
                   AND EM.INTERVENTO_ID = I.ID(+)
                   AND EM.SETTORE_EROGANTE_ID = SEROG.ID(+)
                   AND EM.SETTORE_GESTORE_ID = SGEST.ID(+)
                   AND SGEST.ORGANIZZAZIONE_ID = ORGGEST.ID(+)
                   AND SEROG.ORGANIZZAZIONE_ID = ORGEROG.ID(+)
                   AND EM.SETTORE_TITOLARE_ID = STIT.ID(+)
                   AND STIT.ORGANIZZAZIONE_ID = ORGTIT.ID(+)
                   AND EM.OPERATORE_SETTORE_ID = osett.id(+)
                   AND OSETT.SETTORE_ID = SETTMAST.ID(+)
                   AND SETTMAST.ORGANIZZAZIONE_ID = ORGMAST.ID(+)
                   AND EMSOGG.INT_ESEG_MAST_ID = EM.ID
                   AND osett.operatore_id = OSETTANA.ID(+)
                   AND EM.tipo_intervento_custom_id = tic.id(+)
                   AND EM.FF_ORIGINE_ID = LF.ID(+)
                   AND S.ORGANIZZAZIONE_ID = O.ID(+)
                   AND I.COMPONENTE_ID = COMP.ID(+)
                   AND COMP.DISPONIBILITA_ID = DISP.ID(+)
                   AND COMP.ANAGRAFICA_ID = ANA.ID(+)
                   AND EM.CATEGORIA_SOCIALE_ID = CS.ID(+)) SEL
           LEFT JOIN cs_flg_intervento FLG ON SEL.I_ID = FLG.INTERVENTO_ID
           LEFT JOIN CS_D_DIARIO D ON FLG.DIARIO_ID = D.ID
           LEFT JOIN cs_a_caso c ON D.CASO_ID = C.ID
     WHERE (   flg.DIARIO_ID IS NULL
            OR flg.DIARIO_ID = (SELECT MAX (DIARIO_ID)
                                  FROM CS_FLG_INTERVENTO II
                                 WHERE II.INTERVENTO_ID = FLG.INTERVENTO_ID));


