/* Formatted on 18/07/2022 12:23:37 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_FSE_EROGAZIONI
(
    CODICE_INVIANTE,
    TIPO,
    ID,
    DATA_SOTTOSCRIZIONE,
    PROGETTO,
    ATTIVITA_ID,
    COGNOME,
    NOME,
    CF,
    SESSO,
    DATA_NASCITA,
    COMUNE_NASCITA_ID,
    NAZIONE_NASCITA_ID,
    CITTADINANZA,
    INDIRIZZO_RESIDENZA,
    COMUNE_RES_ID,
    INDIRIZZO_DOMICILIO,
    COMUNE_DOM_ID,
    TELEFONO,
    CELLULARE,
    EMAIL,
    COND_MERCATO_INGRESSO,
    FLAG_FREQUENZA_ALTRO_CORSO,
    DURATA_RICERCA_LAVORO,
    TIPOLOGIA_LAVORO,
    TIPO_ORARIO_LAVORO,
    RAGIONE_SOCIALE_AZIENDA,
    PARTITA_IVA_AZIENDA,
    CODICE_FISCALE_AZIENDA,
    INDIRIZZO_AZIENDA,
    COMUNE_AZIENDA_ID,
    ATECO_AZIENDA_COD_ATECO_ANNO,
    AZ_FORMA_GIURIDICA_RNA_COD,
    DIMENSIONE_AZIENDA,
    TITOLO_STUDIO,
    ANNO_CONSEGUIMENTO_TITOLO_STU,
    GRUPPO_VULNERABILE_PA,
    IBAN,
    FLAG_COMUNICAZIONE_RESIDENZA
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            INV.ID_INVIANTE,
            TIPO.ID
                AS TIPO,
            M.ID,
            c.dt_sottoscrizione
                AS DATA_SOTTOSCRIZIONE,
            arp.descrizione
                PROGETTO,
            arpa.codice
                PROGETTO_ATTIVITA_ID,
            S.COGNOME,
            S.NOME,
            S.CF,
            SIR.SESSO,
            SIR.DATA_NASCITA,
            SIR.COMUNE_NASCITA_ID,
            SIR.NAZIONE_NASCITA_ID,
            SIR.CITTADINANZA,
            S.VIA_RESIDENZA
                INDIRIZZO_RESIDENZA,
            SIR.COMUNE_RES_ID,
            DECODE (TO_CHAR (C.COMUNE_DOMICILIO),
                    NULL, S.VIA_RESIDENZA,
                    C.VIA_DOMICILIO)
                INDIRIZZO_DOMICILIO,
            DECODE (TO_CHAR (C.COMUNE_DOMICILIO),
                    NULL, SIR.COMUNE_RES_ID,
                    SIR.COMUNE_DOM_ID)
                COMUNE_DOM_ID,
            C.TELEFONO,
            C.CELLULARE,
            C.EMAIL,
            CHK_ING_MER.DESCRIZIONE_MERCATO_INGRESSO
                COND_MERCATO_INGRESSO,
            C.FLAG_ALTRO_CORSO
                FLAG_FREQUENZA_ALTRO_CORSO,
            CHK_DUR_RIC.DESCRIZIONE_DURATA_RICERCA
                DURATA_RICERCA_LAVORO,
            CHK_TIP_LAV.DESCRIZIONE
                TIPOLOGIA_LAVORO,
            CHK_ORA_LAV.DESCRIZIONE
                TIPO_ORARIO_LAVORO,
            C.AZ_RAGIONE_SOCIALE
                RAGIONE_SOCIALE_AZIENDA,
            C.AZ_PI
                PARTITA_IVA_AZIENDA,
            C.AZ_CF
                CODICE_FISCALE_AZIENDA,
            C.AZ_VIA
                INDIRIZZO_AZIENDA,
            C.AZ_COMUNE_COD
                COMUNE_AZIENDA_ID,
            SIR.COD_ATECO_ANNO
                ATECO_AZIENDA_COD_ATECO_ANNO,
            SIR.FRM_GIURIDICA_COD
                AZ_FORMA_GIURIDICA_RNA_COD,
            CHK_AZ_DIM.DESCRIZIONE
                DIMENSIONE_AZIENDA,
            CHK_TIT_STUDIO.DESCRIZIONE_TITOLO_STUDIO
                TITOLO_STUDIO,
            DECODE (C.ANNO_CONSEGUIMENTO_TITOLO_STU,
                    '0', NULL,
                    C.ANNO_CONSEGUIMENTO_TITOLO_STU)
                ANNO_CONSEGUIMENTO_TITOLO_STU,
            CHK_GR_VULN.DESCR_VULNERABILE_PA
                GR_VULNERABILE_PA,
            C.IBAN,
            SIR.FLAG_RESIDENZA
                FLAG_COMUNICAZIONE_RESIDENZA
       FROM CS_TB_TIPO_EXTRA_FSE          TIPO,
            V_INTERVENTO_PR_FSE_JSON_EXT  c
            LEFT JOIN CS_I_INTERVENTO_ESEG_MAST m
                ON (m.INT_PROGETTO_ID = c.INTERVENTO_PR_ID)
            LEFT JOIN CS_I_INTERVENTO_PR pr ON (PR.ID = C.INTERVENTO_PR_ID)
            LEFT JOIN V_AR_SETTORE_PROGETTO arp
                ON (    arp.settore_id = pr.settore_titolare_id
                    AND PR.progetto_id = arp.id)
            LEFT JOIN AR_FF_PROGETTO_ATTIVITA arpa
                ON (arpa.id = pr.progetto_attivita_id)
            LEFT JOIN V_BI_INVIANTE INV
                ON (    ARP.ORGANIZZAZIONE_ID = INV.ID_ORGANIZZAZIONE
                    AND INV.TIPO_INVIANTE = 'SISO')
            LEFT JOIN V_EROG_MAST_SOGG_JSON_EXT s
                ON (m.ID = s.INT_ESEG_MAST_ID AND FLAG_RIFERIMENTO = 1)
            LEFT JOIN CS_TB_G_VULNERABILE gr ON (C.GR_VULNERABILE_ID = gr.id)
            LEFT JOIN CS_TB_FORMA_GIURIDICA az_fg
                ON (C.AZ_FORMA_GIURIDICA = az_fg.id)
            LEFT JOIN CS_I_INTERVENTO_PR_FSE_SIRU sir
                ON (C.INTERVENTO_PR_ID = SIR.INTERVENTO_PR_ID)
            LEFT JOIN FSE_CHK_CONDIZIONE_MERCATO CHK_ING_MER
                ON SIR.COND_MERCATO_INGRESSO =
                   CHK_ING_MER.COND_MERCATO_INGRESSO
            LEFT JOIN FSE_CHK_DURATA_RICERCA CHK_DUR_RIC
                ON SIR.DURATA_RICERCA = CHK_DUR_RIC.DURATA_RICERCA
            LEFT JOIN FSE_CHK_TIPOLOGIA_LAVORO CHK_TIP_LAV
                ON SIR.TIPOLOGIA_LAVORO_ID = CHK_TIP_LAV.ID
            LEFT JOIN FSE_CHK_TIPO_ORARIO_LAVORO CHK_ORA_LAV
                ON SIR.TIPO_ORARIO_LAVORO_ID = CHK_ORA_LAV.ID
            LEFT JOIN FSE_CHK_DIMENSIONE_AZIENDA CHK_AZ_DIM
                ON SIR.DIMENSIONE_AZIENDA_ID = CHK_AZ_DIM.ID
            LEFT JOIN FSE_CHK_TITOLO_STUDIO CHK_TIT_STUDIO
                ON SIR.TITOLO_STUDIO = CHK_TIT_STUDIO.TITOLO_STUDIO
            LEFT JOIN FSE_CHK_GRUPPO_VUL_PART CHK_GR_VULN
                ON SIR.COD_VULNERABILE_PA = CHK_GR_VULN.CODICE_VULNERABILE_PA
      WHERE TIPO.ID = 3 AND M.ID IS NOT NULL AND S.CF IS NOT NULL);


