/* Formatted on 18/07/2022 12:23:38 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_FSE_PIC
(
    CODICE_INVIANTE,
    TIPO,
    ID,
    DATA_SOTTOSCRIZIONE,
    PROGETTO,
    ATTIVITA_ID,
    COGNOME,
    NOME,
    CF,
    SESSO,
    DATA_NASCITA,
    COMUNE_NASCITA_ID,
    NAZIONE_NASCITA_ID,
    CITTADINANZA,
