    INDIRIZZO_DOMICILIO,
    COMUNE_DOM_ID,
    TELEFONO,
    CELLULARE,
    EMAIL,
    COND_MERCATO_INGRESSO,
    FLAG_FREQUENZA_ALTRO_CORSO,
    DURATA_RICERCA_LAVORO,
    TIPOLOGIA_LAVORO,
    TIPO_ORARIO_LAVORO,
    RAGIONE_SOCIALE_AZIENDA,
    PARTITA_IVA_AZIENDA,
    CODICE_FISCALE_AZIENDA,
    INDIRIZZO_AZIENDA,
    COMUNE_AZIENDA_ID,
    ATECO_AZIENDA_COD_ATECO_ANNO,
    AZ_FORMA_GIURIDICA_RNA_COD,
    DIMENSIONE_AZIENDA,
    TITOLO_STUDIO,
    ANNO_CONSEGUIMENTO_TITOLO_STU,
    GRUPPO_VULNERABILE_PA,
    IBAN,
    FLAG_COMUNICAZIONE_RESIDENZA
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            INV.CODICE_INVIANTE,
            TIPO.ID
                AS TIPO,
            m.caso_id
                AS CASO_ID,
            c.dt_sottoscrizione
                DATA_SOTTOSCRIZIONE,
            progetto.descrizione
                PROGETTO,
            attivita.codice
                PROGETTO_ATTIVITA_ID,
            a.cognome,
            TO_CHAR (a.nome),
            A.CF
                CODICE_FISCALE,
            SIR.SESSO,
            SIR.DATA_NASCITA,
            SIR.COMUNE_NASCITA_ID,
            SIR.NAZIONE_NASCITA_ID,
            SIR.CITTADINANZA,
               RESIDENZA.INDIRIZZO
            || DECODE (RESIDENZA.CIVICO_NUMERO,
                       NULL, '',
                       ', ' || RESIDENZA.CIVICO_NUMERO)
                INDIRIZZO_RESIDENZA,
            SIR.COMUNE_RES_ID,
            DECODE (
                DOMIND.ANA_INDIRIZZO_ID,
                NULL,    RESIDENZA.INDIRIZZO
                      || DECODE (RESIDENZA.CIVICO_NUMERO,
                                 NULL, '',
                                 ', ' || RESIDENZA.CIVICO_NUMERO),
                   DOMICILIO.INDIRIZZO
                || DECODE (DOMICILIO.CIVICO_NUMERO,
                           NULL, '',
                           ', ' || DOMICILIO.CIVICO_NUMERO))
                INDIRIZZO_DOMICILIO,
            DECODE (DOMIND.ANA_INDIRIZZO_ID,
                    NULL, SIR.COMUNE_RES_ID,
                    SIR.COMUNE_DOM_ID)
                COMUNE_DOM_ID,
            A.TEL,
            A.CELL,
            A.EMAIL,
            CHK_ING_MER.DESCRIZIONE_MERCATO_INGRESSO
                COND_MERCATO_INGRESSO,
            C.FLAG_ALTRO_CORSO
                FLAG_FREQUENZA_ALTRO_CORSO,
            CHK_DUR_RIC.DESCRIZIONE_DURATA_RICERCA
                DURATA_RICERCA_LAVORO,
            CHK_TIP_LAV.DESCRIZIONE
                TIPOLOGIA_LAVORO,
            CHK_ORA_LAV.DESCRIZIONE
                TIPO_ORARIO_LAVORO,
            C.AZ_RAGIONE_SOCIALE
                RAGIONE_SOCIALE_AZIENDA,
            C.AZ_PI
                PARTITA_IVA_AZIENDA,
            C.AZ_CF
                CODICE_FISCALE_AZIENDA,
            C.AZ_VIA
                INDIRIZZO_AZIENDA,
            C.AZ_COMUNE_COD
                COMUNE_AZIENDA_ID,
            SIR.COD_ATECO_ANNO
                ATECO_AZIENDA_COD_ATECO_ANNO,
            SIR.FRM_GIURIDICA_COD
                AZ_FORMA_GIURIDICA_RNA_COD,
            CHK_AZ_DIM.DESCRIZIONE
                DIMENSIONE_AZIENDA,
            CHK_TIT_STUDIO.DESCRIZIONE_TITOLO_STUDIO
                TITOLO_STUDIO,
            DECODE (C.ANNO_CONSEGUIMENTO_TITOLO_STU,
                    '0', NULL,
                    C.ANNO_CONSEGUIMENTO_TITOLO_STU)
                ANNO_CONSEGUIMENTO_TITOLO_STU,
            CHK_GR_VULN.DESCR_VULNERABILE_PA
                GR_VULNERABILE_PA,
            C.IBAN,
            SIR.FLAG_RESIDENZA
                FLAG_COMUNICAZIONE_RESIDENZA
       FROM CS_EXTRA_FSE_DATI_LAVORO  c
            LEFT JOIN CS_EXTRA_FSE_MAST m ON (C.EXTRA_FSE_MAST_ID = M.ID)
            LEFT JOIN CS_TB_TIPO_EXTRA_FSE TIPO
                ON (M.TIPO_EXTRA_FSE_ID = tipo.id)
            LEFT JOIN CS_A_SOGGETTO s ON (M.CASO_ID = S.CASO_ID)
            LEFT JOIN CS_A_ANAGRAFICA a ON (S.ANAGRAFICA_ID = a.id)
            LEFT JOIN V_BI_TR_CS_AN INV ON (INV.CASO_ID = M.CASO_ID)
            LEFT JOIN CS_A_INDIRIZZO resInd
                ON (    S.ANAGRAFICA_ID = resInd.SOGGETTO_ANAGRAFICA_ID
                    AND resInd.TIPO_INDIRIZZO_ID = 1
                    AND resInd.data_fine_app IS NULL)
            LEFT JOIN CS_A_ANA_INDIRIZZO residenza
                ON (RESIND.ANA_INDIRIZZO_ID = residenza.id)
            LEFT JOIN CS_A_INDIRIZZO domInd
                ON (    S.ANAGRAFICA_ID = domInd.SOGGETTO_ANAGRAFICA_ID
                    AND domInd.TIPO_INDIRIZZO_ID = 3
                    AND domInd.data_fine_app IS NULL)
            LEFT JOIN CS_A_ANA_INDIRIZZO domicilio
                ON (domInd.ANA_INDIRIZZO_ID = domicilio.id)
            LEFT JOIN CS_A_DATI_SOCIALI ds
                ON (DS.SOGGETTO_ANAGRAFICA_ID = a.id)
            LEFT JOIN CS_EXTRA_FSE_SIRU sir ON (M.ID = SIR.EXTRA_FSE_MAST_ID)
            LEFT JOIN AR_FF_PROGETTO progetto
                ON (progetto.id = C.PROGETTO_ID)
            LEFT JOIN AR_FF_PROGETTO_ATTIVITA attivita
                ON (attivita.id = C.PROGETTO_ATTIVITA_ID)
            LEFT JOIN FSE_CHK_CONDIZIONE_MERCATO CHK_ING_MER
                ON SIR.COND_MERCATO_INGRESSO =
                   CHK_ING_MER.COND_MERCATO_INGRESSO
            LEFT JOIN FSE_CHK_DURATA_RICERCA CHK_DUR_RIC
                ON SIR.DURATA_RICERCA = CHK_DUR_RIC.DURATA_RICERCA
            LEFT JOIN FSE_CHK_TIPOLOGIA_LAVORO CHK_TIP_LAV
                ON SIR.TIPOLOGIA_LAVORO_ID = CHK_TIP_LAV.ID
            LEFT JOIN FSE_CHK_TIPO_ORARIO_LAVORO CHK_ORA_LAV
                ON SIR.TIPO_ORARIO_LAVORO_ID = CHK_ORA_LAV.ID
            LEFT JOIN FSE_CHK_DIMENSIONE_AZIENDA CHK_AZ_DIM
                ON SIR.DIMENSIONE_AZIENDA_ID = CHK_AZ_DIM.ID
            LEFT JOIN FSE_CHK_TITOLO_STUDIO CHK_TIT_STUDIO
                ON SIR.TITOLO_STUDIO = CHK_TIT_STUDIO.TITOLO_STUDIO
            LEFT JOIN FSE_CHK_GRUPPO_VUL_PART CHK_GR_VULN
                ON SIR.COD_VULNERABILE_PA = CHK_GR_VULN.CODICE_VULNERABILE_PA
      WHERE M.TIPO_EXTRA_FSE_ID = 1 AND progetto.codice_memo IS NOT NULL);


