                COMUNE_DOM_ID,
            SS.TELEFONO
                AS TELEFONO,
            SS.CEL
                AS CELLULARE,
            SS.EMAIL
                AS EMAIL,
            CHK_ING_MER.DESCRIZIONE_MERCATO_INGRESSO
                COND_MERCATO_INGRESSO,
            C.FLAG_ALTRO_CORSO
                FLAG_FREQUENZA_ALTRO_CORSO,
            CHK_DUR_RIC.DESCRIZIONE_DURATA_RICERCA
                DURATA_RICERCA_LAVORO,
            CHK_TIP_LAV.DESCRIZIONE
                TIPOLOGIA_LAVORO,
            CHK_ORA_LAV.DESCRIZIONE
                TIPO_ORARIO_LAVORO,
            C.AZ_RAGIONE_SOCIALE
                RAGIONE_SOCIALE_AZIENDA,
            C.AZ_PI
                PARTITA_IVA_AZIENDA,
            C.AZ_CF
                CODICE_FISCALE_AZIENDA,
            C.AZ_VIA
                INDIRIZZO_AZIENDA,
            C.AZ_COMUNE_COD
                COMUNE_AZIENDA_ID,
            SIR.COD_ATECO_ANNO
                ATECO_AZIENDA_COD_ATECO_ANNO,
            SIR.FRM_GIURIDICA_COD
                AZ_FORMA_GIURIDICA_RNA_COD,
            CHK_AZ_DIM.DESCRIZIONE
                DIMENSIONE_AZIENDA,
            CHK_TIT_STUDIO.DESCRIZIONE_TITOLO_STUDIO
                TITOLO_STUDIO,
            DECODE (C.ANNO_CONSEGUIMENTO_TITOLO_STU,
                    '0', NULL,
                    C.ANNO_CONSEGUIMENTO_TITOLO_STU)
                ANNO_CONSEGUIMENTO_TITOLO_STU,
            CHK_GR_VULN.DESCR_VULNERABILE_PA
                GR_VULNERABILE_PA,
            C.IBAN,
            SIR.FLAG_RESIDENZA
                FLAG_COMUNICAZIONE_RESIDENZA
       FROM CS_EXTRA_FSE_DATI_LAVORO  c
            LEFT JOIN CS_EXTRA_FSE_MAST m ON (C.EXTRA_FSE_MAST_ID = M.ID)
            LEFT JOIN CS_TB_TIPO_EXTRA_FSE TIPO
                ON (M.TIPO_EXTRA_FSE_ID = tipo.id)
            LEFT JOIN SS_SCHEDA s ON (M.SCHEDA_ID = S.ID)
            LEFT JOIN SS_SCHEDA_SEGNALATO ss ON (s.segnalato = ss.id)
            LEFT JOIN SS_ANAGRAFICA a ON (SS.ANAGRAFICA = a.id)
            LEFT JOIN SS_INDIRIZZO residenza ON (SS.RESIDENZA = residenza.id)
            LEFT JOIN SS_INDIRIZZO domicilio ON (ss.domicilio = domicilio.id)
            LEFT JOIN CS_EXTRA_FSE_SIRU sir ON (M.ID = SIR.EXTRA_FSE_MAST_ID)
            LEFT JOIN AR_FF_PROGETTO progetto
                ON (progetto.id = C.PROGETTO_ID)
            LEFT JOIN AR_FF_PROGETTO_ATTIVITA attivita
                ON (attivita.id = C.PROGETTO_ATTIVITA_ID)
            LEFT JOIN V_BI_TR_SA BI ON (BI.PK_SCHEDA_ID = M.SCHEDA_ID)
            LEFT JOIN FSE_CHK_CONDIZIONE_MERCATO CHK_ING_MER
                ON SIR.COND_MERCATO_INGRESSO =
                   CHK_ING_MER.COND_MERCATO_INGRESSO
            LEFT JOIN FSE_CHK_DURATA_RICERCA CHK_DUR_RIC
                ON SIR.DURATA_RICERCA = CHK_DUR_RIC.DURATA_RICERCA
            LEFT JOIN FSE_CHK_TIPOLOGIA_LAVORO CHK_TIP_LAV
                ON SIR.TIPOLOGIA_LAVORO_ID = CHK_TIP_LAV.ID
            LEFT JOIN FSE_CHK_TIPO_ORARIO_LAVORO CHK_ORA_LAV
                ON SIR.TIPO_ORARIO_LAVORO_ID = CHK_ORA_LAV.ID
            LEFT JOIN FSE_CHK_DIMENSIONE_AZIENDA CHK_AZ_DIM
                ON SIR.DIMENSIONE_AZIENDA_ID = CHK_AZ_DIM.ID
            LEFT JOIN FSE_CHK_TITOLO_STUDIO CHK_TIT_STUDIO
                ON SIR.TITOLO_STUDIO = CHK_TIT_STUDIO.TITOLO_STUDIO
            LEFT JOIN FSE_CHK_GRUPPO_VUL_PART CHK_GR_VULN
                ON SIR.COD_VULNERABILE_PA = CHK_GR_VULN.CODICE_VULNERABILE_PA
      WHERE M.TIPO_EXTRA_FSE_ID = 2 AND progetto.codice_memo IS NOT NULL);


