/* Formatted on 18/07/2022 12:23:38 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_TABULATO_CASI
(
    CHIAVE,
    ZONA_SOCIALE,
    BELFIORE,
    IDENTIFICATIVO,
    ID,
    "DATA APERTURA",
    "ANNO APERTURA",
    "MESE APERTURA",
    "DATA ITER",
    "ANNO ITER",
    "MESE ITER",
    "Cognome - Nome",
    CF,
    DATA_NASCITA,
    C_ETA,
    ETA,
    CITTADINANZA,
    COMUNE,
    "CATEGORIA SOCIALE",
    SETTORE,
    "STATO CARTELLA",
    OPERATORE,
    RESPONSABILE,
    "cf operatore",
    "tipo operatore",
    DATA_INIZIO_APP,
    DATA_FINE_APP,
    DATA_INIZIO_TRIB_MIN,
    DATA_INIZIO_TRIB_MAX,
    DATA_INIZIO_TRIB_MIN_ANNO,
    DATA_INIZIO_TRIB_MIN_ANNO_MESE,
    DATA_INIZIO_TRIB_MAX_ANNO,
    DATA_INIZIO_TRIB_MAX_ANNO_MESE,
    UFFICIO,
    ZONA_SOCIALE_DESC,
    TRIB_TM_CIVILE,
    TRIB_TM_AMMINISTRATIVO,
    TRIB_PENALE_MINORILE,
    TRIB_T_O,
    TRIB_PROCURA_MINORILE,
    TRIB_PROCURA_ORDINARIA,
    ULTIMO_ANNO_PIC,
    PRIMO_ANNO_PIC,
    PIC_ANNO_TRIBUNALE,
    ID_ORG,
    CODICE_ORG
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT
           A."CHIAVE",
           A."ZONA_SOCIALE",
           A."BELFIORE",
           A."IDENTIFICATIVO",
           A."ID",
           A."DATA APERTURA",
           A."ANNO APERTURA",
           A."MESE APERTURA",
           A."DATA ITER",
           A."ANNO ITER",
           A."MESE ITER",
           A."Cognome - Nome",
           A."CF",
           A."DATA_NASCITA",
           A."C_ETA",
           A."ETA",
           A."CITTADINANZA",
           A."COMUNE",
           A."CATEGORIA SOCIALE",
           A."SETTORE",
           A."STATO CARTELLA",
           A."OPERATORE",
           A."RESPONSABILE",
           A."cf operatore",
           A."tipo operatore",
           A."DATA_INIZIO_APP",
           A."DATA_FINE_APP",
           a.DATA_INIZIO_TRIB_MIN,
           a.DATA_INIZIO_TRIB_MAX,
           EXTRACT (YEAR FROM DATA_INIZIO_TRIB_MIN)
               DATA_INIZIO_TRIB_MIN_ANNO,
           EXTRACT (MONTH FROM DATA_INIZIO_TRIB_MIN)
               DATA_INIZIO_TRIB_MIN_ANNO_MESE,
           EXTRACT (YEAR FROM DATA_INIZIO_TRIB_MAX)
               DATA_INIZIO_TRIB_MAX_ANNO,
           EXTRACT (MONTH FROM DATA_INIZIO_TRIB_MAX)
               DATA_INIZIO_TRIB_MAX_ANNO_MESE,
           A."UFFICIO",
           A."ZONA_SOCIALE_DESC",
           TRIB_TM_CIVILE,
           TRIB_TM_AMMINISTRATIVO,
           TRIB_PENALE_MINORILE,
           TRIB_T_O,
           TRIB_PROCURA_MINORILE,
           TRIB_PROCURA_ORDINARIA,
           TO_CHAR (b.data_iter, 'YYYY')
               ULTIMO_ANNO_pic,
           TO_CHAR (c.data_iter, 'YYYY')
               PRIMO_ANNO_pic,
           CASE
               WHEN (EXTRACT (YEAR FROM DATA_INIZIO_TRIB_MIN)) =
                    TO_CHAR (c.data_iter, 'yyyy')
               THEN
                   'SI'
               WHEN (EXTRACT (YEAR FROM DATA_INIZIO_TRIB_MIN)) IS NULL
               THEN
                   'TRIBUNALE ASSENTE'
               ELSE
                   'NO'
           END
               PIC_ANNO_TRIBUNALE,
           A.ID_ORG,
           A.CODICE_ORG
      FROM (SELECT DISTINCT
                   c.ID || '-' || (SELECT NOME FROM CS_O_ZONA_SOC)
                       CHIAVE,
                   (SELECT NOME FROM CS_O_ZONA_SOC)
                       ZONA_SOCIALE,
                   CASI.O_ORG_BELFIORE
                       BELFIORE,
                   C.IDENTIFICATIVO,
                   C.ID,
                   C.DT_INS
                       "DATA APERTURA",
                   EXTRACT (YEAR FROM C.DT_INS)
                       "ANNO APERTURA",
                   EXTRACT (MONTH FROM C.DT_INS)
                       "MESE APERTURA",
                   CASI.IT_ULTIMO_STATO_ITER_DATA
                       "DATA ITER",
                   EXTRACT (YEAR FROM CASI.IT_ULTIMO_STATO_ITER_DATA)
                       "ANNO ITER",
                   EXTRACT (MONTH FROM CASI.IT_ULTIMO_STATO_ITER_DATA)
                       "MESE ITER",
                   A.COGNOME || ' ' || A.NOME
                       "Cognome - Nome",
                   A.CF,
                   A.DATA_NASCITA,
                   TRUNC (MONTHS_BETWEEN (SYSDATE, a.data_nascita) / 12)
                       C_ETA,
                   CASE
                       WHEN TRUNC (
                                MONTHS_BETWEEN (SYSDATE, a.data_nascita) / 12) <
                            18
                       THEN
                           'MINORENNE'
                       ELSE
                           'MAGGIORENNE'
                   END
                       ETA,
                   CASE
                       WHEN A.CITTADINANZA = 'ITALIANA' THEN 'ITALIANA'
                       ELSE 'STRANIERA'
                   END
                       CITTADINANZA,
                   --  DIOGENE.ID_ORIG "NUMERO FAMIGLIA",
                   CASI.O_ORG_NOME
                       COMUNE,
                   CAT.DESCRIZIONE
                       "CATEGORIA SOCIALE",
                   CASI.O_SETTORE_NOME
                       "SETTORE",
                   casi.IT_ULTIMO_STATO_CASO
                       "STATO CARTELLA",
                   AMA.COGNOME || ' ' || AMA.NOME
                       "OPERATORE",
                   COPE.FLAG_RESPONSABILE
                       "RESPONSABILE",
                   OPER.USERNAME
                       "cf operatore",
                   TIPOP.DESCRIZIONE
                       "tipo operatore",
                   NVL (COPE.DATA_INIZIO_APP,
                        TO_DATE ('01/01/1000', 'dd/MM/yyyy'))
                       DATA_INIZIO_APP,
                   NVL (COPE.DATA_FINE_APP,
                        TO_DATE ('01/01/1000', 'dd/MM/yyyy'))
                       DATA_FINE_APP,
                   (SELECT MIN (CSAT.DATA_INIZIO_APP)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       DATA_INIZIO_TRIB_MIN,
                   (SELECT MAX (CSAT.DATA_INIZIO_APP)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       DATA_INIZIO_TRIB_MAX,
                   (SELECT MAX (CSAT.TM_CIVILE)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       TRIB_TM_CIVILE,
                   (SELECT MAX (CSAT.TM_AMM)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       TRIB_TM_AMMINISTRATIVO,
                   (SELECT MAX (CSAT.PENALE_MIN)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       TRIB_PENALE_MINORILE,
                   (SELECT MAX (CSAT.TO_FLG)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       TRIB_T_O,
                   (SELECT MAX (CSAT.PROCURA_MIN)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       TRIB_PROCURA_MINORILE,
                   (SELECT MAX (CSAT.PROCURA_ORD)
                      FROM cs_a_tribunale csat
                     WHERE csat.soggetto_anagrafica_id = A.ID)
                       TRIB_PROCURA_ORDINARIA,
                   OPER.TOOLTIP
                       UFFICIO,
                   (SELECT a.NOME
                      FROM CS_O_ZONA_SOC A)
                       ZONA_SOCIALE_DESC,
                   CASI.ID_ORG,
                   CASI.CODICE_ORG
              --   END
              -- TRIBUNALE_DESC
              FROM cs_a_soggetto                  s,
                   cs_a_anagrafica                a,
                   cs_a_caso                      c,
                   cs_a_soggetto_categoria_soc    sc,
                   cs_c_categoria_sociale         cat,
                   CS_A_CASO_OPE_TIPO_OPE         COPE,
                   CS_A_CASO_OPE_TIPO_OPE2        COPE2,
                   CS_O_OPERATORE_tipo_operatore  opetope,
                   cs_o_operatore_settore         os,
                   cs_o_operatore                 oper,
                   cs_tb_tipo_operatore           tipop,
                   V_AM_ANAGRAFICA                AMA,
                   v_t0_casi                      casi,
                   CS_A_TRIBUNALE                 tri
             --    --      ,(select distinct p.codfisc, f.id_orig from DIOGENE_G478_2.sit_d_persona p, DIOGENE_G478_2.SIT_D_PERS_FAM_DDATE pf , DIOGENE_G478_2.SIT_D_FAMIGLIA f
             --where P.ID_EXT=PF.ID_EXT_D_PERSONA(+)
             --and PF.ID_EXT_D_FAMIGLIA=F.ID_EXT(+)
             --and sysdate between nvl(PF.DT_INIZIO_DATO,TO_DATE('01/01/0001','dd/MM/yyyy')) and nvl(PF.DT_FINE_DATO,TO_DATE('31/12/9999','dd/MM/yyyy'))
             --and sysdate between nvl(PF.DT_INIZIO_VAL,TO_DATE('01/01/0001','dd/MM/yyyy')) and nvl(PF.DT_FINE_VAL,TO_DATE('31/12/9999','dd/MM/yyyy'))
             --and sysdate between nvl(F.DT_INIZIO_DATO,TO_DATE('01/01/0001','dd/MM/yyyy')) and nvl(F.DT_FINE_DATO,TO_DATE('31/12/9999','dd/MM/yyyy'))) DIOGENE
             WHERE     S.ANAGRAFICA_ID = A.ID
                   AND S.CASO_ID = C.ID
                   AND A.ID = SC.SOGGETTO_ANAGRAFICA_ID
                   AND SC.CATEGORIA_SOCIALE_ID = CAT.ID
                   AND C.ID = COPE.CASO_ID(+)
                   AND C.ID = COPE2.CASO_ID(+)
                   AND COPE.OPERATORE_TIPO_OPERATORE_ID = OPETOPE.ID(+)
                   AND OPETOPE.OPERATORE_SETTORE_ID = OS.ID(+)
                   AND OS.OPERATORE_ID = OPER.ID(+)
                   AND OPETOPE.TIPO_OPERATORE_ID = tipop.id(+)
                   AND OPER.USERNAME = AMA.FK_AM_USER(+)
                   AND S.CASO_ID = casi.pk_t0_caso_id
                   AND SC.SOGGETTO_ANAGRAFICA_ID =
                       tri.soggetto_anagrafica_id(+)
                   AND SC.PREVALENTE = 1
                   --    AND A.CF=DIOGENE.CODFISC(+)
                   AND (   tri.id IS NULL
                        OR tri.id IN
                               (SELECT (tt.id)
                                  FROM CS_A_TRIBUNALE tt
                                 WHERE tt.soggetto_anagrafica_id =
                                       tri.soggetto_anagraficA_id))) a
           LEFT JOIN ((  SELECT MAX (DATA_ITER) data_iter, CASO_Id, it2.STATO
                           FROM V_T5_ITER it2
                          WHERE IT2.STATO = 'Presa In Carico'
                       GROUP BY caso_id, STATO)) b
               ON a.id = b.caso_id
           LEFT JOIN ((  SELECT MIN (DATA_ITER) data_iter, CASO_Id, it3.STATO
                           FROM V_T5_ITER it3
                          WHERE IT3.STATO = 'Presa In Carico'
                       GROUP BY caso_id, STATO)) c
               ON a.id = c.caso_id;


