           E.ER_ORGANIZZAZIONE_ER_NOME,
           E.ER_ORGANIZZAZIONE_TIT_ID,
           E.ER_ORGANIZZAZIONE_TIT_BELFIORE,
           E.ER_ORGANIZZAZIONE_TIT_NOME,
