               TO_CHAR (fse.comune_domicilio),
               'null', NULL,
               TO_CHAR (
                   SUBSTR (fse.comune_domicilio,
                           INSTR (fse.comune_domicilio, '"cap":"') + 7,
                           5)))                 CAP_DOMICILIO,
           FSE.TELEFONO,
           FSE.CELLULARE,
           FSE.EMAIL,
           FSE.COND_MERCATO_INGRESSO,
           FSE.FLAG_FREQUENZA_ALTRO_CORSO       FLAG_FREQUENZA_ALTRO_CORSO,
           FSE.DURATA_RICERCA_LAVORO_COD        DURATA_RICERCA,
           FSE.TIPOLOGIA_LAVORO_ID,
           FSE.TIPO_ORARIO_LAVORO_ID,
           FSE.RAGIONE_SOCIALE_AZIENDA,
           FSE.PARTITA_IVA_AZIENDA,
           FSE.CODICE_FISCALE_AZIENDA           CODICE_FISCALE_AZIENDA,
           FSE.INDIRIZZO_AZIENDA,
           FSE.COMUNE_AZIENDA_ID,
