           FSE.ANNO_CONSEGUIMENTO_TITOLO_STU    ANNO_CONSEGUIMENTO_TITOLO,
           FSE.COD_VULNERABILE_PA               CODICE_VULNERABILE_PA,
           FSE.IBAN,
           FSE.FLAG_COMUNICAZIONE_RESIDENZA,
           FSE.CAP_AZIENDA,
           PRIMOULTIMOSTATO.ER_PRIMO_STATO,
           primoultimostato.er_primo_stato_dt,
           PRIMOULTIMOSTATO.ER_PRIMO_STATO_TIPO,
           PRIMOULTIMOSTATO.ER_PRIMO_STATO_FLAG_CHIUDI,
           PRIMOULTIMOSTATO.ER_ULTIMO_STATO,
           PRIMOULTIMOSTATO.ER_ULTIMO_STATO_DT,
           PRIMOULTIMOSTATO.ER_ULTIMO_STATO_ER_POSSIBILE,
           PRIMOULTIMOSTATO.ER_ULTIMO_STATO_FLAG_CHIUDI,
           PRIMOULTIMOSTATO.ER_ULTIMO_STATO_TIPO,
           E.ER_SETTORE_GEST_ID,
           E.ER_SETTORE_GEST,
           E.ER_SETTORE_EROG_ID,
           E.ER_SETTORE_EROG,
           E.ER_SETTORE_TIT_ID,
           E.ER_SETTORE_TIT,
           E.ER_ORGANIZZAZIONE_GS_ID,
           E.ER_ORGANIZZAZIONE_GS_BELFIORE,
           E.ER_ORGANIZZAZIONE_GS_NOME,
           E.ORGMAST_CF,
           E.ER_ORGANIZZAZIONE_ER_CF,
           E.ER_ORGANIZZAZIONE_GS_CF,
           E.ER_ORGANIZZAZIONE_TIT_CF
      FROM V_T4_EROGAZIONI_FSE  fse,
           V_T4_EROGAZIONI      e
           LEFT JOIN V_EROG_FIRST_LAST primoultimostato
               ON (primoultimostato.ER_MAST_ID = e.ER_MAST_ID)
     WHERE     E.PR_ID = FSE.INTERVENTO_PR_ID
           AND E.Z_ZONA_SOCIALE = FSE.Z_ZONA_SOCIALE
           AND E.ER_SOGG_FLAG_RIFERIMENTO = 1;


DROP VIEW CS_ROMA.V_BI_TR_CS_PR;

/* Formatted on 18/07/2022 12:23:39 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_PR
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    CASO_ID,
    ER_MAST_ID,
    ER_SOGG_STATO_ITER,
    ER_CS_ID,
    TI_COD_ISTAT,
    COD_PRESTAZIONE,
    PROTOCOLLO_DSU,
    DATA_DSU,
    FLAG_PROVA_MEZZI,
    TIC_CODICE_MEMO,
    FLAG_SOGGETTO_IN_CARICO,
    ER_O_CODICE_ORG_ER,
    ER_SETTORE_EROG_NOME,
    ER_TIPO_BENEFICIARIO,
    ER_NUM_BENEFICIARI,
    ER_O_CODICE_ORG_TIT,
    ER_SETTORE_TIT_NOME,
    ER_OPE_COG_INS,
    ER_OPE_NOME_INS,
    FLAG_SERVIZIO_AMBITO,
    FF_FONTE_FINANZIAMENTO,
    FF_PROGETTO,
    PR_N_SOTTOCORSO_ATTIVITA,
    ER_SPESA,
    ER_COMPART_SSN,
    ER_COMPART_UTENTI,
    ER_COMPART_ALTRE,
    QR_FREQUENZA_SERVIZIO,
    QR_FLAG_PERIODO_RIPARTIZ,
    QR_N_GG_SETTIMANALI,
    QR_VAL_QUOTA_PERIODO,
    ER_UNITA_MISURA,
    QR_N_TOT_ACCESSI_SERVIZIO,
    CDS_CONDIZIONE_LAVORATIVA,
    CDS_TITOLO_STUDIO,
    PAI_ID,
    ER_SOGG_COGNOME,
    ER_SOGG_NOME,
    ER_SOGG_CF,
    ER_SOGG_CITTADINANZA,
    ER_SOGG_SESSO,
    ER_SOGG_ANNO_NASCITA,
    ER_SOGG_RES_INDIRIZZO,
    ER_SOGG_RES_COMUNE_ID,
    ER_SOGG_RES_PROVINCIA_SIGLA
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            'CS_PR'
                AS TIPO_RECORD,
            (SELECT nome FROM cs_o_zona_soc)
                Z_ZONA_SOCIALE,
            inv.ID_INVIANTE
                CODICE_INVIANTE,
            E.ER_SOGG_CASO_ID
                CASO_ID,
            E.ER_ID
                ER_MAST_ID,
            E.ER_SOGG_STATO_ITER,
            E.ER_CS_ID,
            TI_COD_ISTAT,
            PS.COD_PRESTAZIONE,
            DECODE (
                (   PS.PREFIX_PROT_DSU
                 || '-'
                 || PS.NUM_PROT_DSU
                 || '-'
                 || PS.PROG_PROT_DSU),
                '--', NULL,
                (   PS.PREFIX_PROT_DSU
                 || '-'
                 || PS.NUM_PROT_DSU
                 || '-'
                 || PS.PROG_PROT_DSU))
                PROTOCOLLO_DSU,
            PS.DATA_DSU,
            PS.FLAG_PROVA_MEZZI,
            E.TIC_CODICE_MEMO,
            DECODE (NVL (PS.FLAG_IN_CARICO, '2'),
                    1, 'Si',
                    0, 'No',
                    'Non so')
                FLAG_SOGGETTO_IN_CARICO,
            ER_O.O_CODICE_ORG
                ER_O_CODICE_ORG_ER,
            NVL (E.ER_SETTORE_EROG, 'Non specificato')
                ER_SETTORE_EROG_NOME,
            E.ER_TIPO_BENEFICIARIO,
            (SELECT COUNT (UPPER (SOGG.CF))
               FROM CS_I_INTERVENTO_ESEG_MAST_SOGG SOGG
              WHERE     E.ER_ID = SOGG.INT_ESEG_MAST_ID
                    AND SOGG.FLAG_RIFERIMENTO = 0)
                ER_NUM_BENEFICIARI,
            ER_T.O_CODICE_ORG
                ER_O_CODICE_ORG_TIT,
            NVL (E.ER_SETTORE_TIT, 'Non specificato')
                ER_SETTORE_TIT_NOME,
            E.ER_OPE_COG_INS,
            E.ER_OPE_NOME_INS,
            DECODE (PR.FLAG_SERVIZIO_AMBITO, 1, 'SI', 'NO')
                FLAG_SERVIZIO_AMBITO,
            E.FF_FONTE_FINANZIAMENTO,
            E.FF_PROGETTO_DESCRIZIONE
                FF_PROGETTO,
            E.PR_N_SOTTOCORSO_ATTIVITA,
            E.ER_SPESA,
            E.ER_COMPART_SSN,
            E.ER_COMPART_UTENTI,
            E.ER_COMPART_ALTRE,
            E.QR_FREQUENZA_SERVIZIO,
            E.QR_FLAG_PERIODO_RIPARTIZ,
            E.QR_N_GG_SETTIMANALI,
            E.QR_VAL_QUOTA_PERIODO,
            E.ER_UNITA_MISURA
                ER_UNITA_MISURA,
            E.QR_N_TOT_ACCESSI_SERVIZIO,
            PR.COND_LAVORO
                CDS_CONDIZIONE_LAVORATIVA,
            PR.TITOLO_STUDIO
                CDS_TITOLO_STUDIO,
            E.PAI_ID,
            E.ER_SOGG_COGNOME,
            E.ER_SOGG_NOME,
            E.ER_SOGG_CF,
            DECODE (E.ER_SOGG_CITTADINANZA,
                    'ITALIANA', '000',
                    NAZ_CITTADINANZA.COD_ISTAT_NAZIONE)
                ER_SOGG_CITTADINANZA,
            E.ER_SOGG_SESSO,
            E.ER_SOGG_ANNO_NASCITA,
            E.er_sogg_res_indirizzo
                ER_SOGG_RES_INDIRIZZO,
            E.ER_SOGG_RES_COMUNE_ISTAT
                ER_SOGG_RES_COMUNE_ID,
            E.ER_SOGG_RES_PROV
                ER_SOGG_RES_PROVINCIA_SIGLA
       FROM V_EROG_LST_MASTER  E
            LEFT JOIN V_BI_INVIANTE INV
                ON (    E.ER_ORGANIZZAZIONE_TIT_ID = INV.ID_ORGANIZZAZIONE
                    AND INV.TIPO_INVIANTE = 'SISO')
            LEFT JOIN CS_I_PS PS ON PS.INT_ESEG_MAST_ID = E.ER_ID
            LEFT JOIN V_BI_UTIL_TIPO_ORG ER_O
                ON ER_O.ID_ORGANIZZAZIONE = E.ER_ORGANIZZAZIONE_ER_ID
            LEFT JOIN V_BI_UTIL_TIPO_ORG ER_T
                ON ER_T.ID_ORGANIZZAZIONE = E.ER_ORGANIZZAZIONE_TIT_ID
            LEFT JOIN V_EROG_MAST_PR PR ON E.PR_ID = PR.PR_ID
            LEFT JOIN AM_TAB_NAZIONI NAZ_CITTADINANZA
                ON (    E.ER_SOGG_CITTADINANZA = NAZ_CITTADINANZA.NAZIONALITA
                    AND NAZ_CITTADINANZA.NAZIONALITA_PRINCIPALE = 1
                    AND NAZ_CITTADINANZA.ATTIVO = 1)
      WHERE E.ER_SOGG_FLAG_RIFERIMENTO = 1);


DROP VIEW CS_ROMA.V_BI_TR_CS_PRB;

/* Formatted on 18/07/2022 12:23:39 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_PRB
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    ER_MAST_ID,
    ER_TIPO_BENEFICIARIO,
    ER_SOGG_COGNOME,
    ER_SOGG_NOME,
    ER_SOGG_CF,
    ER_SOGG_CITTADINANZA,
    ER_SOGG_SESSO,
    ER_SOGG_ANNO_NASCITA
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            'CS_PRB'
                AS TIPO_RECORD,
            (SELECT nome FROM cs_o_zona_soc)
                Z_ZONA_SOCIALE,
            inv.ID_INVIANTE
                CODICE_INVIANTE,
            E.ER_ID
                ER_MAST_ID,
            E.ER_TIPO_BENEFICIARIO,
            E.ER_SOGG_COGNOME,
            E.ER_SOGG_NOME,
            E.ER_SOGG_CF,
            DECODE (E.ER_SOGG_CITTADINANZA,
                    'ITALIANA', '000',
                    NAZ_CITTADINANZA.COD_ISTAT_NAZIONE)
                ER_SOGG_CITTADINANZA,
            E.ER_SOGG_SESSO,
            E.ER_SOGG_ANNO_NASCITA
       FROM V_EROG_LST_MASTER  E
            LEFT JOIN V_BI_INVIANTE INV
                ON E.ER_ORGANIZZAZIONE_TIT_ID = INV.ID_ORGANIZZAZIONE
            LEFT JOIN AM_TAB_NAZIONI NAZ_CITTADINANZA
                ON (    E.ER_SOGG_CITTADINANZA = NAZ_CITTADINANZA.NAZIONALITA
                    AND NAZ_CITTADINANZA.NAZIONALITA_PRINCIPALE = 1
                    AND NAZ_CITTADINANZA.ATTIVO = 1)
      WHERE E.ER_SOGG_FLAG_RIFERIMENTO = 0);


DROP VIEW CS_ROMA.V_BI_TR_CS_PRD;

/* Formatted on 18/07/2022 12:23:39 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_BI_TR_CS_PRD
(
    TIPO_RECORD,
    Z_ZONA_SOCIALE,
    CODICE_INVIANTE,
    ER_MAST_ID,
    ER_DETT_ID,
    ER_DATA_ESECUZIONE,
    ER_DATA_ESECUZIONE_A,
    ER_QUOTA_VALORE,
    ER_SPESA_DETT,
    ER_COMPART_SSN,
    ER_COMPART_UTENTI,
    ER_COMPART_ALTRE,
    ER_OPERATORE_DENOM,
    ER_STATO_NOME
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            'CS_PRD'                             AS TIPO_RECORD,
            (SELECT nome FROM cs_o_zona_soc)     Z_ZONA_SOCIALE,
            inv.ID_INVIANTE                      CODICE_INVIANTE,
            E.ER_ID                              ER_MAST_ID,
            D.ER_DETT_ID,
            D.ER_DATA_ESECUZIONE,
            ES.DATA_ESECUZIONE_A                 ER_DATA_ESECUZIONE_A,
            D.ER_QUOTA_VALORE,
            D.ER_SPESA_DETT,
            ES.COMPART_SSN                       ER_COMPART_SSN,
            ES.COMPART_UTENTI                    ER_COMPART_UTENTI,
            ES.COMPART_ALTRE                     ER_COMPART_ALTRE,
            D.ER_OPERATORE_DENOM,
            D.ER_STATO_NOME
       FROM V_EROG_LST_MASTER  E
            LEFT JOIN V_BI_INVIANTE INV
                ON E.ER_ORGANIZZAZIONE_TIT_ID = INV.ID_ORGANIZZAZIONE
            LEFT JOIN V_EROG_LST_DETT D ON D.ER_MAST_ID = E.ER_ID
            LEFT JOIN CS_I_INTERVENTO_ESEG ES ON D.ER_DETT_ID = ES.ID);


