DROP VIEW CS_ROMA.V_T4_EROGAZIONI_FSE_WS;

/* Formatted on 18/07/2022 12:23:39 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW CS_ROMA.V_T4_EROGAZIONI_FSE_WS
(
    ER_MAST_ID,
    PR_ID,
    Z_ZONA_SOCIALE,
    ATTIVITA_ID,
    NOME,
    COGNOME,
    CODICE_FISCALE,
    SESSO,
    DATA_NASCITA,
    COMUNE_NASCITA_ID,
    NAZIONE_NASCITA_ID,
    CITTADINANZA,
    INDIRIZZO_RESIDENZA,
    COMUNE_RES_ID,
    CAP_RESIDENZA,
    INDIRIZZO_DOMICILIO,
    COMUNE_DOM_ID,
    CAP_DOMICILIO,
    TELEFONO,
    CELLULARE,
    EMAIL,
    COND_MERCATO_INGRESSO,
    FLAG_FREQUENZA_ALTRO_CORSO,
    DURATA_RICERCA,
    TIPOLOGIA_LAVORO_ID,
    TIPO_ORARIO_LAVORO_ID,
    RAGIONE_SOCIALE_AZIENDA,
    PARTITA_IVA_AZIENDA,
    CODICE_FISCALE_AZIENDA,
    INDIRIZZO_AZIENDA,
    COMUNE_AZIENDA_ID,
    ATECO_AZIENDA_COD_ATECO_ANNO,
    FORMA_GIURIDICA_RNA_AZ_COD,
    DIMENSIONE_AZIENDA_ID,
    TITOLO_STUDIO,
    ANNO_CONSEGUIMENTO_TITOLO,
    CODICE_VULNERABILE_PA,
    IBAN,
    FLAG_COMUNICAZIONE_RESIDENZA,
    CAP_AZIENDA,
    DATA_INGRESSO,
    DATA_USCITA,
    STATO_PARTECIPANTE,
    DATA_CONSEGUIMENTO_QUALIFICA
)
BEQUEATH DEFINER
AS
    (SELECT DISTINCT
            WS0.ER_MAST_ID,
            WS0.pr_id,
            Z_ZONA_SOCIALE,
            WS0.attivita_id,
            WS0.nome,
            WS0.cognome,
            WS0.codice_fiscale,
            WS0.SESSO,
            WS0.DATA_NASCITA,
            WS0.COMUNE_NASCITA_ID,
            WS0.NAZIONE_NASCITA_ID,
            WS0.CITTADINANZA,
            WS0.INDIRIZZO_RESIDENZA,
            WS0.COMUNE_RES_ID,
            WS0.CAP_RESIDENZA,
            WS0.INDIRIZZO_DOMICILIO,
            WS0.COMUNE_DOM_ID,
            WS0.CAP_DOMICILIO,
            WS0.TELEFONO,
            WS0.CELLULARE,
            WS0.EMAIL,
            WS0.COND_MERCATO_INGRESSO,
            WS0.FLAG_FREQUENZA_ALTRO_CORSO    FLAG_FREQUENZA_ALTRO_CORSO,
            WS0.DURATA_RICERCA,
            WS0.TIPOLOGIA_LAVORO_ID,
            WS0.TIPO_ORARIO_LAVORO_ID,
            WS0.RAGIONE_SOCIALE_AZIENDA,
            WS0.PARTITA_IVA_AZIENDA,
            WS0.CODICE_FISCALE_AZIENDA        CODICE_FISCALE_AZIENDA,
            WS0.INDIRIZZO_AZIENDA,
            WS0.COMUNE_AZIENDA_ID,
            WS0.ATECO_AZIENDA_COD_ATECO_ANNO,
            WS0.FORMA_GIURIDICA_RNA_AZ_COD,
            WS0.DIMENSIONE_AZIENDA_ID,
            WS0.TITOLO_STUDIO,
            WS0.ANNO_CONSEGUIMENTO_TITOLO,
            WS0.CODICE_VULNERABILE_PA,
            WS0.IBAN,
            WS0.FLAG_COMUNICAZIONE_RESIDENZA,
            WS0.CAP_AZIENDA,
            WS0.er_primo_stato_dt             DATA_INGRESSO,
            DECODE (WS0.er_ultimo_stato_FLAG_CHIUDI,
                    1, WS0.ER_ULTIMO_STATO_DT,
                    NULL)                     AS DATA_USCITA,
            CASE WS0.er_ultimo_stato
                WHEN 'Ritirato durante servizio'
                THEN
                    '02'
                WHEN 'Ritirato prima di iniziare'
                THEN
                    '03'
                WHEN 'Respinto/Non ammesso'
                THEN
                    '03'
                ELSE
                    (CASE WS0.er_ultimo_stato_TIPO
                         WHEN 'E'
                         THEN
                             '01'
                         ELSE
                             (CASE WS0.ER_ULTIMO_STATO_FLAG_CHIUDI
                                  WHEN 1 THEN '02'
                                  WHEN 0 THEN '01'
                              END)
                     END)
            END                               AS STATO_PARTECIPANTE,
            NULL                              DATA_CONSEGUIMENTO_QUALIFICA
       FROM V_T4_EROGAZIONI_FSE_WS0 WS0);

DROP VIEW ARGO_ROMA.RDC_ANAGRAFICA_GEPI;

/* Formatted on 18/07/2022 12:23:48 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGO_ROMA.RDC_ANAGRAFICA_GEPI
(
    ID_DOMANDA,
    DATA_PRESENTAZIONE_DOMANDA,
    AMBITO_APPARTENENZA,
    CF,
    NOME_COMPLETO,
    DATA_NASCITA,
    SESSO,
    NAS_COMUNE_COD,
    NAS_COMUNE_DES,
    NAZIONALITA,
    RES_COMUNE_COD,
    RES_INDIRIZZO,
    TELEFONO,
    CELLULARE,
    EMAIL,
    RICHIEDENTE
)
BEQUEATH DEFINER
AS
    SELECT D.cod_identificativo_dom                  AS id_domanda,
           d.data_presentazione_domanda,
           d.ambito_appartenenza,
           F.CF,
           F.NOME_COMPLETO,
           f.data_nascita,
           f.genere                                  AS sesso,
           F.COD_COMUNE_NAS                          AS NAS_COMUNE_COD,
           F.COMUNE_NAS                              AS NAS_COMUNE_DES,
           F.NAZIONALITA,
           D.RESIDENZA_COMUNE_COD                    AS RES_COMUNE_COD,
           F.INDIRIZZO                               AS RES_INDIRIZZO,
           F.TELEFONO,
           F.CELLULARE,
           F.EMAIL,
           CASE F.CF WHEN D.CF THEN 1 ELSE 0 END     RICHIEDENTE
      FROM RDC_GEPI_DOMANDA  D
           LEFT JOIN RDC_GEPI_COMPONENTE_FAMIGLIA F
               ON F.FK_RDC_DOMANDA = D.cod_identificativo_dom;


DROP VIEW ARGO_ROMA.RDC_USER;

/* Formatted on 18/07/2022 12:23:48 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGO_ROMA.RDC_USER
(
    USERNAME,
    ENTE_DEFAULT,
    PATH_ROOT,
    COGNOME,
    NOME,
    CF,
    COMUNE_NASCITA,
    DATA_NASCITA,
    PROVINCIA_NASCITA,
    SESSO,
    EMAIL
)
BEQUEATH DEFINER
AS
    (SELECT username,
            RDC_COMUNE_FK      ENTE_DEFAULT,
            path_root,
            cognome,
            nome,
            codice_fiscale     cf,
            comune_nascita,
            data_nascita,
            provincia_nascita,
            sesso,
            email
       FROM RDC_USER_ANAGRAFICA  a,
            RDC_AM_PATH          PATH,
            (SELECT *
               FROM (SELECT schema_orig,
                            RDC_USER_FK,
                            RDC_COMUNE_FK,
                            ROW_NUMBER ()
                                OVER (PARTITION BY schema_orig, RDC_USER_FK
                                      ORDER BY RDC_COMUNE_FK)    AS rownumber
                       FROM RDC_USER_ENTE)
              WHERE rownumber = 1) ue
      WHERE     PATH.SCHEMA_ORIG = A.SCHEMA_ORIG
            AND A.USERNAME = UE.RDC_USER_FK
            AND A.SCHEMA_ORIG = UE.SCHEMA_ORIG);


DROP VIEW ARGO_ROMA.V_GERARCHIA_SERVIZI;

/* Formatted on 18/07/2022 12:23:48 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGO_ROMA.V_GERARCHIA_SERVIZI
(
    ID,
    Q_CLASSE_ID,
    T_CLASSE_ID,
    NUM_LIVELLO,
    DESC_LIVELLO,
    CODICE_MEMO,
    DESCRIZIONE,
    DESCRIZIONE2,
    FLAG_INTERVENTO,
    ROOT_T_CLASSE_ID,
    ROOT_DESCRIZIONE,
    AREAT_ID
)
BEQUEATH DEFINER
AS
        SELECT AR_Q_CLASSE.id,
               AR_Q_CLASSE.Q_CLASSE_ID,
               AR_Q_CLASSE.t_classe_id,
               LEVEL
                   NUM_LIVELLO,
               LPAD ('-', 2 * (LEVEL - 1)) || AR_T_CLASSE.DESCRIZIONE
                   DESC_LIVELLO,
               ar_t_classe.codice_memo,
               AR_T_CLASSE.DESCRIZIONE,
               AR_T_CLASSE.DESCRIZIONE2,
               AR_Q_CLASSE.flag_intervento,
               CONNECT_BY_ROOT AR_T_CLASSE.ID
                   AS root_t_classe_id,
               CONNECT_BY_ROOT AR_T_CLASSE.DESCRIZIONE
                   AS root_DESCRIZIONE,
               ar_q_classe.areat_id
          FROM AR_Q_CLASSE, AR_T_CLASSE
         WHERE AR_Q_CLASSE.T_CLASSE_ID = AR_T_CLASSE.ID AND MODELLO_ID = '4'
    START WITH AR_Q_CLASSE.Q_CLASSE_ID IS NULL
    CONNECT BY PRIOR AR_Q_CLASSE.ID = AR_Q_CLASSE.Q_CLASSE_ID;


DROP VIEW ARGO_ROMA.V_LINEAFIN;

/* Formatted on 18/07/2022 12:23:48 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGO_ROMA.V_LINEAFIN
(
    ID,
    CODICE_MEMO,
    DESCRIZIONE,
    USER_INS,
    DT_INS,
    USR_MOD,
    DT_MOD,
    ABILITATO,
    DATA_INIZIO_VAL,
    DT_FINE_VAL,
    FONDO_ID,
    PROGETTO_ID,
    IMPORTO,
    FONDO,
    PROGETTO,
    BELFIORE
)
BEQUEATH DEFINER
AS
    SELECT l."ID",
           l."CODICE_MEMO",
           l."DESCRIZIONE",
           l."USER_INS",
           l."DT_INS",
           l."USR_MOD",
           l."DT_MOD",
           l."ABILITATO",
           l."DATA_INIZIO_VAL",
           l."DT_FINE_VAL",
           l."FONDO_ID",
           l."PROGETTO_ID",
           l."IMPORTO",
           f.descrizione     fondo,
           p.descrizione     progetto,
           o.belfiore
      FROM ar_o_organizzazione  o
           INNER JOIN ar_ff_lineafin_org lfo ON o.id = lfo.organizzazione_id
           INNER JOIN ar_ff_lineafin l ON lfo.lineafin_id = l.id
           LEFT JOIN ar_ff_fondo f ON (l.fondo_id = f.id)
           LEFT JOIN ar_ff_progetto p ON L.PROGETTO_ID = p.id;


