DROP VIEW ARGO_ROMA.V_RDC_TB_CODICI_SAP;

/* Formatted on 18/07/2022 12:23:48 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGO_ROMA.V_RDC_TB_CODICI_SAP
(
    TABELLA,
    CODICE,
    DESCRIZIONE
)
BEQUEATH DEFINER
AS
    (SELECT "TABELLA", "CODICE", "DESCRIZIONE" FROM RDC_TB_SAP_CODICI
     UNION ALL
     SELECT 'ATECO2007', codice, descrizione FROM AR_TB_ATECO
     UNION ALL
     SELECT 'CITTADINANZA', c.cod_cittadinanza, c.des_cittadinanza
       FROM AR_TB_NAZIONI c
     UNION ALL
     SELECT 'CPI - OPERATORI ABILITATI GG', CODICE, DENOMINAZIONE
       FROM RDC_TB_CPI
     UNION ALL
     SELECT 'CPI - OPERATORI ABILITATI GG', COD_INTERMEDIARIO, NOME
       FROM RDC_TB_OPERATORI_ABILITATI_GG
     UNION ALL
     SELECT DISTINCT 'COMUNE O NAZIONE', cod_comune, des_comune
       FROM AR_TB_COMUNI
      WHERE SYSDATE BETWEEN dt_inizio AND dt_fine
     UNION ALL
     SELECT DISTINCT 'COMUNE O NAZIONE', cod_min_finanze, des_nazione
       FROM AR_TB_NAZIONI
      WHERE cod_min_finanze IS NOT NULL
     UNION ALL
     SELECT DISTINCT 'REGIONI PROVINCE AUTONOME', codice, descrizione
       FROM AR_TB_REGIONI);


DROP VIEW ARGO_ROMA.V_SERVIZI_CUSTOM;

/* Formatted on 18/07/2022 12:23:48 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGO_ROMA.V_SERVIZI_CUSTOM
(
    INTERVENTO_CUSTOM_ID,
    CODICE_MEMO,
    INTERVENTO_DESCRIZIONE,
    AREAT_ID,
    AREAT_DESCRIZIONE,
    CODICE_MEMO_AREAT,
    INPS_CODICE,
    INPS_DENOMINAZIONE,
    INPS_DESCRIZIONE,
    INPS_PSA
)
BEQUEATH DEFINER
AS
      SELECT INTCUSTOM.ID
                 INTERVENTO_CUSTOM_ID,
             INTCUSTOM.CODICE_MEMO,
             INTCUSTOM.DESCRIZIONE
                 INTERVENTO_DESCRIZIONE,
             CSAREAT.ID
                 AREAT_ID,
             REPLACE (CSAREAT.DESCRIZIONE, 'Famiglie', 'Famiglia')
                 AREAT_DESCRIZIONE,
             CSAREAT.CODICE_MEMO
                 CODICE_MEMO_AREAT,
             TABINPS.CODICE
                 INPS_CODICE,
             TABINPS.DENOMINAZIONE
                 INPS_DENOMINAZIONE,
             TABINPS.DESCRIZIONE
                 INPS_DESCRIZIONE,
             TABINPS.FLAG_PSA
                 PSA
        FROM CS_C_TIPO_INTERVENTO_CUSTOM intCustom
             INNER JOIN AR_REL_INT_CUSTOM_AREAT areat
                 ON INTCUSTOM.ID = AREAT.INT_CUSTOM_ID
             INNER JOIN AR_CS_AREAT csAreat ON AREAT.T_AREA_ID = CSAREAT.ID
             LEFT JOIN AR_REL_INT_CUSTOM_PRES_INPS customInps
                 ON INTCUSTOM.ID = CUSTOMINPS.CUSTOM_CLASSE_ID
             LEFT JOIN AR_TB_PRESTAZIONI_INPS tabINPS
                 ON CUSTOMINPS.PRESTAZIONE_INPS_CODICE = TABINPS.CODICE
       WHERE INTCUSTOM.ABILITATO = 1
    ORDER BY INTCUSTOM.ID ASC;


DROP VIEW ARGO_ROMA.V_STRUTTURA_AREA;

/* Formatted on 18/07/2022 12:23:48 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGO_ROMA.V_STRUTTURA_AREA
(
    ID_STRUTTURA,
    NOME_STRUTTURA,
    INDIRIZZO,
    FLAG_ATTREZZATO,
    TIPO_STRUTTURA,
    ABILITATO,
    TIPOLOGIA_SERVIZIO,
    GESTORE_SERVIZIO,
    TELEFONO_FISSO_GESTORE,
    MAIL_GESTORE,
    PEC_GESTORE,
    COORDINATORE,
    TELEFONO_FISSO_COORDINATORE,
    MAIL_COORDINATORE,
    CODICE_COMUNE,
    DESCRIZIONE_COMUNE,
    COD_BELFIORE_COMUNE,
    MACRO_TIPOLOGIA_SERVIZIO,
    ID_TIPOLOGIA_SERVIZIO,
    ID_AREA,
    DESCRIZIONE
)
BEQUEATH DEFINER
AS
      SELECT a.id              AS id_struttura,
             a.NOME_STRUTTURA,
             a.INDIRIZZO,
             a.FLAG_ATTREZZATO,
             a.TIPO_STRUTTURA,
             a.ABILITATO,
             a.TIPOLOGIA_SERVIZIO,
             a.GESTORE_SERVIZIO,
             a.TELEFONO_FISSO_GESTORE,
             a.MAIL_GESTORE,
             a.PEC_GESTORE,
             a.COORDINATORE,
             a.TELEFONO_FISSO_COORDINATORE,
             a.MAIL_COORDINATORE,
             a.CODICE_COMUNE,
             a.DESCRIZIONE_COMUNE,
             a.COD_BELFIORE_COMUNE,
             a.MACRO_TIPOLOGIA_SERVIZIO,
             a.ID_TIPOLOGIA_SERVIZIO,
             NVL (c.id, 0)     AS id_Area,
             c.DESCRIZIONE
        FROM AR_RP_STRUTTURA a
             LEFT JOIN AR_RP_REL_STRUTTURA_AREA b ON a.ID = b.ID_STRUTTURA
             LEFT JOIN AR_RP_AREA c ON b.ID_AREA = c.ID
    ORDER BY NOME_STRUTTURA;


