DROP VIEW DBTOTALE_H501.SUCCESSIONI;

/* Formatted on 18/07/2022 12:23:57 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DBTOTALE_H501.SUCCESSIONI
(
    CF_DEFUNTO,
    COGNOME_DEFUNTO,
    NOME_DEFUNTO,
    STATO_SOGGETTO_D,
    CF_EREDE,
    COGNOME_EREDE,
    NOME_EREDE,
    STATO_SOGGETTO_E,
    PERC,
    FOGLIO,
    PARTICELLA,
    PARTICELLA_DUE,
    SUBALTERNO,
    SUBALTERNO_DUE,
    DENUNCIA,
    DENUNCIA_DUE,
    NUM_Q,
    DEN_Q,
    DATA_APERTURA,
    TIPO_DICHIARAZIONE,
    INDIRIZZO_IMMOBILE,
    AGEVOLAZIONE_1_CASA,
    UFFICIO,
    ANNO,
    VOLUME,
    NUMERO,
    SOTTONUMERO,
    COMUNE,
    PROGRESSIVO,
    FORNITURA
)
BEQUEATH DEFINER
AS
    SELECT A.cf_defunto,
           A.COGNOME_DEFUNTO,
           A.NOME_DEFUNTO,
           'DEFUNTO'
               AS STATO_SOGGETTO_D,
           B.cf_erede,
           RTRIM (SUBSTR (B.DENOMINAZIONE, 1, 25))
               COGNOME_EREDE,
           RTRIM (SUBSTR (B.DENOMINAZIONE, 26))
               NOME_EREDE,
           'EREDE'
               AS STATO_SOGGETTO_E,
           ROUND (
               DECODE (D.denominatore_quota,
                       NULL, NULL,
                       0, NULL,
                       D.numeratore_quota / D.denominatore_quota * 100),
               3)
               perc,
           DECODE (C.foglio, NULL, '-', C.foglio)
               AS foglio,
           DECODE (C.particella1, NULL, '-', C.particella1)
               AS particella,
           DECODE (C.particella2, NULL, '-', C.particella2)
               AS particella_due,
           DECODE (C.subalterno1, NULL, '-', C.subalterno1)
               AS subalterno,
           DECODE (C.subalterno2, NULL, '-', C.subalterno2)
               AS subalterno_due,
           DECODE (C.denuncia1, NULL, '-', C.denuncia1)
               AS denuncia,
           DECODE (C.denuncia2, NULL, '-', C.denuncia2)
               AS denuncia_due,
           NUMERATORE_QUOTA
               NUM_Q,
           DENOMINATORE_QUOTA
               DEN_Q,
           TO_DATE (A.DATA_APERTURA, 'YYYY-MM-DD')
               DATA_APERTURA,
           A.TIPO_DICHIARAZIONE,
           C.INDIRIZZO_IMMOBILE,
           D.AGEVOLAZIONE_1_CASA,
           A.UFFICIO,
           A.ANNO,
           A.VOLUME,
           A.NUMERO,
           A.SOTTONUMERO,
           A.COMUNE,
           A.PROGRESSIVO,
           A.FORNITURA
      FROM MI_SUCCESSIONI_A  A,
           MI_SUCCESSIONI_B  B,
           MI_SUCCESSIONI_C  C,
           MI_SUCCESSIONI_D  D
     WHERE     D.ufficio = C.ufficio
           AND D.anno = C.anno
           AND D.volume = C.volume
           AND D.numero = C.numero
           AND D.sottonumero = C.sottonumero
           AND D.comune = C.comune
           AND D.progressivo_immobile = C.progressivo_immobile
           ------
           AND D.ufficio = A.ufficio
           AND D.anno = A.anno
           AND D.volume = A.volume
           AND D.numero = A.numero
           AND D.sottonumero = A.sottonumero
           AND D.comune = A.comune
           ------
           AND D.ufficio = B.ufficio
           AND D.anno = B.anno
           AND D.volume = B.volume
           AND D.numero = B.numero
           AND D.sottonumero = B.sottonumero
           AND D.comune = B.comune
           AND D.progressivo_erede = B.progressivo_erede;


DROP VIEW DBTOTALE_H501.UIU_VISTA;

/* Formatted on 18/07/2022 12:23:57 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DBTOTALE_H501.UIU_VISTA
(
    CHIAVE,
    FOGLIO,
    PARTICELLA,
    SUB,
    UNIMM,
    FK_COMUNE,
    PKID_UIU,
    DATA_INIZIO_VAL,
    DATA_FINE_VAL,
    COD_NAZIONALE
)
BEQUEATH DEFINER
AS
    SELECT    cod_nazionale
           || '|'
           || foglio
           || '|'
           || particella
           || '|'
           || sub
           || '|'
           || unimm
           || '|'
           || TO_CHAR (data_fine_val, 'dd/mm/yyyy')
           || '|'
           || TO_CHAR (data_inizio_val, 'dd/mm/yyyy')    AS chiave,
           foglio                                        AS foglio,
           LTRIM (RTRIM (particella))                    AS particella,
           sub                                           AS sub,
           unimm                                         AS unimm,
           cod_nazionale                                 AS fk_comune,
           pkid_uiu                                      AS pkid_uiu,
           data_inizio_val                               AS data_inizio_val,
           data_fine_val                                 AS data_fine_val,
           cod_nazionale
      FROM sitiuiu;


DROP VIEW DBTOTALE_H501.VISTA_CIVICI_UIU_VISTA;

/* Formatted on 18/07/2022 12:23:57 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DBTOTALE_H501.VISTA_CIVICI_UIU_VISTA
(
    PK_SEQU_CIVICO,
    CROSSLINK_CIVICO,
    COD_NAZIONALE,
    FK_ID_STRA,
    UK_CIVICO,
    NOME_VIA,
    SEDIME,
    DESCRIZIONE_CIVICO,
    PKID_STRA,
    DESCR_VIA,
    FOGLIO_CATASTALE,
    PARTICELLA_CATASTALE,
    SUBALTERNO,
    UNITA_IMMOBILIARE,
    DATA_ATTIVAZIONE
)
BEQUEATH DEFINER
AS
    SELECT civ.pkid_civi                                  AS pk_sequ_civico,
              civ.cod_nazionale
           || LPAD (NVL (civ.pkid_stra, '00000000'), 8, 0)
           || LPAD (NVL (civ.civico, '0000000'), 7, 0)
           || '000000000'                                 AS crosslink_civico,
           civ.cod_nazionale                              AS cod_nazionale,
           str.pkid_stra                                  AS fk_id_stra,
              TRIM (civ.cod_nazionale)
           || '|'
           || TRIM (str.nome)
           || '|'
           || TRIM (str.prefisso)
           || '|'
           || TRIM (civ.civico)                           AS uk_civico,
           str.nome                                       AS nome_via,
           str.prefisso                                   AS sedime,
           civ.civico                                     AS descrizione_civico,
           str.pkid_stra                                  AS pkid_stra,
           str.prefisso || ' ' || str.nome                AS descr_via,
           uiu.foglio                                     AS foglio_catastale,
           uiu.particella                                 AS particella_catastale,
           uiu.sub                                        AS subalterno,
           LPAD (TO_CHAR (uiu.unimm), 4, '0')             AS unita_immobiliare,
           TO_CHAR (civ.data_inizio_val, 'DD/MM/YYYY')    AS data_attivazione
      FROM siticivi      civ,
           sitidstr      str,
           siticivi_uiu  ciuiu,
           sitiuiu       uiu
     WHERE     uiu.pkid_uiu(+) = ciuiu.pkid_uiu
           AND ciuiu.pkid_civi(+) = civ.pkid_civi
           AND civ.pkid_stra = str.pkid_stra(+)
           AND str.data_fine_val(+) =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
           AND civ.data_fine_val =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
           AND ciuiu.data_fine_val(+) =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
           AND uiu.data_fine_val(+) =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');


DROP VIEW DBTOTALE_H501.VISTA_CIVICI_VISTA;

/* Formatted on 18/07/2022 12:23:57 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW DBTOTALE_H501.VISTA_CIVICI_VISTA
(
    PK_SEQU_CIVICO,
    CROSSLINK_CIVICO,
    COD_NAZIONALE,
    FK_ID_STRA,
    UK_CIVICO,
    NOME_VIA,
    SEDIME,
    DESCRIZIONE_CIVICO,
    PKID_STRA,
    DESCR_VIA,
    DATA_ATTIVAZIONE
)
BEQUEATH DEFINER
AS
    SELECT civ.pkid_civi                                  AS pk_sequ_civico,
              civ.cod_nazionale
           || LPAD (NVL (civ.pkid_stra, '00000000'), 8, 0)
           || LPAD (NVL (civ.civico, '0000000'), 7, 0)
           || '000000000'                                 AS crosslink_civico,
           civ.cod_nazionale                              AS cod_nazionale,
           str.pkid_stra                                  AS fk_id_stra,
              TRIM (civ.cod_nazionale)
           || '|'
           || TRIM (str.nome)
           || '|'
           || TRIM (str.prefisso)
           || '|'
           || TRIM (civ.civico)                           AS uk_civico,
           str.nome                                       AS nome_via,
           str.prefisso                                   AS sedime,
           civ.civico                                     AS descrizione_civico,
           str.pkid_stra                                  AS pkid_stra,
           str.prefisso || ' ' || str.nome                AS descr_via,
           TO_CHAR (civ.data_inizio_val, 'DD/MM/YYYY')    AS data_attivazione
      FROM siticivi civ, sitidstr str
     WHERE     civ.pkid_stra = str.pkid_stra
           AND str.data_fine_val =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
           AND civ.data_fine_val =
               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');


