CREATE TABLE SITI_H501.SITIUNAR
(
  PKID_UNAR         NUMBER(9)                   NOT NULL,
  COD_NAZIONALE     VARCHAR2(4 BYTE)            NOT NULL,
  FOGLIO            NUMBER(4)                   NOT NULL,
  PARTICELLA        CHAR(5 BYTE)                NOT NULL,
  SUB               VARCHAR2(3 BYTE)            NOT NULL,
  UNAR              NUMBER(5)                   NOT NULL,
  DATA_INIZIO_VAL   DATE                        DEFAULT SYSDATE               NOT NULL,
  DATA_FINE_VAL     DATE                        DEFAULT TO_DATE('99991231','YYYYMMDD') NOT NULL,
  DATA_LAV          DATE                        DEFAULT SYSDATE               NOT NULL,
  TIPO_UNAR         NUMBER(1)                   NOT NULL,
  AREA              NUMBER(10),
  SESTO_SU_FILA     NUMBER(4),
  SESTO_TRA_FILE    NUMBER(4),
  NUM_CEPPI         NUMBER(6)                   NOT NULL,
  ANNO_IMPI         NUMBER(4),
  FORMA_ALL         VARCHAR2(2 BYTE),
  FLAG_IRRI         NUMBER(1),
  COD_DEST_PROD     NUMBER(1)                   NOT NULL,
  COD_TIPO_COLT     NUMBER(1)                   NOT NULL,
  COD_VARIETA       VARCHAR2(3 BYTE)            NOT NULL,
  COD_TIPO_VARI     NUMBER(2)                   NOT NULL,
  UTENTE            VARCHAR2(20 BYTE),
  UTENTE_FINE       VARCHAR2(20 BYTE),
  ID_TRASF          NUMBER(9),
  ID_TRASF_FINE     NUMBER(9),
  NUM_PIAN_PROD     NUMBER(9),
  NUM_ALTRE         NUMBER(9),
  CAMPAGNA          NUMBER(4),
  COD_TIPO_VIGN     NUMBER(1)                   DEFAULT 0                     NOT NULL,
  TIPO_IMPI         NUMBER(1),
  NUM_CAST          NUMBER(5),
  IDEN_REGI         VARCHAR2(2 BYTE),
  SUPPLEMENTARI     NUMBER(1),
  MECCANIZZABILE    NUMBER(1),
  GIACITURA         NUMBER(1),
  ROCCIA            VARCHAR2(1 BYTE),
  SCHELETRO         NUMBER(1),
  STATO_VEGETATIVO  VARCHAR2(1 BYTE),
  POTATURA          VARCHAR2(1 BYTE),
  GIUDIZIO          VARCHAR2(1 BYTE),
  DIM_CHIOMA_CM     NUMBER(9),
  ETA_IMPI          VARCHAR2(1 BYTE),
  SORGENTE          NUMBER(9),
  ISOLATE           NUMBER(9),
  GRUPPO            NUMBER(9),
  ID_PARTICELLA     NUMBER(9)
)
TABLESPACE GIT
PCTUSED    0
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE;

COMMENT ON TABLE SITI_H501.SITIUNAR IS 'Catasto - Catasto unità arboree';

COMMENT ON COLUMN SITI_H501.SITIUNAR.PKID_UNAR IS 'Sequence';

COMMENT ON COLUMN SITI_H501.SITIUNAR.COD_NAZIONALE IS 'Codice Nazionale';

COMMENT ON COLUMN SITI_H501.SITIUNAR.FOGLIO IS 'Foglio';

COMMENT ON COLUMN SITI_H501.SITIUNAR.PARTICELLA IS 'Particella';

COMMENT ON COLUMN SITI_H501.SITIUNAR.SUB IS 'Subalterno';

COMMENT ON COLUMN SITI_H501.SITIUNAR.UNAR IS 'Numero progressivo dell''unità arborea all''interno della particella';

COMMENT ON COLUMN SITI_H501.SITIUNAR.DATA_INIZIO_VAL IS 'Data inizio validità';

COMMENT ON COLUMN SITI_H501.SITIUNAR.DATA_FINE_VAL IS 'Data fine validità';

COMMENT ON COLUMN SITI_H501.SITIUNAR.DATA_LAV IS 'Data lavorazione';

COMMENT ON COLUMN SITI_H501.SITIUNAR.TIPO_UNAR IS 'Tipologia dell''unità arborea:
0 = TUTTE LE ARBOREE
1 = VINO
2 = OLIO
3 = AGRUMI
4 = FAG
5 = ALTRE
6 = PERE/PESCHE
7 = CICLO BREVE';

COMMENT ON COLUMN SITI_H501.SITIUNAR.AREA IS 'Area dell''unità arborea (mq)';

COMMENT ON COLUMN SITI_H501.SITIUNAR.SESTO_SU_FILA IS 'Sesto su fila (cm)';

COMMENT ON COLUMN SITI_H501.SITIUNAR.SESTO_TRA_FILE IS 'Sesto tra file (cm)';

COMMENT ON COLUMN SITI_H501.SITIUNAR.NUM_CEPPI IS 'Numero ceppi';

COMMENT ON COLUMN SITI_H501.SITIUNAR.ANNO_IMPI IS 'Anno impianto';

COMMENT ON COLUMN SITI_H501.SITIUNAR.FORMA_ALL IS 'Forma di allevamento:
SELECT CODICE, DESCRIZIONE
FROM SITIUNAR_DECO
WHERE NOME_CAMPO = ''FORMA_ALL''
AND TIPO_UNAR = ?';

COMMENT ON COLUMN SITI_H501.SITIUNAR.FLAG_IRRI IS 'Flag irrigazione:
1 = NON IRRIGATO
2 = IRRIGATO
3 = SCORRIMENTO O A CONCHE
4 = GOCCIA
5 = ASPERSIONE';

COMMENT ON COLUMN SITI_H501.SITIUNAR.COD_DEST_PROD IS 'Destinazione produttiva:
SELECT CODICE, DESCRIZIONE
FROM SITIUNAR_DECO
WHERE NOME_CAMPO = ''COD_DEST_PROD''
AND TIPO_UNAR = ?';

COMMENT ON COLUMN SITI_H501.SITIUNAR.COD_TIPO_COLT IS 'Tipo di coltivazione:
0 = NON IMPOSTATO
1 = SPECIALIZZATA
2 = PROMISCUA';

COMMENT ON COLUMN SITI_H501.SITIUNAR.COD_VARIETA IS 'Varietà:
SELECT CODICE, DESCRIZIONE
FROM SITIUNAR_DECO
WHERE NOME_CAMPO = ''COD_VARIETA''
AND TIPO_UNAR = ?';

COMMENT ON COLUMN SITI_H501.SITIUNAR.COD_TIPO_VARI IS 'Tipo varietà';

COMMENT ON COLUMN SITI_H501.SITIUNAR.UTENTE IS 'Utente inserimento';

COMMENT ON COLUMN SITI_H501.SITIUNAR.UTENTE_FINE IS 'Utente cancellazione';

COMMENT ON COLUMN SITI_H501.SITIUNAR.ID_TRASF IS 'Identificativo trasformazione catastale iniziale (NON INFLUENTE)';

COMMENT ON COLUMN SITI_H501.SITIUNAR.ID_TRASF_FINE IS 'Identificativo trasformazione catastale finale (NON INFLUENTE)';

COMMENT ON COLUMN SITI_H501.SITIUNAR.NUM_PIAN_PROD IS 'Numero piante produttivo';

COMMENT ON COLUMN SITI_H501.SITIUNAR.NUM_ALTRE IS 'Numero altre piante';

COMMENT ON COLUMN SITI_H501.SITIUNAR.CAMPAGNA IS 'Campagna';

COMMENT ON COLUMN SITI_H501.SITIUNAR.COD_TIPO_VIGN IS 'Tipo di vigneto:
0 = NORMALE
1 = CONSUMO FAMILIARE
2 = VIVAISMO
3 = FINALITA` SPERIMENTALI';

COMMENT ON COLUMN SITI_H501.SITIUNAR.TIPO_IMPI IS 'Tipo di impianto';

COMMENT ON COLUMN SITI_H501.SITIUNAR.NUM_CAST IS 'Numero castagni';

COMMENT ON COLUMN SITI_H501.SITIUNAR.IDEN_REGI IS 'Identificativo regionr (NON INFLUENTE)';

COMMENT ON COLUMN SITI_H501.SITIUNAR.SUPPLEMENTARI IS 'Unità arborea supplementare:
0 = NO
1 = SI';

COMMENT ON COLUMN SITI_H501.SITIUNAR.MECCANIZZABILE IS 'Unità arborea meccanizzabile:
0 = NO
1 = SI';

COMMENT ON COLUMN SITI_H501.SITIUNAR.GIACITURA IS 'Giacitura:
0 = PIANEGGIANTE
1 = LIEVE PENDENZA
2 = FORTE PENDENZA 15-25%
3 = FORTE PENDENZA > 25%
4 = TERRAZZE';

COMMENT ON COLUMN SITI_H501.SITIUNAR.ROCCIA IS 'Roccia:
0 = ASSENTE
1 = 0 - 25%
2 = > 25%';

COMMENT ON COLUMN SITI_H501.SITIUNAR.SCHELETRO IS 'Scheletro:
0 = ASSENTE
1 = SCARSA
2 = CONSISTENTE
3 = ELEVATA';

COMMENT ON COLUMN SITI_H501.SITIUNAR.STATO_VEGETATIVO IS 'Stato vegetativo:
S = SCADENTE
B = BUONO
O = OTTIMO';

COMMENT ON COLUMN SITI_H501.SITIUNAR.POTATURA IS 'Potatura:
R = REGOLARE
S = SALTUARIA
A = ASSENTE';

COMMENT ON COLUMN SITI_H501.SITIUNAR.GIUDIZIO IS 'Giudizio:
A = ABBANDONATO
S = SCADENTE
B = BUONO
O = OTTIMO';

COMMENT ON COLUMN SITI_H501.SITIUNAR.DIM_CHIOMA_CM IS 'Dimensione chioma (cm)';

COMMENT ON COLUMN SITI_H501.SITIUNAR.ETA_IMPI IS 'Età impianto:
A = FINO A 5 ANNI
B = DA 5 A 10 ANNI
C = DA 10 A 20 ANNI
D = DA 20 A 25 ANNI
E = DA 25 A 100 ANNI
F = OLTRE 100 ANNI';

COMMENT ON COLUMN SITI_H501.SITIUNAR.SORGENTE IS 'Codice della sorgente - FK (sitiload_indirizzi):
SELECT DESCRIZIONE, INDIRIZZO
FROM SITILOAD_INDIRIZZI
WHERE ID_INDIRIZZO = ?';

COMMENT ON COLUMN SITI_H501.SITIUNAR.GRUPPO IS 'Gruppo (codice di relazione con le unar associate)';


