CREATE OR REPLACE TRIGGER SITI_H501.AGGR_GRAF_TIB
BEFORE INSERT
ON SITI_H501.AGGR_GRAF
FOR EACH ROW
BEGIN
  SELECT AGGR_GRAF_SEQ.NEXTVAL INTO :NEW.SE_ROW_ID FROM DUAL;
  IF :NEW.NUMERO IS NULL THEN
    SELECT 'GEN' || TRIM(TO_CHAR(AGGR_TOPO_NUMERO_SEQ.NEXTVAL,'000000')) INTO :NEW.NUMERO FROM DUAL;
  END IF;
END;
/


DROP SEQUENCE SITI_H501.AGGR_LOCALIZZA_SEQ;

CREATE SEQUENCE SITI_H501.AGGR_LOCALIZZA_SEQ
  START WITH 11240
  MAXVALUE 999999999999999999999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.AGGR_LOCALIZZA_TIB 
BEFORE INSERT ON SITI_H501.AGGR_LOCALIZZA 
FOR EACH ROW
BEGIN 
	IF :NEW.PKID_LOC IS NULL THEN 
		SELECT AGGR_LOCALIZZA_SEQ.NEXTVAL INTO :NEW.PKID_LOC FROM DUAL; 
	END IF; 
	IF :NEW.COD_NAZIONALE IS NULL THEN 
	   select cod_nazionale into :new.cod_nazionale 
	     from aggr_topo t, aggr_localizza_types lt 
		where lt.pkid_type = :new.fkid_type 
		  and t.aggr_code = lt.aggr_code 
		  and PKID_TOPO = :new.pkid_topo 
		  AND DATA_INIZIO_VAL <= :NEW.DATA_INIZIO_VAL 
		  AND DATA_FINE_VAL >= :NEW.DATA_FINE_VAL; 
	END IF; 

  if :new.al_1 is null then
    :new.al_1 := :new.nome;
  end if;

--	IF :NEW.ID_TRASF>0 THEN 
--		:NEW.DATA_FINE_VAL := UPDATE_GIS_DATA.SCADI_CIVICO(:NEW.PKID_LOC,:NEW.NOME,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE,:NEW.ID_TRASF); 
--	END IF; 
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.AGGR_LOCALIZZA_TIUA 
AFTER INSERT OR UPDATE ON SITI_H501.AGGR_LOCALIZZA 
FOR EACH ROW
DECLARE
  bb      boolean;
BEGIN

  if :new.fkid_type = -1 then
    bb := :old.shape is null;
    if not bb and :new.shape is not null then
      bb := sdo_geom.relate(:new.shape, 'EQUAL', :old.shape, 0.005) = 'FALSE';
    end if;

    if :new.shape is not null and (inserting or bb) then
      assegna_civico(:new.PKID_LOC, :new.UTENTE, :new.SHAPE);
    end if;  
  end if;

END;
/


DROP SEQUENCE SITI_H501.CATA_TOPO_SEQ;

CREATE SEQUENCE SITI_H501.CATA_TOPO_SEQ
  START WITH 1
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.AGGR_TOPO_ID
BEFORE INSERT OR UPDATE
ON SITI_H501.AGGR_TOPO
FOR EACH ROW
DECLARE
  ID NUMBER(9);
BEGIN

  IF :NEW.NUMERO IS NULL THEN
    RAISE_APPLICATION_ERROR(-20999,'VALORIZZARE IL CODICE AGGREGATO [NUMERO]');
  END IF;

  IF :NEW.ID_CATA_TOPO IS NULL THEN
    BEGIN
      SELECT ID_CATA_TOPO INTO ID FROM CATA_TOPO WHERE AGGR_CODE = :NEW.AGGR_CODE AND NUMERO=:NEW.NUMERO and COD_NAZIONALE=:new.COD_NAZIONALE;
    EXCEPTION
      WHEN OTHERS THEN
        SELECT CATA_TOPO_SEQ.NEXTVAL INTO ID FROM DUAL;
        INSERT INTO CATA_TOPO(ID_CATA_TOPO, AGGR_CODE, NUMERO,COD_NAZIONALE)
        VALUES(ID,:NEW.AGGR_CODE,:NEW.NUMERO,:new.COD_NAZIONALE);
    END;
    :NEW.ID_CATA_TOPO:=ID;
  END IF;

END;
/


