CREATE OR REPLACE TRIGGER SITI_H501.ANAG_SOGGETTI_PATRI_TIB
  before insert ON SITI_H501.ANAG_SOGGETTI  
  for each row
declare
  num number;
begin
  select count(*) into num
    from anag_soggetti_ext
   where cod_soggetto = :new.cod_soggetto;
  
  if num = 0 then
    insert into anag_soggetti_ext (cod_soggetto) values (:new.cod_soggetto);
  end if;
   
end anag_soggetti_patri_TIB;
/


