CREATE SEQUENCE SITI_H501.ANAG_SOGGETTO_SEQ
  START WITH 3597
  MAXVALUE 999999999999999999999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.ANAG_SOGGETTI_TIB
  before insert or update ON SITI_H501.ANAG_SOGGETTI  
  for each row
declare
  dataFine date := to_date('31129999', 'ddmmyyyy');
  vcuaa varchar2(16) := null;
  deno varchar2(300) := null;
begin
  if :new.PKID is null then
    select anag_soggetto_seq.nextval into :new.pkid from dual;
  end if;

  if :new.denominazione is null then 
   :new.denominazione := trim(:new.cognome || ' ' || :new.nome);
  end if;
  
  if :new.INDIRIZZO_EST is null then
    if :new.FKCIVICO_RESI is not null then
      begin
        select trim(t.PREFISSO || ' ' || t.NOME || ' ' || l.nome)
          into :new.INDIRIZZO_EST  
          from aggr_localizza l, AGGR_TOPO t 
         where l.PKID_LOC = :new.FKCIVICO_RESI 
           and l.fkid_type = -1
           and t.AGGR_CODE = 1
           and t.PKID_TOPO = l.PKID_TOPO
           and sysdate between t.DATA_INIZIO_VAL and t.DATA_FINE_VAL;
      exception when no_data_found then
        null;
      end; 
    end if;
  end if;
  
end anag_soggetti_TIB;
/


