CREATE SEQUENCE SITI_H501.CEN_HEADER_SEQ
  START WITH 1
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.CEN_HEADER_TIB
BEFORE INSERT
ON SITI_H501.CEN_HEADER
FOR EACH ROW
BEGIN
   :NEW.NOMEFILE:=UPPER(:NEW.NOMEFILE);
   IF :NEW.ID_CEN IS NULL THEN
    SELECT CEN_HEADER_SEQ.NEXTVAL INTO :NEW.ID_CEN FROM DUAL;
   END IF;
   IF :NEW.FOGLIO IS NULL THEN
      :NEW.FOGLIO:=UNFORMATFOGLIO(SUBSTR(:NEW.NOMEFILE,5,3));
      :NEW.ALLEGATO:=SUBSTR(:NEW.NOMEFILE,8,1);
      :NEW.SVILUPPO:=SUBSTR(:NEW.NOMEFILE,9,1);
   END IF;
   IF :NEW.COD_NAZIONALE IS NULL THEN
      :NEW.COD_NAZIONALE :=SUBSTR(:NEW.NOMEFILE,1,4);
   END IF;
   IF :NEW.ISTATP IS NULL THEN
       SELECT SITICOMU.ISTATP INTO :NEW.ISTATP FROM SITICOMU WHERE SITICOMU.COD_NAZIONALE=:NEW.COD_NAZIONALE;
   END IF;
   :NEW.DATA_FINE_VAL:=CEN_UTILS.SCADI_HEADER(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20999,'COMUNE NON TROVATO');
END;
/


