DROP SEQUENCE SITI_H501.CXF_HEADER_SEQ;

CREATE SEQUENCE SITI_H501.CXF_HEADER_SEQ
  START WITH 24
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.CXF_HEADER_TIB
/*
  a.caleffi 2009-08-27 aggiunta scadenza dati in tabella VEST_LINEA
  a.caleffi 2009-08-27 aggiunta scadenza strati di VESTizione in base a foglio ed allegato
*/
BEFORE INSERT
ON SITI_H501.CXF_HEADER
FOR EACH ROW
BEGIN
   :NEW.NOMEFILE:=UPPER(:NEW.NOMEFILE);
   IF :NEW.ID_CXF IS NULL THEN
    SELECT CXF_HEADER_SEQ.NEXTVAL INTO :NEW.ID_CXF FROM DUAL;
   END IF;
   IF :NEW.CODI_FISC_LUNA IS NULL THEN
      :NEW.CODI_FISC_LUNA:=SUBSTR(:NEW.NOMEFILE,1,4);
      :NEW.ID_SEZC:=SUBSTR(:NEW.NOMEFILE,5,1);
      IF :NEW.ID_SEZC = '_' THEN :NEW.ID_SEZC:=NULL; END IF;
   END IF;
   IF :NEW.FOGLIO IS NULL THEN
      :NEW.FOGLIO:=TO_NUMBER(SUBSTR(:NEW.NOMEFILE,6,4));
      :NEW.ALLEGATO:=SUBSTR(:NEW.NOMEFILE,10,1);
      :NEW.SVILUPPO:=SUBSTR(:NEW.NOMEFILE,11,1);
   END IF;
   IF :NEW.COD_NAZIONALE IS NULL THEN
      IF :NEW.ID_SEZC IS NULL THEN
        SELECT SITICOMU.COD_NAZIONALE INTO :NEW.COD_NAZIONALE FROM SITICOMU WHERE SITICOMU.CODI_FISC_LUNA=:NEW.CODI_FISC_LUNA AND SITICOMU.ID_SEZC IS NULL;
      ELSE
        SELECT SITICOMU.COD_NAZIONALE INTO :NEW.COD_NAZIONALE FROM SITICOMU WHERE SITICOMU.CODI_FISC_LUNA=:NEW.CODI_FISC_LUNA AND SITICOMU.ID_SEZC=:NEW.ID_SEZC;
      END IF;
   END IF;
   IF :NEW.ISTATP IS NULL THEN
       SELECT SITICOMU.ISTATP INTO :NEW.ISTATP FROM SITICOMU WHERE SITICOMU.COD_NAZIONALE=:NEW.COD_NAZIONALE;
   END IF;
   :NEW.DATA_FINE_VAL:=CXF_UTILS.SCADI_HEADER(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE,:NEW.ALLEGATO,:NEW.SVILUPPO);

  IF :NEW.CARICO_VESTIZIONE = 'L' THEN

    -- a.caleffi 2009-08-27 gli strati di VESTizione vanon fatti scadere non tutti in base
    -- al solo foglio, ma in base al foglio ed allegato; altrimenti se per lo stesso foglio X
    -- c'e' l'allegato A,B,C ad ogni caricamento verrebbero fatti scadere sempre tutti gli
    -- strati e rimarrebbe valido solo l'ultimo, quello di C
    UPDATE VEST_SIMBOLO
    SET DATA_FINE_VAL = :NEW.DATA_INIZIO_VAL
    WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE
    AND TAVOLA=:NEW.FOGLIO
    AND DATA_FINE_VAL = TO_DATE('99991231','YYYYMMDD')
    AND id_cxf IN  -- solo per gli id_cxf dell'allegato corretto e non tutti
    (
      SELECT id_cxf
      FROM cxf_header
      WHERE cod_nazionale=:NEW.COD_NAZIONALE
        AND foglio=:NEW.FOGLIO
        AND allegato=:NEW.allegato
        AND sviluppo=:NEW.sviluppo
    );


    UPDATE VEST_FIDUCIALE
    SET DATA_FINE_VAL = :NEW.DATA_INIZIO_VAL
    WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE
    AND TAVOLA=:NEW.FOGLIO
    AND DATA_FINE_VAL = TO_DATE('99991231','YYYYMMDD')
    AND id_cxf IN  -- solo per gli id_cxf dell'allegato corretto e non tutti
    (
      SELECT id_cxf
      FROM cxf_header
      WHERE cod_nazionale=:NEW.COD_NAZIONALE
        AND foglio=:NEW.FOGLIO
        AND allegato=:NEW.allegato
        AND sviluppo=:NEW.sviluppo
    );


    UPDATE VEST_TESTO
    SET DATA_FINE_VAL = :NEW.DATA_INIZIO_VAL
    WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE
    AND TAVOLA=:NEW.FOGLIO
    AND DATA_FINE_VAL = TO_DATE('99991231','YYYYMMDD')
    AND id_cxf IN  -- solo per gli id_cxf dell'allegato corretto e non tutti
    (
      SELECT id_cxf
      FROM cxf_header
      WHERE cod_nazionale=:NEW.COD_NAZIONALE
        AND foglio=:NEW.FOGLIO
        AND allegato=:NEW.allegato
        AND sviluppo=:NEW.sviluppo
    );


    -- a.caleffi 2009-08-27 aggiunta scadenza dati in tabella VEST_LINEA
    UPDATE VEST_LINEA
    SET DATA_FINE_VAL = :NEW.DATA_INIZIO_VAL
    WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE
    AND TAVOLA=:NEW.FOGLIO
    AND DATA_FINE_VAL = TO_DATE('99991231','YYYYMMDD')
    AND id_cxf IN  -- solo per gli id_cxf dell'allegato corretto e non tutti
    (
      SELECT id_cxf
      FROM cxf_header
      WHERE cod_nazionale=:NEW.COD_NAZIONALE
        AND foglio=:NEW.FOGLIO
        AND allegato=:NEW.allegato
        AND sviluppo=:NEW.sviluppo
    );


    :NEW.CARICO_VESTIZIONE := 'Y';
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20999,'COMUNE NON TROVATO');
END;
/


