CREATE OR REPLACE TRIGGER SITI_H501.CXF_TESTO_TIB
BEFORE INSERT OR UPDATE
ON SITI_H501.CXF_TESTO
FOR EACH ROW
DECLARE
BEGIN
  IF :NEW.FLAG IS NULL THEN
   :NEW.FLAG:= 0;
  END IF;

  IF :NEW.ID_TESTO IS NULL THEN
    SELECT CXF_TESTO_SEQ.NEXTVAL INTO :NEW.ID_TESTO FROM DUAL;
  END IF;

  IF :NEW.DIMENSIONE = 0 THEN
    :NEW.FLAG := BITOR(:NEW.FLAG,1);
  END IF;

  IF SUBSTR(:NEW.TESTO,1,1)='(' THEN
     IF SubStr(:NEW.TESTO,Length(:NEW.TESTO),1) = ')' THEN
      :NEW.FLAG := BITOR(:NEW.FLAG,2);
     END IF;
  END IF;
END;
/


