CREATE OR REPLACE TRIGGER SITI_H501.IMPO_SITIFILE_PARTICELLE_TR1
before insert ON SITI_H501.IMPO_SITIFILE_PARTICELLE
for each row
declare
  cn  varchar2(4);
  id_atto number;
begin
  select cod_nazionale into cn
    from siticomu
   where istatp=:new.istatp
     and istatc = :new.istatc
     and sezione_censuaria = :new.id_sezc;

  begin
    select pkid_atto into id_atto
      from sitidata_atti_titoli
     where pkid_atto_utente = :new.id_atto;

    insert into sitifile_particelle (COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, FKID_ATTO, DATA_INIZIO, UTENTE_INIZIO)
      values (cn, :new.foglio, :new.particella, :new.sub, id_atto, :new.data_inizio, 'LOADER');
  exception when no_data_found then
    raise_application_error(-20001, 'Atto non trovato!');
  end;
end;
/


