DROP SEQUENCE SITI_H501.VEST_FIDUCIALE_SEQ;

CREATE SEQUENCE SITI_H501.VEST_FIDUCIALE_SEQ
  START WITH 1
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.IMPO_VEST_FIDUCIALE_TIB
/*
a.caleffi 2009-04-29
Inserendo un record nella tabella impo_vest_fiduciale
viene inserito un record nella tabella vest_fiduciale, convertendo il codice id_cxf
in quello corrispondente nella tabelle cxf_header
*/
BEFORE INSERT OR UPDATE
ON SITI_H501.IMPO_VEST_FIDUCIALE
FOR EACH ROW
DECLARE
  fld_id_fiduciale NUMBER(9);
  fld_id_cxf NUMBER(9);

  CURSOR curCxfHeader(pi_cxf_nomefile varchar2, pi_cxf_data_inizio_val date, pi_cxf_data_fine_val date)
  IS
  SELECT id_cxf
  FROM cxf_header
  WHERE nomefile = pi_cxf_nomefile
  AND data_inizio_val = pi_cxf_data_inizio_val
  AND data_fine_val = pi_cxf_data_fine_val;

BEGIN
  -- genero un nuovo codice per l'id_fiduciale
  SELECT VEST_FIDUCIALE_SEQ.NEXTVAL INTO fld_id_fiduciale FROM DUAL;

  -- cerco il codice del CXF in base al nome file del CXF stesso e alla sua
  -- data di validita'

  OPEN curCxfHeader(:NEW.cxf_nomefile, :NEW.cxf_data_inizio_val, :NEW.cxf_data_fine_val);

  FETCH curCxfHeader INTO fld_id_cxf;
  IF (curCxfHeader%NOTFOUND) THEN
    fld_id_cxf := -1;
  END IF;

  CLOSE curCxfHeader;

  -- se non lo trovo allora genero un'eccezione
  IF (-1 = fld_id_cxf) THEN
    raise_application_error(-20001, 'ID CxfHeader non trovato; nomefile=[' || :NEW.cxf_nomefile || '] data_inizio_val=[' || :NEW.data_inizio_val || '] data_fine_val=[' || :NEW.data_fine_val || ']');
  END IF;

  -- inserisco il record nella tabella
  INSERT INTO vest_fiduciale(cod_nazionale, tavola, id_fiduciale
    , codice, fiduciale, data_inizio_val
    , data_fine_val, utente, utente_fine
    , id_cxf, shape)
  VALUES(:NEW.cod_nazionale, :NEW.tavola, fld_id_fiduciale
    , :NEW.codice, :NEW.fiduciale, :NEW.data_inizio_val
    , :NEW.data_fine_val, :NEW.utente, :NEW.utente_fine
    , fld_id_cxf, :NEW.shape);

END;
/


