CREATE OR REPLACE TRIGGER SITI_H501.IMPO_VEST_LINEA_TIB
/*
a.caleffi 2009-04-29
Inserendo un record nella tabella impo_vest_linea
viene inserito un record nella tabella vest_linea, convertendo il codice id_cxf
in quello corrispondente nella tabelle cxf_header
*/
BEFORE INSERT OR UPDATE
ON SITI_H501.IMPO_VEST_LINEA
FOR EACH ROW
DECLARE
  fld_id_linea NUMBER(9);
  fld_id_cxf NUMBER(9);

  CURSOR curCxfHeader(pi_cxf_nomefile varchar2, pi_cxf_data_inizio_val date, pi_cxf_data_fine_val date)
  IS
  SELECT id_cxf
  FROM cxf_header
  WHERE nomefile = pi_cxf_nomefile
  AND data_inizio_val = pi_cxf_data_inizio_val
  AND data_fine_val = pi_cxf_data_fine_val;

BEGIN
  -- genero un nuovo codice per l'id_linea
  SELECT VEST_LINEA_SEQ.NEXTVAL INTO fld_id_linea FROM DUAL;

  -- cerco il codice del CXF in base al nome file del CXF stesso e alla sua
  -- data di validita'

  OPEN curCxfHeader(:NEW.cxf_nomefile, :NEW.cxf_data_inizio_val, :NEW.cxf_data_fine_val);

  FETCH curCxfHeader INTO fld_id_cxf;
  IF (curCxfHeader%NOTFOUND) THEN
    fld_id_cxf := -1;
  END IF;

  CLOSE curCxfHeader;

  -- se non lo trovo allora genero un'eccezione
  IF (-1 = fld_id_cxf) THEN
    raise_application_error(-20001, 'ID CxfHeader non trovato; nomefile=[' || :NEW.cxf_nomefile || '] data_inizio_val=[' || :NEW.data_inizio_val || '] data_fine_val=[' || :NEW.data_fine_val || ']');
  END IF;

  -- inserisco il record nella tabella
  INSERT INTO vest_linea(cod_nazionale, tavola, id_linea
    , codice, data_inizio_val, data_fine_val
    , utente, utente_fine, id_cxf
    , shape)
  VALUES(:NEW.cod_nazionale, :NEW.tavola, fld_id_linea
    , :NEW.codice, :NEW.data_inizio_val, :NEW.data_fine_val
    , :NEW.utente, :NEW.utente_fine, fld_id_cxf
    , :NEW.shape);
END;
/


