CREATE OR REPLACE TRIGGER SITI_H501.LOADANAG_TIB
BEFORE INSERT
ON SITI_H501.LOADANAGRAFICA
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
DECLARE
   scartato          NUMBER (1);
   -- id_soggetto
   pkcuaa            cons_azie_tab.pk_cuaa%TYPE;
   -- codice Belfiore comune di nascita
   comunascita       siticomu_istat.codi_fisc_luna%TYPE;
   -- codice Belfiore comune di residenza
   comuresi          siticomu_istat.codi_fisc_luna%TYPE;
   -- id_soggetto rappresentante legale
   idrapplegale      anag_soggetti.cod_soggetto%TYPE;
   -- id_civico
   idcivico          anag_soggetti.fkcivico_resi%TYPE;
   numcivico         siticivi.civico%TYPE;
   idstrada          NUMBER;
   -- denominazione
   dedenominazione   anag_soggetti.denominazione%TYPE;
   -- cognome
   decognome         anag_soggetti.cognome%TYPE;
   -- validita
   valido_inizio     anag_soggetti.valido_inizio%TYPE;
   valido_fine       anag_soggetti.valido_fine%TYPE;
   -- data fine
   dtfin             DATE;
BEGIN
   :NEW.cod_errore := 0;
   scartato := 0;
   pkcuaa := 0;
   idcivico := NULL;

   /*
    * controlla la presenza del Codice Belfiore
    * se non esiste utilizza l'istatc e istat p per ricavarlo
    */
   IF :NEW.comu_nasc IS NULL
   THEN
      BEGIN
         SELECT codi_fisc_luna
           INTO comunascita
           FROM siticomu_istat
          WHERE istatp = :NEW.comu_nasc_istatp
                AND istatc = :NEW.comu_nasc_istatc;
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            comunascita := NULL;
      END;
   ELSE
      comunascita := :NEW.comu_nasc;
   END IF;

   comuresi := :NEW.comu_resi;

   /*
   * calcolo del rappresentante legale se esiste
   */
   BEGIN
      SELECT pk_cuaa
        INTO idrapplegale
        FROM cons_azie_tab c
       WHERE cuaa = :NEW.cuaa_rapp_legale
         AND SYSDATE BETWEEN c.data_inizio AND c.data_fine;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         idrapplegale := NULL;
   END;

   /*
   * storicizza l'anagrafica attuale
   */
   BEGIN
      SELECT pk_cuaa
        INTO pkcuaa
        FROM cons_azie_tab
       WHERE cuaa = :NEW.cuaa;

      UPDATE anag_soggetti
         SET data_fine_val = :NEW.data_inizio_val - (1 / 24 / 60 / 60)
       WHERE cod_soggetto = pkcuaa
         AND data_fine_val = TO_DATE ('99991231', 'yyyymmdd');
   -- se non esiste aggiorna la consistenza aziende
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         SELECT cons_azie_seq.NEXTVAL
           INTO pkcuaa
           FROM DUAL;

         INSERT INTO cons_azie_tab
                     (pk_cuaa, cuaa, data_inizio,
                      data_fine, data_registrazione, utente
                     )
              VALUES (pkcuaa, :NEW.cuaa, :NEW.data_inizio_val,
                      :NEW.data_fine_val, SYSDATE, :NEW.utente
                     );
   END;

   -- data fine di default
   dtfin := TO_DATE ('99991231', 'yyyymmdd');

   -- calcolo del civico
   IF (:NEW.indirizzo IS NOT NULL)
   THEN
      SELECT aggr_topo_numero_seq.NEXTVAL
        INTO idstrada
        FROM DUAL;

      -- inserisce la strada se esiste un indirizzo
      INSERT INTO aggr_topo
                  (aggr_code, pkid_topo, prefisso, nome, cod_nazionale,
                   data_inizio_val, data_fine_val, utente,
                   numero, tipo
                  )
           VALUES ('1', idstrada, NULL, :NEW.indirizzo, :NEW.comu_resi,
                   :NEW.data_inizio_val, dtfin, :NEW.utente,
                   aggr_topo_numero_seq.NEXTVAL, 'SC'
                  );

      -- inserisce il civico
      IF :NEW.num_civico IS NOT NULL
      THEN
         numcivico := :NEW.num_civico;
      ELSE
         numcivico := ' ';
      END IF;

      SELECT siticivi_seq.NEXTVAL
        INTO idcivico
        FROM DUAL;

      INSERT INTO siticivi
                  (pkid_civi, pkid_stra, cod_nazionale, civico,
                   utente, data_inizio_val, data_fine_val
                  )
           VALUES (idcivico, idstrada, :NEW.comu_resi, numcivico,
                   :NEW.utente, :NEW.data_inizio_val, dtfin
                  );
   END IF;

   /*
   * Aggiorna con la nuova anagrafica
   */
   -- controllo validita iniziale
   IF :NEW.valido_inizio IS NULL
   THEN
      valido_inizio := :NEW.valido_inizio;
   ELSE
      valido_inizio := 'N';
   END IF;

   -- controllo validità finale
   IF :NEW.valido_fine IS NULL
   THEN
      valido_fine := :NEW.valido_fine;
   ELSE
      valido_fine := 'N';
   END IF;

   IF TRIM (:NEW.nome) IS NOT NULL AND TRIM (:NEW.nome) <> ''
   THEN
      dedenominazione := nvl((TRIM (:NEW.denominazione) || ' ' || TRIM (:NEW.nome)),' ');
      decognome := TRIM (:NEW.denominazione);
   ELSE
      dedenominazione := nvl((TRIM (:NEW.denominazione)),' ');
      decognome := NULL;
   END IF;

   INSERT INTO anag_soggetti
               (pkid, cod_soggetto, denominazione,
                nome, sesso, d_nascita, d_morte,
                fkcod_comu_nasc, fkcivico_resi, flag_pers_fisica,
                cod_fiscale, part_iva, data_inizio_val, data_fine_val,
                data_lav, utente_inizio, utente_fine, fkrapp_legale,
                valido_inizio, natura_giuridica, valido_fine,
                atto_inizio, atto_fine, fonte_inizio,
                fonte_fine, fkcod_comu_resi, localita, cap,
                fkcod_comu_recapito, fkcivico_recapito, d_costituzione,
                telefono, fax, mail, indirizzo_est, indirizzo_est_recap,
                cap_recap, cognome
               )
        VALUES (anag_soggetto_seq.NEXTVAL, pkcuaa, dedenominazione,
                :NEW.nome, :NEW.sesso, :NEW.d_nascita, :NEW.d_morte,
                comunascita, idcivico, :NEW.flag_pers_fisica,
                :NEW.cod_fiscale, :NEW.part_iva, :NEW.data_inizio_val, dtfin,
                SYSDATE, :NEW.utente, NULL, idrapplegale,
                valido_inizio, :NEW.natura_giuridica, valido_fine,
                :NEW.atto_ini, :NEW.atto_fine, :NEW.fonte_inizio,
                :NEW.fonte_fine, comuresi, :NEW.localita, :NEW.cap,
                NULL, NULL, NULL,
                NULL, NULL, NULL, :NEW.indirizzo, NULL,
                NULL, decognome
               );
EXCEPTION
   WHEN OTHERS
   THEN
      :NEW.cod_errore := SQLCODE;
END loadanag_tib;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOAD_CAT_PAR_TR1
before insert ON SITI_H501.LOAD_CAT_PAR
for each row
declare
begin

  select /*+ rule*/
         nvl(max(seq) + 1, 0)
    into :new.seq
    from load_cat_par
   where codi_fisc_luna = :new.codi_fisc_luna
     and sezione = :new.sezione
     and id_imm = :new.id_imm
     and progressivo = :new.progressivo;

end;
/


CREATE OR REPLACE TRIGGER SITI_H501.load_cat_run_tr1
  BEFORE INSERT
  ON SITI_H501.LOAD_CAT_RUN
  FOR EACH ROW
DECLARE
  n       NUMBER;
  creas   CHAR (1) := 'N';
  creac   CHAR (1) := 'N';
BEGIN
  IF :NEW.flag = 'S' THEN
    n := load_catasto.load_soggetti();
  ELSIF :NEW.flag = 'P' THEN
    n := load_catasto.load_part();
    n := load_catasto.load_part_por();
  ELSIF :NEW.flag = 'PT' THEN
    n := load_catasto.load_part_tit();
  ELSIF :NEW.flag = 'U' THEN
    n := load_catasto.load_uiu();
  ELSIF :NEW.flag = 'UA' THEN
    n := load_catasto.load_uiu_graf();
    n := load_catasto.load_uiu_util();
  ELSIF :NEW.flag = 'UT' THEN
    n := load_catasto.load_uiu_tit();
--    n := load_catasto.processagraffati ();
  ELSIF :NEW.flag = 'UP' THEN
    --load_catasto.spalma_titolarita_part();
    NULL;
  ELSIF :NEW.flag = 'UI' THEN
    IF :NEW.creastr = 'Y' THEN
      creas := 'Y';
    END IF;

    IF :NEW.creaciv = 'Y' THEN
      creac := 'Y';
    END IF;

    n := load_catasto.load_uiu_ind (creas, creac);
  ELSIF :NEW.flag = 'SUPERFICI' THEN
  	n := load_catasto_sup.load_sup1();
    n := load_catasto_sup.load_sup4();
  elsif :new.flag = 'PRE_PULIZIA' then
    delete from load_cat_sog where toDelete > 0 and stato_siti != 'T';
    delete from load_cat_tit where toDelete > 0;
    delete from load_cat_uiu_id where toDelete > 0;
    delete from load_cat_uiu_ind where toDelete > 0;
    delete from load_cat_uiu_util where toDelete > 0;
  ELSIF :new.flag = 'PULISCI' then
    delete from LOAD_CAT_UIU_UTIL where STATO_SITI is null;
    --delete from load_cat_uiu_ris;
    --delete from load_cat_par_ded;
    --delete from load_cat_par_ris;
    delete from load_cat_par_por where stato_siti is null;
    
    update load_cat_sog s
       set stato_siti='T', todelete=0
     where stato_siti is null
        and not exists (select 1 
                          from load_cat_sog 
                         where codi_fisc_luna=s.codi_fisc_luna 
                           and sezione=s.sezione 
                           and id_sog=s.id_sog
                           and tp_sog=s.tp_sog
                           and stato_siti='T'); 
                      
    delete from load_cat_sog where stato_siti is null;
    
    --update load_cat_sog set stato_siti='T', todelete=0 where stato_siti is null;
    --delete from load_cat_tit where stato_siti is null;
  END IF;

  INSERT INTO load_cat_run_res (load_id, flag) VALUES (:NEW.load_id, :NEW.flag);
EXCEPTION
  WHEN OTHERS THEN
    INSERT INTO load_cat_run_res (load_id, flag) VALUES (:NEW.load_id, :NEW.flag);
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOAD_CAT_SOG_TR1
before insert ON SITI_H501.LOAD_CAT_SOG
for each row
begin
  select nvl(max(toDelete) + 1, 0)
    into :new.toDelete
    from load_cat_sog
   where codi_fisc_luna = :new.codi_fisc_luna
     and sezione = :new.sezione
     and id_sog = :new.id_sog
     and tp_sog = :new.tp_sog
     and stato_siti='N';

  if trim(replace(:new.COD_FISC, '0', ' ')) is null or trim(replace(:new.COD_FISC, '1', ' ')) is null then
    :new.COD_FISC := null;
  end if;

end;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOAD_CAT_TIT_TR1
before insert ON SITI_H501.LOAD_CAT_TIT
for each row
declare
	newSeq	load_cat_tit.seq%type;
begin

  begin
    select nvl(max(seq), 0) + 1
      into newSeq
      from load_cat_tit
     where codi_fisc_luna = :new.codi_fisc_luna
       and sezione = :new.sezione
  	   and tp_imm = :new.tp_imm
	   and id_tit = :new.id_tit;
  exception when no_data_found then
  	newSeq := 0;
  end;

  :new.seq := newSeq;

  if trim(:new.regime) is null then
    :new.regime := 'P';
  end if;

  select nvl(max(toDelete) + 1, 0)
    into :new.toDelete
    from load_cat_tit
   where codi_fisc_luna = :new.codi_fisc_luna
     and sezione = :new.sezione
     and tp_imm = :new.tp_imm
     and id_tit = :new.id_tit
     and id_mut_ini = :new.id_mut_ini
     and (id_mut_fin = :new.id_mut_fin or (id_mut_fin is null and :new.id_mut_fin is null));

end;
/


