CREATE OR REPLACE TRIGGER SITI_H501.LOAD_CAT_UIU_UTIL_TR1
before insert ON SITI_H501.LOAD_CAT_UIU_UTIL
for each row
declare
  flag  number;
begin
  if :new.foglio is null then
    :new.foglio := 0;
  end if;
  if :new.mappale is null then
    :new.mappale := '00000';
  end if;
  if :new.sub is null then
    :new.sub := ' ';
  end if;

  select /*+rule*/ nvl(max(toDelete) + 1, 0)
    into :new.toDelete
    from load_cat_uiu_util
   where codi_fisc_luna = :new.codi_fisc_luna
     and sezione = :new.sezione
     and id_imm = :new.id_imm
     and progressivo = :new.progressivo
     and sez = :new.sez
     and foglio = :new.foglio
     and mappale = :new.mappale
     and sub = :new.sub;

  if :new.seq is null then
    select /*+rule*/ nvl(max(seq) + 1, 0)
      into :new.seq
      from load_cat_uiu_util
     where codi_fisc_luna = :new.codi_fisc_luna
       and sezione = :new.sezione
       and id_imm = :new.id_imm
       and progressivo = :new.progressivo;
  end if;
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOADCONS_PART_TIA AFTER INSERT ON SITI_H501.LOADCONS_PART FOR EACH ROW
DECLARE
  tp_tit      cons_cons_tab.tipo_titolo%type;
BEGIN

  if :new.atto_ini is not null and :new.atto_fin is null then
    select tipo_titolo into tp_tit
      from loadcons
     where ID_CARICAMENTO = :new.id_caricamento
       and ID_PARTICELLA = :new.id_particella
       and rownum = 1;

    if (tp_tit = 1 or tp_tit = 3) then
      -- Se proprietà o usufrutto
      patri_pck.nuovoTitolo(:new.cod_nazionale, :new.foglio, :new.particella, :new.sub, null, :new.data_inizio, :new.data_fine, :new.atto_ini);
    end if;
  end if;
END;
/


DROP SEQUENCE SITI_H501.CONS_TIT_SEQ;

CREATE SEQUENCE SITI_H501.CONS_TIT_SEQ
  START WITH 89442
  MAXVALUE 999999999999999999999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.LOADCONS_PART_TIB BEFORE INSERT ON SITI_H501.LOADCONS_PART FOR EACH ROW
/*
  a.caleffi 2008-12-10 aggiunta gestione colonna loadcons.atto_ini per avere il codice
    dell'atto sul singolo record della consistenza terreni
*/
DECLARE
   CURSOR c1
   IS
      SELECT MIN (data_inizio), MAX (data_fine)
        FROM cons_cons_tab
       WHERE cod_nazionale = :NEW.cod_nazionale
         AND foglio = :NEW.foglio
         AND particella = :NEW.particella
         AND sub = :NEW.sub
         AND data_inizio <= :NEW.data_inizio
         AND data_fine >= :NEW.data_fine;

   CURSOR c2
   IS
      SELECT MIN (data_inizio), MAX (data_fine)
        FROM cons_ufre_tab
       WHERE cod_nazionale = :NEW.cod_nazionale
         AND foglio = :NEW.foglio
         AND particella = :NEW.particella
         AND sub = :NEW.sub
         AND data_inizio <= :NEW.data_inizio
         AND data_fine >= :NEW.data_fine;

   CURSOR c3
   IS
      SELECT MIN (data_inizio)
        FROM cons_cons_tab
       WHERE cod_nazionale = :NEW.cod_nazionale
         AND foglio = :NEW.foglio
         AND particella = :NEW.particella
         AND sub = :NEW.sub
         AND data_inizio >= :NEW.data_inizio;

   CURSOR c4
   IS
      SELECT MIN (data_inizio)
        FROM cons_ufre_tab
       WHERE cod_nazionale = :NEW.cod_nazionale
         AND foglio = :NEW.foglio
         AND particella = :NEW.particella
         AND sub = :NEW.sub
         AND data_inizio >= :NEW.data_inizio;

   -- a.caleffi 2008-12-10 aggiunta colonna atto_ini
   CURSOR ccond
   IS
      SELECT cuaa, quota_conduzione, quota_limite, tipo_titolo,
             DECODE (pkcuaa,
                     NULL, get_pk_cuaa (cuaa, :NEW.data_inizio),
                     pkcuaa
                    )
             , atto_ini
        FROM loadcons
       WHERE id_caricamento = :NEW.id_caricamento
         AND id_particella = :NEW.id_particella;

   condpkcuaa             NUMBER (9);
   condcuaa               VARCHAR2 (16);
   condquota_conduzione   NUMBER (11, 2);
   condquota_limite       NUMBER (11, 2);
   condtipo_titolo        NUMBER (11, 2);
   cond_attoini           NUMBER (9);
   dinic                  DATE;
   diniu                  DATE;
   dfinc                  DATE;
   dfinu                  DATE;
   dinicsucc              DATE;
   diniusucc              DATE;
   perc_prop              NUMBER (9);
   perc_cond              NUMBER (9);
   scartato               NUMBER (1);
   quotarifc              cons_cons_tab.perc_poss%TYPE   := 0;
   quotarifu              cons_ufre_tab.perc_poss%TYPE   := 0;
   ctrlnosuperi           BOOLEAN;
   ctrlnoincompleti       BOOLEAN;
   ctrlscadiprec          BOOLEAN;
   ctrlstrict             BOOLEAN;
   ctrl_raise             boolean;
   bdummy                 BOOLEAN;
   iDummy                 pls_integer;
   v_flag_cata            NUMBER (1)                     := 0;
   v_sub                  VARCHAR2 (3);
BEGIN
   :NEW.cod_errore := 0;
   scartato := 0;
   ctrlnosuperi := (BITAND (:NEW.controlli, 1) = 1);
   ctrlnoincompleti := (BITAND (:NEW.controlli, 2) = 2);
   ctrlscadiprec := (BITAND (:NEW.controlli, 8) = 8);
   ctrlstrict := (BITAND (:NEW.controlli, 16) = 16);
   ctrlstrict := (BITAND (:NEW.controlli, 16) = 16);
   ctrl_raise := (BITAND (:NEW.controlli, 32) = 32);

   /* corrado: comune AU*/
   SELECT flag_cata
     INTO v_flag_cata
     FROM siticomu
    WHERE cod_nazionale = :NEW.cod_nazionale;

   IF v_flag_cata = 2
   THEN
      :NEW.foglio := 9999;
   END IF;

   BEGIN
      v_sub := TO_CHAR (TO_NUMBER (NVL (TRIM (:NEW.sub), '0')));

      IF v_sub = '0'
      THEN
         :NEW.sub := ' ';
      ELSE
         :NEW.sub := v_sub;
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         NULL;
   END;

   SELECT NVL (SUM (get_percentuale (quota_conduzione, quota_limite)), 0)
     INTO perc_prop
     FROM loadcons
    WHERE id_caricamento = :NEW.id_caricamento
      AND id_particella = :NEW.id_particella
      AND tipo_titolo IN ('1', '3');

   SELECT NVL (SUM (get_percentuale (quota_conduzione, quota_limite)), 0)
     INTO perc_cond
     FROM loadcons
    WHERE id_caricamento = :NEW.id_caricamento
      AND id_particella = :NEW.id_particella
      AND tipo_titolo != '1'
      AND tipo_titolo != '3';

   IF perc_prop != 0 AND perc_cond != 0 AND ctrlstrict
   THEN
      :NEW.cod_errore := -20006;
      scartato := 1;
   END IF;

   IF scartato = 0 AND ctrlnosuperi
   THEN
      IF perc_prop > 101 OR perc_cond > 101
      THEN
         :NEW.cod_errore := -20003;
         scartato := 1;
      END IF;
   END IF;

   IF scartato = 0 AND ctrlnoincompleti
   THEN
      IF    (perc_prop < 99 AND perc_prop > 0)
         OR (perc_cond < 99 AND perc_cond > 0)
      THEN
         :NEW.cod_errore := -20004;
         scartato := 1;
      END IF;
   END IF;

   IF (:NEW.pk_cuaa_rif IS NOT NULL)
   THEN
      IF :NEW.pk_cuaa_rif != 999999999
      THEN
         BEGIN
            SELECT perc_poss
              INTO quotarifc
              FROM cons_cons_tab
             WHERE cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_fine
               AND pk_cuaa = :NEW.pk_cuaa_rif
               AND ROWNUM = 1;
         EXCEPTION
            WHEN OTHERS
            THEN
               quotarifc := 0;
         END;

         BEGIN
            SELECT perc_poss
              INTO quotarifu
              FROM cons_ufre_tab
             WHERE cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_fine
               AND pk_cuaa = :NEW.pk_cuaa_rif
               AND ROWNUM = 1;
         EXCEPTION
            WHEN OTHERS
            THEN
               quotarifu := 0;
         END;
      ELSE
         BEGIN
            SELECT 100 - nvl(SUM(perc_poss), 0)
              INTO quotarifc
              FROM cons_cons_tab
             WHERE cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_fine
               AND pk_cuaa != 999999999;
         EXCEPTION
            WHEN OTHERS
            THEN
               quotarifc := 0;
         END;

         BEGIN
            SELECT 100 - nvl(SUM(perc_poss), 0)
              INTO quotarifu
              FROM cons_ufre_tab
             WHERE cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_fine
               AND pk_cuaa != 999999999;
         EXCEPTION
            WHEN OTHERS
            THEN
               quotarifu := 0;
         END;
      END IF;

      IF quotarifc = 0 AND quotarifu = 0
      THEN
         :NEW.cod_errore := -20005;
         scartato := 1;
      END IF;
   END IF;

   -- Stessa data inizio, data fine <
   IF scartato = 0
   THEN
      OPEN c1;

      FETCH c1
       INTO dinic, dfinc;

      IF c1%NOTFOUND
      THEN
         dinic := NULL;
      END IF;

      CLOSE c1;

      OPEN c2;

      FETCH c2
       INTO diniu, dfinu;

      IF c2%NOTFOUND
      THEN
         diniu := NULL;
      END IF;

      CLOSE c2;

      bdummy := perc_prop != 0;

      IF bdummy AND dinic = :NEW.data_inizio
      THEN
         IF :NEW.data_fine < dfinc
         THEN
            IF (:NEW.pk_cuaa_rif IS NULL)
            THEN
               UPDATE cons_cons_tab
                  SET atto_fin = :NEW.atto_ini,
                      data_fine = :NEW.data_fine
                WHERE cod_nazionale = :NEW.cod_nazionale
                  AND foglio = :NEW.foglio
                  AND particella = :NEW.particella
                  AND sub = :NEW.sub
                  AND data_inizio <= :NEW.data_inizio
                  AND data_fine >= :NEW.data_fine;
            ELSE
               UPDATE cons_cons_tab
                  SET atto_fin = :NEW.atto_ini,
                      data_fine = :NEW.data_fine
                WHERE cod_nazionale = :NEW.cod_nazionale
                  AND foglio = :NEW.foglio
                  AND particella = :NEW.particella
                  AND sub = :NEW.sub
                  AND data_inizio <= :NEW.data_inizio
                  AND data_fine >= :NEW.data_fine
                  AND pk_cuaa = :NEW.pk_cuaa_rif;
            END IF;

            scartato := 1;
         ELSE
          if :NEW.pk_cuaa_rif is null then
            :NEW.cod_errore := -20001;
          end if;
         END IF;
      END IF;

      bdummy := perc_cond != 0;

      IF bdummy AND diniu = :NEW.data_inizio
      THEN
         IF :NEW.data_fine < dfinu
         THEN
            IF (:NEW.pk_cuaa_rif IS NULL)
            THEN
               UPDATE cons_ufre_tab
                  SET atto_fin = :NEW.atto_ini,
                      data_fine = :NEW.data_fine
                WHERE cod_nazionale = :NEW.cod_nazionale
                  AND foglio = :NEW.foglio
                  AND particella = :NEW.particella
                  AND sub = :NEW.sub
                  AND data_inizio <= :NEW.data_inizio
                  AND data_fine >= :NEW.data_fine;
            ELSE
               UPDATE cons_ufre_tab
                  SET atto_fin = :NEW.atto_ini,
                      data_fine = :NEW.data_fine
                WHERE cod_nazionale = :NEW.cod_nazionale
                  AND foglio = :NEW.foglio
                  AND particella = :NEW.particella
                  AND sub = :NEW.sub
                  AND data_inizio <= :NEW.data_inizio
                  AND data_fine >= :NEW.data_fine
                  AND pk_cuaa = :NEW.pk_cuaa_rif;
            END IF;

            scartato := 1;
         ELSE
          if :NEW.pk_cuaa_rif is null then
            :NEW.cod_errore := -20001;
          end if;
         END IF;
      END IF;
   END IF;

   IF scartato = 0
   THEN
      IF dinic IS NULL OR dfinc <> TO_DATE ('99991231', 'YYYYMMDD')
      THEN
         OPEN c3;

         FETCH c3
          INTO dinicsucc;

         IF c3%NOTFOUND
         THEN
            dinicsucc := NULL;
         END IF;

         CLOSE c3;
      END IF;

      IF diniu IS NULL OR dfinu <> TO_DATE ('99991231', 'YYYYMMDD')
      THEN
         OPEN c4;

         FETCH c4
          INTO diniusucc;

         IF c4%NOTFOUND
         THEN
            diniusucc := NULL;
         END IF;

         CLOSE c4;
      END IF;

      bdummy := (ctrlnosuperi AND perc_prop != 0);
      IF bdummy AND NOT (dinic IS NULL) THEN
        if ctrlscadiprec then
          IF (:NEW.pk_cuaa_rif IS NULL) THEN
             UPDATE cons_cons_tab
                SET atto_fin = :NEW.atto_ini,
                    data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
              WHERE cod_nazionale = :NEW.cod_nazionale
                AND foglio = :NEW.foglio
                AND particella = :NEW.particella
                AND sub = :NEW.sub
                AND data_inizio <= :NEW.data_inizio
                AND data_fine >= :NEW.data_fine;
          ELSE
             UPDATE cons_cons_tab
                SET atto_fin = :NEW.atto_ini,
                    data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
              WHERE cod_nazionale = :NEW.cod_nazionale
                AND foglio = :NEW.foglio
                AND particella = :NEW.particella
                AND sub = :NEW.sub
                AND data_inizio <= :NEW.data_inizio
                AND data_fine >= :NEW.data_fine
                AND pk_cuaa = :NEW.pk_cuaa_rif;
          END IF;
        else
          IF (:NEW.pk_cuaa_rif IS NULL) THEN
            select count(*) into iDummy
              from cons_cons_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio;
          ELSE
            select count(*) into iDummy
              from cons_cons_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio
               AND pk_cuaa = :NEW.pk_cuaa_rif;
          END IF;

          if iDummy > 0 then
            :NEW.cod_errore := -20003;
          end if;
        end if;
      END IF;

      bdummy := (ctrlnosuperi AND perc_cond != 0);
      IF bdummy AND NOT (diniu IS NULL) THEN
        if ctrlscadiprec then
           IF (:NEW.pk_cuaa_rif IS NULL) THEN
              UPDATE cons_ufre_tab
                 SET atto_fin = :NEW.atto_ini,
                     data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
               WHERE cod_nazionale = :NEW.cod_nazionale
                 AND foglio = :NEW.foglio
                 AND particella = :NEW.particella
                 AND sub = :NEW.sub
                 AND data_inizio <= :NEW.data_inizio
                 AND data_fine >= :NEW.data_fine;
           ELSE
              UPDATE cons_ufre_tab
                 SET atto_fin = :NEW.atto_ini,
                     data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
               WHERE cod_nazionale = :NEW.cod_nazionale
                 AND foglio = :NEW.foglio
                 AND particella = :NEW.particella
                 AND sub = :NEW.sub
                 AND data_inizio <= :NEW.data_inizio
                 AND data_fine >= :NEW.data_fine
                 AND pk_cuaa = :NEW.pk_cuaa_rif;
           END IF;
        else
          IF (:NEW.pk_cuaa_rif IS NULL) THEN
            select count(*) into iDummy
              from cons_ufre_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio;
          ELSE
            select count(*) into iDummy
              from cons_ufre_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio
               AND pk_cuaa = :NEW.pk_cuaa_rif;
          END IF;

          if iDummy > 0 then
            :NEW.cod_errore := -20003;
          end if;

        end if;
      END IF;

      IF dinicsucc IS NULL
      THEN
         dfinc := :NEW.data_fine;
      ELSE
         dfinc := dinicsucc - (1 / 24 / 60 / 60);
      END IF;

      dinic := :NEW.data_inizio;

      IF diniusucc IS NULL
      THEN
         dfinu := :NEW.data_fine;
      ELSE
         dfinu := diniusucc - (1 / 24 / 60 / 60);
      END IF;

      diniu := :NEW.data_inizio;

      OPEN ccond;

      LOOP
         -- a.caleffi 2008-12-10 aggiunto fecth campo cond_attoini
         FETCH ccond
          INTO condcuaa, condquota_conduzione, condquota_limite,
               condtipo_titolo, condpkcuaa, cond_attoini;

         EXIT WHEN (ccond%NOTFOUND OR :NEW.cod_errore != 0);

         IF condpkcuaa = 0
         THEN
            :NEW.cod_errore := -20002;
         ELSE
            condquota_conduzione :=
                     get_percentuale (condquota_conduzione, condquota_limite);

            IF condtipo_titolo = '1' OR condtipo_titolo = '3'
            THEN
               IF (:NEW.pk_cuaa_rif IS NOT NULL)
               THEN
                  condquota_conduzione :=
                                       condquota_conduzione * quotarifc / 100;
               END IF;

               INSERT INTO cons_cons_tab
                           (pkid_cons, cod_nazionale,
                            foglio, particella, sub,
                            perc_poss, tipo_titolo, data_registrazione,
                            utente, pk_cuaa, data_inizio, data_fine,
                            allegato, sviluppo, TIMESTAMP, sorgente,
                            atto_ini, atto_fin
                           )
                    VALUES (cons_cons_seq.NEXTVAL, :NEW.cod_nazionale,
                            :NEW.foglio, :NEW.particella, :NEW.sub,
                            condquota_conduzione, condtipo_titolo, SYSDATE,
                            :NEW.utente, condpkcuaa, dinic, dfinc,
                            '0', '0', SYSDATE, :NEW.sorgente,
                            :NEW.atto_ini, :NEW.atto_fin
                           );
            ELSE
               IF (:NEW.pk_cuaa_rif IS NOT NULL)
               THEN
                  condquota_conduzione :=
                                       condquota_conduzione * quotarifu / 100;
               END IF;

               -- a.caleffi 2008-12-10 il valore di atto_ini viene preso dalla tabella
               --   loadcons e non piu' dalla loadcons_part, cosi' il codice atto
               --   viene caricato per singolo record di consistenza e non uguale
               --   al codice atto dell'ultimo record di consistenza caricato
               INSERT INTO cons_ufre_tab
                           (pkid_uffr, cod_nazionale,
                            foglio, particella, sub,
                            perc_poss, tipo_titolo, data_registrazione,
                            utente, pk_cuaa, data_inizio, data_fine,
                            allegato, sviluppo, TIMESTAMP, sorgente,
                            atto_ini, atto_fin
                           )
                    VALUES (cons_ufre_seq.NEXTVAL, :NEW.cod_nazionale,
                            :NEW.foglio, :NEW.particella, :NEW.sub,
                            condquota_conduzione, condtipo_titolo, SYSDATE,
                            :NEW.utente, condpkcuaa, diniu, dfinu,
                            '0', '0', SYSDATE, :NEW.sorgente,
                            cond_attoini, :NEW.atto_fin
                           );
            END IF;
         END IF;
      END LOOP;

      CLOSE ccond;
   END IF;                                                          --SCARTATO

   if (ctrl_raise and :new.cod_errore != 0) then
     raise_application_error(:new.cod_errore, 'Error ' || :new.cod_errore);
   end if;

EXCEPTION WHEN OTHERS  THEN
   if (ctrl_raise) then
     raise;
   else
     :NEW.cod_errore := SQLCODE;
     DBMS_OUTPUT.put_line (SQLERRM);
   end if;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOADCONS_PART_UIU_TIA AFTER INSERT ON SITI_H501.LOADCONS_PART_UIU FOR EACH ROW
DECLARE
  tp_tit      cons_cons_tab.tipo_titolo%type;
BEGIN

  if :new.atto_ini is not null and :new.atto_fin is null then
    select tipo_titolo into tp_tit
      from loadcons_uiu
     where ID_CARICAMENTO = :new.id_caricamento
       and ID_PARTICELLA = :new.id_particella
       and rownum = 1;

    if (tp_tit = 1 or tp_tit = 3) then
      patri_pck.nuovoTitolo(:new.cod_nazionale, :new.foglio, :new.particella, :new.sub, :new.unimm, :new.data_inizio, :new.data_fine, :new.atto_ini);
    end if;
  end if;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOADCONS_PART_UIU_TIB  BEFORE INSERT  ON SITI_H501.LOADCONS_PART_UIU  FOR EACH ROW
/*
  a.caleffi 2008-12-12 aggiunta gestione colonna loadcons_uiu.atto_ini per avere il codice
    dell'atto sul singolo record della consistenza uiu
*/
DECLARE
  CURSOR c1 IS
    SELECT MIN (data_inizio), MAX (data_fine)
      FROM cons_csui_tab
     WHERE cod_nazionale = :NEW.cod_nazionale
       AND foglio = :NEW.foglio
       AND particella = :NEW.particella
       AND sub = :NEW.sub
       AND unimm = :NEW.unimm
       AND data_inizio <= :NEW.data_inizio
       AND data_fine >= :NEW.data_fine;

  CURSOR c2 IS
    SELECT MIN (data_inizio), MAX (data_fine)
      FROM cons_urui_tab
     WHERE cod_nazionale = :NEW.cod_nazionale
       AND foglio = :NEW.foglio
       AND particella = :NEW.particella
       AND sub = :NEW.sub
       AND unimm = :NEW.unimm
       AND data_inizio <= :NEW.data_inizio
       AND data_fine >= :NEW.data_fine;

  CURSOR c3 IS
    SELECT MIN (data_inizio)
      FROM cons_csui_tab
     WHERE cod_nazionale = :NEW.cod_nazionale
       AND foglio = :NEW.foglio
       AND particella = :NEW.particella
       AND sub = :NEW.sub
       AND unimm = :NEW.unimm
       AND data_inizio >= :NEW.data_inizio;

  CURSOR c4 IS
    SELECT MIN (data_inizio)
      FROM cons_urui_tab
     WHERE cod_nazionale = :NEW.cod_nazionale
       AND foglio = :NEW.foglio
       AND particella = :NEW.particella
       AND sub = :NEW.sub
       AND unimm = :NEW.unimm
       AND data_inizio >= :NEW.data_inizio;

  -- a.caleffi 2008-12-12 aggiunta colonna atto_ini
  CURSOR ccond IS
    SELECT cuaa, quota_conduzione, quota_limite, tipo_titolo,
           DECODE (pkcuaa, NULL, get_pk_cuaa (cuaa, :NEW.data_inizio), pkcuaa)
           , atto_ini
      FROM loadcons_uiu
     WHERE id_caricamento = :NEW.id_caricamento
       AND id_particella = :NEW.id_particella;

  condpkcuaa             NUMBER (9);
  condcuaa               VARCHAR2 (16);
  condquota_conduzione   NUMBER (11, 2);
  condquota_limite       NUMBER (11, 2);
  condtipo_titolo        NUMBER (11, 2);
  cond_attoini           NUMBER (9);
  dinic                  DATE;
  diniu                  DATE;
  dfinc                  DATE;
  dfinu                  DATE;
  dinicsucc              DATE;
  diniusucc              DATE;
  perc_prop              NUMBER (9);
  perc_cond              NUMBER (9);
  scartato               NUMBER (1);
  quotarifc              cons_csui_tab.perc_poss%TYPE   := 0;
  quotarifu              cons_urui_tab.perc_poss%TYPE   := 0;
  ctrlnosuperi           BOOLEAN;
  ctrlnoincompleti       BOOLEAN;
  ctrlscadiprec          BOOLEAN;
  ctrl_raise             boolean;
  ctrlstrict             BOOLEAN;
  bdummy                 BOOLEAN;
  iDummy                 pls_integer;
BEGIN
  :NEW.cod_errore := 0;
  scartato := 0;
  ctrlnosuperi := (BITAND (:NEW.controlli, 1) = 1);
  ctrlnoincompleti := (BITAND (:NEW.controlli, 2) = 2);
  ctrlscadiprec := (BITAND (:NEW.controlli, 8) = 8);
  ctrlstrict := (BITAND (:NEW.controlli, 16) = 16);
  ctrl_raise := (BITAND (:NEW.controlli, 32) = 32);

  SELECT NVL (SUM (get_percentuale (quota_conduzione, quota_limite)), 0)
    INTO perc_prop
    FROM loadcons_uiu
   WHERE id_caricamento = :NEW.id_caricamento
     AND id_particella = :NEW.id_particella
     AND tipo_titolo IN ('1', '3');

  SELECT NVL (SUM (get_percentuale (quota_conduzione, quota_limite)), 0)
    INTO perc_cond
    FROM loadcons_uiu
   WHERE id_caricamento = :NEW.id_caricamento
     AND id_particella = :NEW.id_particella
     AND tipo_titolo != '1'
     AND tipo_titolo != '3';

  IF perc_prop != 0 AND perc_cond != 0 AND ctrlstrict THEN
    :NEW.cod_errore := -20006;
    scartato := 1;
  END IF;

  IF scartato = 0 AND ctrlnosuperi THEN
    IF perc_prop > 101 OR perc_cond > 101 THEN
      :NEW.cod_errore := -20003;
      scartato := 1;
    END IF;
  END IF;

  IF scartato = 0 AND ctrlnoincompleti THEN
    IF    (perc_prop < 99 AND perc_prop > 0)
       OR (perc_cond < 99 AND perc_cond > 0) THEN
      :NEW.cod_errore := -20004;
      scartato := 1;
    END IF;
  END IF;

  IF (:NEW.pk_cuaa_rif IS NOT NULL) THEN
    IF :NEW.pk_cuaa_rif != 999999999 THEN
      BEGIN
        SELECT perc_poss
          INTO quotarifc
          FROM cons_csui_tab
         WHERE cod_nazionale = :NEW.cod_nazionale
           AND foglio = :NEW.foglio
           AND particella = :NEW.particella
           AND sub = :NEW.sub
           AND unimm = :NEW.unimm
           AND data_inizio <= :NEW.data_inizio
           AND data_fine >= :NEW.data_fine
           AND pk_cuaa = :NEW.pk_cuaa_rif
           AND ROWNUM = 1;
      EXCEPTION
        WHEN OTHERS THEN
          quotarifc := 0;
      END;

      BEGIN
        SELECT perc_poss
          INTO quotarifu
          FROM cons_urui_tab
         WHERE cod_nazionale = :NEW.cod_nazionale
           AND foglio = :NEW.foglio
           AND particella = :NEW.particella
           AND sub = :NEW.sub
           AND unimm = :NEW.unimm
           AND data_inizio <= :NEW.data_inizio
           AND data_fine >= :NEW.data_fine
           AND pk_cuaa = :NEW.pk_cuaa_rif
           AND ROWNUM = 1;
      EXCEPTION
        WHEN OTHERS THEN
          quotarifu := 0;
      END;
    ELSE
      BEGIN
        SELECT 100 - nvl(SUM(perc_poss), 0)
          INTO quotarifc
          FROM cons_csui_tab
         WHERE cod_nazionale = :NEW.cod_nazionale
           AND foglio = :NEW.foglio
           AND particella = :NEW.particella
           AND sub = :NEW.sub
           AND unimm = :NEW.unimm
           AND data_inizio <= :NEW.data_inizio
           AND data_fine >= :NEW.data_fine
           AND pk_cuaa != 999999999;
      EXCEPTION
        WHEN OTHERS THEN
          quotarifc := 0;
      END;

      BEGIN
        SELECT 100 - nvl(SUM(perc_poss), 0)
          INTO quotarifu
          FROM cons_urui_tab
         WHERE cod_nazionale = :NEW.cod_nazionale
           AND foglio = :NEW.foglio
           AND particella = :NEW.particella
           AND sub = :NEW.sub
           AND unimm = :NEW.unimm
           AND data_inizio <= :NEW.data_inizio
           AND data_fine >= :NEW.data_fine
           AND pk_cuaa != 999999999;
      EXCEPTION
        WHEN OTHERS THEN
          quotarifu := 0;
      END;
    END IF;

    IF quotarifc = 0 AND quotarifu = 0 THEN
      :NEW.cod_errore := -20005;
      scartato := 1;
    END IF;
  END IF;

  -- Stessa data inizio, data fine <
  IF scartato = 0 THEN
    OPEN c1;

    FETCH c1
     INTO dinic, dfinc;

    IF c1%NOTFOUND THEN
      dinic := NULL;
    END IF;

    CLOSE c1;

    OPEN c2;

    FETCH c2
     INTO diniu, dfinu;

    IF c2%NOTFOUND THEN
      diniu := NULL;
    END IF;

    CLOSE c2;

    bdummy := perc_prop != 0;

    IF bdummy AND dinic = :NEW.data_inizio THEN
      IF :NEW.data_fine < dfinc THEN
        IF (:NEW.pk_cuaa_rif IS NULL) THEN
          UPDATE cons_csui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_fine
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine;
        ELSE
          UPDATE cons_csui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_fine
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine
             AND pk_cuaa = :NEW.pk_cuaa_rif;
        END IF;

        scartato := 1;
      ELSE
        if :NEW.pk_cuaa_rif is null then
          :NEW.cod_errore := -20001;
        end if;
      END IF;
    END IF;

    bdummy := perc_cond != 0;

    IF bdummy AND diniu = :NEW.data_inizio THEN
      IF :NEW.data_fine < dfinu THEN
        IF (:NEW.pk_cuaa_rif IS NULL) THEN
          UPDATE cons_urui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_fine
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine;
        ELSE
          UPDATE cons_urui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_fine
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine
             AND pk_cuaa = :NEW.pk_cuaa_rif;
        END IF;

        scartato := 1;
      ELSE
        if :NEW.pk_cuaa_rif is null then
          :NEW.cod_errore := -20001;
        end if;
      END IF;
    END IF;
  END IF;

  IF scartato = 0 THEN
    IF dinic IS NULL OR dfinc <> TO_DATE ('99991231', 'YYYYMMDD') THEN
      OPEN c3;

      FETCH c3
       INTO dinicsucc;

      IF c3%NOTFOUND THEN
        dinicsucc := NULL;
      END IF;

      CLOSE c3;
    END IF;

    IF diniu IS NULL OR dfinu <> TO_DATE ('99991231', 'YYYYMMDD') THEN
      OPEN c4;

      FETCH c4
       INTO diniusucc;

      IF c4%NOTFOUND THEN
        diniusucc := NULL;
      END IF;

      CLOSE c4;
    END IF;

    bdummy := (ctrlnosuperi AND perc_prop != 0);
    IF bdummy AND NOT (dinic IS NULL)  THEN
      if ctrlscadiprec then
        IF (:NEW.pk_cuaa_rif IS NULL) THEN
          UPDATE cons_csui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine;
        ELSE
          UPDATE cons_csui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine
             AND pk_cuaa = :NEW.pk_cuaa_rif;
        END IF;
      else
          IF (:NEW.pk_cuaa_rif IS NULL) THEN
            select count(*) into iDummy
              from cons_csui_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND unimm = :NEW.unimm
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio;
          ELSE
            select count(*) into iDummy
              from cons_csui_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND unimm = :NEW.unimm
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio
               AND pk_cuaa = :NEW.pk_cuaa_rif;
          END IF;

          if iDummy > 0 then
            :NEW.cod_errore := -20003;
          end if;
      end if;
    END IF;

    bdummy := (ctrlnosuperi AND perc_cond != 0);
    IF bdummy AND NOT (diniu IS NULL) THEN
      if ctrlscadiprec then
        IF (:NEW.pk_cuaa_rif IS NULL) THEN
          UPDATE cons_urui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine;
        ELSE
          UPDATE cons_urui_tab
             SET atto_fin = :NEW.atto_ini,
                 data_fine = :NEW.data_inizio - (1 / 24 / 60 / 60)
           WHERE cod_nazionale = :NEW.cod_nazionale
             AND foglio = :NEW.foglio
             AND particella = :NEW.particella
             AND sub = :NEW.sub
             AND unimm = :NEW.unimm
             AND data_inizio <= :NEW.data_inizio
             AND data_fine >= :NEW.data_fine
             AND pk_cuaa = :NEW.pk_cuaa_rif;
        END IF;
      else
          IF (:NEW.pk_cuaa_rif IS NULL) THEN
            select count(*) into iDummy
              from cons_urui_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND unimm = :NEW.unimm
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio;
          ELSE
            select count(*) into iDummy
              from cons_urui_tab
             where cod_nazionale = :NEW.cod_nazionale
               AND foglio = :NEW.foglio
               AND particella = :NEW.particella
               AND sub = :NEW.sub
               AND unimm = :NEW.unimm
               AND data_inizio <= :NEW.data_inizio
               AND data_fine >= :NEW.data_inizio
               AND pk_cuaa = :NEW.pk_cuaa_rif;
          END IF;

          if iDummy > 0 then
            :NEW.cod_errore := -20003;
          end if;
      end if;
    END IF;

    IF dinicsucc IS NULL THEN
      dfinc := :NEW.data_fine;
    ELSE
      dfinc := dinicsucc - (1 / 24 / 60 / 60);
    END IF;

    dinic := :NEW.data_inizio;

    IF diniusucc IS NULL THEN
      dfinu := :NEW.data_fine;
    ELSE
      dfinu := diniusucc - (1 / 24 / 60 / 60);
    END IF;

    diniu := :NEW.data_inizio;

    OPEN ccond;

    LOOP
      -- a.caleffi 2008-12-12 aggiunto fecth campo cond_attoini
      FETCH ccond
       INTO condcuaa, condquota_conduzione, condquota_limite,
            condtipo_titolo, condpkcuaa, cond_attoini;

      EXIT WHEN (ccond%NOTFOUND OR :NEW.cod_errore != 0);

      IF condpkcuaa = 0 THEN
        :NEW.cod_errore := -20002;
      ELSE
        condquota_conduzione :=
                     get_percentuale (condquota_conduzione, condquota_limite);

        IF condtipo_titolo = '1' OR condtipo_titolo = '3' THEN
          IF (:NEW.pk_cuaa_rif IS NOT NULL) THEN
            condquota_conduzione := condquota_conduzione * quotarifc / 100;
          END IF;

          INSERT INTO cons_csui_tab
                      (pkid_csui, cod_nazionale,
                       foglio, particella, sub, unimm,
                       perc_poss, tipo_titolo, data_registrazione,
                       utente, pk_cuaa, data_inizio, data_fine, allegato,
                       sviluppo, TIMESTAMP, sorgente, atto_ini,
                       atto_fin
                      )
               VALUES (cons_csui_seq.NEXTVAL, :NEW.cod_nazionale,
                       :NEW.foglio, :NEW.particella, :NEW.sub, :NEW.unimm,
                       condquota_conduzione, condtipo_titolo, SYSDATE,
                       :NEW.utente, condpkcuaa, dinic, dfinc, '0',
                       '0', SYSDATE, :NEW.sorgente, :NEW.atto_ini,
                       :NEW.atto_fin
                      );
        ELSE
          IF (:NEW.pk_cuaa_rif IS NOT NULL) THEN
            condquota_conduzione := condquota_conduzione * quotarifu / 100;
          END IF;

          -- a.caleffi 2008-12-12 il valore di atto_ini viene preso dalla tabella
          --   loadcons_uiu e non piu' dalla loadcons_part, cosi' il codice atto
          --   viene caricato per singolo record di consistenza e non uguale
          --   al codice atto dell'ultimo record di consistenza caricato
          INSERT INTO cons_urui_tab
                      (pkid_urui, cod_nazionale,
                       foglio, particella, sub, unimm,
                       perc_poss, tipo_titolo, data_registrazione,
                       utente, pk_cuaa, data_inizio, data_fine, allegato,
                       sviluppo, TIMESTAMP, sorgente, atto_ini,
                       atto_fin
                      )
               VALUES (cons_urui_seq.NEXTVAL, :NEW.cod_nazionale,
                       :NEW.foglio, :NEW.particella, :NEW.sub, :NEW.unimm,
                       condquota_conduzione, condtipo_titolo, SYSDATE,
                       :NEW.utente, condpkcuaa, diniu, dfinu, '0',
                       '0', SYSDATE, :NEW.sorgente, cond_attoini,
                       :NEW.atto_fin
                      );
        END IF;
      END IF;
    END LOOP;

    CLOSE ccond;
  END IF;                                                           --SCARTATO
   if (ctrl_raise and :new.cod_errore != 0) then
     raise_application_error(:new.cod_errore, 'Error ' || :new.cod_errore);
   end if;

EXCEPTION WHEN OTHERS  THEN
   if (ctrl_raise) then
     raise;
   else
     :NEW.cod_errore := SQLCODE;
     DBMS_OUTPUT.put_line (SQLERRM);
   end if;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOADC_TIB
BEFORE
INSERT
ON SITI_H501.LOADC
FOR EACH ROW
DECLARE
  -- HO USATO PK DI SITITRKC PER CONTROLLARE SE ESISTE, IN SITICATA, IL CENTROIDE DA CARICARE
  -- (IN SITICATA ESISTE DATA_FINE E NON DATA_FINE_VAL COME IN SITICENT)
  CURSOR CCENS IS SELECT 1 FROM SITICATA WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE=:NEW.DATA_FINE_VAL;
  CURSOR CCENT IS SELECT 1 FROM SITICENT WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB;
  CURSOR CCOMU IS SELECT 1 FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FLAG_CATA=2;
  ESISTE NUMBER(1);
BEGIN
  :NEW.COD_ERRORE := 0;

  IF BITAND(:NEW.CONTROLLI,1)=1 THEN
    ESISTE:=0;
    OPEN CCENS;
    FETCH CCENS INTO ESISTE;
    CLOSE CCENS;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20010; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,64)=64 THEN
    ESISTE:=0;
    OPEN CCENT;
    FETCH CCENT INTO ESISTE;
    CLOSE CCENT;
    IF ESISTE != 0 THEN    :NEW.COD_ERRORE:=-20016; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,128)=128 THEN
    ESISTE:=0;
    OPEN CCOMU;
    FETCH CCOMU INTO ESISTE;
    CLOSE CCOMU;
    IF ESISTE != 0 THEN :NEW.FOGLIO:=9999; END IF;
  END IF;

  IF :NEW.COD_ERRORE = 0 THEN
    IF :NEW.DATA_LAV IS NULL THEN
      :NEW.DATA_LAV:=SYSDATE;
    END IF;
    IF :NEW.DATA_INIZIO_VAL IS NULL THEN
      :NEW.DATA_INIZIO_VAL:=SYSDATE;
    END IF;
    INSERT INTO SITICENT(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,DATA_LAV,ALLEGATO,SVILUPPO,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,FLAG_FONTE_DATO,CODI_FORN,SHAPE,ISTATP,SORGENTE,TAVOLA,FLAGCARICO,STATO_PROP)
    VALUES(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DATA_LAV,:NEW.ALLEGATO,:NEW.SVILUPPO,:NEW.UTENTE,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.FLAG_FONTE_DATO,:NEW.CODI_FORN,:NEW.SHAPE,:NEW.ISTATP,:NEW.SORGENTE,:NEW.TAVOLA,:NEW.FLAGCARICO,:NEW.STATO_PROP);
  END IF;
EXCEPTION
   WHEN OTHERS
   THEN
      :NEW.COD_ERRORE := SQLCODE;
      IF SQLCODE = -20005 THEN
        UPDATE SITICENT SET DATA_FINE_VAL = :NEW.DATA_FINE_VAL,UTENTE_FINE = :NEW.UTENTE WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_INIZIO_VAL=:NEW.DATA_INIZIO_VAL;
        :NEW.COD_ERRORE := 0;
      ELSIF SQLCODE = -20001 THEN
        :NEW.COD_ERRORE := 0;
      END IF;
END;
/


DROP SEQUENCE SITI_H501.FOGL_SEQ;

CREATE SEQUENCE SITI_H501.FOGL_SEQ
  START WITH 1
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.LOADF_TIB
BEFORE INSERT
ON SITI_H501.LOADF
FOR EACH ROW
DECLARE
  IDFOG NUMBER(9);
  IDTAVO NUMBER(9);
  IDMAP NUMBER(9);
  MTYP NUMBER(9);
/*
  a.caleffi 2009-08-26 fix su union geometrie
*/
BEGIN
  IDFOG:=MIGRAZIONE.CREA_ID_FOGLIO(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
  IF :NEW.SHAPE IS NOT NULL THEN
    IDTAVO:=MIGRAZIONE.CREA_ID_TAVO(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.TAVOLA,:NEW.SHAPE);
  ELSE
    IDTAVO:=MIGRAZIONE.GET_ID_TAVO(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.TAVOLA);
  END IF;

  IF IDTAVO != 0 THEN
    IF :NEW.SHMAP IS NOT NULL THEN
      IDMAP := MIGRAZIONE.GET_ID_MAPPA(IDTAVO,:NEW.ALLEGATO,:NEW.SVILUPPO,0,'SITI');
      MTYP:=1;
      IF :NEW.FILETYPE='DWG' THEN MTYP:=2; END IF;

      IF IDMAP!= 0 THEN
        UPDATE GIS_MAPPE SET NOME_MAPPA=:NEW.FILENAME,MAP_TYPE=MTYP,SHAPE=:NEW.SHMAP WHERE ID_MAPPA=IDMAP;
      ELSE

        SELECT FOGL_SEQ.NEXTVAL INTO IDMAP FROM DUAL;

        INSERT INTO GIS_MAPPE(ID_MAPPA, ID_TAVO, ALLEGATO, SVILUPPO, NOME_MAPPA, MAP_TYPE, MAP_VERSION, SCALA, SHAPE)
        VALUES(IDMAP,IDTAVO,:NEW.ALLEGATO,:NEW.SVILUPPO,:NEW.FILENAME,MTYP,'SITI',0,:NEW.SHMAP);
      END IF;
    END IF;

    IF :NEW.SHAPE IS NOT NULL AND :NEW.ALLEGATO='0' AND :NEW.SVILUPPO='0' THEN
      UPDATE GIS_TAVO SET SHAPE=:NEW.SHAPE WHERE ID_TAVO=IDTAVO;
    ELSE
      -- a.caleffi 2009-08-26 aggiunta funzione sdo_tools.remove_duplicate_points
      -- alle geometrie degli shape, dato che nella versione 10 di oracle va in errore:
      --
      -- ORA-13050: impossibile costruire l'oggetto spaziale
      -- ORA-06512: a "MDSYS.SDO_3GL", line 715
      -- ORA-06512: a "MDSYS.SDO_GEOM", line 2968
      -- ORA-06512: a "MDSYS.SDO_GEOM", line 3029
      --
      -- la patch per la correzione dell'errore e' la
      -- 10.2.0.4 5871002 SDO_TOPO_GEOMETRY constructor fails on versioned topology

      UPDATE GIS_TAVO
      SET SHAPE =
        SDO_GEOM.SDO_UNION(sdo_tools.remove_duplicate_points(SHAPE), sdo_tools.remove_duplicate_points(:NEW.SHAPE), 0.005)
      WHERE ID_TAVO=IDTAVO
      AND SHAPE IS NOT NULL;


      IF SQL%ROWCOUNT = 0 THEN
        UPDATE GIS_TAVO SET SHAPE=:NEW.SHAPE WHERE ID_TAVO=IDTAVO;
      END IF;

    END IF;

  END IF;
END;
/


DROP SEQUENCE SITI_H501.LOADICI_CARICATI_SEQ;

