CREATE OR REPLACE TRIGGER SITI_H501.LOADICI_CARICATI_TIB
   BEFORE INSERT
   ON SITI_H501.LOADICI_CARICATI
   FOR EACH ROW
DECLARE
BEGIN
  IF :NEW.PKID IS NULL
    THEN
      SELECT LOADICI_CARICATI_SEQ.NEXTVAL
