CREATE OR REPLACE TRIGGER SITI_H501.LOADM_TIB
BEFORE INSERT
ON SITI_H501.LOADM
FOR EACH ROW
DECLARE
  CURSOR CCENS IS SELECT 1 FROM SITICATA WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND SITICATA.DATA_INIZIO <= :NEW.DATA_INIZIO_VAL AND SITICATA.DATA_FINE > :NEW.DATA_INIZIO_VAL;
  CURSOR CFOG IS SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND TAVOLA=:NEW.FOGLIO AND SDO_RELATE(SITIFGLC.SHAPE,:NEW.SHAPE, 'MASK=ANYINTERACT') = 'TRUE';
  CURSOR CSUCC IS SELECT 1 FROM SITIFOTC WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_INIZIO_VAL > :NEW.DATA_INIZIO_VAL;

  ESISTE NUMBER(1);
BEGIN
  :NEW.COD_ERRORE := 0;

  IF BITAND(:NEW.CONTROLLI,1)=1 AND :NEW.DATA_FINE_VAL > SYSDATE THEN
    ESISTE:=0;
    OPEN CCENS;
    FETCH CCENS INTO ESISTE;
    CLOSE CCENS;
    IF ESISTE != 1 THEN
      :NEW.DATA_FINE_VAL := SYSDATE;
      :NEW.FLAGCARICO := 1;
      --:NEW.COD_ERRORE:=-20002;
    END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,2)=2 THEN
    ESISTE:=0;
    OPEN CFOG;
    FETCH CFOG INTO ESISTE;
    CLOSE CFOG;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20003; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,4)=4 THEN
    ESISTE:=0;
    OPEN CSUCC;
    FETCH CSUCC INTO ESISTE;
    CLOSE CSUCC;
    IF ESISTE = 1 THEN    :NEW.COD_ERRORE:=-20004; END IF;
  END IF;

  IF :NEW.COD_ERRORE = 0 THEN
    INSERT INTO SITIFOTC(cod_nazionale,foglio,particella,sub,data_lav,utente,data_inizio_val,data_fine_val,shape,istatp,sorgente,tavola,FLAGCARICO,NOME_FOTO,ROTAZIONE,PROG_FOTO)
    VALUES(:NEW.cod_nazionale,:NEW.foglio,:NEW.particella,:NEW.sub,:NEW.data_lav,:NEW.utente,:NEW.data_inizio_val,:NEW.data_fine_val,:NEW.shape,:NEW.istatp,:NEW.sorgente,:NEW.tavola,:NEW.FLAGCARICO,:NEW.NOME_FOTO,:NEW.ROTAZIONE,:NEW.PROG_FOTO);
  END IF;
EXCEPTION
   WHEN OTHERS
   THEN
      :NEW.COD_ERRORE := SQLCODE;
      IF SQLCODE = -20005 THEN
        UPDATE SITIFOTC SET DATA_FINE_VAL = :NEW.data_fine_val,UTENTE_FINE = :NEW.utente WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND data_inizio_val=:NEW.data_inizio_val;
        :NEW.COD_ERRORE := 0;
      ELSIF SQLCODE = -20001 THEN
        :NEW.COD_ERRORE := 0;
      END IF;
      --IF SQLCODE != -20001 THEN        RAISE      END IF;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOADO_TIB
BEFORE
INSERT
ON SITI_H501.LOADO
FOR EACH ROW
DECLARE
  CURSOR CPART IS SELECT 1 FROM SITIPART WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND DATA_FINE_VAL=:NEW.DATA_FINE_VAL;
  CURSOR CSUOL IS SELECT 1 FROM SITISUOLO WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND PROG_POLIGONO=:NEW.PROG_POLIGONO;
  CURSOR CCOMU IS SELECT 1 FROM SITICOMU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FLAG_CATA=2;
  ESISTE NUMBER(1);
BEGIN
  :NEW.COD_ERRORE := 0;

  IF BITAND(:NEW.CONTROLLI,16)=16 THEN
    ESISTE:=0;
    OPEN CPART;
    FETCH CPART INTO ESISTE;
    CLOSE CPART;
    IF ESISTE != 1 THEN    :NEW.COD_ERRORE:=-20014; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,64)=64 THEN
    ESISTE:=0;
    OPEN CSUOL;
    FETCH CSUOL INTO ESISTE;
    CLOSE CSUOL;
    IF ESISTE != 0 THEN    :NEW.COD_ERRORE:=-20016; END IF;
  END IF;

  IF BITAND(:NEW.CONTROLLI,128)=128 THEN
    ESISTE:=0;
    OPEN CCOMU;
    FETCH CCOMU INTO ESISTE;
    CLOSE CCOMU;
    IF ESISTE != 0 THEN :NEW.FOGLIO:=9999; END IF;
  END IF;

  IF :NEW.COD_ERRORE = 0 THEN
    IF :NEW.DATA_LAV IS NULL THEN
      :NEW.DATA_LAV:=SYSDATE;
    END IF;
    IF :NEW.DATA_INIZIO_VAL IS NULL THEN
      :NEW.DATA_INIZIO_VAL:=SYSDATE;
    END IF;

    INSERT INTO SITIPIANTE(cod_nazionale,foglio,particella,sub,data_lav,allegato,sviluppo,utente,data_inizio_val,data_fine_val,shape,istatp,sorgente,tavola,PROG_POLIGONO,COD_UTIL,COD_COLTURA,COD_VARIETA,NUME_PIAN,CAMPAGNA,FLAGCARICO,stato_prop,nume_pian_prod,SUPE_IMPI,PROG_SUOLO,ISOLATE)
    VALUES(:NEW.cod_nazionale,:NEW.foglio,:NEW.particella,:NEW.sub,:NEW.data_lav,:NEW.allegato,:NEW.sviluppo,:NEW.utente,:NEW.data_inizio_val,:NEW.data_fine_val,:NEW.shape,:NEW.istatp,:NEW.sorgente,:NEW.tavola,:NEW.PROG_POLIGONO,:NEW.COD_UTIL,:NEW.COD_COLTURA,:NEW.COD_VARIETA,:NEW.NUME_PIAN,:NEW.CAMPAGNA,:NEW.FLAGCARICO,:NEW.stato_prop,:NEW.nume_pian_prod,:NEW.SUPE_IMPI,:NEW.PROG_SUOLO,:NEW.ISOLATE);
  END IF;
EXCEPTION
   WHEN OTHERS
   THEN
      :NEW.COD_ERRORE := SQLCODE;
      IF SQLCODE = -20005 THEN
        UPDATE SITIPIANTE SET DATA_FINE_VAL = :NEW.data_fine_val,UTENTE_FINE = :NEW.utente WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND data_inizio_val=:NEW.data_inizio_val;
        :NEW.COD_ERRORE := 0;
      ELSIF SQLCODE = -20001 THEN
        :NEW.COD_ERRORE := 0;
        INSERT INTO TEST_TABLE VALUES ('SCATRTO' || :NEW.COD_NAZIONALE || :NEW.FOGLIO || :NEW.PARTICELLA || :NEW.PROG_POLIGONO);
      END IF;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOAD_PATRI_LOC_CANONIPL_TR1 before insert on SITI_H501.LOAD_PATRI_LOC_CANONIPL for each ROW
/*
 a.caleffi 2008-12-12 modifiche ricerca atto
*/

declare
  id_atto number;
begin

  -- a.caleffi 2008-12-12 fix, corretto criterio ricerca da 'pkid_atto' a ':NEW.pkid_atto' per ricerca atto
  SELECT pkid_atto
    INTO id_atto
    FROM sitidata_atti_titoli
   WHERE pkid_atto_utente = :NEW.pkid_atto AND fkid_tipo_atto = -22;

  insert into PATRI_LOC_CANONIPL (ID_CANONE, CODICE, IMPORTO, ANNO)
    values ((select nvl(max(id_canone), 0) + 1 from PATRI_LOC_CANONIPL where codice=id_atto), id_atto, :new.IMPORTO, :new.ANNO);
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOAD_PATRI_LOC_SCAD_CONTR_TR1 before insert ON SITI_H501.LOAD_PATRI_LOC_SCADENZE_CONTR for each row
declare
  id_atto number;
  id_doc number;
begin

  SELECT pkid_atto
    INTO id_atto
    FROM sitidata_atti_titoli
   WHERE pkid_atto_utente = :new.pkid_atto AND fkid_tipo_atto = -22;

  select ad.fkid_doc into id_doc
    from sitifile_atti_doc ad, sitifile_documenti d
   where ad.fkid_atto = id_atto
     and d.FKID_TIPO_DOC = -27
     and d.pkid_doc = ad.FKID_DOC
     and rownum = 1;

  insert into PATRI_LOC_SCADENZE_CONTR
    (PKID_SCAD, FKID_DOC, DATA_INIZIO, DATA_FINE, DATA_DISDETTA, DATA_RIC_COM, DATA_SPEDIZIONE, COMUNICAZIONE, TIPO, DATA_RILASCIO)
   values ((select nvl(max(pkid_scad), 0) + 1 from PATRI_LOC_SCADENZE_CONTR where fkid_doc=id_doc), id_doc, :new.DATA_INIZIO, :new.DATA_FINE, :new.DATA_DISDETTA, :new.DATA_RIC_COM,
           :new.DATA_SPEDIZIONE, :new.COMUNICAZIONE, :new.TIPO, :new.DATA_RILASCIO);
end;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOAD_PATRI_LOC_SPESE_TR1
  BEFORE INSERT
  ON SITI_H501.LOAD_PATRI_LOC_SPESE
  FOR EACH ROW
DECLARE
  id_atto   NUMBER;
  id_doc    NUMBER;
BEGIN
  SELECT pkid_atto
    INTO id_atto
    FROM sitidata_atti_titoli
   WHERE pkid_atto_utente = :NEW.fk_atto AND fkid_tipo_atto = -22;

  INSERT INTO patri_loc_spese
              (fk_atto, cod_fat, importo, dataini, datafin, imprate, numtrate,
               numprate, note, cod_mil, cod_bil, conguaglio, datafinprec, gruppo,
               codrisc, id_contr, compe_dal, compe_al, periodo, tipo_comp,
               ID, soc_assoc, sogg_iva, fattura, sing_cod_inq,
               id_stornato, il_id
              )
       VALUES (id_atto, :NEW.cod_fat, :NEW.importo, :NEW.dataini, :NEW.datafin, :NEW.imprate, :NEW.numtrate,
               :NEW.numprate, :NEW.note, :NEW.cod_mil, :NEW.cod_bil, :NEW.conguaglio, :NEW.datafinprec, :NEW.gruppo,
               :NEW.codrisc, :NEW.id_contr, :NEW.compe_dal, :NEW.compe_al, :NEW.periodo, :NEW.tipo_comp,
               (SELECT NVL (MAX (ID), 0) + 1 FROM patri_loc_spese), :NEW.soc_assoc, :NEW.sogg_iva, :NEW.fattura, :NEW.sing_cod_inq,
               :NEW.id_stornato, (SELECT NVL (MAX (ID), 0) + 1 FROM patri_loc_spese)
