  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.SITIDOCTRASF_TIB
BEFORE INSERT ON SITI_H501.SITIDOCTRASF
REFERENCING OLD AS OLD NEW AS NEW FOR EACH ROW
DECLARE
   sql_stmt   VARCHAR2 (2048);
   valore     NUMBER (5);
BEGIN
   SELECT sitidoctrasf_seq.NEXTVAL INTO :NEW.pkid_doctrasf FROM DUAL;
   IF :NEW.progressivo IS NULL THEN
      sql_stmt := 'SELECT MAX (progressivo) FROM sitidoctrasf WHERE id_trasf = :1 AND tipo_immo = :2';
      EXECUTE IMMEDIATE sql_stmt INTO valore USING :NEW.id_trasf, :NEW.tipo_immo;
      IF valore IS NULL THEN
         :NEW.progressivo := 1;
      ELSE
         :NEW.progressivo := valore + 1;
      END IF;
   END IF;
END;
/


