CREATE OR REPLACE TRIGGER SITI_H501.SITIEDI_VANI_ID
BEFORE INSERT OR UPDATE
ON SITI_H501.SITIEDI_VANI
FOR EACH ROW
DECLARE
  ID NUMBER(9);
BEGIN

  IF :NEW.ID_CATA_VANO IS NULL THEN
    BEGIN
      SELECT ID_CATA_VANO INTO ID FROM CATA_VANI WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND UNIMM=:NEW.UNIMM AND VANO=:NEW.VANO;
    EXCEPTION
      WHEN OTHERS THEN
        SELECT CATA_VANI_SEQ.NEXTVAL INTO ID FROM DUAL;
        INSERT INTO CATA_VANI(ID_CATA_VANO, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, UNIMM, VANO)
        VALUES(ID,:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.UNIMM,:NEW.VANO);
    END;
    :NEW.ID_CATA_VANO:=ID;
  END IF;

END;
/


DROP SEQUENCE SITI_H501.SITIEDI_VANI_SEQ;

CREATE SEQUENCE SITI_H501.SITIEDI_VANI_SEQ
  START WITH 291521
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.SITIEDI_VANI_TIB
BEFORE INSERT or UPDATE
ON SITI_H501.SITIEDI_VANI
FOR EACH ROW
/*
a.caleffi 2010-02-19 fix :new.se_row_id
*/
DECLARE
  cursor c(dfv date) is
    select *
      from cons_urui_tab
     where cod_nazionale = :new.cod_nazionale
       and foglio = :new.foglio
       and particella = :new.particella
       and sub = :new.sub
       and unimm = :new.unimm
       and fl_totale = 'Y'
       and data_inizio <= dfv
       and data_fine >= :new.data_inizio_val
    order by data_fine desc;

  r     c%rowtype;
  gotIt boolean;
  cnt   pls_integer;
BEGIN
  if inserting then
    UPDATE_PATRI_DATA.insertingVano := 'Y';

  IF :NEW.SHAPE IS NULL THEN
     :NEW.SHAPE := UPDATE_PATRI_DATA.GET_SHAPE_VANO(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.UNIMM,:NEW.VANO,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL);
    END IF;

  IF :NEW.ID_ATTO IS NULL THEN
     :NEW.ID_ATTO := UPDATE_PATRI_DATA.GET_ATTO_VANO(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.UNIMM,:NEW.VANO,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL);
    END IF;

		-- a.caleffi 2010-02-19 aggiunto controllo se ha valore -1
		-- in SITIModelli non venendo attribuito il valore di se_row_id viene impostato a 0 per i nuovi record
		-- le procedure di inserimento considerano 0 come NULL e viene generato un errore
		-- allora viene passato -1 ad indicare un ALIAS di NULL affinche' il valore venga preso dalla sequenza
    IF :NEW.SE_ROW_ID IS NULL OR (-1 = :NEW.SE_ROW_ID) THEN
      SELECT SITIEDI_VANI_SEQ.NEXTVAL INTO :NEW.SE_ROW_ID FROM DUAL;
    END IF;
    IF :NEW.DATA_LAV IS NULL THEN :NEW.DATA_LAV:=SYSDATE; END IF;

    :NEW.DATA_FINE_VAL := UPDATE_PATRI_DATA.SCADI_VANI(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.UNIMM,:NEW.VANO,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE);

    open c(:new.data_fine_val);
    fetch c into r;
    gotIt := c%found;
    close c;

    if gotIt then
      begin
        insert into cons_urui_vani (id_atto, cod_nazionale, foglio, particella, sub, unimm, vano, data_inizio_val, data_fine_val)
          values (r.atto_ini, :new.cod_nazionale, :new.foglio, :new.particella, :new.sub, :new.unimm, :new.vano, r.data_inizio, r.data_fine);
      exception when dup_val_on_index then
        -- Sto storicizzando un vano giï¿½ presente...
        null;
      end;
    end if;

  elsif UPDATE_PATRI_DATA.insertingVano is null or UPDATE_PATRI_DATA.insertingVano != 'Y' then
    -- UPDATE_PATRI_DATA.SCADI_VANI da un update di questa tabella... in quel caso non devo intervenire
    -- Rigetto storicizzazioni se c'ï¿½ un affitto in corso
    if (:old.data_fine_val != :new.data_fine_val) then
      open c(:old.data_fine_val);
      fetch c into r;
      gotIt := c%found;
      close c;

      if gotIt then
        -- E' un affitto totale
        /*
        -- Lascio storicizzare tutto tranne l'ultimo vano...
        select count(*) into cnt
          from cons_urui_vani
         where cod_nazionale = :old.cod_nazionale
           and foglio = :old.foglio
           and particella = :old.particella
           and sub = :old.sub
           and unimm = :old.unimm
           and vano = :old.vano
           and data_inizio <= :old.data_fine_val
           and data_fine >= :old.data_inizio_val;

        if cnt = 1 and r.data_fine > :new.data_fine_val then
        */
        if r.data_fine > :new.data_fine_val then
          raise_application_error(-20002, 'Affitto in corso...');
        end if;
      else
        -- Solo alcuni vani sono affittati
        select count(*) into cnt
          from cons_urui_vani
         where cod_nazionale = :old.cod_nazionale
           and foglio = :old.foglio
           and particella = :old.particella
           and sub = :old.sub
           and unimm = :old.unimm
           and vano = :old.vano
           and data_inizio_val <= :old.data_fine_val
           and data_fine_val >= :old.data_inizio_val;

        if (cnt > 0) then
          raise_application_error(-20002, 'Affitto in corso...');
        end if;
      end if;

    end if;
  end if;

END;
/


