CREATE SEQUENCE SITI_H501.SITIFOTC_SEQ
  START WITH 281
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.SITIFOTC_TIB
BEFORE INSERT
ON SITI_H501.SITIFOTC
FOR EACH ROW
BEGIN
   SELECT SITIFOTC_SEQ.NEXTVAL INTO :NEW.se_row_id FROM dual;
   IF :NEW.ISTATP IS NULL THEN
       SELECT SITICOMU.ISTATP INTO :NEW.ISTATP FROM SITICOMU WHERE SITICOMU.COD_NAZIONALE=:NEW.COD_NAZIONALE;
   END IF;
   IF :NEW.NOME_FOTO IS NULL THEN
   	:NEW.NOME_FOTO :=:NEW.COD_NAZIONALE || TRIM(TO_CHAR(:NEW.FOGLIO,'0000')) || :NEW.PARTICELLA || :NEW.SUB || TRIM(TO_CHAR(:NEW.PROG_FOTO,'000')) || '.JPG';
   END IF;
   IF :NEW.SORGENTE > 0 THEN
      :NEW.DATA_FINE_VAL := UPDATE_GIS_DATA.SCADI_FOTC(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE,:NEW.PROG_FOTO,:NEW.STATO_PROP,:NEW.ID_TRASF);
      IF :NEW.SORGENTE = 3 AND :NEW.STATO_PROP=0 THEN
        UPDATE SITIFOTC SET STATO_PROP=0,VALI_PROD=2 WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND STATO_PROP > 0 AND DATA_INIZIO_VAL < :NEW.DATA_INIZIO_VAL;
      END IF;
   END IF;
END;
/


