CREATE OR REPLACE TRIGGER SITI_H501.SITILOG_CONV_TIB
BEFORE INSERT
ON SITI_H501.SITILOG_CONV
FOR EACH ROW
DECLARE

BEGIN
  IF :NEW.TIPO_OPERAZIONE = 1 THEN
    IF :NEW.COD_NAZ_ORIG IS NOT NULL AND :NEW.COD_NAZ_DEST IS NULL AND :NEW.TAVOLA_ORIG IS NOT NULL AND :NEW.TAVOLA_DEST IS NOT NULL THEN
      SITICONV.INVERSIONE_TAVOLA(:NEW.COD_NAZ_ORIG, :NEW.TAVOLA_ORIG, :NEW.TAVOLA_DEST, :NEW.MOV_CONS_TERRENI, :NEW.MOV_CONS_UIU, :NEW.MOV_UNAR, :NEW.MOV_GIS, :NEW.MOV_UIU, :NEW.MOV_STRADE, :NEW.MOV_FIUMI, :NEW.MOV_CATASTO_TERRENI);
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: PARAMETRI ERRATI ALLA FUNZIONE INVERSIONE_TAVOLA. SONO RICHIESTI: COD_NAZ_ORIG, TAVOLA_ORIG, TAVOLA_DEST');
    END IF;
  ELSIF :NEW.TIPO_OPERAZIONE = 2 THEN
    IF :NEW.COD_NAZ_ORIG IS NOT NULL AND :NEW.COD_NAZ_DEST IS NOT NULL AND :NEW.TAVOLA_ORIG IS NULL AND :NEW.TAVOLA_DEST IS NULL THEN
      SITICONV.INVERSIONE_COMUNE(:NEW.COD_NAZ_ORIG, :NEW.COD_NAZ_DEST, :NEW.MOV_CONS_TERRENI, :NEW.MOV_CONS_UIU, :NEW.MOV_UNAR, :NEW.MOV_GIS, :NEW.MOV_UIU, :NEW.MOV_STRADE, :NEW.MOV_FIUMI, :NEW.MOV_CATASTO_TERRENI);
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: PARAMETRI ERRATI ALLA FUNZIONE INVERSIONE_COMUNE. SONO RICHIESTI: COD_NAZ_ORIG, COD_NAZ_DEST');
    END IF;
  ELSIF :NEW.TIPO_OPERAZIONE = 3 THEN
    IF :NEW.COD_NAZ_ORIG IS NOT NULL AND :NEW.COD_NAZ_DEST IS NOT NULL AND :NEW.TAVOLA_ORIG IS NOT NULL AND :NEW.TAVOLA_DEST IS NULL THEN
      SITICONV.SPOSTA_FOGLIO_SU_NUOVO_COMUNE(:NEW.COD_NAZ_ORIG, :NEW.COD_NAZ_DEST, :NEW.TAVOLA_ORIG, :NEW.MOV_CONS_TERRENI, :NEW.MOV_CONS_UIU, :NEW.MOV_UNAR, :NEW.MOV_GIS, :NEW.MOV_UIU, :NEW.MOV_STRADE, :NEW.MOV_FIUMI, :NEW.MOV_CATASTO_TERRENI);
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: PARAMETRI ERRATI ALLA FUNZIONE SPOSTA_FOGLIO_SU_NUOVO_COMUNE. SONO RICHIESTI: COD_NAZ_ORIG, COD_NAZ_DEST, TAVOLA_ORIG');
    END IF;
  ELSIF :NEW.TIPO_OPERAZIONE = 4 THEN
    IF :NEW.COD_NAZ_ORIG IS NOT NULL AND :NEW.FOGLIO_ORIG IS NOT NULL AND :NEW.FOGLIO_DEST IS NOT NULL AND :NEW.TAVOLA_ORIG IS NOT NULL THEN
      SITICONV.CAMBIA_TAVOLA(:NEW.COD_NAZ_ORIG, :NEW.TAVOLA_ORIG, :NEW.FOGLIO_ORIG, :NEW.FOGLIO_DEST, :NEW.MOV_GIS);
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: PARAMETRI ERRATI ALLA FUNZIONE CAMBIA_TAVOLA. SONO RICHIESTI: COD_NAZ_ORIG, TAVOLA_ORIG, FOGLIO_ORIG, FOGLIO_DEST');
    END IF;
  END IF;
END;
/


