FOR EACH ROW
DECLARE
  IDF NUMBER (9);
BEGIN

  IF :NEW.COD_NAZIONALE IS NULL AND :NEW.ID_PARTICELLA IS NOT NULL THEN
    SELECT
    COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,FOGLIO
    INTO
    :NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.TAVOLA
    FROM CATA_PART WHERE ID_CATA_PART = :NEW.ID_PARTICELLA;
  END IF;

  IF :NEW.ID_PARTICELLA IS NULL AND :NEW.COD_NAZIONALE IS NOT NULL THEN

    IDF:=MIGRAZIONE.CREA_ID_FOGLIO(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
    :NEW.ID_PARTICELLA:=MIGRAZIONE.CREA_ID_PARTICELLA(IDF,:NEW.PARTICELLA, :NEW.SUB);

  END IF;

END;
/


DROP SEQUENCE SITI_H501.SITISUOLO_SEQ;

CREATE SEQUENCE SITI_H501.SITISUOLO_SEQ
  START WITH 154279
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.SITISUOLO_TIB
BEFORE
INSERT
ON SITI_H501.SITISUOLO
FOR EACH ROW
DECLARE
	STMT  VARCHAR2(2048);
	VCOUNT INTEGER;
BEGIN
	IF :NEW.PROG_POLIGONO IS NULL THEN
		STMT := 'SELECT MAX(PROG_POLIGONO) FROM SITISUOLO WHERE COD_NAZIONALE=''' || :NEW.COD_NAZIONALE || ''' AND FOGLIO=' || :NEW.FOGLIO || ' AND PARTICELLA=''' || :NEW.PARTICELLA ||''' AND SUB=''' || :NEW.SUB ||''' ';
		EXECUTE IMMEDIATE STMT INTO VCOUNT;
		IF VCOUNT IS NULL THEN
			:NEW.PROG_POLIGONO:=1;
		ELSE
			:NEW.PROG_POLIGONO:=VCOUNT+1;
		END IF;
	END IF;

	SELECT SITISUOLO_SEQ.NEXTVAL INTO :NEW.se_row_id FROM dual;
	IF :NEW.ISTATP IS NULL THEN
		SELECT SITICOMU.ISTATP INTO :NEW.ISTATP FROM SITICOMU WHERE SITICOMU.COD_NAZIONALE=:NEW.COD_NAZIONALE;
	END IF;
  IF :NEW.SORGENTE > 0 THEN
      :NEW.DATA_FINE_VAL := UPDATE_GIS_DATA.SCADI_SUOLO(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE,:NEW.PROG_POLIGONO,:NEW.STATO_PROP,:NEW.ID_TRASF);
      SITIUTILS.AGG_ANOM_REFR(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
   END IF;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.SITISUOLO_TUB
after update
ON SITI_H501.SITISUOLO
FOR EACH ROW
BEGIN
        SITIUTILS.AGG_ANOM_REFR(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
END;
/


