CREATE OR REPLACE TRIGGER SITI_H501.SITIUIU_ID
BEFORE INSERT OR UPDATE
ON SITI_H501.SITIUIU
FOR EACH ROW
DECLARE
  ID NUMBER(9);
BEGIN

  IF :NEW.ID_CATA_UIU IS NULL THEN
    BEGIN
      SELECT ID_CATA_UIU INTO ID FROM CATA_UIU WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND UNIMM=:NEW.UNIMM;
    EXCEPTION
      WHEN OTHERS THEN
        SELECT CATA_UIU_SEQ.NEXTVAL INTO ID FROM DUAL;
        INSERT INTO CATA_UIU(ID_CATA_UIU, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, UNIMM)
        VALUES(ID,:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.UNIMM);
    END;
    :NEW.ID_CATA_UIU:=ID;
  END IF;

END;
