DROP SEQUENCE SITI_H501.SITIUNAR_SEQ;

CREATE SEQUENCE SITI_H501.SITIUNAR_SEQ
  START WITH 81
  MAXVALUE 999999999
  MINVALUE 1
  NOCYCLE
  CACHE 20
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER SITI_H501.SITIUNARTIB
BEFORE
INSERT
ON SITI_H501.SITIUNAR
FOR EACH ROW
DECLARE
  idf NUMBER(9);
BEGIN

  IF :NEW.COD_NAZIONALE IS NULL AND :NEW.ID_PARTICELLA IS NOT NULL THEN
    SELECT
    COD_NAZIONALE,FOGLIO,PARTICELLA,SUB
    INTO
    :NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB
    FROM CATA_PART WHERE ID_CATA_PART = :NEW.ID_PARTICELLA;
  END IF;

  IF :NEW.ID_PARTICELLA IS NULL AND :NEW.COD_NAZIONALE IS NOT NULL THEN

    IDF:=MIGRAZIONE.CREA_ID_FOGLIO(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
    :NEW.ID_PARTICELLA:=MIGRAZIONE.CREA_ID_PARTICELLA(IDF,:NEW.PARTICELLA, :NEW.SUB);

  END IF;

  IF :NEW.PKID_UNAR IS NULL THEN
   SELECT SITIUNAR_SEQ.NEXTVAL INTO :NEW.PKID_UNAR FROM DUAL;
  END IF;
  IF :NEW.UNAR IS NULL THEN
   SELECT Nvl(MAX(UNAR),0)+1 INTO :NEW.UNAR FROM SITIUNAR WHERE COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB;
  END IF;

  IF :NEW.SORGENTE > 0 THEN
    :NEW.DATA_FINE_VAL := UPDATE_GIS_DATA.SCADI_UNARB(:NEW.COD_NAZIONALE,:NEW.FOGLIO,:NEW.PARTICELLA,:NEW.SUB,:NEW.UNAR,:NEW.DATA_INIZIO_VAL,:NEW.DATA_FINE_VAL,:NEW.UTENTE);
  END IF;

  IF :NEW.COD_TIPO_COLT IS NULL THEN    :NEW.COD_TIPO_COLT:=0;  END IF;
  IF :NEW.GRUPPO = 0 THEN    :NEW.GRUPPO := NULL;  END IF;

  IF :NEW.AREA IS NULL AND :NEW.GRUPPO > 0 THEN
    BEGIN
      SELECT AREA_COLT
      INTO :NEW.AREA
      FROM SITISUOLO WHERE
      COD_NAZIONALE=:NEW.COD_NAZIONALE AND FOGLIO=:NEW.FOGLIO AND PARTICELLA=:NEW.PARTICELLA AND SUB=:NEW.SUB AND
      DATA_INIZIO_VAL <= :NEW.DATA_FINE_VAL AND DATA_FINE_VAL >= :NEW.DATA_FINE_VAL AND
      GRUPPO=:NEW.GRUPPO;
      EXCEPTION
        WHEN Others THEN
          NULL;
    END;
  END IF;

  SITIUTILS.AGG_ANOM_REFR(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.SITIUNAR_TUB
after update
ON SITI_H501.SITIUNAR
FOR EACH ROW
BEGIN
     SITIUTILS.AGG_ANOM_REFR(:NEW.COD_NAZIONALE,:NEW.FOGLIO);
END;
