CREATE OR REPLACE TRIGGER SITI_H501.TIB_CESITIRPAN
BEFORE
INSERT
ON SITI_H501.CESITIRPAN
FOR EACH ROW
DECLARE
 STMT  VARCHAR2(2048);
 CODICE_LETTO CHAR(4);
 IP NUMBER(3);
 IC NUMBER(3);
 SS VARCHAR2(3);
BEGIN
  IF :NEW.COD_NAZIONALE IS NULL THEN
    STMT := 'SELECT COD_NAZIONALE FROM SITICOMU WHERE ISTATP=''' || TRIM(TO_CHAR(:NEW.ISTAT_PROV,'000')) || ''' AND ISTATC=''' || TRIM(TO_CHAR(:NEW.ISTAT_COM,'000')) || ''' AND NVL(ID_SEZC , '' '') = ''' || UPPER(:NEW.SEZIONE) || '''';
    EXECUTE IMMEDIATE STMT INTO CODICE_LETTO;
    IF CODICE_LETTO IS NOT NULL THEN
      :NEW.COD_NAZIONALE := CODICE_LETTO;
    END IF;
  ELSE
    IF :NEW.ISTAT_PROV IS NULL THEN
      STMT := 'SELECT TO_NUMBER(ISTATP),TO_NUMBER(ISTATC),Decode(ID_SEZC,NULL,'' '',ID_SEZC) FROM SITICOMU WHERE COD_NAZIONALE=''' || :NEW.COD_NAZIONALE || '''';
      EXECUTE IMMEDIATE STMT INTO IP,IC,SS;
      IF IP IS NOT NULL THEN
        :NEW.ISTAT_PROV := IP;
        :NEW.ISTAT_COM := IC;
        :NEW.SEZIONE := SS;
      END IF;
    END IF;
  END IF;
END;
/


