CREATE OR REPLACE TRIGGER SITI_H501.AN_SOGGETTI_TAGS_TIB
BEFORE INSERT
ON SITI_H501.AN_SOGGETTI_TAGS
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
DECLARE

BEGIN
    if :new.ID is null then
        SELECT AN_SOGGETTI_TAGS_SEQ.NEXTVAL INTO :new.ID  FROM dual;
    end if;
END AN_SOGGETTI_TAGS_TIB;
/


CREATE OR REPLACE TRIGGER SITI_H501.CENTRIRESP_CHECK_TIB
BEFORE INSERT
ON SITI_H501.CENTRIRESP
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
DECLARE
  existing_tipo                 VARCHAR (1) := NULL;
  check_enabled                 VARCHAR (2) := 'SI';
BEGIN
  -- verifico se esiste un oggetto padre o figlio all'interno dei centri di responsabilitï¿½
  BEGIN
    SELECT NVL (valore, 'SI')
      INTO check_enabled
      FROM gisparams
     WHERE variabile = 'PATRI_SETTORI_CHECK';
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      check_enabled := 'SI';
  END;

  IF check_enabled = 'SI' THEN
    BEGIN
      SELECT DISTINCT obj.tipo
                 INTO existing_tipo
                 FROM
                      /* AGGREGATI */
                      (SELECT   a.id_cata_topo AS id_object,
                                'A' AS tipo,
                                b.cod_nazionale,
                                b.foglio,
                                b.particella,
                                b.sub,
                                -1 AS unimm,
                                -1 AS vano,
                                MIN (b.data_inizio_val) AS data_inizio_val,
                                MAX (b.data_fine_val) AS data_fine_val
                           FROM aggr_topo a, aggr_part b
                          WHERE a.aggr_code = b.aggr_code AND a.pkid_topo = b.pkid_topo
                       GROUP BY a.id_cata_topo, b.cod_nazionale, b.foglio, b.particella, b.sub
                       /* PARTICELLE */
                       UNION
                       SELECT   id_particella AS id_object,
                                'P' AS tipo,
                                cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                -1 AS unimm,
                                -1 AS vano,
                                MIN (data_aggi) AS data_inizio_val,
                                MAX (data_fine) AS data_fine_val
                           FROM sititrkc
                       GROUP BY id_particella, cod_nazionale, foglio, particella, sub
                       /* UIU */
                       UNION
                       SELECT   id_cata_uiu AS id_object,
                                'U' AS tipo,
                                cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm,
                                -1 AS vano,
                                MIN (data_inizio_val) AS data_inizio_val,
                                MAX (data_fine_val) AS data_fine_val
                           FROM sitiuiu
                       GROUP BY id_cata_uiu, cod_nazionale, foglio, particella, sub, unimm
                       /* VANI*/
                       UNION
                       SELECT   id_cata_vano AS id_object,
                                'V' AS tipo,
                                cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm,
                                -1 AS vano,
                                MIN (data_inizio_val) AS data_inizio_val,
                                MAX (data_fine_val) AS data_fine_val
                           FROM sitiedi_vani
                       GROUP BY id_cata_vano, cod_nazionale, foglio, particella, sub, unimm, vano) obj,
                      --centriresp cr,
							 (SELECT * FROM centriresp WHERE FK_OBJECT <> :NEW.fk_object AND TIPO <> :NEW.tipo AND DATA_INIZIO_VAL <> :NEW.data_inizio_val AND DATA_FINE_VAL <> :NEW.data_fine_val) cr,
                      -- ricerco i dati catastali in base al tipo e all'id dell'oggetto
                      (SELECT DISTINCT cod_nazionale,
                                       foglio,
                                       particella,
                                       sub,
                                       unimm,
                                       vano
                                  FROM (
                                        /* AGGREGATI */
                                        SELECT DISTINCT b.cod_nazionale,
                                                        b.foglio,
                                                        b.particella,
                                                        b.sub,
                                                        -1 AS unimm,
                                                        -1 AS vano
                                                   FROM aggr_topo a, aggr_part b
                                                  WHERE a.aggr_code = b.aggr_code AND a.pkid_topo = b.pkid_topo
                                                        AND a.id_cata_topo = :NEW.fk_object AND 'A' = :NEW.tipo
                                        UNION
                                        /* PARTICELLE */
                                        SELECT DISTINCT cod_nazionale,
                                                        foglio,
                                                        particella,
                                                        sub,
                                                        -1 AS unimm,
                                                        -1 AS vano
                                                   FROM sititrkc
                                                  WHERE id_particella = :NEW.fk_object AND 'P' = :NEW.tipo
                                        UNION
                                        /* UIU */
                                        SELECT DISTINCT cod_nazionale,
                                                        foglio,
                                                        particella,
                                                        sub,
                                                        unimm,
                                                        -1 AS vano
                                                   FROM sitiuiu
                                                  WHERE id_cata_uiu = :NEW.fk_object AND 'U' = :NEW.tipo
                                        UNION
                                        /* VANI*/
                                        SELECT DISTINCT cod_nazionale,
                                                        foglio,
                                                        particella,
                                                        sub,
                                                        unimm,
                                                        vano
                                                   FROM sitiedi_vani
                                                  WHERE id_cata_vano = :NEW.fk_object AND 'V' = :NEW.tipo)) o
                WHERE obj.cod_nazionale = o.cod_nazionale
        AND obj.foglio = o.foglio
      AND obj.particella = o.particella
                  AND obj.sub = o.sub
                  AND obj.unimm =
                       CASE
                         WHEN (obj.tipo = 'U' OR obj.tipo = 'V') AND (:NEW.tipo = 'U' OR :NEW.tipo = 'V') THEN o.unimm
         ELSE obj.unimm
                       END
      AND obj.vano =
        CASE
                         WHEN obj.tipo = 'V' AND :NEW.tipo = 'V' THEN o.vano
                         ELSE obj.vano
                       END
                  AND cr.data_inizio_val <= :NEW.data_fine_val
                  AND cr.data_fine_val >= :NEW.data_inizio_val
       AND obj.id_object = cr.fk_object
                  AND obj.tipo = cr.tipo
      AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        existing_tipo := NULL;
    END;

    IF existing_tipo = 'A' THEN
      raise_application_error (-20001, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati all'' aggregato ');
    ELSIF existing_tipo = 'P' THEN
      raise_application_error (-20002, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati alla particella ');
    ELSIF existing_tipo = 'U' THEN
      raise_application_error (-20003, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati all'' unitï¿½ immobiliare ');
    ELSIF existing_tipo = 'V' THEN
      raise_application_error (-20004, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati ad uno o piï¿½ vani ');
    ELSIF existing_tipo IS NOT NULL THEN
      raise_application_error (-20005, 'Esistono giï¿½ dei centri di responsabilitï¿½ associati ad altri oggetti ');
    END IF;
  END IF;
END;
/


CREATE OR REPLACE TRIGGER SITI_H501.IMPO_SITIEDI_VANI BEFORE INSERT ON SITI_H501.IMPO_SITIEDI_VANI
FOR EACH row
/*
a.caleffi 2009-12-17

processa l'inserimento del record nella tabella impo_sitiedi_vani inserendo il record nella tabella
sitiedi_vani previa convalida dei dati di input
*/
DECLARE
  strFldCod_nazionale VARCHAR2(4);
  iFldEdificio NUMBER(5);
  iTempValue NUMBER(5);
  iFldVano NUMBER(5);

  CURSOR curFindUiuExt(pi_strCodNazionale VARCHAR2, pi_iFoglio NUMBER, pi_strParticella VARCHAR2
    , pi_strSub VARCHAR2, pi_iUnimm NUMBER, pi_dtDataInizioVal DATE) is
  SELECT fk_tipologia
  FROM sitiedi_uiu_ext
  WHERE cod_nazionale = pi_strCodNazionale
  AND foglio = pi_iFoglio
  AND particella = pi_strParticella
  AND sub = pi_strSub
  AND unimm = pi_iUnimm
  AND pi_dtDataInizioVal BETWEEN data_inizio_val AND data_fine_val;

  iFld_fk_tipologia NUMBER(9);

BEGIN

  :NEW.piano := Upper(:NEW.piano);
  :NEW.nome_vano := upper(:NEW.nome_vano);

  ---------------------------------------
  -- cerco il codice nazionale del comune
  ---------------------------------------
  SELECT getcodnaz(:NEW.istatp, :NEW.istatc, :NEW.id_sezc)
  INTO strFldCod_nazionale
  FROM dual;

  IF (strFldCod_nazionale IS NULL) THEN
    RAISE_APPLICATION_ERROR(-20001, '(1) Errore. Codice nazionale comune non trovato istatp=[' || :NEW.istatp || '] istatc=[' || :NEW.istatc || '] id_sezc=[' || :NEW.id_sezc || ']');
  END IF;


  -------------------------------------
  -- cerco il valore del campo edificio
  -------------------------------------
  SELECT impo_sitiedi_findEdificio(:NEW.codice_edificio, :NEW.data_inizio_val)
  INTO iFldEdificio
  FROM dual;

  IF (0 = iFldEdificio) THEN
    RAISE_APPLICATION_ERROR(-20001, '(2) Errore. Codice edificio [' || :NEW.codice_edificio || '] non trovato.');
  END IF;

  -- controllo il valore del campo sub
  IF ((:NEW.sub IS NULL) or (:NEW.sub = '')) THEN
    :NEW.sub := ' ';
  END IF;

  --------------------------
  -- controllo esistenza UIU
  --------------------------
  SELECT Count(*)
  INTO iTempValue
  FROM sitiuiu
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND unimm = :NEW.unimm
  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;

  IF (0 = iTempValue) THEN
    RAISE_APPLICATION_ERROR(-20001, '(3) Errore. UIU non trovata, istatp=[' || :NEW.istatp || ']'
      || ' istatc=[' || :NEW.istatc || ']'
      || ' id_sezc=[' || :NEW.id_sezc || ']'
      || ' foglio=[' || :NEW.foglio || ']'
      || ' particella=[' || :NEW.particella || ']'
      || ' sub=[' || :NEW.sub || ']'
      || ' unimm=[' || :NEW.unimm || ']'
      || ' data_inizio_val=[' || :NEW.data_inizio_val || ']');
  END if;

  ---------------------
  -- controllo AMBIENTE
  ---------------------

  -- cerco la tipologia in base al record della tabella SITIEDI_UIU_EXT
  OPEN curFindUiuExt(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, :NEW.unimm, :NEW.data_inizio_val);

  FETCH curFindUiuExt INTO iFld_fk_tipologia;

  IF (curFindUiuExt%NOTFOUND) THEN
    RAISE_APPLICATION_ERROR(-20001, '(4) Errore. UIU non trovata in tabella SITIEDI_UIU_EXT.istatp=[' || :NEW.istatp || ']'
        || ' istatc=[' || :NEW.istatc || ']'
        || ' id_sezc=[' || :NEW.id_sezc || ']'
        || ' foglio=[' || :NEW.foglio || ']'
        || ' particella=[' || :NEW.particella || ']'
        || ' sub=[' || :NEW.sub || ']'
        || ' unimm=[' || :NEW.unimm || ']'
        || ' data_inizio_val=[' || :NEW.data_inizio_val || ']');
  END IF;


  SELECT Count(*)
  INTO iTempValue
  FROM sitiedi_supe_codes
  WHERE fk_tipologia = iFld_fk_tipologia
  AND internal_code = :NEW.ambiente;

  IF (0 = iTempValue)THEN
    RAISE_APPLICATION_ERROR(-20001, '(5) Errore. Valore Ambiente=[' || :NEW.ambiente || '] non trovato in tabella SITIEDI_SUPE_CODES con'
      || ' fk_tipologia=[' || iFld_fk_tipologia || ']');
  END IF;

  --------------------------
  -- controllo esistenza Piano
  --------------------------

  SELECT Count(*)
  INTO iTempValue
  FROM sitiedi_piani
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND piano = :NEW.piano
  AND edificio = iFldEdificio
  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;

  IF (0 = iTempValue) THEN
    RAISE_APPLICATION_ERROR(-20001, '(6) Errore. Piano [' || :NEW.piano ||'] non trovato');
  END IF;


  --------------------------------------
  -- calcolo il numero del prossimo vano
  --------------------------------------
  SELECT Count(*) +1
  INTO iFldVano
  FROM sitiedi_vani
  WHERE cod_nazionale = strFldCod_nazionale
  AND foglio = :NEW.foglio
  AND particella = :NEW.particella
  AND sub = :NEW.sub
  AND unimm = :NEW.unimm;
--  AND :NEW.data_inizio_val BETWEEN data_inizio_val AND data_fine_val;


  -------------------
  -- inserisco record
  -------------------

  INSERT INTO sitiedi_vani(cod_nazionale, foglio, particella
    , sub, unimm
    , edificio, piano, vano
    , data_inizio_val, data_fine_val, data_lav
    , utente, nome_vano
    , ambiente, supe_ambiente
    , altezzamin, altezzamax
    , volume, perimetro)

  VALUES(strFldCod_nazionale, :NEW.foglio, :NEW.particella
    , :NEW.sub, :NEW.unimm
    , iFldEdificio, :NEW.piano, iFldVano
    , :NEW.data_inizio_val, :NEW.data_fine_val, :NEW.data_inizio_val
    , :NEW.utente, :NEW.nome_vano
    , :NEW.ambiente, :NEW.supe_ambiente
    , :NEW.altezzamin, :NEW.altezzamax
    , :NEW.volume, :NEW.perimetro);

END;
/


CREATE OR REPLACE TRIGGER SITI_H501.LOADICI_FABBRICATI_TIB
   BEFORE INSERT
   ON SITI_H501.LOADICI_FABBRICATI
   FOR EACH ROW
DECLARE
BEGIN
  IF :NEW.PKID IS NULL
    THEN
      SELECT LOADICI_FABBRICATI_SEQ.NEXTVAL
      INTO :NEW.PKID
      FROM DUAL;
    END IF;
END LOADICI_FABBRICATI_TIB;
