COMMENT ON COLUMN SITI_H501.CATA_FOGL.FOGLIO IS 'numero del foglio';

COMMENT ON COLUMN SITI_H501.CATA_FOGL.INIZIO IS 'data inizio validita';

COMMENT ON COLUMN SITI_H501.CATA_FOGL.FINE IS 'data fine validita';

COMMENT ON COLUMN SITI_H501.CATA_FOGL.FLAG_STATO IS 'STATO DEL FOGLIO: 0 = FOGLIO ORDINARIO; 1 = FOGLIO NON DISPONIBILE;2 = FOGLIO RISERVATO';


CREATE UNIQUE INDEX SITI_H501.CATA_FOGL_PK ON SITI_H501.CATA_FOGL
(ID_FOGLIO)
LOGGING
TABLESPACE GIT
PCTFREE    10
INITRANS   2
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           );
CREATE UNIQUE INDEX SITI_H501.CATA_FOGL_UK ON SITI_H501.CATA_FOGL
(ID_SEZIONE, FOGLIO)
LOGGING
TABLESPACE GIT
PCTFREE    10
INITRANS   2
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           );

ALTER TABLE SITI_H501.CATA_FOGL ADD (
  CONSTRAINT CATA_FOGL_PK
  PRIMARY KEY
  (ID_FOGLIO)
  USING INDEX SITI_H501.CATA_FOGL_PK
  ENABLE VALIDATE);


