DROP TRIGGER DIOGENE_H501.TRI_PREGEO_FORNITURE;

CREATE OR REPLACE TRIGGER DIOGENE_H501.TRI_PREGEO_FORNITURE
BEFORE INSERT
ON DIOGENE_H501.PREGEO_FORNITURE 
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
DECLARE
tmpVar NUMBER;

BEGIN
   tmpVar := 0;

   SELECT SEQ_PREGEO.NEXTVAL INTO tmpVar FROM dual;
   :NEW.ID_FOR := tmpVar;

   EXCEPTION
     WHEN OTHERS THEN
       -- Consider logging the error and then re-raise
       RAISE;
END ;
/


