DROP TRIGGER RE_ROMA.SEQ_AB_NORMAL_T;

CREATE OR REPLACE TRIGGER RE_ROMA.SEQ_AB_NORMAL_T
BEFORE INSERT
ON RE_ROMA.R_AB_NORMAL
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
declare
    integrity_error  exception;
    errno            integer;
    errmsg           char(200);
    dummy            integer;
    found            boolean;

    TABNAME  VARCHAR2(100);
    SEQ_NAME VARCHAR2(100);
    RET NUMBER;

begin

    TABNAME := 'R_AB_NORMAL';
    UTIL.SEQUENCE_MAN(TABNAME, :NEW.ID, RET);
    :NEW.ID := RET;

exception
    when integrity_error then
       raise_application_error(errno, errmsg);
end;
/

