DROP SEQUENCE CS_ROMA.SQ_CODICE_CS;

CREATE SEQUENCE CS_ROMA.SQ_CODICE_CS
  START WITH 18258
  MAXVALUE 9999999999999999999999999999
  MINVALUE 1
  NOCYCLE
  NOCACHE
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER CS_ROMA.TRIGGER_SQ_CS
BEFORE INSERT ON CS_ROMA.CS_A_CASO
FOR EACH ROW
BEGIN
    IF :new.IDENTIFICATIVO IS NULL THEN
        SELECT SQ_CODICE_CS.nextval INTO :new.IDENTIFICATIVO FROM DUAL;
    END IF;
END;
/


