DROP TABLE CS_ROMA.CS_A_ANAGRAFICA CASCADE CONSTRAINTS;

CREATE TABLE CS_ROMA.CS_A_ANAGRAFICA
(
  ID                      NUMBER(10),
  COGNOME                 VARCHAR2(100 BYTE),
  NOME                    NVARCHAR2(100),
  DATA_NASCITA            DATE,
  CF                      VARCHAR2(34 BYTE),
  PROV_NASCITA_COD        VARCHAR2(4 BYTE),
  COMUNE_NASCITA_COD      VARCHAR2(100 BYTE),
  COMUNE_NASCITA_DES      VARCHAR2(255 BYTE),
  STATO_NASCITA_COD       VARCHAR2(30 BYTE),
  STATO_NASCITA_DES       VARCHAR2(255 BYTE),
  SESSO                   VARCHAR2(1 BYTE),
  CITTADINANZA            VARCHAR2(255 BYTE),
  DATA_DECESSO            DATE,
  TEL                     VARCHAR2(50 BYTE),
  CELL                    VARCHAR2(50 BYTE),
  EMAIL                   VARCHAR2(100 BYTE),
  NOTE                    VARCHAR2(4000 BYTE),
  CITTADINANZA_ACQ        NUMBER,
  CITTADINANZA_2          VARCHAR2(100 BYTE),
  DATA_APERTURA_FASC_FAM  DATE,
  TIT_TELEFONO            VARCHAR2(200 BYTE),
  TIT_CELLULARE           VARCHAR2(200 BYTE),
  TIT_EMAIL               VARCHAR2(200 BYTE),
  ID_ORIG_WS              VARCHAR2(50 BYTE)
)
