CREATE TABLE CS_ROMA.CS_D_COLLOQUIO
(
  DIARIO_ID            NUMBER(10),
  DIARIO_CONCHI_ID     NUMBER(10),
  TESTO_DIARIO         CLOB,
  DIARIO_DOVE_ID       NUMBER(10),
  TIPO_COLLOQUIO_ID    NUMBER(10),
  RISERVATO            VARCHAR2(1 BYTE)         DEFAULT 0,
  DIARIO_CONCHI_ALTRO  VARCHAR2(100 CHAR)
)
LOB (TESTO_DIARIO) STORE AS BASICFILE (
  TABLESPACE  GIT
  ENABLE      STORAGE IN ROW
  CHUNK       8192
  RETENTION
  NOCACHE
  LOGGING
  STORAGE    (
              INITIAL          64K
              NEXT             1M
              MINEXTENTS       1
              MAXEXTENTS       UNLIMITED
              PCTINCREASE      0
              BUFFER_POOL      DEFAULT
             ))
TABLESPACE GIT
PCTUSED    0
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE;


