DROP SEQUENCE DIOGENE_H501.SEQ_PREGEO;

CREATE SEQUENCE DIOGENE_H501.SEQ_PREGEO
  START WITH 21
  MAXVALUE 9999999999999999999999999999
  MINVALUE 1
  NOCYCLE
  NOCACHE
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER DIOGENE_H501.TRI_PREGEO_FORNITURE
BEFORE INSERT
ON DIOGENE_H501.PREGEO_FORNITURE 
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
DECLARE
tmpVar NUMBER;

BEGIN
   tmpVar := 0;

   SELECT SEQ_PREGEO.NEXTVAL INTO tmpVar FROM dual;
   :NEW.ID_FOR := tmpVar;

   EXCEPTION
     WHEN OTHERS THEN
       -- Consider logging the error and then re-raise
       RAISE;
END ;
/


CREATE OR REPLACE TRIGGER DIOGENE_H501.TRI_PREGEO_INFO
BEFORE INSERT
ON DIOGENE_H501.PREGEO_INFO 
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
DECLARE
tmpVar NUMBER;

BEGIN
   tmpVar := 0;

   SELECT SEQ_PREGEO.NEXTVAL INTO tmpVar FROM dual;
   :NEW.ID_INFO := tmpVar;
   

   EXCEPTION
     WHEN OTHERS THEN
       -- Consider logging the error and then re-raise
       RAISE;
END TRI_PREGEO_INFO;
/


