DROP TABLE AM_ROMA.AM_APPLICATION CASCADE CONSTRAINTS;

CREATE TABLE AM_ROMA.AM_APPLICATION
(
  NAME             VARCHAR2(64 BYTE),
  APP_TYPE         VARCHAR2(1024 BYTE),
  APP_CATEGORY     VARCHAR2(1024 BYTE),
  FLG_DATA_ROUTER  VARCHAR2(1 BYTE)
)
TABLESPACE GIT
PCTUSED    0
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE;


CREATE UNIQUE INDEX AM_ROMA.PK_AM_APPLICATION ON AM_ROMA.AM_APPLICATION
(NAME)
LOGGING
TABLESPACE GIT
PCTFREE    10
INITRANS   2
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           );

ALTER TABLE AM_ROMA.AM_APPLICATION ADD (
  CONSTRAINT PK_AM_APPLICATION
  PRIMARY KEY
  (NAME)
  USING INDEX AM_ROMA.PK_AM_APPLICATION
  ENABLE VALIDATE);


DROP TABLE AM_ROMA.AM_AUDIT CASCADE CONSTRAINTS;

CREATE TABLE AM_ROMA.AM_AUDIT
(
  ID           NUMBER,
  DATA_INS     DATE,
  METHOD_NAME  VARCHAR2(200 BYTE),
  USER_ID      VARCHAR2(50 BYTE),
  ENTE_ID      VARCHAR2(10 BYTE),
  EXCEPTION    VARCHAR2(4000 BYTE),
  CLASS_NAME   VARCHAR2(4000 BYTE),
  SESSION_ID   VARCHAR2(200 BYTE),
  ARGS         CLOB,
  RESULT       CLOB,
  CHIAVE       VARCHAR2(200 BYTE),
  DESCRIZIONE  VARCHAR2(2000 BYTE)
)
LOB (ARGS) STORE AS BASICFILE (
  TABLESPACE  GIT
  ENABLE      STORAGE IN ROW
  CHUNK       8192
  RETENTION
  NOCACHE
  LOGGING
  STORAGE    (
              INITIAL          64K
              NEXT             1M
              MINEXTENTS       1
              MAXEXTENTS       UNLIMITED
              PCTINCREASE      0
              BUFFER_POOL      DEFAULT
             ))
LOB (RESULT) STORE AS BASICFILE (
  TABLESPACE  GIT
  ENABLE      STORAGE IN ROW
  CHUNK       8192
  RETENTION
  NOCACHE
  LOGGING
  STORAGE    (
              INITIAL          64K
              NEXT             1M
              MINEXTENTS       1
              MAXEXTENTS       UNLIMITED
              PCTINCREASE      0
              BUFFER_POOL      DEFAULT
             ))
TABLESPACE GIT
PCTUSED    0
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE;


CREATE UNIQUE INDEX AM_ROMA.PK_AM_AUDIT ON AM_ROMA.AM_AUDIT
(ID)
LOGGING
TABLESPACE GIT
PCTFREE    10
INITRANS   2
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           );

ALTER TABLE AM_ROMA.AM_AUDIT ADD (
