DROP PACKAGE SITI_H501.CONSIP_PCK;

CREATE OR REPLACE PACKAGE SITI_H501.consip_pck IS
  /*
  a.caleffi 2010-03-23 dato il codice univoco della UIU e la data di validita'
  ritorna delle informazioni indentificate dal parametro "pi_what" dalla tabella AGGR_TOPO
  Le query partono dalla tabella SITIUIU_LOC --> AGGR_LOCALIZZA e poi --> AGGR_TOPO
  prendendo di ciascuna il primo record, per avere un unico valore.

  In base al valore di pi_what, viene ritornare una info differente:

  1 : nome (indirizzo)
  2 : numero (numero civico)
  3 : cap (cap della via)


  Usato nei report CONSIP
  */
  FUNCTION get_aggr_topo_pkid_uiu (pi_pkid_uiu NUMBER, pi_date DATE, pi_what INT)
    RETURN VARCHAR2;

  /*
  a.caleffi 2010-03-23 dato il codice della classe della uiu ritorna la transcodifica per la
  destinazione d'uso

  Usato nei report CONSIP

  */
  FUNCTION get_destinazione_uso (pi_categoria VARCHAR2)
    RETURN NUMBER;

  /*
  a.caleffi 2010-03-24 dato il codice nazionale ritorna il primo cap utile dalla tabella aggr_topo


  Usato nei report CONSIP
  */
  FUNCTION get_aggr_topo_cap (pi_str_cod_naz VARCHAR2)
    RETURN VARCHAR2;
END consip_pck;
/


