DROP PACKAGE SITI_H501.LOAD_CATASTO;

CREATE OR REPLACE PACKAGE SITI_H501.load_catasto AUTHID CURRENT_USER AS
/*
2012-11-07 a.caleffi cambiata load_uiu_tit, load_part_tit
2011-10-20 a.caleffi cambiata load_soggetti
*/

  LOADER_USR cons_azie_tab.utente%type := 'LOADER';

  -- Titolarita particelle create automaticamente --
  procedure spalma_titolarita_part(cod_naz in varchar2 default null);

  function merge_civ(civ1 varchar2, civ2 varchar2, civ3 varchar2) return varchar2;

	/*
	Carica i soggetti
	2011-10-20 a.caleffi
	il soggetto viene storicizzato in base a codice fiscale/partita iva e	descrizione.
	*/
  function load_soggetti return pls_integer;

  -- Carica le particelle --
  function load_part return pls_integer;

  -- Carica le porzioni delle particelle --
  function load_part_por return pls_integer;

  /*
	Carica i titolari delle particelle

	2012-11-07 a.caleffi cambiata ricerca del soggetto
	*/

  function load_part_tit return pls_integer;

  -- Carica le uiu --
  function load_uiu return pls_integer;

  -- Carica i graffati alle UIU --
  function load_uiu_graf return pls_integer;

  -- Carica le utilita' comuni delle UIU --
  function load_uiu_util return pls_integer;

  /* Carica gli indirizzi delle UIU, se il parametro
   * createStreetIfNeeded e uguale a 'Y' allora una eventuale
   * strada non trovata in siti viene automaticamente
   * creata = a quella del catasto.
   * Stessa cosa vale per il parametro createCivIfNeeded applicato ai
   * civici.
   *
   * Codici di errore loggati in load_cat_uiu_ind.error_code:
   *  -20001 Se non c'e la strada e non la deve creare
   *  -20002 Se il civico e nullo
   *  -20003 Se non trova il civico e non lo deve creare
   */
  function load_uiu_ind(createStreetIfNeeded char default 'N',
                        createCivIfNeeded char default 'N')
  return pls_integer;

	/*
	 Carica le titolarita delle UIU --
	 2012-11-07 a.caleffi cambiata ricerca del soggetto
	*/
  function load_uiu_tit return pls_integer;

END load_catasto;
/


