DROP PACKAGE SITI_H501.PARTICELLA;

CREATE OR REPLACE PACKAGE SITI_H501.particella AS

	-- Controlla se una particella ha delle unar alla data specificata
  -- 0 = Nessuna unar
  -- 1 = Presenza di unar
  FUNCTION has_unar(codNaz varchar2, fg number, part varchar2, suba varchar2, dataCheck date) RETURN NUMBER;


	-- Controlla se una particella esiste in catasto
  -- 0 = No
  -- 1 = Scaduto
  -- 2 = Si
  FUNCTION stato_cat(codNaz varchar2, fg number, part varchar2, suba varchar2, dataCheck date) RETURN NUMBER;

	-- Controlla se lo stato del catasto è validato
  -- 0 = No
  -- 1 = Si
  function cat_validato(codNaz varchar2, fg number, part varchar2, suba varchar2, dataCheck date) RETURN NUMBER;

	-- Controlla se una particella ha delle UIU in catasto
  -- 0 = No
  -- 1 = Si
  FUNCTION has_uiu_cat(codNaz varchar2, fg number, part varchar2, suba varchar2, dataCheck date) RETURN NUMBER;

 	-- Controlla lo stato di 1 particella in 1 elenco di lavorazione
  -- 0 = Non in elenco
  -- 1 = In elenco ma non lavorato
  -- 2 = In elenco e lavorato
  FUNCTION stato_lav(codNaz varchar2, fg number, part varchar2, suba varchar2, idlav number) RETURN NUMBER;

  FUNCTION get_conduttori(codnaz varchar2, fg number, part varchar2, suba varchar2, datacheck date, separatore varchar2) RETURN VARCHAR2;

END particella;

/


