  canone_concordato    CONSTANT CHAR (1) := '5';                                                   -- Canone concordato
  canone_conc_libero   CONSTANT CHAR (1) := '6';                                                  -- Concessione libera
  canone_conc_superfici CONSTANT CHAR (1) := '7';                                          -- Concessione di superficie
  canone_conc_imbottiglia CONSTANT CHAR (1) := '8';                                  -- Concessione di imbottigliamento

