DROP PACKAGE SITI_H501.TITOLI_PCK;

CREATE OR REPLACE PACKAGE SITI_H501.titoli_pck AS



  -- Ritorna il catalog_id dell'oggetto
  FUNCTION get_obj_id (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
  p_vano            NUMBER DEFAULT NULL
  )
    RETURN NUMBER;

  -- Ritorna il tipo di oggetto ('P'= particella, 'U'=uiu, 'V'=vano)
  FUNCTION get_obj_type (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
  p_vano            NUMBER DEFAULT NULL
  )
    RETURN VARCHAR;

  -- Ritorna la pk_cuaa di conduzione associata all'atto di titolaritï¿½
  -- (se ne esiste + di una prende quella associata alla titolaritï¿½ con data_fine maggiore)
  FUNCTION get_pkcuaa_cond (
    p_atto            NUMBER,
  p_date            DATE DEFAULT NULL,
  p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN number;

  -- Ritorna la pk_cuaa di SUBconduzione associata all'atto di titolaritï¿½
  -- (se ne esiste + di una prende quella associata alla titolaritï¿½ con data_fine maggiore)
  FUNCTION get_pkcuaa_subcond (
    p_atto            NUMBER,
  p_date            DATE DEFAULT NULL,
  p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN number;

  -- Ritorna la pk_cuaa di SUBconduzione associata all'atto di titolaritï¿½
  -- (se ne esiste + di una prende quella associata alla titolaritï¿½ con data_fine maggiore)
  FUNCTION get_pkcuaa_subcond_byid (
    p_atto            NUMBER,
  p_date            DATE DEFAULT NULL,
  p_obj_type                           VARCHAR2,
    p_obj_id                             NUMBER
  )
    RETURN number;

  -- Ritorna la data minima di conduzione associata all'atto di titolaritï¿½
  FUNCTION get_min_date_cond (
    p_atto            NUMBER,
  p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN date;

  -- Ritorna la data massima di fine conduzione associata all'atto di titolaritï¿½
  FUNCTION get_max_date_cond (
    p_atto                       NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
  RETURN DATE;

  -- Ritorna la data minima di SUBconduzione associata all'atto di titolaritï¿½
  FUNCTION get_min_date_subcond (
    p_atto            NUMBER,
  p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN date;

  -- Ritorna la data minima di SUBconduzione associata all'atto di titolaritï¿½
  FUNCTION get_min_date_subcond_byid (
    p_atto            NUMBER,
  p_obj_type                           VARCHAR2,
    p_obj_id                             NUMBER
  )
    RETURN date;

  -- funxione che restituisce 1 se il tipo di titolo ï¿½ di proprietï¿½ altrimenti 0
  FUNCTION is_titolo_proprieta (tipo_titolo VARCHAR2)
    RETURN NUMBER;

  -- RITORNA LA SUPERFICIE DELLA UIU AD UNA CERTA DATA
  FUNCTION get_superficie_uiu (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
    p_dt                                 DATE
  )
    RETURN NUMBER;

  -- RITORNA LA SUPERFICIE DELLA PARTICELLA AD UNA CERTA DATA
  FUNCTION get_superficie_part (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_dt                                 DATE
  )
    RETURN NUMBER;

  FUNCTION perc_prop_part (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER;

  FUNCTION perc_altro_tit_part (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER;

  FUNCTION perc_prop_uiu (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER;

  FUNCTION perc_altro_tit_uiu (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER;

  FUNCTION is_totale_altro_tit_uiu (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER, dt DATE
        DEFAULT SYSDATE)
    RETURN VARCHAR2;

  -- calcola la superficie locata di una particella
  FUNCTION sup_part_altro_tit (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
  p_date            DATE DEFAULT null
  )
    RETURN NUMBER;

  -- calcola la superficie locata di una uiu
  FUNCTION sup_uiu_altro_tit (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
  p_date              DATE DEFAULT null
  )
    RETURN NUMBER;

  -- calcola la percentuale locata di una uiu / particella (se unimm ï¿½ null allora ï¿½ una particella)
  FUNCTION get_perc_locata (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
  p_date              DATE DEFAULT null
  )
    RETURN NUMBER;

  -- LOCAZIONI - applica il fattore di locazione multipla sulla superficie locata passata come parametro
  FUNCTION apply_multiple_rent (
    p_sup                 NUMBER,
  p_atto                NUMBER,
  p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_date                     DATE DEFAULT null)
    RETURN NUMBER;

  -- SUBLOCAZIONI - applica il fattore di locazione multipla sulla superficie locata passata come parametro
  FUNCTION apply_multiple_rent_subloc (
    p_sup                 NUMBER,
  p_atto                NUMBER,
  p_id_obj           NUMBER,
  p_obj_type           VARCHAR2,
    p_date                     DATE DEFAULT null)
    RETURN NUMBER;

  -- calcola la superficie di un oggetto catastale
  FUNCTION get_sup_obj (p_obj_id NUMBER, p_obj_type VARCHAR2, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER;

  -- calcola la percentuale sublocata di una uiu / particella (se unimm ï¿½ null allora ï¿½ una particella)
  FUNCTION get_sup_sublocata (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER;

  FUNCTION get_sup_sublocata_byid (
    p_obj_id                             NUMBER,
    p_obj_type                           VARCHAR2,
    p_pk_atto                            NUMBER,
    p_pk_cuaa                            NUMBER,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER;

  -- calcola la percentuale sublocata di una uiu / particella (se unimm ï¿½ null allora ï¿½ una particella)
  FUNCTION get_perc_sublocata (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER;

  FUNCTION get_perc_sublocata_byid (
    p_obj_id                             NUMBER,
    p_obj_type                           VARCHAR2,
    p_pk_atto                            NUMBER,
    p_pk_cuaa                            NUMBER,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER;



END titoli_pck;
/


