DROP PACKAGE BODY SITI_H501.ABACO;

CREATE OR REPLACE PACKAGE BODY SITI_H501.abaco AS
  FUNCTION GETUTENTEGIS(AUSR IN VARCHAR2, DATO IN VARCHAR2) RETURN VARCHAR2
  IS
    USERNAME VARCHAR2(20);
  BEGIN
    USERNAME := '';
    SELECT USR
    INTO USERNAME
    FROM CONSUSERS WHERE USR=AUSR AND PSW=DATO;
    RETURN USERNAME;

EXCEPTION WHEN No_Data_Found THEN
    IF USERNAME IS NULL THEN USERNAME:='NOT FOUND'; END IF;

    RETURN USERNAME;
  END GETUTENTEGIS;

  FUNCTION GETDATOFROMUSR(COD_UTENTE IN VARCHAR2) RETURN VARCHAR2
  IS
  DATO VARCHAR2(160);
  BEGIN
    SELECT  PSW
    INTO    DATO
    FROM    GISUSERS
    WHERE   USR=COD_UTENTE;

    RETURN DATO;
  END GETDATOFROMUSR;

END ABACO;

/


DROP PACKAGE BODY SITI_H501.ANAGRAFICA;

CREATE OR REPLACE PACKAGE BODY SITI_H501.Anagrafica IS
  FUNCTION stringsdiffers (a VARCHAR2, b VARCHAR2)
    RETURN BOOLEAN IS
  BEGIN
    RETURN (a IS NULL AND b IS NOT NULL) OR (a IS NOT NULL AND b IS NULL) OR (UPPER (a) <> UPPER (b));
  END stringsdiffers;

  /*
   * Controlla se il soggetto e stato modificato.
   */
  FUNCTION controlla_modifiche_soggetto (
    idsoggetto                  IN       NUMBER,
    codfisc                     IN       VARCHAR2,
    cognome                     IN       VARCHAR2,
    nome                        IN       VARCHAR2,
    denominazione               IN       VARCHAR2,
    sesso                       IN       VARCHAR2,
    dnasc                       IN       DATE,
    dcostituzione               IN       DATE,
    dmorte                      IN       DATE,
    codcomunascita              IN       VARCHAR,
    civicoresi                  IN       INTEGER,
    codcomuresi                 IN       VARCHAR2,
    civicorecap                 IN       VARCHAR2,
    codcomurecap                IN       VARCHAR2,
    cap                         IN       VARCHAR2,
    NATURA_GIURIDICA            IN       VARCHAR2,
    flagpersfisica              IN       VARCHAR2,
    partitaiva                  IN       VARCHAR2,
    rapplegale                  IN       NUMBER,
    utente                      IN       VARCHAR2,
    attoini                     IN       NUMBER,
    attofine                    IN       NUMBER,
    pindirizzo_est              IN       VARCHAR2,
    pindirizzo_est_recap        IN       VARCHAR2,
    pcap_recap                  IN       VARCHAR2,
    ptelefono                   IN       VARCHAR2,
    pfax                        IN       VARCHAR2,
    pmail                       IN       VARCHAR2,
    pfl_part_iva                IN       VARCHAR2,
    plocalita                   IN       VARCHAR2,
    cell                                 VARCHAR2 DEFAULT NULL,
    per_rif                              VARCHAR2 DEFAULT NULL
  )
    RETURN NUMBER IS
    cod_sogg                      NUMBER;

    CURSOR sogg IS
      SELECT     *
            FROM ANAG_SOGGETTI
           WHERE pkid = idsoggetto
      FOR UPDATE;

    rowc                          sogg%ROWTYPE;
  BEGIN
    OPEN sogg;

    FETCH sogg
     INTO rowc;

    CLOSE sogg;

    cod_sogg := rowc.cod_soggetto;

    -- Soggetto PI
    IF (rowc.fl_part_iva != pfl_part_iva) OR pfl_part_iva IS NULL THEN
      RETURN cod_sogg;
    END IF;

    -- codice fiscale
    IF stringsdiffers (rowc.cod_fiscale, codfisc) THEN
      -- se e persona fisica aggiorna la corrispondenza in CONS_AZIE_TAB
      IF flagpersfisica = 'P' THEN
        aggiorna_consistenza (cod_sogg, codfisc, utente);
      END IF;

      RETURN cod_sogg;
    END IF;

    -- partita iva
    IF stringsdiffers (rowc.part_iva, partitaiva) THEN
      ---if flagPersFisica = 'G' then
         --aggiorna_consistenza(cod_sogg, partitaIva , utente);
      --end if;
      RETURN cod_sogg;
    END IF;

    -- natura giuridica
    IF stringsdiffers (rowc.NATURA_GIURIDICA, NATURA_GIURIDICA) THEN
      RETURN cod_sogg;
    END IF;

    -- cognome
    IF stringsdiffers (rowc.cognome, cognome) THEN
      RETURN cod_sogg;
    END IF;

    -- nome
    IF stringsdiffers (rowc.nome, nome) THEN
      RETURN cod_sogg;
    END IF;

    -- denominazione
    IF stringsdiffers (rowc.denominazione, denominazione) THEN
      RETURN cod_sogg;
    END IF;

    -- sesso
    IF stringsdiffers (rowc.sesso, sesso) THEN
      RETURN cod_sogg;
    END IF;

    -- data di nascita
    IF (rowc.d_nascita IS NULL AND dnasc IS NOT NULL) OR (rowc.d_nascita IS NOT NULL AND dnasc IS NULL)
       OR (rowc.d_nascita <> dnasc) THEN
      RETURN cod_sogg;
    END IF;

    -- data di costituzione
    IF (rowc.d_costituzione IS NULL AND dcostituzione IS NOT NULL) OR (rowc.d_costituzione <> dcostituzione)
       OR (rowc.d_costituzione IS NOT NULL AND dcostituzione IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- data di morte
    IF (rowc.d_morte IS NULL AND dmorte IS NOT NULL) OR (rowc.d_morte <> dmorte)
       OR (rowc.d_morte IS NOT NULL AND dmorte IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- comune di nascita
    IF (rowc.fkcod_comu_nasc IS NULL AND codcomunascita IS NOT NULL) OR (rowc.fkcod_comu_nasc <> codcomunascita)
       OR (rowc.fkcod_comu_nasc IS NOT NULL AND codcomunascita IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- comune di residenza
    IF (rowc.fkcod_comu_resi IS NULL AND codcomuresi IS NOT NULL) OR (rowc.fkcod_comu_resi <> codcomuresi)
       OR (rowc.fkcod_comu_resi IS NOT NULL AND codcomuresi IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- civico di residenza
    IF (rowc.fkcivico_resi IS NULL AND civicoresi IS NOT NULL)
       OR (rowc.fkcivico_resi IS NOT NULL AND civicoresi IS NULL) OR (rowc.fkcivico_resi <> civicoresi) THEN
      RETURN cod_sogg;
    END IF;

    -- civico di residenza
    IF (rowc.cap IS NULL AND cap IS NOT NULL) OR (rowc.cap <> cap) OR (rowc.cap IS NOT NULL AND cap IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- comune di recapito
    IF (rowc.fkcod_comu_recapito IS NULL AND codcomurecap IS NOT NULL) OR (rowc.fkcod_comu_recapito <> codcomurecap)
       OR (rowc.fkcod_comu_recapito IS NOT NULL AND codcomurecap IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- civico di recapito
    IF (rowc.fkcivico_recapito IS NULL AND civicorecap IS NOT NULL) OR (rowc.fkcivico_recapito <> civicorecap)
       OR (rowc.fkcivico_recapito IS NOT NULL AND civicorecap IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- FLAG persona fisica
    IF (rowc.flag_pers_fisica IS NULL AND flagpersfisica IS NOT NULL) OR (rowc.flag_pers_fisica <> flagpersfisica) THEN
      RETURN cod_sogg;
    END IF;

    -- rappresentante legale
    IF (rowc.fkrapp_legale IS NULL AND rapplegale IS NOT NULL) OR (rowc.fkrapp_legale <> rapplegale) THEN
      RETURN cod_sogg;
    END IF;

    -- atto inizio
    IF (rowc.atto_inizio IS NULL AND attoini IS NOT NULL) OR (rowc.atto_inizio <> attoini) THEN
      RETURN cod_sogg;
    END IF;

    -- atto fine
    IF (rowc.atto_fine IS NULL AND attofine IS NOT NULL) OR (rowc.atto_fine <> attofine) THEN
      RETURN cod_sogg;
    END IF;

    -- indirizzo esteso
    IF (rowc.indirizzo_est IS NULL AND pindirizzo_est IS NOT NULL) OR (rowc.indirizzo_est <> pindirizzo_est)
       OR (rowc.indirizzo_est IS NOT NULL AND pindirizzo_est IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- indirizzo esteso recapito
    IF (rowc.indirizzo_est_recap IS NULL AND pindirizzo_est_recap IS NOT NULL)
       OR (rowc.indirizzo_est_recap <> pindirizzo_est_recap)
       OR (rowc.indirizzo_est_recap IS NOT NULL AND pindirizzo_est_recap IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- cap recapito
    IF (rowc.cap_recap IS NULL AND pcap_recap IS NOT NULL) OR (rowc.cap_recap <> pcap_recap)
       OR (rowc.cap_recap IS NOT NULL AND pcap_recap IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- telefono
    IF (rowc.telefono IS NULL AND ptelefono IS NOT NULL) OR (rowc.telefono <> ptelefono)
       OR (rowc.telefono IS NOT NULL AND ptelefono IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- fax
    IF (rowc.fax IS NULL AND pfax IS NOT NULL) OR (rowc.fax <> pfax) OR (rowc.fax IS NOT NULL AND pfax IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- mail
    IF (rowc.mail IS NULL AND pmail IS NOT NULL) OR (rowc.mail <> pmail) OR (rowc.mail IS NOT NULL AND pmail IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    -- localita
    IF stringsdiffers (rowc.localita, plocalita) THEN
      RETURN cod_sogg;
    END IF;

    IF (rowc.cell IS NULL AND cell IS NOT NULL) OR (rowc.cell <> cell) OR (rowc.cell IS NOT NULL AND cell IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    IF (rowc.per_rif IS NULL AND per_rif IS NOT NULL) OR (rowc.per_rif <> per_rif)
       OR (rowc.per_rif IS NOT NULL AND per_rif IS NULL) THEN
      RETURN cod_sogg;
    END IF;

    RETURN 0;
  END controlla_modifiche_soggetto;

  /*
   * Controlla se l' ute e stata modificata
   */
  FUNCTION controlla_modifiche_ute (
    idunita                     IN       NUMBER,
    codice_soggetto             IN       NUMBER,
    tipologia                   IN       VARCHAR2,
    descrizione                 IN       VARCHAR2,
    codice_assss                IN       VARCHAR2,
    telefono                    IN       VARCHAR2,
    fax                         IN       VARCHAR2,
    piva                        IN       VARCHAR2,
    email                       IN       VARCHAR2,
    note                        IN       VARCHAR2,
    civicolocazione             IN       NUMBER,
    codcomulocazione            IN       VARCHAR2,
    cap                         IN       VARCHAR2,
    pscala                      IN       VARCHAR2,
    ppiano                      IN       NUMBER,
    pinterno                    IN       NUMBER,
    pindirizzo_est              IN       VARCHAR2,
    utente                      IN       VARCHAR2
  )
    RETURN NUMBER IS
    CURSOR ute IS
      SELECT     *
            FROM ANAG_UTE
           WHERE pkid_ute = idunita
      FOR UPDATE;

    rowc                          ute%ROWTYPE;
  BEGIN
    OPEN ute;

    FETCH ute
     INTO rowc;

    CLOSE ute;

    -- descrizione
    IF (rowc.tipologia IS NULL AND tipologia IS NOT NULL) OR (rowc.tipologia <> tipologia)
       OR (rowc.tipologia IS NOT NULL AND tipologia IS NULL) THEN
      RETURN 1;
    END IF;

    -- descrizione
    IF (rowc.descrizione IS NULL AND descrizione IS NOT NULL) OR (rowc.descrizione <> descrizione)
       OR (rowc.descrizione IS NOT NULL AND descrizione IS NULL) THEN
      RETURN 1;
    END IF;

      /*

        if (rowc.codice_a_ss_ss is null and codice_assss is not null) or
           (rowc.codice_a_ss_ss <> codice_assss) or
           (rowc.codice_a_ss_ss is not null and codice_assss is null) then
           return 1;
        end if;
    */

    -- piva
    IF (rowc.partita_iva IS NULL AND piva IS NOT NULL) OR (rowc.partita_iva <> piva)
       OR (rowc.partita_iva IS NOT NULL AND piva IS NULL) THEN
      RETURN 1;
    END IF;

    -- telefono
    IF (rowc.telefono IS NULL AND telefono IS NOT NULL) OR (rowc.telefono <> telefono)
       OR (rowc.telefono IS NOT NULL AND telefono IS NULL) THEN
      RETURN 1;
    END IF;

    -- email
    IF (rowc.mail IS NULL AND email IS NOT NULL) OR (rowc.mail <> email) OR (rowc.mail IS NOT NULL AND email IS NULL) THEN
      RETURN 1;
    END IF;

    -- fax
    IF (rowc.fax IS NULL AND fax IS NOT NULL) OR (rowc.fax <> fax) OR (rowc.fax IS NOT NULL AND fax IS NULL) THEN
      RETURN 1;
    END IF;

    -- note
    IF (rowc.note IS NULL AND note IS NOT NULL) OR (rowc.note <> note) OR (rowc.note IS NOT NULL AND note IS NULL) THEN
      RETURN 1;
    END IF;

    -- civico di locazione
    IF (rowc.fkcivico_locazione IS NULL AND civicolocazione IS NOT NULL)
       OR (rowc.fkcivico_locazione <> civicolocazione) THEN
      RETURN 1;
    END IF;

    IF (rowc.fkcod_comu_locazione IS NULL AND codcomulocazione IS NOT NULL)
       OR (rowc.fkcod_comu_locazione <> codcomulocazione) THEN
      RETURN 1;
    END IF;

    IF (rowc.cap IS NULL AND cap IS NOT NULL) OR (rowc.cap <> cap) OR (rowc.cap IS NOT NULL AND cap IS NULL) THEN
      RETURN 1;
    END IF;

    IF (rowc.indirizzo_est IS NULL AND pindirizzo_est IS NOT NULL) OR (rowc.indirizzo_est <> pindirizzo_est)
       OR (rowc.indirizzo_est IS NOT NULL AND pindirizzo_est IS NULL) THEN
      RETURN 1;
    END IF;

    RETURN 0;
  END controlla_modifiche_ute;

  -- Function inserisci soggetto
  --
  --
  FUNCTION inserisci_soggetto (
    p_strictcontrols                     CHAR,
    codfisc                     IN       VARCHAR2,
    cognome                     IN       VARCHAR2,
    nome                        IN       VARCHAR2,
    denominazione               IN       VARCHAR2,
    sesso                       IN       VARCHAR2,
    dnasc                       IN       DATE,
    dcostituzione               IN       DATE,
    dmorte                      IN       DATE,
    codcomunascita              IN       VARCHAR,
    civicoresi                  IN       INTEGER,
    codcomuresi                 IN       VARCHAR2,
    civicorecap                 IN       VARCHAR2,
    codcomurecap                IN       VARCHAR2,
    cap                         IN       VARCHAR2,
    NATURA_GIURIDICA            IN       VARCHAR2,
    flagpersfisica              IN       VARCHAR2,
    partitaiva                  IN       VARCHAR2,
    rapplegale                  IN       NUMBER,
    utente                      IN       VARCHAR2,
    attoini                     IN       NUMBER,
    attofine                    IN       NUMBER,
    pindirizzo_est              IN       VARCHAR2,
    pindirizzo_est_recap        IN       VARCHAR2,
    pcap_recap                  IN       VARCHAR2,
    ptelefono                   IN       VARCHAR2,
    pfax                        IN       VARCHAR2,
    pmail                       IN       VARCHAR2,
    pfl_part_iva                IN       VARCHAR2,
    plocalita                   IN       VARCHAR2,
    cell                                 VARCHAR2 DEFAULT NULL,
    per_rif                              VARCHAR2 DEFAULT NULL,
    tag                                   VARCHAR2 DEFAULT NULL
  )
    RETURN NUMBER IS
    datafine                      DATE := TO_DATE ('99991231', 'yyyymmdd');
    datainizio                    DATE := TRUNC (SYSDATE);
    ID                            NUMBER;
    codice_soggetto               VARCHAR2 (16);
    id_soggetto                   NUMBER;
    strictcontrols                BOOLEAN;
    tagId                       NUMBER;
  BEGIN
    IF (p_strictcontrols IS NULL OR p_strictcontrols = 'Y' OR p_strictcontrols = 'S') THEN
      strictcontrols := TRUE;
    ELSE
      strictcontrols := FALSE;
    END IF;

    validasoggetto (UPPER (codfisc), UPPER (cognome), UPPER (nome), UPPER (denominazione), sesso, dnasc, dmorte,
                    codcomunascita, civicoresi, flagpersfisica, partitaiva, utente, FALSE, strictcontrols);
    codice_soggetto := creacodicesoggetto (codfisc, partitaiva, flagpersfisica);

    SELECT anag_soggetto_seq.NEXTVAL
      INTO ID
      FROM DUAL;

    id_soggetto := inserisci_consistenza (codice_soggetto, utente);

    INSERT INTO ANAG_SOGGETTI
                (pkid,
                 cod_soggetto,
                 cognome,
                 nome,
                 denominazione,
                 sesso,
                 d_nascita,
                 d_costituzione,
                 d_morte,
                 fkcod_comu_nasc,
                 fkcivico_resi,
                 fkcod_comu_resi,
                 fkcivico_recapito,
                 fkcod_comu_recapito,
                 cap,
                 flag_pers_fisica,
                 cod_fiscale,
                 part_iva,
                 NATURA_GIURIDICA,
                 fkrapp_legale,
                 data_inizio_val,
                 data_fine_val,
                 data_lav,
                 utente_inizio,
                 utente_fine,
                 atto_inizio,
                 atto_fine,
                 indirizzo_est,
                 indirizzo_est_recap,
                 cap_recap,
                 telefono,
                 fax,
                 mail,
                 fl_part_iva,
                 localita,
                 cell,
                 per_rif
                )
         VALUES (ID,
                 id_soggetto,
                 UPPER (cognome),
                 UPPER (nome),
                 UPPER (denominazione),
                 sesso,
                 dnasc,
                 dcostituzione,
                 dmorte,
                 codcomunascita,
                 civicoresi,
                 codcomuresi,
                 civicorecap,
                 codcomurecap,
                 cap,
                 flagpersfisica,
                 UPPER (codfisc),
                 partitaiva,
                 NATURA_GIURIDICA,
                 rapplegale,
                 datainizio,
                 datafine,
                 SYSDATE,
                 utente,
                 NULL,
                 attoini,
                 attofine,
                 UPPER (pindirizzo_est),
                 UPPER (pindirizzo_est_recap),
                 pcap_recap,
                 ptelefono,
                 pfax,
                 pmail,
                 pfl_part_iva,
                 UPPER (plocalita),
                 cell,
                 per_rif
                );

                IF tag IS NOT NULL THEN

                    -- the tag exists?
                    BEGIN
                      tagId := null;
                      SELECT ID_TAG INTO tagId FROM an_tags where id_tag = tag;
                    EXCEPTION WHEN NO_DATA_FOUND THEN
                       tagId := null;
                    END;

                    IF tagId IS NOT NULL THEN
                      INSERT INTO AN_SOGGETTI_TAGS (ID, ID_SOGGETTO, ID_TAG, UT_INIZIO, INIZIO, UT_FINE, FINE, LAST_MODIFIED)
                      (select AN_SOGGETTI_TAGS_SEQ.nextval, id_soggetto, tagId, utente, datainizio,  null, datafine, sysdate from dual);
                    END IF;

                END IF;

    RETURN ID;
  END inserisci_soggetto;

  -- function aggiorna soggetto
  --
  --
  FUNCTION aggiorna_soggetto (
    p_strictcontrols                     CHAR,
    idsoggetto                  IN       NUMBER,
    codfisc                     IN       VARCHAR2,
    cognome                     IN       VARCHAR2,
    nome                        IN       VARCHAR2,
    denominazione               IN       VARCHAR2,
    sesso                       IN       VARCHAR2,
    dnasc                       IN       DATE,
    dcostituzione               IN       DATE,
    dmorte                      IN       DATE,
    codcomunascita              IN       VARCHAR,
    civicoresi                  IN       INTEGER,
    codcomuresi                 IN       VARCHAR2,
    civicorecap                 IN       VARCHAR2,
    codcomurecap                IN       VARCHAR2,
    cap                         IN       VARCHAR2,
    NATURA_GIURIDICA            IN       VARCHAR2,
    flagpersfisica              IN       VARCHAR2,
    partitaiva                  IN       VARCHAR2,
    rapplegale                  IN       NUMBER,
    utente                      IN       VARCHAR2,
    attoini                     IN       NUMBER,
    attofine                    IN       NUMBER,
    pindirizzo_est              IN       VARCHAR2,
    pindirizzo_est_recap        IN       VARCHAR2,
    pcap_recap                  IN       VARCHAR2,
    ptelefono                   IN       VARCHAR2,
    pfax                        IN       VARCHAR2,
    pmail                       IN       VARCHAR2,
    pfl_part_iva                IN       VARCHAR2,
    plocalita                   IN       VARCHAR2,
    cell                                 VARCHAR2 DEFAULT NULL,
    per_rif                              VARCHAR2 DEFAULT NULL,
    tag                                   VARCHAR2 DEFAULT NULL
  )
    RETURN NUMBER IS
    datafine                      DATE := TO_DATE ('99991231', 'yyyymmdd');
    datainizio                    DATE := TRUNC (SYSDATE);
    ID                            NUMBER;
    codsoggetto                   NUMBER := 0;
    strictcontrols                BOOLEAN;
    dummy                         NUMBER;
  BEGIN
    IF (p_strictcontrols IS NULL OR p_strictcontrols = 'Y' OR p_strictcontrols = 'S') THEN
      strictcontrols := TRUE;
    ELSE
      strictcontrols := FALSE;
    END IF;

    validasoggetto (codfisc, UPPER (cognome), UPPER (nome), UPPER (denominazione), sesso, dnasc, dmorte, codcomunascita,
                    civicoresi, flagpersfisica, partitaiva, utente, TRUE, strictcontrols);
    codsoggetto :=
      controlla_modifiche_soggetto (idsoggetto, UPPER (codfisc), UPPER (cognome), UPPER (nome), UPPER (denominazione),
                                    sesso, dnasc, dcostituzione, dmorte, codcomunascita, civicoresi, codcomuresi,
                                    civicorecap, codcomurecap, cap, NATURA_GIURIDICA, flagpersfisica, partitaiva,
                                    rapplegale, utente, attoini, attofine, UPPER (pindirizzo_est),
                                    UPPER (pindirizzo_est_recap), pcap_recap, ptelefono, pfax, pmail, pfl_part_iva,
                                    UPPER (plocalita), cell, per_rif);

    IF codsoggetto > 0 THEN
      SELECT COUNT (*)
        INTO dummy
        FROM ANAG_SOGGETTI t
       WHERE t.cod_soggetto = codsoggetto AND t.data_inizio_val = datainizio
             AND t.data_fine_val = TO_DATE ('99991231', 'yyyymmdd');

      /* Dato che il rec. viene inserito con data_inizio_val=trunc(sysdate),
       * non storicizzo le modifiche fatte nello stesso giorno...
       */
      IF (dummy > 0) THEN
        DELETE FROM ANAG_SOGGETTI t
              WHERE t.cod_soggetto = codsoggetto AND t.data_fine_val = TO_DATE ('99991231', 'yyyymmdd');
      ELSE
        UPDATE ANAG_SOGGETTI t
           SET t.data_fine_val = datainizio - (1 / 24 / 60 / 60),
               t.utente_fine = utente
         WHERE t.cod_soggetto = codsoggetto AND t.data_fine_val = TO_DATE ('99991231', 'yyyymmdd');
      END IF;

      SELECT anag_soggetto_seq.NEXTVAL
        INTO ID
        FROM DUAL;

      INSERT INTO ANAG_SOGGETTI
                  (pkid,
                   cod_soggetto,
                   cognome,
                   nome,
                   denominazione,
                   sesso,
                   d_nascita,
                   d_costituzione,
                   d_morte,
                   fkcod_comu_nasc,
                   fkcivico_resi,
                   fkcod_comu_resi,
                   fkcivico_recapito,
                   fkcod_comu_recapito,
                   cap,
                   flag_pers_fisica,
                   cod_fiscale,
                   part_iva,
                   NATURA_GIURIDICA,
                   fkrapp_legale,
                   data_inizio_val,
                   data_fine_val,
                   data_lav,
                   utente_inizio,
                   utente_fine,
                   atto_inizio,
                   atto_fine,
                   indirizzo_est,
                   indirizzo_est_recap,
                   cap_recap,
                   telefono,
                   fax,
                   mail,
                   fl_part_iva,
                   localita,
                   cell,
                   per_rif
                  )
           VALUES (ID,
                   codsoggetto,
                   UPPER (cognome),
                   UPPER (nome),
                   UPPER (denominazione),
                   sesso,
                   dnasc,
                   dcostituzione,
                   dmorte,
                   codcomunascita,
                   civicoresi,
                   codcomuresi,
                   civicorecap,
                   codcomurecap,
                   cap,
                   flagpersfisica,
                   UPPER (codfisc),
                   partitaiva,
                   NATURA_GIURIDICA,
                   rapplegale,
                   datainizio,
                   datafine,
                   SYSDATE,
                   utente,
                   NULL,
                   attoini,
                   attofine,
                   UPPER (pindirizzo_est),
                   UPPER (pindirizzo_est_recap),
                   pcap_recap,
                   ptelefono,
                   pfax,
                   pmail,
                   pfl_part_iva,
                   UPPER (plocalita),
                   cell,
                   per_rif
                  );
    ELSE
      ID := idsoggetto;
    END IF;

    RETURN ID;
  END aggiorna_soggetto;

  -- function inserisci civico
  --
  FUNCTION inserisci_civico (idstrada IN NUMBER, pcod_nazionale IN VARCHAR2, pcivico IN VARCHAR2, utente IN VARCHAR2)
    RETURN NUMBER IS
    ID                            NUMBER := 0;
  m_cod_nazionale        VARCHAR2(4);
  BEGIN
    validacivico (idstrada, pcod_nazionale, pcivico, utente);

    BEGIN
      SELECT c.pkid_civi
        INTO ID
        FROM siticivi c
       WHERE c.pkid_stra = idstrada AND c.civico = pcivico --AND c.cod_nazionale = pcod_nazionale
         AND c.data_fine_val = TO_DATE ('31129999', 'ddmmyyyy');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        SELECT siticivi_seq.NEXTVAL
          INTO ID
          FROM DUAL;

    -- cerco il cod_nazionale della strada
    SELECT COD_NAZIONALE INTO m_cod_nazionale
      FROM sitidstr
     WHERE pkid_stra = idstrada
       AND data_fine_val = TO_DATE ('31129999', 'ddmmyyyy');

        INSERT INTO siticivi
                    (pkid_civi, pkid_stra, cod_nazionale, civico, data_inizio_val, data_fine_val, utente)
             VALUES (ID, idstrada, m_cod_nazionale, pcivico, SYSDATE, TO_DATE ('31129999', 'ddmmyyyy'), utente);
    END;

    RETURN ID;
  END inserisci_civico;

  -- function inserisci unita tecnica
  --
  FUNCTION inserisci_unitatecnica (
    tipologia                   IN       VARCHAR2,
    descrizione                 IN       VARCHAR2,
    codice_assss                IN       VARCHAR2,
    telefono                    IN       VARCHAR2,
    fax                         IN       VARCHAR2,
    mail                        IN       VARCHAR2,
    note                        IN       VARCHAR2,
    piva                        IN       VARCHAR2,
    civicolocazione             IN       NUMBER,
    codcomulocazione            IN       VARCHAR2,
    cap                         IN       VARCHAR2,
    pscala                      IN       VARCHAR2,
    ppiano                      IN       NUMBER,
    pinterno                    IN       NUMBER,
    pindirizzo_est              IN       VARCHAR2,
    utente                      IN       VARCHAR2,
    id_cata_ute                 IN       NUMBER DEFAULT NULL
  )
    RETURN NUMBER IS
    datafine                      DATE := TO_DATE ('99991231', 'yyyymmdd');
    datainizio                    DATE := SYSDATE;
    RESULT                        NUMBER := 0;
    id_ute                        NUMBER;
    m_id_cata_ute                 NUMBER := NULL;
  BEGIN

    validaunitatecnica (descrizione, codice_assss, civicolocazione);

    IF id_cata_ute IS NULL OR id_cata_ute = 0 THEN
      SELECT cata_ute_seq.NEXTVAL
        INTO m_id_cata_ute
        FROM DUAL;

  -- inserisoc nel catalogo
      INSERT INTO CATA_UTE
                (id_cata_ute, codice)
         VALUES (m_id_cata_ute, UPPER (codice_assss));

  ELSE
    m_id_cata_ute := id_cata_ute;

    END IF;

    SELECT anag_ute_seq.NEXTVAL
      INTO id_ute
      FROM DUAL;

    -- inserisco i dati dell'ute
    INSERT INTO ANAG_UTE
                (pkid_ute,
                 descrizione,
                 telefono,
                 fax,
                 mail,
                 note,
                 fkcivico_locazione,
                 partita_iva,
                 tipologia,
                 cap,
                 fkcod_comu_locazione,
                 indirizzo_est,
                 data_inizio_val,
                 data_fine_val,
                 data_var,
                 user_id,
                 id_cata_ute
                )
         VALUES (id_ute,
                 descrizione,
                 telefono,
                 fax,
                 mail,
                 note,
                 civicolocazione,
                 piva,
                 tipologia,
                 cap,
                 codcomulocazione,
                 pindirizzo_est,
                 datainizio,
                 datafine,
                 SYSDATE,
                 utente,
                 m_id_cata_ute
                );

    RETURN id_ute;
  END inserisci_unitatecnica;

  -- function modifica unita tecnica
   --
  FUNCTION modifica_unitatecnica (
    idunita                     IN       NUMBER,
    tipologia                   IN       VARCHAR2,
    descrizione                 IN       VARCHAR2,
    codice_assss                IN       VARCHAR2,
    telefono                    IN       VARCHAR2,
    fax                         IN       VARCHAR2,
    mail                        IN       VARCHAR2,
    note                        IN       VARCHAR2,
    piva                        IN       VARCHAR2,
    civicolocazione             IN       NUMBER,
    codcomulocazione            IN       VARCHAR2,
    cap                         IN       VARCHAR2,
    pscala                      IN       VARCHAR2,
    ppiano                      IN       NUMBER,
    pinterno                    IN       NUMBER,
    pindirizzo_est              IN       VARCHAR2,
    utente                      IN       VARCHAR2,
  id_cata_ute        IN     NUMBER DEFAULT NULL
  )
    RETURN NUMBER IS
    datafine                      DATE := TO_DATE ('99991231', 'yyyymmdd');
    datainizio                    DATE := SYSDATE;
    RESULT                        NUMBER := 0;
    id_ute                        NUMBER := 0;
    m_id_cata_ute                 NUMBER;
  BEGIN
    IF idunita IS NOT NULL AND idunita > 0 THEN
      -- verifico se l'ute esiste
      BEGIN
        SELECT id_cata_ute
          INTO m_id_cata_ute
          FROM ANAG_UTE
         WHERE pkid_ute = idunita;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          RAISE_APPLICATION_ERROR (-20103, 'Identificativo Ute non valido');
      END;

      id_ute :=
        inserisci_unitatecnica (tipologia, descrizione, codice_assss, telefono, fax, mail, note, piva, civicolocazione,
                                codcomulocazione, cap, pscala, ppiano, pinterno, pindirizzo_est, utente, m_id_cata_ute);

      UPDATE ANAG_UTE t
         SET t.data_fine_val = datainizio - (1 / 24 / 60 / 60),
             t.user_id = utente
       WHERE t.pkid_ute = idunita;
    ELSE
      RAISE_APPLICATION_ERROR (-20103, 'Identificativo Ute non valido');
    END IF;

    RETURN id_ute;
  END modifica_unitatecnica;

  PROCEDURE elimina_unitatecnica (
    idunita                     IN       NUMBER,
    tipologia                   IN       VARCHAR2,
    descrizione                 IN       VARCHAR2,
    codice_assss                IN       VARCHAR2,
    telefono                    IN       VARCHAR2,
    fax                         IN       VARCHAR2,
    mail                        IN       VARCHAR2,
    note                        IN       VARCHAR2,
    piva                        IN       VARCHAR2,
    civicolocazione             IN       NUMBER,
    codcomulocazione            IN       VARCHAR2,
    cap                         IN       VARCHAR2,
    pscala                      IN       VARCHAR2,
    ppiano                      IN       NUMBER,
    pinterno                    IN       NUMBER,
    pindirizzo_est              IN       VARCHAR2,
    utente                      IN       VARCHAR2,
  id_cata_ute       IN     NUMBER DEFAULT NULL
  ) IS
    isDeletable  NUMBER := 0;
  BEGIN


  SELECT SUM (cnt)
    INTO isdeletable
    FROM (SELECT COUNT (*) AS cnt
            FROM ANAG_UTE_SOGGETTI aus, ANAG_UTE anagu
           WHERE aus.id_cata_ute = anagu.id_cata_ute AND anagu.pkid_ute = idunita
          AND aus.data_inizio_val <= SYSDATE
          AND aus.data_fine_val >= SYSDATE
          UNION
          SELECT COUNT (*) AS cnt
            FROM CENTRIRESP cr, ANAG_UTE anagu
           WHERE cr.fk_settore = anagu.id_cata_ute
       AND anagu.pkid_ute = idunita
       AND cr.data_inizio_val <= SYSDATE
             AND cr.data_fine_val >= SYSDATE);


    IF isDeletable < 1 THEN
     UPDATE ANAG_UTE t
        SET t.data_fine_val = SYSDATE - (1 / 24 / 60 / 60),
            t.user_id = utente
      WHERE t.pkid_ute = idunita;

  ELSE
     RAISE_APPLICATION_ERROR (-20108,
                               'Non ï¿½ possibile eliminare l''unitï¿½ tecnica in quanto ï¿½ collegata a ' || isDeletable || ' soggetto/i');
  END IF;

  END elimina_unitatecnica;

  -- function inserisci relazione
   --
  FUNCTION inserisci_relazione (
    idrel                       IN       NUMBER,
    codice_soggetto             IN       NUMBER,
    codice_tipo                 IN       NUMBER,
    codice_ruolo                IN       NUMBER,
    utente                      IN       VARCHAR2,
    p_dt_lavo                            DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    datafine                      DATE := TO_DATE ('99991231', 'yyyymmdd');
    ID                            NUMBER := 0;
  BEGIN
    validarelazione (codice_soggetto, codice_tipo);

    IF idrel IS NOT NULL AND idrel > 0 THEN
      ID := idrel;
    ELSE
      SELECT anag_relazioni_seq.NEXTVAL
        INTO ID
        FROM DUAL;
    END IF;

    INSERT INTO ANAG_RELAZIONI
                (pkid_relazione,
                 pkcod_sogg,
                 pktipo_rel,
                 fkcod_ruolo,
                 data_inizio_val,
                 data_fine_val,
                 data_lav,
                 utente_inizio,
                 utente_fine
                )
         VALUES (ID, codice_soggetto, codice_tipo, codice_ruolo, p_dt_lavo, datafine, SYSDATE, utente, NULL);

    RETURN ID;
  END inserisci_relazione;

  FUNCTION aggiorna_relazione (
    idrel                       IN       NUMBER,
    codice_soggetto             IN       NUMBER,
    codice_tipo                 IN       NUMBER,
    codice_ruolo                IN       NUMBER,
    utente                      IN       VARCHAR2,
    p_dt_lavo                            DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    ID                            NUMBER := 0;
    fin                           DATE := p_dt_lavo - (1 / 24 / 60 / 60);
    ini                           DATE;
    r                             ROWID;
  BEGIN
    UPDATE    ANAG_RELAZIONI t
          SET t.data_fine_val = fin,
              t.utente_fine = utente
        WHERE t.pkid_relazione = idrel AND t.pkcod_sogg = codice_soggetto AND t.pktipo_rel = codice_tipo
              AND t.data_inizio_val <= p_dt_lavo AND t.data_fine_val >= p_dt_lavo
    RETURNING t.data_inizio_val, ROWID
         INTO ini, r;

    IF (fin < ini) THEN
      -- Aggiorno alla stessa data in cui ho inserito la relazione...
      DELETE FROM ANAG_RELAZIONI
            WHERE ROWID = r;
    END IF;

    ID := inserisci_relazione (idrel, codice_soggetto, codice_tipo, codice_ruolo, utente, p_dt_lavo);
    RETURN ID;
  END aggiorna_relazione;

  /*
   * Archivia relazione
   */
  PROCEDURE elimina_relazione (
    idrel                       IN       NUMBER,
    codice_soggetto             IN       NUMBER,
    codice_tipo                 IN       NUMBER,
    codice_ruolo                IN       NUMBER,
    utente                      IN       VARCHAR2,
    p_dt_lavo                            DATE DEFAULT SYSDATE
  ) IS
    stm                           VARCHAR2 (300);
    min_dt                        DATE;
  BEGIN
    -- validaRelazione(codice_soggetto, codice_tipo);
    IF idrel IS NULL OR idrel = 0 THEN
      RAISE_APPLICATION_ERROR (-20105, 'Impossibile eliminare la relazione identificativo obbligatorio');
    END IF;

    SELECT MIN (data_inizio_val)
      INTO min_dt
      FROM ANAG_RELAZIONI
     WHERE pkid_relazione = idrel;

    IF (min_dt >= p_dt_lavo) THEN
      RAISE_APPLICATION_ERROR (-20106,
                               'Impossibile eliminare la relazione a questa data, data minima: '
                               || TO_CHAR (min_dt + 1, 'dd/mm/yyyy'));
    END IF;

    stm :=
      'update anag_relazioni t
       SET t.data_fine_val = :1 - (1 / 24 / 60 / 60), t.utente_fine = :2
      WHERE t.pkid_relazione = '
      || idrel || ' and t.data_inizio_val <= :3 and t.data_fine_val >= :4';

    IF (codice_soggetto IS NOT NULL AND codice_soggetto <> 0) THEN
      stm := stm || ' and t.pkcod_sogg = ' || codice_soggetto;
    END IF;

    IF (codice_tipo IS NOT NULL AND codice_tipo <> 0) THEN
      stm := stm || ' and t.pktipo_rel = ' || codice_tipo;
    END IF;

    EXECUTE IMMEDIATE stm
                USING p_dt_lavo, utente, p_dt_lavo, p_dt_lavo;
  END elimina_relazione;

  /*
   * Elimina relazione
   */
  PROCEDURE elimina_relazione_permanente (
    idrel                       IN       NUMBER,
    codice_soggetto             IN       NUMBER,
    codice_tipo                 IN       NUMBER,
    codice_ruolo                IN       NUMBER,
    utente                      IN       VARCHAR2
  ) IS
  BEGIN
    IF idrel IS NULL OR idrel = 0 THEN
      RAISE_APPLICATION_ERROR (-20105, 'Impossibile eliminare la relazione identificativo obbligatorio');
    END IF;

    DELETE      ANAG_RELAZIONI t
          WHERE t.pkid_relazione = idrel;
  END elimina_relazione_permanente;

  /*
   * Inserisci nuovo soggetto in consistenza
   */
  FUNCTION inserisci_consistenza (codice_soggetto IN VARCHAR2, utente IN VARCHAR2)
    RETURN NUMBER IS
    datafine                      DATE := TO_DATE ('99991231', 'yyyymmdd');
    ID                            NUMBER := NULL;
    cod_test                      VARCHAR2 (16) := NULL;
  BEGIN
    BEGIN
      SELECT pk_cuaa
        INTO cod_test
        FROM CONS_AZIE_TAB
       WHERE UPPER (cuaa) = UPPER (codice_soggetto);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        SELECT cons_azie_seq.NEXTVAL
          INTO ID
          FROM DUAL;

        INSERT INTO CONS_AZIE_TAB
                    (pk_cuaa,
                     cuaa,
                     data_inizio,
                     data_fine,
                     data_registrazione,
                     utente,
                     TIMESTAMP,
                     cod_stato,
                     data_inizio_stato,
                     cod_ente
                    )
             VALUES (ID, UPPER (codice_soggetto), TRUNC (SYSDATE), datafine, SYSDATE, utente, SYSDATE, 0, SYSDATE, NULL);
    END;

    IF cod_test IS NOT NULL THEN
      RAISE_APPLICATION_ERROR (-20000, 'Soggetto gia esistente');
    END IF;

    RETURN ID;
  END inserisci_consistenza;

  /*
   * Aggiorna soggetto in consistenza
   */
  PROCEDURE aggiorna_consistenza (codice_soggetto IN VARCHAR2, nuovo_codice IN VARCHAR2, utente IN VARCHAR2) IS
  BEGIN
    UPDATE CONS_AZIE_TAB t
       SET t.cuaa = UPPER (nuovo_codice)
     WHERE t.pk_cuaa = codice_soggetto AND t.data_fine = TO_DATE ('99991231', 'yyyymmdd');
  END aggiorna_consistenza;

  -- Purpose : validazione dati soggetto.
  PROCEDURE validasoggetto (
    codfisc                     IN       VARCHAR2,
    cognome                     IN       VARCHAR2,
    nome                        IN       VARCHAR2,
    denominazione               IN       VARCHAR2,
    sesso                       IN       VARCHAR2,
    dnasc                       IN       DATE,
    dmorte                      IN       DATE,
    codcomunascita              IN       VARCHAR,
    civicoresi                  IN       INTEGER,
    flagpersfisica              IN       VARCHAR2,
    partitaiva                  IN       VARCHAR2,
    utente                      IN       VARCHAR2,
    modifica                    IN       BOOLEAN,
    strictcontrols                       BOOLEAN
  ) IS
    CURSOR c1 IS
      SELECT 1
        FROM ANAG_SOGGETTI a
       WHERE a.cod_fiscale = codfisc AND a.data_fine_val = TO_DATE ('99991231', 'yyyymmdd');

    --CURSOR C2 IS SELECT 1 FROM ANAG_SOGGETTI a WHERE a.part_iva=partitaIva and a.data_fine_val = to_date('99991231', 'yyyymmdd');
    cf_val                        NUMBER (1) := 0;
  --PI_VAL NUMBER(1) := 0;
  BEGIN
    -- controlla denominazione
    IF denominazione IS NULL AND cognome IS NULL THEN
      RAISE_APPLICATION_ERROR (-20009, 'Denominazione o cognome e campo obbligatorio');
    END IF;

    -- controlla flag
    IF flagpersfisica IS NULL THEN
      RAISE_APPLICATION_ERROR (-20008, 'Flag persona fisica o giuridica e campo obbligatorio');
    END IF;

    -- controlla partita iva o codice fiscale in base al flag
    IF codfisc IS NULL AND strictcontrols THEN
      RAISE_APPLICATION_ERROR (-20002, 'Codice fiscale obbligatorio');
    ELSIF codfisc IS NOT NULL THEN
      -- controllo della lunghezza
      IF flagpersfisica = 'P' AND LENGTH (TRIM (codfisc)) <> 16 THEN
        RAISE_APPLICATION_ERROR (-20003, 'Codice fiscale campo non valido');
      END IF;

      IF flagpersfisica = 'G' AND LENGTH (TRIM (codfisc)) <> 16 AND LENGTH (TRIM (codfisc)) <> 11 THEN
        RAISE_APPLICATION_ERROR (-20003, 'Codice fiscale campo non valido');
      END IF;

      IF NOT modifica THEN
        -- controllo della presenza
        OPEN c1;

        FETCH c1
         INTO cf_val;

        IF c1%NOTFOUND THEN
          cf_val := 0;
        END IF;

        CLOSE c1;

        IF cf_val > 0 THEN
          RAISE_APPLICATION_ERROR (-20000, 'Soggetto gia esistente');
        END IF;
      END IF;
    -- ceck di validita -
    /*if nome is not null and denominazione is not null and dnasc is not null and sesso is not null then
       if codFisc <> codfisc_pck.get_cod_fisc(nome, denominazione, dnasc, codComuNascita, sesso) then
            Raise_application_error(-20003, 'Codice fiscale campo non valido');
       end if;
    end if;*/
    END IF;

    /*if flagPersFisica = 'G' and partitaIva is null then
       Raise_application_error(-20004, 'Partita IVA campo obbligatorio');
    els*/
    IF partitaiva IS NOT NULL THEN
      -- controllo lunghezza
      IF LENGTH (TRIM (partitaiva)) <> 11 THEN
        RAISE_APPLICATION_ERROR (-20005, 'Pertita IVA campo non valido');
      END IF;
    /*if not modifica then
    -- controllo della presenza
      OPEN C2;
      FETCH C2 INTO PI_VAL;
      IF C2%NOTFOUND THEN PI_VAL:=0; END IF;
      CLOSE C2;
      if PI_VAL > 0 then
         Raise_application_error(-20000, 'Soggetto gia esistente');
      end if;
    end if;*/
    END IF;

    -- controlla utente
    IF utente IS NULL THEN
      RAISE_APPLICATION_ERROR (-20007, 'Utente campo obbligatorio');
    END IF;
  END validasoggetto;

  /*
   * Validazione del civico
   */
  PROCEDURE validacivico (idstrada IN NUMBER, cod_nazionale IN VARCHAR2, civico IN VARCHAR2, utente IN VARCHAR2) IS
  m_idstrada NUMBER := NULL;
 BEGIN
    -- id strada
    IF idstrada IS NULL OR idstrada = 0 THEN
      RAISE_APPLICATION_ERROR (-20200, 'Identificativo della strada e campo obbligatorio');
    END IF;

  BEGIN
     SELECT PKID_STRA INTO m_idstrada
       FROM SITIDSTR
     WHERE PKID_STRA = idstrada
        AND data_fine_val = TO_DATE ('31129999', 'ddmmyyyy');
  EXCEPTION WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR (-20200, 'La strada non esiste o e scaduta');
  END;

    -- cod nazionale
    --IF cod_nazionale IS NULL THEN
    --  RAISE_APPLICATION_ERROR (-20201, 'Codice nazionale e campo obbligatorio');
    --END IF;

    -- civico
    IF civico IS NULL THEN
      RAISE_APPLICATION_ERROR (-20202, 'Civico e campo obbligatorio');
    END IF;

    -- utente
    IF utente IS NULL THEN
      RAISE_APPLICATION_ERROR (-20007, 'Utente campo obbligatorio');
    END IF;
  END validacivico;

  /*
   * Creazione codice soggetto
   */
  FUNCTION creacodicesoggetto (codfisc IN VARCHAR2, partitaiva IN VARCHAR2, flagpersfisica IN VARCHAR2)
    RETURN VARCHAR2 IS
    RESULT                        VARCHAR2 (16);
    fcheck                        BOOLEAN := FALSE;
  BEGIN
    IF (codfisc IS NOT NULL) THEN
      RESULT := codfisc;
      fcheck := TRUE;
    END IF;

    IF (NOT fcheck AND partitaiva IS NOT NULL) THEN
      RESULT := partitaiva;
      fcheck := TRUE;
    END IF;

    IF (NOT fcheck) THEN
      RAISE_APPLICATION_ERROR (-20001, 'Nessuna chiave possibile');
    END IF;

    RETURN (RESULT);
  END creacodicesoggetto;

  -- Purpose : validazione dati unita tecnica.
  PROCEDURE validaunitatecnica (descrizione IN VARCHAR2, codice_assss IN VARCHAR2, civicolocazione IN NUMBER) IS
    cnt                           NUMBER := 0;
  BEGIN
    IF codice_assss IS NULL OR codice_assss = '' THEN
      RAISE_APPLICATION_ERROR (-20100, 'Codice ute ï¿½ campo obbligatorio');
    END IF;

    IF descrizione IS NULL OR descrizione = '' THEN
      RAISE_APPLICATION_ERROR (-20101, 'Descrizione utenza ï¿½ campo obbligatorio');
    END IF;

  END validaunitatecnica;

  -- Purpose : validazione relazione.
  PROCEDURE validarelazione (codice_soggetto IN NUMBER, codice_tipo IN NUMBER) IS
  BEGIN
    -- codice soggetto
    IF codice_soggetto IS NULL OR codice_soggetto = 0 THEN
      RAISE_APPLICATION_ERROR (-20100, 'Codice soggetto e campo obbligatorio');
    END IF;

    -- codice tipo
    IF codice_tipo IS NULL OR codice_tipo = 0 THEN
      RAISE_APPLICATION_ERROR (-20102, 'Codice tipo relazione e campo obbligatorio');
    END IF;

    -- controlla la cardinalita
    checkcardinalita (codice_soggetto, codice_tipo);
  END validarelazione;

  /*
   * Controllo della cardinalita di una relazione
   */
  PROCEDURE checkcardinalita (codice_soggetto IN NUMBER, codice_tipo IN NUMBER) IS
    card                          VARCHAR2 (1) := 'N';
    n_card                        NUMBER := 0;
  BEGIN
    BEGIN
      SELECT t.cardinalita
        INTO card
        FROM ANAG_TIPI_RELAZIONI t
       WHERE t.pkid_tipo = codice_tipo;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR (-20103, 'Codice tipo relazione non e valido');
    END;

    IF card = '1' THEN
      SELECT COUNT (*)
        INTO n_card
        FROM ANAG_RELAZIONI t
       WHERE t.pkcod_sogg = codice_soggetto AND t.pktipo_rel = codice_tipo
             AND t.data_fine_val = TO_DATE ('99991231', 'yyyymmdd');

      IF n_card > 0 THEN
        RAISE_APPLICATION_ERROR (-20104, 'Il tipo di relazione ha occorrenza uno ed e gia presente.');
      END IF;
    END IF;
  END checkcardinalita;

  /*
   * Controllo del tipo di una relazione
   */
  FUNCTION checktiporelazione (codice_soggetto IN NUMBER, codice_tipo IN NUMBER, p_data DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    n                             NUMBER := 0;
  BEGIN
    SELECT COUNT (*)
      INTO n
      FROM ANAG_RELAZIONI t
     WHERE t.pkcod_sogg = codice_soggetto AND t.pktipo_rel = codice_tipo AND t.data_inizio_val <= p_data
           AND t.data_fine_val >= p_data;

    RETURN n;
  END checktiporelazione;
END Anagrafica;
/


DROP PACKAGE BODY SITI_H501.AU;

CREATE OR REPLACE package body SITI_H501.au as

  function equals(a varchar2, b varchar2) return boolean is
    ret boolean;
  begin
    if (a is null and b is null) then
      ret := true;
    elsif (a is not null and b is not null) then
      ret := (a = b);
    else
      ret := false;
    end if;
    return ret;
  end equals;

  function equals(a number, b number) return boolean is
    ret boolean;
  begin
    if (a is null and b is null) then
      ret := true;
    elsif (a is not null and b is not null) then
      ret := (a = b);
    else
      ret := false;
    end if;
    return ret;
  end equals;

  function equals(a date, b date) return boolean is
    ret boolean;
  begin
    if (a is null and b is null) then
      ret := true;
    elsif (a is not null and b is not null) then
      ret := (a = b);
    else
      ret := false;
    end if;
    return ret;
  end equals;

end au;
/


DROP PACKAGE BODY SITI_H501.CATALOG_DATA;

CREATE OR REPLACE PACKAGE BODY SITI_H501.catalog_data
IS
   FUNCTION getcodeprgc (cod IN NUMBER)
      RETURN VARCHAR2
   IS
      CURSOR cur
      IS
         SELECT codut
           FROM sitideco_catalog
          WHERE codice = cod;

      retval   VARCHAR2 (2048);
   BEGIN
      OPEN cur;

      FETCH cur
       INTO retval;

      IF cur%NOTFOUND
      THEN
         retval := '';
      END IF;

      CLOSE cur;

      RETURN retval;
   END getcodeprgc;

   FUNCTION getcodeprgc_descr (cod IN NUMBER)
      RETURN VARCHAR2
   IS
      CURSOR cur
      IS
         SELECT codut || ' - ' || descrizione
           FROM sitideco_catalog
          WHERE codice = cod;

      retval   VARCHAR2 (2048);
   BEGIN
      OPEN cur;

      FETCH cur
       INTO retval;

      IF cur%NOTFOUND
      THEN
         retval := '';
      END IF;

      CLOSE cur;

      RETURN retval;
   END getcodeprgc_descr;

   FUNCTION setcodeprgc (str IN VARCHAR2)
      RETURN NUMBER
   IS
      CURSOR cur
      IS
         SELECT codice
           FROM sitideco_catalog
          WHERE codut = str;

      retval   NUMBER;
   BEGIN
      OPEN cur;

      FETCH cur
       INTO retval;

      IF cur%NOTFOUND
      THEN
         retval := 0;
      END IF;

      CLOSE cur;

      RETURN retval;
   END setcodeprgc;

   PROCEDURE assegnacodici (idc IN NUMBER)
   IS
      TYPE emptycur IS REF CURSOR;

      CURSOR cur
      IS
         SELECT cod_nazionale, foglio, particella, sub, shape
           FROM sitipart
          WHERE data_fine_val =
                               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
            AND shape IS NOT NULL
            AND cod_nazionale = 'C313'
            AND ((foglio >= 8 AND foglio <= 13) OR foglio = 29 OR foglio = 141
                );

      ccod        emptycur;
      tablename   VARCHAR2 (30);
      fieldcode   VARCHAR2 (70);
      sqlstr      VARCHAR2 (1024);
      cn          VARCHAR2 (4);
      fo          NUMBER (4);
      pa          VARCHAR2 (5);
      su          VARCHAR2 (3);
      sh          MDSYS.SDO_GEOMETRY;
      conta       NUMBER (4);
      cod         NUMBER (9);
      pcod        NUMBER (9);
   BEGIN
      conta := 0;

      SELECT tabella, code_field
        INTO tablename, fieldcode
        FROM siticatalog
       WHERE id_cat = idc;

      sqlstr :=
            'SELECT CATALOG_DATA.SETCODEPRGC('
         || fieldcode
         || ') FROM '
         || tablename
         || ' A WHERE A.id_cat='
         || TO_CHAR (idc)
         || ' AND sdo_relate(a.shape,:1,''mask=ANYINTERACT querytype=WINDOW'') = ''TRUE'' ORDER BY '
         || fieldcode;

      DELETE FROM sitipart_cat
            WHERE id_cat = idc;

      COMMIT;

      OPEN cur;

      LOOP
         FETCH cur
          INTO cn, fo, pa, su, sh;

         EXIT WHEN (cur%NOTFOUND);

--  IF 1=0 THEN
--    DBMS_OUTPUT.put_line(CN || ' - ' || To_Char(FO) || ' ' || PA || '/' || SU);
         OPEN ccod FOR sqlstr USING sh;

         pcod := 0;

         LOOP
            FETCH ccod
             INTO cod;

            EXIT WHEN (ccod%NOTFOUND);

            IF cod IS NOT NULL
            THEN
               IF cod > 0 AND cod != pcod
               THEN
                  INSERT INTO sitipart_cat
                              (id_cat, cod_nazionale, foglio, particella,
                               sub, data_inizio_val,
                               data_fine_val,
                               data_lav, codice
                              )
                       VALUES (idc, cn, fo, pa,
                               su, SYSDATE,
                               TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS'),
                               SYSDATE, cod
                              );

                  pcod := cod;
                  conta := conta + 1;

                  IF conta = 500
                  THEN
                     COMMIT;
                     conta := 0;
                  END IF;
               END IF;
            END IF;
         END LOOP;

         CLOSE ccod;
--  END IF;
      END LOOP;

      CLOSE cur;

      COMMIT;
   END assegnacodici;

   FUNCTION is_part_in_cat (
      idc        IN   NUMBER,
      codc       IN   NUMBER,
      codnaz     IN   VARCHAR2,
      fog        IN   NUMBER,
      part       IN   VARCHAR2,
      subal      IN   VARCHAR2,
      datactrl   IN   DATE
   )
      RETURN NUMBER
   IS
      CURSOR c1
      IS
         SELECT 1
           FROM sitipart_cat
          WHERE id_cat = idc
            AND cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND data_fine_val >= datactrl
            AND codice = codc
            AND data_inizio_val <= datactrl;

      retval   NUMBER (1) := 0;
   BEGIN
      OPEN c1;

      FETCH c1
       INTO retval;

      IF c1%NOTFOUND
      THEN
         retval := 0;
      END IF;

      CLOSE c1;

      RETURN retval;
   END is_part_in_cat;

   PROCEDURE cataloga_part (
      codnaz   IN   VARCHAR2,
      fog      IN   NUMBER,
      part     IN   VARCHAR2,
      subo     IN   VARCHAR2,
      datal    IN   DATE,
      idc      IN   NUMBER
   )
   IS
      TYPE emptycur IS REF CURSOR;

      c                  emptycur;
      dl                 DATE;
      dl1                DATE;
      id_catalogo        NUMBER (9);
      nome_tabella       VARCHAR2 (30);
      nome_funz_encode   VARCHAR2 (70);
      nome_codice        VARCHAR2 (70);
      tipo_catalogo      VARCHAR2 (10);
      area_trascura      NUMBER (11, 2);
      shp                MDSYS.SDO_GEOMETRY;
      shpc               MDSYS.SDO_GEOMETRY;
      area_part          NUMBER (11, 2);

      CURSOR cp
      IS
         SELECT shape, area_part
           FROM sitipart
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subo
            AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');

      CURSOR cc
      IS
         SELECT shape
           FROM siticent
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subo
            AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');
   BEGIN
      IF datal IS NULL
      THEN
         dl := SYSDATE;
      ELSE
         dl := datal;
      END IF;

      OPEN cp;

      FETCH cp
       INTO shp, area_part;

      IF cp%NOTFOUND
      THEN
         shp := NULL;
         area_part := NULL;
      END IF;

      CLOSE cp;

      OPEN cc;

      FETCH cc
       INTO shpc;

      IF cc%NOTFOUND
      THEN
         shpc := NULL;
      END IF;

      CLOSE cc;

      IF idc IS NULL OR idc = 0
      THEN
         OPEN c FOR
            SELECT   id_cat, tabella, plencode, code_field, shape_type,
                     supe_trascura
                FROM siticatalog
            ORDER BY id_cat;
      ELSE
         OPEN c FOR
            SELECT id_cat, tabella, plencode, code_field, shape_type,
                   supe_trascura
              FROM siticatalog
             WHERE id_cat = idc;
      END IF;

      LOOP
         FETCH c
          INTO id_catalogo, nome_tabella, nome_funz_encode, nome_codice,
               tipo_catalogo, area_trascura;

         EXIT WHEN (c%NOTFOUND);

         -- PaoloBravo 26/07/2006: annullo l'istanza dopo aver fetchatto
         UPDATE sitipart_cat
            SET data_fine_val = dl - (1 / 24 / 60 / 60)
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subo
            AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
            AND id_cat = id_catalogo;

         IF area_trascura < 0
         THEN
            intersezioni_part_cat (codnaz,
                                   fog,
                                   part,
                                   subo,
                                   dl,
                                   id_catalogo,
                                   nome_tabella,
                                   nome_funz_encode,
                                   nome_codice,
                                   tipo_catalogo,
                                   area_trascura,
                                   area_part,
                                   shpc
                                  );
         ELSE
            intersezioni_part_cat (codnaz,
                                   fog,
                                   part,
                                   subo,
                                   dl,
                                   id_catalogo,
                                   nome_tabella,
                                   nome_funz_encode,
                                   nome_codice,
                                   tipo_catalogo,
                                   area_trascura,
                                   area_part,
                                   shp
                                  );
         END IF;
      END LOOP;

      CLOSE c;
   END cataloga_part;

   PROCEDURE intersezioni_part_cat (
      codnaz       IN   VARCHAR2,
      fog          IN   NUMBER,
      part         IN   VARCHAR2,
      subo         IN   VARCHAR2,
      datal        IN   DATE,
      idc          IN   NUMBER,
      nometab      IN   VARCHAR2,
      nomefunzen   IN   VARCHAR2,
      nomecod      IN   VARCHAR2,
      tipocat      IN   VARCHAR2,
      areatrasc    IN   NUMBER,
      area_part    IN   NUMBER,
      shp_part     IN   MDSYS.SDO_GEOMETRY
   )
   IS
      TYPE emptycur IS REF CURSOR;

      c            emptycur;
      dl           DATE;
      codcat       NUMBER (9);
      area_inte    NUMBER (11, 2);
      catserow     VARCHAR2 (20);
      catserowid   NUMBER;
   BEGIN
      IF datal IS NULL
      THEN
         dl := SYSDATE;
      ELSE
         dl := datal;
      END IF;

      -- PB 26/07/2006: richiamata a SITICATALOG per scaricarmi il nome campo del poligono
      SELECT id_field
        INTO catserow
        FROM siticatalog
       WHERE id_cat = idc;

      -- PB 26/07/2006: modificate select parametriche
      IF tipocat = 'POLYGON'
      THEN
         IF areatrasc < 0
         THEN
            OPEN c FOR    'SELECT '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || ') AS COD,'
                       || '(A.'                     -- PB 26/07/2006: aggiunta
                       || catserow                  -- PB 26/07/2006: aggiunta
                       || ') AS CATSEROWID,'        -- PB 26/07/2006: aggiunta
                       || 'NULL AS AGGRSHP FROM '
                       || nometab
                       || ' A WHERE A.ID_CAT='
                       || TRIM (TO_CHAR (idc))
                       || ' AND SDO_RELATE(A.SHAPE, :2, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || '),'
                       || '(A.'                     -- PB 26/07/2006: aggiunta
                       || catserow                  -- PB 26/07/2006: aggiunta
                       || ')' USING shp_part;
         ELSE
            OPEN c FOR    'SELECT COD, CATSEROWID, SDO_GEOM.SDO_AREA(AGGRSHP, 0.00005) FROM (SELECT '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || ') AS COD,'
                       || '(A.'                     -- PB 26/07/2006: aggiunta
                       || catserow                  -- PB 26/07/2006: aggiunta
                       || ') AS CATSEROWID,'        -- PB 26/07/2006: aggiunta
                       || 'SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SDO_GEOM.SDO_INTERSECTION(SDO_TOOLS.REMOVE_DUPLICATE_POINTS(A.SHAPE), :1, 0.00005), 0.00005)) AS AGGRSHP FROM '
                       || nometab
                       || ' A WHERE A.ID_CAT='
                       || TRIM (TO_CHAR (idc))
                       || ' AND SDO_RELATE(A.SHAPE, :2, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || '),'
                       || '(A.'
                       || catserow
                       || '))' USING shp_part, shp_part;
         END IF;
      ELSE
         OPEN c FOR    'SELECT '
                    || nomefunzen
                    || '(A.'
                    || nomecod
                    || '),'
                    || '(A.'                        -- PB 26/07/2006: aggiunta
                    || catserow                     -- PB 26/07/2006: aggiunta
                    || '),'                         -- PB 26/07/2006: aggiunta
                    || 'NULL FROM '
                    || nometab
                    || ' A WHERE A.ID_CAT='
                    || TRIM (TO_CHAR (idc))
                    || ' AND SDO_RELATE(A.SHAPE, :1, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY '
                    || nomefunzen
                    || '(A.'
                    || nomecod
                    || '),'
                    || '(A.'
                    || catserow
                    || '), NULL' USING shp_part;
      END IF;

      LOOP
         FETCH c
          INTO codcat, catserowid, area_inte;

         EXIT WHEN c%NOTFOUND;

         IF areatrasc < 0
         THEN
            area_inte :=
               get_supe_gis (codnaz,
                             fog,
                             part,
                             subo,
                             TO_DATE ('99991231', 'YYYYMMDD'),
                             0
                            );

            INSERT INTO sitipart_cat
                        (id_cat, cod_nazionale, foglio, particella, sub,
                         data_inizio_val, data_fine_val,
                         data_lav, codice, supe_inte, cat_se_row_id
                        )
                 VALUES (idc, codnaz, fog, part, subo,
                         dl, TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS'),
                         dl, codcat, area_inte, catserowid
                        );
         ELSE
            IF    (    tipocat = 'POLYGON'
                   AND area_inte / area_part * 100 >= areatrasc
                  )
               OR (tipocat <> 'POLYGON' AND area_inte IS NULL)
            THEN
               INSERT INTO sitipart_cat
                           (id_cat, cod_nazionale, foglio, particella, sub,
                            data_inizio_val,
                            data_fine_val,
                            data_lav, codice, supe_inte, cat_se_row_id
                           )
                    VALUES (idc, codnaz, fog, part, subo,
                            dl,
                            TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS'),
                            dl, codcat, area_inte, catserowid
                           );
            END IF;
         END IF;
      END LOOP;

      CLOSE c;
   END intersezioni_part_cat;

   PROCEDURE assegnacodici_comune (
      codnaz   IN   VARCHAR2,
      datal    IN   DATE,
      idc      IN   NUMBER
   )
   IS
      TYPE emptycur IS REF CURSOR;

      c                  emptycur;
      c2                 emptycur;
      dl                 DATE;
      i                  NUMBER;
      nome_tabella       VARCHAR2 (30);
      nome_funz_encode   VARCHAR2 (70);
      nome_codice        VARCHAR2 (70);
      tipo_catalogo      VARCHAR2 (10);
      area_trascura      NUMBER (11, 2);
      hasmbrcol          NUMBER (1);
      ctavola            NUMBER (4);
      fog                NUMBER (4);
      part               VARCHAR2 (5);
      subo               VARCHAR2 (3);
      shp                MDSYS.SDO_GEOMETRY;
      area_part          NUMBER (11, 2);
   BEGIN
      IF datal IS NULL
      THEN
         dl := SYSDATE;
      ELSE
         dl := datal;
      END IF;

      UPDATE sitipart_cat
         SET data_fine_val = dl - (1 / 24 / 60 / 60)
       WHERE cod_nazionale = codnaz
         AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
         AND id_cat = idc;

      OPEN c FOR
         SELECT tabella, plencode, code_field, shape_type, supe_trascura,
                hasmbrcolumn
           FROM siticatalog
          WHERE id_cat = idc;

      FETCH c
       INTO nome_tabella, nome_funz_encode, nome_codice, tipo_catalogo,
            area_trascura, hasmbrcol;

      IF c%NOTFOUND
      THEN
         nome_tabella := NULL;
         nome_funz_encode := NULL;
         nome_codice := NULL;
         tipo_catalogo := NULL;
         area_trascura := NULL;
         hasmbrcol := NULL;
      END IF;

      CLOSE c;

      i := 0;

      IF hasmbrcol > 0
      THEN
         OPEN c2 FOR    'SELECT TAVOLA FROM '
                     || nome_tabella
                     || ' B,SITIFGLC A WHERE A.COD_NAZIONALE='''
                     || codnaz
                     || ''' AND SDO_RELATE(B.SHAPEMBR,SDO_GEOM.SDO_MBR(A.SHAPE),''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY TAVOLA';
      ELSE
         OPEN c2 FOR    'SELECT TAVOLA FROM SITIFGLC A WHERE A.COD_NAZIONALE='''
                     || codnaz
                     || ''' GROUP BY TAVOLA';
      END IF;

      LOOP
         FETCH c2
          INTO ctavola;

         EXIT WHEN (c2%NOTFOUND);

         IF area_trascura < 0
         THEN
            OPEN c FOR
               SELECT foglio, particella, sub, shape, NULL AS area_part
                 FROM siticent
                WHERE cod_nazionale = codnaz
                  AND tavola = ctavola
                  AND data_fine_val =
                                TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');
         ELSE
            OPEN c FOR
               SELECT foglio, particella, sub, shape, area_part
                 FROM sitipart
                WHERE cod_nazionale = codnaz
                  AND tavola = ctavola
                  AND data_fine_val =
                                TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');
         END IF;

         LOOP
            FETCH c
             INTO fog, part, subo, shp, area_part;

            EXIT WHEN (c%NOTFOUND);
            intersezioni_part_cat (codnaz,
                                   fog,
                                   part,
                                   subo,
                                   dl,
                                   idc,
                                   nome_tabella,
                                   nome_funz_encode,
                                   nome_codice,
                                   tipo_catalogo,
                                   area_trascura,
                                   area_part,
                                   shp
                                  );
            i := i + 1;

            IF i = 500
            THEN
               COMMIT;
               i := 0;
            END IF;
         END LOOP;

         CLOSE c;
      END LOOP;

      COMMIT;
   END assegnacodici_comune;

   PROCEDURE intersezioni_part_cat_active (
      nome_campoid   IN   VARCHAR2,
      catserow       IN   NUMBER,
      codnaz         IN   VARCHAR2,
      fog            IN   NUMBER,
      part           IN   VARCHAR2,
      subo           IN   VARCHAR2,
      datal          IN   DATE,
      idc            IN   NUMBER,
      nometab        IN   VARCHAR2,
      nomefunzen     IN   VARCHAR2,
      nomecod        IN   VARCHAR2,
      tipocat        IN   VARCHAR2,
      areatrasc      IN   NUMBER,
      area_part      IN   NUMBER,
      shp_part       IN   MDSYS.SDO_GEOMETRY
   )
   IS
      TYPE emptycur IS REF CURSOR;

      c           emptycur;
      dl          DATE;
      codcat      NUMBER (9);
      area_inte   NUMBER (11, 2);
   BEGIN
      IF datal IS NULL
      THEN
         dl := SYSDATE;
      ELSE
         dl := datal;
      END IF;

      IF tipocat = 'POLYGON'
      THEN
         IF areatrasc < 0
         THEN
            OPEN c FOR    'SELECT '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || ') AS COD, NULL AS AGGRSHP FROM '
                       || nometab
                       || ' A WHERE A.ID_CAT='
                       || TRIM (TO_CHAR (idc))
                       || ' AND A.'
                       || nome_campoid
                       || '='
                       || TRIM (TO_CHAR (catserow))
                       || ' AND SDO_RELATE(A.SHAPE, :2, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || ')' USING shp_part;
         ELSE
            OPEN c FOR    'SELECT COD, SDO_GEOM.SDO_AREA(AGGRSHP, 0.00005) FROM (SELECT '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || ') AS COD, SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SDO_GEOM.SDO_INTERSECTION(SDO_TOOLS.REMOVE_DUPLICATE_POINTS(A.SHAPE), :1, 0.00005), 0.00005)) AS AGGRSHP FROM '
                       || nometab
                       || ' A WHERE A.ID_CAT='
                       || TRIM (TO_CHAR (idc))
                       || ' AND A.'
                       || nome_campoid
                       || '='
                       || TRIM (TO_CHAR (catserow))
                       || ' AND SDO_RELATE(A.SHAPE, :2, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY '
                       || nomefunzen
                       || '(A.'
                       || nomecod
                       || '))' USING shp_part, shp_part;
         END IF;
      ELSE
         OPEN c FOR    'SELECT '
                    || nomefunzen
                    || '(A.'
                    || nomecod
                    || '), NULL FROM '
                    || nometab
                    || ' A WHERE A.ID_CAT='
                    || TRIM (TO_CHAR (idc))
                    || ' AND A.'
                    || nome_campoid
                    || '='
                    || TRIM (TO_CHAR (catserow))
                    || ' AND SDO_RELATE(A.SHAPE, :1, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY '
                    || nomefunzen
                    || '(A.'
                    || nomecod
                    || '), NULL' USING shp_part;
      END IF;

      LOOP
         FETCH c
          INTO codcat, area_inte;

         EXIT WHEN c%NOTFOUND;

         IF areatrasc < 0
         THEN
            area_inte :=
               get_supe_gis (codnaz,
                             fog,
                             part,
                             subo,
                             TO_DATE ('99991231', 'YYYYMMDD'),
                             0
                            );

            INSERT INTO sitipart_cat
                        (id_cat, cod_nazionale, foglio, particella, sub,
                         data_inizio_val, data_fine_val,
                         data_lav, codice, supe_inte, cat_se_row_id
                        )
                 VALUES (idc, codnaz, fog, part, subo,
                         dl, TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS'),
                         dl, codcat, area_inte, catserow
                        );
         ELSE
            IF    (    tipocat = 'POLYGON'
                   AND area_inte / area_part * 100 >= areatrasc
                  )
               OR (tipocat <> 'POLYGON' AND area_inte IS NULL)
            THEN
               INSERT INTO sitipart_cat
                           (id_cat, cod_nazionale, foglio, particella, sub,
                            data_inizio_val,
                            data_fine_val,
                            data_lav, codice, supe_inte, cat_se_row_id
                           )
                    VALUES (idc, codnaz, fog, part, subo,
                            dl,
                            TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS'),
                            dl, codcat, area_inte, catserow
                           );
            END IF;
         END IF;
      END LOOP;

      CLOSE c;
   EXCEPTION
      WHEN OTHERS
      THEN
         NULL;
   END intersezioni_part_cat_active;

   PROCEDURE active_particella (
      idc        IN   NUMBER,
      datal      IN   DATE,
      catserow   IN   NUMBER,
      codnaz     IN   VARCHAR2,
      fog        IN   NUMBER,
      part       IN   VARCHAR2,
      subo       IN   VARCHAR2
   )
   IS
      TYPE emptycur IS REF CURSOR;

      c                  emptycur;
      dl                 DATE;
      nome_tabella       VARCHAR2 (30);
      nome_funz_encode   VARCHAR2 (70);
      nome_codice        VARCHAR2 (70);
      nome_campoid       VARCHAR2 (20);
      tipo_catalogo      VARCHAR2 (10);
      area_trascura      NUMBER (11, 2);
      the_codnaz         VARCHAR2 (4);
      the_fog            NUMBER (4);
      the_part           VARCHAR2 (5);
      the_subo           VARCHAR2 (3);
      shp                MDSYS.SDO_GEOMETRY;
      area_part          NUMBER (11, 2);
   BEGIN
      IF datal IS NULL
      THEN
         dl := SYSDATE;
      ELSE
         dl := datal;
      END IF;

      UPDATE sitipart_cat
         SET data_fine_val = dl - (1 / 24 / 60 / 60)
       WHERE cat_se_row_id = catserow
         AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
         AND cod_nazionale = codnaz
         AND foglio = fog
         AND particella = part
         AND sub = subo
         AND id_cat = idc;

      OPEN c FOR
         SELECT tabella, plencode, code_field, id_field, shape_type,
                supe_trascura
           FROM siticatalog
          WHERE id_cat = idc;

      FETCH c
       INTO nome_tabella, nome_funz_encode, nome_codice, nome_campoid,
            tipo_catalogo, area_trascura;

      IF c%NOTFOUND
      THEN
         nome_tabella := NULL;
         nome_funz_encode := NULL;
         nome_codice := NULL;
         nome_campoid := NULL;
         tipo_catalogo := NULL;
         area_trascura := NULL;
      END IF;

      CLOSE c;

      IF area_trascura < 0
      THEN
         OPEN c FOR    'SELECT B.COD_NAZIONALE, B.FOGLIO, B.PARTICELLA, B.SUB, B.SHAPE, NULL AS AREA_PART FROM '
                    || nome_tabella
                    || ' A, SITICENT B WHERE B.COD_NAZIONALE='''
                    || codnaz
                    || ''' AND B.FOGLIO='
                    || TO_CHAR (fog)
                    || ' AND B.PARTICELLA='''
                    || part
                    || ''' AND B.SUB='''
                    || subo
                    || ''' AND A.'
                    || nome_campoid
                    || '='
                    || TRIM (TO_CHAR (catserow))
                    || ' AND B.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND SDO_RELATE(B.SHAPE, A.SHAPE, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE''';
      ELSE
         OPEN c FOR    'SELECT B.COD_NAZIONALE, B.FOGLIO, B.PARTICELLA, B.SUB, SDO_TOOLS.REMOVE_DUPLICATE_POINTS(B.SHAPE), B.AREA_PART FROM '
                    || nome_tabella
                    || ' A, SITIPART B WHERE B.COD_NAZIONALE='''
                    || codnaz
                    || ''' AND B.FOGLIO='
                    || TO_CHAR (fog)
                    || ' AND B.PARTICELLA='''
                    || part
                    || ''' AND B.SUB='''
                    || subo
                    || ''' AND A.'
                    || nome_campoid
                    || '='
                    || TRIM (TO_CHAR (catserow))
                    || ' AND B.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND SDO_RELATE(B.SHAPE, A.SHAPE, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE''';
      END IF;

      LOOP
         FETCH c
          INTO the_codnaz, the_fog, the_part, the_subo, shp, area_part;

         EXIT WHEN (c%NOTFOUND);
         intersezioni_part_cat_active (nome_campoid,
                                       catserow,
                                       the_codnaz,
                                       the_fog,
                                       the_part,
                                       the_subo,
                                       dl,
                                       idc,
                                       nome_tabella,
                                       nome_funz_encode,
                                       nome_codice,
                                       tipo_catalogo,
                                       area_trascura,
                                       area_part,
                                       shp
                                      );
      END LOOP;

      CLOSE c;
   END active_particella;

   PROCEDURE assegnacodici_active (
      idc        IN   NUMBER,
      datal      IN   DATE,
      catserow   IN   NUMBER
   )
   IS
      TYPE emptycur IS REF CURSOR;

      c                  emptycur;
      c2                 emptycur;
      dl                 DATE;
      nome_tabella       VARCHAR2 (30);
      nome_funz_encode   VARCHAR2 (70);
      nome_codice        VARCHAR2 (70);
      nome_campoid       VARCHAR2 (20);
      tipo_catalogo      VARCHAR2 (10);
      area_trascura      NUMBER (11, 2);
      hasmbrcol          NUMBER (1);
      ctavola            NUMBER (4);
      ccomu              VARCHAR2 (4);
      codnaz             VARCHAR2 (4);
      fog                NUMBER (4);
      part               VARCHAR2 (5);
      subo               VARCHAR2 (3);
      shp                MDSYS.SDO_GEOMETRY;
      area_part          NUMBER (11, 2);
      conta              NUMBER             := 0;
   BEGIN
      IF datal IS NULL
      THEN
         dl := SYSDATE;
      ELSE
         dl := datal;
      END IF;

      UPDATE sitipart_cat
         SET data_fine_val = dl - (1 / 24 / 60 / 60)
       WHERE cat_se_row_id = catserow
         AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
         AND id_cat = idc;

      OPEN c FOR
         SELECT tabella, plencode, code_field, id_field, shape_type,
                supe_trascura, hasmbrcolumn
           FROM siticatalog
          WHERE id_cat = idc;

      FETCH c
       INTO nome_tabella, nome_funz_encode, nome_codice, nome_campoid,
            tipo_catalogo, area_trascura, hasmbrcol;

      IF c%NOTFOUND
      THEN
         nome_tabella := NULL;
         nome_funz_encode := NULL;
         nome_codice := NULL;
         nome_campoid := NULL;
         tipo_catalogo := NULL;
         area_trascura := NULL;
         hasmbrcol := NULL;
      END IF;

      CLOSE c;

      IF hasmbrcol > 0
      THEN
         OPEN c2 FOR    'SELECT B.COD_NAZIONALE, B.TAVOLA FROM '
                     || nome_tabella
                     || ' A, SITIFGLC B WHERE A.'
                     || nome_campoid
                     || '='
                     || TRIM (TO_CHAR (catserow))
                     || ' AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND SDO_RELATE(b.SHAPE,A.SHAPEMBR, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'' GROUP BY B.COD_NAZIONALE, B.TAVOLA';
      ELSE
         OPEN c2 FOR 'SELECT NULL,0 FROM DUAL';
      END IF;

      LOOP
         FETCH c2
          INTO ccomu, ctavola;

         EXIT WHEN (c2%NOTFOUND);

         IF (ctavola = 0 AND ccomu IS NULL)
         THEN
            IF area_trascura < 0
            THEN
               OPEN c FOR    'SELECT B.COD_NAZIONALE, B.FOGLIO, B.PARTICELLA, B.SUB, B.SHAPE, NULL AS AREA_PART FROM '
                          || nome_tabella
                          || ' A, SITICENT B WHERE A.'
                          || nome_campoid
                          || '=:1 AND B.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND SDO_RELATE(B.SHAPE, A.SHAPE, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'''
               USING catserow;
            ELSE
               OPEN c FOR    'SELECT B.COD_NAZIONALE, B.FOGLIO, B.PARTICELLA, B.SUB, SDO_TOOLS.REMOVE_DUPLICATE_POINTS(B.SHAPE), B.AREA_PART FROM '
                          || nome_tabella
                          || ' A, SITIPART B WHERE A.'
                          || nome_campoid
                          || '=:1 AND B.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND SDO_RELATE(B.SHAPE, A.SHAPE, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE'''
               USING catserow;
            END IF;
         ELSE
            IF area_trascura < 0
            THEN
               OPEN c FOR    'SELECT B.COD_NAZIONALE, B.FOGLIO, B.PARTICELLA, B.SUB, B.SHAPE, NULL AS AREA_PART FROM '
                          || nome_tabella
                          || ' A, SITICENT B WHERE B.COD_NAZIONALE='''
                          || ccomu
                          || ''' AND B.TAVOLA='
                          || TO_CHAR (ctavola)
                          || ' AND A.'
                          || nome_campoid
                          || '='
                          || TRIM (TO_CHAR (catserow))
                          || ' AND B.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND SDO_RELATE(B.SHAPE, A.SHAPE, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE''';
            ELSE
               OPEN c FOR    'SELECT B.COD_NAZIONALE, B.FOGLIO, B.PARTICELLA, B.SUB, SDO_TOOLS.REMOVE_DUPLICATE_POINTS(B.SHAPE), B.AREA_PART FROM '
                          || nome_tabella
                          || ' A, SITIPART B WHERE B.COD_NAZIONALE='''
                          || ccomu
                          || ''' AND B.TAVOLA='
                          || TO_CHAR (ctavola)
                          || ' AND A.'
                          || nome_campoid
                          || '='
                          || TRIM (TO_CHAR (catserow))
                          || ' AND B.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND SDO_RELATE(B.SHAPE, A.SHAPE, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE''';
            END IF;
         END IF;

         LOOP
            FETCH c
             INTO codnaz, fog, part, subo, shp, area_part;

            EXIT WHEN (c%NOTFOUND);
            intersezioni_part_cat_active (nome_campoid,
                                          catserow,
                                          codnaz,
                                          fog,
                                          part,
                                          subo,
                                          dl,
                                          idc,
                                          nome_tabella,
                                          nome_funz_encode,
                                          nome_codice,
                                          tipo_catalogo,
                                          area_trascura,
                                          area_part,
                                          shp
                                         );
         /*conta := conta + 1;

         IF conta = 50
         THEN
            COMMIT;
            conta := 0;
         END IF;
         */
         END LOOP;

         CLOSE c;
      END LOOP;

      CLOSE c2;
   END assegnacodici_active;

   PROCEDURE assegnacodici_part (
      idc      IN   NUMBER,
      datal    IN   DATE,
      codnaz   IN   VARCHAR2,
      fog      IN   NUMBER,
      part     IN   VARCHAR2,
      subo     IN   VARCHAR2
   )
   IS
      TYPE emptycur IS REF CURSOR;

      c              emptycur;
      dl             DATE;
      nome_tabella   VARCHAR2 (30);
      nome_campoid   VARCHAR2 (20);
      catserow       NUMBER;
   BEGIN
      IF datal IS NULL
      THEN
         dl := SYSDATE;
      ELSE
         dl := datal;
      END IF;

      OPEN c FOR
         SELECT tabella, id_field
           FROM siticatalog
          WHERE id_cat = idc;

      FETCH c
       INTO nome_tabella, nome_campoid;

      IF c%NOTFOUND
      THEN
         nome_tabella := NULL;
         nome_campoid := NULL;
      END IF;

      CLOSE c;

      UPDATE sitipart_cat
         SET data_fine_val = dl - (1 / 24 / 60 / 60)
       WHERE cod_nazionale = codnaz
         AND foglio = fog
         AND particella = part
         AND sub = subo
         AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS')
         AND id_cat = idc;

      OPEN c FOR    'SELECT A.'
                 || nome_campoid
                 || ' FROM '
                 || nome_tabella
                 || ' A, SITIPART B WHERE B.COD_NAZIONALE='''
                 || codnaz
                 || ''' AND B.FOGLIO='
                 || TRIM (TO_CHAR (fog))
                 || ' AND B.PARTICELLA='''
                 || part
                 || ''' AND B.SUB='''
                 || subo
                 || ''' AND B.DATA_FINE_VAL=TO_DATE(''99991231000000'',''YYYYMMDDHH24MISS'') AND A.ID_CAT='
                 || TRIM (TO_CHAR (idc))
                 || ' AND A.DATA_FINE_VAL=TO_DATE(''99991231000000'', ''YYYYMMDDHH24MISS'') AND SDO_RELATE(A.SHAPE, B.SHAPE, ''MASK=ANYINTERACT QUERYTYPE=WINDOW'')=''TRUE''';

      LOOP
         FETCH c
          INTO catserow;

         EXIT WHEN (c%NOTFOUND);
         active_particella (idc, dl, catserow, codnaz, fog, part, subo);
      END LOOP;

      CLOSE c;
   END assegnacodici_part;
END catalog_data; 
/


DROP PACKAGE BODY SITI_H501.CENSUARIO;

CREATE OR REPLACE PACKAGE BODY SITI_H501.censuario AS

PROCEDURE CORREGGI_MILLESIMI(CO IN VARCHAR2, FO IN VARCHAR2,PA IN VARCHAR2,SU IN VARCHAR2,UTENTEMODI IN VARCHAR2,DATARIF IN DATE DEFAULT NULL)
IS
	DATAR 	DATE;
	SUPETOT NUMBER(12,2);
	MILLTOT	NUMBER (9);
	NUMUIU 	NUMBER(9);
	PKUI	NUMBER(9);
	SUPEUI	NUMBER(10,2);
	CURSOR C1 IS SELECT SUM(NVL(SUP_CAT,0)),COUNT(*),SUM(NVL(MILLESIMI_TERRENO,0)) FROM SITIUIU WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO_VAL <= DATAR AND DATA_FINE_VAL>=DATAR;
	CURSOR C2 IS SELECT PKID_UIU,SUP_CAT FROM SITIUIU WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO_VAL <= DATAR AND DATA_FINE_VAL>=DATAR;
BEGIN
	DATAR:=DATARIF;
	IF DATAR IS NULL THEN DATAR:=TO_DATE('99991231','YYYYMMDD'); END IF;

	OPEN C1;
	FETCH C1 INTO SUPETOT,NUMUIU,MILLTOT;
	IF C1%NOTFOUND THEN NUMUIU:=0; END IF;
	CLOSE C1;

	IF NUMUIU > 0 AND MILLTOT=0 THEN
		IF SUPETOT > 0 THEN
			OPEN C2;
			LOOP
				FETCH C2 INTO PKUI,SUPEUI;
				EXIT WHEN C2%NOTFOUND;
				IF SUPEUI>0 THEN
					UPDATE SITIUIU SET MILLESIMI_TERRENO=round((SUPEUI/SUPETOT)*1000) WHERE PKID_UIU=PKUI;
				ELSE
					UPDATE SITIUIU SET MILLESIMI_TERRENO=0 WHERE PKID_UIU=PKUI;
				END IF;
			END LOOP;
			CLOSE C2;
		ELSE
			UPDATE SITIUIU SET MILLESIMI_TERRENO=0 WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO_VAL <= DATAR AND DATA_FINE_VAL>=DATAR;
		END IF;
	END IF;

END CORREGGI_MILLESIMI;

FUNCTION INSERISCI_CATASTO(CO IN VARCHAR2, FO IN VARCHAR2,PA IN VARCHAR2,SU IN VARCHAR2,SUP IN VARCHAR2,DATA_PAR IN DATE,UTENTE_PAR IN VARCHAR2,REDDAGR_PAR IN VARCHAR2,REDDDOM_PAR IN VARCHAR2,IDFRAZ IN NUMBER,SUB_USOCIVICO IN VARCHAR2,QUALI_CAT IN NUMBER,CLASSE IN VARCHAR2,PARTITAT IN VARCHAR2,p_pk_atto number,  p_note VARCHAR2) RETURN NUMBER
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;

  IDP NUMBER;
  DAL DATE:=NULL;
  PRT VARCHAR2(7):=NULL;
  RND NUMBER:=NULL;
  CLS VARCHAR2(5);
BEGIN
  PRT := PARTITAT;
  RND :=0;
  IF PRT IS NULL THEN PRT:='0000000'; END IF;
  CLS:=CLASSE;
  IF LENGTH(CLS) < 2 THEN CLS := '00' || CLS; CLS:=SubStr(CLS,Length(CLS)-1); END IF;

  INSERT INTO SITITRKC
  (ID_TRASF,SIGLA_PROV, COD_NAZIONALE, FOGLIO,PARTICELLA, SUB, QUAL_CAT,CLASSE_TERRENO, AREA_PART, PARTITA, DATA_AGGI,
  RENDITA, ISTATP, UTENTE,  REDDITO_AGRARIO, REDDITO_DOMINICALE, SUB_UC,atto_ini, ANNOTAZIONI)
  VALUES (IDFRAZ,(SELECT SIGLA_PROV FROM SITICOMU WHERE COD_NAZIONALE=CO),CO,FO,PA,SU,QUALI_CAT,
  CLS,SUP,PRT,DATA_PAR,RND,(SELECT ISTATP FROM SITICOMU WHERE COD_NAZIONALE=CO), UTENTE_PAR, REDDAGR_PAR, REDDDOM_PAR,
  SUB_USOCIVICO, p_pk_atto, p_note);

  RETURN 0;

  EXCEPTION WHEN OTHERS THEN
  DBMS_OUTPUT.PUT_LINE ('ERRORE: ' || SQLERRM);
  RETURN SQLCODE;
END INSERISCI_CATASTO;

FUNCTION GETSUPECENS(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE,USOCIVICO IN VARCHAR2 DEFAULT 'Y') RETURN NUMBER
IS
  CURSOR C1 IS SELECT AREA_PART,SUB_UC FROM SITITRKC WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND DATA_AGGI <= DATAV AND DATA_FINE >= DATAV AND ROWNUM=1;
  CURSOR C2 IS SELECT Sum(AREA_PART) FROM SITITRKC WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB_UC=SUBA AND DATA_AGGI <= DATAV AND DATA_FINE >= DATAV GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB_UC;
  SUPERFI NUMBER(12,3);
  SUPERFIUC NUMBER(12,3);
  UCSUB VARCHAR2(3);
BEGIN
  OPEN C1;
  FETCH C1 INTO SUPERFI,UCSUB;
  IF C1%NOTFOUND THEN SUPERFI:=NULL; END IF;
  CLOSE C1;

  IF SUPERFI IS NOT NULL AND UCSUB IS NULL AND USOCIVICO='Y' THEN --POTREBBE AVERE DEI FIGLI USO-CIVICO
    OPEN C2;
    FETCH C2 INTO SUPERFIUC;
    IF C2%NOTFOUND THEN SUPERFIUC:=NULL; END IF;
    CLOSE C2;
    IF SUPERFIUC IS NOT NULL THEN
      SUPERFI:=Greatest(SUPERFI - SUPERFIUC,0);
    END IF;
  END IF;
  RETURN SUPERFI;
END;

FUNCTION GETSOMMAPORZIONI(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE) RETURN NUMBER
IS
  CURSOR C2 IS SELECT Sum(AREA_PART) FROM SITITRKC WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB_UC=SUBA AND DATA_AGGI <= DATAV AND DATA_FINE >= DATAV GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB_UC;
  SUPERFI NUMBER(12,3);
BEGIN
	OPEN C2;
	FETCH C2 INTO SUPERFI;
	IF C2%NOTFOUND THEN SUPERFI:=NULL; END IF;
	CLOSE C2;

	RETURN SUPERFI;
END;

FUNCTION GETSUPECENSVALI(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE) RETURN NUMBER
IS
	CURSOR C1 IS SELECT AREA_PART,DATA_INIZIO_VAL FROM SITIPART WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND DATA_INIZIO_VAL <= DATAV AND DATA_FINE_VAL >= DATAV;
	CURSOR C2 IS SELECT SUPE,DATA_INIZIO FROM SITICATA WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND DATA_INIZIO <= DATAV AND DATA_FINE >= DATAV;
	AGIS NUMBER(11,2);
	DGIS DATE;
	ACAT NUMBER(11,2);
	DCAT DATE;
BEGIN
	OPEN C1;
	FETCH C1 INTO AGIS,DGIS;
	IF C1%NOTFOUND THEN DGIS:=NULL;AGIS:=NULL; END IF;
	CLOSE C1;
	OPEN C2;
	FETCH C2 INTO ACAT,DCAT;
	IF C2%NOTFOUND THEN DCAT:=NULL;ACAT:=NULL; END IF;
	CLOSE C2;

	IF DGIS IS NULL OR DCAT > DGIS THEN
		RETURN ACAT;
	ELSE
		RETURN AGIS;
	END IF;
END;

FUNCTION GETDATAVALI(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_AGGI FROM SITITRKC WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND DATA_AGGI <= DATAV AND DATA_FINE >= DATAV AND ROWNUM=1;
  DATAVALI DATE;
BEGIN
  OPEN C1;
  FETCH C1 INTO DATAVALI;
  IF C1%NOTFOUND THEN DATAVALI:=NULL; END IF;
  CLOSE C1;
  RETURN DATAVALI;
END;

FUNCTION GETSUPECENS2(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE) RETURN NUMBER
IS
  supecens NUMBER(12,3);
BEGIN
  supecens:=getsupecens(cn, fog, part, suba, datav);
  IF supecens IS NULL THEN supecens:=-1; END IF;
  RETURN supecens;
END;

END CENSUARIO;
/


DROP PACKAGE BODY SITI_H501.CEN_UTILS;

CREATE OR REPLACE PACKAGE BODY SITI_H501.cen_utils AS

PROCEDURE SHIFTA_CEN(CODNAZ IN VARCHAR2,FOGO IN NUMBER,DELTAX IN NUMBER, DELTAY IN NUMBER)
IS
BEGIN
	UPDATE CENFILES SET SHAPE=SDO_TOOLS.OFFSET(SHAPE,DELTAX,DELTAY) WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOGO;
END SHIFTA_CEN;

FUNCTION SCADI_HEADER(CODNAZ IN VARCHAR2, FOG IN NUMBER,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_INIZIO_VAL,DATA_FINE_VAL,ID_CEN FROM CEN_HEADER WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO;
  CURSOR C2 IS SELECT DATA_INIZIO_VAL FROM CEN_HEADER WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL > DATA_INIZIO;

  INIZIO_VER DATE;
  FINE_VER DATE;
  SEROWIDATT NUMBER(9);
  INIZIO_VER_SUCC DATE;
  RETVAL DATE;  -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE
BEGIN

  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER,SEROWIDATT;
  IF C1%NOTFOUND THEN SEROWIDATT:= NULL; END IF;
  CLOSE C1;

  IF INIZIO_VER = DATA_INIZIO THEN
    IF DATA_FINE <  FINE_VER THEN raise_application_error(-20005, 'Scartato'); END IF;
    RAISE_APPLICATION_ERROR(-20001, 'SCARTATO');
  END IF;

  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> To_Date('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;

  IF NOT(SEROWIDATT IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
      UPDATE CEN_HEADER SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN WHERE ID_CEN = SEROWIDATT;
  END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;

  RETURN RETVAL;

END SCADI_HEADER;

PROCEDURE CARICA_CEN_FILE(CODNAZ IN VARCHAR2,FOGO IN NUMBER,DATARIF IN DATE, UTEN IN VARCHAR2)
IS
	TYPE EMPTYCUR IS REF CURSOR;
	C1 EMPTYCUR;

	CURSOR C2 IS SELECT FLAG_CATA,COD_PROVINCIA FROM SITICOMU WHERE COD_NAZIONALE=CODNAZ;

	FC NUMBER(1);
	IP NUMBER(3);
	ICEN NUMBER(9);
	FOG NUMBER(4);
	ALLE VARCHAR2(1);
	SVIL VARCHAR2(1);
	TAVO NUMBER(4);

	PA VARCHAR2(5);
	SU VARCHAR2(3);
	SHP MDSYS.SDO_GEOMETRY;
	SHPFO MDSYS.SDO_GEOMETRY;
	ESISTEFOGLIO NUMBER(9);

	CURSOR C3 IS SELECT PARTICELLA,SUB,SHAPE FROM CEN_PARTICELLA WHERE ID_CEN=ICEN;
	CURSOR C4 IS SELECT SHAPE FROM CEN_FOGLIO WHERE ID_CEN=ICEN;
	CURSOR C5 IS SELECT SE_ROW_ID FROM SITIFGLC WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=TAVO AND ALLEGATO=ALLE AND SVILUPPO=SVIL;
BEGIN
	OPEN C2;
	FETCH C2 INTO FC,IP;
	CLOSE C2;

	IF FOGO IS NOT NULL THEN
		OPEN C1 FOR SELECT ID_CEN,FOGLIO,ALLEGATO,SVILUPPO FROM CEN_HEADER WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOGO AND DATA_FINE_VAL=To_Date('99991231','YYYYMMDD');
	ELSE
		OPEN C1 FOR SELECT ID_CEN,FOGLIO,ALLEGATO,SVILUPPO FROM CEN_HEADER WHERE COD_NAZIONALE=CODNAZ AND DATA_FINE_VAL=To_Date('99991231','YYYYMMDD');
	END IF;
	LOOP
		FETCH C1 INTO ICEN,TAVO,ALLE,SVIL;
		EXIT WHEN C1%NOTFOUND;

		OPEN C4;
		FETCH C4 INTO SHPFO;
		IF C4%NOTFOUND THEN SHPFO:=NULL; END IF;
		CLOSE C4;

		IF SHPFO IS NOT NULL THEN
			OPEN C5;
			FETCH C5 INTO ESISTEFOGLIO;
			IF C5%NOTFOUND THEN ESISTEFOGLIO:=0; END IF;
			CLOSE C5;
		END IF;

		FOG:=TAVO;
		IF FC=1 THEN
			FOG:=Round((TAVO / 100)-0.5);
		END IF;
		IF FC=2 THEN
			FOG:=9999;
		END IF;

		-- 0 CARICO IL LIMITE DI FOGLIO
		IF SHPFO IS NOT NULL THEN
			IF ESISTEFOGLIO>0 THEN
				UPDATE SITIFGLC SET SHAPE=SHPFO,TIPO='A' WHERE SE_ROW_ID=ESISTEFOGLIO;
			ELSE
				INSERT INTO LOADF(cod_nazionale,foglio,allegato,sviluppo,data_cat,tipo,shape,istatp,tavola)
				VALUES(CODNAZ,FOG,ALLE,SVIL,To_Char(SYSDATE,'YYYYMM'),'A',SHPFO,IP,TAVO);
			END IF;
		END IF;

		-- 1 CARICO I CENTROIDI
		OPEN C3;
		LOOP
			FETCH C3 INTO PA,SU,SHP;
			EXIT WHEN C3%NOTFOUND;

			CARICA_CEN_PARTICELLA(IP,CODNAZ,FOG,TAVO,DATARIF,UTEN,PA,SU,SHP);
		END LOOP;
		CLOSE C3;
		-- 2 FACCIO SCADERE I CENTROIDI CHE NON ESISTONO IN CATASTO (X QUESTO FOGLIO)
		--UPDATE SITICENT A SET DATA_FINE_VAL=DATARIF + 1/24/60/60 WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=TAVO AND DATA_FINE_VAL = To_Date('99991231','YYYYMMDD') AND (SELECT 1 FROM SITICATA B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.FOGLIO=A.FOGLIO AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE = To_Date('99991231','YYYYMMDD') AND ROWNUM=1) IS NULL;
		-- 3 FACCIO SCADERE TUTTE LE PART SENZA CENT
		--UPDATE SITIPART A SET DATA_FINE_VAL=DATARIF + 1/24/60/60 WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=TAVO AND DATA_FINE_VAL = To_Date('99991231','YYYYMMDD') AND (SELECT 1 FROM SITICENT B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.TAVOLA=A.TAVOLA AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE_VAL = To_Date('99991231','YYYYMMDD') AND ROWNUM=1) IS NULL;
		-- 4 FACCIO SCADERE TUTTE LE PART CON IL CENT ESTERNO
		UPDATE SITIPART A SET DATA_FINE_VAL=DATARIF + 1/24/60/60,UTENTE_FINE='CENF' WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=TAVO AND DATA_FINE_VAL = To_Date('99991231','YYYYMMDD') AND (SELECT 1 FROM SITICENT B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.TAVOLA=A.TAVOLA AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE_VAL = To_Date('99991231','YYYYMMDD') AND SDO_GEOM.RELATE(A.SHAPE,'anyinteract',B.SHAPE,0.0005)='TRUE' AND ROWNUM=1) IS NULL;
		-- 5 FACCIO SCADERE TUTTE LE PART CON + DI UN CENTROIDE
		UPDATE SITIPART A SET DATA_FINE_VAL=DATARIF + 1/24/60/60,UTENTE_FINE='CENF' WHERE A.DATA_FINE_VAL = To_Date('99991231','YYYYMMDD') AND (COD_NAZIONALE,TAVOLA,PARTICELLA,SUB) IN
		(
			SELECT 	/*+ ORDERED */
			A.COD_NAZIONALE,A.TAVOLA,A.PARTICELLA,A.SUB
			FROM
			SITICENT B,SITIPART A
			WHERE
			A.COD_NAZIONALE=CODNAZ AND
			A.TAVOLA=TAVO AND
			A.DATA_FINE_VAL = To_Date('99991231','YYYYMMDD') AND
			B.COD_NAZIONALE=CODNAZ AND
			B.TAVOLA=TAVO AND
			B.DATA_FINE_VAL = To_Date('99991231','YYYYMMDD')
			AND SDO_RELATE(A.SHAPE, B.SHAPE, 'MASK=ANYINTERACT QUERYTYPE=JOIN')='TRUE'
			GROUP BY A.COD_NAZIONALE,A.TAVOLA,A.PARTICELLA,A.SUB
			HAVING Count(*) > 1
		);

		UPDATE CEN_HEADER SET CARICATO=1 WHERE ID_CEN=ICEN;

	END LOOP;
	CLOSE C1;
END CARICA_CEN_FILE;

PROCEDURE SCARICA_CEN_FILE(CODNAZ IN VARCHAR2,FOGO IN NUMBER,UTEN IN VARCHAR2)
IS
BEGIN

DELETE FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=FOGO AND UTENTE=UTEN;

UPDATE SITICENT SET DATA_FINE_VAL=TO_DATE('99991231','YYYYMMDD')
WHERE SE_ROW_ID IN
(
SELECT MAX(SE_ROW_ID) FROM SITICENT WHERE
(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB)
IN
(
	SELECT COD_NAZIONALE,FOGLIO,PARTICELLA,SUB FROM SITICENT
	WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=FOGO AND UTENTE_FINE=UTEN AND
	(COD_NAZIONALE,TAVOLA,PARTICELLA,SUB) NOT IN
		(
			SELECT COD_NAZIONALE,TAVOLA,PARTICELLA,SUB FROM SITICENT
			WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=FOGO AND DATA_FINE_VAL=TO_DATE('99991231','YYYYMMDD')
		)
)
GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB
);

UPDATE SITIPART SET DATA_FINE_VAL=TO_DATE('99991231','YYYYMMDD')
WHERE SE_ROW_ID IN
(
SELECT MAX(SE_ROW_ID) FROM SITIPART WHERE
(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB)
IN
(
	SELECT COD_NAZIONALE,FOGLIO,PARTICELLA,SUB FROM SITIPART
	WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=FOGO AND UTENTE_FINE=UTEN AND
	(COD_NAZIONALE,TAVOLA,PARTICELLA,SUB) NOT IN
		(
			SELECT COD_NAZIONALE,TAVOLA,PARTICELLA,SUB FROM SITIPART
			WHERE COD_NAZIONALE=CODNAZ AND TAVOLA=FOGO AND DATA_FINE_VAL=TO_DATE('99991231','YYYYMMDD')
		)
)
GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB
);

END SCARICA_CEN_FILE;

PROCEDURE CARICA_CEN_PARTICELLA(IP IN NUMBER, CODNAZ IN VARCHAR2, FOG IN NUMBER,TAV IN NUMBER, DATARIF IN DATE, UTEN IN VARCHAR2,PART IN VARCHAR2, SUBO IN VARCHAR2, SHP IN MDSYS.SDO_GEOMETRY)
IS
BEGIN
	INSERT INTO LOADC(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,DATA_LAV,UTENTE,DATA_INIZIO_VAL,SHAPE,ISTATP,SORGENTE,TAVOLA,CONTROLLI)
	VALUES(CODNAZ,FOG,PART,SUBO,DATARIF,UTEN,DATARIF,SHP,IP,9,TAV,1);

END CARICA_CEN_PARTICELLA;

PROCEDURE PROCESSA_PLAV_IMPOSTATO
IS
	CURSOR C1 IS SELECT COD_NAZIONALE,FOGLIO FROM CEN_HEADER WHERE (PLAV_IMPOSTATO!='Y' OR PLAV_IMPOSTATO IS NULL)  AND DATA_FINE_VAL=TO_DATE('99991231','YYYYMMDD');
BEGIN
	FOR C1R IN C1 LOOP
		UPDATE SITIPLAV SET COD_LAVORAZIONE=COD_LAVORAZIONE WHERE
		COD_NAZIONALE=C1R.COD_NAZIONALE AND FOGLIO=C1R.FOGLIO AND LAST=1;
	END LOOP;
	UPDATE CEN_HEADER SET PLAV_IMPOSTATO='Y' WHERE (PLAV_IMPOSTATO!='Y' OR PLAV_IMPOSTATO IS NULL);
	COMMIT;
END PROCESSA_PLAV_IMPOSTATO;

END;
/


DROP PACKAGE BODY SITI_H501.CHECK_GIS_DATA;

CREATE OR REPLACE PACKAGE BODY SITI_H501.check_gis_data AS

FUNCTION CENTROK(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER
IS
  CURSOR C0 IS SELECT SDO_RELATE(A.shape,B.SHAPE,'mask=anyinteract querytype=WINDOW') FROM SITIPART A,SITICENT B WHERE B.cod_nazionale=A.cod_nazionale AND B.foglio=A.foglio AND B.particella=A.particella AND B.sub=A.sub AND A.DATA_INIZIO_VAL <= DATACTRL AND A.DATA_FINE_VAL >= DATACTRL AND B.DATA_INIZIO_VAL <= DATACTRL AND B.DATA_FINE_VAL >= DATACTRL;
  RETVAL NUMBER;
  INTERSECA VARCHAR2(5);
BEGIN
  RETVAL:=0;
  OPEN C0;
  FETCH C0 INTO INTERSECA;
  CLOSE C0;

  IF INTERSECA<>'FALSE' THEN
    RETVAL:=1;
  END IF;

  RETURN RETVAL;
END CENTROK;

FUNCTION GET_LAVCAT(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATACTRL IN DATE) RETURN NUMBER
IS
CURSOR C1 IS SELECT MAX(ID_TRASF) FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL>=DATACTRL GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB;
CURSOR C2 IS SELECT ID_TRASF FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL>=DATACTRL;
CURSOR C3 IS SELECT ID_TRASF FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL>=DATACTRL;

IDTRLETTO NUMBER(9);

BEGIN

IDTRLETTO:=0;

OPEN C1;
FETCH C1 INTO IDTRLETTO;
IF C1%NOTFOUND THEN IDTRLETTO:=0; END IF;
CLOSE C1;
IF IDTRLETTO = 0 THEN
  OPEN C2;
  FETCH C2 INTO IDTRLETTO;
  IF C2%NOTFOUND THEN IDTRLETTO:=0; END IF;
  CLOSE C2;
  IF IDTRLETTO = 0 THEN
    OPEN C3;
    FETCH C3 INTO IDTRLETTO;
    IF C3%NOTFOUND THEN IDTRLETTO:=0; END IF;
    CLOSE C3;
  END IF;
END IF;

RETURN IDTRLETTO;
END GET_LAVCAT;

FUNCTION ANOMALIA1(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER IS
	CURSOR C1 IS SELECT Sum(AREA) FROM SITIUNAR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL >= DATACTRL AND TIPO_UNAR=1;
	CURSOR C2 IS SELECT Sum(AREA_COLT) FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL >= DATACTRL AND COD_VARIETA IN(410,413,412,411,414,415,416);
	SUPUV NUMBER(12,3);
	SUPPO NUMBER(12,3);
BEGIN
	OPEN C1;
	FETCH C1 INTO SUPUV;
	IF C1%NOTFOUND THEN SUPUV:=NULL; END IF;
	CLOSE C1;

	IF SUPUV IS NOT NULL THEN
		OPEN C2;
		FETCH C2 INTO SUPPO;
		IF C2%NOTFOUND THEN SUPPO:=0; END IF;
		CLOSE C2;

      IF ((SUPUV > SUPPO + LEAST(SUPPO * 0.1,10000)) OR (SUPUV < SUPPO - LEAST(SUPPO * 0.1,10000))) AND ((SUPUV-SUPPO > 100) OR (SUPPO-SUPUV > 100)) THEN
		RETURN 1;
	  END IF;
	END IF;

	RETURN 0;
END ANOMALIA1;

FUNCTION ANOMALIA2(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER IS
CURSOR C1 IS SELECT /*+ INDEX (SITIPART SITIPART_PK) */ 1 FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL >= DATACTRL AND ROWNUM=1;
CURSOR C2 IS SELECT 1 FROM SITIUTIL WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND COD_ELE=1 AND ROWNUM=1;

NUMGIS NUMBER(4);
SUPEUTIL NUMBER(12,3);
RETVAL NUMBER;

BEGIN

NUMGIS:=0;
SUPEUTIL:=0;
RETVAL:=0;

  OPEN C2;
  FETCH C2 INTO SUPEUTIL;
  IF C2%NOTFOUND THEN SUPEUTIL:=0; END IF;
  CLOSE C2;

  IF SUPEUTIL>0 THEN
    OPEN C1;
    FETCH C1 INTO NUMGIS;
    IF C1%NOTFOUND THEN NUMGIS:=0; END IF;
    CLOSE C1;
    IF NUMGIS = 0 THEN RETVAL:=1; END IF;
  END IF;
RETURN RETVAL;
END ANOMALIA2;

FUNCTION ANOMALIA3(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER
IS
   is_supero   NUMBER := 0;
BEGIN
      SELECT 1
        INTO is_supero
        FROM cons_supa_tab a
       WHERE a.cod_nazionale = codnaz
         AND a.foglio = fog
         AND a.particella = part
         AND a.sub = subal
         AND a.data_fine = TO_DATE ('99991231', 'YYYYMMDD')
         AND ROWNUM=1;

      RETURN is_supero;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RETURN 0;
      WHEN OTHERS
      THEN
         RETURN 0;
END ANOMALIA3;

FUNCTION ANOMALIA4(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER
IS
  perc NUMBER:=0;
BEGIN
  SELECT
  1
  INTO perc
  FROM cons_cons_tab
  WHERE cod_nazionale = codnaz
  AND foglio = fog
  AND particella = part
  AND sub = subal
  AND data_fine = TO_DATE ('99991231', 'YYYYMMDD')
  AND pk_cuaa < 999999999
  GROUP BY
  cod_nazionale,
  foglio,
  particella,
  sub
  HAVING
  SUM(perc_poss) < 100 AND SUM(perc_poss) > 0;

  IF perc > 0 THEN
    RETURN 1;
  ELSE
    RETURN 0;
  END IF;

   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RETURN 0;
      WHEN OTHERS
      THEN
         RETURN 0;
END ANOMALIA4;

