/*
  RITORNA:
  1=DISCORDANTI
  2=CENS=SI GIS=NO
  3=GIS=SI CENS=NO
  4=GIS=SI CENS=SCAD
  5=CENS=SI GIS=SCAD
  6=CENS=NO GIS=NO
*/
FUNCTION GISVSCENS(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER IS
CURSOR C1 IS SELECT /*+ INDEX (SITIPART SITIPART_PK) */ AREA_PART FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL >= DATACTRL;
CURSOR C2 IS SELECT SUPE FROM SITICATA WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO <= DATACTRL AND DATA_FINE >= DATACTRL;
CURSOR C3 IS SELECT /*+ INDEX (SITIPART SITIPART_PK) */ AREA_PART FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_FINE_VAL < DATACTRL;
CURSOR C4 IS SELECT SUPE FROM SITICATA WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_FINE < DATACTRL;

SUPEPART NUMBER(12,3):=0;
SUPECAT NUMBER(12,3):=0;
RETVAL NUMBER:=0;

BEGIN
  OPEN C2;
  FETCH C2 INTO SUPECAT;
  IF C2%NOTFOUND THEN SUPECAT:=NULL; END IF;
  CLOSE C2;

  OPEN C1;
  FETCH C1 INTO SUPEPART;
  IF C1%NOTFOUND THEN SUPEPART:=NULL; END IF;
  CLOSE C1;

  IF SUPECAT>0 AND SUPEPART > 0 THEN
      IF ((SUPEPART > SUPECAT + LEAST(SUPECAT * 0.1,10000)) OR (SUPEPART < SUPECAT - LEAST(SUPECAT * 0.1,10000))) AND ((SUPEPART-SUPECAT > 100) OR (SUPECAT-SUPEPART > 100)) THEN RETVAL:=1; END IF;
  ELSE
    IF SUPECAT IS NULL AND SUPEPART IS NULL THEN
      RETVAL:=6;
    ELSE
      IF SUPECAT >0 AND SUPEPART IS NULL THEN
        OPEN C3;
        FETCH C3 INTO SUPEPART;
        IF C3%NOTFOUND THEN SUPEPART:=NULL; END IF;
        CLOSE C3;

        IF SUPEPART IS NULL THEN
          RETVAL:=2;
        ELSE
          RETVAL:=5;
        END IF;
      ELSE
        IF SUPEPART >0 AND SUPECAT IS NULL THEN
          OPEN C4;
          FETCH C4 INTO SUPECAT;
          IF C4%NOTFOUND THEN SUPECAT:=NULL; END IF;
          CLOSE C4;

          IF SUPECAT IS NULL THEN
            RETVAL:=3;
          ELSE
            RETVAL:=4;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;
RETURN RETVAL;
END GISVSCENS;

FUNCTION ANOMALIA41(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER IS
CURSOR C1 IS SELECT /*+ INDEX (SITIPART SITIPART_PK) */ AREA_PART FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL >= DATACTRL;
CURSOR C2 IS SELECT /*+ INDEX (SITISUOLO SITISUOLO_PK) */ SUM(AREA_COLT) FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL >= DATACTRL GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB;
SUPEPART NUMBER(12,3) := 0;
SUPESUOLO NUMBER(12,3) := 0;
RETVAL NUMBER:=0;
BEGIN
  OPEN C2;
  FETCH C2 INTO SUPESUOLO;
  IF C2%NOTFOUND THEN SUPESUOLO:=0; END IF;
  CLOSE C2;

  IF SUPESUOLO>0 THEN
    OPEN C1;
    FETCH C1 INTO SUPEPART;
    IF C1%NOTFOUND THEN SUPEPART:=0; END IF;
    CLOSE C1;
    IF SUPEPART <> 0 THEN
      IF (SUPESUOLO > SUPEPART + LEAST(SUPEPART * 0.1,10000)) OR (SUPESUOLO < SUPEPART - LEAST(SUPEPART * 0.1,10000)) THEN RETVAL:=1; END IF;
    END IF;
  END IF;

  RETURN RETVAL;
END ANOMALIA41;

FUNCTION ANOMALIA42(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER IS
CURSOR C1 IS SELECT /*+ INDEX (SITISUOLO SITISUOLO_PK) */ 1 FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL >= DATACTRL AND (COD_UTIL=0 OR COD_UTIL IS NULL) AND ROWNUM=1 GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB;
NUMGIS NUMBER(4):=0;
RETVAL NUMBER(1):=0;
BEGIN
  OPEN C1;
  FETCH C1 INTO NUMGIS;
  IF C1%NOTFOUND THEN NUMGIS:=0; END IF;
  CLOSE C1;
  IF NUMGIS > 0 THEN RETVAL:=1; END IF;
  RETURN RETVAL;
END ANOMALIA42;

FUNCTION ANOMALIA43(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATACTRL IN DATE) RETURN NUMBER IS
CURSOR C1 IS SELECT /*+ INDEX (SITISUOLO SITISUOLO_PK) */ MAX(STATO_PROP) FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL>=DATACTRL GROUP BY COD_NAZIONALE,FOGLIO,PARTICELLA,SUB;
CURSOR C2 IS SELECT /*+ INDEX (SITIPART SITIPART_PK) */ STATO_PROP FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL>=DATACTRL;
CURSOR C3 IS SELECT /*+ INDEX (SITICENT SITICENT_PK) */ STATO_PROP FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATACTRL AND DATA_FINE_VAL>=DATACTRL;
STATO NUMBER(1):=0;
BEGIN
  OPEN C1;
  FETCH C1 INTO STATO;
  IF C1%NOTFOUND THEN STATO:=0; END IF;
  CLOSE C1;
  IF STATO = 0 THEN
    OPEN C2;
    FETCH C2 INTO STATO;
    IF C2%NOTFOUND THEN STATO:=0; END IF;
    CLOSE C2;
    IF STATO = 0 THEN
      OPEN C3;
      FETCH C3 INTO STATO;
      IF C3%NOTFOUND THEN STATO:=0; END IF;
      CLOSE C3;
    END IF;
  END IF;
  IF STATO >0 THEN STATO:=1; END IF;
  RETURN STATO;
END ANOMALIA43;

