CURSOR C1 IS SELECT 1 FROM SITICOND WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO <= DATACTRL AND DATA_FINE >= DATACTRL AND ROWNUM=1;
