FUNCTION ANOMALIA84(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER IS
CURSOR C1 IS SELECT 1 FROM sitiuiu A, siticivi_uiu B WHERE a.cod_nazionale = codnaz  AND A.foglio = fog  AND A.particella = part  AND A.sub = subal  AND A.data_fine_VAL = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS') AND A.PKID_UIU  =  b.PKID_UIU (+) AND b.PKID_UIU IS NULL AND ROWNUM=1;
RETVAL NUMBER:=0;
