  OPEN C1;
  FETCH C1 INTO RETVAL;
  IF C1%NOTFOUND THEN RETVAL:=0; END IF;
  CLOSE C1;

  RETURN RETVAL;
END ANOMALIA84;

FUNCTION ISANOMALA(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN NUMBER
IS
  CURSOR C1 IS SELECT 1 FROM SITICOND WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO <= DATACTRL AND DATA_FINE >= DATACTRL AND ROWNUM=1;
  CURSOR C2 IS SELECT 1 FROM SITICOND_IMM WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO <= DATACTRL AND DATA_FINE >= DATACTRL AND ROWNUM=1;
  INCONDT NUMBER;
  INCONDU NUMBER;

  ANOMALA NUMBER(9):=0;
BEGIN
  /*
  5,6,7,8,9,10 = 25,26,27,28,29,30 = 44,45,46 = 61,62 = 81,82 = GISVSCENS
  47 = 63 = 83 = NOTITOLARITA = ANOMALIA47
  */

  ANOMALA:=ANOMALA + GISVSCENS(CODNAZ,FOG,PART,SUBAL,DATACTRL);
  IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA41(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
  IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA42(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
  IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA43(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
  IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA84(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;

  IF ANOMALA=0 THEN
    OPEN C1;
    FETCH C1 INTO INCONDT;
    IF C1%NOTFOUND THEN INCONDT:=0; END IF;
    CLOSE C1;

    OPEN C2;
    FETCH C2 INTO INCONDU;
    IF C2%NOTFOUND THEN INCONDU:=0; END IF;
    CLOSE C2;

    IF INCONDT > 0 THEN
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA1(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA2(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA3(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA4(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
    END IF;
    IF INCONDU > 0 THEN
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA21(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA22(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA23(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
      IF ANOMALA=0 THEN    ANOMALA:=ANOMALA + ANOMALIA24(CODNAZ,FOG,PART,SUBAL,DATACTRL);  END IF;
    END IF;
    IF ANOMALA=0 AND (INCONDU + INCONDT = 0)  THEN    ANOMALA:=1;  END IF;
  END IF;

  IF ANOMALA>0 THEN
    RETURN 1;
  ELSE
    RETURN 0;
  END IF;
END ISANOMALA;

FUNCTION GETANOMALIE(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBAL IN VARCHAR2, DATACTRL IN DATE) RETURN VARCHAR2
IS
  CURSOR C1 IS SELECT 1 FROM SITICOND WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO <= DATACTRL AND DATA_FINE >= DATACTRL AND ROWNUM=1;
  CURSOR C2 IS SELECT 1 FROM SITICOND_IMM WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO <= DATACTRL AND DATA_FINE >= DATACTRL AND ROWNUM=1;
  INCONDT NUMBER;
  INCONDU NUMBER;
  ANOMALA VARCHAR2(1024):='(';
  GISCE NUMBER(2):=0;
BEGIN
  OPEN C1;
  FETCH C1 INTO INCONDT;
  IF C1%NOTFOUND THEN INCONDT:=0; END IF;
  CLOSE C1;

  OPEN C2;
  FETCH C2 INTO INCONDU;
  IF C2%NOTFOUND THEN INCONDU:=0; END IF;
  CLOSE C2;

  IF INCONDT > 0 THEN
    IF ANOMALIA1(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '1,';  END IF;
    IF ANOMALIA2(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '2,';  END IF;
    IF ANOMALIA3(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '3,';  END IF;
    IF ANOMALIA4(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '4,';  END IF;
  END IF;
  IF INCONDU > 0 THEN
    IF ANOMALIA21(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '21,';  END IF;
    IF ANOMALIA22(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '22,';  END IF;
    IF ANOMALIA23(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '23,';  END IF;
    IF ANOMALIA24(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '24,';  END IF;
  END IF;
  IF ANOMALIA41(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '41,';  END IF;
  IF ANOMALIA42(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '42,';  END IF;
  IF ANOMALIA43(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '43,';  END IF;
  IF ANOMALIA84(CODNAZ,FOG,PART,SUBAL,DATACTRL) = 1 THEN    ANOMALA:=ANOMALA || '84,';  END IF;

  IF INCONDU + INCONDT = 0 THEN    ANOMALA:=ANOMALA || '47,';  END IF;

  GISCE:=GISVSCENS(CODNAZ,FOG,PART,SUBAL,DATACTRL);
  IF GISCE=1 THEN ANOMALA:=ANOMALA || '5,';  END IF;
  IF GISCE=2 THEN ANOMALA:=ANOMALA || '8,';  END IF;
  IF GISCE=3 THEN ANOMALA:=ANOMALA || '6,';  END IF;
  IF GISCE=4 THEN ANOMALA:=ANOMALA || '7,';  END IF;
  IF GISCE=5 THEN ANOMALA:=ANOMALA || '9,';  END IF;
  IF GISCE=6 THEN ANOMALA:=ANOMALA || '10,';  END IF;

  IF ANOMALA != '(' THEN
    ANOMALA := SubStr(ANOMALA,1,Length(ANOMALA)-1) || ')';
  ELSE
    ANOMALA := '(0)';
  END IF;
  RETURN ANOMALA;
END GETANOMALIE;

END CHECK_GIS_DATA;

/


DROP PACKAGE BODY SITI_H501.CODFISC_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.codfisc_pck
IS
   FUNCTION get_cod_fisc (
      innome            IN   VARCHAR2,
      incognome         IN   VARCHAR2,
      data_nascita      IN   DATE,
      inluogo_nascita   IN   VARCHAR2,
      insesso           IN   VARCHAR2
   )
      RETURN VARCHAR2
   IS
      nome             VARCHAR2 (100);
      cognome          VARCHAR2 (100);
      luogo_nascita    VARCHAR2 (100);
      sesso            VARCHAR2 (100);
      codice_fiscale   VARCHAR2 (16);
      vocali           VARCHAR2 (100);
      consonanti       VARCHAR2 (100);
      i                INTEGER;
      cfn              VARCHAR2 (3);
      cfc              VARCHAR2 (3);
      cfa              VARCHAR2 (2);
      cfm              VARCHAR2 (1);
      cfg              VARCHAR2 (2);
      cfco             VARCHAR2 (1);
   BEGIN
      nome := UPPER (TRIM (innome));

      IF nome IS NULL
      THEN
         RETURN NULL;
      END IF;

      cognome := UPPER (TRIM (incognome));

      IF cognome IS NULL
      THEN
         RETURN NULL;
      END IF;

      IF data_nascita IS NULL
      THEN
         RETURN NULL;
      END IF;

      luogo_nascita := UPPER (TRIM (inluogo_nascita));

      IF luogo_nascita IS NULL
      THEN
         RETURN NULL;
      END IF;

      IF LENGTH (luogo_nascita) <> 4
      THEN
         RETURN NULL;
      END IF;

      /* controllo esistenza comune*/
      sesso := UPPER (TRIM (insesso));

      IF sesso IS NULL
      THEN
         RETURN NULL;
      END IF;

      IF LENGTH (sesso) <> 1
      THEN
         RETURN NULL;
      END IF;

      IF sesso <> 'M' AND sesso <> 'F'
      THEN
         RETURN NULL;
      END IF;

      analisi (cognome, vocali, consonanti);

      IF vocali IS NULL
      THEN
         RETURN NULL;
      END IF;

      i := LENGTH (consonanti);

      IF i >= 3
      THEN
         cfc := SUBSTR (consonanti, 1, 3);
      ELSIF i = 2
      THEN
         cfc := consonanti || SUBSTR (vocali, 1, 1);
      ELSIF i = 1
      THEN
         IF LENGTH (vocali) >= 2
         THEN
            cfc := consonanti || SUBSTR (vocali, 1, 2);
         ELSE
            cfc := consonanti || vocali || 'X';
         END IF;
      END IF;

      analisi (nome, vocali, consonanti);

      IF vocali IS NULL
      THEN
         RETURN NULL;
      END IF;

      i := LENGTH (consonanti);

      IF i > 3
      THEN
         cfn := SUBSTR (consonanti, 1, 1) || SUBSTR (consonanti, 3, 2);
      ELSIF i = 3
      THEN
         cfn := consonanti;
      ELSIF i = 2
      THEN
         cfn := consonanti || SUBSTR (vocali, 1, 1);
      ELSIF i = 1
      THEN
         IF LENGTH (vocali) >= 2
         THEN
            cfn := consonanti || SUBSTR (vocali, 1, 2);
         ELSE
            cfn := consonanti || vocali || 'X';
         END IF;
      END IF;

      cfa := TO_CHAR (data_nascita, 'YY');

      CASE TO_NUMBER (TO_CHAR (data_nascita, 'MM'))
         WHEN 1
         THEN
            cfm := 'A';
         WHEN 2
         THEN
            cfm := 'B';
         WHEN 3
         THEN
            cfm := 'C';
         WHEN 4
         THEN
            cfm := 'D';
         WHEN 5
         THEN
            cfm := 'E';
         WHEN 6
         THEN
            cfm := 'H';
         WHEN 7
         THEN
            cfm := 'L';
         WHEN 8
         THEN
            cfm := 'M';
         WHEN 9
         THEN
            cfm := 'P';
         WHEN 10
         THEN
            cfm := 'R';
         WHEN 11
         THEN
            cfm := 'S';
         WHEN 12
         THEN
            cfm := 'T';
      END CASE;

      IF sesso = 'F'
      THEN
         cfg := LPAD (TO_NUMBER (TO_CHAR (data_nascita, 'DD')) + 40, 2, '0');
      ELSE
         cfg := LPAD (TO_NUMBER (TO_CHAR (data_nascita, 'DD')), 2, '0');
      END IF;

      codice_fiscale := cfc || cfn || cfa || cfm || cfg || luogo_nascita;
      cfco := controllo (codice_fiscale);
      codice_fiscale := codice_fiscale || cfco;
      RETURN codice_fiscale;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN 'XXXXXXXXXXXXXXXX';
   END;

   PROCEDURE analisi (
      testo        IN       VARCHAR2,
      vocali       OUT      VARCHAR2,
      consonanti   OUT      VARCHAR2
   )
   IS
      i   INTEGER      := 0;
      t   VARCHAR2 (1) := '';
   BEGIN
      vocali := NULL;
      consonanti := NULL;

      WHILE i < LENGTH (testo)
      LOOP
         i := i + 1;
         t := SUBSTR (testo, i, 1);

         IF ASCII (t) >= 65 AND ASCII (t) <= 90
         THEN
            IF INSTR ('AEIOU', t) > 0
            THEN
               vocali := vocali || t;
            ELSE
               consonanti := consonanti || t;
            END IF;
         END IF;
      END LOOP;
   END;

   FUNCTION tab_a (c IN VARCHAR2)
      RETURN INTEGER
   IS
      i   INTEGER := 0;
   BEGIN
      CASE c
         WHEN '0'
         THEN
            i := 0;
         WHEN '1'
         THEN
            i := 1;
         WHEN '2'
         THEN
            i := 2;
         WHEN '3'
         THEN
            i := 3;
         WHEN '4'
         THEN
            i := 4;
         WHEN '5'
         THEN
            i := 5;
         WHEN '6'
         THEN
            i := 6;
         WHEN '7'
         THEN
            i := 7;
         WHEN '8'
         THEN
            i := 8;
         WHEN '9'
         THEN
            i := 9;
         WHEN 'A'
         THEN
            i := 0;
         WHEN 'B'
         THEN
            i := 1;
         WHEN 'C'
         THEN
            i := 2;
         WHEN 'D'
         THEN
            i := 3;
         WHEN 'E'
         THEN
            i := 4;
         WHEN 'F'
         THEN
            i := 5;
         WHEN 'G'
         THEN
            i := 6;
         WHEN 'H'
         THEN
            i := 7;
         WHEN 'I'
         THEN
            i := 8;
         WHEN 'J'
         THEN
            i := 9;
         WHEN 'K'
         THEN
            i := 10;
         WHEN 'L'
         THEN
            i := 11;
         WHEN 'M'
         THEN
            i := 12;
         WHEN 'N'
         THEN
            i := 13;
         WHEN 'O'
         THEN
            i := 14;
         WHEN 'P'
         THEN
            i := 15;
         WHEN 'Q'
         THEN
            i := 16;
         WHEN 'R'
         THEN
            i := 17;
         WHEN 'S'
         THEN
            i := 18;
         WHEN 'T'
         THEN
            i := 19;
         WHEN 'U'
         THEN
            i := 20;
         WHEN 'V'
         THEN
            i := 21;
         WHEN 'W'
         THEN
            i := 22;
         WHEN 'X'
         THEN
            i := 23;
         WHEN 'Y'
         THEN
            i := 24;
         WHEN 'Z'
         THEN
            i := 25;
      END CASE;

      RETURN i;
   END;

   FUNCTION tab_b (c IN VARCHAR2)
      RETURN INTEGER
   IS
      i   INTEGER := 0;
   BEGIN
      CASE c
         WHEN '0'
         THEN
            i := 1;
         WHEN '1'
         THEN
            i := 0;
         WHEN '2'
         THEN
            i := 5;
         WHEN '3'
         THEN
            i := 7;
         WHEN '4'
         THEN
            i := 9;
         WHEN '5'
         THEN
            i := 13;
         WHEN '6'
         THEN
            i := 15;
         WHEN '7'
         THEN
            i := 17;
         WHEN '8'
         THEN
            i := 19;
         WHEN '9'
         THEN
            i := 21;
         WHEN 'A'
         THEN
            i := 1;
         WHEN 'B'
         THEN
            i := 0;
         WHEN 'C'
         THEN
            i := 5;
         WHEN 'D'
         THEN
            i := 7;
         WHEN 'E'
         THEN
            i := 9;
         WHEN 'F'
         THEN
            i := 13;
         WHEN 'G'
         THEN
            i := 15;
         WHEN 'H'
         THEN
            i := 17;
         WHEN 'I'
         THEN
            i := 19;
         WHEN 'J'
         THEN
            i := 21;
         WHEN 'K'
         THEN
            i := 2;
         WHEN 'L'
         THEN
            i := 4;
         WHEN 'M'
         THEN
            i := 18;
         WHEN 'N'
         THEN
            i := 20;
         WHEN 'O'
         THEN
            i := 11;
         WHEN 'P'
         THEN
            i := 3;
         WHEN 'Q'
         THEN
            i := 6;
         WHEN 'R'
         THEN
            i := 8;
         WHEN 'S'
         THEN
            i := 12;
         WHEN 'T'
         THEN
            i := 14;
         WHEN 'U'
         THEN
            i := 16;
         WHEN 'V'
         THEN
            i := 10;
         WHEN 'W'
         THEN
            i := 22;
         WHEN 'X'
         THEN
            i := 25;
         WHEN 'Y'
         THEN
            i := 24;
         WHEN 'Z'
         THEN
            i := 23;
      END CASE;

      RETURN i;
   END;

   FUNCTION get_controllo (i IN INTEGER)
      RETURN VARCHAR2
   IS
   BEGIN
      RETURN CHR (i + 65);
   END;

   FUNCTION controllo (cf IN VARCHAR2)
      RETURN VARCHAR2
   IS
      i   INTEGER := 0;
      n   INTEGER := 0;
   BEGIN
      WHILE i < LENGTH (cf)
      LOOP
         i := i + 1;

         IF MOD (i, 2) = 0
         THEN
            n := n + tab_a (SUBSTR (cf, i, 1));
         ELSE
            n := n + tab_b (SUBSTR (cf, i, 1));
         END IF;
      END LOOP;

      n := MOD (n, 26);
      RETURN get_controllo (n);
   END;

   FUNCTION check_piva (inpiva IN VARCHAR2)
      RETURN INTEGER
   IS
      piva   VARCHAR2 (11);
      valp   INTEGER       := 0;
      vald   INTEGER       := 0;
      v      INTEGER       := 0;
      c      INTEGER       := 0;
   BEGIN
      IF TRIM (inpiva) IS NULL OR LENGTH (TRIM (inpiva)) <> 11
      THEN
         RETURN 0;
      END IF;

      piva := TRIM (inpiva);

      FOR i IN 1 .. 10
      LOOP
         IF MOD (i, 2) = 0
         THEN
            v := TO_NUMBER (SUBSTR (piva, i, 1)) * 2;

            IF v > 9
            THEN
               v := 1 + MOD (v, 10);
            END IF;

            valp := valp + v;
         ELSE
            vald := vald + TO_NUMBER (SUBSTR (piva, i, 1));
         END IF;
      END LOOP;

      c := MOD ((10 - MOD ((vald + valp), 10)), 10);

      IF c = TO_NUMBER (SUBSTR (piva, 11, 1))
      THEN
         RETURN 1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION check_cf (incf IN VARCHAR2)
      RETURN INTEGER
   IS
      cf   VARCHAR2 (16);
      c    VARCHAR2 (1);
   BEGIN
      IF TRIM (incf) IS NULL OR LENGTH (TRIM (incf)) <> 16
      THEN
         RETURN 0;
      END IF;

      cf := TRIM (incf);
      c := controllo (SUBSTR (cf, 1, 15));

      IF c = SUBSTR (cf, 16, 1)
      THEN
         RETURN 1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION get_sesso_from_cod_fisc (incf IN VARCHAR2)
      RETURN VARCHAR2
   IS
      n   INTEGER := 0;
   BEGIN
      IF TRIM (incf) IS NULL OR LENGTH (incf) <> 16
      THEN
         RETURN NULL;
      END IF;

      n := TO_NUMBER (SUBSTR (incf, 10, 2));

      IF n > 40
      THEN
         RETURN 'F';
      ELSE
         RETURN 'M';
      END IF;
   END;
END;

/


DROP PACKAGE BODY SITI_H501.CONSIP_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.Consip_Pck IS
  FUNCTION get_aggr_topo_pkid_uiu (pi_pkid_uiu NUMBER, pi_date DATE, pi_what INT)
    RETURN VARCHAR2 AS
    -- dato il codice della uiu cerca il codice del pkid_loc per la tabella AGGR_LOCALIZZA
    CURSOR cur_sitiloc_uiu (pi_pkid_uiu NUMBER, pi_date DATE) IS
      SELECT   fkid_type, pkid_loc
          FROM SITILOC_UIU kslu
         WHERE kslu.pkid_uiu = pi_pkid_uiu
           AND kslu.fkid_type = -1                                            -- solo numeri civici
           AND pi_date BETWEEN kslu.data_inizio_val AND kslu.data_fine_val    -- locazione uiu in corso di validita'
      ORDER BY kslu.principale DESC,                                          -- prima i record con Y e poi quelli con N
               kslu.data_fine_val DESC;

    -- dato il codice di localizzazione ritorna il codice nella tabella AGGR_TOPO
    CURSOR cur_aggr_localizza (pi_pkid_loc NUMBER, pi_date DATE) IS
      SELECT kal.pkid_topo, kal.nome
        FROM AGGR_LOCALIZZA kal
       WHERE kal.pkid_loc = pi_pkid_loc
         AND pi_date BETWEEN kal.data_inizio_val AND kal.data_fine_val;

    -- dato il codice del toponimo ritorna le info sulla via
    CURSOR cur_aggr_topo (pi_pkid_topo NUMBER, pi_date DATE) IS
      SELECT kat.nome, kat.cap
        FROM AGGR_TOPO kat
       WHERE kat.aggr_code = 1                                           -- via
         AND kat.pkid_topo = pi_pkid_topo
         AND pi_date BETWEEN kat.data_inizio_val AND kat.data_fine_val;

    fld_pkid_type                 NUMBER (9);
    fld_pkid_loc                  NUMBER (9);
    fld_pkid_topo                 NUMBER (9);
    fld_nome                      VARCHAR2 (200);
    fld_numero                    VARCHAR2 (100);
    fld_cap                       VARCHAR2 (5);
    str_retval                    VARCHAR2 (200);
  BEGIN
    -- pongo il valore di ritorno a null
    str_retval := NULL;

    OPEN cur_sitiloc_uiu (pi_pkid_uiu, pi_date);

    FETCH cur_sitiloc_uiu
     INTO fld_pkid_type, fld_pkid_loc;

    IF (cur_sitiloc_uiu%FOUND) THEN
      -- ho trovato il record della locazione
      -- ora devo cercare nella tabella aggr_localizza
      OPEN cur_aggr_localizza (fld_pkid_loc, pi_date);

      FETCH cur_aggr_localizza
       INTO fld_pkid_topo, fld_numero;

      IF (cur_aggr_localizza%FOUND) THEN
        OPEN cur_aggr_topo (fld_pkid_topo, pi_date);

        FETCH cur_aggr_topo
         INTO fld_nome, fld_cap;

        IF (cur_aggr_topo%FOUND) THEN
          CASE pi_what
            WHEN 1 THEN
              str_retval := fld_nome;
            WHEN 2 THEN
              str_retval := fld_numero;
            WHEN 3 THEN
              str_retval := fld_cap;
          END CASE;
        END IF;

        CLOSE cur_aggr_topo;
      END IF;

      CLOSE cur_aggr_localizza;
    END IF;

    CLOSE cur_sitiloc_uiu;

    RETURN str_retval;
  END get_aggr_topo_pkid_uiu;


  FUNCTION get_destinazione_uso (pi_categoria VARCHAR2)
    RETURN NUMBER AS
    i_retval                      NUMBER;
  BEGIN
 /*
 -    ND
 1 A01  ABITAZIONE DI TIPO SIGNORILE
 1 A02  ABITAZIONE DI TIPO CIVILE
 1 A03  ABITAZIONE DI TIPO ECONOMICO
 1 A04  ABITAZIONE DI TIPO POPOLARE
 1 A05  ABITAZIONE DI TIPO ULTRAPOPOLARE
 1 A06  ABITAZIONE DI TIPO RURALE, IN EFFETTI, TIPO RUSTICO
 1 A07  ABITAZIONE IN VILLINI
 1 A08  ABITAZIONE IN VILLE
 1 A09  CASTELLI, PALAZZI DI EMINENTI PREGI ARTISTICI E STORICI
 1 A11  ABITAZIONE ED ALLOGGI TIPICI DEI LUOGHI
 1 D10  RESIDENZE
 1 F01  AREA URBANA

 2 C06  STALLE, SCUDERIE, RIMESSE E AUTORIMESSE
 2 C07  TETTOIE CHIUSE ED APERTE

 3 B08  MAGAZZINI SOTTERRANEI PER DEPOSITO DERRATE
 3 C01  NEGOZI E BOTTEGHE
 3 C02  MAGAZZINI E LOCALI DI DEPOSITO
 3 D08  FABBRICATI COSTRUITI O ADATTATI PER SPECIALI ESIGENZE DI UNA ATTIVITA COMMERCIALE

 4 A10  UFFICI E STUDI PRIVATI
 4 D05  ISTITUTI DI CREDITO, CAMBIO ED ASSICURAZIONE

 5 C03  LABORATORI PER ARTI E MESTIERI
 5 D01  OPIFICI
 5 D07  FABBRICATI COSTRUITI O ADATTATI PER SPECIALI ESIGENZE DI UNA ATTIVITA INDUSTRIALE

 6 C04  FABBRICATI E LOCALI PER ESERCIZI SPORTIVI
 6 C05  STABILIMENTI BALNEARI E DI ACQUE CURATIVE
 6 D02  ALBERGHI E PENSIONI
 6 D03  TEATRI, CINEMATOGRAFI, SALE PER CONCERTI E SIMILI
 6 D06  FABBRICATI E LOCALI PER ESERCIZI SPORTIVI
 6 D12  POSTI BARCA IN PORTI TURISTICI, STABILIMENTI BALNEARI

 7 B01  COLLEGGI E CONVITTI EDUCANDATI, RICOVERI, ORFANATROFI, OSPIZI, CONVENTI, SEMINARI E CASERME
 7 B02  CASE DI CURA ED OSPEDALI
 7 B03  PRIGIONI E RIFORMATORI
 7 B04  UFFICI PUBBLICI
 7 B05  SCUOLE, LABORATORI SCIENTIFICI
 7 B06  BIBLIOTECHE, PINACOTECHE, MUSEI, GALLERIE, ACCADEMIE CHE NON HANNO SEDE IN EDIFICI DELLA CATEGORIA A/9
 7 B07  CAPPELLE ED ORATORI NON DESTINATI ALL'ESERCIZIO PUBBLICO DEI CULTI
 7 D04  CASE DI CURA ED OSPEDALI
 7 D11  SCUOLE E LABORATORI SCIENTIFICI PRIVATI
 7 E03  COSTRUZIONI E FABBRICATI PER SPECIALI ESIGENZE PUBBLICHE
 7 E04  RECINTI CHIUSI PER SPECIALI ESIGENZE PUBBLICHE
 7 E07  FABBRICATI DESTINATI ALL'USO PUBBLICO DEI CULTI
 7 E08  FABBRICATI E COSTRUZIONI NEI CIMITERI, ESCLUSI I COLOMBARI, I SEPOLCRI, E LE TOMBE DI FAMIGLIA
 7 E09  EDIFICI A DESTINAZIONE PARTICOLARE NON COMPRESI NELLE CATEGORIE PRECEDENTI DEL GRUPPO E

 8 D09  EDIFICI GALLEGGIANTI O SOSPESI, ASSICURATI A PUNTI FISSI AL SUOLO: PONTI PRIVATI SOGGETTI A PEDAGGIO
 8 E01  STAZIONI PER SERVIZIO DI TRASPORTO TERRESTRE, MARITTIMO ED AEREO
 8 E02  PONTI COMUNALI E PROVINCIALI SOGGETTI A PEDAGIO
 8 E05  FABBRICATI COSTITUENTI FORTIFICAZIONI E LORO DIPENDENZE
 8 E06  FARI, SEMAFORI, TORRI PER RENDERE D'USO PUBBLICO L'OROLOGIO COMUNALE
 8 F02  UNITA' COLLABENTI
 8 F03  UNITA' IN CORSO DI COSTRUZIONE
 8 F04  UNITA' IN CORSO DI DEFINIZIONE
 8 F05  LASTRICO SOLARE
 */
    IF (pi_categoria IN ('A01', 'A02', 'A03', 'A04', 'A05', 'A06', 'A07', 'A08', 'A09', 'A11', 'D10', 'F01')) THEN
      i_retval := 1;
    ELSE
      IF (pi_categoria IN ('C06', 'C07')) THEN
        i_retval := 2;
      ELSE
        IF (pi_categoria IN ('B08', 'C01', 'C02', 'D08')) THEN
          i_retval := 3;
        ELSE
          IF (pi_categoria IN ('A10', 'D05')) THEN
            i_retval := 4;
          ELSE
            IF (pi_categoria IN ('C03', 'D01', 'D07')) THEN
              i_retval := 5;
            ELSE
              IF (pi_categoria IN ('C04', 'C05', 'D02', 'D03', 'D06', 'D12')) THEN
                i_retval := 6;
              ELSE
                IF (pi_categoria IN
                      ('B01', 'B02', 'B03', 'B04', 'B05', 'B06', 'B07', 'D04', 'D11', 'E03', 'E04', 'E07', 'E08', 'E09')
                   ) THEN
                  i_retval := 7;
                ELSE
                  i_retval := 8;
                END IF;
              END IF;
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    RETURN i_retval;
  END get_destinazione_uso;



  FUNCTION get_aggr_topo_cap (pi_str_cod_naz VARCHAR2)
    RETURN VARCHAR2 AS
    CURSOR cur_aggr_topo (pi_str_cod_naz VARCHAR2) IS
      SELECT   kat.cap
          FROM AGGR_TOPO kat
         WHERE kat.aggr_code = 1                                                                                 -- via
           AND kat.cod_nazionale = pi_str_cod_naz
      ORDER BY cap NULLS LAST;

    fld_cap                       VARCHAR2 (5);
    str_retval                    VARCHAR2 (200);
  BEGIN
    -- pongo il valore di ritorno a null
    str_retval := NULL;

    OPEN cur_aggr_topo (pi_str_cod_naz);

    FETCH cur_aggr_topo
     INTO fld_cap;

    IF (cur_aggr_topo%FOUND) THEN
      str_retval := fld_cap;
    END IF;

    CLOSE cur_aggr_topo;

    RETURN str_retval;
  END get_aggr_topo_cap;
END Consip_Pck;
/


DROP PACKAGE BODY SITI_H501.CONSTERR;

CREATE OR REPLACE PACKAGE BODY SITI_H501.consterr
AS
   PROCEDURE RISOLVI_SUPERO (PKSUPA IN NUMBER)
   IS
      CURSOR C1
      IS
         SELECT PK_CUAA, PERC_POSS, PERC_AFFI, PKID_ATTO, UTENTE
           FROM CONS_SUAZ_TAB
          WHERE PKID_SUPA = PKSUPA;

      CURSOR C2
      IS
         SELECT COD_NAZIONALE, FOGLIO, PARTICELLA, SUB
           FROM CONS_SUPA_TAB
          WHERE PKID_SUPA = PKSUPA;

      CO          VARCHAR2 (4);
      FO          NUMBER;
      PA          VARCHAR2 (5);
      SU          VARCHAR2 (3);
      PKCO        NUMBER;
      PPOSS       NUMBER;
      PAFFI       NUMBER;
      PKATTO      NUMBER;
      CODUTENTE   VARCHAR2 (50);
      PSPOSS      NUMBER;
      PSAFFI      NUMBER;
      TOT_POSS    NUMBER;
      TOT_AFFI    NUMBER;
      DINIPROP    DATE;
      DINIAFFI    DATE;
      DINISUPE    DATE;

      CURSOR C3
      IS
         SELECT PERC_POSS
           FROM CONS_CONS_TAB
          WHERE PK_CUAA = PKCO
            AND COD_NAZIONALE = CO
            AND FOGLIO = FO
            AND PARTICELLA = PA
            AND SUB = SU
            AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

      CURSOR C4
      IS
         SELECT PERC_POSS
           FROM CONS_UFRE_TAB
          WHERE PK_CUAA = PKCO
            AND COD_NAZIONALE = CO
            AND FOGLIO = FO
            AND PARTICELLA = PA
            AND SUB = SU
            AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

      CURSOR C5
      IS
         SELECT SUM (PERC_POSS), MAX (DATA_INIZIO)
           FROM CONS_CONS_TAB
          WHERE COD_NAZIONALE = CO
            AND FOGLIO = FO
            AND PARTICELLA = PA
            AND SUB = SU
            AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

      CURSOR C6
      IS
         SELECT SUM (PERC_POSS), MAX (DATA_INIZIO)
           FROM CONS_UFRE_TAB
          WHERE COD_NAZIONALE = CO
            AND FOGLIO = FO
            AND PARTICELLA = PA
            AND SUB = SU
            AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

      CURSOR C7
      IS
         SELECT MAX (DATA_INIZIO)
           FROM CONS_SUAZ_TAB
          WHERE PKID_SUPA = PKSUPA;
   BEGIN
      OPEN C2;

      FETCH C2
       INTO CO, FO, PA, SU;

      IF C2%NOTFOUND
      THEN
         CO := NULL;
      END IF;

      CLOSE C2;

      IF CO IS NULL
      THEN
         RAISE_APPLICATION_ERROR
                             (-20001,
                              'PARTICELLA NON TROVATA NELL`ELENCO DEI SUPERI'
                             );
      END IF;

      OPEN C5;

      FETCH C5
       INTO TOT_POSS, DINIPROP;

      IF C5%NOTFOUND
      THEN
         TOT_POSS := 0;
      END IF;

      CLOSE C5;

      OPEN C6;

      FETCH C6
       INTO TOT_AFFI, DINIAFFI;

      IF C6%NOTFOUND
      THEN
         TOT_AFFI := 0;
      END IF;

      CLOSE C6;

      OPEN C7;

      FETCH C7
       INTO DINISUPE;

      CLOSE C7;

      IF DINISUPE <= DINIAFFI OR DINISUPE <= DINIPROP
      THEN
         DINISUPE := DINIPROP + 1 / 24 / 60 / 60;                -- 1 SECONDO

         IF DINISUPE <= DINIAFFI
         THEN
            DINISUPE := DINIAFFI + 1 / 24 / 60 / 60;             -- 1 SECONDO
         END IF;
      END IF;

      OPEN C1;

      LOOP
         FETCH C1
          INTO PKCO, PSPOSS, PSAFFI, PKATTO, CODUTENTE;

         EXIT WHEN C1%NOTFOUND;

         OPEN C3;

         FETCH C3
          INTO PPOSS;

         IF C3%NOTFOUND
         THEN
            PPOSS := 0;
         END IF;

         CLOSE C3;

         OPEN C4;

         FETCH C4
          INTO PAFFI;

         IF C4%NOTFOUND
         THEN
            PAFFI := 0;
         END IF;

         CLOSE C4;

         TOT_POSS := (TOT_POSS - PPOSS) + PSPOSS;
         TOT_AFFI := (TOT_AFFI - PAFFI) + PSAFFI;
      END LOOP;

      CLOSE C1;

      IF TOT_POSS > 100.5 OR TOT_AFFI > 100.5
      THEN
         RAISE_APPLICATION_ERROR
            (-20002,
             'IL SUPERO NON E RISOLVIBILE PERCHE LE PERCENTUALI RICHIESTE SUPERANO IL 100%'
            );
      END IF;

      UPDATE CONS_CONS_TAB
         SET DATA_FINE = DINISUPE
       WHERE PK_CUAA = 999999999
         AND COD_NAZIONALE = CO
         AND FOGLIO = FO
         AND PARTICELLA = PA
         AND SUB = SU
         AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

      UPDATE CONS_UFRE_TAB
         SET DATA_FINE = DINISUPE
       WHERE PK_CUAA = 999999999
         AND COD_NAZIONALE = CO
         AND FOGLIO = FO
         AND PARTICELLA = PA
         AND SUB = SU
         AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

      OPEN C1;

      LOOP
         FETCH C1
          INTO PKCO, PSPOSS, PSAFFI, PKATTO, CODUTENTE;

         EXIT WHEN C1%NOTFOUND;

         UPDATE CONS_CONS_TAB
            SET DATA_FINE = DINISUPE
          WHERE PK_CUAA = PKCO
            AND COD_NAZIONALE = CO
            AND FOGLIO = FO
            AND PARTICELLA = PA
            AND SUB = SU
            AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

         UPDATE CONS_UFRE_TAB
            SET DATA_FINE = DINISUPE
          WHERE PK_CUAA = PKCO
            AND COD_NAZIONALE = CO
            AND FOGLIO = FO
            AND PARTICELLA = PA
            AND SUB = SU
            AND DATA_FINE = TO_DATE ('99991231', 'YYYYMMDD');

         IF PSPOSS > 0
         THEN
            INSERT INTO CONS_CONS_TAB
                        (PKID_CONS, COD_NAZIONALE, FOGLIO, ALLEGATO,
                         SVILUPPO, PARTICELLA, SUB, PERC_POSS, TIPO_TITOLO,
                         DATA_REGISTRAZIONE, UTENTE, "TIMESTAMP",
                         PK_CUAA, DATA_INIZIO,
                         DATA_FINE, atto_ini
                        )
                 VALUES (CONS_CONS_SEQ.NEXTVAL, CO, FO, '0',
                         '0', PA, SU, PSPOSS, '1',
                         DINISUPE + 1 / 24 / 60 / 60, CODUTENTE, SYSDATE,
                         PKCO, DINISUPE + 1 / 24 / 60 / 60,
                         TO_DATE ('99991231', 'YYYYMMDD'), PKATTO
                        );
         END IF;

         IF PSAFFI > 0
         THEN
            INSERT INTO CONS_UFRE_TAB
                        (PKID_UFFR, COD_NAZIONALE, FOGLIO, ALLEGATO,
                         SVILUPPO, PARTICELLA, SUB, PERC_POSS, TIPO_TITOLO,
                         DATA_REGISTRAZIONE, UTENTE, "TIMESTAMP",
                         PK_CUAA, DATA_INIZIO,
                         DATA_FINE, atto_ini
                        )
                 VALUES (CONS_UFRE_SEQ.NEXTVAL, CO, FO, '0',
                         '0', PA, SU, PSAFFI, '2',
                         DINISUPE + 1 / 24 / 60 / 60, CODUTENTE, SYSDATE,
                         PKCO, DINISUPE + 1 / 24 / 60 / 60,
                         TO_DATE ('99991231', 'YYYYMMDD'), PKATTO
                        );
         END IF;
      END LOOP;

      CLOSE C1;

      UPDATE CONS_SUAZ_TAB
         SET DATA_FINE = DINISUPE
       WHERE PKID_SUPA = PKSUPA;

      UPDATE CONS_SUPA_TAB
         SET DATA_FINE = DINISUPE
       WHERE PKID_SUPA = PKSUPA;
   END RISOLVI_SUPERO;

   PROCEDURE CEDI_TITOLARITA (
      PKCUAA_CEDENTE      IN   NUMBER,
      PKCUAA_ACQUIRENTE   IN   NUMBER,
      STORE_UNDO          IN   CHAR DEFAULT 'N'
   )
   IS
      CUAACEDENTE     CONS_AZIE_TAB.CUAA%TYPE;
      CUAAACQUIRENTE  CONS_AZIE_TAB.CUAA%TYPE;
      DT              DATE;
   BEGIN
      CEDI_TITOLARITA_PROP_TERR (PKCUAA_CEDENTE, PKCUAA_ACQUIRENTE);
      CEDI_TITOLARITA_AFFI_TERR (PKCUAA_CEDENTE, PKCUAA_ACQUIRENTE);
      CEDI_TITOLARITA_PROP_IMMO (PKCUAA_CEDENTE, PKCUAA_ACQUIRENTE);
      CEDI_TITOLARITA_AFFI_IMMO (PKCUAA_CEDENTE, PKCUAA_ACQUIRENTE);

      --
      if (STORE_UNDO = 'Y') then
        INSERT INTO CONS_ATTI_TAB_UNDO
            SELECT PKCUAA_CEDENTE, PKID_ATTO
              FROM CONS_ATTI_TAB
             WHERE PK_CUAA = PKCUAA_CEDENTE;
      end if;

      UPDATE CONS_ATTI_TAB
         SET PK_CUAA = PKCUAA_ACQUIRENTE
       WHERE PK_CUAA = PKCUAA_CEDENTE;

      --
      if (STORE_UNDO = 'Y') then
        INSERT INTO CONS_SUAZ_TAB_UNDO
            SELECT PKCUAA_CEDENTE, PKID_SUAZ
              FROM CONS_SUAZ_TAB
             WHERE PK_CUAA = PKCUAA_CEDENTE;
      end if;

      UPDATE CONS_SUAZ_TAB
         SET PK_CUAA = PKCUAA_ACQUIRENTE
       WHERE PK_CUAA = PKCUAA_CEDENTE;

      --
      if (STORE_UNDO = 'Y') then
        INSERT INTO CONS_SUSU_TAB_UNDO
            SELECT PKCUAA_CEDENTE, PKID_SUSU
              FROM CONS_SUSU_TAB
             WHERE PK_CUAA = PKCUAA_CEDENTE;
      end if;

      UPDATE CONS_SUSU_TAB
         SET PK_CUAA = PKCUAA_ACQUIRENTE
       WHERE PK_CUAA = PKCUAA_CEDENTE;

      IF (STORE_UNDO = 'Y')
      THEN

         SELECT CUAA
           INTO CUAACEDENTE
           FROM CONS_AZIE_TAB
          WHERE PK_CUAA = PKCUAA_CEDENTE;

         SELECT CUAA
           INTO CUAAACQUIRENTE
           FROM CONS_AZIE_TAB
          WHERE PK_CUAA = PKCUAA_ACQUIRENTE;

         INSERT INTO CONS_AZIE_TAB_CAT (CUAA, COD_CAT, PK_CUAA) VALUES (CUAAACQUIRENTE, CUAACEDENTE, PKCUAA_CEDENTE);

          DT := SYSDATE;

         UPDATE anag_soggetti
            SET DATA_FINE_val = DT
          WHERE cod_soggetto  = PKCUAA_CEDENTE;

         UPDATE CONS_AZIE_TAB
            SET DATA_FINE = DT
          WHERE PK_CUAA = PKCUAA_CEDENTE;
      END IF;
   END CEDI_TITOLARITA;

   PROCEDURE CEDI_TITOLARITA_PROP_TERR (
      PKCUAA_CEDENTE      IN   NUMBER,
      PKCUAA_ACQUIRENTE   IN   NUMBER
   )
   IS
      TYPE EMPTYCUR IS REF CURSOR;

      C1                  EMPTYCUR;
      C2                  EMPTYCUR;
      PKID_CONS_CED       NUMBER (9);
      COD_NAZIONALE_CED   VARCHAR2 (4);
      FOGLIO_CED          NUMBER (4);
      PARTICELLA_CED      VARCHAR2 (5);
      SUB_CED             VARCHAR2 (3);
      PERC_POSS_CED       NUMBER (5, 2);
      PKID_ATTO_CED       NUMBER (9);
      DATA_FINE_CED       DATE;
      PKID_CONS_ACQ       NUMBER (9);
      PERC_POSS_ACQ       NUMBER (5, 2);
      PKID_ATTO_ACQ       NUMBER (9);
      PERC_POSS_NEW       NUMBER (5, 2);
      PKID_ATTO_REL_NEW   NUMBER (9);
   BEGIN
      OPEN C1 FOR
         SELECT PKID_CONS, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, PERC_POSS,
                atto_ini , DATA_FINE
           FROM CONS_CONS_TAB
          WHERE PK_CUAA = PKCUAA_CEDENTE;

      LOOP
         FETCH C1
          INTO PKID_CONS_CED, COD_NAZIONALE_CED, FOGLIO_CED, PARTICELLA_CED,
               SUB_CED, PERC_POSS_CED, PKID_ATTO_CED, DATA_FINE_CED;

         EXIT WHEN (C1%NOTFOUND);

         INSERT INTO CONS_CONS_TAB_UNDO (PKID_CONS, PK_CUAA) VALUES (PKID_CONS_CED, PKCUAA_CEDENTE);

         OPEN C2 FOR
            SELECT PKID_CONS, PERC_POSS, atto_ini
              FROM CONS_CONS_TAB
             WHERE COD_NAZIONALE = COD_NAZIONALE_CED
               AND FOGLIO = FOGLIO_CED
               AND PARTICELLA = PARTICELLA_CED
               AND SUB = SUB_CED
               AND DATA_FINE = DATA_FINE_CED
               AND PK_CUAA = PKCUAA_ACQUIRENTE;

         FETCH C2
          INTO PKID_CONS_ACQ, PERC_POSS_ACQ, PKID_ATTO_ACQ;

         IF C2%NOTFOUND
         THEN
            UPDATE CONS_CONS_TAB
               SET PK_CUAA = PKCUAA_ACQUIRENTE
             WHERE PKID_CONS = PKID_CONS_CED;
         ELSE
            PERC_POSS_NEW := PERC_POSS_CED + PERC_POSS_ACQ;
            PKID_ATTO_REL_NEW := AGGIORNA_ATTI (PKID_ATTO_CED, PKID_ATTO_ACQ);

            UPDATE CONS_CONS_TAB
               SET PERC_POSS = PERC_POSS_NEW,
                   atto_ini  = PKID_ATTO_REL_NEW
             WHERE PKID_CONS = PKID_CONS_ACQ;

            DELETE FROM CONS_CONS_TAB
                  WHERE PKID_CONS = PKID_CONS_CED;
         END IF;

         CLOSE C2;

      END LOOP;

      CLOSE C1;
   END CEDI_TITOLARITA_PROP_TERR;

   PROCEDURE CEDI_TITOLARITA_AFFI_TERR (
      PKCUAA_CEDENTE      IN   NUMBER,
      PKCUAA_ACQUIRENTE   IN   NUMBER
   )
   IS
      TYPE EMPTYCUR IS REF CURSOR;

      C1                  EMPTYCUR;
      C2                  EMPTYCUR;
      PKID_UFFR_CED       NUMBER (9);
      COD_NAZIONALE_CED   VARCHAR2 (4);
      FOGLIO_CED          NUMBER (4);
      PARTICELLA_CED      VARCHAR2 (5);
      SUB_CED             VARCHAR2 (3);
      PERC_POSS_CED       NUMBER (5, 2);
      PKID_ATTO_CED       NUMBER (9);
      DATA_FINE_CED       DATE;
      PKID_UFFR_ACQ       NUMBER (9);
      PERC_POSS_ACQ       NUMBER (5, 2);
      PKID_ATTO_ACQ       NUMBER (9);
      PERC_POSS_NEW       NUMBER (5, 2);
      PKID_ATTO_REL_NEW   NUMBER (9);
   BEGIN
      OPEN C1 FOR
         SELECT PKID_UFFR, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, PERC_POSS,
                atto_ini , DATA_FINE
           FROM CONS_UFRE_TAB
          WHERE PK_CUAA = PKCUAA_CEDENTE;

      LOOP
         FETCH C1
          INTO PKID_UFFR_CED, COD_NAZIONALE_CED, FOGLIO_CED, PARTICELLA_CED,
               SUB_CED, PERC_POSS_CED, PKID_ATTO_CED, DATA_FINE_CED;

         EXIT WHEN (C1%NOTFOUND);

         INSERT INTO CONS_UFRE_TAB_UNDO (PKID_UFRE, PK_CUAA) VALUES (PKID_UFFR_CED, PKCUAA_CEDENTE);

         OPEN C2 FOR
            SELECT PKID_UFFR, PERC_POSS, atto_ini
              FROM CONS_UFRE_TAB
             WHERE COD_NAZIONALE = COD_NAZIONALE_CED
               AND FOGLIO = FOGLIO_CED
               AND PARTICELLA = PARTICELLA_CED
               AND SUB = SUB_CED
               AND DATA_FINE = DATA_FINE_CED
               AND PK_CUAA = PKCUAA_ACQUIRENTE;

         FETCH C2
          INTO PKID_UFFR_ACQ, PERC_POSS_ACQ, PKID_ATTO_ACQ;

         IF C2%NOTFOUND
         THEN
            UPDATE CONS_UFRE_TAB
               SET PK_CUAA = PKCUAA_ACQUIRENTE
             WHERE PKID_UFFR = PKID_UFFR_CED;
         ELSE
            PERC_POSS_NEW := PERC_POSS_CED + PERC_POSS_ACQ;
            PKID_ATTO_REL_NEW := AGGIORNA_ATTI (PKID_ATTO_CED, PKID_ATTO_ACQ);

            UPDATE CONS_UFRE_TAB
               SET PERC_POSS = PERC_POSS_NEW,
                   atto_ini  = PKID_ATTO_REL_NEW
             WHERE PKID_UFFR = PKID_UFFR_ACQ;

            DELETE FROM CONS_UFRE_TAB
                  WHERE PKID_UFFR = PKID_UFFR_CED;
         END IF;

         CLOSE C2;
      END LOOP;

      CLOSE C1;
   END CEDI_TITOLARITA_AFFI_TERR;

   PROCEDURE CEDI_TITOLARITA_PROP_IMMO (
      PKCUAA_CEDENTE      IN   NUMBER,
      PKCUAA_ACQUIRENTE   IN   NUMBER
   )
   IS
      TYPE EMPTYCUR IS REF CURSOR;

      C1                  EMPTYCUR;
      C2                  EMPTYCUR;
      PKID_CSUI_CED       NUMBER (9);
      COD_NAZIONALE_CED   VARCHAR2 (4);
      FOGLIO_CED          NUMBER (4);
      PARTICELLA_CED      VARCHAR2 (5);
      SUB_CED             VARCHAR2 (3);
      UNIMM_CED           NUMBER (5);
      PERC_POSS_CED       NUMBER (5, 2);
      PKID_ATTO_CED       NUMBER (9);
      DATA_FINE_CED       DATE;
      PKID_CSUI_ACQ       NUMBER (9);
      PERC_POSS_ACQ       NUMBER (5, 2);
      PKID_ATTO_ACQ       NUMBER (9);
      PERC_POSS_NEW       NUMBER (5, 2);
      PKID_ATTO_REL_NEW   NUMBER (9);
   BEGIN
      OPEN C1 FOR
         SELECT PKID_CSUI, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, UNIMM,
                PERC_POSS, atto_ini , DATA_FINE
           FROM CONS_CSUI_TAB
          WHERE PK_CUAA = PKCUAA_CEDENTE;

      LOOP
         FETCH C1
          INTO PKID_CSUI_CED, COD_NAZIONALE_CED, FOGLIO_CED, PARTICELLA_CED,
               SUB_CED, UNIMM_CED, PERC_POSS_CED, PKID_ATTO_CED,
               DATA_FINE_CED;

         EXIT WHEN (C1%NOTFOUND);

         INSERT INTO CONS_CSUI_TAB_UNDO (PKID_CSUI, PK_CUAA) VALUES (PKID_CSUI_CED, PKCUAA_CEDENTE);

         OPEN C2 FOR
            SELECT PKID_CSUI, PERC_POSS, atto_ini
              FROM CONS_CSUI_TAB
             WHERE COD_NAZIONALE = COD_NAZIONALE_CED
               AND FOGLIO = FOGLIO_CED
               AND PARTICELLA = PARTICELLA_CED
               AND SUB = SUB_CED
               AND UNIMM = UNIMM_CED
               AND DATA_FINE = DATA_FINE_CED
               AND PK_CUAA = PKCUAA_ACQUIRENTE;

         FETCH C2
          INTO PKID_CSUI_ACQ, PERC_POSS_ACQ, PKID_ATTO_ACQ;

         IF C2%NOTFOUND
         THEN
            UPDATE CONS_CSUI_TAB
               SET PK_CUAA = PKCUAA_ACQUIRENTE
             WHERE PKID_CSUI = PKID_CSUI_CED;
         ELSE
            PERC_POSS_NEW := PERC_POSS_CED + PERC_POSS_ACQ;
            PKID_ATTO_REL_NEW := AGGIORNA_ATTI (PKID_ATTO_CED, PKID_ATTO_ACQ);

            UPDATE CONS_CSUI_TAB
               SET PERC_POSS = PERC_POSS_NEW,
                   atto_ini  = PKID_ATTO_REL_NEW
             WHERE PKID_CSUI = PKID_CSUI_ACQ;

            DELETE FROM CONS_CSUI_TAB
                  WHERE PKID_CSUI = PKID_CSUI_CED;
         END IF;

         CLOSE C2;
      END LOOP;

      CLOSE C1;
   END CEDI_TITOLARITA_PROP_IMMO;

   PROCEDURE CEDI_TITOLARITA_AFFI_IMMO (
      PKCUAA_CEDENTE      IN   NUMBER,
      PKCUAA_ACQUIRENTE   IN   NUMBER
   )
   IS
      TYPE EMPTYCUR IS REF CURSOR;

      C1                  EMPTYCUR;
      C2                  EMPTYCUR;
      PKID_URUI_CED       NUMBER (9);
      COD_NAZIONALE_CED   VARCHAR2 (4);
      FOGLIO_CED          NUMBER (4);
      PARTICELLA_CED      VARCHAR2 (5);
      SUB_CED             VARCHAR2 (3);
      UNIMM_CED           NUMBER (5);
      PERC_POSS_CED       NUMBER (5, 2);
      PKID_ATTO_CED       NUMBER (9);
      DATA_FINE_CED       DATE;
      PKID_URUI_ACQ       NUMBER (9);
      PERC_POSS_ACQ       NUMBER (5, 2);
      PKID_ATTO_ACQ       NUMBER (9);
      PERC_POSS_NEW       NUMBER (5, 2);
      PKID_ATTO_REL_NEW   NUMBER (9);
   BEGIN
      OPEN C1 FOR
         SELECT PKID_URUI, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, UNIMM,
                PERC_POSS, atto_ini, DATA_FINE
           FROM CONS_URUI_TAB
          WHERE PK_CUAA = PKCUAA_CEDENTE;

      LOOP
         FETCH C1
          INTO PKID_URUI_CED, COD_NAZIONALE_CED, FOGLIO_CED, PARTICELLA_CED,
               SUB_CED, UNIMM_CED, PERC_POSS_CED, PKID_ATTO_CED,
               DATA_FINE_CED;

         EXIT WHEN (C1%NOTFOUND);

         INSERT INTO CONS_URUI_TAB_UNDO (PKID_URUI, PK_CUAA) VALUES (PKID_URUI_CED, PKCUAA_CEDENTE);

         OPEN C2 FOR
            SELECT PKID_URUI, PERC_POSS, atto_ini
              FROM CONS_URUI_TAB
             WHERE COD_NAZIONALE = COD_NAZIONALE_CED
               AND FOGLIO = FOGLIO_CED
               AND PARTICELLA = PARTICELLA_CED
               AND SUB = SUB_CED
               AND UNIMM = UNIMM_CED
               AND DATA_FINE = DATA_FINE_CED
               AND PK_CUAA = PKCUAA_ACQUIRENTE;

         FETCH C2
          INTO PKID_URUI_ACQ, PERC_POSS_ACQ, PKID_ATTO_ACQ;

         IF C2%NOTFOUND
         THEN
            UPDATE CONS_URUI_TAB
               SET PK_CUAA = PKCUAA_ACQUIRENTE
             WHERE PKID_URUI = PKID_URUI_CED;
         ELSE
            PERC_POSS_NEW := PERC_POSS_CED + PERC_POSS_ACQ;
            PKID_ATTO_REL_NEW := AGGIORNA_ATTI (PKID_ATTO_CED, PKID_ATTO_ACQ);

            UPDATE CONS_URUI_TAB
               SET PERC_POSS = PERC_POSS_NEW,
                   atto_ini = PKID_ATTO_REL_NEW
             WHERE PKID_URUI = PKID_URUI_ACQ;

            DELETE FROM CONS_URUI_TAB
                  WHERE PKID_URUI = PKID_URUI_CED;
         END IF;

         CLOSE C2;
      END LOOP;

      CLOSE C1;
   END CEDI_TITOLARITA_AFFI_IMMO;

   FUNCTION AGGIORNA_ATTI (PKID_ATTO_CED IN NUMBER, PKID_ATTO_ACQ IN NUMBER)
      RETURN NUMBER
   IS
      TYPE EMPTYCUR IS REF CURSOR;

      C1                  EMPTYCUR;
      PKID_ATEX_NEW       NUMBER (9) := 0;
      PKID_ATTO_REL_NEW   NUMBER (9) := 0;
   BEGIN
      IF PKID_ATTO_CED = PKID_ATTO_ACQ
      THEN
         PKID_ATTO_REL_NEW := PKID_ATTO_ACQ;
      ELSIF PKID_ATTO_CED = 0 AND PKID_ATTO_ACQ <> 0
      THEN
         PKID_ATTO_REL_NEW := PKID_ATTO_ACQ;
      ELSIF PKID_ATTO_CED <> 0 AND PKID_ATTO_ACQ = 0
      THEN
         PKID_ATTO_REL_NEW := PKID_ATTO_CED;
      ELSIF PKID_ATTO_CED <> PKID_ATTO_ACQ
      THEN
         OPEN C1 FOR
            SELECT DISTINCT PKID_ATEX
                       FROM CONS_ATRL_TAB
                      WHERE PKID_ATTO IN (PKID_ATTO_CED, PKID_ATTO_ACQ);

         SELECT CONS_ATRL_SEQ.NEXTVAL
           INTO PKID_ATTO_REL_NEW
           FROM DUAL;

         LOOP
            FETCH C1
             INTO PKID_ATEX_NEW;

            EXIT WHEN C1%NOTFOUND;

            INSERT INTO CONS_ATRL_TAB
                        (PKID_ATTO, PKID_ATEX
                        )
                 VALUES (PKID_ATTO_REL_NEW, PKID_ATEX_NEW
                        );
         END LOOP;

         CLOSE C1;
      END IF;

      RETURN PKID_ATTO_REL_NEW;
   END AGGIORNA_ATTI;

FUNCTION GETSUPECOND(CO IN VARCHAR2,FO IN NUMBER,PA IN VARCHAR2,SU IN VARCHAR2,INPKCUAA IN VARCHAR2,DATARIF IN DATE,TIPOCOND IN NUMBER) RETURN NUMBER
IS
--CURSOR C1 IS SELECT CENSUARIO.GETSUPECENSVALI(CO, FO, PA, SU, DATARIF) FROM DUAL;
CURSOR C1 IS SELECT CENSUARIO.GETSUPECENS(CO, FO, PA, SU, DATARIF) FROM DUAL;
CURSOR C2 IS SELECT NVL(PERC_POSS, 0) FROM CONS_CONS_TAB WHERE PK_CUAA=INPKCUAA AND COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF;
CURSOR C3 IS SELECT NVL(SUM(PERC_POSS)/100, 0) FROM CONS_UFRE_TAB WHERE PK_CUAA>0 AND COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF;
CURSOR C4 IS SELECT NVL(PERC_POSS, 0) FROM CONS_UFRE_TAB WHERE PK_CUAA=INPKCUAA AND COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF;
SUPECATAVALI NUMBER;
PERCPOSS NUMBER(5,2);
PERCPOSSALTRI NUMBER(5,2);
SUPECOND NUMBER;
BEGIN
  OPEN C1;
  FETCH C1 INTO SUPECATAVALI;
  IF C1%NOTFOUND THEN SUPECATAVALI:=0; END IF;
  CLOSE C1;

  IF TIPOCOND=0 THEN
    OPEN C2;
    FETCH C2 INTO PERCPOSS;
    IF C2%NOTFOUND THEN PERCPOSS:=0; END IF;
    CLOSE C2;

    OPEN C3;
    FETCH C3 INTO PERCPOSSALTRI;
    IF C3%NOTFOUND THEN PERCPOSSALTRI:=0; END IF;
    CLOSE C3;

    SUPECOND:=(PERCPOSS / 100.0) * (SUPECATAVALI - (PERCPOSSALTRI * SUPECATAVALI));
  ELSE
    OPEN C4;
    FETCH C4 INTO PERCPOSS;
    IF C4%NOTFOUND THEN PERCPOSS:=0; END IF;
    CLOSE C4;

    SUPECOND:=SUPECATAVALI * (PERCPOSS / 100.0);
  END IF;

  RETURN SUPECOND;

-- 1) LEGGO SUPCAT GETSUPECENSVALI
-- 2.TIPOCOND 0) LEGGO PERCCOND(PROP,CUAA)
-- 3.TIPOCOND 0) LEGGO PERCCOND(AFFI,TUTTI)
-- 2.TIPOCOND 1) LEGGO PERCCOND(AFFI,CUAA)
END;

FUNCTION GETSUPECONDUIU(CO IN VARCHAR2,FO IN NUMBER,PA IN VARCHAR2,SU IN VARCHAR2,UN IN NUMBER,INPKCUAA IN VARCHAR2,DATARIF IN DATE,TIPOCOND IN NUMBER) RETURN NUMBER
IS
  CURSOR C1 IS SELECT SUP_CAT FROM SITIUIU WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND UNIMM=UN AND DATA_INIZIO_VAL <= DATARIF AND DATA_FINE_VAL >= DATARIF;
  CURSOR C2 IS SELECT NVL(PERC_POSS, 0) FROM CONS_CSUI_TAB WHERE PK_CUAA=INPKCUAA AND COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND UNIMM=UN AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF;
  CURSOR C3 IS SELECT NVL(SUM(PERC_POSS)/100, 0) FROM CONS_URUI_TAB WHERE PK_CUAA>0 AND COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND UNIMM=UN AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF;
  CURSOR C4 IS SELECT NVL(PERC_POSS, 0) FROM CONS_URUI_TAB WHERE PK_CUAA=INPKCUAA AND COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND UNIMM=UN AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF;
  SUPECATAVALI NUMBER;
  PERCPOSS NUMBER(5,2);
  PERCPOSSALTRI NUMBER(5,2);
  SUPECOND NUMBER;
BEGIN
  OPEN C1;
  FETCH C1 INTO SUPECATAVALI;
  IF C1%NOTFOUND THEN SUPECATAVALI:=0; END IF;
  CLOSE C1;

  IF TIPOCOND=0 THEN
    OPEN C2;
    FETCH C2 INTO PERCPOSS;
    IF C2%NOTFOUND THEN PERCPOSS:=0; END IF;
    CLOSE C2;

    OPEN C3;
    FETCH C3 INTO PERCPOSSALTRI;
    IF C3%NOTFOUND THEN PERCPOSSALTRI:=0; END IF;
    CLOSE C3;

    SUPECOND:=(PERCPOSS / 100.0) * (SUPECATAVALI - (PERCPOSSALTRI * SUPECATAVALI));
  ELSE
    OPEN C4;
    FETCH C4 INTO PERCPOSS;
    IF C4%NOTFOUND THEN PERCPOSS:=0; END IF;
    CLOSE C4;

    SUPECOND:=SUPECATAVALI * (PERCPOSS / 100.0);
  END IF;

  RETURN SUPECOND;

-- 1) LEGGO SUPCAT GETSUPECENSVALI
-- 2.TIPOCOND 0) LEGGO PERCCOND(PROP,CUAA)
-- 3.TIPOCOND 0) LEGGO PERCCOND(AFFI,TUTTI)
-- 2.TIPOCOND 1) LEGGO PERCCOND(AFFI,CUAA)
END;

FUNCTION GETDESCRBREVEANOM(LISTAANOM IN VARCHAR2) RETURN VARCHAR2
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;
  DESCR VARCHAR2(1024):='';
  DESCRANOM VARCHAR2(4096):='';
BEGIN

  OPEN C1 FOR 'SELECT DESCRBREVE FROM SITIANOM WHERE CODICE IN ' || LISTAANOM;
  LOOP
    FETCH C1 INTO DESCR;
    EXIT WHEN C1%NOTFOUND;
    DESCRANOM:=DESCRANOM || DESCR || ',';
  END LOOP;
  CLOSE C1;

  IF LENGTH(DESCRANOM)>0 THEN
    DESCRANOM:=SUBSTR(DESCRANOM, 0, LENGTH(DESCRANOM)-1);
  END IF;

  RETURN DESCRANOM;
  END;

FUNCTION GETAREAGIS(CO IN VARCHAR2,FO IN NUMBER,PA IN VARCHAR2,SU IN VARCHAR2, DATARIF IN DATE) RETURN NUMBER
IS
  CURSOR C1 IS SELECT AREA_PART FROM SITIPART WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO_VAL <= DATARIF AND DATA_FINE_VAL >= DATARIF AND ROWNUM=1;
  AREAGIS NUMBER(11,2):=-1;
BEGIN
  OPEN C1;
  FETCH C1 INTO AREAGIS;
  IF C1%NOTFOUND THEN AREAGIS:=-1; END IF;
  CLOSE C1;
  RETURN AREAGIS;
END;

FUNCTION GETDATAGIS(CO IN VARCHAR2,FO IN NUMBER,PA IN VARCHAR2,SU IN VARCHAR2, DATARIF IN DATE) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_INIZIO_VAL FROM SITIPART WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO_VAL <= DATARIF AND DATA_FINE_VAL >= DATARIF AND ROWNUM=1;
  DATAGIS DATE;
BEGIN
  OPEN C1;
  FETCH C1 INTO DATAGIS;
  IF C1%NOTFOUND THEN DATAGIS:=NULL; END IF;
  CLOSE C1;
  RETURN DATAGIS;
END;

FUNCTION GETNOMECOMUNE(CO IN VARCHAR2) RETURN VARCHAR2
IS
  CURSOR C1 IS SELECT NOME || ' (' || SIGLA_PROV || ')' FROM SITICOMU WHERE COD_NAZIONALE=CO AND ROWNUM=1;
  NOMECOM VARCHAR2(45):='';
BEGIN
  OPEN C1;
  FETCH C1 INTO NOMECOM;
  IF C1%NOTFOUND THEN NOMECOM:=''; END IF;
  CLOSE C1;
  RETURN NOMECOM;
END;

FUNCTION GETTOTSUPECOND(CO IN VARCHAR2,FO IN NUMBER,PA IN VARCHAR2,SU IN VARCHAR2,DATARIF IN DATE,TIPOCOND IN NUMBER) RETURN NUMBER
IS
  CURSOR CPROP IS SELECT PK_CUAA FROM CONS_CONS_TAB WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF AND PK_CUAA<>999999999;
  CURSOR CAFFI IS SELECT PK_CUAA FROM CONS_UFRE_TAB WHERE COD_NAZIONALE=CO AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND DATA_INIZIO <= DATARIF AND DATA_FINE >= DATARIF AND PK_CUAA<>999999999;
  SUPECOND NUMBER := 0;
  PKCUAA NUMBER;
BEGIN
  IF TIPOCOND=0 THEN
    OPEN CPROP;
      LOOP
        FETCH CPROP INTO PKCUAA;
        EXIT WHEN CPROP%NOTFOUND;
        SUPECOND := SUPECOND + GETSUPECOND(CO, FO, PA, SU, PKCUAA, DATARIF, TIPOCOND);
      END LOOP;
    CLOSE CPROP;
  ELSE
    OPEN CAFFI;
      LOOP
        FETCH CAFFI INTO PKCUAA;
        EXIT WHEN CAFFI%NOTFOUND;
        SUPECOND := SUPECOND + GETSUPECOND(CO, FO, PA, SU, PKCUAA, DATARIF, TIPOCOND);
      END LOOP;
    CLOSE CAFFI;
  END IF;

  RETURN SUPECOND;
END;

END CONSTERR;
/


DROP PACKAGE BODY SITI_H501.CONTRACT_UTILITY;

CREATE OR REPLACE package body SITI_H501.contract_utility as
FUNCTION get_pktit_cespite (pfk_cespiti IN NUMBER) RETURN NUMBER IS PKTITCESPITE  NUMBER;
   valore1 number;
   valore2 number;
   BEGIN
     valore1:=0;
  valore2:=0;
  begin
       select patri_cespiti_uiu.pk_tit into valore2 from patri_cespiti_uiu where patri_cespiti_uiu.fk_cespite = pfk_cespiti;
         exception when no_data_found then valore2 :=0;
  end;

     if valore2 = 0 then
     begin
          select patri_cespiti_part.pk_tit into valore1 from patri_cespiti_part where patri_cespiti_part.fk_cespite = pfk_cespiti;
           exception when no_data_found then valore1 :=0;
  end;
  end if;
  if valore1 =0 then
     PKTITCESPITE := valore2;
  else
     PKTITCESPITE := valore1;
     end if;
     return PKTITCESPITE;
END get_pktit_cespite;

FUNCTION get_Tipo_cespite (pfk_cespiti IN NUMBER) RETURN NUMBER IS
   tipocespite  NUMBER;
   pktitcespite NUMBER;
   /*
     tipocespite = 0 = uiu
  tipocespite = 1 = particella
   */
   BEGIN
     pktitcespite:=0;
     begin
       select patri_cespiti_uiu.pk_tit into pktitcespite from patri_cespiti_uiu where patri_cespiti_uiu.fk_cespite = pfk_cespiti;
         exception when no_data_found then pktitcespite :=0;
  end;
    if pktitcespite = 0 then
    tipocespite := 1;
 else
    tipocespite := 0;
 end if;
    return tipocespite;

  END get_Tipo_cespite;

 function get_pktit_conduz(pktit IN NUMBER, tipo_cespite in number, numero_contr in number) return number is pktit_conduz number;
   mcod_nazionale varchar2(4);
   mfoglio number;
   mparticella varchar2(5);
   msub varchar2(3);
   munimm number;
   BEGIN
     pktit_conduz:=0;
     if tipo_cespite = 0 then
        select cod_nazionale, foglio, particella, sub, unimm into mcod_nazionale, mfoglio, mparticella, msub, munimm from siticonduz_imm_all2 where pkid_tit = pktit and (tipo_titolo = '1' or tipo_titolo = '3');
        if munimm is not null then
      select distinct pkid_tit into  pktit_conduz from siticonduz_imm_all2 where cod_nazionale = mcod_nazionale and  foglio = mfoglio and particella = mparticella and sub = msub and unimm = munimm  and atto_inizio = numero_contr and tipo_titolo <> '1' and tipo_titolo <> '3' and rownum = 1;
   if pktit_conduz is null then
      pktit_conduz :=0;
   end if;
     end if;
     else
       select cod_nazionale, foglio, particella, sub into mcod_nazionale, mfoglio, mparticella, msub from siticond_all2 where pkid_tit = pktit and (tipo_titolo = '1' or tipo_titolo = '3');
       if mcod_nazionale is not null then
       if msub is not null then
              select distinct pkid_tit into  pktit_conduz from siticond_all2 where cod_nazionale = mcod_nazionale and  foglio = mfoglio and particella = mparticella and sub = msub  and atto_inizio = numero_contr and tipo_titolo <> '1' and tipo_titolo <> '3' and rownum = 1;
    else
          select distinct pkid_tit into  pktit_conduz from siticond_all2 where cod_nazionale = mcod_nazionale and  foglio = mfoglio and particella = mparticella and atto_inizio = numero_contr and tipo_titolo <> '1' and tipo_titolo <> '3' and rownum = 1;
    end if;
          if pktit_conduz is null then
             pktit_conduz :=0;
          end if;
       end if;

    end if;
    return pktit_conduz;

 end get_pktit_conduz;

function get_codces_da_estremi(pcod_nazionale IN varchar2, pfoglio in number, ppart IN varchar2,psub in varchar2, punimm in number, petype in varchar2) return varchar2 IS
  codice_cespite varchar2(12);
  MPK_CESPITE NUMBER;

  BEGIN
     MPK_CESPITE  := 0;
     codice_cespite := NULL;
  IF (PSUB IS NULL or psub = '') AND PUNIMM IS NULL THEN

       SELECT PK_CESPITE INTO MPK_CESPITE FROM PATRI_CESPITI_CAT_VIW WHERE
         COD_NAZIONALE = PCOD_NAZIONALE
      aND FOGLIO = PFOGLIO
             AND PARTICELLA = PPART AND ETYPE = petype;
           /* exception when no_data_found then MPK_CESPITE :=0;*/
  elsIF PUNIMM IS NULL THEN

       SELECT max(PK_CESPITE) INTO MPK_CESPITE FROM PATRI_CESPITI_CAT_VIW WHERE
         COD_NAZIONALE = PCOD_NAZIONALE
             aND FOGLIO = PFOGLIO
          and sub = psub
             AND PARTICELLA = PPART AND ETYPE = petype;

  ELSIF PSUB IS NULL THEN

        SELECT max(PK_CESPITE) INTO MPK_CESPITE FROM PATRI_CESPITI_CAT_VIW WHERE
          COD_NAZIONALE = PCOD_NAZIONALE
       aND FOGLIO = PFOGLIO
       AND PARTICELLA = PPART AND ETYPE = petype
    AND UNIMM = PUNIMM;
       /*exception when no_data_found then MPK_CESPITE :=0;*/

  ELSE

      SELECT max(PK_CESPITE) INTO MPK_CESPITE FROM PATRI_CESPITI_CAT_VIW WHERE
         COD_NAZIONALE = PCOD_NAZIONALE
      aND FOGLIO = PFOGLIO
       AND PARTICELLA = PPART AND ETYPE = petype
          aND SUB = PSUB
    AND UNIMM = PUNIMM;
       /*exception when no_data_found then MPK_CESPITE :=0;*/

  END IF;

  IF MPK_CESPITE <> 0 THEN
      begin
        select patri_cespiti.COD_CESPITE into codice_cespite from patri_cespitI where patri_cespiti.Pk_cespite = MPK_CESPITe;
              exception when no_data_found then codice_cespite := NULL;
       end;
  END IF;

 RETURN codice_cespite;
end get_codces_da_estremi;

end contract_utility;
/


DROP PACKAGE BODY SITI_H501.CONVERSION_UTILS_PCK;

CREATE OR REPLACE package body SITI_H501.conversion_utils_pck is

  function metri2ettari_type(mq number) return ettari_type is
    ret     ettari_type;
  begin
    
    ret.centiare := floor(mq + 0.5);
    ret.ettari := floor(mq / 10000);
    ret.centiare := ret.centiare - (ret.ettari * 10000);
    ret.are := floor(ret.centiare / 100);
    ret.centiare := ret.centiare - (ret.are * 100);
  
    return ret;
  end;

  function metri2ettari_round(mq number) return number is
  begin
    return metri2ettari_type(mq).ettari;
  end metri2ettari_round;
  
  function metri2are_round(mq number) return number is
  begin
    return metri2ettari_type(mq).are;
  end metri2are_round;
  
  function metri2centiare_round(mq number) return number is
  begin
    return metri2ettari_type(mq).centiare;
  end metri2centiare_round;

end conversion_utils_pck;
/


DROP PACKAGE BODY SITI_H501.CXF_UTILS;

CREATE OR REPLACE PACKAGE BODY SITI_H501.cxf_utils AS
FUNCTION SCADI_HEADER(CODNAZ IN VARCHAR2, FOG IN NUMBER,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2,ALLEG IN VARCHAR2,SVILU IN VARCHAR2) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_INIZIO_VAL,DATA_FINE_VAL,ID_CXF FROM CXF_HEADER WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO AND ALLEGATO=ALLEG AND SVILUPPO=SVILU;
  CURSOR C2 IS SELECT DATA_INIZIO_VAL FROM CXF_HEADER WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL > DATA_INIZIO AND ALLEGATO=ALLEG AND SVILUPPO=SVILU;
  INIZIO_VER DATE;
  FINE_VER DATE;
  SEROWIDATT NUMBER(9);
  INIZIO_VER_SUCC DATE;
  RETVAL DATE;
BEGIN
  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER,SEROWIDATT;
  IF C1%NOTFOUND THEN SEROWIDATT:= NULL; END IF;
  CLOSE C1;
  IF INIZIO_VER = DATA_INIZIO THEN
    IF DATA_FINE <  FINE_VER THEN raise_application_error(-20005, 'Scartato'); END IF;
    RAISE_APPLICATION_ERROR(-20001, 'SCARTATO');
  END IF;
  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> To_Date('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;
  IF NOT(SEROWIDATT IS NULL) THEN
      UPDATE CXF_HEADER SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN WHERE ID_CXF = SEROWIDATT;
  END IF;
  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
  RETURN RETVAL;
END SCADI_HEADER;

FUNCTION SCADI_CALIB(IDCXF IN NUMBER,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_INIZIO_VAL,DATA_FINE_VAL,ID_CALIB FROM CXF_CALIB WHERE ID_CXF=IDCXF AND DATA_INIZIO_VAL <= DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO;
  CURSOR C2 IS SELECT DATA_INIZIO_VAL FROM CXF_CALIB WHERE ID_CXF=IDCXF AND DATA_INIZIO_VAL > DATA_INIZIO;
  INIZIO_VER DATE;
  FINE_VER DATE;
  SEROWIDATT NUMBER(9);
  INIZIO_VER_SUCC DATE;
  RETVAL DATE;
BEGIN
  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER,SEROWIDATT;
  IF C1%NOTFOUND THEN SEROWIDATT:= NULL; END IF;
  CLOSE C1;
  IF INIZIO_VER = DATA_INIZIO THEN
    IF DATA_FINE <  FINE_VER THEN raise_application_error(-20005, 'Scartato'); END IF;
    RAISE_APPLICATION_ERROR(-20001, 'SCARTATO');
  END IF;
  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> To_Date('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;
  IF NOT(SEROWIDATT IS NULL) THEN
      UPDATE CXF_CALIB SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN WHERE ID_CALIB = SEROWIDATT;
  END IF;
  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
  RETURN RETVAL;
END SCADI_CALIB;

