FUNCTION DBMAP_POINT (X NUMBER,Y NUMBER) RETURN MDSYS.SDO_GEOMETRY IS
BEGIN
  RETURN MDSYS.SDO_GEOMETRY(2001,NULL,NULL,MDSYS.SDO_ELEM_INFO_ARRAY(1,1,1),MDSYS.SDO_ORDINATE_ARRAY(X,Y));
END DBMAP_POINT;

PROCEDURE GENERA_CENTROIDI_FOGLIO(IN_COD_NAZIONALE IN VARCHAR2,IN_FOGLIO IN NUMBER) IS
  CURSOR C1 IS SELECT * FROM CXF_CENTROIDE;
  CURSOR C2 IS
      SELECT COD_NAZIONALE,FOGLIO,TAVOLA,PARTICELLA,SUB,DATA_LAV,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,ALLEGATO,SVILUPPO,SDO_GEOM.SDO_CENTROID(SHAPE,0.5) AS CEN
      FROM SITIPART A
      WHERE A.COD_NAZIONALE=IN_COD_NAZIONALE AND A.FOGLIO=IN_FOGLIO
      AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS')
      AND NOT EXISTS
      (
      SELECT 1 FROM SITICENT B
      WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.FOGLIO=A.FOGLIO AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB
      AND B.DATA_FINE_VAL = A.DATA_FINE_VAL
      );

  SH1 MDSYS.SDO_GEOMETRY;
BEGIN

  DELETE FROM CXF_CENTROIDE;

  FOR C2R IN C2 LOOP
    SH1:= C2R.CEN;
    INSERT INTO CXF_CENTROIDE (COD_NAZIONALE,FOGLIO,TAVOLA,PARTICELLA,SUB,DATA_LAV,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,ALLEGATO,SVILUPPO,THEX,THEY)
    VALUES(C2R.COD_NAZIONALE,C2R.FOGLIO,C2R.TAVOLA,C2R.PARTICELLA,C2R.SUB,C2R.DATA_LAV,C2R.UTENTE,C2R.DATA_INIZIO_VAL,
    C2R.DATA_FINE_VAL,C2R.ALLEGATO,C2R.SVILUPPO,SDO_TOOLS.GET_POINT_X(SH1),SDO_TOOLS.GET_POINT_Y(SH1));
  END LOOP;

  FOR C1R IN C1 LOOP
    BEGIN
      IF C1R.THEX IS NOT NULL THEN
        SH1:= DBMAP_POINT(C1R.THEX,C1R.THEY);
        INSERT INTO SITICENT(COD_NAZIONALE,FOGLIO,TAVOLA,PARTICELLA,SUB,DATA_LAV,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,ALLEGATO,SVILUPPO,SHAPE)
        VALUES(C1R.COD_NAZIONALE,C1R.FOGLIO,C1R.TAVOLA,C1R.PARTICELLA,C1R.SUB,C1R.DATA_LAV,C1R.UTENTE,C1R.DATA_INIZIO_VAL,C1R.DATA_FINE_VAL,C1R.ALLEGATO,C1R.SVILUPPO,SH1);
      END IF;
    EXCEPTION
        WHEN Others THEN
          NULL;
    END;
  END LOOP;

END GENERA_CENTROIDI_FOGLIO;

PROCEDURE COPIA_CALIB(IN_ID_CALIB IN NUMBER,IN_ID_CXF IN NUMBER,IN_UTENTE IN VARCHAR2)
IS
  CURSOR C1 IS
    SELECT
    ORIGINEX1, ORIGINEY1, DESTINAZIONEX1, DESTINAZIONEY1, ORIGINEX2, ORIGINEY2, DESTINAZIONEX2, DESTINAZIONEY2, ORIGINEX3, ORIGINEY3, DESTINAZIONEX3, DESTINAZIONEY3,
    ORIGINEX4, ORIGINEY4, DESTINAZIONEX4, DESTINAZIONEY4, ORIGINEX5, ORIGINEY5, DESTINAZIONEX5, DESTINAZIONEY5, ORIGINEX6, ORIGINEY6, DESTINAZIONEX6, DESTINAZIONEY6
    FROM CXF_CALIB WHERE ID_CALIB = IN_ID_CALIB;

  C1R C1%ROWTYPE;

BEGIN

  OPEN C1;
  FETCH C1 INTO C1R;
  IF C1%NOTFOUND THEN
    Raise_Application_Error(-20999,'La calibrazione richiesta non esiste più');
  END IF;
  CLOSE C1;

  INSERT INTO CXF_CALIB
  (
  ID_CXF, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE,
  ORIGINEX1, ORIGINEY1, DESTINAZIONEX1, DESTINAZIONEY1, ORIGINEX2, ORIGINEY2, DESTINAZIONEX2, DESTINAZIONEY2, ORIGINEX3, ORIGINEY3, DESTINAZIONEX3, DESTINAZIONEY3,
  ORIGINEX4, ORIGINEY4, DESTINAZIONEX4, DESTINAZIONEY4, ORIGINEX5, ORIGINEY5, DESTINAZIONEX5, DESTINAZIONEY5, ORIGINEX6, ORIGINEY6, DESTINAZIONEX6, DESTINAZIONEY6
  )
  VALUES
  (
  in_id_cxf,SYSDATE,To_Date('99991231','YYYYMMDD'),IN_UTENTE,
  C1R.ORIGINEX1, C1R.ORIGINEY1, C1R.DESTINAZIONEX1, C1R.DESTINAZIONEY1, C1R.ORIGINEX2, C1R.ORIGINEY2, C1R.DESTINAZIONEX2, C1R.DESTINAZIONEY2, C1R.ORIGINEX3, C1R.ORIGINEY3, C1R.DESTINAZIONEX3, C1R.DESTINAZIONEY3,
  C1R.ORIGINEX4, C1R.ORIGINEY4, C1R.DESTINAZIONEX4, C1R.DESTINAZIONEY4, C1R.ORIGINEX5, C1R.ORIGINEY5, C1R.DESTINAZIONEX5, C1R.DESTINAZIONEY5, C1R.ORIGINEX6, C1R.ORIGINEY6, C1R.DESTINAZIONEX6, C1R.DESTINAZIONEY6
  );

END COPIA_CALIB;

END; 
/


DROP PACKAGE BODY SITI_H501.DOCFA;

CREATE OR REPLACE PACKAGE BODY SITI_H501.docfa AS

  function getLoadId(fileName varchar2) return number is
    ret   number(9);
  begin
    insert into docfa_caricati (load_id, file_name) values (docfa_caricati_seq.nextval, fileName)
      returning load_id into ret;

    return ret;
  end getLoadId;

END docfa;
