DROP PACKAGE BODY SITI_H501.IMPORT_GIS_DATA;

CREATE OR REPLACE PACKAGE BODY SITI_H501.import_gis_data AS

PROCEDURE IMPORT_SITICOMU(COD_NAZIONALE  IN VARCHAR2,ISTATP IN VARCHAR2,ISTATC IN VARCHAR2,ID_SEZC IN VARCHAR2,NOME   IN VARCHAR2,DENO_PROV IN VARCHAR2,SIGLA_PROV IN VARCHAR2,ISTATR IN VARCHAR2,CODI_FISC_LUNA IN VARCHAR2,FLAG_CATA IN NUMBER)
IS
BEGIN
  INSERT INTO SITICOMU(COD_NAZIONALE,ISTATP,ISTATC,ID_SEZC,NOME,DENO_PROV,SIGLA_PROV,ISTATR,CODI_FISC_LUNA,FLAG_CATA) VALUES(COD_NAZIONALE,ISTATP,ISTATC,ID_SEZC,NOME,DENO_PROV,SIGLA_PROV,ISTATR,CODI_FISC_LUNA,FLAG_CATA);
END IMPORT_SITICOMU;

PROCEDURE IMPORT_SITICOML(ISTATP IN VARCHAR2,ISTATC IN VARCHAR2,SHAPE IN MDSYS.SDO_GEOMETRY)
IS
BEGIN
  INSERT INTO SITICOML(ISTATP,ISTATC,SHAPE) VALUES(ISTATP,ISTATC,SHAPE);
END IMPORT_SITICOML;

PROCEDURE IMPORT_SITITRKC(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, DATAL IN VARCHAR2, AREA IN NUMBER, REND NUMBER, CLA IN VARCHAR2, QUAL NUMBER, PARTIT VARCHAR2,UTEN IN VARCHAR2,RAG IN NUMBER,RDO IN NUMBER,note varchar2, subo_uc varchar2)
IS
SIGLA VARCHAR2(2);
BEGIN
  SIGLA:=GETSIGLAPROV(CODNAZ);
  INSERT INTO SITITRKC(SIGLA_PROV,COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,QUAL_CAT,CLASSE_TERRENO,AREA_PART,PARTITA,DATA_AGGI,RENDITA,VALIDA,reddito_agrario,reddito_dominicale,annotazioni,sub_uc)
  VALUES(SIGLA, CODNAZ, FOG, PART, SUBO, QUAL, CLA, AREA, PARTIT, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), REND, 1,RAG,RDO,note, subo_uc);
END IMPORT_SITITRKC;

PROCEDURE IMPORT_SITIDSTR(CODNAZ IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, NUMSTRADA IN VARCHAR2, PREF IN VARCHAR2, NOME_STRA IN VARCHAR2, TIPO_STRA IN VARCHAR2)
IS
BEGIN
  INSERT INTO SITIDSTR(PREFISSO, NOME, COD_NAZIONALE, DATA_INIZIO_VAL, DATA_FINE_VAL, TIPO, NUMERO, UTENTE)
  VALUES(PREF, NOME_STRA, CODNAZ, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), TO_DATE('99991231000000','YYYYMMDDHH24MISS'), TIPO_STRA, NUMSTRADA, UTEN);
END IMPORT_SITIDSTR;

PROCEDURE IMPORT_SITIDFIU(CODNAZ IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, NUMFIUME IN VARCHAR2, PREF IN VARCHAR2, NOME_FIUM IN VARCHAR2, TIPO_FIUM IN VARCHAR2)
IS
BEGIN
  INSERT INTO SITIDFIU(PREFISSO, NOME, COD_NAZIONALE, DATA_INIZIO_VAL, DATA_FINE_VAL, TIPO, NUMERO, UTENTE)
  VALUES(PREF, NOME_FIUM, CODNAZ, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), TO_DATE('99991231000000','YYYYMMDDHH24MISS'), TIPO_FIUM, NUMFIUME, UTEN);
END IMPORT_SITIDFIU;

PROCEDURE IMPORT_SITIDSTR_GRAF(CODNAZ IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, NUMSTRADA IN VARCHAR2, SHP IN MDSYS.SDO_GEOMETRY)
IS
BEGIN
  INSERT INTO SITIDSTR_GRAF(COD_NAZIONALE, NUMERO, DATA_LAV, UTENTE, SHAPE)
  VALUES(CODNAZ, NUMSTRADA, TO_DATE(DATAL, 'YYYYMMDDHH24MISS'), UTEN, SHP);
END IMPORT_SITIDSTR_GRAF;

PROCEDURE IMPORT_SITIDFIU_GRAF(CODNAZ IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, NUMFIUME IN VARCHAR2, SHP IN MDSYS.SDO_GEOMETRY)
IS
BEGIN
  INSERT INTO SITIDFIU_GRAF(COD_NAZIONALE, NUMERO, DATA_LAV, UTENTE, SHAPE)
  VALUES(CODNAZ, NUMFIUME, TO_DATE(DATAL, 'YYYYMMDDHH24MISS'), UTEN, SHP);
END IMPORT_SITIDFIU_GRAF;

PROCEDURE IMPORT_SITISTRA(DNAZIONALE IN VARCHAR2,ISTATP IN VARCHAR2,ISTATC IN VARCHAR2,ID_SEZC IN VARCHAR2,FOGLIO IN NUMBER,PARTICELLA IN CHAR,SUB IN VARCHAR2,DATA_LAV IN VARCHAR2,NUMERO IN VARCHAR2)
IS
  CODNAZ VARCHAR2(4);
  PKSTRA NUMBER;
BEGIN
  IF DNAZIONALE IS NULL THEN
    CODNAZ:=GETCODNAZ(ISTATP,ISTATC,ID_SEZC);
  ELSE
    CODNAZ:=DNAZIONALE;
  END IF;
  PKSTRA:=GETPKIDSTRA(NUMERO,CODNAZ);
  INSERT INTO SITISTRA(PKID_STRA,COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,DATA_INIZIO_VAL,DATA_FINE_VAL,UTENTE)
  VALUES(PKSTRA,CODNAZ,FOGLIO,PARTICELLA,SUB,DATA_LAV,To_Date('99991231000000','YYYYMMDDHH24MISS'),'LOADER');
END IMPORT_SITISTRA;

PROCEDURE IMPORT_SITIFIUM(DNAZIONALE IN VARCHAR2,ISTATP IN VARCHAR2,ISTATC IN VARCHAR2,ID_SEZC IN VARCHAR2,FOGLIO IN NUMBER,PARTICELLA IN CHAR,SUB IN VARCHAR2,DATA_LAV IN VARCHAR2,NUMERO IN VARCHAR2)
IS
  CODNAZ VARCHAR2(4);
  PKFIUM NUMBER;
BEGIN
  IF DNAZIONALE IS NULL THEN
    CODNAZ:=GETCODNAZ(ISTATP,ISTATC,ID_SEZC);
  ELSE
    CODNAZ:=DNAZIONALE;
  END IF;
  PKFIUM:=GETPKIDFIUM(NUMERO,CODNAZ);
  INSERT INTO SITIFIUM(PKID_FIUM,COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,DATA_INIZIO_VAL,DATA_FINE_VAL,UTENTE)
  VALUES(PKFIUM,CODNAZ,FOGLIO,PARTICELLA,SUB,DATA_LAV,To_Date('99991231000000','YYYYMMDDHH24MISS'),'LOADER');
END IMPORT_SITIFIUM;

PROCEDURE IMPORT_SITICIVI(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, NUMSTRADA IN VARCHAR2, CIV IN VARCHAR2, SHP IN MDSYS.SDO_GEOMETRY)
IS
  PKSTRA NUMBER:=NULL;
  PKCIVI NUMBER:=NULL;
  PKUIU NUMBER:=NULL;
  FG NUMBER:=FOG;
  PT VARCHAR2(5):=PART;
  SB VARCHAR2(3):=SUBO;
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;
BEGIN
  PKSTRA:=GETPKIDSTRA(NUMSTRADA, CODNAZ);
  PKCIVI:=GETPKIDCIVI(PKSTRA, CIV);
  IF PKCIVI IS NULL THEN
    OPEN C FOR SELECT SITICIVI_SEQ.NEXTVAL FROM DUAL;
    FETCH C INTO PKCIVI;
    IF C%NOTFOUND THEN PKCIVI:=NULL; END IF;
    CLOSE C;
    INSERT INTO SITICIVI(PKID_CIVI, PKID_STRA, COD_NAZIONALE, CIVICO, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, SHAPE)
    VALUES(PKCIVI, PKSTRA, CODNAZ, CIV, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), TO_DATE('99991231000000','YYYYMMDDHH24MISS'), UTEN, SHP);
  elsif SHP is not null then
    update siticivi set shape = shp where pkid_civi=pkcivi;
  END IF;
  IF PT IS NULL AND SHP IS NOT NULL THEN
    OPEN C FOR SELECT FOGLIO, PARTICELLA, SUB FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND SDO_RELATE(SHAPE, SHP, 'QUERYTYPE=WINDOW MASK=CONTAINS')='TRUE';
    FETCH C INTO FG, PT, SB;
    IF C%NOTFOUND THEN
      FG:=NULL;
      PT:=NULL;
      SB:=NULL;
    END IF;
    CLOSE C;
  END IF;
  IF PT IS NOT NULL THEN
    OPEN C FOR SELECT A.PKID_UIU FROM SITIUIU A WHERE A.COD_NAZIONALE=CODNAZ AND A.FOGLIO=FG AND A.PARTICELLA=PT AND A.SUB=SB AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND (SELECT COUNT(*) FROM SITICIVI_UIU B WHERE B.PKID_UIU=A.PKID_UIU AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS'))=0;
    LOOP
      FETCH C INTO PKUIU;
      EXIT WHEN C%NOTFOUND;
      begin
        INSERT INTO SITICIVI_UIU(PKID_CIVI, PKID_UIU, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, SCALA, PIANO, INTERNO)
        VALUES(PKCIVI, PKUIU, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), TO_DATE('99991231000000','YYYYMMDDHH24MISS'), UTEN, '0', 0, (SELECT NVL(MAX(INTERNO),0)+1 FROM SITICIVI_UIU WHERE PKID_CIVI=PKCIVI));
      exception when dup_val_on_index then
        null;
      end;
    END LOOP;
  CLOSE C;
  END IF;
END;

PROCEDURE IMPORT_SITIUIU(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, UIMM IN NUMBER, DATAL IN VARCHAR2, CAT IN VARCHAR2, CLA IN NUMBER, CONS IN NUMBER, SUPCAT IN NUMBER, MILL_TERR IN NUMBER, ZN IN VARCHAR2, MICROZN IN VARCHAR2, REND IN NUMBER, UTEN IN VARCHAR2, NT IN VARCHAR2)
IS
BEGIN
  INSERT INTO SITIUIU(COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, UNIMM, DATA_INIZIO_VAL, DATA_FINE_VAL, DATA_LAV, CATEGORIA, CLASSE, CONSISTENZA, SUP_CAT, MILLESIMI_TERRENO, ZONA,MICROZONA, RENDITA, UTENTE, NOTE)
  VALUES(CODNAZ, FOG, PART, SUBO, UIMM, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), TO_DATE('99991231000000','YYYYMMDDHH24MISS'), TO_DATE(DATAL,'YYYYMMDDHH24MISS'), CAT, decode(CLA, 0, 'U', to_char(cla)), CONS, SUPCAT, MILL_TERR, ZN, MICROZN, REND, UTEN, NT);
END IMPORT_SITIUIU;

PROCEDURE IMPORT_SITICIVI_UIU(CODNAZ IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, NUMSTRADA IN VARCHAR2, CIV IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, UIMM IN NUMBER, NUMSCALA IN VARCHAR2, NUMPIANO IN VARCHAR2, NUMINT IN VARCHAR2)
IS
  PKSTRA NUMBER;
  PKCIVI  NUMBER;
  PKUIU  NUMBER;
  DL     date;
BEGIN

  if datal is null then
    dl := sysdate;
  else
    dl := TO_DATE(DATAL,'YYYYMMDDHH24MISS');
  end if;

  PKUIU:=GETPKIDUIU(CODNAZ, FOG, PART, SUBO, UIMM);
  IF PKUIU IS NULL THEN
    RAISE_APPLICATION_ERROR(-20007, 'Un.Imm. non trovata.');
  END IF;

  PKSTRA:=GETPKIDSTRA(NUMSTRADA, CODNAZ);
  begin
    SELECT PKID_STRA into PKSTRA
    FROM SITIDSTR
    WHERE COD_NAZIONALE in (select cod_nazionale from siticomu where (istatp, istatc) in (select istatp, istatc from siticomu where cod_nazionale=CODNAZ)) AND NUMERO=NUMSTRADA AND ROWNUM=1;
  exception when no_data_found then
    RAISE_APPLICATION_ERROR(-20005, 'Strada non trovata.');
  end;

  PKCIVI:=GETPKIDCIVI(PKSTRA, CIV);
  IF PKCIVI IS NULL THEN
    RAISE_APPLICATION_ERROR(-20006, 'Civico non trovato.');
  END IF;

  INSERT INTO SITICIVI_UIU(PKID_CIVI, PKID_UIU, DATA_INIZIO_VAL, DATA_FINE_VAL, SCALA, PIANO, INTERNO, UTENTE)
  VALUES(PKCIVI, PKUIU, dl, TO_DATE('99991231000000','YYYYMMDDHH24MISS'), NUMSCALA, NUMPIANO, NUMINT, UTEN);
END IMPORT_SITICIVI_UIU;

PROCEDURE IMPORT_SITISOGG(CODSOGG IN VARCHAR2, CODFISC IN VARCHAR2, PARTIVA IN VARCHAR2, RS IN VARCHAR2, NM IN VARCHAR2, SEX IN VARCHAR2, DN IN VARCHAR2, COMNASC IN VARCHAR2, RES_VIA IN VARCHAR2, RES_COM IN VARCHAR2, NAT_GIUR IN VARCHAR2, PERS_FIS IN VARCHAR2, MATRICOLA IN VARCHAR2, CODFISC_RAPP IN VARCHAR2, DATA_REG IN VARCHAR2, UTEN IN VARCHAR2)
IS
  PKCUAA NUMBER(9):=NULL;
  ESISTE NUMBER(1):=NULL;
  PKIDRAPP NUMBER(9):=NULL;
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;
  C2 EMPTYCUR;
  cnResi      varchar2(4);
  cnComNasc      varchar2(4);  -- comune di nascita
  mPERS_FIS   char(1) := PERS_FIS;
BEGIN


  if (RES_COM is not null) then
    begin
      -- a.caleffi 2008-11-05 cambiato da cod_nazionale a codi_fisc_luna
      select codi_fisc_luna into cnResi
        from siticomu
       where istatp = substr(RES_COM, 1, 3)
         and istatc = substr(RES_COM, 4)
         and rownum = 1;
    exception when no_data_found then
      null;
    end;
  end if;

  -- a.caleffi 2008-11-05 controllo comune di nascita
  if (COMNASC is not null) then
    begin
      -- a.caleffi 2008-11-05 cambiato da cod_nazionale a codi_fisc_luna
      select codi_fisc_luna into cnComNasc
        from siticomu
       where istatp = substr(COMNASC, 1, 3)
         and istatc = substr(COMNASC, 4)
         and rownum = 1;
    exception when no_data_found then
      null;
    end;
  end if;

  OPEN C FOR SELECT PK_CUAA FROM CONS_AZIE_TAB WHERE CUAA=CODSOGG AND DATA_FINE=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');
  FETCH C INTO PKCUAA;
  IF C%NOTFOUND THEN PKCUAA:=NULL; END IF;
  CLOSE C;

  IF PKCUAA IS NULL THEN
    OPEN C FOR SELECT CONS_AZIE_SEQ.NEXTVAL FROM DUAL;
    FETCH C INTO PKCUAA;
    IF C%NOTFOUND THEN PKCUAA:=NULL; END IF;
    CLOSE C;

    INSERT INTO CONS_AZIE_TAB(PK_CUAA, CUAA, DATA_INIZIO, DATA_FINE, DATA_REGISTRAZIONE, UTENTE, COD_STATO, DATA_INIZIO_STATO)
    VALUES(PKCUAA, CODSOGG, TO_DATE(DATA_REG, 'YYYYMMDDHH24MISS'), TO_DATE('99991231000000', 'YYYYMMDDHH24MISS'), TO_DATE(DATA_REG, 'YYYYMMDDHH24MISS'), UTEN, '0', TO_DATE(DATA_REG, 'YYYYMMDDHH24MISS'));
  END IF;

  IF CODFISC_RAPP IS NOT NULL THEN
    OPEN C FOR SELECT PKID FROM anag_soggetti s WHERE s.cod_fiscale=CODFISC_RAPP AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');
    FETCH C INTO PKIDRAPP;
    IF C%NOTFOUND THEN PKIDRAPP:=NULL; END IF;
    CLOSE C;
  END IF;

  OPEN C2 FOR SELECT 1 FROM anag_soggetti s WHERE s.cod_soggetto=PKCUAA AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');
  FETCH C2 INTO ESISTE;
  IF C2%NOTFOUND THEN ESISTE:=NULL; END IF;
  CLOSE C2;

  IF ESISTE IS NULL THEN
    if mPERS_FIS = 'F' then
      mPERS_FIS := 'P';
    end if;

    -- a.caleffi 2008-11-05 aggiunto campo natura_giuridica, fkcod_comu_nasc
    insert into anag_soggetti (cod_soggetto, cod_fiscale, part_iva,
        denominazione, cognome, nome,
        indirizzo_est, FKCOD_COMU_RESI, sesso,
        d_nascita, flag_pers_fisica, data_inizio_val,
        data_fine_val, data_lav, utente_inizio,
        natura_giuridica, fkcod_comu_nasc)
    values (PKCUAA, CODFISC, PARTIVA,
      decode(mPERS_FIS, 'P', upper(RS) || ' ' || upper(NM), upper(RS)), decode(mPERS_FIS, 'P', upper(RS), null), upper(NM),
        res_via, cnResi, SEX,
        to_date(DN, 'YYYYMMDDHH24MISS'), mPERS_FIS, TO_DATE(DATA_REG, 'YYYYMMDDHH24MISS'),
        TO_DATE('99991231000000', 'YYYYMMDDHH24MISS'), TO_DATE(DATA_REG, 'YYYYMMDDHH24MISS'), UTEN,
        NAT_GIUR, cnComNasc);
  END IF;
END IMPORT_SITISOGG;

PROCEDURE IMPORT_SITIFGLC(CODNAZ IN VARCHAR2,TAV IN NUMBER,ALLE IN VARCHAR2,SVIL IN VARCHAR2,DATAC IN VARCHAR2,STATO IN NUMBER, SHP IN MDSYS.SDO_GEOMETRY)
IS
  FLAG_CATA NUMBER;
BEGIN
  FLAG_CATA:=GETFLAG_CATA(CODNAZ);
  IF FLAG_CATA = 2 THEN
    INSERT INTO SITIFGLC(COD_NAZIONALE,FOGLIO,TAVOLA,ALLEGATO,SVILUPPO,DATA_CAT,FLAG_STATO,TIPO,SHAPE)
    VALUES(CODNAZ,9999,TAV,ALLE,SVIL,DATAC,STATO,'L',SHP);
  ELSE
    INSERT INTO SITIFGLC(COD_NAZIONALE,FOGLIO,TAVOLA,ALLEGATO,SVILUPPO,DATA_CAT,FLAG_STATO,TIPO,SHAPE)
    VALUES(CODNAZ,TAV,TAV,ALLE,SVIL,DATAC,STATO,'L',SHP);
  END IF;
END IMPORT_SITIFGLC;

PROCEDURE IMPORT_SITIREGI(DENO_REGI IN VARCHAR2,FUSO IN VARCHAR2,ISTATR IN NUMBER,SHAPE IN MDSYS.SDO_GEOMETRY)
IS
BEGIN
  INSERT INTO SITIREGI(DENO_REGI,FUSO,ISTATR,SHAPE,ID_COD_REG)
  VALUES(DENO_REGI,FUSO,ISTATR,SHAPE,Trim(To_Char(ISTATR,'00')));
END IMPORT_SITIREGI;

PROCEDURE IMPORT_SITIPROV(ISTATR IN NUMBER,DENO_PROV IN VARCHAR2,SIGLA_PROV IN VARCHAR2,ID_PRO IN VARCHAR2,SHAPE IN MDSYS.SDO_GEOMETRY)
IS
BEGIN
  INSERT INTO SITIPROV(id_pro,id_cod_reg,deno_prov,sigla_prov,istatp,shape)
  VALUES(ID_PRO,Trim(To_Char(ISTATR,'00')),deno_prov,sigla_prov,To_Number(Nvl(ID_PRO,'0')),SHAPE);
END IMPORT_SITIPROV;

PROCEDURE IMPORT_SITICENT(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, SORG IN NUMBER, SHP IN MDSYS.SDO_GEOMETRY, DATAFINE IN DATE)
IS
  FLAG_CATA NUMBER;
BEGIN
  FLAG_CATA:=GETFLAG_CATA(CODNAZ);
  IF FLAG_CATA = 2 THEN
    INSERT INTO SITICENT(COD_NAZIONALE, FOGLIO, TAVOLA, ALLEGATO, SVILUPPO, PARTICELLA, SUB, DATA_LAV, UTENTE, SORGENTE, SHAPE, DATA_INIZIO_VAL, DATA_FINE_VAL)
    VALUES(CODNAZ, 9999, FOG, '0', '0', PART, SUBO, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), UTEN, SORG, SHP, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), DATAFINE);
  ELSE
    INSERT INTO SITICENT(COD_NAZIONALE, FOGLIO, TAVOLA, ALLEGATO, SVILUPPO, PARTICELLA, SUB, DATA_LAV, UTENTE, SORGENTE, SHAPE, DATA_INIZIO_VAL, DATA_FINE_VAL)
  VALUES(CODNAZ, FOG, FOG, '0', '0', PART, SUBO, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), UTEN, SORG, SHP, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), DATAFINE);
  END IF;
END IMPORT_SITICENT;

PROCEDURE IMPORT_SITIPART(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, SORG IN NUMBER, CODEDIF IN NUMBER, SHP IN MDSYS.SDO_GEOMETRY, DATAFINE IN DATE)
IS
  FLAG_CATA NUMBER;
BEGIN
  FLAG_CATA:=GETFLAG_CATA(CODNAZ);
  IF FLAG_CATA = 2 THEN
    INSERT INTO SITIPART(COD_NAZIONALE, FOGLIO, TAVOLA, ALLEGATO, SVILUPPO, PARTICELLA, SUB, DATA_LAV, UTENTE, SORGENTE, COD_EDIF, SHAPE, AREA_PART, DATA_INIZIO_VAL, DATA_FINE_VAL)
    VALUES(CODNAZ, 9999, FOG, '0', '0', PART, SUBO, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), UTEN, SORG, CODEDIF, SHP, SDO_GEOM.SDO_AREA(SHP,0.005), TO_DATE(DATAL,'YYYYMMDDHH24MISS'), DATAFINE);
  ELSE
    INSERT INTO SITIPART(COD_NAZIONALE, FOGLIO, TAVOLA, ALLEGATO, SVILUPPO, PARTICELLA, SUB, DATA_LAV, UTENTE, SORGENTE, COD_EDIF, SHAPE, AREA_PART, DATA_INIZIO_VAL, DATA_FINE_VAL)
    VALUES(CODNAZ, FOG, FOG, '0', '0', PART, SUBO, TO_DATE(DATAL,'YYYYMMDDHH24MISS'), UTEN, SORG, CODEDIF, SHP, SDO_GEOM.SDO_AREA(SHP,0.005), TO_DATE(DATAL,'YYYYMMDDHH24MISS'), DATAFINE);
  END IF;
END IMPORT_SITIPART;

PROCEDURE IMPORT_SITIPART_NOATTRIB(SHP IN MDSYS.SDO_GEOMETRY, DATAL IN VARCHAR2, UTEN IN VARCHAR2, SORG IN NUMBER, CODEDIF IN NUMBER,NONINS IN NUMBER)
IS
  CODNAZ VARCHAR2(4);
  FOG NUMBER;
  PART VARCHAR2(5);
  SUBO VARCHAR2(3);
  NCENT NUMBER;
BEGIN

  SELECT Count(*) INTO NCENT FROM SITICENT  WHERE SDO_RELATE(SHAPE, SHP, 'MASK=ANYINTERACT')='TRUE' AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');

  IF NCENT=1 THEN
    SELECT COD_NAZIONALE, FOGLIO, PARTICELLA, SUB INTO CODNAZ, FOG, PART, SUBO
    FROM SITICENT  WHERE SDO_RELATE(SHAPE, SHP, 'MASK=ANYINTERACT')='TRUE' AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');

    IF CODNAZ IS NOT NULL THEN
      INSERT INTO IMPO_SITIPART(COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, DATA_LAV, UTENTE, SORGENTE, COD_EDIF, SHAPE)
      VALUES(CODNAZ, FOG, PART, SUBO, DATAL, UTEN, SORG, CODEDIF, SHP);
    END IF;
  ELSE
    IF NCENT < 10 AND NONINS=0 THEN
      INSERT INTO SITIPART_NOATTRIB_APPOGGIO(shape,data_lav,utente,sorgente,cod_edif) VALUES(SHP,DATAL,UTEN,SORG,CODEDIF);
    END IF;
  END IF;
END IMPORT_SITIPART_NOATTRIB;

PROCEDURE ELABORA_PNOATAPPOGGIO
IS
  CURSOR C1 IS SELECT SHAPE,DATA_LAV,UTENTE,SORGENTE,COD_EDIF FROM SITIPART_NOATTRIB_APPOGGIO;
  DATAL VARCHAR2(14);
  SORG NUMBER;
  UTEN VARCHAR2(20);
  CODEDIF NUMBER;
  NSHP MDSYS.SDO_GEOMETRY;
BEGIN
  OPEN C1;
  LOOP
    FETCH C1 INTO NSHP,DATAL,UTEN,SORG,CODEDIF;
    EXIT WHEN C1%NOTFOUND;
    import_gis_data.PNOATAPPOGGIO_SINGOLA(NSHP,DATAL,UTEN,SORG,CODEDIF);
  END LOOP;
  CLOSE C1;
END;

PROCEDURE PNOATAPPOGGIO_SINGOLA(SHP IN MDSYS.SDO_GEOMETRY, DATAL IN VARCHAR2, UTEN IN VARCHAR2, SORG IN NUMBER, CODEDIF IN NUMBER)
IS
  NSHP MDSYS.SDO_GEOMETRY;
  SHPP MDSYS.SDO_GEOMETRY;
BEGIN

  SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(sdo_tools.remove_duplicate_points(shape), 0.01))
  INTO SHPP
  FROM SITIPART WHERE DATA_FINE_VAL=To_Date('99991231','YYYYMMDD') AND
  (COD_NAZIONALE,FOGLIO,PARTICELLA,SUB) IN
  (
    SELECT COD_NAZIONALE, FOGLIO, PARTICELLA, SUB
    FROM SITICENT  WHERE SDO_RELATE(SHAPE, sdo_tools.remove_duplicate_points(SHP), 'MASK=ANYINTERACT')='TRUE' AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS')
  );

  IF SHPP IS NOT NULL THEN
    SELECT SDO_GEOM.SDO_DIFFERENCE(SDO_TOOLS.REMOVE_DUPLICATE_POINTS(SHP),sdo_tools.remove_duplicate_points(SHPP),0.01)
    INTO NSHP
    FROM DUAL;

    IF NSHP IS NOT NULL THEN
      NSHP:= SDO_TOOLS.REMOVE_DUPLICATE_POINTS(NSHP);

      IF NSHP IS NOT NULL THEN
        IMPORT_GIS_DATA.IMPORT_SITIPART_NOATTRIB(NSHP,DATAL,UTEN,SORG,CODEDIF,1);
      END IF;
    END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN;
END;

PROCEDURE IMPORT_SITISUOLO(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, DATAL IN VARCHAR2, UTEN IN VARCHAR2, SORG IN NUMBER, USO_SUOLO IN VARCHAR2, SHP IN MDSYS.SDO_GEOMETRY, DATAFINE IN DATE)
IS
  FLAG_CATA NUMBER;
  CODEDIF NUMBER;
  CODUTIL NUMBER:=0;
BEGIN
  FLAG_CATA:=GETFLAG_CATA(CODNAZ);

  IF FLAG_CATA = 2 THEN
    CODEDIF:=GETCODEDIF(CODNAZ, 9999, PART, SUBO, DATAL);
  ELSE
    CODEDIF:=GETCODEDIF(CODNAZ, FOG, PART, SUBO, DATAL);
  END IF;

  IF CODEDIF=3 OR CODEDIF=4 THEN
    RAISE_APPLICATION_ERROR(-20004, 'Strada o Acqua.');
  END IF;

  IF USO_SUOLO='S' THEN
    IF CODEDIF=1 THEN
    CODUTIL:=110;
  ELSIF CODEDIF=2 THEN
    CODUTIL:=1;
  END IF;
  ELSIF USO_SUOLO='I' THEN
    IF CODEDIF=1 THEN
    CODUTIL:=110;
  ELSIF CODEDIF=2 THEN
    CODUTIL:=2;
  END IF;
  ELSIF USO_SUOLO='A' THEN
    IF CODEDIF=1 THEN
    CODUTIL:=110;
  ELSIF CODEDIF=2 THEN
    CODUTIL:=3;
  END IF;
  ELSIF USO_SUOLO='C' THEN
    IF CODEDIF=1 THEN
    CODUTIL:=100;
  ELSIF CODEDIF=2 THEN
    CODUTIL:=5;
  END IF;
  ELSIF USO_SUOLO='N' THEN
    IF CODEDIF=1 THEN
    CODUTIL:=110;
  ELSIF CODEDIF=2 THEN
    CODUTIL:=5;
  END IF;
  ELSE
    IF CODEDIF=1 THEN
    CODUTIL:=110;
  ELSIF CODEDIF=2 THEN
    CODUTIL:=5;
  END IF;
  END IF;

  IF FLAG_CATA = 2 THEN
    INSERT INTO SITISUOLO(COD_NAZIONALE, FOGLIO, TAVOLA, ALLEGATO, SVILUPPO, PARTICELLA, SUB, PROG_POLIGONO, DATA_LAV, UTENTE, SORGENTE, COD_UTIL, CAMPAGNA, SHAPE, AREA_COLT, DATA_INIZIO_VAL, DATA_FINE_VAL)
    VALUES(CODNAZ, 9999, FOG, '0', '0', PART, SUBO, (SELECT NVL(MAX(PROG_POLIGONO),0)+1 FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=9999 AND PARTICELLA=PART AND SUB=SUBO), TO_DATE(DATAL,'YYYYMMDDHH24MISS'), UTEN, SORG, CODUTIL, TO_NUMBER(SUBSTR(DATAL,1,4)), SHP, SDO_GEOM.SDO_AREA(SHP,0.005), TO_DATE(DATAL,'YYYYMMDDHH24MISS'), DATAFINE);
  ELSE
    INSERT INTO SITISUOLO(COD_NAZIONALE, FOGLIO, TAVOLA, ALLEGATO, SVILUPPO, PARTICELLA, SUB, PROG_POLIGONO, DATA_LAV, UTENTE, SORGENTE, COD_UTIL, CAMPAGNA, SHAPE, AREA_COLT, DATA_INIZIO_VAL, DATA_FINE_VAL)
    VALUES(CODNAZ, FOG, FOG, '0', '0', PART, SUBO, (SELECT NVL(MAX(PROG_POLIGONO),0)+1 FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO), TO_DATE(DATAL,'YYYYMMDDHH24MISS'), UTEN, SORG, CODUTIL, TO_NUMBER(SUBSTR(DATAL,1,4)), SHP, SDO_GEOM.SDO_AREA(SHP,0.005), TO_DATE(DATAL,'YYYYMMDDHH24MISS'), DATAFINE);
  END IF;
END IMPORT_SITISUOLO;

PROCEDURE IMPORT_TOPONIMI(TAV IN VARCHAR2, EDI IN NUMBER, DAT IN NUMBER, TOPO IN VARCHAR2, REGI IN NUMBER, COD IN VARCHAR2, NSER IN VARCHAR2, ESTP IN NUMBER, NORP IN NUMBER, ESTL IN NUMBER, NORL IN NUMBER, ESTR IN NUMBER, NORR IN NUMBER)
IS
  SHPCEN MDSYS.SDO_GEOMETRY;
  SHPLIM MDSYS.SDO_GEOMETRY;
  CODFISC VARCHAR2(4);
BEGIN
  SHPCEN:=MDSYS.SDO_GEOMETRY(2001, NULL, MDSYS.SDO_POINT_TYPE(ESTP, NORP, NULL), NULL, NULL);
  SHPLIM:=NULL;
  IF ESTL IS NOT NULL AND NORL IS NOT NULL AND ESTR IS NOT NULL AND NORR IS NOT NULL THEN
    SHPLIM:=MDSYS.SDO_GEOMETRY(2003, NULL, NULL, MDSYS.SDO_ELEM_INFO_ARRAY(1, 1003, 3), MDSYS.SDO_ORDINATE_ARRAY(ESTL, NORL, ESTR, NORR));
  END IF;
  CODFISC:=GETCODIFISCLUNAFROMPOINT(SHPCEN);
  IF CODFISC IS NULL THEN
    RAISE_APPLICATION_ERROR(-20008, 'Comune non trovato.');
  ELSE
    INSERT INTO SITITOPO(CODI_FISC_LUNA, SHAPE, SHAPELIM, TAVOLA, EDIZ, DATA, TOPONIMO, REGIONE, CODICE)
    VALUES(CODFISC, SHPCEN, SHPLIM, TAV, EDI, DAT, TOPO, REGI, COD);
  END IF;
END IMPORT_TOPONIMI;

PROCEDURE ASSEGNA_PART_STRADE(CODFISC IN VARCHAR2)
IS
  CURSOR C IS SELECT FOGLIO FROM SITIFGLC WHERE COD_NAZIONALE=CODFISC;
  FG NUMBER(4);
BEGIN
  DELETE FROM IMPO_SITISTRA;
  DELETE FROM SITISTRA WHERE COD_NAZIONALE=CODFISC;
  COMMIT;

  OPEN C;
  LOOP
    FETCH C INTO FG;
    EXIT WHEN C%NOTFOUND;

    INSERT INTO IMPO_SITISTRA(NUMERO, DNAZIONALE, FOGLIO, PARTICELLA, SUB, DATA_LAV)
    (
    SELECT B.NUMERO, A.COD_NAZIONALE, A.FOGLIO, A.PARTICELLA, A.SUB, sysdate
    FROM SITIPART A, SITIDSTR_GRAF B
    WHERE A.COD_NAZIONALE=CODFISC AND A.FOGLIO=FG AND A.COD_EDIF=3
    AND B.NUMERO<>'0'
    AND SDO_FILTER(B.SHAPE,(SELECT C.SHAPE FROM SITIFGLC C WHERE C.COD_NAZIONALE=CODFISC AND C.FOGLIO=FG AND C.ALLEGATO='0' AND C.SVILUPPO='0'),'QUERYTYPE=WINDOW')='TRUE'
    AND SDO_RELATE(A.SHAPE, SDO_GEOM.SDO_BUFFER(B.SHAPE,5,0.005),'MASK=ANYINTERACT QUERYTYPE=WINDOW')='TRUE'
    GROUP BY B.NUMERO, A.COD_NAZIONALE, A.FOGLIO, A.PARTICELLA, A.SUB
    );
    /*OVERLAPBDYINTERSECT*/
    COMMIT;
  END LOOP;
  CLOSE C;

  DELETE FROM IMPO_SITISTRA;
  COMMIT;
END;

FUNCTION GETCODEDIF(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBO IN VARCHAR2, DATAL IN VARCHAR2) RETURN NUMBER
IS
  CURSOR C IS SELECT COD_EDIF FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO AND DATA_INIZIO_VAL<=TO_DATE(DATAL, 'YYYYMMDDHH24MISS') AND DATA_FINE_VAL>=TO_DATE(DATAL, 'YYYYMMDDHH24MISS');
  RETVAL NUMBER:=2;
BEGIN
  OPEN C;
  FETCH C INTO RETVAL;
  IF C%NOTFOUND THEN RETVAL:=2; END IF;
  CLOSE C;
  RETURN RETVAL;
END GETCODEDIF;

FUNCTION GETCODNAZ(IISTATP IN VARCHAR2,IISTATC IN VARCHAR2,IID_SEZC IN VARCHAR2) RETURN VARCHAR2
IS
  CURSOR C1 IS SELECT A.COD_NAZIONALE FROM SITICOMU A WHERE A.ISTATP=IISTATP AND A.ISTATC=IISTATC AND A.ID_SEZC=IID_SEZC;
  CURSOR C2 IS SELECT A.COD_NAZIONALE FROM SITICOMU A WHERE A.ISTATP=IISTATP AND A.ISTATC=IISTATC AND A.ID_SEZC IS NULL;
  RETVAL VARCHAR2(4);
BEGIN
  IF IID_SEZC IS NULL THEN
    OPEN C2;
    FETCH C2 INTO RETVAL;
    IF C2%NOTFOUND THEN RETVAL:=NULL; END IF;
    CLOSE C2;
  ELSE
    OPEN C1;
    FETCH C1 INTO RETVAL;
    IF C1%NOTFOUND THEN RETVAL:=NULL; END IF;
    CLOSE C1;
  END IF;
  RETURN RETVAL;
END GETCODNAZ;

FUNCTION GETSIGLAPROV(CODNAZ IN VARCHAR2) RETURN VARCHAR2
IS
  CURSOR C1 IS SELECT A.SIGLA_PROV FROM SITICOMU A WHERE A.COD_NAZIONALE=CODNAZ;
  RETVAL VARCHAR2(4);
BEGIN
  OPEN C1;
  FETCH C1 INTO RETVAL;
  IF C1%NOTFOUND THEN RETVAL:=NULL; END IF;
  CLOSE C1;
  RETURN RETVAL;
END GETSIGLAPROV;

FUNCTION GETFLAG_CATA(CODNAZ IN VARCHAR2) RETURN NUMBER
IS
  CURSOR C1 IS SELECT A.FLAG_CATA FROM SITICOMU A WHERE A.COD_NAZIONALE=CODNAZ;
  RETVAL NUMBER;
BEGIN
  OPEN C1;
  FETCH C1 INTO RETVAL;
  IF C1%NOTFOUND THEN RETVAL:=NULL; END IF;
  CLOSE C1;
  RETURN RETVAL;
END GETFLAG_CATA;

FUNCTION GETPKIDSTRA(STRADA IN VARCHAR2,CODNAZ IN VARCHAR2) RETURN NUMBER
IS
  RETVAL NUMBER;
BEGIN
  SELECT PKID_STRA
  INTO RETVAL
  FROM SITIDSTR
  WHERE COD_NAZIONALE=CODNAZ AND NUMERO=STRADA AND ROWNUM=1;

  RETURN RETVAL;
  EXCEPTION
  WHEN No_Data_Found THEN
    DBMS_OUTPUT.put_line('Non trovo');
    RETURN NULL;
  WHEN others THEN
    DBMS_OUTPUT.put_line('Errore');
    RAISE;
    RETURN NULL;
END GETPKIDSTRA;

FUNCTION GETPKIDFIUM(FIUME IN VARCHAR2,CODNAZ IN VARCHAR2) RETURN NUMBER
IS
  RETVAL NUMBER;
BEGIN
  SELECT PKID_FIUM
  INTO RETVAL
  FROM SITIDFIU
  WHERE COD_NAZIONALE=CODNAZ AND NUMERO=FIUME AND ROWNUM=1;

  RETURN RETVAL;
  EXCEPTION
  WHEN No_Data_Found THEN
    DBMS_OUTPUT.put_line('Non trovo');
    RETURN NULL;
  WHEN others THEN
    DBMS_OUTPUT.put_line('Errore');
    RAISE;
    RETURN NULL;
END GETPKIDFIUM;

FUNCTION GETPKIDUIU(CODNAZ IN VARCHAR2,FOG IN NUMBER,PART IN VARCHAR2,SSUB IN VARCHAR2,UIMM IN NUMBER) RETURN NUMBER
IS
  CURSOR C1 IS SELECT A.PKID_UIU FROM SITIUIU A WHERE A.COD_NAZIONALE=CODNAZ AND A.FOGLIO=FOG AND A.PARTICELLA=PART AND A.SUB=SSUB AND A.UNIMM=UIMM AND A.DATA_FINE_VAL=To_Date('99991231000000','YYYYMMDDHH24MISS');
  RETVAL NUMBER;
BEGIN
  OPEN C1;
  FETCH C1 INTO RETVAL;
  IF C1%NOTFOUND THEN RETVAL:=NULL; END IF;
  CLOSE C1;

  RETURN RETVAL;
END GETPKIDUIU;

FUNCTION GETPKIDCIVI(PKSTRA IN NUMBER,CIV IN VARCHAR2) RETURN NUMBER
IS
  CURSOR C1 IS SELECT A.PKID_CIVI FROM SITICIVI A WHERE A.PKID_STRA=PKSTRA AND A.CIVICO=CIV AND A.DATA_FINE_VAL=To_Date('99991231000000','YYYYMMDDHH24MISS');
  RETVAL NUMBER;
BEGIN
  OPEN C1;
  FETCH C1 INTO RETVAL;
  IF C1%NOTFOUND THEN RETVAL:=NULL; END IF;
  CLOSE C1;

  RETURN RETVAL;
END GETPKIDCIVI;

PROCEDURE RINUMERA_PROGPOLIGONO
IS
  CURSOR C1 IS SELECT cod_nazionale,tavola,particella,sub,Count(*) FROM sitipoligoni GROUP BY cod_nazionale,tavola,particella,sub HAVING Count(*) > 1;
  CO CHAR(4);
  FO NUMBER(4);
  PA CHAR(5);
  SU VARCHAR2(3);
  NU NUMBER(4);
  I NUMBER(4);
BEGIN
  OPEN C1;
  LOOP
      FETCH C1 INTO CO,FO,PA,SU,NU;
      EXIT WHEN (C1%NOTFOUND);

      I:=1;
      WHILE I <= NU - 1
      LOOP
        UPDATE SITIPOLIGONI SET PROG_POLIGONO=((NU-I)+1) WHERE COD_NAZIONALE=CO AND TAVOLA=FO AND PARTICELLA=PA AND SUB=SU AND PROG_POLIGONO=1 AND ROWNUM=1;
        I:=I+1;
      END LOOP;
  END LOOP;
  CLOSE C1;
  COMMIT;
END RINUMERA_PROGPOLIGONO;

PROCEDURE IMPORTA_POLIGONI
IS
  CURSOR C1 IS SELECT se_row_id FROM sitipoligoni WHERE particella IS NOT NULL ORDER BY cod_nazionale,tavola,particella,sub;
  cse NUMBER(9);
BEGIN
  OPEN C1;
  LOOP
      FETCH C1 INTO cse;
      EXIT WHEN (C1%NOTFOUND);

      INSERISCIPOLIGONO(cse);
  END LOOP;
  CLOSE C1;
END IMPORTA_POLIGONI;

PROCEDURE INSERISCIPOLIGONO(cse IN NUMBER)
IS
  cf VARCHAR2(4);
  fo NUMBER(4);
  ta NUMBER(4);
  pa VARCHAR2(5);
  su VARCHAR2(3);
  pp NUMBER(5);
  df DATE;
  di DATE;
  dl DATE;
  sh mdsys.sdo_geometry;
  ac NUMBER(11,2);
  ut VARCHAR2(20);
  cu NUMBER(3);
  cc NUMBER(3);
  cv NUMBER(3);
  CURSOR C1 IS SELECT COD_NAZIONALE,FOGLIO,TAVOLA,PARTICELLA,SUB,PROG_POLIGONO,DATA_FINE_VAL,DATA_INIZIO_VAL,DATA_LAV,AREA_COLT,SHAPE,UTENTE,COD_UTIL,COD_COLTURA,COD_VARIETA FROM SITIPOLIGONI WHERE SE_ROW_ID=cse;
BEGIN
      OPEN C1;
      FETCH C1 INTO cf,fo,ta,pa,su,pp,df,di,dl,ac,sh,ut,cu,cc,cv;
      CLOSE C1;

      INSERT INTO sitisuolo
      (
      COD_NAZIONALE,FOGLIO,TAVOLA,PARTICELLA,SUB,prog_poligono,
      DATA_FINE_VAL,DATA_INIZIO_VAL,ALLEGATO,SVILUPPO,DATA_LAV,
      AREA_COLT,SHAPE,UTENTE,COD_UTIL,COD_COLTURA,COD_VARIETA,
      CAMPAGNA,SORGENTE
      )
      VALUES
      (
        cf,fo,ta,pa,su,pp,df,di,'0','0',dl,ac,sh,ut,cu,cc,cv,2004,4
      );
      COMMIT;

    EXCEPTION WHEN OTHERS THEN
      DBMS_OUTPUT.put_line ('SCARTATO SE_ROW_ID=' || cse);

END INSERISCIPOLIGONO;

FUNCTION getcodnaz_from_luna (icodifiscluna IN VARCHAR2,iid_sezc IN VARCHAR2) RETURN VARCHAR2
IS
  ritorno   VARCHAR2 (4);
BEGIN
  SELECT cod_nazionale
  INTO ritorno
  FROM siticomu
  WHERE codi_fisc_luna = icodifiscluna
  AND NVL (id_sezc, '_') = NVL (TRIM (UPPER (iid_sezc)), '_');

  RETURN ritorno;
  EXCEPTION
  WHEN NO_DATA_FOUND
  THEN
  RETURN '0000';
  WHEN OTHERS
  THEN
  RETURN '0000';
END;

FUNCTION GETCODIFISCLUNAFROMPOINT(SHP IN MDSYS.SDO_GEOMETRY) RETURN VARCHAR2
IS
  CODFISC VARCHAR2(4);
BEGIN
  SELECT (SELECT B.CODI_FISC_LUNA FROM SITICOMU B WHERE B.COD_PROVINCIA=A.ISTATP AND B.COD_COMUNE=A.ISTATC AND ROWNUM=1)
  INTO CODFISC
  FROM SITICOML A
  WHERE SDO_RELATE(A.SHAPE, SHP, 'MASK=CONTAINS QUERYTYPE=WINDOW')='TRUE';

  RETURN CODFISC;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN NULL;
  WHEN OTHERS THEN
    RETURN NULL;
END GETCODIFISCLUNAFROMPOINT;

END IMPORT_GIS_DATA;
/


DROP PACKAGE BODY SITI_H501.I18N_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.i18n_pck IS
  --------------------
  type t_langs is table of varchar2(10) index by binary_integer;

  --------------------
  function get_langs(p_lang varchar2) return t_langs is
    idx       pls_integer;
    idx_prec  pls_integer := 1;
    cnt       pls_integer := 0;
    l         varchar2(20);
    ret       t_langs;
  begin
    idx := instr(p_lang, '_', 1, 1);
    while idx > 0 loop
      l := l || substr(p_lang, idx_prec, idx - idx_prec);
      ret(cnt) := l;
      l := l || '_';
      idx_prec := idx + 1;
      idx := instr(p_lang, '_', idx_prec, 1);
      cnt := cnt + 1;
    end loop;
    l := l || substr(p_lang, idx_prec);
    ret(cnt) := l;

    return ret;
  end get_langs;

  --------------------
  function get_with_langs(p_lang t_langs, p_code varchar2, p_scope varchar2) return varchar2 is
    ret   varchar2(200);
    i     pls_integer;
  begin
    for i in reverse p_lang.first .. p_lang.last loop
      begin
        if p_scope is null then
          select descr into ret from i18n where lang = p_lang(i) and code= p_code and scope is null;
        else
          select descr into ret from i18n where lang = p_lang(i) and code= p_code and scope = p_scope;
        end if;

        -- Esco al primo match...
        exit;
      exception when no_data_found then
        null;
      end;
    end loop;

    if ret is null then
      if p_scope is null then
        raise no_data_found;
      else
        -- Provo a vedere se e' internazionalizzata sullo scope <null>
        ret := get_with_langs(p_lang, p_code, null);
      end if;
    end if;

    return ret;
  end get_with_langs;

  --------------------
  function get(p_lang varchar2, p_code varchar2, p_scope varchar2 default null) return varchar2 is
    m_scope   varchar2(30) := p_scope;
  begin
    return get_with_langs(get_langs(p_lang), p_code, p_scope);
  exception when no_data_found then
    return p_code;
  end get;
END;
/


DROP PACKAGE BODY SITI_H501.LOAD_CATASTO;

CREATE OR REPLACE PACKAGE BODY SITI_H501.load_catasto AS

	-- a.caleffi 2012-11-07 flag used in : load_uiu_tit, load_part_tit

	-- *AC* flag to allow debug output; 1 = debug on; 0 = debug off; default 0
	m_iDebug number(1) := 0;
	-- *AC* flag to allow sql insert/update; 1 = sql statements performed; 0 = sql disabled; default 1
	m_iSql number(1) := 1;


-- Tipi e variabili privati
  type atto_tp is record (
    COD_NAZIONALE   siticomu.COD_NAZIONALE%TYPE,
    ID_MUT          NUMBER,
    DATA            DATE,
    TP_ENTITA       char(1),
    COD_DIRITTO     VARCHAR2(3),
    TP_NOTA         CHAR(1),
    NUM_NOTA        VARCHAR2(6),
    PROGR_NOTA      VARCHAR2(3),
    ANNO_NOTA       VARCHAR2(4),
    COD_CAUSALE     VARCHAR2(3),
    DES_ATTO        VARCHAR2(100),
    prot_notifica   varchar2(18),
    data_notifica   date
  );

  DT_SIT_ATT   date := to_date('99991231', 'yyyymmdd');

-- Funzioni e procedure private
------------------------------------------------------------------------------
  function is_numeric(str in varchar2) return boolean is
    i     pls_integer;
  begin

    for i in 1..length(str) loop
      if instr('0123456789', substr(str, i, 1)) = 0 then
        return false;
      end if;
    end loop;

    return true;
  end is_numeric;

function merge_civ(civ1 varchar2, civ2 varchar2, civ3 varchar2) return varchar2 is
    civ varchar2(100);
  begin
	civ := null;
    if civ1 is not null then
    	civ := civ1;
	end if;
    if civ2 is not null then
    	if civ is not null then
        	civ := civ || '-';
        end if;
        civ := civ || civ2;
    end if;
    if civ3 is not null then
    	if civ is not null then
        	civ := civ || '-';
        end if;
        civ := civ || civ3;
    end if;

    if civ is null then
    	civ := 'SNC';
    else
    	civ := substr(civ, 1, 20);
    end if;

    return civ;
  end merge_civ;

