  function gestioneAtti(estremi atto_tp, pkCuaa number default null) return number is
  pkDoc     SITIFILE_DOCUMENTI.PKID_DOC%type;
    pkAtto        sitifile_atti.pkid_atto%type;
    tpTitolo      cons_atti_tab.tipo_titolo%type;
    codIden       cons_atti_tab.codice_iden%type;
    descrTpNota   cat_d_tiponota.descr%type;
  begin
    select FKID_DOC
      into pkDoc
      from SITIFILE_DOCUMENTI_CAMPI_EXT
     where SYS_ATTOCAT_ID_EXT = estremi.cod_nazionale || estremi.tp_entita || estremi.id_mut
       and rownum = 1;

    if estremi.cod_diritto is not null then
      update SITIFILE_DOCUMENTI_CAMPI_EXT
         set SYS_ATTOCAT_CODDIRITTO = estremi.cod_diritto
       where FKID_DOC = pkDoc;
    end if;

    select FKID_ATTO
      into pkAtto
      from SITIFILE_ATTI_DOC
     where FKID_DOC = pkDoc
       and rownum = 1;

    return pkAtto;

  exception
    when no_data_found then
      select sitifile_atti_seq.nextval
        into pkAtto
        from dual;

      insert into sitifile_atti (PKID_ATTO, FKID_TIPO_ATTO, DATA_AGGIORNAMENTO, UTENTE_INS, DATA_INS, VALIDO)
                         values (pkAtto, -1, sysdate, LOADER_USR,sysdate, 'Y');

      begin
        select descr
          into descrTpNota
          from cat_d_tiponota
         where pk_id = estremi.tp_entita || estremi.tp_nota;
      exception
        when no_data_found then
          descrTpNota := estremi.tp_entita || estremi.tp_nota;
      end;

      codIden :=  estremi.num_nota;
      if remove_lead_zero(estremi.progr_nota) is not null then
        codIden := codIden || '.' || remove_lead_zero(estremi.progr_nota);
      end if;
      if estremi.anno_nota is not null then
        codIden := codIden || '/' || estremi.anno_nota;
      end if;

      if estremi.cod_diritto = '10' then
        tpTitolo := '1';
      else
        tpTitolo := '9';
      end if;

      select SITIFILE_DOCUMENTI_seq.nextval
        into pkDoc
        from dual;

      INSERT INTO SITIFILE_DOCUMENTI (PKID_DOC, FKID_TIPO_DOC, DESCRIZIONE_BREVE, DATA_LAV, DATA_SCADENZA, COD_ARCHIVIAZIONE,
                                      UTENTE_INS, DATA_AGGIORNAMENTO, DESCRIZIONE_ESTESA, VALIDO)
                              VALUES (pkDoc, -1, 'Documento catastale', sysdate, DT_SIT_ATT, codIden,
                                      LOADER_USR, sysdate, nvl(estremi.des_atto, 'Documento caricato in fase di importazione dati catastali'), 'Y');


      INSERT INTO SITIFILE_DOCUMENTI_CAMPI_EXT (FKID_DOC, SYS_ATTOCAT_DATA, SYS_ATTOCAT_TPNOTA, SYS_ATTOCAT_NUMNOTA,
                                                SYS_ATTOCAT_PROGRNOTA, SYS_ATTOCAT_ANNONOTA, SYS_ATTOCAT_ID_EXT,
                                                SYS_ATTOCAT_CODDIRITTO, SYS_ATTOCAT_CODCAUSALE,
                                                SYS_ATTOCAT_PROT_NOT, SYS_ATTOCAT_DT_NOT)
                                        VALUES (pkDoc, estremi.data, estremi.tp_nota, estremi.num_nota,
                                                estremi.progr_nota, estremi.anno_nota, estremi.cod_nazionale || estremi.tp_entita || estremi.id_mut,
                                                estremi.cod_diritto, estremi.cod_causale,
                                                estremi.prot_notifica, estremi.data_notifica);

      INSERT INTO SITIFILE_ATTI_DOC (FKID_ATTO, FKID_DOC, NOTE, UTENTE_INS, DATA_AGGIORNAMENTO, DATA_INIZIO_VAL)
                             VALUES (pkAtto, pkDoc, null, LOADER_USR, sysdate, nvl(estremi.data, sysdate));

      return pkAtto;

  end gestioneAtti;

