  procedure spalma_titolarita_part(cod_naz in varchar2 default null) is
    CUSTOM_EXCEPTION_20080 EXCEPTION;
    PRAGMA EXCEPTION_INIT (CUSTOM_EXCEPTION_20080, -20080);

    cursor cPart is
    select *
      from sititrkc p
     where not exists
       (select 'X' from cons_cons_tab t
         where t.cod_nazionale = p.cod_nazionale
           and t.foglio = p.foglio
           and t.particella = p.particella
           and t.sub = p.sub
       )
       and data_fine = DT_SIT_ATT;


    dummy   cons_csui_tab.PKID_CSUI%type;

  begin

    begin
      select pkid_csui
        into dummy
        from cons_csui_tab
       where rownum = 1;
    exception when no_data_found then
      -- Inutile proseguire se non ci sono titolarita da spalmare...
      return;
    end;

    for rec in cPart loop
      censuario.CORREGGI_MILLESIMI(rec.cod_nazionale,
                                   rec.foglio,
                                   rec.particella,
                                   rec.sub,
                                   LOADER_USR,
                                   DT_SIT_ATT);

      begin
        aggiorna_terreni(rec.cod_nazionale,
                         rec.foglio,
                         rec.particella,
                         rec.sub,
                         DT_SIT_ATT,
                         LOADER_USR);
      exception when CUSTOM_EXCEPTION_20080 then
        null;
      end;

    end loop;

  end spalma_titolarita_part;

