  -- calcolo del canone periodico del canone di concessione acqua (REGIONE VENETO)
 FUNCTION get_val_loc_periodico_conc_h20(
  	 p_id_atto     		 NUMBER,
    p_id_doc      		 NUMBER,
    p_data_lav    		 DATE default sysdate,
	 p_canone_annuo 		 NUMBER default 0
 )
   RETURN dati_calcolo_type IS
    m_dati_calcolo                dati_calcolo_type;
  BEGIN
    -- inizializzo l'oggetto
    m_dati_calcolo := dati_calcolo_type (null, null, null, p_canone_annuo, null, null, 1, 0, 0, 0, null, null, 0, 0);

    -- periodicità
    SELECT (12 / NVL (p.periodo, 12))
      INTO m_dati_calcolo.periodo
      FROM sitifile_documenti_campi_ext ce, percan p
     WHERE ce.fkid_doc = p_id_doc AND p.codice = ce.sys_loc_cod_periodo;

    m_dati_calcolo.val_loc_periodico := m_dati_calcolo.val_loc / m_dati_calcolo.periodo;
    m_dati_calcolo.canone_periodico := p_canone_annuo / m_dati_calcolo.periodo;
    m_dati_calcolo.canone_periodico_noistat := m_dati_calcolo.canone_periodico;

    RETURN m_dati_calcolo;
 END get_val_loc_periodico_conc_h20;

