   /*
  *
  *    UTILITA' AL CONTRATTO DI CONCESSIONE
  *
  *
  */

---------------------------------------------------------------------------------------------

  FUNCTION calc_canone_conc_superficie (
    p_tipo_concessione                   NUMBER,
    p_superficie                         NUMBER,
    p_importo_sup                        NUMBER,
    importo_minimo                       NUMBER,
    importo_pertin                       NUMBER,
    riduzione_imbottigl                  NUMBER
  )
    RETURN NUMBER IS
    m_tipo_concessione            NUMBER := NVL (p_tipo_concessione, 0);
    m_canone                      NUMBER;
  BEGIN
    IF m_tipo_concessione >= 1 AND m_tipo_concessione <= 3 THEN
      m_canone :=
        (GREATEST (CEIL (p_superficie) * p_importo_sup, NVL (importo_minimo, 0))) * NVL (riduzione_imbottigl, 1)
        + importo_pertin;
    ELSE
      m_canone := (GREATEST (CEIL (p_superficie) * p_importo_sup, NVL (importo_minimo, 0))) + importo_pertin;
    END IF;

    RETURN m_canone;
  END calc_canone_conc_superficie;

---------------------------------------------------------------------------------------------

  FUNCTION calc_canone_conc_imbottigl (
    p_tipo_concessione                   NUMBER,
    mc_no_vetro                          NUMBER,
    mc_vetro                             NUMBER,
    mc_potabile                          NUMBER,
    importo_mc                           NUMBER,
    importo_pertin                       NUMBER
  )
    RETURN NUMBER IS
    m_tipo_concessione            NUMBER := NVL (p_tipo_concessione, 0);
    m_canone                      NUMBER;
  BEGIN
    IF m_tipo_concessione >= 1 AND m_tipo_concessione <= 3 THEN
      m_canone :=
        patri_canoni_pck.calc_mc_imbottigliamento (mc_no_vetro, mc_vetro, mc_potabile) * NVL (importo_mc, 0)
        + importo_pertin;
    ELSE
      m_canone := 0;
    END IF;

    RETURN m_canone;
  END calc_canone_conc_imbottigl;

---------------------------------------------------------------------------------------------

  FUNCTION calc_riduzione_imbottigl (mc_no_vetro NUMBER, mc_vetro NUMBER, mc_potabile NUMBER, limite NUMBER)
    RETURN NUMBER IS
  BEGIN
    IF calc_mc_imbottigliamento (mc_no_vetro, mc_vetro, mc_potabile) < NVL (limite, 0) THEN
      RETURN 0.5;
    ELSE
      RETURN 1;
    END IF;
  END calc_riduzione_imbottigl;

---------------------------------------------------------------------------------------------

  FUNCTION calc_mc_imbottigliamento (mc_no_vetro NUMBER, mc_vetro NUMBER, mc_potabile NUMBER)
    RETURN NUMBER IS
  BEGIN
    RETURN NVL (mc_no_vetro, 0) + NVL (mc_vetro, 0) * 0.1 - NVL (mc_potabile, 0);
  END calc_mc_imbottigliamento;

---------------------------------------------------------------------------------------------

  PROCEDURE updateconcessionianno (p_id_atto NUMBER, p_id_doc NUMBER) IS
    m_id_atto                     NUMBER := p_id_atto;
    m_id_atto_sup                 NUMBER;
    m_cod_calcolo                 VARCHAR2 (2);
    m_id_cc                       NUMBER;
    m_tipo_sup                    NUMBER;
    m_sup_concessione             NUMBER;
    m_codice_contr_imb            VARCHAR2 (10);
    m_impo_pertin                 NUMBER;
    m_id_cca                      NUMBER;
    m_importo_sup                 NUMBER;
    m_importo_minimo              NUMBER;
    m_importo_sup                 NUMBER := 0;
  BEGIN
    -- verifico il tipo di contratto
    BEGIN
      SELECT cod_calcolo_canone
        INTO m_cod_calcolo
        FROM patri_loc_tipo_contr
       WHERE fkid_doc = p_id_doc;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_cod_calcolo := '';
    END;

    -- se è un contratto di imbottigliamento
    IF TRIM (m_cod_calcolo) = patri_canoni_pck.canone_conc_imbottiglia THEN
      BEGIN
        SELECT CAST (cc.codice_contr_sup AS NUMBER), cc1.tipo_sup, NVL (cc.impo_pertin, 0)
          INTO m_id_atto_sup, m_tipo_sup, m_impo_pertin
          FROM contratt_concessioni_h2o cc, contratt_concessioni_h2o cc1
         WHERE cc.codice = CAST (m_id_atto AS VARCHAR2 (10)) AND cc.codice_contr_sup = cc1.codice;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          raise_application_error (-20010, 'contratto di imbottigliamento non legato ad una concessione di superficie');
      END;

      -- aggiorno i canoni del contratto di imbottigliamento
      UPDATE contratt_concessioni_anno_h2o a
         SET applicato_anno =
               (SELECT patri_canoni_pck.calc_canone_conc_imbottigl (m_tipo_sup, mc_h2o_no_vetro, mc_h2o_vetro,
                                                                     mc_h2o_potabile_pub, NVL (euro_per_mc, 0),
                                                                     m_impo_pertin)
                  FROM contratt_concessioni_anno_h2o
                 WHERE codice = CAST (m_id_atto AS VARCHAR2 (10)) AND ID = a.ID)
       WHERE a.codice = CAST (p_id_atto AS VARCHAR2 (10));

      -- Imposto m_mod_calcolo e m_id_atto in modo che puntino al contratto di superfice
      -- e quindi vengano aggiornati i relativi canoni
      m_cod_calcolo := patri_canoni_pck.canone_conc_superfici;
      m_id_atto := m_id_atto_sup;
    END IF;

    IF TRIM (m_cod_calcolo) = patri_canoni_pck.canone_conc_superfici THEN
      BEGIN
        -- cerco i dati del contratto
        SELECT cc.ID, cc.tipo_sup, NVL (cc.sup_concessione_mq, 0), cc1.codice, NVL (cc.impo_pertin, 0)
          INTO m_id_cc, m_tipo_sup, m_sup_concessione, m_codice_contr_imb, m_impo_pertin
          FROM contratt_concessioni_h2o cc LEFT JOIN contratt_concessioni_h2o cc1 ON cc.codice = cc1.codice_contr_sup
         WHERE cc.codice = CAST (m_id_atto AS VARCHAR2 (10));

        -- Se non c'è un contratto di imbottigliamento legato a questo contratto di superfice
        -- il canone va calcolato come se fosse di tipo 4 (termale curativa)
        IF m_codice_contr_imb IS NULL THEN
          m_tipo_sup := 4;
        END IF;

        -- Conversione della superficie in base al tipo_sup
        IF m_tipo_sup = 6 OR m_tipo_sup = 7 THEN
          m_sup_concessione := m_sup_concessione / 1000000;
        ELSE
          m_sup_concessione := m_sup_concessione / 10000;
        END IF;

        -- codice da 1 a 3 sono contratti di superficie che possono essere legati
        -- a contratti di imbottigliamento
        IF (m_tipo_sup = 1 OR m_tipo_sup = 2 OR m_tipo_sup = 3) AND m_codice_contr_imb IS NOT NULL THEN
          UPDATE contratt_concessioni_anno_h2o a
             SET applicato_anno =
                   (SELECT patri_canoni_pck.calc_canone_conc_superficie (m_tipo_sup, m_sup_concessione,
                                                                          cca.euro_per_sup, cca.minimo, m_impo_pertin,
                                                                          cca1.h2o_factor)
                      FROM contratt_concessioni_anno_h2o cca
                           LEFT JOIN
                           (SELECT patri_canoni_pck.calc_riduzione_imbottigl (mc_h2o_no_vetro,
                                                                               mc_h2o_vetro,
                                                                               mc_h2o_potabile_pub,
                                                                               NVL (limite_mc, 0)) AS h2o_factor,
                                   anno
                              FROM contratt_concessioni_anno_h2o
                             WHERE codice = CAST (NVL (m_codice_contr_imb, 0) AS VARCHAR2 (10))) cca1
                           ON cca.anno = cca1.anno
                     WHERE cca.codice = CAST (m_id_atto AS VARCHAR2 (10)) AND a.ID = cca.ID)
           WHERE a.codice = CAST (m_id_atto AS VARCHAR2 (10));
        ELSE
          UPDATE contratt_concessioni_anno_h2o a
             SET applicato_anno =
                   (SELECT patri_canoni_pck.calc_canone_conc_superficie (m_tipo_sup, m_sup_concessione, euro_per_sup,
                                                                          minimo, m_impo_pertin, 1)
                      FROM contratt_concessioni_anno_h2o
                     WHERE codice = CAST (m_id_atto AS VARCHAR2 (10)) AND ID = a.ID)
           WHERE a.codice = CAST (m_id_atto AS VARCHAR2 (10));
        END IF;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          RAISE;
      END;
    END IF;
  END updateconcessionianno;

---------------------------------------------------------------------------------------------

END;
/


DROP PACKAGE BODY SITI_H501.PATRI_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.patri_pck IS
  TYPE indirizzo_t IS RECORD (
    numero                        aggr_topo.numero%TYPE,
    civico                        aggr_localizza.nome%TYPE,
    interno                       siticivi_uiu.interno%TYPE,
