  );

  TYPE sc_tedi_t IS RECORD (
    supe_terreno                  NUMBER,
    supe_c6                       NUMBER,
    supe_no_c6                    NUMBER,
    supe_c6_cop                   NUMBER,
    supe_c6_scop                  NUMBER,
    supe_verde_com                NUMBER,
    supe_escl_god                 NUMBER,
    coef_tipol_cat                NUMBER,
    coef_cl_dem                   NUMBER,
    coef_ubicaz                   NUMBER,
    coef_liv_piano                NUMBER,
    coef_stato_cons               NUMBER,
    coef_verde_com                NUMBER,
    mese_costr                    NUMBER,
    anno_costr                    NUMBER,
    mese_ristr                    NUMBER,
    anno_ristr                    NUMBER,
	 vani_utili							 NUMBER
  );

  TYPE ana_inqui_t IS RECORD (
    reddito_ne                    NUMBER,
    reddito_si                    NUMBER,
    reddito_au                    NUMBER,
    reddito_tot                   NUMBER,
    reddito_pe                    NUMBER,
