  ultimo_sc_tedi                sc_tedi_t;
  ultimo_ana_inqui              ana_inqui_t;
  ultimo_ind                    indirizzo_t;
  ultimo_tp_estrom              CHAR (1);

  PROCEDURE subentro_log (
    p_codice                             VARCHAR2,
    p_cod_ces                            VARCHAR2,
    p_cod_inq_in                         NUMBER,
    p_perc_spese_inq_in                  NUMBER,
    p_fattura_in                         CHAR,
    p_data_uscita_out                    DATE,
    p_tipo_uscita_out                    CHAR,
    p_id_impreg_out                      NUMBER,
    p_id_co_out                          NUMBER,
    p_err_code                           NUMBER,
    p_err_msg                            VARCHAR2,
    p_user_log                           VARCHAR2 DEFAULT NULL
  ) IS
    PRAGMA AUTONOMOUS_TRANSACTION;
  BEGIN
    INSERT INTO subentro_log
                (codice,
                 cod_ces,
                 cod_inq_in,
                 perc_spese_inq_in,
                 fattura_in,
                 data_uscita_out,
                 tipo_uscita_out,
                 id_impreg_out,
                 id_co_out,
                 codice_err,
                 msg_err,
                 date_log,
                 user_log
                )
         VALUES (p_codice,
                 p_cod_ces,
                 p_cod_inq_in,
                 p_perc_spese_inq_in,
                 p_fattura_in,
                 p_data_uscita_out,
                 p_tipo_uscita_out,
                 p_id_impreg_out,
                 p_id_co_out,
                 p_err_code,
                 p_err_msg,
                 SYSDATE,
                 p_user_log
                );

    COMMIT;
  END subentro_log;

  PROCEDURE setinventario (codice IN sitiente.cod_ente%TYPE) IS
  BEGIN
    inventario := codice;
  END setinventario;

  FUNCTION getinventario
    RETURN sitiente.cod_ente%TYPE IS
  BEGIN
    RETURN inventario;
  END getinventario;

  FUNCTION get_cespite_padre (p_pk_cespite NUMBER)
    RETURN NUMBER IS
    m_num_part_uiu                NUMBER;
    m_cod_naz                     VARCHAR2 (4);
    m_foglio                      NUMBER;
    m_particella                  VARCHAR2 (5);
    m_sub                         VARCHAR2 (3);
    m_pkcespite_padre             NUMBER;
    m_data_inizio                 DATE;
    m_data_fine                   DATE;
    m_is_proprieta                NUMBER;
  BEGIN
    -- verifico se nel cespite ci sono particelle
    SELECT NVL (COUNT (*), 0)
      INTO m_num_part_uiu
      FROM (SELECT   sa.cod_nazionale,
                     sa.foglio,
                     sa.particella,
                     sa.sub
                FROM patri_cespiti_part pcp, siticond_all2 sa
               WHERE pcp.fk_cespite = p_pk_cespite AND pcp.pk_tit = sa.pkid_tit AND pcp.tipo_titolo = sa.tipo_titolo
            GROUP BY sa.cod_nazionale, sa.foglio, sa.particella, sa.sub);

    -- se nel cespite non ci sono particelle verifico se ci sono uiu che non sono sulla stessa particella
    IF m_num_part_uiu = 0 THEN
      SELECT NVL (COUNT (*), 0)
        INTO m_num_part_uiu
        FROM (SELECT   sia.cod_nazionale,
                       sia.foglio,
                       sia.particella,
                       sia.sub
                  FROM patri_cespiti_uiu pcu, siticonduz_imm_all2 sia
                 WHERE pcu.fk_cespite = p_pk_cespite AND pcu.pk_tit = sia.pkid_tit AND pcu.tipo_titolo = sia.tipo_titolo
              GROUP BY sia.cod_nazionale, sia.foglio, sia.particella, sia.sub);
    ELSE
      m_num_part_uiu := 0;
    END IF;

       --
    /*
    * Se m_num_part_uiu != 1 significa che nel cespite ci sono delle particelle o delle uiu che non sono
    * sulla stessa particella
    */
    IF m_num_part_uiu != 1 THEN
      m_pkcespite_padre := NULL;
    ELSE
      -- verifico se il tipo titolo del cespite ï¿½ di proprietï¿½
      SELECT titoli_pck.is_titolo_proprieta (tipo_titolo)
        INTO m_is_proprieta
        FROM patri_cespiti_uiu
       WHERE fk_cespite = p_pk_cespite AND ROWNUM = 1;

      -- trovo i dati catastali e le date di validitï¿½ della particella corrispondente alle uiu
      SELECT   sia.cod_nazionale,
               sia.foglio,
               sia.particella,
               sia.sub,
               MIN (sia.data_inizio),
               MAX (sia.data_fine)
          INTO m_cod_naz,
               m_foglio,
               m_particella,
               m_sub,
               m_data_inizio,
               m_data_fine
          FROM patri_cespiti_uiu pcu, siticonduz_imm_all2 sia
         WHERE pcu.fk_cespite = p_pk_cespite AND pcu.pk_tit = sia.pkid_tit AND pcu.tipo_titolo = sia.tipo_titolo
      GROUP BY sia.cod_nazionale, sia.foglio, sia.particella, sia.sub;

      -- trovo il cespite corrispondente alla particella
      BEGIN
        --select pcp.fk_cespite
        SELECT MIN (pcp.fk_cespite)
          INTO m_pkcespite_padre
          FROM patri_cespiti_part pcp,
               (SELECT pkid_tit,
                       tipo_titolo
                  FROM siticond_all2
                 WHERE cod_nazionale = m_cod_naz AND foglio = m_foglio AND particella = m_particella AND sub = m_sub
                       AND data_inizio <= m_data_inizio AND data_fine >= m_data_inizio
                       AND titoli_pck.is_titolo_proprieta (tipo_titolo) = m_is_proprieta) sa
         WHERE pcp.pk_tit = sa.pkid_tit AND pcp.tipo_titolo = sa.tipo_titolo;
      --and rownum = 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          m_pkcespite_padre := NULL;
      END;
    END IF;

    RETURN m_pkcespite_padre;
  END get_cespite_padre;

  PROCEDURE aggiorna_figli_fabbricato (p_pk_cespite NUMBER) IS
    m_num_part_uiu                NUMBER;
    m_cod_naz                     VARCHAR2 (4);
    -- a.caleffi 2008-10-29 cambiato da NUMBER a NUMBER(4)
    m_foglio                      NUMBER (4);
    m_particella                  VARCHAR2 (5);
    -- a.caleffi 2008-10-29 cambiato da varchar2(1) a varchar2(3)
    m_sub                         VARCHAR2 (3);
    m_data_inizio                 DATE;
    m_data_fine                   DATE;
    m_is_proprieta                NUMBER;
    m_cod_cespite                 VARCHAR2 (12);
  BEGIN
    -- leggo il codice cespite del cespite
    SELECT cod_cespite
      INTO m_cod_cespite
      FROM patri_cespiti
     WHERE pk_cespite = p_pk_cespite;

    -- verifico se nel cespite ci sono uiu
    SELECT NVL (COUNT (*), 0)
      INTO m_num_part_uiu
      FROM (SELECT   sia.cod_nazionale,
                     sia.foglio,
                     sia.particella,
                     sia.sub
                FROM patri_cespiti_uiu pcu, siticonduz_imm_all2 sia
               WHERE pcu.fk_cespite = p_pk_cespite AND pcu.pk_tit = sia.pkid_tit AND pcu.tipo_titolo = sia.tipo_titolo
            GROUP BY sia.cod_nazionale, sia.foglio, sia.particella, sia.sub);

    -- verifico se nel cespite ci sono particelle
    IF m_num_part_uiu = 0 THEN
      SELECT NVL (COUNT (*), 0)
        INTO m_num_part_uiu
        FROM (SELECT   sa.cod_nazionale,
                       sa.foglio,
                       sa.particella,
                       sa.sub
                  FROM patri_cespiti_part pcp, siticond_all2 sa
                 WHERE pcp.fk_cespite = p_pk_cespite AND pcp.pk_tit = sa.pkid_tit AND pcp.tipo_titolo = sa.tipo_titolo
              GROUP BY sa.cod_nazionale, sa.foglio, sa.particella, sa.sub);
    ELSE
      m_num_part_uiu := 0;
    END IF;

    -- se nel cespite c'ï¿½ solo una particella cerco tutte le uiu di questa particella
    IF m_num_part_uiu = 1 THEN
      -- verifico se il tipo titolo del cespite ï¿½ di proprietï¿½
      SELECT titoli_pck.is_titolo_proprieta (tipo_titolo)
        INTO m_is_proprieta
        FROM patri_cespiti_part
       WHERE fk_cespite = p_pk_cespite AND ROWNUM = 1;

      -- trovo i dati catastali e le date di validitï¿½ della particella
      SELECT   sa.cod_nazionale,
               sa.foglio,
               sa.particella,
               sa.sub,
               MIN (sa.data_inizio),
               MAX (sa.data_fine)
          INTO m_cod_naz,
               m_foglio,
               m_particella,
               m_sub,
               m_data_inizio,
               m_data_fine
          FROM patri_cespiti_part pcp, siticond_all2 sa
         WHERE pcp.fk_cespite = p_pk_cespite AND pcp.pk_tit = sa.pkid_tit AND pcp.tipo_titolo = sa.tipo_titolo
      GROUP BY sa.cod_nazionale, sa.foglio, sa.particella, sa.sub;

      -- aggiorno i cespiti delle uiu
      FOR ruiu IN (SELECT pcu.fk_cespite
                     FROM patri_cespiti_uiu pcu,
                          (SELECT pkid_tit,
                                  tipo_titolo
                             FROM siticonduz_imm_all2
                            WHERE cod_nazionale = m_cod_naz AND foglio = m_foglio AND particella = m_particella
                                  AND sub = m_sub AND data_inizio <= m_data_inizio AND data_fine >= m_data_inizio
                                  AND titoli_pck.is_titolo_proprieta (tipo_titolo) = m_is_proprieta) sia
                    WHERE pcu.pk_tit = sia.pkid_tit AND pcu.tipo_titolo = sia.tipo_titolo) LOOP
        UPDATE patri_cespiti
           SET cod_gruppo = TRIM (m_cod_cespite)
         WHERE pk_cespite = ruiu.fk_cespite;
      END LOOP;
    ELSE
      UPDATE patri_cespiti
         SET cod_gruppo = NULL
       WHERE TRIM (cod_gruppo) = TRIM (m_cod_cespite);
    END IF;
  END aggiorna_figli_fabbricato;

  FUNCTION get_tipo_acquisizione (id_tit NUMBER, tp_tit VARCHAR2)
    RETURN NUMBER IS
    dtiniziotit                   DATE;
    cn                            sitipart.cod_nazionale%TYPE;
    fg                            sitipart.foglio%TYPE;
    pa                            sitipart.particella%TYPE;
    subo                          sitipart.sub%TYPE;
    un                            sitiuiu.unimm%TYPE := NULL;
    cnt                           PLS_INTEGER;
    ret                           NUMBER := NULL;
    etype                         CHAR (1) := NULL;
  BEGIN
    /*
     0 = Acquisto
     2 = Accorpamento
     3 = Frazionamento
     */
    BEGIN
      SELECT 'P'
        INTO etype
        FROM siticond_all2
       WHERE pkid_tit = id_tit AND tipo_titolo = tp_tit;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        etype := 'U';
    END;

    IF etype = 'P' THEN
      SELECT cod_nazionale,
             foglio,
             particella,
             sub,
             data_inizio
        INTO cn,
             fg,
             pa,
             subo,
             dtiniziotit
        FROM siticond_all2
       WHERE pkid_tit = id_tit AND tipo_titolo = tp_tit;

      SELECT COUNT (*)
        INTO cnt
        FROM siticond_all2
       WHERE cod_nazionale = cn AND foglio = fg AND particella = pa AND sub = subo AND data_fine <= dtiniziotit;

      ret := 0;

      IF cnt = 0 THEN
        -- Non ci sono titolaritï¿½ precedenti...
        SELECT COUNT (*)
          INTO cnt
          FROM sititrkc
         WHERE cod_nazionale = cn AND foglio = fg
               --and particella = pa
               --and sub = subo
               AND atto_fin =
                    (SELECT atto_ini
                       FROM sititrkc
                      WHERE cod_nazionale = cn AND foglio = fg AND particella = pa AND sub = subo
                            AND data_aggi <= dtiniziotit AND data_fine >= dtiniziotit);

        IF cnt > 1 THEN
          -- + di un record ha creato questa UIU quini ï¿½ un accorpameno
          ret := 2;
        ELSIF cnt = 1 THEN
          -- E' un probabile frazionamento
          ret := 3;
        END IF;
      END IF;
    ELSE
      SELECT cod_nazionale,
             foglio,
             particella,
             sub,
             unimm,
             data_inizio
        INTO cn,
             fg,
             pa,
             subo,
             un,
             dtiniziotit
        FROM siticonduz_imm_all2
       WHERE pkid_tit = id_tit AND tipo_titolo = tp_tit;

      SELECT COUNT (*)
        INTO cnt
        FROM siticonduz_imm_all2
       WHERE cod_nazionale = cn AND foglio = fg AND particella = pa AND sub = subo AND unimm = un
             AND data_fine <= dtiniziotit;

      ret := 0;

      IF cnt = 0 THEN
        -- Non ci sono titolaritï¿½ precedenti...
        SELECT COUNT (*)
          INTO cnt
          FROM sitiuiu
         WHERE cod_nazionale = cn AND foglio = fg AND particella = pa AND sub = subo
               --and unimm = un
               AND atto_fin =
                    (SELECT atto_ini
                       FROM sitiuiu
                      WHERE cod_nazionale = cn AND foglio = fg AND particella = pa AND sub = subo AND unimm = un
                            AND data_inizio_val <= dtiniziotit AND data_fine_val >= dtiniziotit);

        IF cnt > 1 THEN
          -- + di un record ha creato questa UIU quini ï¿½ un accorpameno
          ret := 2;
        ELSIF cnt = 1 THEN
          -- E' un probabile frazionamento
          ret := 3;
        END IF;
      END IF;
    END IF;

    RETURN ret;
  END get_tipo_acquisizione;

  FUNCTION get_tipo_acquisizione (pk_ces NUMBER)
    RETURN NUMBER IS
    id_tit                        patri_cespiti_part.pk_tit%TYPE;
    tp_tit                        patri_cespiti_part.tipo_titolo%TYPE;
    ret                           NUMBER;
  BEGIN
    BEGIN
      SELECT pk_tit,
             tipo_titolo
        INTO id_tit,
             tp_tit
        FROM patri_cespiti_part
       WHERE fk_cespite = pk_ces AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT pk_tit,
                 tipo_titolo
            INTO id_tit,
                 tp_tit
            FROM patri_cespiti_uiu
           WHERE fk_cespite = pk_ces AND ROWNUM = 1;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            NULL;
        END;
    END;

    IF id_tit IS NOT NULL THEN
      ret := get_tipo_acquisizione (id_tit, tp_tit);
    END IF;

    RETURN ret;
  END get_tipo_acquisizione;

  FUNCTION init_estromissione (p_id_ces NUMBER)
    RETURN DATE IS
    dt                            DATE := NULL;
    cnt                           PLS_INTEGER;
  BEGIN
    -- Controllare che:
    -- a. Tutte le TIT del cespite siano cessate
    -- b. cnt = quante titolaritï¿½ nuove ci sono a paritï¿½ di estremi catastali
    -- c. se cnt > 0 allora V else A
    SELECT MAX (data_fine)
      INTO dt
      FROM (SELECT t.data_fine
              FROM patri_cespiti_part ce, siticond_all2 t
             WHERE ce.fk_cespite = p_id_ces AND t.pkid_tit = ce.pk_tit AND t.tipo_titolo = ce.tipo_titolo
            UNION ALL
            SELECT data_fine
              FROM patri_cespiti_uiu ce, siticonduz_imm_all2 t
             WHERE ce.fk_cespite = p_id_ces AND t.pkid_tit = ce.pk_tit AND t.tipo_titolo = ce.tipo_titolo);

    IF dt < SYSDATE THEN
      SELECT COUNT (*)
        INTO cnt
        FROM (SELECT 1
                FROM patri_cespiti_part ce, siticond_all2 t
               WHERE ce.fk_cespite = p_id_ces AND t.pkid_tit = ce.pk_tit AND t.tipo_titolo = ce.tipo_titolo
                     AND t.data_fine <= SYSDATE
                     AND EXISTS (
                          SELECT 1
                            FROM siticond_all2
                           WHERE cod_nazionale = t.cod_nazionale AND foglio = t.foglio AND particella = t.particella
                                 AND sub = t.sub AND data_fine > SYSDATE)
              UNION
              SELECT 1
                FROM patri_cespiti_uiu ce, siticonduz_imm_all2 t
               WHERE ce.fk_cespite = p_id_ces AND t.pkid_tit = ce.pk_tit AND t.tipo_titolo = ce.tipo_titolo
                     AND t.data_fine <= SYSDATE
                     AND EXISTS (
                          SELECT 1
                            FROM siticonduz_imm_all2
                           WHERE cod_nazionale = t.cod_nazionale AND foglio = t.foglio AND particella = t.particella
                                 AND sub = t.sub AND unimm = t.unimm AND data_fine > SYSDATE));

      IF cnt > 0 THEN
        ultimo_tp_estrom := 'V';
      ELSE
        ultimo_tp_estrom := 'A';
      END IF;
    ELSE
      dt := NULL;
      ultimo_tp_estrom := NULL;
    END IF;

    RETURN dt;
  END init_estromissione;

  FUNCTION get_estromesso
    RETURN CHAR IS
    ret                           CHAR (1);
  BEGIN
    IF ultimo_tp_estrom IS NOT NULL THEN
      RETURN 'S';
    ELSE
      RETURN 'N';
    END IF;
  END get_estromesso;

  FUNCTION get_tipo_estromissione
    RETURN CHAR IS
  BEGIN
    RETURN ultimo_tp_estrom;
  END get_tipo_estromissione;

  FUNCTION init_indirizzo (pk_ces NUMBER)
    RETURN VARCHAR2 IS
  BEGIN
    SELECT *
	 INTO ultimo_ind
  	 FROM (SELECT   numero, civico, interno, scala, piano
            FROM (SELECT str.numero, civ.civico, civ_u.interno, civ_u.scala, civ_u.piano, civ_u.principale,
                         civ_u.data_fine_val
                    FROM patri_cespiti pc,
                         patri_cespiti_uiu cu,
                         siticonduz_imm_all2 t,
                         sitiuiu u,
                         siticivi_uiu civ_u,
                         siticivi civ,
                         sitidstr str
                   WHERE pc.pk_cespite = pk_ces
                     AND cu.fk_cespite = pc.pk_cespite
                     AND t.data_inizio <= pc.data_fine_val
                     AND t.data_fine >= pc.data_fine_val
                     AND t.pkid_tit = cu.pk_tit
                     AND t.tipo_titolo = cu.tipo_titolo
                     AND u.cod_nazionale = t.cod_nazionale
                     AND u.foglio = t.foglio
                     AND u.particella = t.particella
                     AND u.sub = t.sub
                     AND u.unimm = t.unimm
                     AND u.data_inizio_val <= pc.data_fine_val
                     AND u.data_fine_val >= pc.data_fine_val
                     AND civ_u.pkid_uiu = u.pkid_uiu
                     AND civ.pkid_civi = civ_u.pkid_civi
                     AND str.pkid_stra = civ.pkid_stra
                  UNION
                  SELECT str.numero, NULL AS civico, NULL AS interno, NULL AS scala, NULL AS piano, NULL AS principale,
                         ppe.data_fine_val
                    FROM patri_cespiti pc,
                         patri_cespiti_part cp,
                         siticond_all2 t,
                         sititrkc p,
                         patri_part_ext ppe,
                         sitidstr str
                   WHERE pc.pk_cespite = pk_ces
                     AND cp.fk_cespite = pc.pk_cespite
                     AND t.data_inizio <= pc.data_fine_val
                     AND t.data_fine >= pc.data_fine_val
                     AND t.pkid_tit = cp.pk_tit
                     AND t.tipo_titolo = cp.tipo_titolo
                     AND p.cod_nazionale = t.cod_nazionale
                     AND p.foglio = t.foglio
                     AND p.particella = t.particella
                     AND p.sub = t.sub
                     AND p.data_aggi <= pc.data_fine_val
                     AND p.data_fine >= pc.data_fine_val
                     AND p.cod_nazionale = ppe.cod_nazionale
                     AND p.foglio = ppe.foglio
                     AND p.particella = ppe.particella
                     AND p.sub = ppe.sub
                     AND ppe.cod_via = str.pkid_stra
                     AND p.data_aggi <= ppe.data_fine_val
                     AND p.data_fine >= ppe.data_fine_val)
        ORDER BY principale DESC, data_fine_val DESC)
 WHERE ROWNUM = 1;


    RETURN ultimo_ind.numero;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
