     WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
           AND v.cod_nazionale = t.cod_nazionale AND v.foglio = t.foglio AND v.particella = t.particella
