  FUNCTION get_numero_vani (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
    p_dt                                 DATE
  )
    RETURN NUMBER IS
    num_vani                      NUMBER := 0;
  BEGIN
    BEGIN
      SELECT COUNT (*)
        INTO num_vani
        FROM sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
       WHERE v.cod_nazionale = p_codnaz AND v.foglio = p_foglio AND v.particella = p_particella AND v.sub = p_sub
             AND v.unimm = p_unimm AND v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio
             AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm AND e.data_inizio_val <= p_dt
             AND e.data_fine_val >= p_dt AND v.data_inizio_val <= p_dt AND v.data_fine_val >= p_dt
             AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        num_vani := 0;
    END;

    RETURN num_vani;
  END get_numero_vani;

