  END;

  FUNCTION get_superficie_cespite (p_pk_cespite NUMBER, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_suptot                      NUMBER := 0;
    m_supu                        NUMBER := 0;
    m_supp                        NUMBER := 0;
    m_dt_inizio_ces               DATE := NULL;
    m_dt_fine_ces                 DATE := NULL;
  BEGIN
    -- calcolo superfici particella/e
    BEGIN
      /*
         SELECT NVL (SUM (area_part), 0) AS supp
           INTO m_supp
           FROM sititrkc
          WHERE (cod_nazionale, foglio, particella, sub) IN (
                  SELECT t.cod_nazionale,
                         t.foglio,
                         t.particella,
                         t.sub
                    FROM patri_cespiti_part c, siticond_all2 t
                   WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                         AND t.data_inizio <= p_date AND t.data_fine >= p_date)
                AND data_aggi <= p_date AND data_fine >= p_date;
      */
      SELECT NVL (SUM (DECODE (supp, -1, 0, supp)), 0)
        INTO m_supp
        FROM (SELECT titoli_pck.get_superficie_part (st.cod_nazionale, st.foglio, st.particella, st.sub, p_date)
                                                                                                                AS supp
                FROM patri_cespiti_part c, siticond_all2 t, sititrkc st
               WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                     AND t.data_inizio <= p_date AND t.data_fine >= p_date AND t.cod_nazionale = st.cod_nazionale
                     AND t.foglio = st.foglio AND t.particella = st.particella AND t.sub = st.sub
                     AND st.data_aggi <= p_date AND st.data_fine >= p_date);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_supp := 0;
    END;

    -- calcolo superfici uiu
    BEGIN
       /*
        SELECT NVL (SUM (titoli_pck.get_superficie_uiu (t.cod_nazionale, t.foglio, t.particella, t.sub, t.unimm, p_date)),
                    0)
          INTO m_supu
          FROM patri_cespiti_uiu cu, siticonduz_imm_all2 t
         WHERE cu.fk_cespite = p_pk_cespite AND t.pkid_tit = cu.pk_tit AND t.tipo_titolo = cu.tipo_titolo
               AND t.data_inizio <= p_date AND t.data_fine >= p_date;
      */
      SELECT NVL (SUM (DECODE (supp, -1, 0, supp)), 0)
        INTO m_supu
        FROM (SELECT titoli_pck.get_superficie_uiu (st.cod_nazionale, st.foglio, st.particella, st.sub, st.unimm,
                                                    p_date) AS supp
                FROM patri_cespiti_uiu c, siticonduz_imm_all2 t, sitiuiu st
               WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                     AND t.data_inizio <= p_date AND t.data_fine >= p_date AND t.cod_nazionale = st.cod_nazionale
                     AND t.foglio = st.foglio AND t.particella = st.particella AND t.sub = st.sub AND t.unimm = st.unimm
                     AND st.data_inizio_val <= p_date AND st.data_fine_val >= p_date);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_supu := 0;
    END;

    m_suptot := m_supp + m_supu;
    RETURN m_suptot;
  END get_superficie_cespite;

    /*
    FUNCTION get_superficie_cespite_locata (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_date DATE DEFAULT SYSDATE)
      RETURN NUMBER IS
      m_suptot                      NUMBER := 0;
      m_sump                        NUMBER := 0;
      m_sumu                        NUMBER := 0;
      m_dt_fine_ces                 DATE := NULL;
      m_dt_inizio_ces               DATE := NULL;
      m_existpart                   NUMBER := -1;
      m_existuiu                    NUMBER := -1;
      m_multiple_rent               VARCHAR2 (2) := 'NO';

      -- UIU che sono affittate E sono nel cespite richiesto
      CURSOR cuiu (pp_dt DATE) IS
        SELECT t.cod_nazionale,
               t.foglio,
               t.particella,
               t.sub,
               t.unimm
          FROM patri_cespiti_uiu c, siticonduz_imm_all2 t
         WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
               AND EXISTS (
                    SELECT 1
                      FROM cons_urui_tab
                     WHERE atto_ini = p_pk_atto AND cod_nazionale = t.cod_nazionale AND foglio = t.foglio
                           AND particella = t.particella AND sub = t.sub AND unimm = t.unimm AND data_inizio <= pp_dt
                           AND data_fine >= pp_dt)
               AND t.data_inizio <= pp_dt AND t.data_fine >= pp_dt;

      -- Recupero i titoli di affitto UIU
      CURSOR cuiuaffitto (pp_cn VARCHAR2, pp_fg NUMBER, pp_part VARCHAR2, pp_sub VARCHAR2, pp_unimm NUMBER, pp_dt DATE) IS
        SELECT fl_totale
          FROM cons_urui_tab
         WHERE cod_nazionale = pp_cn AND foglio = pp_fg AND particella = pp_part AND sub = pp_sub AND unimm = pp_unimm
               AND data_inizio <= pp_dt AND data_fine >= pp_dt AND atto_ini = p_pk_atto AND ROWNUM = 1;
    BEGIN
      BEGIN
        -- superficie locata delle particelle
  --
  --   SELECT NVL (SUM (area_part), 0),
  --              COUNT (*)
  --         INTO m_sump,
  --              m_existpart
  --         FROM sititrkc
  --        WHERE (cod_nazionale, foglio, particella, sub) IN (
  --                SELECT t.cod_nazionale,
  --                       t.foglio,
  --                       t.particella,
  --                       t.sub
  --                  FROM patri_cespiti_part c, siticond_all2 t
  --                 WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
  --                       AND EXISTS (
  --                            SELECT 1
  --                              FROM cons_ufre_tab
  --                             WHERE atto_ini = p_pk_atto AND cod_nazionale = t.cod_nazionale AND foglio = t.foglio
  --                                   AND particella = t.particella AND sub = t.sub AND data_inizio <= p_date
  --                                   AND data_fine >= p_date))
  --              AND data_aggi <= p_date AND data_fine >= p_date;
  --
    SELECT NVL (SUM (titoli_pck.apply_multiple_rent (st.area_part, p_pk_atto, st.cod_nazionale, st.foglio, st.particella, st.sub, null, p_date)), 0),
               COUNT (*)
          INTO m_sump,
               m_existpart
          FROM sititrkc st, patri_cespiti_part c, siticond_all2 t
     WHERE c.fk_cespite = p_pk_cespite
       AND t.atto_inizio = p_pk_atto
     AND t.data_inizio <= p_date
           AND t.data_fine >= p_date
     AND st.data_aggi <= p_date
     AND st.data_fine >= p_date
     AND t.pkid_tit = c.pk_tit
     AND t.tipo_titolo = c.tipo_titolo
     AND t.tipo_titolo not in ('1', '3', '9')
       AND st.cod_nazionale = t.cod_nazionale
       AND st.foglio = t.foglio
     AND st.particella = t.particella
     AND st.sub = t.sub;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          m_existpart := -1;
          m_sump := 0;
      END;

      IF m_existpart = 0 THEN
        m_existpart := -1;
      END IF;

      FOR rec IN cuiu (p_date) LOOP
        m_existuiu := 1;

        FOR recaffitto IN cuiuaffitto (rec.cod_nazionale, rec.foglio, rec.particella, rec.sub, rec.unimm, p_date) LOOP
          IF (recaffitto.fl_totale IS NOT NULL AND recaffitto.fl_totale != 'N') THEN
            m_sumu :=
              m_sumu
              + NVL (
        titoli_pck.apply_multiple_rent (
           titoli_pck.get_superficie_uiu (rec.cod_nazionale, rec.foglio, rec.particella, rec.sub, rec.unimm, p_date),
         p_pk_atto, rec.cod_nazionale, rec.foglio, rec.particella, rec.sub, rec.unimm, p_date
        ), 0);
          ELSE
            BEGIN
              SELECT m_sumu + SUM (NVL (
         titoli_pck.apply_multiple_rent (
           supe_ambiente * c.coef_supe_modelli,
          p_pk_atto, rec.cod_nazionale, rec.foglio, rec.particella, rec.sub, rec.unimm, p_date
         ), 0))
                INTO m_sumu
                FROM cons_urui_vani t, sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
               WHERE t.id_atto = p_pk_atto AND t.data_inizio_val <= p_date AND t.data_fine_val >= p_date
                     AND t.cod_nazionale = rec.cod_nazionale AND t.foglio = rec.foglio AND t.particella = rec.particella
                     AND t.sub = rec.sub AND t.unimm = rec.unimm AND v.cod_nazionale = t.cod_nazionale
                     AND v.foglio = t.foglio AND v.particella = t.particella AND v.sub = t.sub AND v.unimm = t.unimm
                     AND v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio AND v.particella = e.particella
                     AND v.sub = e.sub AND v.unimm = e.unimm AND e.data_inizio_val <= p_date AND e.data_fine_val >= p_date
                     AND v.vano = t.vano AND v.data_inizio_val <= p_date AND v.data_fine_val >= p_date
                     AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;
            EXCEPTION
              WHEN NO_DATA_FOUND THEN
                m_sumu := m_sumu + 0;
            END;
          END IF;
        END LOOP;
      END LOOP;

      m_suptot := m_sump + m_sumu;

    -- 2009/10/01 Contratti multipli su particelle e uiu
      -- moltiplico la superficie locata per il coefficiente del contratto di locazione che
      -- ï¿½ nel campo perc_cond di tutte le titolaritï¿½
      --m_suptot := titoli_pck.apply_multiple_rent (m_suptot, p_pk_atto);

      --raise_application_error (-20002, 'm_existUiu: ' || m_existUiu || '  m_existPart: ' || m_existPart);
      IF m_existpart = -1 AND m_existuiu = -1 THEN
        m_suptot := -1;
      END IF;

      RETURN m_suptot;
    END get_superficie_cespite_locata;
  */
  FUNCTION get_superficie_cespite_locata (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_suptot                      NUMBER := 0;
    m_sump                        NUMBER := 0;
    m_sumu                        NUMBER := 0;
    m_existpart                   NUMBER := -1;
    m_existuiu                    NUMBER := -1;
  BEGIN
    BEGIN
      -- superficie locata delle particelle
      SELECT NVL (SUM (titoli_pck.sup_part_altro_tit (p_pk_atto, NULL, part.cod_nazionale, part.foglio, part.particella,
                                                      part.sub, p_date)),
                  0),
             COUNT (*)
        INTO m_sump,
             m_existpart
        FROM (SELECT DISTINCT t.cod_nazionale,
                              t.foglio,
                              t.particella,
                              t.sub
                         FROM patri_cespiti_part c, siticond_all2 t
                        WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                              AND t.data_inizio <= p_date AND t.data_fine >= p_date
                              AND EXISTS (
                                   SELECT 1
                                     FROM cons_ufre_tab
                                    WHERE atto_ini = p_pk_atto AND cod_nazionale = t.cod_nazionale AND foglio = t.foglio
                                          AND particella = t.particella AND sub = t.sub AND data_inizio <= p_date
                                          AND data_fine >= p_date)) part;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existpart := -1;
        m_sump := 0;
    END;

    IF m_existpart = 0 THEN
      m_existpart := -1;
    END IF;

    BEGIN
      SELECT NVL (SUM (titoli_pck.sup_uiu_altro_tit (p_pk_atto, NULL, uiu.cod_nazionale, uiu.foglio, uiu.particella,
                                                     uiu.sub, uiu.unimm, p_date)),
                  0),
             COUNT (*)
        INTO m_sumu,
             m_existuiu
        FROM (SELECT DISTINCT t.cod_nazionale,
                              t.foglio,
                              t.particella,
                              t.sub,
                              t.unimm
                         FROM patri_cespiti_uiu c, siticonduz_imm_all2 t
                        WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                              AND t.data_inizio <= p_date AND t.data_fine >= p_date
                              AND EXISTS (
                                   SELECT 1
                                     FROM cons_urui_tab
                                    WHERE atto_ini = p_pk_atto AND cod_nazionale = t.cod_nazionale AND foglio = t.foglio
                                          AND particella = t.particella AND sub = t.sub AND unimm = t.unimm
                                          AND data_inizio <= p_date AND data_fine >= p_date)) uiu;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existuiu := -1;
        m_sumu := 0;
    END;

    IF m_existuiu = 0 THEN
      m_existuiu := -1;
    END IF;

    m_suptot := m_sump + m_sumu;

    --raise_application_error (-20002, 'm_existUiu: ' || m_existUiu || '  m_existPart: ' || m_existPart);
    IF m_existpart = -1 AND m_existuiu = -1 THEN
      m_suptot := -1;
    END IF;

    RETURN m_suptot;
  END get_superficie_cespite_locata;

  FUNCTION get_pct_sup_cespite_locata (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    sup_locata                    NUMBER;
    perc_locata                   NUMBER := 100;
  BEGIN
    sup_locata := get_superficie_cespite_locata (p_pk_cespite, p_pk_atto, p_date);
    perc_locata := get_pct_sup_cespite_locata1 (p_pk_cespite, sup_locata, p_pk_atto, p_date);
    RETURN perc_locata;
  END get_pct_sup_cespite_locata;

  FUNCTION get_pct_sup_cespite_locata1 (
    p_pk_cespite                         NUMBER,
    p_sup_locata                         NUMBER,
    p_pk_atto                            NUMBER,
    p_date                               DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    sup                           NUMBER;
    perc_locata                   NUMBER := 100;
  BEGIN
    sup := get_superficie_cespite (p_pk_cespite, p_date);

    -- se sup_locata vale -1 vuol dire che non esiste una superficie locata
    IF (sup = 0 OR sup < p_sup_locata OR p_sup_locata = -1) THEN
      sup := p_sup_locata;
    END IF;

    IF sup = -1 THEN
      perc_locata := 0;
    ELSIF sup = 0 THEN
      perc_locata := patri_pck.get_pct_multiple_rent (p_pk_atto, p_pk_cespite, p_date);
    ELSE
      perc_locata := (p_sup_locata / sup) * 100;
    END IF;

    RETURN perc_locata;
  END get_pct_sup_cespite_locata1;

  -- se le superfici sono nulle questa funzione ritorna le percentuali memorizzate nelle titolaritï¿½
  FUNCTION get_pct_multiple_rent (p_pk_atto NUMBER, p_pk_cespite NUMBER, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_pcttot                      NUMBER := 0;
    m_sump                        NUMBER := 0;
    m_sumu                        NUMBER := 0;
    m_existpart                   NUMBER := -1;
    m_existuiu                    NUMBER := -1;
    m_pctpart                     NUMBER := 0;
    m_pctuiu                      NUMBER := 0;
    m_multiple_rent               VARCHAR2 (2) := 'NO';
    m_denominator                 NUMBER := 0;
  BEGIN
    BEGIN
      -- superficie locata delle particelle
      SELECT NVL (SUM (perc_poss), 0),
             COUNT (*)
        INTO m_sump,
             m_existpart
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              perc_poss
                         FROM cons_ufre_tab cut
                        WHERE cut.atto_ini = p_pk_atto AND cut.data_inizio <= p_date AND cut.data_fine >= p_date
                              AND EXISTS (
                                   SELECT 1
                                     FROM patri_cespiti_part c, siticond_all2 t
                                    WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit
                                          AND t.tipo_titolo = c.tipo_titolo AND t.data_inizio <= p_date
                                          AND t.data_fine >= p_date AND t.cod_nazionale = cut.cod_nazionale
                                          AND t.foglio = cut.foglio AND t.particella = cut.particella
                                          AND t.sub = cut.sub));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existpart := -1;
        m_sump := 0;
    END;

    IF m_existpart <= 0 THEN
      m_existpart := -1;
      m_pctpart := 0;
      m_denominator := 0;
    ELSE
      m_pctpart := m_sump / (m_existpart * 100);
      m_denominator := 1;
    END IF;

    BEGIN
      -- superficie locata delle uiu
      SELECT NVL (SUM (perc_poss), 0),
             COUNT (*)
        INTO m_sumu,
             m_existuiu
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              unimm,
                              perc_poss
                         FROM cons_urui_tab cut
                        WHERE cut.atto_ini = p_pk_atto AND cut.data_inizio <= p_date AND cut.data_fine >= p_date
                              AND EXISTS (
                                   SELECT 1
                                     FROM patri_cespiti_uiu c, siticonduz_imm_all2 t
                                    WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit
                                          AND t.tipo_titolo = c.tipo_titolo AND t.data_inizio <= p_date
                                          AND t.data_fine >= p_date AND t.cod_nazionale = cut.cod_nazionale
                                          AND t.foglio = cut.foglio AND t.particella = cut.particella
                                          AND t.sub = cut.sub AND t.unimm = cut.unimm));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existuiu := -1;
        m_sumu := 0;
    END;

    IF m_existuiu <= 0 THEN
      m_existuiu := -1;
      m_pctuiu := 0;
    ELSE
      m_pctuiu := m_sumu / (100 * m_existuiu);
      m_denominator := m_denominator + 1;
    END IF;

    m_pcttot := 0;

    IF m_denominator > 0 THEN
      m_pcttot := (m_pctuiu + m_pctpart) / m_denominator;
    END IF;

    --raise_application_error (-20002, 'm_existUiu: ' || m_existUiu || '  m_existPart: ' || m_existPart);
    --IF m_existpart = -1 AND m_existuiu = -1 THEN
    --  m_pcttot := 0;
    --END IF;
    RETURN m_pcttot;
  END get_pct_multiple_rent;

  FUNCTION get_sup_cespite_sublocata (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_suptot                      NUMBER := 0;
    m_sump                        NUMBER := 0;
    m_sumu                        NUMBER := 0;
    m_existpart                   NUMBER := -1;
    m_existuiu                    NUMBER := -1;
  BEGIN
    -- superficie sublocata delle particelle
    BEGIN
      SELECT NVL (SUM (DECODE (supp, -1, 0, supp)), 0),
             COUNT (*)
        INTO m_sump,
             m_existpart
        FROM (SELECT titoli_pck.get_sup_sublocata (p_pk_atto, NULL, st.cod_nazionale, st.foglio, st.particella, st.sub,
                                                   NULL, p_date) AS supp
                FROM patri_cespiti_part c, siticond_all2 t, sititrkc st
               WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                     AND t.data_inizio <= p_date AND t.data_fine >= p_date AND t.cod_nazionale = st.cod_nazionale
                     AND t.foglio = st.foglio AND t.particella = st.particella AND t.sub = st.sub
                     AND st.data_aggi <= p_date AND st.data_fine >= p_date);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existpart := -1;
        m_sump := 0;
    END;

    IF m_existpart = 0 THEN
      m_existpart := -1;
    END IF;

    -- superficie sublocata delle uiu
    BEGIN
      SELECT NVL (SUM (DECODE (supp, -1, 0, supp)), 0),
             COUNT (*)
        INTO m_sumu,
             m_existuiu
        FROM (SELECT titoli_pck.get_sup_sublocata (p_pk_atto, NULL, st.cod_nazionale, st.foglio, st.particella, st.sub,
                                                   st.unimm, p_date) AS supp
                FROM patri_cespiti_uiu c, siticonduz_imm_all2 t, sitiuiu st
               WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                     AND t.data_inizio <= p_date AND t.data_fine >= p_date AND t.cod_nazionale = st.cod_nazionale
                     AND t.foglio = st.foglio AND t.particella = st.particella AND t.sub = st.sub AND t.unimm = st.unimm
                     AND st.data_inizio_val <= p_date AND st.data_fine_val >= p_date);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existuiu := -1;
        m_sumu := 0;
    END;

    IF m_existuiu = 0 THEN
      m_existuiu := -1;
    END IF;

    m_suptot := m_sump + m_sumu;

    --raise_application_error (-20002, 'm_existUiu: ' || m_existUiu || '  m_existPart: ' || m_existPart);
    IF m_existpart = -1 AND m_existuiu = -1 THEN
      m_suptot := -1;
    END IF;

    RETURN m_suptot;
  END get_sup_cespite_sublocata;

  FUNCTION get_pct_sup_cespite_sublocata (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    sup_sublocata                 NUMBER;
    perc_locata                   NUMBER := 100;
  BEGIN
    sup_sublocata := get_sup_cespite_sublocata (p_pk_cespite, p_pk_atto, p_date);
    perc_locata := get_pct_sup_cespite_sublocata1 (p_pk_cespite, sup_sublocata, p_pk_atto, p_date);
    RETURN perc_locata;
  END get_pct_sup_cespite_sublocata;

  FUNCTION get_pct_sup_cespite_sublocata1 (
    p_pk_cespite                         NUMBER,
    p_sup_sublocata                      NUMBER,
    p_pk_atto                            NUMBER,
    p_date                               DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    sup                           NUMBER;
    perc_locata                   NUMBER := 100;
  BEGIN
    sup := get_superficie_cespite (p_pk_cespite, p_date);

    -- se sup_locata vale -1 vuol dire che non esiste una superficie locata
    IF (sup = 0 OR sup < p_sup_sublocata OR p_sup_sublocata = -1) THEN
      sup := p_sup_sublocata;
    END IF;

    IF sup = -1 THEN
      perc_locata := 0;
    ELSIF sup = 0 THEN
      perc_locata := patri_pck.get_pct_multiple_subrent (p_pk_atto, p_pk_cespite, p_date);
    ELSE
      perc_locata := (p_sup_sublocata / sup) * 100;
    END IF;

    RETURN perc_locata;
  END get_pct_sup_cespite_sublocata1;

  -- se le superfici sono nulle questa funzione ritorna le percentuali memorizzate nelle sublocazioni
  FUNCTION get_pct_multiple_subrent (p_pk_atto NUMBER, p_pk_cespite NUMBER, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_pcttot                      NUMBER := 0;
    m_sump                        NUMBER := 0;
    m_sumu                        NUMBER := 0;
    m_existpart                   NUMBER := -1;
    m_existuiu                    NUMBER := -1;
    m_pctpart                     NUMBER := 0;
    m_pctuiu                      NUMBER := 0;
    m_multiple_rent               VARCHAR2 (2) := 'NO';
    m_denominator                 NUMBER := 0;
  BEGIN
    BEGIN
      -- particelle
       -- utilizzo la funzione che calcola la superficie dei contratti in presenza di multilocazione
      -- fornendo una superficie fittizia di 100. In questo modo ï¿½ come se mi ritornasse una percentuale
      SELECT NVL (SUM (titoli_pck.apply_multiple_rent_subloc (100, p_pk_atto, id_cata_part, 'P', p_date)), 0),
             COUNT (*)
        INTO m_sump,
             m_existpart
        FROM (SELECT cp.id_cata_part
                FROM patri_cespiti_part c, siticond_all2 t, cata_part cp
               WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                     AND t.data_inizio <= p_date AND t.data_fine >= p_date AND t.cod_nazionale = cp.cod_nazionale
                     AND t.foglio = cp.foglio AND t.particella = cp.particella AND t.sub = cp.sub);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existpart := -1;
        m_sump := 0;
    END;

    IF m_existpart <= 0 THEN
      m_existpart := -1;
      m_pctpart := 0;
      m_denominator := 0;
    ELSE
      m_pctpart := m_sump / (m_existpart * 100);
      m_denominator := 1;
    END IF;

    BEGIN
        -- uiu
        -- utilizzo la funzione che calcola la superficie dei contratti in presenza di multilocazione
      -- fornendo una superficie fittizia di 100. In questo modo ï¿½ come se mi ritornasse una percentuale
      SELECT NVL (SUM (titoli_pck.apply_multiple_rent_subloc (100, p_pk_atto, id_cata_uiu, 'U', p_date)), 0),
             COUNT (*)
        INTO m_sumu,
             m_existuiu
        FROM (SELECT cp.id_cata_uiu
                FROM patri_cespiti_uiu c, siticonduz_imm_all2 t, cata_uiu cp
               WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                     AND t.data_inizio <= p_date AND t.data_fine >= p_date AND t.cod_nazionale = cp.cod_nazionale
                     AND t.foglio = cp.foglio AND t.particella = cp.particella AND t.sub = cp.sub AND t.unimm = cp.unimm);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_existuiu := -1;
        m_sumu := 0;
    END;

    IF m_existuiu <= 0 THEN
      m_existuiu := -1;
      m_pctuiu := 0;
    ELSE
      m_pctuiu := m_sumu / (100 * m_existuiu);
      m_denominator := m_denominator + 1;
    END IF;

    m_pcttot := 0;

    IF m_denominator > 0 THEN
      m_pcttot := (m_pctuiu + m_pctpart) / m_denominator;
    END IF;

    --raise_application_error (-20002, 'm_existUiu: ' || m_existUiu || '  m_existPart: ' || m_existPart);
    --IF m_existpart = -1 AND m_existuiu = -1 THEN
    --  m_pcttot := 0;
    --END IF;
    RETURN m_pcttot;
  END get_pct_multiple_subrent;

  FUNCTION get_supercifie (p_pk_cespite NUMBER)
    RETURN NUMBER IS
    CURSOR cuiu (dt DATE) IS
      SELECT t.pkid_tit,
             t.fl_totale,
             t.atto_inizio,
             t.cod_nazionale,
             t.foglio,
             t.particella,
             t.sub,
             t.unimm
        FROM patri_cespiti_uiu cu, siticonduz_imm_all2 t
       WHERE cu.fk_cespite = p_pk_cespite AND t.pkid_tit = cu.pk_tit AND t.tipo_titolo = cu.tipo_titolo
             AND t.data_inizio <= dt AND t.data_fine >= dt;

    supu                          NUMBER := 0;
    supp                          NUMBER := 0;
    dt_fine_ces                   DATE;
    num_vani                      NUMBER;
  BEGIN
    SELECT data_fine_val
      INTO dt_fine_ces
      FROM patri_cespiti
     WHERE pk_cespite = p_pk_cespite;

    SELECT NVL (SUM (area_part), 0)
      INTO supp
      FROM sititrkc
     WHERE (cod_nazionale, foglio, particella, sub) IN (
             SELECT cod_nazionale,
                    foglio,
                    particella,
                    sub
               FROM patri_cespiti_part c, siticond_all2 t
              WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                    AND data_inizio <= dt_fine_ces AND t.data_fine >= dt_fine_ces)
           AND data_aggi <= dt_fine_ces AND data_fine >= dt_fine_ces;

    FOR rec IN cuiu (dt_fine_ces) LOOP
      IF (rec.fl_totale IS NOT NULL AND rec.fl_totale != 'N') THEN
        -- se ho affittato tutta la uiu verifico se ci sono dei vani associati
        -- se si calcolo la superficie in base alla somma delle superfici dei vani stessi
        BEGIN
          SELECT COUNT (*)
            INTO num_vani
            FROM cons_urui_vani t, sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
           WHERE t.id_atto = rec.atto_inizio AND t.data_inizio_val <= dt_fine_ces AND t.data_fine_val >= dt_fine_ces
                 AND v.cod_nazionale = rec.cod_nazionale AND v.foglio = rec.foglio AND v.particella = rec.particella
                 AND v.sub = rec.sub AND v.unimm = rec.unimm AND v.cod_nazionale = e.cod_nazionale
                 AND v.foglio = e.foglio AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm
                 AND e.data_inizio_val <= dt_fine_ces AND e.data_fine_val >= dt_fine_ces AND v.vano = t.vano
                 AND v.data_inizio_val <= dt_fine_ces AND v.data_fine_val >= dt_fine_ces
                 AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            num_vani := 0;
        END;
      ELSE
        num_vani := 0;
      END IF;

      IF (rec.fl_totale IS NOT NULL AND rec.fl_totale != 'N' AND num_vani = 0) THEN
        SELECT supu + NVL (DECODE (NVL (supe_modelli, 0), 0, sup_cat, supe_modelli), 0)
          INTO supu
          FROM sitiuiu
         WHERE cod_nazionale = rec.cod_nazionale AND foglio = rec.foglio AND particella = rec.particella
               AND sub = rec.sub AND unimm = rec.unimm AND data_inizio_val <= dt_fine_ces
               AND data_fine_val >= dt_fine_ces;
      ELSE
        SELECT supu + SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0))
          INTO supu
          FROM cons_urui_vani t, sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
         WHERE t.id_atto = rec.atto_inizio AND t.data_inizio_val <= dt_fine_ces AND t.data_fine_val >= dt_fine_ces
               AND v.cod_nazionale = rec.cod_nazionale AND v.foglio = rec.foglio AND v.particella = rec.particella
               AND v.sub = rec.sub AND v.unimm = rec.unimm AND v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio
               AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm
               AND e.data_inizio_val <= dt_fine_ces AND e.data_fine_val >= dt_fine_ces AND v.vano = t.vano
               AND v.data_inizio_val <= dt_fine_ces AND v.data_fine_val >= dt_fine_ces
               AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;
      END IF;
    END LOOP;

    RETURN supp + supu;
  END get_supercifie;

  FUNCTION get_superficie_locata (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_data DATE := SYSDATE)
    RETURN NUMBER IS
    -- UIU che sono affittate E sono nel cespite richiesto
    CURSOR cuiu IS
      SELECT t.cod_nazionale,
             t.foglio,
             t.particella,
             t.sub,
             t.unimm
        FROM patri_cespiti_uiu c, siticonduz_imm_all2 t
       WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
             AND EXISTS (
                  SELECT 1
                    FROM cons_urui_tab
                   WHERE atto_ini = p_pk_atto AND cod_nazionale = t.cod_nazionale AND foglio = t.foglio
                         AND particella = t.particella AND sub = t.sub AND unimm = t.unimm AND data_inizio <= p_data
                         AND data_fine >= p_data);

    -- and t.data_inizio <= p_data
    -- and t.data_fine >= p_data;

    -- Recupero i titoli di affitto UIU
    CURSOR cuiuaffitto (pp_cn VARCHAR2, pp_fg NUMBER, pp_part VARCHAR2, pp_sub VARCHAR2, pp_unimm NUMBER) IS
      SELECT fl_totale
        FROM cons_urui_tab
       WHERE cod_nazionale = pp_cn AND foglio = pp_fg AND particella = pp_part AND sub = pp_sub AND unimm = pp_unimm
             AND data_inizio <= p_data AND data_fine >= p_data AND atto_ini = p_pk_atto AND ROWNUM = 1;

    sump                          NUMBER := 0;
    sumu                          NUMBER := 0;
    tot                           NUMBER := 0;
  BEGIN
    SELECT NVL (SUM (area_part), 0)
      INTO sump
      FROM sititrkc
     WHERE (cod_nazionale, foglio, particella, sub) IN (
             SELECT t.cod_nazionale,
                    t.foglio,
                    t.particella,
                    t.sub
               FROM patri_cespiti_part c, siticond_all2 t
              WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                    AND EXISTS (
                         SELECT 1
                           FROM cons_ufre_tab
                          WHERE atto_ini = p_pk_atto AND cod_nazionale = t.cod_nazionale AND foglio = t.foglio
                                AND particella = t.particella AND sub = t.sub AND data_inizio <= p_data
                                AND data_fine >= p_data))
           AND data_aggi <= p_data AND data_fine >= p_data;

    FOR rec IN cuiu LOOP
      FOR recaffitto IN cuiuaffitto (rec.cod_nazionale, rec.foglio, rec.particella, rec.sub, rec.unimm) LOOP
        IF (recaffitto.fl_totale IS NOT NULL AND recaffitto.fl_totale != 'N') THEN
          SELECT sumu + NVL (DECODE (NVL (supe_modelli, 0), 0, sup_cat, supe_modelli), 0)
            INTO sumu
            FROM sitiuiu
           WHERE cod_nazionale = rec.cod_nazionale AND foglio = rec.foglio AND particella = rec.particella
                 AND sub = rec.sub AND unimm = rec.unimm AND data_inizio_val <= p_data AND data_fine_val >= p_data;
        ELSE
          SELECT sumu + SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0))
            INTO sumu
            FROM cons_urui_vani t, sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
           WHERE t.id_atto = p_pk_atto AND t.data_inizio_val <= SYSDATE AND t.data_fine_val >= SYSDATE
                 AND v.cod_nazionale = rec.cod_nazionale AND v.foglio = rec.foglio AND v.particella = rec.particella
                 AND v.sub = rec.sub AND v.unimm = rec.unimm AND v.cod_nazionale = e.cod_nazionale
                 AND v.foglio = e.foglio AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm
                 AND e.data_inizio_val <= SYSDATE AND e.data_fine_val >= SYSDATE AND v.vano = t.vano
                 AND v.data_inizio_val <= SYSDATE AND v.data_fine_val >= SYSDATE AND c.fk_tipologia = e.fk_tipologia
                 AND c.internal_code = v.ambiente;
        END IF;
      END LOOP;
    END LOOP;

    tot := sump + sumu;
    RETURN tot;
  END get_superficie_locata;

  /*
  function get_pct_locata(p_pk_atto number) return number is
    pct   number;
  begin

    -- Si dï¿½ per scontato che in un contratto le percentuali di affitto siano omogenee per tutto ciï¿½ che ï¿½ affittato
    select nvl(sum(perc_poss), 0) / decode(count(*),0, 1, count(*)) into pct
      from cons_ufre_tab
     where atto_ini = p_pk_atto;

    if (pct = 0) then
      -- Le % dovrebbero essere = su entrambe le tabelle...
      select nvl(sum(perc_poss), 0) / decode(count(*),0, 1, count(*)) into pct
        from cons_urui_tab
       where atto_ini = p_pk_atto;
    end if;

    return pct;
  end get_pct_locata;
  */
  FUNCTION get_pct_locata (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_data DATE := SYSDATE)
    RETURN NUMBER IS
    sup                           NUMBER;
    sup_locata                    NUMBER;
    perc_locata                   NUMBER := 100;
  BEGIN
    sup_locata := get_superficie_locata (p_pk_cespite, p_pk_atto, p_data);
    sup := get_supercifie (p_pk_cespite);

    IF (sup = 0 OR sup < sup_locata) THEN
      sup := sup_locata;
    END IF;

    IF (sup = 0) THEN
      perc_locata := 100;
    ELSE
      perc_locata := (sup_locata / sup) * 100;
    END IF;

    RETURN perc_locata;
  END get_pct_locata;

  FUNCTION min_pk_ces_from_affitto (p_pk_atto NUMBER, p_fl_att_pass CHAR)
    RETURN NUMBER IS
    ret                           NUMBER;
  BEGIN
    IF p_fl_att_pass = 'A' THEN
      SELECT MIN (fk_cespite)
        INTO ret
        FROM (SELECT c.fk_cespite
                FROM cons_ufre_tab t, cons_cons_tab t2, patri_cespiti_part c
               WHERE t.atto_ini = p_pk_atto AND t2.cod_nazionale = t.cod_nazionale AND t2.foglio = t.foglio
                     AND t2.particella = t.particella AND t2.sub = t.sub AND t2.data_inizio <= t.data_fine
                     AND t2.data_fine >= t.data_inizio AND c.pk_tit = t2.pkid_cons AND c.tipo_titolo = t2.tipo_titolo
              UNION ALL
              SELECT c.fk_cespite
                FROM cons_urui_tab t, cons_csui_tab t2, patri_cespiti_uiu c
               WHERE t.atto_ini = p_pk_atto AND t2.cod_nazionale = t.cod_nazionale AND t2.foglio = t.foglio
                     AND t2.particella = t.particella AND t2.sub = t.sub AND t2.unimm = t.unimm
                     AND t2.data_inizio <= t.data_fine AND t2.data_fine >= t.data_inizio AND c.pk_tit = t2.pkid_csui
                     AND c.tipo_titolo = t2.tipo_titolo);
    ELSE
      SELECT MIN (fk_cespite)
        INTO ret
        FROM (SELECT c.fk_cespite
                FROM cons_ufre_tab t, patri_cespiti_part c
               WHERE t.atto_ini = p_pk_atto AND c.pk_tit = t.pkid_uffr AND c.tipo_titolo = t.tipo_titolo
              UNION ALL
              SELECT c.fk_cespite
                FROM cons_urui_tab t, patri_cespiti_uiu c
               WHERE t.atto_ini = p_pk_atto AND c.pk_tit = t.pkid_urui AND c.tipo_titolo = t.tipo_titolo);
    END IF;

    RETURN ret;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
  END min_pk_ces_from_affitto;

  FUNCTION getid_contr (p_pk_cespite NUMBER, p_pk_atto NUMBER, p_fl_att_pass CHAR)
    RETURN NUMBER IS
    ret                           NUMBER;
    m_data_fine_val               DATE;
  BEGIN
    BEGIN
      SELECT data_fine_val
        INTO m_data_fine_val
        FROM patri_cespiti
       WHERE pk_cespite = p_pk_cespite;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RETURN 1;
    END;

    BEGIN
      IF p_fl_att_pass = 'A' THEN
        SELECT COUNT (*)
          INTO ret
          FROM (SELECT DISTINCT *
                           FROM (SELECT pc.pk_cespite,
                                        pc.data_fine_val
                                   FROM cons_ufre_tab t, cons_cons_tab t2, patri_cespiti_part c, patri_cespiti pc
                                  WHERE t.atto_ini = p_pk_atto AND t2.cod_nazionale = t.cod_nazionale
                                        AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub
                                        AND t2.data_inizio <= t.data_fine AND t2.data_fine >= t.data_inizio
                                        AND c.pk_tit = t2.pkid_cons AND c.tipo_titolo = t2.tipo_titolo
                                        AND c.fk_cespite = pc.pk_cespite
                                 UNION ALL
                                 SELECT pc.pk_cespite,
                                        pc.data_fine_val
                                   FROM cons_urui_tab t, cons_csui_tab t2, patri_cespiti_uiu c, patri_cespiti pc
                                  WHERE t.atto_ini = p_pk_atto AND t2.cod_nazionale = t.cod_nazionale
                                        AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub
                                        AND t2.unimm = t.unimm AND t2.data_inizio <= t.data_fine
                                        AND t2.data_fine >= t.data_inizio AND c.pk_tit = t2.pkid_csui
                                        AND c.tipo_titolo = t2.tipo_titolo AND c.fk_cespite = pc.pk_cespite)
                          WHERE data_fine_val > m_data_fine_val
                                OR (data_fine_val = m_data_fine_val AND pk_cespite < p_pk_cespite));
      ELSE
        SELECT COUNT (*)
          INTO ret
          FROM (SELECT DISTINCT *
                           FROM (SELECT pc.pk_cespite,
                                        pc.data_fine_val
                                   FROM cons_ufre_tab t, patri_cespiti_part c, patri_cespiti pc
                                  WHERE t.atto_ini = p_pk_atto AND c.pk_tit = t.pkid_uffr
                                        AND c.tipo_titolo = t.tipo_titolo AND c.fk_cespite = pc.pk_cespite
                                 UNION ALL
                                 SELECT pc.pk_cespite,
                                        pc.data_fine_val
                                   FROM cons_urui_tab t, patri_cespiti_uiu c, patri_cespiti pc
                                  WHERE t.atto_ini = p_pk_atto AND c.pk_tit = t.pkid_urui
                                        AND c.tipo_titolo = t.tipo_titolo AND c.fk_cespite = pc.pk_cespite)
                          WHERE data_fine_val > m_data_fine_val
                                OR (data_fine_val = m_data_fine_val AND pk_cespite < p_pk_cespite));
      END IF;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        ret := 0;
    END;

    RETURN ret + 1;
  END getid_contr;

  FUNCTION get_cod_ces_da_altro_tit (p_pk_tit NUMBER, p_tipo_titolo VARCHAR2)
    RETURN VARCHAR2 IS
    ret                           patri_cespiti.cod_cespite%TYPE;
  BEGIN
    BEGIN
      SELECT c.cod_cespite
        INTO ret
        FROM patri_cespiti c, patri_cespiti_part cp, cons_ufre_tab t, cons_cons_tab t2
       WHERE t.pkid_uffr = p_pk_tit AND t.tipo_titolo = p_tipo_titolo AND t2.cod_nazionale = t.cod_nazionale
             AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub
             AND t2.data_inizio <= t.data_fine AND t2.data_fine >= t.data_inizio AND cp.pk_tit = t2.pkid_cons
             AND cp.tipo_titolo = t2.tipo_titolo AND c.pk_cespite = cp.fk_cespite AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT c.cod_cespite
            INTO ret
            FROM patri_cespiti c, patri_cespiti_uiu cp, cons_urui_tab t, cons_csui_tab t2
           WHERE t.pkid_urui = p_pk_tit AND t.tipo_titolo = p_tipo_titolo AND t2.cod_nazionale = t.cod_nazionale
                 AND t2.foglio = t.foglio AND t2.particella = t.particella AND t2.sub = t.sub
                 AND t2.data_inizio <= t.data_fine AND t2.data_fine >= t.data_inizio AND cp.pk_tit = t2.pkid_csui
                 AND cp.tipo_titolo = t2.tipo_titolo AND c.pk_cespite = cp.fk_cespite AND ROWNUM = 1;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            ret := NULL;
        END;
    END;

    RETURN ret;
  END get_cod_ces_da_altro_tit;

  PROCEDURE expirecespite (p_pk_cespite NUMBER, p_dt_ini DATE) IS
    cnt                           PLS_INTEGER;
    dt_fin                        DATE;
  BEGIN
    dt_fin := p_dt_ini - (1 / 60 / 60 / 24);

    SELECT COUNT (*)
      INTO cnt
      FROM (SELECT 1
              FROM patri_cespiti_part c, siticond_all2 t
             WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                   AND t.data_fine > dt_fin
            UNION ALL
            SELECT 1
              FROM patri_cespiti_uiu c, siticonduz_imm_all2 t
             WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                   AND t.data_fine > dt_fin);

    IF (cnt = 0) THEN
      UPDATE patri_cespiti
         SET data_fine_val = dt_fin,
             tipo_estrom = 'V'
       WHERE pk_cespite = p_pk_cespite;
    END IF;
  END expirecespite;

-- fa una copia del cespite su un altro soggetto
  PROCEDURE copycespite (
    p_pk_cespite                         NUMBER,
    p_dt_ini                             DATE,
    p_dt_fin                             DATE,
    etype                                VARCHAR2,
    p_pkidnewtit                         NUMBER,
    p_pk_cuaa                            NUMBER,
    p_tipo_titolo                        VARCHAR2
  ) IS
    cnt                           PLS_INTEGER;
    dt_fin                        DATE;
    m_pk_cespite                  NUMBER;
  BEGIN
    dt_fin := p_dt_ini - (1 / 60 / 60 / 24);

    SELECT COUNT (*)
      INTO cnt
      FROM (SELECT 1
              FROM patri_cespiti_part c, siticond_all2 t
             WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                   AND t.data_fine > dt_fin
            UNION ALL
            SELECT 1
              FROM patri_cespiti_uiu c, siticonduz_imm_all2 t
             WHERE c.fk_cespite = p_pk_cespite AND t.pkid_tit = c.pk_tit AND t.tipo_titolo = c.tipo_titolo
                   AND t.data_fine > dt_fin);

    IF (cnt = 0) THEN
      SELECT patri_cespiti_seq.NEXTVAL
        INTO m_pk_cespite
        FROM DUAL;

      -- Inserisco il nuovo cespite
      INSERT INTO patri_cespiti
                  (pk_cespite,
                   descrizione,
                   cod_cespite,
                   cod_imm,
                   num_inventario,
                   cod_cat_inv,
                   cod_cat_ces,
                   cod_cat_ces_alt,
                   cod_aliq_amm,
                   cod_aliq_amm_fisc,
                   data_amm_ini,
                   data_amm_fisc_ini,
                   cat_amminis,
                   cod_amminis,
                   cod_invevend,
                   fl_soggetto_ici,
                   tp_val_ici,
                   cod_aliq_ici,
                   cod_metodo_stima,
                   provenienza,
                   fl_tp_locazione,
                   val_bene,
                   val_originale,
                   val_attuale,
                   val_residuo,
                   val_a_nuovo,
                   rivalutazioni,
                   dt_ult_rival,
                   dt_ult_amm_dal,
                   dt_ult_amm_al,
                   ult_amm_impo,
                   val_attuale_f,
                   val_residuo_f,
                   dt_ult_amm_dal_f,
                   dt_ult_amm_al_f,
                   ult_amm_impo_f,
                   ult_fv_cons,
                   dt_ult_fv_cons,
                   data_lav,
                   utente_ini,
                   data_inizio_val,
                   cod_nazionale,
                   val_tot_f,
                   val_terre_f,
                   pk_atto,
                   cod_gruppo,
                   data_fine_val,
                   tipo_estrom,
                   val_terre,
                   cod_via,
                   civico,
                   interno,
                   note,
                   scala,
                   piano,
                   pk_cuaa
                  )
        (SELECT m_pk_cespite,
                descrizione,
                cod_cespite,
                cod_imm,
                num_inventario,
                cod_cat_inv,
                cod_cat_ces,
                cod_cat_ces_alt,
                cod_aliq_amm,
                cod_aliq_amm_fisc,
                data_amm_ini,
                data_amm_fisc_ini,
                cat_amminis,
                cod_amminis,
                cod_invevend,
                fl_soggetto_ici,
                tp_val_ici,
                cod_aliq_ici,
                cod_metodo_stima,
                provenienza,
                fl_tp_locazione,
                val_bene,
                val_originale,
                val_attuale,
                val_residuo,
                val_a_nuovo,
                rivalutazioni,
                dt_ult_rival,
                dt_ult_amm_dal,
                dt_ult_amm_al,
                ult_amm_impo,
                val_attuale_f,
                val_residuo_f,
                dt_ult_amm_dal_f,
                dt_ult_amm_al_f,
                ult_amm_impo_f,
                ult_fv_cons,
                dt_ult_fv_cons,
                SYSDATE,
                'SYSTEM',
                p_dt_ini,
                cod_nazionale,
                val_tot_f,
                val_terre_f,
                pk_atto,
                cod_gruppo,
                p_dt_fin,
                tipo_estrom,
                val_terre,
                cod_via,
                civico,
                interno,
                note,
                scala,
                piano,
                p_pk_cuaa
           FROM patri_cespiti
          WHERE pk_cespite = p_pk_cespite);

      IF etype = 'P' THEN
        INSERT INTO patri_cespiti_part
                    (fk_cespite, pk_tit, tipo_titolo, pkid)
             VALUES (m_pk_cespite, p_pkidnewtit, p_tipo_titolo, patri_cespiti_part_uiu_seq.NEXTVAL);
      ELSE
        INSERT INTO patri_cespiti_uiu
                    (fk_cespite, pk_tit, tipo_titolo, pkid)
             VALUES (m_pk_cespite, p_pkidnewtit, p_tipo_titolo, patri_cespiti_part_uiu_seq.NEXTVAL);
      END IF;

      UPDATE patri_cespiti
         SET data_fine_val = dt_fin
       WHERE pk_cespite = p_pk_cespite;

      -- sistema il cod_gruppo
      allinea_cespite (m_pk_cespite);
    END IF;
  END copycespite;

  PROCEDURE storicizecespite (p_pk_cespite NUMBER, p_dt_ini DATE) IS
    dt_fin                        DATE;
    m_pk_cespite                  NUMBER;
    dummy                         NUMBER;
  BEGIN
    dt_fin := p_dt_ini - (1 / 60 / 60 / 24);

    -- creo l'id del nuovo cespite
    SELECT patri_cespiti_seq.NEXTVAL
      INTO m_pk_cespite
      FROM DUAL;

    BEGIN
      -- Se il cespite con queste date esiste giï¿½ non lo storicizzo
      SELECT pk_cespite
        INTO dummy
        FROM patri_cespiti
       WHERE pk_cespite = p_pk_cespite AND data_inizio_val = p_dt_ini AND data_fine_val = dt_fin;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        --IF (dt_fin > p_dt_ini)
        --THEN
           -- inserisco il nuovo cespite
        INSERT INTO patri_cespiti
                    (pk_cespite,
                     descrizione,
                     cod_cespite,
                     cod_imm,
                     num_inventario,
                     cod_cat_inv,
                     cod_cat_ces,
                     cod_cat_ces_alt,
                     cod_aliq_amm,
                     cod_aliq_amm_fisc,
                     data_amm_ini,
                     data_amm_fisc_ini,
                     cat_amminis,
                     cod_amminis,
                     cod_invevend,
                     fl_soggetto_ici,
                     tp_val_ici,
                     cod_aliq_ici,
                     cod_metodo_stima,
                     provenienza,
                     fl_tp_locazione,
                     val_bene,
                     val_originale,
                     val_attuale,
                     val_residuo,
                     val_a_nuovo,
                     rivalutazioni,
                     dt_ult_rival,
                     dt_ult_amm_dal,
                     dt_ult_amm_al,
                     ult_amm_impo,
                     val_attuale_f,
                     val_residuo_f,
                     dt_ult_amm_dal_f,
                     dt_ult_amm_al_f,
                     ult_amm_impo_f,
                     ult_fv_cons,
                     dt_ult_fv_cons,
                     data_lav,
                     utente_ini,
                     data_inizio_val,
                     cod_nazionale,
                     val_tot_f,
                     val_terre_f,
                     pk_atto,
                     cod_gruppo,
                     data_fine_val,
                     tipo_estrom,
                     val_terre,
                     cod_via,
                     civico,
                     interno,
                     note,
                     scala,
                     piano,
                     pk_cuaa
                    )
          (SELECT m_pk_cespite,
                  descrizione,
                  cod_cespite,
                  cod_imm,
                  num_inventario,
                  cod_cat_inv,
                  cod_cat_ces,
                  cod_cat_ces_alt,
                  cod_aliq_amm,
                  cod_aliq_amm_fisc,
                  data_amm_ini,
                  data_amm_fisc_ini,
                  cat_amminis,
                  cod_amminis,
                  cod_invevend,
                  fl_soggetto_ici,
                  tp_val_ici,
                  cod_aliq_ici,
                  cod_metodo_stima,
                  provenienza,
                  fl_tp_locazione,
                  val_bene,
                  val_originale,
                  val_attuale,
                  val_residuo,
                  val_a_nuovo,
                  rivalutazioni,
                  dt_ult_rival,
                  dt_ult_amm_dal,
                  dt_ult_amm_al,
                  ult_amm_impo,
                  val_attuale_f,
                  val_residuo_f,
                  dt_ult_amm_dal_f,
                  dt_ult_amm_al_f,
                  ult_amm_impo_f,
                  ult_fv_cons,
                  dt_ult_fv_cons,
                  data_lav,
                  utente_ini,
                  p_dt_ini,
                  cod_nazionale,
                  val_tot_f,
                  val_terre_f,
                  pk_atto,
                  cod_gruppo,
                  data_fine_val,
                  tipo_estrom,
                  val_terre,
                  cod_via,
                  civico,
                  interno,
                  note,
                  scala,
                  piano,
                  pk_cuaa
             FROM patri_cespiti
            WHERE pk_cespite = p_pk_cespite);

        -- aggiorno la data di fine del vecchio cespite
        UPDATE patri_cespiti
           SET data_fine_val = dt_fin
         WHERE pk_cespite = p_pk_cespite;

        -- aggiorno il collegamento con la titolaritï¿½ delle particelle
        INSERT INTO patri_cespiti_part
                    (fk_cespite, pk_tit, tipo_titolo, pkid)
          (SELECT m_pk_cespite,
                  pk_tit,
                  tipo_titolo,
                  patri_cespiti_part_uiu_seq.NEXTVAL
             FROM patri_cespiti_part
            WHERE fk_cespite = p_pk_cespite);

        -- aggiorno il collegamento con la titolaritï¿½ delle uiu
        INSERT INTO patri_cespiti_uiu
                    (fk_cespite, pk_tit, tipo_titolo, pkid)
          (SELECT m_pk_cespite,
                  pk_tit,
                  tipo_titolo,
                  patri_cespiti_part_uiu_seq.NEXTVAL
             FROM patri_cespiti_uiu
            WHERE fk_cespite = p_pk_cespite);
    --END IF;
    END;
  END storicizecespite;

-- Quando faccio cessare un titolo di conduzione su una uiu (con vani) potrei dover storicizzare gli eventuali cespiti
-- giï¿½ esistenti in modo che mantengano le superifici giuste
  PROCEDURE expiretitoloconduzione (
    p_cn                                 VARCHAR2,
    p_fg                                 NUMBER,
    p_pt                                 VARCHAR2,
    p_sb                                 VARCHAR2,
    p_un                                 NUMBER,
    p_dt_ini                             DATE,
    p_dt_fin                             DATE,
    p_ai                                 NUMBER
  ) IS
    CURSOR ccesuiu IS
      SELECT DISTINCT c.pk_cespite
                 FROM siticonduz_imm_all2 t, patri_cespiti_uiu cu, patri_cespiti c
                WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb
                      AND t.unimm = p_un AND t.data_inizio <= p_dt_fin AND t.data_fine >= p_dt_ini
                      AND cu.pk_tit = t.pkid_tit AND cu.tipo_titolo = t.tipo_titolo AND c.pk_cespite = cu.fk_cespite
                      AND c.data_inizio_val <= p_dt_ini AND c.data_fine_val >= p_dt_ini;

    isconduzione                  NUMBER := 0;
    recuiu                        ccesuiu%ROWTYPE;
    numnewtit                     NUMBER;
    numoldtit                     NUMBER;
    pkidnewtit                    NUMBER;
    m_pk_cuaa                     NUMBER;
    m_tipo_titolo                 VARCHAR2 (5);
  BEGIN
    -- verifico se la titolaritï¿½ ï¿½ di conduzione interamente su uiu
    BEGIN
      SELECT 1
        INTO isconduzione
        FROM cons_urui_tab t
       WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
             AND t.atto_ini = p_ai AND t.data_inizio < p_dt_ini AND t.data_fine = p_dt_fin AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        -- se fallisce la conduzione su uiu verifico se la conduzione ï¿½ sui vani
        BEGIN
          SELECT 1
            INTO isconduzione
            FROM cons_urui_vani t
           WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
                 AND t.id_atto = p_ai AND t.data_inizio_val < p_dt_ini AND t.data_fine_val = p_dt_fin AND ROWNUM = 1;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            isconduzione := 0;
        END;
    END;

    -- se il titolo ï¿½ di conduzione seleziono tutti i cespiti in corso di validtitï¿½ (data_fine_val = 31/12/99999)
    -- che intersecano la titolaritï¿½ corrente
    IF isconduzione = 1 THEN
      FOR recuiu IN ccesuiu LOOP
        storicizecespite (recuiu.pk_cespite, p_dt_fin + (1 / 60 / 60 / 24));
      END LOOP;
    END IF;
  END expiretitoloconduzione;

-- Quando inserisco un nuovo titolo di conduzione su una uiu (con vani) potrei dover storicizzare gli eventuali cespiti
-- giï¿½ esistenti in modo che mantengano le superifici giuste
  PROCEDURE nuovotitoloconduzione (
    p_cn                                 VARCHAR2,
    p_fg                                 NUMBER,
    p_pt                                 VARCHAR2,
    p_sb                                 VARCHAR2,
    p_un                                 NUMBER,
    p_dt_ini                             DATE,
    p_dt_fin                             DATE,
    p_ai                                 NUMBER
  ) IS
    CURSOR ccesuiu IS
      SELECT DISTINCT c.pk_cespite
                 FROM siticonduz_imm_all2 t, patri_cespiti_uiu cu, patri_cespiti c
                WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb
                      AND t.unimm = p_un AND t.data_inizio <= p_dt_fin AND t.data_fine >= p_dt_ini
                      AND cu.pk_tit = t.pkid_tit AND cu.tipo_titolo = t.tipo_titolo AND c.pk_cespite = cu.fk_cespite
                      AND c.data_inizio_val <= p_dt_ini AND c.data_fine_val > p_dt_ini;

    isconduzione                  NUMBER := 0;
    recuiu                        ccesuiu%ROWTYPE;
    numnewtit                     NUMBER;
    numoldtit                     NUMBER;
    pkidnewtit                    NUMBER;
    m_pk_cuaa                     NUMBER;
    m_tipo_titolo                 VARCHAR2 (5);
  BEGIN
    -- verifico se la titolaritï¿½ ï¿½ di conduzione su uiu
    BEGIN
      SELECT 1
        INTO isconduzione
        FROM cons_urui_tab t
       WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
             AND t.atto_ini = p_ai AND t.data_inizio <= p_dt_ini AND t.data_fine >= p_dt_fin AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        isconduzione := 0;
    END;

    -- se il titolo ï¿½ di conduzione seleziono tutti i cespiti in corso di validtitï¿½
    -- che intersecano la titolaritï¿½ corrente
    IF isconduzione = 1 THEN
      FOR recuiu IN ccesuiu LOOP
        storicizecespite (recuiu.pk_cespite, p_dt_ini);
      END LOOP;
    END IF;
  END nuovotitoloconduzione;

  PROCEDURE nuovotitolo (
    p_cn                                 VARCHAR2,
    p_fg                                 NUMBER,
    p_pt                                 VARCHAR2,
    p_sb                                 VARCHAR2,
    p_un                                 NUMBER,
    p_dt_ini                             DATE,
    p_dt_fin                             DATE,
    p_af                                 NUMBER
  ) IS
    CURSOR ccespart IS
      SELECT t.*,
             c.pk_cespite,
             c.tipo_estrom,
             c.data_fine_val
        FROM cons_cons_tab t, patri_cespiti_part cp, patri_cespiti c
       WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.atto_fin = p_af
             AND cp.pk_tit = t.pkid_cons AND cp.tipo_titolo = t.tipo_titolo AND c.pk_cespite = cp.fk_cespite
             AND c.data_inizio_val <= p_dt_ini AND c.data_fine_val >= p_dt_fin;

    CURSOR ccesuiu IS
      SELECT t.*,
             c.pk_cespite,
             c.tipo_estrom,
             c.data_fine_val
        FROM cons_csui_tab t, patri_cespiti_uiu cu, patri_cespiti c
       WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
             AND t.atto_fin = p_af AND cu.pk_tit = t.pkid_csui AND cu.tipo_titolo = t.tipo_titolo
             AND c.pk_cespite = cu.fk_cespite AND c.data_inizio_val <= p_dt_ini AND c.data_fine_val >= p_dt_fin;

    recpart                       ccespart%ROWTYPE;
    recuiu                        ccesuiu%ROWTYPE;
    numnewtit                     NUMBER;
    numoldtit                     NUMBER;
    old_is_new                    NUMBER;
    pkidnewtit                    NUMBER;
    m_pk_cuaa                     NUMBER;
    m_tipo_titolo                 VARCHAR2 (5);
  BEGIN
    IF p_un IS NULL THEN                                                                            -- ï¿½ una particella
      BEGIN
        -- verifico il numero di nuove titolaritï¿½ inserite sulla particella
        SELECT COUNT (*)
          INTO numnewtit
          FROM cons_cons_tab t
         WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.atto_ini = p_af
               AND t.data_inizio = p_dt_ini AND t.data_fine = p_dt_fin;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          numnewtit := 0;
      END;

      BEGIN
        -- verifico il numero di vecchie titolaritï¿½ inserite sulla particella
        SELECT COUNT (*)
          INTO numoldtit
          FROM cons_cons_tab t
         WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.atto_fin = p_af
               AND t.data_fine < p_dt_ini;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          numoldtit := 0;
      END;

      -- verifico se qualcuno dei vecchi titolari ï¿½ anche un nuovo titolare
      BEGIN
        SELECT COUNT (*)
          INTO old_is_new
          FROM cons_cons_tab t, cons_cons_tab t1
         WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.atto_fin = p_af
               AND t.data_fine < p_dt_ini AND t1.cod_nazionale = t.cod_nazionale AND t1.foglio = t.foglio
               AND t1.particella = t.particella AND t1.sub = t.sub AND t1.pk_cuaa = t.pk_cuaa
               AND t1.atto_ini = t.atto_fin AND t1.data_inizio = p_dt_ini AND t1.data_fine = p_dt_fin;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          old_is_new := 0;
      END;

      -- se c'ï¿½ piï¿½ di una vecchia o nuova titolaritï¿½ estrometto i cespiti
      IF (numnewtit <> 1 OR numoldtit > 1) AND old_is_new = 0 THEN
        FOR recpart IN ccespart LOOP
          -- Questi cespiti hanno la titolaritï¿½ cessata; controllo se ne resta almeno 1 valida...
          expirecespite (recpart.pk_cespite, p_dt_ini);
        END LOOP;
      ELSE
        IF numnewtit = 1 AND numoldtit = 1 THEN
          -- trasferisco  il cespite da un solo soggetto ad un altro
              -- c'ï¿½ una sola titolaritï¿½ scaduta e una sola nuova, storicizzo il cespite
          SELECT pkid_cons,
                 pk_cuaa,
                 tipo_titolo
            INTO pkidnewtit,
                 m_pk_cuaa,
                 m_tipo_titolo
            FROM cons_cons_tab t
           WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb
                 AND t.atto_ini = p_af AND t.data_inizio = p_dt_ini AND t.data_fine = p_dt_fin;

          -- il ciclo non servirebbe tanto il record ï¿½ uno
          FOR recpart IN ccespart LOOP
            IF (recpart.tipo_estrom IS NULL AND recpart.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy')) THEN
              copycespite (recpart.pk_cespite, p_dt_ini, p_dt_fin, 'P', pkidnewtit, m_pk_cuaa, m_tipo_titolo);
            END IF;
          END LOOP;
        ELSIF old_is_new > 0 THEN
          -- trasferisco il cespite dalla vecchia titolaritï¿½ alla nuova per lo stesso soggetto
          FOR recpart IN ccespart LOOP
            SELECT pkid_cons,
                   pk_cuaa,
                   tipo_titolo
              INTO pkidnewtit,
                   m_pk_cuaa,
                   m_tipo_titolo
              FROM cons_cons_tab t
             WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb
                   AND t.atto_ini = p_af AND t.data_inizio = p_dt_ini AND t.data_fine = p_dt_fin
                   AND t.pk_cuaa = recpart.pk_cuaa AND ROWNUM = 1;

            IF (recpart.tipo_estrom IS NULL AND recpart.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy')) THEN
              copycespite (recpart.pk_cespite, p_dt_ini, p_dt_fin, 'P', pkidnewtit, m_pk_cuaa, m_tipo_titolo);
            END IF;
          END LOOP;
        END IF;
      END IF;
    ELSE                                                                                                    -- ï¿½ una uiu
      BEGIN
        -- verifico il numero di nuove titolaritï¿½ inserite sulla uiu
        SELECT COUNT (*)
          INTO numnewtit
          FROM cons_csui_tab t
         WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
               AND t.atto_ini = p_af AND t.data_inizio = p_dt_ini AND t.data_fine = p_dt_fin;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          numnewtit := 0;
      END;

      BEGIN
        -- verifico il numero di vecchie titolaritï¿½ inserite sulla particella
        SELECT COUNT (*)
          INTO numoldtit
          FROM cons_csui_tab t
         WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
               AND t.atto_fin = p_af AND t.data_fine < p_dt_ini;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          numoldtit := 0;
      END;

      -- verifico se qualcuno dei vecchi titolari ï¿½ anche un nuovo titolare
      BEGIN
        SELECT COUNT (*)
          INTO old_is_new
          FROM cons_csui_tab t, cons_csui_tab t1
         WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
               AND t.atto_fin = p_af AND t.data_fine < p_dt_ini AND t1.cod_nazionale = t.cod_nazionale
               AND t1.foglio = t.foglio AND t1.particella = t.particella AND t1.sub = t.sub AND t1.unimm = t.unimm
               AND t1.pk_cuaa = t.pk_cuaa AND t1.atto_ini = t.atto_fin AND t1.data_inizio = p_dt_ini
               AND t1.data_fine = p_dt_fin;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          old_is_new := 0;
      END;

      -- se c'ï¿½ piï¿½ di una vecchia o nuova titolaritï¿½ estrometto i cespiti
      IF (numnewtit <> 1 OR numoldtit > 1) AND old_is_new = 0 THEN
        FOR recuiu IN ccesuiu LOOP
          -- Questi cespiti hanno la titolaritï¿½ cessata; controllo se ne resta almeno 1 valida...
          expirecespite (recuiu.pk_cespite, p_dt_ini);
        END LOOP;
      ELSE
        IF numnewtit = 1 AND numoldtit = 1 THEN
          -- c'ï¿½ una sola titolaritï¿½ scaduta e una sola nuova, storicizzo il cespite
          SELECT pkid_csui,
                 pk_cuaa,
                 tipo_titolo
            INTO pkidnewtit,
                 m_pk_cuaa,
                 m_tipo_titolo
            FROM cons_csui_tab t
           WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb AND t.unimm = p_un
                 AND t.atto_ini = p_af AND t.data_inizio = p_dt_ini AND t.data_fine = p_dt_fin;

          -- il ciclo non servirebbe tanto il record ï¿½ uno
          FOR recuiu IN ccesuiu LOOP
            IF (recuiu.tipo_estrom IS NULL AND recuiu.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy')) THEN
              copycespite (recuiu.pk_cespite, p_dt_ini, p_dt_fin, 'U', pkidnewtit, m_pk_cuaa, m_tipo_titolo);
            END IF;
          END LOOP;
        ELSIF old_is_new > 0 THEN
          -- trasferisco il cespite dalla vecchia titolaritï¿½ alla nuova per lo stesso soggetto
          FOR recuiu IN ccesuiu LOOP
            SELECT pkid_csui,
                   pk_cuaa,
                   tipo_titolo
              INTO pkidnewtit,
                   m_pk_cuaa,
                   m_tipo_titolo
              FROM cons_csui_tab t
             WHERE t.cod_nazionale = p_cn AND t.foglio = p_fg AND t.particella = p_pt AND t.sub = p_sb
                   AND t.unimm = p_un AND t.atto_ini = p_af AND t.data_inizio = p_dt_ini AND t.data_fine = p_dt_fin
                   AND t.pk_cuaa = recuiu.pk_cuaa AND ROWNUM = 1;

            IF (recuiu.tipo_estrom IS NULL AND recuiu.data_fine_val >= TO_DATE ('31129999', 'ddmmyyyy')) THEN
              copycespite (recuiu.pk_cespite, p_dt_ini, p_dt_fin, 'U', pkidnewtit, m_pk_cuaa, m_tipo_titolo);
            END IF;
          END LOOP;
        END IF;
      END IF;
    -- se il titolo ï¿½ di conduzione
    --NuovoTitoloConduzione(p_cn, p_fg, p_pt, p_sb, p_un, p_dt_ini, p_dt_fin, p_af);
    END IF;
  END nuovotitolo;

  PROCEDURE allinea_cespite (p_pk_cespite NUMBER) IS
    dt                            DATE;
    dummy                         VARCHAR2 (50);
    dummyn                        NUMBER;
    m_flag_rla                    VARCHAR2 (1);
    m_id                          NUMBER;
    m_tp                          VARCHAR2 (10);
    m_cod_gruppo                  VARCHAR2 (50);
    m_cespite_padre               NUMBER;
  BEGIN
      -- imposto l'indirizzo del cespite
      /*
       select data_fine_val into dt
         from patri_cespiti where pk_cespite = p_pk_cespite;

      dummy := init_indirizzo(p_pk_cespite, dt);
    */
    dummy := init_indirizzo (p_pk_cespite);

    IF (dummy IS NOT NULL) THEN
      UPDATE patri_cespiti
         SET cod_via = ultimo_ind.numero,
             civico = ultimo_ind.civico,
             interno = ultimo_ind.interno,
             scala = ultimo_ind.scala,
             piano = ultimo_ind.piano
       WHERE pk_cespite = p_pk_cespite;
    ELSE
      UPDATE patri_cespiti
         SET cod_via = NULL,
             civico = NULL,
             interno = NULL
       WHERE pk_cespite = p_pk_cespite;
    END IF;

    -- cerco il cespite padre e aggiorno il gruppo (solo se il cespite ï¿½ composto da uiu)
    m_cespite_padre := get_cespite_padre (p_pk_cespite);

    UPDATE patri_cespiti
       SET cod_gruppo = (SELECT cod_cespite
                           FROM patri_cespiti
                          WHERE pk_cespite = m_cespite_padre)
     WHERE pk_cespite = p_pk_cespite;

    -- cerco i cespiti figli e li aggiorno tutti con cespite_figlio.cod_gruppo = cespite_padre.cod_cespite (solo se il cespite ï¿½ composto da una particella)
    aggiorna_figli_fabbricato (p_pk_cespite);
    allinea_coefficienti_cespite (p_pk_cespite);
  -- allinea il pk_cuaa del cespite
  -- (vedi definizione per errore) allinea_pk_cuaa_cespite (p_pk_cespite);
  END allinea_cespite;

  /*
   * procedure allinea_tutti_cespiti
   * author: CALEFFI Andrea
   * create date: 2008-11-05
   *
   * La procedura chiama la procedura patri_pck.allinea_cespite su tutti i cespiti
   *
   */
  PROCEDURE allinea_tutti_cespiti IS
    CURSOR curcespite IS
      SELECT pk_cespite
        FROM patri_cespiti;
  BEGIN
    FOR rec IN curcespite LOOP
      patri_pck.allinea_cespite (rec.pk_cespite);
    END LOOP;
  END;

  PROCEDURE allinea_coefficienti_cespite (p_pk_cespite NUMBER) IS
  BEGIN
    UPDATE patri_cespiti_ec pcec
       SET (coef_tp_cat, coef_cl_demog, coef_ubic, coef_piano, coef_stato_cm, coef_verde_com) =
             (SELECT pue.coef_tipol_cat,
                     pue.coef_classe_demog,
                     pue.coef_ubicazione,
                     pue.coef_liv_piano,
                     pue.coef_stato_cons,
                     pue.coef_verde_com
                FROM patri_cespiti_cat_viw pccw, patri_uiu_ext pue
               WHERE pccw.cod_nazionale = pue.cod_nazionale AND pccw.foglio = pue.foglio
                     AND pccw.particella = pue.particella AND pccw.sub = pue.sub AND pccw.unimm = pue.unimm
                     AND pccw.pk_cespite = pcec.pk_cespite AND ROWNUM = 1)
     WHERE pcec.pk_cespite = p_pk_cespite;
  END allinea_coefficienti_cespite;

  PROCEDURE do_cambia_codcespite (tablename VARCHAR2, fieldname VARCHAR2, p_old_cod VARCHAR2, p_new_cod VARCHAR2) IS
    m_old_cod                     VARCHAR2 (12);
    m_new_cod                     VARCHAR2 (12);
  BEGIN
    m_old_cod := UPPER (p_old_cod);
    m_new_cod := UPPER (p_new_cod);

    EXECUTE IMMEDIATE 'update ' || tablename || ' set ' || fieldname || ' = :1 where cod_ces = :2'
                USING m_new_cod, m_old_cod;
  END do_cambia_codcespite;

  PROCEDURE cambia_codcespite (p_old_cod VARCHAR2, p_new_cod VARCHAR2) IS
    TYPE vc_array IS TABLE OF VARCHAR2 (30)
      INDEX BY PLS_INTEGER;

    tabelle                       vc_array;
  BEGIN
    tabelle (0) := 'rivsval';
    tabelle (1) := 'sc_mod_h';
    tabelle (2) := 'sc_rif_f';
    tabelle (3) := 'sc_rif_l';
    tabelle (4) := 'sc_rif_s';
    tabelle (5) := 'assicura';
    tabelle (6) := 'ammorta';
    tabelle (7) := 'ammorta_fisc';
    tabelle (8) := 'fair_value';
    tabelle (9) := 'sc_stab';
    tabelle (10) := 'mov_ces';
    tabelle (11) := 'fattpag';
    tabelle (12) := 'fatture';
    tabelle (13) := 'indicebi';
    tabelle (14) := 'millesi';
    tabelle (15) := 'millesi_valid';
    tabelle (16) := 'bilanci';
    tabelle (17) := 'consumi';
    tabelle (18) := 'mil_erog_dif';
    tabelle (19) := 'lp_fattpag';
    tabelle (20) := 'lp_fatture';
    tabelle (21) := 'lp_indicebi';
    tabelle (22) := NULL;                                                                             --'lp_coproprie';
    tabelle (23) := 'lp_bilanci';
    tabelle (24) := 'lp_fatdett';
    tabelle (25) := 'doc_par';
    tabelle (26) := 'disegni';
    tabelle (27) := 'mod_par';
    tabelle (28) := 'modelli';
    tabelle (29) := 'id_archivioobb';
    tabelle (30) := 'im_cmp';
    tabelle (31) := 'im_festivi';
    tabelle (32) := 'costi_gestione';
    tabelle (33) := 'costi_trib';
    tabelle (34) := 'utenze';
    tabelle (35) := 'costi_cap_ces';
    tabelle (36) := 'am_bilanci';
    tabelle (37) := 'am_indicebi';
    tabelle (38) := 'am_assegna';
    tabelle (39) := 'am_assegnadett';

    FOR i IN tabelle.FIRST .. tabelle.LAST LOOP
      IF tabelle (i) IS NOT NULL THEN
        do_cambia_codcespite (tabelle (i), 'cod_ces', p_old_cod, p_new_cod);
      END IF;
    END LOOP;

    do_cambia_codcespite ('sc_mob', 'uni_imm', p_old_cod, p_new_cod);
    do_cambia_codcespite ('sc_mop', 'uni_imm', p_old_cod, p_new_cod);
    do_cambia_codcespite ('sc_tel', 'uni_imm', p_old_cod, p_new_cod);
    do_cambia_codcespite ('sc_comp', 'uni_imm', p_old_cod, p_new_cod);
    do_cambia_codcespite ('sc_pro', 'uni_imm', p_old_cod, p_new_cod);
    do_cambia_codcespite ('consumi', 'cod_uni', p_old_cod, p_new_cod);
    do_cambia_codcespite ('im_cmp', 'uni_imm', p_old_cod, p_new_cod);

    EXECUTE IMMEDIATE 'update patri_cespiti set cod_gruppo = :1 where cod_cespite = :2'
                USING UPPER (p_new_cod), UPPER (p_old_cod);
  END cambia_codcespite;

  -- Inizializza i dati necessari  e torna il reddito netto
  FUNCTION init_ana_inqui (p_cod_soggetto NUMBER, p_data DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_red_ne                      NUMBER;
    m_red_au                      NUMBER;
    m_tot_detr                    NUMBER;
    pct_ne                        NUMBER;
    pct_au                        NUMBER;
    m_num_over18                  NUMBER;
    m_num_under15                 NUMBER;
    dummy                         NUMBER;
  BEGIN
    BEGIN
      -- verifico se il soggetto ï¿½ collegato ad un nucleo famigliare
      SELECT s2.cod_soggetto
        INTO dummy
        FROM anag_relazioni r, anag_relazioni r2, anag_soggetti s2
       WHERE r.pktipo_rel = -100 AND r.pkcod_sogg = p_cod_soggetto AND s2.cod_soggetto = r2.pkcod_sogg
             AND p_data BETWEEN r2.data_inizio_val AND r2.data_fine_val
             AND p_data BETWEEN r.data_inizio_val AND r.data_fine_val
             AND p_data BETWEEN s2.data_inizio_val AND s2.data_fine_val AND r2.pkid_relazione = r.pkid_relazione
             AND r.fkcod_ruolo > -301 AND r2.fkcod_ruolo > -301 AND ROWNUM = 1;

      SELECT 0,
             SUM (m.reddito_lav_dip),
             SUM (m.reddito_lav_aut),
             SUM (m.reddito_lav_dip) + SUM (m.reddito_lav_aut) + SUM (m.reddito_pens),
             SUM (m.reddito_pens),
             COUNT (*),
             0,
             0,
             0,
             SUM (m.ise),
             SUM (m.isee)
        INTO ultimo_ana_inqui
        FROM anag_relazioni r, anag_relazioni r2, anag_soggetti s2, patri_anag_redditi m
       WHERE r.pktipo_rel = -100 AND r.pkcod_sogg = p_cod_soggetto AND s2.cod_soggetto = r2.pkcod_sogg
             AND m.cod_soggetto(+) = s2.cod_soggetto AND p_data BETWEEN r2.data_inizio_val AND r2.data_fine_val
             AND p_data BETWEEN r.data_inizio_val AND r.data_fine_val
             AND p_data BETWEEN s2.data_inizio_val AND s2.data_fine_val AND p_data BETWEEN m.data_inizio_val(+) AND m.data_fine_val(+)
             AND r2.pkid_relazione = r.pkid_relazione AND r.fkcod_ruolo > -301 AND r2.fkcod_ruolo > -301;

      -- cerco il numero di maggiorenni
      SELECT COUNT (*)
        INTO m_num_over18
        FROM anag_relazioni r, anag_relazioni r2, anag_soggetti s2, patri_anag_redditi m
       WHERE r.pktipo_rel = -100 AND r.pkcod_sogg = p_cod_soggetto AND s2.cod_soggetto = r2.pkcod_sogg
             AND m.cod_soggetto(+) = s2.cod_soggetto AND p_data BETWEEN r2.data_inizio_val AND r2.data_fine_val
             AND p_data BETWEEN r.data_inizio_val AND r.data_fine_val
             AND p_data BETWEEN s2.data_inizio_val AND s2.data_fine_val AND p_data BETWEEN m.data_inizio_val(+) AND m.data_fine_val(+)
             AND r2.pkid_relazione = r.pkid_relazione AND r.fkcod_ruolo > -301 AND r2.fkcod_ruolo > -301
             AND EXTRACT (YEAR FROM p_data) - EXTRACT (YEAR FROM d_nascita) >= 18;

      -- cerco il numero componenti < di 15 anni
      SELECT COUNT (*)
        INTO m_num_under15
        FROM anag_relazioni r, anag_relazioni r2, anag_soggetti s2, patri_anag_redditi m
       WHERE r.pktipo_rel = -100 AND r.pkcod_sogg = p_cod_soggetto AND s2.cod_soggetto = r2.pkcod_sogg
             AND m.cod_soggetto(+) = s2.cod_soggetto AND p_data BETWEEN r2.data_inizio_val AND r2.data_fine_val
             AND p_data BETWEEN r.data_inizio_val AND r.data_fine_val
             AND p_data BETWEEN s2.data_inizio_val AND s2.data_fine_val AND p_data BETWEEN m.data_inizio_val(+) AND m.data_fine_val(+)
             AND r2.pkid_relazione = r.pkid_relazione AND r.fkcod_ruolo > -301 AND r2.fkcod_ruolo > -301
             AND EXTRACT (YEAR FROM p_data) - EXTRACT (YEAR FROM d_nascita) < 15;

      SELECT COUNT (*)
        INTO ultimo_ana_inqui.comp_car
        FROM anag_relazioni r, anag_relazioni r2
       WHERE r.pktipo_rel = -100 AND r.pkcod_sogg = p_cod_soggetto
             AND p_data BETWEEN r.data_inizio_val AND r.data_fine_val
             AND (r.fkcod_ruolo IS NULL OR r.fkcod_ruolo > -101 OR r.fkcod_ruolo < -199)
             AND r2.pkid_relazione = r.pkid_relazione AND p_data BETWEEN r2.data_inizio_val AND r2.data_fine_val
             AND r2.fkcod_ruolo <= -101 AND r2.fkcod_ruolo >= -199;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        SELECT 0,
               SUM (NVL (m.reddito_lav_dip, 0)),
               SUM (NVL (m.reddito_lav_aut, 0)),
               SUM (NVL (m.reddito_lav_dip, 0) + NVL (m.reddito_lav_aut, 0) + NVL (m.reddito_pens, 0)),
               SUM (NVL (m.reddito_pens, 0)),
               1,
               0,
               0,
               0,
               SUM (NVL (m.ise, 0)),
               SUM (NVL (m.isee, 0))
          INTO ultimo_ana_inqui
          FROM anag_soggetti s, patri_anag_redditi m
         WHERE s.cod_soggetto = p_cod_soggetto AND m.cod_soggetto(+) = s.cod_soggetto
               AND p_data BETWEEN s.data_inizio_val AND s.data_fine_val AND p_data BETWEEN m.data_inizio_val(+) AND m.data_fine_val(+);

        -- cerco il numero di maggiorenni
        SELECT COUNT (*)
          INTO m_num_over18
          FROM anag_soggetti s
         WHERE EXTRACT (YEAR FROM p_data) - EXTRACT (YEAR FROM d_nascita) >= 18 AND cod_soggetto = p_cod_soggetto
               AND p_data BETWEEN s.data_inizio_val AND s.data_fine_val;

        -- cerco il numero di minori di 15 anni
        SELECT COUNT (*)
          INTO m_num_under15
          FROM anag_soggetti s
         WHERE EXTRACT (YEAR FROM p_data) - EXTRACT (YEAR FROM d_nascita) < 15 AND cod_soggetto = p_cod_soggetto
               AND p_data BETWEEN s.data_inizio_val AND s.data_fine_val;
    END;

    m_red_ne := ultimo_ana_inqui.reddito_si + ultimo_ana_inqui.reddito_pe;
    m_red_au := ultimo_ana_inqui.reddito_au;
    ultimo_ana_inqui.comp_over18 := m_num_over18;
    ultimo_ana_inqui.comp_under15 := m_num_under15;

    IF (ultimo_ana_inqui.comp_car > 0) THEN
      SELECT LEAST (NVL (det_carico, 0) * ultimo_ana_inqui.comp_car, 3098.74)
        INTO m_tot_detr
        FROM costanti
       WHERE ROWNUM = 1;

      IF (m_tot_detr != 0) THEN
        IF (m_red_au = 0 AND m_red_ne > 0) THEN
          m_red_ne := m_red_ne - m_tot_detr;
        ELSIF (m_red_au > 0 AND m_red_ne = 0) THEN
          m_red_au := m_red_au - m_tot_detr;
        ELSIF (m_red_au > 0 AND m_red_ne > 0) THEN
          pct_ne := (m_red_ne * 100) / (m_red_ne + m_red_au);
          pct_au := 100 - pct_ne;
          m_red_ne := m_red_ne - ((m_tot_detr * pct_ne) / 100);
          m_red_au := m_red_au - ((m_tot_detr * pct_au) / 100);
        END IF;
      END IF;
    END IF;

    SELECT m_red_ne * NVL (coef_riduz, 1)
      INTO m_red_ne
      FROM costanti
     WHERE ROWNUM = 1;

    m_red_ne := m_red_ne + m_red_au;
    ultimo_ana_inqui.reddito_ne := m_red_ne;
    RETURN m_red_ne;
  END init_ana_inqui;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_reddito_ne
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.reddito_ne;
  END get_reddito_ne;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_reddito_ld
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.reddito_si;
  END get_reddito_ld;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_reddito_au
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.reddito_au;
  END get_reddito_au;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_reddito_tot
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.reddito_tot;
  END get_reddito_tot;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_reddito_pe
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.reddito_pe;
  END get_reddito_pe;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_comp_nucl
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.comp_nucl;
  END get_comp_nucl;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_comp_car
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.comp_car;
  END get_comp_car;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_comp_over18
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.comp_over18;
  END get_comp_over18;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_comp_under15
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.comp_under15;
  END get_comp_under15;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_ise
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.ise;
  END get_ise;

  -- ATTENZIONE Prima di questa funzione si deve chiamare init_ana_inqui
  FUNCTION get_isee
    RETURN NUMBER IS
  BEGIN
    RETURN ultimo_ana_inqui.isee;
  END get_isee;

  -- crea uno snapshot della vista contratt_cespiti_valid
  FUNCTION get_ccv_ticket (view_perc_sup_locata NUMBER DEFAULT 0)
    RETURN NUMBER IS
    m_ticket                      NUMBER;
  BEGIN
    -- prendo il numero del ticket
    SELECT ccv_snapshot_seq.NEXTVAL
      INTO m_ticket
      FROM DUAL;

    create_ccv_snapshot (m_ticket, view_perc_sup_locata);
    RETURN m_ticket;
  END get_ccv_ticket;

  PROCEDURE create_ccv_snapshot (p_ticket NUMBER, view_perc_sup_locata NUMBER DEFAULT 0) IS
    perc_sup_locata_field         VARCHAR2 (50) := 'NULL';
  BEGIN
    IF view_perc_sup_locata = 1 THEN
      perc_sup_locata_field := 'P_SUP_LOCA';
    END IF;

    -- cancello eventuali record precedenti aventi lo stesso ticket
    DELETE FROM ccv_snapshot
          WHERE ticket = p_ticket;

    -- eseguo l'inserimento
    EXECUTE IMMEDIATE 'insert into ccv_snapshot (TICKET, CODICE, ID_CONTR, COD_CES, DATA_INIZIO_VAL, DATA_FINE_VAL, SUP_LOCA, P_SUP_LOCA, PK_CESPITE) '
                      || '(SELECT :1, CODICE, ID_CONTR, COD_CES, DATA_INIZIO_VAL, DATA_FINE_VAL, SUP_LOCA, '
                      || perc_sup_locata_field || ', PK_CESPITE FROM CONTRATT_CESPITI_VALID)'
                USING p_ticket;
  END create_ccv_snapshot;

  -- a.caleffi 2010-04-28
  PROCEDURE allinea_pk_cuaa_cespite (p_pk_cespite NUMBER) IS
  BEGIN
    UPDATE patri_cespiti pc
       SET pc.pk_cuaa =
             (SELECT DISTINCT pk_cuaa
-- 2010/05/24 Moressi - Questa query potrebbe ritornare + righe con lo stesso soggetto e quindi ï¿½ stata aggiunta la distinct
                         FROM patri_cespiti_cat_viw pcv
                        WHERE pcv.pk_cespite = pc.pk_cespite)
     WHERE pc.pk_cespite = p_pk_cespite;
  END allinea_pk_cuaa_cespite;
END patri_pck;
/


DROP PACKAGE BODY SITI_H501.PATRI_SETTORI_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.patri_settori_pck AS
----------------------------------------------------------------------------
  FUNCTION is_inheritance_enabled
    RETURN NUMBER IS
    m_ps_inheritance_enabled      NUMBER := 1;
  BEGIN
    BEGIN
      SELECT DECODE (UPPER (NVL (valore, 'SI')), 'SI', 1, 0)
        INTO m_ps_inheritance_enabled
        FROM gisparams
       WHERE variabile = 'PATRI_SETTORI_EREDITA';
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_ps_inheritance_enabled := 1;
    END;

    RETURN m_ps_inheritance_enabled;
  END is_inheritance_enabled;

----------------------------------------------------------------------------
  FUNCTION is_aggr_settore (
    p_settore                            NUMBER,
    p_cod_nazionale                      VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_date_val                           DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    m_is_aggr_settore             NUMBER := 0;
  BEGIN
    IF is_inheritance_enabled () = 1 THEN
      SELECT COUNT (*)
        INTO m_is_aggr_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_aggregati
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_particelle
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_uiu
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_vani
                        WHERE fk_settore = p_settore)
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub;
    ELSE
      SELECT COUNT (*)
        INTO m_is_aggr_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_aggregati
                        WHERE fk_settore = p_settore AND etype = 'P')
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub;
    END IF;

    RETURN m_is_aggr_settore;
  END is_aggr_settore;

----------------------------------------------------------------------------
  FUNCTION is_part_settore (
    p_settore                            NUMBER,
    p_cod_nazionale                      VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_date_val                           DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    m_is_part_settore             NUMBER := 0;
  BEGIN
    IF is_inheritance_enabled () = 1 THEN
      SELECT COUNT (*)
        INTO m_is_part_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_aggregati
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_particelle
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_uiu
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_vani
                        WHERE fk_settore = p_settore)
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub;
    ELSE
      SELECT COUNT (*)
        INTO m_is_part_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub
                         FROM settori_cr_particelle
                        WHERE fk_settore = p_settore AND etype = 'P')
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub;
    END IF;

    RETURN m_is_part_settore;
  END is_part_settore;

----------------------------------------------------------------------------
  FUNCTION is_uiu_settore (
    p_settore                            NUMBER,
    p_cod_nazionale                      VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
    p_date_val                           DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    m_is_uiu_settore              NUMBER := 0;
  BEGIN
    IF is_inheritance_enabled () = 1 THEN
      SELECT COUNT (*)
        INTO m_is_uiu_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm
                         FROM settori_cr_aggregati
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm
                         FROM settori_cr_particelle
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm
                         FROM settori_cr_uiu
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm
                         FROM settori_cr_vani
                        WHERE fk_settore = p_settore)
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
             AND NVL (p_unimm, -1) = NVL (unimm, -1);
    ELSE
      SELECT COUNT (*)
        INTO m_is_uiu_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm
                         FROM settori_cr_uiu
                        WHERE fk_settore = p_settore AND etype = 'U')
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
             AND NVL (p_unimm, -1) = NVL (unimm, -1);
    END IF;

    RETURN m_is_uiu_settore;
  END is_uiu_settore;

----------------------------------------------------------------------------
  FUNCTION is_vano_settore (
    p_settore                            NUMBER,
    p_cod_nazionale                      VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
    p_vano                               NUMBER,
    p_date_val                           DATE DEFAULT SYSDATE
  )
    RETURN NUMBER IS
    m_is_vano_settore             NUMBER := 0;
  BEGIN
    IF is_inheritance_enabled () = 1 THEN
      SELECT COUNT (*)
        INTO m_is_vano_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm,
                              NVL (vano, -1) AS vano
                         FROM settori_cr_aggregati
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm,
                              NVL (vano, -1) AS vano
                         FROM settori_cr_particelle
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm,
                              NVL (vano, -1) AS vano
                         FROM settori_cr_uiu
                        WHERE fk_settore = p_settore
              UNION
              SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm,
                              NVL (vano, -1) AS vano
                         FROM settori_cr_vani
                        WHERE fk_settore = p_settore)
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
             AND NVL (p_unimm, -1) = NVL (unimm, -1) AND NVL (p_vano, -1) = NVL (vano, -1);
    ELSE
      SELECT COUNT (*)
        INTO m_is_vano_settore
        FROM (SELECT DISTINCT cod_nazionale,
                              foglio,
                              particella,
                              sub,
                              NVL (unimm, -1) AS unimm,
                              NVL (vano, -1) AS vano
                         FROM settori_cr_vani
                        WHERE fk_settore = p_settore AND etype = 'V')
       WHERE cod_nazionale = p_cod_nazionale AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
             AND NVL (p_unimm, -1) = NVL (unimm, -1) AND NVL (p_vano, -1) = NVL (vano, -1);
    END IF;

    RETURN m_is_vano_settore;
  END is_vano_settore;

