------------------------------------------------------------------------------
procedure set_measure_at_point
  (geom in out mdsys.sdo_geometry,
   n in integer,
   m in integer
   )
is
  pn integer;
  dim_count number;
  lrs_dim number;
  px number;
  py number;
  pz number;

begin
  -- Get the number of dimensions from the gtype
  if length (geom.sdo_gtype) = 4 then
    dim_count := substr (geom.sdo_gtype, 1, 1);
  else
    raise_application_error (-20000, 'GTYPE must be 4 digits');
  end if;

  -- Find the dimension holding the measure
  lrs_dim := substr (geom.sdo_gtype, 2, 1);
  if lrs_dim = 0 then
    -- LRS dimension not specified. Use last dimension
    lrs_dim := dim_count;
  end if;

  -- Make sure the requested point exists
  pn := n;
  if pn > 0 then
    if geom.sdo_ordinates is null or
      pn*dim_count > geom.sdo_ordinates.count() then
      raise_application_error (-20000, 'Point number out of range');
    end if;
  else
    -- We want the last point in the geometry
    pn := geom.sdo_ordinates.count() / dim_count;
  end if;

  -- Set measure of the desired point
  geom.sdo_ordinates((pn-1)*dim_count+lrs_dim) := m;
end;
------------------------------------------------------------------------------
function get_tile_code
  (level in number,
    col  in number,
    row  in number)
  return raw
is

  i integer;   -- Column index
  j integer;   -- Row index
  l integer;   -- Level counter
  ll integer;  -- Shift for storing digits in result
  ic integer;  -- Hold column index converted to (0, 1)
  jc integer;  -- Hold row index converted to (1, 0)
  d integer;   -- Hold tile code digit (0 to 3)
  s integer;   -- Left shift for rounding tile code up to the byte level
  o integer;   -- Offset in bytes

  tile_code integer := 0;   -- Result tilecode in binary
  tile_code_r raw(8) := ''; -- Result tilecode in raw

begin

  -- Verify that input is correct
  if col < 1 or col > 2**level or
     row < 1 or row > 2**level then
    raise_application_error (-20000, 'Invalid tile grid row or column. Must be in the range [1:'||2**level|| ']');
  end if;
  i := col;                             -- Save column index (1 to N)
  j := row;                             -- Save row index (1 to N)
  ll := 1;                              -- Initialize shift

  for l in 1..level loop                -- Loop for each level
    ic := mod (i-1, 2);                 -- Convert column index to (0,1)
    jc := 1- mod (j-1, 2);              -- Convert row index to (1,0)
    d := jc*2+ic;                       -- Compute tile code digit (0 to 3)
    tile_code := d*ll + tile_code;      -- Shift tile code digit by 2 bits and add to result
    i := floor((i+1)/2);                -- Go up one level in the column index
    j := floor((j+1)/2);                -- Go up one level in the row index
    ll := ll * 4;                       -- Advance shift by 4 (= 2 bits)
  end loop;

  -- Need to shift the resulting tilecode left so that it fits into an exact number of bytes
  -- Since each byte can hold up to 4 levels, compute the number of levels missing to form
  -- a multiple of 4
  s := 4 - mod(level, 4);               -- Compute shift (0 to 3)
  if s = 4 then
    s := 0;
  end if;
  tile_code := tile_code * 4**s;        -- Shift left

  -- Convert the tile code into RAW format
  --tile_code_r := utl_raw.cast_from_binary_integer(tile_code);

  -- Align the tilecode left
  o := (32 - level*2 - s*2) / 8 + 1;
  tile_code_r := utl_raw.substr(tile_code_r, o);
  return tile_code_r;
end;

FUNCTION AFFINE_LINEAR
(
  THEGEOM IN MDSYS.SDO_GEOMETRY,
  P0 IN NUMBER,
  P1 IN NUMBER,
  P2 IN NUMBER,
  P3 IN NUMBER,
  P4 IN NUMBER,
  P5 IN NUMBER
) RETURN MDSYS.SDO_GEOMETRY IS
OUTGEOM MDSYS.SDO_GEOMETRY;
IDX NUMBER;
THEX NUMBER;
THEY NUMBER;
BEGIN
  IF THEGEOM IS NULL THEN RETURN NULL; END IF;

--  IF THEGEOM.SDO_GTYPE <> G_2D_POLYGON THEN
--    RAISE_APPLICATION_ERROR(-20999,'GTYPE != 2003');
--  END IF;

  OUTGEOM:=THEGEOM;
  IF OUTGEOM.SDO_ORDINATES IS NOT NULL THEN
    FOR IDX IN OUTGEOM.SDO_ORDINATES.FIRST()..OUTGEOM.SDO_ORDINATES.LAST() LOOP
      IF MOD(IDX,2)>0 THEN
        THEX:=OUTGEOM.SDO_ORDINATES(IDX);
        THEY:=OUTGEOM.SDO_ORDINATES(IDX+1);

        OUTGEOM.SDO_ORDINATES(IDX)  :=P0 * THEX + P4 * THEY + P2;
        OUTGEOM.SDO_ORDINATES(IDX+1):=P1 * THEX + P5 * THEY + P3;
      END IF;
    END LOOP;
  ELSE
    THEX:=OUTGEOM.SDO_POINT.X;
    THEY:=OUTGEOM.SDO_POINT.Y;
    OUTGEOM.SDO_POINT.X :=P0 * THEX + P4 * THEY + P2;
    OUTGEOM.SDO_POINT.Y :=P1 * THEX + P5 * THEY + P3;
  END IF;

  RETURN OUTGEOM;
END;

FUNCTION DBMAP_POINT (X NUMBER,Y NUMBER) RETURN MDSYS.SDO_GEOMETRY IS
BEGIN
  RETURN MDSYS.SDO_GEOMETRY(2001,NULL,NULL,MDSYS.SDO_ELEM_INFO_ARRAY(1,1,1),MDSYS.SDO_ORDINATE_ARRAY(X,Y));
END;

FUNCTION DBMAP_RECTANGLE (X1 NUMBER,Y1 NUMBER,X2 NUMBER,Y2 NUMBER) RETURN MDSYS.SDO_GEOMETRY IS
BEGIN
  RETURN MDSYS.SDO_GEOMETRY(2003,NULL,NULL,MDSYS.SDO_ELEM_INFO_ARRAY(1,1003,1),MDSYS.SDO_ORDINATE_ARRAY(X1,Y1,X2,Y1,X2,Y2,X1,Y2,X1,Y1));
END;


END SDO_TOOLS;
/


DROP PACKAGE BODY SITI_H501.SITICOMMONS;

CREATE OR REPLACE PACKAGE BODY SITI_H501.siticommons AS

PROCEDURE AGG_ANOM_REFR(CODNAZ IN VARCHAR2, FOG IN NUMBER)
IS
  CURSOR C0 IS SELECT 1 + gr1 + gr2 + gr3 + gr4 + gr5 + gr6 + gr7 FROM SITIANOM_REFR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND INUSE=0 AND ROWNUM=1;
  CURSOR C1 IS SELECT 1 FROM AGG_FOGLI WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND ROWNUM=1;
  SALTA NUMBER(5);
BEGIN
  OPEN C0;
  FETCH C0 INTO SALTA;
  IF C0%NOTFOUND THEN SALTA:=0; END IF;
  CLOSE C0;

  IF SALTA=0 THEN
    INSERT INTO SITIANOM_REFR(COD_NAZIONALE,FOGLIO,INUSE) VALUES (CODNAZ,FOG,0);
  ELSE
    IF SALTA > 0 THEN -- VUOL DIRE CHE HO GIÀ RICALCOLATO QUALCOSA
      UPDATE SITIANOM_REFR SET GR1=0,GR2=0,GR3=0,GR4=0,GR5=0,GR6=0,GR7=0 WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND INUSE=0 AND ROWNUM=1;
    END IF;
  END IF;

  OPEN C1;
  FETCH C1 INTO SALTA;
  IF C1%NOTFOUND THEN SALTA:=0; END IF;
  CLOSE C1;

  IF SALTA=0 THEN
    INSERT INTO AGG_FOGLI(COD_NAZIONALE,FOGLIO) VALUES (CODNAZ,FOG);
  ELSE
      UPDATE AGG_FOGLI SET DATA_AGG=SYSDATE WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND ROWNUM=1;
  END IF;

END AGG_ANOM_REFR;
	
END siticommons;
/


DROP PACKAGE BODY SITI_H501.SITICONS_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.siticons_pck
IS
   PROCEDURE setutente (utente VARCHAR2)
   IS
   BEGIN
      nome_utente := utente;
   END;

--Procedura soggetto
--Decodifica un soggetto dato un codice fiscale
   PROCEDURE soggetto (
      codice_fiscale     IN       VARCHAR2,
      partita_iva        OUT      VARCHAR2,
      ragione_sociale    OUT      VARCHAR2,
      nome               OUT      VARCHAR2,
      comune_nascita     OUT      VARCHAR2,
      civico_resi        OUT      number,
      errore             OUT      NUMBER
   )
   IS
   BEGIN
      IF codice_fiscale IS NULL OR codice_fiscale = ''
      THEN
         errore := -1;
      ELSE
         SELECT s.part_iva, s.ragi_soci, s.nome, s.fkcod_comu_nasc, s.fkcivico_resi
           INTO partita_iva, ragione_sociale, nome, comune_nascita, civico_resi
           FROM cons_sogg_viw s
          WHERE (   s.cod_fiscale = codice_fiscale
                 OR s.part_iva = codice_fiscale
                 OR cuaa = codice_fiscale
                )
            AND ROWNUM = 1;

         errore := 0;
      END IF;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         errore := -1;
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore GET_AREA_CAT :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         errore := -2;
   END soggetto;

   FUNCTION supe_cata_vali (
      areacat   IN   NUMBER,
      datacat   IN   DATE,
      areagis   IN   NUMBER,
      datagis   IN   DATE
   )
      RETURN NUMBER
   IS
      retvalue      NUMBER;
      discordanza   NUMBER := 0;
   BEGIN
      IF areacat < 0 AND areagis <= 0
      THEN
         retvalue := -1;
      ELSIF areacat >= 0 AND areagis <= 0
      THEN
         retvalue := areacat;
      ELSIF areacat < 0 AND areagis > 0
      THEN
         retvalue := areagis;
      ELSE
         discordanza := esiste_discordanza_aree (areacat, areagis);

         IF discordanza = 0
         THEN
            IF datacat >= datagis
            THEN
               retvalue := areacat;
            ELSE
               retvalue := areagis;
            END IF;
         ELSE
            retvalue := areacat;
         END IF;
      END IF;

      RETURN retvalue;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore get_supe_cata_vali :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         RETURN -2;
   END supe_cata_vali;

   FUNCTION fonte_cata_vali (
      areacat   IN   NUMBER,
      datacat   IN   DATE,
      areagis   IN   NUMBER,
      datagis   IN   DATE
   )
      RETURN NUMBER
   IS
      retvalue      NUMBER;
      discordanza   NUMBER := 0;
   BEGIN
      IF areacat <= 0 AND areagis <= 0
      THEN
         retvalue := -1;
      ELSIF areacat > 0 AND areagis <= 0
      THEN
         retvalue := 0;
      ELSIF areacat <= 0 AND areagis > 0
      THEN
         retvalue := 1;
      ELSE
         discordanza := esiste_discordanza_aree (areacat, areagis);

         IF discordanza = 0
         THEN
            IF datacat >= datagis
            THEN
               retvalue := 0;
            ELSE
               retvalue := 1;
            END IF;
         ELSE
            retvalue := 0;
         END IF;
      END IF;

      RETURN retvalue;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore get_fonte_cata_vali :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         RETURN -2;
   END fonte_cata_vali;

   FUNCTION get_area_cat (
      datainizio   IN   DATE,
      fog          IN   NUMBER,
      part         IN   VARCHAR2,
      subo         IN   VARCHAR2,
      codnaz       IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      areacat       NUMBER;
      DATA          DATE;
      err           NUMBER;
      datarif       DATE;
      flagtipocat   VARCHAR2 (1);
      flagvali      VARCHAR2 (1);
      qual          VARCHAR2 (3);
      classe        VARCHAR2 (2);
      partita       VARCHAR2 (7);
   BEGIN
      IF datainizio IS NULL
      THEN
         datarif := TO_DATE ('99991231', 'YYYYMMDD');
      ELSE
         datarif := datainizio;
      END IF;

      catasto_terreni (datarif,
                       codnaz,
                       fog,
                       part,
                       subo,
                       areacat,
                       flagtipocat,
                       flagvali,
                       DATA,
                       err,
                       qual,
                       classe,
                       partita
                      );

      IF flagvali = 0 AND datarif = TO_DATE ('99991231', 'YYYYMMDD')
      THEN
         areacat := 0;
      END IF;

      IF err < 0
      THEN
         areacat := -1;
      END IF;

      RETURN areacat;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore GET_AREA_CAT :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         RETURN -2;
   END get_area_cat;

   FUNCTION get_area_gis (
      datainizio   IN   DATE,
      fog          IN   NUMBER,
      part         IN   VARCHAR2,
      subo         IN   VARCHAR2,
      codnaz       IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      areagis   NUMBER;
      DATA      DATE;
      err       NUMBER;
      datarif   DATE;
   BEGIN
      IF datainizio IS NULL
      THEN
         datarif := TO_DATE ('99991231', 'YYYYMMDD');
      ELSE
         datarif := datainizio;
      END IF;

      catasto_gis (datarif, codnaz, fog, part, subo, areagis, DATA, err);

      IF err < 0
      THEN
         areagis := -1;
      END IF;

      RETURN areagis;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore GET_AREA_GIS :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         RETURN -2;
   END get_area_gis;

   FUNCTION get_supe_cata_vali (
      datainizio   IN   DATE,
      fog          IN   NUMBER,
      part         IN   VARCHAR2,
      subo         IN   VARCHAR2,
      codnaz       IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      supecatavali   NUMBER;
      areacat        NUMBER;
      datacat        DATE;
      areagis        NUMBER;
      datagis        DATE;
      err            NUMBER;
      datarif        DATE;
      flagtipocat    VARCHAR2 (1);
      flagvali       VARCHAR2 (1);
      qual           VARCHAR2 (3);
      classe         VARCHAR2 (2);
      partita        VARCHAR2 (7);
   BEGIN
      supecatavali := -1;

      IF datainizio IS NULL
      THEN
         datarif := TO_DATE ('99991231', 'YYYYMMDD');
      ELSE
         datarif := datainizio;
      END IF;

      catasto_gis (datarif, codnaz, fog, part, subo, areagis, datagis, err);

      IF err < 0
      THEN
         areagis := -1;
         datagis := NULL;
      END IF;

      catasto_terreni (datarif,
                       codnaz,
                       fog,
                       part,
                       subo,
                       areacat,
                       flagtipocat,
                       flagvali,
                       datacat,
                       err,
                       qual,
                       classe,
                       partita
                      );

      IF flagvali = 0 AND datarif = TO_DATE ('99991231', 'YYYYMMDD')
      THEN
         areacat := 0;
      END IF;

      IF err < 0
      THEN
         areacat := -1;
         datacat := NULL;
      END IF;

      supecatavali := supe_cata_vali (areacat, datacat, areagis, datagis);
      RETURN supecatavali;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore GET_AREA_GIS :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         RETURN -2;
   END get_supe_cata_vali;

   FUNCTION get_data_gis (
      datainizio   IN   DATE,
      fog          IN   NUMBER,
      part         IN   VARCHAR2,
      subo         IN   VARCHAR2,
      codnaz       IN   VARCHAR2
   )
      RETURN DATE
   IS
      areagis   NUMBER;
      DATA      DATE;
      err       NUMBER;
      datarif   DATE;
   BEGIN
      IF datainizio IS NULL
      THEN
         datarif := TO_DATE ('99991231', 'YYYYMMDD');
      ELSE
         datarif := datainizio;
      END IF;

      catasto_gis (datarif, codnaz, fog, part, subo, areagis, DATA, err);

