      END IF;

      RETURN DATA;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore GET_AREA_GIS :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         RETURN NULL;
   END get_data_gis;

