--****************************************************************************
--****************************************************************************
--****************************************************************************

   -- COMMENTO ALLA FUNZIONE

   -- Funzione di aggiornamento di dati catastali.

   -- VALORI RITORNATI

   -- Da -1 .. a -6 fare riferimento alla funzione validapart() dal package ABACO_CONS_PCK.
-- -7  Errore nei parametri in input alla funzione.
-- -8  e stata trovata una versione del dato catastale piu recente di quella che si vuole
--     andare ad inserire.
-- -9  Non e stato inserito il codice nazionale.
-- -10 Errore oracle.
-- -11 L'area della particella passata come parametro e uguale a quella registrata nel database.
--     L'aggiornamento non viene eseguito. Passare un'area diversa alla funzione.
-- 1   Funzione eseguita correttamente.
   FUNCTION aggiorna_catasto (
      cod_naz_par   IN   VARCHAR2,
      foglio_par    IN   VARCHAR2,
      part_par      IN   VARCHAR2,
      suba_par      IN   VARCHAR2,
      area_par      IN   VARCHAR2,
      data_par      IN   VARCHAR2,
      utente_par    IN   VARCHAR2,
	  reddagr_par	IN	 VARCHAR2,
	  redddom_par	IN	 VARCHAR2
   )
      RETURN NUMBER
   IS
      ID               NUMBER (9);
      data_aggi        DATE;
      qual_cat         NUMBER (3);
      classe_terreno   VARCHAR2 (2);
      partita          VARCHAR2 (7);
      rendita          NUMBER (12, 2);
      sigla_prov       VARCHAR2 (2);
      istatp           VARCHAR2 (3);
      esiste           BOOLEAN        := TRUE;
      esito            NUMBER;
      siglap           VARCHAR2 (2);
      istat            VARCHAR2 (3);
      DATA             DATE;
      area             VARCHAR2 (10);
      err_scade        NUMBER;
      part             sitiparticella;
      CURSOR c1
      IS
         SELECT   data_aggi, qual_cat, classe_terreno, partita, rendita,
                  sigla_prov, istatp, area_part
             FROM sititrkc
            WHERE cod_nazionale = cod_naz_par
              AND foglio = foglio_par
              AND particella = part_par
              AND sub = suba_par
         ORDER BY data_aggi DESC, valida DESC;
   BEGIN
      IF cod_naz_par IS NOT NULL
      THEN
         SELECT sigla_prov, istatp
           INTO sigla_prov, istatp
           FROM siticomu
          WHERE cod_nazionale = cod_naz_par;
      ELSE
         DBMS_OUTPUT.put_line ('Non e stato inserito il codice nazionale.');
         RETURN -9;
      END IF;


/*      IF( (reddagr_par IS NULL) OR (reddagr_par='')) THEN
        reddagr_par := '0';
      END IF;
      IF( (redddom_par IS NULL) OR (redddom_par='')) THEN
        redddom_par := '0';
      END IF;
*/
      part.cod_nazionale := cod_naz_par;
      part.foglio := LPAD (foglio_par, 4, '0');
      part.particella := part_par;
      part.subalterno := suba_par;
      DATA := TO_DATE (data_par, 'YYYYMMDDHH24MISS');
      esito := validapart (part);

      IF esito <> 1
      THEN
         RETURN esito;
      END IF;

      IF area_par IS NULL OR data_par IS NULL OR utente_par IS NULL OR reddagr_par IS NULL OR redddom_par IS NULL
      THEN
         DBMS_OUTPUT.put_line
                  ('Almeno uno dei parametri in input alla funzione e nullo.');
         RETURN -7;
      END IF;

      OPEN c1;

      FETCH c1
       INTO data_aggi, qual_cat, classe_terreno, partita, rendita, siglap,
            istat, area;

      IF c1%NOTFOUND
      THEN
         esiste := FALSE;
      END IF;

      CLOSE c1;

      SELECT sititrkc_seq.NEXTVAL
        INTO ID
        FROM DUAL;

      IF esiste
      THEN
         IF area_par = area
         THEN
            DBMS_OUTPUT.put_line
               ('Area della particella passata alla funzione uguale a quella contenuta nel database. Aggiornamento non effettuato.'
               );
            RETURN -11;
         ELSIF data_aggi < DATA
         THEN
            err_scade :=
               scade_catasto (part.cod_nazionale,
                              part.foglio,
                              part.particella,
                              part.subalterno,
                              utente_par
                             );

            INSERT INTO sititrkc
                        (trkc_id, sigla_prov, cod_nazionale, foglio,
                         particella, sub, qual_cat,
                         classe_terreno, area_part, partita, data_aggi,
                         rendita, istatp, utente, valida, reddito_agrario, reddito_dominicale
                        )
                 VALUES (ID, siglap, part.cod_nazionale, part.foglio,
                         part.particella, part.subalterno, qual_cat,
                         classe_terreno, area_par, partita, DATA,
                         rendita, istat, utente_par, '1', reddagr_par, redddom_par
                        );
         ELSE
            DBMS_OUTPUT.put_line
               ('Esiste una versione del dato catastale piu recente di quella che si vuole andare ad inserire. Controllare la data di aggiornamento.'
               );
            RETURN -8;
         END IF;
      ELSE
         INSERT INTO sititrkc
                     (trkc_id, sigla_prov, cod_nazionale, foglio,
                      particella, sub, area_part, data_aggi,
                      istatp, utente, valida, partita, reddito_agrario, reddito_dominicale
                     )
              VALUES (ID, sigla_prov, part.cod_nazionale, part.foglio,
                      part.particella, part.subalterno, area_par, DATA,
                      istatp, utente_par, '1', ' ', Nvl(To_Number(reddagr_par),0), Nvl(To_Number(redddom_par),0)
                     );
      END IF;

      RETURN 1;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line ('ERRORE: ' || SQLERRM);
         RETURN -10;

   END aggiorna_catasto;

 -------------------------------------------------------------
--procedura catasto_terreni
--restituisce i dati associati ad una particella
--nel Catasto Terreni
-------------------------------------------------------------
   PROCEDURE catasto_terreni (
      datainizio    IN       DATE,
      --data di riferimento: null=versione piu recente
      codnaz        IN       VARCHAR2,
      --Codice nazionale del Comune
      fog           IN       NUMBER,
      --Numero del foglio
      part          IN       VARCHAR2,
      --Numero della particella
      subo          IN       VARCHAR2,
      --Subalterno: null= senza subalterno
      areacat       OUT      NUMBER,
      --area catastale alla data di riferimento
      flagtipocat   OUT      VARCHAR2,
      --1=austroungarico
      flagvali      OUT      VARCHAR2,
      --1=versione valida: 0=versione scaduta
      DATA          OUT      DATE,
      -- data di aggiornamento
      err           OUT      NUMBER,
      --codice di errore
      qual          OUT      VARCHAR2,
      --qualita catastale
      classe        OUT      VARCHAR2,
      --classe catastale
      partita       OUT      VARCHAR2
   --partita catastale
   )
   IS
      CURSOR c1
      IS
         SELECT   NVL (area_part, 0) AS area_part, data_aggi, valida,
                  qual_cat, classe_terreno, partita
             FROM sititrkc
            WHERE cod_nazionale = codnaz
              AND foglio = fog
              AND particella = part
              AND sub = NVL (subo, ' ')
         ORDER BY data_aggi DESC, valida DESC;

      cc     NUMBER  := 0;
      esci   BOOLEAN;
   BEGIN
      err := 0;
      esci := FALSE;

      FOR c1_rec IN c1
      LOOP
         EXIT WHEN c1%NOTFOUND;
         cc := cc + 1;
         areacat := c1_rec.area_part;
         DATA := c1_rec.data_aggi;
         flagvali := c1_rec.valida;
         qual := c1_rec.qual_cat;
         classe := c1_rec.classe_terreno;
         partita := c1_rec.partita;

         IF datainizio > DATA
         THEN
            EXIT;
         END IF;
      END LOOP;

      IF cc = 0
      THEN
         err := -1;
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore catasto terreni :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         err := -3;
   END catasto_terreni;

-------------------------------------------------------------
--procedura catasto_terreni
--restituisce i dati associati ad una particella
--nel Catasto Terreni
-------------------------------------------------------------
   PROCEDURE catasto_gis (
      datainizio        IN       DATE,
      --data di riferimento: null=versione valida
      codnaz            IN       VARCHAR2,
      --Codice nazionale del Comune
      fog               IN       NUMBER,
      --Numero del foglio
      part              IN       VARCHAR2,
      --Numero della particella
      subo              IN       VARCHAR2,
      --Subalterno: null= senza subalterno
      areapart          OUT      NUMBER,
      --area catastale alla data di riferimento
      data_inizio_val   OUT      DATE,
      -- data di aggiornamento
      err               OUT      NUMBER
   )
   IS
      CURSOR c1
      IS
         SELECT /*+ INDEX (SITIPART SITIPART_PK) */
                ROUND (NVL (area_part, 0)), data_inizio_val
           FROM sitipart
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = NVL (subo, ' ')
            AND data_inizio_val <=
                            NVL (datainizio, TO_DATE ('99991231', 'YYYYMMDD'))
            AND data_fine_val >=
                            NVL (datainizio, TO_DATE ('99991231', 'YYYYMMDD'));
   BEGIN
      err := 0;

      OPEN c1;

      FETCH c1
       INTO areapart, data_inizio_val;

      IF c1%NOTFOUND
      THEN
         err := -1;
      END IF;

      CLOSE c1;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         err := -2;
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore catasto terreni :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
         err := -3;
   END catasto_gis;

--****************************************************************************
--****************************************************************************
--****************************************************************************

   -- COMMENTO ALLA FUNZIONE

   -- Funzione di scadenza di dati catastali.

   -- VALORI RITORNATI

   -- Da -1 .. a -6 fare riferimento alla funzione validapart() dal package ABACO_CONS_PCK.
-- -7  Errore nei parametri in input alla funzione.
-- -9  Non e stato inserito il codice nazionale.
-- -10 Errore oracle.
-- 1   Funzione eseguita correttamente.
   FUNCTION scade_catasto (
      cod_naz_par   IN   VARCHAR2,
      foglio_par    IN   VARCHAR2,
      part_par      IN   VARCHAR2,
      suba_par      IN   VARCHAR2,
      utente_par    IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      ID       NUMBER (9);
      part     sitiparticella;
      esito    NUMBER;
      esiste   BOOLEAN        := TRUE;

      CURSOR c1
      IS
         SELECT 1
           FROM sititrkc
          WHERE cod_nazionale = cod_naz_par
            AND foglio = foglio_par
            AND particella = part_par
            AND sub = suba_par
            AND valida = 1;
   BEGIN
      IF cod_naz_par IS NULL
      THEN
         DBMS_OUTPUT.put_line ('Non e stato inserito il codice nazionale.');
         RETURN -9;
      END IF;

      part.cod_nazionale := cod_naz_par;
      part.foglio := LPAD (foglio_par, 4, '0');
      part.particella := part_par;
      part.subalterno := suba_par;
      esito := validapart (part);

      IF esito <> 1
      THEN
         RETURN esito;
      END IF;

      IF utente_par IS NULL
      THEN
         DBMS_OUTPUT.put_line
                  ('Almeno uno dei parametri in input alla funzione e nullo.');
         RETURN -7;
      END IF;

      OPEN c1;

      FETCH c1
       INTO ID;

      IF c1%NOTFOUND
      THEN
         esiste := FALSE;
      END IF;

      CLOSE c1;

      IF esiste
      THEN
         UPDATE sititrkc
            SET valida = '0',
                utente = utente_par,
                data_modifica = SYSDATE
          WHERE cod_nazionale = part.cod_nazionale
            AND foglio = part.foglio
            AND particella = part.particella
            AND sub = part.subalterno;
      END IF;

      RETURN 1;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line ('ERRORE: ' || SQLERRM);
         RETURN -10;
   END scade_catasto;

   --****************************************************************************
--****************************************************************************
--****************************************************************************
   FUNCTION validapart (particella IN OUT sitiparticella)
      RETURN NUMBER
   IS
      ----- COMMENTO ALLA FUNZIONE -----
      -- Funzione che data una particella (ISTATP, ISTATC, SEZIONE, FOGLIO, PARTICELLA, SUBALTERNO) individua il codice nazionale e dice se e valida oppure no.

      -- PARAMETRI IN INPUT:
      --    un oggetto particella (ISTATP, ISTATC, SEZIONE, COD_NAZIONALE, FOGLIO, PARTICELLA, SUBALTERNO)
      --    il codice nazionale viene modificato all'interno della funzione.

      -- VALORI RITORNATI:
      --    -1 in caso di errore oracle .
      --    -2 se all'istatp - istatc corrispondono piu codici nazionali.
      --       E' il caso in cui esistono piu sezioni, quindi bisogna specificarla
      --       nel campo SEZIONE dell'oggetto SITIPARTICELLA.
      --    -3 comune (istatp, istatc, sezione) non trovato in siticomu.
      --    -4 se mancano l'istatp o l'istatc.
      --    -5 se il foglio non e di 4 cifre.
      --    -6 se la particella non e di 5 caratteri.
      --    1 se e tutto ok.
      stmt   VARCHAR2 (2048);
      --RS VARCHAR2(16);
      rs     siticomu.cod_nazionale%TYPE;
   BEGIN
      IF LENGTH (particella.foglio) != 4 OR particella.foglio IS NULL
      THEN
         DBMS_OUTPUT.put_line ('LUNGHEZZA FOGLIO ERRATA: RICHIESTO 4');
         RETURN -5;
      END IF;

      IF LENGTH (particella.particella) != 5 OR particella.particella IS NULL
      THEN
         DBMS_OUTPUT.put_line ('LUNGHEZZA PARTICELLA ERRATA: RICHIESTO 5');
         RETURN -6;
      END IF;

      IF particella.subalterno IS NULL OR TRIM (particella.subalterno) = ''
      THEN
         particella.subalterno := ' ';
      END IF;

      --corrado: ho rimesso il controllo sul cod_nazionale
      IF     particella.cod_nazionale IS NOT NULL
         AND particella.istatp IS NULL
         AND particella.istatc IS NULL
      THEN
         IF LENGTH (particella.cod_nazionale) = 4
         THEN
            stmt :=
                  'SELECT COD_NAZIONALE FROM sitiCOMU WHERE COD_NAZIONALE='''
               || particella.cod_nazionale
               || '''';
         ELSE
            DBMS_OUTPUT.put_line ('COMUNE NON TROVATO');
            RETURN -3;
         END IF;
      ELSIF     particella.istatp IS NOT NULL
            AND particella.istatc IS NOT NULL
            AND particella.cod_nazionale IS NULL
      THEN
         stmt :=
               'SELECT COD_NAZIONALE FROM sitiCOMU WHERE ISTATP='''
            || particella.istatp
            || ''' AND ISTATC='''
            || particella.istatc
            || '''';

         IF particella.sezione IS NOT NULL
         THEN
            stmt := stmt || ' AND ID_SEZC=''' || particella.sezione || '''';
         ELSE
            stmt := stmt || ' AND ID_SEZC IS NULL';
         END IF;
      ELSE
         DBMS_OUTPUT.put_line ('ERRORE: ISTAT PROVINCIA E COMUNE RICHIESTI');
         RETURN -4;
      END IF;

      BEGIN
         EXECUTE IMMEDIATE stmt
                      INTO rs;
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            DBMS_OUTPUT.put_line (  'COMUNE NON TROVATO: "'
                                  + particella.istatp
                                  + '" - "'
                                  + particella.istatc
                                  + '" - "'
                                  + particella.sezione
                                  + '"'
                                 );
            RETURN -3;
      END;

      particella.cod_nazionale := rs;
      RETURN 1;
   END validapart;

   PROCEDURE insert_azienda (
      soggcuaa     IN   VARCHAR2,
      datainizio   IN   DATE,
      datafine     IN   DATE,
      USER         IN   VARCHAR2
   )
   IS
      CURSOR c1
      IS
         SELECT COUNT (*)
           FROM cons_azie_tab
          WHERE cuaa = soggcuaa;

      CURSOR c2
      IS
         SELECT cons_azie_seq.NEXTVAL
           FROM DUAL;

      conteggio    NUMBER;
      nextpkcuaa   NUMBER;
   BEGIN
      OPEN c1;

      FETCH c1
       INTO conteggio;

      IF c1%NOTFOUND
      THEN
         conteggio := 0;
      END IF;

      CLOSE c1;

      IF conteggio = 0
      THEN
         OPEN c2;

         FETCH c2
          INTO nextpkcuaa;

         IF c2%NOTFOUND
         THEN
            nextpkcuaa := 0;
         END IF;

         CLOSE c2;

         IF nextpkcuaa > 0
         THEN
            INSERT INTO cons_azie_tab
                        (pk_cuaa, cuaa, data_inizio, data_fine,
                         data_registrazione, utente, TIMESTAMP, cod_stato,
                         data_inizio_stato
                        )
                 VALUES (nextpkcuaa, soggcuaa, datainizio, datafine,
                         SYSDATE, USER, SYSDATE, '0',
                         SYSDATE
                        );
         ELSE
            raise_application_error
                     (-20002,
                      'Impossibile recuperare il nuovo PK_CUAA dal sequence.'
                     );
         END IF;
      ELSE
         raise_application_error (-20001,
                                  'CUAA gia presente nella base dati.'
                                 );
      END IF;
   END insert_azienda;

   --****************************************************************************
--****************************************************************************
--****************************************************************************
   FUNCTION aggiornacons (
      part                       IN OUT   sitiparticella,
      sup_cata_vali              IN       NUMBER,
      n_aziende                  IN       NUMBER,
      cuaa                       IN       varchar_array,
      sup_cond                   IN       number_array,
      tipo_cond                  IN       number_array,
      atto                       IN       number_array,
      percentuali_su_catastale   IN       NUMBER,
      indata                              DATE,
      poss_or_affi               IN       VARCHAR2,
      decimali                   IN       INTEGER
   )
      RETURN NUMBER
   IS
      ----- COMMENTO ALLA FUNZIONE -----

      -- Procedura di aggiornamento consistenza da modifica domanda

      -- PARAMETRI IN INPUT

      -- PART, oggetto SITIPARTICELLA con codici istatp, istatc, sezione, foglio, particella, subalterno.
      -- SUP_CATA_VALI, supertficie totale da considerare per i superi.
      -- N_AZIENDE, numero di aziende che conducono la particella.
      -- CUAA, vettore di codici passati da chiamante che ci si aspetta sia validato per fascicolo.
      -- SUP_COND, vettore di superfici in mq e ricavate da domanda.
      -- TIPO_COND, vettore di titoli 1, 2, 3, 4 (1=proprieta, > 2 = affitto).
      -- ATTO, vettore che contiene l'ID dell'atto che si vuole associare. Puo essere nullo.
      -- ut: utente corrente.
      -- percentuali_su_catastale: se 1 allora le percentuali vengono calcolate su sup_cata_vali altrimenti (se 0) vengono calcolate sul totale del dichiarato

      -- CONTROLLI SUI DATI IN INPUT

      -- SUP_CATA_VALI deve essere > 0
      -- N_AZIENDE deve essere > 0
      -- Se un titolo (TIPO_COND) supera i casi previsti ritorna errore.

      -- VALORI RITORNATI

      -- 0, nussun errore e nessuna anomalia.
      -- 1, generato supero di conduzione in consistenza - Errore non bloccante.
      -- 9, SUP_CATA_VALI <= 0 o N_AZIENDE <= 0  - Errore bloccante nei parametri.
      -- 8, particella non correttamente codificata - Errore bloccante.
      -- 7, errori di connessione al database - Errore bloccante.
      p_cuaa             varchar_array;
      p_perccondu        integer_array;
      sup_tot_condotta   NUMBER;
      spalma_sup         NUMBER;
      p_perc_prog        NUMBER;
      sup_aff_prog       NUMBER;
      sup_prop_prog      NUMBER;
      ret                NUMBER;
      retvalipart        NUMBER;
      pkatto             NUMBER        := NULL;
      errore             NUMBER;
      j                  INTEGER       := 1;
      fattore            INTEGER       := 0;
   BEGIN
      -- INIZIALIZZAZIONE VARIABILI
      p_cuaa := varchar_array ();
      p_perccondu := integer_array ();
      sup_tot_condotta := 0;
      spalma_sup := 0;
      p_perc_prog := 0;
      sup_aff_prog := 0;
      sup_prop_prog := 0;
      pkatto := NULL;
      errore := 0;

      IF decimali IS NULL
      THEN
         fattore := 1;
      ELSE
         fattore := POWER (10, decimali);
      END IF;

      -- FINE INIZIALIZZAZIONE
      IF     n_aziende > 0
         AND (   percentuali_su_catastale = 0
              OR (percentuali_su_catastale = 1 AND sup_cata_vali > 0)
             )
      THEN
         retvalipart := validapart (part);

         IF retvalipart = 1
         THEN
            ret := fineval_ter (part, indata, poss_or_affi);

            IF ret = 1
            THEN
               FOR i IN cuaa.FIRST .. n_aziende
               LOOP
                  ret := validacuaa (cuaa (i));
                  p_cuaa.EXTEND;
                  p_cuaa (i) := ret;
                  sup_tot_condotta := sup_tot_condotta + sup_cond (i);
               END LOOP;

               IF errore != 7
               THEN
------------------warning --- se dentro la tolleranza la percentuale potrebbe essere 0 e quindi non registrata? caso: 61500+61500+100 per 123000 supe cata vali quando gia presenti in due al 50 percento
                  IF    sup_tot_condotta <= sup_cata_vali * 1.02
                     OR percentuali_su_catastale = 0
                  THEN
                     FOR i IN sup_cond.FIRST .. n_aziende
                     LOOP
                        p_perccondu.EXTEND;

                        IF percentuali_su_catastale = 1
                        THEN
                           p_perccondu (i) :=
                                ((sup_cond (i) / sup_cata_vali) * 10000
                                )
                              * fattore
                              / 100;
                        ELSE
                           p_perccondu (i) :=
                                ((sup_cond (i) / sup_tot_condotta) * 10000
                                )
                              * fattore
                              / 100;
                        END IF;

                        IF i = n_aziende
                        THEN
                           --IF     percentuali_su_catastale = 1 AND sup_tot_condotta <> sup_cata_vali
                           IF     percentuali_su_catastale = 1
                              AND ABS (sup_tot_condotta - sup_cata_vali) >
                                                          sup_cata_vali * 0.01
                           THEN
                              p_perccondu (i) := p_perccondu (i);
                           ELSIF     sup_cond (i) = 0
                                 AND p_perc_prog != 100 * fattore
                           THEN
                              WHILE j <= n_aziende
                              LOOP
                                 IF p_perccondu (j) > 0
                                 THEN
                                    p_perccondu (j) :=
                                         p_perccondu (j)
                                       + (100 * fattore - p_perc_prog);
                                    j := n_aziende + 1;
                                 END IF;
                              END LOOP;
                           ELSE
                              p_perccondu (i) := 100 * fattore - p_perc_prog;
                           END IF;
                        END IF;

                        p_perc_prog := p_perc_prog + p_perccondu (i);

                        IF tipo_cond (i) > 1
                        THEN
                           sup_aff_prog := sup_aff_prog + sup_cond (i);
                        ELSE
                           sup_prop_prog := sup_prop_prog + sup_cond (i);
                        END IF;
                     END LOOP;

                     IF sup_aff_prog > 0
                     THEN
                        IF sup_prop_prog > 0
                        THEN
                           FOR i IN 1 .. n_aziende
                           LOOP
                              IF atto IS NOT NULL
                              THEN
                                 pkatto := atto (i);
                              END IF;

                              ret :=
                                 inizioval_ter (p_cuaa (i),
                                                part,
                                                p_perccondu (i) / fattore,
                                                5 + tipo_cond (i),
                                                pkatto,
                                                0,
                                                indata
                                               );
                           END LOOP;

                           ret :=
                              inizioval_ter ('999999999',
                                             part,
                                             0,
                                             1,
                                             '',
                                             0,
                                             indata
                                            );
                        ELSE
                           FOR i IN 1 .. n_aziende
                           LOOP
                              IF atto IS NOT NULL
                              THEN
                                 pkatto := atto (i);
                              END IF;

                              ret :=
                                 inizioval_ter (p_cuaa (i),
                                                part,
                                                p_perccondu (i) / fattore,
                                                tipo_cond (i),
                                                pkatto,
                                                0,
                                                indata
                                               );
                           END LOOP;

                           ret :=
                              inizioval_ter ('999999999',
                                             part,
                                             0,
                                             1,
                                             '',
                                             0,
                                             indata
                                            );
                        END IF;
                     ELSE
                        FOR i IN 1 .. n_aziende
                        LOOP
                           IF atto IS NOT NULL
                           THEN
                              pkatto := atto (i);
                           END IF;

                           ret :=
                              inizioval_ter (p_cuaa (i),
                                             part,
                                             p_perccondu (i) / fattore,
                                             tipo_cond (i),
                                             pkatto,
                                             0,
                                             indata
                                            );
                        END LOOP;
                     END IF;
                  ELSE
                     FOR i IN 1 .. n_aziende
                     LOOP
                        IF atto IS NOT NULL
                        THEN
                           pkatto := atto (i);
                        END IF;

                        ret :=
                           inizioval_ter (p_cuaa (i),
                                          part,
                                          0,
                                          tipo_cond (i),
                                          pkatto,
                                          sup_cond (i),
                                          indata
                                         );
                     END LOOP;

                     errore := 1;
                  END IF;
               END IF;
            ELSE
               errore := 7;
            END IF;
         ELSE
            IF retvalipart = -1
            THEN
               errore := 7;
            ELSE
               errore := 8;
            END IF;
         END IF;
      ELSE
         errore := 9;
      END IF;

--      COMMIT;
      RETURN errore;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (SUBSTR (   'Errore Oracle aggiornaCons :'
                                       || TO_CHAR (SQLCODE)
                                       || ': '
                                       || SQLERRM,
                                       1,
                                       255
                                      )
                              );
--         ROLLBACK;
         RETURN -1;
   END;

   FUNCTION aggiornacons_uiu (
      part                       IN OUT   sitiparticella,
      sup_cata_vali              IN       NUMBER,
      n_aziende                  IN       NUMBER,
      cuaa                       IN       varchar_array,
      sup_cond                   IN       number_array,
