--****************************************************************************
--****************************************************************************
--****************************************************************************
   FUNCTION fineval_ter (
      part           IN OUT   sitiparticella,
      indata                  DATE,
      poss_or_affi   IN       VARCHAR2
   )
      RETURN NUMBER
   IS
      ----- COMMENTO ALLA FUNZIONE -----
      -- Funzione che data una particella pone a fine validita tutte le conduzioni sulla particella
      -- (conservatoria e registro) ed elimina tutti gli eventuali superi sulla particella.

      -- PARAMETRI IN INPUT:
      --  PART, un oggetto particella.

      -- VALORI RITORNATI:
      --   1 se va tutto bene.
      --   -1 in caso di errore oracle.

      --PK_SUPA NUMBER;
      ut        VARCHAR2 (50);
      pk_supa   cons_supa_tab.pkid_supa%TYPE;
      step      NUMBER;
      DATA      DATE;
   BEGIN
      step := 10;
      ut := nome_utente;
      DATA := indata - 1 / (24 * 3600);

      IF poss_or_affi IS NULL OR poss_or_affi = 'P'
      THEN
         DELETE FROM cons_cons_tab
               WHERE cod_nazionale = part.cod_nazionale
                 AND foglio = part.foglio
                 AND particella = part.particella
                 AND sub = part.subalterno
                 AND data_fine = DATA;

         UPDATE cons_cons_tab
            SET utente = ut,
                TIMESTAMP = SYSDATE,
                data_fine = DATA
          WHERE cod_nazionale = part.cod_nazionale
            AND foglio = part.foglio
            AND particella = part.particella
            AND sub = part.subalterno
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      END IF;

      COMMIT;
      step := 20;

      IF poss_or_affi IS NULL OR poss_or_affi = 'A'
      THEN
         DELETE FROM cons_ufre_tab
               WHERE cod_nazionale = part.cod_nazionale
                 AND foglio = part.foglio
                 AND particella = part.particella
                 AND sub = part.subalterno
                 AND data_fine = DATA;

         UPDATE cons_ufre_tab
            SET utente = ut,
                TIMESTAMP = SYSDATE,
                data_fine = DATA
          WHERE cod_nazionale = part.cod_nazionale
            AND foglio = part.foglio
            AND particella = part.particella
            AND sub = part.subalterno
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      END IF;

      step := 30;

      DELETE FROM cons_suaz_tab
            WHERE pkid_supa IN (
                     SELECT pkid_supa
                       FROM cons_supa_tab
                      WHERE cod_nazionale = part.cod_nazionale
                        AND foglio = part.foglio
                        AND particella = part.particella
                        AND sub = part.subalterno
                        AND data_fine = DATA);

      UPDATE cons_suaz_tab
         SET utente = ut,
             TIMESTAMP = SYSDATE,
             data_fine = indata
       WHERE pkid_supa IN (
                SELECT pkid_supa
                  FROM cons_supa_tab
                 WHERE cod_nazionale = part.cod_nazionale
                   AND foglio = part.foglio
                   AND particella = part.particella
                   AND sub = part.subalterno
                   AND data_fine = TO_DATE ('99991231', 'YYYYMMDD'));

      step := 40;

      DELETE FROM cons_supa_tab
            WHERE cod_nazionale = part.cod_nazionale
              AND foglio = part.foglio
              AND particella = part.particella
              AND sub = part.subalterno
              AND data_fine = DATA;

      UPDATE cons_supa_tab
         SET utente = ut,
             TIMESTAMP = SYSDATE,
             data_fine = indata
       WHERE cod_nazionale = part.cod_nazionale
         AND foglio = part.foglio
         AND particella = part.particella
         AND sub = part.subalterno
         AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

      RETURN 1;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (   'Fineval_ter: Errore '
                               || SQLERRM
                               || ' su step '
                               || step
                              );
         RETURN -1;
   END fineval_ter;

   FUNCTION fineval_uiu (
      part           IN OUT   sitiparticella,
      indata                  DATE,
      poss_or_affi   IN       VARCHAR2
   )
      RETURN NUMBER
   IS
      ----- COMMENTO ALLA FUNZIONE -----
      -- Funzione che data una particella pone a fine validita tutte le conduzioni sulla particella
      -- (conservatoria e registro) ed elimina tutti gli eventuali superi sulla particella.

      -- PARAMETRI IN INPUT:
      --  PART, un oggetto particella.

      -- VALORI RITORNATI:
      --   1 se va tutto bene.
      --   -1 in caso di errore oracle.

      --PK_SUPA NUMBER;
      ut        VARCHAR2 (50);
      pk_supa   cons_susu_tab.pkid_suui%TYPE;
      step      NUMBER;
      DATA      DATE;
   BEGIN
      step := 10;
      ut := nome_utente;
      DATA := indata - 1 / (24 * 3600);

      IF poss_or_affi IS NULL OR poss_or_affi = 'P'
      THEN
         DELETE FROM cons_csui_tab
               WHERE cod_nazionale = part.cod_nazionale
                 AND foglio = part.foglio
                 AND particella = part.particella
                 AND sub = part.subalterno
                 AND unimm = part.unimm
                 AND data_fine = DATA;

         UPDATE cons_csui_tab
            SET utente = ut,
                TIMESTAMP = SYSDATE,
                data_fine = DATA
          WHERE cod_nazionale = part.cod_nazionale
            AND foglio = part.foglio
            AND particella = part.particella
            AND sub = part.subalterno
            AND unimm = part.unimm
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      END IF;

      step := 20;

      IF poss_or_affi IS NULL OR poss_or_affi = 'A'
      THEN
         DELETE FROM cons_urui_tab
               WHERE cod_nazionale = part.cod_nazionale
                 AND foglio = part.foglio
                 AND particella = part.particella
                 AND sub = part.subalterno
                 AND unimm = part.unimm
                 AND data_fine = DATA;

         UPDATE cons_urui_tab
            SET utente = ut,
                TIMESTAMP = SYSDATE,
                data_fine = DATA
          WHERE cod_nazionale = part.cod_nazionale
            AND foglio = part.foglio
            AND particella = part.particella
            AND sub = part.subalterno
            AND unimm = part.unimm
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      END IF;

      step := 30;

      UPDATE cons_susu_tab
         SET utente = ut,
             TIMESTAMP = SYSDATE,
             data_fine = indata
       WHERE pkid_suui IN (
                SELECT pkid_suui
                  FROM cons_suui_tab
                 WHERE cod_nazionale = part.cod_nazionale
                   AND foglio = part.foglio
                   AND particella = part.particella
                   AND sub = part.subalterno
                   AND unimm = part.unimm
                   AND data_fine = TO_DATE ('99991231', 'YYYYMMDD'));

      step := 40;

      UPDATE cons_suui_tab
         SET utente = ut,
             TIMESTAMP = SYSDATE,
             data_fine = indata
       WHERE cod_nazionale = part.cod_nazionale
         AND foglio = part.foglio
         AND particella = part.particella
         AND sub = part.subalterno
         AND unimm = part.unimm
         AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

      RETURN 1;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (   'Fineval_uiu: Errore '
                               || SQLERRM
                               || ' su step '
                               || step
                              );
         RETURN -1;
   END fineval_uiu;

--****************************************************************************
--****************************************************************************
--****************************************************************************
   FUNCTION validacuaa (cuaa IN VARCHAR2)
      RETURN NUMBER
   IS
      ----- COMMENTO ALLA FUNZIONE -----
      -- Funzione che dato il cuaa di un'azienda controlla la sua esistenza nella tabella delle aziende.
      -- Se il cuaa esiste e non e scaduto ritorna il pkcuaa associato.
      -- Se il cuaa esiste ma e scaduto, lo aggiorna (data_fine, timestamp, utente) e ritorna il pkcuaa associato.
      -- Se il cuaa non esiste lo inserisce e ritorna il pkcuaa associato.

      -- PARAMETRI IN INPUT:
      --    cuaa dell'azienda.

      -- VALORI RITORNATI:
      --   ritorna il pkcuaa dell'azienda.

      -- Le commit devono essere gestite all'esterno della funzione.
      stmt        VARCHAR2 (2048);
      retvalue    NUMBER;
      pkcuaa      cons_azie_tab.pk_cuaa%TYPE;
      data_fine   cons_azie_tab.data_fine%TYPE;
      ut          VARCHAR2 (50);
   BEGIN
      retvalue := 0;
      ut := nome_utente;
      stmt :=
            'SELECT PK_CUAA, DATA_FINE FROM cons_azie_tab WHERE CUAA='''
         || cuaa
         || '''';

      BEGIN
         EXECUTE IMMEDIATE stmt
                      INTO pkcuaa, data_fine;
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            pkcuaa := NULL;
      END;

      IF pkcuaa IS NULL
      THEN
--         DBMS_OUTPUT.put_line ('inserimento in cons_azie_tab di:' || cuaa);
         stmt := 'SELECT cons_AZIE_SEQ.NEXTVAL FROM DUAL';

         EXECUTE IMMEDIATE stmt
                      INTO pkcuaa;

         INSERT INTO cons_azie_tab
                     (pk_cuaa, cuaa, data_inizio,
                      data_fine, data_registrazione, utente,
                      TIMESTAMP, cod_stato, data_inizio_stato
                     )
              VALUES (pkcuaa, cuaa, SYSDATE,
                      TO_DATE ('99991231', 'YYYYMMDD'), SYSDATE, ut,
                      SYSDATE, '0', SYSDATE
                     );
      ELSE
         IF (data_fine < SYSDATE)
         THEN
            UPDATE cons_azie_tab
               SET data_fine = TO_DATE ('99991231', 'YYYYMMDD'),
                   TIMESTAMP = SYSDATE,
                   utente = ut
             WHERE pk_cuaa = pkcuaa;
         END IF;
      END IF;

      retvalue := pkcuaa;
      RETURN retvalue;
   END validacuaa;

--****************************************************************************
--****************************************************************************
--****************************************************************************
   FUNCTION inizioval_ter (
      pkcuaa            IN   VARCHAR2,
      part              IN   sitiparticella,
      perc_cond         IN   NUMBER,
      titolo_possesso   IN   NUMBER,
      atto              IN   NUMBER,
      sup_cond          IN   NUMBER,
      indata                 DATE
   )
      RETURN NUMBER
   IS
      ----- COMMENTO ALLA FUNZIONE -----
      -- Funzione inserisce una registrazione in conservatoria o registro ed eventualmente inserisce il supero
      -- nel caso in cui la % di conduzione = 0 mentre la superficie condotta e > 0.

      -- PARAMETRI IN INPUT
      --   PKCUAA, il pkcuaa dell'azienda.
      --   PART, un oggetto particella.
      --   PERC_COND, la percentuale di conduzione dell'azienda sulla particella.
      --   TIPO_POSSESSO, 1=proprieta, 2=affitto.
      --   ATTO, l'id dell'atto.
      --   SUP_COND, superficie condotta.

      -- VALORI RITORNATI:
      --   1 se e andato tutto bene.
      ut         VARCHAR2 (50);
      ufre_seq   NUMBER        := 0;
      cons_seq   NUMBER        := 0;
      suaz_seq   NUMBER        := 0;
      supa_seq   NUMBER        := 0;
      step       NUMBER;
   BEGIN
      step := 10;
      ut := nome_utente;

      IF pkcuaa = '999999999'
      THEN
         DELETE FROM cons_cons_tab
               WHERE pk_cuaa = 999999999
                 AND cod_nazionale = part.cod_nazionale
                 AND foglio = part.foglio
                 AND particella = part.particella
                 AND sub = part.subalterno;
      END IF;

      IF perc_cond = 0 AND sup_cond = 0 AND pkcuaa != '999999999'
      THEN
         step := 20;
         RETURN 1;
      ELSE
         step := 30;

         IF titolo_possesso > 1
         THEN
            step := 40;

            SELECT cons_ufre_seq.NEXTVAL
              INTO ufre_seq
              FROM DUAL;

            step := 50;

            INSERT INTO cons_ufre_tab
                        (pkid_uffr, cod_nazionale, foglio, allegato,
                         sviluppo, particella, sub, perc_poss,
                         tipo_titolo, data_registrazione, utente, TIMESTAMP,
                         pk_cuaa, data_inizio, data_fine,
                         atto_ini
                        )
                 VALUES (ufre_seq, part.cod_nazionale, part.foglio, '0',
                         '0', part.particella, part.subalterno, perc_cond,
                         titolo_possesso, SYSDATE, ut, SYSDATE,
                         pkcuaa, indata, TO_DATE ('99991231', 'YYYYMMDD'),
                         atto
                        );
         ELSE
            step := 60;

            SELECT cons_cons_seq.NEXTVAL
              INTO cons_seq
              FROM DUAL;

            step := 70;

            INSERT INTO cons_cons_tab
                        (pkid_cons, cod_nazionale, foglio, allegato,
                         sviluppo, particella, sub, perc_poss,
                         tipo_titolo, data_registrazione, utente, TIMESTAMP,
                         pk_cuaa, data_inizio, data_fine,
                         atto_ini
                        )
                 VALUES (cons_seq, part.cod_nazionale, part.foglio, '0',
                         '0', part.particella, part.subalterno, perc_cond,
                         titolo_possesso, SYSDATE, ut, SYSDATE,
                         pkcuaa, indata, TO_DATE ('99991231', 'YYYYMMDD'),
                         atto
                        );
         END IF;

         IF perc_cond = 0 AND pkcuaa != '999999999'
         THEN
            step := 80;

            BEGIN
               SELECT pkid_supa
                 INTO supa_seq
                 FROM cons_supa_tab
                WHERE cod_nazionale = part.cod_nazionale
                  AND foglio = part.foglio
                  AND particella = part.particella
                  AND sub = part.subalterno
                  AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
            EXCEPTION
               WHEN NO_DATA_FOUND
               THEN
                  supa_seq := 0;
            END;

            IF supa_seq = 0
            THEN
               step := 90;

               SELECT cons_supa_seq.NEXTVAL
                 INTO supa_seq
                 FROM DUAL;

               step := 100;

               INSERT INTO cons_supa_tab
                           (pkid_supa, cod_nazionale, foglio, allegato,
                            sviluppo, particella, sub, utente,
                            TIMESTAMP, data_inizio, data_fine
                           )
                    VALUES (supa_seq, part.cod_nazionale, part.foglio, '0',
                            '0', part.particella, part.subalterno, ut,
                            SYSDATE, indata, TO_DATE ('99991231', 'YYYYMMDD')
                           );
            END IF;

            step := 110;

            SELECT cons_suaz_seq.NEXTVAL
              INTO suaz_seq
              FROM DUAL;

            IF titolo_possesso > 1
            THEN
               step := 120;

               INSERT INTO cons_suaz_tab
                           (pkid_suaz, pkid_supa, pk_cuaa, pkid_atto,
                            perc_poss, perc_affi, supe_poss, supe_affi,
                            TIMESTAMP, data_inizio,
                            data_fine, utente
                           )
                    VALUES (suaz_seq, supa_seq, pkcuaa, atto,
                            0, perc_cond, 0, sup_cond,
                            SYSDATE, indata,
                            TO_DATE ('99991231', 'YYYYMMDD'), ut
                           );
            ELSE
               step := 130;

               INSERT INTO cons_suaz_tab
                           (pkid_suaz, pkid_supa, pk_cuaa, pkid_atto,
                            perc_poss, perc_affi, supe_poss, supe_affi,
                            TIMESTAMP, data_inizio,
                            data_fine, utente
                           )
                    VALUES (suaz_seq, supa_seq, pkcuaa, atto,
                            perc_cond, 0, sup_cond, 0,
                            SYSDATE, indata,
                            TO_DATE ('99991231', 'YYYYMMDD'), ut
                           );
            END IF;
         END IF;
      END IF;

      RETURN 1;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line (   'Inizioval: Errore '
                               || SQLERRM
                               || ' su step '
                               || step
                              );
   END inizioval_ter;

   FUNCTION inizioval_uiu (
