            INSERT INTO cons_csui_tab
                        (pkid_csui, cod_nazionale, foglio, allegato,
                         sviluppo, particella, sub, unimm,
                         perc_poss, tipo_titolo, data_registrazione, utente,
                         TIMESTAMP, pk_cuaa, data_inizio,
                         data_fine, atto_ini
                        )
                 VALUES (cons_seq, part.cod_nazionale, part.foglio, '0',
                         '0', part.particella, part.subalterno, part.unimm,
                         perc_cond, titolo_possesso, SYSDATE, ut,
                         SYSDATE, pkcuaa, indata,
                         TO_DATE ('99991231', 'YYYYMMDD'), atto
                        );
         END IF;

         IF perc_cond = 0 AND pkcuaa != '999999999'
         THEN
            step := 80;

            BEGIN
               SELECT pkid_suui
