                 FROM DUAL;

               step := 100;

               INSERT INTO cons_suui_tab
                           (pkid_suui, cod_nazionale, foglio, allegato,
                            sviluppo, particella, sub,
                            unimm, utente, TIMESTAMP, data_inizio,
                            data_fine
                           )
                    VALUES (supa_seq, part.cod_nazionale, part.foglio, '0',
                            '0', part.particella, part.subalterno,
                            part.unimm, ut, SYSDATE, indata,
                            TO_DATE ('99991231', 'YYYYMMDD')
                           );
            END IF;

            step := 110;

            SELECT cons_susu_seq.NEXTVAL
              INTO suaz_seq
              FROM DUAL;

            IF titolo_possesso > 1
            THEN
               step := 120;

               INSERT INTO cons_susu_tab
                           (pkid_susu, pkid_suui, pk_cuaa, pkid_atto,
                            perc_poss, perc_affi, supe_poss, supe_affi,
                            TIMESTAMP, data_inizio,
