                           )
                    VALUES (suaz_seq, supa_seq, pkcuaa, atto,
                            0, perc_cond, 0, sup_cond,
                            SYSDATE, indata,
                            TO_DATE ('99991231', 'YYYYMMDD'), ut
                           );
            ELSE
               step := 130;

               INSERT INTO cons_susu_tab
                           (pkid_susu, pkid_suui, pk_cuaa, pkid_atto,
                            perc_poss, perc_affi, supe_poss, supe_affi,
                            TIMESTAMP, data_inizio,
                            data_fine, utente
                           )
                    VALUES (suaz_seq, supa_seq, pkcuaa, atto,
