         DBMS_OUTPUT.put_line (   'Inizioval_uiu: Errore '
                               || SQLERRM
                               || ' su step '
                               || step
                              );
   END inizioval_uiu;

/*
Ritorna la somma dei millesimi delle uiu che insistono su una particella
Parametri:
      incodnaz       IN   VARCHAR2,     codice nazionale
      infoglio       IN   NUMBER,       foglio
      inparticella   IN   VARCHAR2,     particella
      insub          IN   VARCHAR2,     subalterno
      indatarif      IN   DATE          data di riferimento null=situazione attuale

*/
   FUNCTION get_particelle_from_cuaa (incuaa IN VARCHAR2)
      RETURN NUMBER
   IS
      ritorno   NUMBER (9);
   BEGIN
      SELECT COUNT (*)
        INTO ritorno
        FROM (SELECT a.cod_nazionale, a.foglio, a.particella, a.sub
                FROM cons_cons_tab a, cons_azie_tab b
               WHERE a.pk_cuaa = b.pk_cuaa
                 AND b.cuaa = incuaa
                 AND a.data_fine = TO_DATE ('99991231', 'YYYYMMDD')
              UNION
              SELECT a.cod_nazionale, a.foglio, a.particella, a.sub
                FROM cons_ufre_tab a, cons_azie_tab b
               WHERE a.pk_cuaa = b.pk_cuaa
                 AND b.cuaa = incuaa
                 AND a.data_fine = TO_DATE ('99991231', 'YYYYMMDD'));

      IF ritorno IS NULL
      THEN
         ritorno := 0;
      END IF;

      RETURN ritorno;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RETURN 0;
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

   FUNCTION get_millesimi_particella (
      incodnaz       IN   VARCHAR2,
      infoglio       IN   NUMBER,
      inparticella   IN   VARCHAR2,
      insub          IN   VARCHAR2,
      indatarif      IN   DATE
   )
      RETURN NUMBER
   IS
      millesimi   NUMBER (9)     := 0;
      datarif     DATE;
      sql_stmt    VARCHAR2 (500);
   BEGIN
      IF indatarif IS NULL
      THEN
         datarif := TO_DATE ('99991231', 'YYYYMMDD');
      ELSE
         datarif := indatarif;
      END IF;

      sql_stmt :=
         'SELECT SUM (millesimi_terreno)
         FROM sitiuiu
         WHERE cod_nazionale = :1
         AND foglio = :2
         AND particella = :3
         AND sub = :4
         AND data_inizio_val <= :5
         AND data_fine_val >= :6';

      EXECUTE IMMEDIATE sql_stmt
                   INTO millesimi
                  USING incodnaz,
                        infoglio,
                        inparticella,
                        insub,
                        datarif,
                        datarif;

      IF millesimi IS NULL
      THEN
         millesimi := 0;
      END IF;

      RETURN millesimi;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RETURN 0;
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line
                             (SUBSTR (   'Errore get_millesimi_particella :'
                                      || TO_CHAR (SQLCODE)
                                      || ': '
                                      || SQLERRM,
                                      1,
                                      255
                                     )
                             );
         RETURN -1;
   END;

   PROCEDURE aggiorna_terreni_from_uiu (
      incodnaz       IN       VARCHAR2,
      infoglio       IN       NUMBER,
      inparticella   IN       VARCHAR2,
      insub          IN       VARCHAR2,
      indatarif      IN       DATE,
      inutente       IN       VARCHAR2,
      prop_or_affi   IN       VARCHAR2,
      outritorno     OUT      NUMBER
   )
   IS
      millesimi_particella   NUMBER         := 0;
      particella             sitiparticella;
      dataultima             DATE;
      datarif                DATE;
   BEGIN
      outritorno := 0;
      millesimi_particella :=
         get_millesimi_particella (incodnaz,
                                   infoglio,
                                   inparticella,
                                   insub,
                                   NULL
                                  );

      IF millesimi_particella > 0
      THEN
         --la particella ha millesimi sulle uiu
         particella.cod_nazionale := incodnaz;
         particella.foglio := infoglio;
         particella.particella := inparticella;
         particella.subalterno := insub;
         --IF fineval_ter (particella, indatarif, prop_or_affi) = 1
         --THEn
         dataultima :=
            data_ultima_modifica (incodnaz,
                                  infoglio,
                                  inparticella,
                                  insub,
                                  NULL,
                                  'T',
                                  prop_or_affi
                                 );

         IF dataultima IS NULL OR dataultima < indatarif
         THEN
            datarif := indatarif;
         ELSE
            datarif := dataultima + 1 / (24 * 3600);
         END IF;

         allineacons_from_uiu (incodnaz,
                               infoglio,
                               inparticella,
                               insub,
                               inutente,
                               datarif,
                               prop_or_affi,
                               outritorno
                              );
      --END IF;
      ELSE
         --la particella non ha millesimi sulle uiu
         --non viene effettuata nessuna modifica
         outritorno := 0;
      END IF;
   END;

   FUNCTION data_ultima_modifica (
      incodnaz       IN   VARCHAR2,
      infoglio       IN   NUMBER,
      inparticella   IN   VARCHAR2,
      insub          IN   VARCHAR2,
      inunimm        IN   NUMBER,
      terr_immo      IN   VARCHAR2,
      prop_affi      IN   VARCHAR2
   )
      RETURN DATE
   IS
      nome_tabella   VARCHAR2 (13);
      sql_stmt       VARCHAR2 (1000);
      dim            DATE;
      dfm            DATE;
      ritorno        DATE;
   BEGIN
      IF terr_immo = 'T'
      THEN
         IF prop_affi = 'P'
         THEN
            nome_tabella := 'CONS_CONS_TAB';
         ELSIF prop_affi = 'A'
         THEN
            nome_tabella := 'CONS_UFRE_TAB';
         END IF;

         sql_stmt :=
               '
SELECT NVL ((SELECT MAX (data_inizio) AS mm
               FROM '
            || nome_tabella
            || '
              WHERE cod_nazionale = a.cod_nazionale
                AND foglio = a.foglio
                AND particella = a.particella
                AND sub = a.sub),
            TO_DATE (''01010001'', ''DDMMYYYY'')
           ) AS dim,
       NVL ((SELECT MAX (data_fine + 1 / (24 * 3600)) AS mm
               FROM '
            || nome_tabella
            || '
              WHERE cod_nazionale = a.cod_nazionale
                AND foglio = a.foglio
                AND particella = a.particella
                AND sub = a.sub
                AND data_fine <> TO_DATE (''99991231'', ''YYYYMMDD'')),
            TO_DATE (''01010001'', ''DDMMYYYY'')
           ) AS dfm
  FROM '
            || nome_tabella
            || ' a
 WHERE cod_nazionale = :1
   AND foglio = :2
   AND particella = :3
   AND sub = :4
   AND ROWNUM = 1';

         EXECUTE IMMEDIATE sql_stmt
                      INTO dim, dfm
                     USING incodnaz, infoglio, inparticella, insub;

         IF dim > dfm
         THEN
            ritorno := dim;
         ELSE
            ritorno := dfm;
         END IF;
      ELSIF terr_immo = 'U'
      THEN
         IF prop_affi = 'P'
         THEN
            nome_tabella := 'CONS_CSUI_TAB';
         ELSIF prop_affi = 'A'
         THEN
            nome_tabella := 'CONS_URUI_TAB';
         END IF;

         sql_stmt :=
               '
SELECT NVL ((SELECT MAX (data_inizio) AS mm
               FROM '
            || nome_tabella
            || '
              WHERE cod_nazionale = a.cod_nazionale
                AND foglio = a.foglio
                AND particella = a.particella
                AND sub = a.sub and unimm=a.unimm),
            TO_DATE (''01010001'', ''DDMMYYYY'')
           ) AS dim,
       NVL ((SELECT MAX (data_fine + 1 / (24 * 3600)) AS mm
               FROM '
            || nome_tabella
            || '
              WHERE cod_nazionale = a.cod_nazionale
                AND foglio = a.foglio
                AND particella = a.particella
                AND sub = a.sub and unimm=a.unimm
                AND data_fine <> TO_DATE (''99991231'', ''YYYYMMDD'')),
            TO_DATE (''01010001'', ''DDMMYYYY'')
           ) AS dfm
  FROM '
            || nome_tabella
            || ' a
 WHERE cod_nazionale = :1
   AND foglio = :2
   AND particella = :3
   AND sub = :4
   and unimm= :5
   AND ROWNUM = 1';

         EXECUTE IMMEDIATE sql_stmt
                      INTO dim, dfm
                     USING incodnaz, infoglio, inparticella, insub, inunimm;

         IF dim > dfm
         THEN
            ritorno := dim;
         ELSE
            ritorno := dfm;
         END IF;
      END IF;

      RETURN ritorno;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN NULL;
   END;

   FUNCTION data_inizio_titolo (
      incuaa         IN       VARCHAR2,
      incodnaz       IN       VARCHAR2,
      infoglio       IN       NUMBER,
      inparticella   IN       VARCHAR2,
      insub          IN       VARCHAR2,
      inunimm        IN       NUMBER,
      datasituaz     IN OUT   DATE,
      terr_immo      IN       VARCHAR2,
      prop_affi      IN       VARCHAR2
   )
      RETURN DATE
   IS
      TYPE ditcurtyp IS REF CURSOR;

      cursordit      ditcurtyp;
      nome_tabella   VARCHAR2 (13);
      sql_stmt       VARCHAR2 (1000);
      datainizio     DATE;
      datafine       DATE;
      percposs       NUMBER;
      datarif        DATE;
      percrif        NUMBER;
      ritorno        DATE;
   BEGIN
      IF (datasituaz IS NULL)
      THEN
         datasituaz := TO_DATE ('99991231', 'YYYYMMDD');
      END IF;

      IF terr_immo = 'T'
      THEN
         IF prop_affi = 'P'
         THEN
            nome_tabella := 'CONS_CONS_TAB';
         ELSIF prop_affi = 'A'
         THEN
            nome_tabella := 'CONS_UFRE_TAB';
         END IF;

         sql_stmt :=
               'select data_inizio,data_fine,perc_poss from '
            || nome_tabella
            || ' where pk_cuaa=(select pk_cuaa from cons_azie_tab where cuaa=:1) and cod_nazionale=:2 and foglio=:3 and particella =:4 and sub=:5 and data_inizio<=to_date(:6, ''YYYYMMDD'') order by data_fine desc';

         OPEN cursordit
          FOR sql_stmt
          USING incuaa,
                incodnaz,
                infoglio,
                inparticella,
                insub,
                TO_CHAR (datasituaz, 'YYYYMMDD');

         LOOP
            FETCH cursordit
             INTO datainizio, datafine, percposs;

            EXIT WHEN cursordit%NOTFOUND;

            IF datarif IS NULL
            THEN
               datarif := datainizio;
               ritorno := datainizio;
               percrif := percposs;
            ELSE
               IF     (datafine + 1 / (24 * 3600)) >= datarif
                  AND percposs = percrif
               THEN
                  datarif := datainizio;
                  ritorno := datainizio;
                  percrif := percposs;
               ELSE
                  ritorno := datarif;
                  EXIT;
               END IF;
            END IF;
         END LOOP;

         CLOSE cursordit;
      ELSIF terr_immo = 'U'
      THEN
         IF prop_affi = 'P'
         THEN
            nome_tabella := 'CONS_CSUI_TAB';
         ELSIF prop_affi = 'A'
         THEN
            nome_tabella := 'CONS_URUI_TAB';
         END IF;

         sql_stmt :=
               'select data_inizio,data_fine,perc_poss from '
            || nome_tabella
            || ' where pk_cuaa=(select pk_cuaa from cons_azie_tab where cuaa=:1) and cod_nazionale=:2 and foglio=:3 and particella =:4 and sub=:5 and unimm=:6 and data_inizio<=to_date(:6, ''YYYYMMDD'') order by data_fine desc';

         OPEN cursordit
          FOR sql_stmt
          USING incuaa,
                incodnaz,
                infoglio,
                inparticella,
                insub,
                inunimm,
                TO_CHAR (datasituaz, 'YYYYMMDD');

         LOOP
            FETCH cursordit
             INTO datainizio, datafine, percposs;

            EXIT WHEN cursordit%NOTFOUND;

            IF datarif IS NULL
            THEN
               datarif := datainizio;
               ritorno := datainizio;
               percrif := percposs;
            ELSE
               IF     (datafine + 1 / (24 * 3600)) >= datarif
                  AND percposs = percrif
               THEN
                  datarif := datainizio;
                  ritorno := datainizio;
                  percrif := percposs;
               ELSE
                  ritorno := datarif;
                  EXIT;
               END IF;
            END IF;
         END LOOP;

         CLOSE cursordit;
      END IF;

      RETURN ritorno;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN NULL;
   END;

   PROCEDURE allineacons_from_uiu (
      para_cod_nazionale            VARCHAR2,
      para_foglio          IN       NUMBER,
      para_particella      IN       VARCHAR2,
      para_sub             IN       VARCHAR2,
      utente               IN       VARCHAR2,
      data_aggiornamento   IN       DATE,
      prop_or_affi         IN       VARCHAR2,
      ret_code             OUT      NUMBER
   )
   IS
      TYPE ditcurtyp IS REF CURSOR;

      cursordit           ditcurtyp;
      sql_stmt            VARCHAR2 (2048);
      i                   NUMBER          := 0;
      particella          sitiparticella;
      codi_tipo_cond      NUMBER;
      n_aziende           NUMBER          := 0;
      supe_cata_vali      NUMBER          := 0;
      cuaa                varchar_array;
      sup_cond            number_array;
      atto                number_array;
      tipo_cond           number_array;
      millesimi_terreno   NUMBER          := 0;
      tetto_quota         NUMBER          := 0;
      codi_fisc_sogg      VARCHAR2 (16);
      pkidatto            NUMBER          := 0;
   BEGIN
      IF utente IS NULL
      THEN
         raise_application_error (-20072, 'Utente non impostato');
      ELSE
         setutente (utente);
      END IF;

      sql_stmt :=
         'SELECT   (SELECT cuaa
                     FROM cons_azie_tab
                    WHERE pk_cuaa = a.pk_cuaa) AS codi_fisc_sogg,
                  ';

      IF prop_or_affi = 'P'
      THEN
         sql_stmt := sql_stmt || '1';
      ELSIF prop_or_affi = 'A'
      THEN
         sql_stmt := sql_stmt || '2';
      END IF;

      sql_stmt :=
            sql_stmt
         || ' AS tipo_cond,
                    SUM
                       (  a.perc_poss
                        * (SELECT NVL (millesimi_terreno, 0)
                             FROM sitiuiu
                            WHERE cod_nazionale = a.cod_nazionale
                              AND foglio = a.foglio
                              AND particella = a.particella
                              AND sub = a.sub
                              AND unimm = a.unimm
                              AND data_fine_val =
                                              TO_DATE ('' 99991231 '', ''YYYYMMDD''))
                       )
                  * 0.1 AS millesimi_terreno,
                  10000 AS tetto_quota
             FROM ';

      IF prop_or_affi = 'P'
      THEN
         sql_stmt := sql_stmt || 'cons_csui_tab';
      ELSIF prop_or_affi = 'A'
      THEN
         sql_stmt := sql_stmt || 'cons_urui_tab';
      END IF;

      sql_stmt :=
            sql_stmt
         || ' a
            WHERE pk_cuaa < 999999999
              AND cod_nazionale = :1
              AND foglio = :2
              AND particella = :3
              AND sub = :4
              AND data_fine = TO_DATE (''99991231'', ''YYYYMMDD'')
         GROUP BY pk_cuaa';
      cuaa := varchar_array ();
      sup_cond := number_array ();
      tipo_cond := number_array ();
      atto := number_array ();
      i := 0;

      OPEN cursordit
       FOR sql_stmt USING para_cod_nazionale, para_foglio, para_particella,
       para_sub;

      LOOP
         FETCH cursordit
          INTO codi_fisc_sogg, codi_tipo_cond, millesimi_terreno,
               tetto_quota;

         EXIT WHEN cursordit%NOTFOUND;

         IF millesimi_terreno > 0
         THEN
            i := i + 1;
            n_aziende := n_aziende + 1;
            supe_cata_vali := tetto_quota;
            cuaa.EXTEND ();
            cuaa (cuaa.LAST) := codi_fisc_sogg;
            sup_cond.EXTEND ();
            sup_cond (sup_cond.LAST) := millesimi_terreno;
            tipo_cond.EXTEND ();
            tipo_cond (tipo_cond.LAST) := codi_tipo_cond;
            atto.EXTEND ();
            pkidatto :=
               insert_atto ('1',
                            '6',
                            '7',
                            'assegnazione da millesimi UIU',
                            NULL,
                            '3',
                            '999999',
                            SYSDATE,
                            utente,
                            validacuaa (codi_fisc_sogg)
                           );

            IF pkidatto > 0
            THEN
               atto (atto.LAST) := pkidatto;
            ELSE
               atto (atto.LAST) := NULL;
            END IF;
         END IF;
      END LOOP;

      CLOSE cursordit;

      particella.cod_nazionale := para_cod_nazionale;
      particella.foglio := LPAD (para_foglio, 4, '0');
      particella.particella := para_particella;
      particella.subalterno := para_sub;

      IF n_aziende > 0
      THEN
         ret_code :=
            aggiornacons (particella,
                          supe_cata_vali,
                          n_aziende,
                          cuaa,
                          sup_cond,
                          tipo_cond,
                          atto,
                          1,
                          data_aggiornamento,
                          prop_or_affi,
                          2
                         );

         IF ret_code NOT IN (0, 1)
         THEN
            DBMS_OUTPUT.put_line
                                (SUBSTR (   'Errore allinea_cons_from_uiu :'
                                         || TO_CHAR (SQLCODE)
                                         || ': '
                                         || SQLERRM,
                                         1,
                                         255
                                        )
                                );
            DBMS_OUTPUT.put_line (   'comu: '
                                  || para_cod_nazionale
                                  || para_foglio
                                  || ' part: '
                                  || para_particella
                                  || ' sub: '
                                  || para_sub
                                 );
         END IF;
      ELSE
         ret_code := 0;
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         DBMS_OUTPUT.put_line
                          (SUBSTR (   'Errore Oracle allineaCons_from_uiu :'
                                   || TO_CHAR (SQLCODE)
                                   || ': '
                                   || SQLERRM,
                                   1,
                                   255
                                  )
                          );
         DBMS_OUTPUT.put_line (SUBSTR (sql_stmt, 1, 254));
   END allineacons_from_uiu;

   PROCEDURE statistiche_cuaa (
      incuaa            IN       VARCHAR2,
      num_part_totali   OUT      NUMBER,
      num_part_prop     OUT      NUMBER,
      num_part_altr     OUT      NUMBER,
      num_part_nocc     OUT      NUMBER,
      num_part_nogi     OUT      NUMBER,
      num_part_dica     OUT      NUMBER,
      num_part_supe     OUT      NUMBER
   )
   IS
      codnazionale   VARCHAR2 (4);
      fog            NUMBER (5);
      par            VARCHAR2 (5);
      suba           VARCHAR2 (3);
      catasto        NUMBER       := 0;
      gis            NUMBER       := 0;
      discordanza    NUMBER       := 0;

      CURSOR c1
      IS
         SELECT cod_nazionale, foglio, particella, sub
           FROM cons_cons_tab
          WHERE pk_cuaa = (SELECT pk_cuaa
                             FROM cons_azie_tab
                            WHERE cuaa = incuaa)
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

      CURSOR c2
      IS
         SELECT cod_nazionale, foglio, particella, sub
           FROM cons_ufre_tab
          WHERE pk_cuaa = (SELECT pk_cuaa
                             FROM cons_azie_tab
                            WHERE cuaa = incuaa)
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
   BEGIN
      num_part_totali := get_particelle_from_cuaa (incuaa);
      num_part_prop := 0;
      num_part_altr := 0;
      num_part_nocc := 0;
      num_part_nogi := 0;
      num_part_dica := 0;
      num_part_supe := 0;

      FOR c1_rec IN c1
      LOOP
         num_part_prop := num_part_prop + 1;
         codnazionale := c1_rec.cod_nazionale;
         fog := c1_rec.foglio;
         par := c1_rec.particella;
         suba := c1_rec.sub;
         catasto := get_area_cat (NULL, fog, par, suba, codnazionale);

         IF catasto <= 0
         THEN
            num_part_nocc := num_part_nocc + 1;
         END IF;

         gis := get_area_gis (NULL, fog, par, suba, codnazionale);

         IF gis <= 0
         THEN
            num_part_nogi := num_part_nogi + 1;
         END IF;

         discordanza := esiste_discordanza_aree (catasto, gis);

         IF discordanza = 0
         THEN
            num_part_dica := num_part_dica + 1;
         END IF;

         num_part_supe :=
              num_part_supe + is_part_in_supero (codnazionale, fog, par, suba);
      END LOOP;

      FOR c2_rec IN c2
      LOOP
         num_part_altr := num_part_altr + 1;
         codnazionale := c2_rec.cod_nazionale;
         fog := c2_rec.foglio;
         par := c2_rec.particella;
         suba := c2_rec.sub;
         catasto := get_area_cat (NULL, fog, par, suba, codnazionale);

         IF catasto <= 0
         THEN
            num_part_nocc := num_part_nocc + 1;
         END IF;

         gis := get_area_gis (NULL, fog, par, suba, codnazionale);

         IF gis <= 0
         THEN
            num_part_nogi := num_part_nogi + 1;
         END IF;

         discordanza := esiste_discordanza_aree (catasto, gis);

         IF discordanza = 0
         THEN
            num_part_dica := num_part_dica + 1;
         END IF;

         num_part_supe :=
              num_part_supe + is_part_in_supero (codnazionale, fog, par, suba);
      END LOOP;
   END;

   FUNCTION esiste_discordanza_aree (supcat IN NUMBER, supgis IN NUMBER)
      RETURN NUMBER
   IS
      tolleranzacalc   NUMBER := 0;
      ritorno          NUMBER := 0;
   BEGIN
      IF supcat > 0 AND supgis > 0
      THEN
         tolleranzacalc := supcat * tollerenza_percentuale * 0.01;

         IF tolleranzacalc > tollerenza_area
         THEN
            tolleranzacalc := tollerenza_area;
         END IF;

         IF     (supgis >= supcat - tolleranzacalc)
            AND (supgis <= supcat + tolleranzacalc)
         THEN
            ritorno := 1;
         ELSE
            ritorno := 0;
         END IF;
      ELSIF supcat > 0 AND supgis <= 0
      THEN
         ritorno := 1;
      ELSIF supcat < 0
      THEN
         ritorno := -1;
      ELSIF supcat = 0
      THEN
         ritorno := -2;
      END IF;

      RETURN ritorno;
   END;

   FUNCTION get_perc_cond (
      incuaa           IN   VARCHAR2,
      inpkcuaa              NUMBER,
      incodnazionale   IN   VARCHAR2,
      infoglio         IN   NUMBER,
      inparticella     IN   VARCHAR2,
      insub            IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      percposs         NUMBER := 0;
      percaffi         NUMBER := 0;
      percaffialtri    NUMBER := 0;
      percsuperoprop   NUMBER := 0;
      percsuperoaffi   NUMBER := 0;
      pkcuaa           NUMBER := 0;
      ritorno          NUMBER := 0;
   BEGIN
      IF inpkcuaa IS NULL
      THEN
         BEGIN
            SELECT pk_cuaa
              INTO pkcuaa
              FROM cons_azie_tab
             WHERE cuaa = incuaa
               AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
         EXCEPTION
            WHEN NO_DATA_FOUND
            THEN
               RETURN -1;
            WHEN OTHERS
            THEN
               RETURN -1;
         END;
      ELSE
         pkcuaa := inpkcuaa;
      END IF;

      BEGIN
         SELECT perc_poss
           INTO percposs
           FROM cons_cons_tab
          WHERE pk_cuaa = pkcuaa
            AND cod_nazionale = incodnazionale
            AND foglio = infoglio
            AND particella = inparticella
            AND sub = insub
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            percposs := 0;
         WHEN OTHERS
         THEN
            RETURN -1;
      END;

      BEGIN
         SELECT perc_poss
           INTO percaffi
           FROM cons_ufre_tab
          WHERE pk_cuaa = pkcuaa
            AND cod_nazionale = incodnazionale
            AND foglio = infoglio
            AND particella = inparticella
            AND sub = insub
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            percaffi := 0;
         WHEN OTHERS
         THEN
            RETURN -1;
      END;

      BEGIN
         SELECT NVL (SUM (perc_poss), 0)
           INTO percaffialtri
           FROM cons_ufre_tab
          WHERE cod_nazionale = incodnazionale
            AND foglio = infoglio
            AND particella = inparticella
            AND sub = insub
            AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            percaffialtri := 0;
         WHEN OTHERS
         THEN
            RETURN -1;
      END;

      BEGIN
         SELECT b.perc_poss, b.perc_affi
           INTO percsuperoprop, percsuperoaffi
           FROM cons_supa_tab a, cons_suaz_tab b
          WHERE ((a.pkid_supa = b.pkid_supa))
            AND b.pk_cuaa = pkcuaa
            AND a.cod_nazionale = incodnazionale
            AND a.foglio = infoglio
            AND a.particella = inparticella
            AND a.sub = insub
            AND a.data_fine = TO_DATE ('99991231', 'YYYYMMDD')
            AND b.data_fine = TO_DATE ('99991231', 'YYYYMMDD');
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            percsuperoprop := 0;
            percsuperoaffi := 0;
         WHEN OTHERS
         THEN
            RETURN -1;
      END;

      IF percsuperoprop > 0
      THEN
         ritorno := percsuperoprop;
      ELSIF percsuperoaffi > 0
      THEN
         ritorno := percsuperoaffi;
      ELSE
         ritorno := percaffi + percposs * (100 - percaffialtri) * 0.01;
      END IF;

      RETURN ritorno;
   END;

   FUNCTION is_uiu_in_supero (
      incodnazionale   IN   VARCHAR2,
      infoglio         IN   NUMBER,
      inparticella     IN   VARCHAR2,
      insub            IN   VARCHAR2,
      inunimm          IN   NUMBER
   )
      RETURN NUMBER
   IS
      is_supero   NUMBER := 0;
   BEGIN
      SELECT 1
        INTO is_supero
        FROM cons_suui_tab a
       WHERE a.cod_nazionale = incodnazionale
         AND a.foglio = infoglio
         AND a.particella = inparticella
         AND a.sub = insub
         AND a.unimm = inunimm
         AND a.data_fine = TO_DATE ('99991231', 'YYYYMMDD');

      RETURN is_supero;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RETURN 0;
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

   FUNCTION is_part_in_supero (
      incodnazionale   IN   VARCHAR2,
      infoglio         IN   NUMBER,
      inparticella     IN   VARCHAR2,
      insub            IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      is_supero   NUMBER := 0;
   BEGIN
      SELECT 1
        INTO is_supero
        FROM cons_supa_tab a
       WHERE a.cod_nazionale = incodnazionale
         AND a.foglio = infoglio
         AND a.particella = inparticella
         AND a.sub = insub
         AND a.data_fine = TO_DATE ('99991231', 'YYYYMMDD');

      RETURN is_supero;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RETURN 0;
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

   FUNCTION get_strati_gis (
      datainizio   IN   DATE,
      fog          IN   NUMBER,
      part         IN   VARCHAR2,
      subo         IN   VARCHAR2,
      codnaz       IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      ritorno   NUMBER := 0;
      step      NUMBER := 0;
      datarif   DATE;
   BEGIN
      IF datainizio IS NULL
      THEN
         datarif := TO_DATE ('99991231', 'YYYYMMDD');
      ELSE
         datarif := datainizio;
      END IF;

      BEGIN
         SELECT /*+ INDEX (SITICENT SITICENT_PK) */
                1
           INTO step
           FROM siticent
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subo
            AND data_inizio_val <= datarif
            AND data_fine_val >= datarif
            AND ROWNUM = 1;
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            step := 0;
         WHEN OTHERS
         THEN
            step := 0;
      END;

      ritorno := ritorno + step;

      BEGIN
         SELECT /*+ INDEX (SITIPART SITIPART_PK) */
                2
           INTO step
           FROM sitipart
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subo
            AND data_inizio_val <= datarif
            AND data_fine_val >= datarif
            AND ROWNUM = 1;
      EXCEPTION
         WHEN NO_DATA_FOUND
         THEN
            step := 0;
         WHEN OTHERS
         THEN
            step := 0;
      END;

      ritorno := ritorno + step;
      RETURN ritorno;
   END;

   FUNCTION insert_atto (
      tipotitolo          IN   VARCHAR2,
      tipodocumento       IN   VARCHAR2,
      tipooperazione      IN   VARCHAR2,
      innote              IN   VARCHAR2,
      datascadenzaatto    IN   DATE,
      tipoarchiviazione   IN   VARCHAR2,
      codiceiden          IN   VARCHAR2,
      dataregistrazione   IN   DATE,
      utente              IN   VARCHAR2,
      pkcuaa              IN   NUMBER
   )
      RETURN NUMBER
   IS
      nsequence    NUMBER := 0;
      rlsequence   NUMBER := 0;
   BEGIN
      nsequence := esiste_atto (pkcuaa, codiceiden, dataregistrazione);

      IF nsequence = 0
      THEN
         SELECT cons_atti_seq.NEXTVAL
           INTO nsequence
           FROM DUAL;

         SELECT cons_atrl_seq.NEXTVAL
           INTO rlsequence
           FROM DUAL;

         INSERT INTO cons_atti_tab
                     (pkid_atto, tipo_titolo, tipo_documento,
                      tipo_operazione, note, data_scadenza_atto,
                      tipo_archiviazione, codice_iden, data_registrazione,
                      utente, TIMESTAMP, pk_cuaa
                     )
              VALUES (nsequence, tipotitolo, tipodocumento,
                      tipooperazione, innote, datascadenzaatto,
                      tipoarchiviazione, codiceiden, dataregistrazione,
                      utente, SYSDATE, pkcuaa
                     );

         INSERT INTO cons_atrl_tab
                     (pkid_atto, pkid_atex
                     )
              VALUES (rlsequence, nsequence
                     );
      ELSE
         SELECT cons_atrl_seq.NEXTVAL
           INTO rlsequence
           FROM DUAL;

         INSERT INTO cons_atrl_tab
                     (pkid_atto, pkid_atex
                     )
              VALUES (rlsequence, nsequence
                     );
      END IF;

      COMMIT;
      RETURN rlsequence;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN -1;
   END;

/*
FUNCTION get_perc_cond_part

Ritorna la percentuale di proprieta di una particella
se =0 allora non esistono proprietari
se =200 allora e in supero
*/
   FUNCTION get_perc_cond_part (
      incodnazionale   IN   VARCHAR2,
      infoglio         IN   NUMBER,
      inparticella     IN   VARCHAR2,
      insub            IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      ritorno   NUMBER := 0;
   BEGIN
      SELECT SUM (perc_poss)
        INTO ritorno
        FROM cons_cons_tab
       WHERE pk_cuaa < 999999999
         AND cod_nazionale = incodnazionale
         AND foglio = infoglio
         AND particella = inparticella
         AND sub = insub
         AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

      IF ritorno IS NULL
      THEN
         ritorno := 0;
      END IF;

      IF ritorno > 99 AND ritorno < 101
      THEN
         ritorno := 100;
      END IF;

      IF is_part_in_supero (incodnazionale, infoglio, inparticella, insub) = 1
      THEN
         ritorno := 200;
      END IF;

      RETURN ritorno;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

   FUNCTION get_perc_cond_uiu (
      incodnazionale   IN   VARCHAR2,
      infoglio         IN   NUMBER,
      inparticella     IN   VARCHAR2,
      insub            IN   VARCHAR2,
      inunimm          IN   NUMBER
   )
      RETURN NUMBER
   IS
      ritorno   NUMBER := 0;
   BEGIN
      SELECT SUM (perc_poss)
        INTO ritorno
        FROM cons_csui_tab
       WHERE pk_cuaa < 999999999
         AND cod_nazionale = incodnazionale
         AND foglio = infoglio
         AND particella = inparticella
         AND sub = insub
         AND unimm = inunimm
         AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

      IF ritorno IS NULL
      THEN
         ritorno := 0;
      END IF;

      IF ritorno > 99 AND ritorno < 101
      THEN
         ritorno := 100;
      END IF;

      IF is_uiu_in_supero (incodnazionale,
                           infoglio,
                           inparticella,
                           insub,
                           inunimm
                          ) = 1
      THEN
         ritorno := 200;
      END IF;

      RETURN ritorno;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

   FUNCTION cal_cond_daconsistenza (
      utente                     IN   VARCHAR2,
      para_cod_nazionale         IN   VARCHAR2,
      para_foglio                IN   NUMBER,
      para_particella            IN   VARCHAR2,
      para_sub                   IN   VARCHAR2,
      para_unimm                 IN   NUMBER,
      sup_cata_val               IN   NUMBER,
      cuaa                       IN   VARCHAR2,
      sup_condotta               IN   NUMBER,
      tit_conduz                 IN   NUMBER,
      id_atto                    IN   NUMBER,
      percentuali_su_catastale   IN   NUMBER,
      indata                     IN   DATE,
      poss_or_affi               IN   VARCHAR2,
      ter_or_uiu                 IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      errore               NUMBER         := 0;
      validapart_esito     NUMBER;
      daticonduz_esito     NUMBER;
      daticonduz_numazie   NUMBER;
      daticonduz_posazie   NUMBER;
      daticonduz_cuaa      varchar_array;
      daticonduz_supcond   number_array;
      daticonduz_titolo    number_array;
      daticonduz_atto      number_array;
      ese_upc              NUMBER;
      part                 sitiparticella;
   BEGIN
      errore := 0;
      part.cod_nazionale := para_cod_nazionale;
      part.foglio := LPAD (para_foglio, 4, '0');
      part.particella := para_particella;
      part.subalterno := para_sub;
      part.unimm := para_unimm;
      validapart_esito := validapart (part);
      setutente (utente);

      IF validapart_esito <> 1
      THEN
         errore := 8;
      END IF;

      IF errore = 0
      THEN
         IF NOT (cuaa IS NULL OR sup_cata_val <= 0)
         THEN
            IF ter_or_uiu = 'T'
            THEN
               daticonduz_esito :=
                  daticonduz_ter (part,
                                  cuaa,
                                  sup_cata_val,
                                  daticonduz_numazie,
                                  daticonduz_posazie,
                                  daticonduz_cuaa,
                                  daticonduz_supcond,
                                  daticonduz_titolo,
                                  daticonduz_atto,
                                  poss_or_affi
                                 );
            ELSE
               daticonduz_esito :=
                  daticonduz_uiu (part,
                                  cuaa,
                                  sup_cata_val,
                                  daticonduz_numazie,
                                  daticonduz_posazie,
                                  daticonduz_cuaa,
                                  daticonduz_supcond,
                                  daticonduz_titolo,
                                  daticonduz_atto,
                                  poss_or_affi
                                 );
            END IF;

            IF     NOT (daticonduz_numazie = 0 AND sup_condotta <= 0)
               AND NOT (daticonduz_posazie = 0 AND sup_condotta <= 0)
               AND (daticonduz_esito = 1)
            THEN
               IF     daticonduz_posazie > 0
                  AND daticonduz_supcond (daticonduz_posazie) = sup_condotta
               THEN
                  ese_upc := 0;
               ELSE
                  ese_upc := 1;
               END IF;

               IF ese_upc = 1
               THEN
                  IF daticonduz_posazie = 0
                  THEN
                     daticonduz_numazie := daticonduz_numazie + 1;
                     daticonduz_posazie := daticonduz_numazie;
                     daticonduz_cuaa.EXTEND;
                     daticonduz_supcond.EXTEND;
                     daticonduz_titolo.EXTEND;
                     daticonduz_atto.EXTEND;
                  END IF;

                  daticonduz_cuaa (daticonduz_posazie) := cuaa;
                  daticonduz_supcond (daticonduz_posazie) := sup_condotta;
                  daticonduz_titolo (daticonduz_posazie) := tit_conduz;
                  daticonduz_atto (daticonduz_posazie) := id_atto;

                  IF ter_or_uiu = 'T'
                  THEN
                     errore :=
                        aggiornacons (part,
                                      sup_cata_val,
                                      daticonduz_numazie,
                                      daticonduz_cuaa,
                                      daticonduz_supcond,
                                      daticonduz_titolo,
                                      daticonduz_atto,
                                      percentuali_su_catastale,
                                      indata,
                                      poss_or_affi,
                                      2
                                     );
                  ELSE
                     errore :=
                        aggiornacons_uiu (part,
                                          sup_cata_val,
                                          daticonduz_numazie,
                                          daticonduz_cuaa,
                                          daticonduz_supcond,
                                          daticonduz_titolo,
                                          daticonduz_atto,
                                          percentuali_su_catastale,
                                          indata,
                                          poss_or_affi,
                                          2
                                         );
                  END IF;

                  COMMIT;
               ELSE
                  DBMS_OUTPUT.put_line
                         ('operazione ignorata: nessuna variazione prevista.');
               END IF;
            ELSE
               IF NOT (daticonduz_esito = 1)
               THEN
                  errore := 5;
               ELSE
                  errore := 6;
               END IF;
            END IF;
         ELSE
            errore := 9;
         END IF;
      ELSE
         errore := 8;
      END IF;

      RETURN errore;
   END;

   FUNCTION daticonduz_ter (
      part           IN       sitiparticella,
      cuaa           IN       VARCHAR2,
      sup_cata_val   IN       NUMBER,
      ret_numazie    OUT      NUMBER,
      ret_posazie    OUT      NUMBER,
      ret_cuaa       OUT      varchar_array,
      ret_supcond    OUT      number_array,
      ret_titolo     OUT      number_array,
      ret_atto       OUT      number_array,
      prop_or_affi            VARCHAR2
   )
      RETURN NUMBER
   IS
      TYPE ditcurtyp IS REF CURSOR;

      sql_stmt         VARCHAR2 (2048);
      cursordit        ditcurtyp;
      codi_fisc_sogg   VARCHAR2 (16);
      codi_tipo_cond   VARCHAR2 (1);
      QUOTA            NUMBER;
      tetto_quota      NUMBER;
      pkidatto         NUMBER;
   BEGIN
      ret_numazie := 0;
      ret_posazie := 0;
      sql_stmt :=
         'SELECT   (SELECT cuaa
                     FROM cons_azie_tab
                    WHERE pk_cuaa = a.pk_cuaa) AS codi_fisc_sogg,
                  ';

      IF prop_or_affi = 'P'
      THEN
         sql_stmt := sql_stmt || '1';
      ELSIF prop_or_affi = 'A'
      THEN
         sql_stmt := sql_stmt || '2';
      END IF;

      sql_stmt :=
            sql_stmt
         || ' AS tipo_cond, a.perc_poss/100 AS quota, pkid_atto
             FROM ';

      IF prop_or_affi = 'P'
      THEN
         sql_stmt := sql_stmt || 'cons_cons_tab';
      ELSIF prop_or_affi = 'A'
      THEN
         sql_stmt := sql_stmt || 'cons_ufre_tab';
      END IF;

      sql_stmt :=
            sql_stmt
         || ' a
            WHERE pk_cuaa < 999999999
              AND cod_nazionale = :1
              AND foglio = :2
              AND particella = :3
              AND sub = :4
              AND data_fine = TO_DATE (''99991231'', ''YYYYMMDD'')';
      ret_cuaa := varchar_array ();
      ret_supcond := number_array ();
      ret_titolo := number_array ();
      ret_atto := number_array ();

      OPEN cursordit
       FOR sql_stmt
       USING part.cod_nazionale, part.foglio, part.particella,
             part.subalterno;

      LOOP
         FETCH cursordit
          INTO codi_fisc_sogg, codi_tipo_cond, QUOTA, pkidatto;

         EXIT WHEN cursordit%NOTFOUND;
         ret_numazie := ret_numazie + 1;
         ret_cuaa.EXTEND ();
         ret_cuaa (ret_cuaa.LAST) := codi_fisc_sogg;

         IF codi_fisc_sogg = cuaa
         THEN
            ret_posazie := ret_numazie;
         END IF;

         ret_supcond.EXTEND ();
         ret_supcond (ret_supcond.LAST) := QUOTA * sup_cata_val;
         ret_titolo.EXTEND ();
         ret_titolo (ret_titolo.LAST) := codi_tipo_cond;
         ret_atto.EXTEND ();
         ret_atto (ret_atto.LAST) := pkidatto;
      END LOOP;

      RETURN 1;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

   FUNCTION daticonduz_uiu (
      part           IN       sitiparticella,
      cuaa           IN       VARCHAR2,
      sup_cata_val   IN       NUMBER,
      ret_numazie    OUT      NUMBER,
      ret_posazie    OUT      NUMBER,
      ret_cuaa       OUT      varchar_array,
      ret_supcond    OUT      number_array,
      ret_titolo     OUT      number_array,
      ret_atto       OUT      number_array,
      prop_or_affi            VARCHAR2
   )
      RETURN NUMBER
   IS
      TYPE ditcurtyp IS REF CURSOR;

      sql_stmt         VARCHAR2 (2048);
      cursordit        ditcurtyp;
      codi_fisc_sogg   VARCHAR2 (16);
      codi_tipo_cond   VARCHAR2 (1);
      QUOTA            NUMBER;
      tetto_quota      NUMBER;
      pkidatto         NUMBER;
   BEGIN
      ret_numazie := 0;
      ret_posazie := 0;
      sql_stmt :=
         'SELECT   (SELECT cuaa
                     FROM cons_azie_tab
                    WHERE pk_cuaa = a.pk_cuaa) AS codi_fisc_sogg,
                  ';

      IF prop_or_affi = 'P'
      THEN
         sql_stmt := sql_stmt || '1';
      ELSIF prop_or_affi = 'A'
      THEN
         sql_stmt := sql_stmt || '2';
      END IF;

      sql_stmt :=
            sql_stmt
         || ' AS tipo_cond, a.perc_poss/100 AS quota, pkid_atto
             FROM ';

      IF prop_or_affi = 'P'
      THEN
         sql_stmt := sql_stmt || 'cons_csui_tab';
      ELSIF prop_or_affi = 'A'
      THEN
         sql_stmt := sql_stmt || 'cons_urui_tab';
      END IF;

      sql_stmt :=
            sql_stmt
         || ' a
            WHERE pk_cuaa < 999999999
              AND cod_nazionale = :1
              AND foglio = :2
              AND particella = :3
              AND sub = :4
              and unimm =:5
              AND data_fine = TO_DATE (''99991231'', ''YYYYMMDD'')';
      ret_cuaa := varchar_array ();
      ret_supcond := number_array ();
      ret_titolo := number_array ();
      ret_atto := number_array ();

      OPEN cursordit
       FOR sql_stmt
       USING part.cod_nazionale,
             part.foglio,
             part.particella,
             part.subalterno,
             part.unimm;

      LOOP
         FETCH cursordit
          INTO codi_fisc_sogg, codi_tipo_cond, QUOTA, pkidatto;

         EXIT WHEN cursordit%NOTFOUND;
         ret_numazie := ret_numazie + 1;
         ret_cuaa.EXTEND ();
         ret_cuaa (ret_cuaa.LAST) := codi_fisc_sogg;

         IF codi_fisc_sogg = cuaa
         THEN
            ret_posazie := ret_numazie;
         END IF;

         ret_supcond.EXTEND ();
         ret_supcond (ret_supcond.LAST) := QUOTA * sup_cata_val;
         ret_titolo.EXTEND ();
         ret_titolo (ret_titolo.LAST) := codi_tipo_cond;
         ret_atto.EXTEND ();
         ret_atto (ret_atto.LAST) := pkidatto;
      END LOOP;

      RETURN 1;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

   FUNCTION esiste_atto (
      pkcuaa       IN   NUMBER,
      codiceiden   IN   VARCHAR2,
      dataregi     IN   DATE
   )
      RETURN NUMBER
   IS
      pkidatto   NUMBER := 0;
   BEGIN
      SELECT pkid_atto
        INTO pkidatto
        FROM cons_atti_tab
       WHERE pk_cuaa = pkcuaa
         AND codice_iden = codice_iden
         AND data_registrazione = dataregi
         AND ROWNUM = 1;

      RETURN pkidatto;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN 0;
   END;

