DROP PACKAGE BODY SITI_H501.SITICONV;

CREATE OR REPLACE PACKAGE BODY SITI_H501.siticonv AS

PROCEDURE INVERSIONE_TAVOLA (
      INCOD_NAZ           IN  VARCHAR2,
      INTAVOLA_ORIG       IN  NUMBER,
      INTAVOLA_DEST       IN  NUMBER,
      INCONS_TERRENI      IN  NUMBER,
      INCONS_UIU          IN  NUMBER,
      INUNAR              IN  NUMBER,
      INGIS               IN  NUMBER,
      INUIU               IN  NUMBER,
      INSTRADE            IN  NUMBER,
      INFIUMI             IN  NUMBER,
      INCATASTO_TERRENI   IN  NUMBER
)
IS
-- GIS
  CURSOR C3 IS SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_ORIG AND ROWNUM=1;
  CURSOR C4 IS SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_DEST AND ROWNUM=1;
-- CONSISTENZA TERRENI
  CURSOR C11 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CONS_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_UFRE_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1)) WHERE ROWNUM=1;
  CURSOR C12 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CONS_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_UFRE_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1)) WHERE ROWNUM=1;
-- CONSISTENZA FABBRICATI
  CURSOR C13 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CSUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_URUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1)) WHERE ROWNUM=1;
  CURSOR C14 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CSUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_URUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1)) WHERE ROWNUM=1;
-- UNITÀ ARBOREE
  CURSOR C15 IS SELECT 1 FROM SITIUNAR WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1;
  CURSOR C16 IS SELECT 1 FROM SITIUNAR WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1;
-- UIU
  CURSOR C17 IS SELECT 1 FROM SITIUIU WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1;
  CURSOR C18 IS SELECT 1 FROM SITIUIU WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1;
-- STRADE
  CURSOR C19 IS SELECT 1 FROM SITISTRA WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1;
  CURSOR C20 IS SELECT 1 FROM SITISTRA WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1;
-- FIUMI
  CURSOR C21 IS SELECT 1 FROM SITIFIUM WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1;
  CURSOR C22 IS SELECT 1 FROM SITIFIUM WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1;
-- CATASTO TERRENI
  CURSOR C23 IS SELECT 1 FROM SITITRKC WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG AND ROWNUM=1;
  CURSOR C24 IS SELECT 1 FROM SITITRKC WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST AND ROWNUM=1;

  CURSOR C25 IS SELECT FOGLIO FROM SITIFGLC WHERE COD_NAZIONALE=INCOD_NAZ AND TAVOLA=INTAVOLA_DEST;

  UPOK   NUMBER(9):=0;
  TMP    NUMBER(9);
  FOGLIO_DEST NUMBER(4);
  FOGLIO_ORIG NUMBER(4);
BEGIN

  IF INCONS_TERRENI IS NOT NULL THEN
    OPEN C11;  FETCH C11 INTO TMP;  IF C11%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C11;
    OPEN C12;  FETCH C12 INTO TMP;  IF C12%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C12;

    IF UPOK=0 THEN
      UPDATE CONS_CONS_TAB SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE CONS_CONS_TAB SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE CONS_CONS_TAB SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
      UPDATE CONS_UFRE_TAB SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE CONS_UFRE_TAB SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE CONS_UFRE_TAB SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (CONS_CONS_TAB, CONS_UFRE_TAB) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;

  IF INCONS_UIU IS NOT NULL THEN
    OPEN C13;  FETCH C13 INTO TMP;  IF C13%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C13;
    OPEN C14;  FETCH C14 INTO TMP;  IF C14%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C14;

    IF UPOK=0 THEN
      UPDATE CONS_CSUI_TAB SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE CONS_CSUI_TAB SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE CONS_CSUI_TAB SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
      UPDATE CONS_URUI_TAB SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE CONS_URUI_TAB SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE CONS_URUI_TAB SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (CONS_CSUI_TAB, CONS_URUI_TAB) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;

  IF INUNAR IS NOT NULL THEN
    OPEN C15;  FETCH C15 INTO TMP;  IF C15%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C15;
    OPEN C16;  FETCH C16 INTO TMP;  IF C16%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C16;

    IF UPOK=0 THEN
      UPDATE SITIUNAR SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE SITIUNAR SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE SITIUNAR SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIUNAR) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;

  IF INGIS IS NOT NULL THEN
    SELECT FOGLIO INTO FOGLIO_ORIG FROM SITIFGLC WHERE COD_NAZIONALE=INCOD_NAZ AND TAVOLA=INTAVOLA_ORIG;
 OPEN C25;
 FETCH C25 INTO FOGLIO_DEST;
 IF C25%NOTFOUND THEN FOGLIO_DEST:=INTAVOLA_DEST; END IF;
 CLOSE C25;

    OPEN C3;  FETCH C3 INTO TMP;  IF C3%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C3;
/*
 IF FOGLIO_DEST>0 THEN
     OPEN C4;  FETCH C4 INTO TMP;  IF C4%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C4;
 END IF;
*/

    IF UPOK = 0 THEN
      UPDATE SITICENT SET TAVOLA = 8888,FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_ORIG;
      UPDATE SITICENT SET TAVOLA = INTAVOLA_ORIG, FOGLIO = FOGLIO_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_DEST;
      UPDATE SITICENT SET TAVOLA = INTAVOLA_DEST, FOGLIO = FOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = 8888;

      UPDATE SITIFGLC SET TAVOLA = 8888,FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_ORIG;
      UPDATE SITIFGLC SET TAVOLA = INTAVOLA_ORIG, FOGLIO = FOGLIO_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_DEST;
      UPDATE SITIFGLC SET TAVOLA = INTAVOLA_DEST, FOGLIO = FOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = 8888;

      UPDATE SITIPART SET TAVOLA = 8888,FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_ORIG;
      UPDATE SITIPART SET TAVOLA = INTAVOLA_ORIG, FOGLIO = FOGLIO_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_DEST;
      UPDATE SITIPART SET TAVOLA = INTAVOLA_DEST, FOGLIO = FOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = 8888;

      UPDATE SITISUOLO SET TAVOLA = 8888,FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_ORIG;
      UPDATE SITISUOLO SET TAVOLA = INTAVOLA_ORIG, FOGLIO = FOGLIO_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_DEST;
      UPDATE SITISUOLO SET TAVOLA = INTAVOLA_DEST, FOGLIO = FOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = 8888;

      UPDATE SITIFOTC SET TAVOLA = 8888,FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_ORIG;
      UPDATE SITIFOTC SET TAVOLA = INTAVOLA_ORIG, FOGLIO = FOGLIO_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = INTAVOLA_DEST;
      UPDATE SITIFOTC SET TAVOLA = INTAVOLA_DEST, FOGLIO = FOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND TAVOLA = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (SITICENT, SITIFGLC, SITIPART, SITISUOLO, SITIFOTC) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;

  IF INUIU IS NOT NULL THEN
    OPEN C17;  FETCH C17 INTO TMP;  IF C17%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C17;
    OPEN C18;  FETCH C18 INTO TMP;  IF C18%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C18;

    IF UPOK=0 THEN
      UPDATE SITIUIU SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE SITIUIU SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE SITIUIU SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIUIU) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;

  IF INSTRADE IS NOT NULL THEN
    OPEN C19;  FETCH C19 INTO TMP;  IF C19%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C19;
    OPEN C20;  FETCH C20 INTO TMP;  IF C20%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C20;

    IF UPOK=0 THEN
      UPDATE SITISTRA SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE SITISTRA SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE SITISTRA SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITISTRA) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;

  IF INFIUMI IS NOT NULL THEN
    OPEN C21;  FETCH C21 INTO TMP;  IF C21%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C21;
    OPEN C22;  FETCH C22 INTO TMP;  IF C22%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C22;

    IF UPOK=0 THEN
      UPDATE SITIFIUM SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE SITIFIUM SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE SITIFIUM SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIFIUM) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;

  IF INCATASTO_TERRENI IS NOT NULL THEN
    OPEN C23;  FETCH C23 INTO TMP;  IF C23%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C23;
    OPEN C24;  FETCH C24 INTO TMP;  IF C24%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C24;

    IF UPOK=0 THEN
      UPDATE SITITRKC SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE SITITRKC SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE SITITRKC SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
      UPDATE SITIFRAZ SET FOGLIO = 8888 WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_ORIG;
      UPDATE SITIFRAZ SET FOGLIO = INTAVOLA_ORIG WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = INTAVOLA_DEST;
      UPDATE SITIFRAZ SET FOGLIO = INTAVOLA_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO = 8888;
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITITRKC) NON CONTIENE UNA DELLE TAVOLE INDICATE');
    END IF;
  END IF;
-- RICALCOLO ANOMALIE
  SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ, INTAVOLA_ORIG);
  SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ, INTAVOLA_DEST);
END INVERSIONE_TAVOLA;

PROCEDURE INVERSIONE_COMUNE (
      INCOD_NAZ_ORIG      IN  VARCHAR2,
      INCOD_NAZ_DEST      IN  VARCHAR2,
      INCONS_TERRENI      IN  NUMBER,
      INCONS_UIU          IN  NUMBER,
      INUNAR              IN  NUMBER,
      INGIS               IN  NUMBER,
      INUIU               IN  NUMBER,
      INSTRADE            IN  NUMBER,
      INFIUMI             IN  NUMBER,
      INCATASTO_TERRENI   IN  NUMBER
)
IS
-- GIS
  CURSOR C1 IS SELECT 1 FROM SITICENT WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C2 IS SELECT 1 FROM SITICENT WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;

  CURSOR C3 IS SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C4 IS SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;

  CURSOR C5 IS SELECT 1 FROM SITIPART WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C6 IS SELECT 1 FROM SITIPART WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;

  CURSOR C7 IS SELECT 1 FROM SITISUOLO WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C8 IS SELECT 1 FROM SITISUOLO WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;
-- CONSISTENZA TERRENI
  CURSOR C11 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CONS_TAB WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_UFRE_TAB WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1)) WHERE ROWNUM=1;
  CURSOR C12 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CONS_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_UFRE_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1)) WHERE ROWNUM=1;
-- CONSISTENZA FABBRICATI
  CURSOR C13 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CSUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_URUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1)) WHERE ROWNUM=1;
  CURSOR C14 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CSUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_URUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1)) WHERE ROWNUM=1;
-- UNITÀ ARBOREE
  CURSOR C15 IS SELECT 1 FROM SITIUNAR WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C16 IS SELECT 1 FROM SITIUNAR WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;
-- UIU
  CURSOR C17 IS SELECT 1 FROM SITIUIU WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C18 IS SELECT 1 FROM SITIUIU WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;
-- STRADE
  CURSOR C19 IS SELECT 1 FROM SITISTRA WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C20 IS SELECT 1 FROM SITISTRA WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;
-- FIUMI
  CURSOR C21 IS SELECT 1 FROM SITIFIUM WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C22 IS SELECT 1 FROM SITIFIUM WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;
-- CATASTO TERRENI
  CURSOR C23 IS SELECT 1 FROM SITITRKC WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND ROWNUM=1;
  CURSOR C24 IS SELECT 1 FROM SITITRKC WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND ROWNUM=1;

  CURSOR C25 IS SELECT FLAG_CATA FROM SITICOMU WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
  CURSOR C26 IS SELECT FLAG_CATA FROM SITICOMU WHERE COD_NAZIONALE = INCOD_NAZ_DEST;

  CURSOR C27 IS SELECT FOGLIO FROM SITIFGLC WHERE COD_NAZIONALE = INCOD_NAZ_ORIG OR COD_NAZIONALE = INCOD_NAZ_DEST GROUP BY FOGLIO;

  UPOK   NUMBER(9):=0;
  TMP    NUMBER(9);
  FOGLIO NUMBER(4);
  FLAG_CATA_ORIG  NUMBER(1);
  FLAG_CATA_DEST  NUMBER(1);
BEGIN

  OPEN C25;   FETCH C25 INTO FLAG_CATA_ORIG;   CLOSE C25;
  OPEN C26;   FETCH C26 INTO FLAG_CATA_DEST;   CLOSE C26;

  IF FLAG_CATA_ORIG = FLAG_CATA_DEST THEN
    IF INCONS_TERRENI IS NOT NULL THEN
      OPEN C11;  FETCH C11 INTO TMP;  IF C11%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C11;
      OPEN C12;  FETCH C12 INTO TMP;  IF C12%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C12;

      IF UPOK=0 THEN
        UPDATE CONS_CONS_TAB SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE CONS_CONS_TAB SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE CONS_CONS_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
        UPDATE CONS_UFRE_TAB SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE CONS_UFRE_TAB SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE CONS_UFRE_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (CONS_CONS_TAB, CONS_UFRE_TAB) NON CONTIENE UN CODICE NAZIONALE INDICATO');
      END IF;
    END IF;

    IF INCONS_UIU IS NOT NULL THEN
      OPEN C13;  FETCH C13 INTO TMP;  IF C13%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C13;
      OPEN C14;  FETCH C14 INTO TMP;  IF C14%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C14;

      IF UPOK=0 THEN
        UPDATE CONS_CSUI_TAB SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE CONS_CSUI_TAB SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE CONS_CSUI_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
        UPDATE CONS_URUI_TAB SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE CONS_URUI_TAB SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE CONS_URUI_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (CONS_CSUI_TAB, CONS_URUI_TAB) NON CONTIENE UN CODICE NAZIONALE INDICATO');
      END IF;
    END IF;

    IF INUNAR IS NOT NULL THEN
      OPEN C15;  FETCH C15 INTO TMP;  IF C15%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C15;
      OPEN C16;  FETCH C16 INTO TMP;  IF C16%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C16;

      IF UPOK=0 THEN
        UPDATE SITIUNAR SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITIUNAR SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITIUNAR SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIUNAR) NON CONTIENE UN CODICE NAZIONALE');
      END IF;
    END IF;

    IF INGIS IS NOT NULL THEN
  UPOK:=0;
--      OPEN C1;  FETCH C1 INTO TMP;  IF C1%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C1;
--      OPEN C2;  FETCH C2 INTO TMP;  IF C2%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C2;
--      OPEN C3;  FETCH C3 INTO TMP;  IF C3%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C3;
--      OPEN C4;  FETCH C4 INTO TMP;  IF C4%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C4;
--      OPEN C5;  FETCH C5 INTO TMP;  IF C5%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C5;
--      OPEN C6;  FETCH C6 INTO TMP;  IF C6%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C6;
--      OPEN C7;  FETCH C7 INTO TMP;  IF C7%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C7;
--      OPEN C8;  FETCH C8 INTO TMP;  IF C8%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C8;

      IF UPOK=0 THEN
        UPDATE SITICENT SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITICENT SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITICENT SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';

        UPDATE SITIFGLC SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITIFGLC SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITIFGLC SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';

        UPDATE SITIPART SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITIPART SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITIPART SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';

        UPDATE SITISUOLO SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITISUOLO SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITISUOLO SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';

        UPDATE SITIFOTC SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITIFOTC SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITIFOTC SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (SITICENT, SITIFGLC, SITIPART, SITISUOLO) NON CONTIENE UN CODICE NAZIONALE INDICATO');
      END IF;
    END IF;

    IF INUIU IS NOT NULL THEN
      OPEN C17;  FETCH C17 INTO TMP;  IF C17%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C17;
      OPEN C18;  FETCH C18 INTO TMP;  IF C18%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C18;

      IF UPOK=0 THEN
        UPDATE SITIUIU SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITIUIU SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITIUIU SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIUIU) NON CONTIENE UN CODICE NAZIONALE INDICATO');
      END IF;
    END IF;

    IF INSTRADE IS NOT NULL THEN
      OPEN C19;  FETCH C19 INTO TMP;  IF C19%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C19;
      OPEN C20;  FETCH C20 INTO TMP;  IF C20%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C20;

      IF UPOK=0 THEN
        UPDATE SITISTRA SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITISTRA SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITISTRA SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITISTRA) NON CONTIENE UN CODICE NAZIONALE INDICATO');
      END IF;
    END IF;

    IF INFIUMI IS NOT NULL THEN
      OPEN C21;  FETCH C21 INTO TMP;  IF C21%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C21;
      OPEN C22;  FETCH C22 INTO TMP;  IF C22%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C22;

      IF UPOK=0 THEN
        UPDATE SITIFIUM SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITIFIUM SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITIFIUM SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIFIUM) NON CONTIENE UN CODICE NAZIONALE INDICATO');
      END IF;
    END IF;

    IF INCATASTO_TERRENI IS NOT NULL THEN
      OPEN C23;  FETCH C23 INTO TMP;  IF C23%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C23;
      OPEN C24;  FETCH C24 INTO TMP;  IF C24%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C24;

      IF UPOK=0 THEN
        UPDATE SITITRKC SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITITRKC SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITITRKC SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
        UPDATE SITIFRAZ SET COD_NAZIONALE = 'TEMP' WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
        UPDATE SITIFRAZ SET COD_NAZIONALE = INCOD_NAZ_ORIG WHERE COD_NAZIONALE = INCOD_NAZ_DEST;
        UPDATE SITIFRAZ SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = 'TEMP';
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITITRKC) NON CONTIENE UN CODICE NAZIONALE INDICATO');
      END IF;
    END IF;
-- RICALCOLO ANOMALIE
    OPEN C27;
    LOOP
      FETCH C27 INTO FOGLIO;
      EXIT WHEN C27%NOTFOUND;
      SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ_ORIG, FOGLIO);
      SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ_DEST, FOGLIO);
    END LOOP;
    CLOSE C27;
  ELSE
    RAISE_APPLICATION_ERROR(-20001,'ERRORE: I CODICI NAZIONALI INDICATI HANNO CATASTO DIVERSO');
  END IF;

END INVERSIONE_COMUNE;

PROCEDURE SPOSTA_FOGLIO_SU_NUOVO_COMUNE (
      INCOD_NAZ_ORIG      IN  VARCHAR2,
      INCOD_NAZ_DEST      IN  VARCHAR2,
      INTAVOLA            IN  NUMBER,
      INCONS_TERRENI      IN  NUMBER,
      INCONS_UIU          IN  NUMBER,
      INUNAR              IN  NUMBER,
      INGIS               IN  NUMBER,
      INUIU               IN  NUMBER,
      INSTRADE            IN  NUMBER,
      INFIUMI             IN  NUMBER,
      INCATASTO_TERRENI   IN  NUMBER
)
IS
-- GIS
  CURSOR C1 IS SELECT 1 FROM SITICENT WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND TAVOLA = INTAVOLA AND ROWNUM=1;
  CURSOR C2 IS SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND TAVOLA = INTAVOLA AND ROWNUM=1;
  CURSOR C3 IS SELECT 1 FROM SITIPART WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND TAVOLA = INTAVOLA AND ROWNUM=1;
  CURSOR C4 IS SELECT 1 FROM SITISUOLO WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND TAVOLA = INTAVOLA AND ROWNUM=1;
  CURSOR C5 IS SELECT 1 FROM SITIFOTC WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND TAVOLA = INTAVOLA AND ROWNUM=1;
-- CONSISTENZA TERRENI
  CURSOR C6 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CONS_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_UFRE_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1)) WHERE ROWNUM=1;
-- CONSISTENZA FABBRICATI
  CURSOR C7 IS SELECT 1 FROM ((SELECT 1 FROM CONS_CSUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1) UNION ALL (SELECT 1 FROM CONS_URUI_TAB WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1)) WHERE ROWNUM=1;
-- UNITÀ ARBOREE
  CURSOR C8 IS SELECT 1 FROM SITIUNAR WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1;
-- UIU
  CURSOR C9 IS SELECT 1 FROM SITIUIU WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1;
-- STRADE
  CURSOR C10 IS SELECT 1 FROM SITISTRA WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1;
-- FIUMI
  CURSOR C11 IS SELECT 1 FROM SITIFIUM WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1;
-- CATASTO TERRENI
  CURSOR C12 IS SELECT 1 FROM SITITRKC WHERE COD_NAZIONALE = INCOD_NAZ_DEST AND FOGLIO = INTAVOLA AND ROWNUM=1;

  CURSOR C13 IS SELECT FLAG_CATA FROM SITICOMU WHERE COD_NAZIONALE = INCOD_NAZ_ORIG;
  CURSOR C14 IS SELECT FLAG_CATA FROM SITICOMU WHERE COD_NAZIONALE = INCOD_NAZ_DEST;

  UPOK   NUMBER(9):=0;
  TMP    NUMBER(9);
  FLAG_CATA_ORIG  NUMBER(1);
  FLAG_CATA_DEST  NUMBER(1);
BEGIN

  OPEN C13;   FETCH C13 INTO FLAG_CATA_ORIG;   CLOSE C13;
  OPEN C14;   FETCH C14 INTO FLAG_CATA_DEST;   CLOSE C14;

  IF FLAG_CATA_ORIG = FLAG_CATA_DEST THEN
    IF INCONS_TERRENI IS NOT NULL THEN
      OPEN C6;  FETCH C6 INTO TMP;  IF C6%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C6;

      IF UPOK=0 THEN
        UPDATE CONS_CONS_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
        UPDATE CONS_UFRE_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (CONS_CONS_TAB, CONS_UFRE_TAB) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;

    IF INCONS_UIU IS NOT NULL THEN
      OPEN C7;  FETCH C7 INTO TMP;  IF C7%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C7;

      IF UPOK=0 THEN
        UPDATE CONS_CSUI_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
        UPDATE CONS_URUI_TAB SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (CONS_CSUI_TAB, CONS_URUI_TAB) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;

    IF INUNAR IS NOT NULL THEN
      OPEN C8;  FETCH C8 INTO TMP;  IF C8%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C8;

      IF UPOK=0 THEN
        UPDATE SITIUNAR SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIUNAR) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;

    IF INGIS IS NOT NULL THEN
      OPEN C1;  FETCH C1 INTO TMP;  IF C1%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C1;
      OPEN C2;  FETCH C2 INTO TMP;  IF C2%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C2;
      OPEN C3;  FETCH C3 INTO TMP;  IF C3%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C3;
      OPEN C4;  FETCH C4 INTO TMP;  IF C4%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C4;
      OPEN C5;  FETCH C5 INTO TMP;  IF C5%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C5;

      IF UPOK = 0 THEN
        UPDATE SITICENT SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND TAVOLA = INTAVOLA;
        UPDATE SITIFGLC SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND TAVOLA = INTAVOLA;
        UPDATE SITIPART SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND TAVOLA = INTAVOLA;
        UPDATE SITISUOLO SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND TAVOLA = INTAVOLA;
        UPDATE SITIFOTC SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND TAVOLA = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: ALMENO UNA DELLE TABELLE DI DESTINAZIONE (SITICENT, SITIFGLC, SITIPART, SITISUOLO, SITIFOTC) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;

    IF INUIU IS NOT NULL THEN
      OPEN C9;  FETCH C9 INTO TMP;  IF C9%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C9;

      IF UPOK=0 THEN
        UPDATE SITIUIU SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIUIU) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;

    IF INSTRADE IS NOT NULL THEN
      OPEN C10;  FETCH C10 INTO TMP;  IF C10%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C10;

      IF UPOK=0 THEN
        UPDATE SITISTRA SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITISTRA) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;

    IF INFIUMI IS NOT NULL THEN
      OPEN C11;  FETCH C11 INTO TMP;  IF C11%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C11;

      IF UPOK=0 THEN
        UPDATE SITIFIUM SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITIFIUM) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;

    IF INCATASTO_TERRENI IS NOT NULL THEN
      OPEN C12;  FETCH C12 INTO TMP;  IF C12%NOTFOUND THEN TMP:=0; ELSE UPOK:=UPOK+1; END IF;  CLOSE C12;

      IF UPOK=0 THEN
        UPDATE SITITRKC SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
        UPDATE SITIFRAZ SET COD_NAZIONALE = INCOD_NAZ_DEST WHERE COD_NAZIONALE = INCOD_NAZ_ORIG AND FOGLIO = INTAVOLA;
      ELSE
        RAISE_APPLICATION_ERROR(-20001,'ERRORE: LA TABELLA DI DESTINAZIONE (SITITRKC) CONTIENE GIÀ LA TAVOLA INDICATA');
      END IF;
    END IF;
-- RICALCOLO ANOMALIE
    SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ_ORIG, INTAVOLA);
    SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ_DEST, INTAVOLA);
  ELSE
    RAISE_APPLICATION_ERROR(-20001,'ERRORE: I CODICI NAZIONALI INDICATI HANNO CATASTO DIVERSO');
  END IF;
END SPOSTA_FOGLIO_SU_NUOVO_COMUNE;

PROCEDURE CAMBIA_TAVOLA (
      INCOD_NAZ           IN  VARCHAR2,
      INTAVOLA_ORIG       IN  NUMBER,
      INFOGLIO_ORIG       IN  NUMBER,
      INFOGLIO_DEST       IN  NUMBER,
      INGIS               IN  NUMBER
)
IS
-- GIS
  CURSOR C3 IS SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO=INFOGLIO_ORIG AND TAVOLA = INTAVOLA_ORIG AND ROWNUM=1;

  UPOK   NUMBER(9):=0;
  TMP    NUMBER(9);
  FLAG_CAT NUMBER(1);
BEGIN

  SELECT FLAG_CATA INTO FLAG_CAT FROM SITICOMU WHERE COD_NAZIONALE=INCOD_NAZ;
  IF FLAG_CAT<>1 THEN
    RAISE_APPLICATION_ERROR(-20001,'ERRORE: IL CATASTO NON È TAVOLARE');
    RETURN;
  END IF;

  IF INGIS IS NOT NULL THEN
    OPEN C3;  FETCH C3 INTO TMP;  IF C3%NOTFOUND THEN UPOK:=UPOK+1; ELSE TMP:=0; END IF;  CLOSE C3;

    IF UPOK = 0 THEN
      UPDATE SITICENT SET FOGLIO = INFOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO=INFOGLIO_ORIG AND TAVOLA = INTAVOLA_ORIG;

      UPDATE SITIFGLC SET FOGLIO = INFOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO=INFOGLIO_ORIG AND TAVOLA = INTAVOLA_ORIG;

      UPDATE SITIPART SET FOGLIO = INFOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO=INFOGLIO_ORIG AND TAVOLA = INTAVOLA_ORIG;

      UPDATE SITISUOLO SET FOGLIO = INFOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO=INFOGLIO_ORIG AND TAVOLA = INTAVOLA_ORIG;

      UPDATE SITIFOTC SET FOGLIO = INFOGLIO_DEST WHERE COD_NAZIONALE = INCOD_NAZ AND FOGLIO=INFOGLIO_ORIG AND TAVOLA = INTAVOLA_ORIG;

-- RICALCOLO ANOMALIE
      SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ, INFOGLIO_ORIG);
      SITIUTILS.AGG_ANOM_REFR(INCOD_NAZ, INFOGLIO_DEST);
    ELSE
      RAISE_APPLICATION_ERROR(-20001,'ERRORE: FOGLIO/TAVOLA DI ORIGINE INESISTENTI');
    END IF;
  END IF;

END CAMBIA_TAVOLA;

END;
/


DROP PACKAGE BODY SITI_H501.SITIEDI_PCK;

CREATE OR REPLACE PACKAGE body SITI_H501.sitiedi_pck AS

  cursor curVani(cn varchar2, fg number, par varchar2, subo varchar2, un number, dt date) is
    select * from sitiedi_vani
      where cod_nazionale = cn
        and foglio = fg
        and particella = par
        and sub = subo
        and unimm = un
        and DATA_INIZIO_VAL <= dt
        and DATA_FINE_VAL >= dt
 order by ambiente;

 --
 function calc_supe_abitazioni(cn varchar2, fg number, par varchar2, subo varchar2, un number, dt date := sysdate) return number is
  ret    number := null;
    supVano  number;
    supPrinc number := 0;
    coef1   number;
    coef2   number;
  begin

  for rec in curVani(cn, fg, par, subo, un, dt) loop
     begin

       select COEF_FACTOR, COEF_FACTOR2
         into coef1, coef2
         from sitiedi_supe_codes
        where FK_TIPOLOGIA = 1
          and INTERNAL_CODE = rec.ambiente;

      exception when no_data_found then
       raise_application_error(-20001, 'Codice ambiente [' || rec.ambiente || '] non valido per la tipologia [1]');
      end;

      supVano := rec.supe_ambiente * coef1;

      if rec.ambiente = 'A' then
       supPrinc := supPrinc + supVano;
      end if;

   if ret is null then
       ret := supVano;
      else
       ret := ret + supVano;
      end if;

    end loop;

  /* La superficie  data dalla minore tra
     * la somma delle superfici calcolate ed
     * il 150% delle superfici dei locali principali.
     */
  supPrinc := supPrinc * 1.5;
    if supPrinc < ret then
   ret := supPrinc;
    end if;

    return round(ret);

  end calc_supe_abitazioni;

 --
 function calc_supe_uffici(cn varchar2, fg number, par varchar2, subo varchar2, un number, dt date := sysdate) return number is
  ret    number := null;
    supVano  number;
    coef1   number;
    coef2   number;
  begin

  for rec in curVani(cn, fg, par, subo, un, dt) loop
     begin

       select COEF_FACTOR, COEF_FACTOR2
         into coef1, coef2
         from sitiedi_supe_codes
        where FK_TIPOLOGIA = 2
          and INTERNAL_CODE = rec.ambiente;

      exception when no_data_found then
       raise_application_error(-20001, 'Codice ambiente [' || rec.ambiente || '] non valido per la tipologia [2]');
      end;

      supVano := rec.supe_ambiente * coef1;

   if ret is null then
       ret := supVano;
      else
       ret := ret + supVano;
      end if;

    end loop;

    return round(ret);

  end calc_supe_uffici;

 --
 function calc_supe_garage(cn varchar2, fg number, par varchar2, subo varchar2, un number, dt date := sysdate) return number is
  ret    number := null;
    supVano  number;
    supPrinc number := 0;
    supF      number := 0;
    coef1   number;
    coef2   number;
  begin

  for rec in curVani(cn, fg, par, subo, un, dt) loop
     begin

       select COEF_FACTOR, COEF_FACTOR2
         into coef1, coef2
         from sitiedi_supe_codes
        where FK_TIPOLOGIA = 3
          and INTERNAL_CODE = rec.ambiente;

      exception when no_data_found then
       raise_application_error(-20001, 'Codice ambiente [' || rec.ambiente || '] non valido per la tipologia [3]');
      end;

   if rec.ambiente = 'F' then
       supVano := 0;
      else
       supVano := rec.supe_ambiente * coef1;
      end if;

      if rec.ambiente = 'A' or rec.ambiente = 'H' then
       supPrinc := supPrinc + supVano;
      end if;

   if ret is null then
       ret := supVano;
      else
       ret := ret + supVano;
      end if;

    end loop;

  /* Se c' dell'area di tipo F devo fare 1 distinguo:
     * Fino a A + H si usa coef1, oltre si usa coef2
     */
    if supF > 0 then
      select COEF_FACTOR, COEF_FACTOR2
        into coef1, coef2
        from sitiedi_supe_codes
       where FK_TIPOLOGIA = 3
         and INTERNAL_CODE = 'F';

     if supF < supPrinc then
       ret := ret + (supF * coef1);
      else
       ret := ret + (supPrinc * coef1);

        supF := supF - supPrinc;
        ret := ret + (supPrinc * coef2);
      end if;
    end if;

  /* La superficie  data dalla minore tra
     * la somma delle superfici calcolate ed
     * il 150% delle superfici dei locali principali + accessori diretti.
     */
  supPrinc := supPrinc * 1.5;
    if supPrinc < ret then
   ret := supPrinc;
    end if;

    return round(ret);

  end calc_supe_garage;

 --
 function calc_supe_negozi(cn varchar2, fg number, par varchar2, subo varchar2, un number, dt date := sysdate) return number is
  ret    number := null;
    supVano  number;
    coef1   number;
    coef2   number;
  begin

  for rec in curVani(cn, fg, par, subo, un, dt) loop
     begin

       select COEF_FACTOR, COEF_FACTOR2
         into coef1, coef2
         from sitiedi_supe_codes
        where FK_TIPOLOGIA = 4
          and INTERNAL_CODE = rec.ambiente;

      exception when no_data_found then
       raise_application_error(-20001, 'Codice ambiente [' || rec.ambiente || '] non valido per la tipologia [4]');
      end;

      supVano := rec.supe_ambiente * coef1;

   if ret is null then
       ret := supVano;
      else
       ret := ret + supVano;
      end if;

    end loop;

    return round(ret);

  end calc_supe_negozi;

  function calc_supe(cn varchar2, fg number, par varchar2, subo varchar2, un number, dt date := sysdate) return number is
   cursor tipo is select t.fk_tipologia
                     from sitiuiu u, SITIEDI_TP_IMM_CAT t
                    where u.cod_nazionale = cn
                      and u.foglio = fg
                      and u.particella = par
                      and u.sub = subo
                      and u.unimm = un
                      and dt between u.data_inizio_val and data_fine_val
                      and t.categoria = u.categoria;

   tp             SITIEDI_TP_IMM_CAT.fk_tipologia%type;
    ret            number;

  begin

  open tipo;

   if tipo%notfound then
    ret := 0;
   else
    fetch tipo into tp;

     if tp = 1 then
      ret := calc_supe_abitazioni(cn, fg, par, subo, un, dt);
     elsif tp = 2 then
      ret := calc_supe_uffici(cn, fg, par, subo, un, dt);
     elsif tp = 3 then
      ret := calc_supe_garage(cn, fg, par, subo, un, dt);
     elsif tp = 4 then
      ret := calc_supe_negozi(cn, fg, par, subo, un, dt);
     end if;

   end if;

   close tipo;

    return ret;

  end calc_supe;

  ----------------------------
  procedure aggiorna_supe_modelli(cn varchar2, fg number, par varchar2, subo varchar2, un number, dt date := sysdate) is
    supe  number;
  begin
    select sum(v.supe_ambiente * c.coef_supe_modelli) into supe
      from sitiedi_uiu_ext u, sitiedi_vani v, sitiedi_supe_codes c
     where u.cod_nazionale = cn and u.foglio = fg and u.particella = par and u.sub = subo and u.unimm = un
       and dt between u.data_inizio_val and u.data_fine_val
       and v.cod_nazionale = cn and v.foglio = fg and v.particella = par and v.sub = subo and v.unimm = un
       and dt between v.data_inizio_val and v.data_fine_val
       and c.fk_tipologia = u.fk_tipologia
       and c.internal_code = v.ambiente;

    update sitiuiu set supe_modelli = supe
     where cod_nazionale = cn and foglio = fg and particella = par and sub = subo and unimm = un
       and dt between data_inizio_val and data_fine_val;

  end aggiorna_supe_modelli;


  -- a.caleffi 2010-01-07 vedi nota ACALEFFI_NOTE
  FUNCTION get_obj_type (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_vano                               NUMBER DEFAULT NULL
  )
    RETURN VARCHAR IS
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    IF p_unimm IS NULL THEN                                                                               -- PARTICELLA
      m_obj_type := 'P';
    ELSIF p_unimm IS NOT NULL AND p_vano IS NULL THEN                                                             -- UIU
      m_obj_type := 'U';
    ELSE
      -- VANO
      m_obj_type := 'V';
    END IF;

    RETURN m_obj_type;
  END get_obj_type;


  -- a.caleffi 2010-01-07 vedi nota ACALEFFI_NOTE
  FUNCTION get_obj_id (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_vano                               NUMBER DEFAULT NULL
  )
    RETURN NUMBER IS
    m_obj_id                      NUMBER;
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm, p_vano);

    IF TRIM (m_obj_type) = 'P' THEN
    -- PARTICELLA
      SELECT DISTINCT id_particella
                 INTO m_obj_id
                 FROM sititrkc
                WHERE cod_nazionale = p_codnaz AND foglio = p_foglio AND particella = p_particella AND sub = p_sub;

  ELSIF TRIM (m_obj_type) = 'U' THEN
    -- UIU
      SELECT DISTINCT id_cata_uiu
                 INTO m_obj_id
                 FROM sitiuiu
                WHERE cod_nazionale = p_codnaz AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
                      AND unimm = p_unimm;

  ELSE
      -- VANO
      SELECT DISTINCT id_cata_vano
                 INTO m_obj_id
                 FROM sitiedi_vani
                WHERE cod_nazionale = p_codnaz AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
                      AND unimm = p_unimm AND vano = p_vano;
    END IF;

    RETURN m_obj_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
  END get_obj_id;


  -- a.caleffi 2010-01-07 vedi nota ACALEFFI_NOTE
  FUNCTION get_superficie_uiu (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
    p_dt                                 DATE
  )
    RETURN NUMBER IS
    m_sup_cat                     NUMBER := 0;
    m_sup_modelli                 NUMBER := 0;
    m_sup_vani                    NUMBER := 0;
    m_num_vani                    NUMBER := 0;
    m_sup_uiu                     NUMBER := 0;
  BEGIN
    BEGIN
      SELECT NVL (u.sup_cat, 0) AS sup_cat,
             NVL (u.supe_modelli, 0) AS supe_modelli,
             NVL (v1.supe_vani, 0) AS supe_vani,
             NVL (v1.num_vani, 0) AS num_vani
        INTO m_sup_cat,
             m_sup_modelli,
             m_sup_vani,
             m_num_vani
        FROM sitiuiu u
             LEFT JOIN
             (SELECT   v.cod_nazionale,
                       v.foglio,
                       v.particella,
                       v.sub,
                       v.unimm,
                       SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0)) AS supe_vani,
                       COUNT (*) AS num_vani
                  FROM sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
                 WHERE v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio AND v.particella = e.particella
                       AND v.sub = e.sub AND v.unimm = e.unimm AND e.data_inizio_val <= p_dt AND e.data_fine_val >= p_dt
                       AND v.data_inizio_val <= p_dt AND v.data_fine_val >= p_dt AND c.fk_tipologia = e.fk_tipologia
                       AND c.internal_code = v.ambiente
              GROUP BY v.cod_nazionale, v.foglio, v.particella, v.sub, v.unimm) v1
             ON u.cod_nazionale = v1.cod_nazionale AND u.foglio = v1.foglio AND u.particella = v1.particella
                AND u.sub = v1.sub AND u.unimm = v1.unimm
       WHERE u.cod_nazionale = p_codnaz AND u.foglio = p_foglio AND u.particella = p_particella AND u.sub = p_sub
             AND u.unimm = p_unimm AND u.data_inizio_val <= p_dt AND u.data_fine_val >= p_dt;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_sup_cat := -1;
        m_sup_modelli := 0;
        m_sup_vani := 0;
        m_num_vani := 0;
    END;

  IF m_sup_cat = -1 THEN

   m_sup_uiu := -1;

  ELSE
     IF m_num_vani > 0 THEN
       IF m_sup_vani > 0 THEN
         m_sup_uiu := m_sup_vani;
       ELSE
         IF m_sup_modelli > 0 THEN
           m_sup_uiu := m_sup_modelli;
         ELSE
           m_sup_uiu := m_sup_cat;
         END IF;
       END IF;
     ELSE
       IF m_sup_modelli > 0 THEN
         m_sup_uiu := m_sup_modelli;
       ELSE
         m_sup_uiu := m_sup_cat;
       END IF;
     END IF;
  END IF;

    RETURN m_sup_uiu;
  END get_superficie_uiu;

  -- a.caleffi 2010-01-07 vedi nota ACALEFFI_NOTE
  FUNCTION get_superficie_part (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_dt                                 DATE
  )
    RETURN NUMBER IS
    m_sup_part                     NUMBER := 0;
  BEGIN
    BEGIN

   SELECT NVL (area_part, 0) AS area
     INTO m_sup_part
     FROM sititrkc a
    WHERE a.cod_nazionale = p_codnaz AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub
      AND a.data_aggi <= p_dt AND a.data_fine >= p_dt;

    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_sup_part := -1;
    END;

  return m_sup_part;

  END get_superficie_part;

  -- a.caleffi 2010-01-07 vedi nota ACALEFFI_NOTE
  FUNCTION get_sup_obj (p_obj_id NUMBER, p_obj_type VARCHAR2, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_suptot                      NUMBER := 0;
    m_exist                       NUMBER := -1;
  BEGIN
    BEGIN
      IF p_obj_type = 'P' THEN

    SELECT SUM (get_superficie_part (cod_nazionale, foglio, particella, sub, p_date)),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM sititrkc
         WHERE data_aggi <= p_date AND data_fine >= p_date AND id_particella = p_obj_id;

      ELSIF p_obj_type = 'U' THEN

        SELECT SUM (get_superficie_uiu (cod_nazionale, foglio, particella, sub, unimm, p_date)),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM (SELECT DISTINCT cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm
                           FROM sitiuiu
                          WHERE id_cata_uiu = p_obj_id);

      ELSIF p_obj_type = 'V' THEN

        SELECT SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0)),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
         WHERE v.id_cata_vano = p_obj_id AND v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio
               AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm AND e.data_inizio_val <= p_date
               AND e.data_fine_val >= p_date AND v.data_inizio_val <= p_date AND v.data_fine_val >= p_date
               AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;

      END IF;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_exist := -1;
        m_suptot := 0;
    END;

    IF m_exist = 0 THEN
      m_exist := -1;
    END IF;

    IF m_exist = -1 THEN
      m_suptot := -1;
    END IF;

    RETURN m_suptot;
  END get_sup_obj;


  -- a.caleffi 2010-01-07 ACALEFFI_NOTE
  -- tutte le funzioni contrassegnate da ACALEFFI_NOTE sono state copiate
  -- dal package TITOLI_PCK per far si' che sitimodelli possa calcolare la superficie di un vano
  -- in modo corretto e non usare le funzioni del package SITIEDI_PCK in quanto sono cablati i
  -- codici della tipologia e i codici INTERNAL_CODE

END sitiedi_pck;
/


DROP PACKAGE BODY SITI_H501.SITIFILE;

CREATE OR REPLACE PACKAGE BODY SITI_H501.sitifile IS
  -- Private type declarations
  TYPE refcursor IS REF CURSOR;

---------------------------------------------------------------
  PROCEDURE valida_atti_da_documento (iddoc IN NUMBER) IS
    atto_valido   CHAR;
  BEGIN
    FOR c IN (SELECT t.fkid_atto id_atto, a.valido
                FROM sitifile_atti_doc t, sitifile_atti a
               WHERE t.fkid_doc = iddoc AND a.pkid_atto = t.fkid_atto) LOOP
      atto_valido := sitifile.valida_atto (c.id_atto);

      IF atto_valido <> c.valido THEN
        UPDATE sitifile_atti p
           SET p.valido = atto_valido
         WHERE p.pkid_atto = c.id_atto;
      END IF;
    END LOOP;
  END valida_atti_da_documento;

---------------------------------------------------------------
  PROCEDURE valida_atti (idatto IN NUMBER) IS
    atto_valido   CHAR;
  BEGIN
    atto_valido := sitifile.valida_atto (idatto);

    UPDATE sitifile_atti p
       SET p.valido = atto_valido
     WHERE p.pkid_atto = idatto;
  END valida_atti;

  -- Function and procedure implementations
---------------------------------------------------------------
  FUNCTION valida_atto (idatto IN NUMBER)
    RETURN CHAR IS
    CURSOR tdoc IS
      SELECT a.pkid_atto id_atto, ta.fkid_tipo_doc id_tipo_doc, ta.obbligatorio obb, ta.created_autom
        FROM sitifile_atti a, sitifile_tipi_atto_doc ta
       WHERE a.pkid_atto = idatto
         AND a.fkid_tipo_atto = ta.fkid_tipo_atto
         AND ta.data_fine_val = TO_DATE ('99991231', 'YYYYMMDD');

    CURSOR dcur (p_id_tipo_doc NUMBER) IS
      SELECT d.valido
        FROM sitifile_documenti d, sitifile_atti_doc t
       WHERE t.fkid_atto = idatto
         AND t.fkid_doc = d.pkid_doc
         AND t.data_fine_val = TO_DATE ('99991231', 'yyyymmdd')
         AND d.fkid_tipo_doc = p_id_tipo_doc;

    --d            dcur%ROWTYPE;
    d_is_valid   char(1);
    c            refcursor;
    num          NUMBER;
    vincoli      sitifile_tipi_atto.vincoli_logici%TYPE;
    rec_tp_doc   sitifile_tipidoc%ROWTYPE;
  BEGIN
    SELECT UPPER (ta.vincoli_logici)
      INTO vincoli
      FROM sitifile_atti a, sitifile_tipi_atto ta
     WHERE a.pkid_atto = idatto AND a.fkid_tipo_atto = ta.pkid_tipo;

    vincoli := REPLACE (vincoli, '&&', ' and ');
    vincoli := REPLACE (vincoli, '||', ' or ');
    vincoli := REPLACE (vincoli, '!', ' not ');

    FOR docrow IN tdoc LOOP
      IF docrow.created_autom != 'Y' THEN
        OPEN dcur (docrow.id_tipo_doc);

        FETCH dcur INTO d_is_valid;

        IF dcur%NOTFOUND THEN
          IF docrow.obb != 'N' THEN
            RETURN 'N';
          ELSE
            vincoli := REPLACE (vincoli, 'V[' || docrow.id_tipo_doc || ']', '1=2');
          END IF;
        ELSE
          -- TOM: 08/01/2009: Perchè l'atto sia valido, tutti i documenti che contiene devono essere validi (anche se non obbligatori)
          --IF docrow.obb != 'N' AND d_is_valid = 'N' THEN
          IF d_is_valid = 'N' THEN
            RETURN 'N';
          END IF;

          IF d_is_valid != 'N' THEN
            vincoli := REPLACE (vincoli, 'V[' || docrow.id_tipo_doc || ']', '1=1');
          ELSE
            vincoli := REPLACE (vincoli, 'V[' || docrow.id_tipo_doc || ']', '1=2');
          END IF;
        END IF;

        CLOSE dcur;
      END IF;
    END LOOP;

    IF vincoli IS NOT NULL THEN
      BEGIN
        OPEN c FOR 'select 1 from dual where ' || vincoli;

        FETCH c
         INTO num;

        IF c%NOTFOUND THEN
          RETURN 'N';
        END IF;

        CLOSE c;
      EXCEPTION
        WHEN OTHERS THEN
          raise_application_error (-20001, 'Errore... vincoli= ' || vincoli);
      END;
    END IF;

    RETURN 'S';
  END;

  --------------
  FUNCTION inserisci_atto (id_tipo_atto IN NUMBER, user_name IN VARCHAR2)
    RETURN NUMBER IS
    act_id   sitifile_atti.pkid_atto%TYPE;
  BEGIN
    INSERT INTO sitifile_atti
                (pkid_atto, fkid_tipo_atto, data_aggiornamento, utente_ins, data_ins, valido
                )
         VALUES (sitifile_atti_seq.NEXTVAL, id_tipo_atto, SYSDATE, user_name, SYSDATE, 'N'
                )
      RETURNING pkid_atto
           INTO act_id;

    valida_atti (act_id);
    RETURN act_id;
  END inserisci_atto;

  --------------
  procedure inserisci_doc_in_atto(p_id_atto number, p_id_doc number, p_user varchar2) is
    id_tipo_atto  sitifile_tipi_atto.pkid_tipo%type;
    id_tipo_doc   sitifile_tipidoc.pkid_tipo_doc%type;
    cnt           pls_integer;
  begin
    select fkid_tipo_atto into id_tipo_atto from sitifile_atti where pkid_atto=p_id_atto;
    select fkid_tipo_doc into id_tipo_doc from sitifile_documenti where pkid_doc=p_id_doc;

    select count(*) into cnt
      from sitifile_tipi_atto_doc
     where fkid_tipo_atto = id_tipo_atto
       and fkid_tipo_doc = id_tipo_doc
       and data_inizio_val <= sysdate
       and data_fine_val >= sysdate;

    if (cnt = 0) then
      raise_application_error(-20001, 'Unsupported document type for this Act!');
    end if;

    insert into sitifile_atti_doc (FKID_ATTO, FKID_DOC, NOTE, UTENTE_INS, DATA_AGGIORNAMENTO, UTENTE_FINE, DATA_INIZIO_VAL, DATA_FINE_VAL)
      values (p_id_atto, p_id_doc, null, p_user, sysdate, null, sysdate, to_date('99991231', 'yyyymmdd'));

  end inserisci_doc_in_atto;

  --------------
  FUNCTION is_atto_valido (p_id_atto NUMBER)
    RETURN CHAR IS
    is_valido   sitifile_atti.valido%TYPE;
  BEGIN
    -- raise no_data_found se non trova nulla (ma e giusto)
    SELECT valido
      INTO is_valido
      FROM sitifile_atti
     WHERE pkid_atto = p_id_atto;

    IF is_valido = 'Y' THEN
      is_valido := 'S';
    END IF;

    RETURN is_valido;
  END is_atto_valido;

  --------------
  FUNCTION get_max_data_scadenza (p_pk_atto NUMBER, p_pk_tipo_doc NUMBER DEFAULT NULL)
    RETURN DATE IS
    dt   DATE;
  BEGIN
    IF (p_pk_tipo_doc IS NULL) THEN
          SELECT MAX (d.data_scadenza)
           INTO dt
           FROM sitifile_documenti d, sitifile_atti_doc ad
          WHERE ad.fkid_atto = p_pk_atto
            AND SYSDATE BETWEEN ad.data_inizio_val AND ad.data_fine_val
            AND d.pkid_doc = ad.fkid_doc
            AND SYSDATE BETWEEN d.data_inizio_val AND d.data_fine_val;
      ELSE
         SELECT MAX (d.data_scadenza)
           INTO dt
           FROM sitifile_documenti d, sitifile_atti_doc ad
          WHERE ad.fkid_atto = p_pk_atto
            AND SYSDATE BETWEEN ad.data_inizio_val AND ad.data_fine_val
            AND d.pkid_doc = ad.fkid_doc
            AND d.fkid_tipo_doc = p_pk_tipo_doc
            AND SYSDATE BETWEEN d.data_inizio_val AND d.data_fine_val;
    END IF;

    RETURN dt;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
  END get_max_data_scadenza;

  --------------
  FUNCTION has_documenti_scaduti (idatto NUMBER, datarif DATE DEFAULT SYSDATE) RETURN CHAR IS
    num   NUMBER;
    ret   CHAR   := 'N';
  BEGIN
    SELECT   COUNT (MAX (doc.data_scadenza))
        INTO num
        FROM sitifile_atti_doc ado, sitifile_documenti doc
       WHERE (ado.fkid_atto = idatto)
         AND (SYSDATE BETWEEN ado.data_inizio_val AND ado.data_fine_val)
         AND (doc.pkid_doc = ado.fkid_doc)
         AND (doc.data_scadenza IS NOT NULL)
         AND (SYSDATE BETWEEN doc.data_inizio_val AND doc.data_fine_val)
    GROUP BY doc.fkid_tipo_doc
      HAVING MAX (doc.data_scadenza) < datarif;

    IF (num > 0) THEN
      ret := 'Y';
    END IF;

    RETURN ret;
  END has_documenti_scaduti;


END sitifile;
/


DROP PACKAGE BODY SITI_H501.SITILOAD_UTILS;

CREATE OR REPLACE PACKAGE BODY SITI_H501.sitiload_utils AS

PROCEDURE FIRE_CENTROIDE_INSERITO(CF IN VARCHAR2, FO IN NUMBER,PA IN VARCHAR2,SU IN VARCHAR2)
IS
	CURSOR CIDL IS SELECT ID_LAV FROM SITILISTALAV WHERE PROV_RIF='NO-GIS';
	IDLAV_NOGIS NUMBER(9);
	CURSOR C2 IS SELECT * FROM SITIPLAV WHERE COD_NAZIONALE=CF AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND LAST=1;
  IDL2 NUMBER(9);
BEGIN
	FOR CID IN CIDL LOOP
    IDLAV_NOGIS:=CID.ID_LAV;

		FOR C2R IN C2 LOOP
			--SE SONO QUI, è PERCHè UN CENTROIDE è STATO INSERITO
			IF C2R.ID_LAV = IDLAV_NOGIS THEN	-- E' SULL'ELENCO I
				IF C2R.FLAG_MOTI>0 THEN	--E' sospesa la metto lavorata
					UPDATE SITIPLAV SET FLAG_MOTI=0,DESC_MOTI=NULL,DATASOSP=NULL,UTENTESOSP=NULL,DATA_LAV=SYSDATE,UTENTE='LOADFONTE',NOTE='ARRIVA DA FONTE ESTERNA'
					WHERE COD_NAZIONALE=C2R.COD_NAZIONALE AND FOGLIO=C2R.FOGLIO AND PARTICELLA=C2R.PARTICELLA AND SUB=C2R.SUB
					AND ID_LAV=C2R.ID_LAV AND LAST=1;
        ELSIF C2R.DATA_LAV IS NULL THEN --E' DA LAVORARE MA QUALCUNO L'HA GIà LAVORATA
					UPDATE SITIPLAV SET FLAG_MOTI=0,DESC_MOTI=NULL,DATASOSP=NULL,UTENTESOSP=NULL,DATA_LAV=SYSDATE,UTENTE='LOADFONTE',NOTE='LAVORATA DA FONTE ESTERNA'
					WHERE COD_NAZIONALE=C2R.COD_NAZIONALE AND FOGLIO=C2R.FOGLIO AND PARTICELLA=C2R.PARTICELLA AND SUB=C2R.SUB
					AND ID_LAV=C2R.ID_LAV AND LAST=1;
				END IF;
			ELSE -- E' in carico a degli utenti
				IF C2R.FLAG_MOTI IN (4,13,14) THEN	--E' sospesa I,K,L la metto da lavorare
          IDL2:=C2R.ID_LAV;

					UPDATE SITIPLAV SET FLAG_MOTI=0,DESC_MOTI=NULL,DATASOSP=NULL,UTENTESOSP=NULL,DATA_LAV=NULL,NOTE='SBLOCCATA CON GIS'
					WHERE COD_NAZIONALE=C2R.COD_NAZIONALE AND FOGLIO=C2R.FOGLIO AND PARTICELLA=C2R.PARTICELLA AND SUB=C2R.SUB
					AND ID_LAV=C2R.ID_LAV AND LAST=1;
				END IF;
			END IF;
    END LOOP;

  END LOOP;
END FIRE_CENTROIDE_INSERITO;

PROCEDURE ASSEGNACODICED(CF IN VARCHAR2, FO IN NUMBER) IS
BEGIN
  UPDATE SITIPLAV SET FLAG_MOTI=8,DESC_MOTI='ACCERTATO D DA BACKOFFICE',DATASOSP=sysdate,UTENTESOSP='BACKOFFICE',DATA_LAV=SYSDATE,UTENTE='BACKOFFICE',NOTE=NULL
  WHERE COD_NAZIONALE=CF AND FOGLIO=FO AND ID_LAV=(SELECT ID_LAV FROM SITILISTALAV WHERE PROV_RIF='NO-GIS') AND LAST=1 AND ((DATASOSP IS NOT NULL AND FLAG_MOTI IN (4,13,14)) OR (DATA_LAV IS NULL) );
END;

PROCEDURE ASSEGNACODICER(CF IN VARCHAR2, FO IN NUMBER) IS
BEGIN
  UPDATE SITIPLAV SET FLAG_MOTI=6,DESC_MOTI='ACCERTATO R DA BACKOFFICE',DATASOSP=sysdate,UTENTESOSP='BACKOFFICE',DATA_LAV=SYSDATE,UTENTE='BACKOFFICE',NOTE=NULL
  WHERE COD_NAZIONALE=CF AND FOGLIO=FO AND ID_LAV=(SELECT ID_LAV FROM SITILISTALAV WHERE PROV_RIF='NO-GIS') AND LAST=1 AND ((DATASOSP IS NOT NULL AND FLAG_MOTI IN (4,13,14)) OR (DATA_LAV IS NULL) );
END;

PROCEDURE ASSEGNACODICEDISPO(CF IN VARCHAR2, FO IN NUMBER) IS
BEGIN
	UPDATE SITIPLAV SET FLAG_MOTI=4,DESC_MOTI=NULL,DATASOSP=sysdate,UTENTESOSP='BACKOFFICE',DATA_LAV=SYSDATE,UTENTE='BACKOFFICE',NOTE='FOGLIO ACCERTATO DISPONIBILE'
  WHERE COD_NAZIONALE=CF AND FOGLIO=FO AND ID_LAV=(SELECT ID_LAV FROM SITILISTALAV WHERE PROV_RIF='NO-GIS') AND LAST=1 AND ((DATASOSP IS NOT NULL AND (FLAG_MOTI=8 OR FLAG_MOTI=6)));
END;

PROCEDURE SBLOCCAALLFOG(CF IN VARCHAR2, FO IN NUMBER) IS
BEGIN
  --SBLOCCO LE G
  UPDATE SITIPLAV SET FLAG_MOTI=0,DESC_MOTI=NULL,DATASOSP=NULL,UTENTESOSP=NULL,DATA_LAV=NULL,NOTE='LAVORATO FOGLIO DISCORDANTE B.O.'
  WHERE COD_NAZIONALE=CF AND FOGLIO=FO AND LAST=1 AND DATASOSP IS NOT NULL AND DATA_LAV IS NOT NULL AND FLAG_MOTI=3;
END;

PROCEDURE INSERISCI_PARTICELLA_I(CF IN VARCHAR2, FO IN NUMBER,PA IN VARCHAR2,SU IN VARCHAR2,UTE IN VARCHAR2,CAMPA IN NUMBER, SETTORE IN NUMBER) IS
  CURSOR CIDL IS SELECT ID_LAV FROM SITILISTALAV WHERE PROV_RIF='NO-GIS' AND CAMPAGNA=CAMPA;
  CURSOR CFOGLIO IS SELECT FLAG_STATO FROM SITIFGLC WHERE COD_NAZIONALE=CF AND TAVOLA=FO;
  CURSOR CCOMU IS SELECT ISOPR FROM SITICOMU WHERE COD_NAZIONALE=CF;
  IDL NUMBER(9);
  FS NUMBER(1);
  OPR NUMBER(1);
  SC NUMBER(2);
  SG NUMBER(2);
BEGIN
  SC := STATO_CENS(CF,FO,PA,SU,To_Date('99991231','YYYYMMDD'));
  SG := STATO_GIS(CF,FO,PA,SU,To_Date('99991231','YYYYMMDD'));

  IF (  SETTORE=3 AND (  SC != 2 OR SG = 0  )   OR  SG = 0 ) THEN
    IF SC != 2 THEN
      UPDATE SITIPLAV SET FLAG_MOTI=13,DESC_MOTI=NULL,NOTE='ACCERTATA K (FASE DI CARICAMENTO)',DATASOSP=SYSDATE,UTENTESOSP=UTE,DATA_LAV=SYSDATE,UTENTE=UTE
      WHERE
      COD_NAZIONALE=CF AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND ID_LAV IN
      ( SELECT ID_LAV FROM SITILISTALAV WHERE CAMPAGNA=CAMPA ) AND LAST=1 AND (DATA_LAV IS NULL OR UTENTE='DICH_PART');
    ELSE

      OPEN CFOGLIO;
      FETCH CFOGLIO INTO FS;
      CLOSE CFOGLIO;

      IF Nvl(FS,0)=0 THEN
        OPEN CIDL;
        FETCH CIDL INTO IDL;
        CLOSE CIDL;

        IF IDL IS NULL THEN
          INSERT INTO SITILISTALAV(COD_SETTORE,PROV_RIF,CAMPAGNA,DATA_IMMI_ELEN,DESCRIZIONE,TIPOLAVORAZIONE)
          VALUES(20,'NO-GIS',CAMPA,SYSDATE,Trim(To_Char(CAMPA)) || ' PARTICELLE I',3);

          OPEN CIDL;
          FETCH CIDL INTO IDL;
          CLOSE CIDL;
        END IF;

        OPEN CCOMU;
        FETCH CCOMU INTO OPR;
        IF CCOMU%NOTFOUND THEN OPR:=0; END IF;
        CLOSE CCOMU;

        IF OPR=0 OR SETTORE=1 THEN
          INSERISCI_PLAV(CF,FO,PA,SU,IDL,'NO-GIS',20,UTE,'N','Y');
        END IF;

        UPDATE SITIPLAV SET FLAG_MOTI=4,DESC_MOTI=NULL,NOTE='ACCERTATA I (FASE DI CARICAMENTO)',DATASOSP=SYSDATE,UTENTESOSP=UTE,DATA_LAV=SYSDATE,UTENTE=UTE
        WHERE
        COD_NAZIONALE=CF AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND ID_LAV IN
        ( SELECT ID_LAV FROM SITILISTALAV WHERE CAMPAGNA=CAMPA ) AND LAST=1 AND (DATA_LAV IS NULL OR UTENTE='DICH_PART');
      ELSIF FS=2 THEN
          UPDATE SITIPLAV SET FLAG_MOTI=6,DESC_MOTI=NULL,NOTE='ACCERTATA R (FASE DI CARICAMENTO)',DATASOSP=SYSDATE,UTENTESOSP=UTE,DATA_LAV=SYSDATE,UTENTE=UTE
          WHERE
          COD_NAZIONALE=CF AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND ID_LAV IN
          ( SELECT ID_LAV FROM SITILISTALAV WHERE CAMPAGNA=CAMPA ) AND LAST=1 AND (DATA_LAV IS NULL OR UTENTE='DICH_PART');
      ELSIF FS=1 THEN
        UPDATE SITIPLAV SET FLAG_MOTI=8,DESC_MOTI=NULL,NOTE='ACCERTATA D (FASE DI CARICAMENTO)',DATASOSP=SYSDATE,UTENTESOSP=UTE,DATA_LAV=SYSDATE,UTENTE=UTE
        WHERE
        COD_NAZIONALE=CF AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND ID_LAV IN
        ( SELECT ID_LAV FROM SITILISTALAV WHERE CAMPAGNA=CAMPA ) AND LAST=1 AND (DATA_LAV IS NULL OR UTENTE='DICH_PART');
      ELSE
        UPDATE SITIPLAV SET FLAG_MOTI=14,DESC_MOTI=NULL,NOTE='ACCERTATA L (FASE DI CARICAMENTO)',DATASOSP=SYSDATE,UTENTESOSP=UTE,DATA_LAV=SYSDATE,UTENTE=UTE
        WHERE
        COD_NAZIONALE=CF AND FOGLIO=FO AND PARTICELLA=PA AND SUB=SU AND ID_LAV IN
        ( SELECT ID_LAV FROM SITILISTALAV WHERE CAMPAGNA=CAMPA ) AND LAST=1 AND (DATA_LAV IS NULL OR UTENTE='DICH_PART');
      END IF;
    END IF;
  ELSE
    --NON è UNA I
    IF SG>0 THEN
      FIRE_CENTROIDE_INSERITO(CF,FO,PA,SU);
    END IF;
  END IF;

END INSERISCI_PARTICELLA_I;

END SITILOAD_UTILS;
/


DROP PACKAGE BODY SITI_H501.SITISTACK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.sitistack AS
  FUNCTION checkvia (pk NUMBER, aggrcode NUMBER)
    RETURN BOOLEAN IS
    ctrl   CHAR (1);
  BEGIN
    SELECT 'X'
      INTO ctrl
      FROM aggr_topo
     WHERE pkid_topo = pk AND aggr_code = aggr_code AND ROWNUM = 1;

    RETURN TRUE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN FALSE;
  END checkvia;

  FUNCTION checkcivico (pk NUMBER)
    RETURN BOOLEAN IS
    ctrl   CHAR (1);
  BEGIN
    SELECT 'X'
      INTO ctrl
      FROM aggr_localizza
     WHERE pkid_loc = pk;

    RETURN TRUE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN FALSE;
  END checkcivico;

-- RAISES -20010 IF NOT FOUND...
  FUNCTION getpkuiu (
    codnaz       VARCHAR2,
    foglio       NUMBER,
    particella   VARCHAR2,
    sub          VARCHAR2,
    unimm        NUMBER,
    p_attuale    NUMBER := 1
  )
    RETURN NUMBER IS
    ret   sitiuiu.pkid_uiu%TYPE;
    dtf   DATE;
  BEGIN
    IF p_attuale = 1 THEN
      SELECT pkid_uiu
        INTO ret
        FROM sitiuiu
       WHERE cod_nazionale = codnaz
         AND foglio = getpkuiu.foglio
         AND particella = getpkuiu.particella
         AND sub = getpkuiu.sub
         AND unimm = getpkuiu.unimm
         AND data_fine_val = TO_DATE ('99991231', 'YYYYMMDD');
    ELSE
      SELECT MAX (data_fine_val)
        INTO dtf
        FROM sitiuiu
       WHERE cod_nazionale = codnaz
         AND foglio = getpkuiu.foglio
         AND particella = getpkuiu.particella
         AND sub = getpkuiu.sub
         AND unimm = getpkuiu.unimm;

      SELECT pkid_uiu
        INTO ret
        FROM sitiuiu
       WHERE cod_nazionale = codnaz
         AND foglio = getpkuiu.foglio
         AND particella = getpkuiu.particella
         AND sub = getpkuiu.sub
         AND unimm = getpkuiu.unimm
         AND data_fine_val = dtf;
    END IF;

    RETURN ret;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      raise_application_error (-20010, 'UIU NON TROVATA!'); --return -1; --
  END getpkuiu;

  PROCEDURE processaindirizzi (pklav NUMBER, utente VARCHAR2, data DATE, faiscadere NUMBER) IS
    CURSOR curind IS
      SELECT *
        FROM sitistack_civi_uiu
       WHERE pkid = pklav
         AND ((faiscadere = 0 AND flag_stato IN ('1', '2')) OR (faiscadere = 1 AND flag_stato IN ('2', '3')));

    ctrl          CHAR (1);
    pkcivitouse   aggr_localizza.pkid_loc%TYPE;
    pkuiutouse    sitiuiu.pkid_uiu%TYPE;
    aggrcode      aggr_topo.aggr_code%TYPE;
   skipAddress   number:= 0;
  BEGIN
    FOR rec IN curind LOOP

    skipAddress := 0;

    SELECT aggr_code
        INTO aggrcode
        FROM aggr_localizza_types
       WHERE pkid_type = rec.pkid_type;

    begin
        IF faiscadere = 1 THEN
          pkuiutouse := getpkuiu (rec.cod_nazionale, rec.foglio, rec.particella, rec.sub, rec.unimm, 0);
        ELSE
          pkuiutouse := getpkuiu (rec.cod_nazionale, rec.foglio, rec.particella, rec.sub, rec.unimm, 1);
        END IF;
     exception when others then
      if SQLCODE = -20010 and rec.flag_stato IN ('2', '3') AND faiscadere = 1 then
        -- la uiu non ï¿½ stata trovata quindi non devo far scadere l'indirizzo
        skipAddress := 1;
      else
        raise_application_error (-20010, 'UIU NON TROVATA!');
      end if;
    end;

    if skipAddress = 0 then
        IF NOT checkvia (rec.pkid_stra, aggrcode) THEN
          raise_application_error (-20001, 'VIA NON TROVATA!');
        END IF;

        IF rec.pkid_civi IS NOT NULL THEN
          IF NOT checkcivico (rec.pkid_civi) THEN
            raise_application_error (-20002, 'CIVICO NON TROVATO!');
          END IF;

          pkcivitouse := rec.pkid_civi;
        ELSE
          BEGIN
            INSERT INTO aggr_localizza
                        (fkid_type, pkid_topo, cod_nazionale, nome, data_inizio_val,
                         data_fine_val, utente, shape
                        )
                 VALUES (rec.pkid_type, rec.pkid_stra, rec.cod_nazionale, rec.civico, data,
                         TO_DATE ('99991231', 'YYYYMMDD'), utente, NULL
                        )
              RETURNING pkid_loc
                   INTO pkcivitouse;
          EXCEPTION
            WHEN DUP_VAL_ON_INDEX THEN
              -- Ho + di una uiu associata ad un civico NUOVO...
              SELECT pkid_loc
                INTO pkcivitouse
                FROM aggr_localizza
               WHERE fkid_type = rec.pkid_type
                 AND pkid_topo = rec.pkid_stra
                 AND nome = rec.civico
                 AND data_fine_val = TO_DATE ('99991231', 'YYYYMMDD');
          END;
        END IF;

        IF rec.flag_stato = '0' THEN
          NULL;                                                                               -- RECORD NON MODIFICATO...
        END IF;

        IF rec.flag_stato IN ('2', '3') AND faiscadere = 1 THEN --and pkuiutouse <> -1 THEN
          UPDATE sitiloc_uiu
             SET data_fine_val = data
           WHERE pkid_loc = pkcivitouse
             AND pkid_uiu = pkuiutouse
             AND (scala = rec.scala OR (scala IS NULL AND rec.scala IS NULL))
             AND (piano = rec.piano OR (piano IS NULL AND rec.piano IS NULL))
             AND (interno = rec.interno OR (interno IS NULL AND rec.interno IS NULL))
             AND data_fine_val = TO_DATE ('99991231', 'YYYYMMDD');
        END IF;

        IF rec.flag_stato IN ('1', '2')  AND faiscadere = 0 THEN -- and pkuiutouse <> -1 THEN
          INSERT INTO sitiloc_uiu
                      (fkid_type, pkid_loc, pkid_uiu, data_inizio_val, data_fine_val, utente,
                       scala, piano, interno, principale, utente_fine
                      )
               VALUES (rec.pkid_type, pkcivitouse, pkuiutouse, data, TO_DATE ('99991231', 'YYYYMMDD'), utente,
                       rec.scala, rec.piano, rec.interno, rec.principale, NULL
                      );
        END IF;
    end if;
    END LOOP;
  END processaindirizzi;

  FUNCTION getstatotr (codnaz IN VARCHAR2, fog IN NUMBER, part IN VARCHAR2, subal IN VARCHAR2)
    RETURN VARCHAR2 IS
    CURSOR c1 IS
      SELECT   flag_lavo
          FROM sitifraz
         WHERE cod_nazionale = codnaz
           AND foglio = fog
           AND ((part_madre = part AND sub_madre = subal) OR (part_figlia = part AND sub_figlia = subal))
      ORDER BY data_lav DESC;

    flaglav   VARCHAR2 (1);
  BEGIN
    OPEN c1;

    FETCH c1
     INTO flaglav;

    IF c1%NOTFOUND THEN
      flaglav := ' ';
    END IF;

    CLOSE c1;

    RETURN flaglav;
  END getstatotr;

  FUNCTION getidtr (codnaz IN VARCHAR2, fog IN NUMBER, part IN VARCHAR2, subal IN VARCHAR2)
    RETURN NUMBER IS
    CURSOR c1 IS
      SELECT   id_trasf
          FROM sitifraz
         WHERE cod_nazionale = codnaz
           AND foglio = fog
           AND ((part_madre = part AND sub_madre = subal) OR (part_figlia = part AND sub_figlia = subal))
      ORDER BY data_lav DESC;

    idtr   NUMBER;
  BEGIN
    OPEN c1;

    FETCH c1
     INTO idtr;

    IF c1%NOTFOUND THEN
      idtr := 0;
    END IF;

    CLOSE c1;

    RETURN idtr;
  END getidtr;

  PROCEDURE stato_stack (
    codnaz    IN       VARCHAR2,
    fog       IN       NUMBER,
    part      IN       VARCHAR2,
    subal     IN       VARCHAR2,
    idtr      OUT      NUMBER,
    flaglav   OUT      VARCHAR2
  ) IS
    CURSOR c1 IS
      SELECT   id_trasf, flag_lavo
          FROM sitifraz
         WHERE cod_nazionale = codnaz
           AND foglio = fog
           AND ((part_madre = part AND sub_madre = subal) OR (part_figlia = part AND sub_figlia = subal))
      ORDER BY data_lav DESC;
  BEGIN
    OPEN c1;

    FETCH c1
     INTO idtr, flaglav;

    IF c1%NOTFOUND THEN
      idtr := 0;
      flaglav := ' ';
    END IF;

    CLOSE c1;
  END stato_stack;

  FUNCTION stato_fraz (idtr IN NUMBER)
    RETURN VARCHAR2 IS
    CURSOR c1 IS
      SELECT flag_lavo
        FROM sitifraz
       WHERE id_trasf = idtr AND ROWNUM = 1;

    retid   VARCHAR2 (1);
  BEGIN
    OPEN c1;

    FETCH c1
     INTO retid;

    IF c1%NOTFOUND THEN
      retid := ' ';
    END IF;

    CLOSE c1;

    RETURN retid;
  END stato_fraz;

  PROCEDURE testfraz (idtr IN NUMBER, retval OUT NUMBER) IS
    TYPE emptycur IS REF CURSOR;

    c1       emptycur;
    c2       emptycur;
    c3       emptycur;
    cf       VARCHAR2 (4);
    fo       NUMBER;
    pa       VARCHAR2 (5);
    su       VARCHAR2 (3);
    pcf      VARCHAR2 (4);
    pfo      NUMBER;
    ppa      VARCHAR2 (5);
    psu      VARCHAR2 (3);
    stato    VARCHAR2 (1);
    tipotr   VARCHAR2 (1);
    esiste   NUMBER (1);
  BEGIN
    OPEN c3 FOR
      SELECT cod_nazionale, flag_lavo, flag_tipo_trasf
        FROM sitifraz
       WHERE id_trasf = idtr;

    FETCH c3
     INTO cf, stato, tipotr;

    IF c3%NOTFOUND THEN
      cf := ' ';
      stato := ' ';
      tipotr := ' ';
    END IF;

    CLOSE c3;

    retval := 0;
    pcf := ' ';
    pfo := 0;
    ppa := ' ';
    psu := ' ';
    esiste := 0;

    IF tipotr <> '3' AND tipotr <> '4' THEN
      OPEN c1 FOR
        SELECT cod_nazionale, foglio, part_madre, sub_madre
          FROM sitifraz
         WHERE id_trasf = idtr;

      LOOP
        FETCH c1
         INTO cf, fo, pa, su;

        EXIT WHEN (c1%NOTFOUND OR esiste = 1);

        IF cf <> pcf OR pfo <> fo OR ppa <> pa OR psu <> su THEN
          pcf := cf;
          pfo := fo;
          ppa := pa;
          psu := su;

          OPEN c2 FOR
            SELECT 1
              FROM siticent
             WHERE cod_nazionale = cf
               AND foglio = fo
               AND particella = pa
               AND sub = su
               AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');

          FETCH c2
           INTO esiste;

          IF c2%NOTFOUND THEN
            esiste := 0;
          END IF;

          CLOSE c2;
        END IF;
      END LOOP;

      CLOSE c1;

      IF esiste <> 0 THEN
        retval := 1;
      END IF;
    END IF;

    IF retval = 0 THEN
      pcf := ' ';
      pfo := 0;
      ppa := ' ';
      psu := ' ';
      esiste := 1;

      OPEN c1 FOR
        SELECT cod_nazionale, foglio, part_figlia, sub_figlia
          FROM sitifraz
         WHERE id_trasf = idtr;

      LOOP
        FETCH c1
         INTO cf, fo, pa, su;

        EXIT WHEN (c1%NOTFOUND OR esiste = 0);

        IF cf <> pcf OR pfo <> fo OR ppa <> pa OR psu <> su THEN
          pcf := cf;
          pfo := fo;
          ppa := pa;
          psu := su;

          OPEN c2 FOR
            SELECT 1
              FROM sitipart
             WHERE cod_nazionale = cf
               AND foglio = fo
               AND particella = pa
               AND sub = su
               AND data_fine_val = TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');

          FETCH c2
           INTO esiste;

          IF c2%NOTFOUND THEN
            esiste := 0;
          END IF;

          CLOSE c2;
        END IF;
      END LOOP;

      CLOSE c1;

      IF esiste <> 1 THEN
        retval := 2;
      END IF;

      IF retval = 0 AND stato = '0' THEN
        UPDATE sitifraz
           SET flag_lavo = '1'
         WHERE id_trasf = idtr;

        COMMIT;
      END IF;
    END IF;
  END testfraz;

  PROCEDURE testfrazui (idtr IN NUMBER, retval OUT NUMBER) IS
    TYPE emptycur IS REF CURSOR;

    c1       emptycur;
    c2       emptycur;
    cf       VARCHAR2 (4);
