      esiste := 1;
      pum := ' ';

      OPEN c1 FOR
        SELECT cod_nazionale, foglio, part_figlia, sub_figlia, unimm_figlia
          FROM sitifrazui
         WHERE id_trasf = idtr;

      LOOP
        FETCH c1
         INTO cf, fo, pa, su, um;

        EXIT WHEN (c1%NOTFOUND OR esiste = 0);

        IF cf <> pcf OR pfo <> fo OR ppa <> pa OR psu <> su OR pum <> um THEN
          pcf := cf;
