      END IF;

      IF retval = 0 AND stato = '0' THEN
        UPDATE sitifrazui
           SET flag_lavo = '1'
         WHERE id_trasf = idtr;

        COMMIT;
      END IF;
    END IF;
  END testfrazui;

  FUNCTION posso_inserire_madre (
    ccuaa     IN   VARCHAR2,
    codnaz    IN   VARCHAR2,
    fog       IN   NUMBER,
    part      IN   VARCHAR2,
    subal     IN   VARCHAR2,
    tipovar        VARCHAR2
  )
    RETURN VARCHAR2 IS
    TYPE emptycur IS REF CURSOR;

    c1           emptycur;
    errmsg       VARCHAR2 (1024) := '';
    catc         NUMBER (1);
    num_cuaa     NUMBER (9)      := 0;
    part_mia     NUMBER (9)      := 0;
    ilcuaa       VARCHAR2 (20);
    esisteazie   NUMBER (1);
    listacuaa    VARCHAR2 (512)  := '';
    sub_uc       VARCHAR2 (3);
  BEGIN
-- GUARDO SE C'E NEL CATASTO CENSUARIO
    OPEN c1 FOR
      SELECT 1
        FROM siticata
       WHERE cod_nazionale = codnaz
         AND foglio = fog
         AND particella = part
         AND sub = subal
         AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

    FETCH c1
     INTO catc;

    IF c1%NOTFOUND THEN
      catc := 0;
    END IF;

    CLOSE c1;

-- GUARDO SE ESISTE IN CONSISTENZA
    OPEN c1 FOR
      SELECT 1
        FROM cons_azie_tab
       WHERE cuaa = ccuaa AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

    FETCH c1
     INTO esisteazie;

    IF c1%NOTFOUND THEN
      esisteazie := 0;
    END IF;

    CLOSE c1;

    IF catc = 0 THEN
      errmsg := '001 - LA PARTICELLA NON ESISTE NEL CATASTO CENSUARIO';
    END IF;

    OPEN c1 FOR
      SELECT DISTINCT (cuaa)
                 FROM siticond
                WHERE cod_nazionale = codnaz
                  AND foglio = fog
                  AND particella = part
                  AND sub = subal
                  AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

    LOOP
      FETCH c1
       INTO ilcuaa;

      EXIT WHEN (c1%NOTFOUND);
      num_cuaa := num_cuaa + 1;

      IF LENGTH (listacuaa) < 490 OR listacuaa IS NULL THEN
        IF LENGTH (listacuaa) > 0 THEN
          listacuaa := listacuaa || ', ' || ilcuaa;
        ELSE
          listacuaa := ilcuaa;
        END IF;
      END IF;

      IF ilcuaa = ccuaa THEN
        part_mia := 1;
      END IF;
    END LOOP;

    CLOSE c1;

    IF (part_mia = 0 AND num_cuaa > 0) THEN
      IF LENGTH (ccuaa) > 0 THEN
        errmsg := '003 - LA PARTICELLA NON RISULTA CONDOTTA DAL SOGGETTO: ' || ccuaa;
        errmsg := errmsg || '<BR>E` CONDOTTA DA:' || listacuaa;
      ELSE
        errmsg := '003 - LA PARTICELLA RISULTA CONDOTTA DA:' || listacuaa;
      END IF;
    END IF;

    -- inizio 07/02/2007 simone
    sub_uc := get_uc (codnaz, fog, part, subal);

    IF UPPER (tipovar) = 'A' THEN
      IF sub_uc IS NULL OR LENGTH (sub_uc) = 0 THEN
        errmsg := '004 - LA PARTICELLA NON PRESENTA PORZIONI';
      END IF;
    ELSE
      IF sub_uc IS NOT NULL AND LENGTH (sub_uc) > 0 AND UPPER (tipovar) IN ('0', '1', '2', '9') THEN
        errmsg := '004 - LA PARTICELLA PRESENTA UNA O PIU PORZIONI';
      END IF;
    END IF;

    -- fine 07/02/2007 simone
    RETURN errmsg;
  END posso_inserire_madre;

  FUNCTION posso_inserire_figlia (
    ccuaa     IN   VARCHAR2,
    codnaz    IN   VARCHAR2,
    fog       IN   NUMBER,
    part      IN   VARCHAR2,
    subal     IN   VARCHAR2,
    tipovar        VARCHAR2
  )
    RETURN VARCHAR2 IS
    TYPE emptycur IS REF CURSOR;

    c1           emptycur;
    errmsg       VARCHAR2 (1024) := '';
    catc         NUMBER (1);
    num_cuaa     NUMBER (9)      := 0;
    part_mia     NUMBER (9)      := 0;
    ilcuaa       VARCHAR2 (20);
    esisteazie   NUMBER (1);
    listacuaa    VARCHAR2 (512)  := '';
    sub_uc       VARCHAR2 (3);
  BEGIN
-- GUARDO SE C'E NEL CATASTO CENSUARIO
    OPEN c1 FOR
      SELECT 1
        FROM siticata
       WHERE cod_nazionale = codnaz
         AND foglio = fog
         AND particella = part
         AND sub = subal
         AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

    FETCH c1
     INTO catc;

    IF c1%NOTFOUND THEN
      catc := 0;
    END IF;

    CLOSE c1;

-- GUARDO SE ESISTE IN CONSISTENZA
    OPEN c1 FOR
      SELECT 1
        FROM cons_azie_tab
       WHERE cuaa = ccuaa AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

    FETCH c1
     INTO esisteazie;

    IF c1%NOTFOUND THEN
      esisteazie := 0;
    END IF;

    CLOSE c1;

    OPEN c1 FOR
      SELECT DISTINCT (cuaa)
                 FROM siticond
                WHERE cod_nazionale = codnaz
                  AND foglio = fog
                  AND particella = part
                  AND sub = subal
                  AND data_fine = TO_DATE ('99991231', 'YYYYMMDD');

    LOOP
      FETCH c1
       INTO ilcuaa;

      EXIT WHEN (c1%NOTFOUND);
      num_cuaa := num_cuaa + 1;

      IF LENGTH (listacuaa) < 490 OR listacuaa IS NULL THEN
        IF LENGTH (listacuaa) > 0 THEN
          listacuaa := listacuaa || ', ' || ilcuaa;
        ELSE
          listacuaa := ilcuaa;
        END IF;
      END IF;

      IF ilcuaa = ccuaa THEN
        part_mia := 1;
      END IF;
    END LOOP;

    CLOSE c1;

/* corrado:
  IF CATC=1 AND PART_MIA=0 THEN
    ERRMSG:= '001 - LA PARTICELLA RISULTA ESISTENTE NEL CATASTO CENSUARIO';
  END IF;
*/
    IF num_cuaa > 0 THEN
      IF esisteazie = 0 THEN
        --NO CONSISTENZA: BLOCCO SE LA PART NON E MIA
        IF part_mia = 0 AND ccuaa IS NOT NULL THEN
          errmsg := '002 - LA PARTICELLA NON RISULTA CONDOTTA DAL SOGGETTO: ' || ccuaa;
          errmsg := errmsg || '<BR>E` CONDOTTA DA:' || listacuaa;
        END IF;
      ELSE
        --SI CONSISTENZA: BLOCCO SE LA PART E CONDOTTA
        IF part_mia = 0 THEN
          errmsg := '003 - LA PARTICELLA RISULTA CONDOTTA DA:' || listacuaa;
        END IF;
      END IF;
    END IF;

    -- inizio 07/02/2007 simone
    sub_uc := get_uc (codnaz, fog, part, subal);

    IF sub_uc IS NOT NULL AND LENGTH (sub_uc) > 0 THEN
      errmsg := '004 - LA PARTICELLA PRESENTA UNA O PIU PORZIONI';
    END IF;

    -- fine 07/02/2007 simone
    RETURN errmsg;
  END posso_inserire_figlia;

  PROCEDURE crealavorazione (
    tipolav         IN       VARCHAR2,
    usr             IN       VARCHAR2,
    prif            IN       VARCHAR2,
    codset          IN       NUMBER,
    id_elenco       IN       NUMBER,
    datalav         IN       DATE,
    caspart         IN       VARCHAR2,
    incuaa          IN       VARCHAR2,
    idlavorazione   OUT      NUMBER
  ) IS
    idlav   NUMBER (9);
  BEGIN
    SELECT sitifraz_seq.NEXTVAL
      INTO idlav
      FROM DUAL;

    INSERT INTO sitistack_header
                (pkid, flag_tipo_trasf, utenteins, prov_rif, cod_settore, datains, pkidfraz, id_ele, casi_particolari,
                 cuaa
                )
         VALUES (idlav, tipolav, usr, prif, codset, datalav, idlav, id_elenco, caspart,
                 incuaa
                );

    idlavorazione := idlav;
  END crealavorazione;

  FUNCTION stessaperc_particelle (pkidlav IN NUMBER, tipop IN NUMBER)
    RETURN NUMBER IS
    CURSOR ctoprocess IS
      SELECT cod_nazionale, foglio, particella, sub
        FROM sitistack_particelle
       WHERE pkid = pkidlav AND tipopart = tipop;

    CURSOR ctit (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2) IS
      SELECT   cuaa || tipo_titolo || perc_poss AS rif
          FROM siticond_all
         WHERE cod_nazionale = cn
           AND foglio = fg
           AND particella = pt
           AND sub = sb
           AND data_fine = TO_DATE ('99991231', 'yyyymmdd')
      GROUP BY cuaa, tipo_titolo, perc_poss;

    ret           NUMBER (1);
    riferimento   VARCHAR2 (32767);
    cur_rif       VARCHAR2 (32767);
  BEGIN
    -- Di default tutto ok
    ret := 1;

    FOR rec IN ctoprocess LOOP
      cur_rif := NULL;

      FOR rectit IN ctit (rec.cod_nazionale, rec.foglio, rec.particella, rec.sub) LOOP
        cur_rif := cur_rif || rectit.rif || '_';
      END LOOP;

      IF riferimento IS NULL THEN
        riferimento := cur_rif;
      END IF;

      IF NVL (riferimento, 'X') != NVL (cur_rif, 'X') THEN
        ret := 0;
        EXIT;
      END IF;
    END LOOP;

    RETURN ret;
  END stessaperc_particelle;

