  FUNCTION stessaperc_uiu (pkidlav IN NUMBER)
    RETURN NUMBER IS
    CURSOR ccessati IS
      SELECT DISTINCT cod_nazionale, foglio, particella_dest, sub_dest, unimm_dest
                 FROM sitistack_uiu
                WHERE pkid = pkidlav AND flag_vari = 3;

    CURSOR criferimenti (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER) IS
      SELECT cod_nazionale, foglio, particella, sub, unimm
        FROM sitistack_uiu
       WHERE pkid = pkidlav
         AND cod_nazionale = cn
         AND foglio = fg
         AND particella_dest = pt
         AND sub_dest = sb
         AND unimm_dest = un
         AND flag_vari = 3;

    CURSOR ctit (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER) IS
      SELECT   cuaa || tipo_titolo || perc_poss AS rif
          FROM siticonduz_imm_all
         WHERE cod_nazionale = cn
           AND foglio = fg
           AND particella = pt
           AND sub = sb
           AND unimm = un
           AND data_fine = TO_DATE ('99991231', 'yyyymmdd')
      GROUP BY cuaa, tipo_titolo, perc_poss;

    ret           NUMBER (1);
    riferimento   VARCHAR2 (32767);
    cur_rif       VARCHAR2 (32767);
  BEGIN
    -- Di default tutto ok
    ret := 1;

    FOR rec IN ccessati LOOP
      EXIT WHEN ret != 1;

      FOR recrif IN criferimenti (rec.cod_nazionale, rec.foglio, rec.particella_dest, rec.sub_dest, rec.unimm_dest) LOOP
        EXIT WHEN ret != 1;
        cur_rif := NULL;

        FOR rectit IN ctit (recrif.cod_nazionale, recrif.foglio, recrif.particella, recrif.sub, recrif.unimm) LOOP
          cur_rif := cur_rif || rectit.rif || '_';
        END LOOP;

        IF riferimento IS NULL THEN
          riferimento := cur_rif;
        END IF;

        IF NVL (riferimento, 'X') != NVL (cur_rif, 'X') THEN
          ret := 0;
        END IF;
      END LOOP;
    END LOOP;

    RETURN ret;
  END stessaperc_uiu;

