  PROCEDURE controlla_date (pkidlav IN NUMBER, out_maxdate OUT DATE, in_check IN INTEGER DEFAULT 0) IS
    TYPE emptycur IS REF CURSOR;

    c1           emptycur;
    tblerr       VARCHAR2 (512) := '';
    datalavo     DATE;
    nperr        DATE;
    maxdate      DATE;
    cod_errore   NUMBER         := 0;
  BEGIN
    SELECT datains
      INTO datalavo
      FROM sitistack_header
     WHERE pkid = pkidlav;

    maxdate := datalavo;
--CONTROLLO CENSUARIO
    nperr := NULL;

    OPEN c1 FOR
      SELECT b.data_aggi
        FROM sitistack_particelle a, sititrkc b
       WHERE a.pkid = pkidlav
         AND b.cod_nazionale = a.cod_nazionale
         AND b.foglio = a.foglio
         AND b.particella = a.particella
         AND b.sub = a.sub
         AND b.data_aggi >= datalavo;

    FETCH c1
     INTO nperr;

    CLOSE c1;

    IF nperr IS NOT NULL THEN
      IF nperr > maxdate THEN
        maxdate := nperr;
      END IF;

      tblerr := tblerr || ', CENSUARIO TERRENI';
    END IF;


--CONTROLLO UIU
    nperr := NULL;

    OPEN c1 FOR
      SELECT b.data_inizio_val
        FROM sitistack_uiu a, sitiuiu b
       WHERE a.pkid = pkidlav
         AND a.flag_vari > 0
         AND b.cod_nazionale = a.cod_nazionale
         AND b.foglio = a.foglio
         AND b.particella = a.particella
         AND b.sub = a.sub
         AND b.unimm = a.unimm
         AND b.data_inizio_val >= datalavo;

    FETCH c1
     INTO nperr;

    CLOSE c1;

    IF nperr IS NOT NULL THEN
      IF nperr > maxdate THEN
        maxdate := nperr;
      END IF;

      tblerr := tblerr || ', CATASTO UIU';
    END IF;

--CONTROLLO UNARB
    nperr := NULL;

    OPEN c1 FOR
      SELECT b.data_inizio_val
        FROM sitistack_unar a, sitiunar b
       WHERE a.pkid = pkidlav
         AND a.flag_vari > 0
         AND b.cod_nazionale = a.cod_nazionale
         AND b.foglio = a.foglio
         AND b.particella = a.particella
         AND b.sub = a.sub
         AND b.unar = a.unar
         AND b.data_inizio_val >= datalavo;

    FETCH c1
     INTO nperr;

    CLOSE c1;

    IF nperr IS NOT NULL THEN
      IF nperr > maxdate THEN
        maxdate := nperr;
      END IF;

      tblerr := tblerr || ', UNITA ARBOREE';
    END IF;

--CONTROLLO CONSISTENZA
    nperr := NULL;

    OPEN c1 FOR
      SELECT b.data_inizio
        FROM sitistack_particelle a, cons_cons_tab b
       WHERE a.pkid = pkidlav
         AND b.pk_cuaa < 999999999
         AND b.cod_nazionale = a.cod_nazionale
         AND b.foglio = a.foglio
         AND b.particella = a.particella
         AND b.sub = a.sub
         AND b.data_inizio >= datalavo;

    FETCH c1
     INTO nperr;

    CLOSE c1;

    IF nperr IS NOT NULL THEN
      IF nperr > maxdate THEN
        maxdate := nperr;
      END IF;

      tblerr := tblerr || ', CONSITENZA TERRENI PROPRIETA';
    END IF;

--CONTROLLO REGISTRO
    nperr := NULL;

    OPEN c1 FOR
      SELECT b.data_inizio
        FROM sitistack_particelle a, cons_ufre_tab b
       WHERE a.pkid = pkidlav
         AND b.pk_cuaa < 999999999
         AND b.cod_nazionale = a.cod_nazionale
         AND b.foglio = a.foglio
         AND b.particella = a.particella
         AND b.sub = a.sub
         AND b.data_inizio >= datalavo;

    FETCH c1
     INTO nperr;

    CLOSE c1;

    IF nperr IS NOT NULL THEN
      IF nperr > maxdate THEN
        maxdate := nperr;
      END IF;

      tblerr := tblerr || ', CONSITENZA TERRENI ALTRA CONDUZIONE';
    END IF;

--CONTROLLO CONS UIU
    nperr := NULL;

    OPEN c1 FOR
      SELECT b.data_inizio
        FROM sitistack_uiu a, cons_csui_tab b
       WHERE a.pkid = pkidlav
         AND a.flag_vari > 0
         AND b.cod_nazionale = a.cod_nazionale
         AND b.foglio = a.foglio
         AND b.particella = a.particella
         AND b.sub = a.sub
         AND TO_NUMBER (b.unimm) = a.unimm
         AND b.data_inizio >= datalavo;

    FETCH c1
     INTO nperr;

    CLOSE c1;

    IF nperr IS NOT NULL THEN
      IF nperr > maxdate THEN
        maxdate := nperr;
      END IF;

      tblerr := tblerr || ', CONSISTENZA UIU PROPRIETA';
    END IF;

--CONTROLLO UFRE UIU
    nperr := NULL;

    OPEN c1 FOR
      SELECT b.data_inizio
        FROM sitistack_uiu a, cons_urui_tab b
       WHERE a.pkid = pkidlav
         AND a.flag_vari > 0
         AND b.cod_nazionale = a.cod_nazionale
         AND b.foglio = a.foglio
         AND b.particella = a.particella
         AND b.sub = a.sub
         AND TO_NUMBER (b.unimm) = a.unimm
         AND b.data_inizio >= datalavo;

    FETCH c1
     INTO nperr;

    CLOSE c1;

    IF nperr IS NOT NULL THEN
      IF nperr > maxdate THEN
        maxdate := nperr;
      END IF;

      tblerr := tblerr || ', CONSISTENZA UIU ALTRA CONDUZIONE';
    END IF;


    IF in_check = 0 THEN
      IF LENGTH (tblerr) > 0 THEN
        tblerr := SUBSTR (tblerr, 3, LENGTH (tblerr));
        raise_application_error (-20999,
                                    'LE SEGUENTI FONTI SONO PIU` AGGIORNATE DELLA DATA PASSATA: ('
                                 || tblerr
                                 || '), LA DATA MINIMA UTILIZZABILE E`: '
                                 || TO_CHAR (maxdate + 1 / 24 / 60, 'DD/MM/YYYY HH24:MI')
                                );
      END IF;
    END IF;

    --corrado : 28-3-2007: faccio ritornare la data minima utilizzabile
    out_maxdate := maxdate;
  END controlla_date;

  FUNCTION aggiusta_titoli_part (
    pkidlav         NUMBER,
    datalavo        DATE,
    datalavo_fine   DATE,
    tipotr          VARCHAR2,
    utentelav       VARCHAR2,
    p_atto_fin      NUMBER
  )
    RETURN BOOLEAN IS
    conspartchanged   BOOLEAN := FALSE;
  BEGIN
    IF tipotr IN ('0', '1', '2', '9', 'A') THEN
      -- Faccio scadere i titoli precedenti
      UPDATE cons_cons_tab t
         SET data_fine = datalavo_fine,
             atto_fin = p_atto_fin,
             pkid_stack_fin = pkidlav                                                              -- corrado 27-11-2007
       WHERE data_fine = TO_DATE ('99991231', 'YYYYMMDD')
         AND (cod_nazionale, foglio, particella, sub) IN (SELECT cod_nazionale, foglio, particella, sub
                                                            FROM sitistack_particelle
                                                           WHERE pkid = pkidlav AND tipopart = 1)
         -- TOM 12/12/2007: Non termino la titolaritï¿½ se la part. esiste anche come figlia
         AND NOT EXISTS (
               SELECT 1
                 FROM sitistack_particelle
                WHERE pkid = pkidlav
                  AND tipopart = 2
                  AND cod_nazionale = t.cod_nazionale
                  AND foglio = t.foglio
                  AND particella = t.particella
                  AND sub = t.sub);

      UPDATE cons_ufre_tab t
         SET data_fine = datalavo_fine,
             atto_fin = p_atto_fin,
             pkid_stack_fin = pkidlav                                                              -- corrado 27-11-2007
       WHERE data_fine = TO_DATE ('99991231', 'YYYYMMDD')
         AND (cod_nazionale, foglio, particella, sub) IN (SELECT cod_nazionale, foglio, particella, sub
                                                            FROM sitistack_particelle
                                                           WHERE pkid = pkidlav AND tipopart = 1)
         -- TOM 12/12/2007: Non termino la titolaritï¿½ se la part. esiste anche come figlia
         AND NOT EXISTS (
               SELECT 1
                 FROM sitistack_particelle
                WHERE pkid = pkidlav
                  AND tipopart = 2
                  AND cod_nazionale = t.cod_nazionale
                  AND foglio = t.foglio
                  AND particella = t.particella
                  AND sub = t.sub);

      conspartchanged := TRUE;
    END IF;

    IF tipotr IN ('0', '1', '2', '9') THEN
      -- Inserisco gli stessi titoli delle madri sulle figlie
      FOR rec IN (SELECT   MAX (a.atto_ini) atto_ini, c.cod_nazionale, c.foglio, c.particella, c.sub, a.perc_poss,
                           a.pk_cuaa, a.tipo_titolo
                      FROM sitistack_particelle c, sitistack_particelle b, cons_cons_tab a
                     WHERE c.pkid = pkidlav
                       AND c.tipopart = 2
                       AND b.pkid = pkidlav
                       AND b.tipopart = 1
                       AND a.cod_nazionale = b.cod_nazionale
                       AND a.foglio = b.foglio
                       AND a.particella = b.particella
                       AND a.sub = b.sub
         AND a.pk_cuaa < 999999999
         -- Mario 18/10/2010: trasferisco i titoli alle figlie anche se la madre non ï¿½ scaduta
                       --AND a.data_fine = datalavo_fine
                       AND a.data_fine >= datalavo_fine
         AND a.data_inizio <= datalavo_fine
                       -- TOM 12/12/2007: Non reinserisco la titolaritï¿½ se non l'ho fatta cessare
                       AND NOT EXISTS (
                             SELECT 1
                               FROM sitistack_particelle
                              WHERE pkid = pkidlav
                                AND tipopart = 1
                                AND cod_nazionale = c.cod_nazionale
                                AND foglio = c.foglio
                                AND particella = c.particella
                                AND sub = c.sub)
                  GROUP BY c.cod_nazionale, c.foglio, c.particella, c.sub, a.perc_poss, a.pk_cuaa, a.tipo_titolo) LOOP

    INSERT INTO cons_cons_tab
                    (pkid_cons, allegato, sviluppo, data_registrazione, utente, "TIMESTAMP", data_inizio,
                     data_fine, atto_ini, cod_nazionale, foglio, particella,
                     sub, perc_poss, pk_cuaa, tipo_titolo, pkid_stack_ini
                    )
             VALUES (cons_cons_seq.NEXTVAL, '0', '0', SYSDATE, utentelav, SYSDATE, datalavo,
                     TO_DATE ('99991231', 'YYYYMMDD'), rec.atto_ini, rec.cod_nazionale, rec.foglio, rec.particella,
                     rec.sub, rec.perc_poss, rec.pk_cuaa, rec.tipo_titolo, pkidlav
                    );
      END LOOP;

      FOR rec IN (SELECT   MAX (a.atto_ini) atto_ini, c.cod_nazionale, c.foglio, c.particella, c.sub, a.perc_poss,
                           a.pk_cuaa, a.tipo_titolo
                      FROM sitistack_particelle c, sitistack_particelle b, cons_ufre_tab a
                     WHERE c.pkid = pkidlav
                       AND c.tipopart = 2
                       AND b.pkid = pkidlav
                       AND b.tipopart = 1
                       AND a.cod_nazionale = b.cod_nazionale
                       AND a.foglio = b.foglio
                       AND a.particella = b.particella
                       AND a.sub = b.sub
                       AND a.pk_cuaa < 999999999
         -- Mario 18/10/2010: trasferisco i titoli alle figlie anche se la madre non ï¿½ scaduta
                       --AND a.data_fine = datalavo_fine
                       AND a.data_fine >= datalavo_fine
         AND a.data_inizio <= datalavo_fine
                       -- TOM 12/12/2007: Non reinserisco la titolaritï¿½ se non l'ho fatta cessare
                       AND NOT EXISTS (
                             SELECT 1
                               FROM sitistack_particelle
                              WHERE pkid = pkidlav
                                AND tipopart = 1
                                AND cod_nazionale = c.cod_nazionale
                                AND foglio = c.foglio
                                AND particella = c.particella
                                AND sub = c.sub)
                  GROUP BY c.cod_nazionale, c.foglio, c.particella, c.sub, a.perc_poss, a.pk_cuaa, a.tipo_titolo) LOOP

    INSERT INTO cons_ufre_tab
                    (pkid_uffr, allegato, sviluppo, data_registrazione, utente, "TIMESTAMP", data_inizio,
                     data_fine, atto_ini, cod_nazionale, foglio, particella,
                     sub, perc_poss, pk_cuaa, tipo_titolo, pkid_stack_ini
                    )
             VALUES (cons_ufre_seq.NEXTVAL, '0', '0', SYSDATE, utentelav, SYSDATE, datalavo,
                     TO_DATE ('99991231', 'YYYYMMDD'), rec.atto_ini, rec.cod_nazionale, rec.foglio, rec.particella,
                     rec.sub, rec.perc_poss, rec.pk_cuaa, rec.tipo_titolo, pkidlav
                    );
      END LOOP;

      conspartchanged := TRUE;
    END IF;

    RETURN conspartchanged;
  END;

  PROCEDURE aggiusta_titoli_uiu (pkidlav NUMBER, datalavo DATE, datalavo_fine DATE, utentelav VARCHAR2, p_atto_fin NUMBER) IS

    cnt   PLS_INTEGER;

    contractCnt PLS_INTEGER;

    m_atto_ini NUMBER;

  BEGIN

    --VARIO CONS_UIU - CONS_CSUI_TAB

    UPDATE cons_csui_tab
       SET data_fine = datalavo_fine,
           pkid_stack_fin = pkidlav                                                               -- CORRADO: 27-11-2007
     WHERE data_fine = TO_DATE ('99991231', 'YYYYMMDD')
       AND (cod_nazionale, foglio, particella, sub, unimm) IN (
                                                   SELECT cod_nazionale, foglio, particella, sub,
                                                          --TRIM (TO_CHAR (unimm))
                                                          unimm
                                                     FROM sitistack_uiu
                                                    WHERE pkid = pkidlav AND flag_vari <> 0);



    -- Modifica MARIO 27-05-2010  - verifico a quanti contratti sono legati le uiu che scadono
      SELECT COUNT(*) INTO contractCnt FROM (
            SELECT distinct d.atto_ini
              FROM sitistack_uiu c,
               (SELECT   a.cod_nazionale, a.foglio, b.perc_poss, b.tipo_titolo, b.pk_cuaa, b.atto_ini, a.particella_dest,
                         sub_dest, unimm_dest
                    FROM cons_csui_tab b, sitistack_uiu a
                   WHERE b.data_fine = datalavo_fine
                     AND b.cod_nazionale = a.cod_nazionale
                     AND b.foglio = a.foglio
                     AND b.particella = a.particella
                     AND b.sub = a.sub
                     AND b.unimm = TRIM (TO_CHAR (a.unimm))
                     AND a.pkid = pkidlav
                     AND a.flag_vari IN (1, 3)
               ) d
         WHERE c.cod_nazionale = d.cod_nazionale
           AND c.foglio = d.foglio
           AND c.particella_dest = d.particella_dest
           AND c.sub_dest = d.sub_dest
           AND c.unimm_dest = d.unimm_dest
           AND c.pkid = pkidlav
           AND c.flag_vari IN (2, 1));



     if contractCnt = 1 then
        SELECT distinct d.atto_ini into m_atto_ini
              FROM sitistack_uiu c,
               (SELECT   a.cod_nazionale, a.foglio, b.perc_poss, b.tipo_titolo, b.pk_cuaa, b.atto_ini, a.particella_dest,
                         sub_dest, unimm_dest
