  PROCEDURE esegui_lavorazione (pkidlav IN NUMBER) IS
    TYPE emptycur IS REF CURSOR;

    c1                emptycur;
    recsp             sitistack_particelle%ROWTYPE;
    cco               VARCHAR2 (4);
    cfo               NUMBER;
    cpa               VARCHAR2 (5);
    csu               VARCHAR2 (3);
    csuc              NUMBER;
    crea              NUMBER;
    cred              NUMBER;
    suc               VARCHAR2 (3);
    quac              NUMBER (3);
    clat              VARCHAR (2);
    ptit              VARCHAR (7);
  annot     VARCHAR2(1000);
    utentelav         VARCHAR2 (20);
    id_elenco         NUMBER (9);
    datalavo          DATE;
    datalavo_fine     DATE;
    provr             VARCHAR2 (9);
    setto             NUMBER;
    pkfraz            NUMBER;
    tipotr            VARCHAR2 (1);
    nummadri          NUMBER;
    numfiglie         NUMBER;
    numatti           NUMBER;
    numuiu            NUMBER;
    numunar           NUMBER;
    statolavo         NUMBER;
    max_date          DATE;
    conspartchanged   BOOLEAN                        := FALSE;
    consuiuchanged    BOOLEAN                        := FALSE;
    id_atto           NUMBER;
  BEGIN
    SELECT utenteins, datains, prov_rif, cod_settore, pkidfraz, flag_tipo_trasf, id_ele
      INTO utentelav, datalavo, provr, setto, pkfraz, tipotr, id_elenco
      FROM sitistack_header
     WHERE pkid = pkidlav;

    IF pkfraz = 0 THEN
      SELECT sitifraz_seq.NEXTVAL
        INTO pkfraz
        FROM DUAL;

      UPDATE sitistack_header
         SET pkidfraz = pkfraz
       WHERE pkid = pkidlav;
    END IF;

    datalavo_fine := datalavo - 1 / 24 / 60 / 60;                                                  --UN SECONDO PRIMA...

    -- corrado 5/2/2006 se la trasformazione ï¿½ = A elimina UC allora il sub di destinazione delle unar e UIU  ï¿½ il sub della madre
    IF tipotr = 'A' THEN
      UPDATE sitistack_unar
         SET sub_dest = get_sub (cod_nazionale, foglio, particella, sub),
             flag_vari = 2
       WHERE pkid = pkidlav AND flag_vari = 0;

      UPDATE sitistack_uiu
         SET sub_dest = get_sub (cod_nazionale, foglio, particella, sub),
             flag_vari = 2
       WHERE pkid = pkidlav AND flag_vari = 0;
    END IF;

    --corrado:fine
    SELECT COUNT (*)
      INTO numatti
      FROM sitistack_atti
     WHERE pkid = pkidlav;

    SELECT COUNT (*)
      INTO nummadri
      FROM sitistack_particelle
     WHERE pkid = pkidlav AND tipopart = 1;

    SELECT COUNT (*)
      INTO numfiglie
      FROM sitistack_particelle
     WHERE pkid = pkidlav AND tipopart = 2;

    SELECT COUNT (*)
      INTO numunar
      FROM sitistack_unar
     WHERE pkid = pkidlav AND flag_vari > 0;

    SELECT COUNT (*)
      INTO numuiu
      FROM sitistack_uiu
     WHERE pkid = pkidlav AND flag_vari > 0;

    IF numatti > 0 THEN
      SELECT pkid_atto
        INTO id_atto
        FROM sitistack_atti
       WHERE pkid = pkidlav AND ROWNUM = 1;
    ELSE
      id_atto := NULL;
    END IF;

    IF nummadri > 1 THEN
      --CONTROLLO CHE LE PARTICELLE MADRI SIANO CONDOTTE DAGLI STESSI CONDUTTORI ALLE STESSE PERCENTUALI
      IF stessaperc_particelle (pkidlav, 1) = 0 THEN
        raise_application_error
                               (-20999,
                                'LE PARTICELLE MADRI NON SONO CONDOTTE DAGLI STESSI SOGGETTI CON LE STESSE PERCENTUALI'
                               );
      END IF;
    END IF;

/* CORRADO: 27-11-2007 : TOLTO IL CONTROLLO SULLA CONDUZIONE DELLE FIGLIE
      IF numfiglie > 1
      THEN
         --CONTROLLO CHE LE PARTICELLE FIGLIE SIANO CONDOTTE DAGLI STESSI CONDUTTORI ALLE STESSE PERCENTUALI
         IF stessaperc_particelle (pkidlav, 2) = 0
         THEN
            raise_application_error
               (-20999,
                'LE PARTICELLE FIGLIE NON SONO CONDOTTE DAGLI STESSI SOGGETTI CON LE STESSE PERCENTUALI'
               );
         END IF;
      END IF;
*/
    controlla_date (pkidlav, max_date);
/*
    IF numuiu > 0 THEN
      IF stessaperc_uiu (pkidlav) = 0 THEN
        raise_application_error (-20999, 'LE UIU COINVOLTE NON HANNO GLI STESSI CONDUTTORI CON LE STESSE PERCENTUALI');
      END IF;
    END IF;
*/
    IF numfiglie = 0 AND nummadri > 0 AND tipotr <> 'A' THEN
      INSERT INTO sitistack_particelle
                  (pkid, tipopart, cod_nazionale, foglio, particella, sub, supecens, reddito_agrario,
                   reddito_dominicale, shape, shape_unar, sub_uc, qual_cat, classe_terreno, partita, annotazioni)
        (SELECT pkid, 2, cod_nazionale, foglio, particella, sub, supecens, reddito_agrario, reddito_dominicale, shape,
                shape_unar, sub_uc, qual_cat, classe_terreno, partita, annotazioni
           FROM sitistack_particelle
          WHERE pkid = pkidlav AND tipopart = 1);
    END IF;

    IF tipotr = 'A' THEN
-- corrado: 27-2-2007 nella cancellazione porzione la madre della porzione ï¿½ sia madre che figlia (simulo accorpamento)
      INSERT INTO sitistack_particelle
                  (pkid, tipopart, cod_nazionale, foglio, particella, sub, supecens, reddito_agrario,
                   reddito_dominicale, shape, shape_unar, sub_uc, qual_cat, classe_terreno, partita, annotazioni)
        (SELECT pkidlav, 2, cod_nazionale, foglio, particella, sub, area_part, reddito_agrario, reddito_dominicale,
                NULL, NULL, sub_uc, qual_cat, classe_terreno, partita, annotazioni
           FROM sititrkc
          WHERE (cod_nazionale, foglio, particella, sub) IN (
                             SELECT cod_nazionale, foglio, particella,
                                    get_sub (cod_nazionale, foglio, particella, sub)
                               FROM sitistack_particelle
                              WHERE pkid = pkidlav AND tipopart = 1)
            AND data_fine > SYSDATE);

      INSERT INTO sitistack_particelle
                  (pkid, tipopart, cod_nazionale, foglio, particella, sub, supecens, reddito_agrario,
                   reddito_dominicale, shape, shape_unar, sub_uc, qual_cat, classe_terreno, partita, annotazioni)
        (SELECT pkidlav, 1, cod_nazionale, foglio, particella, sub, area_part, reddito_agrario, reddito_dominicale,
                NULL, NULL, sub_uc, qual_cat, classe_terreno, partita, annotazioni
           FROM sititrkc
          WHERE (cod_nazionale, foglio, particella, sub) IN (
                              SELECT cod_nazionale, foglio, particella,
                                     get_sub (cod_nazionale, foglio, particella, sub)
                                FROM sitistack_particelle
                               WHERE pkid = pkidlav AND tipopart = 1)
            AND data_fine > SYSDATE);
    END IF;

    IF numfiglie = 1 AND nummadri = 0 THEN
      INSERT INTO sitistack_particelle
                  (pkid, tipopart, cod_nazionale, foglio, particella, sub, supecens, reddito_agrario,
                   reddito_dominicale, shape, shape_unar, sub_uc, qual_cat, classe_terreno, partita)
        (SELECT pkid, 1, cod_nazionale, foglio, particella, sub, supecens, reddito_agrario, reddito_dominicale, shape,
                shape_unar, sub_uc, qual_cat, classe_terreno, partita
           FROM sitistack_particelle
          WHERE pkid = pkidlav AND tipopart = 2);
    END IF;

    -- Richiamo procedura custom
    sitistack_custom.before_esegui_lavorazione (pkidlav);

    --CICLO LE MADRI
    OPEN c1 FOR
      SELECT cod_nazionale, foglio, particella, sub
        FROM sitistack_particelle a
       WHERE pkid = pkidlav
         AND tipopart = 1
         AND NOT EXISTS (
               SELECT 1
                 FROM sitistack_particelle b
                WHERE b.pkid = pkidlav
                  AND b.tipopart = 2
                  AND b.cod_nazionale = a.cod_nazionale
                  AND b.foglio = a.foglio
                  AND b.particella = a.particella
                  AND b.sub = a.sub);

    LOOP
      FETCH c1
       INTO cco, cfo, cpa, csu;

      EXIT WHEN (c1%NOTFOUND);

      --FACCIO SCADERE IL CENSUARIO
  -- 2009-05-28 - Mario: se il tipo di lavorazione ï¿½ 5 (modifica uiu) non faccio scadere la particella.
      IF tipotr <> '5' THEN
   UPDATE sititrkc
          SET valida = 0,
              utente_fine = utentelav,
              data_fine = datalavo_fine,
              data_modifica = datalavo_fine,
              id_trasf_fine = pkfraz,
              atto_fin = id_atto
        WHERE cod_nazionale = cco AND foglio = cfo AND particella = cpa AND sub = csu AND valida = 1;
  END IF;

      -- corrado 7/2/2007 se la lavorazione ï¿½ un frazionamento, accorpamento, rinum allora faccio scadere anche le figlie UC
      IF tipotr IN ('0', '1', '2') THEN
        UPDATE sititrkc
           SET valida = 0,
               utente_fine = utentelav,
               data_fine = datalavo_fine,
               data_modifica = datalavo_fine,
               id_trasf_fine = pkfraz,
               atto_fin = id_atto
         WHERE cod_nazionale = cco AND foglio = cfo AND particella = cpa AND sub_uc = csu AND valida = 1;
      END IF;
    -- fine
    END LOOP;

    CLOSE c1;

    --CICLO LE FIGLIE
    OPEN c1 FOR
      SELECT cod_nazionale, foglio, particella, sub, supecens, reddito_agrario, reddito_dominicale, sub_uc, qual_cat,
             classe_terreno, partita, annotazioni
        FROM sitistack_particelle
       WHERE pkid = pkidlav AND tipopart = 2;

    LOOP
      FETCH c1
       INTO cco, cfo, cpa, csu, csuc, crea, cred, suc, quac, clat, ptit, annot;

      EXIT WHEN (c1%NOTFOUND);
      --INSERISCO LE FIGLIE NEL CENSUARIO

  -- 2009/05/28 mario: se il tipo di lavorazione = 5 (modifica uiu) non inserisco la particella come figlia di sï¿½ stessa
  IF tipotr <> '5' THEN
   statolavo :=
         censuario.inserisci_catasto (cco,
                                      cfo,
                                      cpa,
                                      csu,
                                      csuc,
                                      datalavo,
                                      utentelav,
                                      crea,
                                      cred,
                                      pkfraz,
                                      suc,
                                      quac,
                                      clat,
                                      ptit,
                                      id_atto,
              annot
                                     );

       IF statolavo <> 0 THEN
         raise_application_error (-20999, 'ERRORE INSERENDO IN CATASTO CENSUARIO (' || TO_CHAR (statolavo) || ')');
       END IF;
  END IF;
    END LOOP;

    CLOSE c1;

    OPEN c1 FOR
      SELECT   cod_nazionale, foglio, particella, sub_uc
          FROM sitistack_particelle
         WHERE pkid = pkidlav AND tipopart = 2 AND sub_uc IS NOT NULL
      GROUP BY cod_nazionale, foglio, particella, sub_uc;

    LOOP
      FETCH c1
       INTO cco, cfo, cpa, suc;

      EXIT WHEN (c1%NOTFOUND);

      IF stato_cens (cco, cfo, cpa, suc, datalavo) < 2 THEN
        -- STO CREANDO UNA PORIZONE MA NON ESISTE LA MADRE DELLA PROZIONE
        statolavo :=
          censuario.inserisci_catasto (cco,
                                       cfo,
                                       cpa,
                                       suc,
                                       censuario.getsommaporzioni (cco, cfo, cpa, suc, datalavo),
                                       datalavo,
                                       utentelav,
                                       0,
                                       0,
                                       pkfraz,
                                       NULL,
                                       NULL,
                                       NULL,
                                       NULL,
                                       id_atto,
             ''
                                      );

        IF statolavo <> 0 THEN
          raise_application_error (-20999,
                                   'ERRORE INSERENDO MADRE(PORZIONE) IN CATASTO CENSUARIO (' || TO_CHAR (statolavo)
                                   || ')'
                                  );
        END IF;
      END IF;
    END LOOP;

    CLOSE c1;

    IF numunar > 0 THEN
      --FACCIO SCADERE LE UNARB
      UPDATE sitiunar
         SET data_fine_val = datalavo_fine,
             utente_fine = utentelav,
             id_trasf_fine = pkfraz
       WHERE data_fine_val = TO_DATE ('99991231', 'YYYYMMDD')
         AND (cod_nazionale, foglio, particella, sub, unar) IN (SELECT cod_nazionale, foglio, particella, sub, unar
                                                                  FROM sitistack_unar
                                                                 WHERE pkid = pkidlav AND flag_vari <> 0);

      --INSERISCO LE NUOVE UNARB
      INSERT INTO sitiunar
                  (utente, data_lav, data_inizio_val, cod_nazionale, foglio, particella, sub, unar, tipo_unar, area,
                   sesto_su_fila, sesto_tra_file, num_ceppi, anno_impi, forma_all, flag_irri, cod_dest_prod,
                   cod_tipo_colt, cod_varieta, cod_tipo_vari, num_pian_prod, num_altre, id_trasf, campagna,
                   cod_tipo_vign, tipo_impi, num_cast, gruppo)
        (SELECT utentelav, datalavo, datalavo, cod_nazionale, foglio, particella_dest, sub_dest, unar_dest, tipo_unar,
                area, sesto_su_fila, sesto_tra_file, num_ceppi, anno_impi, forma_all, flag_irri, cod_dest_prod,
                cod_tipo_colt, cod_varieta, cod_tipo_vari, num_pian_prod, num_altre, pkfraz, campagna, cod_tipo_vign,
                tipo_impi, num_cast, gruppo
           FROM sitistack_unar
          WHERE pkid = pkidlav AND (flag_vari NOT IN (0, 3)));
    END IF;

    IF numuiu > 0 THEN
      --FACCIO SCADERE LE UIU
      UPDATE sitiuiu
         SET data_fine_val = datalavo_fine,
             utente_fine = utentelav,
             id_trasf_fine = pkfraz,
             atto_fin = id_atto
       WHERE data_fine_val = TO_DATE ('99991231', 'YYYYMMDD')
         AND (cod_nazionale, foglio, particella, sub, unimm) IN (SELECT cod_nazionale, foglio, particella, sub, unimm
                                                                   FROM sitistack_uiu
                                                                  WHERE pkid = pkidlav AND flag_vari <> 0);

  -- 19/10/2010 FACCIO SCADERE I VANI
--   UPDATE SITIEDI_VANI
--      SET data_fine_val = datalavo_fine,
--      utente_fine = utentelav
--    WHERE data_fine_val = TO_DATE ('99991231', 'YYYYMMDD')
--      AND (cod_nazionale, foglio, particella, sub, unimm) IN (SELECT cod_nazionale, foglio, particella, sub, unimm
--                                                                    FROM sitiuiu su, sitistack_uiu ssu
--                                                                   WHERE ssu.pkid = pkidlav
--                         AND ssu.cod_nazionale = su.cod_nazionale
--                         AND ssu.foglio = su.foglio
--                         AND ssu.particella = su.particella
--                         AND ssu.sub = su.sub
--                         AND ssu.unimm = su.unimm
--                         AND su.data_fine_val < TO_DATE ('99991231', 'YYYYMMDD')
--                       );


  --processaindirizzi (pkidlav, utentelav, 1);
  -- 28/10/2008 MM
      processaindirizzi (pkidlav, utentelav, datalavo_fine, 1);

      --INSERISCO LE NUOVE UIU
      INSERT INTO sitiuiu
                  (utente, sorgente, data_lav, data_inizio_val, cod_nazionale, foglio, particella, sub, particella_urba,
                   sub_urba, unimm, categoria, consistenza, sup_cat, millesimi_terreno, zona, microzona, rendita, note,
                   classe, id_trasf, flag_provenienza, atto_ini, flag_tipo, cod_nazionale_urba, foglio_urba)
        (SELECT utentelav, 0, datalavo, datalavo, cod_nazionale, foglio, particella_dest, sub_dest, particella_urba,
                sub_urba, unimm_dest, categoria, consistenza, sup_cat, millesimi_terreno, zona, microzona, rendita,
                note, classe, pkfraz, 'F', id_atto, flag_tipo, cod_nazionale_urba, foglio_urba
           FROM sitistack_uiu
          WHERE pkid = pkidlav AND (flag_vari NOT IN (0, 3)));

  -- 2010-09-27 -mm - aggiorno la superficie tecnica delle uiu se ï¿½ stata effettuata solo una rinumerazione,
  --          un accorpamento (no frazionamento)
  UPDATE sitiuiu su
     SET supe_modelli =
         (SELECT SUM (supe_modelli)
            FROM sitiuiu su1, sitistack_uiu ssu
           WHERE ssu.cod_nazionale = su.cod_nazionale AND ssu.foglio = su.foglio AND ssu.particella_dest = su.particella
                 AND ssu.sub_dest = su.sub AND ssu.unimm_dest = su.unimm AND ssu.flag_vari = 3 AND ssu.pkid = pkidlav
                 AND ssu.cod_nazionale = su1.cod_nazionale AND ssu.foglio = su1.foglio
                 AND ssu.particella = su1.particella AND ssu.sub = su1.sub AND ssu.unimm = su1.unimm
                 AND ssu.pkid = su1.id_trasf_fine)
       WHERE id_trasf = pkidlav AND data_fine_val = TO_DATE ('31129999', 'DDMMYYYY')
     AND EXISTS (SELECT 1
                   FROM sitistack_uiu ssu
          WHERE ssu.cod_nazionale = su.cod_nazionale
          AND ssu.foglio = su.foglio
                      AND ssu.particella_dest = su.particella
          AND ssu.sub_dest = su.sub
          AND ssu.unimm_dest = su.unimm
                    AND ssu.flag_vari = 3
          AND ssu.pkid = pkidlav);

  -- 2010-09-27 -mm - aggiorno la superficie tecnica delle uiu se ï¿½ stata effettuata solo un aggiornamento di dati
  --                  come ad esempio al via o la sup catastale (no frazionamento )

  UPDATE sitiuiu su
     SET supe_modelli =
         (SELECT supe_modelli
            FROM sitiuiu su1, sitistack_uiu ssu
           WHERE ssu.cod_nazionale = su.cod_nazionale AND ssu.foglio = su.foglio
       AND ssu.particella_dest = su.particella AND ssu.sub_dest = su.sub AND ssu.unimm_dest = su.unimm
     AND ssu.particella = su.particella AND ssu.sub = su.sub AND ssu.unimm = su.unimm
     AND ssu.flag_vari = 1 AND ssu.pkid = pkidlav
             AND ssu.cod_nazionale = su1.cod_nazionale AND ssu.foglio = su1.foglio
             AND ssu.particella = su1.particella AND ssu.sub = su1.sub AND ssu.unimm = su1.unimm
             AND ssu.pkid = su1.id_trasf_fine)
           WHERE id_trasf = pkidlav AND data_fine_val = TO_DATE ('31129999', 'DDMMYYYY')
       AND EXISTS (SELECT 1
                   FROM sitistack_uiu ssu
          WHERE ssu.cod_nazionale = su.cod_nazionale
          AND ssu.foglio = su.foglio
                      AND ssu.particella_dest = su.particella
          AND ssu.sub_dest = su.sub
          AND ssu.unimm_dest = su.unimm
                    AND ssu.particella = su.particella
          AND ssu.sub = su.sub
          AND ssu.unimm = su.unimm
                    AND ssu.flag_vari = 1
          AND ssu.pkid = pkidlav);




  --processaindirizzi (pkidlav, utentelav, 0);
  -- 28/10/2008 MM
      processaindirizzi (pkidlav, utentelav, datalavo, 0);

      --FACCIO SCADERE I CIVICI COLLEGATI COLLE UIU CHE HO FATTO SCADERE
      UPDATE sitiloc_uiu
         SET data_fine_val = datalavo_fine,
             utente_fine = utentelav
       WHERE data_fine_val = TO_DATE ('99991231', 'YYYYMMDD')
         AND pkid_uiu IN (
               SELECT pkid_uiu
                 FROM sitiuiu
                WHERE data_fine_val = datalavo_fine
                  AND (cod_nazionale, foglio, particella, sub, unimm) IN (
                                                                    SELECT cod_nazionale, foglio, particella, sub,
                                                                           unimm
                                                                      FROM sitistack_uiu
                                                                     WHERE pkid = pkidlav AND flag_vari <> 0));

      --REINSERISCO LE IMMAGINI COLLEGATE ALLE NUOVE UIU
      rigenera_immagini (pkidlav, datalavo, utentelav);
    END IF;

    --VARIO CONSISTENZA
    conspartchanged := aggiusta_titoli_part (pkidlav, datalavo, datalavo_fine, tipotr, utentelav, id_atto);

    IF numuiu > 0 THEN
      aggiusta_titoli_uiu (pkidlav, datalavo, datalavo_fine, utentelav, id_atto);
      consuiuchanged := TRUE;
    /*
    Questo blocco di codice va ad inserire anche titoli errati!!!!!
    --CICLO TUTTE LE PARTICELLE PER RICALCOLARE LA QUOTA DI TERRENO
    OPEN c1 FOR
       SELECT   cod_nazionale, foglio, particella, sub
           FROM sitistack_particelle
          WHERE pkid = pkidlav
       GROUP BY cod_nazionale, foglio, particella, sub;

    LOOP
       FETCH c1
        INTO cco, cfo, cpa, csu;

       EXIT WHEN (c1%NOTFOUND);
       aggiorna_terreni (cco, cfo, cpa, csu, datalavo, utentelav);
    END LOOP;

    CLOSE c1;
    */
    END IF;

    --CICLO TUTTE LE PARTICELLE
    clat := '0';

    IF tipotr = '7' THEN
      clat := '1';
    END IF;

    OPEN c1 FOR
      SELECT cod_nazionale, foglio, particella, sub
        FROM sitistack_particelle
       WHERE pkid = pkidlav AND (tipopart = 1 OR tipopart = 2);

    LOOP
      FETCH c1
       INTO cco, cfo, cpa, csu;

      EXIT WHEN (c1%NOTFOUND);

      --INSERISCO IN PLAV
      IF check_gis_data.isanomala (cco, cfo, cpa, csu, datalavo) = 1 THEN
        inserisci_plav (cco, cfo, cpa, csu, id_elenco, provr, setto, utentelav, 'N');
        clat := '0';
      END IF;
    END LOOP;

    CLOSE c1;

    -- FINALMENTE INSERISCO IN SITIFRAZ
    INSERT INTO sitifraz
                (cod_nazionale, foglio, allegato, sviluppo, id_trasf, part_madre, sub_madre, part_figlia, sub_figlia,
                 flag_tipo_trasf, shape, se_row_id, utenteins, flag_tipo_doc, data_lav, flag_lavo)
      (SELECT a.cod_nazionale, a.foglio, '0', '0', c.pkidfraz, a.particella AS part_madre, a.sub AS sub_madre,
              b.particella AS part_figlia, b.sub AS sub_figlia, c.flag_tipo_trasf, b.shape, sitifraz_serow_seq.NEXTVAL,
              utentelav, '2', TO_CHAR (datalavo, 'YYYYMMDDHH24MISS'), clat
         FROM sitistack_particelle a, sitistack_particelle b, sitistack_header c
        WHERE c.pkid = pkidlav AND a.pkid = c.pkid AND b.pkid = c.pkid AND a.tipopart = 1 AND b.tipopart = 2);

    -- Richiamo procedura custom
    sitistack_custom.after_esegui_lavorazione (pkidlav, conspartchanged, consuiuchanged);
  END esegui_lavorazione;

  PROCEDURE rigenera_immagini (pkidlav IN NUMBER, datalavo IN DATE, utenlavo IN VARCHAR2) IS
    TYPE emptycur IS REF CURSOR;

    c1              emptycur;
    c2              emptycur;
    c3              emptycur;
    c4              emptycur;
    c5              emptycur;
    c6              emptycur;
    cco             VARCHAR2 (4);
    cfo             NUMBER (4);
    cpa             VARCHAR2 (5);
    csu             VARCHAR2 (3);
    cun             NUMBER (5);
    cpade           VARCHAR2 (5);
    csude           VARCHAR2 (3);
    cunde           NUMBER (5);
    seekpa          VARCHAR2 (5);
    seeksu          VARCHAR2 (3);
    seekun          NUMBER (5);
    datalavo_fine   DATE;
    oldpkiduiu      NUMBER (9);
    newpkiduiu      NUMBER (9);
    pkcivi          NUMBER (9);
    sca             VARCHAR2 (10);
    pia             NUMBER (5);
    inte            NUMBER (9);
    nomef           VARCHAR2 (70);
    descri          VARCHAR2 (70);
    istp            NUMBER (3);
    progimm         NUMBER (9);
  BEGIN
    datalavo_fine := datalavo - 1 / 24 / 60 / 60;                                                 --UN SECONDO PRIMA...

    OPEN c1 FOR
      SELECT cod_nazionale, foglio, particella, sub, unimm, particella_dest, sub_dest, unimm_dest
        FROM sitistack_uiu
       WHERE pkid = pkidlav AND flag_vari IN (1, 2);

    LOOP
      FETCH c1
       INTO cco, cfo, cpa, csu, cun, cpade, csude, cunde;

      EXIT WHEN (c1%NOTFOUND);
      --CERCO SE CE N'E UNA CANCELLATA CON DEST = CPA...
      seekpa := NULL;

      OPEN c2 FOR
        SELECT particella, sub, unimm
          FROM sitistack_uiu
         WHERE pkid = pkidlav AND flag_vari = 3 AND particella_dest = cpa AND sub_dest = csu AND unimm_dest = cun;

      LOOP
        FETCH c2
         INTO seekpa, seeksu, seekun;

        IF seekpa IS NULL THEN
          IF c2%NOTFOUND THEN
            seekpa := cpa;
            seeksu := csu;
            seekun := cun;
          END IF;
        ELSE
          EXIT WHEN (c2%NOTFOUND);
        END IF;

        --PRENDO PKID_UIU CHE AVEVA (SEEKPA)
        OPEN c3 FOR
          SELECT pkid_uiu
            FROM sitiuiu
           WHERE cod_nazionale = cco
             AND foglio = cfo
             AND particella = seekpa
             AND sub = seeksu
             AND unimm = seekun
             AND data_fine_val = datalavo_fine;

        FETCH c3
         INTO oldpkiduiu;

        IF c3%NOTFOUND THEN
          oldpkiduiu := 0;
        END IF;

        CLOSE c3;

        IF oldpkiduiu > 0 THEN
          --PRENDO PKID_UIU CHE HA (CPADE)
          OPEN c4 FOR
            SELECT pkid_uiu
              FROM sitiuiu
             WHERE cod_nazionale = cco
               AND foglio = cfo
               AND particella = cpade
               AND sub = csude
               AND unimm = cunde
               AND data_fine_val = TO_DATE ('99991231', 'YYYYMMDD');

          FETCH c4
           INTO newpkiduiu;

          IF c4%NOTFOUND THEN
            newpkiduiu := 0;
          END IF;

          CLOSE c4;

          IF newpkiduiu > 0 THEN
                --LEGGO I VALORI DI CIVI_UIU CHE AVEVA
                /*
            OPEN C5 FOR SELECT PKID_CIVI,SCALA,PIANO,INTERNO FROM SITICIVI_UIU WHERE PKID_UIU = OLDPKIDUIU AND DATA_FINE_VAL=DATALAVO_FINE;
                LOOP
                  FETCH C5 INTO PKCIVI,SCA,PIA,INTE;
                  EXIT WHEN (C5%NOTFOUND);
                  --SCRIVO I VALORI DI CIVI_UIU SULLA NUOVA
                  SCRIVI_CIVI_UIU_AUTO(NEWPKIDUIU,PKCIVI,SCA,PIA,INTE,DATALAVO,UTENLAVO);
                END LOOP;
                CLOSE C5;
            */
            progimm := 0;

            OPEN c6 FOR
              SELECT nomefile, descrizione, istatp
                FROM sitiuiu_imm
               WHERE pkid_uiu = oldpkiduiu;

            LOOP
              FETCH c6
               INTO nomef, descri, istp;

              EXIT WHEN (c6%NOTFOUND);
              progimm := progimm + 1;

              INSERT INTO sitiuiu_imm
                          (pkid_uiu, prog_imm, nomefile, descrizione, istatp
                          )
                   VALUES (newpkiduiu, progimm, nomef, descri, istp
                          );
            END LOOP;

            CLOSE c6;
          END IF;
        END IF;
      END LOOP;

      CLOSE c2;
    END LOOP;

    CLOSE c1;
  END rigenera_immagini;

  PROCEDURE scrivi_civi_uiu_auto (
    pkuiu      IN   NUMBER,
    pkcivi     IN   NUMBER,
    sca        IN   VARCHAR2,
    pia        IN   NUMBER,
    inte       IN   NUMBER,
    datalavo   IN   DATE,
    utenlavo   IN   VARCHAR2
  ) IS
    npres    NUMBER (5);
    intern   NUMBER (9);
  BEGIN
    SELECT COUNT (*)
      INTO npres
      FROM siticivi_uiu
     WHERE pkid_civi = pkcivi AND scala = sca AND piano = pia AND interno = inte;

    IF npres > 0 THEN
      SELECT MAX (interno)
        INTO intern
        FROM siticivi_uiu
       WHERE pkid_civi = pkcivi AND scala = sca AND piano = pia;

      intern := intern + 1;
    ELSE
      intern := inte;
    END IF;

    INSERT INTO siticivi_uiu
                (pkid_civi, pkid_uiu, data_inizio_val, data_fine_val, utente, scala, piano, interno
                )
         VALUES (pkcivi, pkuiu, datalavo, TO_DATE ('99991231', 'YYYYMMDD'), utenlavo, sca, pia, intern
                );
  END scrivi_civi_uiu_auto;

  FUNCTION getesitolav (pkidlav IN NUMBER)
    RETURN NUMBER IS
    TYPE emptycur IS REF CURSOR;

    c1      emptycur;
    esito   NUMBER (9);
  BEGIN
    OPEN c1 FOR
      SELECT esitolav
        FROM sitistack_header
       WHERE pkid = pkidlav;

    FETCH c1
     INTO esito;

    IF c1%NOTFOUND THEN
      esito := 0;
    END IF;

    CLOSE c1;

    RETURN esito;
  END getesitolav;

  FUNCTION getpkfraz (pkidlav IN NUMBER)
    RETURN NUMBER IS
    TYPE emptycur IS REF CURSOR;

    c1      emptycur;
    esito   NUMBER (9);
  BEGIN
    OPEN c1 FOR
      SELECT pkidfraz
        FROM sitistack_header
       WHERE pkid = pkidlav;

    FETCH c1
     INTO esito;

    IF c1%NOTFOUND THEN
      esito := 0;
    END IF;

    CLOSE c1;

    RETURN esito;
  END getpkfraz;

  FUNCTION getmindata (pkidlav IN NUMBER)
    RETURN DATE IS
    out_maxdate   DATE;
  BEGIN
    controlla_date (pkidlav, out_maxdate, 1);
    RETURN out_maxdate;
  END;
END sitistack;
/


DROP PACKAGE BODY SITI_H501.SITISTACK_CUSTOM;

CREATE OR REPLACE package body SITI_H501.sitistack_custom AS

  type number_coll is table of number(9);

  function equals(a number_coll, b number_coll) return boolean is
    ret   boolean;
    i     pls_integer;
  begin
    ret := (a.count = b.count);
    if ret and a.count > 0 then
      for i in a.first .. a.last loop
        exit when not ret;
        ret := (a(i) = b(i));
      end loop;
    end if;
    return ret;
  end equals;

  procedure ricalcolaCodiceGruppo(p_pk_cespite number) is
    cursor cPart is
      select distinct cod_nazionale, foglio, particella, sub
        from patri_cespiti_part cp, siticond_all2 t
      where t.pkid_tit = cp.pk_tit
        and t.tipo_titolo = cp.tipo_titolo
        and t.data_fine > sysdate
        and cp.fk_cespite = p_pk_cespite
     group by cod_nazionale, foglio, particella, sub;

   cursor cUiu is
     select distinct cod_nazionale, foglio, particella, sub
       from patri_cespiti_uiu cu, siticonduz_imm_all2 t
      where t.pkid_tit = cu.pk_tit
        and t.tipo_titolo = cu.tipo_titolo
        and t.data_fine > sysdate
        and cu.fk_cespite = p_pk_cespite
     group by cod_nazionale, foglio, particella, sub;

    cnt   pls_integer;
    cn    sitistack_particelle.cod_nazionale%type;
    fg    sitistack_particelle.foglio%type;
    pt    sitistack_particelle.particella%type;
    sb    sitistack_particelle.sub%type;
    ok    boolean;
    cod   patri_cespiti.cod_gruppo%type := null;
  begin

    cnt := 0;
    for r in cPart loop
      cn := r.cod_nazionale;
      fg := r.foglio;
      pt := r.particella;
      sb := r.sub;
      cnt := cnt + 1;
    end loop;

    ok := (cnt <= 1);
    if ok then
      cnt := 0;
      for r in cUiu loop
        exit when not ok;
        ok := (cn = r.cod_nazionale and fg = r.foglio and pt = r.particella and sb = r.sub);
        cn := r.cod_nazionale;
        fg := r.foglio;
        pt := r.particella;
        sb := r.sub;
        cnt := cnt + 1;
      end loop;

      ok := ok and cnt <= 1;
    end if;

    if ok and cnt = 1 then
      begin
        select 'F' || min(trkc_id) into cod
         from sititrkc
        where cod_nazionale = cn
          and foglio = fg
          and particella = pt
          and sub = sb;
      exception when no_data_found then
        cod := null;
      end;
    end if;

    update patri_cespiti set cod_gruppo = cod where pk_cespite = p_pk_cespite;

  end ricalcolaCodiceGruppo;

  procedure syncIndirizzi(pkidlav number) is
    cursor cStackUiu is
      select distinct cu.fk_cespite
        from sitistack_uiu u, patri_cespiti_uiu cu, siticonduz_imm_all2 t
       where u.pkid = pkidlav
         and t.cod_nazionale = u.cod_nazionale
         and t.foglio = u.foglio
         and t.particella = u.particella
         and t.sub = u.sub
         and t.unimm = u.unimm
         and cu.pk_tit = t.pkid_tit
         and cu.tipo_titolo = t.tipo_titolo;
  begin

    for r in cStackUiu loop
      patri_pck.ALLINEA_CESPITE(r.fk_cespite);
    end loop;

  end syncIndirizzi;

  procedure before_esegui_lavorazione(pkidlav in number) is
  begin
    null;
  end before_esegui_lavorazione;

  procedure after_esegui_lavorazione(pkidlav number, consPartChanged boolean, consUiuChanged boolean) is
    cursor cStackPart(tp number) is
      select cod_nazionale, foglio, particella, sub
        from sitistack_particelle
       where pkid = pkidlav
         and tipopart = tp;

    cursor cCespitiPart(cn varchar2, fg number, pt varchar2, sb varchar2) is
      select fk_cespite
        from patri_cespiti_part p, siticond_all2 t
       where t.PKID_TIT = p.PK_TIT
         and t.TIPO_TITOLO = p.TIPO_TITOLO
         and t.cod_nazionale = cn
         and t.foglio=fg
         and t.particella=pt
         and t.sub=sb;

    cursor cStackUiu is
      select * from sitistack_uiu
       where pkid = pkidlav
         and flag_vari != 0
      order by pkid, cod_nazionale, foglio, particella_dest, sub_dest, unimm_dest, flag_vari desc;

    cursor cCespitiPartTouched is
      select distinct fk_cespite
        from sitistack_particelle sp, siticond_all2 t, patri_cespiti_part cp
       where sp.pkid = pkidlav
         and t.cod_nazionale = sp.cod_nazionale
         and t.foglio = sp.foglio
         and t.particella = sp.particella
         and t.sub = sp.sub
         and cp.pk_tit = t.pkid_tit
         and cp.tipo_titolo = t.tipo_titolo;

    cursor cCespitiUiuTouched is
      select distinct fk_cespite
        from sitistack_uiu sp, siticonduz_imm_all2 t, patri_cespiti_uiu cu
       where sp.pkid = pkidlav
         and t.cod_nazionale = sp.cod_nazionale
         and t.foglio = sp.foglio
         and t.particella = sp.particella
         and t.sub = sp.sub
         and t.unimm = sp.unimm
         and cu.pk_tit = t.pkid_tit
         and cu.tipo_titolo = t.tipo_titolo;

    utentelav       sitistack_header.utenteins%type;
    data_lavo       date;
    data_lavo_fine  date;
    tipotr          sitistack_header.flag_tipo_trasf%type;
    ok              boolean;

    cn              sitistack_particelle.cod_nazionale%type;
    fg              sitistack_particelle.foglio%type;
    pt              sitistack_particelle.particella%type;
    sb              sitistack_particelle.sub%type;
    un              sitistack_uiu.unimm%type;

    dummy           pls_integer;
    id_trasf        sitistack_header.PKIDFRAZ%type;
    id_cespiti      number_coll;
    id_cespiti_rif  number_coll := null;
  begin
    if not (consPartChanged or consUiuChanged) then
      return;
    end if;

    SELECT utenteins, datains, flag_tipo_trasf
      INTO utentelav, data_lavo, tipotr
      FROM sitistack_header
     WHERE pkid = pkidlav;

    data_lavo_fine := data_lavo - (1 / 24 / 60 / 60);

    if (consPartChanged) then
      -- Verifico che tutte le madri fossero negli stessi cespiti...
      ok := true;
      for recStack in cStackPart(1) loop
        exit when not ok;

        cn := recStack.cod_nazionale;
        fg := recStack.foglio;
        pt := recStack.particella;
        sb := recStack.sub;

        open cCespitiPart(recStack.cod_nazionale, recStack.foglio, recStack.particella, recStack.sub);
        fetch cCespitiPart bulk collect into id_cespiti;
        close cCespitiPart;

        if id_cespiti_rif is null then
          id_cespiti_rif := id_cespiti;
          id_cespiti := number_coll();
        elsif not equals(id_cespiti_rif, id_cespiti) then
          ok := false;
        end if;
      end loop;

      if ok then
        -- Tutte le madri erano negli stessi cespiti (che sono quelli in id_cespiti_rif)
        if id_cespiti_rif.count > 0 then
          -- Inserisco titolaritï¿½ Figlie negli stessi cespiti...
          -- Visto che tutte le madri DEVONO avere le stesse titolaritï¿½ (controllato da sitistack)
          -- uso l'ultima come riferimento...
          insert into patri_cespiti_part (FK_CESPITE, PK_TIT, TIPO_TITOLO, PKID)
            select p.fk_cespite, t_new.PKID_TIT, t_new.tipo_titolo, patri_cespiti_part_uiu_seq.nextval
              from patri_cespiti_part p, sitistack_particelle sp, siticond_all2 t, siticond_all2 t_new
             where p.PK_TIT = t.PKID_TIT
               and p.TIPO_TITOLO = t.TIPO_TITOLO
               and t.cod_nazionale = cn
               and t.foglio=fg
               and t.particella=pt
               and t.sub=sb
               and t.data_fine >= data_lavo_fine
               and sp.pkid=pkidlav
               and sp.TIPOPART = 2
               and t_new.pk_cuaa = t.pk_cuaa
               and t_new.TIPO_TITOLO = t.TIPO_TITOLO
               and t_new.cod_nazionale = sp.cod_nazionale
               and t_new.foglio=sp.foglio
               and t_new.particella=sp.particella
               and t_new.sub=sp.sub
               and t_new.data_fine = to_date('99991231', 'yyyymmdd')
					AND (sp.cod_nazionale, sp.foglio, sp.particella, sp.sub) NOT IN (SELECT cod_nazionale,
                                                                               			foglio,
                                                                               			particella,
                                                                               			sub
                                                                          			 FROM sitistack_particelle
                                                                         			WHERE pkid = pkidlav
																											  AND tipopart = 1);
        end if;
      else
        select PKIDFRAZ into id_trasf from sitistack_header where pkid=pkidlav;

    if id_cespiti_rif is not null and id_cespiti_rif.count > 0 then
         for dummy in id_cespiti_rif.first .. id_cespiti_rif.last loop

           insert into patri_cespiti_ko (FK_CESPITE, FK_FRAZ) values (id_cespiti_rif(dummy), id_trasf);
         end loop;
    end if;
      end if;

      for r in cCespitiPartTouched loop
        --ricalcolaCodiceGruppo(r.fk_cespite);
    patri_pck.allinea_cespite(r.fk_cespite);
      end loop;
    end if;

    if (consUiuChanged) then
      cn := null;
      fg := null;
      pt := null;
      sb := null;
      un := null;
      ok := true;
      id_cespiti_rif := null;
      id_cespiti := number_coll();

      for rec in cStackUiu loop
        if (rec.flag_vari = 3) then
          if (rec.particella_dest != rec.particella or
              rec.sub_dest != rec.sub or
              rec.unimm_dest != rec.unimm)
          then
            ok := true;

            -- Leggi i cespiti della madre
            select fk_cespite bulk collect into id_cespiti
              from patri_cespiti_uiu u, siticonduz_imm_all2 t
             where t.PKID_TIT = u.PK_TIT
               and t.TIPO_TITOLO = u.TIPO_TITOLO
               and t.cod_nazionale = rec.cod_nazionale
               and t.foglio=rec.foglio
               and t.particella=rec.particella
               and t.sub=rec.sub
               and t.unimm=rec.unimm;

            if (id_cespiti_rif is null) then
              id_cespiti_rif := id_cespiti;
              id_cespiti := number_coll();

              cn := rec.cod_nazionale;
              fg := rec.foglio;
              pt := rec.particella;
              sb := rec.sub;
              un := rec.unimm;

            elsif not equals(id_cespiti_rif, id_cespiti) then
              ok := false;
            end if;
          end if;
        else
          if ok then
            if id_cespiti_rif is not null then
              -- Accorpamento...
              -- I cespiti delle madri sono = e sono contenuti in id_cespiti_rif
              insert into patri_cespiti_uiu (FK_CESPITE, PK_TIT, TIPO_TITOLO, PKID)
                select u.fk_cespite, t_new.PKID_TIT, t_new.tipo_titolo, patri_cespiti_part_uiu_seq.nextval
                  from patri_cespiti_uiu u, siticonduz_imm_all2 t, siticonduz_imm_all2 t_new
                 where u.PK_TIT = t.PKID_TIT
                   and u.TIPO_TITOLO = t.TIPO_TITOLO
                   and t.cod_nazionale = cn
                   and t.foglio=fg
                   and t.particella=pt
                   and t.sub=sb
                   and t.unimm=un
                   and t.data_fine = data_lavo_fine
                   and t_new.pk_cuaa = t.pk_cuaa
                   and t_new.TIPO_TITOLO = t.TIPO_TITOLO
                   and t_new.cod_nazionale = rec.cod_nazionale
                   and t_new.foglio=rec.foglio
                   and t_new.particella=rec.particella
                   and t_new.sub=rec.sub
                   and t_new.unimm = rec.unimm
                   and t_new.data_fine = to_date('99991231', 'yyyymmdd');
            else
              insert into patri_cespiti_uiu (FK_CESPITE, PK_TIT, TIPO_TITOLO, PKID)
                select u.fk_cespite, t_new.PKID_TIT, t_new.tipo_titolo, patri_cespiti_part_uiu_seq.nextval
                  from patri_cespiti_uiu u, siticonduz_imm_all2 t, siticonduz_imm_all2 t_new
                 where u.PK_TIT = t.PKID_TIT
                   and u.TIPO_TITOLO = t.TIPO_TITOLO
                   and t.cod_nazionale = rec.cod_nazionale
                   and t.foglio=rec.foglio
                   and t.particella=rec.particella
                   and t.sub=rec.sub
                   and t.unimm=rec.unimm
                   and t.data_fine = data_lavo_fine
                   and t_new.pk_cuaa = t.pk_cuaa
                   and t_new.TIPO_TITOLO = t.TIPO_TITOLO
                   and t_new.cod_nazionale = rec.cod_nazionale
                   and t_new.foglio=rec.foglio
                   and t_new.particella=rec.particella_dest
                   and t_new.sub=rec.sub_dest
                   and t_new.unimm = rec.unimm_dest
                   and t_new.data_fine = to_date('99991231', 'yyyymmdd');
            end if;

          elsif id_cespiti_rif is not null then
            -- Accorpamento in cui le madri sono in cespiti diversi...
            select PKIDFRAZ into id_trasf from sitistack_header where pkid=pkidlav;

            insert into patri_cespiti_ko (FK_CESPITE, FK_FRAZ)
              select distinct fk_cespite, id_trasf
                from patri_cespiti_uiu u, siticonduz_imm_all2 t
               where u.pk_tit = t.pkid_tit
                 and u.tipo_titolo = t.tipo_titolo
                 and (t.cod_nazionale, t.foglio, t.particella, t.sub, t.unimm) in
                     (select cod_nazionale, foglio, particella, sub, unimm
                       from sitistack_uiu
                      where cod_nazionale = rec.cod_nazionale
                        and foglio=rec.foglio
                        and particella_dest=rec.particella
                        and sub_dest = rec.sub
                        and unimm_dest = rec.unimm);
          end if;

          cn := null;
          fg := null;
          pt := null;
          sb := null;
          un := null;
          id_cespiti_rif := null;
          ok := true;
        end if;
      end loop;

      for r in cCespitiUiuTouched loop
        --ricalcolaCodiceGruppo(r.fk_cespite);
    patri_pck.allinea_cespite(r.fk_cespite);
      end loop;

      --syncIndirizzi(pkidlav);
    end if;
  end after_esegui_lavorazione;

end sitistack_custom;
/


DROP PACKAGE BODY SITI_H501.SITISTAT_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.sitistat_pck
IS
   PROCEDURE stat_particelle (
      incodnazionale   IN       VARCHAR2,
      valide           OUT      NUMBER,
      archiviate       OUT      NUMBER,
      fogli            OUT      NUMBER,
      sup_part         OUT      NUMBER,
      sup_suolo        OUT      NUMBER,
      sup_fogli        OUT      NUMBER
   )
   IS
      sql_stmt   VARCHAR2 (1000);
   BEGIN
      sql_stmt :=
         'select count(*) from sitipart where data_fine_val=to_date(''99991231'',''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO valide;

      sql_stmt :=
         'select count(*) from sitipart where data_fine_val<>to_date(''99991231'',''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO archiviate;

      sql_stmt := 'select count(*) from sitifglc';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
              sql_stmt || ' where cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO fogli;

      sql_stmt :=
         'SELECT
  ROUND(SUM(SDO_GEOM.SDO_AREA(shape,1)) * 0.0001)
FROM sitifglc';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
              sql_stmt || ' where cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO sup_fogli;

      sql_stmt :=
         'SELECT /*+ FULL (sitipart) */
  ROUND(SUM(area_part) * 0.0001)
FROM sitipart
WHERE data_fine_val = TO_DATE(''99991231'', ''YYYYMMDD'') ';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO sup_part;

      sql_stmt :=
         'SELECT /*+ FULL (sitisuolo) */
  ROUND(SUM(area_colt) * 0.0001)
FROM sitisuolo
WHERE data_fine_val = TO_DATE(''99991231'', ''YYYYMMDD'') ';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO sup_suolo;
   END;

   PROCEDURE stat_censuario_ter (
      incodnazionale   IN       VARCHAR2,
      valide           OUT      NUMBER,
      archiviate       OUT      NUMBER,
      superficie       OUT      NUMBER
   )
   IS
      sql_stmt   VARCHAR2 (1000);
   BEGIN
      sql_stmt := 'select count(*) from sititrkc where valida=1';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO valide;

      sql_stmt := 'select count(*) from sititrkc where valida=0';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO archiviate;

      sql_stmt :=
             'select round(sum(area_part)/10000) from sititrkc where valida=1';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO superficie;
   END;

   PROCEDURE stat_censuario_uiu (
      incodnazionale   IN       VARCHAR2,
      valide           OUT      NUMBER,
      archiviate       OUT      NUMBER
   )
   IS
      sql_stmt   VARCHAR2 (1000);
   BEGIN
      sql_stmt :=
         'select count(*) from sitiuiu where data_fine_val=to_date(''99991231'',''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO valide;

      sql_stmt :=
         'select count(*) from sitiuiu where data_fine_val<>to_date(''99991231'',''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO archiviate;
   END;

   PROCEDURE stat_consistenza (
      incodnazionale   IN       VARCHAR2,
      propr_ter        OUT      NUMBER,
      altro_ter        OUT      NUMBER,
      propr_uiu        OUT      NUMBER,
      altro_uiu        OUT      NUMBER,
      ter_con_prop     OUT      NUMBER,
      ter_con_altro    OUT      NUMBER,
      uiu_con_prop     OUT      NUMBER,
      uiu_con_altro    OUT      NUMBER
   )
   IS
      sql_stmt   VARCHAR2 (1000);
   BEGIN
      sql_stmt :=
         '  SELECT /*+ INDEX (cons_cons_tab CONS_CONS_CPK) */
  COUNT(distinct pk_cuaa)
FROM cons_cons_tab
WHERE pk_cuaa < 999999999
  AND data_fine = TO_DATE(''99991231'', ''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO propr_ter;

      sql_stmt :=
         '  SELECT /*+ INDEX (cons_csui_tab CONS_csui_CPK) */
  COUNT(distinct pk_cuaa)
FROM cons_csui_tab
WHERE pk_cuaa < 999999999
  AND data_fine = TO_DATE(''99991231'', ''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO propr_uiu;

      sql_stmt :=
         '  SELECT /*+ INDEX (cons_ufre_tab CONS_ufre_CPK) */
  COUNT(distinct pk_cuaa)
FROM cons_ufre_tab
WHERE pk_cuaa < 999999999
  AND data_fine = TO_DATE(''99991231'', ''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO altro_ter;

      sql_stmt :=
         '  SELECT /*+ INDEX (cons_urui_tab CONS_urui_CPK) */
  COUNT(distinct pk_cuaa)
FROM cons_urui_tab
WHERE pk_cuaa < 999999999
  AND data_fine = TO_DATE(''99991231'', ''YYYYMMDD'')';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      EXECUTE IMMEDIATE sql_stmt
                   INTO altro_uiu;

      sql_stmt :=
         'select count(*) from(SELECT /*+ INDEX (cons_cons_tab CONS_CONS_CPK) */
  1
FROM cons_cons_tab
WHERE
   data_fine = TO_DATE(''99991231'', ''YYYYMMDD'') and pk_cuaa<999999999';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      sql_stmt :=
              sql_stmt || ' group by
  cod_nazionale,foglio,particella,sub )';

      EXECUTE IMMEDIATE sql_stmt
                   INTO ter_con_prop;

      sql_stmt :=
         'select count(*) from(SELECT /*+ INDEX (cons_ufre_tab CONS_UFRE_CPK) */
  1
FROM cons_ufre_tab
WHERE
   data_fine = TO_DATE(''99991231'', ''YYYYMMDD'') and pk_cuaa<999999999';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      sql_stmt :=
              sql_stmt || ' group by
  cod_nazionale,foglio,particella,sub )';

      EXECUTE IMMEDIATE sql_stmt
                   INTO ter_con_altro;

      sql_stmt :=
         'select count(*) from(SELECT /*+ INDEX (cons_csui_tab CONS_CSUI_CPK) */
  1
FROM cons_CSUI_tab
WHERE
   data_fine = TO_DATE(''99991231'', ''YYYYMMDD'') and pk_cuaa<999999999';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      sql_stmt :=
              sql_stmt || ' group by
  cod_nazionale,foglio,particella,sub,unimm )';

      EXECUTE IMMEDIATE sql_stmt
                   INTO uiu_con_prop;

      sql_stmt :=
         'select count(*) from(SELECT /*+ INDEX (cons_urui_tab CONS_URUI_CPK) */
  1
FROM cons_urui_tab
WHERE
   data_fine = TO_DATE(''99991231'', ''YYYYMMDD'') and pk_cuaa<999999999';

      IF incodnazionale IS NOT NULL
      THEN
         sql_stmt :=
                sql_stmt || ' and cod_nazionale=''' || incodnazionale || '''';
      END IF;

      sql_stmt :=
              sql_stmt || ' group by
  cod_nazionale,foglio,particella,sub,unimm )';

      EXECUTE IMMEDIATE sql_stmt
                   INTO uiu_con_altro;
   END;
END;

/


DROP PACKAGE BODY SITI_H501.SITIUIU_PCK;

CREATE OR REPLACE package body SITI_H501.SITIUIU_PCK is 
  /* Costanti private*/ 
  DT_ATTUALE constant date := to_date('31-12-9999', 'dd-mm-yyyy'); 
  /* Controllo esistenza civico*/ 
  procedure check_civico(pkCivi number, dtFine date, dtIni date default null) is 
    nDummy    number; 
  begin 
     
    if dtIni is not null then 
      select count(*)  
        into nDummy  
        from siticivi c 
       where c.pkid_civi=pkCivi 
         and c.data_inizio_val <= dtIni 
         and c.data_fine_val >= dtFine; 
    else 
      select count(*)  
        into nDummy  
        from siticivi c 
       where c.pkid_civi=pkCivi 
         and c.data_inizio_val <= dtFine 
         and c.data_fine_val >= dtFine;       
    end if; 
    if (nDummy is null or nDummy = 0) then 
      Raise_application_error(-20001, 'unknown_civico'); 
    end if; 
   
  end check_civico; 
  /* Inserisce 1 civico per 1 UIU*/ 
  procedure insert_indirizzo(pkCivi number, pkUiu number, dtIni date, dtFine date,  
                             utente varchar2, princ char, pPiano varchar2, pInterno varchar2,  
                             pScala varchar2) is 
    nDummy        number; 
    dtFineToUse   date; 
     
  begin 
     
    if (dtFine is null) then 
      dtFineToUse := DT_ATTUALE; 
    else 
      dtFineToUse := dtFine; 
    end if; 
     
    check_civico(pkCivi, dtIni, dtFineToUse); 
     
    /* Controllo esistenza UIU*/ 
    select count(*) 
      into nDummy 
      from sitiuiu u 
     where u.pkid_uiu = pkUiu 
       and u.data_inizio_val <= dtIni 
       and u.data_fine_val >= dtFineToUse; 
     
    if (nDummy is null or nDummy = 0) then 
      Raise_application_error(-20002, 'unknown_uiu'); 
    end if; 
     
    /* Controllo esistenza associazione...*/ 
    select count(*) 
      into nDummy 
      from siticivi_uiu 
     where PKID_CIVI = pkCivi 
       and PKID_UIU = pkUiu 
       and data_inizio_val <= dtIni 
       and data_fine_val >= dtFineToUse; 
     
    if (nDummy is null or nDummy = 0) then 
      /* Tolgo eventuali altri civici principali...*/ 
      if (princ = 'Y') then 
        update siticivi_uiu 
           set principale = 'N' 
         where principale = 'Y' 
           and pkid_uiu = pkUiu 
           and data_inizio_val <= dtIni 
           and data_fine_val >= dtFineToUse; 
      end if; 
      insert into siticivi_uiu  
        (pkid_civi, pkid_uiu, data_inizio_val, data_fine_val, utente, scala, piano, interno, utente_fine, principale) 
        values 
        (pkCivi, pkUiu, dtIni, dtFineToUse, insert_indirizzo.utente, pScala, pPiano, pInterno, decode(dtFine, DT_ATTUALE, null, insert_indirizzo.utente), princ); 
    else 
      raise dup_val_on_index; 
    end if; 
  end insert_indirizzo; 
  procedure set_indrizzo_pincipale(pkCivi number, pkUiu number, dtFine date, princ char default 'Y') is 
    dtFineToUse     date; 
  begin 
     
    if (dtFine is null) then 
      dtFineToUse := DT_ATTUALE; 
    else 
      dtFineToUse := dtFine; 
    end if; 
    /* Tolgo eventuali altri civici principali...*/ 
    if (princ = 'Y') then 
      update siticivi_uiu 
         set principale = 'N' 
       where principale = 'Y' 
         and pkid_uiu = pkUiu 
         and data_inizio_val <= dtFineToUse 
         and data_fine_val >= dtFineToUse; 
    end if; 
     
    /* Imposto il principale*/ 
    update siticivi_uiu c 
       set principale = princ 
     where c.pkid_civi = pkCivi 
       and c.pkid_uiu = pkUiu 
       and c.data_fine_val = dtFineToUse; 
     
  end set_indrizzo_pincipale; 
   
  /* Author  : NOLLI*/ 
  /* Created : 04/11/2005 11.15.06*/ 
  /* Purpose : Fa scadere un civico associato ad una UIU*/ 
  procedure scadi_indirizzo(dtFine date, theUser varchar2, pkUiu number, pkCivi number default null) is 
    nDummy      number; 
  begin 
     
    if (pkCivi is not null) then 
      select count(*) 
        into nDummy 
        from siticivi_uiu 
       where pkid_civi = pkCivi 
         and pkid_uiu = pkUiu 
         and data_fine_val = DT_ATTUALE; 
       
      if (nDummy = 0) then 
      	return; 
        /*Raise_application_error(-20003, 'unknown_indirizzo');*/ 
      end if; 
      update siticivi_uiu 
         set data_fine_val = dtFine, 
             utente_fine = theUser 
       where pkid_civi = pkCivi 
         and pkid_uiu = pkUiu 
         and data_fine_val = DT_ATTUALE; 
    else 
      update siticivi_uiu 
         set data_fine_val = dtFine, 
             utente_fine = theUser 
       where pkid_uiu = pkUiu 
         and data_fine_val = DT_ATTUALE; 
    end if; 
     
  end scadi_indirizzo; 
end SITIUIU_PCK; 

/


DROP PACKAGE BODY SITI_H501.SITIUTILS;

CREATE OR REPLACE PACKAGE BODY SITI_H501.sitiutils AS

PROCEDURE RPTREFRESHCOM(CODNAZ IN VARCHAR2, RETVALUE OUT NUMBER)
IS
  FG NUMBER(4);
  CURSOR C1 IS SELECT FOGLIO FROM SITICOND WHERE COD_NAZIONALE=CODNAZ GROUP BY FOGLIO;
BEGIN
  OPEN C1;
  LOOP
      FETCH C1 INTO FG;
     EXIT WHEN (C1%NOTFOUND);
      ANOMALIEFOG_TER(CODNAZ,FG,1);
  END LOOP;
  CLOSE C1;
  RETVALUE:=1;

  EXCEPTION WHEN OTHERS THEN
    RETVALUE:=0;
END RPTREFRESHCOM;

PROCEDURE UIRPTREFRESHCOM(CODNAZ IN VARCHAR2, RETVALUE OUT NUMBER)
IS
  FG NUMBER(4);
  CURSOR C1 IS SELECT FOGLIO FROM SITICOND_IMM WHERE COD_NAZIONALE=CODNAZ GROUP BY FOGLIO;
BEGIN
  OPEN C1;
  LOOP
      FETCH C1 INTO FG;
     EXIT WHEN (C1%NOTFOUND);
      UIANOMALIEFOG_TER(CODNAZ,FG,2);
  END LOOP;
  CLOSE C1;
  RETVALUE:=1;

  EXCEPTION WHEN OTHERS THEN
    RETVALUE:=0;
END UIRPTREFRESHCOM;

PROCEDURE GISRPTREFRESHCOM(CODNAZ IN VARCHAR2, RETVALUE OUT NUMBER)
IS
  FG NUMBER(4);
  CURSOR C1 IS SELECT FOGLIO FROM SITICENT WHERE COD_NAZIONALE=CODNAZ GROUP BY FOGLIO;
BEGIN
  OPEN C1;
  LOOP
      FETCH C1 INTO FG;
     EXIT WHEN (C1%NOTFOUND);
      GISANOMALIEFOG_TER(CODNAZ,FG,2);
  END LOOP;
