  EXCEPTION WHEN OTHERS THEN
    RETVALUE:=0;
END GISRPTREFRESHCOM;

PROCEDURE CERPTREFRESHCOM(CODNAZ IN VARCHAR2, RETVALUE OUT NUMBER)
IS
  FG NUMBER(4);
  CURSOR C1 IS SELECT FOGLIO FROM SITICATA WHERE COD_NAZIONALE=CODNAZ GROUP BY FOGLIO;
BEGIN
  OPEN C1;
  LOOP
      FETCH C1 INTO FG;
     EXIT WHEN (C1%NOTFOUND);
      CEANOMALIEFOG_TER(CODNAZ,FG,4);
  END LOOP;
  CLOSE C1;
  RETVALUE:=1;

  EXCEPTION WHEN OTHERS THEN
    RETVALUE:=0;
END CERPTREFRESHCOM;

PROCEDURE CURPTREFRESHCOM(CODNAZ IN VARCHAR2, RETVALUE OUT NUMBER)
IS
  FG NUMBER(4);
  CURSOR C1 IS SELECT FOGLIO FROM SITICATA_IMM WHERE COD_NAZIONALE=CODNAZ GROUP BY FOGLIO;
BEGIN
  OPEN C1;
  LOOP
      FETCH C1 INTO FG;
     EXIT WHEN (C1%NOTFOUND);
      CUANOMALIEFOG_TER(CODNAZ,FG,5);
  END LOOP;
  CLOSE C1;
  RETVALUE:=1;

  EXCEPTION WHEN OTHERS THEN
    RETVALUE:=0;
END CURPTREFRESHCOM;

PROCEDURE ANOMALIEFOG_TER(CODNAZ IN VARCHAR2, FOG IN NUMBER, GRUPPO IN NUMBER)
IS
  INANOMALIA NUMBER(9);
  ANOMTOT NUMBER(9):=0;
  ANOM1 NUMBER(9):=0;
  ANOM2 NUMBER(9):=0;
  ANOM3 NUMBER(9):=0;
  ANOM4 NUMBER(9):=0;
  ANOM5 NUMBER(9):=0;
  ANOM6 NUMBER(9):=0;
  ANOM7 NUMBER(9):=0;
  ANOM8 NUMBER(9):=0;
  ANOM9 NUMBER(9):=0;
  ANOM10 NUMBER(9):=0;
  SESSIO DATE;

  PART VARCHAR2(5);
  SUBA VARCHAR2(3);

  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;
  C2 EMPTYCUR;
  C3 EMPTYCUR;
  C4 EMPTYCUR;

  DATACTR DATE;

  NUMCENT NUMBER(9):=0;
  NUMAZIE1 NUMBER(9):=0;
  NUMAZIE2 NUMBER(9):=0;
  NUMAZIE3 NUMBER(9):=0;
  NUMAZIE4 NUMBER(9):=0;
  NUMAZIE5 NUMBER(9):=0;
  NUMAZIE6 NUMBER(9):=0;
  NUMAZIE7 NUMBER(9):=0;
  NUMAZIE8 NUMBER(9):=0;
  NUMAZIE9 NUMBER(9):=0;
  NUMAZIE10 NUMBER(9):=0;
  NUMAZIE NUMBER(9):=0;

  GISVSCENS NUMBER(9):=0;

  ESISTECOM NUMBER;
BEGIN
  SESSIO:=SYSDATE;
  DATACTR:=To_Date('99991231000000','YYYYMMDDHH24MISS');

  OPEN C4 FOR SELECT 1 FROM SITICOMU WHERE COD_NAZIONALE=CODNAZ;
  FETCH C4 INTO ESISTECOM;
  IF C4%NOTFOUND THEN     ESISTECOM:=0;   END IF;
  CLOSE C4;

  OPEN C1 FOR SELECT PARTICELLA,SUB FROM SITICOND WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO <= DATACTR AND DATA_FINE >= DATACTR GROUP BY PARTICELLA,SUB;
  LOOP
      FETCH C1 INTO PART,SUBA;
     EXIT WHEN (C1%NOTFOUND);

      INANOMALIA:=0;
      IF CHECK_GIS_DATA.ANOMALIA1(CODNAZ,FOG,PART,SUBA,DATACTR) > 0 THEN
        ANOM1:=ANOM1+1;
        INANOMALIA:=INANOMALIA + 1;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA2(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM2:=ANOM2+1;
        INANOMALIA:=INANOMALIA + 2;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA3(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM3:=ANOM3+1;
        INANOMALIA:=INANOMALIA + 4;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA4(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM4:=ANOM4+1;
        INANOMALIA:=INANOMALIA + 8;
      END IF;

      GISVSCENS:=CHECK_GIS_DATA.GISVSCENS(CODNAZ,FOG,PART,SUBA,DATACTR);

      IF GISVSCENS > 0 THEN
        IF GISVSCENS = 1 THEN
          ANOM5:=ANOM5+1;
          INANOMALIA:=INANOMALIA + 16;
        END IF;
        IF GISVSCENS = 3 THEN
          ANOM6:=ANOM6+1;
          INANOMALIA:=INANOMALIA + 32;
        END IF;
        IF GISVSCENS = 4 THEN
          ANOM7:=ANOM7+1;
          INANOMALIA:=INANOMALIA + 64;
        END IF;
        IF GISVSCENS = 2 THEN
          ANOM8:=ANOM8+1;
          INANOMALIA:=INANOMALIA + 128;
        END IF;
        IF GISVSCENS = 5 THEN
          ANOM9:=ANOM9+1;
          INANOMALIA:=INANOMALIA + 256;
        END IF;
        IF GISVSCENS = 6 THEN
          ANOM10:=ANOM10+1;
          INANOMALIA:=INANOMALIA + 512;
        END IF;
      END IF;
      IF INANOMALIA>0 THEN
        INSERT INTO CALC_ANOM(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,FLAG_ANOM)
        VALUES(CODNAZ,FOG,PART,SUBA,INANOMALIA);
        ANOMTOT:=ANOMTOT+1;
      END IF;
  END LOOP;

  CLOSE C1;

  DELETE FROM SITIFGAN WHERE (TIPO_ANOM>=1 AND TIPO_ANOM<=10) AND COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
  DELETE FROM SITIRPAN WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
  DELETE FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
--  COMMIT;

  IF ANOMTOT > 0 THEN
    OPEN C2 FOR SELECT /*+ INDEX (SITICENT SITICENT_PK) */ Count(*) FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATACTR AND DATA_FINE_VAL >= DATACTR;
    FETCH C2 INTO NUMCENT;
    IF C2%NOTFOUND THEN NUMCENT:=0; END IF;
    CLOSE C2;

    INSERT INTO SITIRPAN_CUAA_TAB(CUAA,COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,FLAG_ANOM)
    (
        SELECT A.CUAA,A.COD_NAZIONALE,A.FOGLIO,B.particella,b.sub,B.FLAG_ANOM FROM SITICOND A,CALC_ANOM B
        WHERE
        A.COD_NAZIONALE=CODNAZ AND
        A.FOGLIO=FOG AND
        A.DATA_INIZIO <= DATACTR AND A.DATA_FINE >= DATACTR AND
        B.COD_NAZIONALE=A.COD_NAZIONALE AND
        B.FOGLIO=A.FOGLIO AND
        B.PARTICELLA=A.PARTICELLA AND
        B.SUB = A.SUB
        GROUP BY A.CUAA,A.COD_NAZIONALE,A.FOGLIO,B.particella,b.sub,B.FLAG_ANOM
    );

    IF ANOM1>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,1)=1 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE1;
      IF C3%NOTFOUND THEN NUMAZIE1:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(1,FOG,ANOM1,NUMAZIE1,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM2>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,2)=2 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE2;
      IF C3%NOTFOUND THEN NUMAZIE2:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(2,FOG,ANOM2,NUMAZIE2,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM3>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,4)=4 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE3;
      IF C3%NOTFOUND THEN NUMAZIE3:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(3,FOG,ANOM3,NUMAZIE3,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM4>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,8)=8 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE4;
      IF C3%NOTFOUND THEN NUMAZIE4:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(4,FOG,ANOM4,NUMAZIE4,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM5>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,16)=16 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE5;
      IF C3%NOTFOUND THEN NUMAZIE5:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(5,FOG,ANOM5,NUMAZIE5,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM6>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,32)=32 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE6;
      IF C3%NOTFOUND THEN NUMAZIE6:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(6,FOG,ANOM6,NUMAZIE6,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM7>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,64)=64 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE7;
      IF C3%NOTFOUND THEN NUMAZIE7:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(7,FOG,ANOM7,NUMAZIE7,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM8>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,128)=128 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE8;
      IF C3%NOTFOUND THEN NUMAZIE8:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(8,FOG,ANOM8,NUMAZIE8,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM9>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,256)=256 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE9;
      IF C3%NOTFOUND THEN NUMAZIE8:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(9,FOG,ANOM9,NUMAZIE9,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM10>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,512)=512 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE10;
      IF C3%NOTFOUND THEN NUMAZIE8:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(10,FOG,ANOM10,NUMAZIE10,SESSIO,NUMCENT,1,CODNAZ);
    END IF;

    OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM SITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG GROUP BY CUAA);
    FETCH C3 INTO NUMAZIE;
    IF C3%NOTFOUND THEN NUMAZIE:=0; END IF;
    CLOSE C3;

    INSERT INTO SITIRPAN (foglio,num_part_tot,num_azie_tot,num_part_an1,num_azie_an1,num_part_an2,num_azie_an2,num_part_an3,num_azie_an3,num_part_an4,num_azie_an4,num_part_an5,num_azie_an5,num_part_an6,num_azie_an6,num_part_an7,num_azie_an7,num_part_an8,num_azie_an8,num_part_an9,num_azie_an9,num_part_an10,num_azie_an10,num_cent,flag_pres_mappa,cod_nazionale,data_aggi)
    VALUES(FOG,ANOMTOT,NUMAZIE,ANOM1,NUMAZIE1,ANOM2,NUMAZIE2,ANOM3,NUMAZIE3,ANOM4,NUMAZIE4,ANOM5,NUMAZIE5,ANOM6,NUMAZIE6,ANOM7,NUMAZIE7,ANOM8,NUMAZIE8,ANOM9,NUMAZIE9,ANOM10,NUMAZIE10,NUMCENT,NVL((SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND ROWNUM=1),0),CODNAZ,SESSIO);
  END IF;
  COMMIT;
END ANOMALIEFOG_TER;

PROCEDURE UIANOMALIEFOG_TER(CODNAZ IN VARCHAR2, FOG IN NUMBER, GRUPPO IN NUMBER)
IS
  INANOMALIA NUMBER(9);
  ANOMTOT NUMBER(9):=0;
  ANOM21 NUMBER(9):=0;
  ANOM22 NUMBER(9):=0;
  ANOM23 NUMBER(9):=0;
  ANOM24 NUMBER(9):=0;
  ANOM25 NUMBER(9):=0;
  ANOM26 NUMBER(9):=0;
  ANOM27 NUMBER(9):=0;
  ANOM28 NUMBER(9):=0;
  ANOM29 NUMBER(9):=0;
  ANOM30 NUMBER(9):=0;
  SESSIO DATE;

  PART VARCHAR2(5);
  SUBA VARCHAR2(3);

  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;
  C2 EMPTYCUR;
  C3 EMPTYCUR;

  DATACTR DATE;

  NUMCENT NUMBER;
  NUMAZIE21 NUMBER(9):=0;
  NUMAZIE22 NUMBER(9):=0;
  NUMAZIE23 NUMBER(9):=0;
  NUMAZIE24 NUMBER(9):=0;
  NUMAZIE25 NUMBER(9):=0;
  NUMAZIE26 NUMBER(9):=0;
  NUMAZIE27 NUMBER(9):=0;
  NUMAZIE28 NUMBER(9):=0;
  NUMAZIE29 NUMBER(9):=0;
  NUMAZIE30 NUMBER(9):=0;
  NUMAZIE NUMBER(9):=0;

  GISVSCENS NUMBER(9):=0;
BEGIN
  SESSIO:=SYSDATE;
  DATACTR:=To_Date('99991231000000','YYYYMMDDHH24MISS');
  OPEN C1 FOR SELECT PARTICELLA,SUB FROM SITICOND_IMM WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO <= DATACTR AND DATA_FINE >= DATACTR GROUP BY PARTICELLA,SUB;
  LOOP
      FETCH C1 INTO PART,SUBA;
     EXIT WHEN (C1%NOTFOUND);

      INANOMALIA:=0;
      IF CHECK_GIS_DATA.ANOMALIA21(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM21:=ANOM21+1;
        INANOMALIA:=INANOMALIA + 1;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA22(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM22:=ANOM22+1;
        INANOMALIA:=INANOMALIA + 2;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA23(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM23:=ANOM23+1;
        INANOMALIA:=INANOMALIA + 4;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA24(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM24:=ANOM24+1;
        INANOMALIA:=INANOMALIA + 8;
      END IF;
      GISVSCENS:=CHECK_GIS_DATA.GISVSCENS(CODNAZ,FOG,PART,SUBA,DATACTR);

      IF GISVSCENS > 0 THEN
        IF GISVSCENS = 1 THEN
          ANOM25:=ANOM25+1;
          INANOMALIA:=INANOMALIA + 16;
        END IF;
        IF GISVSCENS = 3 THEN
          ANOM26:=ANOM26+1;
          INANOMALIA:=INANOMALIA + 32;
        END IF;
        IF GISVSCENS = 4 THEN
          ANOM27:=ANOM27+1;
          INANOMALIA:=INANOMALIA + 64;
        END IF;
        IF GISVSCENS = 2 THEN
          ANOM28:=ANOM28+1;
          INANOMALIA:=INANOMALIA + 128;
        END IF;
        IF GISVSCENS = 5 THEN
          ANOM29:=ANOM29+1;
          INANOMALIA:=INANOMALIA + 256;
        END IF;
        IF GISVSCENS = 6 THEN
          ANOM30:=ANOM30+1;
          INANOMALIA:=INANOMALIA + 512;
        END IF;
      END IF;
      IF INANOMALIA>0 THEN
        INSERT INTO CALC_ANOM(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,FLAG_ANOM)
        VALUES(CODNAZ,FOG,PART,SUBA,INANOMALIA);
        ANOMTOT:=ANOMTOT+1;
      END IF;
  END LOOP;
  CLOSE C1;

  DELETE FROM SITIFGAN WHERE (TIPO_ANOM>=21 AND TIPO_ANOM<=30) AND COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
  DELETE FROM UISITIRPAN WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
  DELETE FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
--  COMMIT;

  IF ANOMTOT > 0 THEN
    OPEN C2 FOR SELECT /*+ INDEX (SITICENT SITICENT_PK) */ Count(*) FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATACTR AND DATA_FINE_VAL >= DATACTR;
    FETCH C2 INTO NUMCENT;
    IF C2%NOTFOUND THEN NUMCENT:=0; END IF;
    CLOSE C2;

    INSERT INTO UISITIRPAN_CUAA_TAB(CUAA,COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,FLAG_ANOM)
    (
        SELECT A.CUAA,A.COD_NAZIONALE,A.FOGLIO,B.PARTICELLA,B.SUB,B.FLAG_ANOM FROM SITICOND_IMM A,CALC_ANOM B
        WHERE
        A.COD_NAZIONALE=CODNAZ AND
        A.FOGLIO=FOG AND
        A.DATA_INIZIO <= DATACTR AND A.DATA_FINE >= DATACTR AND
        B.COD_NAZIONALE=A.COD_NAZIONALE AND
        B.FOGLIO=A.FOGLIO AND
        B.PARTICELLA=A.PARTICELLA AND
        B.SUB = A.SUB
        GROUP BY A.CUAA,A.COD_NAZIONALE,A.FOGLIO,B.PARTICELLA,B.SUB,B.FLAG_ANOM
    );

    IF ANOM21>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,1)=1 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE21;
      IF C3%NOTFOUND THEN NUMAZIE21:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(21,FOG,ANOM21,NUMAZIE21,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM22>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,2)=2 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE22;
      IF C3%NOTFOUND THEN NUMAZIE22:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(22,FOG,ANOM22,NUMAZIE22,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM23>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,4)=4 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE23;
      IF C3%NOTFOUND THEN NUMAZIE23:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(23,FOG,ANOM23,NUMAZIE23,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM24>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,8)=8 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE24;
      IF C3%NOTFOUND THEN NUMAZIE24:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(24,FOG,ANOM24,NUMAZIE24,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM25>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,16)=16 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE25;
      IF C3%NOTFOUND THEN NUMAZIE25:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(25,FOG,ANOM25,NUMAZIE25,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM26>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,32)=32 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE26;
      IF C3%NOTFOUND THEN NUMAZIE26:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(26,FOG,ANOM26,NUMAZIE26,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM27>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,64)=64 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE27;
      IF C3%NOTFOUND THEN NUMAZIE27:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(27,FOG,ANOM27,NUMAZIE27,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM28>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,128)=128 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE28;
      IF C3%NOTFOUND THEN NUMAZIE28:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(28,FOG,ANOM28,NUMAZIE28,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM29>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,256)=256 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE29;
      IF C3%NOTFOUND THEN NUMAZIE29:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(29,FOG,ANOM29,NUMAZIE29,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM30>0 THEN
      OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND BITAND(FLAG_ANOM,512)=512 GROUP BY CUAA);
      FETCH C3 INTO NUMAZIE30;
      IF C3%NOTFOUND THEN NUMAZIE30:=0; END IF;
      CLOSE C3;
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(30,FOG,ANOM30,NUMAZIE30,SESSIO,NUMCENT,1,CODNAZ);
    END IF;

    OPEN C3 FOR SELECT Count(*) FROM (SELECT 1 FROM UISITIRPAN_CUAA_TAB WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG GROUP BY CUAA);
    FETCH C3 INTO NUMAZIE;
    IF C3%NOTFOUND THEN NUMAZIE:=0; END IF;
    CLOSE C3;

    INSERT INTO UISITIRPAN (foglio,num_part_tot,num_azie_tot,num_part_an21,num_azie_an21,num_part_an22,num_azie_an22,num_part_an23,num_azie_an23,num_part_an24,num_azie_an24,num_part_an25,num_azie_an25,num_part_an26,num_azie_an26,num_part_an27,num_azie_an27,num_part_an28,num_azie_an28,num_part_an29,num_azie_an29,num_part_an30,num_azie_an30,num_cent,flag_pres_mappa,cod_nazionale,data_aggi)
    VALUES(FOG,ANOMTOT,NUMAZIE,ANOM21,NUMAZIE21,ANOM22,NUMAZIE22,ANOM23,NUMAZIE23,ANOM24,NUMAZIE24,ANOM25,NUMAZIE25,ANOM26,NUMAZIE26,ANOM27,NUMAZIE27,ANOM28,NUMAZIE28,ANOM29,NUMAZIE29,ANOM30,NUMAZIE30,NUMCENT,NVL((SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND ROWNUM=1),0),CODNAZ,SESSIO);
  END IF;
  COMMIT;
END UIANOMALIEFOG_TER;

PROCEDURE GISANOMALIEFOG_TER(CODNAZ IN VARCHAR2, FOG IN NUMBER, GRUPPO IN NUMBER)
