  OPEN C1 FOR SELECT PARTICELLA,SUB FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATACTR AND DATA_FINE_VAL >= DATACTR GROUP BY PARTICELLA,SUB;

  LOOP
      FETCH C1 INTO PART,SUBA;
     EXIT WHEN (C1%NOTFOUND);

