        END IF;
        IF GISVSCENS = 4 THEN
          ANOM45:=ANOM45+1;
          INANOMALIA:=INANOMALIA + 16;
        END IF;
        IF GISVSCENS = 3 THEN
          ANOM46:=ANOM46+1;
          INANOMALIA:=INANOMALIA + 32;
        END IF;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA47(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
