    IF ANOM42>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(42,FOG,ANOM42,NUMAZIE42,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM43>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(43,FOG,ANOM43,NUMAZIE43,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM44>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(44,FOG,ANOM44,NUMAZIE44,SESSIO,NUMCENT,1,CODNAZ);
