    IF ANOM45>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(45,FOG,ANOM45,NUMAZIE45,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM46>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(46,FOG,ANOM46,NUMAZIE46,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM47>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(47,FOG,ANOM47,NUMAZIE47,SESSIO,NUMCENT,1,CODNAZ);
    END IF;

    INSERT INTO GISSITIRPAN (foglio,num_part_tot,num_azie_tot,num_part_an41,num_azie_an41,num_part_an42,num_azie_an42,num_part_an43,num_azie_an43,num_part_an44,num_azie_an44,num_part_an45,num_azie_an45,num_part_an46,num_azie_an46,num_part_an47,num_azie_an47,num_cent,flag_pres_mappa,cod_nazionale,data_aggi)
