PROCEDURE CEANOMALIEFOG_TER(CODNAZ IN VARCHAR2, FOG IN NUMBER, GRUPPO IN NUMBER)
IS
  INANOMALIA NUMBER(9);
  ANOMTOT NUMBER(9):=0;
  ANOM61 NUMBER(9):=0;
  ANOM62 NUMBER(9):=0;
  ANOM63 NUMBER(9):=0;
  SESSIO DATE;

  PART VARCHAR2(5);
  SUBA VARCHAR2(3);

  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;
  C2 EMPTYCUR;
  C3 EMPTYCUR;

  DATACTR DATE;

  NUMCENT NUMBER(9):=0;
  NUMAZIE61 NUMBER(9):=0;
  NUMAZIE62 NUMBER(9):=0;
  NUMAZIE63 NUMBER(9):=0;
  NUMAZIE NUMBER(9):=0;

  GISVSCENS NUMBER(9):=0;
BEGIN
  SESSIO:=SYSDATE;
  DATACTR:=To_Date('99991231000000','YYYYMMDDHH24MISS');
  OPEN C1 FOR SELECT PARTICELLA,SUB FROM SITICATA WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO <= DATACTR AND DATA_FINE >= DATACTR GROUP BY PARTICELLA,SUB;

  LOOP
      FETCH C1 INTO PART,SUBA;
     EXIT WHEN (C1%NOTFOUND);

      INANOMALIA:=0;

      GISVSCENS:=CHECK_GIS_DATA.GISVSCENS(CODNAZ,FOG,PART,SUBA,DATACTR);

      IF GISVSCENS > 0 THEN
        IF GISVSCENS = 5 THEN
          ANOM61:=ANOM61+1;
          INANOMALIA:=INANOMALIA + 1;
        END IF;
        IF GISVSCENS = 2 THEN
          ANOM62:=ANOM62+1;
          INANOMALIA:=INANOMALIA + 2;
        END IF;
      END IF;

      IF CHECK_GIS_DATA.ANOMALIA63(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM63:=ANOM63+1;
        INANOMALIA:=INANOMALIA + 4;
      END IF;
      IF INANOMALIA>0 THEN
        INSERT INTO CALC_ANOM(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,FLAG_ANOM)
        VALUES(CODNAZ,FOG,PART,SUBA,INANOMALIA);
        ANOMTOT:=ANOMTOT+1;
      END IF;
  END LOOP;
  CLOSE C1;
--  COMMIT;

  DELETE FROM SITIFGAN WHERE (TIPO_ANOM>=61 AND TIPO_ANOM<=63) AND COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
  DELETE FROM CESITIRPAN WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;

  IF ANOMTOT > 0 THEN
    OPEN C2 FOR SELECT /*+ INDEX (SITICENT SITICENT_PK) */ Count(*) FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATACTR AND DATA_FINE_VAL >= DATACTR;
    FETCH C2 INTO NUMCENT;
    IF C2%NOTFOUND THEN NUMCENT:=0; END IF;
    CLOSE C2;
    IF ANOM61>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(61,FOG,ANOM61,NUMAZIE61,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM62>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(62,FOG,ANOM62,NUMAZIE62,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM63>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(63,FOG,ANOM63,NUMAZIE63,SESSIO,NUMCENT,1,CODNAZ);
    END IF;

    INSERT INTO CESITIRPAN (foglio,num_part_tot,num_azie_tot,num_part_an61,num_azie_an61,num_part_an62,num_azie_an62,num_part_an63,num_azie_an63,num_cent,flag_pres_mappa,cod_nazionale,data_aggi)
    VALUES(FOG,ANOMTOT,NUMAZIE,ANOM61,NUMAZIE61,ANOM62,NUMAZIE62,ANOM63,NUMAZIE63,NUMCENT,NVL((SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND ROWNUM=1),0),CODNAZ,SESSIO);
  END IF;
  COMMIT;
END CEANOMALIEFOG_TER;

PROCEDURE CuANOMALIEFOG_TER(CODNAZ IN VARCHAR2, FOG IN NUMBER, GRUPPO IN NUMBER)
IS
  INANOMALIA NUMBER(9);
  ANOMTOT NUMBER(9):=0;
  ANOM81 NUMBER(9):=0;
  ANOM82 NUMBER(9):=0;
  ANOM83 NUMBER(9):=0;
  ANOM84 NUMBER(9):=0;
  SESSIO DATE;

  PART VARCHAR2(5);
  SUBA VARCHAR2(3);

  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;
  C2 EMPTYCUR;
  C3 EMPTYCUR;

  DATACTR DATE;

  NUMCENT NUMBER(9):=0;

  GISVSCENS NUMBER(9):=0;
BEGIN
  SESSIO:=SYSDATE;
  DATACTR:=To_Date('99991231000000','YYYYMMDDHH24MISS');
  OPEN C1 FOR SELECT PARTICELLA,SUB FROM SITIUIU WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATACTR AND DATA_FINE_VAL >= DATACTR GROUP BY PARTICELLA,SUB;
  LOOP
      FETCH C1 INTO PART,SUBA;
     EXIT WHEN (C1%NOTFOUND);

      INANOMALIA:=0;
      GISVSCENS:=CHECK_GIS_DATA.GISVSCENS(CODNAZ,FOG,PART,SUBA,DATACTR);

      IF GISVSCENS > 0 THEN
        IF GISVSCENS = 5 THEN
          ANOM81:=ANOM81+1;
          INANOMALIA:=INANOMALIA + 1;
        END IF;
        IF GISVSCENS = 2 THEN
          ANOM82:=ANOM82+1;
          INANOMALIA:=INANOMALIA + 2;
        END IF;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA83(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM83:=ANOM83+1;
        INANOMALIA:=INANOMALIA + 4;
      END IF;
      IF CHECK_GIS_DATA.ANOMALIA84(CODNAZ,FOG,PART,SUBA,DATACTR) = 1 THEN
        ANOM84:=ANOM84+1;
        INANOMALIA:=INANOMALIA + 8;
      END IF;
      IF INANOMALIA>0 THEN
--        INSERT INTO CALC_ANOM(COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,FLAG_ANOM)
--        VALUES(CODNAZ,FOG,PART,SUBA,INANOMALIA);
        ANOMTOT:=ANOMTOT+1;
      END IF;
  END LOOP;
  CLOSE C1;
  --COMMIT;

  DELETE FROM SITIFGAN WHERE (TIPO_ANOM>=81 AND TIPO_ANOM<=84) AND COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;
  DELETE FROM CUSITIRPAN WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG;

  IF ANOMTOT > 0 THEN
    OPEN C2 FOR SELECT /*+ INDEX (SITICENT SITICENT_PK) */ Count(*) FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND DATA_INIZIO_VAL <= DATACTR AND DATA_FINE_VAL >= DATACTR;
    FETCH C2 INTO NUMCENT;
    IF C2%NOTFOUND THEN NUMCENT:=0; END IF;
    CLOSE C2;
    IF ANOM81>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(81,FOG,ANOM81,0,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM82>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(82,FOG,ANOM82,0,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM83>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(83,FOG,ANOM83,0,SESSIO,NUMCENT,1,CODNAZ);
    END IF;
    IF ANOM84>0 THEN
      INSERT INTO SITIFGAN (tipo_anom,foglio,num_part,num_azie,data_aggi,num_cent,flag_pres_mappa,cod_nazionale)
      VALUES(84,FOG,ANOM84,0,SESSIO,NUMCENT,1,CODNAZ);
    END IF;

    INSERT INTO CUSITIRPAN (foglio,num_part_tot,num_azie_tot,num_part_an81,num_azie_an81,num_part_an82,num_azie_an82,num_part_an83,num_azie_an83,num_part_an84,num_azie_an84,num_cent,flag_pres_mappa,cod_nazionale,data_aggi)
    VALUES(FOG,ANOMTOT,0,ANOM81,0,ANOM82,0,ANOM83,0,ANOM84,0,NUMCENT,NVL((SELECT 1 FROM SITIFGLC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND ROWNUM=1),0),CODNAZ,SESSIO);
  END IF;

--  DELETE FROM CALC_ANOM WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG  AND To_Char(SESSIONE,'YYYYMMDDHH24MISS') = To_Char(SESSIO,'YYYYMMDDHH24MISS') AND GRUPPO_ANOM=GRUPPO;
  COMMIT;
END CuANOMALIEFOG_TER;

PROCEDURE RPTREFRESHANOM(COMUNE IN VARCHAR2,GRUPPO IN NUMBER) IS

CN VARCHAR2(4);
FG NUMBER(4);
RET NUMBER(1);

F1 NUMBER(1);
F2 NUMBER(1);
F3 NUMBER(1);
F4 NUMBER(1);
F5 NUMBER(1);

SQLSTR VARCHAR2(1024);

TYPE EMPTYCUR IS REF CURSOR;
C EMPTYCUR;

BEGIN
  SQLSTR:='SELECT A.COD_NAZIONALE, A.FOGLIO,A.GR1,A.GR2,A.GR3,A.GR4,A.GR5 FROM SITIANOM_REFR A ';

  IF COMUNE IS NOT NULL THEN
    IF Length(COMUNE) = 3 THEN
      SQLSTR:=SQLSTR || ',SITICOMU B WHERE A.INUSE=0 AND A.COD_NAZIONALE=B.COD_NAZIONALE AND B.ISTATP=:1';
    ELSE
      SQLSTR:=SQLSTR || ' WHERE A.INUSE=0 AND A.COD_NAZIONALE=:1';
    END IF;
  ELSE
    SQLSTR:=SQLSTR || ' WHERE A.INUSE=0';
  END IF;
  IF GRUPPO=1 THEN  SQLSTR:=SQLSTR || ' AND A.GR1=0'; END IF;
  IF GRUPPO=2 THEN  SQLSTR:=SQLSTR || ' AND A.GR2=0'; END IF;
  IF GRUPPO=3 THEN  SQLSTR:=SQLSTR || ' AND A.GR3=0'; END IF;
  IF GRUPPO=4 THEN  SQLSTR:=SQLSTR || ' AND A.GR4=0'; END IF;
  IF GRUPPO=5 THEN  SQLSTR:=SQLSTR || ' AND A.GR5=0'; END IF;
  IF gruppo=0 OR GRUPPO IS NULL THEN SQLSTR:=SQLSTR || ' AND (A.GR1=0 OR A.GR2=0 OR A.GR3=0 OR A.GR4=0 OR A.GR5=0)'; END IF;

  IF COMUNE IS NOT NULL THEN
    OPEN C FOR SQLSTR USING COMUNE;
  ELSE
    OPEN C FOR SQLSTR;
  END IF;

  LOOP
    FETCH C INTO CN, FG,F1,F2,F3,F4,F5;
  EXIT WHEN C%NOTFOUND;
    UPDATE SITIANOM_REFR SET INUSE=1 WHERE COD_NAZIONALE=CN AND FOGLIO=FG;
    IF GRUPPO IS NULL OR GRUPPO=0 THEN
      ANOMALIEFOG_TER(CN,FG,1);
      UIANOMALIEFOG_TER(CN,FG,2);
      GISANOMALIEFOG_TER(CN,FG,3);
      CEANOMALIEFOG_TER(CN,FG,4);
      CUANOMALIEFOG_TER(CN,FG,5);
      DELETE FROM SITIANOM_REFR WHERE COD_NAZIONALE=CN AND FOGLIO=FG AND INUSE=1;
    ELSE
      IF GRUPPO=1 AND F1=0 THEN ANOMALIEFOG_TER(CN,FG,1); F1:=1; END IF;
      IF GRUPPO=2 AND F2=0 THEN UIANOMALIEFOG_TER(CN,FG,2); F2:=1; END IF;
      IF GRUPPO=3 AND F3=0 THEN GISANOMALIEFOG_TER(CN,FG,3); F3:=1; END IF;
      IF GRUPPO=4 AND F4=0 THEN CEANOMALIEFOG_TER(CN,FG,4); F4:=1; END IF;
      IF GRUPPO=5 AND F5=0 THEN CUANOMALIEFOG_TER(CN,FG,5); F5:=1; END IF;
      IF F1 + F2 + F3 + F4 + F5 = 5 THEN
        DELETE FROM SITIANOM_REFR WHERE COD_NAZIONALE=CN AND FOGLIO=FG AND INUSE=1;
      ELSE
        UPDATE SITIANOM_REFR SET GR1=F1,GR2=F2,GR3=F3,GR4=F4,GR5=F5,INUSE=0 WHERE COD_NAZIONALE=CN AND FOGLIO=FG AND INUSE=1;
      END IF;
    END IF;
  END LOOP;
  CLOSE C;
  COMMIT;

EXCEPTION WHEN OTHERS THEN
  UPDATE SITIANOM_REFR SET INUSE=0 WHERE COD_NAZIONALE=CN AND FOGLIO=FG AND INUSE=1;
  COMMIT;
END RPTREFRESHANOM;

PROCEDURE AGG_ANOM_REFR(CODNAZ IN VARCHAR2, FOG IN NUMBER)
IS
  CURSOR C0 IS SELECT 1 + gr1 + gr2 + gr3 + gr4 + gr5 FROM SITIANOM_REFR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND INUSE=0 AND ROWNUM=1;
  SALTA NUMBER(5);
BEGIN
  OPEN C0;
  FETCH C0 INTO SALTA;
  IF C0%NOTFOUND THEN SALTA:=0; END IF;
  CLOSE C0;

  IF SALTA=0 THEN
    INSERT INTO SITIANOM_REFR(COD_NAZIONALE,FOGLIO,INUSE) VALUES (CODNAZ,FOG,0);
  ELSE
    IF SALTA > 0 THEN -- VUOL DIRE CHE HO GIà RICALCOLATO QUALCOSA
      UPDATE SITIANOM_REFR SET GR1=0,GR2=0,GR3=0,GR4=0,GR5=0 WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND INUSE=0 AND ROWNUM=1;
    END IF;
  END IF;
END AGG_ANOM_REFR;

PROCEDURE DATI_STRADA(PKSTRA IN NUMBER,NUMEROSTRA OUT VARCHAR2,DESCRIZIONE OUT VARCHAR2,LUNGHEZZA OUT NUMBER,SUPE OUT NUMBER,HASGRAPH OUT NUMBER,PREFI OUT VARCHAR, PREFI_ALT OUT VARCHAR2, DESCRIZIONE_ALT OUT VARCHAR2)
IS
  PERIM NUMBER(9) := 0;
  SUPSTRA NUMBER(9) := 0;
  DESCRIZ VARCHAR2(90) := '';
  PRF VARCHAR2(90) := '';
  NMRO VARCHAR2(9);
  CF VARCHAR2(4);
BEGIN
  LUNGHEZZA:=0;
  SUPE:=0;
  DESCRIZIONE:='N.D.';
  HASGRAPH:= 0;
  NUMEROSTRA:='';
  PRF:='';
  DESCRIZIONE_ALT:='';
  PREFI_ALT:='';

  SELECT
  NOME,NUMERO,COD_NAZIONALE,PREFISSO,PREFISSO_ALT,NOME_ALT
  INTO DESCRIZ,NMRO,CF,PRF,PREFI_ALT,DESCRIZIONE_ALT
  FROM SITIDSTR
  WHERE
  PKID_STRA=PKSTRA AND
  DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');

  DESCRIZIONE:=DESCRIZ;
  PREFI:=PRF;

  IF NMRO IS NOT NULL THEN
    NUMEROSTRA:=NMRO;
    SELECT
    SUM(B.AREA_PART),
    Sum(SDO_GEOM.SDO_LENGTH(B.SHAPE, 0.05))
    --SDO_GEOM.SDO_LENGTH(SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(B.SHAPE, 0.005)), 0.05)
    INTO SUPSTRA,PERIM
    FROM SITISTRA A, SITIPART B
    WHERE
    A.COD_NAZIONALE=B.COD_NAZIONALE AND
    A.FOGLIO=B.FOGLIO AND
    A.PARTICELLA=B.PARTICELLA AND
    A.SUB=B.SUB AND
    A.PKID_STRA=PKSTRA AND
    A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND
    B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');

    IF PERIM IS NOT NULL THEN LUNGHEZZA:=PERIM / 2; END IF;
    IF SUPSTRA IS NOT NULL THEN SUPE:=SUPSTRA; END IF;

    IF SUPE>0 OR LUNGHEZZA>0 THEN
      HASGRAPH:=1;
    ELSE
      SELECT
      Sum(SDO_GEOM.SDO_LENGTH(SHAPE, 0.05))
      --SDO_GEOM.SDO_LENGTH(SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SHAPE, 0.005)), 0.05)
      INTO PERIM
      FROM
      SITIDSTR_GRAF
      WHERE
      COD_NAZIONALE=CF AND
      NUMERO=NMRO
      GROUP BY COD_NAZIONALE,NUMERO;

      IF PERIM > 0 THEN HASGRAPH:=1;LUNGHEZZA:=PERIM; END IF;
    END IF;
  END IF;

EXCEPTION WHEN OTHERS THEN
  LUNGHEZZA:=PERIM / 2;
  SUPE:=SUPSTRA;

  IF SUPE>0 OR LUNGHEZZA>0 THEN    HASGRAPH:=1;  END IF;
END DATI_STRADA;

PROCEDURE DATI_FIUME(PKFIUM IN NUMBER,NUMEROFIUM OUT VARCHAR2,DESCRIZIONE OUT VARCHAR2,LUNGHEZZA OUT NUMBER,SUPE OUT NUMBER,HASGRAPH OUT NUMBER,PREFI OUT VARCHAR, PREFI_ALT OUT VARCHAR2, DESCRIZIONE_ALT OUT VARCHAR2)
IS
  PERIM NUMBER(9) := 0;
  SUPFIUM NUMBER(9) := 0;
  DESCRIZ VARCHAR2(90) := '';
  PRF VARCHAR2(90) := '';
  NMRO VARCHAR2(9);
  CF VARCHAR2(4);
BEGIN
  LUNGHEZZA:=0;
  SUPE:=0;
  DESCRIZIONE:='N.D.';
  HASGRAPH:= 0;
  NUMEROFIUM:='';
  PRF:='';

  SELECT
  NOME,NUMERO,COD_NAZIONALE,PREFISSO,PREFISSO_ALT,NOME_ALT
  INTO DESCRIZ,NMRO,CF,PRF,PREFI_ALT,DESCRIZIONE_ALT
  FROM SITIDFIU
  WHERE
  PKID_FIUM=PKFIUM AND
  DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');

  DESCRIZIONE:=DESCRIZ;
  PREFI:=PRF;

  IF NMRO IS NOT NULL THEN
    NUMEROFIUM:=NMRO;
    SELECT
    SUM(B.AREA_PART),
    Sum(SDO_GEOM.SDO_LENGTH(B.SHAPE, 0.05))
    --SDO_GEOM.SDO_LENGTH(SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(B.SHAPE, 0.005)), 0.05)
    INTO SUPFIUM,PERIM
    FROM SITIFIUM A, SITIPART B
    WHERE
    A.COD_NAZIONALE=B.COD_NAZIONALE AND
    A.FOGLIO=B.FOGLIO AND
    A.PARTICELLA=B.PARTICELLA AND
    A.SUB=B.SUB AND
    A.PKID_FIUM=PKFIUM AND
    A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND
    B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');

    IF PERIM IS NOT NULL THEN LUNGHEZZA:=PERIM / 2; END IF;
    IF SUPFIUM IS NOT NULL THEN SUPE:=SUPFIUM; END IF;

    IF SUPE>0 OR LUNGHEZZA>0 THEN
      HASGRAPH:=1;
    ELSE
      SELECT
      Sum(SDO_GEOM.SDO_LENGTH(SHAPE, 0.05))
      --SDO_GEOM.SDO_LENGTH(SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SHAPE, 0.005)), 0.05)
      INTO PERIM
      FROM
      SITIDFIU_GRAF
      WHERE
      COD_NAZIONALE=CF AND
      NUMERO=NMRO
      GROUP BY COD_NAZIONALE,NUMERO;

      IF PERIM > 0 THEN HASGRAPH:=1;LUNGHEZZA:=PERIM; END IF;
    END IF;
  END IF;

EXCEPTION WHEN OTHERS THEN
  LUNGHEZZA:=PERIM / 2;
  SUPE:=SUPFIUM;

  IF SUPE>0 OR LUNGHEZZA>0 THEN    HASGRAPH:=1;  END IF;
END DATI_FIUME;

END SITIUTILS;
/


DROP PACKAGE BODY SITI_H501.SITIUTILS_FRAC;

CREATE OR REPLACE PACKAGE BODY SITI_H501.SITIUTILS_FRAC AS

--THIS FUNCTION IS USED BY DECTOFRAC AND DECTOPROPERFACT

FUNCTION FRAC(X IN NUMBER) RETURN NUMBER
IS
BEGIN
    RETURN ABS(ABS(X) - TRUNC(ABS(X)));
END;


PROCEDURE DECTOFRAC(DECIMALNUM IN NUMBER, NUMERATOR OUT NUMBER, DENOM OUT NUMBER)
IS
BIGNUMBER NUMBER ;
SMALLNUMBER NUMBER ; --(1E-16)
INVERSE NUMBER ;
FRACTIONALPART NUMBER ;
WHOLEPART NUMBER ;
SWAPTEMP NUMBER ;

BEGIN

   BIGNUMBER:=50000;
   SMALLNUMBER := 0.00000000000000001;

   -- THE BIGNUMBER CONSTANT CAN BE ADJUSTED TO HANDLE LARGER FRACTIONAL PARTS

   INVERSE := 1 / DECIMALNUM;
   WHOLEPART := TRUNC(INVERSE);
   FRACTIONALPART := FRAC(INVERSE);

   IF 1 / (FRACTIONALPART + SMALLNUMBER) < BIGNUMBER THEN
        --NOTICE THAT DECTOFRAC IS CALLED RECURSIVELY.
        DECTOFRAC(FRACTIONALPART, NUMERATOR, DENOM);
        NUMERATOR := DENOM * WHOLEPART + NUMERATOR;

        SWAPTEMP := NUMERATOR;
        NUMERATOR := DENOM;
        DENOM := SWAPTEMP;
   ELSE --IF 1 / (FRACTIONALPART + SMALLNUMBER) > BIGNUMBER
        --RECURSION STOPS WHEN THE FINAL VALUE OF FRACTIONALPART IS 0 OR
        --CLOSE ENOUGH.  SMALLNUMBER IS ADDED TO PREVENT DIVISION BY 0.
        NUMERATOR := 1;
        DENOM := TRUNC(INVERSE);
   END IF;
END;



--THIS ADDITIONAL PROCEDURE HANDLES "IMPROPER" FRACTIONS AND RETURNS
--THEM IN MIXED FORM (A B/C) WHEN THE NUMERATOR IS LARGER THAN THE DENOMINATOR

/*SUB DECTOPROPERFRAC(NUMBER X, A AS LONG, B AS LONG, C AS LONG)
   IF X > 1 THEN A = ROUND(X)
   IF FRAC(X) <> 0 THEN
      DECTOFRAC(FRAC(X), B, C)
   END IF
END SUB*/

FUNCTION GET_DENOM  (PERCENTAGE NUMBER)   RETURN NUMBER
IS
NUM NUMBER;
DEN NUMBER;
BEGIN
DECTOFRAC(PERCENTAGE/100,NUM,DEN);
RETURN DEN;
END;

FUNCTION GET_NUMER (PERCENTAGE NUMBER)   RETURN NUMBER
IS
NUM NUMBER;
DEN NUMBER;
BEGIN
DECTOFRAC(PERCENTAGE/100,NUM,DEN);
RETURN NUM;
END;


END SITIUTILS_FRAC;
/


DROP PACKAGE BODY SITI_H501.TITOLI_PCK;

CREATE OR REPLACE PACKAGE BODY SITI_H501.titoli_pck AS
-----------------------------------------------------------------------------------------------------
  FUNCTION is_titolo_proprieta (tipo_titolo VARCHAR2)
    RETURN NUMBER AS
  BEGIN
    IF tipo_titolo = '1' OR tipo_titolo = '3' THEN
      RETURN 1;
    ELSE
      RETURN 0;
    END IF;
  END is_titolo_proprieta;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_superficie_uiu (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
    p_dt                                 DATE
  )
    RETURN NUMBER IS
    m_sup_cat                     NUMBER := 0;
    m_sup_modelli                 NUMBER := 0;
    m_sup_vani                    NUMBER := 0;
    m_num_vani                    NUMBER := 0;
    m_sup_uiu                     NUMBER := 0;
  BEGIN
    BEGIN
      SELECT NVL (u.sup_cat, 0) AS sup_cat,
             NVL (u.supe_modelli, 0) AS supe_modelli,
             NVL (v1.supe_vani, 0) AS supe_vani,
             NVL (v1.num_vani, 0) AS num_vani
        INTO m_sup_cat,
             m_sup_modelli,
             m_sup_vani,
             m_num_vani
        FROM sitiuiu u
             LEFT JOIN
             (SELECT   v.cod_nazionale,
                       v.foglio,
                       v.particella,
                       v.sub,
                       v.unimm,
                       SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0)) AS supe_vani,
                       COUNT (*) AS num_vani
                  FROM sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
                 WHERE v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio AND v.particella = e.particella
                       AND v.sub = e.sub AND v.unimm = e.unimm AND e.data_inizio_val <= p_dt AND e.data_fine_val >= p_dt
                       AND v.data_inizio_val <= p_dt AND v.data_fine_val >= p_dt AND e.fk_tipologia = c.fk_tipologia
                       AND v.ambiente = c.internal_code(+)
              GROUP BY v.cod_nazionale, v.foglio, v.particella, v.sub, v.unimm) v1
             ON u.cod_nazionale = v1.cod_nazionale AND u.foglio = v1.foglio AND u.particella = v1.particella
                AND u.sub = v1.sub AND u.unimm = v1.unimm
       WHERE u.cod_nazionale = p_codnaz AND u.foglio = p_foglio AND u.particella = p_particella AND u.sub = p_sub
             AND u.unimm = p_unimm AND u.data_inizio_val <= p_dt AND u.data_fine_val >= p_dt;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_sup_cat := -1;
        m_sup_modelli := 0;
        m_sup_vani := 0;
        m_num_vani := 0;
    END;

    IF m_sup_cat = -1 THEN
      m_sup_uiu := -1;
    ELSE
      IF m_num_vani > 0 THEN
        IF m_sup_vani > 0 THEN
          m_sup_uiu := m_sup_vani;
        ELSE
          IF m_sup_modelli > 0 THEN
            m_sup_uiu := m_sup_modelli;
          ELSE
            m_sup_uiu := m_sup_cat;
          END IF;
        END IF;
      ELSE
        IF m_sup_modelli > 0 THEN
          m_sup_uiu := m_sup_modelli;
        ELSE
          m_sup_uiu := m_sup_cat;
        END IF;
      END IF;
    END IF;

    RETURN m_sup_uiu;
  END get_superficie_uiu;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_superficie_part (p_codnaz VARCHAR2, p_foglio NUMBER, p_particella VARCHAR2, p_sub VARCHAR2, p_dt DATE)
    RETURN NUMBER IS
    m_sup_part                    NUMBER := 0;
  BEGIN
    BEGIN
      SELECT NVL (area_part, 0) AS area
        INTO m_sup_part
        FROM sititrkc a
       WHERE a.cod_nazionale = p_codnaz AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub
             AND a.data_aggi <= p_dt AND a.data_fine >= p_dt;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_sup_part := -1;
    END;

    RETURN m_sup_part;
  END get_superficie_part;

-----------------------------------------------------------------------------------------------------
  FUNCTION perc_prop_part (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    cnt                           NUMBER;
  BEGIN
    SELECT NVL (SUM (perc_poss), 0)
      INTO cnt
      FROM cons_cons_tab
     WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND data_inizio <= dt AND data_fine >= dt;

    RETURN cnt;
  END perc_prop_part;

-----------------------------------------------------------------------------------------------------
  FUNCTION perc_altro_tit_part (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    cnt                           NUMBER;
  BEGIN
    -- Controllo tipo_titolo = 9 (arriva SOLO da caricamento catastale)
    SELECT NVL (SUM (perc_poss), 0)
      INTO cnt
      FROM cons_ufre_tab
     WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND tipo_titolo = '9'
           AND data_inizio <= dt AND data_fine >= dt;

    IF (cnt = 0) THEN
      SELECT NVL (SUM (perc_poss), 0)
        INTO cnt
        FROM (SELECT DISTINCT atto_ini,
                              perc_poss
                         FROM cons_ufre_tab
                        WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND data_inizio <= dt
                              AND data_fine >= dt
                     GROUP BY atto_ini, perc_poss);

      IF (cnt > 100) THEN
        cnt := 100;
      END IF;
    END IF;

    RETURN cnt;
  END perc_altro_tit_part;

-----------------------------------------------------------------------------------------------------
  FUNCTION perc_prop_uiu (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    cnt                           NUMBER;
  BEGIN
    SELECT NVL (SUM (perc_poss), 0)
      INTO cnt
      FROM cons_csui_tab
     WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND unimm = un AND data_inizio <= dt
           AND data_fine >= dt;

    RETURN cnt;
  END perc_prop_uiu;

-----------------------------------------------------------------------------------------------------
  FUNCTION perc_altro_tit_uiu (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER, dt DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    cnt_y                         NUMBER;
    cnt_n                         NUMBER;
    v                             NUMBER;
  BEGIN
    -- Controllo tipo_titolo=9 (viene solo da catasto)
    SELECT NVL (SUM (perc_poss), 0)
      INTO cnt_y
      FROM cons_urui_tab
     WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND unimm = un AND tipo_titolo = '9'
           AND data_inizio <= dt AND data_fine >= dt;

    IF (cnt_y = 0) THEN
      SELECT NVL (SUM (perc_poss), 0)
        INTO cnt_y
        FROM (SELECT DISTINCT atto_ini,
                              perc_poss
                         FROM cons_urui_tab
                        WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND unimm = un
                              AND fl_totale = 'Y' AND data_inizio <= dt AND data_fine >= dt
                     GROUP BY atto_ini, perc_poss);

      IF (cnt_y >= 100) THEN
        -- E' affittato tutto...
        cnt_y := 100;
        cnt_n := 0;
      ELSIF (cnt_y > 0) THEN
        cnt_y := 50;
      END IF;

      IF (cnt_y < 100) THEN
        SELECT COUNT (*)
          INTO v
          FROM sitiedi_vani
         WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND unimm = un
               AND data_inizio_val <= dt AND data_fine_val >= dt;

        /*
            select count(*) into cnt
              from cons_urui_vani
             where cod_nazionale = cn
               and foglio = fg
               and particella = pt
               and sub = sb
               and unimm = un
               and data_inizio_val <= dt
               and data_fine_val >= dt
               and id_atto in (select distinct atto_ini
                                 from cons_urui_tab
                                where cod_nazionale = cn
                                  and foglio = fg
                                  and particella = pt
                                  and sub = sb
                                  and unimm = un
                                  and fl_totale != 'Y'
                                  and data_inizio <= dt
                                  and data_fine >= dt);  */
        SELECT COUNT (*)
          INTO cnt_n
          FROM (SELECT DISTINCT vano
                           FROM cons_urui_vani
                          WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND unimm = un
                                AND data_inizio_val <= dt AND data_fine_val >= dt
                                AND id_atto IN (
                                     SELECT DISTINCT atto_ini
                                                FROM cons_urui_tab
                                               WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb
                                                     AND unimm = un AND fl_totale != 'Y' AND data_inizio <= dt
                                                     AND data_fine >= dt)
                       GROUP BY vano);

        IF (cnt_n != 0) THEN
          -- 06-07-2010 - TOLGO IL CONTROLLO SE IL FLAG_TOTALE = 'N' MA SONO STATI AFFITTATI TUTTI I VANI
              --IF (v - cnt_n = 0) THEN
              --  cnt_n := 100;                                                                -- Tutti i vani sono affittati
              --ELSE
              --  cnt_n := 50;                                                                       -- E' affittato in parte
              --END IF;
          cnt_n := 50;
        -- else
        -- Non c'ï¿½ nulla affittato
        END IF;
      END IF;
    END IF;

    RETURN GREATEST (cnt_y, cnt_n);
  END perc_altro_tit_uiu;

-----------------------------------------------------------------------------------------------------
  FUNCTION is_totale_altro_tit_uiu (cn VARCHAR2, fg NUMBER, pt VARCHAR2, sb VARCHAR2, un NUMBER, dt DATE DEFAULT SYSDATE)
    RETURN VARCHAR2 IS
    cnt                           NUMBER;
    v                             NUMBER;
    ret                           VARCHAR2 (1);
  BEGIN
    -- Controllo tipo_titolo=9 (viene solo da catasto)
    SELECT NVL (SUM (perc_poss), 0)
      INTO cnt
      FROM cons_urui_tab
     WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND unimm = un AND tipo_titolo = '9'
           AND data_inizio <= dt AND data_fine >= dt;

    ret := 'N';

    IF (cnt = 0) THEN
      SELECT COUNT (*)
        INTO cnt
        FROM cons_urui_tab
       WHERE cod_nazionale = cn AND foglio = fg AND particella = pt AND sub = sb AND unimm = un AND fl_totale = 'Y'
             AND data_inizio <= dt AND data_fine >= dt;

      IF (cnt > 0) THEN
        -- E' affittato tutto...
        ret := 'Y';
      END IF;
    END IF;

    RETURN ret;
  END is_totale_altro_tit_uiu;

-----------------------------------------------------------------------------------------------------
  FUNCTION sup_part_altro_tit (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    ret                           NUMBER := 0;
    m_pk_cuaa                     NUMBER := 0;
    m_date                        DATE;
  BEGIN
    BEGIN
      -- se p_date ï¿½ nullo prendo la data minuma di inizio titolarita
      IF p_date IS NULL THEN
        --  m_date := get_min_date_cond(p_atto_ini, p_codnaz, p_foglio, p_particella, p_sub);
        m_date := SYSDATE;
      ELSE
        m_date := p_date;
      END IF;

      -- se p_pk_cuaa ï¿½ nullo prendo una pk_cuaa a caso tra le ultime titolaritï¿½ che soddisfano gli altri parametri
      IF p_pk_cuaa IS NULL THEN
        m_pk_cuaa := get_pkcuaa_cond (p_atto_ini, m_date, p_codnaz, p_foglio, p_particella, p_sub);
      ELSE
        m_pk_cuaa := p_pk_cuaa;
      END IF;

      -- calcolo la superficie
      SELECT SUM (NVL (get_superficie_part (a.cod_nazionale, a.foglio, a.particella, a.sub, m_date), 0))
        INTO ret
        FROM siticond_all2 a
       WHERE atto_inizio = p_atto_ini AND pk_cuaa = m_pk_cuaa AND tipo_titolo NOT IN (1, 3, 9)
             AND a.cod_nazionale = p_codnaz AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub
             AND a.data_inizio <= m_date AND a.data_fine >= m_date;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        ret := NULL;
    END;

    ret := apply_multiple_rent (ret, p_atto_ini, p_codnaz, p_foglio, p_particella, p_sub, NULL, m_date);
    RETURN ret;
  END sup_part_altro_tit;

-----------------------------------------------------------------------------------------------------
  FUNCTION sup_uiu_altro_tit (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    ret                           NUMBER := 0;
    m_pk_cuaa                     NUMBER := 0;
    m_date                        DATE;
  BEGIN
    BEGIN
      -- se p_date ï¿½ nullo prendo la data minuma di inizio titolarita
      IF p_date IS NULL THEN
        --m_date := get_min_date_cond(p_atto_ini, p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
        m_date := SYSDATE;
      ELSE
        m_date := p_date;
      END IF;

      -- se p_pk_cuaa ï¿½ nullo prendo una pk_cuaa a caso tra le ultime titolaritï¿½ che soddisfano gli altri parametri
      IF p_pk_cuaa IS NULL THEN
        m_pk_cuaa := get_pkcuaa_cond (p_atto_ini, m_date, p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
      ELSE
        m_pk_cuaa := p_pk_cuaa;
      END IF;

/*
      SELECT NVL (SUM (sup_locata), 0)
        INTO ret
        FROM (SELECT SUM (NVL (DECODE (b.supe_modelli, NULL, b.sup_cat, b.supe_modelli), 0)) AS sup_locata
                FROM siticonduz_imm_all a, sitiuiu b
               WHERE a.atto_inizio = p_atto_ini AND a.pk_cuaa = m_pk_cuaa AND a.tipo_titolo NOT IN (1, 3, 9)
                     AND a.fl_totale = 'Y' AND a.cod_nazionale = p_codnaz AND a.foglio = p_foglio
                     AND a.particella = p_particella AND a.sub = p_sub AND a.unimm = p_unimm
                     AND a.cod_nazionale = b.cod_nazionale AND a.foglio = b.foglio AND a.particella = b.particella
                     AND a.sub = b.sub AND a.unimm = b.unimm AND a.data_inizio <= m_date AND a.data_fine >= m_date
                     AND b.data_inizio_val <= m_date AND b.data_fine_val >= m_date
              UNION
              SELECT SUM (NVL (supe_ambiente, 0)) AS sup_locata
                FROM siticonduz_imm_all a, cons_urui_vani b, sitiedi_vani c
               WHERE a.atto_inizio = p_atto_ini AND a.pk_cuaa = m_pk_cuaa AND a.tipo_titolo NOT IN (1, 3, 9)
                     AND a.fl_totale = 'N' AND a.cod_nazionale = p_codnaz AND a.foglio = p_foglio
                     AND a.particella = p_particella AND a.sub = p_sub AND a.unimm = p_unimm
                     AND a.cod_nazionale = b.cod_nazionale AND a.foglio = b.foglio AND a.particella = b.particella
                     AND a.sub = b.sub AND a.unimm = b.unimm AND b.cod_nazionale = c.cod_nazionale
                     AND b.foglio = c.foglio AND b.particella = c.particella AND b.sub = c.sub AND b.unimm = c.unimm
                     AND b.vano = c.vano AND b.id_atto = a.atto_inizio AND a.data_inizio <= m_date
                     AND a.data_fine >= m_date AND b.data_inizio_val <= m_date AND b.data_fine_val >= m_date
                     AND c.data_inizio_val <= m_date AND c.data_fine_val >= m_date);
*/
      SELECT DECODE (sup_locata, -1, NULL, sup_locata)
        INTO ret
        FROM (SELECT titoli_pck.get_superficie_uiu (a.cod_nazionale, a.foglio, a.particella, a.sub, a.unimm, m_date)
                                                                                                          AS sup_locata
                FROM siticonduz_imm_all2 a
               WHERE a.atto_inizio = p_atto_ini AND a.pk_cuaa = m_pk_cuaa AND a.fl_totale = 'Y'
                     AND a.tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz AND a.foglio = p_foglio
                     AND a.particella = p_particella AND a.sub = p_sub AND a.unimm = p_unimm AND a.data_inizio <= m_date
                     AND a.data_fine >= m_date
              UNION
              SELECT SUM (NVL (v1.supe_vani, 0)) AS supe_locata
                FROM sitiuiu u,
                     (SELECT DISTINCT cod_nazionale,
                                      foglio,
                                      particella,
                                      sub,
                                      unimm
                                 FROM siticonduz_imm_all2
                                WHERE fl_totale = 'N' AND tipo_titolo NOT IN (1, 3, 9) AND atto_inizio = p_atto_ini
                                      AND pk_cuaa = m_pk_cuaa AND data_inizio <= m_date AND data_fine >= m_date) scia,
                     (SELECT DISTINCT cod_nazionale,
                                      foglio,
                                      particella,
                                      sub,
                                      unimm,
                                      vano
                                 FROM cons_urui_vani
                                WHERE id_atto = p_atto_ini AND data_inizio_val <= m_date AND data_fine_val >= m_date) cuv,
                     (SELECT v.cod_nazionale,
                             v.foglio,
                             v.particella,
                             v.sub,
                             v.unimm,
                             v.vano,
                             NVL (supe_ambiente * c.coef_supe_modelli, 0) AS supe_vani
                        FROM sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
                       WHERE v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio AND v.particella = e.particella
                             AND v.sub = e.sub AND v.unimm = e.unimm AND e.data_inizio_val <= m_date
                             AND e.data_fine_val >= m_date AND v.data_inizio_val <= m_date AND v.data_fine_val >= m_date
                             AND e.fk_tipologia = c.fk_tipologia AND v.ambiente = c.internal_code(+)) v1
               WHERE u.cod_nazionale = p_codnaz AND u.foglio = p_foglio AND u.particella = p_particella
                     AND u.sub = p_sub AND u.unimm = p_unimm AND u.data_inizio_val <= m_date
                     AND u.data_fine_val >= m_date AND u.cod_nazionale = scia.cod_nazionale AND u.foglio = scia.foglio
                     AND u.particella = scia.particella AND u.sub = scia.sub AND u.unimm = scia.unimm
                     AND u.cod_nazionale = cuv.cod_nazionale AND u.foglio = cuv.foglio AND u.particella = cuv.particella
                     AND u.sub = cuv.sub AND u.unimm = cuv.unimm AND cuv.cod_nazionale = v1.cod_nazionale
                     AND cuv.foglio = v1.foglio AND cuv.particella = v1.particella AND cuv.sub = v1.sub
                     AND cuv.unimm = v1.unimm AND cuv.vano = v1.vano)
       WHERE ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        ret := NULL;
    END;

    ret := apply_multiple_rent (ret, p_atto_ini, p_codnaz, p_foglio, p_particella, p_sub, p_unimm, m_date);
    RETURN ret;
  END sup_uiu_altro_tit;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_perc_locata (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    sup_tot                       NUMBER := 0;
    sup_locata                    NUMBER := 0;
    ret                           NUMBER := 0;
    m_date                        DATE;
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    BEGIN
      -- se p_date ï¿½ nullo prendo la data minuma di inizio titolarita
      IF p_date IS NULL THEN
        --m_date := get_min_date_cond(p_atto_ini, p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
        m_date := SYSDATE;
      ELSE
        m_date := p_date;
      END IF;

      -- calcolo la superficie totale e locata dell'oggetto particella o uiu
      IF m_obj_type = 'P' THEN                                                                             -- particella
        sup_locata :=
                   NVL (sup_part_altro_tit (p_atto_ini, p_pk_cuaa, p_codnaz, p_foglio, p_particella, p_sub, m_date), 0);
        sup_tot := NVL (get_superficie_part (p_codnaz, p_foglio, p_particella, p_sub, m_date), 0);
      ELSE                                                                                                        -- UIU
        sup_locata :=
           NVL (sup_uiu_altro_tit (p_atto_ini, p_pk_cuaa, p_codnaz, p_foglio, p_particella, p_sub, p_unimm, m_date), 0);
        sup_tot := NVL (get_superficie_uiu (p_codnaz, p_foglio, p_particella, p_sub, p_unimm, m_date), 0);
      /*
            SELECT SUM (NVL (DECODE (b.supe_modelli, NULL, b.sup_cat, b.supe_modelli), 0)) AS area
              INTO sup_tot
              FROM siticonduz_imm_all a, sitiuiu b
             WHERE a.atto_inizio = p_atto_ini AND a.pk_cuaa = p_pk_cuaa AND a.tipo_titolo NOT IN (1, 3, 9)
                   AND a.cod_nazionale = p_codnaz AND a.foglio = p_foglio AND a.particella = p_particella
              AND a.sub = p_sub
                   AND a.unimm = p_unimm AND a.cod_nazionale = b.cod_nazionale AND a.foglio = b.foglio
                   AND a.particella = b.particella AND a.sub = b.sub AND a.unimm = b.unimm
                   AND b.data_inizio_val <= a.data_inizio AND b.data_fine_val >= a.data_inizio;
          */
      END IF;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        sup_tot := -1;
    END;

    IF sup_locata IS NULL THEN                                                              -- NESSUNA LOCAZIONE TROVATA
      ret := NULL;
    ELSIF sup_tot = -1 THEN
      ret := NULL;
    ELSIF sup_tot = 0 THEN              -- CI SONO LOCAZIONI MA NON CI SONO LE SUPERFICI-> FORZO AL VALORE DEL CONTRATTO
      ret := apply_multiple_rent (100, p_atto_ini, p_codnaz, p_foglio, p_particella, p_sub, p_unimm, m_date);
    ELSE
      ret := (sup_locata / sup_tot) * 100;
    END IF;

    RETURN ret;
  END get_perc_locata;

-----------------------------------------------------------------------------------------------------
  FUNCTION apply_multiple_rent (
    p_sup                                NUMBER,
    p_atto                               NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    m_date                        DATE;
    m_ret                         NUMBER;
    m_multiple_rent               VARCHAR2 (2) := 'NO';
    m_contract_perc               NUMBER := 1;
  BEGIN
     -- 2009/10/01 Contratti multipli su particelle e uiu
    -- moltiplico la superficie locata per il coefficiente del contratto di locazione che
    -- ï¿½ nel campo perc_cond di tutte le titolaritï¿½
    BEGIN
      SELECT UPPER (NVL (valore, 'NO'))
        INTO m_multiple_rent
        FROM gisparams
       WHERE variabile = 'MULTIPLE_RENT';
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_multiple_rent := 'NO';
    END;

    -- se p_date ï¿½ nullo prendo la data minuma di inizio titolarita
    IF p_date IS NULL THEN
      m_date := get_min_date_cond (p_atto, p_codnaz, p_foglio, p_particella, p_sub, p_unimm);

      IF m_date IS NULL THEN
        m_date := get_min_date_subcond (p_atto, p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
      END IF;

      IF m_date IS NULL THEN
        m_date := SYSDATE;
      END IF;
    ELSE
      m_date := p_date;
    END IF;

    IF m_multiple_rent = 'SI' THEN
      IF p_unimm IS NULL THEN
        SELECT perc_poss / 100
          INTO m_contract_perc
          FROM (SELECT perc_poss
                  FROM siticond_all2
                 WHERE atto_inizio = p_atto AND cod_nazionale = p_codnaz AND foglio = p_foglio
                       AND particella = p_particella AND sub = p_sub AND data_inizio <= m_date AND data_fine >= m_date
                UNION
                SELECT perc_poss
                  FROM cons_subloc_tab
                 WHERE atto_inizio = p_atto AND data_inizio <= m_date AND data_fine >= m_date
                       AND fkid_obj = titoli_pck.get_obj_id (p_codnaz, p_foglio, p_particella, p_sub) AND obj_type = 'P')
         WHERE ROWNUM = 1;
      ELSE
        SELECT perc_poss / 100
          INTO m_contract_perc
          FROM (SELECT perc_poss
                  FROM siticonduz_imm_all2
                 WHERE atto_inizio = p_atto AND cod_nazionale = p_codnaz AND foglio = p_foglio
                       AND particella = p_particella AND sub = p_sub AND unimm = p_unimm AND data_inizio <= m_date
                       AND data_fine >= m_date
                UNION
                SELECT perc_poss
                  FROM cons_subloc_tab
                 WHERE atto_inizio = p_atto AND data_inizio <= m_date AND data_fine >= m_date
                       AND fkid_obj = titoli_pck.get_obj_id (p_codnaz, p_foglio, p_particella, p_sub, p_unimm)
                       AND obj_type = 'U')
         WHERE ROWNUM = 1;
      END IF;
    END IF;

    IF p_sup IS NULL THEN                                                                   -- NESSUNA LOCAZIONE TROVATA
      m_ret := NULL;
    ELSE
      m_ret := p_sup * m_contract_perc;
    END IF;

    RETURN m_ret;
  END apply_multiple_rent;

-----------------------------------------------------------------------------------------------------
  FUNCTION apply_multiple_rent_subloc (
    p_sup                                NUMBER,
    p_atto                               NUMBER,
    p_id_obj                             NUMBER,
    p_obj_type                           VARCHAR2,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    m_date                        DATE;
    m_ret                         NUMBER;
    m_multiple_rent               VARCHAR2 (2) := 'NO';
    m_contract_perc               NUMBER := 1;
  BEGIN
      -- 2009/10/01 Contratti multipli su particelle e uiu
    -- moltiplico la superficie locata per il coefficiente del contratto di locazione che
    -- ï¿½ nel campo perc_cond di tutte le titolaritï¿½
    BEGIN
      SELECT UPPER (NVL (valore, 'NO'))
        INTO m_multiple_rent
        FROM gisparams
       WHERE variabile = 'MULTIPLE_RENT';
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_multiple_rent := 'NO';
    END;

    -- se p_date ï¿½ nullo prendo la data minuma di inizio titolarita
    IF p_date IS NULL THEN
      m_date := get_min_date_subcond_byid (p_atto, p_obj_type, p_id_obj);

      IF m_date IS NULL THEN
        m_date := SYSDATE;
      END IF;
    ELSE
      m_date := p_date;
    END IF;

    IF m_multiple_rent = 'SI' THEN
      BEGIN
        SELECT perc_poss / 100
          INTO m_contract_perc
          FROM (SELECT perc_poss
                  FROM cons_subloc_tab
                 WHERE atto_inizio = p_atto AND data_inizio <= m_date AND data_fine >= m_date AND fkid_obj = p_id_obj
                       AND obj_type = p_obj_type)
         WHERE ROWNUM = 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          m_contract_perc := 1;

          -- potrebbe essere il caso nel quale ho subaffittato dei vani ma
          -- sto cercando la percentuale di conduzione sulla uiu
          -- faccio un tentativo di scalare sui vani
          SELECT cst.perc_poss / 100
            INTO m_contract_perc
            FROM cons_subloc_tab cst,
                 (SELECT DISTINCT id_cata_vano
                             FROM cata_vani CV,
                                  (SELECT cod_nazionale,
                                          foglio,
                                          particella,
                                          sub,
                                          unimm
                                     FROM cata_uiu
                                    WHERE id_cata_uiu = p_id_obj AND p_obj_type = 'U') cu
                            WHERE CV.cod_nazionale = cu.cod_nazionale AND CV.foglio = cu.foglio
                                  AND CV.particella = cu.particella AND CV.sub = cu.sub AND CV.unimm = cu.unimm) vani
           WHERE cst.atto_inizio = p_atto AND cst.fkid_obj = vani.id_cata_vano AND cst.obj_type = 'V'
                 AND data_inizio <= m_date AND data_fine >= m_date AND ROWNUM = 1;
      END;
    END IF;

    IF p_sup IS NULL THEN                                                                   -- NESSUNA LOCAZIONE TROVATA
      m_ret := NULL;
    ELSE
      m_ret := p_sup * m_contract_perc;
    END IF;

    RETURN m_ret;
  END apply_multiple_rent_subloc;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_sup_obj (p_obj_id NUMBER, p_obj_type VARCHAR2, p_date DATE DEFAULT SYSDATE)
    RETURN NUMBER IS
    m_suptot                      NUMBER := 0;
    m_exist                       NUMBER := -1;
  BEGIN
    BEGIN
      IF p_obj_type = 'P' THEN
        SELECT SUM (get_superficie_part (cod_nazionale, foglio, particella, sub, p_date)),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM sititrkc
         WHERE data_aggi <= p_date AND data_fine >= p_date AND id_particella = p_obj_id;
      ELSIF p_obj_type = 'U' THEN
        SELECT SUM (get_superficie_uiu (cod_nazionale, foglio, particella, sub, unimm, p_date)),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM (SELECT DISTINCT cod_nazionale,
                                foglio,
                                particella,
                                sub,
                                unimm
                           FROM sitiuiu
                          WHERE id_cata_uiu = p_obj_id);
      ELSIF p_obj_type = 'V' THEN
        SELECT SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0)),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM sitiedi_vani v, sitiedi_uiu_ext e, sitiedi_supe_codes c
         WHERE v.id_cata_vano = p_obj_id AND v.cod_nazionale = e.cod_nazionale AND v.foglio = e.foglio
               AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm AND e.data_inizio_val <= p_date
               AND e.data_fine_val >= p_date AND v.data_inizio_val <= p_date AND v.data_fine_val >= p_date
               AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;
      END IF;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_exist := -1;
        m_suptot := 0;
    END;

    IF m_exist = 0 THEN
      m_exist := -1;
    END IF;

    IF m_exist = -1 THEN
      m_suptot := -1;
    END IF;

    RETURN m_suptot;
  END get_sup_obj;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_sup_sublocata (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    m_suptot                      NUMBER := 0;
  BEGIN
    SELECT get_sup_sublocata_byid (get_obj_id (p_codnaz, p_foglio, p_particella, p_sub, p_unimm),
                                   get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm), p_atto_ini,
                                   p_pk_cuaa, p_date)
      INTO m_suptot
      FROM DUAL;

    RETURN m_suptot;
  END get_sup_sublocata;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_sup_sublocata_byid (
    p_obj_id                             NUMBER,
    p_obj_type                           VARCHAR2,
    p_pk_atto                            NUMBER,
    p_pk_cuaa                            NUMBER,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    m_suptot                      NUMBER := 0;
    m_exist                       NUMBER := -1;
    m_date                        DATE;
    m_pk_cuaa                     NUMBER;
    m_fk_parent_atto              NUMBER := 0;
  BEGIN
    BEGIN
      -- ricerco l'id del contratto padre
      SELECT DISTINCT fkid_atto
                 INTO m_fk_parent_atto
                 FROM cons_subloc_tab
                WHERE atto_inizio = p_pk_atto;

      -- se p_date ï¿½ nullo prendo la data minuma di inizio titolarita
      IF p_date IS NULL THEN
        --m_date := get_min_date_subcond_byid(p_pk_atto, p_obj_type, p_obj_id);
        m_date := SYSDATE;
      ELSE
        m_date := p_date;
      END IF;

      -- se p_pk_cuaa ï¿½ nullo prendo una pk_cuaa a caso tra le ultime titolaritï¿½ che soddisfano gli altri parametri
      IF p_pk_cuaa IS NULL THEN
        m_pk_cuaa := get_pkcuaa_subcond_byid (p_pk_atto, m_date, p_obj_type, p_obj_id);
      ELSE
        m_pk_cuaa := p_pk_cuaa;
      END IF;

      IF p_obj_type = 'P' THEN
        -- superficie sublocata delle particelle
            --SELECT NVL (SUM (get_superficie_part (cod_nazionale, foglio, particella, sub, m_date)), 0),
        SELECT NVL (SUM (sup_part_altro_tit (m_fk_parent_atto, NULL, cod_nazionale, foglio, particella, sub, m_date)),
                    0),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM sititrkc
         WHERE (id_particella) IN (
                 SELECT fkid_obj
                   FROM cons_subloc_tab
                  WHERE obj_type = p_obj_type AND fkid_obj = p_obj_id AND pk_cuaa = m_pk_cuaa
                        AND atto_inizio = p_pk_atto AND data_inizio <= m_date AND data_fine >= m_date)
               AND data_aggi <= m_date AND data_fine >= m_date AND id_particella = p_obj_id;
      ELSIF p_obj_type = 'U' THEN
        -- superficie sublocata delle uiu
        SELECT COUNT (*)
          INTO m_exist
          FROM cons_subloc_tab
         WHERE fkid_obj = p_obj_id AND obj_type = p_obj_type AND atto_inizio = p_pk_atto AND pk_cuaa = m_pk_cuaa
               AND data_inizio <= m_date AND data_fine >= m_date;

        -- se trova un record vuol dire che ï¿½ affittata tutta la uiu
        -- se NON trova nessun record verifica se sono affittati i vani della UIU
        IF m_exist > 0 THEN
          --SELECT SUM (get_superficie_uiu (cod_nazionale, foglio, particella, sub, unimm, m_date)),
          SELECT SUM (sup_uiu_altro_tit (m_fk_parent_atto, NULL, cod_nazionale, foglio, particella, sub, unimm, m_date)),
                 COUNT (*)
            INTO m_suptot,
                 m_exist
            FROM (SELECT DISTINCT st.cod_nazionale,
                                  st.foglio,
                                  st.particella,
                                  st.sub,
                                  st.unimm
                             FROM cons_subloc_tab cst,
                                  (SELECT DISTINCT 'U' AS obj_type,
                                                   id_cata_uiu AS id_obj,
                                                   cod_nazionale,
                                                   foglio,
                                                   particella,
                                                   sub,
                                                   unimm
                                              FROM sitiuiu
                                             WHERE id_cata_uiu = p_obj_id) st
                            WHERE cst.obj_type = st.obj_type AND cst.fkid_obj = st.id_obj AND cst.fkid_obj = p_obj_id
                                  AND cst.obj_type = p_obj_type AND cst.pk_cuaa = m_pk_cuaa
                                  AND cst.atto_inizio = p_pk_atto AND cst.data_inizio <= m_date
                                  AND cst.data_fine >= m_date);
        ELSE
          --SELECT SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0)),
          SELECT SUM (apply_multiple_rent (NVL (supe_ambiente * c.coef_supe_modelli, 0), m_fk_parent_atto,
                                           v.cod_nazionale, v.foglio, v.particella, v.sub, v.unimm, m_date)),
                 COUNT (*)
            INTO m_suptot,
                 m_exist
            FROM (SELECT DISTINCT sv.cod_nazionale,
                                  sv.foglio,
                                  sv.particella,
                                  sv.sub,
                                  sv.unimm,
                                  sv.vano
                             FROM cons_subloc_tab cst,
                                  (SELECT DISTINCT sv2.id_cata_vano,
                                                   sv2.cod_nazionale,
                                                   sv2.foglio,
                                                   sv2.particella,
                                                   sv2.sub,
                                                   sv2.unimm,
                                                   sv2.vano
                                              FROM sitiedi_vani sv1,
                                                   sitiedi_vani sv2,
                                                   (SELECT DISTINCT cod_nazionale,
                                                                    foglio,
                                                                    particella,
                                                                    sub,
                                                                    unimm
                                                               FROM sitiuiu
                                                              WHERE id_cata_uiu = p_obj_id) su
                                             WHERE su.cod_nazionale = sv1.cod_nazionale AND su.foglio = sv1.foglio
                                                   AND su.particella = sv1.particella AND su.sub = sv1.sub
                                                   AND su.unimm = sv1.unimm AND sv1.cod_nazionale = sv2.cod_nazionale
                                                   AND sv1.foglio = sv2.foglio AND sv1.particella = sv2.particella
                                                   AND sv1.sub = sv2.sub AND sv1.unimm = sv2.unimm
                                                   AND sv1.data_inizio_val <= m_date AND sv1.data_fine_val >= m_date
                                                   AND sv2.data_inizio_val <= m_date AND sv2.data_fine_val >= m_date) sv
                            WHERE cst.obj_type = 'V' AND cst.fkid_obj = sv.id_cata_vano AND cst.atto_inizio = p_pk_atto
                                  AND cst.pk_cuaa = m_pk_cuaa AND cst.data_inizio <= m_date AND cst.data_fine >= m_date) t,
                 sitiedi_vani v,
                 sitiedi_uiu_ext e,
                 sitiedi_supe_codes c
           WHERE v.cod_nazionale = t.cod_nazionale AND v.foglio = t.foglio AND v.particella = t.particella
                 AND v.sub = t.sub AND v.unimm = t.unimm AND v.vano = t.vano AND v.cod_nazionale = e.cod_nazionale
                 AND v.foglio = e.foglio AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm
                 AND e.data_inizio_val <= m_date AND e.data_fine_val >= m_date AND v.data_inizio_val <= m_date
                 AND v.data_fine_val >= m_date AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;
        END IF;
      ELSIF p_obj_type = 'V' THEN
        -- superficie sublocata dei vani
        --SELECT SUM (NVL (supe_ambiente * c.coef_supe_modelli, 0)),
        SELECT SUM (apply_multiple_rent (NVL (supe_ambiente * c.coef_supe_modelli, 0), m_fk_parent_atto,
                                         v.cod_nazionale, v.foglio, v.particella, v.sub, v.unimm, m_date)),
               COUNT (*)
          INTO m_suptot,
               m_exist
          FROM (SELECT DISTINCT sv.cod_nazionale,
                                sv.foglio,
                                sv.particella,
                                sv.sub,
                                sv.unimm,
                                sv.vano
                           FROM cons_subloc_tab cst,
                                (SELECT DISTINCT sv2.id_cata_vano,
                                                 sv2.cod_nazionale,
                                                 sv2.foglio,
                                                 sv2.particella,
                                                 sv2.sub,
                                                 sv2.unimm,
                                                 sv2.vano
                                            FROM sitiedi_vani sv1, sitiedi_vani sv2
                                           WHERE sv1.id_cata_vano = p_obj_id AND sv1.cod_nazionale = sv2.cod_nazionale
                                                 AND sv1.foglio = sv2.foglio AND sv1.particella = sv2.particella
                                                 AND sv1.sub = sv2.sub AND sv1.unimm = sv2.unimm
                                                 AND sv1.data_inizio_val <= m_date AND sv1.data_fine_val >= m_date
                                                 AND sv2.data_inizio_val <= m_date AND sv2.data_fine_val >= m_date) sv
                          WHERE cst.obj_type = 'V' AND cst.fkid_obj = sv.id_cata_vano AND cst.atto_inizio = p_pk_atto
                                AND cst.pk_cuaa = m_pk_cuaa AND cst.data_inizio <= m_date AND cst.data_fine >= m_date) t,
               sitiedi_vani v,
               sitiedi_uiu_ext e,
               sitiedi_supe_codes c
         WHERE v.cod_nazionale = t.cod_nazionale AND v.foglio = t.foglio AND v.particella = t.particella
               AND v.sub = t.sub AND v.unimm = t.unimm AND v.vano = t.vano AND v.cod_nazionale = e.cod_nazionale
               AND v.foglio = e.foglio AND v.particella = e.particella AND v.sub = e.sub AND v.unimm = e.unimm
               AND e.data_inizio_val <= m_date AND e.data_fine_val >= m_date AND v.data_inizio_val <= m_date
               AND v.data_fine_val >= m_date AND c.fk_tipologia = e.fk_tipologia AND c.internal_code = v.ambiente;
      END IF;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        m_exist := -1;
        m_suptot := 0;
    END;

    IF m_exist = 0 THEN
      m_exist := -1;
    END IF;

    -- 2009/10/01 Contratti multipli su particelle e uiu
    -- moltiplico la superficie locata per il coefficiente del contratto di locazione che
    -- ï¿½ nel campo perc_cond di tutte le titolaritï¿½
    m_suptot := apply_multiple_rent_subloc (m_suptot, p_pk_atto, p_obj_id, p_obj_type, m_date);

    --raise_application_error (-20002, 'm_existUiu: ' || m_existUiu || '  m_existPart: ' || m_existPart);
    IF m_exist = -1 THEN
      m_suptot := -1;
    END IF;

    RETURN m_suptot;
  END get_sup_sublocata_byid;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_perc_sublocata (
    p_atto_ini                           NUMBER,
    p_pk_cuaa                            NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    m_perc                        NUMBER := 0;
    m_obj_type                    VARCHAR2 (1);
    m_obj_id                      NUMBER;
  BEGIN
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
    m_obj_id := get_obj_id (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
    m_perc := get_perc_sublocata_byid (m_obj_id, m_obj_type, p_atto_ini, p_pk_cuaa, p_date);
    RETURN m_perc;
  END get_perc_sublocata;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_perc_sublocata_byid (
    p_obj_id                             NUMBER,
    p_obj_type                           VARCHAR2,
    p_pk_atto                            NUMBER,
    p_pk_cuaa                            NUMBER,
    p_date                               DATE DEFAULT NULL
  )
    RETURN NUMBER IS
    m_date                        DATE;
    m_obj_id                      NUMBER;
    sup                           NUMBER;
    sup_locata                    NUMBER;
    perc_locata                   NUMBER := 100;
  BEGIN
    sup_locata := get_sup_sublocata_byid (p_obj_id, p_obj_type, p_pk_atto, p_pk_cuaa, p_date);

    -- se p_date ï¿½ nullo prendo la data minuma di inizio titolarita
    IF p_date IS NULL THEN
      --m_date := get_min_date_subcond_byid(p_pk_atto, p_obj_type, p_obj_id);
      m_date := SYSDATE;
    ELSE
      m_date := p_date;
    END IF;

    IF p_obj_type = 'V' THEN
      -- se ï¿½ un vano devo risalire all'ID della UIU
      SELECT DISTINCT id_cata_uiu
                 INTO m_obj_id
                 FROM sitiuiu
                WHERE (cod_nazionale, foglio, particella, sub, unimm) IN (
                                                           SELECT DISTINCT cod_nazionale,
                                                                           foglio,
                                                                           particella,
                                                                           sub,
                                                                           unimm
                                                                      FROM sitiedi_vani
                                                                     WHERE id_cata_vano = p_obj_id);

      sup := get_sup_obj (m_obj_id, 'U', m_date);
    ELSE
      sup := get_sup_obj (p_obj_id, p_obj_type, m_date);
    END IF;

    -- se sup_locata vale -1 vuol dire che non esiste una superficie locata
    IF (sup = 0 OR sup < sup_locata OR sup_locata = -1) THEN
      sup := sup_locata;
    END IF;

    IF sup = -1 THEN
      perc_locata := 0;
    ELSIF sup = 0 THEN
      perc_locata := apply_multiple_rent_subloc (100, p_pk_atto, p_obj_id, p_obj_type, m_date);
    ELSE
      perc_locata := (sup_locata / sup) * 100;
    END IF;

    RETURN perc_locata;
  END get_perc_sublocata_byid;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_obj_id (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_vano                               NUMBER DEFAULT NULL
  )
    RETURN NUMBER IS
    m_obj_id                      NUMBER;
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm, p_vano);

    IF TRIM (m_obj_type) = 'P' THEN
      -- PARTICELLA
      SELECT DISTINCT id_particella
                 INTO m_obj_id
                 FROM sititrkc
                WHERE cod_nazionale = p_codnaz AND foglio = p_foglio AND particella = p_particella AND sub = p_sub;
    ELSIF TRIM (m_obj_type) = 'U' THEN
      -- UIU
      SELECT DISTINCT id_cata_uiu
                 INTO m_obj_id
                 FROM sitiuiu
                WHERE cod_nazionale = p_codnaz AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
                      AND unimm = p_unimm;
    ELSE
      -- VANO
      SELECT DISTINCT id_cata_vano
                 INTO m_obj_id
                 FROM sitiedi_vani
                WHERE cod_nazionale = p_codnaz AND foglio = p_foglio AND particella = p_particella AND sub = p_sub
                      AND unimm = p_unimm AND vano = p_vano;
    END IF;

    RETURN m_obj_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
  END get_obj_id;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_obj_type (
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL,
    p_vano                               NUMBER DEFAULT NULL
  )
    RETURN VARCHAR IS
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    IF p_unimm IS NULL THEN                                                                               -- PARTICELLA
      m_obj_type := 'P';
    ELSIF p_unimm IS NOT NULL AND p_vano IS NULL THEN                                                             -- UIU
      m_obj_type := 'U';
    ELSE
      -- VANO
      m_obj_type := 'V';
    END IF;

    RETURN m_obj_type;
  END get_obj_type;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_pkcuaa_cond (
    p_atto                               NUMBER,
    p_date                               DATE DEFAULT NULL,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN NUMBER IS
    m_pk_cuaa                     NUMBER;
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);

    -- se la data ï¿½ nulla
    IF p_date IS NULL THEN
      IF m_obj_type = 'P' THEN
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM siticond_all2 a
                   WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
                         AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      ELSE
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM siticonduz_imm_all2 a
                   WHERE atto_inizio = p_atto AND tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
                         AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub AND a.unimm = p_unimm
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      END IF;
    ELSE
      IF m_obj_type = 'P' THEN
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM siticond_all2 a
                   WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
                         AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub
                         AND a.data_inizio <= p_date AND a.data_fine >= p_date
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      ELSE
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM siticonduz_imm_all2 a
                   WHERE atto_inizio = p_atto AND tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
                         AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub AND a.unimm = p_unimm
                         AND a.data_inizio <= p_date AND a.data_fine >= p_date
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      END IF;
    END IF;

    RETURN m_pk_cuaa;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
  END get_pkcuaa_cond;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_pkcuaa_subcond (
    p_atto                               NUMBER,
    p_date                               DATE DEFAULT NULL,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN NUMBER IS
    m_pk_cuaa                     NUMBER;
    m_obj_type                    VARCHAR2 (1);
    m_obj_id                      NUMBER;
  BEGIN
    m_obj_id := get_obj_id (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
    m_pk_cuaa := get_pkcuaa_subcond_byid (p_atto, p_date, m_obj_type, m_obj_id);
    RETURN m_pk_cuaa;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
  END get_pkcuaa_subcond;

-----------------------------------------------------------------------------------------------------
  FUNCTION get_pkcuaa_subcond_byid (p_atto NUMBER, p_date DATE DEFAULT NULL, p_obj_type VARCHAR2, p_obj_id NUMBER)
    RETURN NUMBER IS
    m_pk_cuaa                     NUMBER;
    m_uiu_cnt                     NUMBER;
  BEGIN
    SELECT COUNT (*)
      INTO m_uiu_cnt
      FROM cons_subloc_tab a
     WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = p_obj_type AND fkid_obj = p_obj_id
	    AND data_inizio <= p_date AND data_fine >= p_date;

    -- Se il tipo di oggetto ï¿½ una UIU e non lo trovo nelle sublocazione,
    -- devo verificare se ci sono dei vani affittati
    IF m_uiu_cnt = 0 AND p_obj_type = 'U' THEN
      IF p_date IS NULL THEN
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM cons_subloc_tab a
                   WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = 'V'
                         AND fkid_obj IN (
                              SELECT DISTINCT id_cata_vano
                                         FROM sitiedi_vani
                                        WHERE (cod_nazionale, foglio, particella, sub, unimm) IN (
                                                           SELECT DISTINCT cod_nazionale,
                                                                           foglio,
                                                                           particella,
                                                                           sub,
                                                                           unimm
                                                                      FROM sitiuiu
                                                                     WHERE id_cata_uiu = p_obj_id))
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      ELSE
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM cons_subloc_tab a
                   WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = 'V'
                         AND fkid_obj IN (
                              SELECT DISTINCT id_cata_vano
                                         FROM sitiedi_vani
                                        WHERE (cod_nazionale, foglio, particella, sub, unimm) IN (
                                                           SELECT DISTINCT cod_nazionale,
                                                                           foglio,
                                                                           particella,
                                                                           sub,
                                                                           unimm
                                                                      FROM sitiuiu
                                                                     WHERE id_cata_uiu = p_obj_id))
                         AND data_inizio <= p_date AND data_fine >= p_date
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      END IF;
    ELSE
      IF p_date IS NULL THEN
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM cons_subloc_tab a
                   WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = p_obj_type
                         AND fkid_obj = p_obj_id
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      ELSE
        SELECT pk_cuaa
          INTO m_pk_cuaa
          FROM (SELECT   pk_cuaa
                    FROM cons_subloc_tab a
                   WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = p_obj_type
                         AND fkid_obj = p_obj_id AND data_inizio <= p_date AND data_fine >= p_date
                ORDER BY data_fine DESC)
         WHERE ROWNUM = 1;
      END IF;
    END IF;

    RETURN m_pk_cuaa;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
  END get_pkcuaa_subcond_byid;

-----------------------------------------------------------------------------------------------------
  -- Ritorna la data minima di conduzione associata all'atto di titolaritï¿½
  FUNCTION get_min_date_cond (
    p_atto                               NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN DATE IS
    m_date                        DATE;
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);

    IF m_obj_type = 'P' THEN
      SELECT MIN (data_inizio)
        INTO m_date
        FROM siticond_all2 a
       WHERE atto_inizio = p_atto AND tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
             AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub;
    ELSE
      SELECT MIN (data_inizio)
        INTO m_date
        FROM siticonduz_imm_all2 a
       WHERE atto_inizio = p_atto AND tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
             AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub AND a.unimm = p_unimm;
    END IF;

    RETURN m_date;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN SYSDATE;
  END get_min_date_cond;

-----------------------------------------------------------------------------------------------------
  -- Ritorna la data minima di conduzione associata all'atto di titolaritï¿½
  FUNCTION get_max_date_cond (
    p_atto                               NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN DATE IS
    m_date                        DATE;
    m_obj_type                    VARCHAR2 (1);
  BEGIN
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);

    IF m_obj_type = 'P' THEN
      SELECT MAX (data_fine)
        INTO m_date
        FROM siticond_all2 a
       WHERE atto_inizio = p_atto AND tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
             AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub;
    ELSE
      SELECT MAX (data_fine)
        INTO m_date
        FROM siticonduz_imm_all2 a
       WHERE atto_inizio = p_atto AND tipo_titolo NOT IN (1, 3, 9) AND a.cod_nazionale = p_codnaz
             AND a.foglio = p_foglio AND a.particella = p_particella AND a.sub = p_sub AND a.unimm = p_unimm;
    END IF;

    RETURN m_date;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN SYSDATE;
  END get_max_date_cond;

-----------------------------------------------------------------------------------------------------
  -- Ritorna la data minima di SUBconduzione associata all'atto di titolaritï¿½
  FUNCTION get_min_date_subcond (
    p_atto                               NUMBER,
    p_codnaz                             VARCHAR2,
    p_foglio                             NUMBER,
    p_particella                         VARCHAR2,
    p_sub                                VARCHAR2,
    p_unimm                              NUMBER DEFAULT NULL
  )
    RETURN DATE IS
    m_date                        DATE;
    m_obj_type                    VARCHAR2 (1);
    m_obj_id                      NUMBER;
  BEGIN
    m_obj_id := get_obj_id (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
    m_obj_type := get_obj_type (p_codnaz, p_foglio, p_particella, p_sub, p_unimm);
    m_date := get_min_date_subcond_byid (p_atto, m_obj_type, m_obj_id);
    RETURN m_date;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN SYSDATE;
  END get_min_date_subcond;

-----------------------------------------------------------------------------------------------------
  -- Ritorna la data minima di SUBconduzione associata all'atto di titolaritï¿½
  FUNCTION get_min_date_subcond_byid (p_atto NUMBER, p_obj_type VARCHAR2, p_obj_id NUMBER)
    RETURN DATE IS
    m_date                        DATE;
    m_uiu_cnt                     NUMBER;
  BEGIN
    SELECT COUNT (*)
      INTO m_uiu_cnt
      FROM cons_subloc_tab a
     WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = p_obj_type AND fkid_obj = p_obj_id;

    -- Se il tipo di oggetto ï¿½ una UIU devo verificare se ci sono dei vani affittati
    IF m_uiu_cnt = 0 AND p_obj_type = 'U' THEN
      SELECT MIN (data_inizio)
        INTO m_date
        FROM cons_subloc_tab a
       WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = 'V'
             AND fkid_obj IN (
                  SELECT DISTINCT id_cata_vano
                             FROM sitiedi_vani
                            WHERE (cod_nazionale, foglio, particella, sub, unimm) IN (
                                                           SELECT DISTINCT cod_nazionale,
                                                                           foglio,
                                                                           particella,
                                                                           sub,
                                                                           unimm
                                                                      FROM sitiuiu
                                                                     WHERE id_cata_uiu = p_obj_id));
    ELSE
      SELECT MIN (data_inizio)
        INTO m_date
        FROM cons_subloc_tab a
       WHERE a.atto_inizio = p_atto AND a.tipo_titolo NOT IN (1, 3, 9) AND a.obj_type = p_obj_type
             AND fkid_obj = p_obj_id;
    END IF;

    RETURN m_date;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN SYSDATE;
  END get_min_date_subcond_byid;
END titoli_pck;
/


DROP PACKAGE BODY SITI_H501.UIU;

CREATE OR REPLACE PACKAGE BODY SITI_H501.uiu AS
 
  type DATI_CAT_TP is record (
   cod_nazionale   sitiuiu.COD_NAZIONALE%TYPE,
    foglio     sitiuiu.foglio%type,
    particella   sitiuiu.particella%type,
    sub       sitiuiu.sub%type,
    unimm      sitiuiu.unimm%type,
    validato    sitiuiu.validato_da_cat%type,
    dt_ini     sitiuiu.data_inizio_val%type,
    dt_fin     sitiuiu.data_fine_val%type
  );
  
  
------------------------------
 function getUiu(codNaz varchar2, fg number, part varchar2, suba varchar2, uni number, dataCheck date) RETURN DATI_CAT_TP is
   ret   DATI_CAT_TP;   
  begin

   begin
       select cod_nazionale, foglio, particella, sub, unimm, validato_da_cat, data_inizio_val, data_fine_val
         into ret
     from sitiuiu
        where COD_NAZIONALE = codNaz
          and FOGLIO = fg
          and particella = part
          and sub = suba
          and unimm = uni
          and DATA_INIZIO_VAL <= dataCheck
          and DATA_FINE_VAL >= dataCheck
          and rownum = 1;
    exception when no_data_found then
   begin
    select cod_nazionale, foglio, particella, sub, unimm, validato_da_cat, data_inizio_val, data_fine_val
          into ret
      from sitiuiu
         where COD_NAZIONALE = codNaz
           and FOGLIO = fg
           and particella = part
           and sub = suba
           and unimm = uni
           and DATA_INIZIO_VAL <= dataCheck
           and rownum = 1;
      exception when no_data_found then
       ret := null;
      end;        
    end;

   return ret;
  end getUiu;

  
------------------------------
 FUNCTION stato_gis(codNaz varchar2, fg number, part varchar2, suba varchar2, uni number, dataCheck date) RETURN NUMBER is
  ret   number;   
  begin
   begin
   select 1
        into ret
        from dual
       where exists (select 1
                       from sitisuolo
                      where COD_NAZIONALE = codNaz
                        and FOGLIO = fg
                        and PARTICELLA = part 
                        and SUB = suba
                        and DATA_INIZIO_VAL <= dataCheck
                        and DATA_FINE_VAL >= dataCheck
                        and ((COD_UTIL=100) or (COD_UTIL=5 AND COD_COLTURA=660)));
    exception when no_data_found then
     ret := 0;
    end;
    
    return ret;
  end stato_gis;
    

------------------------------
  FUNCTION stato_cat(codNaz varchar2, fg number, part varchar2, suba varchar2, uni number, dataCheck date) RETURN NUMBER is
  ret   number;
    dt   date;
    tmp   DATI_CAT_TP;
  begin
    dt := nvl(dataCheck, to_date('99991231', 'yyyymmdd'));
    
    tmp := getUiu(codNaz, fg, part, suba, uni, dt);
    
    if tmp.dt_fin < dt then
     ret := 1;
    elsif tmp.dt_fin >= dt then
     ret := 2;
    else
     ret := 0;
    end if;
    
    return ret;
  end stato_cat;

------------------------------  
  function cat_validato(codNaz varchar2, fg number, part varchar2, suba varchar2, uni number, dataCheck date) RETURN NUMBER is
    dt   date;    
    tmp   DATI_CAT_TP;
  begin
    dt := nvl(dataCheck, to_date('99991231', 'yyyymmdd'));   
    
    tmp := getUiu(codNaz, fg, part, suba, uni, dt);
    
    return tmp.validato; 
  end cat_validato;
  
------------------------------  
  function get_categoria(codNaz varchar2, fg number, part varchar2, suba varchar2, uni number, dataCheck date) RETURN varchar2 is
   ret   sitiuiu.categoria%type;
  begin
   begin
     select categoria
        into ret
        from sitiuiu
       where COD_NAZIONALE = codNaz
         and FOGLIO = fg
         and particella = part
         and sub = suba
         and unimm = uni
         and DATA_INIZIO_VAL <= dataCheck
         and DATA_FINE_VAL >= dataCheck
         and rownum = 1;
    exception when no_data_found then
     ret := null;
    end;
    
    return ret;
  end get_categoria;
  
------------------------------
 function get_classe(codNaz varchar2, fg number, part varchar2, suba varchar2, uni number, dataCheck date) RETURN varchar2 is
   ret   sitiuiu.classe%type;
  begin
   begin
     select classe
        into ret
        from sitiuiu
       where COD_NAZIONALE = codNaz
         and FOGLIO = fg
         and particella = part
         and sub = suba
         and unimm = uni
         and DATA_INIZIO_VAL <= dataCheck
         and DATA_FINE_VAL >= dataCheck
         and rownum = 1;
    exception when no_data_found then
     ret := null;
    end;
    
    return ret;
  end get_classe;
    
end uiu;
/


DROP PACKAGE BODY SITI_H501.UPDATE_GIS_DATA;

CREATE OR REPLACE PACKAGE BODY SITI_H501.update_gis_data AS

FUNCTION SCADI_CENT(CodNaz IN VARCHAR2, Fog IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2,STATO_PROP IN NUMBER,IDTR IN NUMBER) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_INIZIO_VAL,DATA_FINE_VAL,SE_ROW_ID FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO;
  CURSOR C2 IS SELECT DATA_INIZIO_VAL FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL > DATA_INIZIO ORDER BY DATA_INIZIO_VAL;

  INIZIO_VER DATE;
  FINE_VER DATE;
  SEROWIDATT NUMBER(9);
  INIZIO_VER_SUCC DATE;
  RETVAL DATE;  -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE
BEGIN
  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER,SEROWIDATT;
  IF C1%NOTFOUND THEN SEROWIDATT:= NULL; END IF;
  CLOSE C1;

  IF INIZIO_VER = DATA_INIZIO THEN
    IF DATA_FINE <  FINE_VER THEN RAISE_APPLICATION_ERROR(-20005, 'Scartato - data fine registrazione è minore della data fine in archivio'); END IF;
    RAISE_APPLICATION_ERROR(-20001, 'Scartato - data inizio registrazione uguale data inizio in archivio');
  END IF;

  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> To_Date('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;

  IF NOT(SEROWIDATT IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
      UPDATE SITICENT SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN,ID_TRASF_FINE=IDTR WHERE SE_ROW_ID = SEROWIDATT;
  END IF;

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
  RETURN RETVAL;
END SCADI_CENT;

FUNCTION SCADI_PART(CodNaz IN VARCHAR2, Fog IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2,STATO_PROP IN NUMBER,IDTR IN NUMBER) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_INIZIO_VAL,DATA_FINE_VAL,SE_ROW_ID FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO;
  CURSOR C2 IS SELECT DATA_INIZIO_VAL FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL > DATA_INIZIO ORDER BY DATA_INIZIO_VAL;

  INIZIO_VER DATE;
  FINE_VER DATE;
  SEROWIDATT NUMBER;
  INIZIO_VER_SUCC DATE;
  RETVAL DATE;  -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE
BEGIN

  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER,SEROWIDATT;
  IF C1%NOTFOUND THEN SEROWIDATT:= NULL; END IF;
  CLOSE C1;

  IF INIZIO_VER = DATA_INIZIO THEN
    IF DATA_FINE <  FINE_VER THEN raise_application_error(-20005, 'Particella Scartata - data fine registrazione è minore della data fine in archivio'); END IF;
    raise_application_error(-20001, 'Particella Scartata - data inizio registrazione uguale data inizio in archivio');
  END IF;

  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> To_Date('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;

  IF NOT(SEROWIDATT IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
    UPDATE SITIPART SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN,ID_TRASF_FINE=IDTR WHERE SE_ROW_ID = SEROWIDATT;
  END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
RETURN RETVAL;
-- OKKIO NON FA LA COMMIT
END SCADI_PART;

FUNCTION SCADI_SUOLO(CodNaz IN VARCHAR2, Fog IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2,PROG_POLI IN NUMBER,STATO_PROP IN NUMBER,IDTR IN NUMBER) RETURN DATE
IS
CURSOR C1 IS SELECT DATA_INIZIO_VAL,DATA_FINE_VAL FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL < DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO;
CURSOR C2 IS SELECT DATA_INIZIO_VAL FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL > DATA_INIZIO ORDER BY DATA_INIZIO_VAL;
CURSOR C3 IS SELECT SE_ROW_ID,DATA_FINE_VAL FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL = DATA_INIZIO AND PROG_POLIGONO = PROG_POLI;

ESISTEGIA NUMBER;
INIZIO_VER DATE;
FINE_VER DATE;
SEROWIDATT NUMBER;
INIZIO_VER_SUCC DATE;
RETVAL DATE;  -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE

BEGIN

OPEN C3;
FETCH C3 INTO ESISTEGIA,FINE_VER;
IF C3%NOTFOUND THEN ESISTEGIA:= 0; END IF;
CLOSE C3;

IF ESISTEGIA>0 THEN
--  RETVAL:=To_Date('99990101000000','YYYYMMDDHH24MISS'); -- SIGNIFICA CHE ESISTE GIa
--  DELETE FROM SITISUOLO WHERE SE_ROW_ID=ESISTEGIA;
  IF DATA_FINE <  FINE_VER THEN raise_application_error(-20005, 'Scartato'); END IF;
  raise_application_error(-20001, 'Scartato');
END IF;

  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER;
  IF C1%NOTFOUND THEN INIZIO_VER:= NULL; END IF;
  CLOSE C1;

  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> To_Date('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;

  IF NOT(INIZIO_VER IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
    UPDATE SITISUOLO SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN,ID_TRASF_FINE=IDTR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL = INIZIO_VER;
  END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
RETURN RETVAL;
-- OKKIO NON FA LA COMMIT
END SCADI_SUOLO;

FUNCTION SCADI_FOTC(CodNaz IN VARCHAR2, Fog IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2,PROG_POLI IN NUMBER,STATO_PROP IN NUMBER,IDTR IN NUMBER) RETURN DATE
IS
TYPE EMPTYCUR IS REF CURSOR;
C1 EMPTYCUR;
C2 EMPTYCUR;
CURSOR C3 IS SELECT SE_ROW_ID FROM SITIFOTC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL = DATA_INIZIO AND PROG_FOTO = PROG_POLI;

ESISTEGIA NUMBER;
INIZIO_VER DATE;
FINE_VER DATE;
SEROWIDATT NUMBER;
INIZIO_VER_SUCC DATE;
RETVAL DATE;  -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE

BEGIN

-- VEDO SE ESISTE UNA VERSIONE CORRENTE ALLA MIA DATA
-- VEDO SE ESITE UNA VERSIONE SUCCESSIVA ALLA MIA DATA
-- VEDO SE IL RECORD CHE STO INSERENDO ESISTE GIa

OPEN C3;
FETCH C3 INTO ESISTEGIA;
IF C3%NOTFOUND THEN ESISTEGIA:= 0; END IF;
CLOSE C3;

IF ESISTEGIA>0 THEN
--  RETVAL:=To_Date('99990101000000','YYYYMMDDHH24MISS'); -- SIGNIFICA CHE ESISTE GIa
--  DELETE FROM SITIFOTC WHERE SE_ROW_ID=ESISTEGIA;
  raise_application_error(-20001, 'Scartato');
END IF;

  OPEN C1 FOR SELECT DATA_INIZIO_VAL,DATA_FINE_VAL FROM SITIFOTC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL < DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO;
  FETCH C1 INTO INIZIO_VER,FINE_VER;
  IF C1%NOTFOUND THEN INIZIO_VER:= NULL; END IF;
  CLOSE C1;

  OPEN C2 FOR SELECT DATA_INIZIO_VAL FROM SITIFOTC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL > DATA_INIZIO ORDER BY DATA_INIZIO_VAL;
  FETCH C2 INTO  INIZIO_VER_SUCC;
  IF C2%NOTFOUND THEN INIZIO_VER_SUCC:= NULL; END IF;
  CLOSE C2;

  IF NOT(INIZIO_VER IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
    UPDATE SITIFOTC SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN,ID_TRASF_FINE=IDTR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL = INIZIO_VER;
  END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
RETURN RETVAL;
-- OKKIO NON FA LA COMMIT
END SCADI_FOTC;

PROCEDURE VALIDA_PARTICELLA(CodNaz IN VARCHAR2, Fog IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_DA_VALIDARE IN DATE,UTEN IN VARCHAR2, IDLAV IN NUMBER)
IS
  CURSOR C1 IS SELECT MAX(DATA_INIZIO_VAL),MIN(DATA_INIZIO_VAL) FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;
  CURSOR C2 IS SELECT MAX(DATA_INIZIO_VAL),MIN(DATA_INIZIO_VAL) FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;
  CURSOR C3 IS SELECT MAX(DATA_INIZIO_VAL),MIN(DATA_INIZIO_VAL) FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;

  DATAIN DATE;
  DATAFI DATE;
BEGIN
  OPEN C1;  FETCH C1 INTO DATAIN,DATAFI;  CLOSE C1;
  IF DATAIN IS NOT NULL THEN
    DELETE FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0 AND DATA_INIZIO_VAL < DATAIN;
    UPDATE SITICENT SET DATA_FINE_VAL=DATAIN - (1 / 24 / 60 / 60) WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATAFI-(1 / 24 / 60 / 60) AND DATA_FINE_VAL >= DATAFI-(1 / 24 / 60 / 60);
  END IF;
  UPDATE SITICENT SET STATO_PROP=0,VALI_PROD=1 WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;

  OPEN C2;  FETCH C2 INTO DATAIN,DATAFI;  CLOSE C2;
  IF DATAIN IS NOT NULL THEN
    DELETE FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0 AND DATA_INIZIO_VAL < DATAIN;
    UPDATE SITIPART SET DATA_FINE_VAL=DATAIN - (1 / 24 / 60 / 60) WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATAFI-(1 / 24 / 60 / 60) AND DATA_FINE_VAL >= DATAFI-(1 / 24 / 60 / 60);
  END IF;
  UPDATE SITIPART SET STATO_PROP=0,VALI_PROD=1 WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;

  OPEN C3;  FETCH C3 INTO DATAIN,DATAFI;  CLOSE C3;
  IF DATAIN IS NOT NULL THEN
    DELETE FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0 AND DATA_INIZIO_VAL < DATAIN;
    UPDATE SITISUOLO SET DATA_FINE_VAL=DATAIN - (1 / 24 / 60 / 60) WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATAFI-(1 / 24 / 60 / 60) AND DATA_FINE_VAL >= DATAFI-(1 / 24 / 60 / 60);
  END IF;
  UPDATE SITISUOLO SET STATO_PROP=0,VALI_PROD=1 WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;

  IF IDLAV >0 THEN
    UPDATE sitiplav SET stato_prop = 0 WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_LAV <= DATA_DA_VALIDARE AND ID_LAV=IDLAV;
  END IF;
END VALIDA_PARTICELLA;

PROCEDURE RIFIUTA_PARTICELLA(CodNaz IN VARCHAR2, Fog IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_DA_VALIDARE IN DATE,UTEN IN VARCHAR2, IDLAV IN NUMBER)
IS
  CURSOR C1 IS SELECT MIN(DATA_INIZIO_VAL),MAX(DATA_FINE_VAL) FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;
  CURSOR C2 IS SELECT MIN(DATA_INIZIO_VAL),MAX(DATA_FINE_VAL) FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;
  CURSOR C3 IS SELECT MIN(DATA_INIZIO_VAL),MAX(DATA_FINE_VAL) FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0;

  DATAIN DATE;
  DATAFI DATE;
BEGIN
  OPEN C1;  FETCH C1 INTO DATAIN,DATAFI;  CLOSE C1;
  IF DATAIN IS NOT NULL THEN
    DELETE FROM SITICENT WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0 AND DATA_INIZIO_VAL>=DATAIN AND DATA_FINE_VAL<=DATAFI;
    UPDATE SITICENT SET DATA_FINE_VAL=DATAFI WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATAIN - (1 / 24 / 60 / 60) AND DATA_FINE_VAL >= DATAIN - (1 / 24 / 60 / 60);
  END IF;

  OPEN C2;  FETCH C2 INTO DATAIN,DATAFI;  CLOSE C2;
  IF DATAIN IS NOT NULL THEN
    DELETE FROM SITIPART WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0 AND DATA_INIZIO_VAL>=DATAIN AND DATA_FINE_VAL<=DATAFI;
    UPDATE SITIPART SET DATA_FINE_VAL=DATAFI WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATAIN - (1 / 24 / 60 / 60) AND DATA_FINE_VAL >= DATAIN - (1 / 24 / 60 / 60);
  END IF;

  OPEN C3;  FETCH C3 INTO DATAIN,DATAFI;  CLOSE C3;
  IF DATAIN IS NOT NULL THEN
    DELETE FROM SITISUOLO WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND STATO_PROP>0 AND DATA_INIZIO_VAL>=DATAIN AND DATA_FINE_VAL<=DATAFI;
    UPDATE SITISUOLO SET DATA_FINE_VAL=DATAFI WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL <= DATAIN - (1 / 24 / 60 / 60) AND DATA_FINE_VAL >= DATAIN - (1 / 24 / 60 / 60);
  END IF;

  IF IDLAV >0 THEN
    UPDATE sitiplav SET stato_prop = 0 WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_LAV <= DATA_DA_VALIDARE AND ID_LAV=IDLAV;
  END IF;
END RIFIUTA_PARTICELLA;

FUNCTION SCADI_UNARB(CodNaz IN VARCHAR2, Fog IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,UIMM IN NUMBER,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2) RETURN DATE
IS
TYPE EMPTYCUR IS REF CURSOR;
C1 EMPTYCUR;
C2 EMPTYCUR;
CURSOR C3 IS SELECT PKID_UNAR FROM SITIUNAR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND UNAR=UIMM AND DATA_INIZIO_VAL = DATA_INIZIO;

ESISTEGIA NUMBER;
INIZIO_VER DATE;
FINE_VER DATE;
SEROWIDATT NUMBER;
INIZIO_VER_SUCC DATE;
RETVAL DATE;  -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE

BEGIN

-- VEDO SE ESISTE UNA VERSIONE CORRENTE ALLA MIA DATA
-- VEDO SE ESITE UNA VERSIONE SUCCESSIVA ALLA MIA DATA
-- VEDO SE IL RECORD CHE STO INSERENDO ESISTE GIa

OPEN C3;
FETCH C3 INTO ESISTEGIA;
IF C3%NOTFOUND THEN ESISTEGIA:= 0; END IF;
CLOSE C3;

IF ESISTEGIA>0 THEN
  raise_application_error(-20001, 'Scartato');
END IF;

  OPEN C1 FOR SELECT DATA_INIZIO_VAL,DATA_FINE_VAL,PKID_UNAR FROM SITIUNAR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND UNAR=UIMM AND DATA_INIZIO_VAL < DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO ORDER BY DATA_INIZIO;
  FETCH C1 INTO INIZIO_VER,FINE_VER,SEROWIDATT;
  IF C1%NOTFOUND THEN SEROWIDATT:= NULL; END IF;
  CLOSE C1;

  OPEN C2 FOR SELECT DATA_INIZIO_VAL FROM SITIUNAR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND UNAR=UIMM AND DATA_INIZIO_VAL > DATA_INIZIO;
  FETCH C2 INTO  INIZIO_VER_SUCC;
  IF C2%NOTFOUND THEN INIZIO_VER_SUCC:= NULL; END IF;
  CLOSE C2;

  IF NOT(SEROWIDATT IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
      UPDATE SITIUNAR SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN WHERE PKID_UNAR = SEROWIDATT;
  END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
RETURN RETVAL;
-- OKKIO NON FA LA COMMIT
END SCADI_UNARB;


FUNCTION SCADI_PIANTE(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2,PROG_POLI IN NUMBER,STATO_PROP IN NUMBER,IDTR IN NUMBER) RETURN DATE
IS
CURSOR C1 IS SELECT DATA_INIZIO_VAL,DATA_FINE_VAL FROM SITIPIANTE WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL < DATA_INIZIO AND DATA_FINE_VAL > DATA_INIZIO;
CURSOR C2 IS SELECT DATA_INIZIO_VAL FROM SITIPIANTE WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL > DATA_INIZIO ORDER BY DATA_INIZIO_VAL;
CURSOR C3 IS SELECT SE_ROW_ID,DATA_FINE_VAL FROM SITIPIANTE WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL = DATA_INIZIO AND PROG_POLIGONO = PROG_POLI;

ESISTEGIA NUMBER;
INIZIO_VER DATE;
FINE_VER DATE;
SEROWIDATT NUMBER;
INIZIO_VER_SUCC DATE;
RETVAL DATE;  -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE

BEGIN

-- VEDO SE ESISTE UNA VERSIONE CORRENTE ALLA MIA DATA
-- VEDO SE ESITE UNA VERSIONE SUCCESSIVA ALLA MIA DATA
-- VEDO SE IL RECORD CHE STO INSERENDO ESISTE GIa

OPEN C3;
FETCH C3 INTO ESISTEGIA,FINE_VER;
IF C3%NOTFOUND THEN ESISTEGIA:= 0; END IF;
CLOSE C3;

IF ESISTEGIA>0 THEN
--  RETVAL:=To_Date('99990101000000','YYYYMMDDHH24MISS'); -- SIGNIFICA CHE ESISTE GIa
--  DELETE FROM SITISUOLO WHERE SE_ROW_ID=ESISTEGIA;
  IF DATA_FINE <  FINE_VER THEN raise_application_error(-20005, 'Scartato'); END IF;
  raise_application_error(-20001, 'Scartato');
END IF;

  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER;
  IF C1%NOTFOUND THEN INIZIO_VER:= NULL; END IF;
  CLOSE C1;

  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> To_Date('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;

  IF NOT(INIZIO_VER IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
    IF STATO_PROP>0 THEN
      UPDATE SITIPIANTE SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN,STATO_PROP=2,ID_TRASF_FINE=IDTR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL = INIZIO_VER;
    ELSE
      UPDATE SITIPIANTE SET DATA_FINE_VAL = DATA_INIZIO - (1 / 24 / 60 / 60),UTENTE_FINE = UTEN,ID_TRASF_FINE=IDTR WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_INIZIO_VAL = INIZIO_VER;
    END IF;
  END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
RETURN RETVAL;
-- OKKIO NON FA LA COMMIT
END SCADI_PIANTE;

FUNCTION SCADI_TRKC(CODNAZ IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2,SUBAL IN VARCHAR2,DATA_INIZIO IN DATE,DATA_FINE IN DATE,UTEN IN VARCHAR2,STATO_PROP IN NUMBER,IDTR IN NUMBER) RETURN DATE
IS
  CURSOR C1 IS SELECT DATA_AGGI,DATA_FINE,TRKC_ID FROM SITITRKC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND data_aggi <= DATA_INIZIO AND DATA_FINE > DATA_INIZIO;
  CURSOR C2 IS SELECT DATA_AGGI FROM SITITRKC WHERE COD_NAZIONALE=CODNAZ AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBAL AND DATA_AGGI > DATA_INIZIO ORDER BY DATA_AGGI;

  INIZIO_VER DATE;
  FINE_VER DATE;
  SEROWIDATT NUMBER(9);
  INIZIO_VER_SUCC DATE;
  RETVAL DATE;
BEGIN
-- VEDO SE ESISTE UNA VERSIONE CORRENTE ALLA MIA DATA
-- VEDO SE ESITE UNA VERSIONE SUCCESSIVA ALLA MIA DATA
-- VEDO SE IL RECORD CHE STO INSERENDO ESISTE GIA

  OPEN C1;
  FETCH C1 INTO INIZIO_VER,FINE_VER,SEROWIDATT;
  IF C1%NOTFOUND THEN SEROWIDATT:= NULL; END IF;
  CLOSE C1;

  IF INIZIO_VER = DATA_INIZIO THEN
    IF DATA_FINE <  FINE_VER THEN RAISE_APPLICATION_ERROR(-20005, 'SCARTATO'); END IF;
    RAISE_APPLICATION_ERROR(-20001, 'SCARTATO');
  END IF;

  INIZIO_VER_SUCC:=NULL;
  IF FINE_VER <> TO_DATE('99991231','YYYYMMDD') OR FINE_VER IS NULL THEN
    OPEN C2;
    FETCH C2 INTO  INIZIO_VER_SUCC;
    CLOSE C2;
  END IF;

  IF NOT(SEROWIDATT IS NULL) THEN --FACCIO SCADERE LA VERSIONE CHE C'ERA
      UPDATE SITITRKC SET DATA_FINE = DATA_INIZIO - (1 / 24 / 60 / 60),VALIDA=0,UTENTE_FINE = UTEN,ID_TRASF_FINE=IDTR WHERE TRKC_ID = SEROWIDATT;
  END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI

  IF INIZIO_VER_SUCC IS NULL THEN
    RETVAL := DATA_FINE;
  ELSE
    RETVAL := INIZIO_VER_SUCC - (1 / 24 / 60 / 60);
  END IF;
RETURN RETVAL;
END SCADI_TRKC;

END UPDATE_GIS_DATA;
/


