   )
      RETURN DATE
   IS
      CURSOR c1
      IS
         SELECT data_inizio_val, data_fine_val, se_row_id
           FROM sitiedi_piani
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND piano = pian
            AND edificio = edif
            AND data_inizio_val <= data_inizio
