      fog           IN   NUMBER,
      part          IN   VARCHAR2,
      subal         IN   VARCHAR2,
      uimm          IN   NUMBER,
      data_inizio   IN   DATE,
      data_fine     IN   DATE,
      uten          IN   VARCHAR2
   )
      RETURN DATE
   IS
      CURSOR c1
      IS
         SELECT data_inizio_val, data_fine_val, se_row_id
           FROM sitiedi_uiu_ext
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND unimm = uimm
            AND data_inizio_val <= data_inizio
            AND data_fine_val > data_inizio;

      CURSOR c2
      IS
         SELECT   data_inizio_val
             FROM sitiedi_uiu_ext
            WHERE cod_nazionale = codnaz
              AND foglio = fog
              AND particella = part
              AND sub = subal
              AND unimm = uimm
              AND data_inizio_val > data_inizio
         ORDER BY data_inizio_val;

      inizio_ver        DATE;
      fine_ver          DATE;
      serowidatt        NUMBER (9);
      inizio_ver_succ   DATE;
      retval            DATE;
                             -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE
   BEGIN
      OPEN c1;

      FETCH c1
       INTO inizio_ver, fine_ver, serowidatt;

      IF c1%NOTFOUND
      THEN
         serowidatt := NULL;
      END IF;

      CLOSE c1;

      IF inizio_ver = data_inizio
      THEN
         IF data_fine < fine_ver
         THEN
            raise_application_error (-20005, 'SCARTATO');
         END IF;

         raise_application_error (-20001, 'SCARTATO');
      END IF;

      inizio_ver_succ := NULL;

      IF fine_ver <> TO_DATE ('99991231', 'YYYYMMDD') OR fine_ver IS NULL
      THEN
         OPEN c2;

         FETCH c2
          INTO inizio_ver_succ;

         CLOSE c2;
      END IF;

      IF NOT (serowidatt IS NULL)
      THEN                              --FACCIO SCADERE LA VERSIONE CHE C'ERA
         UPDATE sitiedi_uiu_ext
            SET data_fine_val = data_inizio - (1 / 24 / 60 / 60),
                utente_fine = uten
          WHERE se_row_id = serowidatt;
      END IF;

      IF inizio_ver_succ IS NULL
      THEN
         retval := data_fine;
      ELSE
         retval := inizio_ver_succ - (1 / 24 / 60 / 60);
      END IF;

      RETURN retval;
   END;

   PROCEDURE scrivi_uiu_civi (
      codnaz        IN   VARCHAR2,
      fog           IN   NUMBER,
      part          IN   VARCHAR2,
      subal         IN   VARCHAR2,
      uimm          IN   NUMBER,
      data_inizio   IN   DATE,
      pkciv         IN   NUMBER,
      scal          IN   VARCHAR2,
      pian          IN   NUMBER,
      intern        IN   NUMBER,
      utent         IN   VARCHAR2
   )
   IS
      CURSOR c3
      IS
         SELECT pkid_uiu, data_inizio_val
           FROM sitiuiu
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND unimm = uimm
            AND data_lav = data_inizio;

      serowidatt   NUMBER;
      datainizio   DATE;
   BEGIN
      OPEN c3;

      FETCH c3
       INTO serowidatt, datainizio;

      IF c3%NOTFOUND
      THEN
         serowidatt := 0;
      END IF;

      CLOSE c3;

      IF serowidatt > 0
      THEN
         INSERT INTO siticivi_uiu
                     (pkid_civi, pkid_uiu, scala, piano, interno, utente,
                      data_inizio_val
                     )
              VALUES (pkciv, serowidatt, scal, pian, intern, utent,
                      datainizio
                     );
      END IF;
   END scrivi_uiu_civi;

   PROCEDURE scrivi_uiuimm (
      codnaz         IN   VARCHAR2,
      fog            IN   NUMBER,
      part           IN   VARCHAR2,
      subal          IN   VARCHAR2,
      uimm           IN   NUMBER,
      data_inizio    IN   DATE,
      mprog_imm      IN   NUMBER,
      mnomefile      IN   VARCHAR2,
      mdescrizione   IN   VARCHAR2
   )
   IS
      CURSOR c3
      IS
         SELECT pkid_uiu
           FROM sitiuiu
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND unimm = uimm
            AND data_lav = data_inizio;

      CURSOR c4
      IS
         SELECT TO_NUMBER (istatp)
           FROM siticomu
          WHERE cod_nazionale = codnaz;

      serowidatt   NUMBER;
      istatprov    NUMBER;
   BEGIN
      OPEN c3;

      FETCH c3
       INTO serowidatt;

      IF c3%NOTFOUND
      THEN
         serowidatt := 0;
      END IF;

      CLOSE c3;

      IF serowidatt > 0
      THEN
         OPEN c4;

         FETCH c4
          INTO istatprov;

         CLOSE c4;

         INSERT INTO sitiuiu_imm
                     (pkid_uiu, prog_imm, nomefile, descrizione,
                      istatp
                     )
              VALUES (serowidatt, mprog_imm, mnomefile, mdescrizione,
                      istatprov
                     );
      END IF;
   END scrivi_uiuimm;

   FUNCTION scadi_uiu (
      codnaz        IN   VARCHAR2,
      fog           IN   NUMBER,
      part          IN   VARCHAR2,
      subal         IN   VARCHAR2,
      uimm          IN   NUMBER,
      data_inizio   IN   DATE,
      data_fine     IN   DATE,
      uten          IN   VARCHAR2
   )
      RETURN DATE
   IS
      TYPE emptycur IS REF CURSOR;

      c1                emptycur;
      c2                emptycur;

      CURSOR c3
      IS
         SELECT pkid_uiu
           FROM sitiuiu
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND unimm = uimm
            AND data_inizio_val = data_inizio;

      esistegia         NUMBER;
      inizio_ver        DATE;
      fine_ver          DATE;
      serowidatt        NUMBER;
      inizio_ver_succ   DATE;
      retval            DATE;
                             -- DATA_FINE DA ASSEGNARE AL POLIGONO DA INSERIRE
   BEGIN
-- VEDO SE ESISTE UNA VERSIONE CORRENTE ALLA MIA DATA
-- VEDO SE ESITE UNA VERSIONE SUCCESSIVA ALLA MIA DATA
-- VEDO SE IL RECORD CHE STO INSERENDO ESISTE GIa
      OPEN c3;

      FETCH c3
       INTO esistegia;

      IF c3%NOTFOUND
      THEN
         esistegia := 0;
      END IF;

      CLOSE c3;

      IF esistegia > 0
      THEN
--  RETVAL:=To_Date('99990101000000','YYYYMMDDHH24MISS'); -- SIGNIFICA CHE ESISTE GIa
--  DELETE FROM SITIPART WHERE SE_ROW_ID=ESISTEGIA;
         raise_application_error (-20001, 'Scartato');
      END IF;

      OPEN c1 FOR
         SELECT data_inizio_val, data_fine_val, pkid_uiu
           FROM sitiuiu
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND unimm = uimm
            AND data_inizio_val < data_inizio
            AND data_fine_val > data_inizio;

      FETCH c1
       INTO inizio_ver, fine_ver, serowidatt;

      IF c1%NOTFOUND
      THEN
         serowidatt := NULL;
      END IF;

      CLOSE c1;

      OPEN c2 FOR
         SELECT   data_inizio_val
             FROM sitiuiu
            WHERE cod_nazionale = codnaz
              AND foglio = fog
              AND particella = part
              AND sub = subal
              AND unimm = uimm
              AND data_inizio_val > data_inizio
         ORDER BY data_inizio_val;

      FETCH c2
       INTO inizio_ver_succ;

      IF c2%NOTFOUND
      THEN
         inizio_ver_succ := NULL;
      END IF;

      CLOSE c2;

      IF NOT (serowidatt IS NULL)
      THEN                              --FACCIO SCADERE LA VERSIONE CHE C'ERA
         UPDATE sitiuiu
            SET data_fine_val = data_inizio - (1 / 24 / 60 / 60),
                utente_fine = uten
          WHERE pkid_uiu = serowidatt;

         UPDATE siticivi_uiu
            SET data_fine_val = data_inizio - (1 / 24 / 60 / 60),
                utente_fine = uten
          WHERE pkid_uiu = serowidatt;
      END IF;

--  IF INIZIO_VER_SUCC IS NULL OR DATA_FINE < INIZIO_VER_SUCC THEN  -- LASCIEREBBE DEI BUCHI
      IF inizio_ver_succ IS NULL
      THEN
         retval := data_fine;
      ELSE
         retval := inizio_ver_succ - (1 / 24 / 60 / 60);
      END IF;

      RETURN retval;
-- OKKIO NON FA LA COMMIT
   END scadi_uiu;

   FUNCTION get_atto_vano (
      codnaz        IN   VARCHAR2,
      fog           IN   NUMBER,
      part          IN   VARCHAR2,
      subal         IN   VARCHAR2,
      uimm          IN   NUMBER,
      pvano         IN   NUMBER,
      data_inizio   IN   DATE,
      data_fine     IN   DATE
   )
      RETURN NUMBER
   IS
      CURSOR c1
      IS
         SELECT id_atto
           FROM sitiedi_vani
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND unimm = uimm
            AND vano = pvano
            AND data_inizio_val <= data_inizio
            AND data_fine_val > data_inizio;

      m_id_atto   NUMBER;
   BEGIN
      OPEN c1;

      FETCH c1
       INTO m_id_atto;

      IF c1%NOTFOUND
      THEN
         m_id_atto := NULL;
      END IF;

      CLOSE c1;

      RETURN m_id_atto;
   END get_atto_vano;

