DROP FUNCTION DBTOTALE_H501.CALCOLASUPERFICETOTALE;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.calcolasuperficetotale (
   p_foglio       IN   VARCHAR2,
   p_particella   IN   VARCHAR2,
   p_sub          IN   VARCHAR2
)
   RETURN VARCHAR2
IS
   retval   VARCHAR2 (20);
BEGIN
   SELECT TO_CHAR (SUM (supe_ambiente) * 0.8)
     INTO retval
     FROM sitiedi_vani
    WHERE (ambiente = 'A' OR ambiente = 'B' OR ambiente = 'C')
      AND foglio = p_foglio
      AND particella = p_particella
      AND unimm = p_sub 
      AND DATA_FINE_VAL = TO_DATE('31-12-9999','DD-MM-YYYY');

   RETURN retval;
EXCEPTION
   WHEN OTHERS
   THEN
      RETURN NULL;
END calcolasuperficetotale;
/


