  --                                 16
   TYPE tabdeco_type IS RECORD (
      ind   VARCHAR2 (2),
      val   NUMBER
   );

   TYPE tabdeco IS TABLE OF tabdeco_type
      INDEX BY BINARY_INTEGER;

   TYPE tabchr IS TABLE OF VARCHAR2 (2)
      INDEX BY BINARY_INTEGER;

   blank   CONSTANT VARCHAR2 (1)   := ' ';                     -- spazio vuoto
