   tabb (33).ind := 'X';
   tabb (33).val := 25;
   tabb (34).ind := 'Y';
   tabb (34).val := 24;
   tabb (35).ind := 'Z';
   tabb (35).val := 23;
   -- tabella [C] - caratteri conversione carattere di controllo
   tabc (0) := 'A';
   tabc (1) := 'B';
   tabc (2) := 'C';
   tabc (3) := 'D';
   tabc (4) := 'E';
   tabc (5) := 'F';
   tabc (6) := 'G';
   tabc (7) := 'H';
   tabc (8) := 'I';
   tabc (9) := 'J';
   tabc (10) := 'K';
   tabc (11) := 'L';
   tabc (12) := 'M';
   tabc (13) := 'N';
   tabc (14) := 'O';
   tabc (15) := 'P';
   tabc (16) := 'Q';
   tabc (17) := 'R';
   tabc (18) := 'S';
   tabc (19) := 'T';
   tabc (20) := 'U';
   tabc (21) := 'V';
   tabc (22) := 'W';
   tabc (23) := 'X';
   tabc (24) := 'Y';
   tabc (25) := 'Z';
   -- tabella [D] - caratteri sostituzione in caso di codice fiscale doppio
   tabd (0) := 'L';
   tabd (1) := 'M';
   tabd (2) := 'N';
   tabd (3) := 'P';
   tabd (4) := 'Q';
   tabd (5) := 'R';
   tabd (6) := 'S';
   tabd (7) := 'T';
   tabd (8) := 'U';
   tabd (9) := 'V';
   -- CCC - (Cognome 3 lettere)
   sztmp := UPPER (REPLACE (p_cgn, blank));
   sztmp := UPPER (REPLACE (p_cgn, apo));

   IF (LENGTH (sztmp) >= 3)
   THEN
      sztmpcons := REPLACE (TRANSLATE (sztmp, voca, blank), blank);
      sztmpvoca := REPLACE (TRANSLATE (sztmp, cons, blank), blank);
      szccc := SUBSTR (sztmpcons || sztmpvoca, 1, 3);
   ELSE
      szccc := RPAD (sztmp, 3, 'X');
   END IF;

   -- NNN - (Nome 3 lettere)
   i := 0;
   sztmp := '';
   sztmpcons := '';
   sztmpvoca := '';
   sztmp := UPPER (REPLACE (p_nom, blank));

   IF (LENGTH (sztmp) >= 3)
   THEN
      sztmpcons := REPLACE (TRANSLATE (sztmp, voca, blank), blank);
      sztmpvoca := REPLACE (TRANSLATE (sztmp, cons, blank), blank);

      IF (LENGTH (sztmpcons) > 3)
      THEN
         sznnn :=
            SUBSTR (   SUBSTR (sztmpcons, 1, 1)
                    || SUBSTR (sztmpcons, 3, 1)
                    || SUBSTR (sztmpcons, 4, 1)
                    || sztmpvoca,
                    1,
                    3
                   );
      ELSE
         sznnn := SUBSTR (sztmpcons || sztmpvoca, 1, 3);
      END IF;
   ELSE
      sznnn := RPAD (sztmp, 3, 'X');
   END IF;

   -- AA
   szaa := TO_CHAR (p_data, 'YY');
   -- M
   szmm := SUBSTR (mesi, TO_NUMBER (TO_CHAR (p_data, 'mm')), 1);

   -- GG
   IF (p_sex = '1' OR p_sex = 'M')
   THEN
      szgg := TO_CHAR (p_data, 'dd');
   ELSIF (p_sex = '2' OR p_sex = 'F')
   THEN
      szgg := TO_CHAR (TO_NUMBER (TO_CHAR (p_data, 'dd')) + 40);
   END IF;

   -- L VVV
   BEGIN
      SELECT istatp || istatc belfiore
        INTO szlvvv
        FROM SITICOMU
       WHERE  istatp || istatc  = p_codi_istat;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RAISE;
      WHEN OTHERS
      THEN
         RAISE;
   END;

   -- K
   sztmp := szccc || sznnn || szaa || szmm || szgg || szlvvv;

   FOR i IN 1 .. LENGTH (sztmp)
   LOOP
      IF (MOD (i, 2) = 0)
      THEN
         --converto i caratteri pari
         FOR j IN 0 .. 35
         LOOP
            IF (taba (j).ind = SUBSTR (sztmp, i, 1))
            THEN
               nconv := nconv + taba (j).val;
            END IF;
         END LOOP;
      ELSE
         --converto i caratteri dispari
         FOR k IN 0 .. 35
         LOOP
            IF (tabb (k).ind = SUBSTR (sztmp, i, 1))
            THEN
               nconv := nconv + tabb (k).val;
            END IF;
         END LOOP;
      END IF;
   END LOOP;

   --calcolo il resto
   nconv := nconv - (TRUNC (nconv / 26, 0) * 26);
   --conversione sul resto
   szk := tabc (nconv);
-- CRAZIONE OUTPUT
--------------------

   --   Dbms_output.put_line (p_cgn);
   --   Dbms_output.put_line (szCCC);
   --   Dbms_output.put_line (p_nom);
   --   Dbms_output.put_line (nConv);
   --   szResult := szCCC || szNNN || szAA;
   DBMS_OUTPUT.put_line (szccc || sznnn || szaa || szmm || szgg || szlvvv
                         || szk
                        );
   RETURN szccc || sznnn || szaa || szmm || szgg || szlvvv || szk || a;
EXCEPTION
   WHEN NO_DATA_FOUND
   THEN
      NULL;
   WHEN OTHERS
   THEN
      -- Consider logging the error and then re-raise
      RAISE;
END cf_calcolo;
/


DROP FUNCTION DBTOTALE_H501.CF_CHK;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.cf_chk (b VARCHAR2 -- codice fiscale da controllare
                                             )
   RETURN VARCHAR2
IS                                                -- restituisce codice errore
   TYPE num_varr_t IS VARRAY (32767) OF NUMBER;

   -- tabella contributo delle posizioni dispari
   c_cf_chk   CONSTANT num_varr_t
      := num_varr_t (1,
                     0,
                     5,
                     7,
                     9,
                     13,
                     15,
                     17,
                     19,
                     21,
                     2,
                     4,
                     18,
                     20,
                     11,
                     3,
                     6,
                     8,
                     12,
                     14,
                     16,
                     10,
                     22,
                     25,
                     24,
                     23
                    );
   l                   PLS_INTEGER;                       -- lunghezza stringa
   c                   PLS_INTEGER;           -- codice del carattere corrente
   k                   PLS_INTEGER;               -- codice normalizzato 0..25
   kcin                PLS_INTEGER;        -- codice di controllo normalizzato
   s                   PLS_INTEGER := 0;                -- codice di controllo
BEGIN
   -- Controlla lunghezza
   l := LENGTH (b);

   IF b IS NULL
   THEN
      RETURN NULL;                                         -- argomento nullo
   ELSIF LENGTH (b) <> 16
   THEN
      RETURN '1';                                         -- lunghezza errata
   END IF;

   -- Ciclo tra i caratteri della stringa
   FOR i IN 1 .. l
   LOOP
      -- Estrae codice ASCII del prossimo carattere
      c := ASCII (SUBSTR (b, i, 1));

      -- Normalizza il codice al range 0..25
      IF c BETWEEN 48 AND 57
      THEN                                                     -- caso: cifra
         k := c - 48;
      ELSIF c BETWEEN 65 AND 90
      THEN                                        -- caso: carattere maiuscolo
         k := c - 65;
      ELSE                                              -- caso: altri simboli
         RETURN '2';                                    -- simbolo non valido
      END IF;

      -- Calcola somma di controllo
      IF i = l
      THEN
         kcin := k;
      ELSIF i MOD 2 = 0
      THEN
         s := s + k;
      ELSE
         s := s + c_cf_chk (k + 1);
      END IF;
   END LOOP;

   -- Controlla validità della somma di controllo
   IF s MOD 26 <> kcin
   THEN
      RETURN '9';                                        -- controllo fallito
   END IF;

   RETURN '0';                                                    -- codice OK
END cf_chk;
/


