DROP FUNCTION DBTOTALE_H501.DATEADD;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.DATEADD(Intvl IN VARCHAR2,NIntvl IN NUMBER,Dexpr IN DATE)
  RETURN DATE IS convDate DATE;
  BEGIN
    IF LOWER(RTRIM(Intvl))='y' or LOWER(RTRIM(Intvl))='w' or LOWER(RTRIM(Intvl))='d' Then
       convDate := Dexpr+NIntvl;
       return(convDate);
    ELSIF LOWER(RTRIM(Intvl)) = 'm' then
       convDate := ADD_MONTHS(Dexpr,NIntvl);
       return(convDate);
    ELSIF LOWER(RTRIM(Intvl)) = 'q' then
       convDate := ADD_MONTHS(Dexpr,3*NIntvl);
       return(convDate);
    ELSIF LOWER(RTRIM(Intvl)) = 'ww' then
       convDate := Dexpr + 7*NIntvl;
       return(convDate);
    ELSIF LOWER(RTRIM(Intvl)) = 'h' then
       convDate := Dexpr + NIntvl/24;
       return(convDate);
    ELSIF LOWER(RTRIM(Intvl)) = 'n' then
       convDate := Dexpr + NIntvl/1440;
       return(convDate);
    ELSIF LOWER(RTRIM(Intvl)) = 's' then
       convDate := Dexpr + NIntvl/86400;
       return(convDate);
    ELSIF LOWER(RTRIM(Intvl)) = 'yyyy' then
       If TRUNC(NIntvl) = NIntvl Then
          convDate := ADD_MONTHS(Dexpr,NIntvl*12);
          return(convDate);
       Else
          convDate := Dexpr + NIntvl*365;
          return(convDate);
       END IF;
    END IF;
  END;
/


DROP FUNCTION DBTOTALE_H501.DATECONV;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.DATECONV (
                            p_enteredtext   varchar2
                          ) RETURN DATE as
 type t_varchartable
    is table of varchar2(50)
   index by binary_integer;    -- table type definition

  v_dateformats t_varchartable; -- table of dateformats

  v_converted   date;           -- varchar date to date
  v_validdate   date;           -- validated date
  V_CONVERTED_TEMP VARCHAR2(10);

BEGIN

/* setup dateformats to check
   * can be expanded freely
   */
  v_dateformats(1) := 'YYYYMMDD';
  v_dateformats(2) := 'DD/MM/YYYY';

  v_validdate := null;

  for v_index in 1..v_dateformats.count loop

    begin

      v_converted := null; -- clear field of previous conversion
      V_CONVERTED_TEMP := p_enteredtext;
      IF v_dateformats(v_index) = v_dateformats(1) THEN
           IF SUBSTR(V_CONVERTED_TEMP,5,2) = '00' THEN
              V_CONVERTED_TEMP := SUBSTR(p_enteredtext,1,4) || '01' ||  SUBSTR(V_CONVERTED_TEMP,-2);
         END IF;
           IF SUBSTR(V_CONVERTED_TEMP,-2) = '00' THEN
              V_CONVERTED_TEMP := SUBSTR(V_CONVERTED_TEMP,1,6) || '01';
         END IF;
      END IF;
      IF v_dateformats(v_index) = v_dateformats(2) THEN
           IF SUBSTR(V_CONVERTED_TEMP,1,2) = '00' THEN
              V_CONVERTED_TEMP := '01' || SUBSTR(p_enteredtext,3,8);
         END IF;
           IF SUBSTR(V_CONVERTED_TEMP,4,2) = '00' THEN
              V_CONVERTED_TEMP := SUBSTR(V_CONVERTED_TEMP,1,3) || '01' || SUBSTR(V_CONVERTED_TEMP,6,5);
         END IF;
      END IF;
      
      /*
       * try to convert date using specific date format, on error
       * loop will continue without raising error
       */
      v_converted := to_date(
                              V_CONVERTED_TEMP
                              ,v_dateformats(v_index)
                            );
      exception
        when others then
        null; -- conversion failed, just continue
    end;

    if not v_converted is null  then             -- is date converted

      if nvl(v_validdate,v_converted) = v_converted then

        /* date is valid */
        v_validdate := v_converted;

      else

        /* a different second valid date has been found
         * routine should quit
         */
        return null;
      end if;

    end if;

  end loop;

  return v_validdate;


END;
/


