DROP FUNCTION DBTOTALE_H501.GET_NOTE_STO_RES_VIA;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.GET_NOTE_STO_RES_VIA (POSIZ_ANA_PARAM VARCHAR2, ID_ORIG_PERSONA_PARAM VARCHAR2, DESCRIZIONE_VIA_PARAM VARCHAR2, CIVICO_PARAM VARCHAR2) RETURN VARCHAR2 IS
NOTE VARCHAR2(100);

BEGIN   
    SELECT (
    CASE WHEN POSIZ_ANA_PARAM = 'D'
    OR (SELECT MAX(P.DATA_MOR) FROM SIT_D_PERSONA P
    WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
    AND P.DT_FINE_VAL IS NULL) IS NOT NULL
    THEN 'DECEDUTO'
    
    WHEN POSIZ_ANA_PARAM = 'E'
    OR ((SELECT MAX(P.DATA_EMI) FROM SIT_D_PERSONA P
        WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
        AND P.DT_FINE_VAL IS NULL) IS NOT NULL
        AND ((SELECT MAX(P.DATA_IMM) FROM SIT_D_PERSONA P
            WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
            AND P.DT_FINE_VAL IS NULL) IS NULL
            OR (SELECT MAX(P.DATA_IMM) FROM SIT_D_PERSONA P
            WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
            AND P.DT_FINE_VAL IS NULL) <
            (SELECT MAX(P.DATA_EMI) FROM SIT_D_PERSONA P
            WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
            AND P.DT_FINE_VAL IS NULL)
        )
    )
    THEN
        CASE WHEN
        (SELECT TO_CHAR(MAX(
        NVL(NVL(PC1.DT_FINE_VAL, PC1.DT_FINE_DATO), 
        (SELECT MAX(P.DATA_EMI) FROM SIT_D_PERSONA P
        WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
        AND P.DT_FINE_VAL IS NULL)
        )), 'DD/MM/YYYY')
        FROM SIT_D_PERSONA_CIVICO PC1
        WHERE PC1.ID_EXT_D_PERSONA = (
        SELECT DISTINCT PC2.ID_EXT FROM SIT_D_PERSONA PC2
        WHERE PC2.ID_ORIG = ID_ORIG_PERSONA_PARAM
        )
        ) IS NULL
        THEN NULL
        ELSE

        'FINO AL ' ||
        (SELECT TO_CHAR(MAX(
        NVL(NVL(PC1.DT_FINE_VAL, PC1.DT_FINE_DATO), 
        (SELECT MAX(P.DATA_EMI) FROM SIT_D_PERSONA P
        WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
        AND P.DT_FINE_VAL IS NULL)
        )), 'DD/MM/YYYY')
        FROM SIT_D_PERSONA_CIVICO PC1
        WHERE PC1.ID_EXT_D_PERSONA = (
        SELECT DISTINCT PC2.ID_EXT FROM SIT_D_PERSONA PC2
        WHERE PC2.ID_ORIG = ID_ORIG_PERSONA_PARAM
        )
        )
        END
    WHEN POSIZ_ANA_PARAM = 'A'
    OR ((SELECT MAX(P.DATA_EMI) FROM SIT_D_PERSONA P
        WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
        AND P.DT_FINE_VAL IS NULL) IS NULL
        OR ((SELECT MAX(P.DATA_IMM) FROM SIT_D_PERSONA P
            WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
            AND P.DT_FINE_VAL IS NULL) IS NOT NULL
            AND (SELECT MAX(P.DATA_IMM) FROM SIT_D_PERSONA P
            WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
            AND P.DT_FINE_VAL IS NULL) >=
            (SELECT MAX(P.DATA_EMI) FROM SIT_D_PERSONA P
            WHERE P.ID_ORIG = ID_ORIG_PERSONA_PARAM
            AND P.DT_FINE_VAL IS NULL)
        )
    )
    THEN        
        (SELECT NOTE FROM (
            WITH TW AS (SELECT
                ID_EXT_D_PERSONA,
                ID_ORIG_VIA,
                DESCRIZIONE_VIA,
                CIVICO,
                DT_INIZIO_VAL,
                DT_FINE_VAL,
                DT_INIZIO_DATO
                FROM (
                SELECT
                CV.ID_ORIG_VIA,
                DECODE(CV.VIASEDIME, NULL, '', '', '', CV.VIASEDIME || ' ') || CV.DESCRIZIONE AS DESCRIZIONE_VIA,

                CASE
                             WHEN     TRIM (LEADING 0 FROM CV.CIV_LIV1) IS NOT NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV2) IS NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV3) IS NULL
                             THEN
                                TRIM (LEADING 0 FROM CV.CIV_LIV1)
                             WHEN     TRIM (LEADING 0 FROM CV.CIV_LIV1) IS NOT NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV2) IS NOT NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV3) IS NULL
                             THEN
                                   TRIM (LEADING 0 FROM CV.CIV_LIV1)
                                || '/'
                                || TRIM (LEADING 0 FROM CV.CIV_LIV2)
                             WHEN     TRIM (LEADING 0 FROM CV.CIV_LIV1) IS NOT NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV2) IS NOT NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV3) IS NOT NULL
                             THEN
                                   TRIM (LEADING 0 FROM CV.CIV_LIV1)
                                || '/'
                                || TRIM (LEADING 0 FROM CV.CIV_LIV2)
                                || '/'
                                || TRIM (LEADING 0 FROM CV.CIV_LIV3)
                             WHEN     TRIM (LEADING 0 FROM CV.CIV_LIV1) IS NOT NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV2) IS NULL
                                  AND TRIM (LEADING 0 FROM CV.CIV_LIV3) IS NOT NULL
                             THEN
                                   TRIM (LEADING 0 FROM CV.CIV_LIV1)
                                || '/'
                                || TRIM (LEADING 0 FROM CV.CIV_LIV3)
                          END
                             CIVICO,
                PC.*
                FROM SIT_D_PERSONA_CIVICO PC, SIT_D_CIVICO_VIA_V CV
                WHERE CV.ID_EXT = PC.ID_EXT_D_CIVICO
                AND PC.ID_EXT_D_PERSONA = (SELECT DISTINCT PTW.ID_EXT
                                    FROM SIT_D_PERSONA PTW
                                    WHERE PTW.ID_ORIG = ID_ORIG_PERSONA_PARAM
                                    )                      
                ))
                SELECT DISTINCT
                CASE WHEN NVL(TRUNC(TW.DT_INIZIO_DATO), TRUNC(TW.DT_INIZIO_VAL)) = NULL
                THEN NULL
                ELSE 'FINO AL ' || TO_CHAR(NVL(TRUNC(TW.DT_INIZIO_DATO), TRUNC(TW.DT_INIZIO_VAL)), 'DD/MM/YYYY')
                END NOTE
                FROM TW          
                WHERE (TW.DESCRIZIONE_VIA <> DESCRIZIONE_VIA_PARAM OR TW.CIVICO <> CIVICO_PARAM)
				AND TW.DT_INIZIO_VAL = (SELECT MIN(TW.DT_INIZIO_VAL)
                                FROM TW
                                WHERE (TW.DESCRIZIONE_VIA <> DESCRIZIONE_VIA_PARAM OR TW.CIVICO <> CIVICO_PARAM)
                                AND TW.DT_INIZIO_VAL >= (SELECT MAX(TW.DT_FINE_VAL)
                                                    FROM TW
                                                    WHERE TW.DESCRIZIONE_VIA = DESCRIZIONE_VIA_PARAM
                                                    AND TW.CIVICO = CIVICO_PARAM
                                                    )
                                )            
                )
        )
        ELSE NULL
    END) INTO NOTE FROM DUAL;
    
    RETURN NOTE;
     
END GET_NOTE_STO_RES_VIA;
/


