DROP FUNCTION DBTOTALE_H501.INGOMBRO_ANAGRAFE;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.INGOMBRO_ANAGRAFE(CN IN VARCHAR2, MY_PK_CODI_ANAGRAFE IN VARCHAR2) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;

    OPEN C FOR SELECT  SDO_GEOM.SDO_MBR(SHAPE) FROM persona_civici_shape_v where CODENT = CN AND PK_ANAGRAFE=MY_PK_CODI_ANAGRAFE;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;


  RETURN RETSHP;
END INGOMBRO_ANAGRAFE;
/


DROP FUNCTION DBTOTALE_H501.INGOMBRO_CIVICI;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.INGOMBRO_CIVICI(MY_CN IN VARCHAR2, MY_PKID_CIVI IN NUMBER,DATAV IN DATE) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;
  DATAVAL DATE;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;
  DATAVAL:=DATAV;
  IF DATAVAL IS NULL THEN DATAVAL:=To_Date('99991231000000','YYYYMMDDHH24MISS'); END IF;

    OPEN C FOR SELECT  SDO_GEOM.SDO_MBR(SHAPE) FROM SITICIVI where COD_NAZIONALE = MY_CN AND PKID_CIVI=MY_PKID_CIVI AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;




  RETURN RETSHP;
END INGOMBRO_CIVICI;
/


DROP FUNCTION DBTOTALE_H501.INGOMBRO_PARTICELLA;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.INGOMBRO_PARTICELLA(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  SUBO VARCHAR2(3);
  DATAVAL DATE;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;
  DATAVAL:=DATAV;

  IF DATAVAL IS NULL THEN DATAVAL:=To_Date('99991231000000','YYYYMMDDHH24MISS'); END IF;

  IF PART IS NOT NULL THEN

      
    OPEN C FOR SELECT /*+ INDEX (SITIPART SITIPART_PK) */ SDO_GEOM.SDO_MBR(SHAPE) FROM SITIPART WHERE COD_NAZIONALE=CN AND LPAD(TRIM(FOGLIO),6,'0')=LPAD(TRIM(FOG),6,'0')AND LPAD(TRIM(PARTICELLA),5,'0')=LPAD(TRIM(PART),5,'0') AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;

    IF RETSHP IS NULL THEN
      OPEN C FOR SELECT /*+ INDEX (SITICENT SITICENT_PK) */ SDO_GEOM.SDO_MBR(SHAPE) FROM SITICENT WHERE COD_NAZIONALE=CN AND LPAD(TRIM(FOGLIO),6,'0')=LPAD(TRIM(FOG),6,'0') AND LPAD(TRIM(PARTICELLA),5,'0')=LPAD(TRIM(PART),5,'0') AND SUB=SUBO AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=null; END IF;
      CLOSE C;

      IF RETSHP IS NOT NULL THEN
        RETSHP:=SDO_GEOM.SDO_BUFFER(RETSHP,100,0.1);
      END IF;
    END IF;
  END IF;

  IF FOG IS NOT NULL AND RETSHP IS NULL THEN
    OPEN C FOR SELECT SDO_AGGR_UNION(mdsys.sdoaggrtype(sdo_geom.sdo_mbr(SHAPE),0.5)) FROM SITIFGLC WHERE COD_NAZIONALE=CN AND LPAD(TRIM(FOGLIO),6,'0')=LPAD(TRIM(FOG),6,'0');
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;
  END IF;

  IF CN IS NOT NULL AND RETSHP IS NULL THEN
      OPEN C FOR SELECT SDO_AGGR_MBR(SHAPE)
      FROM SITICOML
      WHERE (ISTATP,ISTATC) IN (SELECT ISTATP,ISTATC FROM SITICOMU WHERE COD_NAZIONALE=CN);
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=null; END IF;
      CLOSE C;
  END IF;

  RETURN RETSHP;
END INGOMBRO_PARTICELLA;
/


DROP FUNCTION DBTOTALE_H501.INTDIV;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.intdiv( a NUMBER, b NUMBER) RETURN NUMBER IS OUT NUMBER;
  BEGIN
     IF (a IS NULL) OR (b IS NULL) THEN
        RETURN NULL;
     ELSE
        out := trunc( round(a) / round(b) );
        RETURN out;
     END IF;
  END;
/


DROP FUNCTION DBTOTALE_H501.INTN;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.INTN(expn IN NUMBER) RETURN NUMBER IS convNum NUMBER;
  BEGIN
      If expn >= 0 THEN
         convNum := TRUNC( expn );
      ELSE
         convNum := FLOOR( expn );
      END IF;
      RETURN( convNum );
  END;
/


DROP FUNCTION DBTOTALE_H501.ISN;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.isn( a IN NUMBER, b IN VARCHAR2 ) RETURN NUMBER AS out NUMBER;
  BEGIN
     IF ( LOWER(b) = LOWER('NULL') ) THEN
        IF ( a IS NULL ) THEN
           RETURN -1;
        ELSE
           RETURN 0;
        END IF;
     ELSE
        IF ( a IS NOT NULL ) THEN
           RETURN -1;
        ELSE
           RETURN 0;
        END IF;
     END IF;
  END;
/


