  END;
/


DROP FUNCTION DBTOTALE_H501.RND;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.rnd
   RETURN NUMBER AS
     m  CONSTANT NUMBER:=100000000;
     m1 CONSTANT NUMBER:=10000;
     b  CONSTANT NUMBER:=31415821;
     a           NUMBER;
     the_date    DATE;
     days        NUMBER;
     secs        NUMBER;
     iMul        NUMBER;
     p1          NUMBER;
     p0          NUMBER;
     q1          NUMBER;
     q0          NUMBER;
  BEGIN
     the_date := SYSDATE;
     days     := TO_NUMBER( to_char( the_date, 'J'    ) );
     secs     := TO_NUMBER( to_char( the_date, 'SSSSS') );
     a        := days * 24 * 3600 + secs;
     p1       := TRUNC( a / m1 );
     p0       := MOD  ( a,  m1 );
     q1       := TRUNC( b / m1 );
     q0       := MOD  ( b,  m1 );
     iMul     :=( MOD( ( MOD( p0*q1+p1*q0,m1 ) *m1+p0*q0 ), m ) );
     a        :=MOD( iMul+1, m );
     RETURN( a/m );
  END;
/


