DROP FUNCTION DBTOTALE_H501.TRIM_BARRA_LETTERE;

CREATE OR REPLACE FUNCTION DBTOTALE_H501.TRIM_BARRA_LETTERE( A VARCHAR2) RETURN VARCHAR2 AS
BEGIN
  DECLARE
    RET VARCHAR2(32767);
    POS NUMBER;
  BEGIN
    SELECT decode(instr(A,'/'),0,32767, instr(A,'/')) INTO POS FROM DUAL;
    -- TOLGO LA BARRA DALLA STRINGA
    RET:= substr(A,1,POS-1);
    -- TOLGO LE LETTERE
    RET:=REPLACE(RET,'A','');
    RET:=REPLACE(RET,'B','');
    RET:=REPLACE(RET,'C','');
    RET:=REPLACE(RET,'D','');
    RET:=REPLACE(RET,'E','');
    RET:=REPLACE(RET,'F','');
    RET:=REPLACE(RET,'G','');
    RET:=REPLACE(RET,'H','');
    RET:=REPLACE(RET,'I','');
    RET:=REPLACE(RET,'L','');
    RET:=REPLACE(RET,'M','');
    RET:=REPLACE(RET,'N','');
    RET:=REPLACE(RET,'O','');
    RET:=REPLACE(RET,'P','');
    RET:=REPLACE(RET,'Q','');
    RET:=REPLACE(RET,'R','');
    RET:=REPLACE(RET,'S','');
    RET:=REPLACE(RET,'T','');
    RET:=REPLACE(RET,'U','');
    RET:=REPLACE(RET,'V','');
    RET:=REPLACE(RET,'Z','');
    RET:=REPLACE(RET,'X','');
    RET:=REPLACE(RET,'W','');
    RET:=REPLACE(RET,'J','');
    RETURN RET;
  END;
END;
/

