DROP FUNCTION DIOGENE_H501.DATECONV;

CREATE OR REPLACE function DIOGENE_H501.DATECONV(p_enteredtext   varchar2)
RETURN DATE as
 type t_varchartable
    is table of varchar2(50)
   index by binary_integer;    -- table type definition

  v_dateformats t_varchartable; -- table of dateformats

  v_converted   date;           -- varchar date to date
  v_validdate   date;           -- validated date
  V_CONVERTED_TEMP VARCHAR2(10);

BEGIN

/* setup dateformats to check
   * can be expanded freely
   */
  v_dateformats(1) := 'YYYYMMDD';

  v_validdate := null;

  for v_index in 1..v_dateformats.count loop

    begin

      v_converted := null; -- clear field of previous conversion
   V_CONVERTED_TEMP := p_enteredtext;
      IF v_dateformats(v_index) = v_dateformats(1) THEN
     IF SUBSTR(V_CONVERTED_TEMP,5,2) = '00' THEN
        V_CONVERTED_TEMP := SUBSTR(p_enteredtext,1,4) || '01' ||  SUBSTR(V_CONVERTED_TEMP,-2);
   END IF;
     IF SUBSTR(V_CONVERTED_TEMP,-2) = '00' THEN
        V_CONVERTED_TEMP := SUBSTR(V_CONVERTED_TEMP,1,6) || '01';
   END IF;
   END IF;

      /*
       * try to convert date using specific date format, on error
       * loop will continue without raising error
       */
      v_converted := to_date(
                              V_CONVERTED_TEMP
                              ,v_dateformats(v_index)
                            );
      exception
        when others then
        null; -- conversion failed, just continue
    end;

    if not v_converted is null  then             -- is date converted

      if nvl(v_validdate,v_converted) = v_converted then

        /* date is valid */
        v_validdate := v_converted;

      else

        /* a different second valid date has been found
         * routine should quit
         */
        return null;
      end if;

    end if;

  end loop;

  return v_validdate;


END;
/


DROP FUNCTION DIOGENE_H501.GET_CIV_LIV1;

CREATE OR REPLACE FUNCTION DIOGENE_H501.get_CIV_liv1 (CIVICO VARCHAR2 , charsep varchar2)
   RETURN VARCHAR2
IS
   str  VARCHAR2 (1000);
   pos number;
BEGIN
    pos := instr(CIVICO,charsep,1);
    if pos > 0 then
       RETURN LPAD(SUBSTR(CIVICO,1,POS-1),3,'0'); 
    ELSE
       RETURN  LPAD(CIVICO,3,'0');    
    end if;           
EXCEPTION
   WHEN OTHERS
   THEN
      RETURN NULL;
END;
/


DROP FUNCTION DIOGENE_H501.GET_DATE_RIFERIMENTO;

CREATE OR REPLACE FUNCTION DIOGENE_H501.GET_DATE_RIFERIMENTO(MY_BELFIORE VARCHAR2, MY_ID_FONTE INTEGER)
   RETURN VARCHAR2
IS
   CONTA NUMBER;
   RETVAL VARCHAR2(26);
BEGIN
    SELECT COUNT(1) INTO CONTA
    FROM R_TRACCIA_DATE
    WHERE BELFIORE = MY_BELFIORE AND ID_FONTE = MY_ID_FONTE;

    IF CONTA = 1 THEN
        SELECT 'Da '
        || NVL(TO_CHAR(DATAMIN, 'DD/MM/YYYY'), '-')
        || ' a '
        || NVL(TO_CHAR(DATAMAX, 'DD/MM/YYYY'), '-')
        INTO RETVAL
        FROM R_TRACCIA_DATE
        WHERE BELFIORE = MY_BELFIORE AND ID_FONTE = MY_ID_FONTE;
    ELSE
        RETVAL := '-';

        IF MY_ID_FONTE = 1 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select data_ini, data_agg from (
                select sel.*, rownum as n from (
                select max(data_ini) as data_ini, max(data_agg) as data_agg, max(ascot) as ascot from (
                select null as data_ini, max(DT_INIZIO_VAL) as data_agg, 0 as ascot
                from SIT_D_PERSONA
                where DT_INIZIO_VAL is not null
                union all
                select nvl(min(P.DATA_INIZIO_RESIDENZA), min(C.DT_INIZIO_DATO)) as data_ini, null as data_agg, 0 as ascot
                from SIT_D_PERSONA P, SIT_D_PERSONA_CIVICO C
                where P.ID_EXT= C.ID_EXT_D_PERSONA)
                union all
                select max(data_ini) as data_ini, max(data_agg) as data_agg, max(ascot) as ascot from (
                select null as data_ini, max(trunc(DT_START)) as data_agg,
                case WHEN (min(trunc(DT_START)) is null) THEN -1 else 1 end as ascot
                from C_EXEC_PROCESSO
                where FK_COD_LISTA= 'REP_DEMOG_ASCOT'
                and STATO= 'Concluso'
                and ESITO= 'Positivo'
                and substr(FK_EXEC_LISTAP, 0, 4) = (select CODENT from SIT_ENTE)
                union all
                select nvl(min(P.DATA_INIZIO_RESIDENZA), min(C.DT_INIZIO_DATO)) as data_ini, null as data_agg, -1 as ascot
                from SIT_D_PERSONA P, SIT_D_PERSONA_CIVICO C
                where P.ID_EXT= C.ID_EXT_D_PERSONA)
                order by ascot desc) sel)
                where n = 1
            );
        END IF;

        IF MY_ID_FONTE = 2 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                SELECT TO_DATE (DECODE ('0101' || (yea_min),'0101', NULL,'0101' || (yea_min)),'ddmmyyyy')as data_ini, TO_DATE (DECODE ('3112' || (yea_max),'3112', NULL,'3112' || (yea_max)),'ddmmyyyy')as data_agg FROM (select min(yea_den)yea_min, max(yea_den) yea_max from sit_t_ici_oggetto WHERE yea_den IS NOT NULL AND yea_den != '0')
            );
        END IF;

        IF MY_ID_FONTE = 3 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select data_ini, data_agg from(SELECT MAX(PROTOCOLLO_DATA) as data_agg FROM SIT_C_CONCESSIONI WHERE PROTOCOLLO_DATA < SYSDATE),(SELECT MIN(PROTOCOLLO_DATA) as data_ini FROM SIT_C_CONCESSIONI WHERE PROTOCOLLO_DATA > TO_DATE('01011000','DDMMYYYY'))
            );
        END IF;

        IF MY_ID_FONTE = 4 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                SELECT Min(To_Date(p_min.dt_rif,'DD/MM/YYYY')) AS data_ini,Max(To_Date(p_max.dt_rif,'DD/MM/YYYY')) AS data_agg FROM load_cat_prm_incr p_min, load_cat_prm_incr p_max WHERE p_min.dt_carico = (select min(dt_carico) from load_cat_prm_incr) AND p_max.dt_carico = (select max(dt_carico) from load_cat_prm_incr)
            );
        END IF;

        IF MY_ID_FONTE = 5 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                SELECT TO_DATE(DECODE ('0101' || anno_min,'0101', NULL,'0101' || anno_min),'ddmmyyyy') as data_ini, TO_DATE(DECODE ('3112' || anno_max,'3112', NULL,'3112' || anno_max),'ddmmyyyy') as data_agg FROM (select max(anno) anno_max, min(anno) anno_min from LOCAZIONI_A WHERE anno IS NOT NULL )
            );
        END IF;

        IF MY_ID_FONTE = 6 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select min(UTIL.fchar_to_date(data_apertura,'YYYY-MM-DD')) as data_ini, max(UTIL.fchar_to_date(data_apertura,'YYYY-MM-DD')) as data_agg from successioni_a
            );
        END IF;

        IF MY_ID_FONTE = 7 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select min(to_date(data_iniziale,'ddmmyyyy')) as data_ini,max(to_date(data_finale,'ddmmyyyy')) as data_agg from MUI_fornitura
            );
        END IF;

        IF MY_ID_FONTE = 9 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select min(fornitura) as data_ini,last_day(max(fornitura)) as data_agg from docfa_dati_generali
            );
        END IF;

        IF MY_ID_FONTE = 10 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                SELECT TO_DATE (DECODE ('0101' || (anno_riferimento_dati_min),'0101', NULL,'0101' || (anno_riferimento_dati_min)),'ddmmyyyy')  AS data_ini,TO_DATE (DECODE ('3112' || (anno_riferimento_dati_max),'3112', NULL,'3112' || (anno_riferimento_dati_max)),'ddmmyyyy')  AS data_agg FROM (SELECT MIN(anno_riferimento_dati) anno_riferimento_dati_min FROM SIT_ENEL_UTENZA),(SELECT MAX(anno_riferimento_dati) anno_riferimento_dati_max FROM SIT_ENEL_UTENZA)
            );
        END IF;

        IF MY_ID_FONTE = 11 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                SELECT TO_DATE (DECODE ('0101' ||  (anno_imposta_min),'0101', NULL,'0101' ||  (anno_imposta_min)),'ddmmyyyy')AS data_ini,TO_DATE (DECODE ('3112' ||  (anno_imposta_max),'3112', NULL,'3112' ||  (anno_imposta_max)),'ddmmyyyy')AS data_agg FROM (SELECT MIN (anno_imposta) ANNO_IMPOSTA_min FROM red_dati_anagrafici ),(SELECT max (anno_imposta) ANNO_IMPOSTA_max FROM red_dati_anagrafici )
            );
        END IF;

        IF MY_ID_FONTE = 12 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                SELECT TO_DATE (DECODE ('0101' ||  (anno_riferimento_min),'0101', NULL,'0101' ||  (anno_riferimento_min)),'ddmmyyyy') AS data_ini,TO_DATE (DECODE ('3112' ||  (anno_riferimento_max),'3112', NULL,'3112' ||  (anno_riferimento_max)),'ddmmyyyy') AS data_agg from (  select min(anno_riferimento) anno_riferimento_min FROM sit_u_gas ),(  select max(anno_riferimento) anno_riferimento_max FROM sit_u_gas )
            );
        END IF;

        IF MY_ID_FONTE = 13 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select data_ini, data_agg from(SELECT MAX(DATA_RILASCIO) as data_agg FROM SIT_LICENZE_COMMERCIO WHERE DATA_RILASCIO < SYSDATE),(SELECT MIN(DATA_RILASCIO) as data_ini FROM SIT_LICENZE_COMMERCIO WHERE DATA_RILASCIO > TO_DATE('01011000','DDMMYYYY'))
            );
        END IF;

        IF MY_ID_FONTE = 14 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select data_ini, data_agg from(SELECT MAX(DT_INI_VALIDITA) as data_agg  FROM SIT_T_COSAP_TASSA  WHERE DT_INI_VALIDITA < SYSDATE),(SELECT MIN(DT_INI_VALIDITA) as data_ini FROM SIT_T_COSAP_TASSA WHERE DT_INI_VALIDITA > TO_DATE('01011000','DDMMYYYY'))
            );
        END IF;

        IF MY_ID_FONTE = 17 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select UTIL.FCHAR_TO_DATE(min(data_multa),'YYYYMMDD')  as data_ini, UTIL.FCHAR_TO_DATE(MAX(data_multa),'YYYYMMDD')   as data_agg from sit_TRFF_MULTE
            );
        END IF;

        IF MY_ID_FONTE = 18 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select min(data_bolletta)  as data_ini, max(data_bolletta)  as data_agg from sit_rtt_bollette
            );
        END IF;

        IF MY_ID_FONTE = 24 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select TO_DATE(min(data_fornitura)) as data_ini, TO_DATE(max(data_fornitura)) as data_agg from PREGEO_FORNITURE
            );
        END IF;

        IF MY_ID_FONTE = 27 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select min(dt_inizio) as data_ini, max(dt_inizio) as data_agg from sit_pub_prat_testata WHERE dt_inizio < SYSDATE
            );
        END IF;

        IF MY_ID_FONTE = 33 THEN
            SELECT 'Da '
            || NVL(TO_CHAR(DATA_INI, 'DD/MM/YYYY'), '-')
            || ' a '
            || NVL(TO_CHAR(DATA_AGG, 'DD/MM/YYYY'), '-')
            INTO RETVAL
            FROM (
                select min(dt_fornitura) as data_ini, max(dt_fornitura) as data_agg from sit_t_f24_testata
            );
        END IF;

    END IF;

    RETURN RETVAL;
EXCEPTION
   WHEN OTHERS
   THEN
      RETURN NULL;
END;
/


DROP FUNCTION DIOGENE_H501.GET_ELENCO_UIU_GRAFFATE;

CREATE OR REPLACE FUNCTION DIOGENE_H501.GET_ELENCO_UIU_GRAFFATE (COD_NAZIONALE_PARAM VARCHAR2, FOGLIO_PARAM VARCHAR2, MAPPALE_PARAM VARCHAR2, SUB_PARAM VARCHAR2, STR_SEPAR VARCHAR2)
   RETURN VARCHAR2
IS
    UIU_GRAFFATE VARCHAR2 (4000);
BEGIN
    SELECT UTL_I18N.UNESCAPE_REFERENCE('' || XMLAGG(XMLELEMENT(E, CASE WHEN LTRIM(RTRIM(SEZ)) IS NULL THEN NULL ELSE SEZ || ' - ' END 
    || LTRIM(FOGLIO, '0') || ' - ' || LTRIM(MAPPALE, '0') || ' - ' || LTRIM(SUB, '0') || STR_SEPAR) ORDER BY SEZ, FOGLIO, MAPPALE, SUB).EXTRACT('//text()'))
    INTO UIU_GRAFFATE FROM (
    SELECT DISTINCT SEZ, FOGLIO, MAPPALE, SUB
    FROM LOAD_CAT_UIU_ID LC, SITICOMU C 
    WHERE LC.SEZ = C.SEZIONE_CENSUARIA AND C.CODI_FISC_LUNA = LC.CODI_FISC_LUNA 
    AND GRAFFATO = 'Y' 
    AND ID_IMM IN ( 
    SELECT ID_IMM 
    FROM LOAD_CAT_UIU_ID LC, SITICOMU C 
    WHERE LC.SEZ = C.SEZIONE_CENSUARIA AND C.CODI_FISC_LUNA = LC.CODI_FISC_LUNA 
    AND C.COD_NAZIONALE = COD_NAZIONALE_PARAM
    AND LPAD(LC.FOGLIO, 4, '0') = LPAD(FOGLIO_PARAM, 4, '0')
    AND LPAD(LC.MAPPALE, 5, '0') = LPAD(MAPPALE_PARAM, 5, '0')
    AND LPAD(LC.SUB, 4, '0') = LPAD(SUB_PARAM, 4, '0')
    AND GRAFFATO = 'N')
    );
    
    IF UIU_GRAFFATE IS NOT NULL THEN
        UIU_GRAFFATE := SUBSTR(UIU_GRAFFATE, 1, LENGTH(UIU_GRAFFATE) - LENGTH(STR_SEPAR));
    END IF;
    
    RETURN UIU_GRAFFATE;           
EXCEPTION
   WHEN OTHERS
   THEN
      RETURN NULL;
END;
/


DROP FUNCTION DIOGENE_H501.INGOMBRO_ANAGRAFE;

CREATE OR REPLACE FUNCTION DIOGENE_H501.INGOMBRO_ANAGRAFE(CN IN VARCHAR2, MY_PK_CODI_ANAGRAFE IN VARCHAR2) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;

    OPEN C FOR SELECT  SDO_GEOM.SDO_MBR(SHAPE) FROM persona_civici_shape_v where CODENT = CN AND PK_ANAGRAFE=MY_PK_CODI_ANAGRAFE AND ROWNUM=1;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;


  RETURN RETSHP;
END INGOMBRO_ANAGRAFE;
/


DROP FUNCTION DIOGENE_H501.INGOMBRO_CIVICI;

CREATE OR REPLACE FUNCTION DIOGENE_H501.INGOMBRO_CIVICI(MY_CN IN VARCHAR2, MY_PKID_CIVI IN NUMBER,DATAV IN DATE) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;
  DATAVAL DATE;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;
  DATAVAL:=DATAV;
  IF DATAVAL IS NULL THEN DATAVAL:=To_Date('99991231000000','YYYYMMDDHH24MISS'); END IF;

    OPEN C FOR SELECT  SDO_GEOM.SDO_MBR(SHAPE) FROM SITICIVI where COD_NAZIONALE = MY_CN AND PKID_CIVI=MY_PKID_CIVI AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;




  RETURN RETSHP;
END INGOMBRO_CIVICI;
/


DROP FUNCTION DIOGENE_H501.INGOMBRO_PARTICELLA;

CREATE OR REPLACE function DIOGENE_H501.INGOMBRO_PARTICELLA(cn      IN   VARCHAR2,
   fog     IN   NUMBER,
   part    IN   VARCHAR2,
   suba    IN   VARCHAR2,
   datav   IN   DATE)
RETURN MDSYS.SDO_GEOMETRY
IS
   TYPE emptycur IS REF CURSOR;

   c         emptycur;
   subo      VARCHAR2 (3);
   dataval   DATE;
   retshp    MDSYS.SDO_GEOMETRY;
BEGIN
   retshp := NULL;
   dataval := datav;

   IF dataval IS NULL
   THEN
      dataval := TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');
   END IF;

   IF part IS NOT NULL
   THEN
      OPEN c FOR
         SELECT /*+ INDEX (SITIPART SITIPART_PK) */
                sdo_geom.sdo_mbr (shape)
           FROM sitipart
          WHERE cod_nazionale = cn
            AND LPAD (TRIM (foglio), 6, '0') = LPAD (TRIM (fog), 6, '0')
            AND LPAD (TRIM (particella), 5, '0') = LPAD (TRIM (part), 5, '0')
            AND sub=nvl(DECODE(suba,' ', null,suba), ' ')
            AND data_inizio_val <= dataval
            AND data_fine_val >= dataval
            AND ROWNUM = 1;

      FETCH c
       INTO retshp;

          IF c%NOTFOUND THEN
      
            DECLARE
            d         emptycur;
            
            begin
          
              OPEN d FOR
                 SELECT /*+ INDEX (SITIPART SITIPART_PK) */
                        sdo_geom.sdo_mbr (shape)
                   FROM sitipart
                  WHERE cod_nazionale = cn
                    AND LPAD (TRIM (foglio), 6, '0') = LPAD (TRIM (fog), 6, '0')
                    AND LPAD (TRIM (particella), 5, '0') = LPAD (TRIM (part), 5, '0')
                    AND data_inizio_val <= dataval
                    AND data_fine_val >= dataval
                    AND ROWNUM = 1;
                    
               FETCH d
               INTO retshp;

                  IF d%NOTFOUND  THEN    
                        retshp := NULL;
                 END IF;
                CLOSE d;
         
          end;
      
      END IF;
      
      

      CLOSE c;
   END IF;

   IF fog IS NOT NULL AND retshp IS NULL
   THEN
      OPEN c FOR
         SELECT sdo_aggr_union (MDSYS.sdoaggrtype (sdo_geom.sdo_mbr (shape),
                                                   0.5
                                                  )
                               )
           FROM sitifglc
          WHERE cod_nazionale = cn
            AND LPAD (TRIM (foglio), 6, '0') = LPAD (TRIM (fog), 6, '0');

      FETCH c
       INTO retshp;

      IF c%NOTFOUND
      THEN
         retshp := NULL;
      END IF;

      CLOSE c;
   END IF;

   IF cn IS NOT NULL AND retshp IS NULL
   THEN
      OPEN c FOR
         SELECT sdo_aggr_mbr (shape)
           FROM siticoml
          WHERE (istatp, istatc) IN (SELECT istatp, istatc
                                       FROM siticomu
                                      WHERE cod_nazionale = cn);

      FETCH c
       INTO retshp;

      IF c%NOTFOUND
      THEN
         retshp := NULL;
      END IF;

      CLOSE c;
   END IF;

   RETURN retshp;
END ingombro_particella;
/


