DROP FUNCTION DIOGENE_H501.IS_RESIDENTE_IN_PROP;

CREATE OR REPLACE FUNCTION DIOGENE_H501.IS_RESIDENTE_IN_PROP(P_CF VARCHAR2, P_COGN VARCHAR2, P_NOME VARCHAR2, P_DT_NASCITA DATE, P_FOGLIO NUMBER, P_PARTICELLA VARCHAR2) RETURN NUMBER IS
-- TORNA 1 SE IL SOGGETTO E' RESIDENTE IN IMMOBILE DI PROPRIETA'
RET NUMBER;
NO_CONSISTENCE EXCEPTION; 
V_VIA VARCHAR2(100);
V_CIV_LIV1 VARCHAR2(10);
BEGIN
    RET := 0;
    BEGIN 
        select distinct id_orig_via, civ_liv1
        INTO V_VIA, V_CIV_LIV1
        FROM PERSONA_CIVICI_V 
        WHERE ( CODFISC =P_CF OR (cognome=P_COGN and nome=P_NOME and data_nascita=nvl(P_DT_NASCITA, to_date('0001-01-01', 'yyyy-mm-dd'))));
    EXCEPTION 
    WHEN OTHERS THEN
        RAISE NO_CONSISTENCE;
    END;

    DECLARE
        V_ID1 NUMBER;
        V_ID2 NUMBER;
    BEGIN 
        select distinct fid_pertin INTO v_id1
        from HW_pertciv
        where via_cod=V_VIA
        and LPAD(civ_num,5,0)=LPAD(V_CIV_LIV1,5,'0');

        select distinct fid_pertin INTO V_ID2
        from hw_partpert hpp
        where hpp.foglio=P_FOGLIO
        and lpad(hpp.particella,5,'0')=LPAD(P_PARTICELLA,5,'0')
        and hpp.area_int>0.3*area_part;

        IF V_ID1 =V_ID2 THEN 
            RET :=1;
        END IF;

    EXCEPTION 
    WHEN OTHERS THEN
        RAISE NO_CONSISTENCE;
    END;

    RETURN RET;

       
EXCEPTION
WHEN NO_CONSISTENCE THEN
    RETURN -1;
WHEN OTHERS THEN
  RAISE;
END IS_RESIDENTE_IN_PROP;
/


DROP FUNCTION DIOGENE_H501.REDDITO_2004;

CREATE OR REPLACE FUNCTION DIOGENE_H501.reddito_2004 (codfis VARCHAR2)
   RETURN NUMBER
AS
BEGIN
   DECLARE
         reddito   NUMBER (10, 2);
        cf        VARCHAR2 (16);
        CURSOR c2 IS
              SELECT distinct rd.codice_quadro, rd.valore_contabile, rt.cent_divisore
                FROM red_redditi_dichiarati rd, red_trascodifica rt, red_descrizione rdes
               WHERE     rd.anno_imposta = rt.anno_imposta
                     AND rd.codice_quadro = rt.codice_riga
                     AND rdes.ide_telematico=rd.ide_telematico
                     and rdes.anno_imposta=rd.anno_imposta
                     and rdes.codice_fiscale_dic=rd.codice_fiscale_dic
                     AND rd.codice_fiscale_dic = codfis
                     and rt.tipo_modello=rdes.tipo_modello
                     and rd.anno_imposta = 2004
                     and (rd.codice_quadro, rt.tipo_modello) IN (
                        ('DB001001','S'),('RN005004','U'),('PL010001','3'),('PL010002','3'),
                        ('RA052009','5'),('RA052010','5'),('RB035008','5'),('RD015001','5'),
                        ('RE023002','5'),('RF054002','5'),('RG029002','5'),('RH015003','5'),
                        ('RL003002','5'),('RL012001','5'),('RN007001','5'),('RN010001','5'),
                        ('RN011001','5'), ('RN005002','6'),('RN016001','8'));

   BEGIN
            cf := codfis;
            reddito := 0;

            FOR rec_c2 IN c2
            LOOP
                IF SUBSTR (rec_c2.valore_contabile, 0, 1) = '-'
                THEN
                    reddito := reddito - TRUNC (TO_NUMBER (SUBSTR (rec_c2.valore_contabile, 2) / rec_c2.cent_divisore));
                ELSIF SUBSTR (rec_c2.valore_contabile, 0, 1) = '+'
                THEN reddito := reddito + TRUNC (TO_NUMBER (SUBSTR (rec_c2.valore_contabile, 2) / rec_c2.cent_divisore));
                ELSE reddito :=reddito+ TO_NUMBER (replace(rec_c2.valore_contabile,'.','')) / rec_c2.cent_divisore;
              END IF;
            END LOOP;

            RETURN REDDITO;
   END;
END;
/


