  RETURN dati_canone_type IS
BEGIN
   RETURN calc_2 (dati_canone);
END calc_4;
/


DROP FUNCTION SITI_H501.CALC_5;

CREATE OR REPLACE FUNCTION SITI_H501.calc_5 (dati_canone dati_canone_type)
  RETURN dati_canone_type IS

  m_dati_canone_plur            dati_canone_plur_type;
  m_dati_calcolo                dati_calcolo_type;
  m_dati_istat                  dati_istat_type;
  ret                           dati_canone_type;
  m_anno_lav                    NUMBER := EXTRACT (YEAR FROM dati_canone.data_lav);	-- anno calcolo del canone
  m_istat_base_anno          	  NUMBER := 0;	  		  		 									-- Anno istat base
  m_istat_rid                   NUMBER := 0;          										-- % istat ridotta della tabella dei canoni pluriennali

BEGIN

  -- verifico se esiste un canone pluriennale
  m_dati_canone_plur :=
            patri_canoni_pck.get_canone_plur_concordato (dati_canone.id_atto, dati_canone.id_doc, dati_canone.data_lav);

  IF m_dati_canone_plur.exist = 1 THEN

	 -- calcolo il canone periodico
    m_dati_calcolo :=
      patri_canoni_pck.get_val_loc_periodico_concord (dati_canone.id_atto, dati_canone.id_doc, dati_canone.data_lav,
                                                      m_dati_canone_plur.canone, m_dati_canone_plur.canone_ridotto,
                                                      m_dati_canone_plur.fl_canone_rid);


	 -- se il flag m_flag_istat_rid='S' recupero la percentuale istat di riduzione dal primo record della scaletta
    IF m_dati_canone_plur.fl_istat_rid = 'S' THEN
      BEGIN
        SELECT NVL (perc_istat, 0)
          INTO m_istat_rid
          FROM patri_loc_canonipl_concordato
         WHERE codice = dati_canone.id_atto AND id_canone = 1;                            -- primo record della scaletta
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          m_istat_rid := 0;
      END;

      -- la riduzione istat va applicata solo per i primi tre anni dall'inizio della scaletta
      IF m_anno_lav > (m_dati_canone_plur.anno_min + 2) THEN
        m_dati_canone_plur.fl_istat_rid := 'N';
        m_istat_rid := 0;
      END IF;

	 ELSE
      m_istat_rid := 0;
    END IF;

    -- ricerco l'istat base annuale
    BEGIN

		SELECT NVL (pltc.istat_base_anno, EXTRACT (YEAR FROM dati_canone.data_decorrenza))
        INTO m_istat_base_anno
        FROM sitifile_documenti_campi_ext sfce, patri_loc_tipo_contr pltc
       WHERE sfce.fkid_doc = dati_canone.id_doc AND pltc.fkid_doc = sfce.fkid_doc;

	 EXCEPTION
      WHEN NO_DATA_FOUND THEN

		  m_istat_base_anno := EXTRACT (YEAR FROM dati_canone.data_decorrenza);

	 END;

    IF m_istat_base_anno = 0 THEN
      m_istat_base_anno := EXTRACT (YEAR FROM dati_canone.data_decorrenza);
    END IF;

    -- primo anno -> si utilizza l'istat_base_anno altrimenti l'anno della scaletta - 1
    IF m_anno_lav <> m_dati_canone_plur.anno_min THEN
      m_istat_base_anno := m_dati_canone_plur.anno - 1;
    END IF;

    -- calcolo istat
    m_dati_istat :=
      patri_canoni_pck.calcola_istat (dati_canone.id_atto, dati_canone.id_doc, m_dati_calcolo.canone_periodico,
                                      m_istat_base_anno, dati_canone.data_lav, m_istat_rid);

	 m_dati_calcolo.canone_periodico_noistat := m_dati_istat.canone_noistat;
    m_dati_calcolo.canone_periodico := m_dati_istat.canone_istat;

  ELSE
    raise_application_error (-20033, 'Non è stata definita la scaletta');
  END IF;

  -- inizializzo l'oggetto ret
  ret :=
    dati_canone_type (dati_canone.parametri_cespite, dati_canone.coeff_equo_canone, m_dati_calcolo,
                      dati_canone.dati_nucleo_fam, m_dati_istat, m_dati_canone_plur, dati_canone.id_atto,
                      dati_canone.id_doc, dati_canone.data_lav, dati_canone.data_decorrenza,
                      dati_canone.cod_calcolo_canone, dati_canone.cod_personalizzazione, dati_canone.procedura_calcolo,
                      dati_canone.flag_update, dati_canone.ticket_id);
  RETURN ret;
END calc_5;
/


DROP FUNCTION SITI_H501.CALC_6;

CREATE OR REPLACE FUNCTION SITI_H501.calc_6 (dati_canone dati_canone_type)
  RETURN dati_canone_type IS

  m_istat_ipb				  VARCHAR2(1);
BEGIN

	-- istat_IPB può essere solo a percentuali
	SELECT istat_ipb
      INTO m_istat_ipb
      FROM patri_loc_tipo_contr
     WHERE fkid_doc = dati_canone.id_doc;

	IF m_istat_ipb <> patri_canoni_pck.istat_percentuali then
		raise_application_error(-20011, 'L''istat può essere solo a percentuali');
	end if;


   RETURN calc_2(dati_canone);
END calc_6;
/


DROP FUNCTION SITI_H501.CALC_7;

CREATE OR REPLACE FUNCTION SITI_H501.calc_7 (dati_canone dati_canone_type)
  RETURN dati_canone_type IS
  m_dati_canone_plur            dati_canone_plur_type;
  m_dati_calcolo                dati_calcolo_type;
  m_dati_istat                  dati_istat_type;
  ret                           dati_canone_type;
  m_canone_annuo                NUMBER := 0;
  m_anno_base                   NUMBER := 0;
  m_anno_lav                    NUMBER := EXTRACT (YEAR FROM dati_canone.data_lav);	-- anno di riferimento per il calcolo del canone
  m_istat_base_anno             NUMBER := 0;                                        -- Anno istat base
  m_istat_rid                   NUMBER := 0;                                        -- franchigia istat
BEGIN

  -- ricerco il canone_iniziale, il canone_finale gli scatti e l'istat base
  BEGIN
    SELECT NVL (pltc.istat_base_anno, EXTRACT (YEAR FROM dati_canone.data_decorrenza))
      INTO m_istat_base_anno
      FROM patri_loc_tipo_contr pltc
     WHERE pltc.fkid_doc = dati_canone.id_doc;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      m_istat_base_anno := EXTRACT (YEAR FROM dati_canone.data_decorrenza);
  END;

  IF m_istat_base_anno = 0 THEN
    m_istat_base_anno := EXTRACT (YEAR FROM dati_canone.data_decorrenza);
  END IF;

  m_dati_canone_plur :=
          patri_canoni_pck.get_canone_plur_conc_h2o (dati_canone.id_atto, dati_canone.id_doc, dati_canone.data_lav);





  -- se la scaletta esiste leggo i valori
  IF m_dati_canone_plur.exist = 1 THEN

	 -- calcolo dell'anno base
    IF m_dati_canone_plur.anno = m_dati_canone_plur.anno_min THEN
      m_anno_base := m_istat_base_anno;
    ELSE
      m_anno_base := m_dati_canone_plur.anno - 1;
    END IF;

    -- calcolo del canone annuo
    IF m_dati_canone_plur.used = 1 THEN
      m_canone_annuo := m_dati_canone_plur.canone;
    ELSE
      m_canone_annuo := 0;
    END IF;

  -- se la scaletta NON esiste e se il canonoe iniziale e finale coincidono
  ELSE

    m_canone_annuo := 0;
    m_anno_base := m_istat_base_anno;

  END IF;

  -- calcolo il canone periodico
  m_dati_calcolo :=
    patri_canoni_pck.get_val_loc_periodico_conc_h20 (dati_canone.id_atto, dati_canone.id_doc,
	 																  dati_canone.data_lav, m_canone_annuo);

  -- calcolo istat
  m_dati_istat :=
    patri_canoni_pck.calcola_istat (dati_canone.id_atto, dati_canone.id_doc, m_dati_calcolo.canone_periodico,
                                    m_anno_base, dati_canone.data_lav, m_istat_rid);

  m_dati_calcolo.canone_periodico_noistat := m_dati_istat.canone_noistat;
  m_dati_calcolo.canone_periodico := m_dati_istat.canone_istat;

  -- inizializzo l'oggetto ret
  ret :=
    dati_canone_type (dati_canone.parametri_cespite, dati_canone.coeff_equo_canone, m_dati_calcolo,
                      dati_canone.dati_nucleo_fam, m_dati_istat, m_dati_canone_plur, dati_canone.id_atto,
                      dati_canone.id_doc, dati_canone.data_lav, dati_canone.data_decorrenza,
                      dati_canone.cod_calcolo_canone, dati_canone.cod_personalizzazione, dati_canone.procedura_calcolo,
                      dati_canone.flag_update, dati_canone.ticket_id);

  RETURN ret;

END calc_7;
/


