DROP FUNCTION SITI_H501.CLEANDAMAGEISLAND;

CREATE OR REPLACE FUNCTION SITI_H501.cleandamageisland(SHPorg IN MDSYS.SDO_GEOMETRY) RETURN MDSYS.SDO_GEOMETRY
IS
  SHPdst MDSYS.SDO_GEOMETRY;
  SHPtmp MDSYS.SDO_GEOMETRY;
  NumElem number;
  i NUMBER;

BEGIN
  i:=1;
  SHPdst:=NULL;
  NumElem:=sdo_tools.get_num_elements(SHPorg);
  WHILE i<=NumElem LOOP
    SHPtmp:=sdo_tools.get_element(SHPorg,i);
    IF (sdo_tools.get_num_points(SHPtmp)>=4 OR sdo_tools.get_num_points(SHPtmp)=0) THEN
        SHPdst:=SDO_GEOM.SDO_UNION(SHPdst,SHPtmp,0.1);
    END IF;
    i:=i+1;
  END LOOP;
  RETURN SHPdst;
END CleanDamageIsland;

/


DROP FUNCTION SITI_H501.FLAG;

CREATE OR REPLACE function SITI_H501.flag(p_f varchar2, ita char default 'N') return char is
begin
  if length(p_f) > 1 or p_f = 'N' then
    return 'N';
  elsif ita != 'N' then
    return 'S';
  else
    return 'Y';
  end if;
end;
/


DROP FUNCTION SITI_H501.GET_AGGR_TOPO_CAP;

CREATE OR REPLACE FUNCTION SITI_H501.get_aggr_topo_cap(pi_str_cod_naz VARCHAR2)
/*
a.caleffi 2010-03-24 dato il codice nazionale ritorna il primo cap utile dalla tabella aggr_topo


Usato nei report CONSIP
*/

return varchar2
AS

	CURSOR cur_aggr_topo(pi_str_cod_naz varchar2) IS
	SELECT kat.cap
	FROM aggr_topo kat
	WHERE kat.aggr_code = 1  -- via
	AND kat.cod_nazionale = pi_str_cod_naz
	ORDER BY cap nulls last;

	fld_cap VARCHAR2(5);

	str_retval VARCHAR2(200);
BEGIN

	-- pongo il valore di ritorno a null
	str_retval := NULL;

	OPEN cur_aggr_topo(pi_str_cod_naz);
	FETCH cur_aggr_topo INTO fld_cap;

	IF (cur_aggr_topo%FOUND) THEN

		str_retval := fld_cap;

	END IF;

	CLOSE cur_aggr_topo;

	RETURN str_retval;
END;
/


DROP FUNCTION SITI_H501.GET_AGGR_TOPO_PKID_UIU;

CREATE OR REPLACE FUNCTION SITI_H501.get_aggr_topo_pkid_uiu(pi_pkid_uiu NUMBER, pi_date DATE, pi_what int)
/*

a.caleffi 2010-03-23 dato il codice univoco della UIU e la data di validita'
ritorna delle informazioni indentificate dal parametro "pi_what" dalla tabella AGGR_TOPO
Le query partono dalla tabella SITIUIU_LOC --> AGGR_LOCALIZZA e poi --> AGGR_TOPO
prendendo di ciascuna il primo record, per avere un unico valore.

In base al valore di pi_what, viene ritornare una info differente:

1 : nome (indirizzo)
2 : numero (numero civico)
3 : cap (cap della via)

Usato nei report CONSIP

version 1.1 - 2010-03-26
modificata ricerca numero civico, preso da tabella AGGR_LOCALIZZA
*/

return varchar2
AS

	-- dato il codice della uiu cerca il codice del pkid_loc per la tabella AGGR_LOCALIZZA
	CURSOR cur_sitiloc_uiu(pi_pkid_uiu number, pi_date date) IS
	SELECT fkid_type, pkid_loc
	FROM sitiloc_uiu kslu
	WHERE kslu.pkid_uiu = pi_pkid_uiu
	AND kslu.fkid_type = -1 -- solo numeri civici
	AND pi_date BETWEEN kslu.data_inizio_val AND kslu.data_fine_val  -- locazione uiu in corso di validita'
	ORDER BY kslu.principale DESC -- prima i record con Y e poi quelli con N
		, kslu.data_fine_val DESC;

	-- dato il codice di localizzazione ritorna il codice nella tabella AGGR_TOPO
	CURSOR cur_aggr_localizza(pi_pkid_loc NUMBER, pi_date date) IS
	SELECT pkid_topo, nome
	FROM aggr_localizza kal
	WHERE kal.pkid_loc = pi_pkid_loc
	AND pi_date BETWEEN kal.data_inizio_val AND kal.data_fine_val;


	-- dato il codice del toponimo ritorna le info sulla via
	CURSOR cur_aggr_topo(pi_pkid_topo number, pi_date date) IS
	SELECT kat.nome, kat.numero, kat.cap
	FROM aggr_topo kat
	WHERE kat.aggr_code = 1  -- via
	AND kat.pkid_topo = pi_pkid_topo
	AND pi_date BETWEEN kat.data_inizio_val AND kat.data_fine_val;

	fld_pkid_type NUMBER(9);
	fld_pkid_loc NUMBER(9);
	fld_pkid_topo NUMBER(9);

	fld_nome VARCHAR2(200);
	fld_numero VARCHAR2(9);
	fld_cap VARCHAR2(5);

	str_retval VARCHAR2(200);
BEGIN

	-- pongo il valore di ritorno a null
	str_retval := NULL;

	OPEN cur_sitiloc_uiu(pi_pkid_uiu, pi_date);

	FETCH cur_sitiloc_uiu INTO fld_pkid_type, fld_pkid_loc;

	IF (cur_sitiloc_uiu%FOUND)THEN

		-- ho trovato il record della locazione
		-- ora devo cercare nella tabella aggr_localizza

		OPEN cur_aggr_localizza(fld_pkid_loc, pi_date);

		FETCH cur_aggr_localizza INTO fld_pkid_topo, fld_nome;

		IF (cur_aggr_localizza%FOUND) THEN

      IF (2 = pi_what)THEN
        str_retval := fld_nome;
      else
			  OPEN cur_aggr_topo(fld_pkid_topo, pi_date);
			  FETCH cur_aggr_topo INTO fld_nome, fld_numero, fld_cap;

			  IF (cur_aggr_topo%FOUND) THEN

				  CASE pi_what
					  WHEN 1 THEN str_retval := fld_nome;
					  when 3 THEN str_retval := fld_cap;
				  END case;

			  END IF;

			  CLOSE cur_aggr_topo;
      END IF;
		END IF;

		CLOSE cur_aggr_localizza;

	END IF;

	CLOSE cur_sitiloc_uiu;

	RETURN str_retval;
END;
/


DROP FUNCTION SITI_H501.GET_BOOLEAN_DESCRIPTION;

CREATE OR REPLACE FUNCTION SITI_H501.get_boolean_description(BOOL CHAR)
RETURN VARCHAR IS
BEGIN
 IF BOOL <> 'N' THEN
  RETURN 'NO';
   ELSE
     RETURN 'SI';
   END IF;
END get_boolean_description;
/


DROP FUNCTION SITI_H501.GETCODNAZ;

CREATE OR REPLACE FUNCTION SITI_H501.getcodnaz (IISTATP IN VARCHAR2,IISTATC IN VARCHAR2,IID_SEZC IN VARCHAR2) RETURN VARCHAR2
IS
      CURSOR C1 IS SELECT A.COD_NAZIONALE FROM SITICOMU A WHERE A.ISTATP = IISTATP AND A.ISTATC = IISTATC AND A.ID_SEZC = IID_SEZC;
      CURSOR C2 IS SELECT A.COD_NAZIONALE FROM SITICOMU A WHERE A.ISTATP = IISTATP AND A.ISTATC = IISTATC AND A.ID_SEZC IS NULL;
      RETVAL   VARCHAR2 (4);
BEGIN
      IF IID_SEZC IS NULL THEN
         OPEN C2;
         FETCH C2 INTO RETVAL;
         IF C2%NOTFOUND THEN RETVAL := NULL; END IF;
         CLOSE C2;
      ELSE
         OPEN C1;
         FETCH C1 INTO RETVAL;
         IF C1%NOTFOUND THEN RETVAL := NULL; END IF;
         CLOSE C1;
      END IF;

      RETURN RETVAL;
END GETCODNAZ;
/


DROP FUNCTION SITI_H501.GETDATIPART;

CREATE OR REPLACE FUNCTION SITI_H501.getdatipart (
   cod_naz   IN   VARCHAR2,
   fog          IN   NUMBER,
   part      IN   VARCHAR2,
   subo             IN   VARCHAR2,
   unimm           IN   NUMBER,
   cuaa            IN   VARCHAR2
)
   RETURN VARCHAR2
IS
   retvalue   VARCHAR2 (2048):='';
   cent_x     NUMBER(9);
   cent_y     NUMBER(9);
BEGIN
  SELECT ROUND(SDO_TOOLS.GET_POINT_X(SHAPE)), ROUND(SDO_TOOLS.GET_POINT_Y(SHAPE))
  INTO cent_x, cent_y
  FROM SITICENT
  WHERE COD_NAZIONALE=cod_naz AND FOGLIO=fog AND PARTICELLA=part AND SUB=subo AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');

  IF cod_naz = 'A099' THEN  
    retvalue := '<a href="/CDU/cdu.rtf?function=cdu&cduId=rob&fg=' || fog || '&mp=' || part || '&fg=&mp=" target="cdu">Certificato di destinazione urbanistica</a><br><br>';
  END IF;
  IF cod_naz = 'G129' THEN 
    retvalue:=retvalue || '<a href="http://localhost:8888/dbmap3d/dbmap3d.html?initCoordX='|| Trim(To_Char(cent_x)) || '&initCoordY='|| Trim(To_Char(cent_y)) || '&initHeading=0" target="_blank">Apri visualizzazione tridimensionale</a>';
  END IF;
  RETURN retvalue;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN '';
END getdatipart;

/


DROP FUNCTION SITI_H501.GETDATIUIU;

CREATE OR REPLACE FUNCTION SITI_H501.getdatiuiu (
   cod_naz   IN   VARCHAR2,
   fog       IN   NUMBER,
   part      IN   VARCHAR2,
   subo      IN   VARCHAR2,
   unimm     IN   NUMBER,
   cuaa      IN   VARCHAR2
)
   RETURN VARCHAR2
IS
   retvalue   VARCHAR2 (2048) := '';
BEGIN

   RETURN retvalue;
EXCEPTION
   WHEN NO_DATA_FOUND
   THEN
      RETURN '';
END getdatiuiu;
/


DROP FUNCTION SITI_H501.GET_DESTINAZIONE_USO;

CREATE OR REPLACE FUNCTION SITI_H501.get_destinazione_uso(pi_categoria varchar2)
/*
a.caleffi 2010-03-23 dato il codice della classe della uiu ritorna la transcodifica per la
destinazione d'uso

Usato nei report CONSIP

*/
RETURN NUMBER
AS
	i_retval NUMBER;
BEGIN
/*
-    ND
1	A01  ABITAZIONE DI TIPO SIGNORILE
1	A02  ABITAZIONE DI TIPO CIVILE
1	A03  ABITAZIONE DI TIPO ECONOMICO
1	A04  ABITAZIONE DI TIPO POPOLARE
1	A05  ABITAZIONE DI TIPO ULTRAPOPOLARE
1	A06  ABITAZIONE DI TIPO RURALE, IN EFFETTI, TIPO RUSTICO
1	A07  ABITAZIONE IN VILLINI
1	A08  ABITAZIONE IN VILLE
1	A09  CASTELLI, PALAZZI DI EMINENTI PREGI ARTISTICI E STORICI
1	A11  ABITAZIONE ED ALLOGGI TIPICI DEI LUOGHI
1	D10  RESIDENZE
1	F01  AREA URBANA

2	C06  STALLE, SCUDERIE, RIMESSE E AUTORIMESSE
2	C07  TETTOIE CHIUSE ED APERTE

3	B08  MAGAZZINI SOTTERRANEI PER DEPOSITO DERRATE
3	C01  NEGOZI E BOTTEGHE
3	C02  MAGAZZINI E LOCALI DI DEPOSITO
3	D08  FABBRICATI COSTRUITI O ADATTATI PER SPECIALI ESIGENZE DI UNA ATTIVITA COMMERCIALE

4	A10  UFFICI E STUDI PRIVATI
4	D05  ISTITUTI DI CREDITO, CAMBIO ED ASSICURAZIONE

5	C03  LABORATORI PER ARTI E MESTIERI
5	D01  OPIFICI
5	D07  FABBRICATI COSTRUITI O ADATTATI PER SPECIALI ESIGENZE DI UNA ATTIVITA INDUSTRIALE

6	C04  FABBRICATI E LOCALI PER ESERCIZI SPORTIVI
6	C05  STABILIMENTI BALNEARI E DI ACQUE CURATIVE
6	D02  ALBERGHI E PENSIONI
6	D03  TEATRI, CINEMATOGRAFI, SALE PER CONCERTI E SIMILI
6	D06  FABBRICATI E LOCALI PER ESERCIZI SPORTIVI
6	D12  POSTI BARCA IN PORTI TURISTICI, STABILIMENTI BALNEARI

7	B01  COLLEGGI E CONVITTI EDUCANDATI, RICOVERI, ORFANATROFI, OSPIZI, CONVENTI, SEMINARI E CASERME
7	B02  CASE DI CURA ED OSPEDALI
7	B03  PRIGIONI E RIFORMATORI
7	B04  UFFICI PUBBLICI
7	B05  SCUOLE, LABORATORI SCIENTIFICI
7	B06  BIBLIOTECHE, PINACOTECHE, MUSEI, GALLERIE, ACCADEMIE CHE NON HANNO SEDE IN EDIFICI DELLA CATEGORIA A/9
7	B07  CAPPELLE ED ORATORI NON DESTINATI ALL'ESERCIZIO PUBBLICO DEI CULTI
7	D04  CASE DI CURA ED OSPEDALI
7	D11  SCUOLE E LABORATORI SCIENTIFICI PRIVATI
7	E03  COSTRUZIONI E FABBRICATI PER SPECIALI ESIGENZE PUBBLICHE
7	E04  RECINTI CHIUSI PER SPECIALI ESIGENZE PUBBLICHE
7	E07  FABBRICATI DESTINATI ALL'USO PUBBLICO DEI CULTI
7	E08  FABBRICATI E COSTRUZIONI NEI CIMITERI, ESCLUSI I COLOMBARI, I SEPOLCRI, E LE TOMBE DI FAMIGLIA
7	E09  EDIFICI A DESTINAZIONE PARTICOLARE NON COMPRESI NELLE CATEGORIE PRECEDENTI DEL GRUPPO E

8	D09  EDIFICI GALLEGGIANTI O SOSPESI, ASSICURATI A PUNTI FISSI AL SUOLO: PONTI PRIVATI SOGGETTI A PEDAGGIO
8	E01  STAZIONI PER SERVIZIO DI TRASPORTO TERRESTRE, MARITTIMO ED AEREO
8	E02  PONTI COMUNALI E PROVINCIALI SOGGETTI A PEDAGIO
8	E05  FABBRICATI COSTITUENTI FORTIFICAZIONI E LORO DIPENDENZE
8	E06  FARI, SEMAFORI, TORRI PER RENDERE D'USO PUBBLICO L'OROLOGIO COMUNALE
8	F02  UNITA' COLLABENTI
8	F03  UNITA' IN CORSO DI COSTRUZIONE
8	F04  UNITA' IN CORSO DI DEFINIZIONE
8	F05  LASTRICO SOLARE
*/

	IF (pi_categoria IN ('A01', 'A02', 'A03', 'A04', 'A05', 'A06', 'A07', 'A08', 'A09', 'A11', 'D10', 'F01')) THEN
		i_retval := 1;
	ELSE

		IF (pi_categoria IN ('C06', 'C07')) THEN
			i_retval := 2;
		ELSE

			IF (pi_categoria IN ('B08', 'C01', 'C02', 'D08')) THEN
				i_retval := 3;
			ELSE

				IF (pi_categoria IN ('A10', 'D05')) THEN
					i_retval := 4;
				ELSE

					IF (pi_categoria IN ('C03', 'D01', 'D07')) THEN
						i_retval := 5;
					ELSE
						IF (pi_categoria IN ('C04', 'C05', 'D02', 'D03', 'D06', 'D12')) then
							i_retval := 6;
						ELSE
							IF (pi_categoria IN ('B01', 'B02', 'B03', 'B04', 'B05', 'B06', 'B07', 'D04', 'D11', 'E03', 'E04', 'E07', 'E08', 'E09')) THEN
								i_retval := 7;
							else
								i_retval := 8;
							END IF;
						END IF;
					END IF;
				END IF;
			END IF;
		END IF;
	END IF;

	RETURN i_retval;

END;
/


DROP FUNCTION SITI_H501.GET_DOCUMENT_AS_STRING;

CREATE OR REPLACE FUNCTION SITI_H501.get_document_as_string(ID_DOCUMENTO NUMBER)
RETURN VARCHAR IS
 DOCUMENT_TYPE NUMBER;
    QUERY_COLUMNS VARCHAR(1000);
    QUERY_RESULT VARCHAR(1000);
    SITIFILE_SEARCH_DOC_CFG_COUNT NUMBER;
    SITIFILE_SEARCH_DOC_CFG_QUERY VARCHAR(250);
    TYPE CURSORE IS REF CURSOR;
    C CURSORE;
    RECORD_INDEX SITIFILE_SEARCH_DOC_CFG%ROWTYPE;
    CURSOR FORM_FIELDS (DOCUMENT_TYPE IN NUMBER) IS
     SELECT SITI_TIPI_CAMPI_EXT.* FROM SITI_TIPI_CAMPI_EXT
  JOIN SITIFILE_TIPI_DOC_CAMPI_EXT ON SITI_TIPI_CAMPI_EXT.PKID = SITIFILE_TIPI_DOC_CAMPI_EXT.FKID_CAMPO
  WHERE SITIFILE_TIPI_DOC_CAMPI_EXT.FKID_TIPO_DOC = DOCUMENT_TYPE
  AND PKID IN (SELECT STORED_FIELD_ID FROM SITIFILE_SEARCH_DOC_FIELD_CFG WHERE FKID_TIPO_DOC = DOCUMENT_TYPE);
    FORM_FIELD SITI_TIPI_CAMPI_EXT%ROWTYPE;
 CURSOR LINK_FIELDS (DOCUMENT_TYPE IN NUMBER) IS
     SELECT SITIFILE_FIELD_TYPE_EXTLINK.* FROM SITIFILE_FIELD_TYPE_EXTLINK
  JOIN SITIFILE_TIPI_DOC_CAMPI_LINK ON SITIFILE_FIELD_TYPE_EXTLINK.PKID = SITIFILE_TIPI_DOC_CAMPI_LINK.FKID_CAMPO
  WHERE SITIFILE_TIPI_DOC_CAMPI_LINK.FKID_TIPO_DOC = DOCUMENT_TYPE
  AND PKID IN (SELECT STORED_FIELD_ID FROM SITIFILE_SEARCH_DOC_FIELD_CFG WHERE FKID_TIPO_DOC = DOCUMENT_TYPE);
    LINK_FIELD SITIFILE_FIELD_TYPE_EXTLINK%ROWTYPE;
BEGIN
 SELECT FKID_TIPO_DOC INTO DOCUMENT_TYPE FROM SITIFILE_DOCUMENTI WHERE PKID_DOC = ID_DOCUMENTO;

    SELECT COUNT(*) INTO SITIFILE_SEARCH_DOC_CFG_COUNT FROM SITIFILE_SEARCH_DOC_CFG WHERE FKID_TIPO_DOC = DOCUMENT_TYPE;
    IF SITIFILE_SEARCH_DOC_CFG_COUNT = 1 THEN
     SITIFILE_SEARCH_DOC_CFG_QUERY := 'SELECT * FROM SITIFILE_SEARCH_DOC_CFG WHERE FKID_TIPO_DOC = ' || DOCUMENT_TYPE;
    ELSE
     SITIFILE_SEARCH_DOC_CFG_QUERY := 'SELECT -1 AS FKID_TIPO_DOC, ''Y'' AS SHORT_DESCRIPTION, ''N'' AS LONG_DESCRIPTION, ''N'' AS PROTOCOL, ''N'' AS EXPIRATION_DATE, ''Y'' AS LAST_MODIFIED, ''Y'' AS VERSION_START_DATE, ''N'' AS VERSION_END_DATE, ''Y'' AS VALID FROM DUAL';
    END IF;

    OPEN C FOR SITIFILE_SEARCH_DOC_CFG_QUERY;
    LOOP
        FETCH C INTO RECORD_INDEX;
        EXIT WHEN C%NOTFOUND;
      IF RECORD_INDEX.SHORT_DESCRIPTION = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Descrizione: '' || DESCRIZIONE_BREVE || '' '' ||';
         END IF;

         IF RECORD_INDEX.LONG_DESCRIPTION = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Descrizione estesa: '' || DESCRIZIONE_ESTESA || '' '' ||';
         END IF;

         IF RECORD_INDEX.PROTOCOL = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Protocollo: '' || COD_ARCHIVIAZIONE || '' '' ||';
         END IF;

         IF RECORD_INDEX.EXPIRATION_DATE = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Data scadenza: '' || TO_CHAR(DATA_SCADENZA, ''DD/MM/YYYY'') || '' '' ||';
         END IF;

         IF RECORD_INDEX.LAST_MODIFIED = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Ultima modifica: '' || TO_CHAR(DATA_LAV, ''DD/MM/YYYY'') || '' '' ||';
         END IF;

         IF RECORD_INDEX.VERSION_START_DATE = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Creato il: '' || TO_CHAR(DATA_INIZIO_VAL, ''DD/MM/YYYY'') || '' '' ||';
         END IF;

         IF RECORD_INDEX.VERSION_END_DATE = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Eliminato il: '' || TO_CHAR(DATA_FINE_VAL, ''DD/MM/YYYY'') || '' '' ||';
         END IF;

         IF RECORD_INDEX.VALID = 'Y' THEN QUERY_COLUMNS := QUERY_COLUMNS || '''- Valido: '' || get_boolean_description(VALIDO) || '' '' ||';
         END IF;
    END LOOP;
    CLOSE C;

 OPEN FORM_FIELDS (DOCUMENT_TYPE);
 LOOP
  FETCH FORM_FIELDS INTO FORM_FIELD;
       EXIT WHEN FORM_FIELDS%NOTFOUND;
        QUERY_COLUMNS := QUERY_COLUMNS || '''- ' || FORM_FIELD.DESCRIZIONE || ': '' || ' || FORM_FIELD.PKID || ' || '' '' ||';
    END LOOP;
    CLOSE FORM_FIELDS;

 OPEN LINK_FIELDS (DOCUMENT_TYPE);
 LOOP
  FETCH LINK_FIELDS INTO LINK_FIELD;
       EXIT WHEN LINK_FIELDS%NOTFOUND;
        QUERY_COLUMNS := QUERY_COLUMNS || '''- ' || LINK_FIELD.DESCRIZIONE || ': '' || ' || LINK_FIELD.PKID || ' || '' '' ||';
    END LOOP;
    CLOSE LINK_FIELDS;

    EXECUTE IMMEDIATE 'SELECT ' || QUERY_COLUMNS || ''''' FROM SITIFILE_DOCUMENTI DOCUMENTO LEFT JOIN SITIFILE_DOCUMENTI_CAMPI_EXT CAMPI ON DOCUMENTO.PKID_DOC = CAMPI.FKID_DOC WHERE PKID_DOC = ' || ID_DOCUMENTO
     INTO QUERY_RESULT;
    RETURN QUERY_RESULT;
END get_document_as_string;
/


DROP FUNCTION SITI_H501.GET_PERCENTUALE;

CREATE OR REPLACE FUNCTION SITI_H501.GET_PERCENTUALE(QUOTA1 IN NUMBER, QUOTALIMITE IN NUMBER) RETURN NUMBER
IS
  RETVALUE NUMBER(12,3);
BEGIN
  IF QUOTALIMITE <= 0 OR QUOTALIMITE < QUOTA1 THEN
    RETVALUE := 100;
  ELSE
    RETVALUE := (QUOTA1 / QUOTALIMITE) * 100;
  END IF;
  RETURN RETVALUE;
END GET_PERCENTUALE;
/


DROP FUNCTION SITI_H501.GET_PERC_VANI_MANAGED;

CREATE OR REPLACE FUNCTION SITI_H501.get_perc_vani_managed (
   p_cn       VARCHAR2,
   p_foglio   NUMBER,
   p_part     VARCHAR2,
   p_sub      VARCHAR2,
   p_unimm    NUMBER,
	sso_user   VARCHAR2 DEFAULT NULL,
   p_date     DATE DEFAULT SYSDATE
)
   RETURN NUMBER
IS
   m_perc           NUMBER;
   m_number_vani    NUMBER;
   m_managed_vani   NUMBER;
   m_date           DATE;
BEGIN
   m_date := SYSDATE;                                              -- p_date;
   m_perc := 100;

   IF sso_user IS NOT NULL AND LENGTH(TRIM(sso_user)) > 0
   THEN
      SELECT NVL (COUNT (*), 0)
        INTO m_managed_vani
        FROM settori_operators so,
             (SELECT DISTINCT cod_nazionale, foglio, particella, sub, unimm,
                              vano, fk_settore
                         FROM settori_cr_aggregati
                        WHERE etype = 'V'
              UNION
              SELECT DISTINCT cod_nazionale, foglio, particella, sub, unimm,
                              vano, fk_settore
                         FROM settori_cr_particelle
                        WHERE etype = 'V'
              UNION
              SELECT DISTINCT cod_nazionale, foglio, particella, sub, unimm,
                              vano, fk_settore
                         FROM settori_cr_uiu
                        WHERE etype = 'V'
              UNION
              SELECT DISTINCT cod_nazionale, foglio, particella, sub, unimm,
                              vano, fk_settore
                         FROM settori_cr_vani
                        WHERE etype = 'V') cr
       WHERE so.sso_userid = sso_user
         AND so.fkid_ute = cr.fk_settore
         AND cr.cod_nazionale = p_cn
         AND cr.foglio = p_foglio
         AND cr.particella = p_part
         AND cr.sub = p_sub
         AND cr.unimm = p_unimm;

      SELECT NVL (COUNT (*), 0)
        INTO m_number_vani
        FROM sitiedi_vani
       WHERE cod_nazionale = p_cn
         AND foglio = p_foglio
         AND particella = p_part
         AND sub = p_sub
         AND unimm = p_unimm
         AND data_inizio_val <= m_date
         AND data_fine_val >= m_date;

      IF m_managed_vani > m_number_vani
      THEN
         m_managed_vani := m_number_vani;
      END IF;

      IF m_number_vani > 0
      THEN
         m_perc := (m_managed_vani / m_number_vani) * 100;
      ELSE
         m_perc := 100;
      END IF;
   END IF;

   RETURN m_perc;
END get_perc_vani_managed;
/


DROP FUNCTION SITI_H501.GET_PK_CUAA;

CREATE OR REPLACE FUNCTION SITI_H501.GET_PK_CUAA(MYCUAA IN VARCHAR2, MYDATA IN DATE) RETURN NUMBER
IS
  CURSOR C1 IS SELECT PK_CUAA FROM CONS_AZIE_TAB WHERE CUAA=MYCUAA AND DATA_INIZIO <= MYDATA AND DATA_FINE >= MYDATA;
  RETVALUE NUMBER(9);
BEGIN
  OPEN C1;
  FETCH C1 INTO RETVALUE;
  IF C1%NOTFOUND THEN RETVALUE:=0; END IF;
  CLOSE C1;

  RETURN RETVALUE;
END GET_PK_CUAA;
/


DROP FUNCTION SITI_H501.GET_PREVIOUS_CONTRACT;

CREATE OR REPLACE FUNCTION SITI_H501.get_previous_contract (p_id_atto NUMBER)
   RETURN NUMBER
IS
   m_etype           VARCHAR2 (1) := NULL;
   m_codnaz          VARCHAR2 (4) := NULL;
   m_foglio          NUMBER       := NULL;
   m_particella      VARCHAR2 (5) := NULL;
   m_sub             VARCHAR2 (1) := NULL;
   m_unimm           NUMBER       := NULL;
   m_datainizio      DATE         := NULL;
   m_fl_totale       VARCHAR2 (1) := NULL;
   m_prev_contract   NUMBER       := 0;
BEGIN
   -- Cerco il contratto precedente verificando se esiste almeno un record nelle tabelle delle titolarità
   -- che contiene pk_id_atto nel campo atto_fin
   BEGIN
		SELECT NVL (MAX (atto_ini), 0)
	     INTO m_prev_contract
	     FROM (SELECT DISTINCT atto_ini
	                      FROM cons_urui_tab t
	                     WHERE t.atto_fin = p_id_atto
	           UNION
	           SELECT DISTINCT atto_ini
	                      FROM cons_ufre_tab t
	                     WHERE t.atto_fin = p_id_atto)
	    WHERE ROWNUM = 1;
	EXCEPTION WHEN NO_DATA_FOUND THEN
		m_prev_contract := 0;
	END;


   -- Se pk_id_atto non è contenuto nel campo atto_fin cerco la uiu/particella principale e la data di inzio della titolarità
   -- e poi ricerco la stessa uiu/particella con data_fine <= alla data di inizio precedentemente trovata
   IF m_prev_contract = 0
   THEN

		BEGIN
			-- Cerco la UIU/Particella principale
	      SELECT etype, cod_nazionale, foglio, particella, sub, unimm,
	             data_inizio, fl_totale
	        INTO m_etype, m_codnaz, m_foglio, m_particella, m_sub, m_unimm,
	             m_datainizio, m_fl_totale
	        FROM (SELECT DISTINCT 'U' AS etype, su.cod_nazionale, su.foglio,
	                              su.particella, su.sub, su.unimm, su.categoria,
	                              t.data_inizio, t.fl_totale
	                         FROM cons_urui_tab t, sitiuiu su
	                        WHERE t.atto_ini = p_id_atto
	                          AND t.cod_nazionale = su.cod_nazionale
	                          AND t.foglio = su.foglio
	                          AND t.particella = su.particella
	                          AND t.sub = su.sub
	                          AND t.unimm = su.unimm
	              UNION
	              SELECT DISTINCT 'P' AS etype, sp.cod_nazionale, sp.foglio,
	                              sp.particella, sp.sub, NULL AS unimm,
	                              NULL AS categoria, t.data_inizio,
	                              'Y' AS fl_totale
	                         FROM cons_ufre_tab t, sititrkc sp
	                        WHERE t.atto_ini = p_id_atto
	                          AND t.cod_nazionale = sp.cod_nazionale
	                          AND t.foglio = sp.foglio
	                          AND t.particella = sp.particella
	                          AND t.sub = sp.sub
	                     ORDER BY categoria NULLS LAST,
	                              cod_nazionale,
	                              foglio,
	                              particella,
	                              sub)
	       WHERE ROWNUM = 1;

		EXCEPTION WHEN NO_DATA_FOUND THEN
			m_datainizio := NULL;
			m_codnaz := NULL;
		END;


		-- Se ho trovato una UIU/PARTICELLA la ricerco con data fine <=  alla data di inizio trovata
      IF m_datainizio is not NULL AND m_codnaz is not NULL
      THEN
         IF TRIM (m_fl_totale) = 'Y'
         THEN

				-- la UIU/PARTICELLA è locata totalmente
            IF TRIM (m_etype) = 'U'
            THEN
					 BEGIN
	               -- è una UIU
	               SELECT NVL (atto_ini, 0)
	                 INTO m_prev_contract
	                 FROM (SELECT   atto_ini
	                           FROM cons_urui_tab t
	                          WHERE t.cod_nazionale = m_codnaz
	                            AND t.foglio = m_foglio
	                            AND t.particella = m_particella
	                            AND t.sub = m_sub
	                            AND t.unimm = m_unimm
	                            AND t.data_fine <= m_datainizio
	                       ORDER BY t.data_fine DESC)
	                WHERE ROWNUM = 1;
					 EXCEPTION WHEN NO_DATA_FOUND THEN
					 		m_prev_contract := 0;
					 END;
            ELSE
               BEGIN
						-- è una PARTICELLA
	               SELECT NVL (atto_ini, 0)
	                 INTO m_prev_contract
	                 FROM (SELECT   atto_ini
	                           FROM cons_urui_tab t
	                          WHERE t.cod_nazionale = m_codnaz
	                            AND t.foglio = m_foglio
	                            AND t.particella = m_particella
	                            AND t.sub = m_sub
	                            AND t.data_fine <= m_datainizio
	                       ORDER BY t.data_fine DESC)
	                WHERE ROWNUM = 1;
					EXCEPTION WHEN NO_DATA_FOUND THEN
					 		m_prev_contract := 0;
					 END;
            END IF;


         ELSE

				BEGIN
					-- la UIU non è locata totalmente, devo verificare anche i vani
	            SELECT NVL (atto_ini, 0)
	              INTO m_prev_contract
	              FROM (SELECT   t.atto_ini
	                        FROM cons_urui_tab t LEFT JOIN cons_urui_vani tv
	                             ON t.cod_nazionale = tv.cod_nazionale
	                           AND t.foglio = tv.foglio
	                           AND t.particella = tv.particella
	                           AND t.sub = tv.sub
	                           AND t.unimm = tv.unimm
	                           AND t.atto_ini = tv.id_atto
	                       WHERE t.cod_nazionale = m_codnaz
	                         AND t.foglio = m_foglio
	                         AND t.particella = m_particella
	                         AND t.sub = m_sub
	                         AND t.unimm = m_unimm
	                         AND t.data_fine <= m_datainizio
	                         AND (   tv.vano IS NULL
	                              OR tv.vano IN (
	                                    SELECT vano
	                                      FROM cons_urui_vani
	                                     WHERE cod_nazionale = m_codnaz
	                                       AND foglio = m_foglio
	                                       AND particella = m_particella
	                                       AND sub = m_sub
	                                       AND unimm = m_unimm
	                                       AND id_atto = p_id_atto)
	                             )
	                    ORDER BY data_fine DESC)
	             WHERE ROWNUM = 1;
				EXCEPTION WHEN NO_DATA_FOUND THEN
					 m_prev_contract := 0;
				END;

			END IF;

      END IF;

   END IF;

   RETURN m_prev_contract;
END;
/


DROP FUNCTION SITI_H501.GET_PRG_PART;

CREATE OR REPLACE FUNCTION SITI_H501.get_prg_part(IDCATALOG IN NUMBER, CN IN VARCHAR2, FOG IN NUMBER, PART IN VARCHAR2, SUBA IN VARCHAR2, DATAV IN DATE) RETURN VARCHAR2
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  SUBO VARCHAR2(3);
  DATAVAL DATE;
  TEMPSTR VARCHAR2(255);
  RETPRG VARCHAR2(2048):='';
BEGIN
  DATAVAL:=DATAV;
  IF DATAVAL IS NULL THEN DATAVAL:=TO_DATE('99991231000000','YYYYMMDDHH24MISS'); END IF;

  SUBO:=SUBA;
  IF SUBO IS NULL OR TRIM(SUBO)='' THEN SUBO:=' '; END IF;

  OPEN C FOR SELECT (SELECT B.codut || ' - ' || B.DESCRIZIONE FROM SITIDECO_catalog B WHERE B.CODICE=A.CODICE) AS DESCRIZIONE FROM SITIPART_CAT A WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FOG AND A.PARTICELLA=PART AND A.SUB=SUBO AND A.DATA_INIZIO_VAL<=DATAVAL AND A.DATA_FINE_VAL>=DATAVAL AND A.ID_CAT=IDCATALOG;
  LOOP
    FETCH C INTO TEMPSTR;
    EXIT WHEN (C%NOTFOUND);
	IF LENGTH(RETPRG)>0 THEN RETPRG:=RETPRG || CHR(10); END IF;
	RETPRG:=RETPRG || TEMPSTR;
  END LOOP;
  CLOSE C;

  RETURN RETPRG;
END GET_PRG_PART;

/


DROP FUNCTION SITI_H501.GET_QUOTADENOM_OF_TIT;

CREATE OR REPLACE FUNCTION SITI_H501.get_quotadenom_of_tit (

   id_soggetto NUMBER,
   id_immob NUMBER,
   data_ini DATE,
   data_fine DATE,
   cod_diritt VARCHAR2,
   perc_possesso number


)
   RETURN NUMBER

IS

denominatore NUMBER;

BEGIN



  SELECT quota_denom INTO denominatore
  FROM load_cat_tit
  WHERE To_Date(data_effic_ini,'yyyymmdd')=data_ini
  AND To_Date(nvl(data_effic_fin,99991231),'yyyymmdd')=data_fine
  AND id_soggetto=id_sog
  AND id_immob=id_imm
  AND cod_diritt=cod_diritto
  AND ROWNUM=1
  AND  ((quota_num=0 AND quota_denom=0) AND (perc_possesso=100)
		 OR ((case when quota_denom is null or quota_denom = 0 then 0
			else quota_num/quota_denom*100
			end)
			=perc_possesso));





   RETURN denominatore;

EXCEPTION
   WHEN NO_DATA_FOUND
   THEN
      RETURN 0;
END get_quotadenom_of_tit;
/


DROP FUNCTION SITI_H501.GET_QUOTANUM_OF_TIT;

CREATE OR REPLACE FUNCTION SITI_H501.get_quotanum_of_tit (

   id_soggetto NUMBER,
   id_immob NUMBER,
   data_ini DATE,
   data_fine DATE,
   cod_diritt VARCHAR2,
   perc_possesso number


)
   RETURN NUMBER

IS

numeratore NUMBER;

BEGIN



  SELECT quota_num INTO numeratore
  FROM load_cat_tit
  WHERE To_Date(data_effic_ini,'yyyymmdd')=data_ini
  AND To_Date(nvl(data_effic_fin,99991231),'yyyymmdd')=data_fine
  AND id_soggetto=id_sog
  AND id_immob=id_imm
  AND cod_diritt=cod_diritto
  AND ROWNUM=1
  AND  ((quota_num=0 AND quota_denom=0) AND (perc_possesso=100)
         OR ((case when quota_denom is null or quota_denom = 0 then 0
			else quota_num/quota_denom*100
			end)
			=perc_possesso));







   RETURN numeratore;

EXCEPTION
   WHEN NO_DATA_FOUND
   THEN
      RETURN 0;
END get_quotanum_of_tit;
/


DROP FUNCTION SITI_H501.GET_SUB;

CREATE OR REPLACE FUNCTION SITI_H501.get_sub (
   in_cod_nazionale   IN   VARCHAR2,
   in_foglio          IN   NUMBER,
   in_particella      IN   VARCHAR2,
   in_sub             IN   VARCHAR2,
   in_data_rif        IN   DATE DEFAULT TO_DATE ('99991231', 'YYYYMMDD')
)
   RETURN VARCHAR2
IS
   retvalue   VARCHAR2 (3);
   subuc      VARCHAR2 (3);
BEGIN
   BEGIN
      SELECT sub_uc
        INTO subuc
        FROM siticata
       WHERE cod_nazionale = in_cod_nazionale
         AND foglio = in_foglio
         AND particella = in_particella
         AND sub = in_sub
         AND data_inizio <= in_data_rif
         AND data_fine >= in_data_rif
         and rownum = 1;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         subuc := NULL;
   END;

   IF subuc IS NOT NULL
   THEN
      retvalue := subuc;
   ELSE
      retvalue := in_sub;
   END IF;

   RETURN retvalue;
END;
/


DROP FUNCTION SITI_H501.GET_SUPE_CONV;

CREATE OR REPLACE function SITI_H501.get_supe_conv(p_id_atto number, p_data_lav date) return number is
  cursor cDatiUiu(pp_cn varchar2, pp_fg number, pp_pt varchar2, pp_sub varchar2, pp_un number) is
    select u.categoria, nvl(nvl(u.supe_modelli, u.sup_cat), 0) as supe, e.*
      from sitiuiu u, patri_uiu_ext e
     where u.cod_nazionale = pp_cn and u.foglio = pp_fg and u.particella = pp_pt and u.sub = pp_sub
       and u.unimm = pp_un and p_data_lav between u.data_inizio_val and u.data_fine_val
       and e.cod_nazionale(+) = u.cod_nazionale and e.foglio(+) = u.foglio
       and e.particella(+) = u.particella and e.sub(+) = u.sub and e.unimm(+) = u.unimm;

  m_supe_no_c6      number := 0;
  m_supe_balc_sof   number := 0;
  m_supe_c6         number := 0;
  m_supe_c6_cop     number := 0;
  m_supe_c6_scop    number := 0;
  m_supe_verde_com  number := 0;
  m_supe_escl_god   number := 0;

  m_supe_part		number := 0;

  m_supe_conv       number := 0;

begin

  -- Calcolo le superfici
  for rUiu in (select distinct cod_nazionale, foglio, particella, sub, unimm
                 from cons_urui_tab t where atto_ini = p_id_atto) loop

    for rDatiUiu in cDatiUiu(rUiu.cod_nazionale, rUiu.foglio, rUiu.particella, rUiu.sub, rUiu.unimm) loop
      if rDatiUiu.categoria = 'C06' then
        if rDatiUiu.fl_posto_auto is null then
          m_supe_c6 := m_supe_c6 + rDatiUiu.supe;
        elsif rDatiUiu.fl_posto_auto = 'C' then
          m_supe_c6_cop := m_supe_c6_cop + rDatiUiu.supe;
        else
          m_supe_c6_scop := m_supe_c6_scop + rDatiUiu.supe;
        end if;
      else
        m_supe_no_c6 := m_supe_no_c6 + rDatiUiu.supe;
      end if;

      m_supe_verde_com := m_supe_verde_com + nvl(rDatiUiu.sup_verde_comune, 0);
      m_supe_escl_god := m_supe_escl_god + nvl(rDatiUiu.sup_escl_god, 0);

    end loop;

    -- Sup. Balconi, terrazze, cantine, soffitte
    select m_supe_balc_sof + nvl(sum(supe_ambiente), 0) into m_supe_balc_sof
      from sitiedi_vani
     where cod_nazionale = rUiu.cod_nazionale and foglio = rUiu.foglio
       and particella = rUiu.particella and sub = rUiu.sub and unimm = rUiu.unimm
       and p_data_lav between data_inizio_val and data_fine_val
       and ambiente in ('D', 'E');
  end loop;

  if m_supe_no_c6 < 46 then
    m_supe_no_c6 := m_supe_no_c6 * 1.2;
  elsif m_supe_no_c6 >= 46 and m_supe_no_c6 <= 70 then
    m_supe_no_c6 := m_supe_no_c6 * 1.1;
  end if;

  select decode(nvl(cor_garage, 0), 0, 1, cor_garage) * m_supe_c6,
         decode(nvl(cor_a_cop, 0), 0, 1, cor_a_cop) * m_supe_c6_cop,
         decode(nvl(cor_a_sco, 0), 0, 1, cor_a_sco) * m_supe_c6_scop,
         decode(nvl(cor_acce, 0), 0, 1, cor_acce) * m_supe_balc_sof,
         decode(nvl(cor_verde, 0), 0, 1, cor_verde) * m_supe_verde_com,
         decode(nvl(cor_godi, 0), 0, 1, cor_godi) * m_supe_escl_god
    into m_supe_c6, m_supe_c6_cop, m_supe_c6_scop, m_supe_balc_sof, m_supe_verde_com, m_supe_escl_god
    from costanti where rownum = 1;

  -- calcolo superfici terreni
  select nvl(sum(area_part), 0) into m_supe_part
	from  sititrkc trkc,
		  (select distinct cod_nazionale, foglio, particella, sub, unimm
	                 from cons_ufre_tab where atto_ini = p_id_atto) t
	where trkc.cod_nazionale = t.cod_nazionale
	and trkc.foglio = t.foglio
	and trkc.particella = t.particella
	and trkc.sub = t.sub
	and trkc.data_aggi <= p_data_lav
	and trkc.data_fine >= p_data_lav;

  m_supe_conv := m_supe_part + m_supe_no_c6 + m_supe_c6 + m_supe_c6_cop + m_supe_c6_scop + m_supe_balc_sof + m_supe_verde_com + m_supe_escl_god;

  return m_supe_conv;

end;
/


DROP FUNCTION SITI_H501.GET_SUPE_DICH;

CREATE OR REPLACE FUNCTION SITI_H501.get_supe_dich(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE,TIPOCOLT IN NUMBER,DEFVAL IN NUMBER) RETURN NUMBER
IS
	CURSOR C1 IS SELECT Sum(SUPE_COLT) FROM SITIUTIL WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND DATA_FINE=To_Date('99991231','YYYYMMDD');
	CURSOR C2 IS SELECT Sum(SUPE_COLT) FROM SITIUTIL A,SITICODS_REGI B WHERE
	COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA
	AND A.COD_REGI=B.COD_REGI AND B.TIPO_COLT=TIPOCOLT AND A.DATA_FINE=To_Date('99991231','YYYYMMDD');

	RETSUP NUMBER(12,3);
BEGIN
	IF TIPOCOLT IS NULL THEN
		OPEN C1;
		FETCH C1 INTO RETSUP;
		IF C1%NOTFOUND THEN RETSUP:=DEFVAL; END IF;
		CLOSE C1;
	ELSE
		OPEN C2;
		FETCH C2 INTO RETSUP;
		IF C2%NOTFOUND THEN RETSUP:=DEFVAL; END IF;
		CLOSE C2;
	END IF;

	RETURN RETSUP;
END GET_SUPE_DICH;
/


DROP FUNCTION SITI_H501.GET_SUPE_FABBR;

CREATE OR REPLACE FUNCTION SITI_H501.get_supe_fabbr (
      codnaz     IN   VARCHAR2,
      fog        IN   NUMBER,
      part       IN   VARCHAR2,
      subal      IN   VARCHAR2,
      datactrl   IN   DATE
   )
      RETURN NUMBER
   IS
      CURSOR c2
      IS
         SELECT SUM (sup_cat)
           FROM sitiuiu
          WHERE cod_nazionale = codnaz
            AND foglio = fog
            AND particella = part
            AND sub = subal
            AND data_inizio_val <= datactrl
            AND data_fine_val >= datactrl;

      supes   NUMBER (11, 2);
   BEGIN
      OPEN c2;

      FETCH c2
       INTO supes;

      CLOSE c2;

      RETURN supes;
   END;
/


DROP FUNCTION SITI_H501.GET_SUPE_GIS;

CREATE OR REPLACE FUNCTION SITI_H501.GET_SUPE_GIS(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE,DEFVAL IN NUMBER) RETURN NUMBER
IS
	CURSOR C1 IS SELECT AREA_PART FROM SITIPART WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND DATA_FINE_VAL >= DATAV AND DATA_INIZIO_VAL <= DATAV;

	RETSUP NUMBER(12,3);
BEGIN
	OPEN C1;
	FETCH C1 INTO RETSUP;
	IF C1%NOTFOUND THEN RETSUP:=DEFVAL; END IF;
	CLOSE C1;

	RETURN RETSUP;
END GET_SUPE_GIS;
/


DROP FUNCTION SITI_H501.GET_SUPE_SUOLO;

