DROP FUNCTION SITI_H501.GET_UC;

CREATE OR REPLACE FUNCTION SITI_H501.get_uc (
   in_cod_nazionale   IN   VARCHAR2,
   in_foglio          IN   NUMBER,
   in_particella      IN   VARCHAR2,
   in_sub             IN   VARCHAR2,
   in_data_rif        IN   DATE DEFAULT TO_DATE ('99991231', 'YYYYMMDD')
)
   RETURN VARCHAR2
IS
   retvalue   VARCHAR2 (3);
   v_sub      VARCHAR2 (3);
BEGIN
   v_sub :=
      get_sub (in_cod_nazionale,
               in_foglio,
               in_particella,
               in_sub,
               in_data_rif
              );

   IF v_sub = in_sub
   THEN
      retvalue := NULL;
   ELSE
      retvalue := REPLACE (in_sub, v_sub, '');
   END IF;

   RETURN retvalue;
END;
/


DROP FUNCTION SITI_H501.IMPO_SITIEDI_FINDEDIFICIO;

CREATE OR REPLACE FUNCTION SITI_H501.impo_sitiedi_findEdificio(pi_strCodiceEdificio VARCHAR2, pi_dtDataInizioVal DATE)
RETURN NUMBER
/*
a.caleffi 2009-12-17

dato il codice dell'edificio ed una data, cerca nella tabella SITIEDI il campo EDIFICI in base
al campo CODICE_EDIFICIO

se trova il record ritorna il suo valore, altrimenti 0
*/
IS

  CURSOR curFindEdificio(pi_strCodiceEdificio VARCHAR2, pi_dtDataInizioVal DATE) IS
  SELECT edificio
  FROM sitiedi
  WHERE codice_edificio = pi_strCodiceEdificio
  AND pi_dtDataInizioVal BETWEEN data_inizio_val AND data_fine_val;

  iRetVal NUMBER;
BEGIN

  iRetVal := 0;

  -- cerco il numero dell'edificio partendo dal codice edificio
  OPEN curFindEdificio(pi_strCodiceEdificio, pi_dtDataInizioVal);

  FETCH curFindEdificio INTO iRetVal;
  IF (curFindEdificio%NOTFOUND) THEN
    iRetVal := 0;
  END IF;

  CLOSE curFindEdificio;

  RETURN iRetVal;
END;

/


DROP FUNCTION SITI_H501.INGOMBRO_APPOGGIO;

CREATE OR REPLACE FUNCTION SITI_H501.INGOMBRO_APPOGGIO(SSO_USER IN VARCHAR2, p_data_lav IN date) RETURN MDSYS.SDO_GEOMETRY
IS
  RETSHP MDSYS.SDO_GEOMETRY;

BEGIN
  RETSHP:=NULL;

   SELECT SDO_AGGR_MBR(shape) INTO RETSHP
	   FROM (
	    SELECT SHAPE FROM sitipart p, sitiappoggio ap1
	     where p.cod_nazionale = ap1.cod_nazionale
	       and p.foglio = ap1.foglio
	       and p.particella = ap1.particella
	       and p.sub = ap1.sub
	       and p.data_inizio_val <= p_data_lav
	       and p.data_fine_val >= p_data_lav
	       and ap1.utente = sso_user
	       and ap1.data_lav = p_data_lav
			 --and ap1.etype = 'P'
			 and p.shape is not null
		 );


  RETURN RETSHP;
END INGOMBRO_APPOGGIO;
/


DROP FUNCTION SITI_H501.INGOMBRO_AZIENDA;

CREATE OR REPLACE FUNCTION SITI_H501.ingombro_azienda(CUAAP IN VARCHAR2,DATAV IN DATE) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  DATAVAL DATE;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;
  DATAVAL:=DATAV;

  IF DATAVAL IS NULL THEN DATAVAL:=To_Date('99991231000000','YYYYMMDDHH24MISS'); END IF;

  IF CUAAP IS NOT NULL THEN
    OPEN C FOR SELECT SDO_AGGR_mbr(SHAPE)
    FROM
    sitifglc
    WHERE
    se_row_id in
    (
      SELECT B.SE_ROW_ID from
      siticond A, SITIFGLC B
      where A.COD_NAZIONALE=B.COD_NAZIONALE AND
      A.FOGLIO=B.FOGLIO AND
      A.CUAA=CUAAP AND
      A.DATA_INIZIO<=DATAVAL AND
      A.DATA_FINE>=DATAVAL
      group by b.se_row_id
    );

    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;
  END IF;

  RETURN RETSHP;
END INGOMBRO_AZIENDA;

/


DROP FUNCTION SITI_H501.INGOMBRO_CIVICO;

CREATE OR REPLACE FUNCTION SITI_H501.INGOMBRO_CIVICO(INPKID_CIVI IN NUMBER, BUFFER IN NUMBER) RETURN MDSYS.SDO_GEOMETRY
IS
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;

  SELECT SDO_GEOM.SDO_MBR(SDO_GEOM.SDO_BUFFER(SHAPE,BUFFER,0.1)) INTO RETSHP FROM SITICIVI WHERE PKID_CIVI=INPKID_CIVI;

  RETURN RETSHP;
END INGOMBRO_CIVICO;
/


DROP FUNCTION SITI_H501.INGOMBRO_FIUME;

CREATE OR REPLACE FUNCTION SITI_H501.INGOMBRO_FIUME(CN IN VARCHAR2, NUMR IN VARCHAR2) RETURN MDSYS.SDO_GEOMETRY
IS
  SHP1 MDSYS.SDO_GEOMETRY;
  SHP2 MDSYS.SDO_GEOMETRY;

  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;

  SELECT SDO_AGGR_MBR(SHAPE)
  INTO SHP1
  FROM SITIDFIU_GRAF
  WHERE NUMERO=NUMR AND COD_NAZIONALE=CN;

  SELECT SDO_AGGR_MBR(C.SHAPE)
  INTO SHP2
  FROM SITIFIUM A, SITIDFIU B,SITIPART C
  WHERE
  A.PKID_FIUM=B.PKID_FIUM AND
  C.COD_NAZIONALE=A.COD_NAZIONALE AND
  C.FOGLIO=A.FOGLIO AND
  C.PARTICELLA=A.PARTICELLA AND
  C.SUB=A.SUB AND
  A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND
  B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND
  C.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND
  C.SHAPE IS NOT NULL AND
  B.COD_NAZIONALE=CN AND
  B.NUMERO=NUMR;

  IF NOT SHP1 IS NULL AND NOT SHP2 IS NULL THEN
    RETSHP:=SDO_GEOM.SDO_UNION(SHP1,SHP2,0.005);
  ELSE
    IF NOT SHP1 IS NULL THEN
      RETSHP:=SHP1;
    END IF;
    IF NOT SHP2 IS NULL THEN
      RETSHP:=SHP2;
    END IF;
  END IF;

  RETURN RETSHP;
END INGOMBRO_FIUME;

/


DROP FUNCTION SITI_H501.INGOMBRO_GENERICO;

CREATE OR REPLACE FUNCTION SITI_H501.INGOMBRO_GENERICO(IN_ISTATR IN NUMBER, IN_ISTATP IN NUMBER, CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE, ERROR OUT NUMBER) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  SUBO VARCHAR2(3);
  DATAVAL DATE;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;
  DATAVAL:=DATAV;
  ERROR:=0;

  IF DATAVAL IS NULL THEN DATAVAL:=TO_DATE('99991231000000','YYYYMMDDHH24MISS'); END IF;

  IF PART IS NOT NULL THEN
    SUBO:=SUBA;
    IF SUBO IS NULL OR TRIM(SUBO)='' THEN SUBO := ' '; END IF;

    OPEN C FOR SELECT SDO_GEOM.SDO_MBR(SHAPE) FROM SITIPART WHERE COD_NAZIONALE=CN AND TAVOLA=FOG AND PARTICELLA=PART AND SUB=SUBO AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=NULL; END IF;
    CLOSE C;

    IF RETSHP IS NULL THEN
      OPEN C FOR SELECT SDO_GEOM.SDO_MBR(SHAPE) FROM SITICENT WHERE COD_NAZIONALE=CN AND TAVOLA=FOG AND PARTICELLA=PART AND SUB=SUBO AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=NULL; END IF;
      CLOSE C;

      IF RETSHP IS NOT NULL THEN
        RETSHP:=SDO_GEOM.SDO_BUFFER(RETSHP,100,0.1);
	  ELSE
	    ERROR:=1;
      END IF;
    END IF;
  END IF;

  IF FOG IS NOT NULL AND RETSHP IS NULL THEN
    OPEN C FOR SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SDO_GEOM.SDO_MBR(SHAPE),0.5)) FROM SITIFGLC WHERE COD_NAZIONALE=CN AND TAVOLA=FOG;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=NULL; ERROR:=1; END IF;
    CLOSE C;
  END IF;

  IF CN IS NOT NULL AND RETSHP IS NULL THEN
      OPEN C FOR SELECT SDO_AGGR_MBR(SHAPE)
      FROM SITICOML
      WHERE (ISTATP,ISTATC) IN (SELECT ISTATP,ISTATC FROM SITICOMU WHERE COD_NAZIONALE=CN);
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=NULL; ERROR:=1; END IF;
      CLOSE C;
  END IF;

  IF IN_ISTATP IS NOT NULL AND RETSHP IS NULL THEN
      OPEN C FOR SELECT SDO_GEOM.SDO_MBR(SHAPE)
      FROM SITIPROV
      WHERE ISTATP=IN_ISTATP;
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=NULL; ERROR:=1; END IF;
      CLOSE C;
  END IF;

  IF IN_ISTATR IS NOT NULL AND RETSHP IS NULL THEN
      OPEN C FOR SELECT SDO_AGGR_MBR(SHAPE)
      FROM SITIREGI
      WHERE ISTATR=IN_ISTATR;
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=NULL; ERROR:=1; END IF;
      CLOSE C;
  END IF;

  RETURN RETSHP;
END INGOMBRO_GENERICO;
/


