DROP FUNCTION SITI_H501.INGOMBRO_PARTICELLA;

CREATE OR REPLACE FUNCTION SITI_H501.ingombro_particella(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE) RETURN MDSYS.SDO_GEOMETRY
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  SUBO VARCHAR2(3);
  DATAVAL DATE;
  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;
  DATAVAL:=DATAV;

  IF DATAVAL IS NULL THEN DATAVAL:=To_Date('99991231000000','YYYYMMDDHH24MISS'); END IF;

  IF PART IS NOT NULL THEN
    SUBO:=SUBA;
    IF SUBO IS NULL OR TRIM(SUBO)='' THEN SUBO := ' '; END IF;

    OPEN C FOR SELECT /*+ INDEX (SITIPART SITIPART_PK) */ SDO_GEOM.SDO_MBR(SHAPE) FROM SITIPART WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;

    IF RETSHP IS NULL THEN
      OPEN C FOR SELECT /*+ INDEX (SITICENT SITICENT_PK) */ SDO_GEOM.SDO_MBR(SHAPE) FROM SITICENT WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO AND DATA_INIZIO_VAL <= DATAVAL AND DATA_FINE_VAL >= DATAVAL AND ROWNUM=1;
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=null; END IF;
      CLOSE C;

      IF RETSHP IS NOT NULL THEN
       -- Serve l'MBR xchè DbMAP non supporta le geometri ARC di Oracle
        RETSHP:=SDO_GEOM.SDO_MBR(SDO_GEOM.SDO_BUFFER(RETSHP,100,0.1));
      END IF;
    END IF;
  END IF;

  IF FOG IS NOT NULL AND RETSHP IS NULL THEN
    OPEN C FOR SELECT SDO_AGGR_UNION(mdsys.sdoaggrtype(sdo_geom.sdo_mbr(SHAPE),0.5)) FROM SITIFGLC WHERE COD_NAZIONALE=CN AND FOGLIO=FOG;
    FETCH C INTO RETSHP;
    IF C%NOTFOUND THEN RETSHP:=null; END IF;
    CLOSE C;
  END IF;

  IF CN IS NOT NULL AND RETSHP IS NULL THEN
      OPEN C FOR SELECT SDO_AGGR_MBR(SHAPE)
      FROM SITICOML
      WHERE (ISTATP,ISTATC) IN (SELECT ISTATP,ISTATC FROM SITICOMU WHERE COD_NAZIONALE=CN);
      FETCH C INTO RETSHP;
      IF C%NOTFOUND THEN RETSHP:=null; END IF;
      CLOSE C;
  END IF;

  RETURN RETSHP;
END INGOMBRO_PARTICELLA;
/


DROP FUNCTION SITI_H501.INGOMBRO_STRADA;

CREATE OR REPLACE FUNCTION SITI_H501.ingombro_strada(CN IN VARCHAR2, NUMR IN VARCHAR2) RETURN MDSYS.SDO_GEOMETRY
IS
  SHP1 MDSYS.SDO_GEOMETRY;
  SHP2 MDSYS.SDO_GEOMETRY;

  RETSHP MDSYS.SDO_GEOMETRY;
BEGIN
  RETSHP:=NULL;

  SELECT SDO_AGGR_MBR(SHAPE)
  INTO SHP1
  FROM SITIDSTR_GRAF
  WHERE NUMERO=NUMR AND COD_NAZIONALE=CN;

  SELECT SDO_AGGR_MBR(C.SHAPE)
  INTO SHP2
  FROM sitistra A, sitidstr B,SITIPART C
  WHERE
  A.PKID_STRA=B.PKID_STRA AND
  C.COD_NAZIONALE=A.COD_NAZIONALE AND
  C.FOGLIO=A.FOGLIO AND
  C.PARTICELLA=A.PARTICELLA AND
  C.SUB=A.SUB AND
  A.DATA_FINE_VAL=To_Date('99991231000000','YYYYMMDDHH24MISS') AND
  B.DATA_FINE_VAL=To_Date('99991231000000','YYYYMMDDHH24MISS') AND
  C.DATA_FINE_VAL=To_Date('99991231000000','YYYYMMDDHH24MISS') AND
  C.SHAPE IS NOT NULL AND
  B.COD_NAZIONALE=CN AND
  B.NUMERO=NUMR;

  IF NOT SHP1 IS NULL AND NOT SHP2 IS NULL THEN
    RETSHP:=SDO_GEOM.SDO_UNION(SHP1,SHP2,0.005);
  ELSE
    IF NOT SHP1 IS NULL THEN
      RETSHP:=SHP1;
    END IF;
    IF NOT SHP2 IS NULL THEN
      RETSHP:=SHP2;
    END IF;
  END IF;

  RETURN RETSHP;
END INGOMBRO_STRADA;

/


