DROP FUNCTION SITI_H501.INGOMBRO_TOPONIMO;

CREATE OR REPLACE FUNCTION SITI_H501.ingombro_toponimo (pkid IN NUMBER, buffer IN NUMBER)
  RETURN MDSYS.SDO_GEOMETRY IS
  shape_topo      MDSYS.SDO_GEOMETRY;
  shapelim_topo   MDSYS.SDO_GEOMETRY;
  retshp          MDSYS.SDO_GEOMETRY;
  area            NUMBER             := 0;
BEGIN
  retshp := NULL;

  IF pkid > 0 THEN
    SELECT shape, shapelim
      INTO shape_topo, shapelim_topo
      FROM sititopo
     WHERE se_row_id = pkid;

    IF shapelim_topo IS NOT NULL THEN
      retshp := shapelim_topo;
      area := MDSYS.sdo_geom.sdo_area (shapelim_topo, 0.5);
    END IF;

    IF shape_topo IS NOT NULL AND area < 1 THEN
      retshp := sdo_geom.sdo_mbr (sdo_geom.sdo_buffer (shape_topo, buffer, 0.5));
    END IF;
  END IF;

  RETURN retshp;
END ingombro_toponimo;
/


