DROP FUNCTION SITI_H501.IS_NUMBER;

CREATE OR REPLACE function SITI_H501.is_number(str in varchar2) return char is
    i     pls_integer;
  begin
    for i in 1..length(str) loop
      if instr('0123456789', substr(str, i, 1)) = 0 then
        return 'N';
      end if;
    end loop;
    return 'Y';
  end is_number;
/


DROP FUNCTION SITI_H501.IS_NUMERIC;

CREATE OR REPLACE function SITI_H501.is_numeric(str in varchar2) return boolean is
    i     pls_integer;
  begin

    for i in 1..length(str) loop
      if instr('0123456789', substr(str, i, 1)) = 0 then
        return false;
      end if;
    end loop;

    return true;
  end is_numeric;
/


