DROP FUNCTION SITI_H501.NUMBER_FROM_STRING;

CREATE OR REPLACE FUNCTION SITI_H501.number_from_string(STR IN VARCHAR2) RETURN integer
IS
ANUM INTEGER:=0;
TMPS VARCHAR2(20);
S VARCHAR2(20);
I INTEGER :=1;
BEGIN
  IF STR ='' OR STR IS NULL THEN
    ANUM:=0;
  ELSE
    S:=TRIM(STR);
    LOOP
      IF Ascii(SUBSTR(S,I,1))>=Ascii('0') and Ascii(SUBSTR(S,I,1))<=Ascii('9') THEN
        TMPS:=TMPS || SUBSTR(S,I,1);
        S:=SUBSTR(S,I+1);
      ELSE
        EXIT;
      END IF;
    END LOOP;

    IF TMPS ='' OR TMPS IS NULL THEN
      ANUM:=0;
    else
      ANUM:=To_Number(TMPS);
    END IF;
  END IF;
  RETURN ANUM;
END;

/


DROP FUNCTION SITI_H501.PART_INTERSECA;

CREATE OR REPLACE FUNCTION SITI_H501.part_interseca(PID IN NUMBER, CN IN VARCHAR2, FG IN NUMBER, PT IN VARCHAR2, SB IN VARCHAR2, DL IN DATE) RETURN NUMBER
IS
--  TYPE EMPTYCUR IS REF CURSOR;
--  C EMPTYCUR;
--  C2 EMPTYCUR;

  SHP MDSYS.SDO_GEOMETRY;
  DATAL DATE;
  NP NUMBER(9);
  RV NUMBER(9);
BEGIN
  RV:=0;
  IF DL IS NULL THEN
    DATAL:=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
  ELSE
    DATAL:=DL;
  END IF;

  SELECT sdo_tools.cleanup(SHAPE) INTO SHP FROM SITIPART WHERE SE_ROW_ID = PID AND SHAPE IS NOT NULL;

  IF SHP IS NOT NULL THEN
      SELECT 1
      INTO NP
      FROM SITIPART
      WHERE cod_nazionale=CN AND
      foglio=FG AND
      (particella <> PT OR sub <> SB) AND
      DATA_INIZIO_VAL<=To_Date('99991231000000','YYYYMMDDHH24MISS') AND
      DATA_FINE_VAL>=To_Date('99991231000000','YYYYMMDDHH24MISS') AND
      SHAPE IS NOT NULL AND
      SDO_FILTER(SHAPE,SHP,'querytype=WINDOW')='TRUE' AND
      SDO_RELATE(SHAPE,SHP, 'MASK=INSIDE+EQUAL QUERYTYPE=WINDOW')<>'FALSE' AND
      ROWNUM=1;

      IF NP<>0 THEN
        RV:=1;
      ELSE
        SELECT 1
        INTO NP
        FROM SITIPART
        WHERE cod_nazionale=CN AND
        foglio=FG AND
        (particella <> PT OR sub <> SB) AND
        DATA_INIZIO_VAL<=To_Date('99991231000000','YYYYMMDDHH24MISS') AND
        DATA_FINE_VAL>=To_Date('99991231000000','YYYYMMDDHH24MISS') AND
        SHAPE IS NOT NULL AND
        SDO_FILTER(SHAPE,SHP,'querytype=WINDOW')='TRUE' AND
        SDO_RELATE(SHAPE,SHP, 'MASK=OVERLAPBDYINTERSECT QUERYTYPE=WINDOW')<>'FALSE' AND
        ROWNUM=1;
        IF NP<>0 THEN
          RV:=2;
        END IF;
      END IF;
    END IF;
  RETURN RV;

END PART_INTERSECA;

/


DROP FUNCTION SITI_H501.PART_RELATE;

CREATE OR REPLACE FUNCTION SITI_H501.part_relate(CN IN VARCHAR2, FG IN NUMBER, PT IN VARCHAR2, SB IN VARCHAR2, DL IN DATE) RETURN NUMBER
IS

  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  DATAL DATE;
  NP NUMBER;
  RV NUMBER;

BEGIN

  RV:=0;
  IF DL IS NULL THEN
    DATAL:=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
  ELSE
    DATAL:=DL;
  END IF;
  OPEN C FOR SELECT COUNT(*) FROM SITIPART A, SITIPART B WHERE A.COD_NAZIONALE=B.COD_NAZIONALE AND A.FOGLIO=B.FOGLIO AND (A.PARTICELLA<>B.PARTICELLA OR A.SUB<>B.SUB) AND A.DATA_INIZIO_VAL<=DATAL AND A.DATA_FINE_VAL>=DATAL AND B.DATA_INIZIO_VAL<=DATAL AND B.DATA_FINE_VAL>=DATAL AND SDO_RELATE(A.SHAPE, B.SHAPE, 'MASK=CONTAINS QUERYTYPE=WINDOW')='TRUE' AND A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.PARTICELLA=PT AND A.SUB=SB;
  FETCH C INTO NP;
  IF C%NOTFOUND THEN NP:=0; END IF;
  CLOSE C;
  IF NP>0 THEN
    RV:=1; -- La particella contiene altre particelle.
  ELSE
    OPEN C FOR SELECT COUNT(*) FROM SITIPART A, SITIPART B WHERE A.COD_NAZIONALE=B.COD_NAZIONALE AND A.FOGLIO=B.FOGLIO AND (A.PARTICELLA<>B.PARTICELLA OR A.SUB<>B.SUB) AND A.DATA_INIZIO_VAL<=DATAL AND A.DATA_FINE_VAL>=DATAL AND B.DATA_INIZIO_VAL<=DATAL AND B.DATA_FINE_VAL>=DATAL AND SDO_RELATE(A.SHAPE, B.SHAPE, 'MASK=OVERLAPBDYINTERSECT QUERYTYPE=WINDOW')='TRUE' AND A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.PARTICELLA=PT AND A.SUB=SB;
    FETCH C INTO NP;
    IF C%NOTFOUND THEN NP:=0; END IF;
    CLOSE C;
    IF NP>0 THEN RV:=2; END IF; -- La particella interseca altre particelle.
  END IF;
  RETURN RV;

END PART_RELATE;

/


DROP FUNCTION SITI_H501.PART_RELATE2;

CREATE OR REPLACE FUNCTION SITI_H501.PART_RELATE2(PID IN NUMBER, CN IN VARCHAR2, FG IN NUMBER, PT IN VARCHAR2, SB IN VARCHAR2, DL IN DATE) RETURN NUMBER
IS

  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  DATAL DATE;
  NP NUMBER;
  RV NUMBER;

BEGIN

  RV:=0;
  IF DL IS NULL THEN
    DATAL:=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
  ELSE
    DATAL:=DL;
  END IF;
  OPEN C FOR SELECT COUNT(*) FROM SITIPART A, (SELECT * FROM SITIPART B WHERE B.SE_ROW_ID=PID) B WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND (A.PARTICELLA<>PT OR A.SUB<>SB) AND A.DATA_INIZIO_VAL<=DATAL AND A.DATA_FINE_VAL>=DATAL AND SDO_RELATE(B.SHAPE, A.SHAPE, 'MASK=CONTAINS QUERYTYPE=WINDOW')='TRUE';
  FETCH C INTO NP;
  IF C%NOTFOUND THEN NP:=0; END IF;
  CLOSE C;
  IF NP>0 THEN
    RV:=1; -- La particella contiene altre particelle.
  ELSE
    OPEN C FOR SELECT COUNT(*) FROM SITIPART A, (SELECT * FROM SITIPART B WHERE B.SE_ROW_ID=PID) B WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND (A.PARTICELLA<>PT OR A.SUB<>SB) AND A.DATA_INIZIO_VAL<=DATAL AND A.DATA_FINE_VAL>=DATAL AND SDO_RELATE(B.SHAPE, A.SHAPE, 'MASK=OVERLAPBDYINTERSECT QUERYTYPE=WINDOW')='TRUE';
    FETCH C INTO NP;
    IF C%NOTFOUND THEN NP:=0; END IF;
    CLOSE C;
    IF NP>0 THEN RV:=2; END IF; -- La particella interseca altre particelle.
  END IF;
  RETURN RV;

END PART_RELATE2;

/


DROP FUNCTION SITI_H501.REMOVE_CHARS;

CREATE OR REPLACE function SITI_H501.remove_chars(orig varchar2, unwanted_chars varchar2) return varchar2 is
  res   varchar2(32000);
  c     char;
begin
  
  for i in 1 .. length(orig) loop
    if instr(unwanted_chars, c) <= 0 then
      res := res + c;
    end if;
  end loop;
  
  return(res);
end remove_chars;
/


DROP FUNCTION SITI_H501.REMOVE_LEAD_ZERO;

CREATE OR REPLACE FUNCTION SITI_H501.remove_lead_zero (STR IN VARCHAR2) RETURN VARCHAR2
IS
I INTEGER :=1;
S VARCHAR2(2048);
BEGIN
  IF STR ='' OR STR IS NULL THEN
    S:=NULL;
  ELSE
    S:=TRIM(STR);
    LOOP
      IF SUBSTR(S,I,1)='0' THEN
        S:=SUBSTR(S,I+1);
      ELSE
        EXIT;
      END IF;
    END LOOP;
  END IF;
  RETURN S;
END;

/


DROP FUNCTION SITI_H501.REPORTDAMAGEISLAND;

CREATE OR REPLACE FUNCTION SITI_H501.reportdamageisland(SHPorg IN MDSYS.SDO_GEOMETRY) RETURN number
IS
  SHPtmp MDSYS.SDO_GEOMETRY;
  NumElem number;
  RETVAL NUMBER := 0;
  i NUMBER;

BEGIN
  i:=1;
  NumElem:=sdo_tools.get_num_elements(SHPorg);
  WHILE i<=NumElem LOOP
    SHPtmp:=sdo_tools.get_element(SHPorg,i);
    IF NOT (sdo_tools.get_num_points(SHPtmp)>=4 OR sdo_tools.get_num_points(SHPtmp)=0) THEN
        RETVAL:=RETVAL + 1;
    END IF;
    i:=i+1;
  END LOOP;
  RETURN RETVAL;
END ReportDamageIsland;

/


