DROP FUNCTION SITI_H501.STATO_CENS;

CREATE OR REPLACE FUNCTION SITI_H501.stato_cens(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,DATAV IN DATE) RETURN NUMBER
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  SUBO VARCHAR2(3);
  DATAVAL DATE;
  RETSTATO NUMBER:=0;
BEGIN
  DATAVAL:=DATAV;

  IF DATAVAL IS NULL THEN DATAVAL:=TO_DATE('99991231000000','YYYYMMDDHH24MISS'); END IF;

  SUBO:=SUBA;
  IF SUBO IS NULL OR TRIM(SUBO)='' THEN SUBO := ' '; END IF;

  OPEN C FOR SELECT 2 FROM SITICATA WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO AND DATA_INIZIO <= DATAVAL AND DATA_FINE >= DATAVAL AND ROWNUM=1;
  FETCH C INTO RETSTATO;
  IF C%NOTFOUND THEN RETSTATO:=0; END IF;
  CLOSE C;

  IF RETSTATO = 0 THEN
    OPEN C FOR SELECT 1 FROM SITICATA WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO AND DATA_INIZIO <= DATAVAL AND ROWNUM=1;
    FETCH C INTO RETSTATO;
    IF C%NOTFOUND THEN RETSTATO:=0; END IF;
    CLOSE C;
  END IF;

  RETURN RETSTATO;
END STATO_CENS;
/


