DROP FUNCTION SITI_H501.STATO_GIS_BASE;

CREATE OR REPLACE FUNCTION SITI_H501.stato_gis_base (
   cn      IN   VARCHAR2,
   fog     IN   NUMBER,
   part    IN   VARCHAR2,
   suba    IN   VARCHAR2,
   datav   IN   DATE
)
   RETURN NUMBER
IS
   TYPE emptycur IS REF CURSOR;

   c          emptycur;
   subo       VARCHAR2 (3);
   dataval    DATE;
   retstato   NUMBER       := 0;
BEGIN
   dataval := datav;

   IF dataval IS NULL
   THEN
      dataval := TO_DATE ('99991231000000', 'YYYYMMDDHH24MISS');
   END IF;

   subo := suba;

   IF subo IS NULL OR TRIM (subo) = ''
   THEN
      subo := ' ';
   END IF;

   OPEN c FOR
      SELECT /*+ INDEX (SITIPART SITIPART_PK) */
             2
        FROM sitipart
       WHERE cod_nazionale = cn
         AND foglio = fog
         AND particella = part
         AND sub = subo
         AND data_inizio_val <= dataval
         AND data_fine_val >= dataval
         AND ROWNUM = 1;

   FETCH c
    INTO retstato;

   IF c%NOTFOUND
   THEN
      retstato := 0;
   END IF;

   CLOSE c;

   IF retstato = 0
   THEN
      OPEN c FOR
         SELECT /*+ INDEX (SITICENT SITICENT_PK) */
                1
           FROM siticent
          WHERE cod_nazionale = cn
            AND foglio = fog
            AND particella = part
            AND sub = subo
            AND data_inizio_val <= dataval
            AND data_fine_val >= dataval
            AND ROWNUM = 1;

      FETCH c
       INTO retstato;

      IF c%NOTFOUND
      THEN
         retstato := 0;
      END IF;

      CLOSE c;
   END IF;

   RETURN retstato;
END stato_gis_base;
/


DROP FUNCTION SITI_H501.STATO_PLAV;

CREATE OR REPLACE FUNCTION SITI_H501.stato_plav(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,IDLAV IN NUMBER) RETURN NUMBER
-- Ritorna:
-- 0 Non in elenco
-- 1 In lavorazione
-- 2 Lavorata
-- 3 Sospesa
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;

  SUBO VARCHAR2(3);
  DL DATE;
  DS DATE;
  RETSTATO NUMBER:=0;
BEGIN
  SUBO:=SUBA;
  IF SUBO IS NULL OR TRIM(SUBO)='' THEN SUBO := ' '; END IF;
  IF IDLAV IS NOT NULL THEN
    OPEN C FOR SELECT DATASOSP,DATA_LAV,1 FROM SITIPLAV WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO AND LAST=1 AND ID_LAV=IDLAV;
  ELSE
    OPEN C FOR SELECT DATASOSP,DATA_LAV,1 FROM SITIPLAV WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBO AND LAST=1;
  END IF;
  FETCH C INTO DS,DL,RETSTATO;
  IF C%NOTFOUND THEN     RETSTATO:=0;     DL:=NULL;   END IF;
  CLOSE C;
  IF DL IS NOT NULL THEN     RETSTATO:=2;  END IF;
  IF DS IS NOT NULL THEN     RETSTATO:=3;  END IF;

  RETURN RETSTATO;
END STATO_PLAV;
/


DROP FUNCTION SITI_H501.STATO_SUOLO_PROMISCUO;

CREATE OR REPLACE FUNCTION SITI_H501.stato_suolo_promiscuo(CN IN VARCHAR2, FOG IN NUMBER,PART IN VARCHAR2,SUBA IN VARCHAR2,PPOL IN NUMBER,DATAV IN DATE) RETURN VARCHAR2
IS
  GRUPPOLY NUMBER(9);

  CURSOR C1 IS SELECT COUNT(*) FROM SITIUNAR WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND GRUPPO=GRUPPOLY AND DATA_INIZIO_VAL <= DATAV AND DATA_FINE_VAL >= DATAV;

  CURSOR C2 IS SELECT A.GRUPPO,A.COD_VARIeta,B.TIPO_UNAR FROM SITISUOLO A,SITICODS_VARI B WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND PROG_POLIGONO=PPOL AND DATA_INIZIO_VAL <= DATAV AND DATA_FINE_VAL >= DATAV AND B.COD_VARI(+)=A.COD_VARIETA;

  TUNAR NUMBER(9);

  CURSOR C3 IS SELECT COUNT(*) FROM SITIUNAR WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND GRUPPO=GRUPPOLY AND DATA_INIZIO_VAL <= DATAV AND DATA_FINE_VAL >= DATAV AND TIPO_UNAR=TUNAR;

  CURSOR C4 IS SELECT Count(*) FROM (SELECT TIPO_UNAR FROM SITIUNAR WHERE COD_NAZIONALE=CN AND FOGLIO=FOG AND PARTICELLA=PART AND SUB=SUBA AND GRUPPO=GRUPPOLY AND DATA_INIZIO_VAL <= DATAV AND DATA_FINE_VAL >= DATAV GROUP BY TIPO_UNAR);

  NTIPI NUMBER(9);
  NUNAR NUMBER(9);
  NUNAR_TIPO NUMBER(9);
  CVARI NUMBER(9);
BEGIN
  OPEN C2;
  FETCH C2 INTO GRUPPOLY,CVARI,TUNAR;
  IF C2%NOTFOUND THEN GRUPPOLY:=NULL;CVARI:=NULL;TUNAR:=0; END IF;
  CLOSE C2;

  OPEN C1;
  FETCH C1 INTO NUNAR;
  CLOSE C1;

  IF NUNAR=0 OR CVARI IS NULL THEN
    --NON HO UNAR SU QUESTO POLIGONO
    RETURN 'A';
  ELSE
    OPEN C3;
    FETCH C3 INTO NUNAR_TIPO;
    CLOSE C3;

    IF NUNAR=NUNAR_TIPO THEN
      --SONO TUTTE DELLO STESSO TIPO
      RETURN 'B';
    ELSE
      OPEN C4;
      FETCH C4 INTO NTIPI;
      CLOSE C4;

      IF NTIPI = 1 THEN
        --HO SOLO 1 TIPO DI UNAR SU DI UN POLIGONO NON COMPATIBILE
        RETURN 'C';
      ELSE
        IF TUNAR>0 THEN --CVARI=685 THEN
          --HO + TIPI DI UNAR SU DI UN POLIGONO PROMISCUO
          RETURN 'D';
        ELSE
          --HO + TIPI DI UNAR SU DI UN POLIGONO NON PROMISCUO
          RETURN 'E';
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN 'A';
END STATO_SUOLO_PROMISCUO;
/


DROP FUNCTION SITI_H501.UNFORMATFOGLIO;

CREATE OR REPLACE FUNCTION SITI_H501.UNFORMATFOGLIO (STR IN VARCHAR2) RETURN NUMBER
IS
	RETVAL NUMBER(4);
BEGIN
	RETVAL := TO_NUMBER(SubStr(STR,1,1),'X') * 100 + To_Number(SubStr(STR,2));

	RETURN RETVAL;
END;
/


