DROP PROCEDURE VIRGILIO_H501.CORREGGI_ID_NOTA;

CREATE OR REPLACE PROCEDURE VIRGILIO_H501.CORREGGI_ID_NOTA IS
BEGIN

    DECLARE
    CURSOR CUR_FOR IS 
        SELECT DISTINCT B.IID_FORNITURA FROM MI_DUP_NOTA_TRAS B
        GROUP BY B.IID_FORNITURA, B.ID_NOTA
        HAVING COUNT(*) > 1;


    upd varchar2(2000);

    BEGIN
        FOR REC_FOR IN CUR_FOR LOOP
        
            declare
                cursor CUR_NOTA IS 
                SELECT ID_NOTA, IID FROM MI_DUP_NOTA_TRAS
                WHERE IID_FORNITURA = REC_FOR.IID_FORNITURA
                FOR UPDATE OF ID_NOTA;


                CURSOR CUR_TAB IS
                   select DISTINCT 
                    TABLE_NAME from COLS where column_name = 'ID_NOTA' AND TABLE_NAME like 'MI_%'
                    and table_name <> 'MI_DUP_NOTA_TRAS';
                                        
                v_id_nota number;
            
            begin
                v_id_nota := 1;
                FOR REC_NOTA IN CUR_NOTA LOOP
                
                    FOR REC_TAB IN CUR_TAB LOOP
                        
                         begin   
                             upd := 'UPDATE ' || REC_TAB.TABLE_NAME || ' SET ID_NOTA= :V_ID_NOTA WHERE IID_NOTA= :V_IID_NOTA';  
                
                            -- DBMS_OUTPUT.PUT_LINE(UPD || '(' || V_ID_NOTA || ','|| REC_NOTA.IID || ')');
                             EXECUTE IMMEDIATE upd USING V_ID_NOTA, REC_NOTA.IID;
                         exception
                         when  others then
                         DBMS_OUTPUT.PUT_LINE('errore update tabella' || REC_TAB.TABLE_NAME);
                         end;
    
                         update MI_DUP_NOTA_TRAS set ID_NOTA=v_id_nota where IID = REC_NOTA.IID;
                          

                    END LOOP;
                    

                                    
                    v_id_nota := v_id_nota +1;
                END LOOP;
            
            
            
            
            end;
            
        DBMS_OUTPUT.PUT_LINE('finita fornitura ' || REC_FOR.IID_FORNITURA);
        END LOOP;
        commit;
    END;
END;
/


DROP PROCEDURE VIRGILIO_H501.CREA_IDX_SPATIAL;

CREATE OR REPLACE PROCEDURE VIRGILIO_H501.crea_idx_spatial(TABELLA IN VARCHAR2,CAMPO_SHAPE IN VARCHAR2,TABLESPACE_DEST IN VARCHAR2,NOMEINDICE IN VARCHAR2)
AUTHID CURRENT_USER
IS
CURSOR C1 IS SELECT 1 FROM USER_INDEXES WHERE Upper(INDEX_NAME)=UPPER(NOMEINDICE);
ESISTE NUMBER(1);
BEGIN
DELETE FROM USER_SDO_GEOM_METADATA WHERE UPPER(TABLE_NAME)=UPPER(TABELLA) AND UPPER(COLUMN_NAME)=UPPER(CAMPO_SHAPE);
INSERT INTO USER_SDO_GEOM_METADATA (TABLE_NAME, COLUMN_NAME, DIMINFO) VALUES (TABELLA, CAMPO_SHAPE ,MDSYS.SDO_DIM_ARRAY(MDSYS.SDO_DIM_ELEMENT('X', 1313328, 2820083, 0.0050),MDSYS.SDO_DIM_ELEMENT('Y', 3930191, 5220322.5, 0.0050)));
COMMIT;

OPEN C1;
FETCH C1 INTO ESISTE;
IF C1%NOTFOUND THEN ESISTE:=0; END IF;
CLOSE C1;

IF ESISTE=1 THEN
EXECUTE IMMEDIATE 'DROP INDEX ' || NOMEINDICE;
END IF;
IF TABLESPACE_DEST IS NOT NULL THEN
EXECUTE IMMEDIATE 'CREATE INDEX ' || NOMEINDICE || ' ON ' || TABELLA || '(' || CAMPO_SHAPE || ') INDEXTYPE IS MDSYS.SPATIAL_INDEX PARAMETERS(''tablespace=' || TABLESPACE_DEST || ''')';
ELSE
EXECUTE IMMEDIATE 'CREATE INDEX ' || NOMEINDICE || ' ON ' || TABELLA || '(' || CAMPO_SHAPE || ') INDEXTYPE IS MDSYS.SPATIAL_INDEX';
END IF;
END;
/

DROP PROCEDURE RE_ROMA.AGGIORNA_DB_RE_RIF;

CREATE OR REPLACE PROCEDURE RE_ROMA.AGGIORNA_DB_RE_RIF  IS
    tmpVar NUMBER;
    V_SQL VARCHAR2(1000);

        CURSOR C_COMMAND IS 
       SELECT 'INSERT INTO R_COMMAND git VALUES (''' || ID  || ''',''' || DESCR || ''',''' || SYSTEM_COMMAND || ''',''' || LONG_DESCR || ''',''' || FK_COMMAND_TYPE || ''',''' || COD_COMMAND  || ''');' SQLSTRING
        FROM RE_F704_GIT.R_COMMAND DEV
        WHERE NOT EXISTS (SELECT 1 FROM R_COMMAND GIT1 WHERE GIT1.COD_COMMAND = DEV.COD_COMMAND);

        CURSOR C_FONTECOM IS 
       SELECT 'INSERT INTO R_FONTEDATI_COMMAND git VALUES (''' || FK_COMMAND  || ''',''' || ID_FONTE  || ''');' SQLSTRING
        FROM RE_F704_GIT.R_FONTEDATI_COMMAND DEV
        WHERE NOT EXISTS (SELECT 1 FROM R_FONTEDATI_COMMAND GIT1 WHERE GIT1.FK_COMMAND = DEV.FK_COMMAND AND GIT1.ID_FONTE = DEV.ID_FONTE );
 
        CURSOR C_RULE IS 
       SELECT 'INSERT INTO R_RULE git VALUES (''' || ID  || ''',' || 'TO_DATE(''' || TO_CHAR(DATE_START,'DD-MM-YYYY') || ''',''DD-MM-YYYY'')  ,' || 'TO_DATE(''' || TO_CHAR(DATE_END,'DD-MM-YYYY') || ''',''DD-MM-YYYY'')  ,''' || CLASS_NAME || ''',''' || FK_COMMAND  || ''');' SQLSTRING
        FROM RE_F704_GIT.R_RULE DEV
        WHERE NOT EXISTS (SELECT 1 FROM R_RULE GIT1 WHERE GIT1.ID = DEV.ID);

        CURSOR C_CHAIN IS 
       SELECT 'INSERT INTO R_CHAIN git VALUES (''' || ID  || ''',' || 'TO_DATE(''' || TO_CHAR(DATE_START,'DD-MM-YYYY') || ''',''DD-MM-YYYY'')  ,' || 'TO_DATE(''' || TO_CHAR(DATE_END,'DD-MM-YYYY') || ''',''DD-MM-YYYY'')  ,''' ||  FK_COMMAND || ''',''' || COMMAND_ON_EXIT  || ''');' SQLSTRING
        FROM RE_F704_GIT.R_CHAIN DEV
        WHERE NOT EXISTS (SELECT 1 FROM R_CHAIN GIT1 WHERE GIT1.ID = DEV.ID);

        CURSOR C_DIA IS 
       SELECT 'INSERT INTO DIA_CATALOGO git VALUES (''' || IDCATALOGODIA  || ''',''' || FK_COD_COMMAND_GROUP || ''',''' || DESCRIZIONE || ''',''' || SQLCOMMANDPROP || ''',''' || TOOLTIPTEXT ||  ''',''' ||  ABILITATA || ''',''' ||  FK_COD_COMMAND || ''',''' ||  CLASS_TYPE_DIA_NON_STD || ''');' SQLSTRING
        FROM RE_F704_GIT.DIA_CATALOGO DEV
        WHERE NOT EXISTS (SELECT 1 FROM DIA_CATALOGO GIT1 WHERE GIT1.IDCATALOGODIA = DEV.IDCATALOGODIA);

        CURSOR C_ENTE_ESCL IS 
       SELECT 'INSERT INTO R_ENTE_ESCLUSIONI git VALUES (''' || FK_COMMAND  || ''',''' || ENTE_ON || ''',''' || ENTE_OFF  || ''');' SQLSTRING
        FROM RE_F704_GIT.R_ENTE_ESCLUSIONI DEV
        WHERE NOT EXISTS (SELECT 1 FROM R_ENTE_ESCLUSIONI GIT1 WHERE GIT1.FK_COMMAND = DEV.FK_COMMAND);


        CURSOR C_ANAGSTATI IS 
       SELECT 'INSERT INTO R_ANAG_STATI git VALUES (''' || ID  || ''',''' || DESCR || ''',''' || FK_COMMAND_TYPE   || ''',''' ||  TIPO || ''');' SQLSTRING
        FROM RE_F704_GIT.R_ANAG_STATI DEV
        WHERE NOT EXISTS (SELECT 1 FROM R_ANAG_STATI GIT1 WHERE GIT1.ID = DEV.ID);
       
       
       
               CURSOR C_CMDTYPE IS 
       SELECT 'INSERT INTO R_COMMAND_TYPE git VALUES (''' || ID  || ''',''' || DESCR  || ''');' SQLSTRING
        FROM RE_F704_GIT.R_COMMAND_TYPE DEV
        WHERE NOT EXISTS (SELECT 1 FROM R_COMMAND_TYPE GIT1 WHERE GIT1.ID = DEV.ID); 
        
    CURSOR C_UPDCATALOGO IS 
        SELECT 'UPDATE DIA_CATALOGO_TIPOINFO SET (IDCATALOGODIA, DES_PROPERTIES_FIND , DES_BEAN_CLASSNAME, DES_BEAN_PROPERTIES, DESCRIZIONE, INFORMAZIONE, FK_AM_FONTE ) = ( SELECT ''' || 
        DEV.IDCATALOGODIA || ''',''' || DEV.DES_PROPERTIES_FIND || ''',''' || DEV.DES_BEAN_CLASSNAME || ''',''' || DEV.DES_BEAN_PROPERTIES || ''',''' || DEV.DESCRIZIONE || ''',''' || DEV.INFORMAZIONE || ''',''' || DEV.FK_AM_FONTE || ''' FROM DUAL)'  ||
        ' WHERE ID = ''' || GIT.ID  || ''' ;' AS SQLSTRING
        FROM RE_F704_GIT.DIA_CATALOGO_TIPOINFO DEV, DIA_CATALOGO_TIPOINFO  GIT
        WHERE DEV.ID = GIT.ID;
                
        
       CURSOR C_DIACTIPOINFO IS 
       SELECT 'INSERT INTO DIA_CATALOGO_TIPOINFO git VALUES (''' || ID  || ''',''' || IDCATALOGODIA  || ''',''' ||  DES_PROPERTIES_FIND || ''',''' ||  DES_BEAN_CLASSNAME || ''',''' ||  DES_BEAN_PROPERTIES || ''',''' ||  DESCRIZIONE || ''',''' ||  INFORMAZIONE 
       || ''',''' ||  FK_AM_FONTE || ''');' SQLSTRING
        FROM RE_F704_GIT.DIA_CATALOGO_TIPOINFO DEV
        WHERE NOT EXISTS (SELECT 1 FROM DIA_CATALOGO_TIPOINFO GIT1 WHERE GIT1.ID = DEV.ID); 
        
        
        
    BEGIN

  
    
    FOR R_COM IN C_COMMAND LOOP
        DBMS_OUTPUT.PUT_LINE (R_COM.SQLSTRING);
    END LOOP;
    
    
        FOR R_FONTECOM IN C_FONTECOM LOOP
        DBMS_OUTPUT.PUT_LINE (R_FONTECOM.SQLSTRING);
    END LOOP;
 

        FOR R_RULE IN C_RULE LOOP
        DBMS_OUTPUT.PUT_LINE (R_RULE.SQLSTRING);
    END LOOP;
    
    
        FOR RR_CHAIN IN C_CHAIN LOOP
        DBMS_OUTPUT.PUT_LINE (RR_CHAIN.SQLSTRING);
    END LOOP;    
    
    
            FOR RR_DIA IN C_DIA LOOP
        DBMS_OUTPUT.PUT_LINE (RR_DIA.SQLSTRING);
    END LOOP;    
    
                FOR R_ENTE_ESCL IN C_ENTE_ESCL LOOP
        DBMS_OUTPUT.PUT_LINE (R_ENTE_ESCL.SQLSTRING);
    END LOOP;   
    

                FOR R_ANAGSTATI IN C_ANAGSTATI LOOP
        DBMS_OUTPUT.PUT_LINE (R_ANAGSTATI.SQLSTRING);
    END LOOP;   

                FOR R_CMDTYPE IN C_CMDTYPE LOOP
        DBMS_OUTPUT.PUT_LINE (R_CMDTYPE.SQLSTRING);
    END LOOP;       
    
    
     FOR R_DIACTIPOINFO IN C_DIACTIPOINFO LOOP
        DBMS_OUTPUT.PUT_LINE (R_DIACTIPOINFO.SQLSTRING);
    END LOOP;       
    
    
    
    
    
   EXCEPTION
     WHEN OTHERS THEN

       RAISE;
END;
/

