DROP PROCEDURE DIOGENE_H501.DIA_ACCESSI_ISOLA_ECOLOGICA;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.DIA_ACCESSI_ISOLA_ECOLOGICA( idTestata number) AS
BEGIN
    DECLARE
    TBL_EXIST  NUMBER;
    BEGIN
    SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DIA_ACCESSI_ISOLE_ECOLOGICHE';
    IF TBL_EXIST = 1 THEN 
        EXECUTE IMMEDIATE 'TRUNCATE TABLE DIA_ACCESSI_ISOLE_ECOLOGICHE';
        EXECUTE IMMEDIATE 'COMMIT';
    ELSE
          DECLARE 
            v_stmt VARCHAR2(4000);
          BEGIN
            v_stmt := 'CREATE TABLE DIA_ACCESSI_ISOLE_ECOLOGICHE (
                  ID                      NUMBER                        NOT NULL,
                  FK_DIA_TESTATA          NUMBER                        NOT NULL,
                  CODICE                  VARCHAR2(50 BYTE),
                  COGNOME_DENOM         VARCHAR2(500 BYTE),
                  NOME                  VARCHAR2(500 BYTE),
                  CODICE_FISCALE        VARCHAR2(50 BYTE),
                  BELFIORE                VARCHAR2(50 BYTE),
                  COMUNE                VARCHAR2(50 BYTE),
                  PROV                    VARCHAR2(50 BYTE),
                  INDIRIZZO                VARCHAR2(50 BYTE),
                  CIVICO                VARCHAR2(50 BYTE),
                  COD_FAM                VARCHAR2(50 BYTE),
                  INTESTATARIO            VARCHAR2(50 BYTE),
                  TIPO_UTENZA            VARCHAR2(50 BYTE),
                  NUTENZE                VARCHAR2(50 BYTE) 
                  ) ';

            EXECUTE IMMEDIATE v_stmt;
        END;
        
    END IF;
    END;
    
    DECLARE
    TARSU_EXIST  NUMBER;
    BEGIN
    
    SELECT COUNT(*) INTO TARSU_EXIST FROM(
    select distinct cont.id_ext_sogg, sogg.cod_fisc cf, sogg.part_iva piva, sogg.cog_denom cognome_denom, sogg.nome, sogg.dt_nsc dt_nascita,
    case when sogg.des_ind_res is not null then des_ind_res else ind_res_ext end as descrizione_via,
    case when sogg.num_civ_res is not null then case when esp_civ_res is null then num_civ_res else num_civ_res||'/'||esp_civ_res end else num_civ_ext end as civ_res,
    sogg.cap_com_res cap_res_comune_res, sogg.des_com_res, sogg.sigla_prov_res prov_res, 
    sogg.des_stato_res nazione 
    from sit_t_tar_sogg sogg
    left join sit_t_tar_contrib cont
    on sogg.id_ext=cont.id_ext_sogg
    and cont.dt_fine_val is null
    and cont.dt_fine_dato is null
    where sogg.dt_fine_val is null
    and sogg.dt_fine_dato is null
    order by sogg.cog_denom, sogg.nome
    );

    IF TARSU_EXIST > 0 THEN
        --SI PARTE DALLA TARSU
        DECLARE
         v_stmt VARCHAR2(4000);
        BEGIN
            v_stmt := 'TRUNCATE TABLE DIA_ACCESSI_ISOLE_ECO_TMP ';
        
            EXECUTE IMMEDIATE v_stmt; 
        
            v_stmt := 'INSERT INTO DIA_ACCESSI_ISOLE_ECO_TMP (
            ID_EXT_SOGG, CF, PIVA, COGNOME_DENOM, NOME, DT_NASCITA, DESCRIZIONE_VIA, CIV_RES, CAP_RES_COMUNE_RES, DES_COM_RES, PROV_RES, NAZIONE)  
            select distinct cont.id_ext_sogg, sogg.cod_fisc cf, sogg.part_iva piva, sogg.cog_denom cognome_denom, sogg.nome, sogg.dt_nsc dt_nascita,
            case when sogg.des_ind_res is not null then des_ind_res else ind_res_ext end as descrizione_via,
            case when sogg.num_civ_res is not null then case when esp_civ_res is null then num_civ_res else num_civ_res||''/''||esp_civ_res end else num_civ_ext end as civ_res,
            sogg.cap_com_res cap_res_comune_res, sogg.des_com_res, sogg.sigla_prov_res prov_res, 
            sogg.des_stato_res nazione 
            from sit_t_tar_sogg sogg
            left join sit_t_tar_contrib cont
            on sogg.id_ext=cont.id_ext_sogg
            and cont.dt_fine_val is null
            and cont.dt_fine_dato is null
            where sogg.dt_fine_val is null
            and sogg.dt_fine_dato is null
            order by sogg.cog_denom, sogg.nome ';

            EXECUTE IMMEDIATE v_stmt;
        
            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add dati_oggetti varchar2(1000 byte) ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=null;


            update DIA_ACCESSI_ISOLE_ECO_TMP set CF=PIVA WHERE (cf is null or nvl( length(trim(cf)), 0 )=0 ) and PIVA is not null;
                
            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add nutenze number; ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set nutenze=null;
            
            execute immediate 'COMMIT';
            
            begin
            declare cursor c is select distinct id_ext_sogg from DIA_ACCESSI_ISOLE_ECO_TMP;
            begin
                for rec_c in c
                loop
                    declare 
                    errore varchar2(255 byte);
                    info varchar2(1000 byte); 
                    conta number;
                    
                    begin
                        declare cursor c2 is
                        select distinct trim(des_ind||' '||num_civ||' '||esp_civ) ind 
                        from sit_t_tar_oggetto ogg
                        inner join sit_t_tar_contrib cont
                        on cont.id_ext_ogg_rsu=ogg.id_ext
                        where cont.id_ext_sogg=rec_c.id_ext_sogg
                        and ogg.dt_fine_val is null
                        and ogg.dt_fine_dato is null
                        and ogg.des_ind is not null
                        and cont.dt_fine_val is null
                        and cont.dt_fine_dato is null
                        order by ind;
                        
                                                   
                        begin
                            
                            conta:=0;
                            info:= null;
                                                
                            for rec_c2 in c2
                                loop
                                    if info is null then
                                     info:=rec_c2.ind;
                                    else
                                      info:=info||' / '||rec_c2.ind;      
                                    end if;
                                    conta:=conta+1;
                                end loop;
                        end;
                                            
                        update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=info, nutenze=conta
                        where id_ext_sogg=rec_c.id_ext_sogg;

                        commit;
                        
                        exception when others then
                        dbms_output.put_line('Proc1-'||rec_c.id_ext_sogg); 
                        errore:=substr(sqlerrm,1,255);
                        dbms_output.put_line('Errore'||' '||errore);
                    end;
                commit;
                end loop;
            end;
        end;

        END;
        
    ELSE
        --SI PARTE DAL RUOLO
        DECLARE
            v_stmt VARCHAR2(4000);
        BEGIN
            v_stmt := 'TRUNCATE TABLE DIA_ACCESSI_ISOLE_ECO_TMP ';
        
            EXECUTE IMMEDIATE v_stmt; 
        
            v_stmt := 'INSERT INTO DIA_ACCESSI_ISOLE_ECO_TMP (
                COD_COMUNE_ISCR_RUOLO, COD_PARTITA, PROGRESSIVO_MINUTA, CF, COGNOME_DENOM, NOME, DT_NASCITA, DESCRIZIONE_VIA, CIV_RES, CAP_RES_COMUNE_RES, COD_BELFIORE )
                select distinct n2.cod_comune_iscr_ruolo, n2.cod_partita, n2.progressivo_minuta, n2.cod_fiscale cf, 
                case when n2.cognome is not null then n2.cognome else denominazione end cognome_denom, 
                n2.nome nome, to_date(decode(n2.dt_nascita,''0'',null,''00000000'',null,dt_nascita),''ddmmyyyy'') dt_nascita, 
                n2.indirizzo descrizione_via, 
                case when n2.numero_civico is not null then case when n2.lettera_numero_civico is null then to_char(n2.numero_civico) else numero_civico||''/''||lettera_numero_civico end end as civ_res,
                n2.cap cap_res_comune_res, n2.cod_belfiore
                from RE_CNC_N2_ANA_INTEST_RUOLO n2 ';

            EXECUTE IMMEDIATE v_stmt;
            
            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add dati_oggetti varchar2(1000 byte) ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=null;
                
            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add nutenze number; ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set nutenze=null;
            
            execute immediate 'COMMIT';
            
            begin
                declare cursor c is select distinct cod_partita from DIA_ACCESSI_ISOLE_ECO_TMP;
                begin
                    for rec_c in c
                    loop
                        declare 
                        errore varchar2(255 byte);
                        info varchar2(1000 byte);
                        conta number; 
                        
                        begin
                            declare cursor c2 is
                            select distinct info_cartella 
                            from RE_CNC_N4_DATI_CONT 
                            where cod_partita=rec_c.cod_partita
                            order by info_cartella;
                                                       
                            begin
                                
                                conta:=0;
                                info:= null;
                                                    
                                for rec_c2 in c2
                                    loop
                                        if info is null then
                                         info:=rec_c2.info_cartella;

                                        else
                                          info:=info||' / '||rec_c2.info_cartella;      

                                        end if;
                                        conta:=conta+1;
                                    end loop;
                            end;
                                                
                            update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=info, nutenze=conta
                            where cod_partita=rec_c.cod_partita;


                            commit;
                            
                            exception when others then
                            dbms_output.put_line('Proc1-'||rec_c.cod_partita); 
                            errore:=substr(sqlerrm,1,255);
                            dbms_output.put_line('Errore'||' '||errore);
                        end;
                    commit;
                    end loop;
                end;
            end;
        
        END;
        
    END IF;
    
    --INIZIO PARTE IN COMUNE 
    
    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add id_sogg number(5) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP  set id_sogg=rownum;

    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add res varchar2(10) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP set res = null;

    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add id_per varchar2(100 byte) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP set id_per = null;
    --commit;
    execute immediate 'COMMIT';
            
            
    begin
        declare cursor c is select distinct id_sogg from DIA_ACCESSI_ISOLE_ECO_TMP order by id_sogg;
        begin
            for rec_c in c
            loop
                declare 
                errore varchar2(255byte);
                p_ana varchar2(10);
                id_sogge varchar2(100);
                  begin
                    select distinct posiz_ana into p_ana
                      from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                     where c1.id_sogg=rec_c.id_sogg
                       and p.codfisc = c1.cf 
                       and p.dt_fine_val is null
                       and p.dt_fine_dato is null
                       and p.posiz_ana is not null
                       and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) = 
                       (
                       nvl( 
                       (select max(data_inizio_residenza) 
                       from sit_d_persona 
                       where codfisc=c1.cf
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                       ) 
                       );

                    select distinct id_ext into id_sogge
                      from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                     where c1.id_sogg=rec_c.id_sogg
                      and p.codfisc = c1.cf 
                       and p.dt_fine_val is null
                       and p.dt_fine_dato is null
                       and p.posiz_ana is not null
                       and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) = 
                       (
                       nvl( 
                       (select max(data_inizio_residenza) 
                       from sit_d_persona 
                       where codfisc=c1.cf
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                        ) 
                       );

                    if p_ana is null then
                     select posiz_ana into p_ana
                       from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                      where c1.id_sogg=rec_c.id_sogg
                        and p.cognome = c1.cognome_denom
                        and p.nome = c1.nome
                        and p.data_nascita = c1.dt_nascita
                        and p.dt_fine_val is null
                        and p.dt_fine_dato is null
                        and p.posiz_ana is not null
                        and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) = 
                       (
                       nvl( 
                       (select max(data_inizio_residenza) 
                       from sit_d_persona 
                       where cognome = c1.cognome_denom
                        and nome = c1.nome
                        and data_nascita = c1.dt_nascita
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                        ) 
                       );
                    end if;

                    if id_sogge is null then
                     select distinct id_ext into id_sogge
                       from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                      where c1.id_sogg=rec_c.id_sogg
                        and p.cognome = c1.cognome_denom
                        and p.nome = c1.nome
                        and p.data_nascita = c1.dt_nascita
                        and p.dt_fine_val is null
                        and p.dt_fine_dato is null
                        and p.posiz_ana is not null
                        and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) = 
                       (
                       nvl( 
                       (select max(data_inizio_residenza) 
                       from sit_d_persona 
                       where cognome = c1.cognome_denom
                        and nome = c1.nome
                        and data_nascita = c1.dt_nascita
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                       ) 
                       );
                    end if;

                    
                    update DIA_ACCESSI_ISOLE_ECO_TMP set res = p_ana
                    where id_sogg=rec_c.id_sogg;
                    
                    update DIA_ACCESSI_ISOLE_ECO_TMP set id_per=id_sogge
                    where id_sogg=rec_c.id_sogg;

                    exception
                    when no_data_found then null; 
                    when others then
                    dbms_output.put_line('Proc2-'||rec_c.id_sogg); 
                    errore:=substr(sqlerrm,1,255);
                    dbms_output.put_line('Errore'||' '||errore);
                end;
            commit;
            end loop;
        end;        
    end;


    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add n_fam varchar2(100 byte) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP set n_fam = null;

    execute immediate 'update DIA_ACCESSI_ISOLE_ECO_TMP c1 set n_fam = (select id_ext_d_famiglia from sit_d_pers_fam pf where id_ext_d_persona=c1.id_per and pf.dt_fine_val is null and pf.dt_fine_dato is null and pf.dt_inizio_val = ( select max(dt_inizio_val) from sit_d_pers_fam pf1 where pf1.id_ext_d_persona=c1.id_per and pf1.dt_fine_val is null and pf1.dt_fine_dato is null ) )';
    
    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add viasedime varchar2(20) ';
    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add descrizione varchar2(200) ';
    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add civico varchar2(20) ';
    
    update DIA_ACCESSI_ISOLE_ECO_TMP set viasedime = null;
    update DIA_ACCESSI_ISOLE_ECO_TMP set descrizione = null;
    update DIA_ACCESSI_ISOLE_ECO_TMP set civico = null;
    
    execute immediate 'COMMIT';
    
            
    declare cursor c is select distinct id_sogg from DIA_ACCESSI_ISOLE_ECO_TMP where res is not null;
    begin
        for rec_c in c
        loop
            declare 
            errore varchar2(255byte);
            begin
                update DIA_ACCESSI_ISOLE_ECO_TMP set (viasedime, descrizione, civico) =               
                     (  select distinct trim(v.viasedime), trim(v.descrizione),
                        case when ltrim(extractValue(c.civico_composto, '//att[1]/@valore'),'0') is not null then ltrim(extractValue(c.civico_composto, '//att[1]/@valore'),'0') end ||
                        case when ltrim(extractValue(c.civico_composto, '//att[2]/@valore'),'0') is not null then '/'|| ltrim(extractValue(c.civico_composto, '//att[2]/@valore'),'0') end ||
                        case when ltrim(extractValue(c.civico_composto, '//att[3]/@valore'),'0') is not null then '/'||ltrim(extractValue(c.civico_composto, '//att[3]/@valore'),'0') end civico
                        from sit_d_persona p, sit_d_persona_civico pc, sit_d_via v, sit_d_civico c, DIA_ACCESSI_ISOLE_ECO_TMP c1
                        where c1.id_sogg=rec_c.id_sogg
                        and (p.codfisc =c1.cf or (p.cognome=c1.cognome_denom and p.nome=c1.nome and p.data_nascita=c1.dt_nascita))  
                        and p.dt_fine_val is null
                        and p.dt_fine_dato is null
                        and p.id_ext = pc.id_ext_d_persona
                        and pc.dt_fine_val is null
                        and pc.dt_fine_dato is null
                        and pc.id_ext_d_civico=c.id_ext
                        and c.dt_fine_val is null
                        and c.dt_fine_dato is null
                        and c.id_ext_d_via=v.id_ext
                        and v.dt_fine_val is null
                        and v.dt_fine_dato is null
                        and rownum=1
                     )
                where id_sogg=rec_c.id_sogg; 
                exception when others then
                dbms_output.put_line('Proc3-'||rec_c.id_sogg); 
                errore:=substr(sqlerrm,1,255);
                dbms_output.put_line('Errore'||' '||errore);
            end;
        commit;
        end loop;
    end;        


    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add res_civ number (10)';
    
    execute immediate 'update DIA_ACCESSI_ISOLE_ECO_TMP set res_civ=1 where descrizione_via = viasedime ||'' ''|| descrizione and civ_res = civico ';
    execute immediate 'COMMIT';
    
                
                
                
                -- INIZIO PERSONALIZZAZIONE STORED 
                DECLARE
        COD_NAZIONALE VARCHAR2(50);
        BEGIN
                                               SELECT CODENT INTO COD_NAZIONALE FROM SIT_ENTE;
                                               IF COD_NAZIONALE = 'F704' OR COD_NAZIONALE = 'D385' OR COD_NAZIONALE = 'D384' OR COD_NAZIONALE = 'D963' THEN
                                                               
                                                               -- PARTE DEDICATA A MONZA IN CUI SIT_D_PERS_FAM.ID_EXT_D_FAMIGLIA NON è NUMERICO MA STRINGA
                                                               
                                                               execute immediate 'INSERT INTO DIA_ACCESSI_ISOLE_ECOLOGICHE 
                                                                              (ID, FK_DIA_TESTATA, CODICE, COGNOME_DENOM, NOME, CODICE_FISCALE, BELFIORE, COMUNE, PROV, INDIRIZZO, CIVICO, COD_FAM, INTESTATARIO, TIPO_UTENZA, NUTENZE)
                                                               select SEQ_DIA_ACCESSI_ISOLE_ECO.nextval, ' || idTestata || ', codice, cognome_denom, nome, CF, cod_belfiore, comune, prov, indirizzo, civ, codfam, intestatario, tipoutenza,  nutenze from
                                                               (
                                                               select distinct substr(id_per,0,10) codice, cognome_denom, c1.nome, CF, com.codi_fisc_luna cod_belfiore, 
                                                               des_com_res comune, prov_res prov,
                                                               descrizione_via indirizzo, ltrim(civ_res,''0'') civ,  
                                                               substr(n_fam,0,10) codfam, 1 intestatario, case when length(cf)=16 then 0 else 1 end tipoutenza,  nutenze
                                                               from DIA_ACCESSI_ISOLE_ECO_TMP c1
                                                               left join AM_BELFIORE_COMUNE com
                                                               on c1.des_com_res=com.nome_comune
                                                               where cognome_denom is not null
                                                               union
                                                               select DISTINCT substr(p.id_ext,0,10) codice, p.cognome, p.nome, p.codfisc, 
                                                               (SELECT DISTINCT SE.CODENT FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) cod_belfiore, 
                                                               (SELECT DISTINCT SE.DESCRIZIONE FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) comune, 
                                                               (SELECT DISTINCT SC.SIGLA_PROV FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) prov,  
                                                               trim(v.viasedime) ||'' ''|| trim(v.descrizione) indirizzo,
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') is not null then ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') is not null then ''/''|| ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') is not null then ''/''||ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') end civico,
                                                               substr(pf.id_ext_d_famiglia,0,10) codfam, 0 intestatario, 0 as tipoutenza,  ''0'' nutenze
                                                               from sit_d_persona p, sit_d_persona_civico pc, sit_d_via v, sit_d_civico c, sit_d_pers_fam pf
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.id_ext = pc.id_ext_d_persona
                                                               and pc.dt_fine_val is null
                                                               and (pc.dt_fine_dato is null or pc.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and pc.id_ext_d_civico=c.id_ext
                                                               and c.dt_fine_val is null
                                                               and c.dt_fine_dato is null
                                                               and c.id_ext_d_via=v.id_ext
                                                               and v.dt_fine_val is null
                                                               and v.dt_fine_dato is null
                                                               and pf.id_ext_d_persona=p.id_ext
                                                               and pf.dt_fine_val is null
                                                               and (pf.dt_fine_dato is null or pf.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and p.id_ext in (
                                                               select distinct id_ext from sit_d_persona p
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.posiz_ana=''A''
                                                               minus 
                                                               select distinct id_per from DIA_ACCESSI_ISOLE_ECO_TMP
                                                               ) 
                                                               and p.cognome is not null
                                                               order by cognome_denom, nome 
                                                               ) ';
                                                               
                                                               
                                               ELSE
                                               
                                                               -- PARTE DEDICATA A TUTTI QUEI COMUNI CHE HANNO SIT_D_PERS_FAM.ID_EXT_D_FAMIGLIA NUMERICO
                
                                                               execute immediate 'INSERT INTO DIA_ACCESSI_ISOLE_ECOLOGICHE 
                                                                              (ID, FK_DIA_TESTATA, CODICE, COGNOME_DENOM, NOME, CODICE_FISCALE, BELFIORE, COMUNE, PROV, INDIRIZZO, CIVICO, COD_FAM, INTESTATARIO, TIPO_UTENZA, NUTENZE)
                                                               select SEQ_DIA_ACCESSI_ISOLE_ECO.nextval, ' || idTestata || ', codice, cognome_denom, nome, CF, cod_belfiore, comune, prov, indirizzo, civ, codfam, intestatario, tipoutenza,  nutenze from
                                                               (
                                                               select distinct to_number(substr(id_per,0,10)) codice, cognome_denom, c1.nome, CF, com.codi_fisc_luna cod_belfiore, 
                                                               des_com_res comune, prov_res prov,
                                                               descrizione_via indirizzo, ltrim(civ_res,''0'') civ,  
                                                               to_number(substr(n_fam,0,10)) codfam, 1 intestatario, case when length(cf)=16 then 0 else 1 end tipoutenza,  nutenze
                                                               from DIA_ACCESSI_ISOLE_ECO_TMP c1
                                                               left join AM_BELFIORE_COMUNE com
                                                               on c1.des_com_res=com.nome_comune
                                                               where cognome_denom is not null
                                                               union
                                                               select DISTINCT to_number(substr(p.id_ext,0,10)) codice, p.cognome, p.nome, p.codfisc, 
                                                               (SELECT DISTINCT SE.CODENT FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) cod_belfiore, 
                                                               (SELECT DISTINCT SE.DESCRIZIONE FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) comune, 
                                                               (SELECT DISTINCT SC.SIGLA_PROV FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) prov,  
                                                               trim(v.viasedime) ||'' ''|| trim(v.descrizione) indirizzo,
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') is not null then ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') is not null then ''/''|| ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') is not null then ''/''||ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') end civico,
                                                               to_number(substr(pf.id_ext_d_famiglia,0,10)) codfam, 0 intestatario, 0 as tipoutenza,  ''0'' nutenze
                                                               from sit_d_persona p, sit_d_persona_civico pc, sit_d_via v, sit_d_civico c, sit_d_pers_fam pf
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.id_ext = pc.id_ext_d_persona
                                                               and pc.dt_fine_val is null
                                                               and (pc.dt_fine_dato is null or pc.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and pc.id_ext_d_civico=c.id_ext
                                                               and c.dt_fine_val is null
                                                               and c.dt_fine_dato is null
                                                               and c.id_ext_d_via=v.id_ext
                                                               and v.dt_fine_val is null
                                                               and v.dt_fine_dato is null
                                                               and pf.id_ext_d_persona=p.id_ext
                                                               and pf.dt_fine_val is null
                                                               and (pf.dt_fine_dato is null or pf.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and p.id_ext in (
                                                               select distinct id_ext from sit_d_persona p
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.posiz_ana=''A''
                                                               minus 
                                                               select distinct id_per from DIA_ACCESSI_ISOLE_ECO_TMP
                                                               ) 
                                                               and p.cognome is not null
                                                               order by cognome_denom, nome 
                                                               ) ';

                                               
                                               END IF;
                               END;
                
                -- FINE PERSONALIZZAZIONE STORED 
                
                

    execute immediate 'COMMIT';
    

    END;

END DIA_ACCESSI_ISOLA_ECOLOGICA;
/


DROP PROCEDURE DIOGENE_H501.DOCFA_REP;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.DOCFA_REP AS
BEGIN
    DECLARE
    TBL_EXIST  NUMBER;
    BEGIN
    SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_TEMP_001';
    IF TBL_EXIST = 1 THEN 
    EXECUTE IMMEDIATE 'DROP TABLE DOCFA_TEMP_001 CASCADE CONSTRAINT';
    END IF;
    END;

  DECLARE 
  v_stmt VARCHAR2(4000);
  SQLSTMT VARCHAR2(100);
  BEGIN

    v_stmt := 'CREATE TABLE DOCFA_TEMP_001 AS(
    SELECT DISTINCT C.FORNITURA, C.IDENTIFICATIVO_IMMOBILE, C.PROTOCOLLO_REGISTRAZIONE, C.DATA_REGISTRAZIONE,
                    C.ZONA, C.CATEGORIA, C.CLASSE, C.CONSISTENZA, C.SUPERFICIE, C.RENDITA_EURO,
                    C.FOGLIO, C.NUMERO, C.SUBALTERNO, C.PRESENZA_GRAFFATI, C.TOPONIMO, C.INDIRIZZO, 
                    C.CIVICO_1, 1 AS FLAG
    FROM DOCFA_DATI_CENSUARI C 
    WHERE C.CATEGORIA IN (''A01'',''A02'',''A03'',''A04'',''A05'',''A06'',''A07'',''A08'',''A09'',''A11'')
    )
    ';

    EXECUTE IMMEDIATE v_stmt;

    DECLARE TBL_EXIST  PLS_INTEGER;
    
    BEGIN
      SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_DIAGNOSTICHE';
      IF TBL_EXIST = 1 THEN 
        EXECUTE IMMEDIATE 'DROP TABLE DOCFA_DIAGNOSTICHE CASCADE CONSTRAINT';
      END IF;
    END;

    v_stmt := 'CREATE TABLE DOCFA_DIAGNOSTICHE AS 
              (SELECT FORNITURA, COUNT(*) AS NREC_DATI_CENSUARI,1 AS RES_NO_RES  FROM DOCFA_TEMP_001
              GROUP BY FORNITURA
              )';
    EXECUTE IMMEDIATE v_stmt;
    
    
    v_stmt := 'UPDATE DOCFA_TEMP_001 C SET FLAG=0 
              WHERE SUBSTR(DATA_REGISTRAZIONE,1,6) = SUBSTR(TO_CHAR(FORNITURA,''YYYYMMDD''),1,6)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE ADD (NREC_DATAREG_NO_COER NUMBER)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE CD SET NREC_DATAREG_NO_COER =NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_001
              WHERE FLAG=1
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';

    EXECUTE IMMEDIATE v_stmt;


    DECLARE TBL_EXIST  PLS_INTEGER;
    
    BEGIN
    SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_TEMP_002';
    IF TBL_EXIST = 1 THEN 
    EXECUTE IMMEDIATE 'DROP TABLE DOCFA_TEMP_002 CASCADE CONSTRAINT';
    END IF;
    END;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_002 AS(
              SELECT DISTINCT C1.*, D.TIPO_OPERAZIONE FROM DOCFA_TEMP_001 C1
              LEFT JOIN DOCFA_UIU D 
              ON C1.FORNITURA=D.FORNITURA
              AND C1.PROTOCOLLO_REGISTRAZIONE = D.PROTOCOLLO_REG
              AND C1.FOGLIO = D.FOGLIO
              AND C1.NUMERO = D.NUMERO
              AND NVL(C1.SUBALTERNO,''    '') = D.SUBALTERNO
              )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE ADD (NREC_TIPO_OPER_NO_UNICO NUMBER)';
    EXECUTE IMMEDIATE v_stmt;


    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE CD SET NREC_TIPO_OPER_NO_UNICO =NVL((SELECT SUM(CONTA) FROM (SELECT   COUNT (*) AS CONTA, C.FORNITURA, C.IDENTIFICATIVO_IMMOBILE, C.PROTOCOLLO_REGISTRAZIONE, C.DATA_REGISTRAZIONE, C.ZONA,
                C.CATEGORIA, C.CLASSE, C.CONSISTENZA, C.SUPERFICIE, C.RENDITA_EURO, C.FOGLIO, C.NUMERO, C.SUBALTERNO, C.PRESENZA_GRAFFATI, C.TOPONIMO,
                C.INDIRIZZO, C.CIVICO_1, FLAG
           FROM DOCFA_TEMP_002 C
        GROUP BY C.FORNITURA, C.IDENTIFICATIVO_IMMOBILE, C.PROTOCOLLO_REGISTRAZIONE, C.DATA_REGISTRAZIONE, C.ZONA,
                C.CATEGORIA, C.CLASSE, C.CONSISTENZA, C.SUPERFICIE, C.RENDITA_EURO, C.FOGLIO, C.NUMERO, C.SUBALTERNO,
                C.PRESENZA_GRAFFATI, C.TOPONIMO, C.INDIRIZZO, C.CIVICO_1, FLAG
         HAVING COUNT (*) > 1
        ) CA
        WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;


    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE ADD (NREC_TIPO_OPER_NULL NUMBER)';
    EXECUTE IMMEDIATE v_stmt;



    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE CD SET NREC_TIPO_OPER_NULL =NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_002
              WHERE TIPO_OPERAZIONE IS NULL
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE ADD (NREC_TIPO_OPER_CESS NUMBER)';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE CD SET NREC_TIPO_OPER_CESS =NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_002
              WHERE TIPO_OPERAZIONE = ''S''
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'DROP TABLE DOCFA_TEMP_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_001 AS(
                SELECT DISTINCT C2.FORNITURA, C2.IDENTIFICATIVO_IMMOBILE, C2.PROTOCOLLO_REGISTRAZIONE,
                C2.DATA_REGISTRAZIONE, C2.ZONA, C2.CATEGORIA, C2.CLASSE, C2.CONSISTENZA, C2.SUPERFICIE,
                C2.RENDITA_EURO, C2.FOGLIO, C2.NUMERO, C2.SUBALTERNO, C2.PRESENZA_GRAFFATI, C2.TOPONIMO,
                C2.INDIRIZZO, C2.CIVICO_1, C2.TIPO_OPERAZIONE FROM DOCFA_TEMP_002 C2
                WHERE FLAG=0 
                 AND (TIPO_OPERAZIONE = ''C'' OR TIPO_OPERAZIONE = ''V'') 
                )';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE ADD (NREC_DOCFA_OK NUMBER)';
    EXECUTE IMMEDIATE v_stmt;
    

    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE CD SET NREC_DOCFA_OK = NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_001
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE ADD (NREC_UIU NUMBER)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE CD SET NREC_UIU = NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM(SELECT DISTINCT FORNITURA,FOGLIO,NUMERO,SUBALTERNO FROM DOCFA_TEMP_001 )
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_002 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_002 AS(
              SELECT DISTINCT C1.*, G.FLAG_NC FROM DOCFA_TEMP_001 C1
              LEFT JOIN DOCFA_DATI_GENERALI G
              ON C1.FORNITURA = G.FORNITURA 
              AND C1.PROTOCOLLO_REGISTRAZIONE=G.PROTOCOLLO_REG
              )  ';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_001 AS(
                SELECT DISTINCT C2.*, D.DIC_COGNOME, D.DIC_NOME, D.TEC_COGNOME, D.TEC_NOME  FROM DOCFA_TEMP_002 C2
                LEFT JOIN DOCFA_DICHIARANTI D
                ON C2.FORNITURA = D.FORNITURA 
                AND C2.PROTOCOLLO_REGISTRAZIONE = D.PROTOCOLLO_REG
                )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_002';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_002 AS( 
                SELECT DISTINCT C2.*, M.ZC, M.OLD_MICROZONA, M.NEW_MICROZONA FROM DOCFA_TEMP_001 C2
                LEFT JOIN DOCFA_FOGLI_MICROZONA M
                ON TO_NUMBER(C2.FOGLIO) = TO_NUMBER(M.FOGLIO) 
                AND TO_NUMBER(C2.FOGLIO) NOT IN ( 
                    SELECT TO_NUMBER(FOGLIO) FROM(
                    SELECT COUNT(*), FOGLIO FROM DOCFA_FOGLI_MICROZONA
                    GROUP BY FOGLIO
                    HAVING COUNT(*) >1)
                    )          
                )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt; 

    v_stmt := 'CREATE TABLE DOCFA_TEMP_001 AS(
                SELECT DISTINCT C1.*, M.ZC AS ZC_2, M.OLD_MICROZONA AS OLD_MICROZONA_2, M.NEW_MICROZONA AS NEW_MICROZONA_2 FROM DOCFA_TEMP_002 C1
                LEFT JOIN DOCFA_FOGLI_MICROZONA M
                ON TO_NUMBER(C1.FOGLIO) = TO_NUMBER(M.FOGLIO) 
                AND TO_NUMBER(C1.ZONA)=TO_NUMBER(M.ZC) 
                AND TO_NUMBER(C1.FOGLIO) IN ( 
                    SELECT TO_NUMBER(FOGLIO) FROM(
                    SELECT COUNT(*), FOGLIO FROM DOCFA_FOGLI_MICROZONA
                    GROUP BY FOGLIO
                    HAVING COUNT(*) >1)
                    )
                )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'UPDATE DOCFA_TEMP_001 SET ZC=ZC_2, OLD_MICROZONA=OLD_MICROZONA_2, NEW_MICROZONA=NEW_MICROZONA_2
              WHERE ZC_2 IS NOT NULL';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_TEMP_001 DROP COLUMN ZC_2';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_TEMP_001 DROP COLUMN OLD_MICROZONA_2';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_TEMP_001 DROP COLUMN NEW_MICROZONA_2';
    EXECUTE IMMEDIATE v_stmt;

        v_stmt := 'DROP TABLE DOCFA_TEMP_002 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    
-- INIZIO IF KML_SHAPE
    
    DECLARE
    VAL_COMMLE_MODE  VARCHAR2(100);
    BEGIN
    SELECT VALUE_CONF INTO VAL_COMMLE_MODE FROM AM_KEY_VALUE_EXT WHERE KEY_CONF = 'docfa.modalita.calcolo.valore.commerciale' AND FK_AM_COMUNE = ( SELECT CODENT FROM SIT_ENTE );
    
    DBMS_OUTPUT.PUT_LINE('METODO DI CALCOLO DEL VALORE COMMERCIALE SELEZIONATO: ' || VAL_COMMLE_MODE);
    
    IF VAL_COMMLE_MODE = 'KML_SHAPE' THEN 
            --METODO KML_SHAPE
            
            DECLARE TBL_EXIST  PLS_INTEGER;
    
            BEGIN
            SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_PART_ZONE_OMI';
            IF TBL_EXIST = 1 THEN 
            EXECUTE IMMEDIATE 'DROP TABLE DOCFA_PART_ZONE_OMI CASCADE CONSTRAINT';
            END IF;
            END;
            
        v_stmt := 'CREATE TABLE DOCFA_PART_ZONE_OMI AS(
                        select DISTINCT ZOMI.NAME AS OMI_ZONE, PART.FOGLIO AS FOGLIO, PART.PARTICELLA AS PARTICELLA, PART.SUB AS SUBALTERNO
                        from SHP_ZONE_OMI ZOMI, SITIPART PART
                        where sdo_relate (ZOMI.shape, PART.shape, ''mask=ANYINTERACT'')=''TRUE''
                        )';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'ALTER TABLE DOCFA_PART_ZONE_OMI ADD (AREA_SM NUMBER )';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'UPDATE DOCFA_PART_ZONE_OMI DPZO SET DPZO.AREA_SM = (
        SELECT SDO_GEOM.SDO_AREA(
        (
        SELECT SDO_GEOM.SDO_INTERSECTION(ZOMI.shape, PART.shape, 0.005)
           FROM SHP_ZONE_OMI ZOMI, SITIPART PART 
           WHERE ZOMI.NAME = DPZO.OMI_ZONE AND
           PART.FOGLIO = DPZO.FOGLIO 
        AND PART.PARTICELLA = DPZO.PARTICELLA AND ROWNUM = 1
        ), 0.005) FROM DUAL
        )';
        EXECUTE IMMEDIATE v_stmt;
        
        /*
        PER EVITARE CHE UNA PARTICELLA SI INTERSECHI CON PIU DI UNA ZONA OMI, SI CALCOLA L'AREA DI MAGGIOR INTERSEZIONE
        
        select OMI_ZONE, FOGLIO, PARTICELLA, SUBALTERNO, AREA_SM 
    from DOCFA_PART_ZONE_OMI 
    where foglio = 7 AND PARTICELLA = '00ST0'
    GROUP BY OMI_ZONE, FOGLIO, PARTICELLA, SUBALTERNO, AREA_SM
    order by AREA_SM desc, foglio, particella
    
    /*
    MONZA - Zona OMI B11    7    00ST0         2487,83207207364
    MONZA - Zona OMI B3    7    00ST0         350,827481691458
    MONZA - Zona OMI D2    7    00ST0         24083,6610966829
    */
        
        /*
        SELECT t.OMI_ZONE, t.FOGLIO, t.PARTICELLA, r.MaxAREA
        FROM (SELECT FOGLIO, PARTICELLA, MAX(AREA_SM) as MaxAREA
              FROM DOCFA_PART_ZONE_OMI
              --where foglio = 7 AND PARTICELLA = '00ST0'
              GROUP BY FOGLIO, PARTICELLA) r
        INNER JOIN DOCFA_PART_ZONE_OMI t ON t.FOGLIO = r.FOGLIO AND t.PARTICELLA = r.PARTICELLA AND t.AREA_SM = r.MaxAREA
        */

        DECLARE TBL_EXIST  PLS_INTEGER;
        BEGIN
            SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_PART_ZONE_OMI_MAX';
            IF TBL_EXIST = 1 THEN 
            EXECUTE IMMEDIATE 'DROP TABLE DOCFA_PART_ZONE_OMI_MAX CASCADE CONSTRAINT';
            END IF;
            END;
            
            
         v_stmt := 'CREATE TABLE DOCFA_PART_ZONE_OMI_MAX AS(
                        SELECT t.OMI_ZONE, t.FOGLIO, t.PARTICELLA, r.MaxAREA
                        FROM (SELECT FOGLIO, PARTICELLA, MAX(AREA_SM) as MaxAREA
                              FROM DOCFA_PART_ZONE_OMI
                              GROUP BY FOGLIO, PARTICELLA) r
                        INNER JOIN DOCFA_PART_ZONE_OMI t ON t.FOGLIO = r.FOGLIO AND t.PARTICELLA = r.PARTICELLA AND t.AREA_SM = r.MaxAREA
                        )';
        EXECUTE IMMEDIATE v_stmt;        
        
        v_stmt := 'ALTER TABLE DOCFA_TEMP_001 ADD (OMI_ZONE VARCHAR2(100) )';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'UPDATE DOCFA_TEMP_001 DT1 SET DT1.OMI_ZONE=(
                SELECT DISTINCT DPZO.OMI_ZONE FROM DOCFA_PART_ZONE_OMI_MAX DPZO WHERE DT1.FOGLIO = DPZO.FOGLIO AND DT1.NUMERO = DPZO.PARTICELLA
        )';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'ALTER TABLE DOCFA_TEMP_001 ADD (COD_OMI_ZONE VARCHAR2(100) )';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'UPDATE DOCFA_TEMP_001 DT1 SET DT1.COD_OMI_ZONE=(
                SELECT SUBSTR(DPZO.OMI_ZONE, INSTR(DPZO.OMI_ZONE, '' '', -1, 1)+1 ) FROM DOCFA_PART_ZONE_OMI_MAX DPZO WHERE DT1.FOGLIO = DPZO.FOGLIO AND DT1.NUMERO = DPZO.PARTICELLA
        )';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'CREATE TABLE DOCFA_TEMP_002 AS(
                   SELECT C2.*, V.VAL_MED AS VAL_COMM_MQ, C2.RENDITA_EURO*100 AS RENDITA_DOCFAx100, 
                     C2.RENDITA_EURO*105 AS RENDITA_DOCFA_AGG, C2.SUPERFICIE*V.VAL_MED AS VAL_COMM,
                    CASE 
                         WHEN C2.RENDITA_EURO > 0  THEN (C2.SUPERFICIE*V.VAL_MED)/(C2.RENDITA_EURO*100) 
                         ELSE NULL
                    END AS RAPPORTO_1,
                    CASE
                        WHEN C2.RENDITA_EURO > 0  THEN (C2.SUPERFICIE*V.VAL_MED)/(C2.RENDITA_EURO*105)
                        ELSE NULL 
                    END AS RAPPORTO_2
                    FROM DOCFA_TEMP_001 C2
                    LEFT JOIN DOCFA_VALORI V
                    ON  V.ZONA = C2.COD_OMI_ZONE
                    AND V.TIPOLOGIA_EDILIZIA=(CASE WHEN C2.CATEGORIA IN (''A01'',''A02'',''A07'',''A08'',''A09'') THEN ''ABITAZIONI CIVILI''
                                                  WHEN C2.CATEGORIA IN (''A03'',''A04'',''A05'',''A06'') THEN ''ABITAZIONI TIPO ECONOMICO''
                                             END)
                    AND V.STATO=(CASE WHEN C2.FLAG_NC = 0 THEN ''Normale''
                                     WHEN C2.FLAG_NC = 1 THEN ''Ottimo''
                                END)                         
                    )';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'DROP TABLE DOCFA_PART_ZONE_OMI_MAX CASCADE CONSTRAINT';
        EXECUTE IMMEDIATE v_stmt;
        
        v_stmt := 'DROP TABLE DOCFA_PART_ZONE_OMI CASCADE CONSTRAINT';
        EXECUTE IMMEDIATE v_stmt;
        
    ELSE
        v_stmt := 'CREATE TABLE DOCFA_TEMP_002 AS(
                    SELECT C2.*, V.VAL_MED AS VAL_COMM_MQ, C2.RENDITA_EURO*100 AS RENDITA_DOCFAx100, 
                     C2.RENDITA_EURO*105 AS RENDITA_DOCFA_AGG, C2.SUPERFICIE*V.VAL_MED AS VAL_COMM,
                    CASE WHEN C2.RENDITA_EURO = 0 THEN 0 ELSE (C2.SUPERFICIE*V.VAL_MED)/(C2.RENDITA_EURO*100) END AS RAPPORTO_1,
                    CASE WHEN C2.RENDITA_EURO = 0 THEN 0 ELSE (C2.SUPERFICIE*V.VAL_MED)/(C2.RENDITA_EURO*105) END AS RAPPORTO_2
                    FROM DOCFA_TEMP_001 C2
                    LEFT JOIN DOCFA_VALORI V
                    ON TO_NUMBER(V.MICROZONA) = TO_NUMBER(C2.NEW_MICROZONA) 
                    AND V.TIPOLOGIA_EDILIZIA=(CASE WHEN C2.CATEGORIA IN (''A01'',''A02'',''A07'',''A08'',''A09'') THEN ''ABITAZIONI CIVILI''
                                                  WHEN C2.CATEGORIA IN (''A03'',''A04'',''A05'',''A06'') THEN ''ABITAZIONI TIPO ECONOMICO''
                                             END)
                    AND V.STATO=(CASE WHEN C2.FLAG_NC = 0 THEN ''Normale''
                                     WHEN C2.FLAG_NC = 1 THEN ''Ottimo''
                                END)                         
                    )';
        EXECUTE IMMEDIATE v_stmt;

    END IF;
    
    END;


    -- FINE IF KML_SHAPE

      DECLARE TBL_EXIST  PLS_INTEGER;
      BEGIN
      SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_REPORT';
      IF TBL_EXIST = 1 THEN 
      EXECUTE IMMEDIATE 'DROP TABLE DOCFA_REPORT CASCADE CONSTRAINT';
      END IF;
      END;

    v_stmt := 'CREATE TABLE DOCFA_REPORT AS (
              SELECT
               FORNITURA AS FORN,
               IDENTIFICATIVO_IMMOBILE AS ID_IMM,                 
               PROTOCOLLO_REGISTRAZIONE AS PROT,  
               DATA_REGISTRAZIONE AS DATA_REG,
               ZONA AS ZC_DOCFA,
               CATEGORIA AS CAT,                 
               CLASSE,
               CONSISTENZA,
               SUPERFICIE,
               RENDITA_EURO AS RENDITA_DOCFA,
               FOGLIO,                    
               NUMERO AS PART,            
               SUBALTERNO AS SUB,   
               PRESENZA_GRAFFATI AS GRAFFATI, 
               TOPONIMO,
               INDIRIZZO,   
               CIVICO_1,   
               TIPO_OPERAZIONE,    
                FLAG_NC AS NC,  
                DIC_COGNOME,
               DIC_NOME,
               TEC_COGNOME,
               TEC_NOME,
               ZC AS ZC_CAT,
               OLD_MICROZONA AS OLD_MZ,
               NEW_MICROZONA AS NEW_MZ,
               VAL_COMM_MQ,     
                RENDITA_DOCFAx100,
               RENDITA_DOCFA_AGG, 
               VAL_COMM,
               ROUND(RAPPORTO_1,2) AS RAPP_1,
               ROUND(RAPPORTO_2,2) AS RAPP_2,
               TO_NUMBER(ZONA)-TO_NUMBER(ZC) AS ZC_DIFF                     
              FROM DOCFA_TEMP_002
              )';
    EXECUTE IMMEDIATE v_stmt;
    
  END;
  

END DOCFA_REP;
/


DROP PROCEDURE DIOGENE_H501.DOCFA_REP_NORES;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.DOCFA_REP_NORES AS
BEGIN
    DECLARE
    TBL_EXIST  NUMBER;
    BEGIN
    SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_TEMP_NORES_001';
    IF TBL_EXIST = 1 THEN 
    EXECUTE IMMEDIATE 'DROP TABLE DOCFA_TEMP_NORES_001 CASCADE CONSTRAINT';
    END IF;
    END;

  DECLARE 
  v_stmt VARCHAR2(4000);
  SQLSTMT VARCHAR2(100);
  BEGIN

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_001 AS(
    SELECT DISTINCT C.FORNITURA, C.IDENTIFICATIVO_IMMOBILE, C.PROTOCOLLO_REGISTRAZIONE, C.DATA_REGISTRAZIONE,
                    C.ZONA, C.CATEGORIA, C.CLASSE, C.CONSISTENZA, C.SUPERFICIE, C.RENDITA_EURO,
                    C.FOGLIO, C.NUMERO, C.SUBALTERNO, C.PRESENZA_GRAFFATI, C.TOPONIMO, C.INDIRIZZO, 
                    C.CIVICO_1, 1 AS FLAG
    FROM DOCFA_DATI_CENSUARI C 
    WHERE C.CATEGORIA IN (''C01'',''C02'',''C03'',''C04'',''C05'',''C06'',''C07'',''A10'')
    )
    ';

    EXECUTE IMMEDIATE v_stmt;

    DECLARE TBL_EXIST  PLS_INTEGER;
    
    BEGIN
      SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_DIAGNOSTICHE_NORES';
      IF TBL_EXIST = 1 THEN 
        EXECUTE IMMEDIATE 'DROP TABLE DOCFA_DIAGNOSTICHE_NORES CASCADE CONSTRAINT';
      END IF;
    END;

    v_stmt := 'CREATE TABLE DOCFA_DIAGNOSTICHE_NORES AS 
              (SELECT FORNITURA, COUNT(*) AS NREC_DATI_CENSUARI,1 AS RES_NO_RES  FROM DOCFA_TEMP_NORES_001
              GROUP BY FORNITURA
              )';
    EXECUTE IMMEDIATE v_stmt;
    
    
    v_stmt := 'UPDATE DOCFA_TEMP_NORES_001 C SET FLAG=0 
              WHERE SUBSTR(DATA_REGISTRAZIONE,1,6) = SUBSTR(TO_CHAR(FORNITURA,''YYYYMMDD''),1,6)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE_NORES ADD (NREC_DATAREG_NO_COER NUMBER)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE_NORES CD SET NREC_DATAREG_NO_COER =NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_NORES_001
              WHERE FLAG=1
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';

    EXECUTE IMMEDIATE v_stmt;


    DECLARE TBL_EXIST  PLS_INTEGER;
    
    BEGIN
    SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_TEMP_NORES_002';
    IF TBL_EXIST = 1 THEN 
    EXECUTE IMMEDIATE 'DROP TABLE DOCFA_TEMP_NORES_002 CASCADE CONSTRAINT';
    END IF;
    END;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_002 AS(
              SELECT DISTINCT C1.*, D.TIPO_OPERAZIONE FROM DOCFA_TEMP_NORES_001 C1
              LEFT JOIN DOCFA_UIU D 
              ON C1.FORNITURA=D.FORNITURA
              AND C1.PROTOCOLLO_REGISTRAZIONE = D.PROTOCOLLO_REG
              AND C1.FOGLIO = D.FOGLIO
              AND C1.NUMERO = D.NUMERO
              AND NVL(C1.SUBALTERNO,''    '') = D.SUBALTERNO
              )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE_NORES ADD (NREC_TIPO_OPER_NO_UNICO NUMBER)';
    EXECUTE IMMEDIATE v_stmt;


    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE_NORES CD SET NREC_TIPO_OPER_NO_UNICO =NVL((SELECT SUM(CONTA) FROM (SELECT   COUNT (*) AS CONTA, C.FORNITURA, C.IDENTIFICATIVO_IMMOBILE, C.PROTOCOLLO_REGISTRAZIONE, C.DATA_REGISTRAZIONE, C.ZONA,
                C.CATEGORIA, C.CLASSE, C.CONSISTENZA, C.SUPERFICIE, C.RENDITA_EURO, C.FOGLIO, C.NUMERO, C.SUBALTERNO, C.PRESENZA_GRAFFATI, C.TOPONIMO,
                C.INDIRIZZO, C.CIVICO_1, FLAG
           FROM DOCFA_TEMP_NORES_002 C
        GROUP BY C.FORNITURA, C.IDENTIFICATIVO_IMMOBILE, C.PROTOCOLLO_REGISTRAZIONE, C.DATA_REGISTRAZIONE, C.ZONA,
                C.CATEGORIA, C.CLASSE, C.CONSISTENZA, C.SUPERFICIE, C.RENDITA_EURO, C.FOGLIO, C.NUMERO, C.SUBALTERNO,
                C.PRESENZA_GRAFFATI, C.TOPONIMO, C.INDIRIZZO, C.CIVICO_1, FLAG
         HAVING COUNT (*) > 1
        ) CA
        WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;


    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE_NORES ADD (NREC_TIPO_OPER_NULL NUMBER)';
    EXECUTE IMMEDIATE v_stmt;



    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE_NORES CD SET NREC_TIPO_OPER_NULL =NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_NORES_002
              WHERE TIPO_OPERAZIONE IS NULL
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE_NORES ADD (NREC_TIPO_OPER_CESS NUMBER)';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE_NORES CD SET NREC_TIPO_OPER_CESS =NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_NORES_002
              WHERE TIPO_OPERAZIONE = ''S''
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_001 AS(
                SELECT DISTINCT C2.FORNITURA, C2.IDENTIFICATIVO_IMMOBILE, C2.PROTOCOLLO_REGISTRAZIONE,
                C2.DATA_REGISTRAZIONE, C2.ZONA, C2.CATEGORIA, C2.CLASSE, C2.CONSISTENZA, C2.SUPERFICIE,
                C2.RENDITA_EURO, C2.FOGLIO, C2.NUMERO, C2.SUBALTERNO, C2.PRESENZA_GRAFFATI, C2.TOPONIMO,
                C2.INDIRIZZO, C2.CIVICO_1, C2.TIPO_OPERAZIONE FROM DOCFA_TEMP_NORES_002 C2
                WHERE FLAG=0 
                 AND (TIPO_OPERAZIONE = ''C'' OR TIPO_OPERAZIONE = ''V'') 
                )';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE_NORES ADD (NREC_DOCFA_OK NUMBER)';
    EXECUTE IMMEDIATE v_stmt;
    

    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE_NORES CD SET NREC_DOCFA_OK = NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM DOCFA_TEMP_NORES_001
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_DIAGNOSTICHE_NORES ADD (NREC_UIU NUMBER)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'UPDATE DOCFA_DIAGNOSTICHE_NORES CD SET NREC_UIU = NVL(
              (SELECT CONTA FROM (SELECT FORNITURA, COUNT(*) AS CONTA
              FROM(SELECT DISTINCT FORNITURA,FOGLIO,NUMERO,SUBALTERNO FROM DOCFA_TEMP_NORES_001 )
              GROUP BY FORNITURA) CA
              WHERE CD.FORNITURA = CA.FORNITURA),0)';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_002 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_002 AS(
              SELECT DISTINCT C1.*, G.FLAG_NC FROM DOCFA_TEMP_NORES_001 C1
              LEFT JOIN DOCFA_DATI_GENERALI G
              ON C1.FORNITURA = G.FORNITURA 
              AND C1.PROTOCOLLO_REGISTRAZIONE=G.PROTOCOLLO_REG
              )  ';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_001 AS(
                SELECT DISTINCT C2.*, D.DIC_COGNOME, D.DIC_NOME, D.TEC_COGNOME, D.TEC_NOME  FROM DOCFA_TEMP_NORES_002 C2
                LEFT JOIN DOCFA_DICHIARANTI D
                ON C2.FORNITURA = D.FORNITURA 
                AND C2.PROTOCOLLO_REGISTRAZIONE = D.PROTOCOLLO_REG
                )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_002';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_002 AS( 
                SELECT DISTINCT C2.*, M.ZC, M.OLD_MICROZONA, M.NEW_MICROZONA FROM DOCFA_TEMP_NORES_001 C2
                LEFT JOIN DOCFA_FOGLI_MICROZONA M
                ON TO_NUMBER(C2.FOGLIO) = TO_NUMBER(M.FOGLIO) 
                AND TO_NUMBER(C2.FOGLIO) NOT IN ( 
                    SELECT TO_NUMBER(FOGLIO) FROM(
                    SELECT COUNT(*), FOGLIO FROM DOCFA_FOGLI_MICROZONA
                    GROUP BY FOGLIO
                    HAVING COUNT(*) >1)
                    )          
                )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt; 

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_001 AS(
                SELECT DISTINCT C1.*, M.ZC AS ZC_2, M.OLD_MICROZONA AS OLD_MICROZONA_2, M.NEW_MICROZONA AS NEW_MICROZONA_2 FROM DOCFA_TEMP_NORES_002 C1
                LEFT JOIN DOCFA_FOGLI_MICROZONA M
                ON TO_NUMBER(C1.FOGLIO) = TO_NUMBER(M.FOGLIO) 
                AND TO_NUMBER(C1.ZONA)=TO_NUMBER(M.ZC) 
                AND TO_NUMBER(C1.FOGLIO) IN ( 
                    SELECT TO_NUMBER(FOGLIO) FROM(
                    SELECT COUNT(*), FOGLIO FROM DOCFA_FOGLI_MICROZONA
                    GROUP BY FOGLIO
                    HAVING COUNT(*) >1)
                    )
                )';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'UPDATE DOCFA_TEMP_NORES_001 SET ZC=ZC_2, OLD_MICROZONA=OLD_MICROZONA_2, NEW_MICROZONA=NEW_MICROZONA_2
              WHERE ZC_2 IS NOT NULL';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_TEMP_NORES_001 DROP COLUMN ZC_2';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_TEMP_NORES_001 DROP COLUMN OLD_MICROZONA_2';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_TEMP_NORES_001 DROP COLUMN NEW_MICROZONA_2';
    EXECUTE IMMEDIATE v_stmt;
    
    
    
    
    
    -- Aggiunta della classe minima 
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_002 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_002 AS(
                SELECT DISTINCT C1.*, M.CLASSE_MIN FROM DOCFA_TEMP_NORES_001 C1
                LEFT JOIN DOCFA_CLASSI_MIN M
                 ON C1.OLD_MICROZONA = M.OLD_MICROZONA 
                AND C1.CATEGORIA = M.CATEGORIA
                )';
    EXECUTE IMMEDIATE v_stmt;


    -- Aggiunta destinazione d'uso
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_001 AS(
                SELECT DISTINCT C2.*, H.NR_PROG FROM DOCFA_TEMP_NORES_002 C2
                LEFT JOIN DOCFA_IN_PARTE_DUE_H H
                 ON C2.FORNITURA = H.FORNITURA 
                AND C2.PROTOCOLLO_REGISTRAZIONE = H.PROTOCOLLO_REG
                AND TO_NUMBER(C2.FOGLIO)=TO_NUMBER(H.CT_FOGLIO_01)
                AND TRIM(C2.NUMERO)=TRIM(H.CT_NUMERO_01)
                AND NVL(C2.SUBALTERNO,''    '')=H.CT_SUBALTERNO_01
                )';
    EXECUTE IMMEDIATE v_stmt; 
      
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_002 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;
      
    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_002 AS(
                SELECT DISTINCT C1.*, H.NR_PROG AS NR_PROG_2 FROM DOCFA_TEMP_NORES_001 C1
                LEFT JOIN DOCFA_IN_PARTE_DUE_H H
                 ON C1.FORNITURA = H.FORNITURA 
                AND C1.PROTOCOLLO_REGISTRAZIONE = H.PROTOCOLLO_REG
                AND TO_NUMBER(C1.FOGLIO)=TO_NUMBER(H.CT_FOGLIO_02)
                AND TRIM(C1.NUMERO)=TRIM(H.CT_NUMERO_02)
                AND NVL(C1.SUBALTERNO,''    '')=H.CT_SUBALTERNO_02
                )';
    EXECUTE IMMEDIATE v_stmt;
       
       
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_001 AS(
                    SELECT DISTINCT C2.*, H.NR_PROG AS NR_PROG_3 FROM DOCFA_TEMP_NORES_002 C2
                    LEFT JOIN DOCFA_IN_PARTE_DUE_H H
                     ON C2.FORNITURA = H.FORNITURA 
                    AND C2.PROTOCOLLO_REGISTRAZIONE = H.PROTOCOLLO_REG
                    AND TO_NUMBER(C2.FOGLIO)=TO_NUMBER(H.CT_FOGLIO_03)
                    AND TRIM(C2.NUMERO)=TRIM(H.CT_NUMERO_03)
                    AND NVL(C2.SUBALTERNO,''    '')=H.CT_SUBALTERNO_03
                    )';
    EXECUTE IMMEDIATE v_stmt;
       
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_002 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_002 AS(
                SELECT DISTINCT C1.*, H.NR_PROG AS NR_PROG_4 FROM DOCFA_TEMP_NORES_001 C1
                LEFT JOIN DOCFA_IN_PARTE_DUE_H H
                 ON C1.FORNITURA = H.FORNITURA 
                AND C1.PROTOCOLLO_REGISTRAZIONE = H.PROTOCOLLO_REG
                AND TO_NUMBER(C1.FOGLIO)=TO_NUMBER(H.CT_FOGLIO_04)
                AND TRIM(C1.NUMERO)=TRIM(H.CT_NUMERO_04)
                AND NVL(C1.SUBALTERNO,''    '')=H.CT_SUBALTERNO_04
                )';
    EXECUTE IMMEDIATE v_stmt;
       
    v_stmt := 'UPDATE DOCFA_TEMP_NORES_002 SET NR_PROG=NR_PROG_2 
                WHERE NR_PROG IS NULL
                  AND NR_PROG_2 IS NOT NULL';
    EXECUTE IMMEDIATE v_stmt; 

    v_stmt := 'UPDATE DOCFA_TEMP_NORES_002 SET NR_PROG=NR_PROG_3 
        WHERE NR_PROG IS NULL
          AND NR_PROG_3 IS NOT NULL';
    EXECUTE IMMEDIATE v_stmt;
  
    v_stmt := 'UPDATE DOCFA_TEMP_NORES_002 SET NR_PROG=NR_PROG_4 
        WHERE NR_PROG IS NULL
          AND NR_PROG_3 IS NOT NULL';
    EXECUTE IMMEDIATE v_stmt;

    v_stmt := 'ALTER TABLE DOCFA_TEMP_NORES_002 DROP COLUMN NR_PROG_2';
    EXECUTE IMMEDIATE v_stmt; 
    
    v_stmt := 'ALTER TABLE DOCFA_TEMP_NORES_002 DROP COLUMN NR_PROG_3';
    EXECUTE IMMEDIATE v_stmt;
    
    v_stmt := 'ALTER TABLE DOCFA_TEMP_NORES_002 DROP COLUMN NR_PROG_4';
    EXECUTE IMMEDIATE v_stmt; 
    
    
    -- engono aggiunti  record da DOCFA_IN_PARTE_DUE_I  
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_001 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt; 
    
    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_001 AS(
            SELECT DISTINCT C2.*, I.DESTINAZIONE_USO FROM DOCFA_TEMP_NORES_002 C2
            LEFT JOIN DOCFA_IN_PARTE_DUE_I I
             ON C2.FORNITURA = I.FORNITURA 
            AND C2.PROTOCOLLO_REGISTRAZIONE = I.PROTOCOLLO_REG
            AND C2.NR_PROG = I.NR_PROG
            )';
    EXECUTE IMMEDIATE v_stmt; 
    
    -- sottraggo 3 classi nel caso di destinazione d'uso posto auto
    v_stmt := 'DROP TABLE DOCFA_TEMP_NORES_002 CASCADE CONSTRAINT';
    EXECUTE IMMEDIATE v_stmt; 

    v_stmt := 'CREATE TABLE DOCFA_TEMP_NORES_002 AS(
                SELECT DISTINCT C1.*, C1.CLASSE_MIN AS CLASSE_MIN_C06 FROM DOCFA_TEMP_NORES_001 C1
                )';
    EXECUTE IMMEDIATE v_stmt;  
    
    v_stmt := 'UPDATE DOCFA_TEMP_NORES_002 SET CLASSE_MIN_C06=(CLASSE_MIN_C06-3)
                WHERE DESTINAZIONE_USO LIKE ''%POSTO AUTO%'' ';
    EXECUTE IMMEDIATE v_stmt;  
      
    v_stmt := 'ALTER TABLE DOCFA_TEMP_NORES_002 ADD (DIFF  NUMBER)';
    EXECUTE IMMEDIATE v_stmt;  
    
    v_stmt := 'UPDATE DOCFA_TEMP_NORES_002 SET DIFF = (TO_NUMBER(CLASSE_MIN_C06)-TO_NUMBER(CLASSE)) 
                WHERE CLASSE <> ''U''
                  AND CLASSE IS NOT NULL
                  AND CLASSE_MIN <> ''U''
                  AND CLASSE_MIN IS NOT NULL ';
    EXECUTE IMMEDIATE v_stmt;  
      
      
    DECLARE TBL_EXIST  PLS_INTEGER;
      BEGIN
      SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DOCFA_REPORT_NORES';
      IF TBL_EXIST = 1 THEN 
      EXECUTE IMMEDIATE 'DROP TABLE DOCFA_REPORT_NORES CASCADE CONSTRAINT';
      END IF;
      END;
      
    v_stmt := 'CREATE TABLE DOCFA_REPORT_NORES AS (
              SELECT
              FORNITURA AS FORN,
              IDENTIFICATIVO_IMMOBILE AS ID_IMM,                 
              PROTOCOLLO_REGISTRAZIONE AS PROT,  
              TO_CHAR(TO_DATE(DATA_REGISTRAZIONE,''YYYYMMDD''),''DD/MM/YYYY'') AS DATA_REG,
              TO_NUMBER(FOGLIO) AS FOGLIO,                    
              NUMERO AS PART,                    
              TO_NUMBER(SUBALTERNO) AS SUB,                
              TO_NUMBER(ZONA) AS ZC_DOCFA,
              TO_NUMBER(ZC) AS ZC_CAT,
              TO_NUMBER(ZONA)-TO_NUMBER(ZC) AS ZC_DIFF,                     
              OLD_MICROZONA AS OLD_MZ,             
              NEW_MICROZONA AS NEW_MZ,             
              CATEGORIA AS CAT,                 
              (CASE WHEN CLASSE <> ''U'' THEN TO_CHAR(TO_NUMBER(CLASSE))
                                       ELSE CLASSE
               END) AS CLASSE,
              CLASSE_MIN,
              (CASE WHEN CATEGORIA = ''C06'' AND  DESTINAZIONE_USO LIKE ''%POSTO AUTO%'' THEN CLASSE_MIN_C06
                                                                                     ELSE NULL
               END) AS CLASSE_MIN_C06,                
              DIFF,
              TRIM(DESTINAZIONE_USO) AS DEST_USO,                      
              TO_NUMBER(CONSISTENZA) AS CONSISTENZA,               
              TO_NUMBER(SUPERFICIE) AS SUPERFICIE,                
              TO_NUMBER(RENDITA_EURO) AS RENDITA_DOCFA,
              TRIM(TOPONIMO) AS TOPONIMO,                  
              TRIM(INDIRIZZO) AS INDIRIZZO,                 
              CIVICO_1,                  
              TRIM(DIC_COGNOME) AS DIC_COGNOME,               
              TRIM(DIC_NOME) AS DIC_NOME,
              TRIM(TEC_COGNOME) AS TEC_COGNOME,
              TRIM(TEC_NOME) AS TEC_NOME,                  
              FLAG_NC AS NC,
              PRESENZA_GRAFFATI AS GRAFFATI,
              TIPO_OPERAZIONE
              FROM DOCFA_TEMP_NORES_002
              )';
    EXECUTE IMMEDIATE v_stmt;
    
  END;
  

END DOCFA_REP_NORES;
/


DROP PROCEDURE DIOGENE_H501.IA_ACCESSI_ISOLA_ECOLOGICA;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.IA_ACCESSI_ISOLA_ECOLOGICA( idTestata number) AS
BEGIN
    DECLARE
    TBL_EXIST  NUMBER;
    BEGIN
    SELECT COUNT(*) INTO TBL_EXIST FROM USER_TABLES WHERE TABLE_NAME = 'DIA_ACCESSI_ISOLE_ECOLOGICHE';
    IF TBL_EXIST = 1 THEN
        EXECUTE IMMEDIATE 'TRUNCATE TABLE DIA_ACCESSI_ISOLE_ECOLOGICHE';
        EXECUTE IMMEDIATE 'COMMIT';
    ELSE
          DECLARE
            v_stmt VARCHAR2(4000);
          BEGIN
            v_stmt := 'CREATE TABLE DIA_ACCESSI_ISOLE_ECOLOGICHE (
                  ID                      NUMBER                        NOT NULL,
                  FK_DIA_TESTATA          NUMBER                        NOT NULL,
                  CODICE                  VARCHAR2(50 BYTE),
                  COGNOME_DENOM         VARCHAR2(500 BYTE),
                  NOME                  VARCHAR2(500 BYTE),
                  CODICE_FISCALE        VARCHAR2(50 BYTE),
                  BELFIORE                VARCHAR2(50 BYTE),
                  COMUNE                VARCHAR2(50 BYTE),
                  PROV                    VARCHAR2(50 BYTE),
                  INDIRIZZO                VARCHAR2(50 BYTE),
                  CIVICO                VARCHAR2(50 BYTE),
                  COD_FAM                VARCHAR2(50 BYTE),
                  INTESTATARIO            VARCHAR2(50 BYTE),
                  TIPO_UTENZA            VARCHAR2(50 BYTE),
                  NUTENZE                VARCHAR2(50 BYTE)
                  ) ';

            EXECUTE IMMEDIATE v_stmt;
        END;

    END IF;
    END;

    DECLARE
    TARSU_EXIST  NUMBER;
    BEGIN

    SELECT COUNT(*) INTO TARSU_EXIST FROM(
    select distinct cont.id_ext_sogg, sogg.cod_fisc cf, sogg.part_iva piva, sogg.cog_denom cognome_denom, sogg.nome, sogg.dt_nsc dt_nascita,
    case when sogg.des_ind_res is not null then des_ind_res else ind_res_ext end as descrizione_via,
    case when sogg.num_civ_res is not null then case when esp_civ_res is null then num_civ_res else num_civ_res||'/'||esp_civ_res end else num_civ_ext end as civ_res,
    sogg.cap_com_res cap_res_comune_res, sogg.des_com_res, sogg.sigla_prov_res prov_res,
    sogg.des_stato_res nazione
    from sit_t_tar_sogg sogg
    left join sit_t_tar_contrib cont
    on sogg.id_ext=cont.id_ext_sogg
    and cont.dt_fine_val is null
    and cont.dt_fine_dato is null
    where sogg.dt_fine_val is null
    and sogg.dt_fine_dato is null
    order by sogg.cog_denom, sogg.nome
    );

    IF TARSU_EXIST > 0 THEN
        --SI PARTE DALLA TARSU
        DECLARE
         v_stmt VARCHAR2(4000);
        BEGIN
            v_stmt := 'TRUNCATE TABLE DIA_ACCESSI_ISOLE_ECO_TMP ';

            EXECUTE IMMEDIATE v_stmt;

            v_stmt := 'INSERT INTO DIA_ACCESSI_ISOLE_ECO_TMP (
            ID_EXT_SOGG, CF, PIVA, COGNOME_DENOM, NOME, DT_NASCITA, DESCRIZIONE_VIA, CIV_RES, CAP_RES_COMUNE_RES, DES_COM_RES, PROV_RES, NAZIONE)
            select distinct cont.id_ext_sogg, sogg.cod_fisc cf, sogg.part_iva piva, sogg.cog_denom cognome_denom, sogg.nome, sogg.dt_nsc dt_nascita,
            case when sogg.des_ind_res is not null then des_ind_res else ind_res_ext end as descrizione_via,
            case when sogg.num_civ_res is not null then case when esp_civ_res is null then num_civ_res else num_civ_res||''/''||esp_civ_res end else num_civ_ext end as civ_res,
            sogg.cap_com_res cap_res_comune_res, sogg.des_com_res, sogg.sigla_prov_res prov_res,
            sogg.des_stato_res nazione
            from sit_t_tar_sogg sogg
            left join sit_t_tar_contrib cont
            on sogg.id_ext=cont.id_ext_sogg
            and cont.dt_fine_val is null
            and cont.dt_fine_dato is null
            where sogg.dt_fine_val is null
            and sogg.dt_fine_dato is null
            order by sogg.cog_denom, sogg.nome ';

            EXECUTE IMMEDIATE v_stmt;

            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add dati_oggetti varchar2(1000 byte) ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=null;


            update DIA_ACCESSI_ISOLE_ECO_TMP set CF=PIVA WHERE (cf is null or nvl( length(trim(cf)), 0 )=0 ) and PIVA is not null;

            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add nutenze number; ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set nutenze=null;

            execute immediate 'COMMIT';

            begin
            declare cursor c is select distinct id_ext_sogg from DIA_ACCESSI_ISOLE_ECO_TMP;
            begin
                for rec_c in c
                loop
                    declare
                    errore varchar2(255 byte);
                    info varchar2(1000 byte);
                    conta number;

                    begin
                        declare cursor c2 is
                        select distinct trim(des_ind||' '||num_civ||' '||esp_civ) ind
                        from sit_t_tar_oggetto ogg
                        inner join sit_t_tar_contrib cont
                        on cont.id_ext_ogg_rsu=ogg.id_ext
                        where cont.id_ext_sogg=rec_c.id_ext_sogg
                        and ogg.dt_fine_val is null
                        and ogg.dt_fine_dato is null
                        and ogg.des_ind is not null
                        and cont.dt_fine_val is null
                        and cont.dt_fine_dato is null
                        order by ind;


                        begin

                            conta:=0;
                            info:= null;

                            for rec_c2 in c2
                                loop
                                    if info is null then
                                     info:=rec_c2.ind;
                                    else
                                      info:=info||' / '||rec_c2.ind;
                                    end if;
                                    conta:=conta+1;
                                end loop;
                        end;

                        update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=info, nutenze=conta
                        where id_ext_sogg=rec_c.id_ext_sogg;

                        commit;

                        exception when others then
                        dbms_output.put_line('Proc1-'||rec_c.id_ext_sogg);
                        errore:=substr(sqlerrm,1,255);
                        dbms_output.put_line('Errore'||' '||errore);
                    end;
                commit;
                end loop;
            end;
        end;

        END;

    ELSE
        --SI PARTE DAL RUOLO
        DECLARE
            v_stmt VARCHAR2(4000);
        BEGIN
            v_stmt := 'TRUNCATE TABLE DIA_ACCESSI_ISOLE_ECO_TMP ';

            EXECUTE IMMEDIATE v_stmt;

            v_stmt := 'INSERT INTO DIA_ACCESSI_ISOLE_ECO_TMP (
                COD_COMUNE_ISCR_RUOLO, COD_PARTITA, PROGRESSIVO_MINUTA, CF, COGNOME_DENOM, NOME, DT_NASCITA, DESCRIZIONE_VIA, CIV_RES, CAP_RES_COMUNE_RES, COD_BELFIORE )
                select distinct n2.cod_comune_iscr_ruolo, n2.cod_partita, n2.progressivo_minuta, n2.cod_fiscale cf,
                case when n2.cognome is not null then n2.cognome else denominazione end cognome_denom,
                n2.nome nome, to_date(decode(n2.dt_nascita,''0'',null,''00000000'',null,dt_nascita),''ddmmyyyy'') dt_nascita,
                n2.indirizzo descrizione_via,
                case when n2.numero_civico is not null then case when n2.lettera_numero_civico is null then to_char(n2.numero_civico) else numero_civico||''/''||lettera_numero_civico end end as civ_res,
                n2.cap cap_res_comune_res, n2.cod_belfiore
                from RE_CNC_N2_ANA_INTEST_RUOLO n2 ';

            EXECUTE IMMEDIATE v_stmt;

            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add dati_oggetti varchar2(1000 byte) ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=null;

            --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add nutenze number; ';
            update DIA_ACCESSI_ISOLE_ECO_TMP set nutenze=null;

            execute immediate 'COMMIT';

            begin
                declare cursor c is select distinct cod_partita from DIA_ACCESSI_ISOLE_ECO_TMP;
                begin
                    for rec_c in c
                    loop
                        declare
                        errore varchar2(255 byte);
                        info varchar2(1000 byte);
                        conta number;

                        begin
                            declare cursor c2 is
                            select distinct info_cartella
                            from RE_CNC_N4_DATI_CONT
                            where cod_partita=rec_c.cod_partita
                            order by info_cartella;

                            begin

                                conta:=0;
                                info:= null;

                                for rec_c2 in c2
                                    loop
                                        if info is null then
                                         info:=rec_c2.info_cartella;

                                        else
                                          info:=info||' / '||rec_c2.info_cartella;

                                        end if;
                                        conta:=conta+1;
                                    end loop;
                            end;

                            update DIA_ACCESSI_ISOLE_ECO_TMP set dati_oggetti=info, nutenze=conta
                            where cod_partita=rec_c.cod_partita;


                            commit;

                            exception when others then
                            dbms_output.put_line('Proc1-'||rec_c.cod_partita);
                            errore:=substr(sqlerrm,1,255);
                            dbms_output.put_line('Errore'||' '||errore);
                        end;
                    commit;
                    end loop;
                end;
            end;

        END;

    END IF;

    --INIZIO PARTE IN COMUNE

    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add id_sogg number(5) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP  set id_sogg=rownum;

    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add res varchar2(10) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP set res = null;

    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add id_per varchar2(100 byte) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP set id_per = null;
    --commit;
    execute immediate 'COMMIT';


    begin
        declare cursor c is select distinct id_sogg from DIA_ACCESSI_ISOLE_ECO_TMP order by id_sogg;
        begin
            for rec_c in c
            loop
                declare
                errore varchar2(255byte);
                p_ana varchar2(10);
                id_sogge varchar2(100);
                  begin
                    select distinct posiz_ana into p_ana
                      from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                     where c1.id_sogg=rec_c.id_sogg
                       and p.codfisc = c1.cf
                       and p.dt_fine_val is null
                       and p.dt_fine_dato is null
                       and p.posiz_ana is not null
                       and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) =
                       (
                       nvl(
                       (select max(data_inizio_residenza)
                       from sit_d_persona
                       where codfisc=c1.cf
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                       )
                       );

                    select distinct id_ext into id_sogge
                      from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                     where c1.id_sogg=rec_c.id_sogg
                      and p.codfisc = c1.cf
                       and p.dt_fine_val is null
                       and p.dt_fine_dato is null
                       and p.posiz_ana is not null
                       and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) =
                       (
                       nvl(
                       (select max(data_inizio_residenza)
                       from sit_d_persona
                       where codfisc=c1.cf
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                        )
                       );

                    if p_ana is null then
                     select posiz_ana into p_ana
                       from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                      where c1.id_sogg=rec_c.id_sogg
                        and p.cognome = c1.cognome_denom
                        and p.nome = c1.nome
                        and p.data_nascita = c1.dt_nascita
                        and p.dt_fine_val is null
                        and p.dt_fine_dato is null
                        and p.posiz_ana is not null
                        and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) =
                       (
                       nvl(
                       (select max(data_inizio_residenza)
                       from sit_d_persona
                       where cognome = c1.cognome_denom
                        and nome = c1.nome
                        and data_nascita = c1.dt_nascita
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                        )
                       );
                    end if;

                    if id_sogge is null then
                     select distinct id_ext into id_sogge
                       from DIA_ACCESSI_ISOLE_ECO_TMP c1, sit_d_persona p
                      where c1.id_sogg=rec_c.id_sogg
                        and p.cognome = c1.cognome_denom
                        and p.nome = c1.nome
                        and p.data_nascita = c1.dt_nascita
                        and p.dt_fine_val is null
                        and p.dt_fine_dato is null
                        and p.posiz_ana is not null
                        and nvl(p.data_inizio_residenza, to_date('01/01/1900', 'dd/MM/yyyy')) =
                       (
                       nvl(
                       (select max(data_inizio_residenza)
                       from sit_d_persona
                       where cognome = c1.cognome_denom
                        and nome = c1.nome
                        and data_nascita = c1.dt_nascita
                       and dt_fine_val is null
                       and dt_fine_dato is null
                       and posiz_ana is not null),  to_date('01/01/1900', 'dd/MM/yyyy')
                       )
                       );
                    end if;


                    update DIA_ACCESSI_ISOLE_ECO_TMP set res = p_ana
                    where id_sogg=rec_c.id_sogg;

                    update DIA_ACCESSI_ISOLE_ECO_TMP set id_per=id_sogge
                    where id_sogg=rec_c.id_sogg;

                    exception
                    when no_data_found then null;
                    when others then
                    dbms_output.put_line('Proc2-'||rec_c.id_sogg);
                    errore:=substr(sqlerrm,1,255);
                    dbms_output.put_line('Errore'||' '||errore);
                end;
            commit;
            end loop;
        end;
    end;


    --execute immediate ' alter table DIA_ACCESSI_ISOLE_ECO_TMP add n_fam varchar2(100 byte) ';
    update DIA_ACCESSI_ISOLE_ECO_TMP set n_fam = null;

    execute immediate 'update DIA_ACCESSI_ISOLE_ECO_TMP c1 set n_fam = (select id_ext_d_famiglia from sit_d_pers_fam pf where id_ext_d_persona=c1.id_per and pf.dt_fine_val is null and pf.dt_fine_dato is null)';

    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add viasedime varchar2(20) ';
    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add descrizione varchar2(200) ';
    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add civico varchar2(20) ';

    update DIA_ACCESSI_ISOLE_ECO_TMP set viasedime = null;
    update DIA_ACCESSI_ISOLE_ECO_TMP set descrizione = null;
    update DIA_ACCESSI_ISOLE_ECO_TMP set civico = null;

    execute immediate 'COMMIT';


    declare cursor c is select distinct id_sogg from DIA_ACCESSI_ISOLE_ECO_TMP where res is not null;
    begin
        for rec_c in c
        loop
            declare
            errore varchar2(255byte);
            begin
                update DIA_ACCESSI_ISOLE_ECO_TMP set (viasedime, descrizione, civico) =
                     (  select distinct trim(v.viasedime), trim(v.descrizione),
                        case when ltrim(extractValue(c.civico_composto, '//att[1]/@valore'),'0') is not null then ltrim(extractValue(c.civico_composto, '//att[1]/@valore'),'0') end ||
                        case when ltrim(extractValue(c.civico_composto, '//att[2]/@valore'),'0') is not null then '/'|| ltrim(extractValue(c.civico_composto, '//att[2]/@valore'),'0') end ||
                        case when ltrim(extractValue(c.civico_composto, '//att[3]/@valore'),'0') is not null then '/'||ltrim(extractValue(c.civico_composto, '//att[3]/@valore'),'0') end civico
                        from sit_d_persona p, sit_d_persona_civico pc, sit_d_via v, sit_d_civico c, DIA_ACCESSI_ISOLE_ECO_TMP c1
                        where c1.id_sogg=rec_c.id_sogg
                        and (p.codfisc =c1.cf or (p.cognome=c1.cognome_denom and p.nome=c1.nome and p.data_nascita=c1.dt_nascita))
                        and p.dt_fine_val is null
                        and p.dt_fine_dato is null
                        and p.id_ext = pc.id_ext_d_persona
                        and pc.dt_fine_val is null
                        and pc.dt_fine_dato is null
                        and pc.id_ext_d_civico=c.id_ext
                        and c.dt_fine_val is null
                        and c.dt_fine_dato is null
                        and c.id_ext_d_via=v.id_ext
                        and v.dt_fine_val is null
                        and v.dt_fine_dato is null
                        and rownum=1
                     )
                where id_sogg=rec_c.id_sogg;
                exception when others then
                dbms_output.put_line('Proc3-'||rec_c.id_sogg);
                errore:=substr(sqlerrm,1,255);
                dbms_output.put_line('Errore'||' '||errore);
            end;
        commit;
        end loop;
    end;


    --execute immediate 'alter table DIA_ACCESSI_ISOLE_ECO_TMP add res_civ number (10)';

    execute immediate 'update DIA_ACCESSI_ISOLE_ECO_TMP set res_civ=1 where descrizione_via = viasedime ||'' ''|| descrizione and civ_res = civico ';
    execute immediate 'COMMIT';




                -- INIZIO PERSONALIZZAZIONE STORED
                DECLARE
        COD_NAZIONALE VARCHAR2(50);
        BEGIN
                                               SELECT CODENT INTO COD_NAZIONALE FROM SIT_ENTE;
                                               IF COD_NAZIONALE = 'F704' OR COD_NAZIONALE = 'D385' OR COD_NAZIONALE = 'D384' THEN

                                                               -- PARTE DEDICATA A MONZA IN CUI SIT_D_PERS_FAM.ID_EXT_D_FAMIGLIA NON è NUMERICO MA STRINGA

                                                               execute immediate 'INSERT INTO DIA_ACCESSI_ISOLE_ECOLOGICHE
                                                                              (ID, FK_DIA_TESTATA, CODICE, COGNOME_DENOM, NOME, CODICE_FISCALE, BELFIORE, COMUNE, PROV, INDIRIZZO, CIVICO, COD_FAM, INTESTATARIO, TIPO_UTENZA, NUTENZE)
                                                               select SEQ_DIA_ACCESSI_ISOLE_ECO.nextval, ' || idTestata || ', codice, cognome_denom, nome, CF, cod_belfiore, comune, prov, indirizzo, civ, codfam, intestatario, tipoutenza,  nutenze from
                                                               (
                                                               select distinct substr(id_per,0,10) codice, cognome_denom, c1.nome, CF, com.codi_fisc_luna cod_belfiore,
                                                               des_com_res comune, prov_res prov,
                                                               descrizione_via indirizzo, ltrim(civ_res,''0'') civ,
                                                               substr(n_fam,0,10) codfam, 1 intestatario, case when length(cf)=16 then 0 else 1 end tipoutenza,  nutenze
                                                               from DIA_ACCESSI_ISOLE_ECO_TMP c1
                                                               left join AM_BELFIORE_COMUNE com
                                                               on c1.des_com_res=com.nome_comune
                                                               where cognome_denom is not null
                                                               union
                                                               select DISTINCT substr(p.id_ext,0,10) codice, p.cognome, p.nome, p.codfisc,
                                                               (SELECT DISTINCT SE.CODENT FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) cod_belfiore,
                                                               (SELECT DISTINCT SE.DESCRIZIONE FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) comune,
                                                               (SELECT DISTINCT SC.SIGLA_PROV FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) prov,
                                                               trim(v.viasedime) ||'' ''|| trim(v.descrizione) indirizzo,
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') is not null then ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') is not null then ''/''|| ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') is not null then ''/''||ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') end civico,
                                                               substr(pf.id_ext_d_famiglia,0,10) codfam, 0 intestatario, 0 as tipoutenza,  ''0'' nutenze
                                                               from sit_d_persona p, sit_d_persona_civico pc, sit_d_via v, sit_d_civico c, sit_d_pers_fam pf
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.id_ext = pc.id_ext_d_persona
                                                               and pc.dt_fine_val is null
                                                               and (pc.dt_fine_dato is null or pc.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and pc.id_ext_d_civico=c.id_ext
                                                               and c.dt_fine_val is null
                                                               and c.dt_fine_dato is null
                                                               and c.id_ext_d_via=v.id_ext
                                                               and v.dt_fine_val is null
                                                               and v.dt_fine_dato is null
                                                               and pf.id_ext_d_persona=p.id_ext
                                                               and pf.dt_fine_val is null
                                                               and (pf.dt_fine_dato is null or pf.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and p.id_ext in (
                                                               select distinct id_ext from sit_d_persona p
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.posiz_ana=''A''
                                                               minus
                                                               select distinct id_per from DIA_ACCESSI_ISOLE_ECO_TMP
                                                               )
                                                               and p.cognome is not null
                                                               order by cognome_denom, nome
                                                               ) ';


                                               ELSE

                                                               -- PARTE DEDICATA A TUTTI QUEI COMUNI CHE HANNO SIT_D_PERS_FAM.ID_EXT_D_FAMIGLIA NUMERICO

                                                               execute immediate 'INSERT INTO DIA_ACCESSI_ISOLE_ECOLOGICHE
                                                                              (ID, FK_DIA_TESTATA, CODICE, COGNOME_DENOM, NOME, CODICE_FISCALE, BELFIORE, COMUNE, PROV, INDIRIZZO, CIVICO, COD_FAM, INTESTATARIO, TIPO_UTENZA, NUTENZE)
                                                               select SEQ_DIA_ACCESSI_ISOLE_ECO.nextval, ' || idTestata || ', codice, cognome_denom, nome, CF, cod_belfiore, comune, prov, indirizzo, civ, codfam, intestatario, tipoutenza,  nutenze from
                                                               (
                                                               select distinct to_number(substr(id_per,0,10)) codice, cognome_denom, c1.nome, CF, com.codi_fisc_luna cod_belfiore,
                                                               des_com_res comune, prov_res prov,
                                                               descrizione_via indirizzo, ltrim(civ_res,''0'') civ,
                                                               to_number(substr(n_fam,0,10)) codfam, 1 intestatario, case when length(cf)=16 then 0 else 1 end tipoutenza,  nutenze
                                                               from DIA_ACCESSI_ISOLE_ECO_TMP c1
                                                               left join AM_BELFIORE_COMUNE com
                                                               on c1.des_com_res=com.nome_comune
                                                               where cognome_denom is not null
                                                               union
                                                               select DISTINCT to_number(substr(p.id_ext,0,10)) codice, p.cognome, p.nome, p.codfisc,
                                                               (SELECT DISTINCT SE.CODENT FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) cod_belfiore,
                                                               (SELECT DISTINCT SE.DESCRIZIONE FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) comune,
                                                               (SELECT DISTINCT SC.SIGLA_PROV FROM SIT_ENTE SE LEFT JOIN SITICOMU SC ON SE.CODENT = SC.CODI_FISC_LUNA) prov,
                                                               trim(v.viasedime) ||'' ''|| trim(v.descrizione) indirizzo,
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') is not null then ltrim(extractValue(c.civico_composto, ''//att[1]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') is not null then ''/''|| ltrim(extractValue(c.civico_composto, ''//att[2]/@valore''),''0'') end ||
                                                               case when ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') is not null then ''/''||ltrim(extractValue(c.civico_composto, ''//att[3]/@valore''),''0'') end civico,
                                                               to_number(substr(pf.id_ext_d_famiglia,0,10)) codfam, 0 intestatario, 0 as tipoutenza,  ''0'' nutenze
                                                               from sit_d_persona p, sit_d_persona_civico pc, sit_d_via v, sit_d_civico c, sit_d_pers_fam pf
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.id_ext = pc.id_ext_d_persona
                                                               and pc.dt_fine_val is null
                                                               and (pc.dt_fine_dato is null or pc.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and pc.id_ext_d_civico=c.id_ext
                                                               and c.dt_fine_val is null
                                                               and c.dt_fine_dato is null
                                                               and c.id_ext_d_via=v.id_ext
                                                               and v.dt_fine_val is null
                                                               and v.dt_fine_dato is null
                                                               and pf.id_ext_d_persona=p.id_ext
                                                               and pf.dt_fine_val is null
                                                               and (pf.dt_fine_dato is null or pf.dt_fine_dato=to_date(''01011777'',''ddmmyyyy''))
                                                               and p.id_ext in (
                                                               select distinct id_ext from sit_d_persona p
                                                               where p.dt_fine_val is null
                                                               and p.dt_fine_dato is null
                                                               and p.posiz_ana=''A''
                                                               minus
                                                               select distinct id_per from DIA_ACCESSI_ISOLE_ECO_TMP
                                                               )
                                                               and p.cognome is not null
                                                               order by cognome_denom, nome
                                                               ) ';


                                               END IF;
                               END;

                -- FINE PERSONALIZZAZIONE STORED



    execute immediate 'COMMIT';


    END;

END DIA_ACCESSI_ISOLA_ECOLOGICA;
/


DROP PROCEDURE DIOGENE_H501.SETAR_FROM_TEMP_TO_SETAR;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.SETAR_FROM_TEMP_TO_SETAR(BELFIORE IN VARCHAR2)
IS
CANTIDAD NUMBER(3);

PRAGMA AUTONOMOUS_TRANSACTION;

BEGIN

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'SETAR_ELAB';
IF (CANTIDAD >0) THEN
        execute immediate 'DELETE FROM SETAR_ELAB ';
        commit;
END IF;

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'SETAR_STAT';
IF (CANTIDAD >0) THEN
        execute immediate 'DELETE FROM SETAR_STAT ';
        commit;
END IF;

execute immediate ' Insert into SETAR_ELAB (ID, CODI_FISC_LUNA, ID_SEZC, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, UNIMM, CATEGORIA, CLASSE, CONSISTENZA, RENDITA, SUP_CAT, SUP_TARSU, STATO_CATASTO, SUP_CAT_TARSU, SUP_CAT_TARSU_80, DELTA_DICH_80, SUP_A, SUP_B, SUP_C, SUP_D, SUP_E, SUP_F, SUP_G, SUP_H, SUP_I, SUP_L, SUP_CAT_DPR138_98, DELTA_SUP_CAT_CALC, SUP_CAT_TARSU_CALC, DELTA_SUP_CAT_TARSU_CALC, VANO) SELECT SEQ_SETAR.NEXTVAL, CODI_FISC_LUNA, ID_SEZC, COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, UNIMM, CATEGORIA, CLASSE, CONSISTENZA, RENDITA, SUP_CAT, SUP_TARSU, STATO_CATASTO, SUP_CAT_TARSU, SUP_CAT_TARSU_80, DELTA_DICH_80, SUP_A, SUP_B, SUP_C, SUP_D, SUP_E, SUP_F, SUP_G, SUP_H, SUP_I, SUP_L, SUP_CAT_DPR138_98, DELTA_SUP_CAT_CALC, SUP_CAT_TARSU_CALC, DELTA_SUP_CAT_TARSU_CALC, VANO FROM TEMP_001 ';

execute immediate ' Insert into SETAR_STAT (CATEGORIA, NUMERO, SUM_CONSISTENZA, SUM_SUP_CAT_TARSU, SUM_SUP_CAT_TARSU_80, SUP_0, SUM_CONS_SUP_0, ID, CODI_FISC_LUNA) SELECT CATEGORIA, NUMERO, SUM_CONSISTENZA, SUM_SUP_CAT_TARSU, SUM_SUP_CAT_TARSU_80, SUP_0, SUM_CONS_SUP_0, SEQ_SETAR.NEXTVAL , ''' || BELFIORE || ''' FROM TEMP_003 ';

commit;

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'TEMP_001';
IF (CANTIDAD >0) THEN
        execute immediate 'DROP TABLE TEMP_001  CASCADE CONSTRAINTS ';
END IF;

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'TEMP_002';
IF (CANTIDAD >0) THEN
        execute immediate 'DROP TABLE TEMP_002  CASCADE CONSTRAINTS ';
END IF;

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'TEMP_003';
IF (CANTIDAD >0) THEN
        execute immediate 'DROP TABLE TEMP_003  CASCADE CONSTRAINTS ';
END IF;

END;
/


DROP PROCEDURE DIOGENE_H501.SETAR_SET_DIA;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.SETAR_SET_DIA
IS
CANTIDAD NUMBER(3);

PRAGMA AUTONOMOUS_TRANSACTION;

BEGIN

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'SETAR_DIA';
IF (CANTIDAD >0) THEN
        execute immediate 'DELETE FROM SETAR_DIA ';
        commit;
END IF;

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(1, ''DATA ULTIMA ELABORAZIONE TARES'',  ( select To_char(SYSDATE,''dd/MM/yyyy'') from dual) ) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(2, ''DATA ULTIMO AGGIORNAMENTO CATASTO'', ( SELECT Max(To_Date(p_max.dt_rif,''dd/MM/yyyy'')) AS data_agg FROM load_cat_prm_incr p_min, load_cat_prm_incr p_max WHERE p_min.dt_carico = (select min(dt_carico) from load_cat_prm_incr) AND p_max.dt_carico = (select max(dt_carico) from load_cat_prm_incr))) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(3, ''NUM. UNITA IMMOBILIARI ATTIVE ALLA DATA DI ULTIMO AGGIORNAMENTO'',  ( select count(*) from sitiuiu where data_fine_val=to_date(''99991231'',''yyyymmdd'') ) ) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(4, ''NUM. UNITA IMMOBILIARI CON SUPERFICIE CATASTALE (dal file FAB) VALORIZZATA'',  ( select count(*) from temp_001 where sup_cat is not null ) ) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(5, ''NUM. UNITA IMMOBILIARI CON SUPERFICIE DICHIARATA TARSU VALORIZZATA (agganciata per foglio, particella, subalterno)'',  ( select count(*) from temp_001 where sup_tarsu is not null ) ) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(6, ''NUM. OGGETTI TARSU'',  ( select count(*) from sit_t_tar_oggetto where dat_fin is null ) ) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(7, ''NUM. OGGETTI TARSU CON COORDINATE CATASTALI VALORIZZATE'',  ( select count(*) from sit_t_tar_oggetto where dat_fin is null and foglio is not null and numero is not null ) ) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(8, ''NUM. UNITA IMMOBILIARI CON SUPERFICIE CATASTALE AI FINI TARSU (da file DAT) NULLA'',  ( select count(*) from temp_001 where (sup_cat_tarsu is null or sup_Cat_tarsu=0) and categoria <> ''-''  ) ) ';

execute immediate ' insert into SETAR_DIA ( ID, DESCRIZIONE, VALORE ) VALUES(9, ''NUM. UNITA IMMOBILIARI CON DATI METRICI NON VALORIZZATI'',  ( select count(*) from temp_001 where sup_cat_dpr138_98 is null ) ) ';

commit;

END;
/


DROP PROCEDURE DIOGENE_H501.SETAR_SET_TEMP001_SUP_TARSU;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.SETAR_SET_TEMP001_SUP_TARSU 
IS

PRAGMA AUTONOMOUS_TRANSACTION;

begin
declare cursor c is 
select distinct t1.foglio, t1.particella, t1.unimm 
from DIOGENE_GIT.temp_001 t1, DIOGENE_GIT.temp_002 ogg
where ltrim(ogg.foglio, '0')=t1.foglio
and lpad(ogg.numero,5,'0')=lpad(t1.particella,5,'0')
and ltrim(ogg.sub, '0')=t1.unimm;

max_data_ini date;

    begin
        for rec_c in c
        loop
        
            select max(dat_ini) into max_data_ini 
            from DIOGENE_GIT.temp_002
            where  ltrim(foglio, '0')=rec_c.foglio
            and lpad(numero,5,'0')=lpad(rec_c.particella,5,'0')
            and  ltrim(sub, '0')=rec_c.unimm;
        
            update DIOGENE_GIT.temp_001 set sup_tarsu=
                (select sum(sup_tot) from DIOGENE_GIT.temp_002
                 where  ltrim(foglio, '0')=rec_c.foglio
                 and lpad(numero,5,'0')=lpad(rec_c.particella,5,'0')
                 and  ltrim(sub, '0')=rec_c.unimm
                 and dat_ini=max_data_ini)
            where  ltrim(foglio, '0') = rec_c.foglio
            and lpad(particella,5,'0')=lpad(rec_c.particella,5,'0')
            and  ltrim(unimm, '0')=rec_c.unimm;
            
            commit;
        end loop;
    end;
end;
/


