DROP PROCEDURE DIOGENE_H501.SETAR_SET_TEMP001_SUP_X_CAT1;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.SETAR_SET_TEMP001_SUP_X_CAT1 
IS

PRAGMA AUTONOMOUS_TRANSACTION;


begin

declare 
sup_princ number;
sup_acc number;
sup_cata number;


cursor c is select distinct cod_nazionale, foglio, particella, sub, unimm, categoria, 
sup_a, sup_i, sup_l, sup_b, sup_c, sup_d, sup_e, sup_f, sup_g, sup_h from temp_001;

    begin
        for rec_c in c
        loop
          declare errore varchar2(255byte);
          begin
            
            sup_princ:=0;
            sup_acc:=0;
            sup_cata:=0;

            if rec_c.categoria in ('A01','A02','A03','A04','A05','A06','A09','A11')
            then 
                sup_princ:=nvl(rec_c.sup_a,0) + nvl(rec_c.sup_h,0);
                
                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25+
                case when nvl(rec_c.sup_d,0)<=25 then nvl(rec_c.sup_d,0)*0.3 else 7.5+(rec_c.sup_d-25)*0.1 end +
                case when nvl(rec_c.sup_e,0)<=25 then nvl(rec_c.sup_e,0)*0.15 else 3.75+(rec_c.sup_e-25)*0.05 end +
                case when nvl(rec_c.sup_f,0)<=nvl(rec_c.sup_a,0) then nvl(rec_c.sup_f,0)*0.10 else nvl(rec_c.sup_a,0)*0.10+(rec_c.sup_f-rec_c.sup_a)*0.02 end;
                
                if sup_acc < 0.5 * sup_princ 
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5*sup_princ;
                end if;
                
            end if;

            if rec_c.categoria in ('A07','A08')
            then 
                sup_princ:=nvl(rec_c.sup_a,0) + nvl(rec_c.sup_h,0);
                
                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25+
                case when nvl(rec_c.sup_d,0)<=25 then nvl(rec_c.sup_d,0)*0.3 else 7.5+(rec_c.sup_d-25)*0.1 end +
                case when nvl(rec_c.sup_e,0)<=25 then nvl(rec_c.sup_e,0)*0.15 else 3.75+(rec_c.sup_e-25)*0.05 end +
                case when nvl(rec_c.sup_f,0) > 5 * nvl(rec_c.sup_a,0) then 
                case when nvl(rec_c.sup_f,0)-5*nvl(rec_c.sup_a,0)<=nvl(rec_c.sup_a,0) then (nvl(rec_c.sup_f,0)-5*nvl(rec_c.sup_a,0))*0.10 else nvl(rec_c.sup_a,0)*0.10+(rec_c.sup_f-6*rec_c.sup_a)*0.02 end
                else 0
                end;
                
                if sup_acc < 0.5 * sup_princ
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5*sup_princ;
                end if;
                
            end if;

            if rec_c.categoria in ('B01','B02','B03','B04','B05','B06','B07')
            then 
                sup_princ:=nvl(rec_c.sup_a,0) + nvl(rec_c.sup_h,0);
                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25+nvl(rec_c.sup_d,0)*0.1+nvl(rec_c.sup_e,0)*0.1;
                
                if sup_acc < 0.5 * sup_princ
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5*sup_princ;
                end if;
            end if;            

            if rec_c.categoria in ('C01')
            then 
                sup_cata := nvl(rec_c.sup_i,0)+nvl(rec_c.sup_l,0)*0.5+nvl(rec_c.sup_h,0)+nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25+nvl(rec_c.sup_d,0)*0.1+nvl(rec_c.sup_e,0)*0.1+nvl(rec_c.sup_f,0)*0.2;
            end if;            
            
            if rec_c.categoria in ('C06')
            then 
                sup_princ:=nvl(rec_c.sup_i,0)+nvl(rec_c.sup_l,0)*0.5+nvl(rec_c.sup_h,0);
                
                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25+
                case when nvl(rec_c.sup_d,0)<=25 then nvl(rec_c.sup_d,0)*0.3 else 7.5+(rec_c.sup_d-25)*0.1 end +
                case when nvl(rec_c.sup_e,0)<=25 then nvl(rec_c.sup_e,0)*0.15 else 3.75+(rec_c.sup_e-25)*0.05 end +
                case when nvl(rec_c.sup_f,0)<=nvl(rec_c.sup_i,0)+nvl(rec_c.sup_l,0)*0.5 then nvl(rec_c.sup_f,0)*0.10 else (nvl(rec_c.sup_i,0)+nvl(rec_c.sup_l,0)*0.5)*0.10+(rec_c.sup_f-(nvl(rec_c.sup_i,0)+nvl(rec_c.sup_l,0)*0.5))*0.02 end;
                
                if sup_acc < 0.5 * sup_princ
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5 * sup_princ;
                end if;
                
            end if;
            
            
            if rec_c.categoria in ('A10','B08','C02','C03','C04','C05','C07')
            then 
                sup_cata := nvl(rec_c.sup_a,0)+nvl(rec_c.sup_h,0)+nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25+nvl(rec_c.sup_d,0)*0.1+nvl(rec_c.sup_e,0)*0.1+nvl(rec_c.sup_f,0)*0.1;
            end if;               
                
            update temp_001 set sup_cat_DPR138_98 = sup_cata
            where cod_nazionale=rec_c.cod_nazionale 
            and foglio = rec_c.foglio
            and particella = rec_c.particella
            and sub = rec_c.sub
            and unimm = rec_c.unimm;

          commit;

          exception when others then 
          dbms_output.put_line(rec_c.foglio||'/'||rec_c.particella||'/'||rec_c.sub||'/'||rec_c.unimm );
          errore:=substr(sqlerrm,1,255);
          dbms_output.put_line('Errore'||' '||errore);
                      
         end;

        end loop;
    end;   

--calcolo il delta tra superficie catastale dichiarata e calcolata
EXECUTE IMMEDIATE ' update temp_001 set delta_sup_cat_calc= null ';

EXECUTE IMMEDIATE ' update temp_001 set delta_sup_cat_calc= nvl(sup_cat,0)-nvl(sup_cat_dpr138_98,0) ';

--calcolo la superficie ai fini tarsu
EXECUTE IMMEDIATE ' update temp_001 set sup_cat_tarsu_calc = null ';

commit;
    
end;
/


DROP PROCEDURE DIOGENE_H501.SETAR_SET_TEMP001_SUP_X_CAT2;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.SETAR_SET_TEMP001_SUP_X_CAT2
IS

PRAGMA AUTONOMOUS_TRANSACTION;

begin

declare
sup_princ number;
sup_acc number;
sup_cata number;


cursor c is select distinct cod_nazionale, foglio, particella, sub, unimm, categoria,
sup_a, sup_i, sup_l, sup_b, sup_c, sup_d, sup_e, sup_f, sup_g, sup_h from temp_001;

    begin
        for rec_c in c
        loop
          declare errore varchar2(255byte);
          begin

            sup_princ:=0;
            sup_acc:=0;
            sup_cata:=0;

            if rec_c.categoria in ('A01','A02','A03','A04','A05','A06','A09','A11')
            then
                sup_princ:=nvl(rec_c.sup_a,0) + nvl(rec_c.sup_h,0);

                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25;

                if sup_acc < 0.5 * sup_princ
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5*sup_princ;
                end if;

            end if;

            if rec_c.categoria in ('A07','A08')
            then
                sup_princ:=nvl(rec_c.sup_a,0) + nvl(rec_c.sup_h,0);

                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25;

                if sup_acc < 0.5 * sup_princ
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5*sup_princ;
                end if;

            end if;

            if rec_c.categoria in ('B01','B02','B03','B04','B05','B06','B07')
            then
                sup_princ:=nvl(rec_c.sup_a,0) + nvl(rec_c.sup_h,0);
                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25;

                if sup_acc < 0.5 * sup_princ
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5*sup_princ;
                end if;
            end if;

            if rec_c.categoria in ('C01')
            then
                sup_cata := nvl(rec_c.sup_i,0)+nvl(rec_c.sup_l,0)*0.5+nvl(rec_c.sup_h,0)+nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25;
            end if;

            if rec_c.categoria in ('C06')
            then
                sup_princ:=nvl(rec_c.sup_i,0)+nvl(rec_c.sup_l,0)*0.5+nvl(rec_c.sup_h,0);

                sup_acc := nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25;

                if sup_acc < 0.5 * sup_princ
                then sup_cata:=sup_princ+sup_acc;
                else sup_cata:=1.5 * sup_princ;
                end if;

            end if;


            if rec_c.categoria in ('A10','B08','C02','C03','C04','C05','C07')
            then
                sup_cata := nvl(rec_c.sup_a,0)+nvl(rec_c.sup_h,0)+nvl(rec_c.sup_b,0)*0.5+nvl(rec_c.sup_c,0)*0.25;
            end if;

            update temp_001 set sup_cat_tarsu_calc = sup_cata
            where cod_nazionale=rec_c.cod_nazionale
            and foglio = rec_c.foglio
            and particella = rec_c.particella
            and sub = rec_c.sub
            and unimm = rec_c.unimm;

          commit;

          exception
          when no_data_found then null;
          when others then
          dbms_output.put_line(rec_c.foglio||'/'||rec_c.particella||'/'||rec_c.sub||'/'||rec_c.unimm );
          errore:=substr(sqlerrm,1,255);
          dbms_output.put_line('Errore'||' '||errore);

         end;

        end loop;
    end;


EXECUTE IMMEDIATE ' update temp_001 set delta_sup_cat_tarsu_calc = null ';

EXECUTE IMMEDIATE ' update temp_001 set delta_sup_cat_tarsu_calc=nvl(sup_cat_tarsu,0)-nvl(sup_cat_tarsu_calc,0) ';

--calcolo il rapporto tra superficie e vani
EXECUTE IMMEDIATE ' update temp_001 set vano= sup_cat_tarsu/consistenza ';

commit;

end;
/


DROP PROCEDURE DIOGENE_H501.SETAR_TEMP001_TEMP002;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.SETAR_TEMP001_TEMP002(BELFIORE IN VARCHAR2)
IS
CANTIDAD NUMBER(3);

PRAGMA AUTONOMOUS_TRANSACTION;

BEGIN
SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'TEMP_001';
IF (CANTIDAD >0) THEN
        execute immediate 'DROP TABLE TEMP_001  CASCADE CONSTRAINTS ';
END IF;

execute immediate ' create table TEMP_001 as( select distinct sc.codi_fisc_luna, sc.id_sezc, ui.cod_nazionale, ui.zona, ui.microzona, to_char(ui.foglio) foglio, ui.particella, ui.sub, to_char(ui.unimm) unimm, ui.categoria, ui.classe, ui.consistenza, ui.rendita, ui.sup_cat from sitiuiu ui, siticomu sc where ui.cod_nazionale=sc.cod_nazionale and sc.codi_fisc_luna= ''' || BELFIORE || ''' and data_fine_val=to_date(''99991231'',''yyyymmdd'')) ';

execute immediate ' alter table TEMP_001 add sup_tarsu number(10,2) ';
execute immediate ' alter table TEMP_001 add stato_catasto number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_cat_tarsu number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_cat_tarsu_80 number(10,2) ';
execute immediate ' alter table TEMP_001 add delta_dich_80 number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_a number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_i number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_l number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_b number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_c number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_d number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_e number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_f number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_g number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_h number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_cat_dpr138_98 number(10,2) ';
execute immediate ' alter table TEMP_001 add delta_sup_cat_calc number(10,2) ';
execute immediate ' alter table TEMP_001 add sup_cat_tarsu_calc number(10,2) ';
execute immediate ' alter table TEMP_001 add delta_sup_cat_tarsu_calc number(10,2) ';
execute immediate ' alter table TEMP_001 add vano number(10,2) ';

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'TEMP_002';
IF (CANTIDAD >0) THEN
        execute immediate 'DROP TABLE TEMP_002  CASCADE CONSTRAINTS ';
END IF;

execute immediate ' create table TEMP_002 as select ogg.foglio, lpad(ogg.numero,5,''0'') numero, nvl(ogg.sub,''0'') sub, ogg.dat_ini, ogg.sup_tot from sit_t_tar_oggetto ogg where ogg.dat_fin = to_date(''99991231'',''yyyymmdd'') or ogg.dat_fin is null ';



SELECT COUNT(*) INTO CANTIDAD FROM user_indexes WHERE index_name = 'TEMP_002_FNS_IDX';
IF CANTIDAD > 0 THEN
    execute immediate ' drop index TEMP_002_FNS_IDX ';
END IF;
execute immediate ' create index TEMP_002_FNS_IDX on TEMP_002 (foglio, numero, sub) logging noparallel ';



SELECT COUNT(*) INTO CANTIDAD FROM user_indexes WHERE index_name = 'TEMP_002_FNSD_IDX';
IF CANTIDAD > 0 THEN
    execute immediate ' drop index TEMP_002_FNSD_IDX ';
END IF;
execute immediate ' create index TEMP_002_FNSD_IDX on TEMP_002 (foglio, numero, sub, dat_ini) logging noparallel ';



SELECT COUNT(*) INTO CANTIDAD FROM user_indexes WHERE index_name = 'TEMP_001_FPS_IDX';
IF CANTIDAD > 0 THEN
    execute immediate ' drop index TEMP_001_FPS_IDX ';
END IF;
execute immediate ' create index TEMP_001_FPS_IDX on TEMP_001 (foglio, particella, unimm) logging noparallel ';



SELECT COUNT(*) INTO CANTIDAD FROM user_indexes WHERE index_name = 'TEMP_001_FPDS_IDX';
IF CANTIDAD > 0 THEN
    execute immediate ' drop index TEMP_001_FPDS_IDX ';
END IF;
execute immediate ' create index TEMP_001_FPDS_IDX on TEMP_001 (foglio, particella, sub, unimm) logging noparallel ';



END;
/


DROP PROCEDURE DIOGENE_H501.SETAR_TEMP003;

CREATE OR REPLACE PROCEDURE DIOGENE_H501.SETAR_TEMP003
IS
CANTIDAD NUMBER(3);

PRAGMA AUTONOMOUS_TRANSACTION;

BEGIN

SELECT COUNT(*) INTO CANTIDAD FROM USER_TABLES WHERE TABLE_NAME = 'TEMP_003';
IF (CANTIDAD >0) THEN
        execute immediate 'DROP TABLE TEMP_003  CASCADE CONSTRAINTS ';
END IF;

execute immediate ' create table TEMP_003 as select categoria, count(*) numero, sum(consistenza) sum_consistenza, sum(sup_cat_tarsu) sum_sup_cat_tarsu, 0.8*sum(sup_cat_tarsu) sum_sup_cat_tarsu_80 from temp_001 group by categoria order by categoria ';

execute immediate ' alter table temp_003 add SUP_0 number(10,2) ';
execute immediate ' alter table temp_003 add SUM_CONS_SUP_0 number(10,2) ';

EXECUTE IMMEDIATE ' update temp_003 t3 set (sup_0, sum_cons_sup_0)=(select count(*), sum(consistenza) from temp_001 t1 where t1.categoria=t3.categoria and (t1.sup_cat_tarsu is null or t1.sup_cat_tarsu=0) ) ';

commit;

END;
/

