DROP PROCEDURE SITI_H501.AGGIORNA_ENTI;

CREATE OR REPLACE procedure SITI_H501.AGGIORNA_ENTI is

CURSOR C1 IS SELECT e.id_lstente, e.descr_ente, e.cod_tipoente, e.cod_fiscale FROM ACCR_LISTA_ENTI e WHERE e.cod_tipoente = 'ENTELOCALE';
CROW C1%rowtype;
id number;
 
begin
 open C1;
    loop
    fetch C1
        into CROW;
      exit when C1%notfound;
    
      select SITIENTE_SEQ.NEXTVAL into id from dual;
      
      insert into SITIENTE (COD_ENTE, 
             DES_ENTE, 
             DATA_INIZIO, 
             DATA_FINE, 
             INDIRIZZO, 
             CAP, 
             PROVINCIA, 
             COMUNE, 
             TELEFONO, 
             E_MAIL, 
             FAX, 
             TIPOENTE, 
             COD_FISCALE)
             
      values (id, 
             crow.descr_ente, 
             to_date('01-01-2001', 'dd-mm-yyyy'), 
             to_date('31-12-9999', 'dd-mm-yyyy'), 
             null, 
             null, 
             null, 
             null, 
             null, 
             null, 
             null, 
             crow.cod_tipoente, 
             crow.cod_fiscale);
    
      update ACCR_LISTA_ENTI ae set ae.cod_ente = id where ae.id_lstente = crow.id_lstente;
      
    end loop;
    
 close C1;
  
 --commit;
end AGGIORNA_ENTI;

/


DROP PROCEDURE SITI_H501.AGGIORNA_TERRENI;

CREATE OR REPLACE procedure SITI_H501.aggiorna_terreni (incodnaz IN VARCHAR2, infoglio IN NUMBER, inparticella IN VARCHAR2, insub IN VARCHAR2, indatarif IN DATE, inutente IN VARCHAR2)
IS
   retvalue NUMBER(9) := 0;
BEGIN
  siticons_pck.aggiorna_terreni_from_uiu(incodnaz,infoglio,inparticella,insub,indatarif,inutente,'P',retvalue);
  IF retvalue = 0 THEN
    siticons_pck.aggiorna_terreni_from_uiu(incodnaz,infoglio,inparticella,insub,indatarif,inutente,'A',retvalue);
  END IF;
  IF NOT (retvalue = 0 OR retvalue = 1 OR retvalue IS NULL) THEN
    raise_application_error (-20080, 'Errore');
  END IF;
END aggiorna_terreni;

/


DROP PROCEDURE SITI_H501.ASSEGNA_CIVICO;

CREATE OR REPLACE procedure SITI_H501.assegna_civico(pk number, uten varchar2, shp mdsys.sdo_geometry, data_lav date := sysdate) is
  cursor cPart(s mdsys.sdo_geometry) is
    select *
      from sitipart
     where SDO_RELATE(shape, s, 'QUERYTYPE=WINDOW MASK=ANYINTERACT')='TRUE';

  dt    date;
begin

  if shp is null then
    return;
  end if;

  dt := data_lav - (1 / 24 / 60 / 60);

  -- Storicizzo le vecchie associazioni--prima era su siticivi_uiu ma era errato: errore dentro al trigger instead of update che faceva scadere anche gli scaduti, creando duplicati su data fine
  update sitiloc_uiu set data_fine_val = dt
   where PKID_LOC = pk
    AND fkid_type=-1
     and data_inizio_val <= data_lav
     and data_fine_val >= data_lav;

  -- Carico le nuove
  for rec in cPart(shp) loop
    if rec.data_inizio_val <= data_lav and rec.data_fine_val >= data_lav then
      insert into siticivi_uiu (PKID_CIVI, PKID_UIU, DATA_INIZIO_VAL, DATA_FINE_VAL, UTENTE, PRINCIPALE)
        select pk, pkid_uiu, sysdate, to_date('99991231', 'yyyymmdd'), uten, 'N'
          from sitiuiu
         where cod_nazionale = rec.cod_nazionale
           and foglio = rec.foglio
           and particella = rec.particella
           and sub = rec.sub
           and data_inizio_val <= data_lav
           and data_fine_val >= data_lav;
    end if;
  end loop;
end;
/


DROP PROCEDURE SITI_H501.CREACAMPO;

CREATE OR REPLACE PROCEDURE SITI_H501.creacampo(TABELLA IN VARCHAR2,CAMPO IN VARCHAR2,TIPO IN VARCHAR2)
IS
CURSOR C1 IS SELECT 1 FROM USER_TAB_COLUMNS WHERE UPPER(TABLE_NAME)=UPPER(TABELLA) AND UPPER(COLUMN_NAME)=UPPER(CAMPO);
ESISTE NUMBER(1);
BEGIN
  OPEN C1;
  FETCH C1 INTO ESISTE;
  IF C1%NOTFOUND THEN ESISTE:=0; END IF;
  CLOSE C1;

  IF ESISTE=0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE ' || TABELLA ||' ADD ' || CAMPO || ' ' || TIPO || '';
  END IF;
END;
/


DROP PROCEDURE SITI_H501.CREA_CENSUARIO_TERRENI;

CREATE OR REPLACE PROCEDURE SITI_H501.crea_censuario_terreni(CODNAZ IN VARCHAR2)
IS
BEGIN

  INSERT INTO SITITRKC(COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, AREA_PART, SIGLA_PROV, PARTITA, VALIDA, DATA_AGGI)
  SELECT A.COD_NAZIONALE, A.FOGLIO, A.PARTICELLA, A.SUB, A.AREA_PART, (SELECT C.SIGLA_PROV FROM SITICOMU C WHERE C.COD_NAZIONALE=A.COD_NAZIONALE) AS SIGLA_PROV, '1111111' AS PARTITA, 1 AS VALIDA, A.DATA_LAV AS DATA_AGGI
  FROM SITIPART A, SITITRKC B
  WHERE A.COD_NAZIONALE=CODNAZ
  AND A.COD_NAZIONALE=B.COD_NAZIONALE(+)
  AND A.FOGLIO=B.FOGLIO(+)
  AND A.PARTICELLA=B.PARTICELLA(+)
  AND A.SUB=B.SUB(+)
  AND A.DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS')
  AND B.COD_NAZIONALE IS NULL;

  COMMIT;

END CREA_CENSUARIO_TERRENI;

/


DROP PROCEDURE SITI_H501.CREA_IDX_SPATIAL;

CREATE OR REPLACE PROCEDURE SITI_H501.crea_idx_spatial(TABELLA IN VARCHAR2,CAMPO_SHAPE IN VARCHAR2,TABLESPACE_DEST IN VARCHAR2,NOMEINDICE IN VARCHAR2)
AUTHID CURRENT_USER
IS
	CURSOR C1 IS SELECT 1 FROM USER_INDEXES WHERE Upper(INDEX_NAME)=UPPER(NOMEINDICE);
	ESISTE NUMBER(1);
BEGIN
	DELETE FROM USER_SDO_GEOM_METADATA WHERE UPPER(TABLE_NAME)=UPPER(TABELLA) AND UPPER(COLUMN_NAME)=UPPER(CAMPO_SHAPE);
	INSERT INTO USER_SDO_GEOM_METADATA (TABLE_NAME, COLUMN_NAME, DIMINFO) VALUES (TABELLA, CAMPO_SHAPE ,MDSYS.SDO_DIM_ARRAY(MDSYS.SDO_DIM_ELEMENT('X', 1313328, 2820083, 0.0050),MDSYS.SDO_DIM_ELEMENT('Y', 3930191, 5220322.5, 0.0050)));
	COMMIT;

	OPEN C1;
	FETCH C1 INTO ESISTE;
	IF C1%NOTFOUND THEN ESISTE:=0; END IF;
	CLOSE C1;

	IF ESISTE=1 THEN
		EXECUTE IMMEDIATE 'DROP INDEX ' || NOMEINDICE;
	END IF;
	IF TABLESPACE_DEST IS NOT NULL THEN
		EXECUTE IMMEDIATE 'CREATE INDEX ' || NOMEINDICE || ' ON ' || TABELLA || '(' || CAMPO_SHAPE || ') INDEXTYPE IS MDSYS.SPATIAL_INDEX PARAMETERS(''tablespace=' || TABLESPACE_DEST || ''')';
	ELSE
		EXECUTE IMMEDIATE 'CREATE INDEX ' || NOMEINDICE || ' ON ' || TABELLA || '(' || CAMPO_SHAPE || ') INDEXTYPE IS MDSYS.SPATIAL_INDEX';
	END IF;
END; 
/


DROP PROCEDURE SITI_H501.CREAINDICE;

CREATE OR REPLACE PROCEDURE SITI_H501.creaindice(TABELLA IN VARCHAR2,NOMEINDICE IN VARCHAR2,COLONNE IN VARCHAR2,UNICO IN NUMBER DEFAULT 0)
IS
CURSOR C1 IS SELECT 1 FROM USER_INDEXES WHERE TABLE_NAME=TABELLA AND INDEX_NAME=NOMEINDICE;
ESISTE NUMBER(1);
BEGIN
  OPEN C1;
  FETCH C1 INTO ESISTE;
  IF C1%NOTFOUND THEN ESISTE:=0; END IF;
  CLOSE C1;

  IF ESISTE=0 THEN
    EXECUTE IMMEDIATE 'CREATE INDEX ' || NOMEINDICE || ' ON ' || TABELLA || '(' || COLONNE || ') NOLOGGING';
  END IF;
END;
/


DROP PROCEDURE SITI_H501.CREA_STRADE_FROM_GRAFO;

CREATE OR REPLACE PROCEDURE SITI_H501.crea_strade_from_grafo(CN IN VARCHAR2, FG IN NUMBER, BUF IN NUMBER)
IS

  TYPE EMPTYCUR IS REF CURSOR;
  C EMPTYCUR;
  SHP MDSYS.SDO_GEOMETRY;
  IDX NUMBER;
  PRG_STRADA NUMBER;

BEGIN

  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - AVVIO PROCEDURA');
  DELETE FROM SITISUOLO A WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND (SELECT B.COD_EDIF FROM SITIPART B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.FOGLIO=A.FOGLIO AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS'))=3;
  DELETE FROM SITICENT A WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND (SELECT B.COD_EDIF FROM SITIPART B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.FOGLIO=A.FOGLIO AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS'))=3;
  DELETE FROM SITIPART A WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND A.COD_EDIF=3;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - CANCELLATI CENTROIDI, PARTICELLE E SUOLO');
  DELETE FROM TEMP_SITIDSTR_GRAF;
  INSERT INTO TEMP_SITIDSTR_GRAF(SHAPE)
  SELECT SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_INTERSECTION(SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_DIFFERENCE(SDO_GEOM.SDO_ARC_DENSIFY(SDO_GEOM.SDO_BUFFER(A.SHAPE, BUF, 0.005),0.005,'ARC_TOLERANCE=1'), (SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SDO_TOOLS.REMOVE_DUPLICATE_POINTS(B.SHAPE), 0.005)) FROM SITIPART B WHERE B.COD_NAZIONALE=CN AND B.FOGLIO=FG AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS')), 0.005)), (SELECT B.SHAPE FROM SITIFGLC B WHERE B.COD_NAZIONALE=CN AND B.FOGLIO=FG AND B.ALLEGATO='0' AND B.SVILUPPO='0'), 0.005))
  FROM SITIDSTR_GRAF A
  WHERE SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_INTERSECTION(SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_DIFFERENCE(SDO_GEOM.SDO_ARC_DENSIFY(SDO_GEOM.SDO_BUFFER(A.SHAPE, BUF, 0.005),0.005,'ARC_TOLERANCE=1'), (SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SDO_TOOLS.REMOVE_DUPLICATE_POINTS(B.SHAPE), 0.005)) FROM SITIPART B WHERE B.COD_NAZIONALE=CN AND B.FOGLIO=FG AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS')), 0.005)), (SELECT B.SHAPE FROM SITIFGLC B WHERE B.COD_NAZIONALE=CN AND B.FOGLIO=FG AND B.ALLEGATO='0' AND B.SVILUPPO='0'), 0.005)) IS NOT NULL;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - COMPLETATO RIEMPIMENTO TABELLA TEMP');
  PRG_STRADA:=1;
  SHP:=NULL;
  OPEN C FOR SELECT SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_DIFFERENCE(A.SHAPE,(SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(B.SHAPE,0.005)) FROM TEMP_SITIDSTR_GRAF B WHERE B.SE_ROW_ID<>A.SE_ROW_ID),0.005)) FROM TEMP_SITIDSTR_GRAF A WHERE SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_DIFFERENCE(A.SHAPE,(SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(B.SHAPE,0.005)) FROM TEMP_SITIDSTR_GRAF B WHERE B.SE_ROW_ID<>A.SE_ROW_ID),0.005)) IS NOT NULL;
  LOOP
    FETCH C INTO SHP;
    EXIT WHEN C%NOTFOUND;
	IDX:=1;
	LOOP
	  EXIT WHEN IDX>SDO_TOOLS.GET_NUM_ELEMENTS(SHP);
      INSERT INTO SITIPART(COD_NAZIONALE,FOGLIO,TAVOLA,PARTICELLA,SUB,DATA_LAV,AREA_PART,DELTA_X_FOTO,DELTA_Y_FOTO,CONTRASTO,LUMINOSITA,COD_EDIF,FLAG1,FLAG2,FLAG3,SHAPE,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,ALLEGATO,SVILUPPO)
      VALUES(CN,FG,FG,'STRAD',TRIM(TO_CHAR(PRG_STRADA)),TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDD') || '000000','YYYYMMDDHH24MISS'),SDO_GEOM.SDO_AREA(SDO_TOOLS.GET_ELEMENT(SHP,IDX),0.005),0,0,0,0,3,'000','000','000',SDO_TOOLS.GET_ELEMENT(SHP,IDX),'LOAD',TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDD') || '000000','YYYYMMDDHH24MISS'),TO_DATE('99991231000000','YYYYMMDDHH24MISS'),'0','0');
      PRG_STRADA:=PRG_STRADA+1;
	  IDX:=IDX+1;
	END LOOP;
  END LOOP;
  CLOSE C;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - CREATE PARTICELLE RITAGLIATE');
  SHP:=NULL;
  OPEN C FOR SELECT SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_DIFFERENCE((SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(A.SHAPE,0.005)) FROM TEMP_SITIDSTR_GRAF A),(SELECT SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(B.SHAPE,0.005)) FROM SITIPART B WHERE B.COD_NAZIONALE=CN AND B.FOGLIO=FG AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND COD_EDIF=3),0.005)) FROM DUAL;
  LOOP
    FETCH C INTO SHP;
    EXIT WHEN C%NOTFOUND;
	IDX:=1;
	LOOP
	  EXIT WHEN IDX>SDO_TOOLS.GET_NUM_ELEMENTS(SHP);
      INSERT INTO SITIPART(COD_NAZIONALE,FOGLIO,TAVOLA,PARTICELLA,SUB,DATA_LAV,AREA_PART,DELTA_X_FOTO,DELTA_Y_FOTO,CONTRASTO,LUMINOSITA,COD_EDIF,FLAG1,FLAG2,FLAG3,SHAPE,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,ALLEGATO,SVILUPPO)
      VALUES(CN,FG,FG,'STRAD',TRIM(TO_CHAR(PRG_STRADA)),TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDD') || '000000','YYYYMMDDHH24MISS'),SDO_GEOM.SDO_AREA(SDO_TOOLS.GET_ELEMENT(SHP,IDX),0.005),0,0,0,0,3,'000','000','000',SDO_TOOLS.GET_ELEMENT(SHP,IDX),'LOAD',TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDD') || '000000','YYYYMMDDHH24MISS'),TO_DATE('99991231000000','YYYYMMDDHH24MISS'),'0','0');
      PRG_STRADA:=PRG_STRADA+1;
	  IDX:=IDX+1;
	END LOOP;
  END LOOP;
  CLOSE C;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - CREATE PARTICELLE INTERSEZIONE');
  INSERT INTO SITICENT(COD_NAZIONALE, FOGLIO, TAVOLA, PARTICELLA, SUB,DATA_LAV,SHAPE,UTENTE,DATA_INIZIO_VAL,DATA_FINE_VAL,ALLEGATO,SVILUPPO)
  SELECT A.COD_NAZIONALE, A.FOGLIO, A.FOGLIO, A.PARTICELLA, A.SUB, A.DATA_LAV, SDO_GEOM.SDO_CENTROID(A.SHAPE,0.5), A.UTENTE, A.DATA_INIZIO_VAL, A.DATA_FINE_VAL, A.ALLEGATO, A.SVILUPPO
  FROM SITIPART A
  WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND A.COD_EDIF=3;
  UPDATE SITICENT A SET A.SHAPE=NULL WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND (SELECT B.COD_EDIF FROM SITIPART B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.FOGLIO=A.FOGLIO AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS'))=3 AND SDO_RELATE(A.SHAPE,(SELECT B.SHAPE FROM SITIPART B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.FOGLIO=A.FOGLIO AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND B.COD_EDIF=3),'MASK=ANYINTERACT QUERYTYPE=WINDOW')<>'TRUE';
  UPDATE SITICENT A SET A.SHAPE=SDO_GEOM.SDO_POINTONSURFACE((SELECT B.SHAPE FROM SITIPART B WHERE B.COD_NAZIONALE=A.COD_NAZIONALE AND B.FOGLIO=A.FOGLIO AND B.PARTICELLA=A.PARTICELLA AND B.SUB=A.SUB AND B.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND B.COD_EDIF=3),0.5) WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND A.SHAPE IS NULL;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - CREATI CENTROIDI');
  INSERT INTO SITISUOLO(COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, PROG_POLIGONO, DATA_FINE_VAL, ALLEGATO, SVILUPPO, CAMPAGNA, UTENTE, DATA_INIZIO_VAL, DATA_LAV, AREA_COLT, COD_COLTURA, SHAPE, COD_VARIETA, ISTATP, COD_UTIL, SORGENTE, TAVOLA)
  SELECT A.COD_NAZIONALE, A.FOGLIO, A.PARTICELLA, A.SUB, 1, A.DATA_FINE_VAL, A.ALLEGATO, A.SVILUPPO, TO_NUMBER(TO_CHAR(SYSDATE,'YYYY')), A.UTENTE, A.DATA_INIZIO_VAL, A.DATA_LAV, A.AREA_PART, 900, A.SHAPE, 900, A.ISTATP, 300, 0, A.FOGLIO
  FROM SITIPART A
  WHERE A.COD_NAZIONALE=CN AND A.FOGLIO=FG AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND A.COD_EDIF=3;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - CREATO USO DEL SUOLO (STRADE)');
  DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - FINE PROCEDURA');

  EXCEPTION WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - ERRORE!!!');
	DBMS_OUTPUT.PUT_LINE(SQLERRM);
	DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - FINE PROCEDURA');
END CREA_STRADE_FROM_GRAFO;
/


DROP PROCEDURE SITI_H501.CREA_STRADE_FROM_GRAFO_COMUNE;

CREATE OR REPLACE PROCEDURE SITI_H501.crea_strade_from_grafo_comune(CN IN VARCHAR2, BUF IN NUMBER)
IS
  CURSOR C1 IS SELECT FOGLIO FROM SITIFGLC WHERE COD_NAZIONALE=CN;
  FG NUMBER(4);
BEGIN
  OPEN C1;
  LOOP
    FETCH C1 INTO FG;
    EXIT WHEN C1%NOTFOUND;
    CREA_STRADE_FROM_GRAFO(CN,FG,BUF);
  END LOOP;
  CLOSE C1;
END;
/


DROP PROCEDURE SITI_H501.CREA_SUOLO;

CREATE OR REPLACE PROCEDURE SITI_H501.crea_suolo(CODNAZ IN VARCHAR2)
IS
  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;
  C2 EMPTYCUR;

  MY_CODNAZ VARCHAR2(4);
  MY_FOG NUMBER(4);
  MY_PART VARCHAR2(5);
  MY_SUB VARCHAR2(3);
  MY_PEDIF VARCHAR2(3);

  MY_COD_ELEG NUMBER(3);
  MY_COD_UTIL NUMBER(3);
  MY_COD_VARI NUMBER(3);
  MY_COD_EDIF NUMBER(3);
BEGIN

  IF CODNAZ IS NULL THEN
    OPEN C1 FOR SELECT A.COD_NAZIONALE, A.FOGLIO, A.PARTICELLA, A.SUB, A.COD_EDIF FROM SITIPART A, SITISUOLO B WHERE A.COD_NAZIONALE=B.COD_NAZIONALE(+) AND A.FOGLIO=B.FOGLIO(+) AND A.PARTICELLA=B.PARTICELLA(+) AND A.SUB=B.SUB(+) AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND B.DATA_FINE_VAL(+)=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND B.COD_NAZIONALE IS NULL;
  ELSE
    OPEN C1 FOR SELECT A.COD_NAZIONALE, A.FOGLIO, A.PARTICELLA, A.SUB, A.COD_EDIF FROM SITIPART A, SITISUOLO B WHERE A.COD_NAZIONALE=B.COD_NAZIONALE(+) AND A.FOGLIO=B.FOGLIO(+) AND A.PARTICELLA=B.PARTICELLA(+) AND A.SUB=B.SUB(+) AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND B.DATA_FINE_VAL(+)=TO_DATE('99991231000000','YYYYMMDDHH24MISS') AND A.COD_NAZIONALE=CODNAZ AND B.COD_NAZIONALE IS NULL;
  END IF;
  LOOP
    FETCH C1 INTO MY_CODNAZ, MY_FOG, MY_PART, MY_SUB,MY_PEDIF;
  	  EXIT WHEN (C1%NOTFOUND);
    IF MY_PEDIF <3 OR MY_PEDIF>4 THEN
    	OPEN C2 FOR SELECT B.COD_ELEG, B.COD_UTIL, B.COD_VARI,B.COD_EDIF FROM SITITRKC A, SITICODS_QUAL B WHERE A.QUAL_CAT=B.CODI_QUAL AND A.COD_NAZIONALE=MY_CODNAZ AND A.FOGLIO=MY_FOG AND A.PARTICELLA=MY_PART AND A.SUB=MY_SUB AND A.VALIDA=1;
    	FETCH C2 INTO MY_COD_ELEG, MY_COD_UTIL, MY_COD_VARI,MY_COD_EDIF;
    	IF C2%NOTFOUND THEN
    	  MY_COD_ELEG:=5;
    	  MY_COD_UTIL:=0;
    	  MY_COD_VARI:=0;
        MY_COD_EDIF:=2;
    	END IF;
        CLOSE C2;
      INSERT INTO SITISUOLO(COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, PROG_POLIGONO, DATA_FINE_VAL, ALLEGATO, SVILUPPO, CAMPAGNA, UTENTE, DATA_INIZIO_VAL, DATA_LAV, AREA_COLT, COD_COLTURA, SHAPE, COD_VARIETA, ISTATP, COD_UTIL, SORGENTE, TAVOLA) SELECT A.COD_NAZIONALE, A.FOGLIO, A.PARTICELLA, A.SUB, 1, A.DATA_FINE_VAL, A.ALLEGATO, A.SVILUPPO, TO_NUMBER(TO_CHAR(SYSDATE,'YYYY')), 'LOADER_SAUTO', A.DATA_INIZIO_VAL, A.DATA_LAV, A.AREA_PART, MY_COD_UTIL, A.SHAPE, MY_COD_VARI, A.ISTATP, MY_COD_ELEG, 0, A.FOGLIO FROM SITIPART A WHERE A.COD_NAZIONALE=MY_CODNAZ AND A.FOGLIO=MY_FOG AND A.PARTICELLA=MY_PART AND A.SUB=MY_SUB AND A.DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
      UPDATE sitipart SET COD_EDIF=MY_COD_EDIF WHERE COD_NAZIONALE=MY_CODNAZ AND FOGLIO=MY_FOG AND PARTICELLA=MY_PART AND SUB=MY_SUB AND DATA_FINE_VAL=TO_DATE('99991231000000','YYYYMMDDHH24MISS');
    END IF;
  END LOOP;
  COMMIT;
  CLOSE C1;

END CREA_SUOLO;

/


DROP PROCEDURE SITI_H501.DROPPAINDICE;

CREATE OR REPLACE PROCEDURE SITI_H501.DROPPAINDICE(INDICE IN VARCHAR2)
IS
CURSOR C1 IS SELECT 1 FROM USER_INDEXES WHERE Upper(INDEX_NAME)=UPPER(INDICE);
ESISTE NUMBER(1);
BEGIN
  OPEN C1;
  FETCH C1 INTO ESISTE;
  IF C1%NOTFOUND THEN ESISTE:=0; END IF;
  CLOSE C1;

  IF ESISTE=1 THEN
    EXECUTE IMMEDIATE 'DROP INDEX ' || INDICE;
  END IF;
END;
/


DROP PROCEDURE SITI_H501.DROPPASEQUENCE;

CREATE OR REPLACE PROCEDURE SITI_H501.droppasequence(NOMESEQ IN VARCHAR2)
IS
CURSOR C1 IS SELECT 1 FROM USER_SEQUENCES WHERE Upper(SEQUENCE_NAME)=UPPER(NOMESEQ);
ESISTE NUMBER(1);
BEGIN
  OPEN C1;
  FETCH C1 INTO ESISTE;
  IF C1%NOTFOUND THEN ESISTE:=0; END IF;
  CLOSE C1;

  IF ESISTE=1 THEN
    EXECUTE IMMEDIATE 'DROP SEQUENCE ' || NOMESEQ ||'';
  END IF;
END;
/


DROP PROCEDURE SITI_H501.DROPPATABELLA;

CREATE OR REPLACE PROCEDURE SITI_H501.droppatabella(TABELLA IN VARCHAR2)
IS
CURSOR C1 IS SELECT 1 FROM USER_TABLES WHERE Upper(TABLE_NAME)=UPPER(TABELLA);
ESISTE NUMBER(1);
BEGIN
  OPEN C1;
  FETCH C1 INTO ESISTE;
  IF C1%NOTFOUND THEN ESISTE:=0; END IF;
  CLOSE C1;

  IF ESISTE=1 THEN
    EXECUTE IMMEDIATE 'DROP TABLE ' || TABELLA ||' CASCADE CONSTRAINTS';
  END IF;
END;
/


DROP PROCEDURE SITI_H501.GENERA_AREE_CORTIVE;

CREATE OR REPLACE PROCEDURE SITI_H501.GENERA_AREE_CORTIVE(CN IN VARCHAR2, UT IN VARCHAR2, DL IN DATE)
IS

  TYPE EMPTYCUR IS REF CURSOR;
  C1 EMPTYCUR;
  C2 EMPTYCUR;
  C3 EMPTYCUR;
  FG NUMBER(4);
  PT VARCHAR2(5);
  SB VARCHAR2(3);
  AP NUMBER(11,2);
  AC NUMBER(11,2);
  DT DATE;
  SHPP MDSYS.SDO_GEOMETRY;
  SHP MDSYS.SDO_GEOMETRY;
  NP NUMBER(9):=0;

BEGIN

  OPEN C1 FOR SELECT FOGLIO, PARTICELLA, SUB, AREA_PART, SDO_TOOLS.REMOVE_DUPLICATE_POINTS(SHAPE) FROM SITIPART WHERE COD_NAZIONALE=CN AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS') AND COD_EDIF=1;
  LOOP
    FETCH C1 INTO FG, PT, SB, AP, SHPP;
    EXIT WHEN C1%NOTFOUND;
    OPEN C2 FOR SELECT SUM(AREA_COLT),MIN(DATA_INIZIO_VAL) FROM SITISUOLO WHERE COD_NAZIONALE=CN AND FOGLIO=FG AND PARTICELLA=PT AND SUB=SB AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');
    FETCH C2 INTO AC,DT;
    IF C2%NOTFOUND THEN AC:=0; END IF;
    CLOSE C2;
    IF AP > AC + AP * 5/100 THEN
      OPEN C3 FOR SELECT SDO_TOOLS.CLEANUP(SDO_GEOM.SDO_DIFFERENCE(SHPP,SDO_AGGR_UNION(MDSYS.SDOAGGRTYPE(SDO_TOOLS.REMOVE_DUPLICATE_POINTS(SHAPE), 0.005)),0.005)) FROM SITISUOLO WHERE COD_NAZIONALE=CN AND FOGLIO=FG AND PARTICELLA=PT AND SUB=SB AND DATA_FINE_VAL=TO_DATE('99991231000000', 'YYYYMMDDHH24MISS');
      FETCH C3 INTO SHP;
      IF C3%NOTFOUND THEN SHP:=NULL; END IF;
      CLOSE C3;
      IF SHP IS NOT NULL THEN
		IF DL IS NULL THEN
        	INSERT INTO SITISUOLO(COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, DATA_FINE_VAL, ALLEGATO, SVILUPPO, CAMPAGNA, UTENTE, DATA_INIZIO_VAL, DATA_LAV, AREA_COLT, COD_COLTURA, SHAPE, COD_VARIETA, COD_UTIL, SORGENTE, TAVOLA)
        	VALUES(CN, FG, PT, SB, TO_DATE('99991231000000', 'YYYYMMDDHH24MISS'), '0', '0', TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY')), UT, DT, DT, SDO_GEOM.SDO_AREA(SHP,0.005), 0, SHP, 0, 110, 0, FG);
		ELSE
        	INSERT INTO SITISUOLO(COD_NAZIONALE, FOGLIO, PARTICELLA, SUB, DATA_FINE_VAL, ALLEGATO, SVILUPPO, CAMPAGNA, UTENTE, DATA_INIZIO_VAL, DATA_LAV, AREA_COLT, COD_COLTURA, SHAPE, COD_VARIETA, COD_UTIL, SORGENTE, TAVOLA)
        	VALUES(CN, FG, PT, SB, TO_DATE('99991231000000', 'YYYYMMDDHH24MISS'), '0', '0', TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY')), UT, DL, DL, SDO_GEOM.SDO_AREA(SHP,0.005), 0, SHP, 0, 110, 0, FG);
		END IF;
        NP:=NP+1;
        IF MOD(NP,100)=0 THEN COMMIT; END IF;
      END IF;
    END IF;
  END LOOP;
  CLOSE C1;
  IF MOD(NP,100)<>0 THEN COMMIT; END IF;

  EXCEPTION WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS') || ' - ERRORE!!!');
	  DBMS_OUTPUT.PUT_LINE(SQLERRM);
END GENERA_AREE_CORTIVE;

/


DROP PROCEDURE SITI_H501.GET_STATO_LOCK_CUAA;

CREATE OR REPLACE PROCEDURE SITI_H501.GET_STATO_LOCK_CUAA (INCUAA IN VARCHAR2,TIPOLOCK OUT NUMBER,UTENTELOCK OUT VARCHAR2,TEMPOLOCK OUT DATE)
IS
  CURSOR C1 IS SELECT UTENTE,TIPO_LOCK,"TIMESTAMP" FROM CONS_LKCU_TAB WHERE CUAA=INCUAA;
BEGIN
  OPEN C1;
  FETCH C1 INTO UTENTELOCK,TIPOLOCK,TEMPOLOCK;
  IF C1%NOTFOUND THEN UTENTELOCK:=NULL;TIPOLOCK:=NULL;TEMPOLOCK:=NULL; END IF;
  CLOSE C1;
END;
/


DROP PROCEDURE SITI_H501.IMPORTA_CONSISTENZA_TER;

CREATE OR REPLACE PROCEDURE SITI_H501.importa_consistenza_ter (uten IN VARCHAR2) IS
/*
  a.caleffi 2009-02-23 aggiunto controllo su c1rec.pkid_atto
  a.caleffi 2008-12-10 aggiunta gestione colonna loadcons.atto_ini
*/
  CURSOR c1 IS
    SELECT     *
          FROM impo_cons_ter_base
      ORDER BY istatp, istatc, id_sezc, foglio, particella, sub, data_scadenz, data_lav
    FOR UPDATE;

  dt      DATE;
  dt2     DATE;
  co      VARCHAR2 (5);
  fo      NUMBER (4);
  pa      VARCHAR2 (5);
  su      VARCHAR2 (3);
  ut      VARCHAR2 (20);
  dini    DATE;
  dfin    DATE;
  tmpco   VARCHAR2 (5);
  ec      NUMBER;
  id_atto number;
BEGIN
  ut := uten;

  DELETE FROM loadcons;

  DELETE FROM loadcons_part;

  FOR c1rec IN c1 LOOP
    tmpco := getcodnaz (c1rec.istatp, c1rec.istatc, TRIM (c1rec.id_sezc));

    -- a.caleffi 2009-02-23 aggiunto controllo sul valore 0, dato che SITIDATA
    -- passa 0, altrimenti l'atto verrebbe cercato anche con valore 0
    IF c1rec.pkid_atto IS NOT NULL AND 0 <> c1rec.pkid_atto THEN
      SELECT pkid_atto
        INTO id_atto
        FROM sitidata_atti_titoli
       WHERE pkid_atto_utente = c1rec.pkid_atto AND fkid_tipo_atto = -22;
    END IF;

    IF dt IS NOT NULL AND (dt <> c1rec.data_scadenz OR dt2 <> c1rec.data_lav OR co != tmpco OR fo != c1rec.foglio OR pa != c1rec.particella OR su != c1rec.sub) THEN
      INSERT INTO loadcons_part
                  (id_caricamento, id_particella, cod_nazionale, foglio, particella, sub, utente, data_inizio,
                   data_fine, controlli, sorgente, atto_ini)
           VALUES (1, 1, co, fo, pa, su, ut, dini, dfin, 32, 9, id_atto);

      SELECT cod_errore
        INTO ec
        FROM loadcons_part
       WHERE id_caricamento = 1;

      IF (ec IS NOT NULL AND ec != 0) THEN
        raise_application_error (ec, 'Error ' || ec);
      END IF;

      DELETE FROM loadcons;

      DELETE FROM loadcons_part;
    END IF;

    -- a.caleffi 2008-12-10 aggiunta colonna atto_ini per memorizzare il codice dell'atto
    --   usato nel trigger loadcons_part
    INSERT INTO loadcons
                (id_caricamento, id_particella, cuaa, quota_conduzione, quota_limite, tipo_titolo
                , atto_ini)
         VALUES (1, 1, c1rec.cod_soggetto, c1rec.QUOTA, c1rec.limite, c1rec.tipo_titolo
                , id_atto);

    dt := c1rec.data_scadenz;
    dt2 := c1rec.data_lav;
    co := tmpco;
    fo := c1rec.foglio;
    pa := c1rec.particella;
    su := c1rec.sub;
    dini := c1rec.data_lav;
    dfin := c1rec.data_scadenz;
  END LOOP;

  INSERT INTO loadcons_part
              (id_caricamento, id_particella, cod_nazionale, foglio, particella, sub, utente, data_inizio, data_fine,
               controlli, sorgente, atto_ini)
       VALUES (1, 1, co, fo, pa, su, ut, dini, dfin, 32, 9, id_atto);

  SELECT cod_errore
    INTO ec
    FROM loadcons_part
   WHERE id_caricamento = 1;

  IF (ec IS NOT NULL AND ec != 0) THEN
    raise_application_error (ec, 'Error ' || ec);
  END IF;
-- COMMIT;
END;
/


DROP PROCEDURE SITI_H501.IMPORTA_CONSISTENZA_UIU;

CREATE OR REPLACE PROCEDURE SITI_H501.importa_consistenza_uiu (uten IN VARCHAR2) IS
/*
  a.caleffi 2008-12-12 aggiunta gestione colonna loadcons_uiu.atto_ini
  a.caleffi 2008-12-22 aggiunto controllo su valore c1rec.pkid_atto <> 0
*/
  CURSOR c1 IS
    SELECT * FROM impo_cons_uiu_base
    ORDER BY unimm, data_scadenz, data_lav
    for update;

  dt     DATE;
  dt2    DATE;
  co     VARCHAR2 (5);
  fo     NUMBER (4);
  pa     VARCHAR2 (5);
  su     VARCHAR2 (3);
  uni    NUMBER (5);
  ut     VARCHAR2 (20);
  dini   DATE;
  dfin   DATE;
  id_atto number(9);
  errCode number;
  ec number;
BEGIN
  ut := uten;

  DELETE FROM loadcons_uiu;
  DELETE FROM loadcons_part_uiu;

  FOR c1rec IN c1 LOOP
    BEGIN
      -- a.caleffi 2008-12-22 controllo l'atto se non e' null e se ha un valore diverso da 0
      IF c1rec.pkid_atto IS NOT NULL AND (0 <> c1rec.pkid_atto) THEN
        SELECT pkid_atto
          INTO id_atto
          FROM sitidata_atti_titoli
         WHERE pkid_atto_utente = c1rec.pkid_atto AND fkid_tipo_atto = -22;
      ELSE
        id_atto := NULL;
      END IF;

      IF dt IS NOT NULL AND (dt <> c1rec.data_scadenz OR dt2 <> c1rec.data_lav OR uni <> c1rec.unimm) THEN
        INSERT INTO loadcons_part_uiu
                    (id_caricamento, id_particella, cod_nazionale, foglio, particella, sub, unimm, utente, data_inizio,
                     data_fine, controlli, sorgente, atto_ini)
             VALUES (1, 1, co, fo, pa, su, uni, ut, dini,
                     dfin, 32, 9, id_atto);

       select cod_errore into ec from loadcons_part_uiu where id_caricamento=1;
       if (ec is not null and ec != 0) then
        raise_application_error(ec, 'Error ' || ec);
       end if;

        DELETE FROM loadcons_uiu;
        DELETE FROM loadcons_part_uiu;
      END IF;

      BEGIN
        -- a.caleffi 2008-12-12 aggiunta colonna atto_ini per memorizzare il codice dell'atto
        --   usato nel trigger loadcons_uiu_part

        INSERT INTO loadcons_uiu
                    (id_caricamento, id_particella, cuaa, quota_conduzione, quota_limite, tipo_titolo
                    , atto_ini)
             VALUES (1, 1, c1rec.cod_soggetto, c1rec.QUOTA, c1rec.limite, c1rec.tipo_titolo
                    , id_atto);
      --EXCEPTION
        --WHEN OTHERS THEN
          --NULL;
      END;

      dt := c1rec.data_scadenz;
      dt2 := c1rec.data_lav;
      co := getcodnaz (c1rec.istatp, c1rec.istatc, TRIM (c1rec.id_sezc));
      fo := c1rec.foglio;
      pa := c1rec.particella;
      su := c1rec.sub;
      uni := c1rec.unimm;
      dini := c1rec.data_lav;
      dfin := c1rec.data_scadenz;
--    exception when others then
--      errCode := sqlcode;
--      update impo_cons_uiu_base set error_code=errCode where current of c1;
    end;
  END LOOP;

  INSERT INTO loadcons_part_uiu
              (id_caricamento, id_particella, cod_nazionale, foglio, particella, sub, unimm, utente, data_inizio,
               data_fine, controlli, sorgente, atto_ini)
       VALUES (1, 1, co, fo, pa, su, uni, ut, dini,
               dfin, 32, 9, id_atto);

   select cod_errore into ec from loadcons_part_uiu where id_caricamento=1;
   if (ec is not null and ec != 0) then
    raise_application_error(ec, 'Error ' || ec);
   end if;

  -- COMMIT;
END;
/


DROP PROCEDURE SITI_H501.IMPOSTA_NULLABLE;

CREATE OR REPLACE PROCEDURE SITI_H501.imposta_nullable(TABELLA IN VARCHAR2,CAMPO IN VARCHAR2,IMPOSTALO_A_NULL NUMBER)
IS
CURSOR C1 IS SELECT 1 FROM USER_TAB_COLUMNS WHERE UPPER(TABLE_NAME)=UPPER(TABELLA) AND UPPER(COLUMN_NAME)=UPPER(CAMPO) AND UPPER(NULLABLE)='Y';
CURSOR C2 IS SELECT 1 FROM USER_TAB_COLUMNS WHERE UPPER(TABLE_NAME)=UPPER(TABELLA) AND UPPER(COLUMN_NAME)=UPPER(CAMPO) AND UPPER(NULLABLE)='N';
ESISTE NUMBER(1);
BEGIN
  IF IMPOSTALO_A_NULL = 1 THEN
  	OPEN C1;
  	FETCH C1 INTO ESISTE;
  	IF C1%NOTFOUND THEN ESISTE:=0; END IF;
  	CLOSE C1;
  ELSE
  	OPEN C2;
  	FETCH C2 INTO ESISTE;
  	IF C2%NOTFOUND THEN ESISTE:=0; END IF;
  	CLOSE C2;
  END IF;
  IF ESISTE=0 THEN
  	IF IMPOSTALO_A_NULL = 1 THEN
    	EXECUTE IMMEDIATE 'ALTER TABLE ' || TABELLA ||' MODIFY(' || CAMPO || ' NULL)';
	ELSE
		EXECUTE IMMEDIATE 'ALTER TABLE ' || TABELLA ||' MODIFY(' || CAMPO || ' NOT NULL)';
	END IF;
  END IF;
END;
/


DROP PROCEDURE SITI_H501.INSERISCI_PLAV;

CREATE OR REPLACE PROCEDURE SITI_H501.inserisci_plav(
    CN IN VARCHAR2,
    FOG IN NUMBER,
    PART IN VARCHAR2,
    SUBA IN VARCHAR2,
    IDLAV IN NUMBER,
    PROVRIF IN VARCHAR2,
    SETTORE IN NUMBER,
    UTENTE_INS IN VARCHAR2 DEFAULT 'AUTOMATICO',
    COMMITTA IN VARCHAR2 DEFAULT 'Y',
    SKIP_SE_PRESENTE VARCHAR2 DEFAULT 'N',
    INCAMPAGNA IN NUMBER DEFAULT 0,
    INTIPOLAVO IN NUMBER DEFAULT 0,
    MR IN NUMBER DEFAULT 0)
--  INSERISCE ALL'INTERNO DELLA TABELLA SITIPLAV
--  IDLAV PUò ESSERE NULLO IN TAL CASO VERRà RICAVATO UTILIZZANDO I CAMPI PROV_RIF + SETTORE
--  SE IDLAV NON è NULLO PROVRIF + SETTORE VERRANNO IGNORATI
--  SE CN è DI 4 CARATTERI SI INTENDE CODICE NAZIONALE, ALTRIMENTI SI INTENDE ISTATP || ISTATC || SEZIONE
--  ESEMPIO: '020030 ' PER COMUNE DI MANTOVA
IS
  ELE NUMBER(9);
  COMU VARCHAR2(4);
  FG  NUMBER(4);
  ISAU NUMBER(1);
  NUM_PRESENTI NUMBER(9);
  PTOUSE VARCHAR2(10);
BEGIN
  IF IDLAV IS NULL OR IDLAV=0 THEN
    SELECT ID_LAV
    INTO ELE
    FROM
    (
      SELECT ID_LAV
      FROM SITILISTALAV
      WHERE COD_SETTORE = SETTORE AND PROV_RIF=PROVRIF AND TIPOLAVORAZIONE<=5 AND
      (CAMPAGNA=INCAMPAGNA OR INCAMPAGNA=0) AND (TIPOLAVORAZIONE=INTIPOLAVO OR INTIPOLAVO=0)
      ORDER BY CAMPAGNA DESC,DATA_IMMI_ELEN DESC
    )
    WHERE ROWNUM=1;
  ELSE
    ELE:=IDLAV;
  END IF;

  IF Length(CN)=4 THEN
    COMU := CN;
  ELSE
    SELECT COD_NAZIONALE
    INTO COMU
    FROM SITICOMU
    WHERE COD_PROVINCIA = SubStr(CN,1,3) AND COD_COMUNE = SubStr(CN,4,3) AND SEZIONE_CENSUARIA = SubStr(CN,7,1);
  END IF;

  PTOUSE := LPad(PART,5,'0');

  SELECT FLAG_CATA
  INTO ISAU
  FROM SITICOMU WHERE COD_NAZIONALE=COMU;

  IF ISAU=2 THEN
    FG:=9999;
  ELSE
    FG:=FOG;
  END IF;

  IF Upper(SKIP_SE_PRESENTE)='Y' THEN
    SELECT Count(*)
    INTO NUM_PRESENTI
    FROM SITIPLAV WHERE cod_nazionale=COMU AND foglio=FG AND particella=PTOUSE AND sub=SUBA AND ID_LAV=ELE AND LAST=1;
  ELSE
    SELECT Count(*)
    INTO NUM_PRESENTI
    FROM SITIPLAV WHERE cod_nazionale=COMU AND foglio=FG AND particella=PTOUSE AND sub=SUBA AND ID_LAV=ELE AND DATA_LAV IS NULL AND LAST=1;
  END IF;

  IF(NUM_PRESENTI=0) THEN
    INSERT INTO SITIPLAV(ID_LAV,MOTI_RICH,COD_NAZIONALE,FOGLIO,PARTICELLA,SUB,UTENTEINS)
    VALUES (ELE,MR,COMU,FG,PTOUSE,SUBA,UTENTE_INS);
    IF COMMITTA='Y' THEN commit; END IF;
  ELSE
    IF SKIP_SE_PRESENTE='y' THEN
      --serve per far scattare i trg
      UPDATE SITIPLAV SET MOTI_RICH=MR WHERE cod_nazionale=COMU AND foglio=FG AND particella=PTOUSE AND sub=SUBA AND ID_LAV=ELE AND LAST=1;
      IF COMMITTA='Y' THEN commit; END IF;
    END IF;
  END IF;
END INSERISCI_PLAV;
/


DROP PROCEDURE SITI_H501.PATRI_GENERA_PARTICELLE;

CREATE OR REPLACE procedure SITI_H501.patri_genera_particelle(p_id_soggetto number) is
  -- Genera le particelle per le uiu che non l'hanno e le dà in proprietà al soggetto specificato
  cursor cUiu is
    select min(data_inizio_val) as data_inizio_val, max(data_fine_val) as data_fine_val,
           cod_nazionale, foglio, particella, sub from sitiuiu u
     where data_fine_val >= sysdate
       and not exists (select 1 from sititrkc where cod_nazionale=u.cod_nazionale and foglio=u.foglio and particella=u.particella
                          and sub=u.sub and data_fine >= sysdate)
    group by cod_nazionale, foglio, particella, sub;

  m_id_part   number(9);

begin
  for r in cUiu loop
    insert into sititrkc (sigla_prov, cod_nazionale, foglio, particella, sub, area_part, partita, valida, data_aggi,
                          rendita, data_fine) values
                         ((select sigla_prov from siticomu where cod_nazionale=r.cod_nazionale), r.cod_nazionale, r.foglio,
                          r.particella, r.sub, 0, '0', 1, r.data_inizio_val, 0, r.data_fine_val)
      returning trkc_id into m_id_part;

    insert into cons_cons_tab (pkid_cons, cod_nazionale, foglio, allegato, sviluppo, particella, sub, perc_poss, tipo_titolo,
                               pk_cuaa, data_inizio, data_fine, fl_totale)
      values (cons_tit_seq.nextval, r.cod_nazionale, r.foglio, '0', '0', r.particella, r.sub, 100, '1',
              p_id_soggetto, r.data_inizio_val, r.data_fine_val, 'Y');
  end loop;

  commit;
end;
/


DROP PROCEDURE SITI_H501.PATRI_SEND_MAIL;

CREATE OR REPLACE PROCEDURE SITI_H501.PATRI_SEND_MAIL (
   mittente       IN   VARCHAR2,
   destinatario   IN   VARCHAR2,
   oggetto        IN   VARCHAR2,
   messaggio      IN   VARCHAR2,
   smtpserver     IN   VARCHAR2,
   smtpport       IN   number,
   smtpuser       IN   VARCHAR2,
   smtppass       IN   VARCHAR2
)
IS
-- dichiarazione di una variabile a cui assegnare il nome del server SMTP utilizzato
-- in questo esempio l'SMTP ï¿½ quello di yahoo
   mailhost         VARCHAR2 (30)       := nvl(smtpserver,'localhost');
-- dichiarazione di una variabile di tipo utl_smtp.connection
-- a cui verrï¿½ assegnato l'SMTP ed il numero di porta (25)
   conn             UTL_SMTP.connection;
   crlf             VARCHAR2 (2)        := CHR (13) || CHR (10);
   mesg             VARCHAR2 (1000);
   local_mittente   VARCHAR2 (2000)     := mittente;
BEGIN
-- Apertura di una connessione al server
   conn := UTL_SMTP.open_connection (mailhost, nvl(smtpport,25));

    if not (smtpuser is null or smtppass is null or smtpuser =' ' or smtppass =' ') then
      UTL_SMTP.command( conn, 'AUTH LOGIN');
      UTL_SMTP.command( conn, utl_raw.cast_to_varchar2( utl_encode.base64_encode( utl_raw.cast_to_raw( smtpuser ))) );
      UTL_SMTP.command( conn, utl_raw.cast_to_varchar2( utl_encode.base64_encode( utl_raw.cast_to_raw( smtppass ))) );
    end if;


-- Assegnazione alla variabile mesg dell'intestazione della mail
   mesg :=
         'Date:'
      || TO_CHAR (SYSDATE, 'dy, dd Mon yyyy hh24:mi:ss', 'nls_date_language=english')
      || crlf
      || 'From:'
      || mittente
      || crlf
      || 'Subject:'
      || oggetto
      || crlf
      || 'To:'
      || destinatario
      || crlf
      || ''
      || crlf
      || messaggio;
-- Apertura di un collegamento al server
   UTL_SMTP.helo (conn, mailhost);
-- Inizio di una transazione di posta con il server passandogli il mittente
   UTL_SMTP.mail (conn, local_mittente);
-- il destinatario
   UTL_SMTP.rcpt (conn, destinatario);
-- ed il testo del messaggio
   UTL_SMTP.DATA (conn, mesg);
-- Chiusura della connessione
   UTL_SMTP.quit (conn);
END;
/


DROP PROCEDURE SITI_H501.PROCESSA_INDIRIZZI;

CREATE OR REPLACE procedure SITI_H501.processa_indirizzi(codNazionale varchar2, foglio number default null, particella varchar2 default null, sub varchar2 default null) is

  cursor cTemp is select p.cod_nazionale cod_naz, p.particella part, p.foglio foglio, p.sub sub,
                       c.pkid_civi pkciv 
         from siticivi c, sitipart p;

  TYPE refCur IS REF CURSOR;
  cur refCur;
  rowc cTemp%rowtype;
  sql_string VARCHAR(300);
begin
  sql_string := 'select p.cod_nazionale cod_naz, p.particella part, p.foglio foglio, p.sub sub, c.pkid_civi pkciv ' || ' from siticivi c, sitipart p ' || 
             ' where sdo_relate(c.shape, p.shape, ''querytype=WINDOW mask=ANYINTERACT'') = ''TRUE'' and ' || 
             ' p.cod_nazionale= ''' || codNazionale || ''' and ' || 
             ' p.data_fine_val = to_date(''99991231'',''yyyymmdd'')';
              
  if foglio is not null then
     sql_string := sql_string || ' and foglio = ' || foglio;
  end if; 
      
  if particella is not null then
     sql_string := sql_string || ' and particella = ''' || particella || '''';
  end if; 
   
  if sub is not null then
     sql_string := sql_string || ' and sub = ''' || sub || '''';
  end if; 
          
  open cur for sql_string;
  loop
    fetch cur into rowc;
    exit when cur%notfound;
    
    delete from siticivi_uiu cu
           where cu.pkid_uiu in (select u.pkid_uiu 
                                        from sitiuiu u where u.cod_nazionale = rowc.cod_naz
                                                             and u.foglio = rowc.foglio
                                                             and u.particella = rowc.part
                                                             and u.sub = rowc.sub
                                                             and data_fine_val = to_date('99991231', 'yyyymmdd'));
           
    for c in (select * 
                    from sitiuiu u where u.cod_nazionale = rowc.cod_naz
                                         and u.foglio = rowc.foglio
                                         and u.particella = rowc.part
                                         and u.sub = rowc.sub
                                         and data_fine_val = to_date('99991231', 'yyyymmdd'))
    loop
       insert into siticivi_uiu
         (pkid_civi, pkid_uiu, data_inizio_val, data_fine_val, scala, interno, piano, utente, utente_fine)
       values
         (rowc.pkciv, c.pkid_uiu, c.data_inizio_val, to_date('99991231','yyyymmdd'), 0, 0, 0, c.utente, c.utente_fine);
      
    end loop;
  
  end loop;
  close cur;

  /*commit;*/
end processa_indirizzi;

/


DROP PROCEDURE SITI_H501.RINOMINACAMPO;

CREATE OR REPLACE PROCEDURE SITI_H501.rinominacampo(TABELLA IN VARCHAR2,CAMPO IN VARCHAR2,NEWCAMPO IN VARCHAR2)
IS
CURSOR C1 IS SELECT 1 FROM USER_TAB_COLUMNS WHERE UPPER(TABLE_NAME)=UPPER(TABELLA) AND UPPER(COLUMN_NAME)=UPPER(CAMPO);
ESISTE NUMBER(1);
BEGIN
  OPEN C1;
  FETCH C1 INTO ESISTE;
  IF C1%NOTFOUND THEN ESISTE:=0; END IF;
  CLOSE C1;

  IF ESISTE=1 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE ' || TABELLA ||' RENAME COLUMN ' || CAMPO || ' TO ' || NEWCAMPO || '';
  END IF;
END;
/

