DROP PROCEDURE CS_ROMA.LOB_REPLACE;

CREATE OR REPLACE PROCEDURE CS_ROMA.lob_replace( p_lob in out clob, p_what in varchar2, p_with in varchar2 ) 
IS 
n number; 
begin 
n := dbms_lob.instr( p_lob, p_what ); 
if ( nvl(n,0) > 0 ) 
then 
dbms_lob.copy( p_lob, 
p_lob, 
dbms_lob.getlength(p_lob), 
n+length(p_with), 
n+length(p_what) );
dbms_lob.write( p_lob, length(p_with), n, p_with ); 
if ( length(p_what) > length(p_with) ) 
then 
dbms_lob.trim( p_lob, 
dbms_lob.getlength(p_lob)-(length(p_what)-length(p_with)) ); 
end if; 
end if; 
end;
/


