DROP PROCEDURE AM_ROMA.AGGIORNA_DB_AM_RIF;

CREATE OR REPLACE PROCEDURE AM_ROMA.AGGIORNA_DB_AM_RIF  IS
    tmpVar NUMBER;
    V_SQL VARCHAR2(1000);

    CURSOR C_APPLICATION IS 
        SELECT 'UPDATE AM_APPLICATION SET (APP_TYPE, APP_CATEGORY , FLG_DATA_ROUTER ) = ( SELECT ''' || 
        DEV.APP_TYPE || ''',''' || DEV.APP_CATEGORY || ''',''' || DEV.FLG_DATA_ROUTER || ''' FROM DUAL)'  ||
        ' WHERE NAME = ''' || GIT.NAME  || ''' ;' AS SQLSTRING
        FROM AM_F704_GIT.AM_APPLICATION DEV, AM_F704_GIT.AM_APPLICATION GIT
        WHERE DEV.NAME = GIT.NAME;

        CURSOR C_INS_APPLICATION IS
        SELECT 'insert into AM_APPLICATION  VALUES (''' || NAME || ''',''' ||  APP_TYPE || ''',''' ||  APP_CATEGORY || ''',''' ||  FLG_DATA_ROUTER || '''); ' SQLSTRING 
        FROM AM_F704_GIT.AM_APPLICATION  dev
        WHERE NOT EXISTS (SELECT 1 FROM AM_APPLICATION  git WHERE DEV.NAME = git.name );

        CURSOR C_ITEM IS 
        SELECT 'INSERT INTO am_item git VALUES (''' || NAME  || ''' );' SQLSTRING
        FROM AM_F704_GIT.AM_ITEM DEV
        WHERE NOT EXISTS (SELECT 1 FROM AM_ITEM GIT1 WHERE GIT1.NAME = DEV.NAME);

        CURSOR C_APP_ITEM IS 
        SELECT 'INSERT INTO am_application_item git VALUES ( (SELECT MAX(ID)+1 FROM AM_APPLICATION_ITEM) , '''|| FK_AM_APPLICATION  || ''',''' ||  FK_AM_ITEM  || ''');' SQLSTRING
        FROM AM_F704_GIT.AM_APPLICATION_ITEM DEV
        WHERE NOT EXISTS (SELECT 1 FROM AM_APPLICATION_ITEM GIT1 WHERE GIT1.FK_AM_APPLICATION = DEV.FK_AM_APPLICATION
        AND GIT1.FK_AM_ITEM = DEV.FK_AM_ITEM);


        CURSOR C_ROLE IS 
        SELECT 'INSERT INTO am_ROLE git VALUES (''' || NAME  || ''' );' SQLSTRING
        FROM AM_F704_GIT.AM_ROLE DEV
        WHERE NOT EXISTS (SELECT 1 FROM AM_ROLE GIT1 WHERE GIT1.NAME = DEV.NAME);


        CURSOR C_PERMISSION IS 
        SELECT 'INSERT INTO am_PERMISSION git VALUES ( ''' || NAME   || ''',''' ||  FK_AM_ITEM  || ''');' SQLSTRING
        FROM AM_F704_GIT.AM_PERMISSION DEV
        WHERE NOT EXISTS (SELECT 1 FROM AM_PERMISSION GIT1 WHERE GIT1.NAME = DEV.NAME
        AND GIT1.FK_AM_ITEM = DEV.FK_AM_ITEM);

        CURSOR C_FONTE IS 
        SELECT 'INSERT INTO am_FONTE git VALUES ( ''' || ID   || ''',''' ||  CODICE  || ''',''' || DESCRIZIONE || ''',''' || TIPO_FONTE || ''',''' || N_ORDINE || ''');' SQLSTRING
        FROM AM_F704_GIT.AM_FONTE DEV
        WHERE NOT EXISTS (SELECT 1 FROM AM_FONTE GIT1 WHERE GIT1.ID = DEV.ID);


        CURSOR C_FONTE_TI IS 
        SELECT 'INSERT INTO am_FONTE_TIPOINFO git VALUES ( ''' || FK_AM_FONTE   || ''',''' ||  INFORMAZIONE  || ''',''' || PROG_OLD || ''',''' || N_ORDINE_SU_FONTE || ''');' SQLSTRING
        FROM AM_F704_GIT.am_FONTE_TIPOINFO DEV
        WHERE NOT EXISTS (SELECT 1 FROM am_FONTE_TIPOINFO GIT1 WHERE GIT1.FK_AM_FONTE = DEV.FK_AM_FONTE AND GIT1.INFORMAZIONE = DEV.INFORMAZIONE);


        CURSOR C_SECTION IS 
       SELECT 'INSERT INTO AM_SECTION git VALUES ( ''' || NAME    || ''',''' ||  TIPO  || ''',''' ||  FK_AM_APPLICATION   || ''',''' ||  FK_AM_FONTE || ''',''' ||  N_ORDINE || ''', (SELECT MAX(ID)+1 FROM AM_SECTION) );' SQLSTRING
        FROM AM_F704_GIT.AM_SECTION  DEV
        WHERE NOT EXISTS (SELECT 1 FROM AM_SECTION GIT1 WHERE GIT1.NAME  = DEV.NAME 
       AND GIT1.FK_AM_APPLICATION = DEV.FK_AM_APPLICATION )
        AND EXISTS (SELECT 1 FROM AM_APPLICATION AA WHERE DEV.FK_AM_APPLICATION =  AA.NAME );

        CURSOR C_AUDIT_DECODE IS
       SELECT 'INSERT INTO am_audit_decode git VALUES ( ''' || ID    || ''',''' || STANDARD  || ''',''' ||  METHOD_NAME   || ''',''' ||  CLASS_NAME || ''',''' ||  DESCRIZIONE 
       || ''',''' ||  CAMPO_CHIAVE
       || ''',''' ||  FK_AM_FONTE
       || ''',''' ||  FK_AM_FONTE_TIPOINFO
       || ''');' SQLSTRING
        FROM AM_F704_GIT.am_audit_decode  DEV
        WHERE NOT EXISTS (SELECT 1 FROM am_audit_decode GIT1 WHERE GIT1.ID  = DEV.ID 
       AND GIT1.STANDARD = DEV.STANDARD );

        CURSOR C_KEY_VALUE IS 
            SELECT 'INSERT INTO AM_KEY_VALUE git VALUES ( ''' || KEY_CONF   || ''',''' ||  VALUE_CONF  || ''',''' ||  KEY_INDEX  || ''',''' ||  DELETED || ''',''' ||  MUST_BE_SET  || ''',''' ||  OVERW_TYPE  || ''',''' ||  SECTION_NAME 
            ||  ''',''' ||  FK_AM_APPLICATION || ''',''' ||  DESCRIZIONE_KEY || ''', (SELECT MAX(ID)+1 FROM AM_KEY_VALUE) );' SQLSTRING
            FROM AM_F704_GIT.AM_KEY_VALUE DEV
            WHERE NOT EXISTS (SELECT 1 FROM AM_KEY_VALUE GIT1 WHERE GIT1.KEY_CONF = DEV.KEY_CONF
            AND GIT1.SECTION_NAME = DEV.SECTION_NAME  
            AND GIT1.FK_AM_APPLICATION = DEV.FK_AM_APPLICATION 
            and DEV.FK_AM_APPLICATION  is not null
            )
            and DEV.FK_AM_APPLICATION  is NOT null
            AND EXISTS (SELECT 1 FROM AM_APPLICATION AA WHERE DEV.FK_AM_APPLICATION =  AA.NAME )
            UNION
            SELECT 'INSERT INTO AM_KEY_VALUE git VALUES ( ''' || KEY_CONF   || ''',''' ||  VALUE_CONF  || ''',''' ||  KEY_INDEX  || ''',''' ||  DELETED || ''',''' ||  MUST_BE_SET  || ''',''' ||  OVERW_TYPE  || ''',''' ||  SECTION_NAME 
                    ||  ''',''' ||  FK_AM_APPLICATION || ''',''' ||  DESCRIZIONE_KEY || ''', (SELECT MAX(ID)+1 FROM AM_KEY_VALUE) );' SQLSTRING
                    FROM AM_F704_GIT.AM_KEY_VALUE DEV
                    WHERE NOT EXISTS (SELECT 1 FROM AM_KEY_VALUE GIT1 WHERE GIT1.KEY_CONF = DEV.KEY_CONF
                    AND GIT1.SECTION_NAME = DEV.SECTION_NAME  
                   )
                    and DEV.FK_AM_APPLICATION  is null;
        

    BEGIN

    FOR R_APPLICATION IN C_APPLICATION LOOP
        DBMS_OUTPUT.PUT_LINE (R_APPLICATION.SQLSTRING);
    END LOOP;
    
    
    FOR R_INS_APPLICATION IN C_INS_APPLICATION LOOP
        DBMS_OUTPUT.PUT_LINE (R_INS_APPLICATION.SQLSTRING);
    END LOOP;
    
    FOR R_ITEM IN C_ITEM LOOP
        DBMS_OUTPUT.PUT_LINE (R_ITEM.SQLSTRING);
    END LOOP;
    
    FOR R_APP_ITEM IN C_APP_ITEM LOOP
        DBMS_OUTPUT.PUT_LINE (R_APP_ITEM.SQLSTRING);
    END LOOP;


    FOR R_ROLE IN C_ROLE LOOP
        DBMS_OUTPUT.PUT_LINE (R_ROLE.SQLSTRING);
    END LOOP;

    FOR R_PERMISSION IN C_PERMISSION LOOP
        DBMS_OUTPUT.PUT_LINE (R_PERMISSION.SQLSTRING);
    END LOOP;
    

        FOR R_FONTE IN C_FONTE LOOP
        DBMS_OUTPUT.PUT_LINE (R_FONTE.SQLSTRING);
    END LOOP;
    
        FOR R_SECTION IN C_SECTION LOOP
        DBMS_OUTPUT.PUT_LINE (R_SECTION.SQLSTRING);
    END LOOP;
    
    FOR R_KEY_VALUE IN C_KEY_VALUE LOOP
        DBMS_OUTPUT.PUT_LINE (R_KEY_VALUE.SQLSTRING);
    END LOOP;
    
    
            FOR R_FONTE_TI IN C_FONTE_TI  LOOP
        DBMS_OUTPUT.PUT_LINE (R_FONTE_TI.SQLSTRING);
    END LOOP;
    
    
    FOR R_AUDIT_D IN C_AUDIT_DECODE  LOOP
        DBMS_OUTPUT.PUT_LINE (R_AUDIT_D.SQLSTRING);
    END LOOP;
    
    DBMS_OUTPUT.PUT_LINE  ( '**************** LE DUE INSERT SONO DA INCLUDERE NELLO SCRIPT  solo dopo che non ci sono altre insert dall''esecuzione dello script******************' ); 
         DBMS_OUTPUT.PUT_LINE  ( ' INSERT INTO AM_AI_ROLE AIR 
        SELECT (SELECT MAX(ID) FROM AM_AI_ROLE) + ROWNUM ID  , AI.ID FK_AM_APPLICATION_ITEM , ''Manager''
         FROM AM_APPLICATION_ITEM  AI
         WHERE NOT EXISTS 
         (SELECT 1 FROM AM_AI_ROLE AIR WHERE AIR.FK_AM_APPLICATION_ITEM =  AI.ID);');

    DBMS_OUTPUT.PUT_LINE  ( 'INSERT INTO AM_PERMISSION_AIR 
   SELECT P.NAME , AIR.ID FROM AM_PERMISSION P , AM_AI_ROLE AIR, AM_APPLICATION_ITEM AI
   WHERE P.FK_AM_ITEM = AI.FK_AM_ITEM
   AND AIR.FK_AM_APPLICATION_ITEM = AI.ID
   AND AIR.FK_AM_ROLE = ''Manager'' AND p.name not in (''Restrizione lista soggetti'',''Mappa ESRI'')
   AND NOT EXISTS
   (select 1 from AM_PERMISSION_AIR AAA WHERE  AAA.FK_AM_AI_ROLE = AIR.ID AND AAA.FK_AM_PERMISSION = P.NAME);');

    DBMS_OUTPUT.PUT_LINE  ( '******************************************************************************************' ); 

    DBMS_OUTPUT.PUT_LINE  ( '******************************************************************************************' ); 
    DBMS_OUTPUT.PUT_LINE  ( '***********************attenzione : LA PROCEDURA DEVE ESSERE RILANCIATA PIU'' VOLTE *************************************' ); 
    DBMS_OUTPUT.PUT_LINE  ( '************************ FINO A QUANDO NON CI SARANNO PIU INSERT DA FARE                ******************' ); 
    DBMS_OUTPUT.PUT_LINE  ( '************************** TRANNE LE DUE FINALI                                                    *************************' ); 
    DBMS_OUTPUT.PUT_LINE  ( '******************************************************************************************' ); 



   EXCEPTION
     WHEN OTHERS THEN

       RAISE;
END AGGIORNA_DB_AM_RIF;
/

DROP VIEW AM_ROMA.V_COMUNI_UTENTI_APPLICAZIONI;

/* Formatted on 18/07/2022 12:40:42 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW AM_ROMA.V_COMUNI_UTENTI_APPLICAZIONI
(
    FK_AM_USER,
    FK_AM_COMUNE,
    FK_AM_APPLICATION
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT uaiR.fk_am_user, IC.fk_am_comune, AI.FK_AM_APPLICATION
      FROM AM_USER_AIR          uaiR,
           AM_AI_ROLE           air,
           AM_APPLICATION_ITEM  AI,
           AM_INSTANCE          I,
           AM_INSTANCE_COMUNE   IC,
           AM_COMUNE            C
     WHERE     uair.fk_am_ai_role = AIR.ID
           AND AI.ID = AIR.FK_AM_APPLICATION_ITEM
           AND I.FK_AM_APPLICATION = AI.FK_AM_APPLICATION
           AND I.NAME = IC.FK_AM_INSTANCE
           AND IC.FK_AM_COMUNE = UAIR.FK_AM_COMUNE
           AND C.BELFIORE = IC.FK_AM_COMUNE
    UNION
    SELECT DISTINCT uGR.fk_am_user, IC.fk_am_comune, AI.FK_AM_APPLICATION
      FROM AM_GROUP_AIR         gAiR,
           AM_AI_ROLE           air,
           AM_APPLICATION_ITEM  AI,
           AM_INSTANCE          I,
           AM_INSTANCE_COMUNE   IC,
           AM_GROUP             GR,
           AM_USER_GROUP        UGR
     WHERE     gair.fk_am_ai_role = AIR.ID
           AND AI.ID = AIR.FK_AM_APPLICATION_ITEM
           AND I.FK_AM_APPLICATION = AI.FK_AM_APPLICATION
           AND I.NAME = IC.FK_AM_INSTANCE
           AND IC.FK_AM_COMUNE = GR.FK_AM_COMUNE
           AND GR.NAME = GAIR.FK_AM_GROUP
           AND UGR.FK_AM_GROUP = GR.NAME;


DROP VIEW AM_ROMA.V_COMUNI_UTENTI_INSTANCE;

/* Formatted on 18/07/2022 12:40:42 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW AM_ROMA.V_COMUNI_UTENTI_INSTANCE
(
    FK_AM_USER,
    FK_AM_COMUNE,
    FK_AM_INSTANCE,
    FK_AM_APPLICATION,
    URL
)
BEQUEATH DEFINER
AS
    SELECT A.FK_AM_USER,
           AIC."FK_AM_COMUNE",
           AIC."FK_AM_INSTANCE",
           I.FK_AM_APPLICATION,
           I.URL
      FROM V_COMUNI_UTENTI_APPLICAZIONI  A,
           AM_INSTANCE_COMUNE            AIC,
           AM_INSTANCE                   I
     WHERE     A.FK_AM_COMUNE = AIC.FK_AM_COMUNE
           AND A.FK_AM_APPLICATION = I.FK_AM_APPLICATION
           AND I.NAME = AIC.FK_AM_INSTANCE;


DROP VIEW AM_ROMA.V_UTENTI_INSTANCE_GRUPPI;

/* Formatted on 18/07/2022 12:40:42 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW AM_ROMA.V_UTENTI_INSTANCE_GRUPPI
(
    FK_AM_USER,
    FK_AM_APPLICATION,
    FK_AM_COMUNE,
    INSTANCE,
    GRUPPO
)
BEQUEATH DEFINER
AS
    SELECT DISTINCT uGR.fk_am_user,
                    I.FK_AM_APPLICATION,
                    IC.fk_am_comune,
                    I.NAME      INSTANCE,
                    GR.NAME     GRUPPO
      FROM AM_GROUP_AIR         gAiR,
           AM_AI_ROLE           air,
           AM_APPLICATION_ITEM  AI,
           AM_INSTANCE          I,
           AM_INSTANCE_COMUNE   IC,
           AM_GROUP             GR,
           AM_USER_GROUP        UGR
     WHERE     gair.fk_am_ai_role = AIR.ID
           AND AI.ID = AIR.FK_AM_APPLICATION_ITEM
           AND I.FK_AM_APPLICATION = AI.FK_AM_APPLICATION
           AND I.NAME = IC.FK_AM_INSTANCE
           AND IC.FK_AM_COMUNE = GR.FK_AM_COMUNE
           AND GR.NAME = GAIR.FK_AM_GROUP
           AND UGR.FK_AM_GROUP = GR.NAME;


