DROP PACKAGE BODY DBTOTALE_H501.T00_UTIL;

CREATE OR REPLACE Package Body DBTOTALE_H501.T00_util IS

----------------------------------------------------------------------------------------
-- Apre e ritorna l'handler del file
----------------------------------------------------------------------------------------
FUNCTION open_file(p_directory VARCHAR2, p_file_name VARCHAR2)
RETURN sys.utl_file.file_type
IS
BEGIN
   file_name := p_file_name||'_'||TO_CHAR(SYSDATE,'DD_MM_YYYY')||'.txt';
   return sys.utl_file.FOPEN(p_directory,file_name,'w');
END;


----------------------------------------------------------------------------------------
-- Chiude il file
----------------------------------------------------------------------------------------
PROCEDURE close_file(p_file_hwnd IN OUT sys.utl_file.file_type)
IS
BEGIN
     sys.utl_file.FFLUSH(p_file_hwnd);
     sys.utl_file.fclose(p_file_hwnd);
END;


----------------------------------------------------------------------------------------
-- Scrive il log sul file
----------------------------------------------------------------------------------------
PROCEDURE scrivi_file(p_file_hwnd IN OUT sys.utl_file.file_type , p_log VARCHAR2)
IS
BEGIN
     sys.utl_file.PUT_LINE(p_file_hwnd,p_log);
END;

----------------------------------------------------------------------------------------
-- Ritorna il nome del file
----------------------------------------------------------------------------------------
FUNCTION get_file_name
RETURN VARCHAR2
IS
BEGIN
return UPPER(file_name);
END;


END;
/

DROP PACKAGE BODY RE_ROMA.UTIL;

CREATE OR REPLACE PACKAGE BODY RE_ROMA.UTIL as

   procedure DROP_IF_EXIST (TABNAME varchar2) AS
	Begin  
	  execute immediate 'Drop table ' || TABNAME;
	  Exception when others then null;
	End;

  procedure SEQUENCE_MAN (TABNAME VARCHAR2, VALID NUMBER,  RET OUT NUMBER)
  as
       pragma AUTONOMOUS_TRANSACTION;

       seq_name varchar2(100);
	   sqlstr varchar2(255);
	   LASTN NUMBER;
	   DIFF NUMBER;
   begin
       seq_name := 'SEQ_' || TABNAME;

	   BEGIN

	   		IF VALID IS NOT NULL THEN
			   	   -- CONTROLLO SE IL VALORE ICHE SI VUOLE INSERIRE IN ID
				   -- E' MINORE DEL SEQUENCE
				   select LAST_NUMBER INTO LASTN from user_sequences
			   	   where SEQUENCE_NAME =seq_name;

				   IF LASTN >= VALID THEN
				   	  		-- NEL CASO SIA MINORE O UGUALE ALLORA NON INSERISCO IL VALID MA IL VALORE DEL SEQUENCE
				   		   EXECUTE IMMEDIATE 'SELECT ' || SEQ_NAME || '.NEXTVAL FROM DUAL' INTO RET;
				   ELSE
			   		-- NEL CASO CHE VALID SIA MAGGIORE DEL VALORE CORRENTE DEL SEGUENCE
					-- ALLORA MODIFICO IL SEQUENCE, DANDOGLI L'ULTIMO VALORE QUELLO DI VALID
			   		DIFF := (VALID - LASTN) + 1;
					-- RIALLINEO IL SEQUENCE
					sqlstr := 'ALTER SEQUENCE '||  seq_name || ' INCREMENT BY ' || NVL(DIFF,1);
					EXECUTE IMMEDIATE  sqlstr;
		            EXECUTE IMMEDIATE 'SELECT ' || SEQ_NAME || '.NEXTVAL FROM DUAL' INTO RET;
					EXECUTE IMMEDIATE 'ALTER SEQUENCE '||  seq_name || ' INCREMENT BY 1';

				   END IF;
		     ELSE
  		   		   EXECUTE IMMEDIATE 'SELECT ' || SEQ_NAME || '.NEXTVAL FROM DUAL' INTO RET;
			 END IF;
			 COMMIT;
       EXCEPTION
	   WHEN OTHERS THEN
	   		NULL;
       END;


   end;

   
end UTIL; 
/

DROP PACKAGE BODY ARGO_ROMA.AR_PROGETTI_REFRESH;

CREATE OR REPLACE PACKAGE BODY ARGO_ROMA.AR_PROGETTI_REFRESH AS

 PROCEDURE AGGIORNA_PROGETTI_FSE is
 begin

   --Valorizzo il belfiore della tabella di import per gestire le fasi successive
    update IMPORT_SIRU_PROGETTI_ATTIVITA imp
    set imp.belfiore = (select distinct SIRU_BELFIORE from AR_O_ORGANIZZAZIONE_FSE where upper(siru_denominazione)=upper(imp.denominazione_sog))
    where imp.belfiore is null;

    --Carico i progetti non presenti in AR_FF_PROGETTO
    MERGE INTO AR_FF_PROGETTO p USING
    (select distinct COD_LOCALE_PROGETTO, 'FSE: '||INT_DESCRIZIONE DESCRIZIONE from IMPORT_SIRU_PROGETTI_ATTIVITA WHERE BELFIORE IS NOT NULL) np
    ON (np.COD_LOCALE_PROGETTO=p.CODICE_MEMO)
    WHEN NOT MATCHED THEN INSERT(ID,CODICE_MEMO,DESCRIZIONE,USER_INS,DT_INS,ABILITATO)
    VALUES(SQ_ID.nextval,np.COD_LOCALE_PROGETTO,np.DESCRIZIONE,'AR_PROGETTI_REFRESH',SYSDATE,1);

    --Collego i progetti alle organizzazioni
    MERGE into AR_FF_PROGETTO_ORG porg USING
    (select o.ar_o_org_id, p.id progetto_id from AR_O_ORGANIZZAZIONE_FSE o, AR_FF_PROGETTO p, IMPORT_SIRU_PROGETTI_ATTIVITA imp
    where upper(IMP.DENOMINAZIONE_SOG) = upper(o.siru_denominazione) and IMP.COD_LOCALE_PROGETTO=P.CODICE_MEMO AND P.CODICE_MEMO like 'FSE%'
    minus
    select organizzazione_id, progetto_id from AR_FF_PROGETTO_ORG) xx
    ON (XX.ar_o_org_id=porg.organizzazione_id and XX.progetto_id=porg.progetto_id)
    WHEN NOT MATCHED THEN INSERT(ID,ORGANIZZAZIONE_ID,PROGETTO_ID,ABILITATO,USER_INS,DT_INS)
    VALUES (SQ_ID.nextval,xx.ar_o_org_id, xx.progetto_id, 1, 'AR_PROGETTI_REFRESH', SYSDATE);

    --Inserisco le attività
    MERGE INTO AR_FF_PROGETTO_ATTIVITA a USING
    (select p.id progetto_id, IMP.ATTIVITA_ID, IMP.TITOLO_CORSO, LPAD(IMP.COD_CORSO,2,'0') tooltip from AR_FF_PROGETTO p, IMPORT_SIRU_PROGETTI_ATTIVITA imp
    where IMP.COD_LOCALE_PROGETTO=P.CODICE_MEMO AND P.CODICE_MEMO like 'FSE%') an
    ON (a.progetto_id=an.progetto_id and a.codice=an.ATTIVITA_ID)
    WHEN NOT MATCHED THEN INSERT (ID,PROGETTO_ID,CODICE, DESCRIZIONE,TOOLTIP,ABILITATO,USER_INS,DT_INS)
    VALUES(SQ_ID.nextval, an.PROGETTO_ID, an.ATTIVITA_ID,TITOLO_CORSO,  an.TOOLTIP, 1, 'AR_PROGETTI_REFRESH', SYSDATE);

end;

end;
/


DROP PACKAGE BODY ARGO_ROMA.ETL_CHARTA;

CREATE OR REPLACE PACKAGE BODY ARGO_ROMA.ETL_CHARTA
AS
   PROCEDURE ETL_CHARTA_CS
   IS
   BEGIN
      DELETE FROM V_NUM_INT_CS@SOCIOSAN_SPAGO;


      INSERT INTO V_NUM_INT_CS@SOCIOSAN_SPAGO
         SELECT * FROM ARGO.V_NUM_INT_CS;

      COMMIT;
   END;

   PROCEDURE ETL_CHARTA_UDC
   IS
   BEGIN
      DELETE FROM V_NUM_INT_UDC_DETT@SOCIOSAN_SPAGO;


      --  INSERT INTO V_NUM_INT_UDC_DETT@SOCIOSAN_SPAGO
      -- SELECT * FROM ARGO.V_NUM_INT_UDC_DETT;

      EXECUTE IMMEDIATE 'DROP TABLE V_NUM_INT_UDC_DETT_TEMP';

      EXECUTE IMMEDIATE 'create table V_NUM_INT_UDC_DETT_TEMP as  SELECT
     ZONA_SOCIALE, ID_SCHEDA, ORGANIZZAZIONE_ID, ORGANIZZAZIONE, UFFICIO_ID,
     UFFICIO, PUNTO_DI_CONTATTO_ID, PUNTO_DI_CONTATTO, sha1.gethash(COGNOME) COGNOME,sha1.gethash(NOME) NOME,
     CITTADINANZA, COMUNE, VIA, TIPO_INTEVENTO_ID, TIPO_INTERVENTO,
     INTERLOCUTORE, COMPLETA, ELIMINATA, DATA_INSERIMENTO, DATA_ACCESSO,
     SESSO, DATA_NASCITA, ETA, ID, BISOGNI_ESPRESSI,
     INTER_RICH, SERVIZI_RICHIESTI
     FROM V_NUM_INT_UDC_DETT WHERE COMPLETA = 1 AND ELIMINATA = 0';


      INSERT INTO V_NUM_INT_UDC_DETT@SOCIOSAN_SPAGO
         SELECT * FROM V_NUM_INT_UDC_DETT_TEMP;

      COMMIT;

      --EXECUTE IMMEDIATE 'drop table V_NUM_INT_UDC_DETT_TEMP';
   END;
END;
/


DROP PACKAGE BODY ARGO_ROMA.SHA1;

CREATE OR REPLACE Package Body ARGO_ROMA.sha1 Is Function gethash_raw (p_raw In Raw) Return Raw As Language Java Name 'Sha1.GetHash(byte[]) return byte[]'; Function gethash(p_str In Varchar2) Return Varchar2 Is Begin Return RawToHex(gethash_raw(Utl_Raw.Cast_To_Raw(p_str))); End gethash; End sha1;
/

