-- LA PROCEDURA COLLEGA CIVICO TOTALE A CIVICO UNICO  
PROCEDURE STEP_UPDATE_CIVICO_TOTALE IS

BEGIN

    ------------ svuoto relazioni   
    --update SIT_CIVICO_TOTALE t set t.FK_CIVICO = NULL , t.NOTE = null, t.RATING = null, t.REL_DESCR = null;

    --BEGIN
    --    EXECUTE IMMEDIATE 'TRUNCATE TABLE SIT_CIVICO_UNICO';
    --EXCEPTION 
    --WHEN OTHERS THEN 
    --    NULL;
    --END;        

    --INSERT INTO SIT_CIVICO_UNICO (ID_CIVICO,CIVICO,FK_VIA,DT_INS) 
      --                              select  SEQ_CIVICO_UNICO.nextval ID_CIVICO , CIVICO, FK_VIA,DT_INS  
      --                              from (select distinct  
      --                              t.CIV_LIV1 CIVICO,   
      --                              vt.FK_VIA FK_VIA, 
      --                              sysdate DT_INS  
      --                              from SIT_CIVICO_TOTALE t, SIT_VIA_TOTALE vt  
      --                              where  
      --                              vt.FK_ENTE_SORGENTE = t.FK_ENTE_SORGENTE 
      --                              and vt.PROG_ES = t.PROG_ES 
      --                              and t.ID_ORIG_VIA_TOTALE = vt.ID_DWH );



    declare
        cursor c_vu is select * from sit_via_unico;
    begin
        for rec_vu in c_vu loop
            DECLARE
                CURSOR C_VT IS SELECT * FROM SIT_VIA_TOTALE VT WHERE 
                VT.FK_VIA = REC_VU.ID_VIA;
            BEGIN
            FOR REC_VT IN C_VT LOOP
                UPDATE SIT_CIVICO_TOTALE CT SET FK_VIA = rec_vu.id_via
                where 
                    ct.id_orig_via_totale = REC_VT.ID_DWH       AND
                    REC_Vt.fk_ente_sorgente = ct.fk_ente_sorgente    AND
                    REC_Vt.prog_es = ct.PROG_ES;

                COMMIT;
            END LOOP;
                
            END;
            
                        
        end loop;
    end;
        
            DECLARE 
                cursor c_cu is 
                select u.civico, u.id_civico, FK_VIA
                from sit_civico_unico u;
            begin        
        
                for rec_c in c_cu loop
                
                    
                      UPDATE sit_civico_totale t 
                                    SET t.fk_civico = REC_C.id_civico ,
                                      t.rating = 100, 
                                      t.rel_descr = 'NATIVA'
                      WHERE T.FK_VIA = REC_C.FK_VIA
                      AND T.CIV_LIV1 = REC_C.CIVICO;
                    

                    COMMIT;

                end loop;
            end;
            
END;

END;
/


DROP PACKAGE BODY DIOGENE_H501.LAYER_TOOLS;

CREATE OR REPLACE PACKAGE BODY DIOGENE_H501.LAYER_TOOLS AS
/******************************************************************************
   NAME:       LAYER_TOOLS
   PURPOSE:

   REVISIONS:
   Ver        Date        Author           Description
   ---------  ----------  ---------------  ------------------------------------
   1.0        16/12/2011      Utente       1. Created this package body.
******************************************************************************/
  FUNCTION getcodeprgc (cod IN NUMBER)
      RETURN VARCHAR2
   IS
      CURSOR cur
      IS
         SELECT codut
           FROM PGT_SQL_DECO_LAYER
          WHERE id = cod;

      retval   VARCHAR2 (2048);
   BEGIN
      OPEN cur;

      FETCH cur
       INTO retval;

      IF cur%NOTFOUND
      THEN
         retval := '';
      END IF;

      CLOSE cur;

      RETURN retval;
   END getcodeprgc;

   FUNCTION getcodeprgc_descr (cod IN NUMBER)
      RETURN VARCHAR2
   IS
      CURSOR cur
      IS
         SELECT codut || ' - ' || descrizione
           FROM PGT_SQL_DECO_LAYER
          WHERE id = cod;

      retval   VARCHAR2 (2048);
   BEGIN
      OPEN cur;

      FETCH cur
       INTO retval;

      IF cur%NOTFOUND
      THEN
         retval := '';
      END IF;

      CLOSE cur;

      RETURN retval;
   END getcodeprgc_descr;

   FUNCTION setcodeprgc (str IN VARCHAR2)
      RETURN NUMBER
   IS
      CURSOR cur
      IS
         SELECT id
           FROM PGT_SQL_DECO_LAYER
          WHERE codut = str;

      retval   NUMBER;
   BEGIN
      OPEN cur;

      FETCH cur
       INTO retval;

      IF cur%NOTFOUND
      THEN
         retval := 0;
      END IF;

      CLOSE cur;

      RETURN retval;
   END setcodeprgc;



END LAYER_TOOLS;
/


DROP PACKAGE BODY DIOGENE_H501.PROGETTO_TARSU;

CREATE OR REPLACE package body DIOGENE_H501.progetto_tarsu as

procedure prepara_sit_rep_tarsu (codente varchar2) is

begin

    begin
        execute immediate 'DELETE SIT_REP_TARSU';
        exception when others then null;
    end;
    
    insert into sit_rep_tarsu
    (pkid_uiu, foglio, particella, sub, unimm, data_inizio_val, categoria, classe, 
    consistenza, rendita, sup_cat, zona, edificio, scala, interno, piano, 
    pk_cuaa, cuaa, perc_poss, tipo_titolo, data_inizio, 
    pkid, denominazione, sesso, d_nascita)
    (select distinct 
    u.pkid_uiu, u.foglio, u.particella, u.sub, u.unimm, u.data_inizio_val, u.categoria, u.classe, 
    u.consistenza,  u.rendita, u.sup_cat, u.zona, u.edificio, u.scala, u.interno, u.piano, 
    sc.pk_cuaa, sc.cuaa, sc.perc_poss, sc.tipo_titolo, sc.data_inizio, 
    to_char (ans.pkid) as pkid, ans.denominazione, ans.sesso, ans.d_nascita
    from sitiuiu u, siticonduz_imm_all sc, anag_soggetti ans
    where u.cod_nazionale=codente
    and u.data_fine_val=to_date('99991231','yyyymmdd')
    and u.cod_nazionale=sc.cod_nazionale (+)
    and u.data_fine_val=sc.data_fine (+) 
    and u.foglio=sc.foglio(+) 
    and u.particella=sc.particella(+) 
    and u.sub=sc.sub(+)
    and u.unimm=sc.unimm(+)
    and sc.data_fine= ans.data_fine_val (+)
    and sc.pk_cuaa=ans.cod_soggetto (+));
    
end;



procedure sup_tarsu_cat is
begin
    declare cursor c is select distinct foglio, particella, sub, unimm, sup_cat from sit_rep_tarsu;
    begin
       for rec_c in c
       loop
          declare 
            errore varchar2(255byte);
            V_SUP_TARSU NUMBER;
            V_SUP_DA_TARSU NUMBER;
            V_CHECK_C340 NUMBER := 0;
          begin
            BEGIN
                select (sum (supe_ambiente)) INTO V_SUP_TARSU
                 from sitiedi_vani sev
                where (ambiente = 'A' or ambiente = 'B' or ambiente = 'C')
                  and foglio = rec_c.foglio
                  and particella = rec_c.particella
                  and sub = rec_c.sub
                  and unimm = rec_c.unimm
                  and data_fine_val=to_date('99991231','yyyymmdd');
            EXCEPTION 
            WHEN OTHERS THEN
                V_SUP_TARSU := NULL;
            END;
          
            BEGIN
                select T.SUP_TOT INTO V_SUP_DA_TARSU 
                from sit_t_TAR_OGGETTO t
                                where LPAD(T.foglio,5,'0') = LPAD(TO_CHAR(rec_c.foglio),5,'0') 
                                    and LPAD(T.NUMERO,5,'0') = LPAD(rec_c.particella,5,'0')  
                                    and LPAD(T.sub,4,'0') = LPAD(TO_CHAR(rec_c.UNIMM),4,'0') 
                                    and (t.DAT_FIN = '31/12/9999' or t.dat_fin is null);
            EXCEPTION 
            WHEN 
            OTHERS THEN
                V_SUP_DA_TARSU := NULL;
            END;                            
            
            IF rec_c.sup_cat IS NOT NULL AND V_SUP_DA_TARSU IS NOT NULL THEN
                IF V_SUP_DA_TARSU > rec_c.sup_cat * 80 / 100 THEN
                    V_CHECK_C340 := 1;
                END IF;          
            END IF;
          
            update sit_rep_tarsu set sup_tarsu_cat= TO_CHAR(V_SUP_TARSU), F_C340 = V_CHECK_C340
                 where foglio = rec_c.foglio
                  and particella = rec_c.particella
                  and sub = rec_c.sub
                  and unimm = rec_c.unimm;
                  
                  
          exception when others then 
          dbms_output.put_line(rec_c.foglio||'/'||rec_c.particella||'/'||rec_c.sub||'/'||rec_c.unimm );
          errore:=substr(sqlerrm,1,255);
          dbms_output.put_line('Errore'||' '||errore);
          end;
       commit;
       end loop;
    end;
end;

procedure uiu_civ is
begin
    declare cursor c is select distinct pkid_uiu from sit_rep_tarsu;
    begin
        for rec_c in c
        loop
         declare errore varchar2(255byte);
          begin
              update sit_rep_tarsu r set uiu_civ = (
                select count(*) from siticivi_uiu
                where data_fine_val=to_date('99991231','yyyymmdd')
                and pkid_uiu = rec_c.pkid_uiu)
                where r.pkid_uiu=rec_c.pkid_uiu;
              exception when others then 
              dbms_output.put_line(rec_c.pkid_uiu);
              errore:=substr(sqlerrm,1,255);
              dbms_output.put_line('Errore'||' '||errore);
          end;
        commit;
        end loop;
    end;
end;

procedure res is
begin
    declare cursor c is select distinct pkid from sit_rep_tarsu;
    begin
        for rec_c in c
        loop
            declare 
            errore varchar2(255byte);
            conta number(3);
            begin
                select count(*) into conta   
                from j_sogg_cat_ana sca, sit_d_persona p
                where sca.id_dwh_a = rec_c.pkid
                and sca.id_dwh_b = p.id_ext
                and sca.rel_descr_a <> 'PI'
                and p.dt_fine_val is null
                and p.posiz_ana='A';

                update sit_rep_tarsu r set res = conta
                where r.pkid=rec_c.pkid;  

                exception when others then
                dbms_output.put_line(rec_c.pkid); 
                errore:=substr(sqlerrm,1,255);
                dbms_output.put_line('Errore'||' '||errore);
            end;
        commit;
        end loop;
    end;        
end;

procedure res_civ is
begin
    declare cursor c is select distinct pkid_uiu, pkid from sit_rep_tarsu where res>0;
    begin
        for rec_c in c
        loop
            declare 
            errore varchar2(255byte);
            begin
                update sit_rep_tarsu set res_civ =               
                     (select count(*) from j_civ_cat_ana
                          where id_dwh_a in                 
                                (select pkid_civi 
                                 from siticivi_uiu
                                 where pkid_uiu = rec_c.pkid_uiu 
                                   and data_fine_val = to_date ('99991231', 'yyyymmdd'))
                            and id_dwh_b in
                                 (select pc.id_ext_d_civico  
                                  from j_sogg_cat_ana sca, sit_d_persona_civico pc, sit_d_persona p
                                  where sca.id_dwh_a = rec_c.pkid  
                                    and sca.rel_descr_a <> 'PI' 
                                    and sca.id_dwh_b = pc.id_ext_d_persona  
                                    and pc.dt_fine_val is null
                                    and pc.id_ext_d_persona = p.id_ext
                                    and p.dt_fine_val is null
                                    and (p.posiz_ana = 'ISCRITTO NELL''A.P.R.' or p.posiz_ana ='A')))
                where pkid_uiu=rec_c.pkid_uiu
                  and pkid=rec_c.pkid; 
                exception when others then
                dbms_output.put_line(rec_c.pkid_uiu||'/'||rec_c.pkid); 
                errore:=substr(sqlerrm,1,255);
                dbms_output.put_line('Errore'||' '||errore);
            end;
        commit;
        end loop;
    end;        
end;

