    declare cursor c is select distinct pkid from sit_rep_tarsu;
    begin
        for rec_c in c
        loop
            declare errore varchar2(255byte);
            begin
             update sit_rep_tarsu r set tarsu_fam = 
             (select count(*)
              from j_sogg_ana_trib sct,  v_t_tar_sogg_all v , sit_t_tar_oggetto o
                        where  V.ID_EXT_OGG_RSU = O.ID_EXT
                        and O.DT_FINE_VAL is null
                        and  (o.dat_fin = '31/12/9999' or o.dat_fin is null)
                        and
                        sct.id_dwh_a = rec_c.pkid
                        and sct.id_dwh_b = v.id
                        and sct.id_dwh_a in 
                    (select pf1.id_ext_d_persona
                    from j_sogg_cat_ana sca, sit_d_pers_fam pf, sit_d_pers_fam pf1 
                        where sca.id_dwh_a = rec_c.pkid
                        and sca.id_dwh_b = pf.id_ext_d_persona
                        and pf.dt_fine_val is null
                        and pf.id_ext_d_famiglia = pf1.id_ext_d_famiglia
                        and pf1.dt_fine_val is null
                    minus --tolgo l'id del titolare   
                    select pf.id_ext_d_persona
                    from j_sogg_cat_ana sca, sit_d_pers_fam pf
                        where sca.id_dwh_a = rec_c.pkid
                        and sca.id_dwh_b = pf.id_ext_d_persona
                        and pf.dt_fine_val is null)
                )
              where pkid=rec_c.pkid;         
              exception when others then 
              dbms_output.put_line(rec_c.pkid);
              errore:=substr(sqlerrm,1,255);
              dbms_output.put_line('Errore'||' '||errore);
            end;    
        commit;
        end loop;
    end;
end; 

