end;   


procedure locatari is
begin
    declare cursor c is select distinct pkid from sit_rep_tarsu where locatore>0 ;
    begin
        for rec_c in c
        loop
            declare errore varchar2(255byte);
            begin
              update sit_rep_tarsu set locatari = 
                (select count(*) from(
                select distinct ufficio||anno||serie||numero||prog_soggetto from locazioni_b
                    where ufficio || anno || serie || numero in
                    (select distinct l.ufficio || l.anno || l.serie || l.numero
                      from j_sogg_cat_locazioni scl, locazioni_b l
                     where  scl.id_dwh_a = rec_c.pkid
                       and scl.id_dwh_b= l.ufficio || l.anno || l.serie || l.numero || l.prog_soggetto
                       and l.tipo_soggetto = 'D')
                    and tipo_soggetto='A'))
                    where pkid=rec_c.pkid;
              exception when others then 
              dbms_output.put_line(rec_c.pkid);
              errore:=substr(sqlerrm,1,255);
              dbms_output.put_line('Errore'||' '||errore);
            end;    
        commit;
        end loop;
    end;
end;


procedure locatari_tarsu is
begin
    declare cursor c is select distinct pkid from sit_rep_tarsu where locatore > 0;
    begin
        for rec_c in c
        loop
            declare errore varchar2(255byte);
            begin
              update sit_rep_tarsu set locatari_tarsu = 
                 (select count(*) 
                 from(
                            (select distinct slt.id_dwh_b from j_sogg_locazioni_trib slt,  v_t_tar_sogg_all v
                     where id_dwh_a in  
                        (select distinct ufficio||anno||serie||numero||prog_soggetto from locazioni_b
                          where ufficio || anno || serie || numero in
                          (select distinct l.ufficio || l.anno || l.serie || l.numero
                             from j_sogg_cat_locazioni scl, locazioni_b l
                            where  scl.id_dwh_a = rec_c.pkid
                              and scl.id_dwh_b= l.ufficio || l.anno || l.serie || l.numero || l.prog_soggetto
                              and l.tipo_soggetto = 'D')
                          and tipo_soggetto='A')
                       and slt.id_dwh_b = v.id
                            )
                        )
                  )
                    where pkid=rec_c.pkid;
              exception when others then 
              dbms_output.put_line(rec_c.pkid);
              errore:=substr(sqlerrm,1,255);
              dbms_output.put_line('Errore'||' '||errore);
            end;    
        commit;
        end loop;
    end;
end;

procedure altri_res_civ is
begin
    declare cursor c is select distinct pkid_uiu from sit_rep_tarsu where uiu_civ>0;
    begin
        for rec_c in c
        loop
            declare errore varchar2(255byte);
            begin
                update sit_rep_tarsu set altri_res_civ = 
                (select count(*) from sit_d_persona 
                 where dt_fine_val is null
                  and (posiz_ana = 'ISCRITTO NELL''A.P.R.' or posiz_ana ='A')
                  and id_ext in(
                    select id_ext_d_persona from sit_d_persona_civico pc
                     where dt_fine_val is null
                       and id_ext_d_civico in( 
                            select id_dwh_b from j_civ_cat_ana
                             where id_dwh_a in( 
                                select pkid_civi 
                                  from siticivi_uiu
                                 where pkid_uiu = rec_c.pkid_uiu
                                   and data_fine_val = to_date ('99991231', 'yyyymmdd')))))
                where pkid_uiu=rec_c.pkid_uiu;                 
              exception when others then 
              dbms_output.put_line(rec_c.pkid_uiu);
              errore:=substr(sqlerrm,1,255);
              dbms_output.put_line('Errore'||' '||errore);
            end;    
        commit;
        end loop;
    end;
end;   

procedure altri_res_tarsu is
begin
    declare cursor c is select distinct pkid_uiu from sit_rep_tarsu;
    begin
        for rec_c in c
        loop
            declare errore varchar2(255byte);
            begin
              update sit_rep_tarsu set altri_res_tarsu = 
                (select count(*) from j_sogg_ana_trib sat,  v_t_tar_sogg_all v , sit_t_tar_oggetto o
                    where sat.id_dwh_a in( 
                                                select id_ext_d_persona from sit_d_persona_civico pc
                                                 where pc.dt_fine_val is null
                                                   and pc.id_ext_d_civico in( 
                                                        select id_dwh_b from j_civ_cat_ana
                                                         where id_dwh_a in( 
                                                            select pkid_civi 
                                                              from siticivi_uiu
                                                             where pkid_uiu = rec_c.pkid_uiu 
                                                               and data_fine_val = to_date ('99991231', 'yyyymmdd'))))
                    and sat.id_dwh_b = v.id
                    and V.ID_EXT_OGG_RSU = O.ID_EXT
                    and O.DT_FINE_VAL is null
                    and  (o.dat_fin = '31/12/9999' or o.dat_fin is null)
                )
                where pkid_uiu=rec_c.pkid_uiu;
              exception when others then 
              dbms_output.put_line(rec_c.pkid_uiu);
              errore:=substr(sqlerrm,1,255);
              dbms_output.put_line('Errore'||' '||errore);
            end;    
        commit;
        end loop;
    end;
end;


end progetto_tarsu;
