DROP PACKAGE BODY DIOGENE_H501.UTIL;

CREATE OR REPLACE PACKAGE BODY DIOGENE_H501.UTIL
AS




PROCEDURE DROP_TABLE(TABELLA IN VARCHAR2)
IS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
                EXECUTE IMMEDIATE 'DROP TABLE ' || TABELLA;
END;


   /*
     *   PROCEDURA CHE SOSTITUISCE UNA TABELLA DEST , CON LA TABELLA SRC
     * LE TABELLE DEVONO AVERE UNA STESSA STRUTTURA
     * LA PROCEDURA COPIA INDICI E CONSTRAINTS DELLA TABELLA DEST SU SRC E POI RINOMINA SRC IN DEST
     *
     */
   PROCEDURE REVERT_TABLE_SRC_TO_DEST (P_SRC VARCHAR2, P_DEST VARCHAR2)
   AS
      l_ddl      VARCHAR2 (32000);
      v_drop     VARCHAR2 (5000);
      v_rename   VARCHAR2 (2000);

      V_DROP_CONSTR VARCHAR2 (5000);

      TYPE DDL_tab IS VARRAY (1000) OF VARCHAR2 (4000);

      ddls       DDL_tab := DDL_tab ();
      i          INTEGER := 1;
      dmsf       PLS_INTEGER;
   BEGIN
      ddls.EXTEND (1000);

      dmsf := DBMS_METADATA.session_transform;
      DBMS_METADATA.set_transform_param (dmsf, 'TABLESPACE', FALSE);
      DBMS_METADATA.set_transform_param (dmsf, 'STORAGE', FALSE);
      DBMS_METADATA.set_transform_param (dmsf, 'SEGMENT_ATTRIBUTES', FALSE);

      -- PRENDO TUTTI GLI INDICI DELLA TABELLA
      FOR trg IN (SELECT index_name
                    FROM user_indexes
                   WHERE table_name = P_DEST)
      LOOP
         IF INSTR (trg.index_name, 'SYS_') <> 1
         THEN
             l_ddl :=
                REPLACE (DBMS_METADATA.get_ddl ('INDEX', trg.index_name),
                         '."' || P_DEST || '"' ,
                         '."' || P_SRC || '"');

             DBMS_OUTPUT.put_line (l_ddl);
             ddls (i) := l_ddl;
             i := i + 1;
        END IF;
      END LOOP;


      -- PRENDO TUTTE LE CONSTRAINT DELLA TABELLA
      FOR trg IN (SELECT *
                    FROM USER_CONSTRAINTS
                   WHERE table_name = P_DEST)
      LOOP
         IF INSTR (trg.CONSTRAINT_NAME, 'SYS_') <> 1
         THEN
            l_ddl :=
               REPLACE (
                  DBMS_METADATA.get_ddl ('CONSTRAINT', trg.CONSTRAINT_NAME),
                  '."' ||  P_DEST || '"' ,
                   '."' ||  P_SRC || '"' );

          -- non serve V_DROP_CONSTR := 'alter table ' || P_SRC ||  ' drop constraint ' || trg.CONSTRAINT_NAME;
          -- EXECUTE IMMEDIATE  V_DROP_CONSTR;


            DBMS_OUTPUT.put_line (l_ddl);

            ddls (i) := l_ddl;
            i := i + 1;
         END IF;
      END LOOP;

      -- FACCIO LA DROP DELLA PRIMA TABELLA
      v_drop := 'DROP TABLE ' || P_DEST;

      EXECUTE IMMEDIATE v_drop;


      -- tolgo la pk, se presente sulla seconda
      BEGIN
          v_drop := 'alter table ' || P_SRC ||  ' drop primary key';
          EXECUTE IMMEDIATE v_drop;

     EXCEPTION
     WHEN OTHERS THEN
        NULL;
     END;
      --  ELIMINO TUTTTI GLI INDICI DALLA SECONDA (quelli creati nella classe it.webred.rulengine.brick.loadDwh.load.util.Util   )
      BEGIN
      FOR trg IN (SELECT index_name
                    FROM user_indexes
                   WHERE table_name = P_SRC)
      LOOP
         IF INSTR (trg.index_name, 'SYS_') <> 1
         THEN

              v_drop := 'DROP INDEX ' ||  trg.index_name ;
              EXECUTE IMMEDIATE v_drop;

        END IF;
      END LOOP;



     EXCEPTION
     WHEN OTHERS THEN
        NULL;
     END;
     -- CREO GLI INDICI E LE CONSTRAINTS SULLA SECONDA
      FOR elem IN 1 .. ddls.COUNT
      LOOP
         DECLARE
            v_sql   VARCHAR2 (4000);
         BEGIN
            v_sql := ddls (elem);

            IF v_sql IS NULL
            THEN
               EXIT WHEN v_sql IS NULL;
            END IF;

            DBMS_OUTPUT.put_line (elem || ': ' || v_sql);

            EXECUTE IMMEDIATE v_sql;
         EXCEPTION
            WHEN OTHERS
            THEN
               IF (SQLCODE = -1408 OR SQLCODE = -2260)
               THEN -- esiste gia un indice per questa lista di colonne -- TABELLA PUO CONTENERE SOLO UNA CHIAVE PRIMARIA
                  DBMS_OUTPUT.put_line (SQLCODE);
               ELSE
                  DBMS_OUTPUT.put_line (SQLCODE);
                  raise_application_error (-20000, SQLERRM || '-' || v_sql);
               END IF;
         END;
      END LOOP;


      -- RINOMINO LA SECONDA NELLA PRIMA
      v_rename := 'ALTER TABLE ' || P_SRC || '  RENAME TO ' || P_DEST;

      EXECUTE IMMEDIATE v_RENAME;
   /*

   */


   END;


   PROCEDURE SEQUENCE_MAN (TABNAME VARCHAR2, VALID NUMBER, RET OUT NUMBER)
   AS
      PRAGMA AUTONOMOUS_TRANSACTION;
      seq_name   VARCHAR2 (100);
      sqlstr     VARCHAR2 (255);
      lastn      NUMBER;
      diff       NUMBER;
   BEGIN
      seq_name := 'SEQ_' || tabname;

      BEGIN
         IF valid IS NOT NULL
         THEN
            -- CONTROLLO SE IL VALORE ICHE SI VUOLE INSERIRE IN ID
            -- E' MINORE DEL SEQUENCE
            SELECT last_number
              INTO lastn
              FROM user_sequences
             WHERE sequence_name = seq_name;

            IF lastn >= valid
            THEN
               -- NEL CASO SIA MINORE O UGUALE ALLORA NON INSERISCO IL VALID MA IL VALORE DEL SEQUENCE
               EXECUTE IMMEDIATE
                  'SELECT ' || seq_name || '.NEXTVAL FROM DUAL'
                  INTO ret;
            ELSE
               -- NEL CASO CHE VALID SIA MAGGIORE DEL VALORE CORRENTE DEL SEGUENCE
               -- ALLORA MODIFICO IL SEQUENCE, DANDOGLI L'ULTIMO VALORE QUELLO DI VALID
               diff := (valid - lastn) + 1;
               -- RIALLINEO IL SEQUENCE
               sqlstr :=
                     'ALTER SEQUENCE '
                  || seq_name
                  || ' INCREMENT BY '
                  || NVL (diff, 1);

               EXECUTE IMMEDIATE sqlstr;

               EXECUTE IMMEDIATE
                  'SELECT ' || seq_name || '.NEXTVAL FROM DUAL'
                  INTO ret;

               EXECUTE IMMEDIATE
                  'ALTER SEQUENCE ' || seq_name || ' INCREMENT BY 1';
            END IF;
         ELSE
            EXECUTE IMMEDIATE 'SELECT ' || seq_name || '.NEXTVAL FROM DUAL'
               INTO ret;
         END IF;

         COMMIT;
      EXCEPTION
         WHEN OTHERS
         THEN
            NULL;
      END;
   END;


   FUNCTION To_Number_All (n VARCHAR2)
      RETURN NUMBER
   IS
      num     NUMBER;
      num_v   VARCHAR2 (255);
   BEGIN
      BEGIN
         Num_v := REPLACE (N, ',', '.');
         num := TO_NUMBER (Num_v);
         RETURN num;
      EXCEPTION
         WHEN OTHERS
         THEN
            num := NULL;
      END;

      BEGIN
         Num_v := REPLACE (N, '.', ',');
         num := TO_NUMBER (Num_v);
         RETURN num;
      EXCEPTION
         WHEN OTHERS
         THEN
            num := NULL;
      END;

      RETURN num;
   END;

   FUNCTION substr_trim (stringa IN VARCHAR2, da INTEGER, aa INTEGER)
      RETURN VARCHAR2
   AS
   BEGIN
      RETURN TRIM (SUBSTR (stringa, da, aa));
   END;

   FUNCTION ANDN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a <> 0 AND b <> 0
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION TRIM (DEXPR IN VARCHAR2)
      RETURN VARCHAR2
   AS
   BEGIN
      RETURN LTRIM (RTRIM (dexpr));
   END;

   FUNCTION TIME_2
      RETURN CHAR
   AS
      convdate   CHAR (8);
   BEGIN
      convdate := TO_CHAR (SYSDATE, 'hh24:mi:ss');
      RETURN (convdate);
   END;

   FUNCTION TIME_1 (DEXPR IN DATE)
      RETURN CHAR
   AS
      convdate   CHAR (8);
   BEGIN
      convdate := TO_CHAR (dexpr, 'hh24:mi:ss');
      RETURN (convdate);
   END;

   FUNCTION SPACE_ (LEN IN NUMBER)
      RETURN VARCHAR2
   AS
      dstr   VARCHAR2 (32767);
   BEGIN
      dstr := LPAD (' ', len, ' ');
      RETURN (dstr);
   END;

   FUNCTION RND
      RETURN NUMBER
   AS
      m    CONSTANT NUMBER := 100000000;
      m1   CONSTANT NUMBER := 10000;
      b    CONSTANT NUMBER := 31415821;
      a             NUMBER;
      the_date      DATE;
      days          NUMBER;
      secs          NUMBER;
      imul          NUMBER;
      p1            NUMBER;
      p0            NUMBER;
      q1            NUMBER;
      q0            NUMBER;
   BEGIN
      the_date := SYSDATE;
      days := TO_NUMBER (TO_CHAR (the_date, 'J'));
      secs := TO_NUMBER (TO_CHAR (the_date, 'SSSSS'));
      a := days * 24 * 3600 + secs;
      p1 := TRUNC (a / m1);
      p0 := MOD (a, m1);
      q1 := TRUNC (b / m1);
      q0 := MOD (b, m1);
      imul := (MOD ( (MOD (p0 * q1 + p1 * q0, m1) * m1 + p0 * q0), m));
      a := MOD (imul + 1, m);
      RETURN (a / m);
   END;

   FUNCTION RIGHT (SRCSTR IN VARCHAR2, LEN IN INTEGER)
      RETURN VARCHAR2
   AS
      dstr   VARCHAR2 (32767);
   BEGIN
      IF (len >= LENGTH (srcstr))
      THEN
         RETURN (srcstr);
      END IF;

      dstr := SUBSTR (srcstr, LENGTH (srcstr) - len + 1, len);
      RETURN (dstr);
   END;

   FUNCTION ORN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a <> 0 OR b <> 0
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION NOTN (A NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a = 0
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION NOTEQN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a <> b
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION MID (SRCSTR   IN VARCHAR2,
                 STRT     IN INTEGER,
                 LEN      IN NUMBER DEFAULT 32767)
      RETURN VARCHAR2
   AS
      dstr   VARCHAR2 (32767);
   BEGIN
      IF (strt > LENGTH (srcstr))
      THEN
         RETURN (NULL);
      END IF;

      dstr := SUBSTR (srcstr, strt, len);
      RETURN (dstr);
   END;

   FUNCTION LTN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a < b
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION LTEN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a <= b
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION LEFT (SRCSTR IN VARCHAR2, LEN IN INTEGER)
      RETURN VARCHAR2
   AS
      dstr   VARCHAR2 (32767);
   BEGIN
      dstr := SUBSTR (srcstr, 1, len);
      RETURN (dstr);
   END;

   FUNCTION IS_NUMBER (IN_VAR IN VARCHAR2)
      RETURN NUMBER
   AS
      v_number   NUMBER;
   BEGIN
      SELECT TO_NUMBER (in_var) INTO v_number FROM DUAL;

      RETURN 0;                                                 -- è un numero
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN 1;                                          -- non è un numero
   END;

   FUNCTION ISN (A IN NUMBER, B IN VARCHAR2)
      RETURN NUMBER
   AS
      OUT   NUMBER;
   BEGIN
      IF (LOWER (b) = LOWER ('NULL'))
      THEN
         IF (a IS NULL)
         THEN
            RETURN -1;
         ELSE
            RETURN 0;
         END IF;
      ELSE
         IF (a IS NOT NULL)
         THEN
            RETURN -1;
         ELSE
            RETURN 0;
         END IF;
      END IF;
   END;

   FUNCTION INTN (EXPN IN NUMBER)
      RETURN NUMBER
   AS
      convnum   NUMBER;
   BEGIN
      IF expn >= 0
      THEN
         convnum := TRUNC (expn);
      ELSE
         convnum := FLOOR (expn);
      END IF;

      RETURN (convnum);
   END;

   FUNCTION INTDIV (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
      OUT   NUMBER;
   BEGIN
      IF (a IS NULL) OR (b IS NULL)
      THEN
         RETURN NULL;
      ELSE
         OUT := TRUNC (ROUND (a) / ROUND (b));
         RETURN OUT;
      END IF;
   END;

   FUNCTION GTN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a > b
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION GTEN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a >= b
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION FCHAR_TO_DATE (P_CHAR VARCHAR2, P_FORMAT VARCHAR2)
      RETURN DATE
   AS
   BEGIN
      RETURN TO_DATE (p_char, p_format);
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN DATECONV (P_CHAR);
   END fchar_to_date;

   FUNCTION EQN (A NUMBER, B NUMBER)
      RETURN NUMBER
   AS
   BEGIN
      IF a = b
      THEN
         RETURN -1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION DATECONV (P_ENTEREDTEXT VARCHAR2)
      RETURN DATE
   AS
      TYPE t_varchartable IS TABLE OF VARCHAR2 (50)
                                INDEX BY BINARY_INTEGER;

      v_dateformats      t_varchartable;
      v_converted        DATE;
      v_validdate        DATE;
      v_converted_temp   VARCHAR2 (10);
   BEGIN
      /* setup dateformats to check
         * can be expanded freely
         */
      v_dateformats (1) := 'YYYYMMDD';
      v_dateformats (2) := 'DD/MM/YYYY';
      v_validdate := NULL;

      FOR v_index IN 1 .. v_dateformats.COUNT
      LOOP
         BEGIN
            v_converted := NULL;         -- clear field of previous conversion
            v_converted_temp := p_enteredtext;

            IF v_dateformats (v_index) = v_dateformats (1)
            THEN
               IF SUBSTR (v_converted_temp, 5, 2) = '00'
               THEN
                  v_converted_temp :=
                        SUBSTR (p_enteredtext, 1, 4)
                     || '01'
                     || SUBSTR (v_converted_temp, -2);
               END IF;

               IF SUBSTR (v_converted_temp, -2) = '00'
               THEN
                  v_converted_temp := SUBSTR (v_converted_temp, 1, 6) || '01';
               END IF;
            END IF;

            IF v_dateformats (v_index) = v_dateformats (2)
            THEN
               IF SUBSTR (v_converted_temp, 1, 2) = '00'
               THEN
                  v_converted_temp := '01' || SUBSTR (p_enteredtext, 3, 8);
               END IF;

               IF SUBSTR (v_converted_temp, 4, 2) = '00'
               THEN
                  v_converted_temp :=
                        SUBSTR (v_converted_temp, 1, 3)
                     || '01'
                     || SUBSTR (v_converted_temp, 6, 5);
               END IF;
            END IF;

            /*
             * try to convert date using specific date format, on error
             * loop will continue without raising error
             */
            v_converted := TO_DATE (v_converted_temp, v_dateformats (v_index));
         EXCEPTION
            WHEN OTHERS
            THEN
               NULL;                       -- conversion failed, just continue
         END;

         IF NOT v_converted IS NULL
         THEN                                             -- is date converted
            IF NVL (v_validdate, v_converted) = v_converted
            THEN
               /* date is valid */
               v_validdate := v_converted;
            END IF;
         END IF;
      END LOOP;

      RETURN v_validdate;
   END;

   FUNCTION DATEADD (INTVL IN VARCHAR2, NINTVL IN NUMBER, DEXPR IN DATE)
      RETURN DATE
   AS
      convdate   DATE;
   BEGIN
      IF    LOWER (RTRIM (intvl)) = 'y'
         OR LOWER (RTRIM (intvl)) = 'w'
         OR LOWER (RTRIM (intvl)) = 'd'
      THEN
         convdate := dexpr + nintvl;
         RETURN (convdate);
      ELSIF LOWER (RTRIM (intvl)) = 'm'
      THEN
         convdate := ADD_MONTHS (dexpr, nintvl);
         RETURN (convdate);
      ELSIF LOWER (RTRIM (intvl)) = 'q'
      THEN
         convdate := ADD_MONTHS (dexpr, 3 * nintvl);
         RETURN (convdate);
      ELSIF LOWER (RTRIM (intvl)) = 'ww'
      THEN
         convdate := dexpr + 7 * nintvl;
         RETURN (convdate);
      ELSIF LOWER (RTRIM (intvl)) = 'h'
      THEN
         convdate := dexpr + nintvl / 24;
         RETURN (convdate);
      ELSIF LOWER (RTRIM (intvl)) = 'n'
      THEN
         convdate := dexpr + nintvl / 1440;
         RETURN (convdate);
      ELSIF LOWER (RTRIM (intvl)) = 's'
      THEN
         convdate := dexpr + nintvl / 86400;
         RETURN (convdate);
      ELSIF LOWER (RTRIM (intvl)) = 'yyyy'
      THEN
         IF TRUNC (nintvl) = nintvl
         THEN
            convdate := ADD_MONTHS (dexpr, nintvl * 12);
            RETURN (convdate);
         ELSE
            convdate := dexpr + nintvl * 365;
            RETURN (convdate);
         END IF;
      END IF;
   END;
END UTIL;
/


DROP PACKAGE BODY DIOGENE_H501.UTIL_UNATANTUM;

CREATE OR REPLACE PACKAGE BODY DIOGENE_H501.UTIL_UNATANTUM AS
/******************************************************************************
   NAME:       UTIL_UNATANTUM
   PURPOSE:

   REVISIONS:
   Ver        Date        Author           Description
   ---------  ----------  ---------------  ------------------------------------
   1.0        18/11/2011      Utente       1. Created this package body.
******************************************************************************/


/*
La procedura permette di accorpare i soggetti_unici CHE HANNO STESSA DEOMINAZIOEN E PI ='00000000000'
ipotizzando che siano lo stesso soggetto.
GENARIO (alla v. 15.0. di GIT non effetua infatti questo accorpamento) , una modifica è stata prevista al prodotto.
*/
PROCEDURE UNIONSOGG_PIZERO_DENOMUGUALE IS


            CURSOR C IS
            -- prima si accorpa quelli che hanno CRF nullo con quelli che hanno cf non null
            SELECT * FROM
            (
            select U.ID_SOGGETTO ID_SOGGETTO_OLD, U.DENOMINAZIONE,
            (SELECT ID_SOGGETTO FROM sit_soggetto_unico UU WHERE
            UU.PI = U.pi
            and UU.DENOMINAZIONE = U.DENOMINAZIONE  AND ROWNUM <= 1  and (Uu.codfisc is not null OR UU.COGNOME IS NOT NULL OR UU.NOME IS NOT NULL) ) ID_SOGGETTO
            from  sit_soggetto_unico u
            where u.pi ='00000000000' and u.cognome is null and u.nome is null and u.codfisc is null
            and u.denominazione is not null
            )
            WHERE ID_SOGGETTO_OLD <> ID_SOGGETTO;


            ID_SOGG NUMBER(10);

            BEGIN

            FOR REC_C IN C LOOP
                -- aggiorno i totali con il nuovo id_soggetto
                ID_SOGG:= REC_C.ID_SOGGETTO;
                UPDATE SIT_SOGGETTO_TOTALE SET FK_SOGGETTO = ID_SOGG
                WHERE FK_SOGGETTO = REC_C.ID_SOGGETTO_OLD;



            END LOOP;

            COMMIT;

            -- cancello tutti gli unici rimasti orfani
            DELETE FROM SIT_SOGGETTO_UNICO WHERE NOT EXISTS
            (SELECT 1 FROM SIT_SOGGETTO_TOTALE WHERE ID_SOGGETTO =  FK_SOGGETTO);


            COMMIT;

END;


END UTIL_UNATANTUM;
/

