 PROCEDURE ETL_UTENTI_UFFICI_SETTORI is
 begin


        DELETE FROM AR_V_UTENTI_UFFICI_SETTORI
        WHERE ZONA_SOCIALE = (SELECT NOME FROM CS_O_ZONA_SOC WHERE ABILITATO = '1');

        INSERT INTO AR_V_UTENTI_UFFICI_SETTORI
        SELECT * FROM V_UTENTI_UFFICI_SETTORI;

        COMMIT;

 end;

  PROCEDURE ETL_INDIRIZZI_ZONE is
 begin

        DELETE FROM AR_V_INDIRIZZI_ZONE  A
        WHERE NOT EXISTS
        ( SELECT 1 FROM V_AR_V_INDIRIZZI_ZONE B
        WHERE  A.ZONA_SOC = B. ZONA_SOC
        AND A.INDIRIZZO_HASH = B.INDIRIZZO_HASH
        ) and A.ZONA_SOC=(select nome from cs_o_zona_soc WHERE ABILITATO = '1') ;

        MERGE INTO AR_V_INDIRIZZI_ZONE TA
        USING (SELECT * FROM V_AR_V_INDIRIZZI_ZONE) T
        ON (TA.INDIRIZZO_HASH = T.INDIRIZZO_HASH AND TA.ZONA_SOC= T.ZONA_SOC)
        WHEN NOT MATCHED THEN
        INSERT (ZONA_SOC  , CODICE_VIA   ,INDIRIZZO    ,CIVICO_NUMERO    ,COMUNE_DES   ,COMUNE_COD   ,STATO_COD   ,PROV_SIGLA   ,STATO_DES   ,INDIRIZZO_HASH   ,INDIRIZZO_ESTESO   ,TIMESTAMP )
        VALUES (T.ZONA_SOC,
                T.CODICE_VIA   ,
                T.INDIRIZZO    ,
                T.CIVICO_NUMERO    ,
                T.COMUNE_DES   ,
                T.COMUNE_COD   ,
                T.STATO_COD   ,
                T.PROV_SIGLA   ,
                T.STATO_DES   ,
                T.INDIRIZZO_HASH   ,
                T.INDIRIZZO_ESTESO   ,
                SYSDATE);


        COMMIT;



 end;

 end;
/


