        WHERE Z_ZONA_SOCIALE = (SELECT NOME FROM CS_O_ZONA_SOC WHERE ABILITATO = 1 AND FLG_DEL_ARGOBI= 1);

        INSERT INTO ARBI_T7_PAI_AFFIDO
        SELECT * FROM V_T7_PAI_AFFIDO;
        
        DELETE FROM ARBI_V_CS_UNITA_CRISI
        WHERE ZONA_SOCIALE = (SELECT NOME FROM CS_O_ZONA_SOC WHERE ABILITATO = 1 AND FLG_DEL_ARGOBI= 1);

        INSERT INTO ARBI_V_CS_UNITA_CRISI
        SELECT * FROM V_CS_UNITA_CRISI;

         DELETE FROM ARBI_V_TAB_ACCESSI_INT_CUST
        WHERE ZONA_SOCIALE = (SELECT NOME FROM CS_O_ZONA_SOC WHERE ABILITATO = 1 AND FLG_DEL_ARGOBI= 1);

        INSERT INTO  ARBI_V_TAB_ACCESSI_INT_CUST
        SELECT * FROM V_TAB_ACCESSI_INT_CUST;

        DELETE FROM ARBI_V_INT_CUST_JSON
        WHERE ZONA_SOC = (SELECT NOME FROM CS_O_ZONA_SOC WHERE ABILITATO = 1 AND FLG_DEL_ARGOBI= 1);

        INSERT INTO ARBI_V_INT_CUST_JSON
        SELECT * FROM V_INT_CUST_JSON;    

        DELETE FROM ARBI_V_MONITORAGGIO M
        WHERE M."ZONA SOCIALE" = (SELECT NOME FROM CS_O_ZONA_SOC WHERE ABILITATO = 1 AND FLG_DEL_ARGOBI= 1);

        INSERT INTO ARBI_V_MONITORAGGIO
        SELECT * FROM V_MONITORAGGIO; 
        
        DELETE FROM ARBI_V_INDIRIZZI_CASO M
        WHERE M.ZONA_SOCIALE = (SELECT NOME FROM CS_O_ZONA_SOC WHERE ABILITATO = 1 AND FLG_DEL_ARGOBI= 1);

        INSERT INTO ARBI_V_INDIRIZZI_CASO
        SELECT * FROM V_INDIRIZZI_CASO;

        COMMIT;



 end;
end;
/


DROP PACKAGE BODY CS_ROMA.INDIRIZZI_UTIL;

CREATE OR REPLACE PACKAGE BODY CS_ROMA.INDIRIZZI_UTIL Is

Function gethash_raw (p_raw In Raw) Return Raw As Language Java Name 'Sha1.GetHash(byte[]) return byte[]';

Function gethash(INDIRIZZO In Varchar2 , CIVICO In Varchar2, COMUNE_DES In Varchar2,  PROV_SIGLA In Varchar2, NAZIONE_DES In Varchar2 ) Return a_b Is
Begin

DECLARE
    V_CIVICO VARCHAR2(4000);
    V_COMUNE_DES VARCHAR2(4000);
    V_PROV_SIGLA VARCHAR2(4000);
    V_NAZIONE_DES VARCHAR2(4000);
    ret a_b := a_b(null,null);
BEGIN
    SELECT DECODE(civico, NULL, NULL, ', ' || civico ) INTO V_CIVICO FROM DUAL;

    SELECT DECODE(COMUNE_DES,NULL,NULL, ', ' || COMUNE_DES  ) INTO V_COMUNE_DES FROM DUAL;

    SELECT DECODE(PROV_SIGLA, NULL,NULL, ', ' || PROV_SIGLA ) INTO V_PROV_SIGLA FROM DUAL;

    SELECT DECODE(NAZIONE_DES, 'ITALIA',NULL, null, null, ', ' || NAZIONE_DES ) INTO V_NAZIONE_DES FROM DUAL;


    ret.a := RawToHex(gethash_raw(Utl_Raw.Cast_To_Raw(nvl(INDIRIZZO,'-') || nvl(V_CIVICO,'-') ||  nvl(V_COMUNE_DES,'-') || nvl(V_PROV_SIGLA,'-') || nvl(V_NAZIONE_DES,'-'))));
    ret.b := INDIRIZZO || V_CIVICO || V_COMUNE_DES || V_PROV_SIGLA || V_NAZIONE_DES;

    return ret;

END;

End gethash;

End INDIRIZZI_UTIL;
/


DROP PACKAGE BODY CS_ROMA.PROC_REFRESH;

CREATE OR REPLACE PACKAGE BODY CS_ROMA.PROC_REFRESH AS
  PROCEDURE REFRESH_ORGANIZZAZIONE_CF IS
  BEGIN

  update cs_o_organizzazione SET CF = (SELECT CF FROM AM_TAB_COMUNI_INDICEPA WHERE CODICE = COD_CATASTALE) where CF IS NULL;

  COMMIT;
  END;

  PROCEDURE REFRESH_SETT_CSOC_ESCLUSIVA IS
  BEGIN

    MERGE into CS_REL_SETT_CATSOC_ESCLUSIVA esc using
    (select REL.CATEGORIA_SOCIALE_ID, REL.SETTORE_ID, (select ID from CS_TB_TIPO_DIARIO WHERE descrizione = 'Dati Scuola') diario_id
    from CS_REL_SETTORE_CATSOC rel, CS_O_SETTORE sett
    where REL.CATEGORIA_SOCIALE_ID=1 AND sett.id = REL.SETTORE_ID) INS
    ON (INS.CATEGORIA_SOCIALE_ID=ESC.SCS_CATEGORIA_SOCIALE_ID AND ins.SETTORE_ID=ESC.SCS_SETTORE_ID and ins.diario_id=ESC.TIPO_DIARIO_ID)
    WHEN NOT MATCHED THEN INSERT (SCS_CATEGORIA_SOCIALE_ID, SCS_SETTORE_ID,TIPO_DIARIO_ID, ABILITATO, DT_INS, USER_INS)
    VALUES (ins.CATEGORIA_SOCIALE_ID, ins.SETTORE_ID,ins.diario_id, 1, sysdate, '');

    MERGE into CS_REL_SETT_CATSOC_ESCLUSIVA esc using
    (select REL.CATEGORIA_SOCIALE_ID, REL.SETTORE_ID, (select ID from CS_TB_TIPO_DIARIO WHERE descrizione = 'Valutazione S.In.Ba.') diario_id
   from CS_REL_SETTORE_CATSOC rel, CS_O_SETTORE sett
    where REL.CATEGORIA_SOCIALE_ID=1 AND sett.id = REL.SETTORE_ID) INS
    ON (INS.CATEGORIA_SOCIALE_ID=ESC.SCS_CATEGORIA_SOCIALE_ID AND ins.SETTORE_ID=ESC.SCS_SETTORE_ID and ins.diario_id=ESC.TIPO_DIARIO_ID)
    WHEN NOT MATCHED THEN INSERT (SCS_CATEGORIA_SOCIALE_ID, SCS_SETTORE_ID,TIPO_DIARIO_ID, ABILITATO, DT_INS, USER_INS)
    VALUES (ins.CATEGORIA_SOCIALE_ID, ins.SETTORE_ID,ins.diario_id, 1, sysdate, 'SISO-777');

    -- Anziani e disabili
    merge into CS_REL_SETT_CATSOC_ESCLUSIVA esc using
    (select REL.CATEGORIA_SOCIALE_ID, REL.SETTORE_ID, (select ID from CS_TB_TIPO_DIARIO WHERE upper(descrizione) like '%MULTIDIMENSIONALE%') diario_id
    from CS_REL_SETTORE_CATSOC rel, CS_O_SETTORE sett
    where REL.CATEGORIA_SOCIALE_ID IN (2,4) AND sett.id = REL.SETTORE_ID) INS
    ON (INS.CATEGORIA_SOCIALE_ID=ESC.SCS_CATEGORIA_SOCIALE_ID AND ins.SETTORE_ID=ESC.SCS_SETTORE_ID and ins.diario_id=ESC.TIPO_DIARIO_ID)
    WHEN NOT MATCHED THEN INSERT (SCS_CATEGORIA_SOCIALE_ID, SCS_SETTORE_ID,TIPO_DIARIO_ID, ABILITATO, DT_INS, USER_INS)
    VALUES (ins.CATEGORIA_SOCIALE_ID, ins.SETTORE_ID,ins.diario_id, 1, sysdate, 'SISO-739');

    MERGE into CS_REL_SETT_CATSOC_ESCLUSIVA esc using
    (select REL.CATEGORIA_SOCIALE_ID, REL.SETTORE_ID, (select ID from CS_TB_TIPO_DIARIO WHERE descrizione = 'Provvedimenti Tribunale') diario_id
    from CS_REL_SETTORE_CATSOC rel, CS_O_SETTORE sett
    where REL.CATEGORIA_SOCIALE_ID=1 AND sett.id = REL.SETTORE_ID) INS
    ON (INS.CATEGORIA_SOCIALE_ID=ESC.SCS_CATEGORIA_SOCIALE_ID AND ins.SETTORE_ID=ESC.SCS_SETTORE_ID and ins.diario_id=ESC.TIPO_DIARIO_ID)
    WHEN NOT MATCHED THEN INSERT (SCS_CATEGORIA_SOCIALE_ID, SCS_SETTORE_ID,TIPO_DIARIO_ID, ABILITATO, DT_INS, USER_INS)
    VALUES (ins.CATEGORIA_SOCIALE_ID, ins.SETTORE_ID,ins.diario_id, 1, sysdate, '');

    COMMIT;


  END;

