 PROCEDURE REFRESH_TIPO_INTERVENTO is
 begin

        execute immediate 'alter table CS_CFG_INT_ESEG_ATT_UM disable constraint CS_CFGINT_ESEGATTUM_STINT_FK';
        execute immediate 'alter table cs_cfg_int_eseg_stato_int disable constraint CS_CFG_INTESEGSTATO_INTESEG_FK';
        execute immediate 'alter table cs_cfg_int_eseg disable constraint cs_cfg_int_eseg_tipoint_fk';
        execute immediate 'alter table cs_rel_catsoc_tipo_inter disable constraint cs_rel_catsoc_ti_tipoint_fk';
        execute immediate 'alter table cs_rel_relazione_tipoint disable constraint cs_rel_reltipoint_tintfk';
        execute immediate 'alter table CS_I_INTERVENTO_ESEG_MAST disable constraint INTER_ESEG_MAST_TIPOINTER_FK';
        execute immediate 'alter table CS_CFG_INT_PR_FORM disable constraint CS_C_INTPRDETT_TIPOINTER_FK';
        execute immediate 'alter table CS_REL_MACROINT_TIPOINT disable constraint CS_REL_MACROINT_INTFK';

        DBMS_MVIEW.REFRESH(LIST=>'CS_C_TIPO_INTERVENTO');

        --Ripulisco le tabelle di configurazione
        DELETE FROM CS_REL_SETT_CSOC_TIPO_INTER WHERE CSTI_TIPO_INTERVENTO_ID NOT IN (SELECT ID FROM CS_C_TIPO_INTERVENTO);
        DELETE FROM CS_REL_CATSOC_TIPO_INTER WHERE TIPO_INTERVENTO_ID NOT IN (SELECT ID FROM CS_C_TIPO_INTERVENTO);
        DELETE FROM CS_CFG_INT_ESEG where tipo_intervento_id not in (select id from cs_c_tipo_intervento);
        DELETE FROM CS_CFG_INT_ESEG_STATO_INT where CFG_INT_ESEG_ID NOT IN (SELECT ID FROM CS_CFG_INT_ESEG);
        DELETE FROM CS_CFG_INT_ESEG_ATT_UM WHERE CFG_INT_ESEG_STATO_INT_ID NOT IN (SELECT ID FROM CS_CFG_INT_ESEG_STATO_INT);
        DELETE FROM CS_REL_MACROINT_TIPOINT WHERE TIPO_INTERVENTO_ID NOT IN (SELECT ID FROM CS_C_TIPO_INTERVENTO);

        execute immediate 'alter table CS_CFG_INT_ESEG_ATT_UM enable constraint CS_CFGINT_ESEGATTUM_STINT_FK';
        execute immediate 'alter table cs_cfg_int_eseg_stato_int enable constraint CS_CFG_INTESEGSTATO_INTESEG_FK';
        execute immediate 'alter table cs_cfg_int_eseg enable constraint cs_cfg_int_eseg_tipoint_fk';
        execute immediate 'alter table cs_rel_catsoc_tipo_inter enable constraint cs_rel_catsoc_ti_tipoint_fk';
        execute immediate 'alter table cs_rel_relazione_tipoint enable constraint cs_rel_reltipoint_tintfk';
        execute immediate 'alter table CS_I_INTERVENTO_ESEG_MAST ENABLE constraint INTER_ESEG_MAST_TIPOINTER_FK';
        execute immediate 'alter table CS_CFG_INT_PR_FORM ENABLE constraint CS_C_INTPRDETT_TIPOINTER_FK';
        execute immediate 'alter table CS_REL_MACROINT_TIPOINT ENABLE constraint CS_REL_MACROINT_INTFK';


        insert into CS_CFG_INT_ESEG
        (
        select sq_id.nextval, id from cs_c_tipo_intervento
        where id not in ( select tipo_intervento_id from CS_CFG_INT_ESEG)
        );

        -- COLLEGAMENTO TIPO INTERVENTOALLE CATEGORIE SOCIALI
        MERGE INTO CS_REL_CATSOC_TIPO_INTER csti
        USING
        (
        SELECT CS.ID cs_id , TI.ID ti_id FROM CS_C_CATEGORIA_SOCIALE CS,  CS_C_TIPO_INTERVENTO TI
        where cs.descrizione in ('Famiglia e Minori','Disabili','Dipendenze','Anziani','Immigrati e nomadi','Povertà, disagio adulti e senza dimora')
        ) s
        on (csti.categoria_sociale_id = s.cs_id and csti.tipo_intervento_id = s.ti_id )
        WHEN NOT MATCHED THEN INSERT (categoria_sociale_id, tipo_intervento_id, ABILITATO, USER_INS,DT_INS)
        VALUES (S.CS_ID, S.TI_ID, '1' ,  'MV_REFRESH_TIPO_INTERVENTO' , SYSDATE) ;

        -- COLLEGAMENTO AL SETTORE / CATEGORIA SOCIALE DEI TIPI INTERVENTO COSI COME DA GERARCHIA SERVIZI ISTAT
        insert into cs_rel_sett_csoc_tipo_inter (
        SCS_SETTORE_ID,
        CSTI_TIPO_INTERVENTO_ID,
        SCS_CATEGORIA_SOCIALE_ID,
        abilitato,
        USER_INS,
        DT_INS)
        SELECT SETTORE_ID,INTERVENTO_ID,CATEGORIA_SOCIALE_ID,1,'script',SYSDATE
        FROM V_SETT_CATSOC_TIPOINT s
        WHERE not exists
        (
        select 1 from cs_rel_sett_csoc_tipo_inter inter
        where csti_tipo_intervento_id = S.INTERVENTO_ID
        and S.SETTORE_ID = INTER.SCS_SETTORE_ID
        and INTER.SCS_CATEGORIA_SOCIALE_ID =  S.categoria_sociale_id
        ) and ORIGINE_DATO = 'ARGO'
        and categoria_sociale_descr <> 'Multiutenza';

       
       
       ----Minori Struttura devo eliminare per i settori con il 2 livello EQUIPE gli insterventi che non sono relativi all'inserimento
     -----in struttura
        DELETE FROM cs_rel_sett_csoc_tipo_inter c
	      WHERE SCS_SETTORE_ID IN (   
	           SELECT cos2.ID 
	           FROM CS_O_SETTORE cos2 INNER JOIN CS_TB_SECONDO_LIVELLO ctsl 
	            ON cos2.ID_SECONDO_LIVELLO = ctsl.ID 
	           WHERE ctsl.DESCRIZIONE ='Equipe Minori')
	       AND c.CSTI_TIPO_INTERVENTO_ID NOT IN(SELECT ID FROM CS_C_TIPO_INTERVENTO WHERE DESCRIZIONE ='Strutture residenziali');
	       
       
        -- stato Pausa
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id, (select id from CS_CFG_INT_ESEG_STATO where nome ='Disattivazione temporanea'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Disattivazione temporanea'
        );

         insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id, (select id from CS_CFG_INT_ESEG_STATO where nome ='Riattivazione'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Riattivazione'
        );


        --
        -- Vado a collegare i 5 stati standard ai vari tipi intervento
        --
        -- stato Avvio
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id, (select id from CS_CFG_INT_ESEG_STATO where nome ='Avvio'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Avvio'
        );

        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id, (select id from CS_CFG_INT_ESEG_STATO where nome ='Respinto/Non ammesso'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Respinto/Non ammesso'
        );

        -- stato Erogazione
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id, (select id from CS_CFG_INT_ESEG_STATO where nome ='Erogazione'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Erogazione'
        );

        -- stato Ritirato durante servizio (SISO-888) - duplica configurazione dello stato CHIUSURA
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id,  (select id from CS_CFG_INT_ESEG_STATO where nome ='Ritirato durante servizio'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Ritirato durante servizio'
        );

        -- stato Ritirato prima di iniziare (SISO-888) - duplica configurazione dello stato CHIUSURA
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id,  (select id from CS_CFG_INT_ESEG_STATO where nome ='Ritirato prima di iniziare'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Ritirato prima di iniziare'
        );

        -- stato Stop
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id,  (select id from CS_CFG_INT_ESEG_STATO where nome ='Chiusura'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Chiusura'
        );

        -- Erogazione e Chiusura
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id,  (select id from CS_CFG_INT_ESEG_STATO where nome ='Erogazione e Chiusura'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Erogazione e Chiusura'
        );

        -- Mancata Erogazione
        insert into CS_CFG_INT_ESEG_STATO_INT
        select sq_id.nextval , id,  (select id from CS_CFG_INT_ESEG_STATO where nome ='Mancata Erogazione'), 0  from cs_cfg_int_eseg  ie
        where not exists
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO_INT si, CS_CFG_INT_ESEG_STATO s
        where s.id = SI.STATO_ID
        and si.cfg_int_eseg_id =  ie.id
        and S.NOME = 'Mancata Erogazione'
        );


        --SCOLLEGO ALCUNI STATI STANDARD DA ALCUNI DEI SERVIZI IN QUANTO HANNO
        -- DEI PROPRI STATI NON STANDARD
        DELETE FROM CS_CFG_INT_ESEG_STATO_INT SI
        WHERE EXISTS
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO s, CS_CFG_INT_ESEG IE
        where s.id = SI.STATO_ID
        AND STATO_ID = (select id from CS_CFG_INT_ESEG_STATO where nome ='Erogazione')
        and S.NOME = 'Erogazione'
        AND IE.ID = SI.CFG_INT_ESEG_ID
        AND IE.TIPO_INTERVENTO_ID IN (77,139,133,134,135,136,137,138));


        DELETE FROM CS_CFG_INT_ESEG_STATO_INT SI
        WHERE EXISTS
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO s, CS_CFG_INT_ESEG IE
        where s.id = SI.STATO_ID
        AND STATO_ID = (select id from CS_CFG_INT_ESEG_STATO where nome ='Chiusura')
        and S.NOME = 'Chiusura'
        AND IE.ID = SI.CFG_INT_ESEG_ID
        AND IE.TIPO_INTERVENTO_ID IN (77,139,133,134,135,136,137,138));

         -- stato Ritirato durante servizio (SISO-888) - duplica configurazione dello stato CHIUSURA
        DELETE FROM CS_CFG_INT_ESEG_STATO_INT SI
        WHERE EXISTS
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO s, CS_CFG_INT_ESEG IE
        where s.id = SI.STATO_ID
        AND STATO_ID = (select id from CS_CFG_INT_ESEG_STATO where nome ='Ritirato durante servizio')
        and S.NOME = 'Ritirato durante servizio'
        AND IE.ID = SI.CFG_INT_ESEG_ID
        AND IE.TIPO_INTERVENTO_ID IN (77,139,133,134,135,136,137,138));

        -- stato Ritirato prima di iniziare (SISO-888) - duplica configurazione dello stato CHIUSURA
        DELETE FROM CS_CFG_INT_ESEG_STATO_INT SI
        WHERE EXISTS
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO s, CS_CFG_INT_ESEG IE
        where s.id = SI.STATO_ID
        AND STATO_ID = (select id from CS_CFG_INT_ESEG_STATO where nome ='Ritirato prima di iniziare')
        and S.NOME = 'Ritirato prima di iniziare'
        AND IE.ID = SI.CFG_INT_ESEG_ID
        AND IE.TIPO_INTERVENTO_ID IN (77,139,133,134,135,136,137,138));

        DELETE FROM CS_CFG_INT_ESEG_STATO_INT SI
        WHERE EXISTS
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO s, CS_CFG_INT_ESEG IE
        where s.id = SI.STATO_ID
        AND STATO_ID = (select id from CS_CFG_INT_ESEG_STATO where nome ='Erogazione e Chiusura')
        and S.NOME = 'Erogazione e Chiusura'
        AND IE.ID = SI.CFG_INT_ESEG_ID
        AND IE.TIPO_INTERVENTO_ID IN (77,139,133,134,135,136,137,138));

        DELETE FROM CS_CFG_INT_ESEG_STATO_INT SI
        WHERE EXISTS
        (
        select cfg_int_eseg_id, stato_id from CS_CFG_INT_ESEG_STATO s, CS_CFG_INT_ESEG IE
        where s.id = SI.STATO_ID
        AND STATO_ID = (select id from CS_CFG_INT_ESEG_STATO where nome ='Mancata Erogazione')
        and S.NOME = 'Mancata Erogazione'
        AND IE.ID = SI.CFG_INT_ESEG_ID
        AND IE.TIPO_INTERVENTO_ID IN (139,133,134,135,136,137,138));


        CONFIGURA_SAL;
        CONFIGURA_AFFIDI;
end;

end;
/


DROP PACKAGE BODY CS_ROMA.SVUOTA_DB;

CREATE OR REPLACE PACKAGE BODY CS_ROMA.SVUOTA_DB AS
/******************************************************************************
   NAME:       SVUOTA_DB
   PURPOSE:
   RICORDARSI PRIMA DELL'ESECUZIONE DI DISABILITARE LE CONSTRAINTS (TUTTE)

    select 'DELETE FROM  ' ||  table_name || ' ;'  from tabs WHERE TABLE_NAME LIKE 'CS_%' AND TABLE_NAME NOT LIKE 'CS_TB%' AND TABLE_NAME NOT LIKE 'CS_C%' 
    AND TABLE_NAME NOT LIKE 'CS_CFG%' AND TABLE_NAME <> 'CS_ALERT_CONFIG' AND TABLE_NAME = 'CS_C_COMUNITA'


******************************************************************************/

  PROCEDURE RIPULIAMO_SETTORE_OPERATORI IS
  BEGIN
  
    DELETE FROM  CS_O_SETTORE ;
    DELETE FROM  CS_C_COMUNITA;
    DELETE FROM  CS_REL_SETT_CSOC_TIPO_INTER_ER ;
    DELETE FROM  CS_REL_SETT_CSOC_TIPO_INTER ;
    DELETE FROM  CS_REL_SETT_CATSOC_ESCLUSIVA ;
    DELETE FROM  CS_REL_SETTORE_CATSOC ;
    DELETE FROM  CS_O_ORGANIZZAZIONE ;
    DELETE FROM  CS_O_OPERATORE_TIPO_OPERATORE ;
    DELETE FROM  CS_O_OPERATORE_SETTORE ;
    DELETE FROM  CS_O_OPERATORE ;
    
    COMMIT;


  END;
   

  PROCEDURE RIPULIAMO_NO_TB IS
    TmpVar NUMBER;
  BEGIN
   


        RIPULIAMO_SETTORE_OPERATORI;

        delete from CS_SS_SCHEDA_SEGR;
        DELETE FROM  CS_REL_RELAZIONE_TIPOINT ;
        DELETE FROM  CS_REL_DIARIO_DIARIORIF ;
