        DELETE FROM  CS_LOAD_DOCUMENTO ;
        DELETE FROM  CS_I_VOUCHERSAD ;
        DELETE FROM  CS_I_SEMI_RESI_MIN ;
        DELETE FROM  CS_I_SCHEDA_LAVORO ;
        DELETE FROM  CS_I_RESI_MINORE ;
        DELETE FROM  CS_I_RESI_ADULTI ;
        DELETE FROM  CS_I_PASTI ;
        DELETE FROM  CS_I_INTERVENTO_ESEG ;
        DELETE FROM  CS_I_INTERVENTO ;
        DELETE FROM  CS_I_CONTR_ECO ;
        DELETE FROM  CS_I_CENTROD ;
        DELETE FROM  CS_I_BUONO_SOC ;
        DELETE FROM  CS_I_AFFIDO_FAM ;
        DELETE FROM  CS_I_ADM_ADH ;
        DELETE FROM  CS_IT_STEP_ATTR_VALUE ;
        DELETE FROM  CS_IT_STEP ;
        DELETE FROM  CS_FLG_INTERVENTO ;
        DELETE FROM  CS_D_VALUTAZIONE ;
        DELETE FROM  CS_D_RELAZIONE ;
        DELETE FROM  CS_D_PAI ;
        DELETE FROM  CS_D_NOTE ;
        DELETE FROM  CS_D_DOC_INDIVIDUALE ;
        DELETE FROM  CS_D_DIARIO_DOC ;
        DELETE FROM  CS_D_DIARIO ;
        DELETE FROM  CS_D_COLLOQUIO ;
        DELETE FROM  CS_D_CLOB ;
        DELETE FROM  CS_A_TRIBUNALE ;
        DELETE FROM  CS_A_SOGGETTO_STATUS ;
        DELETE FROM  CS_A_SOGGETTO_STATO_CIVILE ;
        DELETE FROM  CS_A_SOGGETTO_MEDICO ;
        DELETE FROM  CS_A_SOGGETTO_CATEGORIA_SOC ;
        DELETE FROM  CS_A_SOGGETTO ;
        DELETE FROM  CS_A_INDIRIZZO ;
        DELETE FROM  CS_A_FAMIGLIA_GRUPPO_GIT ;
        DELETE FROM  CS_A_FAMIGLIA_GRUPPO ;
        DELETE FROM  CS_A_DISABILITA ;
        DELETE FROM  CS_A_DATI_SOCIALI ;
        DELETE FROM  CS_A_DATI_INVALIDITA ;
        DELETE FROM  CS_A_COMPONENTE_GIT ;
        DELETE FROM  CS_A_COMPONENTE ;
        DELETE FROM  CS_A_CASO_OPE_TIPO_OPE ;
        DELETE FROM  CS_A_CASO ;
        DELETE FROM  CS_A_ANA_INDIRIZZO ;
        DELETE FROM  CS_A_ANAGRAFICA ;
        DELETE FROM  CS_ALERT_CONFIG ;
        DELETE FROM  CS_ALERT ;

        COMMIT;
  
  
  END;


  PROCEDURE RIPULIAMO_CS_CF(cod_fisc IN varchar2 ) IS
    TmpVar NUMBER;
  BEGIN


        update CS_SS_SCHEDA_SEGR set soggetto_id=null, stato=null, flg_esistente=null
        where soggetto_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
        
        delete from cs_a_anagrafica_log where id_anagrafica in 
        (
          select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );
               
        delete from cs_a_componente_anag_caso_git where SOGGETTO_ANAGRAFICA_ID IN 
        (
          select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );
        
        delete from cs_a_dati_invalidita
        where soggetto_anagrafica_id in 
        (        
        select anagrafica_id from cs_a_soggetto where anagrafica_id in  (select id from CS_A_ANAGRAFICA WHERE cf = cod_fisc)
        );
        
        delete from cs_a_dati_sociali
        where soggetto_anagrafica_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
        
        delete from cs_a_disabilita
        where soggetto_anagrafica_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
        
        UPDATE CS_PAI_AFFIDO_FAMIGLIA_AFF SET MADRE_ID = NULL WHERE MADRE_ID IN
        (SELECT C.ID FROM CS_A_COMPONENTE C, CS_A_FAMIGLIA_GRUPPO F, CS_A_SOGGETTO S, CS_A_ANAGRAFICA A 
         WHERE C.FAMIGLIA_GRUPPO_ID = f.id and F.SOGGETTO_ANAGRAFICA_ID = S.ANAGRAFICA_ID AND A.ID = S.ANAGRAFICA_ID AND A.CF = cod_fisc 
        );

        UPDATE CS_PAI_AFFIDO_FAMIGLIA_AFF SET PADRE_ID = NULL WHERE PADRE_ID IN
        (SELECT C.ID FROM CS_A_COMPONENTE C, CS_A_FAMIGLIA_GRUPPO F, CS_A_SOGGETTO S, CS_A_ANAGRAFICA A 
         WHERE C.FAMIGLIA_GRUPPO_ID = f.id and F.SOGGETTO_ANAGRAFICA_ID = S.ANAGRAFICA_ID AND A.ID = S.ANAGRAFICA_ID AND A.CF = cod_fisc 
        );
        
                
        UPDATE CS_PAI_AFFIDO_FAMIGLIA_ORIG SET MADRE_ID = NULL WHERE MADRE_ID IN
        (SELECT C.ID FROM CS_A_COMPONENTE C, CS_A_FAMIGLIA_GRUPPO F, CS_A_SOGGETTO S, CS_A_ANAGRAFICA A 
         WHERE C.FAMIGLIA_GRUPPO_ID = f.id and F.SOGGETTO_ANAGRAFICA_ID = S.ANAGRAFICA_ID AND A.ID = S.ANAGRAFICA_ID AND A.CF = cod_fisc 
        );

        UPDATE CS_PAI_AFFIDO_FAMIGLIA_ORIG SET PADRE_ID = NULL WHERE PADRE_ID IN
        (SELECT C.ID FROM CS_A_COMPONENTE C, CS_A_FAMIGLIA_GRUPPO F, CS_A_SOGGETTO S, CS_A_ANAGRAFICA A 
         WHERE C.FAMIGLIA_GRUPPO_ID = f.id and F.SOGGETTO_ANAGRAFICA_ID = S.ANAGRAFICA_ID AND A.ID = S.ANAGRAFICA_ID AND A.CF = cod_fisc 
        );
        
       DELETE FROM CS_A_COMPONENTE
       WHERE FAMIGLIA_GRUPPO_ID IN
       ( 
            select f.id from cs_a_famiglia_gruppo f, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and F.SOGGETTO_ANAGRAFICA_ID=a.id and cf = cod_fisc
       );        
       
       --Rimuovere anagrafiche dei componenti orfane in CS_A_ANAGRAFICA
       delete from cs_a_anagrafica where id not in(
            select id_anagrafica from cs_a_anagrafica_log
            union
            select anagrafica_id from cs_a_componente
            union
            select anagrafica_id from cs_a_soggetto
            union 
            select anagrafica_id from cs_d_diario_ana
        );
        
        delete from CS_A_FAMIGLIA_GRUPPO WHERE soggetto_anagrafica_id IN 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        ); 
                       
       DELETE FROM CS_A_COMPONENTE_GIT
       WHERE FAMIGLIA_GRUPPO_GIT_ID IN 
       ( 
            select f.id from cs_a_famiglia_gruppo_git f, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and F.SOGGETTO_ANAGRAFICA_ID=a.id and cf = cod_fisc
       );   

       delete from CS_A_FAMIGLIA_GRUPPO_GIT 
       WHERE soggetto_anagrafica_id IN 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
           
        delete from CS_A_INDIRIZZO where soggetto_anagrafica_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
        
        --Rimuovere indirizzi orfani in CS_A_ANA_INDIRIZZO
        delete from cs_a_ana_indirizzo where id not in (
            select ana_indirizzo_id from cs_c_comunita
            union
            select ana_indirizzo_id from cs_a_indirizzo
            union
            select ana_indirizzo_id from cs_o_settore
);
        
        delete from CS_A_SOGGETTO_CATEGORIA_SOC where soggetto_anagrafica_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
        
        delete from CS_A_SOGGETTO_MEDICO where soggetto_anagrafica_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
        
        delete from CS_A_SOGGETTO_STATO_CIVILE where soggetto_anagrafica_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  

        delete from CS_A_SOGGETTO_STATUS where soggetto_anagrafica_id in 
       (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );  
        
        delete from CS_A_TRIBUNALE where soggetto_anagrafica_id in 
        (        
            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );
        
--       delete from CS_A_servizi WHERE soggetto_anagrafica_id IN 
--        (        
--            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
--        );  
--        
--       delete from CS_A_CONTRIBUTI WHERE soggetto_anagrafica_id IN 
--        (        
--            select anagrafica_id from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
--        ); 
        
        --RIMOZIONE ELEMENTI COLLEGATI A DIARIO
            
        delete from CS_REL_RELAZIONE_TIPOINT 
        where relazione_diario_id in 
        (
            SELECT  diario_id FROM CS_D_RELAZIONE 
            where diario_id in 
            (
                SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
                where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
            )
        );
        
        delete FROM CS_REL_DIARIO_DIARIORIF 
        where diario_id in 
        (
            SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
        delete FROM CS_REL_DIARIO_DIARIORIF 
        where diario_id_rif in 
        (
            SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
        DELETE FROM CS_D_COLLOQUIO
        WHERE DIARIO_ID IN
        (
            SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
        DELETE FROM CS_D_DIARIO_ANA 
        WHERE DIARIO_ID IN
        (
            SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
        
        EXECUTE IMMEDIATE 'ALTER TABLE CS_D_DIARIO_DOC DISABLE CONSTRAINT CS_D_DIARIO_DOC_DOC_FK';
        
        DELETE from cs_load_documento
        WHERE ID IN
        (
            SELECT DOCUMENTO_ID FROM CS_D_DIARIO_DOC
            WHERE DIARIO_ID IN
            (
                SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
                where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
            )
        );

        DELETE FROM CS_D_DIARIO_DOC
        WHERE DIARIO_ID IN
        (
            SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
        EXECUTE IMMEDIATE 'ALTER TABLE CS_D_DIARIO_DOC ENABLE CONSTRAINT CS_D_DIARIO_DOC_DOC_FK';
        
        DELETE FROM CS_D_DOC_INDIVIDUALE
        WHERE DIARIO_ID IN
        (
            SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
        DELETE FROM CS_D_ISEE
        WHERE DIARIO_ID IN
        (
           SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
           where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
        DELETE FROM CS_D_NOTE
        WHERE DIARIO_ID IN
        (
            SELECT d.ID FROM cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a 
            where A.ID = S.ANAGRAFICA_ID and d.caso_id = s.caso_id and cf = cod_fisc
        );
        
       --Start CS_D_PAI
       update CS_I_INTERVENTO set diario_pai_id = null where diario_pai_id in 
       ( 
        select diario_id from cs_d_pai p, cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a
        where p.diario_id = d.id and d.caso_id = s.caso_id and S.ANAGRAFICA_ID = a.id and a.cf = cod_fisc
       );
       
       update CS_I_INTERVENTO_ESEG_MAST set diario_pai_id = null where diario_pai_id in 
       ( 
        select diario_id from cs_d_pai p, cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a
        where p.diario_id = d.id and d.caso_id = s.caso_id and S.ANAGRAFICA_ID = a.id and a.cf = cod_fisc
       );
       
       delete from cs_pai_mast_sogg where diario_id in
       ( 
        select diario_id from cs_d_pai p, cs_d_diario d, cs_a_soggetto s, cs_a_anagrafica a
