            select quota_id from cs_i_intervento
            union
            select quota_id from cs_i_intervento_eseg_mast
        );
        
        delete from cs_i_quota where id not in 
        (
            select quota_id from cs_i_intervento
            union
            select quota_id from cs_i_intervento_eseg_mast
        );

        delete from CS_I_VAL_QUOTA where id not in (
            select val_quota_id from cs_i_intervento_eseg
            union 
            select val_quota_id from cs_i_riga_quota
        );
        
        --Rimozione ITER STEP
        
        DELETE FROM CS_IT_STEP_ATTR_VALUE
        WHERE IT_STEP_ID IN 
        (
           SELECT id from CS_IT_STEP
            WHERE DIARIO_ID IN
            (
               SELECT id FROM CS_D_DIARIO  
               WHERE CASO_ID IN 
               (        
                   select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
               )
            )
        );
        
        DELETE FROM CS_IT_STEP
        WHERE DIARIO_ID IN
        (
           SELECT id FROM CS_D_DIARIO  
           WHERE CASO_ID IN 
           (        
             select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
           )
        );
       
       --Cancellazione dati Diario collegati a CLOB       
       update cs_d_diario set clob_id=null 
       WHERE CASO_ID IN 
       (select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc);

        delete from cs_d_clob where id not in (select clob_id from cs_d_diario where clob_id is not null);

       delete FROM CS_D_DIARIO  
       WHERE CASO_ID IN 
       (select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc);
 
       DELETE FROM CS_A_CASO_ACCESSO_FASCICOLO
       WHERE CASO_ID IN 
       (select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc);

       delete from CS_A_CASO_OPE_TIPO_OPE 
       WHERE CASO_ID IN 
       (select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc);
 
       delete from CS_A_CASO_OPE_TIPO_OPE2 
       WHERE CASO_ID IN 
       (select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc);

       DELETE FROM CS_ALERT
       WHERE CASO_ID IN 
       (select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc);
       

       --Rimozioni dati FSE collegati alla cartella sociale       
        delete from CS_EXTRA_FSE_DATI_LAVORO l where L.EXTRA_FSE_MAST_ID IN (
           select mast.ID from cs_extra_fse_mast mast, cs_a_soggetto s, cs_a_anagrafica a 
           where A.ID = S.ANAGRAFICA_ID and MAST.CASO_ID=s.caso_id and cf = cod_fisc
        ); 

        delete from CS_EXTRA_FSE_SIRU l where L.EXTRA_FSE_MAST_ID IN (
           select mast.ID from cs_extra_fse_mast mast, cs_a_soggetto s, cs_a_anagrafica a 
           where A.ID = S.ANAGRAFICA_ID and MAST.CASO_ID=s.caso_id and cf = cod_fisc
        ); 

        delete from cs_extra_fse_mast
        WHERE CASO_ID IN 
        (        
           select CASO_ID from cs_a_soggetto s, cs_a_anagrafica a 
           where A.ID = S.ANAGRAFICA_ID and cf = cod_fisc
        );
       
       --Inserire le delete delle tabelle collegate mediante caso_id e anagrafica_id  prima di questo punto 
              
       DELETE FROM cs_a_soggetto where anagrafica_id in  (select id from CS_A_ANAGRAFICA WHERE cf = cod_fisc);
       
       DELETE FROM CS_A_CASO C WHERE NOT EXISTS (SELECT 1 FROM CS_A_SOGGETTO S WHERE S.CASO_ID = C.ID );
   
       DELETE from CS_A_ANAGRAFICA WHERE id not in (SELECT anagrafica_id FROM CS_A_COMPONENTE) and cf = cod_fisc ;
       
       COMMIT;
       
  end;     
  
PROCEDURE RIPULIAMO_UDC_CF(cod_fisc IN varchar2 ) IS
    TmpVar NUMBER;
  BEGIN
     
       
       DELETE from cs_ss_scheda_Segr where provenienza = 'SS' and scheda_id in 
       (select s.id from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
        where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);
        
       update cs_d_diario set clob_id=null where scheda_id in 
        (select s.id from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
        where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);

        delete from cs_d_clob where id not in (select clob_id from cs_d_diario where clob_id is not null);

        delete from cs_d_valutazione where diario_id in 
        (select id from cs_d_diario where scheda_id in  
           (select s.id from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
            where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc)); 

        delete from cs_d_diario where scheda_id in 
            (select s.id from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
             where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);
        
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA DISABLE CONSTRAINT SS_SCHEDA_FK1';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA DISABLE CONSTRAINT SS_SCHEDA_FK2';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA DISABLE CONSTRAINT SS_SCHEDA_FK3';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA DISABLE CONSTRAINT SS_SCHEDA_FK4';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA DISABLE CONSTRAINT SS_SCHEDA_FK5';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA DISABLE CONSTRAINT SS_SCHEDA_FK6';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA_SEGNALATO DISABLE CONSTRAINT SS_SCHEDA_SEGNALATO_FK1';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA_SEGNALATO DISABLE CONSTRAINT SS_SCHEDA_SEGNALATO_FK2';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA_PRIVACY DISABLE CONSTRAINT FK_SCHEDA';
        
        delete from SS_SCHEDA_SEGNALANTE where id in 
        (select s.segnalante from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
         where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);
        
        delete from SS_INTERVENTI_SCHEDE where scheda in 
        (select s.interventi from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
         where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);
 
        delete from SS_SCHEDA_INTERVENTI where id in 
        (select s.interventi from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
         where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);

        delete from SS_SCHEDA_RIFERIMENTO where id in 
        (select s.riferimento from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
         where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);

        delete from SS_MOTIVAZIONI_SCHEDE where scheda_motivazione_id in 
        (select s.motivazione from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
         where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);

        delete from SS_SCHEDA_MOTIVAZIONE where id in 
        (select s.motivazione from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
         where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);
        
        delete from SS_SCHEDA_ACCESSO where id in 
        (select s.accesso from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
         where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc);
       
        delete from SS_INDIRIZZO where id in 
        (select ss.residenza from ss_anagrafica a, ss_scheda_segnalato ss where ss.anagrafica=a.id and cf=cod_fisc);

        delete from SS_INDIRIZZO where id in 
        (select ss.domicilio from ss_anagrafica a, ss_scheda_segnalato ss where ss.anagrafica=a.id and cf=cod_fisc);

      --Rimozioni dati FSE collegati alla udc       
        delete from CS_EXTRA_FSE_DATI_LAVORO l where L.EXTRA_FSE_MAST_ID IN (
           select mast.ID from cs_extra_fse_mast mast, ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
           where MAST.SCHEDA_ID = s.id and  s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc
        ); 

        delete from CS_EXTRA_FSE_SIRU l where L.EXTRA_FSE_MAST_ID IN (
          select mast.ID from cs_extra_fse_mast mast, ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
          where MAST.SCHEDA_ID = s.id and  s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc
        ); 

        delete from cs_extra_fse_mast
        WHERE SCHEDA_ID IN 
        (        
           select s.ID from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
           where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc
        );
        
        delete from ss_scheda_accesso_inviante where id_nuova_scheda in (
           select s.ID from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
           where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc
        );
        
        delete from ss_scheda_privacy where scheda_id in (
           select s.ID from ss_scheda s, ss_Scheda_segnalato segn, ss_anagrafica ana 
           where s.segnalato=segn.id and segn.anagrafica= ana.id and ANA.CF = cod_fisc
        );

        delete from SS_SCHEDA where segnalato in 
        (select ss.id from ss_anagrafica a, ss_scheda_segnalato ss where ss.anagrafica=a.id and cf=cod_fisc);

        delete from SS_SCHEDA_SEGNALATO where anagrafica in
        (select a.id from ss_anagrafica a where cf=cod_fisc);
        
        delete from SS_ANAGRAFICA_LOG where id_anagrafica in 
        (select a.id from ss_anagrafica a where cf=cod_fisc);
        
        delete from SS_DIARIO where soggetto in
        (select a.id from ss_anagrafica a where cf=cod_fisc);
        
        delete from SS_INTERVENTO_ECONOMICO where soggetto in
        (select a.id from ss_anagrafica a where cf=cod_fisc);

        delete from ss_anagrafica where cf=cod_fisc;
        
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA ENABLE CONSTRAINT SS_SCHEDA_FK1';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA ENABLE CONSTRAINT SS_SCHEDA_FK2';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA ENABLE CONSTRAINT SS_SCHEDA_FK3';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA ENABLE CONSTRAINT SS_SCHEDA_FK4';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA ENABLE CONSTRAINT SS_SCHEDA_FK5';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA ENABLE CONSTRAINT SS_SCHEDA_FK6';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA_SEGNALATO ENABLE CONSTRAINT SS_SCHEDA_SEGNALATO_FK1';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA_SEGNALATO ENABLE CONSTRAINT SS_SCHEDA_SEGNALATO_FK2';
        EXECUTE IMMEDIATE 'ALTER TABLE SS_SCHEDA_PRIVACY ENABLE CONSTRAINT FK_SCHEDA';
        
  
        COMMIT;
  end;

PROCEDURE RIPULIAMO_UDC_ENTE(ENTE IN varchar2 ) IS
    TmpVar NUMBER;
  BEGIN
  
  
    delete from  CS_SS_SCHEDA_SEGR where cod_ente = ENTE;

    delete from  ss_scheda_privacy where organizzazione_id = (select id from  CS_O_ORGANIZZAZIONE where COD_ROUTING = ENTE);

    delete from  ss_scheda where id in
    (select s.id from  ss_scheda s,  ss_scheda_accesso acc where acc.id = s.accesso and acc.rel_upo_organizzazione_id=
      (select id from  CS_O_ORGANIZZAZIONE where COD_ROUTING = ENTE));

    delete from  ss_scheda_accesso     where id not in (select accesso from  ss_scheda);

    delete from  ss_scheda_segnalato   where id not in (select segnalato from  ss_scheda);

    delete from  ss_scheda_segnalante  where id  not in (select segnalante from  ss_scheda);

    delete from  ss_scheda_riferimento where id not in (select riferimento from  ss_scheda);

    delete from  ss_anagrafica         where id not in (select anagrafica from  ss_scheda_segnalato);
    
    COMMIT;
  
  end;

END SVUOTA_DB;
/

