DROP VIEW ARGOBI_ROMA.V_FACT_CASI;

/* Formatted on 18/07/2022 12:44:17 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGOBI_ROMA.V_FACT_CASI
(
    ZONA_SOCIALE,
    ORGANIZZAZIONE,
    SETTORE,
    ID_CASO,
    COGNOME,
    NOME,
    CF,
    SESSO,
    DATA_NASCITA,
    CATEGORIA,
    ITER,
    DATA_ITER
)
BEQUEATH DEFINER
AS
    SELECT ZS.NOME               zona_sociale,
           O.NOME                ORGANIZZAZIONE,
           SETT.NOME             SETTORE,
           c.ID_CASO,
           S.C_COGNOME           cognome,
           S.C_NOME              nome,
           S.C_CF                cf,
           c.sesso,
           S.C_DATA_NASCITA      data_nascita,
           CSOC.DESCRIZIONE      categoria,
           diter.DESCRIZIONE     iter,
           lastiter.DATA_ITER
      FROM FACT_CASI  c
           LEFT JOIN DIM_ZONA_SOC zs ON ZS.ID = C.ID_ZONA_SOC
           LEFT JOIN DIM_ORGANIZZAZIONE o ON O.CODICE_ORG = c.codice_org
           LEFT JOIN DIM_SETTORE sett ON SETT.ID = C.ID_SETTORE
           LEFT JOIN DIM_SOGGETTI_CASO s
               ON (S.ID = C.ID_SOGGETTO AND S.ID_ZONA_SOC = C.ID_ZONA_SOC)
           LEFT JOIN DIM_CAT_SOC csoc ON CSOC.COD_ISTAT = C.COD_ISTAT_CAT_SOC
           LEFT JOIN DIM_CITTADINANZA citt ON CITT.ID = C.ID_CITTADINANZA
           LEFT JOIN
           (WITH
                summary
                AS
                    (SELECT ITER.*,
                            ROW_NUMBER ()
                                OVER (PARTITION BY iter.id_caso
                                      ORDER BY data_iter DESC, id DESC)    AS rk
                       FROM FACT_ITER ITER)
            SELECT s1.*
              FROM summary s1
             WHERE s1.rk = 1) lastiter
               ON lastiter.id_caso = c.ID
           LEFT JOIN DIM_STATO_ITER diter
               ON DITER.COD_ISTAT = LASTITER.ID_STATO_ITER;


DROP VIEW ARGOBI_ROMA.V_INDIRIZZI_CASO;

/* Formatted on 18/07/2022 12:44:17 (QP5 v5.374) */
CREATE OR REPLACE FORCE VIEW ARGOBI_ROMA.V_INDIRIZZI_CASO
(
    ZONA_SOCIALE,
    ID_ANAGRAFICA,
    ID_CASO,
    CODICE_FISCALE,
    TIPO_INDIRIZZO_ID,
    TIPO_IND_DESC,
    DATA_INIZIO_APP,
    DATA_FINE_APP,
    INDIRIZZO_HASH,
    INDIRIZZO_ESTESO,
    LATITUDINE,
    LONGITUDINE,
    ZONA_CENSUARIA
)
BEQUEATH DEFINER
AS
    SELECT avic."ZONA_SOCIALE",
           avic."ID_ANAGRAFICA",
           avic."ID_CASO",
           avic."CODICE_FISCALE",
           avic."TIPO_INDIRIZZO_ID",
           avic."TIPO_IND_DESC",
           avic."DATA_INIZIO_APP",
           avic."DATA_FINE_APP",
           avic."INDIRIZZO_HASH",
           avic."INDIRIZZO_ESTESO",
           aviz.GM_LAT             AS LATITUDINE,
           aviz.GM_LON             AS LONGITUDINE,
           aviz.ZONA_CENSUARIA     AS ZONA_CENSUARIA
      FROM ARBI_V_INDIRIZZI_CASO  avic
           LEFT JOIN ARGO_ROMA.AR_V_INDIRIZZI_ZONE aviz
               ON     avic.INDIRIZZO_HASH = aviz.INDIRIZZO_HASH
                  AND avic.ZONA_SOCIALE = aviz.ZONA_SOC;


CREATE OR REPLACE SYNONYM ARGO_ROMA.V_ARBI_CASI FOR ARGOBI_ROMA.V_FACT_CASI;

BEGIN
  SYS.DBMS_SCHEDULER.DROP_JOB
    (job_name  => 'CS_ROMA.MV_REFRESH_CONFIGURAZIONI');
END;
