BEGIN
  SYS.DBMS_SCHEDULER.CREATE_JOB
    (
       job_name        => 'CS_ROMA.REFRESH_AR_ORG'
      ,start_date      => TO_TIMESTAMP_TZ('2015/11/18 18:38:38.000000 +01:00','yyyy/mm/dd hh24:mi:ss.ff tzh:tzm')
      ,repeat_interval => 'FREQ=MINUTELY; INTERVAL=30'
      ,end_date        => NULL
      ,job_class       => 'DEFAULT_JOB_CLASS'
      ,job_type        => 'PLSQL_BLOCK'
      ,job_action      => '
begin

DBMS_SCHEDULER.purge_log (
log_history => 1, 
which_log => ''JOB_AND_WINDOW_LOG'',
job_name => ''REFRESH_AR_ORG'');

INSERT INTO ar_o_organizzazione
SELECT SQ_ID_ARGO.NEXTVAL ID, S.* FROM 
(
select NOME TOOLTIP, EMAIL, NOME, cod_routing BELFIORE, NVL(CF,''00000000000'') PIVA_CF , (SELECT NOME FROM CS_O_ZONA_SOC) ZONA_NOME,1 ABILITATO
from CS_O_ORGANIZZAZIONE WHERE cod_routing IS NOT NULL
) S
where not exists 
(select 1 from ar_o_organizzazione oo where oo.BELFIORE = s.belfiore AND S.ZONA_NOME=OO.ZONA_NOME);


INSERT INTO AR_FF_LINEAFIN_ORG (ID, ORGANIZZAZIONE_ID, LINEAFIN_ID, IMPORTO)
select   SQ_ID_ARGO.NEXTVAL ID, s.*
from (
SELECT DISTINCT O.ID idorg, LF.ID , NULL  IMPORTO
FROM AR_FF_LINEAFIN LF, AR_O_ORGANIZZAZIONE O
WHERE LF.DESCRIZIONE =''Non definito''
and not exists (select 1 from AR_FF_LINEAFIN_ORG fo, AR_FF_LINEAFIN f  where fo.organizzazione_id = o.id and fo.lineafin_id = f.id and f.descrizione =''Non definito'')
) s ;

MERGE INTO AR_O_ORGANIZZAZIONE_FSE ofse USING
(SELECT o.id, o.belfiore, o.nome, (SELECT COD_ROUTING FROM CS_O_ORGANIZZAZIONE WHERE FLAG_CAPOFILA=1) capofila  
        FROM AR_O_ORGANIZZAZIONE o, CS_O_ORGANIZZAZIONE co
where CO.COD_CATASTALE IS NOT NULL and CO.COD_ROUTING=o.belfiore) no
ON (no.belfiore = ofse.ar_o_org_belfiore)
WHEN NOT MATCHED THEN INSERT VALUES(no.id, no.nome, no.belfiore, no.capofila, null);

commit;


end;
'
      ,comments        => NULL
    );
  SYS.DBMS_SCHEDULER.SET_ATTRIBUTE
    ( name      => 'CS_ROMA.REFRESH_AR_ORG'
     ,attribute => 'RESTARTABLE'
     ,value     => FALSE);
  SYS.DBMS_SCHEDULER.SET_ATTRIBUTE
    ( name      => 'CS_ROMA.REFRESH_AR_ORG'
     ,attribute => 'LOGGING_LEVEL'
     ,value     => SYS.DBMS_SCHEDULER.LOGGING_OFF);
  SYS.DBMS_SCHEDULER.SET_ATTRIBUTE_NULL
