DROP MATERIALIZED VIEW DBTOTALE_H501.COMPRAVENDITE_FAVORE;

CREATE MATERIALIZED VIEW DBTOTALE_H501.COMPRAVENDITE_FAVORE 
    (DATA_VALIDITA_ATTO_DATE,CODICE_FISCALE,COGNOME,NOME,DATA_NASCITA,
     DENOMINAZIONE,FOGLIO,NUMERO,DENOMINATORE,SUBALTERNO,
     CATEGORIA,CLASSE,VANI,MQ,SUPERFICIE,
     RENDITA_EURO,T_INDIRIZZO,T_CIVICO1)
TABLESPACE GIT
PCTUSED    0
PCTFREE    10
INITRANS   2
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           )
NOCACHE
NOLOGGING
NOCOMPRESS
BUILD DEFERRED
REFRESH FORCE ON DEMAND
WITH PRIMARY KEY
AS 
/* Formatted on 18/07/2022 12:44:51 (QP5 v5.374) */
SELECT DISTINCT nota.data_validita_atto_date,
                sogg.codice_fiscale,
                sogg.cognome,
                sogg.nome,
                sogg.data_nascita,
                sogg.denominazione,
                fabbr.foglio,
                fabbr.numero,
                fabbr.denominatore,
                fabbr.subalterno,
                fabinfo.categoria,
                fabinfo.classe,
                fabinfo.vani,
                fabinfo.mq,
                fabinfo.superficie,
                fabinfo.rendita_euro,
                fabinfo.t_indirizzo,
                fabinfo.t_civico1
  FROM mui_nota_tras              nota,
       mui_titolarita             tito,
       mui_fabbricati_info        fabinfo,
       mui_soggetti               sogg,
       mui_fabbricati_identifica  fabbr
 WHERE     nota.iid_fornitura = tito.iid_fornitura
       AND nota.iid = tito.iid_nota
       AND tito.iid_fornitura = sogg.iid_fornitura
       AND tito.iid_nota = sogg.iid_nota
       AND tito.id_soggetto_nota = sogg.id_soggetto_nota
       AND nota.iid = fabbr.iid_nota
       AND nota.iid_fornitura = fabbr.iid_fornitura
       AND fabbr.iid_nota = fabinfo.iid_nota
       AND fabbr.iid_fornitura = fabinfo.iid_fornitura
       AND fabbr.id_immobile = fabinfo.id_immobile
       AND tito.sf_flag_tipo_titol_nota = 'F';


COMMENT ON MATERIALIZED VIEW DBTOTALE_H501.COMPRAVENDITE_FAVORE IS 'snapshot table for snapshot DBTOTALE_GIT.COMPRAVENDITE_FAVORE';

DROP MATERIALIZED VIEW DBTOTALE_H501.TITOLARITA_IMMOBILI;

CREATE MATERIALIZED VIEW DBTOTALE_H501.TITOLARITA_IMMOBILI 
    (TITOLARITA,CODI_FISC,FOGLIO,PARTICELLA,UNIMM,
     DATA_INIZIO,DATA_FINE,TIPO_TITOLO,PERC_POSS)
TABLESPACE GIT
PCTUSED    0
PCTFREE    10
INITRANS   2
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           )
NOCACHE
NOLOGGING
NOCOMPRESS
BUILD DEFERRED
REFRESH FORCE ON DEMAND
WITH PRIMARY KEY
AS 
/* Formatted on 18/07/2022 12:44:51 (QP5 v5.374) */
SELECT seltit.titolarita,
       seltit.codi_fisc,
       LPAD (TO_CHAR (NVL (seltit.foglio, 0)), 6, '0')
           foglio,
       LPAD (LTRIM (RTRIM (NVL (seltit.particella, '0'))), 5, '0')
           particella,
       LPAD (TO_CHAR (NVL (seltit.unimm, 0)), 5, '0')
           unimm,
       seltit.data_inizio,
       seltit.data_fine,
       seltit.tipo_titolo,
       seltit.perc_poss
  FROM (SELECT 'PRIOPRIETA'     titolarita,
               a.codi_fisc,
               foglio,
               particella,
               unimm,
               b.data_inizio,
               b.data_fine,
               b.tipo_titolo,
               b.perc_poss
          FROM cons_sogg_viw a, cons_csui_tab b
         WHERE a.pk_cuaa = b.pk_cuaa
        UNION
        SELECT 'ALTRE TITOLARITA'     titolarita,
               a1.codi_fisc,
               b1.foglio,
               b1.particella,
               b1.unimm,
               b1.data_inizio,
               b1.data_fine,
               b1.tipo_titolo,
               b1.perc_poss
          FROM cons_sogg_viw a1, cons_urui_tab b1
         WHERE a1.pk_cuaa = b1.pk_cuaa) seltit;


COMMENT ON MATERIALIZED VIEW DBTOTALE_H501.TITOLARITA_IMMOBILI IS 'snapshot table for snapshot DBTOTALE_GIT.TITOLARITA_IMMOBILI';

DROP MATERIALIZED VIEW DBTOTALE_H501.UIU_COND;

CREATE MATERIALIZED VIEW DBTOTALE_H501.UIU_COND 
    (FOGLIO,PART,ALLEGATO,SUB,CATEGORIA,
     CLASSE,CONSISTENZA,RENDITA,SUP_CAT,PIANO,
     CF,DENOMINAZIONE,NOME,SESSO,D_NASCITA,
     PERC_POSS,TIPO_TITOLO)
TABLESPACE GIT
PCTUSED    0
PCTFREE    10
INITRANS   2
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
           )
NOCACHE
NOLOGGING
NOCOMPRESS
BUILD DEFERRED
REFRESH FORCE ON DEMAND
WITH PRIMARY KEY
AS 
/* Formatted on 18/07/2022 12:44:51 (QP5 v5.374) */
SELECT su.foglio,
       su.particella                                             AS part,
       su.sub                                                    AS allegato,
       su.unimm                                                  AS sub,
       su.categoria,
       su.classe,
       su.consistenza,
       su.rendita,
       su.sup_cat,
       su.piano,
       sc.cuaa                                                   AS cf,
       ans.denominazione,
       ans.nome,
       ans.sesso,
       ans.d_nascita,
       sc.perc_poss,
       DECODE (sc.tipo_titolo,  1, 'Proprietà',  9, 'Altro')    AS tipo_titolo
  FROM sitiuiu  su
       LEFT JOIN siticonduz_imm_all sc
           ON     su.cod_nazionale = sc.cod_nazionale
              AND su.foglio = sc.foglio
              AND su.particella = sc.particella
              AND su.sub = sc.sub
              AND su.unimm = sc.unimm
              AND su.data_fine_val = sc.data_fine
       LEFT JOIN anag_soggetti ans
           ON     sc.pk_cuaa = ans.cod_soggetto
              AND sc.data_fine = ans.data_fine_val
 WHERE     su.cod_nazionale IN (SELECT cod_nazionale
                                  FROM sit_ente e, siticomu c
                                 WHERE e.codent = c.codi_fisc_luna)
       AND su.data_fine_val = TO_DATE ('99991231', 'yyyymmdd');


