BEGIN
  SYS.DBMS_SCHEDULER.CREATE_JOB
    (
       job_name        => 'AM_ROMA.REFRESH_PROFILAZIONE_SOCLAV'
      ,start_date      => TO_TIMESTAMP_TZ('2020/11/18 18:38:38.000000 +01:00','yyyy/mm/dd hh24:mi:ss.ff tzh:tzm')
      ,repeat_interval => 'FREQ=MINUTELY; INTERVAL=10'
      ,end_date        => NULL
      ,job_class       => 'DEFAULT_JOB_CLASS'
      ,job_type        => 'PLSQL_BLOCK'
      ,job_action      => '
begin

DBMS_SCHEDULER.purge_log (
log_history => 1, 
which_log => ''JOB_AND_WINDOW_LOG'',
job_name => ''REFRESH_PROFILAZIONE_SOCLAV'');

DELETE FROM RDC_USER_ENTE WHERE SCHEMA_ORIG = SYS_CONTEXT(''USERENV'',''CURRENT_SCHEMA'');
DELETE FROM RDC_USER_ANAGRAFICA WHERE SCHEMA_ORIG = SYS_CONTEXT(''USERENV'',''CURRENT_SCHEMA'');

insert into RDC_USER_ANAGRAFICA
SELECT DISTINCT SYS_CONTEXT(''USERENV'',''CURRENT_SCHEMA'') SCHEMA_ORIG, a.FK_AM_USER USERNAME,
cognome, nome, codice_fiscale, comune_nascita, data_nascita, provincia_nascita, sesso, U.EMAIL
FROM AM_ANAGRAFICA a,  V_COMUNI_UTENTI_APPLICAZIONI v, AM_USER u
where v.fk_am_application = ''SocLav'' and v.fk_am_user=a.fk_am_user and a.fk_am_user=u.name;

MERGE INTO RDC_COMUNE ue USING
(select c.* from am_instance_comune ic, am_comune c, am_instance i
where IC.FK_AM_COMUNE = C.BELFIORE and IC.FK_AM_INSTANCE = I.NAME and I.FK_AM_APPLICATION = ''SocLav'') sel
ON (sel.belfiore = ue.belfiore)
WHEN NOT MATCHED THEN INSERT VALUES (sel.belfiore, sel.descrizione);

MERGE INTO RDC_USER_ENTE ue USING
(SELECT DISTINCT SYS_CONTEXT(''USERENV'',''CURRENT_SCHEMA'') SCHEMA_ORIG, v.*
FROM V_COMUNI_UTENTI_APPLICAZIONI v
where v.fk_am_application = ''SocLav'') sel
ON (ue.schema_orig = sel.schema_orig and ue.RDC_USER_FK = sel.fk_am_user and ue.RDC_COMUNE_FK=sel.fk_am_comune)
WHEN NOT MATCHED THEN INSERT (SCHEMA_ORIG, RDC_USER_FK, RDC_COMUNE_FK) VALUES (sel.schema_orig, sel.fk_am_user, sel.fk_am_comune);

commit;


end;
'
      ,comments        => NULL
    );
  SYS.DBMS_SCHEDULER.SET_ATTRIBUTE
    ( name      => 'AM_ROMA.REFRESH_PROFILAZIONE_SOCLAV'
     ,attribute => 'RESTARTABLE'
     ,value     => FALSE);
  SYS.DBMS_SCHEDULER.SET_ATTRIBUTE
    ( name      => 'AM_ROMA.REFRESH_PROFILAZIONE_SOCLAV'
     ,attribute => 'LOGGING_LEVEL'
     ,value     => SYS.DBMS_SCHEDULER.LOGGING_OFF);
