DROP TRIGGER ARGO_ROMA.DOC_AFTER_INSERT;

CREATE OR REPLACE TRIGGER ARGO_ROMA.DOC_AFTER_INSERT BEFORE
    INSERT ON ARGO_ROMA.AR_CS_PAI_PTI_DOCUMENTO
    FOR EACH ROW
BEGIN
    UPDATE ar_cs_pai_pti_documento
    SET
        valido_a = sysdate
    WHERE
            id_pai_pti = :new.id_pai_pti
        AND cod_routing = :new.cod_routing AND tipo_documento = :new.tipo_documento AND valido_a is null;

END;
/

